INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geride Kalan', 'geride-kalan-volkan-i-ncel-hma3w', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'özlem ne kadar gelip kurulsa da 

başköşeye

bir ana

bir yar

gerisi yalan

herkes gider evine

bitince talan

bir evlat 

bir yar geride kalan', 'özlem ne kadar gelip kurulsa da  başköşeye bir ana bir yar gerisi yalan herkes gider evine bitince talan bir evlat  bir yar geride kalan...', ARRAY['Türk Edebiyatı','Şiir','Volkan İncel']::text[], 8.5, '{"poet":"Volkan İncel","poet_slug":"volkan-i-ncel","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/geride-kalan-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dürüstük', 'durustuk-abdulkadir-azakli-dlb6b', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ey allah''a inananlar.

İnanmanın sırrı budur.

Kimlerin kalbi dürüstse.

İşte onlar salıh kuldur.

Allah inananı sever.

Kötülüklerden men eder.

Yanlış inanan insanlar.

Ömür boyu çile çeker.

İnanalım ey kardeşler.

Doğru söze inanalım.

Zamanı geçmiş söslerle.

Vaktımızı almayalım.

Allah bize çalışın diyor.

Çalışmadan rızık vermez.

Çok dürüst çalışmak lazim.

Dürüst olmayanı sevmez.

Ol cennetin anaktarı.

Bimeliyiz dürüstlüktür.

Orası kutsal bir yerdir.

Orda fitne fesat yoktur.

Ey tanrıya inananlar.

Yolun doğrusunu bulun.

Hal ve hareketinizle.

İnsanlara örnek olun.

İnsamlara iyiliktir.

İbadetlerin efteli.

Tarı bundan hönüt olur.

Çok büyük öder bedeli.

İşinde gayet titiz ol.

Sakın adaletten şaşma.

Sen kendinden sorumlusun.

Sağına soluna bakma.

İnsan oğlu düşünürsün.

Bunları nerde bulursun.

Bu sözlere uyabilsen.

bilki saadet bulursun.', 'Ey allah''a inananlar. İnanmanın sırrı budur. Kimlerin kalbi dürüstse. İşte onlar salıh kuldur. Allah inananı sever. Kötülüklerden men eder. ...', ARRAY['Türk Edebiyatı','Şiir','Abdulkadir Azaklı']::text[], 8.5, '{"poet":"Abdulkadir Azaklı","poet_slug":"abdulkadir-azakli","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/durustuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Böyle Biri', 'boyle-biri-halil-aksoy-65fpi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çirkin bir çenesi vardı,

İpek gibide saçları.

Uzun bir burun,

Kapkaraydı kaşları.

Upuzun bir boyun,

Boyun, üzerinde duruyor,

Daracık bir omuzun

Gövdesi kısacık,

Bacakları upuzun.

Elleri yaba gibi 

Kulakları  kepçe.

Islık çalıyordu kısık kısık.

Adımlarını atardı,

Adımları çarpık çarpık. 

Kızdımı,

Yeşil ğözlü bir kediye,

Güldümü,

Ak sakallı bir dedeye benziyordu.

Kim di? Neydi? Kimlerdendi? 

Vallahi dün akşam rüyamda gördüğüm,

Aynen böyle biriydi.', 'Çirkin bir çenesi vardı, İpek gibide saçları. Uzun bir burun, Kapkaraydı kaşları. Upuzun bir boyun, Boyun, üzerinde duruyor, Daracık bir omu...', ARRAY['Türk Edebiyatı','Şiir','Halil Aksoy']::text[], 8.5, '{"poet":"Halil Aksoy","poet_slug":"halil-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/boyle-biri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adalete açız ekmeğe değil', 'adalete-aciz-ekmege-degil-i-lhami-arslantas-gc3w3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Adalete açız ekmeğe değil,

Kurusu da olsa yiyenlerdeniz.

Bizdeki vicdanın sarısı değil,

Vicdanın sesini duyanlardanız.

Hakkı bırakmayız demeyiz çalsın,

Davayı yarına koymayız kalsın,

Ses versin adalet yerini bulsun,

O zaman nizama uyanlardanız.

Kararımız birdir kısadır, özdür,

Yemini bilmeyiz sözümüz sözdür,

Sanmayın bizleri yobazdır, yozdur,

Biz yılan dişini sayanlardanız,

Hatalara karşı kırmızı kartız,

Yerinde çelikten daha da sertiz,

Soyumuz bellidir mert oğlu mert’iz,

Taşı gediğine koyanlardanız.

Der ilhami halktır milletin kendi,

Halk gücüne aciz paranın fendi,

Yeter şimdiye dek o bizi yendi,

Lütfetmeyin lafa doyanlardanız.

...............Biz aymaz değiliz ayanlardanız.', 'Adalete açız ekmeğe değil, Kurusu da olsa yiyenlerdeniz. Bizdeki vicdanın sarısı değil, Vicdanın sesini duyanlardanız. Hakkı bırakmayız deme...', ARRAY['Türk Edebiyatı','Şiir','İlhami Arslantaş']::text[], 8.5, '{"poet":"İlhami Arslantaş","poet_slug":"i-lhami-arslantas","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/adalete-aciz-ekmege-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz ve Kış', 'deniz-ve-kis-halil-aksoy-5ffzs', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aylardan aralık,

Ve yağmurlu bir gün.

Kış için soğuk denemez,

İyi bir gün.

İndim sahile,

Sırtımda çantam,

Elimde şemsiyeyle.

Gene yağmur inceden inceden atıyor.

Denize baktım.

Körfezin suları çarşaf gibi.

Uzanmış yatıyor.

Denizin hali dikkatimi çekti.

Sanki üzerinde bir insan,

Rahat yürüyecekti.

Hava kara kara,

Bakmasına ramen.

Deniz  üzerine,

Gümüş bir örtü çekti.

Gülümsüyordu,

Kararan güne inat.

Dokunmayın bana,diyordu,

Seyredin sadece,

Gel bunu, sefere çıkan gemiye,

Gökten dökülen yağmura anlat.

Baktım uzun uzun denize.

Ne ğüzel bir sürpriz hazırlamış,

Bu kış mevsiminde  bize.

Bakalım daha neler var,

Göstereceğin bizlere.', 'Aylardan aralık, Ve yağmurlu bir gün. Kış için soğuk denemez, İyi bir gün. İndim sahile, Sırtımda çantam, Elimde şemsiyeyle. Gene yağmur inc...', ARRAY['Türk Edebiyatı','Şiir','Halil Aksoy']::text[], 8.5, '{"poet":"Halil Aksoy","poet_slug":"halil-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/deniz-ve-kis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıllar sonra bu zaman', 'yillar-sonra-bu-zaman-suleyman-demir-gfvpz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'simsiyah dumanıyla hüzün yüklü bir katar,

geçerken uzaklardan ufka dalar gözlerim! 

acı siren sesleri hüznüme hüzün katar,

ve ben pencerelerde yollarını gözlerim...

tek katlı ahşap bir ev ve geçmişten nameler,

nedensiz bir hıçkırık iki damla gözyaşı...

gün batar ufuklarda kızıllaşır perdeler,

son haddine ulaşır yüreğimin telaşı...

ne ben gencimdir artık ne de sen böyle güzel,

anılar çizgi çizgi yanağında son bulur! 

yıllar sonra bu zaman ne sevmek böyle güzel,

ve ne de benim kadar seni bekleyen olur...', 'simsiyah dumanıyla hüzün yüklü bir katar, geçerken uzaklardan ufka dalar gözlerim!  acı siren sesleri hüznüme hüzün katar, ve ben pencereler...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Demir']::text[], 8.5, '{"poet":"Süleyman Demir","poet_slug":"suleyman-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yillar-sonra-bu-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eşim- Birtanem', 'esim-birtanem-halil-aksoy-npy61', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yalnızlıkta açan bir çiçeksin sen. 

Birtanem.

Aşkın sevginin simgesi.

Güzel duyguların ifadesi.

Bütün çiçeklerin kraliçesisin.

Gözlerin yeni doğmuş bir ay gibi parlar.

Güldüğünde,

Masumuyetin bebekleri bile kıskandırır.

Sıcaklığın bütün kalbini  doldurur herkesin.

Sen bir tanesin.

Benim birtanemsin.

Arı kovanına çomak sokmuşçasına, 

Kızgın olduğum zamanlarda bile.

Konuşurken saçmaladığım.

Yemek yerken üzerime damlattığım.

Soguk karlı havalarda arabama zincir taktığım,

Zamanlarda bile hep seni sevdim.

Parıldayan ışığınla,

İçime umut umut umutlarımı yazdım.

Birtanem 

gülümsemen eksilmesin yüzünde.

Her sabah bana günaydın de.

Yıldızlardan bahset bana.

Rüyalarını anlat.

Nefes al yanımda.

Hayatıma hayat kat.', 'Yalnızlıkta açan bir çiçeksin sen.  Birtanem. Aşkın sevginin simgesi. Güzel duyguların ifadesi. Bütün çiçeklerin kraliçesisin. Gözlerin yeni...', ARRAY['Türk Edebiyatı','Şiir','Halil Aksoy']::text[], 8.5, '{"poet":"Halil Aksoy","poet_slug":"halil-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/esim-birtanem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbet', 'gurbet-suleyman-demir-9gdjg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'beni meçhule saldı,

umutlarım kızakta! 

vatan uzakta kaldı,

sevdiklerim uzakta! 

ben garibi her yerin,

ben çocuğu kederin,

gurbet! işte eserin:

evim kaldı uzakta,

annem kaldı uzakta!', 'beni meçhule saldı, umutlarım kızakta!  vatan uzakta kaldı, sevdiklerim uzakta!  ben garibi her yerin, ben çocuğu kederin, gurbet! işte eser...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Demir']::text[], 8.5, '{"poet":"Süleyman Demir","poet_slug":"suleyman-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gurbet-122-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muhakeme', 'muhakeme-suleyman-demir-y03lb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'evimden uzaktayım,

düşün yıldızlar düşün! 

bin çeşit tuzaktayım,

sonunda her bir düş''ün.

nerede o soğuk su? 

ve ormanın kokusu? 

dört bir yanında pusu,

ve yalnızsın bir düşün...', 'evimden uzaktayım, düşün yıldızlar düşün!  bin çeşit tuzaktayım, sonunda her bir düş''ün. nerede o soğuk su?  ve ormanın kokusu?  dört bir ya...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Demir']::text[], 8.5, '{"poet":"Süleyman Demir","poet_slug":"suleyman-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/muhakeme-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Farklılık ve insanlar', 'farklilik-ve-insanlar-abdulkadir-azakli-0f867', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Allah insanları farklı yaratmiş.

Mazlumu zalıme kölemi yapmış.

Her zaman eziyor zalım mazlumu.

Mazlum Allah diye diye aldanmiş.

Bazı insanlar var doğruyu bilmez.

Bazıları bilir işine gelmez.

Doğruyu yanlışı ayıran insan.

Mazlumu kendine köle eylemez.

Bilmeliyiz dostlar gerçek bozulmaz.

Gerçeği görmeyen insan sayılmaz.

Gerçek görülmeyen memleketlerde.

Düzen bozuk olur adalet olmaz.', 'Allah insanları farklı yaratmiş. Mazlumu zalıme kölemi yapmış. Her zaman eziyor zalım mazlumu. Mazlum Allah diye diye aldanmiş. Bazı insanla...', ARRAY['Türk Edebiyatı','Şiir','Abdulkadir Azaklı']::text[], 8.5, '{"poet":"Abdulkadir Azaklı","poet_slug":"abdulkadir-azakli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/farklilik-ve-insanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bunları Düşünürüm', 'bunlari-dusunurum-halil-aksoy-6urju', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yıldızlar parıldasa ne fark eder.

Nefes almaya mecalim yok.

Suratımda bir karış sakalımla, ben

Bu koca dünyada,

Yüzüm eğik gezer.

Anlayamam siyahla beyazın,

Yan yana duruşunu.

Garip duygular geçer aklımdan,

El ele tutuşan iki sevgiliyi gördüğümde.

Düşünürüm.

Ne zaman fark edecekler,

Pembeden de başka rengin olduğunu.

Sakalım uazamışken.

Anlayamam gözlerimin solmuşluğunu.

Neden bütün karıncalar,

Karşılıklı yürürken birbiriyle selamlaşır. 

Hiç mi aralarında kötülük eden yok.

İhanet eden, aldatan…

Gecelere inat güneş doğar sabahları,

Ap aydınlık bir güne,

Karanlık kaplar.

Sakalım uzamışken ve yere bakarken,

Ve nefes almaya gücüm yetmezken.

Ayın parlak ışıltısını görmezken.

Bunları düşünürüm.

Ansızın bastıran bir sağnak gibi,

Islanırım bu düşüncelerimin altında.

Ufak ufacık bir karınca olsam.

Süzülsem gitsem yuvadan içeri

İçim içine çekiyor içeri.', 'Yıldızlar parıldasa ne fark eder. Nefes almaya mecalim yok. Suratımda bir karış sakalımla, ben Bu koca dünyada, Yüzüm eğik gezer. Anlayamam ...', ARRAY['Türk Edebiyatı','Şiir','Halil Aksoy']::text[], 8.5, '{"poet":"Halil Aksoy","poet_slug":"halil-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/bunlari-dusunurum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Memleket Kokusu', 'memleket-kokusu-halil-aksoy-0445n', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne olmuş hava karlı ve soğuksa.

Fırtınadan göz gözü görmüyorsa.

Elektirik telleri kopmuş,

Minareler yıkılmışsa.

Alt tarafı memlekete gideceğiz.', 'Ne olmuş hava karlı ve soğuksa. Fırtınadan göz gözü görmüyorsa. Elektirik telleri kopmuş, Minareler yıkılmışsa. Alt tarafı memlekete gideceğ...', ARRAY['Türk Edebiyatı','Şiir','Halil Aksoy']::text[], 8.5, '{"poet":"Halil Aksoy","poet_slug":"halil-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/memleket-kokusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sadık Yarim ve Ben', 'sadik-yarim-ve-ben-erkan-arslan-s9ek5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hızla,peşim sıra,yollara düşüyorum,

Zaman küçülüp vakit sık sık darlaşıyor.

Göz önüne geliveren gölgeler malum,

Uçun gecenin pak kelebeği gölgeler...

Ben peşimde gölge hızlıca yürüyorum.

Gözlerim iple dikilmiş,ahşap tavana.

Hiç gördünüz mü peşini kaybeden adam,

Pamuk ipliği ile asılmış zamana.

İki ten arası telaş odasındalar,

Sokak ortasından,oda aralarına.

Gece yarısına kaçıp kaybolmaktalar.

Bu göğsümden fışkırarak kerpiç tavana.

Hey adam! Sen peşimde gezinen kimsin sen? 

Gün aralarından,zaman ortalarına! 

Hey dik dik yüzüme bakıp durma! Kimsin sen? 

  Boyun anca ben kadar,bu bendende kısa.

O üç benle yürürken,bu sadık ben geldi,

Gözüm,gözünün üstünden incelip kopmuş.

Bu peşimde gezinen,bu meçhul ben geldi,

Bu korkusundan dirilen gömleği kokmuş.

Büyük iş becermiş,bana mecbursun adam,

Siman bana da benzer,bu renginde solmuş.

Sere serpe yer zemine uzanmış,adam,

Her dakika ıslanan giysisi de çekmiş.

Ben giderim,gölgem sadık,benimle gider

Sadık yarim aksediyor meçhul adamdan.

Sen bu bedene hapisken,bensizlik gider.	 

Nam-ı diğer adıyla,sadık yarim ve ben...

                                         

                                              Eylül 1997', 'Hızla,peşim sıra,yollara düşüyorum, Zaman küçülüp vakit sık sık darlaşıyor. Göz önüne geliveren gölgeler malum, Uçun gecenin pak kelebeği gö...', ARRAY['Türk Edebiyatı','Şiir','Erkan Arslan']::text[], 8.5, '{"poet":"Erkan Arslan","poet_slug":"erkan-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/sadik-yarim-ve-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüya', 'ruya-serhat-caliskan-jjgi4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Lambada titreyen ateş,

Daha ne bekliyorsun,sön artık

Sönki hayallere dalayım,

Hayalimde sevgilime varayım.

Onunla bir uçağa binelim önce,

Paris,Londra,Monaco ve daha nice

Görülesi yerlere gidelim

Eğlenelim delice

Özgürce ve biz bize.

Sonra bir faytona binelim,

Eski İstanbulda

Turlayalım koca şehri 

Elele,omuz omuza.

Sonra duralım bir iskelede

Martıları sayalım,

Denizdeki balıklara birer olta atalım

Ama tutmamacasına,

Yada bir ormana gidelim onunla

Kurtlar bize kucak açsın

Kartallar selamlasın

Ağaçlaraisimlerimizi kazıyalım

Hiç silmemecesine.

Ve bir dağa çıkalım

Haykıralım semaya

Birbirimizi seviyoruuuuuuzzzzzzz

Hemde ölümüne.

Bir ağacın dibine uzanalım ardından

Papatya falları açalım,

İlanı aşklar edelim

Zaman dursun o ağacın altında,

Hiç ilerlemesin biz istemedikçe.

Derken akşam olsun,

Yağmur yağsın,fırtına kopsun

Sığınacak bir yer bulalım

Bizden başkası olmasın

Başka bir nefes girmesin aramıza.

O uyusun kollarımda

Bense yine yalvarayım lambaya

Neolur sön diye,

Bu tatlı rüyadan uyanıp

Söndürmek zorda gelse', 'Lambada titreyen ateş, Daha ne bekliyorsun,sön artık Sönki hayallere dalayım, Hayalimde sevgilime varayım. Onunla bir uçağa binelim önce, Pa...', ARRAY['Türk Edebiyatı','Şiir','Serhat Çalışkan']::text[], 8.5, '{"poet":"Serhat Çalışkan","poet_slug":"serhat-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/ruya-241-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül Bahçesi', 'gul-bahcesi-halil-aksoy-ao9tw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Önümüzde uzun yollar olsun istedik.

Gül bahçelerine giden,

Ey gül bahçelerine gidenler merhaba.

Çakıl taşları gibi serildik yollara.

Damarlarımızdaki kan aynı,

Kalplerde hep aynı dua.

Göçmen kuşlar gibi,

Katar katar olduk gökyüzünde.

Ay hatrımızı sordu.

Bulutlar selam verdi hepimize.

Yıldızlar yol gösterdi geceleyin.

Bir meşenin koynunda yattık, geceleyin

Çimenlere sorduk,’’Gül bahçeleri nerede? ’’

Gül bahçelerini arar olduk hepimiz.

Arılara sorun dediler,onlar bilir en iyi,

Birde kalpten sevenler bilir.

Güller sırlarını onlara verir.

Sabah oldu koyulduk yola.

Ey gül bahçesine gidenler.

Gönüllerinizde bıkkınlık.

Dizlerinizde yorgunluk olmaya.

Umutlar gürül gürül çağlaya.

Bulacağız gül bahçelerini.

Huzur dolacak yüreklerimiz.

Sarmaş dolaş olacak kalplerimiz.

Hepimizin yolu açık ola.', 'Önümüzde uzun yollar olsun istedik. Gül bahçelerine giden, Ey gül bahçelerine gidenler merhaba. Çakıl taşları gibi serildik yollara. Damarla...', ARRAY['Türk Edebiyatı','Şiir','Halil Aksoy']::text[], 8.5, '{"poet":"Halil Aksoy","poet_slug":"halil-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/gul-bahcesi-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Martı Çığlığı', 'marti-cigligi-abdullah-oral-xw7pn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Martı çığlığı

Üreti ayaklarına düşeli sermayenin

bütün emekçiler 

kendi coğrafyalarının sürgünü oldular.

özverinin hüküm sürdüğü topraklara

şimdilerde hüzün ekiliyor,

Gün gelir mavileri çalınmış bir çınar

Döker eteklerinden gök yüzünüde.

O gün

 güvercin kanatlı şiirler kuşatır yer yüzünü.

Bölüşürken ekmeği güneşin sofrasında.

Sonra okyanus olur yüreğinde 

              Yıkar kendi kıyılarını 

Gayrı sığdıramazsın Göğüs kafesine

             Her yer de Martı çığlığı …', 'Martı çığlığı Üreti ayaklarına düşeli sermayenin bütün emekçiler  kendi coğrafyalarının sürgünü oldular. özverinin hüküm sürdüğü topraklara ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Oral']::text[], 8.5, '{"poet":"Abdullah Oral","poet_slug":"abdullah-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/marti-cigligi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Memlekete dönerken', 'memlekete-donerken-suleyman-demir-0cqhk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sen benim bir haziran sabahı yarı ayık,

Doğankent''ten Kürtün''e dönüşümsün pürneşe! 

yüreğim ki bir coşkun sevinç ile kabarık, 

gözlerim ki telaşlı varmak için güneşe...

pırıl pırıl bir güneş karşılıyorken bizi, 

haşin çamlarla süslü yüce dağ başlarından,

artık görmesem n''olur hırçın Karadeniz''i? 

binbir okyanus akar şelale taşlarından...

binbir renkte çiçekler ağaçlar arasında,

nazlı nazlı parlarken çiğ düşen yaprakları,

çarpar durur yüreğim daha yol yarısında,

öpmek ister dudağım eğilip toprakları...

rüzgarların esmekte güçlük çektiği dünya! 

dağları,taşları,insanıyla şahane...

biter gurbet elinde ıstırap yüklü rüya,

ve avuçlar kalbimi yemyeşil Gümüşhane', 'sen benim bir haziran sabahı yarı ayık, Doğankent''ten Kürtün''e dönüşümsün pürneşe!  yüreğim ki bir coşkun sevinç ile kabarık,  gözlerim ki t...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Demir']::text[], 8.5, '{"poet":"Süleyman Demir","poet_slug":"suleyman-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/memlekete-donerken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tatil-Bayram ve Biz', 'tatil-bayram-ve-biz-halil-aksoy-wow44', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sabah kalkar güneşi severiz

Kahvaltımızı yapar.

Serçelere selam veririz.

Canımız sıkıldı mı sahilde gezer.

Bir bankta oturur.

Hem dinlenir hem simit yeriz.

Akşam oldumu,

Mutfağımızda yemeğimizi yer. 

Kumandayı alır televizyon seyrederiz.

Filmin yarısında uykumuz gelir.

En kısa yoldan yatağa gideriz. 

Memlekete gitsek,

Budefa kurban kesemeyiz.

Biz önü arkası belli memuruz.

Böyledir bayramımız,

Böyledir bizim tatilimiz.', 'Sabah kalkar güneşi severiz Kahvaltımızı yapar. Serçelere selam veririz. Canımız sıkıldı mı sahilde gezer. Bir bankta oturur. Hem dinlenir h...', ARRAY['Türk Edebiyatı','Şiir','Halil Aksoy']::text[], 8.5, '{"poet":"Halil Aksoy","poet_slug":"halil-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/tatil-bayram-ve-biz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başardım', 'basardim-halil-aksoy-ouzqp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hayat nedir? 

Başarmak bunun neresinde? 

Nefes aldığımız zaman mı? 

Başarmış oluruz....

Yoksa,

Kendimizi avutmak mıdır? 

Başarmak.

Adı aynıdır onun, herkes için.

Ama yaşanan hayatlar farklı.

Farklıdır her hayat içinde,

Başarmanın tadı.

Hayat nedir? 

Başarmak bunun neresinde? 

Kime neye göre başardım diyeceğim.

Hayal kırıklıklıklarını mı örtmek için başarılı oluruz? 

Yoksa bize aferin desinler diye mi? 

Kabul görmek mi derdimiz? 

Her ne olursa olsun.

Hepimizin ihtiyacı var başarmaya.

Nefes almak ta başarmak değil midir? 

Haydi ne duruyorsunuz? 

Nefes alalım doya doya.', 'Hayat nedir?  Başarmak bunun neresinde?  Nefes aldığımız zaman mı?  Başarmış oluruz.... Yoksa, Kendimizi avutmak mıdır?  Başarmak. Adı aynıd...', ARRAY['Türk Edebiyatı','Şiir','Halil Aksoy']::text[], 8.5, '{"poet":"Halil Aksoy","poet_slug":"halil-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/basardim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üzgünüm', 'uzgunum-halil-aksoy-edfkl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bizimkide nafile.

Yaradana sual olunmazki.

Koskoca biçimsiz kafamız varmış.

Doymasını bilmeyen bir de mide.

Durum vaziyet belli.

Herşey gözler önünde.

Işıldayan göz,

Gümbür gümbür atan kalp,

Kimin umurunda.

Anlaşılan herşey görüntüde.

Saçılıveriyor duygular,

İnci taneleri gibi etrafa.

Donuk bakışlarla karşılaşınca

Üzüzlüyor,

Üzülüyor insan.

Neden üzüldüğünü anlamasada. 

Anladık biraz etine dolgunuz işte. 

Hiç mi kilolu adam görmediniz?', 'Bizimkide nafile. Yaradana sual olunmazki. Koskoca biçimsiz kafamız varmış. Doymasını bilmeyen bir de mide. Durum vaziyet belli. Herşey gözl...', ARRAY['Türk Edebiyatı','Şiir','Halil Aksoy']::text[], 8.5, '{"poet":"Halil Aksoy","poet_slug":"halil-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/uzgunum-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kirdin Sevdigim', 'kirdin-sevdigim-yasar-gurlek-eza5f', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gine  duman  coktu,  gonul  dagima

Yildirimlar   dustu,  sag  yanima

Dusman  guler  oldu,  benim  halima

Kolumu  kanadimi  kirdin   sevdigim

Deger  bana  butun,  dunya  taslari

Pinar  oldu  akar, gozum yaslari

Biraktin ustume,  butun  suclari

Dalimi  budagimi  kirdin sevdigim

Nedir  felek senin, benle islerin

Yalan oldu hayal oldu, benim duslerim

Yerden  yere  vurdu  beni, bu  gidislerin

Gonlumu  kalbimi  kirdin  sevdigim

Yasar,i  aglarsin hep,  gulmek yasakmi

Bendeki  bu  beni,  alip  asakmi

Zorla  verdin  aski,  simdi  kusakmi

Sevdami  askimi  kirdin  sevdigim

Yasar  Gurlek

15-03-2006

ROTTERDAM

HOLLANDA', 'Gine  duman  coktu,  gonul  dagima Yildirimlar   dustu,  sag  yanima Dusman  guler  oldu,  benim  halima Kolumu  kanadimi  kirdin   sevdigim...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Gürlek']::text[], 8.5, '{"poet":"Yaşar Gürlek","poet_slug":"yasar-gurlek","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kirdin-sevdigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haziran 26', 'haziran-26-abdullah-oral-xooy7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '26 HAZİRAN

Güneşe kaldırdık başlarımızı

Umutlara tohum ekenlere bak

Rüzgarlara saldık biz sevdamızı

Hücrede ölüme gidenlere bak

Aşılmaz dediler aşıldı dağlar

On iki sevdayla çatladı duvar

Ne zincir kar eyler ne prangalar

Ölümü taşlara çalanlara bak

Umut tohumları toprağa düştü

Beyinsiz softalar aklını şaştı

Koç yiğitler bulutlara ulaştı

Ölümü hücreye gömenlere bak

Zalimin kırbacı düştü elinden

Kanıyor yaralar daha derinden

Vurguni dost akan  umut selinden

Coştukça bendini yıkanlara bak', '26 HAZİRAN Güneşe kaldırdık başlarımızı Umutlara tohum ekenlere bak Rüzgarlara saldık biz sevdamızı Hücrede ölüme gidenlere bak Aşılmaz dedi...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Oral']::text[], 8.5, '{"poet":"Abdullah Oral","poet_slug":"abdullah-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/haziran-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaldiralim Biz', 'kaldiralim-biz-yasar-gurlek-o6af5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ozmusun oveymisin,  soyle  bilelim

Bilelimde  ona  gore,  bizde  gulelim

Yakinmisin uzakmisin,  soyle  gelelim

Aramizda  engelleri,  kaldiralim  biz

Ne  guldun ne  guldurdun,  aglariz  boyle

Sirmisin  sirdasmisin,  gel  bunu  soyle

Yetmedimi  izdirabin, sen insaf  eyle

Aramizda  bu   daglari,  kaldiralim  biz

Yasar,inin  balindan,  yiyip  ictinmi

Daha once bu dergahtan, gelip gectinmi

Dostunu  dusmanini,  iyi  sectinmi

Aramizda  dusmanlari  kaldiralim  biz

Yasar  Gurlek

15-03-2006

ROTTERDAM

HOLLANDA', 'Ozmusun oveymisin,  soyle  bilelim Bilelimde  ona  gore,  bizde  gulelim Yakinmisin uzakmisin,  soyle  gelelim Aramizda  engelleri,  kaldira...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Gürlek']::text[], 8.5, '{"poet":"Yaşar Gürlek","poet_slug":"yasar-gurlek","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kaldiralim-biz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pişman Olma', 'pisman-olma-halil-aksoy-jjcib', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen ki hayatımdan bir yaprak gibi kopan kadın.

Aklına bir şey gelmesin.

Sana kırgınlığım yok.

Gittiğine kendin pişman olacaksın.

Pişman olup  döndüğünde,

Birde bakmışsın.

Bıraktığın yerde,

Aynı güneş, aynı hava,aynı nefes yok.

Gidişine kendinde şaşacaksın.

Aklına bir şey gelmesin.

Sana kırgınlığım yok.

Kendi doğrularını kendin bilir,

Kendi doğrularının peşinden gidersin.

O doğrular değil midir bizi ayakta tutan? 

Bizi yaşatan.

Aklına bir şey gelmesin.

İnanki tek endişem.

O doğrular,

Seni benim yanıma tekrar getirmesin. 

Eh gelirsen de,

Neye niyet kime kısmet.

Gün ola devran döne,

Kim öle kim kala.', 'Sen ki hayatımdan bir yaprak gibi kopan kadın. Aklına bir şey gelmesin. Sana kırgınlığım yok. Gittiğine kendin pişman olacaksın. Pişman olup...', ARRAY['Türk Edebiyatı','Şiir','Halil Aksoy']::text[], 8.5, '{"poet":"Halil Aksoy","poet_slug":"halil-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/pisman-olma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maasallah', 'maasallah-yasar-gurlek-y8pp0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Pinarin basina  oturmus  nidelim

Bu  beladan kacipta  nere  gidelim

Hele  bir yanasak, bir laf edelim

Sevilir   severiz    INSAALLAH

Basina  baglamis  acem  salini

Sorum dedim su guzelin halini

Baktikca vuruldum, cemalini

Nazar   degmesin  MAASALLAH

Gozlerine  vurulup, baglanip kaldim

Bu belayi  ben niye,  basima  aldim

Ask  denen deryaya,  daldikca  daldim

Yakildim yikildim  MAAZALLAH

O gunden bu gune, yanar  aglarim

Done  done yaralara,  kara  baglarim

Ozan olduk, sair olduk, boyle caglarim

O gunden bu gune  EYVAALLAH

Yasar,i  gormedi,  yuzun bir  daha

Bendeki  muratlar, hep kalkmis  saha

Yemin olsun yemin, bin yemin aha

Sevmiyecem bir daha   ILLAALLAH

Yasar  Gurlek

15-03-2006

ROTTERDAM

HOLLANDA', 'Pinarin basina  oturmus  nidelim Bu  beladan kacipta  nere  gidelim Hele  bir yanasak, bir laf edelim Sevilir   severiz    INSAALLAH Basina ...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Gürlek']::text[], 8.5, '{"poet":"Yaşar Gürlek","poet_slug":"yasar-gurlek","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/maasallah-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnat', 'i-nat-halil-aksoy-li5iz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gökyüzü karanlık mı karanlık,

Havada alabildiğine soğuk,

Şunlara baksana.

İkisi  bir olmuş,

Bu akşam karşılar bana.

İnadına soğuk,

İnadına karanlık.

Birleşmişler inadına.

Sokak lambaları bile,

Titreyerek işık saçmakta.

Bende üşüdüm demiyorum.

Ellerimi oğuşturmuyorum.

Gece gökyüzüne bakmıyorum.

Karanlığın ve soğuğun inadına.', 'Gökyüzü karanlık mı karanlık, Havada alabildiğine soğuk, Şunlara baksana. İkisi  bir olmuş, Bu akşam karşılar bana. İnadına soğuk, İnadına k...', ARRAY['Türk Edebiyatı','Şiir','Halil Aksoy']::text[], 8.5, '{"poet":"Halil Aksoy","poet_slug":"halil-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/inat-46-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kacip Gittiler', 'kacip-gittiler-yasar-gurlek-yazvq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Uc  bes kisi bir  olup  yolum kestiler

Deli ruzgar gibi gelip estiler

Bu yollarda kirilir bizde testiler

Gorunce demiri kacip gittiler

Neyin nesi anlamadim kimdi bu itler

Hepte gelir beni bulur yavsaklar bitler

Ellerindede var idi demirden sisler

Gorunce silahi kacip gittiler

Hic bir kula olmamistir benim zararim

Ben benle secdece yari  ararim

Vuracaktim hepsini vardi kararim

Cekince silahi kacip gittiler

Yasar,i  ye   kurmuslar bir guzel tuzak

Yaklasamiyor itler hepside uzak

Ne od var bunlarda nede kursak

Parlayinca  silah  kacip  gittiler

Yasar  Gurlek

15-03-2006

ROTTERDAM

HOLLANDA', 'Uc  bes kisi bir  olup  yolum kestiler Deli ruzgar gibi gelip estiler Bu yollarda kirilir bizde testiler Gorunce demiri kacip gittiler Neyin...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Gürlek']::text[], 8.5, '{"poet":"Yaşar Gürlek","poet_slug":"yasar-gurlek","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kacip-gittiler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Kadın', 'sen-kadin-emre-saricicek-i9au6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Derdime dert kattın.

Kalbinden hemen attın.

On paraya beni sattın.

Ne zalimsin sen kadın.

Yalnızlığında yıldızsın sen.

Aydınlatan gecemsin sen.

Bir zalime kapıldım ben.

Ne zalimsin sen kadın.

Malım mülküm kalmadı.

Sensiz günüm olmadı.

Bu aşk beni bunalttı.

Ne zalimsin sen kadın.

Beni benden aldın sen.

Bir kenara attın sen.

Virane olsamda ben.

Ne zalimsin sen kadın.

Yaşayacağın gün bugündür.', 'Derdime dert kattın. Kalbinden hemen attın. On paraya beni sattın. Ne zalimsin sen kadın. Yalnızlığında yıldızsın sen. Aydınlatan gecemsin s...', ARRAY['Türk Edebiyatı','Şiir','Emre Sarıçiçek']::text[], 8.5, '{"poet":"Emre Sarıçiçek","poet_slug":"emre-saricicek","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sen-kadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasıl hoş göreyim', 'nasil-hos-goreyim-abdullah-oral-cd7ce', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'NASIL HOŞ GÖREYİM

Her yeni yıldan bir şeyler bekleriz

Umut etmek gayrı soldurur beni

Öğretmen istiyor, çocuklar suçlu

İnsanlık ayıbı öldürür beni

Post modern bir pislik gezer evreni

Yalancıktan koru derler çevreni

Yeni dünya diye zorba düzeni

Baksana tarihten sildirir beni

Hani nerde kaldı sınıfsal bilinç

Her gün maymunlaştık olduk çok gülünç 

Sofunun yobazın elinde kılıç

Ot deyip topraktan yoldurur beni

Tutmuyor dizlerim dağları aşam

Kim çaldı düşleri söyle ey paşam

Hoşgörü derler ya onursuz yaşam

Dostun ölümüne güldürür beni

Pişmemiş, çiğ kalmış insan hamuru

Herkes birbirine atar çamuru

Dünyayı kirleten asit yağmuru 

Zamansız uykuya daldırır beni

Hani Avrupa’ydı aydınlar yurdu

Söyleyin Bosna''yı kimler kırdırdı

Deyyusların hepsi birden kudurdu

Gayrı gelecekte yıldırır beni

Viyetnam’da solgun gördüm gülümü

Afgan’da kestiler kökten dilimi

Irak’ta Amerikalı zulümü 

Toplu mezarlara doldurur beni

Vurguni soyguncu kapar hep payı

Geceye saklanmış gün görmez ayı

Nasıl hoş göreyim böyle dünyayı

Somali’de açlık öldürür beni', 'NASIL HOŞ GÖREYİM Her yeni yıldan bir şeyler bekleriz Umut etmek gayrı soldurur beni Öğretmen istiyor, çocuklar suçlu İnsanlık ayıbı öldürür...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Oral']::text[], 8.5, '{"poet":"Abdullah Oral","poet_slug":"abdullah-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/nasil-hos-goreyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Renk Renk Oldu', 'renk-renk-oldu-yasar-gurlek-kg4e2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Pisman olup anlamissin, sende hatani

Uzulme  buzulme  af  ettim  seni

Seni degil bilirim  ben,  senin atani

O dostun hatirina  af ettim  seni

Renk renk oldu birden, gorunce  beni

Korkma  morkma  af ettim seni

Nasilsa  bilmeden, uzmussun beni

O yarin hatirina  af  ettim  seni

Bundan sonra dikkat et, dalma her seye

Bu devirde deveyi, koyarlar kucuk siseye

Her zaman iyi bak, kiyi  koseye

O canan  hatirina  af  ettim  seni

Yasar,i bir tek,  ALLAH tan korkar

Cekinmez bir seyden, yilan olup sarkar

Kotulugu bu dunyada, saymadi  kar

Onun icin onun  icin af  ettim  seni

Yasar  Gurlek

15-03-2006

ROTTERDAM

HOLLANDA', 'Pisman olup anlamissin, sende hatani Uzulme  buzulme  af  ettim  seni Seni degil bilirim  ben,  senin atani O dostun hatirina  af ettim  sen...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Gürlek']::text[], 8.5, '{"poet":"Yaşar Gürlek","poet_slug":"yasar-gurlek","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/renk-renk-oldu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret', 'hasret-halil-aksoy-54z6d', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hasret bitiyor.

Özlediğim sevdiğim günler yakın.

Bunaldık içeride oturmaktan.

Dört duvar arasına sıkışmaktan.

Hasret bitiyor.

Az kaldı toprağın doğanın uyanmasına.

Az kaldı doğa ile kucaklaşmama.

Çiçekler arasında dolaşacağım.

Kelebeklerle yarışacağım.

Karıncalarla selamlaşıp,

Kendimi yem yeşil cimlere bırakacağım.

Gökte  uçan kuşlara,

Bulutlara el sallayacağım.

Toprağın kokusunu,

Göğsüme  dolduracağım.

Hasretten sabırsızlaşan ellerimi,

Toprağa gömüp.

Anneme sarılır gıbi sarılacağım.

Az kaldı.', 'Hasret bitiyor. Özlediğim sevdiğim günler yakın. Bunaldık içeride oturmaktan. Dört duvar arasına sıkışmaktan. Hasret bitiyor. Az kaldı topra...', ARRAY['Türk Edebiyatı','Şiir','Halil Aksoy']::text[], 8.5, '{"poet":"Halil Aksoy","poet_slug":"halil-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/hasret-344-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akıllı olan insan', 'akilli-olan-insan-abdulkadir-azakli-9siq2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Akıllı olan insan, İyi düşünmelidir.

Geriye doğru değil, ileri gitmelidir.

Hep güleryüz olalım, hiç gönül kırmayalım.

Menfaat peres olup, hayale dalmayalım.

Yaşadığın bu ömrü, geçir mutlu olarak.

Kederde yardımlaşıp, neşeyi paylaşarak

Hep ileri bakalım ufkumuz geniş olsun.

Kini nefreti bırak  insanlar kardeş olsun.

Hep güzel düşünelim, barış sever olalım.

Gideceğimiz yolun, doğrusunu bulalım.

Eğer komşun ağlarsa,sende onunla ağla.

Elinden geliyorsa yaralarını bağla.

Adaleti unutma, her an aklında olsun.

Sen haklıdan yana ol isterse kafir olsun.', 'Akıllı olan insan, İyi düşünmelidir. Geriye doğru değil, ileri gitmelidir. Hep güleryüz olalım, hiç gönül kırmayalım. Menfaat peres olup, ha...', ARRAY['Türk Edebiyatı','Şiir','Abdulkadir Azaklı']::text[], 8.5, '{"poet":"Abdulkadir Azaklı","poet_slug":"abdulkadir-azakli","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/akilli-olan-insan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değişim', 'degisim-yilmaz-turkyilmaz-31ymf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Herkes değişti değişti,

Bir biz eski kaldık şurada.

Zengin olup değişmeyen,

Kaç kişi gördük şurada? 

Değişiklik imaj falan,

Ömrümüze hakim yalan,

Bizi yalnız insan kılan,

Söyle ne kaldı şurada? 

Paran varsa sen adamsın,

Malın varsa havadasın,

Garipleri kim tanısın? 

Yoksul kaldık biz şurada.

Hepten marka düşkünüyüz,

Ense göbek şişkiniyiz,

Yalan dolan pişkiniyiz,

Daha ne çaldık şurada! ? 

TÜRKYILMAZ olduk haşarı,

Sözüm meclisten dışarı,

Şeref dibe, şan yukarı,

Bir yere vardık şurada.

Her yere vardık şurada.

                              29.11.2002- Antalya', 'Herkes değişti değişti, Bir biz eski kaldık şurada. Zengin olup değişmeyen, Kaç kişi gördük şurada?  Değişiklik imaj falan, Ömrümüze hakim y...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Türkyılmaz']::text[], 8.5, '{"poet":"Yılmaz Türkyılmaz","poet_slug":"yilmaz-turkyilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/degisim-47-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bedel', 'bedel-halil-aksoy-e1s3r', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözlerindeki ışıltıyı,

Ateş sandım.

Kalbimi yakacak.

Işıltın kalbimi değil,

Ruhumu yaktı kararttı.

Ne yürek,ne sevgi,ne kucak,

Bırakmadın açacak.

Olacağı varmış oldu.

Bir kör kurşuna kurban gittik.

Küçük bir tebessüme,

Her şeyi feda ettik.

Nasihat uyarı kar etmiyor.

Dostlar alınmasın.

Acılar sevinçler mutlaka yaşanıyor.

Bende yaşadım senin gözlerinde,

Yaşanacak ne varsa

Hayat insana herşeyi öğretiyor.

Herşeyin bir bedeli var.

Her insan bunu er geç ödüyor.', 'Gözlerindeki ışıltıyı, Ateş sandım. Kalbimi yakacak. Işıltın kalbimi değil, Ruhumu yaktı kararttı. Ne yürek,ne sevgi,ne kucak, Bırakmadın aç...', ARRAY['Türk Edebiyatı','Şiir','Halil Aksoy']::text[], 8.5, '{"poet":"Halil Aksoy","poet_slug":"halil-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bedel-50-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda kapısı', 'sevda-kapisi-abdullah-oral-ovifr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'SEVDA KAPISI

Ehil olmayanlar aşk şerbetini

İçtikçe kendinden geçebilir mi? 

Kefensize kefen diye ömrünü

Ak libas kumaştan biçebilir mi? 

Yaşam dediğimiz koca bir çınar

Her gelen geçen kuş dalına konar

Duldasında ölüm izleri var yar

Gönül bu ateşten kaçabilir mi? 

Kurumuş dallarda açar mı çiçek

Düş içinde sevgi olur mu gerçek

Arı bal yaparken oturan böcek

Sevda kapısını açabilir mi? 

Vurguni bu sevda üşütür bizi

Dilek ağacına yazılmış yazı

Aşık olanların kör imiş gözü

Kuşlar gibi konup göçebilir mi?', 'SEVDA KAPISI Ehil olmayanlar aşk şerbetini İçtikçe kendinden geçebilir mi?  Kefensize kefen diye ömrünü Ak libas kumaştan biçebilir mi?  Yaş...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Oral']::text[], 8.5, '{"poet":"Abdullah Oral","poet_slug":"abdullah-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sevda-kapisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir', 'siir-halil-aksoy-yuwvy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şiir bir acılar denizidir.

Demiş üstat.

Katılmamak mümkün mü.', 'Şiir bir acılar denizidir. Demiş üstat. Katılmamak mümkün mü....', ARRAY['Türk Edebiyatı','Şiir','Halil Aksoy']::text[], 8.5, '{"poet":"Halil Aksoy","poet_slug":"halil-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/siir-154-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelme', 'gelme-halil-aksoy-on4nx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kalmaya niyetin yoksa, gelme hiç.

Benim kalbim yol geçen hanı değil.

Beyhude akan sular gibi,

Akıttım göz yaşlarımı.

Susuz kalmış topraklara çevirdin, dudaklarımı.

 Gelme artık gelme.

Bu gönül artık sana muhtaç değil.', 'Kalmaya niyetin yoksa, gelme hiç. Benim kalbim yol geçen hanı değil. Beyhude akan sular gibi, Akıttım göz yaşlarımı. Susuz kalmış topraklara...', ARRAY['Türk Edebiyatı','Şiir','Halil Aksoy']::text[], 8.5, '{"poet":"Halil Aksoy","poet_slug":"halil-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/gelme-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Temmuzlar Üşür', 'temmuzlar-usur-abdullah-oral-pgr3t', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'TEMMUZLAR ÜŞÜTÜR

Öyle bir bahçe ki şu Anadolu

Yakmış yüreğini yozda insanlar

Kardeşliğin katli vacip olalı

Ot gibi biçilir bizde insanlar

Kızılırmak akar kendi halinde

Turnalar geziyor sevda gölünde

Bir it ulur uzak Arap çölünde 

Yakar türküleri sözde insanlar

Güneş küsmüş  dönmez şu kssara güce

Bu nasıl sır bilmem nasıl bilmece

Kap kara öfkeye tutunmuş gece

Üşümüş temmuzda yazda insanlar

Ovalarım çimen, gül yaprakları

Kan ile yuğmuşlar bu toprakları

Unutulmuş bizde insan hakları

Can verir elleri sazda insanlar

Vurguni der sofu birazcık düşün 

İnsan katletmek mi hep senin işin

Yakar mı türküyü o kör ateşin

Semah tutar döner közde insanlar', 'TEMMUZLAR ÜŞÜTÜR Öyle bir bahçe ki şu Anadolu Yakmış yüreğini yozda insanlar Kardeşliğin katli vacip olalı Ot gibi biçilir bizde insanlar Kı...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Oral']::text[], 8.5, '{"poet":"Abdullah Oral","poet_slug":"abdullah-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/temmuzlar-usur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Gün Bu Gün mü Yoksa?', 'o-gun-bu-gun-mu-yoksa-yilmaz-turkyilmaz-hkb7q', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'O gün bugün mü yoksa?

Işık sızmalı,

Ağzı kilitli gümüş sandıklara.

Akışı değişmeli zamanın,

Yükselmeli ayaklarımızın altındaki dağlar! ? 

Dokunmalı biiir bir,

Erişilmez sandığımız nice yıldızlara…

Haykırışlarımı duymalı gönlün,

Dönüşmeden yalvarışlara! ...

Çözülmeli buzlar aramızda,

Gök kuşağından damlacıklarla.

Harmanım savruldu diyenlerden değilim,

Ben her baharda filizlenirim,

Her hazanla dem tutarım mahzenlerde…

Yanar tüterim kimi zaman! 

Odun olmam, bir yakımlık sobalarda! 

Ey titrek gönlün mahzun bedeni! 

Ey ateşli bakışların habersiz gözleri! 

Ya el ver gönlünün götürdüğü yere kadar,

Yada üstümden çek,

Yüreğime dokundurduğun, şirin şifa ellerini…

                                          16.06.2004- Antalya', 'O gün bugün mü yoksa? Işık sızmalı, Ağzı kilitli gümüş sandıklara. Akışı değişmeli zamanın, Yükselmeli ayaklarımızın altındaki dağlar! ?  Do...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Türkyılmaz']::text[], 8.5, '{"poet":"Yılmaz Türkyılmaz","poet_slug":"yilmaz-turkyilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/o-gun-bu-gun-mu-yoksa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme', 'gitme-halil-aksoy-b5bji', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gitme bir tanem.

Bana mutluluk dileme.

Nefesini tenimde hissetmek,

Dünyanın en büyük mutluluğu,

Benim için.

Ben açmamış goncalar,

Kardan beyaz güller istemem.

Başka koku deydirmem,

Tenime.

Yaşıyorsam dünyada,

Bil ki bu senin için.

Gitme bir tanem.

Bana başka acılar yaşatma.

Sarıl bir tanem,

Doyasıya sarıl.

Kulağıma ayrılık rüzgarları çınlatma.', 'Gitme bir tanem. Bana mutluluk dileme. Nefesini tenimde hissetmek, Dünyanın en büyük mutluluğu, Benim için. Ben açmamış goncalar, Kardan bey...', ARRAY['Türk Edebiyatı','Şiir','Halil Aksoy']::text[], 8.5, '{"poet":"Halil Aksoy","poet_slug":"halil-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gitme-165-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diyemezdim ki', 'diyemezdim-ki-altay-taskin-y80ce', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yaşıyorum yaşıyorum

neler görüyorum

bir gün pencereden bakarken

süslü püslü arabalarla

sevinç-coşku içinde eğlenerek

düğün yapanları

belki gözlerimin içi gülüyor

benim de haberim olmadan

onlar öyle geçip gidiyor

yaşıyorum yaşıyorum

bakıyorum gözlerimle yine

ama pencereden ama yolda yürürken

omuzlarda taşınan bir hüzün

üstü bayrakla örtülü bazen yeşil örtüyle

gözlerimin içi yaş doluyor gidenler için

diyemezdim ki ne düğün olmasın

ne de tabut görünmesin gözlerime

sadece katlanmam gerekir bu gördüklerime

ister istemez yaşadığım sürece...', 'yaşıyorum yaşıyorum neler görüyorum bir gün pencereden bakarken süslü püslü arabalarla sevinç-coşku içinde eğlenerek düğün yapanları belki g...', ARRAY['Türk Edebiyatı','Şiir','Altay Taşkın']::text[], 8.5, '{"poet":"Altay Taşkın","poet_slug":"altay-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/diyemezdim-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Aşk', 'ey-ask-halil-aksoy-yi3b9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yalnızca ikimiz  vardık,

Ay ve yıldızları saymassak,

Yanlızdık ikimiz o gece,

Yapayanlızdık.

Ey aşk sen nelere kadirsin. 

Oturduk bütün gece,

Gökteki tüm yıldızları saydık', 'Yalnızca ikimiz  vardık, Ay ve yıldızları saymassak, Yanlızdık ikimiz o gece, Yapayanlızdık. Ey aşk sen nelere kadirsin.  Oturduk bütün gece...', ARRAY['Türk Edebiyatı','Şiir','Halil Aksoy']::text[], 8.5, '{"poet":"Halil Aksoy","poet_slug":"halil-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ey-ask-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğinde Uyut', 'yureginde-uyut-hasan-ozturk-2-l9mg1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevği dolu, yanık sözlerde.

Keder yüklü, yaşlı gözlerde.

Hasret tüten, acı günlerde.

Yüreğinde uyut, bul beni.

O beklettiğin, viran yerde.

İlk verdiğin, soluk güllerde.

Seni öptüğüm, boş sahilde.

Yüreğinde uyut, gör beni.

Cılğın aşık, garip halimle.

Sevğim olsun, sana hediye,

Saklı varsa, bakıp resmime,

Yüreğinde uyut, sal beni.', 'Sevği dolu, yanık sözlerde. Keder yüklü, yaşlı gözlerde. Hasret tüten, acı günlerde. Yüreğinde uyut, bul beni. O beklettiğin, viran yerde. İ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Öztürk 2']::text[], 8.5, '{"poet":"Hasan Öztürk 2","poet_slug":"hasan-ozturk-2","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yureginde-uyut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün', 'bugun-abdullah-oral-pqqel', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'BUGÜN

Yüreğimi ince ateş sarınca

Dalımda çiçekler allandı bugün

Güneşin üstüne yağmur yağınca

Yine çiçeklerim sellendi bugün.

Gördüm hayat denen yaşam selinde

Dost kendini arar olmuş kendinde 

Vurulmuş sevdalar kalmış enginde

Hüzün bizden yana yollandı bugün.

Zemheri üstüne bahar gelince

Kar mı kalır dağda rüzgar esince

Kardelen çiçeğe hele düşünce

Yeniden dallarım güllendi bugün.

Vurguni gidem de dosta yüz sürem

Arzuhal edeyim hatırın soram

Kanarsa yarası bir çaput saram

Sazlar sese geldi dillendi bugün...', 'BUGÜN Yüreğimi ince ateş sarınca Dalımda çiçekler allandı bugün Güneşin üstüne yağmur yağınca Yine çiçeklerim sellendi bugün. Gördüm hayat d...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Oral']::text[], 8.5, '{"poet":"Abdullah Oral","poet_slug":"abdullah-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bugun-93-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaz Gelmeyecek', 'yaz-gelmeyecek-halil-aksoy-yxmww', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hafiften esen bir lodos.

Hava kapalı.

İnceden inceden yağmur atıştırmakta.

Deniz gene gümüş rengini almış.

Kış görüntüsünü andıran bir hava.

Yok yok anlaşılan bu sene yaz gelmeyecek.', 'Hafiften esen bir lodos. Hava kapalı. İnceden inceden yağmur atıştırmakta. Deniz gene gümüş rengini almış. Kış görüntüsünü andıran bir hava....', ARRAY['Türk Edebiyatı','Şiir','Halil Aksoy']::text[], 8.5, '{"poet":"Halil Aksoy","poet_slug":"halil-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yaz-gelmeyecek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuk Olsam', 'cocuk-olsam-halil-aksoy-qokzi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Keşke çocuk olsam.

Koşsam,uçarcasına koşsam,

Uçsuz bucaksız,

Kırlarda bayırlarda.

Geceleyin yıldızlardan ev yapsam kendime,

Aydan fener.

Kayan yıldızları selamlasam,birer birer.

Keşke çocuk olsam,

Kıvrılıp yatsam annemin koynuna,

Bir kolu yastık olsa,

Bir kolu yorgan.

Götürse beni düşler sokağına.

Aydınlığın tam ortasına.

Keşke çocuk olsam.

Çocuklarla oynasam.

Sıcak,

Sıcacık.

Dostluklar kursam.', 'Keşke çocuk olsam. Koşsam,uçarcasına koşsam, Uçsuz bucaksız, Kırlarda bayırlarda. Geceleyin yıldızlardan ev yapsam kendime, Aydan fener. Kay...', ARRAY['Türk Edebiyatı','Şiir','Halil Aksoy']::text[], 8.5, '{"poet":"Halil Aksoy","poet_slug":"halil-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/cocuk-olsam-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söyle Sazım', 'soyle-sazim-suna-doganay-abhjf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir tuhaflık sezdim sazım telinde,

Dağların ardında son gül dalında.

Kaç hasret vuruldu omuzlarında,

Söyle sazım neden dertli çalarsın? 

Dalga dalga esen yelin ardından,

Oluk oluk ter akıyor alnından.

Uykuya yas tutan akşamlarından,

Söyle sazım neden dertli çalarsın? 

Dünyanın yükünü sen mi taşırsın,

Kazarlar kuyunu dostsuz kalırsın.

Giden dönmüyorsa yer gök yarılsın.

Söyle sazım neden dertli çalarsın? 

Ne evini bilir ne de köyünü

Kendini saklar da vermez huyunu.

Dalından koparır gonca gülünü,

Söyle sazım neden dertli çalarsın? 

Yarısı karanlık yarısı loştur.

Bir lokma ekmeğin helâli hoştur.

Örümcek ağ örer çırpınmak boştur.

Söyle sazım neden dertli çalarsın? 

Dertsiz ırmakların dingin yatağı,

Karanfil kokulu bülbül otağı

Oltaya takılır söner ocağı

Söyle sazım neden dertli çalarsın?', 'Bir tuhaflık sezdim sazım telinde, Dağların ardında son gül dalında. Kaç hasret vuruldu omuzlarında, Söyle sazım neden dertli çalarsın?  Dal...', ARRAY['Türk Edebiyatı','Şiir','Suna Doğanay']::text[], 8.5, '{"poet":"Suna Doğanay","poet_slug":"suna-doganay","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/soyle-sazim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Papatyalar', 'papatyalar-altay-taskin-4i299', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'güneş açmış baharda

toprak sevinçli

esneyerek uyanıyor papatyalar

bakınarak etrafa

katılmak için şenliğe

giymişler beyaz eteklerini

kendilerinden geçmiş

oynuyorlar arılarla

baharın süsü

tepelerde deniz olmuş

dalgalanıyor papatyalar

koparmayın onları

kırlarda gezenler

otlayan koyunlar

kavallı çobanlar

onları gülerken 

görelim

topraktan ayırırsak

hep beraber ağlarlar...', 'güneş açmış baharda toprak sevinçli esneyerek uyanıyor papatyalar bakınarak etrafa katılmak için şenliğe giymişler beyaz eteklerini kendiler...', ARRAY['Türk Edebiyatı','Şiir','Altay Taşkın']::text[], 8.5, '{"poet":"Altay Taşkın","poet_slug":"altay-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/papatyalar-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüzgar Gülü', 'ruzgar-gulu-halil-aksoy-81ftc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yeter artık dönme be, rüzgar gülü.

Zaten dünya dönüyor.', 'Yeter artık dönme be, rüzgar gülü. Zaten dünya dönüyor....', ARRAY['Türk Edebiyatı','Şiir','Halil Aksoy']::text[], 8.5, '{"poet":"Halil Aksoy","poet_slug":"halil-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/ruzgar-gulu-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İyilik Yap', 'i-yilik-yap-yilmaz-turkyilmaz-dosbe', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İyiliktir insanlığın direği,

İyilik yap arkasını arama.

İyilik dediğin asla zay olmaz,

İyilik yap arkasını arama.

Ümidini sakın kesme Tanrıdan,

Balı kim eyledi minik arıdan? 

Sen ben bilmez isek bilir yaratan,

İyilik yap arkasını arama.

İnsanlığa hizmet gelir kâmilden,

Neler çektik kendin bilmez cahilden? ! 

Kayalara dalga vurur sahilden,

İyilik yap arkasını arama.

Kim ki zarar verse eder kendine,

Kimi nefret sığmaz kendi bendine,

Kötülükler yenik kendi kendine! 

İyilik yap arkasını arama.

Gerçeğin peşinde sürünüp durdum,

Yar için kendimi ağlarken gördüm,

TÜRKYILMAZ‘a nice öğütler verdim,

İyilik yap arkasını arama.

                              31.01.2003 /Antalya', 'İyiliktir insanlığın direği, İyilik yap arkasını arama. İyilik dediğin asla zay olmaz, İyilik yap arkasını arama. Ümidini sakın kesme Tanrıd...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Türkyılmaz']::text[], 8.5, '{"poet":"Yılmaz Türkyılmaz","poet_slug":"yilmaz-turkyilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/iyilik-yap-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üç Kez', 'uc-kez-halil-aksoy-cuz3q', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yalnızca üç kez söyledim, seni sevdiğimi.

Birincisinde çok açtım.

İkincisinde ay ışığı vardı.

Üçüncüsünde eşim dışarıdaydı.

Eee.. be pırasa yemeği,

Sen de kendini adamdan saydın.', 'Yalnızca üç kez söyledim, seni sevdiğimi. Birincisinde çok açtım. İkincisinde ay ışığı vardı. Üçüncüsünde eşim dışarıdaydı. Eee.. be pırasa ...', ARRAY['Türk Edebiyatı','Şiir','Halil Aksoy']::text[], 8.5, '{"poet":"Halil Aksoy","poet_slug":"halil-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/uc-kez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hikaye', 'hikaye-halil-aksoy-w65ka', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yalnızca seni sevdim,

Beyaz örtülü yastığım.

Gerisi hep hikaye', 'Yalnızca seni sevdim, Beyaz örtülü yastığım. Gerisi hep hikaye...', ARRAY['Türk Edebiyatı','Şiir','Halil Aksoy']::text[], 8.5, '{"poet":"Halil Aksoy","poet_slug":"halil-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/hikaye-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayaklarım', 'ayaklarim-halil-aksoy-mw42u', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hayır hayır deme ayaklarım.

Ne olur beni istediğim yere götür.

Sen başkalarına aldırma.

İnanma kuşların dediklerine.

Beklemiyor beni,

Senin götürdüğün yerde.

Al yazmalı bir yosma.

İnanma,

Sakın inanma.', 'Hayır hayır deme ayaklarım. Ne olur beni istediğim yere götür. Sen başkalarına aldırma. İnanma kuşların dediklerine. Beklemiyor beni, Senin ...', ARRAY['Türk Edebiyatı','Şiir','Halil Aksoy']::text[], 8.5, '{"poet":"Halil Aksoy","poet_slug":"halil-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ayaklarim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Toprak', 'kara-toprak-yilmaz-turkyilmaz-uj313', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nasıl olsa bir gün düşeceğim! 

En yakınlarım belki umursamayacak! ? 

Fırsat düşkünleri saldıracak,

Leş kargaları üzerimde dört dolanacak,

Üstüme üşüşecek börtü böcek,

Uykularımı özleyeceğim yorgan döşek 

Sarmaşık bile kol atmaya çalışacak derinlerime.

Dost bildiklerimin çoğu dost çıkmayacak! ? ...

Ben doğduğuma bin pişman bir vaziyette,

Debeleneceğim hayatın pençesinde.

Lâkin biri var ki imdadıma yetişecek! ? 

Zengin fakir demeyecek,

Giyinik, çıplak seçmeyecek,

Dekolteli, tesettürlü ayırmayacak,

Söylenmeyecek, sövmeyecek, küfretmeyecek,

Sırlarımdan kimseye söz etmeyecek,

Kalbini, kollarını açacak,

Beni bağrına basacak.

Ve işte ebedi dost! 

Ve işte çıkarsız dost,

Hepimizin dostu,

Gizli sevdalımız; Kara toprak...

                                  06.04.2003/ANTALYA', 'Nasıl olsa bir gün düşeceğim!  En yakınlarım belki umursamayacak! ?  Fırsat düşkünleri saldıracak, Leş kargaları üzerimde dört dolanacak, Üs...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Türkyılmaz']::text[], 8.5, '{"poet":"Yılmaz Türkyılmaz","poet_slug":"yilmaz-turkyilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/kara-toprak-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şimdi Zamanı', 'simdi-zamani-halil-aksoy-kktpo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ay ışığında yürüsek el ele.

Yaşımızdan uzak,

Gençliğimize yakın.

Unutsak zaman içinde kendimizi.

Dertlerden uzak.

Yıldızlara yakın.

Sarılsak doya doya.

Seninle,

Gözlerden uzak,

Kalplere yakın.

Şimdi aşk zamanıdır sevdiğim.

Rüyaların en güzeli.

Beni hiç uyandırma sakın.', 'Ay ışığında yürüsek el ele. Yaşımızdan uzak, Gençliğimize yakın. Unutsak zaman içinde kendimizi. Dertlerden uzak. Yıldızlara yakın. Sarılsak...', ARRAY['Türk Edebiyatı','Şiir','Halil Aksoy']::text[], 8.5, '{"poet":"Halil Aksoy","poet_slug":"halil-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/simdi-zamani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değiştim', 'degistim-halil-aksoy-rjsb8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Artık ben değiştim.

Kaptan kaba döküldüm dostlar.

Ağaçlardaki kuş yavrularını merak edip,

Tırmanmıyorum artık.

Neydi halim o zamanlar.

Zincirle bağlasalar,

Tepeme yumruk atsalar,

İnatla çıkar bakardım.

Bütün yuvalar benden sorulur.

Bilirim ne yaptıklarını.

Şimdi derdim başka.

İnsan kaptan kaba dökülünce durulur.

Beni futbol değil,

Güzel bir resim heyecanlandırıyor artık,

Baktığımda.

Çoçukluğumda deli gibi koşardım.

Mahalle aralarında.

Plastik yuvarlağın peşinden.

Kim bilir ne çok kavga ettik.

Sudan sebeblerle.

Şimdi hepsi,

Gözümün önünden geçti birden.

İnsan kaptan kaba dökülünce,

Değişiyor eski düzeninden.

Yalnız uyumuyorum artık,

Uykum üç kişilik.

Bedenim düşlerim,ruhum,

Üç kişilik.

Sahipsiz gezdiğim günler geçti.

Geç kalırsam sofraya,

Gözleyenim var bilirim.

Kapıdan girince içeri, 

Kızıma hesap veririm.

Değiştim artık ben.

Kaptan kaba döküldüm.

Şimdi babamı daha iyi anlıyorum.

Kızıma her konuda hak veriyorum.', 'Artık ben değiştim. Kaptan kaba döküldüm dostlar. Ağaçlardaki kuş yavrularını merak edip, Tırmanmıyorum artık. Neydi halim o zamanlar. Zinci...', ARRAY['Türk Edebiyatı','Şiir','Halil Aksoy']::text[], 8.5, '{"poet":"Halil Aksoy","poet_slug":"halil-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/degistim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıktın Oğul', 'yiktin-ogul-halil-aksoy-k7wud', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni  çeken neydi oğul dağlara? 

Sebebin neydi yürüdün oralara? 

Al kınalı kurban mı gördün? 

Kendini rüyanda.

Ne ettin oğul? 

Yaktın içimizi.

Kurumuş çöllere çevirdin yüreğimizi.

Dört ay sonra bulduk izini.

Yatmış uzanmışsın oraya.

O çamların arasına.

Seni öyle görenin.

İnsan olurda nasıl yüreği dayana.

Dört ay boyunca,

Yatmışsın toprağın koynuna.

Aradık oğul seni çok ardık.

Acıpayam ovasında yasa boğulduk. 

Uçan kuştan seni sorduk.

Dağlar taşlar sır vermedi.

Sır vermedi kurtlar kuşlar.

Her gün yolunu bakar olduk.

Baktık oğul bakar olduk.

Uçan kuştan haber umduk.

Derdin mi vardı,düşmanın mı hasmın mı? 

Yoksa ölümün soğuk nefesi mi? 

Fısıldadı kulağına.

Sana gel diyen kimdi? 

Kimden soralım oğul.

Kime gidelim öğrenelim.

Kanayan yüreğimizi nasıl dindirelim.

Açmamış goncamız kurudu,

Oğul ne edelim?

Topraktan aldık seni,

Doyamadan tekrar toprağa verdik oğul

Yüreğimizi toprağa gömdük oğul.

Gömdük oğul,

Kendimizi toprağa gömdük.

Acıpayam ovasında yasa boğulduk.

Ateş düştüğü yeri yaktı,

Yaktı içimizi oğul.

Gülmedik oğul. 

Sen yoksun gülmedik.

Aslan gibi boyuna posuna değil,

Mezar taşına sarılmak,

Kaderimizmiş oğul bilmedik bilemedik.', 'Seni  çeken neydi oğul dağlara?  Sebebin neydi yürüdün oralara?  Al kınalı kurban mı gördün?  Kendini rüyanda. Ne ettin oğul?  Yaktın içimiz...', ARRAY['Türk Edebiyatı','Şiir','Halil Aksoy']::text[], 8.5, '{"poet":"Halil Aksoy","poet_slug":"halil-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/yiktin-ogul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hızır-Hızır', 'hizir-hizir-halil-aksoy-r3lwz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dara düşmeden Hızır yetişmez derler.

Dardayım dostlar dardayım.

O güzelden sana yar olmaz derler.

Dardayım dostlar dardayım.

Sağa sola bakarım,

Oturur bir sigara yakarım.

Geldiğini görünce,

Döner o yana bakarım.

Aklım almadı bu işe.

Hızır imdadıma yetişe.

Benden mühim işi ne ise.

Hızır’ın işine pek şaşarım.

Dardayım dostlar dardayım.

Bakmayın böyle göründüğüme,

Bedenim allak pullak,

Benliğimle çok uzaklardayım.

İnanmayın hızıra,

Hatta hiç güvenmeyin.

Kendi işinizi kendiniz görün.

Kendiniz pişirip kendiniz yiyin.

Elden gelenin öğünü olmaz.

Oda vaktinde gelmez.

Ben bunu bilir bunu söylerim.

Hızır sana güle güle derim.

Ben efendice gider,

Sevdiğimi o güzele söylerim.

İşime burnunu sokarsan,

İnan ki seni mahvederim.', 'Dara düşmeden Hızır yetişmez derler. Dardayım dostlar dardayım. O güzelden sana yar olmaz derler. Dardayım dostlar dardayım. Sağa sola bakar...', ARRAY['Türk Edebiyatı','Şiir','Halil Aksoy']::text[], 8.5, '{"poet":"Halil Aksoy","poet_slug":"halil-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/hizir-hizir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biçare Gönüller', 'bicare-gonuller-halil-aksoy-cag4c', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Biçere gönüller umutsuz gözleriyle,

Ufukları taradığında.

Parlayan bir ışık görmeyi hayal ederler. 

Yapayanlız olmadıklarını,

Göstermektir dertleri kendilerine.

Kalp atışlarını dinlerler.

Derin bir huşuğ içinde.

Kulaklarının uğultusu,

Sağır eder benliğini.

Kopuk kopuk düşünmek.

Kesik kesik nefes almak,

Deli eder onları.

Çok şey istemezler aslında.

Kabul görmek,

Onaylanmaktır tek dertleri.', 'Biçere gönüller umutsuz gözleriyle, Ufukları taradığında. Parlayan bir ışık görmeyi hayal ederler.  Yapayanlız olmadıklarını, Göstermektir d...', ARRAY['Türk Edebiyatı','Şiir','Halil Aksoy']::text[], 8.5, '{"poet":"Halil Aksoy","poet_slug":"halil-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bicare-gonuller-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ahir..', 'ahir-hasan-akin-kf0r7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Cabar dalı oyluk sarmış ağlaşır...

Kimde demli; 

Kimden öte saçların...

Derler, düşür eğerini

Geçti senden mezralı...

Sıran yandı; 

Getirsene mendili...

yeşilce...(soner ''e ve öner ''e)', 'Cabar dalı oyluk sarmış ağlaşır... Kimde demli;  Kimden öte saçların... Derler, düşür eğerini Geçti senden mezralı... Sıran yandı;  Getirsen...', ARRAY['Türk Edebiyatı','Şiir','Hasan Akın']::text[], 8.5, '{"poet":"Hasan Akın","poet_slug":"hasan-akin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ahir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Erciyes şiiri daha', 'bir-erciyes-siiri-daha-ayse-adlim-bm186', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Damganı vurdun bu sabaha da

Pırıl pırıl, dupduru güzelliğin

yine karşımda

Güneş de ilk seni görmüş

meyletmiş sana

doğmuş doruklarına

Nedir bu bilmem

Aşk mı, sevgi mi

Kara sevda mı yoksa

Neden ağlar gözlerim

Sana her bakışımda

Ve işte yine

Bir Erciyes şiiri daha', 'Damganı vurdun bu sabaha da Pırıl pırıl, dupduru güzelliğin yine karşımda Güneş de ilk seni görmüş meyletmiş sana doğmuş doruklarına Nedir b...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Adlım']::text[], 8.5, '{"poet":"Ayşe Adlım","poet_slug":"ayse-adlim","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bir-erciyes-siiri-daha-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oksuz evlatlik', 'oksuz-evlatlik-ulya-erkman-aw6x6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tokat in bir nahiyesin de dogmus

Oksuz bir kizdi

Oranin esrafindan bir aile evlatlik diye

Yanlarina almislardi

Elif cok zeki ve dikkatliydi gozunden

Hicbirsey kacmazdi

Evin hanimiyla beraber herseyleri ogrenmege

Buyuk bir hirsla hazirdi

Elif evlatliktan ziyade adeta

Bir hizmetciydi

Her gun koca evi siler supurur

Temizlerdi

Hanimina her sahada 

Yardim ederdi

Yemek pisirme camasir utu

Maksadi herseyi ogrenip kendini yetistirmekti

Uc sene sonra Aga onu Istanbulda

Bir akrabasina gonderdi

Elifin turkcesi o kadar bozuktu ki

Karga diyemez garga derdi

Ama Elif durur mu? herkesi dikkatle dinler

Kendi kendine tekrarlayip dogruyu soylerdi

Bir sene sonra Elif evin kizlari gibi

Konusmayi becerdi

Evin beyi emekli ogretmendiElif onunla 

Yazma okumayi da ogrendi

Evin kizlarinin verdigi elbiseleri keser bicer

Kendine gore yapar ancak oyle giyerdi

Mecmualarda yemek tanzim resimlerine bakar

Sofraya ayni sekilde tanzim edilmis yemekler getirirdi

Butun gayesi kendini her sahada yetistirmek olan bu kiz

Kendine bir is bulmayi bile becerdi

Evin buyukleri vefat etmis

Kizlar evlenmisti

Elif ise kazanciyla bir ufak 

Daireye yerlesmisti

O esnada kimsesi olmayan bir emekli subay

Evine,ve kendine bakabilecek birini

Bulmalarini istemisti

Adam Elifin butun hayatini ogrenmis 

Onu cok taktir etmisti

Nihayet birgun Elife evlenme teklif ederek

Benden sonra da artik hakkin olan hayati 

Yasayabilirsin '' demisti

Elifin hikayesi bir 

Hakikattir

Tokatin oksuz kizi bence 

Bir numunedir

Hizmetcilige ragmen imkanlardan

Istifade etmesini bilmistir

Kendini yetistirmekti gayesi

Muradina ermistir

Boyle Eliflere benim verebilecegim

Ancak kalpten derin bir hurmettir 

Bugun Elif evinin hanimefendisi olarak

davetler yapiyor,sohpetleri dinleniyor

Ikramlarina ise ancak ''gorulmemis''

Denebiliyor', 'Tokat in bir nahiyesin de dogmus Oksuz bir kizdi Oranin esrafindan bir aile evlatlik diye Yanlarina almislardi Elif cok zeki ve dikkatliydi ...', ARRAY['Türk Edebiyatı','Şiir','Ulya Erkman']::text[], 8.5, '{"poet":"Ulya Erkman","poet_slug":"ulya-erkman","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/oksuz-evlatlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliye...', 'sevgiliye-tugba-ozgur-6ar5w', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tükenişlerime varsın sevgili

kayboluşlarıma denk geldin

aç kalbini biraz bana

dinle kulak ver fısıltılarıma

ışıkları yakma ne olur

geç karşımda otur

anlatmalıyım derdimi sana

en çok dönüşlerini sevdim sevgili

sen uzaklardayken

yoktun bukadar içimde

gözlerim şahitlik edince güzelliğine

içime kazındı koşulsuz bağlandığım sevdan

ve gözlerindi ruhumu iklimler boyu ardına katan

kendimden kaçışlarımsın sevgili

yitip gittiğimde tutup elimden

düzlüğe çıkartansın sen

uykularımın en derin boyutusun

rüyaların ardı ardına dizilişinde

hep başka bir hal alıyorsun

çocuksu hallerin vardı sevgili

gözlerime bakşındı aşk

sıcaklığını hissetmemdi

ellerimi tutmak için çabalayan

yeni yetme aşk heveslerindi

kazıdım içime sevgini

hangi kum fırtınaları

hangi deli rüzgarlar

hangi yağmurlar siler şimdi seni', 'Tükenişlerime varsın sevgili kayboluşlarıma denk geldin aç kalbini biraz bana dinle kulak ver fısıltılarıma ışıkları yakma ne olur geç karşı...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Özgür']::text[], 8.5, '{"poet":"Tuğba Özgür","poet_slug":"tugba-ozgur","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sevgiliye-165-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onlar', 'onlar-halil-aksoy-mqef1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Fark etmek zor değildir onları.

Onlar kader mahkümu.

Kaderin oyunu,

Onlara farklı oynadı oyununu.

Saplanmış gibi kara çamura,

Öylece kalakalırlar hayatın ortasında.

Ne bir adım öne,ne bir adım geri.

Adım atarlar ama yerinde sayarlar.

Güneş farklı bakar onlara, ay farklı.	

Onların gündüzleri farklı,

Geceleri farklı.

Farklıdır onların yeri,

Oysa bir anlık hatadır.

Bütün bir ömür boyunca çektikleri.

Abdal olmuş,kör olmuş,topal olmuş,

Demir parmaklıktan bakar olmuş.

Anlına vurulan damgayı,taşır.

Gün be gün etini satar olmuş.

Ne farkeder.

İnsan değilmiyiz hepimiz.

Aynı atten kemikten yaratılmadık mı? 

İnsan düşünüyor kahroluyor.

Yüreğime bir sızı batar oluyor.

Yediğim lokmalar,

 Boğazıma dizilmesin istiyorum artık.', 'Fark etmek zor değildir onları. Onlar kader mahkümu. Kaderin oyunu, Onlara farklı oynadı oyununu. Saplanmış gibi kara çamura, Öylece kalakal...', ARRAY['Türk Edebiyatı','Şiir','Halil Aksoy']::text[], 8.5, '{"poet":"Halil Aksoy","poet_slug":"halil-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/onlar-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkım İstanbul', 'askim-i-stanbul-huseyin-celik-nhjl6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aşktan yana iki damla söz

Ve sevgiden yana.

Dinlerken kubbeler seher vakti.

O kutlu sese yönelen  ben.

Dilimde senden yana kalan iki  kelime

Seni isteyen ve seni özleyen.

Yurdum insanıyım fakat; 

Bir farkım var diğerlerinden.

	

Ben sana aşık, ben sana yanık,

Ben sana sarhoşum, gönlüm uyanık,

İçmek istesem seni; yudum,yudum

Mümkün mü  tüketebilmek ve 

Sana kanabilmek? 

Açsam elerimi avuçlarımda sen,

Gözlerimde sen  ve sözlerimde,

Ah bir görebilsem, bir sezebilsem

Dinlerdim seni aşıkların yüreğinde,

Ağıdında, hayalinde, şiirlerinde

Sen Mecnuna Leyla, Kereme Aslı,

Bana da yarsın.

Sen namus arsın.

Sana ne aşıklar vardı? bilemem.

Ve ne aşıklar var hala,

Saçlarına nem düşer, eteklerine kar

Gelsene eyy yar.

Dilim lal oldu, gözlerim ağma

Ne hissedebilirim, nede duyarım

Ey sevgili sana 

Ne hayaller kurarım.

Bastığım toprakta baktığım gökyüzünde,

Hep seni ararım, sana yanarım.

Aşkına türkü söyler ve hayaller kurarım.

Gülerim, oynarım, ağlarım,

Bilirim! 

Sen bana aşıksın, ben sana aşık

Dünyaya gelirken olduk sarmaşık.

Peygamberden gelen  nişanın takıp

Seni seviyorum eyy İstanbul, İstanbul

Gelsene  nehir gibi gönlüme  akıp!', 'Aşktan yana iki damla söz Ve sevgiden yana. Dinlerken kubbeler seher vakti. O kutlu sese yönelen  ben. Dilimde senden yana kalan iki  kelime...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Çelik']::text[], 8.5, '{"poet":"Hüseyin Çelik","poet_slug":"huseyin-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/askim-istanbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben', 'ben-aslan-koyuncu-wzfda', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gönül eğlemedik gençlik çağında

Şarabı bilmeden üzüm bağında

Renkleri erittik gök kuşağında

Sırra talip olduk gerçek dururken

Yolu zor seçmişiz  engelli  yokuş

Çileyi dokuduk hep nakış nakış

Ne fırtına dedik ne de karakış

Kar''a talip olduk bahar dururken

Acıya bal dedik gönül sesinde

Yürüdük gerçeğin ayak izinde

Külleri savurduk sıra köz''ünde

Zora talip olduk kolay dururken', 'Gönül eğlemedik gençlik çağında Şarabı bilmeden üzüm bağında Renkleri erittik gök kuşağında Sırra talip olduk gerçek dururken Yolu zor seçmi...', ARRAY['Türk Edebiyatı','Şiir','Aslan Koyuncu']::text[], 8.5, '{"poet":"Aslan Koyuncu","poet_slug":"aslan-koyuncu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ben-258-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türküler', 'turkuler-halil-aksoy-fjcz2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne zaman bir türkü dinlesem,

Hep şiir yazasım gelir.', 'Ne zaman bir türkü dinlesem, Hep şiir yazasım gelir....', ARRAY['Türk Edebiyatı','Şiir','Halil Aksoy']::text[], 8.5, '{"poet":"Halil Aksoy","poet_slug":"halil-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/turkuler-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şizofren şiir', 'sizofren-siir-tugba-ozgur-8v3nd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'biraz da şizofrenidir şiir 

belki birazda şizofrendir şair

hiçbir durgun akıldan anlayış göremez şizofrenler

aslında hayatı yalın görendir şizofren

biraz da şizofrenidir şiir

duyguların çıldırması belki de...

aşkı binbir çeşitte anlamaktır

birazda şizofrendir şair

dahası ne olabilir ki? ? ? 

gölgelerin savaşını

ateşin aslında aşkdan serin olduğunu

ve hatta rüzgarın ağaçlarla dans edip

haykırılan şiirlere fon oluşturduğunu

kim söyleyebilir başka? ? ? 

biraz da şizofrenidir şiir

belki birazda şizofrendir şair

kim görür sevdiğinin gözündeki 

gözyaşlarının aslında altın olduğunu? ? ? 

kim değer verir 

sahibinin bile cömertce harcadığı altın gözyaşlarına

kim farkeder sevdiğinin adı geçince 

heryerin yandığını

biraz da şizofrenidir şiir

belki birazda şizofrendir şair

ben bir şairim

ben görüyorum onun geçtiği

sokakların şenlik yerine dönüştüğünü

görüyorum rüzgarın saçlarını taradığını

büyük bir özenle...

güneşi kıskandıracak bakışları görüyorum gözlerinde

sevdiği herşeyi

sokaktaki zavallı bir kediyi bile kıskanıyorum

onu görüyorum her rüyada

hayatın gerçeğini onda buluyorum

dünyanın en güzel sözleriyle dolu

şiirlerini ona adamak istiyorum

sevdiği şarkıları ezberleyip

okuduğu kitapları biriktiriyorum

esen rüzgarda kokusunu duyuyor

doğan güneşle sıcaklığını anımsıyorum

bütün geceyi yanında geçirsem

sabah uyandığımda özlemiş oluyorum

biraz da şizofrenidir şiir

belki birazda şizofrendir şair

ben bir şairim

baktığım her resimde onu görüyorum

onu iliştiriyorum bir köşeye

eğer bu resimde onu kurgulayamazsam

eskik görünüyor gözümde

okuduğum kitaptaki bir kahramanı

ona benzetiyorum

yazar ne kadar överse bu kahramanı

bende onu gözümde okadar yüceltiyorum

sokakta yürürken 

herkesin onu izlediğini sanıyorum

ve olası kıskançlık krizlerini engelleyemiyorum

ben bir şairim ve

bu gibi şizofrenik durumları anlatıyorum şiirlerimde

işte bu yüzden

biraz da şizofrenidir şiir

belki birazda şizofrendir şair', 'biraz da şizofrenidir şiir  belki birazda şizofrendir şair hiçbir durgun akıldan anlayış göremez şizofrenler aslında hayatı yalın görendir ş...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Özgür']::text[], 8.5, '{"poet":"Tuğba Özgür","poet_slug":"tugba-ozgur","theme":"Türk Şiiri","is_hero":false,"total_lines":61,"source_url":"https://www.antoloji.com/sizofren-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uykuda', 'uykuda-ayse-adlim-hhhlk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Alma canım uykuda

Görmeliyim geldiğini

Sesini duymalıyım

Bakmalıyım yüzüne

Elini tutmalıyım

Nazlanmalıyım

Hadi dediğinde

Alma canım uykuda

Hissetmeliyim ölümü

Acıysa acı

Korkuysa korku

Yaşamalıyım her anını

Son bir kez bakmalıyım 

boşluğa

Teslim olmalıyım

çaresiz

Alma canım uykuda

Açık kalsın gözlerim

Akmasın içime

gözyaşlarım

Kıpırdasın dudaklarım

Kelimeler dökülsün

gizemli

Alma canım uykuda

Tatmalıyım ölümün de

Varsa acısını

korkusunu

Ve belki de

huzurunu', 'Alma canım uykuda Görmeliyim geldiğini Sesini duymalıyım Bakmalıyım yüzüne Elini tutmalıyım Nazlanmalıyım Hadi dediğinde Alma canım uykuda H...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Adlım']::text[], 8.5, '{"poet":"Ayşe Adlım","poet_slug":"ayse-adlim","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/uykuda-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünya Detleri', 'dunya-detleri-halil-aksoy-xin6x', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ey aslı fesli bulunmayan dünya dertleri,

Bu gün bari yakamı bırakın da,

Rahat rahat düşler kurayım.', 'Ey aslı fesli bulunmayan dünya dertleri, Bu gün bari yakamı bırakın da, Rahat rahat düşler kurayım....', ARRAY['Türk Edebiyatı','Şiir','Halil Aksoy']::text[], 8.5, '{"poet":"Halil Aksoy","poet_slug":"halil-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/dunya-detleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Açız Sevgiye', 'aciz-sevgiye-halil-aksoy-dx9c3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Birçok insan, 

Duygularını kalbine kilitleyip,

Mezara götürüyor benim memleketimde.

Bağrı yanık kara toprağın,

Suya hasreti gibi,

Açız sevgiye.', 'Birçok insan,  Duygularını kalbine kilitleyip, Mezara götürüyor benim memleketimde. Bağrı yanık kara toprağın, Suya hasreti gibi, Açız sevgi...', ARRAY['Türk Edebiyatı','Şiir','Halil Aksoy']::text[], 8.5, '{"poet":"Halil Aksoy","poet_slug":"halil-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/aciz-sevgiye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şaşıyorum', 'sasiyorum-halil-aksoy-5zy7l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şaşıyorum şu kadına.

Ayyaş bir kocası,

Laftan anlamaz onca çocuk,

Patırtılı cinsten kaynana cabası.

Şaşıyorum şu kadına.

Şaşıyorum. 

Hala dim dik ayakta.', 'Şaşıyorum şu kadına. Ayyaş bir kocası, Laftan anlamaz onca çocuk, Patırtılı cinsten kaynana cabası. Şaşıyorum şu kadına. Şaşıyorum.  Hala di...', ARRAY['Türk Edebiyatı','Şiir','Halil Aksoy']::text[], 8.5, '{"poet":"Halil Aksoy","poet_slug":"halil-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sasiyorum-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutkular ve Duygular', 'tutkular-ve-duygular-halil-aksoy-3sai3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Erkekler tutkularının,

Kadınlar duygularının peşinden,

Gider hayatta.

Birbirimizden tek farkımız bu olsa gerek,

Şu yalancı dünyada.', 'Erkekler tutkularının, Kadınlar duygularının peşinden, Gider hayatta. Birbirimizden tek farkımız bu olsa gerek, Şu yalancı dünyada....', ARRAY['Türk Edebiyatı','Şiir','Halil Aksoy']::text[], 8.5, '{"poet":"Halil Aksoy","poet_slug":"halil-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/tutkular-ve-duygular-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşa Öğratmenim', 'yasa-ogratmenim-halil-aksoy-2i87p', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yalnızca o vardı kara tahtanın başında.

insanlığı uzaya taşıdı hünerli elleriyle.

Karanlığın arkasındaki ışığı gördü.

İleri bakan gözleriyle.

Eğriyi, doğruyu ayırdı birbirinden.

Yıkılan dünyayı her seferinde o kurdu yeniden.

Zengin, fakir, yoksul demeden,

Aldı bağrına.

Kucakladı tüm insanların hepsini birden. 

Yalnızca o vardı kara tahtanın başında.

Yıldızları topladı, serdi insanlığın önüne.

Umut, neşe, ışık doldurdu.

İnsanlığın gönlüne.

Çok şey beklemeden çalıştı, didindi.

El ele tutuşmuş insanları görünce,

Çektiği tüm acılar bir anda dindi.

Yaşa öğretmenim.

İnsanlık seninle sevindi.', 'Yalnızca o vardı kara tahtanın başında. insanlığı uzaya taşıdı hünerli elleriyle. Karanlığın arkasındaki ışığı gördü. İleri bakan gözleriyle...', ARRAY['Türk Edebiyatı','Şiir','Halil Aksoy']::text[], 8.5, '{"poet":"Halil Aksoy","poet_slug":"halil-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yasa-ogratmenim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çanakkale Destanı', 'canakkale-destani-sultan-mustafa-tjljg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yüz binler vermişiz senin uğruna

Adın dillerde neş’e Çanakkalem

Duyunca koşarız yine çağrına

Bakmayız eşe aşa Çanakkalem

Bizimdir toprağın bizimdir suyun

Bizimle oynanmaz böyle bir oyun

On sekiz mart senin bitmeyen toyun

Çıkılmaz seninle başa Çanakkalem

Türküz, Türk oğluyuz, kanımız asil

Uğruna canını verir bu nesil

Yan bakanın hali olmaz mı zelil

Dönmez mi yazı kışa Çanakkalem

Kafirler gelmeden boğazı tuttuk

Sen imdat demeden biz sana yettik

Onlar da bilsinler diye öğrettik

Adını kurda kuşa Çanakkalem

Kararan bahtımız yine ağardı

Düşmanın dünyası o gün pek dardı

Anafartalar’da şanına vardı

Nice er nice paşa Çanakkalem

Gelirse bir gün üstümüze düşman

Vururuz yeniden vermeyiz aman

Hainlerin işi olmaz mı yaman

Vurunca dizi taşa Çanakkalem

Bu milletin gönlü sendedir elbet

Sanma biter kalpte sana muhabbet

Beş-on asırla değil, ilelebet

Biz var oldukça yaşa Çanakkalem

Sultan Mustafa da senin düşkünün

Kölesi olmuşuz vatan aşkının

Sana eğri bakan hain şaşkının

Çıkar gayreti boşa Çanakkalem', 'Yüz binler vermişiz senin uğruna Adın dillerde neş’e Çanakkalem Duyunca koşarız yine çağrına Bakmayız eşe aşa Çanakkalem Bizimdir toprağın b...', ARRAY['Türk Edebiyatı','Şiir','Sultan Mustafa']::text[], 8.5, '{"poet":"Sultan Mustafa","poet_slug":"sultan-mustafa","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/canakkale-destani-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar', 'bahar-halil-aksoy-ek1e4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu sabah ilk defa,

Pırıl pırıl güneş vardı penceremde.

Kuşlar dallarda ötüşmekte.

Toprak ve hava acele bir telaş içinde.

Çünkü bahar geldi.

Telaş boşuna değil.

Hazırlıksız yakalanmak var,

İşin içinde.', 'Bu sabah ilk defa, Pırıl pırıl güneş vardı penceremde. Kuşlar dallarda ötüşmekte. Toprak ve hava acele bir telaş içinde. Çünkü bahar geldi. ...', ARRAY['Türk Edebiyatı','Şiir','Halil Aksoy']::text[], 8.5, '{"poet":"Halil Aksoy","poet_slug":"halil-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bahar-127-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nedir?', 'nedir-halil-aksoy-r100j', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Korkmam inlerden cinlerden.

İşim olmaz yabanilerle.

Günün diğer yarısı diye bakarım gecelere.

Her konuda aklıma güvenirim.

Kimdir nedir? 

Gece rüyalarımda uğraştıklarım.', 'Korkmam inlerden cinlerden. İşim olmaz yabanilerle. Günün diğer yarısı diye bakarım gecelere. Her konuda aklıma güvenirim. Kimdir nedir?  Ge...', ARRAY['Türk Edebiyatı','Şiir','Halil Aksoy']::text[], 8.5, '{"poet":"Halil Aksoy","poet_slug":"halil-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/nedir-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim mucizem sensin', 'benim-mucizem-sensin-tugba-ozgur-c945k', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'topla gökyüzündeki yıldızları

hadi bir mucize yap bana

çekip çıkar düştüğüm kuyulardan

göster yüzünü her sabah

düşleyemediklerimi yaşat bana

fısıltılarla anlat en korkunç hikayeleri

dünyayı rengarek boya

şarkılar çal geceleri

ağlat...güldür...

şarkılarda yaşat hayatı

yanındayken özgür hissettir

uzağındayken esir

bakışlarınla baştan çıkar

gülüşünle yaşamayı sevdir

bana hiçbir şairin yazamayacağı

şiirler yaşat

uzaktayken çıkma aklımdan

yanımdayken al aklımı başımdan

yıldızları toplama

bırak onlar eksilmesin

mucizeye gerek yok

benim mucizem sensin...', 'topla gökyüzündeki yıldızları hadi bir mucize yap bana çekip çıkar düştüğüm kuyulardan göster yüzünü her sabah düşleyemediklerimi yaşat bana...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Özgür']::text[], 8.5, '{"poet":"Tuğba Özgür","poet_slug":"tugba-ozgur","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/benim-mucizem-sensin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeşil', 'yesil-tugba-ozgur-x2np4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu öyle bir yeşilki 

görmesi ölüm getirisi

haykırdıkca ölüm sessizliği

yardım diledikçe batış

varlığına bağlanmaktan kaçış

ecel diledikçe sonsuza uzanış

yazmak istdikçe siliniş

var olmak istedikçe tükeniş

gitmek istemediğinde elveda

koşmak yerine yürümek parmak ucunda

yıldızlar gibidir yok bunun sonu

derine indikçe deniz vurgunu

bazen çılgın bazen dingin bir nehir

bir şiir bir şarkı değil 

işte bu öyle bir YEŞİL...', 'Bu öyle bir yeşilki  görmesi ölüm getirisi haykırdıkca ölüm sessizliği yardım diledikçe batış varlığına bağlanmaktan kaçış ecel diledikçe so...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Özgür']::text[], 8.5, '{"poet":"Tuğba Özgür","poet_slug":"tugba-ozgur","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yesil-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğimdesin en çok...', 'yuregimdesin-en-cok-tugba-ozgur-vqg2t', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'üç mum yaktım 

birde sigara...

alevin kızıllığında

dumanın griliğinde

odamın her köşesindesin

yüreğimdesin en çok

gittin! ! ! 

kokun kaldı ellerimde

kalsın istiyorum sonsuza kadar

gecenin tam ortası

karanlığın en acımasız zamanı

geldi sensizlik çöktü odama

karanlıktan daha kara

yok olmak istiyorum

şimdi zamanıdır! 

istiyorum ki beni bulama! ! 

hatırlatma kendini

tam unutmuşken canımı alma...', 'üç mum yaktım  birde sigara... alevin kızıllığında dumanın griliğinde odamın her köşesindesin yüreğimdesin en çok gittin! ! !  kokun kaldı e...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Özgür']::text[], 8.5, '{"poet":"Tuğba Özgür","poet_slug":"tugba-ozgur","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yuregimdesin-en-cok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Garıp', 'garip-halil-aksoy-oe5ey', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Saatin tıkır tıkır dönmesi gibi,

Hiç atlamadan,

Acı cekecekse çekiyor insan.

Günü saati zamanı geldiğinde,

Sanki sihirli bir deynek,

Dokunuveriyor dünyamıza.

Dünkü o mutlu insan,

Biz değilmişiz gibi,

Harap oluyor dünyamız.

Hiç kurtulamayacağımız bir hastalığa,

Tutulmuş gibi hissederiz kendimizi.

Acı çekecek se çekiyor insan.

Ha şöyle ha böyle.

Göçmen kuşlar gibi,

Durum vaziyete bakıp,

Göç edecek halimiz yok ya.

Zamanı geldiğinde acılar çekilecekse,

Çekeriz ne yapalım.', 'Saatin tıkır tıkır dönmesi gibi, Hiç atlamadan, Acı cekecekse çekiyor insan. Günü saati zamanı geldiğinde, Sanki sihirli bir deynek, Dokunuv...', ARRAY['Türk Edebiyatı','Şiir','Halil Aksoy']::text[], 8.5, '{"poet":"Halil Aksoy","poet_slug":"halil-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/garip-45-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Merak', 'merak-halil-aksoy-um5f5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Marangoz biçtiği ağaçların yerine,

Acaba kaç  fidan dikti yeryüzüne? 

Balıkçı ne kadar yumurta bıraktı denizlere? 

Madenci ne bıraktı çıkardığı kömürün yerine? 

Benimkide sırf merak işte,

Merak…

Fabrikalar ne verdi, gökyüzüne.

Emdiği temiz havanın yerine.

Çernobil nasıl soktu acıyı,

İnsanların yüreğine.

Benimki de sırf merak işte,

Merak…', 'Marangoz biçtiği ağaçların yerine, Acaba kaç  fidan dikti yeryüzüne?  Balıkçı ne kadar yumurta bıraktı denizlere?  Madenci ne bıraktı çıkard...', ARRAY['Türk Edebiyatı','Şiir','Halil Aksoy']::text[], 8.5, '{"poet":"Halil Aksoy","poet_slug":"halil-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/merak-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'On Sekiz Mart', 'on-sekiz-mart-altay-taskin-c10ns', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'tarihin yüreği çarpıyor on sekiz martta

orada bir cevap vardı dosta düşmana

ben yurdumun masum bir köşesiydim

Türkün dışında kimseye yar edilmemeliydim

yıldıramadı beni yedi düvel komutlar

koca gemileri oldu boğazımda lokma

ben and içtim taşıma toprağıma

şehidimin kanları gömlek oldu sırtıma

hangi tarih yüzümüze gülmedi

barış gülleri yakamızdan inmedi

şimşekler çaktı yıldırım düşmedi

her bir şehit bağrımda kükredi

koşarım vatanım için soluk soluğa

umutlarım çıkmadı hiç boşluğa

yüreğimden çıkaramam sevgimi

vatan aşkı değişilmez  hiçbir varlığa', 'tarihin yüreği çarpıyor on sekiz martta orada bir cevap vardı dosta düşmana ben yurdumun masum bir köşesiydim Türkün dışında kimseye yar edi...', ARRAY['Türk Edebiyatı','Şiir','Altay Taşkın']::text[], 8.5, '{"poet":"Altay Taşkın","poet_slug":"altay-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/on-sekiz-mart-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sadece', 'sadece-halil-aksoy-go5ju', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'inanır mısınız? 

gündüz,

paltomun içinde,

geceleri de,

sadece yatağımda ısınırım.', 'inanır mısınız?  gündüz, paltomun içinde, geceleri de, sadece yatağımda ısınırım....', ARRAY['Türk Edebiyatı','Şiir','Halil Aksoy']::text[], 8.5, '{"poet":"Halil Aksoy","poet_slug":"halil-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sadece-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünya Şehri İSTANBUL', 'dunya-sehri-i-stanbul-abdullah-yasar-erdogan-tyc7t', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dünya  Şehri  İSTANBUL

İstanbul’da yerleşim Taş Devri’nden başlar,

Yarımburgaz Mağarası’nda resimler var,

Tunç Çağı’ndan kalma bulunmuştur araçlar,

Tarih şehri, Dünya şehri güzel İstanbul.

Byzas, Delfi Kahini’nden şehir yeri ister,

O “Körler ülkesinin karşısına kur” der,

Kenti kurup adına da “Byzantion” derler,

Tarih şehri, Dünya şehri güzel İstanbul.

Belgeler altı yüz atmış da kuruldu demekte,

Bir süre kalmıştır Pers egemenliğinde,

Bağımsızdır  Büyük İskender döneminde,

Tarih şehri, Dünya şehri güzel İstanbul.

İsâ’dan sonra yetmiş üç, Roma elinde,

Septimius’a geçmiştir yüz doksan üçte,

Bayındırlık işi yeniden başlar kentte,

Tarih şehri, Dünya şehri güzel İstanbul.

Kentin gelişimi Constantinus’a rastlar,

Üç yüz otuz da Roma’nın başkenti sayar,

Kentin adını “Konstantinopolis” yapar,

Tarih şehri, Dünya şehri güzel İstanbul.

Müslümanlar Konstantiniye diye anmış,

Sahabe döneminde seferler yapılmış,

Bazı sahabeler surlara kadar varmış,

Tarih şehri, Dünya şehri güzel İstanbul.

Bu şehir, komutanları kendine çekmiş,

Pek çoğu surları bir türlü geçememiş,

Allah, bunu Sultan Mehmed’e nasip etmiş,

Tarih şehri, Dünya şehri güzel İstanbul.

Resûlü misafir edeni, misafir eder,

Ebü’l-El-Ensâri’ye burada yaşam biter,

Fatih Sultan Mehmed ki; o dağları yol eder,

Tarih şehri, Dünya şehri güzel İstanbul.

Bin dört yüz elli üç, kentin dönüm noktası,

Fatih’in Fethi ki; her sultanın rüyası,

Bir kez görenden gitmez İstanbul sevdası,

Tarih şehri, Dünya şehri güzel İstanbul.

Kente; Estenbul, Stimbol, İstambol denilmiştir,

On yedi, on sekiz asırda “İstanbul” denir,

O günden beridir ki, böyle bilinmektedir,

Tarih şehri, Dünya şehri güzel İstanbul.

Osmanlı resmi dilde, kentin adı başka,

Dersaadet, Deraliyye, Darulhilafe,

Bir başka bilinen adı da Asitane,

Tarih şehri, Dünya şehri güzel İstanbul.

Bin dört yüz elli üçte Osmanlı başkenti,

Bin beş yüz on yedi de hilafet merkezi,

Dünya Savaşı’nda baskı altına girdi,

Tarih şehri, Dünya şehri güzel İstanbul.

Ekim bin dokuz yüz yirmi üçte gün doğdu,

Türk Milleti işgalcileri kentten kovdu,

Bin dokuz yüz yirmi dörtte hilafet söndü,

Tarih şehri, Dünya şehri güzel İstanbul.

İstanbul ilk çağdan beri önemli yerdir,

Cumhuriyet döneminde hızla kentleşir,

Türkiye için her konuda bir merkezdir,

Tarih şehri, Dünya şehri güzel İstanbul.

Dünyanın kilit noktası olmuş İstanbul,

Avrasya arasındaki bağlantılı yol,

Her gün her dakika ziyaretçileri bol,

Tarih şehri, Dünya şehri güzel İstanbul.

Sen ki; Fatih’imden emanetsin bizlere,

Güzelliğinle şevk salarsın gönüllere,

Seni Sultan yapmalı bütün şehirlere,

Tarih şehri, Dünya şehri güzel İstanbul.

Metropollerin güzeli İstanbul şehri,

Boğazıyla dünyanın nadide incisi,

Kucaklar her santimi gelmişi, geçmişi,

Tarih şehri, Dünya şehri güzel İstanbul.

Evlad-ı İyâle miras olarak yeter,

Dilerim İstanbul’u sarmasın bir keder,

İstanbul ki; güzellikte bir ve de lider,

Tarih şehri, Dünya şehri güzel İstanbul.

Yedi tepede, yedi düvelden insan var,

İstanbul üstüne yükselmiş minareler,

Tarihe şereftir kentteki mimariler,

Tarih şehri, Dünya şehri güzel İstanbul.

Şair: Abdullah Yaşar Erdoğan', 'Dünya  Şehri  İSTANBUL İstanbul’da yerleşim Taş Devri’nden başlar, Yarımburgaz Mağarası’nda resimler var, Tunç Çağı’ndan kalma bulunmuştur a...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yaşar Erdoğan']::text[], 8.5, '{"poet":"Abdullah Yaşar Erdoğan","poet_slug":"abdullah-yasar-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":78,"source_url":"https://www.antoloji.com/dunya-sehri-istanbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağlar', 'daglar-muzaffer-boz-4022i', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'DAĞLAR 

Dağlar seninde başın karanlık,

Bencileyin başında duman mı var? 

Dertlerim depreşti, yaram koyak,

Yaramı özenip saran mı var? 

***

Yalnızım garip gönlüm pek nazik,

Halimi soranım yok, çok yazık,

Kalbim perişan düzenim bozuk,

Halime bakıp ağlayan mı var? 

***

Çıktım çamurlu taşlı yollara,

Dert açtım ağaçlara,dallara,

Ardımdan Mevlam güzel hallara,

Deyip te dua okuyan mı var? 

***

Derdimi açtım sırdaşım oldun,

Koynunda yattım kardeşim oldun,

Hayatımda tek yoldaşım oldun,

Benimle coşup çağlayan mı var? 

***

Beni saklayıp kol kanat gerdin,

Yandım kaynaklarından su verdin,

Yoluma lale,sümbül,gül serdin,

Beni başkaca eğleyen mi var.

***

Alaçamın kekliği palazı,

Sert olur fırtınası ayazı,

Muzaffer bu dağa bazı, bazı,

Kalbini kırıp yollayan mı var? 

                                   Muzaffer Boz', 'DAĞLAR  Dağlar seninde başın karanlık, Bencileyin başında duman mı var?  Dertlerim depreşti, yaram koyak, Yaramı özenip saran mı var?  *** Y...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Boz']::text[], 8.5, '{"poet":"Muzaffer Boz","poet_slug":"muzaffer-boz","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/daglar-70-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şükür', 'sukur-ayse-adlim-9mw6r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Adını anar oldum

Şükürler olsun

Derdime dermanı

Sende arar oldum

Şükürler olsun

Sığınacak 

kucak ol bana

Ağlayacağım omuz

Yalnız Sana yalvarayım

Sen beni anlayansın

Beni en iyi bilensin

Yalnız Sen ol yardımcım

Yalnız Sen ol koruyucum

Yalnız Sen ol dermanım

Yalnız Sana şükürler olsun', 'Adını anar oldum Şükürler olsun Derdime dermanı Sende arar oldum Şükürler olsun Sığınacak  kucak ol bana Ağlayacağım omuz Yalnız Sana yalvar...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Adlım']::text[], 8.5, '{"poet":"Ayşe Adlım","poet_slug":"ayse-adlim","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sukur-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Desem', 'desem-ayse-adlim-c5wjs', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çöktü içime hüznü

Ayrılık mı desem

Hasret mi desem

Gözden ırak olan

gönülden de ırak

olur mu desem

olmaz mı desem

Bir de gurbet olunca

Ölüm mü desem

Kalım mı desem', 'Çöktü içime hüznü Ayrılık mı desem Hasret mi desem Gözden ırak olan gönülden de ırak olur mu desem olmaz mı desem Bir de gurbet olunca Ölüm ...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Adlım']::text[], 8.5, '{"poet":"Ayşe Adlım","poet_slug":"ayse-adlim","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/desem-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat', 'hayat-muzaffer-boz-x4i1g', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'HAYAT 

''''-Hayat direnmektir...''''

Dayanmaktır yaşamak,

Sonu bilmeden sonsuzluğa,

Davranmaktır yaşamak.

***

Bir baş kaldırının umudunda,

Yüksek bir amacın uğrunda,

Bir büyük isyanın sonunda,

Kendini dağlara vurmaktır yaşamak.

***

İnsanların mutsuz olduğu rüyaların,

Gerçekleşmeyen ümit dolu hülyaların,

Kızgınlıkla üstüne yürüyen dünyaların,

Karşısında kale gibi durmaktır yaşamak.

***

Sıkıntılarla dolu her anında,

Herkes kaçıp da kimse kalmazsa yanında,

Böyle geçen kara günlerin sonunda,

Gerçek dosta varmaktır yaşamak.

***

Zalimin gözünü bürüyen zulümü eziyeti,

Alimin elindeki türlü türlü meziyeti,

Sergilenen her türlü kötü niyeti,

İyiye doğruya yormaktır yaşamak.

***

İster zengin olsun, isterse kimsesiz,garip,

Bütün dünyayı eş, dost, kardeş bilip,

İnsanı, insan olduğu için sevip,

Bağrına basıp sarmaktır yaşamak.

***

Yaradan aşkına yaratılanı severek,

Aleme sultan kendine kul diyerek,

Muzaffer''im gahi isyan gahi hizmet ederek,

İnsanı insanca görmektir yaşamak. 

.Muzaffer Boz', 'HAYAT  ''''-Hayat direnmektir...'''' Dayanmaktır yaşamak, Sonu bilmeden sonsuzluğa, Davranmaktır yaşamak. *** Bir baş kaldırının umudunda, Yükse...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Boz']::text[], 8.5, '{"poet":"Muzaffer Boz","poet_slug":"muzaffer-boz","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/hayat-319-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Dedikleri', 'sevda-dedikleri-seval-kemertas-zxjcg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ümitle sarılıp acı günlere

hayalle yaşamışın ben sevdayı

harcanıp gitmişim yalan sözlerle

meğer dünya yalanlarla dönermiş

sevda dedikleri bu derin sancı

kalleşliğin kol gezdiği

zalim bir şehirmiş...

10/11/2003', 'ümitle sarılıp acı günlere hayalle yaşamışın ben sevdayı harcanıp gitmişim yalan sözlerle meğer dünya yalanlarla dönermiş sevda dedikleri bu...', ARRAY['Türk Edebiyatı','Şiir','Seval Kemertaş']::text[], 8.5, '{"poet":"Seval Kemertaş","poet_slug":"seval-kemertas","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sevda-dedikleri-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkımızın Şarkısı', 'askimizin-sarkisi-seval-kemertas-u79c1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'gecenin sessizliğini dinle

okşayarak karanlığın saçlarını

ay doğuyor yüreğimin ardındaki tepede

uzayan yollara hüzün serperek, 

gecenin karasına yıldız dökerek, 

aşkımızın şarkısını söylüyor rüzgar...

ben hüzünlü, acı dolu yüreğimle

karanlığı tutuşturup bir köşesinden

tutunmaya çalışırken gecenin eteklerine

sen nerede, kimbilir kiminle

en güzel düşlerin koynundayken belki de

aşkımızın şarkısını söylüyor rüzgar...

şimdi ıssız bir tepenin yamacında

çoban ateşlerinin geceyi yakan alazında

gözlerinin denize çalan mavisine dalarak

sonra kaybolarak engin maviler içinde

ve ben köpükler gibi yok olurken sessizce

aşkımızın şarkısını söylüyor rüzgar...

gecenin sessizliğini dinle

senin yüreğinde taze aşkların telaşı

benim gözlerimde veda eden bir kaç damla gözyaşı

umutlarım gibi dökülürken kaldırımlara

senin bahar dallarında, 

benim karlı dağlarımda, 

aşkımızın şarkısını söylüyor rüzgar...

14/03/2003', 'gecenin sessizliğini dinle okşayarak karanlığın saçlarını ay doğuyor yüreğimin ardındaki tepede uzayan yollara hüzün serperek,  gecenin kara...', ARRAY['Türk Edebiyatı','Şiir','Seval Kemertaş']::text[], 8.5, '{"poet":"Seval Kemertaş","poet_slug":"seval-kemertas","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/askimizin-sarkisi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Henüz çok erken', 'henuz-cok-erken-meryem-i-sler-k7i7y', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dökme gözyaşlarını henüz çok erken

Vakti gelince bir bir düşeçekler zaten

Hüzünleri kov kapından 

Gün gelecek girecekler içeri izin almadan

Bugünlerin değerini bil yıllar yüzüne gülerken

Sev sevil aynalar seni terk etmeden

Gençliğinin doyasıya yaşa baharın kışa ermeden

Sil gözyaşlarını henüz çok çok erken', 'Dökme gözyaşlarını henüz çok erken Vakti gelince bir bir düşeçekler zaten Hüzünleri kov kapından  Gün gelecek girecekler içeri izin almadan ...', ARRAY['Türk Edebiyatı','Şiir','Meryem İşler']::text[], 8.5, '{"poet":"Meryem İşler","poet_slug":"meryem-i-sler","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/henuz-cok-erken-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz Ayrıdık Hep', 'biz-ayridik-hep-muzaffer-boz-2fxps', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'BİZ    AYRIYDIK HEP………..

Seni sevdim Karagözlüm, seni sevdim,

Ölürcesine sevdim,taparcasına sevdim,

Gecelerde sevdim,gündüzlerde sevdim,

Güneşle sevdim,yıldızlarla sevdim,ayla sevdim,

Uzaklarda sevdim,yakınlarda sevdim,

Delice sevdim.

                 ***

Ayrıydık hep ayrı kaldık,hiç kavuşamadık,

Hasret çektik gurbete gitmeden,

Vuslatı görmedik hiç.

İçimiz buruk,içimiz garip,içimiz yetim,

İçimiz dolmadı hiç sevinç.

Hep yaslı,hep gamlı,hep dumanlı,

Gözlerimiz hüzünlü gözlerimiz ağlamaklı,

Gözlerimiz kanlı.

                 ***

Çaresizdik,biçareydik,naçardık,

Ara sıra telefonlarda görüşürdük,

Gönlümüzü telefonlarda açardık,,

Telefonlarda güler,telefonlarda ağlardık,

Bazen telefonlarda kırılır,

Telefonlarda küserdik.

Yine telefonlarda barışır,

Telefonlarda söyleşirdik.

                 ***

Gariptik kimsesizdik,

Ama yaradılış tanda bir gariptik.

Sen dururdun aramadan sormadan,

Lakin ben durmazdım,duramazdım.

Yanardım kendi kendime,için,için.

Gönül bırakırdım…

Ve hatta üzülürdüm,kırılırdım,

Yıkılırdı dünyam çatır,çatır.

Yoktu be güzelim senden başka kimsem,

Kime gideyim, kime varayım,,kime ağlayayım,

Kime küsem...                                                                            

                                          Muzaffer Boz', 'BİZ    AYRIYDIK HEP……….. Seni sevdim Karagözlüm, seni sevdim, Ölürcesine sevdim,taparcasına sevdim, Gecelerde sevdim,gündüzlerde sevdim, Gün...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Boz']::text[], 8.5, '{"poet":"Muzaffer Boz","poet_slug":"muzaffer-boz","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/biz-ayridik-hep-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Kokuyor Deniz', 'sen-kokuyor-deniz-seval-kemertas-4ewys', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'gaddar bir kıştı kapımı zorlayan

hoyrat bir rüzgardı ömrümü yalayan

sensizliğin acısı çöreklenince içime

sürgün oldum, 

göç ettim senin şehrinden

yağan deli yağmurlar bile 

yolumdan geri döndüremedi...

şimdi sensizliğin sürüklediği 

ıssız bir sahildeyim

sen kokuyor buram buram deniz

senden esiyor yüzümü yakan rüzgar

gözlerimde bin bir pişmanlık

içimde dalgaların ayak sesleri

bir bağ bozumu daha yaşıyor gönlüm...

bu sahil içimdeki boşluk kadar ıssız

burada bir başka giyiniyor siyahlarını gece

derinlerinde söndürüp ay ışığını

seni saklıyor denizlerin gizli suları

ve ben hala çözemiyorum kıramıyorum

yüreğime vurduğun prangaları...

23/10/2003', 'gaddar bir kıştı kapımı zorlayan hoyrat bir rüzgardı ömrümü yalayan sensizliğin acısı çöreklenince içime sürgün oldum,  göç ettim senin şehr...', ARRAY['Türk Edebiyatı','Şiir','Seval Kemertaş']::text[], 8.5, '{"poet":"Seval Kemertaş","poet_slug":"seval-kemertas","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sen-kokuyor-deniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşman Yağar Dünyama', 'dusman-yagar-dunyama-hasan-ulusoy-bpuub', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kara yeller ak bahtı mı üşütür 

Ruhumdaki güzelliğe çiğ düştü. 

Kör karanlık ak günüme ışıktır 

Fırtınalar öz dünyama üşüştü 

Karlar indi odama. 

Yosun renkli sular, durgun mu durgun, 

Vurulmuş ayağına, beton pranga. 

Eriyen buzlara karışan günler 

Vuruldu önümde gün manga manga. 

Ömür mahkum idama... 

Sana yönelirken, uçan serçeler, 

Sana gelir daldan inen her yaprak 

Yüzünü dön bana, karalı talih, 

Çevir sayfaları, bir bir açarak, 

Bana da göster ama.... 

Göster birer birer, sayfalarını, 

Oku, okut, tek tek, gizli kalmasın 

Ne var ne yok küf kokulu kitapta 

İkimizden başka bilen olmasın 

Düşman yağar dünyama...', 'Kara yeller ak bahtı mı üşütür  Ruhumdaki güzelliğe çiğ düştü.  Kör karanlık ak günüme ışıktır  Fırtınalar öz dünyama üşüştü  Karlar indi od...', ARRAY['Türk Edebiyatı','Şiir','Hasan Ulusoy']::text[], 8.5, '{"poet":"Hasan Ulusoy","poet_slug":"hasan-ulusoy","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dusman-yagar-dunyama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soğuk kış geçeleri', 'soguk-kis-geceleri-sinan-aydindag-gjemk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '10.Mart.2006

Böyle soğuk kış gecelerinde yokluğun

Daha bir acı veriyor

Belki gelirde yüreğimin buzullarını çözersin

Belki ateşinle tüm vücudumu ısıtıverirsin

Ama biliyorum ki gelmeyeceksin

Yüreğinden yüreğime çiçekler vermeyeceksin

Kışa dönmüş tüm mevsimlerime, yazları getirmeyeceksin

Getirmeyeceksin', '10.Mart.2006 Böyle soğuk kış gecelerinde yokluğun Daha bir acı veriyor Belki gelirde yüreğimin buzullarını çözersin Belki ateşinle tüm vücud...', ARRAY['Türk Edebiyatı','Şiir','Sinan Aydındağ']::text[], 8.5, '{"poet":"Sinan Aydındağ","poet_slug":"sinan-aydindag","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/soguk-kis-geceleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski mutlu günler', 'eski-mutlu-gunler-sinan-aydindag-8zrmh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '10.Mart.2006

Eski mutlu günleri arıyorum şimdi

Belki bir çocuk tadında elma şekeri yemeyi

Belki bir genç tadında sevmeyi sevilmeyi

Eski mutlu günleri arıyorum

Hiçbir zaman bulamayacağımı bildiğim halde

Sanki gün geçtikçe kirleniyor bu dünya, kötüleşiyor

Rengi, tadı, kokusu, çizgileri sanki siliniyor

Gün geçtikçe gün, geçiyor

Ve ben her geçen gün için eskiyi biraz daha arıyorum

Sızısını tam şuramda, şuramda duyuyorum', '10.Mart.2006 Eski mutlu günleri arıyorum şimdi Belki bir çocuk tadında elma şekeri yemeyi Belki bir genç tadında sevmeyi sevilmeyi Eski mutl...', ARRAY['Türk Edebiyatı','Şiir','Sinan Aydındağ']::text[], 8.5, '{"poet":"Sinan Aydındağ","poet_slug":"sinan-aydindag","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/eski-mutlu-gunler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uykuların kaçacak', 'uykularin-kacacak-sinan-aydindag-aldra', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '10.Mart.2006

Uykuların kaçacak ağlayacaksın

Benim gibi sende zevk almadan yaşayacaksın

Yalnızlığın ne demek olduğunu 

Benden sonra çok iyi anlayacaksın

Diyorsun ki aramıza dağlar girsin

Mesafeler yollar girsin

Diyorsun ki bu aşkı erteleyelim

Nasıl biterse öyle bitsin, nasıl giderse öyle gitsin

Aşkımız Allaha kalmış da haberimiz yok', '10.Mart.2006 Uykuların kaçacak ağlayacaksın Benim gibi sende zevk almadan yaşayacaksın Yalnızlığın ne demek olduğunu  Benden sonra çok iyi a...', ARRAY['Türk Edebiyatı','Şiir','Sinan Aydındağ']::text[], 8.5, '{"poet":"Sinan Aydındağ","poet_slug":"sinan-aydindag","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/uykularin-kacacak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Sabret*', 'sabret-zeynep-sahin-beirh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yaban gülleri açıyormuş dağlarda 

Menekşeler soluyormuş

İnin cinin top oynadığı boş ovalarda

Güneş bir doğuyor, bir batıyormuş...

Oy yaradılışta alnına yalnızlık mühürlenmiş dağlar,

Siz de ağlarmısınız benim gibi sessiz

Dalarmısınız engine 

Sorarmısınız yaşam niye bu kadar densiz

Bilirmisiniz düzen neden böyle dengesiz...

Hayır iç çekme

Dalıp gitme uzaklara sevdalı

Öyle dertli dertli durmamalı

Yalnızlık seni vuruyorsa acımadan

İnadına ağlamadan

Yağacak bulut gibi dolmadan 

Devrilecek çınar gibi de durmadan

Git gidebilirsen buralardan.

Ama dersen ki; 

Yazgımda varsa körü körüne bağlanmak

O zaman sabret derim çünkü; 

Sabredene vardır büyük mükafat...', 'Yaban gülleri açıyormuş dağlarda  Menekşeler soluyormuş İnin cinin top oynadığı boş ovalarda Güneş bir doğuyor, bir batıyormuş... Oy yaradıl...', ARRAY['Türk Edebiyatı','Şiir','Zeynep Şahin']::text[], 8.5, '{"poet":"Zeynep Şahin","poet_slug":"zeynep-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sabret-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şair/Ateş/Su', 'sair-ates-su-guzin-eye-dundar-mvw28', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sözcükler imgelere sırnaşır 

dizeler düşer / kalkar kararsız 

büyür, hapsolur kozasına 

doğum ve ölüm 

eşsiz ritim / gizemli haz 

bir ömürlük birikim 

su ve ateş 

isimlendirir

eşsiz ipeği 

kozada şekil kalmaz

tavında  ince tül 

yaprağın değil ışığın yansıması 

kabuktan öte renkli 

bir eli aklın ucunda iz sürer 

bir kalem ucunda ağlar eli...', 'Sözcükler imgelere sırnaşır  dizeler düşer / kalkar kararsız  büyür, hapsolur kozasına  doğum ve ölüm  eşsiz ritim / gizemli haz  bir ömürlü...', ARRAY['Türk Edebiyatı','Şiir','Güzin Eye Dündar']::text[], 8.5, '{"poet":"Güzin Eye Dündar","poet_slug":"guzin-eye-dundar","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sair-ates-su-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaç yıl dayanacaksın bu acıya?', 'kac-yil-dayanacaksin-bu-aciya-sinan-aydindag-wqct9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '14.Mart 2006

Kaç yıl dayanacaksın bu acıya,

Söyle kaç yüzyıl katlanacaksın

İstesen de beni hayatından çıkaramazsın

Bir dövme gibi işte orandayım ben

İşte buramdasın sen

Ne kadar denersen dene 

Ne kadar istersen iste

Unutamazsın beni, bende seni

Geride karışmış nefeslerimiz var

Geride dökülmüş gözyaşlarımız var

Geride iki yarım hayat var 

Unut şimdi unutabilirsen

Çıkar hayatından çıkarabilirsen', '14.Mart 2006 Kaç yıl dayanacaksın bu acıya, Söyle kaç yüzyıl katlanacaksın İstesen de beni hayatından çıkaramazsın Bir dövme gibi işte orand...', ARRAY['Türk Edebiyatı','Şiir','Sinan Aydındağ']::text[], 8.5, '{"poet":"Sinan Aydındağ","poet_slug":"sinan-aydindag","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kac-yil-dayanacaksin-bu-aciya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu aşk bitmeyecek', 'bu-ask-bitmeyecek-sinan-aydindag-qsjmp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '15.Mart 2006

Bu birliktelik bitti diye bu aşk bitmeyecek

Bitecekte dirhem, dirhem azalarak bitecek

Belki aylar sürecek belki yüzyılları da geçecek

Bunu bize en iyi zaman gösterecek

Ama bu birliktelik bitti işte 

Artık hayatımda 

Ellerimi tutan, vücudumda dolaşan ellerin yok

Artık dünyamda

Gözlerime bakan, dünyamı aydınlatan gözlerin de yok

Anladım sen yoksun hiçbir şey yok

Hiçbir şeyin anlamı yok

Ne güzel günlerdi bitti işte

Yüzyıllar sonrada olsa kavuşmak dileğiyle', '15.Mart 2006 Bu birliktelik bitti diye bu aşk bitmeyecek Bitecekte dirhem, dirhem azalarak bitecek Belki aylar sürecek belki yüzyılları da g...', ARRAY['Türk Edebiyatı','Şiir','Sinan Aydındağ']::text[], 8.5, '{"poet":"Sinan Aydındağ","poet_slug":"sinan-aydindag","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bu-ask-bitmeyecek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çile', 'cile-levent-ozgec-mqdg1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '- - - - - ÇİLE - - - - -

Ben çileyle nikah kıydım

Zemheri yaz gelir bana! 

Dert kitabı yazanların

Ustası az gelir bana! 

*             *               *

Alırsam kalem elime

Gülerim kendi halime

Çile düşerse dilime

Notası saz gelir bana! 

*               *               *

Yelken açtım dertten yana

Takıldım meçhul kervana

El açınca yaradana

Yarası haz gelir bana! 

*               *               *

Ben çileyle savrulmuşum

Hamurunda yoğrulmuşum

Bin bir dertten doğrulmuşum

Dahası vız gelir bana! 

*               *               *

Alıştı gönül hileye

Bir ömür verdi çileye

Bu kalp dönmüşse eleğe

Fazlası naz gelir bana! 

*               *               *

Duysun beni cümle alem

Çileyi yazar bu kalem

Daha ''Ç'' harfi gelmeden

Yolası kaz gelir bana! 

                   M.Levent ÖZGEÇ

            (Mısralar da Ağlar kitabından)', '- - - - - ÇİLE - - - - - Ben çileyle nikah kıydım Zemheri yaz gelir bana!  Dert kitabı yazanların Ustası az gelir bana!  *             *    ...', ARRAY['Türk Edebiyatı','Şiir','Levent Özgeç']::text[], 8.5, '{"poet":"Levent Özgeç","poet_slug":"levent-ozgec","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/cile-45-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '**Ellerim Yanar', 'ellerim-yanar-umut-gul-leupv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '''Ben Umudum Gülüm Sensin. 

Ne olur tükenmesin umutlar, solmasın güller, 

bak önümüz bahar, 

bir seher yeliyle gel, 

gül koksun umutlarım 

sen olup baksın hüzün gözlerim....'' 



Hasan DURUŞ 

__Ellerim Yanar______TÜRKÜ__

Yüreğimde gül açtı zemheride 

Adını söylerken dillerim yanar 

Giydiğim urbalar ısıtmaz beni 

Elleri değince ellerim yanar 

Söylesem adını göçmen kuşlara 

Arz edip halimi döksem onlara

Götürse selamım nazlı yarime

Kağıda yazdığım sitemim yanar 

Değince saçların okşar yüzümü

Bakışın ateş gibi yakar özümü

Koydun yüreğe hasretin közünü

Ellerim üşürde  yüreğim yanar

Hasretin okudur sineme vuran 

Yarim gül cemalin karşımda duran 

Kuruyan dudağım dillerim susan

Söylerken adını türküler yanar

Değerde kem gözler bu büyük aşka

Gelirse ayrılık sevdalı başa 

Dönerde yaz ayım kara bir kışa

Umudum tükenir  güllerim yanar

            mart 2006', '''Ben Umudum Gülüm Sensin.  Ne olur tükenmesin umutlar, solmasın güller,  bak önümüz bahar,  bir seher yeliyle gel,  gül koksun umutlarım  se...', ARRAY['Türk Edebiyatı','Şiir','Umut Gül']::text[], 8.5, '{"poet":"Umut Gül","poet_slug":"umut-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/ellerim-yanar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*İyilik Geliyor*', 'i-yilik-geliyor-zeynep-sahin-rxsye', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kapın vurulur bazen; 

Hüzün müsaade ister girmek için içeri

Yol verir mutluluk, yol verir sevinç.

Kapın çalınır bazen; 

Sabır izin ister girmek için içeri

Yol verir acele, çekilir telaş.

Kapın vurulur bazen de; 

Mutluluk izin ister girmek için içeri

Yol keser acı, yol keser gözyaşı.

Bir mutluluk kalmışsa sana gelmedik 

Bir tatlı an kalmışsa selam vermedik

Bir huzurlu yaşamaksa öğrenilmedik

Biz bu dünyaya ne diye geldik

Hüzün zorlada olsa ezberletse adını

Gözyaşları bir an olsun eksilmese gözünden

Acıların en acısı ses verse yüreğinden

Yine de gönül kapın açık olsun

ardına kadar…

Bir büyük iyilik geliyor

Dünyalar kadar…', 'Kapın vurulur bazen;  Hüzün müsaade ister girmek için içeri Yol verir mutluluk, yol verir sevinç. Kapın çalınır bazen;  Sabır izin ister gir...', ARRAY['Türk Edebiyatı','Şiir','Zeynep Şahin']::text[], 8.5, '{"poet":"Zeynep Şahin","poet_slug":"zeynep-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/iyilik-geliyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SuaLLemelerim...', 'suallemelerim-asima-azra-1hf45', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kararsız bir sokak lambası gibi

sokağından geçmesem sönecek misin? 

Sözlerin kutuptan esiyor sanki

ısıtıp da göndersen ölecek misin? 

Ellerinde kalmamak uğruna tek

iplerim dolanırdı boynuma hep

bir düğüm de sen at, niyetine çek

çözülsem avucunda görecek misin? 

Bak zamandan çalıyor şarkılar bizi

……..yakalayıp, dizinde dövecek misin? 

ve ketum yelkovanda akrebin izi

……..kalıyor diye aşka sövecek misin?', 'Kararsız bir sokak lambası gibi sokağından geçmesem sönecek misin?  Sözlerin kutuptan esiyor sanki ısıtıp da göndersen ölecek misin?  Elleri...', ARRAY['Türk Edebiyatı','Şiir','Asima Azra']::text[], 8.5, '{"poet":"Asima Azra","poet_slug":"asima-azra","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/suallemelerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İs/Lam/Bol', 'i-s-lam-bol-reyhan-tataroglu-tztam', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sana kimler aşık olmadı ki

                              Kaç körpe saçlarını yolmadı ki

                              Beşiğiydin,sallarken medeniyetleri

                              Hep kan,hep acı,hep zulüm oldu diyetleri

                              Girilirken kapından hadis''e binayen

                              Yaşandı sinende her din ayan beyan

                              Anadolu''dan Rumeli''ye kadardır hisar

                              Kaç gülle açtı yüreğinde,kaç hasar

                             Topkapı Saray,Eyüp Sultan

                             Ayasofya ile Sultanahmetdir Sulh Han

                             Yeditepe diye geçersin bi tarihte

                             Tarihe sığmazsın,yoksun ki tarifte

   

                             Kanadını açan martısın,boğazından geçer su

                             Öyle bir boğaz ki, haram lokmaya pusu 

                            Sadelikti sendeki,boyandın binbir renge

                            Büründün, şimdi kaç sevdasız ahenge

                            Kim bildi kıymetini,söyle benden başka

                            Kim düştü benim gibi,karşılıksız bir aşka

                           Ben seni köylü güzeli diye sevdim

                           Yeditepelerinde gezen bir devdim

                          Şimdi sıraya girmiş birer birer dünürlerin

                          Ben hala ordayım,ben hala dün gürlerim

                         Senden geriye kalan bir boğaz,iki deniz

                         Omuzları çökmüş,yorgun ve soluk bir beniz

                         Yetmiş iki millet çiğner seni,yetmiş iki kul

                         Tevazuda birincisin,ayarda bir incisin

                         Ey! Sevgili İstanbul...', 'Sana kimler aşık olmadı ki                               Kaç körpe saçlarını yolmadı ki                               Beşiğiydin,sallarken m...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Tataroğlu']::text[], 8.5, '{"poet":"Reyhan Tataroğlu","poet_slug":"reyhan-tataroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/is-lam-bol-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kim Bunlar', 'kim-bunlar-levent-ozgec-f4o7p', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Canım hocam Halil SOYUER''İ rahmetle anıyorum.

Onun ''KİM BUNLAR'' İsimli şiirinden etkilenerek yazılmıştır.

             - - - KİM BUNLAR - - -

Benim gönül dünyama kimleri davet ettim

Bazıları vardı ki GELMEYE erindiler! 

Mutlu olduğum anlar gözlerimde parlarken

Bazıları vardı ki GÜLMEYE erindiler! 

*                    *                    *                    *

Sabır çekip oturdum kıbleye yüzüm verip

İnsanların içini bir bir içime serip

Olanın ve bitenin o an farkına varıp

Sorduğum soruları BİLMEYE erindiler! 

*                    *                    *                    *

Çıkmazların içinde bir çıkar yol aradım

Gönlümde ki yer çoktu onları da sarardım

Ne yazık ki ben var ya bu uğurda sarardım

Gözümdeki yaşları SİLMEYE erindiler! 

*                    *                    *                    *

Gönlüm sükut etmedi kaybetmiştim kendimi

Karıştırdım içimde boylam mıydı enlem mi

Yitirince anladım benliğimde ki beni

Kaybolan umudumu BULMAYA erindiler! 

*                    *                    *                    *

Kendime geldiğim an vakit artık geçmişti

Benim gönül dünyamdan kimler gelip geçmişti

Müstehakmış onlara yanlış bir yol seçmişti

Bencilliği taşlara ÇALMAYA erindiler! 

Açtığım bu gönülde KALMAYA erindiler...! 

                                                 M.Levent ÖZGEÇ', 'Canım hocam Halil SOYUER''İ rahmetle anıyorum. Onun ''KİM BUNLAR'' İsimli şiirinden etkilenerek yazılmıştır.              - - - KİM BUNLAR - - ...', ARRAY['Türk Edebiyatı','Şiir','Levent Özgeç']::text[], 8.5, '{"poet":"Levent Özgeç","poet_slug":"levent-ozgec","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/kim-bunlar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arkadaş', 'arkadas-levent-ozgec-xs5aj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '-- ARKADAŞ --

Delikanlı bilirdik biz bu yiğit adamı

Süt dökmüş kedi gibi GÖRÜRMÜSÜN arkadaş! 

Bir zamanlar baktıkça eritirmiş adamı

Sende ona baktıkça ERİRMİSİN arkadaş! 

*                        *                         *

Başını dik tutsa da belli boynu eğilmiş

Yanındaki güzele kötü meyil verilmiş

Sanki mavzer kurşunu yüreğinde eğilmiş

Sende buna gülmekten ÖLÜRMÜSÜN arkadaş! 

*                         *                            *

Bırak ona ilişme biraz seyre dalalım

Bilmem ki hali neydi hayırlara yoralım

Gördüğümüz gerçekse gel bir anlam verelim

Ben anlam veremezsem VERİRMİSİN arkadaş! 

*                           *                            *

Bu kalkışı bak şimdi neden çok ani oldu

Rengi benzi atınca  hemen sarardı soldu

Kızdan azar yiyince gözüne duman doldu

Giden bu huri kimdi BİLİRMİSİN arkadaş! 

*                             *                          *

Haydi kalkıp soralım içini döksün bize

Delikanlıyız elbet konuşalım yüz yüze

Bu haline yazıktır yoksa çıkamaz güze

Yanına varıp gelsem DURURMUSUN arkadaş! 

*                               *                          *

Çekingen bir tavırla selam verip oturdum

Biri gelecek sandım o baktı ben yoruldum

Muhabbet içindeyken en son bir soru sordum

Şimdi başın duvara VURURMUSUN arkadaş! 

*                                *                          *

Yeniden geri döndüm anlattım bu olanı

Yiğit bilmiştim meğer çayıra salınanı

Şimdi sende gördün mü sararmadan solanı

Bu esketek yoluna KURURMUSUN arkadaş! 

Sonra başın duvara VURURMUSUN arkadaş! 

                                                M. Levent ÖZGEÇ

                                       GÖNÜL PINARI Kitabından', '-- ARKADAŞ -- Delikanlı bilirdik biz bu yiğit adamı Süt dökmüş kedi gibi GÖRÜRMÜSÜN arkadaş!  Bir zamanlar baktıkça eritirmiş adamı Sende on...', ARRAY['Türk Edebiyatı','Şiir','Levent Özgeç']::text[], 8.5, '{"poet":"Levent Özgeç","poet_slug":"levent-ozgec","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/arkadas-118-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Zor Olmalıydı*', 'zor-olmaliydi-zeynep-sahin-6zqxb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu kadar kolay olmamalıydı mücadelemiz

Öyle kolay elde edilmemeliydi nimetler.

Bilmeliydik şükretmesini.

Çekişmemiz büyük olmalıydı ormanlar kralıyla 

Hani ağzında ya ekmek aslanın.

Kolay olmamalıydı zamanla yarışımız 

Ya teknemiz batmalıydı bu okyanusta 

Ya da kaybolmalıydı küreklerimiz.

Öyle kolay olmamalıydı mücadelemiz

kolay olmamalıydı nefes almamız 

Her nefes alışımızda tabiata borçlu olmalıydık

Temiz bir dünya bırakmalıydık gelecek kuşaklara 

Kolay olmamalıydı ağaç kesmek çiçek koparmak

Kolay olmamalıydı kardeşim parfümü, fabrikası

Delinmemeliydi ozon tabakası…', 'Bu kadar kolay olmamalıydı mücadelemiz Öyle kolay elde edilmemeliydi nimetler. Bilmeliydik şükretmesini. Çekişmemiz büyük olmalıydı ormanlar...', ARRAY['Türk Edebiyatı','Şiir','Zeynep Şahin']::text[], 8.5, '{"poet":"Zeynep Şahin","poet_slug":"zeynep-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/zor-olmaliydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çoban ile Kuzu', 'coban-ile-kuzu-ozgur-coban-udxw2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yirmi yedi yılın sır-namesidir bu! 

Aşkın kalp atışı, ayak sesidir bu! 

Güzeller güzeli bir körpe kuzuyla

Bir özgür çobanın hikâyesidir bu! 

(Özgür Çoban)', 'Yirmi yedi yılın sır-namesidir bu!  Aşkın kalp atışı, ayak sesidir bu!  Güzeller güzeli bir körpe kuzuyla Bir özgür çobanın hikâyesidir bu! ...', ARRAY['Türk Edebiyatı','Şiir','Özgür Çoban']::text[], 8.5, '{"poet":"Özgür Çoban","poet_slug":"ozgur-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/coban-ile-kuzu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güllere Adanmış Bir Ömür', 'gullere-adanmis-bir-omur-nihat-malkoc-te0dd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Güllere adanmış bir ömür bizimkisi, gonca güllere…

Camdaki buğudur çocukların öfkesi

Aynadaki suretimdir yarınlara yansıyan ışık.

Ziller vuslattır yürekleri birbirine bağlayan.

İçimdeki çocuğun gözyaşları çağlayan

Gonca güller yetiştiren bahçıvanım ben

Yani öğretmen! ...

Süzülen kanadıyım tutsak yüreklerin

Eriyen mum misali yandıkça aydınlanır ufuklar

Keskin bir ışığım karanlığı delen

Bir çığlığım Edirne’den Kars’a yankılanan

Benden doğar akarsular ve güneş.

Fesleğenler yetiştiren bahçıvanım ben

Yani öğretmen! ...

Şehrin uğultusunda sükûnetim,

Karanlıklar içinde ürkek bir ay ışığı

Harmanlanmış sevgiyim yüreklerde

Duayım göğün yedinci katında kabul bekleyen

Umuda bakan gözlerin mavisiyim

Sardunyalar yetiştiren bahçıvanım ben

Yani öğretmen! ...

Bir sabah rüzgârıyım, püfür püfür esen yel

Aklım Yunus, kalbim Mevlâna’dır benim

Hicran ateşine bir damlacık su

Anadolu bozkırında açan kardelen

Gönül ummanlarına akan sel

Karanfiller yetiştiren bahçıvanım ben

Yani öğretmen! ...

Şiirler, masallar, kırık dökük hikâyeler geçer düşlerimden

Göğümde parıldar, büyür yıldızlar

Çatlamış yüreğime rahmet yağmurları yağar

Çorak tarlalara güller dikerim, boynu bükük güller

Derede, tepede, kırda izim var

Yaseminler yetiştiren bahçıvanım ben

Yani öğretmen! ...

Bir demet gülüm kırık vazolarda solmaya mahkûm

Toprağa düşen buğday tanesiyim

Bire bin veririm hoyrat rüzgârlara rağmen

Sonsuzluğa açılan yelkenliyim açık denizlerde

Çiçekler kokusunu alır benden

Menekşeler yetiştiren bahçıvanım ben

Yani öğretmen! ..

Mecnun’un kalbinde yanan sevda ateşiyim

Serçelerin sırtına binse de develer, 

Düşmanıyım umarsızlığın, irfan bayrağıyım ben

Kokuşmuş eylüllerde gönüllü umut taciriyim

Kanım kılcal damarlarında gezer gençliğin

Şebboylar yetiştiren bahçıvanım ben

Yani öğretmen! ..

Kalemdeki mürekkep alın terimdir

Koca dünya kaybolur avuçlarımda

Gökyüzüne salınan uçurtmayım ben

Kır çiçeklerinde üşüyen şebnem

Ağıyı bal eyleyen Eyüp’ün sabrı

Çiğdemler yetiştiren bahçıvanım ben

Yani öğretmen! ...

Yanık bir ezgiyim hasret türkülerinde

Malazgirt’te paslı bir hançer, Patnos’ta yalnızlık

Safranbolu’daki ahşap evin sofasıyım

Tokat’ta genç kızların kırdığı acı tütün

İdare lambasında titreyen loş ışığım

Gelincikler yetiştiren bahçıvanım ben

Yani öğretmen! ...

Anadolu yollarında kağnılar benden geçer

Irmakları besleyen kaynak benim

Yarının türküsünü söyler dudaklarım

Toprak kokar minik elleri çocukların

Ben ki yüce dağ başında sönmeyen ateş

Sümbüller yetiştiren bahçıvanım ben

Yani öğretmen! ...

Ağrı Dağı’nda tipi, Bolu Dağı’nda gürgen

Gelinlik bir kızın sandığındaki çeyiz

Parmaklıklar ardında bekleyenlerin düşü

Garip bir köylünün ayağında yırtık çarık

Öğrencinin elinde bembeyaz tebeşirim

Gülhatmiler yetiştiren bahçıvanım ben

Yani öğretmen! ...

Gözlerde parlayan nur, şairin dilinde söz

Cerrahın elinde neşter, âlimin hokkasında mürekkep

Karanlığa yakılan mum, kanayan yaraya merhem

Dede Efendi’de yarım kalmış şehnaz bir şarkı

İnsanlığın ilk babası cennetten kovulmuş Âdem

Bin bir renkte açan çiçek, her bir güzel şeyim ben

Yani öğretmen! ...

Öksüzlere sıcak kucak, ezilene çelik bilek

Zalime saplanan kılıç, susayana soğuk pınar

Şeytanın yanında melek, dudaklarda kutlu dilek

Hâkimin kalbinde vicdan, mahkûmun içinde umut

Garibanın tutan eli, âşığın sazının teli

Misk ü amber kokan öpülesi elim ben

Yani öğretmen! ...', 'Güllere adanmış bir ömür bizimkisi, gonca güllere… Camdaki buğudur çocukların öfkesi Aynadaki suretimdir yarınlara yansıyan ışık. Ziller vus...', ARRAY['Türk Edebiyatı','Şiir','Nihat Malkoç']::text[], 8.5, '{"poet":"Nihat Malkoç","poet_slug":"nihat-malkoc","theme":"Türk Şiiri","is_hero":false,"total_lines":91,"source_url":"https://www.antoloji.com/gullere-adanmis-bir-omur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ressamın Ellerimmiş', 'ressamin-ellerimmis-guler-atas-nqnfs', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Önce saçlarımı kazıttım

Kafamın içini görmek için

Sonra gözlerimi daha renkli yaptım

İçinde kararan seni seçmek için

Onlarca seni dizdim önüme

Kendimi gördüm durduğun yerde

aklımda

Gözlerimde

Renklerimde

Yüreğimde 

Benim ellerimmiş ressamın

Sonra kan vermişim damarlarımdan

Yüreğimi bölmüş bir cerrah

Aşk vermiş sana

Renklerimi çıkardım resimden

Siyah beyazmışsın

Damarlarımı tıkadım 

Cansızmışsın

Yüreğimi aldım 

Ölmüşsün

Şimdi gidiyorum 

Aslında hiç yokmuşsun

           

       15/03/2006....bodrum/22:30', 'Önce saçlarımı kazıttım Kafamın içini görmek için Sonra gözlerimi daha renkli yaptım İçinde kararan seni seçmek için Onlarca seni dizdim önü...', ARRAY['Türk Edebiyatı','Şiir','Güler Ataş']::text[], 8.5, '{"poet":"Güler Ataş","poet_slug":"guler-atas","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ressamin-ellerimmis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şehri İstanbul', 'sehri-i-stanbul-ali-kemal-i-cen-w9rhp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Öyle bir devir ki

Ne gökyüzü gördü

Ne yeryüzü böyle bir ihtişam ve zerafet

İşte o şehri istanbul.

Denizden çekilen kayılar

Martı sesleri ve arka sokakları

Ne ister gönül sahil kenarında

Bir çay birde kuşlara atılan bir parça ekmek.

Emek kouyor bu sehir

Meydanlarında isyanın sesi

Sokakları küllenmiş sevdalar gibi savruluyor

Yanlızlık aksamı sonbaharda 

Yaşadığımız şehri istanbul.

Öyle doyulmaz bakıyor ki mavi gökyüzü

Sana ve o güzel denize

Saraylarıdan ve meydanların da 

Sana sesleniyorum

Ey şehri istanbul 

Yaşamak seni anlamaktır 

Ve ulaşmak sana çok uzak değildir.

15-03-2006', 'Öyle bir devir ki Ne gökyüzü gördü Ne yeryüzü böyle bir ihtişam ve zerafet İşte o şehri istanbul. Denizden çekilen kayılar Martı sesleri ve ...', ARRAY['Türk Edebiyatı','Şiir','Ali Kemal İçen']::text[], 8.5, '{"poet":"Ali Kemal İçen","poet_slug":"ali-kemal-i-cen","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sehri-istanbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ellerinde', 'ellerinde-nur-demirciler-cy9i5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Harman yeri gibi dağınık,

sana dair ne varsa aklımda.

Gözlerinde hapis,

sımsıkı, ezik yine yüreğim.

En ağır vebali öder gibiyim.

Ne sözler verdim oysaki kendime, 

ne sözler...

Söz geçirebilseydim eğer...

Bu kez gerçekten emindim, 

dönmeyecektim geri.

Silmeye, söküp atmaya kararlıydım 

yüreğimden sosuza dek seni.

Yeminler ettim,

hemde büyük yeminler.

Her yemin yeniden doğuşum oldu sanki.

Ne zaman çıktıysan karşıma,

uçup gitti yine, ne varsa aklımda.

Verdiğim her söz, ettiğim her yemin,

daha da büyütmüş meğer,

duyduğum aşkı yüreğimde,

sen bilmesende.

Bildiğim tek şey var ki ben,

Yaşamla ölüm arasında bir yerlerde,

Kurtuluşum ellerinde.

15/03/2000

İstanbul', 'Harman yeri gibi dağınık, sana dair ne varsa aklımda. Gözlerinde hapis, sımsıkı, ezik yine yüreğim. En ağır vebali öder gibiyim. Ne sözler v...', ARRAY['Türk Edebiyatı','Şiir','Nur Demirciler']::text[], 8.5, '{"poet":"Nur Demirciler","poet_slug":"nur-demirciler","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ellerinde-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yokuşlar', 'yokuslar-mustafa-anar-7yt1q', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yokuşlar…

İnsafsız yokuşlar…

Ümidimin eşiğinden

Hayallerime kadar,

Her çırpınışımda biraz daha dar

Her haykırışımda biraz daha karanlık

Sese ses vermeyen zindanlar içinde

Uzar, uzar, uzar yokuşlar.

Su, hava, yer, gök, ufuklar

Ve ümit

Bir gün susar.

İşte o an başlar yokuşların senfonisi.

Hüzzam bir beste çalınır sazlarında

Gökkubeyi boğar nağmeleri

Ve yağmur yağar

Sazlar sustuğu an 

Dardır artık sabahlar

Dardır artık sabahların o en sevdiğim vakti bile.

Biter artık yokuşlar

Hayatıma son rötuşlar

Ve ben artık ölürüm…', 'Yokuşlar… İnsafsız yokuşlar… Ümidimin eşiğinden Hayallerime kadar, Her çırpınışımda biraz daha dar Her haykırışımda biraz daha karanlık Sese...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Anar']::text[], 8.5, '{"poet":"Mustafa Anar","poet_slug":"mustafa-anar","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yokuslar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yenik Savaşçı', 'yenik-savasci-mustafa-anar-hwmpw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şehrin tüm sessizliğini çektim içime

Gürültü boğdu şehri.

Kalabalıklar taştı şehirden

Çünkü tüm yalnızlıkları doldurdum yüreğime

Artık ben,

Göçememiş bir kuş kadar yalnız

Yenilmiş bir yürek gibi sessiz

Dolaşırım şehrin bu küf kokan sokaklarında.

Tırnaklarıma akıttığım öfkeyle taralı saçlarıma

Konuk olur yıldızlar.

Ayaklarıma yürünmemiş yolların hırçın merakı dolar

Sıklaşır adımlarım.

Bin hüzün dadanır göz bebeklerime.

Kirpiklerim karanlıkları emer,

hiç süt emmemiş bir çocuğun şevkiyle.

Her durakta bir hüzün toplar gönlüm.

Yenik bakışlarla seyrederim her birine bir hayali gömdüğüm bulutları.

Her adımda daha fazla özlerim son durağı.

Ben 

Yenilmişliğin ezikliğini duymadığım an,

Görmediğim an acımtırak bakışları,

Bu küf kokusunu solumadığım zaman,

Ben

İşte o an başlayacağım hayata yeniden

Şehrin tüm sessizliğini içime çektiğim yerden', 'Şehrin tüm sessizliğini çektim içime Gürültü boğdu şehri. Kalabalıklar taştı şehirden Çünkü tüm yalnızlıkları doldurdum yüreğime Artık ben, ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Anar']::text[], 8.5, '{"poet":"Mustafa Anar","poet_slug":"mustafa-anar","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yenik-savasci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut ve Ben', 'umut-ve-ben-mustafa-anar-sff69', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Umudum var

Sevdalım umut

Gün olur yağmur ekeriz göğün göğsüne 

Birlikte

Umut yağmur olur, çiçek olur, açar yar elinde

Ben gözyaşı biçerim yarin bakmadığı gözlerimde

Yalnız…

Kah kuş olur umut

Takılırım kanadına gezeriz olmaz düşlerde

Birlikte…

Umut düşlerde kalır,

Ben uyanıp kör karanlıklarda ağlarım

Yalnız….

Kah yıldız olur umut

Ben kuyruğu olurum

Kayarız gecenin en derinlerine

Birlikte….

Bir dilek tutar sevgililer ardımızdan

Umut onların olur

Ben uykusuz seherlere düşerim

Yalnız…..

Kağıt olur umut, kalem olur

Şiirler yazarız, sevda şiirleri

Birlikte…..

Kalem gerçeğe çarpar, umut gidiverir sebepsiz

Ben son mısraya düşerim

Yalnız….

Nefes olur umut

Çekerim onu gönlüme doyuncak, yaşarız sevgilerde

Birlikte….

Ve ömür dolar bir akşam vakti

Umut başka bir yar bulur kendine

Ben son kez tükenirim ve yine

Yalnız…..', 'Umudum var Sevdalım umut Gün olur yağmur ekeriz göğün göğsüne  Birlikte Umut yağmur olur, çiçek olur, açar yar elinde Ben gözyaşı biçerim ya...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Anar']::text[], 8.5, '{"poet":"Mustafa Anar","poet_slug":"mustafa-anar","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/umut-ve-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklediğim', 'bekledigim-mustafa-anar-c2z1l', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bitecek işkenceler, bitecek zulüm

Bir karanlık odada güneşe doyacağım

Kalkacak bedenimden tüm ağırlıklar

Uzaklarda bir yere kuş olup uçacağım

Bulutların üstünden son bir kez

Bakacağım köhne dünyaya

Ve sonra

Yırtarak perdeleri

Göreceğim görünmezleri

Bileceğim bilinmezlerin hepsini

Biliyorum ölümü seveceğimi

Biliyorum ölümün bir gün 

Beni de isteyeceğini

Biliyorum', 'Bitecek işkenceler, bitecek zulüm Bir karanlık odada güneşe doyacağım Kalkacak bedenimden tüm ağırlıklar Uzaklarda bir yere kuş olup uçacağı...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Anar']::text[], 8.5, '{"poet":"Mustafa Anar","poet_slug":"mustafa-anar","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bekledigim-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çanakkale Savaşı', 'canakkale-savasi-betul-pehlivan-0zg95', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yıl 1915,

Günlerden 18 Mart,

Bugün hava yine çok sıcaktı,

Buna rağmen, savaş sürmekteydi.

Ordumuz var gücü ile savaşmaktaydı.

Sıcaktan da hiç bunalmamaktaydı.

Çünkü onlar Türk oğlu Türk’tü,

Fransız ve İngilizler,

Hem bunaldılar, hem de yenildiler.

Bu sonuca sevindi Türk oğlu,

Biraz da üzüldü hani Türk oğlu,

Çünkü 1000’lerce şehit vermişler.

Bu kutsal toprak ve bayrak uğruna,

Nice nice evladını şehit vermişler.

15 Mart 2003 KIRIKKALE', 'Yıl 1915, Günlerden 18 Mart, Bugün hava yine çok sıcaktı, Buna rağmen, savaş sürmekteydi. Ordumuz var gücü ile savaşmaktaydı. Sıcaktan da hi...', ARRAY['Türk Edebiyatı','Şiir','Betül Pehlivan']::text[], 8.5, '{"poet":"Betül Pehlivan","poet_slug":"betul-pehlivan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/canakkale-savasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çanakkale’m', 'canakkale-m-betul-pehlivan-dyhn5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yıl 1915,

Mustafa Kemal Atatürk koştu,

Kahraman ordusuyla,

Yendi düşmanları, 

Fransız ve İngilizler bizi top ateşine tutsa da,

Bizden sayıca üstün olsalar bile,

100’lerce gemileri olsa da,

Biz yendik onları, savaşın sonunda.

Yendik ama,

Verdik binlerce şehit,

Yurdumuz yanıp kül olsa bile,

Savaştık biz. 

Koruduk yurdumuzu,

Verdik canımızı topraklarımıza,

Sonunda gitti düşman,

Kalmadı topraklarımız onlara,

Birçok şehit verdik,

Ama unutmadık ve her daim andık onları,

Her 18 Mart’ta,

Silmedik kalplerimizden sizi.

Bizlerde koruyacağız,

Canlarınızı verdiğiniz,

Bu kutsal toprağımızı,

12 Mart 2004 Kırıkkale', 'Yıl 1915, Mustafa Kemal Atatürk koştu, Kahraman ordusuyla, Yendi düşmanları,  Fransız ve İngilizler bizi top ateşine tutsa da, Bizden sayıca...', ARRAY['Türk Edebiyatı','Şiir','Betül Pehlivan']::text[], 8.5, '{"poet":"Betül Pehlivan","poet_slug":"betul-pehlivan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/canakkale-m-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göremezsin Aynada Aksini', 'goremezsin-aynada-aksini-birsen-ates-mbwxi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sardı yine soluğumu anlamsız yaşam

sen yoksun hiç olmadın ki

alıyorum derinden bir nefes daha

yaşıyor muyum

solgun bir aynadan 

çığlık çığlığa düşlerime

gözleri ışıltılı biri bakıyor 

bakışları değmedi gözlerime

artık göremezsin aynada aksini

biliyorum

umudun rengiydi mavim siliniyor

yaşam bir kısır döngü

bizler içinde dönüp duruyorken

hep aynı sanrılı düşünceler

soluğuma sarılıyor gri şehir

ve acı gözlerimi büyütüyor

hayallerimi kim çaldı benden

yoksa ben mi takılı kaldım düşlere

ruhum çarpar durur yalnızlığıma 

ürkütüyor

biliyorum şimdi

sislerin ardından gelen değilim

yiten bir siluetim

aynalar öyle söylüyor

15.03.06', 'sardı yine soluğumu anlamsız yaşam sen yoksun hiç olmadın ki alıyorum derinden bir nefes daha yaşıyor muyum solgun bir aynadan  çığlık çığlı...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/goremezsin-aynada-aksini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kader dedim ya....', 'kader-dedim-ya-veysel-siltag-e5yqy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kader dedim ya yaşanmış saydığın hüzünlü tarihine...

Ve sensiz geçirdiğim o kahrolası günlere....

Yalan olan sahte sevgiliye ve de olmayan sevgiye...

Sen gözümün nuru, sen yalan sevdam..! 

Kader dedim ya, artık sensiz geçmiş olan dünlere.....

Hayatımın hoyrat vaktiydi, çekip gittiğin gün....

Gecelerim kabus artık, gündüzlerim sürgün....

Aşkın yüreğim de halen daha koca bir yangın....

Sen gerçek sevdamın, yalan kahramanı......! 

Gün dediğin gelir geçer, hesaplaşırız mahşerde birgün....', 'Kader dedim ya yaşanmış saydığın hüzünlü tarihine... Ve sensiz geçirdiğim o kahrolası günlere.... Yalan olan sahte sevgiliye ve de olmayan s...', ARRAY['Türk Edebiyatı','Şiir','Veysel Sıltağ']::text[], 8.5, '{"poet":"Veysel Sıltağ","poet_slug":"veysel-siltag","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kader-dedim-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '2003 Yılından Beklediklerim', '2003-yilindan-beklediklerim-betul-pehlivan-50gxk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '2003 YILINDAN BEKLEDİKLERİM

1. Savaş Çıkmasını İstemiyorum! 

    Savaş çıkarsa krizler çıkacaktır. Kriz çıkınca da insanlar yiyecek alamaz. Yiyecek alamayınca açlıktan öleceklerdir. Açlıktan ölmek, savaşıp ölmekten iyidir. Yiyeceğe  tek bizim değil, devleti yönetenlerinde ihtiyacı vardır. Onlarda yiyecek bulamazlar ise; onlarda ölecektir. Peki açlıktan herkes ölürse bu devletin sahibi kim olacak? Iraklılar mı? 

    Atatürk:”Zorunlu olmadıkça savaş bir cinayettir” demiştir. Biz de bu savaş için zorunlu muyuz? Zorunlu değilsek savaşmaya da gerek yoktur.

    Amerika savaşmamızı istiyor. Çünkü tek başına bu coğrafyada savaşamaz. Savaşsa da başarılı olamaz.  Belki de yok olacaktır. Bunun içinde bizi savaşa zorlamaktadır. Kendini değil, bizi, bizim ekonomimizi batıracaktır. O nedenle bizi yönetenler, savaş kararı almadan şapkalarını önlerine koyup bir daha düşünseler diyorum.

2. Ekonomimiz düzelsin! Kimse dilenmesin, kimse aç, evsiz ve işsiz kalmasın! 

    Ben 5nci sınıfa gidiyorum. Büyüyünce doktor olmak istiyorum. Sınıfımızda avukat, mühendis, memur olmak isteyen arkadaşlarım da var. Ama ekonomimiz düzelmez, beni ve arkadaşlarımı istihdam edecek iş sahaları olmaz ise, Türk insanının mutluluğu azalır. Refah seviyesi düşer.

    Eğer hâlâ aynı şeyi yaparsak; ülkemizdeki hırsız, kapkaççı, dolandırıcı vb. kişiler çoğalır. İnsanlar işsizlikten intihar ederse, analar 10-20 çocuk doğurursa, ekonomi düzelmezse, ülkemize sahip çıkan olmaz. Sahipsiz bir ülke de çöker ve tarihin çöplüğüne atılır. 

3. Yurdumuzun Zenginleri! 

    Bu ülkenin kaynaklarını kullanarak zengin olan iş adamlarımız; şu anda yurt dışında bulunan paralarınızı acaba ne zaman ülkemize getirip ekonomiye kazandıracaksınız? Bunu yapmadığınız sürece terör, işsizlik, kaptı kaçtı vb. eylemler hergün daha da artarak devam edeceğini biliyor musunuz? Yoksa bilmek mi istemiyorsunuz? Hadi bu sene sizin için yurt dışı paralarınızın ülkemize transfer yılı ve ekonomiye kazandırma yılı olsun. Olmaz mı? Ya siz meclis sakinleri bu konuda acaba sizler neler yapmayı düşünüyor sunuz? Sermayenin ülkemize transferi ve tekrar kazandırılması için kanun değişiklikleri yapacak mısınız? Lütfen elele verip daha zengin bir ülke yaratmaya ne dersiniz? 

4. Tarihi Eserlerimize Sahip Çıkalım.

    Ülkemiz tarihi eser yönünden oldukça zengin bir ülkedir. Ama bu tarihi zenginlikleri yakıp, yıkmak ve onları yok etmek için adeta görünmeyen bir el işaret etmiş ve herkes el birliği ile bunları yok etme gayreti içerisine girmiştir. Neden? Bir daha Hitit, Lidya, veya Frigya devleti kurulacak mı? Ya da Osmanlı Devleti kurulacak mı? Cevabınız hayır ise onların miras bıraktığı tüm güzelliklere sahip çıkalım. Onların bakım ve onarımını yaparak ülkemize gelecek turistlere sunalım. Olmaz mı? Böylece de büyük bir döviz girdisi olan kaynağı daha güçlü ve sağlam tutarız. 

     Hatta bununla da yetinmeyip, bize ait olan kültür miraslarının yurt dışındaki müzelerden getirilerek ülkemizdeki müzelerde sergilenmesi için bir seferberlik başlatmalıyız. Hadi! ...

5. Sağlam Yapı ve Binalar İstiyorum! 

    Gazeteleri veya Tv.leri izliyoruz hergün yıkılan veya göçen bir bina veya ev yada minare (lodostan yıkılmış)  Neden yıkılıyorlar ki? Mimar Sinan’ın 4-5 asırlık eserlerine bir şey olmaz iken neden şimdi modern imkanlar ile ve modern teknik anlayışıyla yapılan binalar hemen yerle bir oluyor? Acaba inşaat mühendisliği fakülteleri mi yoksa mimarlık fakültelerinin eğitimi mi yetersiz? Bir daha 17 AĞUSTOSLAR olmasın diye hergün dilek ve temennide bulunuyoruz ama neden bunlar oluyor? 

Yine mi çadır kentler? Ve yine ceset torbalı bizim insanlarımız. Haber bültenlerinde izliyoruz, en kıytırık ülkede 7.6 şiddetinde deprem oluyor ve 1 kişi bile ölmez iken bizde 6 ve üstünde meydana gelen depremlerde ölü sayısı hemen 50-100’leri buluyor. Artık bunlara yeter denmeli ve insanımıza yakışan bina teknik ve teknolojileri kullanılmalıdır. Bina enkazlarından meydana gelen insan kaybına hayır! ... Buna göre: Bir insanın hatası, bin insanın ölümüne bedel oluyorsa birileri utanmalı veya bunun hesabını vermelidir.

6. Para Peşinde Koşulmasını İstemiyorum! 

    İnsana yakışan değerlerin başında gelen insanlık ve insanlığa değer verilmesi günümüzde maalesef bir anlam ve önem taşımamaktadır. Örnek: Şimdiki öğretmenler çocuklara (yani biz öğrencilere)  fazla bir şey öğretmiyorlar/vermiyorlar. Hatta şimdiki öğretmenler branş öğretmenliğini seçiyorlar. Böylece de başka bir yapıp daha çok para kazanabiliyorlar. 

   Siz öğretmenler böyle yaparsa çocuklar (yani biz öğrenciler)  hem bir şey öğrenemez, hem de yaptıkları 2 nci işlerden elde ettikleri gelir ile bu geliri elde edecek diğer insanları da gelirinden etmektedirler. Sonra da derslerde dürüstlük nutukları atılmasın ve ahlâk üzerine öğütler verilmesin...

7. Son Sözüm: Bu millet, yurdumuzdan olmayan birisini başbakan yapmak isterse veya böyle bir özlem içerisinde bulunursa bizi elbette krizler, soygunculuk, vb. kirli işler bekler. Sonuçta da yok oluruz. 

Tüm bu yazdıklarımın hepsinin birer gerçek olduğunu bilmenizi istiyorum. İnsanlar hâlâ aynı şeyleri yaparsa, devlet görevini yapmazsa, bu Dünya’nın ve Ülkemizin hali nice olur? 

Cevap: Yok olur.

Betül (Lali)  Pehlivan

NOT: Bu yazım, Mersin Tabipler Odası Bülteni olan “ARTER” dergisinin 15nci sayısı MART – NİSAN 2003 tarihinde yayınlanmıştır. (Sf.45)', '2003 YILINDAN BEKLEDİKLERİM 1. Savaş Çıkmasını İstemiyorum!      Savaş çıkarsa krizler çıkacaktır. Kriz çıkınca da insanlar yiyecek alamaz. ...', ARRAY['Türk Edebiyatı','Şiir','Betül Pehlivan']::text[], 8.5, '{"poet":"Betül Pehlivan","poet_slug":"betul-pehlivan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/2003-yilindan-beklediklerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdik! ..Yaradan''dan Ötürü', 'sevdik-yaradan-dan-oturu-kadir-albayrak-6dwg4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni sevdim diye

Seni sevdim diye sevmiştim herkesi

En çirkinleri, sevimsizleri

Tahammül edemediklerimi bile

Sırf ama sırf seni sevdim diye

………………

Sonra anladım ki; Yanılmışım

Ben severken, 

Severken aldatılmışım! ...

Bir darbe daha mı

Ne kadar aptalmışım! ....

………………

Sen gittin diye

Gittin diye nefret etmedim kimseden

Senin gibilerde “insanlığın bir türü”

Lakin yaratılanı sevdik,

Sevdik! .... Yaradan’dan  ötürü', 'Seni sevdim diye Seni sevdim diye sevmiştim herkesi En çirkinleri, sevimsizleri Tahammül edemediklerimi bile Sırf ama sırf seni sevdim diye ...', ARRAY['Türk Edebiyatı','Şiir','Kadir Albayrak']::text[], 8.5, '{"poet":"Kadir Albayrak","poet_slug":"kadir-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sevdik-yaradan-dan-oturu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Varlık', 'varlik-levent-i-skenderoglu-qjj39', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Varlık üstüne varlık

Yokluk kaşıkta aş

Sen gülümse hayata 

Zorluk bir kuşa eş

Sen tanı aynaları 

Yansıyan sana kardeş

Yanılsa yansıyanı 

İçine doğsun güneş', 'Varlık üstüne varlık Yokluk kaşıkta aş Sen gülümse hayata  Zorluk bir kuşa eş Sen tanı aynaları  Yansıyan sana kardeş Yanılsa yansıyanı  İçi...', ARRAY['Türk Edebiyatı','Şiir','Levent İskenderoğlu']::text[], 8.5, '{"poet":"Levent İskenderoğlu","poet_slug":"levent-i-skenderoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/varlik-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnan Hakkım Bile Yok', 'i-nan-hakkim-bile-yok-kadir-albayrak-f3r9m', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Belki boş yere sevdim belki ''suçlu'' değilsin

Ne desen fark etmiyor yine yüreğimdesin

Seni unutmak çok zor buna itirazım yok

Ama sen affetmek! ... ''İnan hakkım bile yok! ..''', 'Belki boş yere sevdim belki ''suçlu'' değilsin Ne desen fark etmiyor yine yüreğimdesin Seni unutmak çok zor buna itirazım yok Ama sen affetmek...', ARRAY['Türk Edebiyatı','Şiir','Kadir Albayrak']::text[], 8.5, '{"poet":"Kadir Albayrak","poet_slug":"kadir-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/inan-hakkim-bile-yok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öyle yazmalıyım ki', 'oyle-yazmaliyim-ki-levent-i-skenderoglu-84c8b', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Öyle yazmalıyım ki şiiri 

Dedi şair

Söz söylenmesin üstüne

Bir daha aşka dair', 'Öyle yazmalıyım ki şiiri  Dedi şair Söz söylenmesin üstüne Bir daha aşka dair...', ARRAY['Türk Edebiyatı','Şiir','Levent İskenderoğlu']::text[], 8.5, '{"poet":"Levent İskenderoğlu","poet_slug":"levent-i-skenderoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/oyle-yazmaliyim-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çanakkale Geçilmez', 'canakkale-gecilmez-mehmet-ali-cetin-gursr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir destan ki

Adı Çanakkale

Ey ölüm 

Bugün diriler günü 

Sen yere gir

Diri kalan Şehitler

Bugün göğe çekilir

Mehmedim sıra sıra

Peygamberin ardında

Bak ne diyor iyi dinle

Kime diyor iyi belle

Sadece iki kelime

“Çanakkale geçilmez”', 'Bir destan ki Adı Çanakkale Ey ölüm  Bugün diriler günü  Sen yere gir Diri kalan Şehitler Bugün göğe çekilir Mehmedim sıra sıra Peygamberin ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Çetin']::text[], 8.5, '{"poet":"Mehmet Ali Çetin","poet_slug":"mehmet-ali-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/canakkale-gecilmez-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gün', 'bu-gun-levent-ozgec-sye2l', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '- - - BU GÜN - - -



Ne sonbahar tadı var ne de yaz ile kışın

Mevsimler yağmurları sanki BÖLÜYOR bu gün! 

Damlayınca gönlüme gözümden akan yaşım

Gözlerin bu halime sanki GÜLÜYOR bu gün! 

*                               *                                      *

İçimde hüzün varken gözlerin neden güler

Neler geçer aklımdan bir bilsen neler neler

Bu gözlerin gönlümden bakarsın bir af diler

Sözlerin gözyaşımı sanki SİLİYOR bu gün! 

*                               *                                      *

Ey sevgili sen boş ver benim garip halimi

Ağlayıp gülsem bile avuturum kendimi

Varsın şu an desinler akıllı mı,deli mi

Bakışların bağrımı sanki DELİYOR bu gün! 

Gözlerin gözlerime sanki ÇİLİYOR bu gün..! 

                                                    M.Levent ÖZGEÇ

                                              GÖNÜL PINARI kitabından', '- - - BU GÜN - - - Ne sonbahar tadı var ne de yaz ile kışın Mevsimler yağmurları sanki BÖLÜYOR bu gün!  Damlayınca gönlüme gözümden akan yaş...', ARRAY['Türk Edebiyatı','Şiir','Levent Özgeç']::text[], 8.5, '{"poet":"Levent Özgeç","poet_slug":"levent-ozgec","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bu-gun-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
