INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölçü', 'olcu-necati-cavdar-1dh1p', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Batın için; sır ve hikmet

Zahir için; çıplak hakikat', 'Batın için; sır ve hikmet Zahir için; çıplak hakikat...', ARRAY['Türk Edebiyatı','Şiir','Necati Çavdar']::text[], 8.5, '{"poet":"Necati Çavdar","poet_slug":"necati-cavdar","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/olcu-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şehit', 'sehit-necati-cavdar-pdts4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ŞEHİT

Göğsünü siper eder demir devlere,

Ruhları uçar gider

Rab’leri için can verenleri; 

Refik-i ala''da misafir eder, Peygamber

Hak’a bağlanmışsın; 

Başın dik, yüce dağlardan yüce

Sana yarın, sonsuz aydınlık

Zalime ebedi karanlık gece...

Onlar için bir hiçtir; 

Kahpe dünyanın güzellikleri

 Hürriyet isterler; 

 Vatandan başka yok istekleri

Göğüsleri iman dolu; 

Allah’a varmak isterler böylece

 Mülk sahibine can verirler,

Ulaşırlar Rab’lerine gündüz gece

Geçit ver aşılmaz dağ; 

Gelen yabancı değil

Ey korkaklar bilin ki

Zalimin gülmesi sonsuz değil

Kanları ile yazdı destan; 

 Şeyh Şamil’in civanları

Sevgiyle yad eder tarih

Firavunları yıkan aslanları

                               27 Ocak 1990/Çığlık', 'ŞEHİT Göğsünü siper eder demir devlere, Ruhları uçar gider Rab’leri için can verenleri;  Refik-i ala''da misafir eder, Peygamber Hak’a bağlan...', ARRAY['Türk Edebiyatı','Şiir','Necati Çavdar']::text[], 8.5, '{"poet":"Necati Çavdar","poet_slug":"necati-cavdar","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sehit-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Toprak', 'toprak-necati-cavdar-b6flu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kucaklar, temizler, verir, uğruna ölünür

Mütevazi, sakin, sabırlı, kükreyince devinir', 'Kucaklar, temizler, verir, uğruna ölünür Mütevazi, sakin, sabırlı, kükreyince devinir...', ARRAY['Türk Edebiyatı','Şiir','Necati Çavdar']::text[], 8.5, '{"poet":"Necati Çavdar","poet_slug":"necati-cavdar","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/toprak-57-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oğul! ...', 'ogul-necati-cavdar-1idxh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Oğul! 

Ey oğul! 

Dünyada  eğer rahat  istersen,

Elini köze sokma

Maşa ara, kendine iyi bir ayı, bul

Kaliteli adam önemli değil,

Kullanacağın, iri dayı bul...

İster az, istersen bol ver

Kimden alırsan al, ama ver

Kesme, azda olsa hep “yal” ver

Çok ye,  çok yedir,

Damağında  lezzeti kalacak   bal ver

Ez, ezdir yeter ki iri dayı bul

Zulmet, süründür keyfini  çıkar..

Kirin olsun, kinin olsun

Kalbin ne kirli olsa, halk içinde temiz görün

Yap, yaptır ama  hep “ ak kaşık” kal

Kuralını bul,  kuralına  uydur

Uymazsa, kural koydur 

Hep üste kal..

Çatışmak, ilim, uzmanlık önemli eğil

İleri gitme, vasat kal

Her şeyde ileri olmak kolay

İlacı biraz yag, biraz yal

Çoğunluğu titret, tanıma ez ve gez

Bir kaç dayı bul, kim önde gider onu sez

Elinde bal oldukça

Tavlanmayacak ayı mı var? 

Biraz şamata, biraz cümbüş ve de saz

Marifet sana kalmış, önüne  samanda gerek biraz

Kılıfına uydur al ve çal yeter ki; çek yaz

Kabul  etmeyene istersen  mezar kaz

Tavuğu esirgeme, yolunacaksa kaz..

İsterse yalandan olsun

Yeter ki cebin dolsun

İyi söyle, güzel giyin, fiyakalı gez

Parti  pıtırtı önemli değil  adam bul

Kim oy verir? Önemli değil, yeme gelir her “kul”

Yedek akçe ayır, yemlemek için

  Hep yayında bulunsun üç beş pul

Herkese Verme, ucunu göster

Ayı yavruları sana pervane olup yalamak ister

Küpün dolana kadar “ayı” ile irtibatı kesme, sebat göster

Küpün dolunca kes ipini, kapıyı göster.

Daha iri “ayı” yola çıkar, biraz itina göster

Elin altında etkili hukukçun olsun, doktorun olsun

Rapor yazanların bulunsun, karar vericilerin olsun

Olmaz olmaz deme, lazım olmasa bile yakınında bulunsun

Fakirlere yüz verme, sadaka ver

Zengin muhitlerde  barakada olsa,  edin yer

Yanında yağcıların olsun, hocaların bulunsun

Bunlar  kirlerini temizler, aklında olsun

Mabetlerde gözyaşı dökmesen de Hak’ka

İyi görünmek için halka

Arada  bir ünlü hacılara, hocalara uğra

Gidemezsen - mühim kişilerle - selam yolla 

Hakikisine çatma, sahtelerini iyi kolla

Modaya uy, gerekli yere uygun rozet  tak

Kimi  zaman kelle, duruma göre ampüle bak

Güce eriş, karşındakilerin çırasını yak

Söndür hayatlarını, keyfine bak

Ey oğul,

Eğer huzur bulmak istersen.. 

Eşek gibi  tepme

Üstüne altın sırmalı palanda sersen

Eşeklikten fayda yok

Sen insan ol, insan öl

Gözü dönmüş köpek gibi saldırma

Yamyamlar; leş yesin, sen  aldırma

Verilene şükret, olanın sefasını sür,  keyfet

Unutma hesabı, mizanı aklet

Mayasızlardan olma,

Beşiğinde  söylenen sözlere dikkat et.

Resululhahın yüzüne nasıl bakacaksın

Ölçünü mizanını ona göre ayarla, sabret..

Kötü kalpliler, kem gözlüler hor görse de seni

Hak yoldan ayrılma. Sözün, özün Hak’ka yönelik olsun

Yiyen yesin, çalan çalsın uyma onlara

Bu gün değil ise yarın hesap sorulur ayıya dayı diyen  kullara

                                                            Aşiyan 2005', 'Oğul!  Ey oğul!  Dünyada  eğer rahat  istersen, Elini köze sokma Maşa ara, kendine iyi bir ayı, bul Kaliteli adam önemli değil, Kullanacağın...', ARRAY['Türk Edebiyatı','Şiir','Necati Çavdar']::text[], 8.5, '{"poet":"Necati Çavdar","poet_slug":"necati-cavdar","theme":"Türk Şiiri","is_hero":false,"total_lines":80,"source_url":"https://www.antoloji.com/ogul-45-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'El Etmiş', 'el-etmis-necati-cavdar-n41gs', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'KADİM DOSTUM EL ETMİŞ

                                                                Musa Keskin kardeşime 

Kadim dostum, düşünüp “gel” demiş bize 

Özlediğini söyleyip “el” etmiş bize 

Duygularımı anlatmakta acizim size 

“Musa” gibi ezelden ebede dost geldi bize

Geçmişi anıp, bu günlere gelmiş

Meğer iki kelamın hatırı varmış

Unutup gitmemmiş, hem kadir bilmiş

Kadim dosttan acele  “gel “dendi bize

 Düdük çalıp, haramiler taş koydu yola 

Belki de aynı  mesken, olacaktı yuva

Mezarlıkta karşılaştırdı,  rızk davasına 

Yine kavuştuk; yıllar uzun, ömür kısa

Takdir..Yücelik sanmayın bakidir  size

Sahtelik sizin olsun, şeref kalsın bize

Çok para, makam, derman değildir dize

Saltanat dediğin yaz değilse biter güze

Çok ulaşılmaza ulaşıp, gördü, O

“Yüce” bilinen “alçak”ları bildi, O

 Bir dönem; tarihi kayda aldı, O

Mekan  ne büyük olsa alçalır bize

Hiç gerekçesiz sevdik bizde  onu

Davasında Keskin, zikzaksız yolu 

Memleketten   müsemma gül huyu

Benzetme değil, Türk oğlu, tertemiz soylu 

Yine elektronlar buluşturuyor ikimizi

Muhabbeti her zaman mest eder sizi 

Çizgisi; iyi.. Yolu; doğru.. Yok  eğrisi

Yüksek seciyesi gerçekten dost etti bizi

İsmine uygun Musa gönüllü,  sohbeti hoş

Yalan dünya  neye değer, sonu boş

Dosttan gel oldumu koş ama hemen koş

Dostun kelamı değil, sade çayı  eder sarhoş

ORDAYIM 

Dosttan ayrılık zor imiş meğer

Arayan soran var imiş meğer

Dostun sohbeti dermanmış meğer

Hazırla demi, kıvama gelince ordayım

Kalp gözü açıksa  hacet  kalır mı söze

Gönülden olunca sevgi ulaşır bize 

Yalan dolan  giremez çağlayan öze

 Bahar geçti, sonbahar  uzak, yaz başı ordayım

Irak  sayma, hep yayındayım 

Hak var iken sanma  zordayım

Kalabalık  içinde; yalnız, dardayım 

Az kaldı geliyorum bil ki yoldayım

Gönülden çıkmazsa ayrılık; yakar, çırağı 

Can evinden vurur dostun selamı

İçmeyiz ama sarhoş eder dostun kelamı

Sen kahveyi söyle  telve zamanı ordayım.

                           19 Haziran  2005

                                    Saat 19 

                           Türk Ocağı- Aşiyan- Ankara', 'KADİM DOSTUM EL ETMİŞ                                                                 Musa Keskin kardeşime  Kadim dostum, düşünüp “gel” dem...', ARRAY['Türk Edebiyatı','Şiir','Necati Çavdar']::text[], 8.5, '{"poet":"Necati Çavdar","poet_slug":"necati-cavdar","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/el-etmis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Ana hele baksana *', 'ana-hele-baksana-zernisan-aydogan-50ul2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Taş üstünde oturdum

Ben bir kıza tutuldum

Geldi geçti yanımdan

Can evimden vuruldum

Oy oy

Ana hele baksana

Onu bana alsana

Onu bana almazsan

Birdaha demem ana

Oy oy

Boyu uzun dal gibi

Beli ince yay gibi

Kaşları keman gibi

Derdime derman gibi

Oy oy

Ana hele baksana

Onu bana alsana

Onu bana almazsan

Birdaha demem ana

Oy oy

Gözleri boncuk mavi

Taze doğmuş ay gibi

Alamazsam o yari

Gezerim mecnun gibi

Oy oy 

Ana hele baksana

Onu bana alsana

Onu bana almazsan

Birdaha demem ana

Oy  oy

         

              15.03.2006

                 Erzurum  / zernişan Aydoğan', 'Taş üstünde oturdum Ben bir kıza tutuldum Geldi geçti yanımdan Can evimden vuruldum Oy oy Ana hele baksana Onu bana alsana Onu bana almazsan...', ARRAY['Türk Edebiyatı','Şiir','Zernişan Aydoğan']::text[], 8.5, '{"poet":"Zernişan Aydoğan","poet_slug":"zernisan-aydogan","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/ana-hele-baksana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen de Çıkıp Gel Artık', 'sen-de-cikip-gel-artik-huseyin-erdogan-cb6ss', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çamlıca ne de muhteşemsin sen

farkın fark edilir eteklerinden çıkarken

sana hayran kalır seni gezip gören

bir daha çıkaramaz seni beyninden

Pendik Marmara''nın kıyısında

bir başka bambaşka güzelsin sen

gün batımlarında gece yarılarında

seyredince Gözdağı Tepesi''nden

hiç kimse gözlerini ayıramaz senden

haydi uzat ellerini bana Sabiha Gökçen

inan ki insan hayran kalıyor sana

baktıkça bakmak istiyor gök yüzünden

İstanbul ne de şanslı bir şehirsin sen

bekle bir gün benim şiirim gelecek sana

trafik duracak o sokaklarına çıktığı anda

gezeceğiz sevdiğimle el ele Boğaz''ında

güzelliğin pekiştikçe pekişecek onunla

sevdamız kazınacak attığımız her adımda

ey sevgilim gözlerim kalmasın yollarında

ne olursun sen de çıkıp gel artık Allah aşkına

sakın erteleyip durma beni çevirme şaşkına

ya da sen gel de bana atlayıp geleyim uçağa

yeter ki ölmeden sarılalım birbirimize bu dünyada

sevgili şiirim razıyım sadece havaalanında olsa da

                                                              17.03.2006

                                                           Hüseyin Erdoğan', 'Çamlıca ne de muhteşemsin sen farkın fark edilir eteklerinden çıkarken sana hayran kalır seni gezip gören bir daha çıkaramaz seni beyninden ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sen-de-cikip-gel-artik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Kere', 'bir-kere-ufuk-coban-l9erz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İnsan kaç kere sever küçük yürekleri,

Söz geçer mi zamanın büyüklüğüne? 

Elinde var mı birşey bakamazsın,

Birşeysizlik korku salar benliğine.

Yağmur dindi mi hiç bahar günlerinde,

Güneş ısıttı mı yüreğini kimsesizliklerde? 

Yalnızlığın soğuğunda tek başına,

Kalmak mutlu etti mi seni kışın ortasında? 

Son kere dedin hep kendine inanmadan,

Son bitmiyor ki gözlerini kapatmadan.

Körpecik bir yürek besledin umutla,

Senden önce büyümedi ürkek kaçışlarda.

Zaman sudan beter engel de koysan durmaz,

Sende kalan parçası varsa acıdan durmaz.

Hayat küçük bir masal kimine uğrar kimine uğramaz,

Bir kere kırılmaya gönül, parçaları hiçkimsede bulunmaz.

17/03/2006 09:00', 'İnsan kaç kere sever küçük yürekleri, Söz geçer mi zamanın büyüklüğüne?  Elinde var mı birşey bakamazsın, Birşeysizlik korku salar benliğine...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Çoban']::text[], 8.5, '{"poet":"Ufuk Çoban","poet_slug":"ufuk-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bir-kere-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerinle Yıktın Beni', 'gozlerinle-yiktin-beni-yusuf-onder-bahceci-ojgg3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen benim için, benim için erişilmezmisin,

Sen benim için engin, engin denizlermisin,

Gözlerinle yıktın beni be sen depremmisin,

Sen benim için, benim için erişilmezmisin....', 'Sen benim için, benim için erişilmezmisin, Sen benim için engin, engin denizlermisin, Gözlerinle yıktın beni be sen depremmisin, Sen benim i...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gozlerinle-yiktin-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-can-tas-y6e7b', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aşkın güneşisin,sevdamın ateşi

Ne gündüz yeter ne gece

Sen Çözümü Olmayan Bilmece

Sen yıldızlar kadar uzak

Aksi kadar yakınsın

Onlar kadar uzak

Aksi kadar Yalansın.', 'Aşkın güneşisin,sevdamın ateşi Ne gündüz yeter ne gece Sen Çözümü Olmayan Bilmece Sen yıldızlar kadar uzak Aksi kadar yakınsın Onlar kadar u...', ARRAY['Türk Edebiyatı','Şiir','Can Taş']::text[], 8.5, '{"poet":"Can Taş","poet_slug":"can-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sen-787-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gençlere Öğütler', 'genclere-ogutler-i-brahim-pataz-h0dey', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Öğüt veriyorum, bizim gençlere,                                                                        

İlim tarlasında, iziniz olsun.

Karşı koymak için gaddar güçlere,

İmanla örülmüş, özünüz olsun.

   Gece gündüz, umut dolu çalışın.

   Acınızı, sevginizi bölüşün.

   Teknik ile yaşamaya alışın.

   Ellerden ileri, hızınız olsun.

Her zaman olunuz,  bir kalp,  bir kafa,

Ölçüsüz davranıp sığınman affa,

Kimse kulak vermez  değersiz lafa,

Yerinde, etkili sözünüz olsun.

   Birlikte kovalım, gel cehaleti,

   Yaşamadan yoksulluğu illeti,

   Bilgi ile doyuralım milleti,

   Sizin de bu aşta, tuzunuz olsun.

Her gelen gün, kendinizle yarışın.

Amaçlanan hedeflere erişin.

Güçlü olmak, teminatı barışın.

İlim kullanılır kozunuz olsun.

   Artırarak okuyanı yazanı,

   Üretirsin, uçağını füzeni.

   Adalet ararken “Dünya Düzeni”,

   Haklıyı savunur,  teziniz olsun.

Beşere yön veren insan aklıdır.

Adem oğlu akıl ile yüklüdür.

Zerrecikte, koca alem saklıdır.

Arayıp görecek gözünüz olsun.

   ELEMİ der, boş geçirme ömürü,

   Böyle değil midir Hak’kın emiri? 

   Çiğneyin nefisi atın kibiri,

    ALLAH’ a varacak yüzünüz olsun.

  İbrahim PATAZ

         24/12/1994 ADANA', 'Öğüt veriyorum, bizim gençlere,                                                                         İlim tarlasında, iziniz olsun. Karşı...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Pataz']::text[], 8.5, '{"poet":"İbrahim Pataz","poet_slug":"i-brahim-pataz","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/genclere-ogutler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece', 'gece-can-tas-36qem', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kör karanlığında gecenin

Yürürken ıslak adımlarla

Girdabındayım bir düşüncenin

Dertleşirken kaldırımlarla

Bu gece hava soğuk,ayaz mı ayaz

Ellerim cepte,soğuk ise yanaklarımda

Yokluğun şimdi içimde avaz avaz

Sensizlik türküsü dudaklarımda', 'Kör karanlığında gecenin Yürürken ıslak adımlarla Girdabındayım bir düşüncenin Dertleşirken kaldırımlarla Bu gece hava soğuk,ayaz mı ayaz El...', ARRAY['Türk Edebiyatı','Şiir','Can Taş']::text[], 8.5, '{"poet":"Can Taş","poet_slug":"can-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gece-220-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizliğe Alıştım...', 'sensizlige-alistim-hasan-i-yigun-thb93', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni sensizlikte buldum...

İlk günler olamaz, yaşayamam sanıyordum

Ama derler ya, zaman en iyi ilaçtır

Yaşayıp gidiyorum işte

Dönmesen de olur artık

Sensizlik nedir bilir misin bir tanem? 

Nereden bileceksin ki

Sen hiç sensiz kalmadın...

Oysa ben iyi bilirim

Her akşam kapıyı kendi anahtarımla açmanın 

Nasıl acıtan bir duygu olduğunu...

Sen bilemezsin bir tanem

Soğuk ve sensiz eve yalnız adım atmanın

Ne kadar zor olduğunu bilemezsin

Karar verdim geriye dönüp bakmamaya

Sevmesen de olur artık

Zor da olsa alıştım, bırak böyle kalsın

Beni anılarımla baş başa bırak

Sadece onlar kaldı hayalimde

Sensizliğe alıştım

Gelmesen de olur artık', 'Seni sensizlikte buldum... İlk günler olamaz, yaşayamam sanıyordum Ama derler ya, zaman en iyi ilaçtır Yaşayıp gidiyorum işte Dönmesen de ol...', ARRAY['Türk Edebiyatı','Şiir','Hasan İyigün']::text[], 8.5, '{"poet":"Hasan İyigün","poet_slug":"hasan-i-yigun","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sensizlige-alistim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelincik Tarlasındaki Cinayet', 'gelincik-tarlasindaki-cinayet-omer-resad-k594d', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gelincik tarlasında buldular

Kalbinin her iki yanında iki büyük yarayla

Etrafta hiç kan yoktu.

Garipti öldüğü yer, garipti yarası,

Gördükleri ve görecekleri gibi.

Papatyalar arasında sereserpe yatardı.

Her bahar, bu zamanlarda.

Bu tarladan ne zengin olunurdu

Ne de böyle çiçeksiz kalınırdı.

Her sene papatyalar açardı,

Beyaz beyaz taç yapraklı,

Kocaman kocaman...

Yatardı onların arasına, umut ettikleriyle

Olmayacaklarla...

Bu sene gelincikler bitirvermişti

Anlam verememişti, anlamamıştı

Diğerlerinin umrunda bile değildi.

İşte o tarlada ölü buldular onu.

Kalbinin her iki yanında iki büyük yarayla.

Etrafta hiç kan yoktu.

Kana gelen böcek veya akbaba da...

Öyle sereserpe yatıyordu yaralarıyla.

Her zamanki ifade vardı suratında,

Hep umut ettikleri elinde,

Papatyaların arasına uzanmış gibi...

Sanki hiç ölmemiş, hiç yaşamamış gibi.

Gelincik tarlasında hiç kan akıtmadan öldürmüşlerdi,

Kendi de anlam verememişti, anlamamıştı.

Diğerlerinin umrundaydı şimdi

Gelincikler solunca 

Papatyalar açacak bir tarla vardı ortada.', 'Gelincik tarlasında buldular Kalbinin her iki yanında iki büyük yarayla Etrafta hiç kan yoktu. Garipti öldüğü yer, garipti yarası, Gördükler...', ARRAY['Türk Edebiyatı','Şiir','Ömer Reşad']::text[], 8.5, '{"poet":"Ömer Reşad","poet_slug":"omer-resad","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/gelincik-tarlasindaki-cinayet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninle Çıkalım Dağlara', 'seninle-cikalim-daglara-yusuf-onder-bahceci-fzp85', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gel seninle, şöyle çıkalım dağlara,

Ben gerçekleri söyleyim sen ağla,

Nemli gözlerle bak gözlere, dağla,

Gel seninle, şöyle çıkalım dağlara.

Hiç kimse olmasa, sessizlik olsa,

Güzel gözlere baksam neler olsa,

Yine sevdim diyemem bu nasılsa, 

Gel seninle, şöyle çıkalım dağlara.

Gel, dağların en yücesine çıkalım,

Yaşananlara, yücelerden bakalım,

Başımıza sarmaşık taçları takalım,

Gel, dağların en yücesine, çıkalım.

Bazı, bazı dağlar vardır erişilmez,

Zirvesinde, boranla tipi eksilmez,

Sevip ayrılmışsan, dilin söylemez,

Gel, dağların en yücesine, çıkalım.', 'Gel seninle, şöyle çıkalım dağlara, Ben gerçekleri söyleyim sen ağla, Nemli gözlerle bak gözlere, dağla, Gel seninle, şöyle çıkalım dağlara....', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/seninle-cikalim-daglara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bil Bakalım Hangi Oyun Bu Oyun?', 'bil-bakalim-hangi-oyun-bu-oyun-omer-resad-c6yoz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Önündeki karanlık aydınlandığında,

Torpakları binlerce asır önce çatlamış,

Bitkilerin ruhlarının  bile kaybolduğu,

Yakıcı rüzgarların yanağını ısırdığı,

Susadığın, nefes alamadığın bir çölde olsan.

Sonra kararsa her yer,

İki el çevirse seni olduğun yerde ve aydınlansa gene her yer.

Bir çimenlikte olsan şimdi bir kampüs bahçesi mesela.

Çimenler öğrenciler oturup ezmesin diye yeni sulanmış,

Ama gene de oturulmuş, nemli.

Dün geceden hüzünlü, ışıkları altındaki cam kırıklarıyla.

Çok eskilerden çok hüzünlü mü geldi, bekleme! 

Karart aydınlığını bu sefer kendin, dön etrafında.

Aç gözlerini.

Kumral bir sahil kenarında yeşil tertemiz bir denizin,

Sahile rengini veren kumlara kaleler yap.

Kaleleri boz yerine masal kentleri yap, ama bozma onları.

Yeşil denize dal, dalabildiğin kadar.

Dal ama kum çıkarma. 

Sahilinde insanlar cıvıldaşsın,

Kalabalıklar ve diğer balıklar denizde oynaşsın,

Gözlerine huzur uykusu girsin, kendi hikayeni yaşa...

Ama istemezsin belki 

O zaman...

-----

Dur ne olur kalmak isterim artık burada.

Bu kumral sahil ve yeşil deniz kenarında.

Sıkıldım artık körebe oynamaktan.

Ne karartmak isterim gözlerimi ne de dönmek.

Bu kumral adaya kar yağana kadar,

Bu yeşil deniz donana kadar kalmak isterim burada.

Belki o zaman karartır gözlerimi dönerim 

Ama bu sefer olamam körebe çünkü...', 'Önündeki karanlık aydınlandığında, Torpakları binlerce asır önce çatlamış, Bitkilerin ruhlarının  bile kaybolduğu, Yakıcı rüzgarların yanağı...', ARRAY['Türk Edebiyatı','Şiir','Ömer Reşad']::text[], 8.5, '{"poet":"Ömer Reşad","poet_slug":"omer-resad","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/bil-bakalim-hangi-oyun-bu-oyun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakar Öpüşlerin', 'yakar-opuslerin-hatice-bediroglu-o1zd5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gezinirken ellerin 

Ruhumun çıplaklığında 

Denizin kokusu 

Doluşur burnuma

Sarhoş olurum 

Upuzun olsun isterim 

Kucaklayışların

Özlemine 

Akar yüreğim

Kıvılcımlı gülücükler 

Gözlerinde 

Yetersiz kaldığı an 

Tüüm tariflerin 

Ağustos güneşi gibi 

Yakar öpüşlerin

Düş Kuruyor Gece '' adlı kitabımdan - Ocak 2008 -

www.haticebediroglu.net', 'Gezinirken ellerin  Ruhumun çıplaklığında  Denizin kokusu  Doluşur burnuma Sarhoş olurum  Upuzun olsun isterim  Kucaklayışların Özlemine  Ak...', ARRAY['Türk Edebiyatı','Şiir','Hatice Bediroğlu']::text[], 8.5, '{"poet":"Hatice Bediroğlu","poet_slug":"hatice-bediroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yakar-opuslerin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuru Mehmet Amca', 'kuru-mehmet-amca-omer-resad-hbshp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hiç haram yemedi

Gözleri hiç kötü bakmadı

Ne sana ne bana

Ne de bir isme...

Çoçukken çocuk gibiydi

Gel dedilerse geldi 

Git dedilerse üzüldüğünü belli etmedi.

Gizli gizli oynadı

Oynamalıklarından utandı gizledi

Gençken adam gibiydi

Kıt kanaate çalıştı

Yedi, içti

Gizli gizli eğlendi

Güldüğünden utandı gizledi

Üzüntüsünü abarttı

Şimdi ihtiyarlığında çocuk gibi

Adamdan başka olmayı bildiği

Tek şey gibi.

Elleri nasırlı, yüzü buruş buruş

Pantalonu çengel iğneli

Altında iki kat pijama

Üstünde ceket

Altında iki kat pijama 

Bıyıklarının ortası sarı

Kenarları ak 

Tütün kokuyor her yeri.

Hiç var mıydı aramızda

Gören oldu mu onu hiç,

Orada burada

Pazarda peynir satarken

Eşeğiyle odun taşırken

Yol kenarında tarlayı beklerken

Yoldan geçen sürünün gerisinde

O zaman var mıydı

Yoksa özlediği sona

Çoktan varmış mıydı? 

O nerde şimdi?', 'Hiç haram yemedi Gözleri hiç kötü bakmadı Ne sana ne bana Ne de bir isme... Çoçukken çocuk gibiydi Gel dedilerse geldi  Git dedilerse üzüldü...', ARRAY['Türk Edebiyatı','Şiir','Ömer Reşad']::text[], 8.5, '{"poet":"Ömer Reşad","poet_slug":"omer-resad","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/kuru-mehmet-amca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şehirde Yokum', 'sehirde-yokum-omer-resad-4hekw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ilık yaz rüzgarında

Hatta bir sahil kenarında

Alımlı ama kıvrak  bir kızın 

oradan oraya savrulan sarı saçları gibi 

sonbahar rüzgaları önündeki yapraklar...

Sarayburnu’nda bir taşın üzerinde

Gözleri nemli, kırpışarak bakan

Hüzünlü bir genç kızın gözleri gibi

Sonbaharda köpüklü koyu yeşil sular.

***

ve arada gözlerinden süzülen 

tek tük yaşlar gibi

bulutlar altında renkleri donuk vapurlar

***

Oradan oraya savrulan sarı saçlarına

Doluyorum ellerimi, yumuşak okşuyor tenini

Nemli, önüne bakan gözlerine 

Bakıyorum, hüznü yansıyor gözlerime.

Sonbaharda bir garibim

Şefkat umuyorum şehirden.', 'Ilık yaz rüzgarında Hatta bir sahil kenarında Alımlı ama kıvrak  bir kızın  oradan oraya savrulan sarı saçları gibi  sonbahar rüzgaları önün...', ARRAY['Türk Edebiyatı','Şiir','Ömer Reşad']::text[], 8.5, '{"poet":"Ömer Reşad","poet_slug":"omer-resad","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sehirde-yokum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şehirsiz', 'sehirsiz-omer-resad-c1a8z', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Birgün seninle burada karşılaşırsak

Sisler dağılacak

Vagonların altından geçtiği bu demirler

Yokolacak.

Yokuşun başında karşıma çıkarsan

Korkusu hep içimde

Yokuşun ortasındaki izlencede orta bir masada

Kelimeciklerle seni bir arada

Görürsem eğer

Tahtalı masalı masal yokolacak

Çatılarda keşfetmek dipsiz caddeyi

Elindeki mum şehri aydınlatırken

Bir şeyden ümit başka pencereden seyretmek

Belki görürüm diye bizi

Korkusu hep içimde

Bir gün seni görürsem

Yokolacağız biz

Buralar eskisi gibi olmayacak

Keşfinde hayallerim de...', 'Birgün seninle burada karşılaşırsak Sisler dağılacak Vagonların altından geçtiği bu demirler Yokolacak. Yokuşun başında karşıma çıkarsan Kor...', ARRAY['Türk Edebiyatı','Şiir','Ömer Reşad']::text[], 8.5, '{"poet":"Ömer Reşad","poet_slug":"omer-resad","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sehirsiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Yaşamak Gibi Olsa', 'hayat-yasamak-gibi-olsa-omer-resad-438dv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tramvaylar dursa, kapıları açılsa,

Kalabalıklar halka karışsa

Halaylar meydanlarda halkla buluşsa

Gökyüzünden çiçekler yağsa

Hüzünleri, kahkalar oyunlar bozsa

Çocukların ellerine rengarenk boyalar bulaşsa

Ağızlarında şen şarkılar olsa,

Mendiller yağ satarım bal satarımda kullanılsa,

Bankalar çocukluk kredisi verse,

Çocuklar çocuk gibi olsa

Taksi dolmuşa, dolmuş otobüse

Otobüs yolcuya günaydın demek için

Camdan kolunu çıkarsa, bağırsa.

Kornalar düğünler için çalsa,

Hastalar, uyuyan çocuklar camlardan kahkalar atsa.

Bir gül kokusu sarayburnundan girse 

Taaa kavağa kadar her mahalleye uğrasa,

Insanlar hep gülse

Gülmek için hiç bitmeyecek nedenleri olsa

Hayat yaşamak gibi olsa…', 'Tramvaylar dursa, kapıları açılsa, Kalabalıklar halka karışsa Halaylar meydanlarda halkla buluşsa Gökyüzünden çiçekler yağsa Hüzünleri, kahk...', ARRAY['Türk Edebiyatı','Şiir','Ömer Reşad']::text[], 8.5, '{"poet":"Ömer Reşad","poet_slug":"omer-resad","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hayat-yasamak-gibi-olsa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Candan Nasılsın?', 'candan-nasilsin-belgin-turan-0qoau', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni gördüğüme değil, görmeseydim ah ederdim,

Bu nezaket, bu güzelliğe daima hasret çekerdim,

Eskilerden kalma doğal, sana özgü  zarafetin,

Aldı beni benden  götürdü canım bu asalettin,

Hayran kaldı gönlüm büyüledi kalbi, ruhuyetin,

Herkes der nasılsın? 

Kimi kafana vurur  gibi,

Kimi lakırdı olsun diye,

Kimi mecburiyetten,

Senin nasılsın deyişin? 

Ruhumun en nazik tellerini okşar gibi,

Uçar gönlüm der:-Bu ne incelik yar,

Neleri anlatır bir ben bilirim...

Önceleri tanımadığıma hasrettim,

Şimdi varsın, varlığına hasretim,

Razıyım buna canım efendim,

Yokluğunu değil varlığını yeğlerim,

Hasretindir inan benim tek kudrettim.

Belgin Turan              15.03.2006', 'Seni gördüğüme değil, görmeseydim ah ederdim, Bu nezaket, bu güzelliğe daima hasret çekerdim, Eskilerden kalma doğal, sana özgü  zarafetin, ...', ARRAY['Türk Edebiyatı','Şiir','Belgin Turan']::text[], 8.5, '{"poet":"Belgin Turan","poet_slug":"belgin-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/candan-nasilsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Kimse Sevemez', 'seni-kimse-sevemez-yusuf-onder-bahceci-tajp7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni benden fazla kimse sevemez, sevemez,

Annen bile olsa sana böyle mısralar dizemez,

Seni öyle severim ki, Hak''tan başkası bilmez,

Seni benden fazla kimse sevemez, sevemez,', 'Seni benden fazla kimse sevemez, sevemez, Annen bile olsa sana böyle mısralar dizemez, Seni öyle severim ki, Hak''tan başkası bilmez, Seni be...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/seni-kimse-sevemez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haramiler', 'haramiler-zeynal-yaman-950ng', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ağıt yaktım ''caz'' dediler

Kemer sıktım ''naz'' dediler

''Bütün bunlar az'' dediler

Haramiler haramiler

Elim verdim ''kol'' dediler

Soygun dedim ''yol'' dediler

Yok''u yedim ''bol'' dediler

Haramiler haramiler

Suyum verdim ''kan'' dediler

''Kuru ekmek ban'' dediler

''Her gün bizi an'' dediler

Haramiler haramiler

Gece dedim ''tan'' dediler

''İçin için yan'' dediler

''Soymak bize şan'' dediler

Haramiler haramiler

Hakkım dedim ''yok'' dediler

''Al sinene ok'' dediler

''Şifa veren şok'' dediler

Haramiler haramiler

Kanım durdu ''don'' dediler

İniltime ''fon'' dediler

''Susar isen on'' dediler

Haramiler haramiler

1990,Çatalca', 'Ağıt yaktım ''caz'' dediler Kemer sıktım ''naz'' dediler ''Bütün bunlar az'' dediler Haramiler haramiler Elim verdim ''kol'' dediler Soygun dedim ''y...', ARRAY['Türk Edebiyatı','Şiir','Zeynal Yaman']::text[], 8.5, '{"poet":"Zeynal Yaman","poet_slug":"zeynal-yaman","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/haramiler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eller''im (!) Hayın', 'eller-im-hayin-lokman-hamitoglu-78oby', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ELLER ‘İM (!)  HAYIN

Vurulmuşum sırtımdan

Param parça olmuş postum

Güvendiklerimce (!)  kurulmuş pusum

Boynum kıldan ince değil

Kılıçtan keskinim

Amma... 

Amma ellerim zincir

Eller ‘im hayın

Anlatamam nasıl zordayım

Sevinçlerim öyle firar ki

Öyle bitkinim ki 

Sakın bana derinden bakma

Ölebilirim! ... 

   Lokman HAMİTOĞLU', 'ELLER ‘İM (!)  HAYIN Vurulmuşum sırtımdan Param parça olmuş postum Güvendiklerimce (!)  kurulmuş pusum Boynum kıldan ince değil Kılıçtan kes...', ARRAY['Türk Edebiyatı','Şiir','Lokman Hamitoğlu']::text[], 8.5, '{"poet":"Lokman Hamitoğlu","poet_slug":"lokman-hamitoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/eller-im-hayin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülü Kopardılar', 'gulu-kopardilar-yusuf-onder-bahceci-g3v1s', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Vazoda daha güzel görünür dediler, Gülü kopardılar,

Sade Gülümü kopardılar, seven yüreği söküp aldılar,

Bu Allah''tan korkmazlar, güle, bülbüle hiç acımadılar,

Vazoda daha güzel görünür dediler, Gülü kopardılar...', 'Vazoda daha güzel görünür dediler, Gülü kopardılar, Sade Gülümü kopardılar, seven yüreği söküp aldılar, Bu Allah''tan korkmazlar, güle, bülbü...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gulu-kopardilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hissediyorum', 'hissediyorum-umit-tuna-5ldi1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hissediyorum bu gece,

Geleceksin.

Hissediyorum bu gece,

Beni yeniden seveceksin.

Hissediyorum

Benim olmak isteyeceksin,

Seni seviyorum diyeceksin,

Beni doya doya öpeceksin.

Koynumda uyumak isteyeceksin,

Hiç yanımdan gitmeyeceksin,

Ebediyen süreceksin,

Hissediyorum çok mutlu olacaksın.

Benimleyken dünyanın tadına varacaksın,

Ayrılmak yok diye haykıracaksın,

Bak ne güzel hissediyorum,

Hayaller gerçek olsun istiyorum! ...

ÇILGIN MUHASEBECİ', 'Hissediyorum bu gece, Geleceksin. Hissediyorum bu gece, Beni yeniden seveceksin. Hissediyorum Benim olmak isteyeceksin, Seni seviyorum diyec...', ARRAY['Türk Edebiyatı','Şiir','Ümit Tuna']::text[], 8.5, '{"poet":"Ümit Tuna","poet_slug":"umit-tuna","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hissediyorum-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canan Sende gel', 'canan-sende-gel-mustafa-karamelek-wwpgg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'CANAN SENDE GEL      

Bir bahar daha geldi

Bereketi efil efil

Yağmuru  çisil çisil

Çiğdem çiçek lale sümbül

Mor menekşe sende gel.

Karıncalar arılar yaşam çabasında

Bir güne bir ömür sığdırır kelebek

Meleşir kırlarda kuzular

Saldırır ana memesine 

Sevdası kuzusuna ananın

Öylesi bir sevda sende gel.

Meşk içinde muhabbet

Beni gözlerine hapset

Tut ellerimi bırakma

Gölgesiz zamanlara gidelim

Gönül payıma sevda düşsün

Hüzün hazan zaten hep içimde

Mutluluk sevinç sende gel.

Aşkına müebbet giydim

Bazen yaşayan kul idim

Ümitlerim yaşama hevesim vardı

Kurumuyor şimdi göz yaşlarım

Biraz umut biraz sevgi

Teselli mendil sende gel.

Ömrüme bir gün bahar gelsin

Benim de umutların çiçeklensin

Dallarımda kuşlar türkü söylesin

Usandım kıraç topraklara sarılmaktan

Bağıma bağban canıma can ol

Canan sende gel.

Sancılar sızılar çöreklenmiş bağrıma

Sırtım dağ göğsüm deniz olsa da

Gülmek uzak mutluluk gurbet

Gün yüzü görmez yüzüm

Kabus çökmüş gecelerime

Huzur uyku düş sende gel…

Mustafa KARAMELEK', 'CANAN SENDE GEL       Bir bahar daha geldi Bereketi efil efil Yağmuru  çisil çisil Çiğdem çiçek lale sümbül Mor menekşe sende gel. Karıncala...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Karamelek']::text[], 8.5, '{"poet":"Mustafa Karamelek","poet_slug":"mustafa-karamelek","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/canan-sende-gel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğime Yürek Verdin', 'yuregime-yurek-verdin-candan-sevinc-1xzzg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aykırı düşmedi gönlüm hiç senden yana

Dere kenarında boy veren bir çiçek gibi

Yüreğime boy verdin

Kaçmadı hiç ellerimden sevdan

Seke seke oynadığım bir oyun gibi

Önüme uzanıverdin

Senin sevdandı başımı bulutlara erdiren

Sen bir ateş ben külün oldum

Senin sevdandı gözyaşlarını silen

Sen bir hanımeli ben yaprağın oldum

Ayrı düşmedi sevgimiz hiç

Kerem gibi Ferhat gibi

Yanı başımda  filizlendin

Durmadı yüreğimin devinimli atışları

Zamanında çalan bir saat gibi

Yüreğime yürek verdin.', 'Aykırı düşmedi gönlüm hiç senden yana Dere kenarında boy veren bir çiçek gibi Yüreğime boy verdin Kaçmadı hiç ellerimden sevdan Seke seke oy...', ARRAY['Türk Edebiyatı','Şiir','Candan Sevinç']::text[], 8.5, '{"poet":"Candan Sevinç","poet_slug":"candan-sevinc","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yuregime-yurek-verdin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kabahat', 'kabahat-mehmet-can-ww2xm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Mahmurlu gözlerimden  belgesel izliyorum..

Saniyelerle hayatı

Umutlar esir olmuş olmazlara

Kimde arasam kabahatı?', 'Mahmurlu gözlerimden  belgesel izliyorum.. Saniyelerle hayatı Umutlar esir olmuş olmazlara Kimde arasam kabahatı?...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Can']::text[], 8.5, '{"poet":"Mehmet Can","poet_slug":"mehmet-can","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kabahat-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Giderim', 'giderim-temel-kilincarslan-85eb8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Varsın gözlerini görmesin gözüm

Varsın,saçlarına değmesin elim

Olsun,bu acıyı albet çekerim

Kalbimi sırtıma vurur giderim.

Yalnız onun değil benimde suçum

Gönül savaşında bende suçluyum

Artık ayrılıktan taç yapmayalım

Tacımı başıma takar giderim.

Şimdi anlıyorum ne çok sevmişim

Zalim, sana nasıl gönül vermişim

Bu kadar zamandır ne söylemişim

Söylediklerimi alır giderim.

Senden aldığımı inkar edemem

Hiç sevmedim diye yalan diyemem

Artık bundan sonra geri dönemem

Senden ne aldıysam verir giderim.', 'Varsın gözlerini görmesin gözüm Varsın,saçlarına değmesin elim Olsun,bu acıyı albet çekerim Kalbimi sırtıma vurur giderim. Yalnız onun değil...', ARRAY['Türk Edebiyatı','Şiir','Temel Kılınçarslan']::text[], 8.5, '{"poet":"Temel Kılınçarslan","poet_slug":"temel-kilincarslan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/giderim-62-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Ne Zaman Yakınımda Hissetsem', 'seni-ne-zaman-yakinimda-hissetsem-candan-sevinc-a41xg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni ne zaman yakınımda hissetsem

Kır çiçekleri açar solgun bahçelerde

Sevinç çığlıkları yükselir otlayan kuzulardan

Bir çoban sürüsüne yenik düşer

Daha sabah olmadan

Seni ne zaman yakınımda hissetsem

Yemyeşil bir vadi uzanır boylu boyunca

Bir nilüfer boy gösterir maviler arasından

Daha güneş doğmadan

Bir yüzü tamamen sen.', 'Seni ne zaman yakınımda hissetsem Kır çiçekleri açar solgun bahçelerde Sevinç çığlıkları yükselir otlayan kuzulardan Bir çoban sürüsüne yeni...', ARRAY['Türk Edebiyatı','Şiir','Candan Sevinç']::text[], 8.5, '{"poet":"Candan Sevinç","poet_slug":"candan-sevinc","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/seni-ne-zaman-yakinimda-hissetsem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gölgeler Bastı Karanlığı', 'golgeler-basti-karanligi-candan-sevinc-b0ijf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Güneşin leylak kokulu gölgesinde

Üşüyen bir ben değilim

Parmaklarımdan çekilirken deniz

Bir damla cana hasretim

Kar beyazı gözbebeklerinden damlayan

Bir serapsa eğer

Sana uzanan vadi ben değilim

Gölgeler bastı karanlığı

Gülüşlerde saklanan ezgi ben değilim.', 'Güneşin leylak kokulu gölgesinde Üşüyen bir ben değilim Parmaklarımdan çekilirken deniz Bir damla cana hasretim Kar beyazı gözbebeklerinden ...', ARRAY['Türk Edebiyatı','Şiir','Candan Sevinç']::text[], 8.5, '{"poet":"Candan Sevinç","poet_slug":"candan-sevinc","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/golgeler-basti-karanligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlemindeyim İşte', 'ozlemindeyim-i-ste-zeliha-bicer-q8rw5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yazmalar yetmiyor, dokunmak gerek

Martılar yetmiyor, gelmen gerek

İçkiler yetmiyor, sarhoş etmelisin beni

Gün batımıyla, martı kanadıyla

Gittiğin o vapurla,dönmelisin artık

Kıyıları dövmesin dalgalar.

Cemreler de düştü havaya,suya,toprağa

Birtek sen gelmedin hala baharda

Yalnızım, kalabalığım ol

Sensizim, sıcağım ol

Sevgisiz değilim, sevginleyim

Özlemindeyim yine, yine en diplerdeyim.', 'Yazmalar yetmiyor, dokunmak gerek Martılar yetmiyor, gelmen gerek İçkiler yetmiyor, sarhoş etmelisin beni Gün batımıyla, martı kanadıyla Git...', ARRAY['Türk Edebiyatı','Şiir','Zeliha Bicer']::text[], 8.5, '{"poet":"Zeliha Bicer","poet_slug":"zeliha-bicer","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ozlemindeyim-iste-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Kadınım', 'benim-kadinim-mehmet-kesici-ftviw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Benim kadınım böyledir işte,

uysal ve sevecen..

toprak kadar fadakar,

deniz gibi doyumsuz,

yüreğinde öyle bir aşk vardır ki,

öyle bir sevgi, ölümsüz..

Benim kadınım böyledir işte,

sevgi dolu, şefkat dolu, his dolu..

elleriyle açılır onun,

ayakları altından geçer cennetin yolu..

Benim kadınım böyledir işte,

kıskanır onu bütün melekler..

bütün çiçekler soluk kalır,

onda doğar tüm mevsimler..

Benim kadınım böyledir işte,

yaradılışına, var oluşuna uygun..

Erkek oluşuma utanmalıyım, 

onu sevmeyip üzersem bir gün..

ondardır doğumum, ona ölürüm.....', 'Benim kadınım böyledir işte, uysal ve sevecen.. toprak kadar fadakar, deniz gibi doyumsuz, yüreğinde öyle bir aşk vardır ki, öyle bir sevgi,...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kesici']::text[], 8.5, '{"poet":"Mehmet Kesici","poet_slug":"mehmet-kesici","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/benim-kadinim-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul Sen, Sen İstanbul', 'i-stanbul-sen-sen-i-stanbul-sair-sozdeniz-6l3ur', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir gün geleceğim sana,

ya yağmurlu bir ilkbahar sabahında,

ya da güz yaprakları düşerken kaldırım taşlarına

gezeceğim sokaklarında 

üstümde yıldız, altımda deniz

geçeceğim karşı kıyıya

ama asla çıkmayacağım karşına

Söyleyeceğim birşeyler var belki sana

ama yok mümkün değil

söyleyemedim ki kendime bile daha.

Bilmiyorum hayallerimmisin, yoksa sen bir hayalmisin

yok yok benim için

İstanbul sen, sen İstanbul

yakınımdaki uzak şehirsin', 'Bir gün geleceğim sana, ya yağmurlu bir ilkbahar sabahında, ya da güz yaprakları düşerken kaldırım taşlarına gezeceğim sokaklarında  üstümde...', ARRAY['Türk Edebiyatı','Şiir','Şair Sözdeniz']::text[], 8.5, '{"poet":"Şair Sözdeniz","poet_slug":"sair-sozdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/istanbul-sen-sen-istanbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevildim mi Bilemedim', 'sevildim-mi-bilemedim-yusuf-onder-bahceci-wq089', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu nasıl sevda, sevdim, sevildim mi bilemedim,

Lâl oldu dillerim, seni seviyorum be diyemedim,

Şimdi iyimi oldu diyorum dersimi ezber ederim,

Bu nasıl sevda, sevdim, sevildim mi bilemedim.', 'Bu nasıl sevda, sevdim, sevildim mi bilemedim, Lâl oldu dillerim, seni seviyorum be diyemedim, Şimdi iyimi oldu diyorum dersimi ezber ederim...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sevildim-mi-bilemedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğimi Sende Rehin Bıraktım', 'yuregimi-sende-rehin-biraktim-erdal-ozkan-9ykdf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gidiyorum tükenmiş umutlarımla

Gidiyorum sevgimi sevgisizliğine mahkum ederek

Umarsız bu aşkın çaresizliğinde

Yokluklar içinde ben gidiyorum

Hiç kırgın değilim biraz buruğum

Suçlayamam seni sevmedin diye

İstemem bana acımanı

Yok olup gitsemde sevgisizliğinde

İsyanım kendime isyanım yüreğime

Nerden düştüm bilmemki böyle sevgiye

Haram bana artık senden başkası

Kendimi bu aşkın ateşiyle yaktım

İstesemde kimseyi sevemem artık

Çünkü.....

Yüreğimi sende rehin bıraktım.', 'Gidiyorum tükenmiş umutlarımla Gidiyorum sevgimi sevgisizliğine mahkum ederek Umarsız bu aşkın çaresizliğinde Yokluklar içinde ben gidiyorum...', ARRAY['Türk Edebiyatı','Şiir','Erdal Özkan']::text[], 8.5, '{"poet":"Erdal Özkan","poet_slug":"erdal-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yuregimi-sende-rehin-biraktim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kâlbi Hain Olanlar', 'k-lbi-hain-olanlar-yusuf-onder-bahceci-9pqym', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kâlbi hain olanlara, nasihat, kâr eder mi,

Çok sevdiğim yârim bana isyan eder mi,

Çok seven biriyse böyle bırakıp gider mi,

Kâlbi hain olanlara, nasihat, kâr eder mi.

Gül bahçesine girenler, hep gül kokarlar,

Sevenlerin arasına, öyle mertek sokarlar,

Bunların kâlbi hain be münafıktır yakarlar,

Kâlbi hain olanlara, nasihat, kâr eder mi.

Dikkatli bak gözlerine, haindir sözlerine,

Gafil olma sevdiğim, seni kandırırlar bre,

Yıllardır düşünürüm nasıl düşmüşüm dile,

Kâlbi hain olanlara, nasihat, kâr eder mi.', 'Kâlbi hain olanlara, nasihat, kâr eder mi, Çok sevdiğim yârim bana isyan eder mi, Çok seven biriyse böyle bırakıp gider mi, Kâlbi hain olanl...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kalbi-hain-olanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Gülüme Küstüm Artık', 'ben-gulume-kustum-artik-erdal-ozkan-2d13p', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben gülüme küstüm artık

Hiç aramaz sormaz oldu

Resminide yaktım artık

Güller gibi oda soldu

Aramıyor son günlerde

Benden uzak bu günlerde

Bilmiyorum şimdi nerde

Birdenbire o kayboldu

Hem elele hem göz göze

Herkes imrenirdi bize

Gözmü değdi sevgimize

Aşkımız niye son buldu

Teselli yok kederime

Boyun eğdim kaderime

Onu gömdüm yüreğime

Benim için artık öldü.', 'Ben gülüme küstüm artık Hiç aramaz sormaz oldu Resminide yaktım artık Güller gibi oda soldu Aramıyor son günlerde Benden uzak bu günlerde Bi...', ARRAY['Türk Edebiyatı','Şiir','Erdal Özkan']::text[], 8.5, '{"poet":"Erdal Özkan","poet_slug":"erdal-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ben-gulume-kustum-artik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönlüm Firarda', 'gonlum-firarda-erdal-ozkan-fu22p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Korkarım diyemem çok sevdiğimi

Yok derse ölürüm belki o anda

Sevgisi bırakmaz bir an peşimi

Ben ise kaçarım gönlüm firarda

Saklasam ne yazar artık sevgimi

Herkes biliyor gönül derdimi

Bir büyük suçun faili gibİ

Herkesten kaçıyor gönlüm firarda.', 'Korkarım diyemem çok sevdiğimi Yok derse ölürüm belki o anda Sevgisi bırakmaz bir an peşimi Ben ise kaçarım gönlüm firarda Saklasam ne yazar...', ARRAY['Türk Edebiyatı','Şiir','Erdal Özkan']::text[], 8.5, '{"poet":"Erdal Özkan","poet_slug":"erdal-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gonlum-firarda-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Kenarında', 'bir-kenarinda-erdal-ozkan-i4vrb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Öyle kolay silinmez bu aşkın izi

Çok yıllar yaşar hatıralarında

Küçükte olsa bir sızı kalır

Mutlaka kalbinin bir kenarında

Gözlerin gizili gizli beni gözlüyor

İnkar etsende kalbin beni özlüyor

Hayalim gizlenmiş seni izliyor

Mutlaka odanın bir kenarında

Yaşanan bir aşk var inkar edilmez

Bugün yok sanırsın yarın bilinmez

Koskoca mazidir kolay silinmez

Mutlaka izi kalır bir kenarında.', 'Öyle kolay silinmez bu aşkın izi Çok yıllar yaşar hatıralarında Küçükte olsa bir sızı kalır Mutlaka kalbinin bir kenarında Gözlerin gizili g...', ARRAY['Türk Edebiyatı','Şiir','Erdal Özkan']::text[], 8.5, '{"poet":"Erdal Özkan","poet_slug":"erdal-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-kenarinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost bildim...', 'dost-bildim-mehmet-coban-z3eaj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dostumu dost bildim düşmandan uzak.. 

Düşman bilmedim kimseyi dosttan uzak 

İnsanlar ikiye ayrıldı gözümde her zaman 

Ya dostumdur, ya da bilmediğim insan 

Bildiğimi dost bildim, düşmanca davransada 

Hatalar buldum kendimde, düşmanlıklarına

Hatam yokken devam etse de düşmanlığa

Umutla yaklaşırım insanların dostluğuna

Kavgam yok asla içimden insanlığa, insanlara

Meşru müdafaam vardır, saldırılan insanlığıma

17.03.2006 -İzmir', 'Dostumu dost bildim düşmandan uzak..  Düşman bilmedim kimseyi dosttan uzak  İnsanlar ikiye ayrıldı gözümde her zaman  Ya dostumdur, ya da bi...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çoban']::text[], 8.5, '{"poet":"Mehmet Çoban","poet_slug":"mehmet-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/dost-bildim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köpekler Gibi Saldırdılar', 'kopekler-gibi-saldirdilar-yusuf-onder-bahceci-qq7en', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Her taraftan saldırdılar sanki köpekler gibi,

Güya nasihatlar ettiler, sanki, kötekler gibi,

Anlamadınmı Gülüm sanki seni itekler gibi,

Her taraftan saldırdılar sanki köpekler gibi.

Hayatlarında hiç sevgi olmuş mu bir sorun,

Seven gönülleri, böylesine ayıran alçaklar,

Yarın Hak''kın divanında, ateş sizi kucaklar, 

Her taraftan saldırdılar sanki köpekler gibi.

Soruyorum şimdi elinize ne geçti, ne geçti,

Bu kaderin ayrılık orağı bizi yetmeden biçti,

Dilimin ucuna geldi diyemedim ayıran piçti,

Her taraftan saldırdılar sanki köpekler gibi.

Bu şiirler sizlere garip gelmesin, gelmesin,

Nerede seven varsa, hemen sevdim desin,

Kâlbi hainlere aman, aman fırsat vermesin,

Her taraftan saldırdılar sanki köpekler gibi.', 'Her taraftan saldırdılar sanki köpekler gibi, Güya nasihatlar ettiler, sanki, kötekler gibi, Anlamadınmı Gülüm sanki seni itekler gibi, Her ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kopekler-gibi-saldirdilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoşgeldi hicran', 'hosgeldi-hicran-munevver-senol-wjoaz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen burağın çok sevdiği nişanlısı.

                                 Bizimde ilk gözağrımız hemde cansın.

                                 Adın isimlerde kalsın hiç hicran yaşamıyasın.

                                 Sen dalında gonca gülsün.

                                 Cankızım benim iyiki varsın.', 'Sen burağın çok sevdiği nişanlısı.                                  Bizimde ilk gözağrımız hemde cansın.                                  Ad...', ARRAY['Türk Edebiyatı','Şiir','Münevver Şenol']::text[], 8.5, '{"poet":"Münevver Şenol","poet_slug":"munevver-senol","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/hosgeldi-hicran-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sorunsuz, sorgusuz', 'sorunsuz-sorgusuz-riza-aslan-8q265', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sorunsuz , sorgusuz başlangıçlar zamanıdır şimdi

ne bir plan olmalı geçmişe dair

ne de bir düzen

ne bir yol 

ne de bir iz

kayıp şehirler bulunmalı

geçmişinden kaçan

yolculuklar yapılmalı

kayıp şehirler arası

virane sokaklardaki

o ruhsuz sessizlik

korkutmamalı

hayalinde dahi ne bir imge

ne de ona ait bir yansıma olmalı

iz bırakmamalı

geçmişinin sana ulaş(a) maması için 

hayal kurulmamalı

geleceğin buğulu camından

geçmişle ilgili

ama sadece gitmeli

ne bir yol olmalı

gidilecek

ne de bir iz 

ardın sıra seni takip ettirecek

12 Mart 2006 

Mersin', 'sorunsuz , sorgusuz başlangıçlar zamanıdır şimdi ne bir plan olmalı geçmişe dair ne de bir düzen ne bir yol  ne de bir iz kayıp şehirler bul...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sorunsuz-sorgusuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şu Bir Bardak Şarapta XIV', 'su-bir-bardak-sarapta-xiv-i-brahim-balci-vpfh3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir harabe varken peşimde, yakılamamış gemilerden oluşan

Zift, kükürt ve neftden miras kalmış bir yangınsın içimde

Şu bir bardak şarapta, kaosu gördü ruhum

Sen ki ey hazan bülbülü, kadim fıtratımda tenakuz’sun

Şerbetliyim unutulmaya, mümkün değil ama unutmak

Rum ateşisin, sıkılan yüreğimdeki yangına çırılçıplak

Şu bir bardak şarapta, Şule’yi gördü ruhum

Sen ki ey alev tacı, kadim bir habis Ur’sun

Yüreğim yangın yeri, yakmışım yarden gayri her şeyi

Bir sen varsın içimde, bir de naifliğimle baş başa ben

Şu bir bardak şarapta, sadakat buldu ruhum

Sen ki ey kanatsız melek, sen kadim parlak nur’sun', 'Bir harabe varken peşimde, yakılamamış gemilerden oluşan Zift, kükürt ve neftden miras kalmış bir yangınsın içimde Şu bir bardak şarapta, ka...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Balcı']::text[], 8.5, '{"poet":"İbrahim Balcı","poet_slug":"i-brahim-balci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/su-bir-bardak-sarapta-xiv-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdiğin El Olur', 'sevdigin-el-olur-yusuf-onder-bahceci-zj4ik', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şimdi seviyorum desem ne olur, sanki çaremi olur,

Ayrılıktan, gizli, gizli akan gözyaşlarım, bilki sel olur,

Cânından çok sevdiğin güzel, gider, gider elin olur,

Şimdi seviyorum desem ne olur, sanki çaremi olur,

Ayrılıktan, gizli, gizli akan gözyaşlarım, bilki sel olur...', 'Şimdi seviyorum desem ne olur, sanki çaremi olur, Ayrılıktan, gizli, gizli akan gözyaşlarım, bilki sel olur, Cânından çok sevdiğin güzel, gi...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sevdigin-el-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçmiş', 'gecmis-nergis-unlucay-ovigj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tenin sınırlarınca ve daimliğince var olan olacaklar,

Silinmiş yitmiş bulutlar, 

Bir bakışın dilsizliği kadar bile değil.

Bir yerlere varmak için değildi belki ömürler,

Öksüzdük kovulmuştuk, 

En kötüsü olmayandan bile. 

Susturamadığım dilimden çok ellerimdi,

Bir iz bırakmak için değil de, bir anlam iliştirmek için soluğa..

Herkes meşguldü, yetişilmesi gereken lüzumsuzluklar hep vardı 

Ve zaman geçmek yerine ömrümüzü kemiriyordu, 

Tenin altında adsız bir yeri acıtarak. 

Farkındalık yetmiyordu değiştirmeye değişmeye,

Gereklilik kiplerini bilmek ve sıkışmak, gerekli oldurmuyordu.

Sonralarında sonraları vardı, sonsuzdular.

Gitmeler vardı, belirsiz hedefsiz sessizce

Ardına bakmadan kayıtsız... 

Sözcükler vardı koparıldıkça, 

Anlam fışkırtan gözümüze, soluğumuzu baltalayan,

Hani biri varmış, gerçekmiş, ölemezmiş 

Aklıma düşmüş peşine takılmış imgelerim.  

İçim bomboş muymuş 

Bir kıpırtı bile yok muymuş 

Ya da sadece kimsesiz sonsuz bir döngü 

Alışılıyor muymuş korkamadan

Üzgün değilim,olacaklar için bile.

Sebepsiz bir sükunet, bu ellerimi tırmalayan.', 'Tenin sınırlarınca ve daimliğince var olan olacaklar, Silinmiş yitmiş bulutlar,  Bir bakışın dilsizliği kadar bile değil. Bir yerlere varmak...', ARRAY['Türk Edebiyatı','Şiir','Nergis Ünlüçay']::text[], 8.5, '{"poet":"Nergis Ünlüçay","poet_slug":"nergis-unlucay","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/gecmis-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Gülüm', 'kara-gulum-tahmine-yildirim-9s2bm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gülüşün andırır sevgiyi

arkadaşlığın ise dostluğu

kişiliğin müjdeler mutluluğu

canım benim kara gülüm

sakın unutma beni 

bilki ben hep sevmişim seni

taktirde etmişimdir hep kişiliğini

canım benim kara gülüm

arada bir ararsan sevinirim

sana hep mutluluklar diliyirum

sevdiklerinin hep yanında olmasını umuyorum

canım benim kara gülüm

isteklerin hep gerçek olsun

yuvan hep mutluluk dolsun

düşmanlarınında hep rengi solsun

canım benim kara gülüm........                                                 TEMMUZ     

                                                                                     1995', 'Gülüşün andırır sevgiyi arkadaşlığın ise dostluğu kişiliğin müjdeler mutluluğu canım benim kara gülüm sakın unutma beni  bilki ben hep sevmi...', ARRAY['Türk Edebiyatı','Şiir','Tahmine Yıldırım']::text[], 8.5, '{"poet":"Tahmine Yıldırım","poet_slug":"tahmine-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kara-gulum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dün bugün ve yarın aşk', 'dun-bugun-ve-yarin-ask-kemal-eyupoglu-3o9uc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İlmik ilmik dokunan

Ve nakış nakış işlenen

Bir elbise gibiydi aşk

İçine ikimizin birden girdiği

Sevdamızın çıplaklığını saklayan.

Sonra,zaman kemirdi ilmikleri,düğümleri

Sökülmeye başladı dikişler

Ve daha sonra çekiştirmeler başladı

Kolları sende kaldı

Yakası bende

Diğer parçalar el uzatan herkeste

Şimdi

Boynumu sıkıyor

Aşkının bende kalan yakası.

Uzaklardasın

Ama seni görüyorum

Kaldırımsız sokaklarda yürüyorsun

Ayak seslerini duyuyorum

Gözlerin, hala gözlerimin içinde

Ve dudakların hala dudaklarımda

 Uzaklarda olsan da

Sen benimlesin.

Zalim bir avcı gibiydi Zaman

Günlerimi vururken birer birer

Ölen her gün

Hayat zincirinden kopan her halka

Nasılda dağıttı beni

Ve kaç parçaya ayırdı aşkı

Bugün,nefes alamıyorum sensiz

Kıymetleniyor sevdalar ölünce

Nasıl özlüyorum bir bilsen

Soluduğun havayı.', 'İlmik ilmik dokunan Ve nakış nakış işlenen Bir elbise gibiydi aşk İçine ikimizin birden girdiği Sevdamızın çıplaklığını saklayan. Sonra,zama...', ARRAY['Türk Edebiyatı','Şiir','Kemal Eyüpoğlu']::text[], 8.5, '{"poet":"Kemal Eyüpoğlu","poet_slug":"kemal-eyupoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/dun-bugun-ve-yarin-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Palyaço', 'palyaco-riza-aslan-lfu5r', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bir palyaçoyum ben 

sahnede insanları

kahkahalarla güldürürken

kuliste

içten içe ağlayan

bir palyaçoyum ben

gülerek ağlayan

bir palyaçoyum ben

yüzündeki maskeler düştüğünde

aynadaki kendisinden kaçan

bir palyaçoyum ben

güldürürken ağlayan

ben...

13 Mart  2006 

Mersin', 'bir palyaçoyum ben  sahnede insanları kahkahalarla güldürürken kuliste içten içe ağlayan bir palyaçoyum ben gülerek ağlayan bir palyaçoyum b...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/palyaco-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstenmeyen miras', 'i-stenmeyen-miras-riza-aslan-16sr9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'benim değil 

yüzümdeki bu anlamsız ifade

şaşkınlıklar, belirsizlikler

arasında gidip gelen bu benlik

benim değil

miras bırakılmış bana

atalarımdan

onlara da atalarından

13 Mart 2006 

Mersin', 'benim değil  yüzümdeki bu anlamsız ifade şaşkınlıklar, belirsizlikler arasında gidip gelen bu benlik benim değil miras bırakılmış bana atala...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/istenmeyen-miras-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uykuya yenik beden', 'uykuya-yenik-beden-riza-aslan-ulqeo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'uykuya yenik düşen

günlerce uyuyan

sadece bedenin

ruhun ise hala uykusuz

13 Mart 2006 

Mersin', 'uykuya yenik düşen günlerce uyuyan sadece bedenin ruhun ise hala uykusuz 13 Mart 2006  Mersin...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/uykuya-yenik-beden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hokkabazlar Kâlbimi Güldüremez', 'hokkabazlar-k-lbimi-gulduremez-yusuf-onder-bahceci-lkv1f', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dünya''nın en maharetli, hokkabazları gelse,

Türlü, türlü şakaları ve şamataları etse, etse,

Kıçından bir sürü yumurtalar türetse, türetse,

Maymun gibi parendeler atıp, amuda gelse,

Tavuklar gibi gıdak yumurtamsa sıcak dese,

Hindiler gibi kabarsa çok komik bir hâl alsa,

Penguenler gibi, hep paytak, paytak yürüse,

Ayılar gibi sağa sola saldırsa, bal, bal dese,

Yaralı kâlbimi asla güldüremez, güldüremez.', 'Dünya''nın en maharetli, hokkabazları gelse, Türlü, türlü şakaları ve şamataları etse, etse, Kıçından bir sürü yumurtalar türetse, türetse, M...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/hokkabazlar-kalbimi-gulduremez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayata küsmek', 'hayata-kusmek-riza-aslan-wche3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bu mudur yaşam? 

hayata küsmek midir bu? 

hayatın bundan haberi ol (a)  madan

13 Mart 2006 

Mersin', 'bu mudur yaşam?  hayata küsmek midir bu?  hayatın bundan haberi ol (a)  madan 13 Mart 2006  Mersin...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/hayata-kusmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsteyenin Bir Yüzü', 'i-steyenin-bir-yuzu-omer-faruk-altuntas-zplvi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Zaman dolu bardağı devirmiş bir kedi gibi hissediyorum kendimi. 

Binlerce tuğlalık bir binanın en altındaki tuğlasının çekildiğini görüyorum kabuslarımda. 

Kalabalıklara baktığımda gözyaşlarımı tutamamak istiyorum. 

Kalabalıkların gözyaşı olmak istiyorum. 

Batan bir geminin altı delik filikasını düşünüyorum. 

Bir mermi olup kurbanımın yüzünü görmek istiyorum son anlarında. 

Bir şairin ne demek istediğini son mısralarında 

Bir sobaya sarılmak en sıcak zamanlarında 

Bir zirveye tırmanmak tırnaklarımla 

Düşünmek istiyorum anlatamayacağım şeyleri, 

Düşünmek istiyorum anlayamayacağım şeyleri. 

Lamelifin tam ortasına bir salıncak kurup sallanmak istiyorum. 

Balık olup bir çocuğun oltasında, 

Bakmak istiyorum ona tam beni yakaladığı anda. 

Bir ormanda geyik olup avlanmak istiyorum, 

Bir küheylan şahlanıp, çatlamak istiyorum. 

İstiyorum, istiyorum istemek hakkımı istiyorum..', 'Zaman dolu bardağı devirmiş bir kedi gibi hissediyorum kendimi.  Binlerce tuğlalık bir binanın en altındaki tuğlasının çekildiğini görüyorum...', ARRAY['Türk Edebiyatı','Şiir','Ömer Faruk Altuntaş']::text[], 8.5, '{"poet":"Ömer Faruk Altuntaş","poet_slug":"omer-faruk-altuntas","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/isteyenin-bir-yuzu-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitmek - kalmak', 'gitmek-kalmak-riza-aslan-sjxci', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'zordur 

gitmekle – kalmak arasındaki 

o ince çizgide yürümek

zordur 

göz göre göre yitmek

yitirilmek

zordur

içinde olan savaşlarda

kaybedenin yine 

kendin olduğunu bilmek

zordur bazen gitmek

zordur bazen kalmak

13 Mart 2006

 Mersin', 'zordur  gitmekle – kalmak arasındaki  o ince çizgide yürümek zordur  göz göre göre yitmek yitirilmek zordur içinde olan savaşlarda kaybedeni...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gitmek-kalmak-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık Yeli Esti', 'ayrilik-yeli-esti-yusuf-onder-bahceci-dztvq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir zamanlar yan yanayken ve cân canayken,

Bir ayrılık yeli esti kaderimizden nasıl ayrıldık,

Gözlerime güleriken, bana, sevdiğim derken,

Bir ayrılık yeli esti kaderimizden nasıl ayrıldık.

Bizi ayıranlar ayıranlar mıdır, yoksa ayılar mı,

Ben geçmeyen yılları saydım, onlar ne saydı,

Sanki kürek mahkumuyum bir günü, bir aydı,

Bir ayrılık yeli esti kaderimizden nasıl ayrıldık.', 'Bir zamanlar yan yanayken ve cân canayken, Bir ayrılık yeli esti kaderimizden nasıl ayrıldık, Gözlerime güleriken, bana, sevdiğim derken, Bi...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ayrilik-yeli-esti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meydan Ayırana Kalsın', 'meydan-ayirana-kalsin-yusuf-onder-bahceci-d2gzo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Senden bana, gelmez haber,

Senden ayrı, her anım keder,

Önder birgün çeker de gider,

Bu meydan ayıranlara kalsın.', 'Senden bana, gelmez haber, Senden ayrı, her anım keder, Önder birgün çeker de gider, Bu meydan ayıranlara kalsın....', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/meydan-ayirana-kalsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret Ateşi', 'hasret-atesi-tahmine-yildirim-ufn0b', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kafamda kıvılcımlar oluşuyor

kalbimse inceden inceye sızlıyor

dizleriminde arada bir bağı çözülüyor

yüreğimi yakıyor bu hasret ateşi

geceler boyu yazmak istiyorum

duygularımı hislerimi kaleme döküyorum

her kelimeyede hüzünde katıyorum

satırlarımın hepsinde var hasret ateşi

gurbetçilik kaderimde var benim

ben yinede nedense bu halimi severim

gün gelir hem ağlar hem hüzünlenirim

kahkahalarla güldüğüm zamanda bile

içimde yanar yine o hasret ateşi.......................Kasım          1995', 'Kafamda kıvılcımlar oluşuyor kalbimse inceden inceye sızlıyor dizleriminde arada bir bağı çözülüyor yüreğimi yakıyor bu hasret ateşi geceler...', ARRAY['Türk Edebiyatı','Şiir','Tahmine Yıldırım']::text[], 8.5, '{"poet":"Tahmine Yıldırım","poet_slug":"tahmine-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hasret-atesi-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdim de Yeter', 'sevdim-de-yeter-i-brahim-yavuz-wuaph', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kirpiklerin oktur gözlerin cennet

İnan ki mecnundan beterim beter

Senin belan benim canıma minnet

Yeter ki sevdim de bu bana yeter

Ben sana yakınım sen bana ırak

Bitsin bu hasretlik bitsin bu firak

İstersen kırk gece uykusuz bırak

Yeter ki sevdim de bu bana yeter

İstediğin kadar üzebilirsin

Ayaklar altında ezebilirsin

İstersen kurşuna dizebilirsin

Yeter ki sevdim de bu bana yeter

Beni uçurumdan at istiyorsan

Götür köle gibi sat istiyorsan

Yemeğime zehir kat istiyorsan

Yeter ki sevdim de bu bana yeter

Umurumda değil düşsem de dile

Sensizliktir bana en büyük çile

Esirgemem senden canımı bile

Yeter ki sevdim de bu bana yeter', 'Kirpiklerin oktur gözlerin cennet İnan ki mecnundan beterim beter Senin belan benim canıma minnet Yeter ki sevdim de bu bana yeter Ben sana ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Yavuz']::text[], 8.5, '{"poet":"İbrahim Yavuz","poet_slug":"i-brahim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sevdim-de-yeter-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessiz Sevdim', 'sessiz-sevdim-yasar-tezel-enimc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Senin yüzünden bütün sıkıntılarım

Toprağımsın sürülmeye mahkum

Sevgiliye kucak açmış tevekkel

İçimizde kalsın ha..  güzelim

Gölümüze atılan taş  halkalanan su

Kaç dairesinde sende unutulursun

Gök kubbe gördü sen görmedin

İçimizde kalsın ha... güzelim

Canım seni çekerse kabahat benim

Neyine aşık olmak bir meleğe, neyleyim

Ben seni, sen bilmeden sessiz  sevdim

İçimizde kalsın ha... güzelim', 'Senin yüzünden bütün sıkıntılarım Toprağımsın sürülmeye mahkum Sevgiliye kucak açmış tevekkel İçimizde kalsın ha..  güzelim Gölümüze atılan ...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Tezel']::text[], 8.5, '{"poet":"Yaşar Tezel","poet_slug":"yasar-tezel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sessiz-sevdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Böyle Bir Yar İstiyorum', 'boyle-bir-yar-i-stiyorum-tahmine-yildirim-t1vl9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İstedimi sıkı sıkı sarılabilen

gerektiğinde benim için ağlayabilen

beni benden daha iyi tanıyabilen

işte ben böyle bir yar istiyorum

istedimi canından çok sevebilen

çevresine hep güven verebilen

gerektiğinde önüme mücevherler serebilen

işte ben böyle bir yar istiyorum

iyi ve kötü günümde yanımda olabilen

haklı olduğum zaman beni haklı görebilen

kanayan yaram olduğunda yaramı sarabilen

işte ben böyle bir yar istiyorum                                            Nisan            1995', 'İstedimi sıkı sıkı sarılabilen gerektiğinde benim için ağlayabilen beni benden daha iyi tanıyabilen işte ben böyle bir yar istiyorum istedim...', ARRAY['Türk Edebiyatı','Şiir','Tahmine Yıldırım']::text[], 8.5, '{"poet":"Tahmine Yıldırım","poet_slug":"tahmine-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/boyle-bir-yar-istiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pazar var', 'pazar-var-yasar-tezel-e0iif', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu gün cuma

Rahmet var

Günlerin efendisinden

Alışverişe mola

Camide bedava

Pazar var

Bulamadığında orada

Paranın geçmediği pazar

Rahmetten damlalar

Günahları melekler yıkar

Bugün huzur var

Cumada bulurlar

Meleklerde huzurda

Alemin kalbi o an duada', 'Bu gün cuma Rahmet var Günlerin efendisinden Alışverişe mola Camide bedava Pazar var Bulamadığında orada Paranın geçmediği pazar Rahmetten d...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Tezel']::text[], 8.5, '{"poet":"Yaşar Tezel","poet_slug":"yasar-tezel","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/pazar-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkarım İstanbul''um', 'korkarim-i-stanbul-um-sinan-gundog-wwehj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dünyanın gözü sende; sana bakarlar,

Nazarları deyer; diye korkarım,

İçinde barınan onca çakallar,

Sana sırtın dayar; diye korkarım.

Ey İstanbul sen ki! Şehirlerin pirisin,

Çağ açıp çağ kapayan, sultanların yerisin,

Sen ki İstanbul''um sen muhteşemsin,

Kötüler kalbin çalar; diye korkarım.

Tüm medeniyetlerin, beşiği sensin,

Aşkını kaybedenin, aşığı sensin,

Yolunu şaşıranın, ışığı sensin,

Vicdansızlar kana bular; diye korkarım.

Hasretlik çektim sende, bak şimdi sılam oldun,

Üç beş yıl ayrı kaldık, kıymete bindin,

Ey İstanbul içimde, kanayan yaram''oldun,

Yaramı kuruturlar; diye korkarım.

Göremedim İstanbul, sendeki birçok semti,

Kısmetse görürüz ileride belki,

Senden bana kalan,bir vapur düdüğü, bir martı sesi,

Onlarıda sustururlar; diye korkarım.

Seninle yatıp kalkan, bilmez senin kıymetini,

Seni anlamak için, çekmek gerek hasretini,

Ben ki İstanbul''um, karşılıksız sevdim seni,

Bu sevgimi anlatırlar; diye korkarım.

Kurunun yanında yaşta yanıyor,

Seni görmeyeli baya oluyor,

İstanbul''um seni seven ayrı kalıyor,

Birgün kapanır yollar; diye korkarım.

Ben ne Orhan Veli nede Kısaküreğim,

Onlara erişmeye belki yetmez yüreğim,

Şu naciz mısralarla safım'' belli edeyim,

Sinan kimmiş unuturlar; diye korkarım.', 'Dünyanın gözü sende; sana bakarlar, Nazarları deyer; diye korkarım, İçinde barınan onca çakallar, Sana sırtın dayar; diye korkarım. Ey İstan...', ARRAY['Türk Edebiyatı','Şiir','Sinan Gündoğ']::text[], 8.5, '{"poet":"Sinan Gündoğ","poet_slug":"sinan-gundog","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/korkarim-istanbul-um-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurtlar 2', 'kurtlar-2-oktay-baykurt-ggn93', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bir tanesi

içimdeki dağların dişi kurdu olman bir tarafa

sana ataerkil olabilmeyi çok istedim

senle sevgi sürüleri kurmayı 

sensizlik sınırında ulumayı ve duymanı

yıldızsız bir gecenin karanlığında senle olmayı

aşk dolu bir in kazıp senle yatmayı

yavrular türetmeyi

bir buzlu nehir kenarından ağzındaki buharla solumayı

ayrılık buynuzlu geyikler yakalyıp kanlarıyla ısınmayı

karda alt üst üst olmayı

güneş bezeli kuyruğunu takip edip saklıca seni öpmeyi

ve o dağda ölmeyi becebilmeyi

leşimi ağzınla sürüyüp ilk karşılaştığımız yere gömmeni', 'bir tanesi içimdeki dağların dişi kurdu olman bir tarafa sana ataerkil olabilmeyi çok istedim senle sevgi sürüleri kurmayı  sensizlik sınırı...', ARRAY['Türk Edebiyatı','Şiir','Oktay Baykurt']::text[], 8.5, '{"poet":"Oktay Baykurt","poet_slug":"oktay-baykurt","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kurtlar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek Adam', 'tek-adam-abdulkadir-kaymak-v3jvx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözlerimin Önündeki O Halin Var Ya! ! 

Sanki hiç Yaşanmamış Anılarımı Sergiliyordu Bana 

Keşke Tekrar Başlayabilseydik 

Keşke Sen Yapmasaydın o Hatayı 

Şimdi Ben ne Sensiz Kalırdım 

Nede Yalnız 

Ama Olsun! ! 

Bir Başıma da Olsam 

Konuşacak Kimseyi Bulamasam da 

Biliyorum ki Suçsuzum 

İçimdekileri Ne Bir Kaç Dörtlük Anlatır 

Nede Bin Dörtlük 

Sen Bir Boşluksun Artık Bende 

Ne Hatırlamak İsterim 

Nede Tekrar Yaşamak 

Bakma Keşke Dediğime 

İçimde Kalan Sevginin Son Zerrecikleri Onlar. 

Ama Ben Biliyorum ki! ! 

Kimse Gelmese de, Kimse Olmasa da Yanımda. 

Bu Halim Senlik Halimden Daha da Güzel 

Birde Sen Hiç Girmeseydin Hayatıma 

O Zaman Yeryüzündeki 

Tek Dalı Kırılmamış 

Tek Parçalanmamış Adam Ben Olurdum 

Varsa ki Pişmanlığım 

Oda 

Seni Hiç Tanımadan Önce 

Sabahları O Börekçinin Önünde 

Senin Geçmeni Beklerken Duyduğum Heyecanı 

Ve Mutluluğu 

Tekrar Yaşayamayacak Olmam', 'Gözlerimin Önündeki O Halin Var Ya! !  Sanki hiç Yaşanmamış Anılarımı Sergiliyordu Bana  Keşke Tekrar Başlayabilseydik  Keşke Sen Yapmasaydı...', ARRAY['Türk Edebiyatı','Şiir','Abdulkadir Kaymak']::text[], 8.5, '{"poet":"Abdulkadir Kaymak","poet_slug":"abdulkadir-kaymak","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/tek-adam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bunalım', 'bunalim-gulden-isik-ipwsp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Saat gecenin bir yarısı..

Bu saatte kimleri uyku tutmaz? 

Ana yüreğinde kırık camların acısını taşıyanları mı? 

Başka hayatlara kendi hayatını adayanları mı? 

Ruhundaki fırtınalara duyguların gözyaşlarıyla karşı koyanları mı? 

Ne yapacağını bildiği halde yapamayan korkakları mı? 

Değişmesini istediği şeylerin hayalini bile kurmaya

Cesaret edemeyen kaybedenleri mi? 

''''Hele bir sabah olsun'''' diye diye gecelerin hakkını yiyenleri mi? 

Yarınların tapusunu almış gibi

Bu günleri görmezden gelenleri mi? 

Sabrın bile sabrını taşıran kendini en son sevenleri mi? 

Uykular uyunurken güzelmiş..uyunurken! 

Uyunmayan gecelerde sanki meydan savaşı var; 

Ne kazananı belli ne de kaybedeni.

Bedenler dokunulmalardan uzak sevmiyor sevenini.

Ağrılar fışkırıyor her yandan..

Kendi kendine anlatılıyor dertler bir bir.

Saat gecenin bir yarısı..

Bu saatte kimleri uyku tutmaz? 

Bunu ancak gecelerde geceleyenler bilir.

2000', 'Saat gecenin bir yarısı.. Bu saatte kimleri uyku tutmaz?  Ana yüreğinde kırık camların acısını taşıyanları mı?  Başka hayatlara kendi hayatı...', ARRAY['Türk Edebiyatı','Şiir','Gülden Işık']::text[], 8.5, '{"poet":"Gülden Işık","poet_slug":"gulden-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bunalim-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul Ve Ben', 'i-stanbul-ve-ben-abdulkadir-kaymak-itv1m', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kimi Zaman Ağladığım Şehir 

Kimi Zaman Güldüğüm 

Kimi zaman Sevdiğim 

Ve kimi Zaman 

Aldatıldığım Şehir oldun 

Seni Çamlıcadan Seyrederken 

O kadar masum 

O kadar Mahzun Duruyorsun ki Karsımda 

Hep orda kalıp 

Seni Seyretmek İstiyor Bu Mahkum Kalp 

Ne zaman Sokaklarına 

Ne zaman kalabalık caddelerine girsem 

O zaman anılarım canlanıyor 

Gözlerim doluyor adımlarım yavaşlayıp 

Nefesim daralıyor 

Bir meydan arıyorum 

Kalabalık olmayan bir meydan 

Bu sefer 

Aşağıdan Çamlıca yı arıyorum 

Kendimi orda hayal edip 

Toparlanmaya çalışıyorum 

Bir kaç kez 

Başarsam da bunu 

Artık beceremiyorum 

İstanbul 

Beni de hapsettin artık 

Bir mahpushane gibisin hiç dolmayan 

Bir demir parmaklık olmuş 

Büyük gökdelenlerin 

Sadece 

Seni Çamlıca dan seyretmek 

Rahatlatıyor beni 

Artık ne sokak nede caddelerine 

Girmeyeceğim 

Artık beni hapsetmene izin 

Vermeyeceğim.', 'Kimi Zaman Ağladığım Şehir  Kimi Zaman Güldüğüm  Kimi zaman Sevdiğim  Ve kimi Zaman  Aldatıldığım Şehir oldun  Seni Çamlıcadan Seyrederken  ...', ARRAY['Türk Edebiyatı','Şiir','Abdulkadir Kaymak']::text[], 8.5, '{"poet":"Abdulkadir Kaymak","poet_slug":"abdulkadir-kaymak","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/istanbul-ve-ben-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çanakkale', 'canakkale-sevgi-damlalari-chpb7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ÇANAKKALE 

Övün ey Çanakkale, cihan durdukça övün! Ömründe göstermedin bin düşmana bir gün. Sen bir büyük milletin savaşa girdiği gün, Başına yüz milletin birden üştüğü yersin! 

Sen savaşa girince mızrakla, okla, yayla. Karşına çıktı düşman çelikten bir alayla. Sen topun donanmayla, tüfeğin bataryayla, Neferin ordularla boy ölçtüğü yersin! 

Nice tüysüz yiğitler yılmadı cenk devinden, Koştu senin koynundan çıkar çıkmaz evinden. Sen onların açtığı bayrağın alevinden, Kaç bayrağın tutuşup yere düştüğü yersin! 

Toprağından fazladır sende yatan adamlar, Irmağın kanla çağlar, yağmurun kanla damlar. O cenkten armağandır sana kızıl akşamlar, Sen silahın inançla son sövüştüğü yersin! 

Bir destana benziyor senin bugünkü halin. Okurken duyuyorum sesini ihtilalin. Övün ey Çanakkale, ki sen Mustafa Kemal''in, Yüz milletle yüz yüze ilk görüştüğü yersin! 

Faruk Nafiz Çamlıbel

RESİMLİ', 'ÇANAKKALE  Övün ey Çanakkale, cihan durdukça övün! Ömründe göstermedin bin düşmana bir gün. Sen bir büyük milletin savaşa girdiği gün, Başın...', ARRAY['Türk Edebiyatı','Şiir','Sevgi Damlaları']::text[], 8.5, '{"poet":"Sevgi Damlaları","poet_slug":"sevgi-damlalari","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/canakkale-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman', 'zaman-i-smet-onar-193wp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Zaman,

Ne kalır,ne tükenir..

Giden gider hey,kalan kötü zaman.

Pervasız vurur sebepsiz,çoğu zaman

Giden gider hey..kalan kötü zaman

Bir düş anı bir düşünce zamanı,

İhanetleri gizler çoğu zaman

Mesnetsiz vurur,sinsi ve hain...

Giden gider hey kalan kötü zaman.

Su, yüzüne vurur düşman gözüne

Dostun darbesini saklar çoğu zaman..

Namlu şakağında durur..namus kanında.

Bir gaflet anında vurur çoğu zaman

Giden gider hey kalan kötü zaman..

Bir ana ağlar..Bir kız düşer sokağa

Kan gider sürgüne,bir can gider..

Orospu yatağında ölür çoğu zaman

Giden gider hey kalan kötü zaman..

İsmet ONAR

16,03,2006 Adana', 'Zaman, Ne kalır,ne tükenir.. Giden gider hey,kalan kötü zaman. Pervasız vurur sebepsiz,çoğu zaman Giden gider hey..kalan kötü zaman Bir düş ...', ARRAY['Türk Edebiyatı','Şiir','İsmet Onar']::text[], 8.5, '{"poet":"İsmet Onar","poet_slug":"i-smet-onar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/zaman-308-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acı Hayat', 'aci-hayat-tahmine-yildirim-fibxc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bilmemki içim neden bir kömür kadar kara

bu hayat bazan çok acı veriyor bana

dostluğun pek güven vermiyor nedense bana

yinede içimden güvenmek geliyor sana

her gülüşümde içimde bir ses ağlıyor

her an yüreğimi pare pare dağlıyor

içimdeki o garip his beni sana bağlıyor

yine o his dünyaya iyimser bakmamı sağlıyor

her yokuşun bir inişi vardır der atalarımız

onlar olmasa kaybolurdu yollarımız

geriye gelse keşke boş geçen o yıllarımız

yanımızda olsun her zaman yüce Tanrımız     

                                                                                  Temmuz         1995', 'Bilmemki içim neden bir kömür kadar kara bu hayat bazan çok acı veriyor bana dostluğun pek güven vermiyor nedense bana yinede içimden güvenm...', ARRAY['Türk Edebiyatı','Şiir','Tahmine Yıldırım']::text[], 8.5, '{"poet":"Tahmine Yıldırım","poet_slug":"tahmine-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/aci-hayat-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilir misin Yavrum', 'bilir-misin-yavrum-derya-akgun-gc9bw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '2005 Yılı Milli Eğitim Müdürlüğünün düzenlediği “Öğretmen “ konulu yarışmada ilçe 3.sü “Bilir misin Yavrum”(Şiir)      

Bilir misin yavrum? 

Benim yüreğim engin denizlere benzer,

Sarar tüm yavrularını

Arındırır tüm kötülüklerin kirinden

Bilir misin yavrum? 

Benim yüreğim başı dumanlı yüce dağlara benzer,

Alır minicik canları

Ulaştırır erdemlerin şahikasına.

Bilir misin yavrum? 

Benim yüreğim sonsuz parçalara bölünmüş bir kalbe benzer.

Onun her parçası

Her biriniz için ayrı ayrı atar.

Bilir misin yavrum? 

Benim yüreğim kızgın çöldeki suya benzer.

Cehalet kuraklığından yanmış, susamışlara

Çağıl çağıl akar.

Bilir misin yavrum? 

Benim yüreğim zifiri karanlıktaki kandillere benzer

Karanlığın zulmetini

Bilginin nuruyla boğar.

Ben kim miyim yavrum? 

Ben seninle var olan,

Seninle hayat bulan,

Sen geliştikçe gül gül açan

Yurdumun emektarı,

Aydınlık geleceğin mimarı,

Şanlı ecdadımın itirafı,

ÖĞRETMENİM BEN! ...', '2005 Yılı Milli Eğitim Müdürlüğünün düzenlediği “Öğretmen “ konulu yarışmada ilçe 3.sü “Bilir misin Yavrum”(Şiir)       Bilir misin yavrum? ...', ARRAY['Türk Edebiyatı','Şiir','Derya Akgün']::text[], 8.5, '{"poet":"Derya Akgün","poet_slug":"derya-akgun","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/bilir-misin-yavrum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün Bana Değmeyin(Hece)', 'bugun-bana-degmeyin-hece-zehra-yilmaz-6nsl5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gönülden yaralıyım 

Dertli başım eğmeyin 

Özümden karalıyım 

Bugün bana değmeyin

Seversem nur saçarım

Ben yalandan kaçarım

Dertlerimden naçarım

Bugün bana değmeyin 

Dokunsalar ağlarım 

Başıma dert bağlarım

Yüreğimi dağlarım

Bugün bana değmeyin

Gül deseniz gülemem 

Öl deseniz ölemem

Gel deseniz gelemem 

Bugün bana değmeyin

Alın yazım yazılmış

Kırık mızrap sazımmış

Mezarımda kazılmış 

Bugün bana değmeyin.', 'Gönülden yaralıyım  Dertli başım eğmeyin  Özümden karalıyım  Bugün bana değmeyin Seversem nur saçarım Ben yalandan kaçarım Dertlerimden naça...', ARRAY['Türk Edebiyatı','Şiir','Zehra Yılmaz']::text[], 8.5, '{"poet":"Zehra Yılmaz","poet_slug":"zehra-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bugun-bana-degmeyin-hece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Orda Bir Köy Ağlıyor', 'orda-bir-koy-agliyor-gulden-isik-a0900', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Orda bir köy ağlıyor

Bacaları tütmüyor

Arşa varmış ahları

Kimse halin bilmiyor

Alın teri yetmiyor

Tarla çorak ekmiyor

İsyan olmuş aşkları

Sevgi filiz vermiyor

Eller birlik olmuyor

Yaraları sarmıyor

Duman almış dağları

Canı cana katmıyor

Gözyaşını saklıyor

Yiğitliğe doymuyor

Çile olsa sonları

Elde çiçek bekliyor

1999 Zonguldak', 'Orda bir köy ağlıyor Bacaları tütmüyor Arşa varmış ahları Kimse halin bilmiyor Alın teri yetmiyor Tarla çorak ekmiyor İsyan olmuş aşkları Se...', ARRAY['Türk Edebiyatı','Şiir','Gülden Işık']::text[], 8.5, '{"poet":"Gülden Işık","poet_slug":"gulden-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/orda-bir-koy-agliyor-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elveda Aşk Güvercinime!', 'elveda-ask-guvercinime-i-pek-caglan-da4yq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çoğu fark edilmez öldüğünde; 

Daracık karanlık apartman boşluklarında

Bazen lüks bir otomobilin tekerleri altında

Ya da bir yağmur oluğunun arasında

Hem de tam penceremin karşısında,

Sıkışarak can verdiğinde.

Gövdesi oluğa sıkışmış

Bir kanadı da belli ki kırılmış, aşağı sarkmış

Allah’ım kim bilir ne çok çırpınmış! 

Günden güne gözümün önünde soluyor ipek tüyleri

Çürüyor minicik zayıf bedeni

Yağmur yağdı yağalı

Açamıyorum perdeleri

Görmüyorum aşk güvercinimin oluktaki cansız bedenini.

Can verirken yetişemedim ikisine de; 

Hem aşkıma hem güvercinime…

Elveda artık ikisine de,

Elveda Aşk Güvercinime!', 'Çoğu fark edilmez öldüğünde;  Daracık karanlık apartman boşluklarında Bazen lüks bir otomobilin tekerleri altında Ya da bir yağmur oluğunun ...', ARRAY['Türk Edebiyatı','Şiir','İpek Çağlan']::text[], 8.5, '{"poet":"İpek Çağlan","poet_slug":"i-pek-caglan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/elveda-ask-guvercinime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Bir Günün Akşamında', 'guzel-bir-gunun-aksaminda-i-pek-caglan-iko4c', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Güzel geçen bir günün akşamında

Ben,

Seninle geçirdiğim tatlı dakikaların anılarında,

Dudaklarımda yarım kalan bir tebessümle.

Yarımı

Paylaştığımız güzel dakikalara,

Olmayan yarımı da

Saatlerdir aramayışına.

Bir de ıslak kirpiklerim gece yarısında,

Onlar da

Güzel geçen bir günün akşamında

Yine unutulmama.', 'Güzel geçen bir günün akşamında Ben, Seninle geçirdiğim tatlı dakikaların anılarında, Dudaklarımda yarım kalan bir tebessümle. Yarımı Paylaş...', ARRAY['Türk Edebiyatı','Şiir','İpek Çağlan']::text[], 8.5, '{"poet":"İpek Çağlan","poet_slug":"i-pek-caglan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/guzel-bir-gunun-aksaminda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni de Beni de Kanatır', 'seni-de-beni-de-kanatir-i-pek-caglan-aey0s', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Zorlanıyorsun severken beni bazen, biliyorum

Biliyorum sevgilim, sana fazla yükleniyorum.

Çok görme yalvarırım

Çocukluğumdan beri bir parça şefkat arıyorum

Bir yudum sevginin peşi sıra geziyorum.

Biliyorum, bazen seni de kendimi de kanatıyorum.

Kızma ne olursun,

Elimde değil sevgilim

Çocukken dost dediklerim gül ağacına ittiler beni.

Dikenlerim o günden hatıradır

Çok yaklaşma ne olur,

Seni de beni de kanatır.', 'Zorlanıyorsun severken beni bazen, biliyorum Biliyorum sevgilim, sana fazla yükleniyorum. Çok görme yalvarırım Çocukluğumdan beri bir parça ...', ARRAY['Türk Edebiyatı','Şiir','İpek Çağlan']::text[], 8.5, '{"poet":"İpek Çağlan","poet_slug":"i-pek-caglan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/seni-de-beni-de-kanatir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kardelenler Kara İnat Büyür', 'kardelenler-kara-i-nat-buyur-derya-akgun-nqe6r', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '2008 YILI 6. TÜRKÇE OLİMPİYATLARINDA ALMANYAYI  TEMSİL EDEN BÜŞRA KAYNAK TARAFINDAN OKUNMUŞ VE BÜŞRA   ANADİL ŞİİR KATEGORİSİNDE GÜMÜŞ ÖDÜL KAZANMIŞTIR.

2004 Yılı İzmirlioğlu İ.Ö.O’nun düzenlediği “Öğretmen” yarışmada ilçe 1.si “Kardelenler Kara İnat Büyür”(Şiir)                

                2004 Yılı ESDER’in düzenlediği”Öğretmen” yarışmada ilçe 1.si “Kardelenler Kara İnat Büyür”

      	2005 Yılı Milli Eğitim Müdürlüğünün düzenlediği “Öğretmen “ konulu yarışmada ilçe 2.si “Kardelenler Kara İ nat Büyür

-------

Bu şiir görevi başında şehit edilen Mustafa Gümüş öğretmen ve Onun manevi şahsında tüm şehitlerimize ithaf olunur...



Kardelenler Kara İnat Büyür

Batmanın dağlarında bir kardelen büyür,

Karın acımasız soğuğuna inat

Ulaşır güneşe, buluşur dünyayla,

Bazen bir Mustafa''dır o, bazen bir Murat.

Öğretmen Mustafa gençti, idealistti.

Gözleri pırıl pırıl, yüreği sevgi dolu.

''Ana'' dedi. ''Batman''a çıktı tayinim.''

''Oğul'' dedi anası: ''Gitme, ıraktır oralar, hem de tehlikeli.''

Güldü, Öğretmen Mustafa: '' Ana '' dedi.

''Bayrağın dalgalandığı yer değil midir vatan toprağı? ''

''Sen, ben kaçarsak kim aydınlatır karanlığı? ''

Gül yüzlü Mustafa öğretmen, yanında 20 günlük karısı

Eşkıyanın zulmüne, karın soğuğuna inat vardılar batman''a.

Cehaletin karanlığına inat,

Eşkıyanın zulmüne inat,

Karın soğuğuna inat,

Kara tahtanın karanlığına inat...

Elinde beyaz tebeşiri, yüreğinde vatan sevgisiyle

Mustafa öğretmen tüm aydınlık düşmanlarına inat...

Mutluydu Mustafa öğretmen.

Gül yüzlü çocukları, gül bahçesi misali sınıfı vardı.

Evde onu bakleyeni, seveni, sevileni vardı.

Ama çok sürmedi mutluluk,

Kara kalpli, kara kaputlu eşkıya alıp gitti onu, karlı bir Batman gecesi.

20 günlük karısı, gül yüzlü yavruları günlerce boşuna bekledi yolunu...

...............

Beyaz karlar üstüne cansız düşerken gövdesi,

Karın soğuğuna, 

Eşkıyanın zulmüne,

Cehaletin karanlığına inat

Bir kardelen büyüdü.

Kara kalpli, kara kaputlu zalim anlayamadı gerçeği,

Öğretmen bir ölür, bin dirilir,

Bugün Mustafa, yarın Aslı, diğer bir gün Mehmet gelir.

Kardelen misali...

Eşkıyaya, cehalete inat.

Her yıl, her gün, her an yeniden büyür,

Bu ülke için,

Bu ülkenin gül yüzlü çocukları için...

Batman''ın dağlarında bir kardelen büyür.

Karın acımasız soğuğuna inat,

Öğretmen Mustafa misali,

Ulaşır güneşe, buluşur aydınlıkla

Cehaletin karanlığına inat', '2008 YILI 6. TÜRKÇE OLİMPİYATLARINDA ALMANYAYI  TEMSİL EDEN BÜŞRA KAYNAK TARAFINDAN OKUNMUŞ VE BÜŞRA   ANADİL ŞİİR KATEGORİSİNDE GÜMÜŞ ÖDÜL ...', ARRAY['Türk Edebiyatı','Şiir','Derya Akgün']::text[], 8.5, '{"poet":"Derya Akgün","poet_slug":"derya-akgun","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/kardelenler-kara-inat-buyur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '13 Kavramların Laneti 1', '13-kavramlarin-laneti-1-ahmet-yozgat-wvrqr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '-nötr kavrama inananlara...-

1/:

La/ki… Li/ki…

Bir beyaz çığ düşer saçlarıma

Sayın ki... 

Kuzeyimde buz olur

Güneyimde cehennem.

La ki … li ki…

Isıtır bir ana gibi donuk dağları

Ta ki... 

Zemheriyi doğuruncaya kadar ovalar

Şerefsiz bir demircidir döğen damağımda

Mizan niyetine zavallı ve nötr balyaları

Çukurova kan olur özlediğim aşkımı vurup

Toroslara banar anam rahmini...

La ni…  li ki…

1.a/:

Yarılır orta yerinden bir ergen çağla

Ta ki... 

Domatesler utancından morarana dek

Kimya ile inadına karaciğerimde doludizgin

Simya ile kararlı sükutun altınında

Ben ışıkların gölgesine yanmışım  dağlar oy

Vurmuş sağ börümü kavramların laneti...

La ti… li ki…

1.b/:

Ta ki... 

Toprakla kucaklaşmışım gerdeğimde her gece

Sayın ki...

Hayalime katrankarası gözlerimi banmışım

Sülalem terk etmiş bir caminin avlusuna,

Masumiyeti yeşile çalan bakışlarımı.

Ben ışıkların gölgesine yanmışım  dağlar oy...

Yüzümdeki vadilere saklanmış kalmışım...', '-nötr kavrama inananlara...- 1/: La/ki… Li/ki… Bir beyaz çığ düşer saçlarıma Sayın ki...  Kuzeyimde buz olur Güneyimde cehennem. La ki … li ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/13-kavramlarin-laneti-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '01Ay Lümüne De Vay Lümün', '01ay-lumune-de-vay-lumun-ahmet-yozgat-7cz17', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '1/:

Ay Lümüne…

Vallah dayanmaz yüreğim bir bilsen

Esen rüzgarların topal taylara binenine.

Ve mavi mavi bakışan gecelerden bir gece

Seni o son durakta gördüğüm sevince.

1.a/…

De vay Lümüne…

Bu dem bir başka düğümlenirken yola

Kol kola giriyor sevda ile ayrılık.

Nedense Lümün? 

Akşamların kavşakları yıpranıyor apansız

Sevdamın sarışın seferberlik ateşinden. 

Gözlerim yudumluyor... Göklerin esrarını

Nabzını ateşliyor acılarımın bir Urbanusta

Ve yüreğimi dolduran aşkımın bitkin nabzı.

Yeryüzünde sevişen bizleri Lümün

Bulutların seyretmesi boşuna değil.

Ve değil boş yere

Kehkeşanlarda şahlanışı doru tayların

Ay Lümün sen de atla kuyruklu yıldızımın terkine

Unutma ucu tanık mektuplarında şahadeti 

Maverayı bilir... Sevdaya binen...

2/:

Ay Lümüne…

Vallah dayanmaz yüreğim bilesin,

Gecelerden son seferi bozguna uğrayan gece

Seni bulduğum o cesur sevince

Ve delice uçuşan şakak kuşlarımı görünce...

2/a:

De vay Lümüne…

Bu an bir alem... Nedense bilemem Lümün? 

Bir damla su ruhum... Acının denizinde..

Gözlerinden yüreğime atlıyor bak ansızın

Zincirini paralayan ateşten aslan

Sevdanın kazanında kaynayan bedenimi

Ve hüzünkâr ruhumu emiyor iştah ile

Dudağı yerle gök arası zulumkar devler.

Yıldızların zavallı yerlileri sarı sümbüller

Vurulup sensizliğin okuyla Lümün

Sevgiden yıldırımlara binip

Yeryüzüne yani yüreğime indiler.

***

Ay kız Lümüne bu gece…

Beynimi keşfe ne gerek

Sevdanın adresi yürektir yürek! 

3/:

Ay Lümüne…

Vallah dayanmaz yüreğim bilesin

Gecelerden bir cimri gece

Senin var ettiğin cömert sevince...

3/a:

De vay Lümüne…

Bu can bir garip... Nedense Lümün? 

Yıldırımlar öksürüyor akşamların döşünde

Kalbimin yaylasına ebabiller konuyor

Yağmur yüklü bulutları sevdamın ürkek

İnliyor ruhumu şenlendiren ceylanlar

Mavi volkanlar patlıyor gözlerinde ay Lümün

Sükuneti bürünmüş bilgece hatıraların

Karanlığı bir zar gibi yırtılıyor ve benliğimi,

Ve karanlığı umutla kavrayan ellerimi...

3/b:

Oysa ay kız Lümün…

Yıllar önce terkettim ben kendimi ve ruhumu

Yitirdim ağustosla zifafa giren arsız güneşi

Ve hüzün dudağımdan duyuruyor an be an

Melankolik çığlığını sabırsız insanlara

Izdırapsa bir mezbaha adacığıdır kızıl deryada

Gerdanım kapısında bekleyen kurban.

4/:

Ay kız Lümüne…

Vallah dayanmaz yüreğim bilesin

Gecelerden şaşkın bir gece

Rüyama düştüğün sevince...

4/a:

De vay Lümüne…

Bu kan bir deli... Nedense bilmem ay Lümün? 

Bahtımın kurtları parçalıyor aşkımı

Ve gözlerim bir savaş meydanı artığı sanki

Kalbimse iki büklüm dil aralığında

Yalnızlığın görünmez ağırlığından

İçimdeki karanlık oda hüzne hamile

İzbesinde doğuruyor tutkumun korkularını...

4/b:

Ay can Lümüne…

Varma üstüme n’olur

Gözyaşıdır sızan şimdi göklerin cübbesinden

Gözlerinse... İnandığım bir diğergam efsane

De vay Lümüne…

Vay... Vay... Vaay…

Yazıklar ola bu vefasız geceye

Ve çaresiz hayallere vurgun kendime...', '1/: Ay Lümüne… Vallah dayanmaz yüreğim bir bilsen Esen rüzgarların topal taylara binenine. Ve mavi mavi bakışan gecelerden bir gece Seni o s...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":93,"source_url":"https://www.antoloji.com/01ay-lumune-de-vay-lumun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '01 Kısrakların Toynağındayım Zilaka', '01-kisraklarin-toynagindayim-zilaka-ahmet-yozgat-zhfu3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1/:

Kısrakların toynağında okudum…

***

Kız Zilaka,

Yazgımda virgül

Hüznümde bir güldün maviye çalan...

Hamdı dünya daha. 

Tropik meyveler inadına hamdı

Ne İblis inmişti Cebeli Rahme’nin temeline

Ne de bizim komşu Salih amca aşkın özüne

Volkanlar sevişirken kıyamette sol gözümde

Ölüler zifafında kan düştü saçlarıma

Ellerin kınalandı senin mağma gülleri ile

Topraklar utandı... Söylemedi sırrını.

Kısrakların toynağında okudum

Ben yandım damağımdaki tandırdan

Kahrından gizemli gözlerin yandı Zilaka! 	

Kız Zilaka, gözleri gül Zilaka...

Yazgımda virgül Zilaka...

Hüznümde bir gülsün maviye çalan...

2/:

Kısrakların toynağında okudum…

*** 

Kız Zilaka,

Yazgımda virgül

Elemimde bir güldün sarıya çalan...

Uzak diyarlardan gelmiş leylalar

Dolunaylar gibi dökülmüşler yollara

Tuzbuz olmuş kahrilen bir öğlen üstü

Soruları cevaplayamayan tozlu aynalar

Şairler oturup tarihin kından kanadına

Çöle özlem dolu yalancı name yazarlar

Divitleri cana batar Zilaka

Hayalleri gerilir ufuklara...

Ben direnirim 318’inci ortamda yeniçerileyin

Hatta direnirim tüm dinginliğime inat

Kantarmalı kısraklar son savaşta şaha kalkar

Kutsal davet uçuşur hamasi türkülerimde

Hatırıma tropikal nem düşer,

Sıcak sevdalarıma gölgeli kasvet…

Kız Zilaka,

Yazgımda virgül

Gözlerimde bir güldün elaya çalan...

Kısrakların toynağında okudum bir ak şafakta...

Gözkapaklarıma basıp yazdılar geçen en son atlılar

Tarih zafer zafer boşandı vadilere... Ben yandım

Uhrevi çığlıkların yandı Zilaka!', '1/: Kısrakların toynağında okudum… *** Kız Zilaka, Yazgımda virgül Hüznümde bir güldün maviye çalan... Hamdı dünya daha.  Tropik meyveler in...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/01-kisraklarin-toynagindayim-zilaka-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '01 Bir İşveli Küheylana Destan', '01-bir-i-sveli-kuheylana-destan-ahmet-yozgat-co8v0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '1/:

İşveli bir küheylandın sen kız Miraye.

Delimsirek biraz,

Ve şaha hazır her daim

Kız Miraye işveli bir küheylandın sen,

Daha ne deyim? ...

***

Yüreğini bindirip... kudurgan yaylara

Döndür dizginlerini sür benden yana

Çeliğe dökülmüş gözlerini oturtup

Çıldırgan ceylanların avangardına al şafakta

Kaçırma gözlerimden aşkımın enkazını

Uzak ve hurda dağlara...

Dön benden yana Miraye…

Yüreğini bindirip işveli küheylanlara...

2/:

İşveli bir küheylandın sen kız Miraye.

Delimsirek biraz,

Ve savaşa hazır her daim... 

Yüreğim sıcacık... Ekvatorda bir oda say ki

Tandırında gürül gürül gül yakan

Çınarlarsa yaprak yaprak... El sallamada 

İçimdeki çölde azan katarımın ardından

Bense Miraye... Say ki nedense

Gözlerine gömülen... Ufacık bir serçeyim

İzin verin denizler... Üstünüzden geçeyim

Ve ılık sular içeyim Miraye gözlerinden. 

Dön artık benden yana…

Yüreğini bindirip işveli küheylanlara...

3/:

İşveli bir küheylandın sen kız Miraye.

Delimsirek biraz,

Ve koşmaya hazır her daim...

Ellerinin unuttuklarıdır deli kız... Ömrümün sermayesi

Mevsimlerden güç alıyor sensizlik

Gözyaşım onun için ağlamaklı

Ve ağlayışım ondandır kahkahalarla

Beti benzi bereketli... Ve hırçın bir çiğdem tarlası

Hücre hücre beynimdeki tarlada yaşar

Yokluğunun hırsıyla ördüğün duvar

Seni de hapsediyor benim dışıma

Gözyaşıma biniyor beynimdeki atlılar

Kaçırma gözlerini ıssız ufuklara deli kız

Dön benden yana Miraye…

Yüreğini bindirip işveli küheylanlara

Ve yüreğini bindirip... Göçmen kuşlara

Döndür benden yana... Dön benden yana...

Delimsirek biraz,

Ve aşka hazır her daim...', '1/: İşveli bir küheylandın sen kız Miraye. Delimsirek biraz, Ve şaha hazır her daim Kız Miraye işveli bir küheylandın sen, Daha ne deyim? .....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/01-bir-isveli-kuheylana-destan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '01 Bu Şehirde Vurdular Beni', '01-bu-sehirde-vurdular-beni-ahmet-yozgat-gyguw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '-Dedefakılılı Seyidcan’a-

1/:

Elbette bu şehirde vurdular beni ağalar.

Elleriyle koymuş gibi buldular,

Caddelere katran katran sinen... 

Acılı ve üryan yüreğimi.

1.a/:

Mamak-Sincan arası işler bu kentte

Nabzı namert atan mart trenleri.

Bir buhurdan kaynar döşümde

Tavşankanı sevdalar demler.

Bir türkü dokur tetik tetik Ankara.

Yüreğime banar bin sayfa kadim aşklar tarihinden

Kaldırımı ezberleyen hıfzi serçeler.

1.b/:

Elbette ağalar bu şehirde vurdular beni.

Gün görmeden... Evet evet görmeden

Mamak’ta… Yılan sığmaz bir aralıkta

İnsafsızca söktüler yüreğimi…

2/:

Elbette bu şehirde vurdular beni ağalar.

Elleriyle koymuş gibi buldular

Bulvarlara sinen... Acılı ve yalın yüreğimi.

2.a/:

Cebeci’de kırıldı lacivert kalemim tam belinden

Sustu arsız sokağın bilcümle apartmanları

Güvercinler anlamsızca seyretti

Gözbebeği titrerdi gri camların

Egzost soluklanan kör rüzgarlara bindi

Turkuvaz sevdamın acemi kırıntıları…

2.b/:

Elbette bu şehirde vurdular ağalar beni.

Ölmeden... Evet evet ölmeden daha

Mamak’ta... Karanlık bir arka sokakta

Fütursuzca söktüler yüreğimi…

3/:

Ağalar elbette bu şehirde vurdular beni.

Elleriyle koymuş gibi buldular

Monoksit kokan... Acılı ve sitemli yüreğimi.

3.a/:

Galata’yı taşımışlar o gece bu kente

Deniz tuzu kokan saçaklı gri kediler.

Acımı devşirmişler sabaha karşı

Kısık gözlü sarhoşları taşıyan

Hicranın hemşehrisi suskun taksiler.

Tekerleklere dolanan benmişim meğer.

Kornalara hayat veren ben…

Nasıl yanmam ulan? Bir kırık ağıza yenmişim…

3.b/:

Elbette bu şehirde vurdular beni ağalar.

Atmadan şafak... Evet evet atmadan

Mamak’ta... Şerefsiz bir konakta

Gizlice söktüler harman yeri yüreğimi…

4/:

Elbette ağalar bu şehirde vurdular beni.

Elleriyle koymuş gibi buldular

Çorum Çorum gül kokan

Acılı ve ilkbahar taşkını yüreğimi.

4.a/:

Şakağımdan fışkıran deniz kabardı.

Terketti saçlarıma yuva kuran fareler.

Ulus’ta düşen tetik

Nice sonra duyuldu ta Çankaya’dan.

Ağladı hemşehriler... Mamak duruldu.

Dendi usul usul ve mecburen:

“İskilipli Seyidcan gözlerinden vuruldu…”

4.b/:

Elbette bu şehirde sattılar beni ağalar.

Demlenmeden çay damarlarda daha

Ve daha üflemeden bacalar gri hüznü

Sakin Mamak’ta... Yüzü yırtık bir yatakta

Ne yapayım söktüler yüreğimi...

Vay... vay! 

Elbette ağalar bu şehirde vurdular beni.', '-Dedefakılılı Seyidcan’a- 1/: Elbette bu şehirde vurdular beni ağalar. Elleriyle koymuş gibi buldular, Caddelere katran katran sinen...  Acı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":74,"source_url":"https://www.antoloji.com/01-bu-sehirde-vurdular-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdamızın Türküsünü Söyleyelim', 'sevdamizin-turkusunu-soyleyelim-baran-demir-3avr7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yaşamak Zor Sevdiğim

Hayatta Dimdik Durabilmek de

Up Uzun Bu Yolculuk da

Yalpalayacağımız Günlerde Olacak

Bazen de Sendeleyeceğimiz 

Bazen Mutluluk Saçacaz Etrafımıza

Hüzünlü Günler Gibi

Dimdik Yılmadan Yanında Olmak

Seninle Omuz Omuza Yürümek

Türkü Söylemek

Halay Çekmek

Ağlamak İsterim

Sana Bu Hayat Yolculuğunda

Yoldaş,Dost Ve Sırdaş Olmak İsterim

Uzat Ellerini Tut Elimden

Daya Omzunu Omzuma

Sevdamızın Türküsünü Söyleyelim', 'Yaşamak Zor Sevdiğim Hayatta Dimdik Durabilmek de Up Uzun Bu Yolculuk da Yalpalayacağımız Günlerde Olacak Bazen de Sendeleyeceğimiz  Bazen M...', ARRAY['Türk Edebiyatı','Şiir','Baran Demir']::text[], 8.5, '{"poet":"Baran Demir","poet_slug":"baran-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sevdamizin-turkusunu-soyleyelim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '01 İz Süremem Leyla Geceleyin Ben', '01-i-z-suremem-leyla-geceleyin-ben-ahmet-yozgat-2a1am', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '1/:

Altımdaydı serdiğim yamalı bir sonbahar

Mektubunu içtim leyla iştahla.

Satır aralarında sürdüm izini gece,

Hece hece miladıma tarih düştüler,

Senden esen tropikal rüzgarlar.

Yüreğimin mavisiyle... Boyadım gökyüzünü.

Sevdamın ince dalları doldu kuşlarla.

Bulutlarla emzirdim acıkan ellerimi

Ve gözlerimin aydınlık ve bereketli ırmaklarında...

***

Ama Leyla. 

Karanlıklarda asla…

İz süremem geceleyin.

Gözlerimi kan tutar vaktin orta yeri.

Işıklı sevdalarım tutup tutup güneşi

Batıdan doğdurur... Doğudan batar.

Ürperir hayallerim

Korkarım, hâlâ nabzım atar.

2/:

Kuruyan dudağımı ıslatır çöller

Kervanını ıhtırıp serencamımın

Bağdaş kurarım toprağın avucuna

Kokum siner... Yar siner... Gecenin ve çölün ayakucuna

Kuşkum diner... Direnir sağ böğrümdeki akrep

Seni beklerim... Seni beklerim hep seni

Eğer ararsan beni ey Leyla

Yüreğimin en saklı yeridir... İnzivamın adresi

Bense ulaşmak için dolunayda koynuna

Gözlerinde sürmeliyim izini.

***

Ama Leyla. 

Karanlık yollarda asla…

İz süremem geceleyin... Dizlerimi kan tutar

Hamarat hıncım avuçlayıp kaçak güneşi

Batıdan doğdurur... Doğudan batar

Yılar gözlerim

Üşürüm, hâlâ nabzım atar…

3/:

Hilal üzgün sahanlığında gecenin,

Ve ağlamaklı dağların kucağında 

Nefes nefese koşuşmada gözlerim.

Oysa Leyla...

Sendin beni zamanın aynasına mıhlayan

Harlanan çarmıhımın ilkbaharında

Yasak aşkımın külü sevdiğim.

Oysa sevda sarıdır, tohumlar apak

Renkler yok olur zamanın çemberinde.

Saatler yontar sabrımı

Tik tak tik tak…

***

Ama Leyla iz süremem geceleyin

Özlemime mim düşen ihata dağlar! 

Eyerli kısrak olsa... Binemem yaylalara...

***

Yani Leyla

Karanlık odalarda asla…

İz süremem geceleyin

Yeni doğan hayalimi al basar.

Lohusa umutlarım avuçlayıp güneşi

Batıdan doğurur... Doğudan batar

Donar iliklerim

Ölürüm, hâlâ nabzım atar...

4/:

Bu şafaksız gecede Leyla

Binip imgelerim hicranlarına

Yitik adreslere göçtüler masallar bir bir.

Geride soğuk teni... Ve sıcak külleri kaldı ankanın

Beni ve ıssız viranelerimi

Mürekkebe banmış bir yaygı gibi

Bürünür gece gözlerine nihayet.

Yıldız düşer çivisinden... Ay üşür ve titrer.

Ayak ucuma konan kum gibi

Sanal davetim ulaşır ellerime.

Şafakları doğuran dağlar oy! 

Karların beyazlığı haykırır doruklardan.

Seni sorarım ağaran ufuklara ürkerek

Hayalini dokurum terkisi boşalan ışıklara.

***

Ama Leyla

Karanlık yüreklerde asla…

İz süremem geceleyin.

Korkarım ışıklı hayalimi yutan

Lacivert saatlerin gecinden.

İz süremem dağlar oy... Sabahı beklerim

Ben yatarım sırtüstü karanlıklara. 

Küskün hayallerimin çölde azar katarı

Ve sabırsız nabzım atar

Atar... atar...

Ta sensiz ölüme kadar…', '1/: Altımdaydı serdiğim yamalı bir sonbahar Mektubunu içtim leyla iştahla. Satır aralarında sürdüm izini gece, Hece hece miladıma tarih düşt...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":90,"source_url":"https://www.antoloji.com/01-iz-suremem-leyla-geceleyin-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıllar Sonra', 'yillar-sonra-cahit-pehlivan-zumy5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Olmaz denilenler oluyormuş.

Gönül eski âşkına kavuşunca,

Sevmez denilen gönül seviyormuş.

Âşkın da muhasebesi yapılabiliyormuş. Yıllar sonra.

Şimdi o başkasının kollarında mutlu,

Şimdi bir başkası da benim kollarımda umutlu,

Hey gidi gönül hey! Ne yapacaksın acaba? 

Hayalinden bile sildiğin sevgilinle, yıllar sonra.

Ne ilginç ve ne garip bir olay yaşıyoruz.

Seslerimizi duyduğumuzda, ateş gibi yanıyoruz.

Dünya’dan da şimdi bir başka zevk alıyoruz.

Olmaz, olmaz bitti denilen şeyler canlandı, yıllar sonra,

Göz bakmak istemiyor başka güzelliklere,

Hâlâ da gonca gül gibi gözüküyor gözüme,

Yıllar ne ondan, ne de benden bir şey almasa bile,

Gönül kafeslerimizin hâlâ boş olduğunu gördük, yıllar sonra,

Gel, nazlanmadan gel otur yanıma,

Boş ver geçmişe dair bir şey anlatma,

Çocuklar gibi mutluyuz ve şeniz şu anda,

Gençlik iksirimiz oldu bu aşkımız, yıllar sonra.

Ankara', 'Olmaz denilenler oluyormuş. Gönül eski âşkına kavuşunca, Sevmez denilen gönül seviyormuş. Âşkın da muhasebesi yapılabiliyormuş. Yıllar sonra...', ARRAY['Türk Edebiyatı','Şiir','Cahit Pehlivan']::text[], 8.5, '{"poet":"Cahit Pehlivan","poet_slug":"cahit-pehlivan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yillar-sonra-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '01 Mavera Kuyusunda Yozgatlı Ahmet', '01-mavera-kuyusunda-yozgatli-ahmet-ahmet-yozgat-tui02', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '1/:

Ey Mahmut oğlu Yozgatlı Ahmet...

Hafize’den doğma bir öğle güneşinde.

***

Zamanın gölgesi düştü yitik bir anıma

Bir yalan girdabına çelindi kolum.

Oysa balçık deryasında yüzen benmişim.

En donanımlı yarışımda kendime yenilmişim.

Merdivenler oyuldu o an uzayan gözlerime.

Yuvarlaklar sivrildi

Badallar arası ışığın yüzyılları

Yerle gök arası kursağına yuttu takvimi

Güya mavera kuyularına inmişim.

Maviler bozulmuştu orada grinin zifafında

Bir ayarsız altın akmış göllere.

Az gitmiş... Uz gitmişim

Masaldan atlara binmişim (galiba) 

Binmiş(miy) im? 

Veya... Az gitmiş uz gitmişim de

Gitmemiş(miy) im...

Evet Mahmut oğlu Yozgatlı Ahmet

Mantığımı hislerime... Ay ay! 

Ne yazık  ki en tok anımda bile azık etmişim.

2/:

Ey Mahmut oğlu Yozgatlı Ahmet...

Hafize’den doğma bir öğle güneşinde,

Yıl dokuz yüz elli beş...

***

Gözümü tatlandıran yıldızlar hani? 

Hani olur ya diken diken isyanlar,

Kerpiç damlı sevdalara kar yağar ya

Bir ağustos sabahı.

Hayal meyal turnalar Nil kıyısında.

Hatıramın yüzü çiçek bozuğu şimdi.

Ayaklarım yasak sevdaların pranga harmanında.

Özgürüm dediğim an meğerse esirmişim.

Karışmış kan ve günışığı

Maveranın mavi atları dadanmış ak sümbüllere

Atıp ardıma... Ya da takıp böğrüme

Sevdasız vakitlerini ömrün

Transgayya kuyularının hayali ellerimde

Az gitmiş... Uz gitmişim

Ankaların kanadına binmişim

Ayaklarıma boş sevdalar ardında

Evet Mahmut oğlu Yozgatlı Ahmet

Ne de yazık etmişim

Ay... Ay! 

Mantığımı hislerime azık etmişim.

***

Ey Mahmut oğlu Yozgatlı Ahmet...

Hafize’den doğma bir öğle kaderinde,

Yıl dokuz yüz elli beş,

Merhamet yoksulu dünya,

Keramet varsılı güneş...', '1/: Ey Mahmut oğlu Yozgatlı Ahmet... Hafize’den doğma bir öğle güneşinde. *** Zamanın gölgesi düştü yitik bir anıma Bir yalan girdabına çeli...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/01-mavera-kuyusunda-yozgatli-ahmet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçim Sensiz Ayaz', 'i-cim-sensiz-ayaz-kamil-soylemez-ufsej', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gece,mevsimdi yaz

İçimse sensiz kış ve ayaz

Seviyordum....! 

Deli gibi seviyor...

Kedi gibi pısıyordum 

Süt dökmüş bir lajivert yüzüm

Yıldızlarım sapır,sapır..

Bir,bir kayıyordu

Gece,mevsimdi yaz

Dağlara gece

Günlere sevda seriyordum

Mevsimler ayaz

Bense yaz,terliyordum

Bir nehir geçiyordu

Bir kanyon içimden, sevda saz

Mızrabım sendin

Kanuni,bir yas,tende

Seviyordum...

Seviyordum ilk kez

Ve üşüyüp,terliyordum

Düşlerim poyraz

Seviyordum....

Sevgiliyse bilirim beni duymaz

Yüreğiyse bir çocuk gibi haylaz

Bitermi bilmem ki,bu naz,bu yaz....

İşte niyaz.....', 'Gece,mevsimdi yaz İçimse sensiz kış ve ayaz Seviyordum....!  Deli gibi seviyor... Kedi gibi pısıyordum  Süt dökmüş bir lajivert yüzüm Yıldız...', ARRAY['Türk Edebiyatı','Şiir','Kamil Söylemez']::text[], 8.5, '{"poet":"Kamil Söylemez","poet_slug":"kamil-soylemez","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/icim-sensiz-ayaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '01 İzinsiz Kuşum Lüberde', '01-i-zinsiz-kusum-luberde-ahmet-yozgat-msc9g', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '1/:

Kuytu dağların hüznü

Akşam gibi çökende yüreğime.

Seyirir kanat kanat çırptığım yollar.

Takılıp türküsünün yanık ucuna

Telli turna katarında kurarım semaveri.

Al düşer zamansız yanağıma.

Dudağımda efsunkâr alışkanlıklar.

Bir öterim... Bir yanıtsız soru düşer tenime

Yıldızlara astığım yaslı kalbim nerede? 

Nerede deyin kızlar? ...

1/a:

Yani ben bir izinsiz kuşum...

Uçarım yüreklerin mayınlı tarlasında.

***

Lüberde…

Hüznüm günahlarıma perde

Oy lüberde kız, Lüberde…

Sevdalarımı dizdiğim kafeslerim nerede? 

Nerede deyin kızlar? ...

2/:

Deyin gururuna yenilmeyen zirveler

Ve kurşunlarla vurulup rüyalarımdan

Geçerken konduğum yalçın hayaller.

Ne ettiniz? Üstünüze serptiğim sevdalarımı

Ve nerde yüreğimin gülümseyen köpüklü çavlanları? 

Belki de vurgun yemiş gözlerim... Zaman denen avcıdan

Baldıranlar damıtmış ağıtlarım

Nerede kafesim ve garip çalılıklarım? 

Nerede deyin kızlar? ...

2/a:

Ben bir izinsiz kuşum.

Öttüğüme bakmayın sahipsiz çayırlarda.

Gün olur güneşlere dalarım

Öperim buhurdanını simyalı yüreklerin.

***

Lüberde…

Hicranım sevdama perde

Oy lüberde... Lüberde…

Çığlığımı gömdüğüm türkülerim nerede? 

Nerede deyin kızlar? ...

3/:

Kenarından teğet geçtiğim yollar gerimde.

Ama işte tozlara harcolan kanım.

İmbiklerden geçen usta avcılar

Kerterken ruhumun çınarlarını.

Iraklardan hecin hecin taşıdığım anılar

Asılır katarımın kanadına ağır ve elemli.

Diğer yanda fantastik hayallerim durmada.

Ve ötüşümü iştah ile serişim nakış nakış

Büyülü yıldızların nakışlı bulvarlarına

Nerede gözesinde çimdiğim kocaman gözler? 

Hasretimi gömdüğüm yolar nerede? 

Nerede deyin kızlar? ...

3/a:

Ben bir izinsiz kuşum…

Yıldızlara konduğuma bakmayın

Gül tüten akşamlarda ürkek uçar da

Saklanacak kuytu kâhkül duldaları ararım.

***

Lüberde…

Zülfüm yüzüme perde.

Oy lüberde. Lüberde vay…

Aşkımı unuttuğum viranelerim nerde? 

Nerede deyin kızlar? ...

4/:

Sevdalara mezar olan sonbaharlar söyleyin.

Bin bir özen ile ördüğüm eylül kokulu yuvam

Neden mezar olur kaygusuz yağmurunuza? 

Üzerim alaca aydınlık bakın gözyaşlarıyla.

Göğsüm dünyalara el çırparken korlarda

Acıları kayalara oyarım elmas uçlu aşk ile.

Beynim boz bulanık akmada göç yolunda.

Bakışlarım söylerken o uzak türküyü

Vururum başımı granit Marmaralara.

Sevdam taze filiz iken donarım

Yanarım eylül eylül kokan yuvama.

Nerede deyin kızlar? ...

4/a:

Ben bir izinsiz kuşum.

Tehlikenin nötr olduğu hudutta

Ummadığım oklarla vurulmuşum.

***

Lüberde…

Ölüm elemlerime perde

Oy lüberde kız, Lüberde…

Ellerimle oyduğum mezarım nerelerde? 

Yüreğinizde mi söyleyin suskun kızlar? ...', '1/: Kuytu dağların hüznü Akşam gibi çökende yüreğime. Seyirir kanat kanat çırptığım yollar. Takılıp türküsünün yanık ucuna Telli turna katar...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":88,"source_url":"https://www.antoloji.com/01-izinsiz-kusum-luberde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '01 Küskün Metropol', '01-kuskun-metropol-ahmet-yozgat-latoo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '1/:

Zifir kusuyordu zaman. 

Ben sırılsıklamdım...

***

Bulvarında vurulduğum metropol kafir

Metropol küskün bir yılandı.

Oğlum doğmamıştı daha.

Doğrusu ikizime gebeydi anam.

Elleri nasırlı inşaat ameleleri

Düşe kalka asfalt çukurlarına

Ağızlarında sunturlu ve Adanavari küfür

Azgın nefesi burunlarında acının

Yürüyorlardı... Ve ayak izleri akan kanımda.

***

Altımda ıkhtırdığım metropol kafir

Metropol yutuyordu zamanı,

Ve ana rahmini kımıldayan her şeyin.

Ben sırılsıklamdım...

B/:

Zifir kusuyordu zaman volkanik bacasından.

Bulvarında vurulduğum metropol kafir. 

Eskiyen rüyalarımı keşfe çıkmıştım.

Altımda düz tavanları sakin apartmanların.

Ama ayrılınca kabuk... Yırtılınca zar…

Yollara akıyordu... Hatıraları hırçın kalabalıklar.

***

Metropol küskün bir yılandı

Tısıl tısıl... Ve dan dan! …

Daha anasından doğmadan özgürlük.

Elleri nasırlı iblis işi işçileri

Boğuyorlardı karanlığın saklı aydınlığını.

Metropol kafirdi ya hem de kıpkızıl

Metropol yutuyordu kutlu emeğini

Ve anarahmini kımıldayan her şeyin.

Ben sırılsıklamdım...

Ba/:

Düşe kalka asfalt çukurlarına

Ağzımda masum bir küfür... 

Azgın nefesi burnumda karayazgı acısının,

Yürüyordum metropolün üstüne.

Ama bulvarında vurulduğum metropol kafir...', '1/: Zifir kusuyordu zaman.  Ben sırılsıklamdım... *** Bulvarında vurulduğum metropol kafir Metropol küskün bir yılandı. Oğlum doğmamıştı dah...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/01-kuskun-metropol-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '01 Ah Cennare Kız Cenna Kız!', '01-ah-cennare-kiz-cenna-kiz-ahmet-yozgat-hso5c', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '1/:

Ah Cennare kız, Cenna kız! 

Sevdanı sular gibi döktüm ağzıma.

Keşfe çıktım ilk defa dudaklarımı.

Bir yanım yıkıldı sahraya karşı.

Parmaklarım çığırmada şafak üzeri

Bileğine yaktığı tuzlu ve anadan doğma ağıtlarını.

***

Ah Cenna! 

Ağzın pamuklu ördek sarısı

Üzerin yeşil tülbent

Bilirsin... Ya da bilir misin bilemem? 

Vurgunluğumu yokluğunun çokluğuna.

2/:

Ah Cennare kız, Cenna kız! 

Ellerim sensiz devşiriyor

Ördek ağzı sarısını bereketli mehtaptan.

Kapaklanıyorum gözü kamaşık ışıkların ayakucuna.

Saçlarımı parlatıyor sahipsiz bir ateş beyi.

Yanıyor yokluğuna tutsak yüreğim.

Sanki güneş beni değil... Kendini ısıtıyor kanımla.

***

Ah Cenna! 

Çekme ahını bensizliğin – ki çekiyorsan ki–

Yetiş... yokluğunda ölmüşüm sanki...

3/:

Ah Cennare kız, Cenna kız! 

Gözyaşına binen savaşçı gibisin

Ve ıslattın çölümün nehirlerini Cenna.

Hayalime tepsi tepsi sunduğun acı

Açmada inadına nedendir? 

İştahımı kapatması lâzımken.

***

Ah Cenna! 

Nedir döşümü sarmalayan bu kararsız ben? 

Ve nedendir? Her Cenna deyişimde

Ağzımdan çıkanı sarmalayan korkun

Ah Cennare kız, Cenna! ...

Korkan ben, korkutan sen olmalısın.

Çünkü okun vızıldaşır kulağımın dibinde.

4/:

Ah Cennare kız, Cenna kız! 

Neden bulamam kafiyesini adının? 

Neden yadigârım olmaz? Bir güzel uyak sana.

Ah harman yeri sevdamın Cennare’si! 

Yeter kollama kendini benden –ki kolluyorsan ki–

Bırak, uğraşma yüreğimle... 

Ölmüşüm say ki...', '1/: Ah Cennare kız, Cenna kız!  Sevdanı sular gibi döktüm ağzıma. Keşfe çıktım ilk defa dudaklarımı. Bir yanım yıkıldı sahraya karşı. Parmak...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/01-ah-cennare-kiz-cenna-kiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '01 Bu Şehrin Varisiyim Ben', '01-bu-sehrin-varisiyim-ben-ahmet-yozgat-ce82l', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '1/:

Açıp koca koca koçanları dün akşam

Beni ağır aksak ölen bu derin kente

Varis yazmış kadim katipler...

***

Yalın bir sevda düşmüş payıma.

Doğrusu ne sevgine aşinâyım

Ne de vurgunum bana miras kalan bu şehre… 

İstediğim sadece gözlerinden su içmek

Ve kıvrılıp sol yanıma…

Rüyalarımın rahvan tayına binip

Efsunkâr krallıklara göçmek.

1/a:

Beni bu sahipsiz ve karanlık kente

Varis yazan kadim katipler…

Salın ırmakları bakir ve teşne çöllere

Azad edin bukağısından tuza tutsak denizi

Kırın Allah aşkına ulan... Kırın kalemlerinizi! ...

2/:

Parsel parsel doğramışlar karanlıkları

Beni üryan doğup üryan ölen bu kente

Varis yazmış kadim katipler...

***

Oysa ben ışık gözü yıldızlara asmışım yüreğimi

Mermerlere mızrak mızrak ağlayıp

Tozlu hendekler kazmışım içimdeki cephede.

Doğrusu ne bildik bir türküdür

Dudağında unuttuğum anılar

Ne de vurgunum bu yoksul şehre.

Gömün hasretimi duygusuz mezarcılar

Matemimi kürek yapıp döşüme

Kalemlere bel bağlayan

Ve şakakları çukur cenazeciler

Sokmayın çivili tabutlara ikimizi.

Açıp koca koca koçanları dün akşam

Boşa varis yazmış bu derin kente beni kadim katipler...

2/a:

Ey beni bu zombi kente

Varis yazan kadim katipler

Kırın Allah aşkına ulan... Kırın kalemlerinizi! 

3/:

Yırtıp küflü tapuları sabaha karşı

Beni kaldırımlarına köle olan bu kente

Varis yazmış mitolojik katipler...

***

Oysa avuçlarım dolu karanlıklarla.

Yanışım soluk kahverengi eskiliğine değil

Laciverte teslim olan şehrimin.

Bir tutup yüreğimi

Dudakları çatlayan gri sularla…

Lâkin ben gözyaşımla kurutmuşum gölleri

Nehirlerle uyumuş... Dereler çizmişim gözaltlarıma

Ne ışıklı zifafına açmışım

Çok kapılı rüyalarımı gece ortası,

Ne vurgunum bu zombi şehre.

Oklayın özleminizi kadim katipler

Acımın harmanisini kefen yapıp yüzüme.

Açıp koca koca koçanları dün akşam

Boşa varis yazmış beni bu kente tozlu katipler...

3/a:

Beni bu mahşerî kente

Varis yazan katipler…

Kırın Allah aşkına ulan... Kırın kalemlerinizi! 

4/:

Yok sayıp antik koçanları dün akşam

Beni kuburlara batık bu fosseptik kente

Varis yazmış kadim katipler...

***

Oysa hayallerim mazlum köylere gebe.

Yüreğimi banmalıyım ah! 

Yıldızlara komşu bakire hayallere.

Tespihim şıkır şıkır... Uşşak makamı.

Bir varmışla başlayan aşk masalım

Bolarsın bin bir varmış ile.

Sabahleyin kahvaltı masam

Donansın anka yumurtasıyla lebalep

Şıp şıp damlasın dizlerime tarihin izi

Ve bozgunlar emanet mezarcılara…

Açıp koca koca koçanları dün akşam

Boşa varis yazmış beni bu kente küflü katipler...

4/a:

Beni sarhoş kente varis yazan katipler

Yakın kalemlerinizi ulan. Yakın Allah aşkına!', '1/: Açıp koca koca koçanları dün akşam Beni ağır aksak ölen bu derin kente Varis yazmış kadim katipler... *** Yalın bir sevda düşmüş payıma....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":83,"source_url":"https://www.antoloji.com/01-bu-sehrin-varisiyim-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni almaya geliyorum', 'seni-almaya-geliyorum-baran-demir-hkq8j', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Zifiri karanlık her yer

Beynim yerinden çıkacak gibi

Düşünüyorum sebep

Koyuyorum yerine her şeyi

Bulutları dağıtıyorum

Seni koyuyorum yerine

Olmuyor

Yapamıyorum

Yılıyorum ve korku kaplıyor

Ya olmazsa diye

Ne yaparım diyorum

Göçer mi olurum acep

Konar mıyım obalara

Çadırımı sırtıma alarak

Yer etmezim artık

Mecnuna dönüşüm bir kez

Sende yoksun 

Düşünmesi bile ölüm

Yok olmak

Yurt edinememek

Zaman akıp gidiyor

Tutmak istiyorum ucundan

Beni dinlemiyor

Elimden kayarak ilerliyor

Depremler oluyor yüreğimde

Yıkıntılar içinde kalıyorum

Işığa hasret olurcasına

Sesin çınlıyor kulağımda

Bir güneş gibi

Zifiri karanlığa inat

Toz duman olmuş dünyama

Çağırıyorum  sesim ulaşmıyor

Umuda

Umut demişken 

Sen geliyorsun aklıma

Umudum oluyorsun

Sensizlik ölümdü ya 

Gün görmez yıkıntılar arasında

Viraneye dönmüş dünyam 

Saraylara dönüşü veriyor

Seni düşündükçe

Ne karanlıklar dan korkum

Nede üzerime yıkılmış dünyam

Vız geliyor

Silkiniyorum 

Dimdik başım havada

Onurla yürüyorum

Seni almaya geliyorum 

Bu yıkık dünyamı yeniden onarmaya', 'Zifiri karanlık her yer Beynim yerinden çıkacak gibi Düşünüyorum sebep Koyuyorum yerine her şeyi Bulutları dağıtıyorum Seni koyuyorum yerine...', ARRAY['Türk Edebiyatı','Şiir','Baran Demir']::text[], 8.5, '{"poet":"Baran Demir","poet_slug":"baran-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/seni-almaya-geliyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '01 Yüreğim Sitem Fideliği', '01-yuregim-sitem-fideligi-ahmet-yozgat-6397i', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '1/:

Sitem fideliği yüreğim sanki

Göğsümü doğrayan sevdama karşı...

***

Ne öfke doluyum kan tüküren dağlarda

Ne de kırgınlık kuşanır belim

Ve uzanır umut vahasında biçare arşa.

Volta keser parmaklarım kevkebler maltasında

Keser ama boş döner elim her daim.

Asırların utancını taşırım Leylam’a karşı

Boş döner her seferinden,

Yeşili ölen muharip düşüncelerim.

2/:

Itır kokar baş parmağımın ucu.

Ama yıldızlar bile koklamaz buhurdanımı.

Toplanır bilcümle zerre gözüme.

Delimsirek düğün kurar... Halay teper hatıralarım.

Ayıklanır ne kadarsa çürüğüm.

Yaşlı ve bilge bir el

Oturup kıyısına Yeşilırmağın…

Hafifler şakaklarım bir gıdımcık kuş olur

Yönelir umut vahasında biçare arşa

Bükülür kevsere dalan sert parmaklarım…

Voltamı keser zamanın maltasında usturasıyla.

Hazzıma harman olan eşkin tay ayaklarım.

Yönelirim umut vahasında biçare arşa

Karşımda kevkebler şahı kuyruklu yıldız

Ama boş döner elim.

Yok oluşun acısını duyarım Leylam’a karşı

Boş döner her şahlanışında,

Aşk elinden, biçare düşüncelerim.', '1/: Sitem fideliği yüreğim sanki Göğsümü doğrayan sevdama karşı... *** Ne öfke doluyum kan tüküren dağlarda Ne de kırgınlık kuşanır belim Ve...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/01-yuregim-sitem-fideligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '13 Kavramların Lâneti 2', '13-kavramlarin-l-neti-2-ahmet-yozgat-pnvpu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1/:

De – em... Ka–er... Es...

Yani herkes...

Daldırıp damarına kurşunî kupasını

Sarhoş sofrasında bir akşam

Yudum yudum…

Ama bendim binip hayalin yaprağına

Ağır ve dengesiz bir tahtaravallinin

Bu ucunda tartıp yüreğimi kendi dertlerimle uyudum.

***

Ey kast diyarının Arilere yenik zavallı paryaları,

Sanmayın kendimizin efendisiyiz

Hepimiz... Lânetli kavramların kölesiyiz

Ve gayya kuyularından

Avuçlarımızla çekip alaca ve bereketli hasatları

Kırmışız kilit kilit sandukasını

Kamış kamış üfürmüşüz acıyı

İşte biz öylesiyiz.

Yani hepimiz lanetli kavramların kölesiyiz.

2/:

De–em... Ka–re... Es...

Herkes... İşte biz öylesiyiz.

Lanetli kavramların vilayet denizlerine garkolmuş

Uçan hiçliklerin sayılmayan efendisiyiz.

Sayısız arzu tekerlenmiş

Ve dökülmüş orta yerde imaret

Kırpılmış temreninden uğuru gösteren parmak

Budanmış racalar ülkesinde o kutsal ezoterik işaret.

Ey kast diyarının Arilere yenik zavallı paryaları,

Yani sanmayın kendimizin efendisiyiz

Hepimiz... Elbet ve (galiba)  ilelebet

Lânetli kavramların kölesiyiz.', '1/: De – em... Ka–er... Es... Yani herkes... Daldırıp damarına kurşunî kupasını Sarhoş sofrasında bir akşam Yudum yudum… Ama bendim binip ha...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/13-kavramlarin-laneti-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '13 Kavramların Lâneti 3', '13-kavramlarin-l-neti-3-ahmet-yozgat-1jp1q', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '1/:

Şe- şe–ar... Ay–te...

İte ite ucundayız bir derin yarın.

Çok uzakta bir bıldırcın ve ben

Çizip kanadıyla kahverengi bulutları

Yüreğimden geçiyor sırrını öte öte.

Dökülmeyin üzerine bastığım taşlar.

İçi boş bir öğle üzerine

Ve sıkıntılı avuçların yalanıyla öz.

Sekende urgan... Bükülende kın…

Harlananda kızıl köz...

2/:

Şe- şe... Ra-da...

Dönün bir kocaman “o” harfinin hüsban raksında.

Ve oturun ince uzun bir asfaltın kenarına.

Çok uzakta bir bıldırcın ki ardı yeleli

Kanadı tüysüz bir kısrak ile karışmış.

Eski ve paslı galerilerde... 

Yüreği yayan, beyni yapıldak

Yeryüzünde uçarak ve koşarak bulutlarda.

Yarısını yuttuğu ipiltili tarihin yapraklarını

Tuzlu bir iştah ile ve salya salya yalayarak.

Bense veya bizse... Terkedip uzak çölleri

Batağa saplanan sinirli ve temreni kirman bir mızrak

Sayıp örs üzerinde şahsımızı

Gömüleceğiz (galiba) ...

Bilcümle karanlığı kutsallarımızla tarayarak…', '1/: Şe- şe–ar... Ay–te... İte ite ucundayız bir derin yarın. Çok uzakta bir bıldırcın ve ben Çizip kanadıyla kahverengi bulutları Yüreğimden...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/13-kavramlarin-laneti-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '01 Niye Ağlar Ayşelerin Gözleri?', '01-niye-aglar-ayselerin-gozleri-ahmet-yozgat-34gx4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '1/:

Onlar ki ezeli bir bölgeden alırlar ağıtlarını.

Gözyaşları çöl sarılığındadır.

Gülüşleriyse nisan turaçlarının uçuşu sanki.

Belki unuttukları yağmur dolu yükleridir.

Belki de hatırlamak istemedikleri

Dökülmüş sitemleri vardır

O çinko tabelalı karatren istasyonlarında…

İstedikleri bir katarda onların

Bir diğer yanda istemedikleri...

***

Niye akar Ayşelerin gözünden? 

Düşündünüz mü hiç niye? 

Hüznü kucaklayan uzak diyar beyleri

“Oy broy.” diye diye...

***

Onlar ki…

Ezeli bir bölgeden alırlar ağıtlarını.

Saçlarına yağız ve ısırgan kokulu sevda örerler.

Bazen hicranın gayyasına dalar umarsız

Daha güneşi doğmamış şafak vakti elleri.

2/:

Onlar ki kendilerini unuturlar yanıbaşlarında.

Gurbete çığırırlar şarkılarının son ayağını.

Denkleri bağlı her zaman

Saçları ise dağınık dağ doruğu rüzgarlarında.

Bir yüzleri çimen yeşili resmederken tenlerine

Öteki parmakları kızıl kınalı

Ve burçak tarlasında sosyoloji devşirmede.

İstedikleri bir yaylada onların

Ya istemedikleri? ...

***

Niye akar Ayşelerin gözünden? 

Düşündünüz mü hiç niye? ..

Öfkeyi doğuran lanetli sarayların beyleri

“Oy broy.” diye diye...

***

Onlar ki...

Kendilerini unuturlar yanıbaşlarında.

Kirpiklerine temmuz akşamları doru kırağı düşer.

Bazen benim de kısmetime doğranır apansız

Henüz akşamüstüsü batmamış o lacivert elleri.

3/:

Onlar ki süt katışık göllerinde çimerler ikindilerin.

Diz çöküp eski zaman şiirleri dinlerler.

Ne sağırdır kulakları sevdaya karşı

Ne de çocuk doğururlar eloğlu için.

Teker teker dizerler uzun ve ince parmaklarına

Hüzne bulanmış sevinçlerini koridorlarda.

Odaları iç içe açılır mor dünyalarının.

İstedikleri uzak bir varoştadır onların.

Bir başka kenar semtinde ise istemedikleri.

**

Niye akar Ayşelerin gözünden? 

Hiç düşündünüz mü niye? ...

Saklı melodileri haykıran şarkıların beyleri

“Oy broy.” diye diye...

***

Onlar ki...

Süt katışık göllerinde çimerler ikindilerin.

Depremlerle sarsılır takvimin bir yerinde

Zemheride ateş keser teşne elleri.

4/:

Onlar ki...

“Onlar ki” diye şiir yazar birileri gıyaben.

Onlar ki oturup türkü yaktırırlar kendilerine.

Ne kehkeşanlara uzanır hayalleri

Düşleri sayısız tonlar içerir aralığında ömrün.

Çırpıp kanat ışıklarını güz aylarında

Bulutların salkımsaçaklarına konarlar yüreklerine binip

Söyleşirler yalnız ve sakin çoban yıldızlarıyla.

İstedikleri bu ucundadır göğün

Filan yıldızda ise istemedikleri...

***

Niye akar Ayşelerin gözünden? 

Hiç düşündünüz mü niye? ...

Kırık ışıklar yayan güneşlerin beyleri...

“Oy broy.” diye diye...

***

Onlar ki...

Oturup türkülere yakarlar kendilerini.

Topuk altlarına karanlığı doğrarlar.

Yıldızlardan sihirli şarkılar derer elleri....', '1/: Onlar ki ezeli bir bölgeden alırlar ağıtlarını. Gözyaşları çöl sarılığındadır. Gülüşleriyse nisan turaçlarının uçuşu sanki. Belki unuttu...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":83,"source_url":"https://www.antoloji.com/01-niye-aglar-ayselerin-gozleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '01 Parantez Mahkumuydu Hasan', '01-parantez-mahkumuydu-hasan-ahmet-yozgat-nexzi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '– Hasan Demir kardeşime –

1/:

Bir parantez içinde ruhum.

Ben bu idim... Ben buyum…

Geçmişten kalan lifli hatıralar buruk…

Savurdum yılların yandaşında kalbimi.

Bir karlı Kastamonu ormanı tiryakiliğinde,

Ellemiştim zamanı yorgun elimle.

Kan fideliği verimli dudaklarım

Ve cana damlayan titrek ve zavallı bir mum.

Kan kokan dallarıma mahkumum.

Bir parantez içinde ruhum hapiste

Arkam akşam... Önüm sıra sekiyor gölgem.

Uzak rüzgârların hızıyla akan

Anılarım yitiriyor daracık hafızasını.

Yerinde sade, tek damlacık kan

Haykırıyor ardımdan derin bir ağız:

Hasan... Hasan... Can Hasan! ...

2/:

Sensiz girişim geceye. 

Say ki cephede bozgun.

Kılıcım kırık uzak bir Dandanakan’da.

Kargıların ucunda bir damlacık can

Ağlıyor keskin kenarlı vefakar bir kayalık:

Hasan... Can Hasan! ..

2a/:

Yanıyor keyfim... Kaçıyor uykum son menziline.

Saçlarım ılık ılık özgürlük üfürüyor enseme.

Bir parantez içinde ankebut ruhum.

Sen yan gayri ey kalbim kendi mahpusuna yan

Hasan... Hasan...  Can Hasan! ...

3/:

Bir parantez içinde kelebek ruhum...

Cereyanlar tarifeli... Pınarlar nöbetleşe akıyor.

Bereketli zamanımı çalan hırsızlar

Cephelere dökülen feryadıma bakıyor.

Canım Hasaniye’m ağlıyor ayakucumda

Gözleri umman içre inci tarlası gibi…

Topraksa nisanın kıblesini soyunup

Azgın ateşler doğruyor damarlarımda.

Kargım kırık temreninin dudak kenarından... 

Hayal meyal bir Dandanakan’da

Tutsak oluyor aşka

Dağlara üzengilik gibi bakan

Yasa durmuş karanlıkta bir çift güvercin.

Ağlıyor hırçın hırçın hıçkırarak:

Hasan... Hasan Can Hasan! ...', '– Hasan Demir kardeşime – 1/: Bir parantez içinde ruhum. Ben bu idim... Ben buyum… Geçmişten kalan lifli hatıralar buruk… Savurdum yılların ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/01-parantez-mahkumuydu-hasan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '01 Şahidimdir Kızılırmak', '01-sahidimdir-kizilirmak-ahmet-yozgat-4lzaj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '1/:

Saçların turnaların göç yolu

Gurbet eker kıyısına katarlar.

Diz kırıp tespih tespih

Azmin ve yorgunluğun mor tuvalinde

Uzak güneşlere kanat çırparlar.

Ve rapt ederler kendilerini ironik yaylalara.

Ama neyleyim ki göçmen yolları ıssız

Şimdilerde saksılarda sencileyin kokarlar…

***

…Andolsun yağmurların nükleik dekoruna

Ve andolsun ki Leylalar…

Şahidimdir Kızılırmak

Ve eriyen yüreğimi donduran sular.

Havar havar... Yar havar! ...

2/:

Darımı kurduğun loş gözlerinde

Kırlangıç kervanları geçiyor Leyla.

Dudaklarında çöl çiçekleri... Hüzün üfürüyor dağlara.

Bir eğilip damağımdan bengi sevda yalıyor.

Yüreğimin tıklatıp kırık camını

Bir efsunlu şiir içiriyor kutsal kaseden...

Bir de ardımda unuttuğum yorgun zamanı...

***

… Andolsun yağmurların atomik hüsbanına

Ve andolsun ki Leylalar…

Şahidimdir Kızılırmak

Ve eriyen yüreğimi donduran sular

Havar havar... Yar havar! ...

3/:

Saçlarının Kalahari lisanından ırlayan ıslığında

İnmiş gülüm suya bu çorak yürek.

Şahittir Kızılırmak… Şahit Tendürek...

And içmiş ayağını yaladığı sıradağlara.

Lacivert akşamilen zifafa giren kahve rengi zirvelerde.

Geme gelmez bir kısrak koşuşmada

Yüreğimin puslu ufku derin gizemli savanlarında.

Sevdamı bindirip canhıraş uçuşuna

Yeleleri kızıl aşka batmada.

Zaman bir yağız beyler memleketinde su

Şakaklarım ise gül dökümü mevsimi.

Alnımdaysa turnalar sulanmada bu sabah.

Kavurucu sıcaklığı beynimin

Günahını yakmada zavallı ellerimin...

***

… Andolsun kutlu yağmurların damlalarına

Ve andolsun ki Leylalar…

Şahidimdir Kızılırmak

Ve samanyolunda yüzen som ışıktan kuğular.

Havar havar... Yar havar! ..

4/:

Diz çöküp zemherinin önüne şakaklarım.

Balta kesmez buz tutmada apansız

Sarışın saçlarının büyülü ıslığıyla.

Gülüm yine iniyor yüreğim suya.

Yani dalmış derin uykuya körmantık

Derin ve bihaber ağaran şafak...

***

Vallah... Şahidimdir Kızılırmak

Ve damlayan yüreğimi kurutan sular.

Havar havar... Yar havar! ...

Andolsun ki berduş yağmurlara

Ve andolsun sevdanıza Leylalar...', '1/: Saçların turnaların göç yolu Gurbet eker kıyısına katarlar. Diz kırıp tespih tespih Azmin ve yorgunluğun mor tuvalinde Uzak güneşlere ka...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":63,"source_url":"https://www.antoloji.com/01-sahidimdir-kizilirmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '14 Abdullahlar Tarihinde Darbe: 1', '14-abdullahlar-tarihinde-darbe-1-ahmet-yozgat-9gi6o', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '1/:

Devir tarihi kadim,

Hanedanı Ahmetistanda bir şehir,

Bölgelerden yürek bölgesi,

Bilmem kaçıncı enleminde alt alta paralellerin,

Çapraz çizgilerin, 

Yani meridyenlerin sayın ki bin birincisindeyiz...

Saltanatta en ilkinci Abdullah…

Yani cennetmeken Abdullahı Sani,

Ah...Ah! 

***

1a/:

Ey birinci Abdullah:

Ben Mahmut oğlu Ahmet, sadık tebandan bir kul...

Seni görende yorgun gözlerim

Ve hissedende acısını bitişin.

Elmalar kesiliyor volkan oğlu taşlarla

Lahuti şeftaliler sonbahar olgunu

Doğumu beklemede yorgun ay.

Vay Abdullah vay! 

1b/:

Bir bebek yumuluyor göbeğinin üstüne

Ağlıyor suya banıp denizderya saçlarını

Sonra kopuyor kordonu karmaşanın.

Beyinleri kilitleyen sandık yumşuyor.

Tırnaklarıyla kazıyor tuğladan duvarları

Ağızda açılan galeriden ürkerek giriliyor

En ilkinci Abdullah gâh ölüyor arkaya,

Gâh öne diriliyor...', '1/: Devir tarihi kadim, Hanedanı Ahmetistanda bir şehir, Bölgelerden yürek bölgesi, Bilmem kaçıncı enleminde alt alta paralellerin, Çapraz ç...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/14-abdullahlar-tarihinde-darbe-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '14 Abdullahlar Tarihinde Darbe: 2', '14-abdullahlar-tarihinde-darbe-2-ahmet-yozgat-zz44f', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '1/:

Saltanatta ikinci Abdullah…

Ah...Ah! 

***

2a/:

Ey ikinci Abdullah:

Atılıyor gün gibi

Ve ürkünç hudutlara aşikar…

Bir münzevi yaylada doğruyorlar kanını

İlkbahar ölende ağdalı doruklarda.

Yıldızlar yıkanıyor her cuma akşamında... 

Şehvetinde şaşkın seyyarelerin gözyaşlarının

Darbeyi beklemede yorgun ay.

Vay Abdullah vay! 

2b/:

Pencereler çiziyor sonsuz sınıra.

Ellerimiz tutsak oysa tartışmasız yazgılara

Ve saçlarının akışkan hışırtısına.

Gün geliyor a be can

Yırtılıyor karamsar perdesi kat’i

Asabî gecelerin.

Vuruluyor ortası gündüzleyin gerçeğin

Vurulup upuzun devriliyor

Abdullah gâh ölüyor arkaya

Gâh öne diriliyor…', '1/: Saltanatta ikinci Abdullah… Ah...Ah!  *** 2a/: Ey ikinci Abdullah: Atılıyor gün gibi Ve ürkünç hudutlara aşikar… Bir münzevi yaylada doğ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/14-abdullahlar-tarihinde-darbe-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '14 Abdullahlar Tarihinde Darbe: 3', '14-abdullahlar-tarihinde-darbe-3-ahmet-yozgat-mm3om', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1/:

Saltanatta üçüncü Abdullah…

Ah...Ah! 

***

3a/:

Ey üçüncü Abdullah:

Her şey kanat dökmesiyle başlıyor

Zamanı oynatan Harran horozlarının

Son Abdullah.. 

Piramitlere oyuyor üçgene tutsak gözlerini

İrisine kiraladığı gölge ise... 

Sadme karşısında esrik sözlerini emiyor

Ömrün ve ucunda durduğun aşkın.

Darbeyi beklemede yorgun ay.

Vay Abdullah vay! 

3b/:

Tarihin o son gününde

Yaklaşmakla kamaşır gözü.

Ya da yaklaşan nabzıdır yıldız yerinin

Yani efsunlu koyungözleri açıyor türkülerde

Korkunç ve demirkazıklı devler devriliyor

Temreninde türküler açan ateş bahçelerinde.

Söylesen de... Ya da sussan da bu an

Boyutlar yay gibi geriliyor

Abdullah gâh ölüyor arkaya

Gâh öne diriliyor...', '1/: Saltanatta üçüncü Abdullah… Ah...Ah!  *** 3a/: Ey üçüncü Abdullah: Her şey kanat dökmesiyle başlıyor Zamanı oynatan Harran horozlarının ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/14-abdullahlar-tarihinde-darbe-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '14 Abdullahlar Tarihinde Darbe: 4', '14-abdullahlar-tarihinde-darbe-4-ahmet-yozgat-p67mf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '1/:

Saltanatta dördüncü Abdullah…

Ah...Ah! 

***

4a/:

Ey dördüncü Abdullah:

Rüzgârlara çehre çizen gözlerim

Neden görmez gözlerinde yıldızı? 

Kızı devlere cariye mezatındaki ruhum,

Neden içmez kısrak derunundaki kozmik hızı? 

Ve sarıya kesen her yağız gecede

Raksa kalkmaz hüsban misali seyyarelerle? 

Bilirim, şimdi tan vakti muharipleri arsız,

Kararsız bir ardiyede beklemede kırpık yeleler.

Yani aslanlar ki azı dişi yorgunu su başlarında,

Darbeyi beklemede yorgun ay.

Vay Abdullah vay! 

4b/:

Hüznün saksısında açıyor mesrûr dilberler

Emiyor annesini bir yavru soru

Kapısı gıcırdıyor son ayrılığın

Saadetim metrik metrik eriyor

Abdullah gâh ölüyor arkaya,

Gâh öne diriliyor...', '1/: Saltanatta dördüncü Abdullah… Ah...Ah!  *** 4a/: Ey dördüncü Abdullah: Rüzgârlara çehre çizen gözlerim Neden görmez gözlerinde yıldızı? ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/14-abdullahlar-tarihinde-darbe-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '14 Abdullahlar Tarihinde Darbe: 5', '14-abdullahlar-tarihinde-darbe-5-ahmet-yozgat-7oxb0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '1/:

Saltanatta son Abdullah…

Ah...Ah! 

***

5a/:

Son Abdullah:

Göğsünü emiyor istemesen de

Zamanın rahmine her doğan öfke.

Kanın garkoluyor bahriummana zoraki

Ve geceleyin yıldızların rengine

Kara bir kanat gibi çırpınıyor vade

Yani ağır hasta şimdi yadellerde hasretlik

Çizgisi kırılıyor mütemadiyen sabit altmış üçünün

Fırlatıp boşluğa arzularını

Diz vuruyor topraklara sonun sonu

Darbeyi beklemede yorgun ay.

Vay Abdullah vay! 

5/:

Dağlar gerdan kırıyor: Eyvallah Ya Hu! 

Toparlanıyor hasat tarlalardan tek tek

Rahleyi tedristen  kaldırılıyor ruhlar 

Zamanın son vuruşuyla uçları sivriliyor

Abdullah gâh ölüyor arkaya,

Bir daha öne dirilmiyor...', '1/: Saltanatta son Abdullah… Ah...Ah!  *** 5a/: Son Abdullah: Göğsünü emiyor istemesen de Zamanın rahmine her doğan öfke. Kanın garkoluyor b...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/14-abdullahlar-tarihinde-darbe-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '01 Bal Diye İçtik Zehri Kebire', '01-bal-diye-i-ctik-zehri-kebire-ahmet-yozgat-27epd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '1/:

Kalbe zulüm Kebire...

Bir bendim diyemem gezinen

O eski kobtî parşömen rulolarında.

Kalbe zulüm Kebire,

Sen anlamak istemesende...

Hepimiz bir bendik aslında mağrur.

Küçültemedik özümüzü kul diye

Takıldı yüreğimiz son hudutta dikenli bir tele

Sevdalarımız yüzü koyun devrildi.

Hüzün aktı gözümüze ayın memelerinden beri

Emdik… 

Emdik bal diye sunulan zehri.

2/:

Kalbe zulüm Kebire,

Sen anlamak istemesende...

Sebepsiz değildi o sonbaharda

Baldıran köklerinin izinsiz büyümesi

Belki çınarlar döktü yaprağını yol diye

Bir eylül akşamüstü yaşadık koyun koyuna

Ve ellerimize bereketli bakır bakraçtı sanki hediye.

Emdik… 

Emdik sunulan zehri bal diye.

3/:

Kalbe zulüm Kebire,

Sen anlamak istemesende...

Cemreler sağıldı mermerlere zamansız

Kahinlerin kehaneti yüz bin kere dürüldü... 

Hamaylılar döndü yıldızlı pencerelerden

Analar zılgıt ile doğurdu kendilerini

Bebeler bekleşedurdu benle beraber

Cesur ve atak bir atlıydı... Hayallenen halbuki

Belki de kağnılar üstünde mermi

Bebeler ve çarıklı genç anneler,

Emdiler… 

Emdiler bal diye sunulan zehri.', '1/: Kalbe zulüm Kebire... Bir bendim diyemem gezinen O eski kobtî parşömen rulolarında. Kalbe zulüm Kebire, Sen anlamak istemesende... Hepim...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/01-bal-diye-ictik-zehri-kebire-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '01 Kız Enerat eneraT', '01-kiz-enerat-enerat-ahmet-yozgat-zjezp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '1/:

Bir su içerim ben eneraT...

Yalnız ve yağmur ormanı gözlerinden

Avuçlarında uyurum cennet kuşu mırıltısıyla.

EneraT… Ah eneraT! ...

Bir cıgara yapıp beş köşeli, kulak arkama

Yaslanırım tiryaki yıldızlara...

Uyurum suların anne damağı şırıltısıyla...

***

Bir su eneraT...

Bir su içerim yalnız gözlerinden.

şakağında ter devesi olurum.

EneraT… Ah eneraT! ...

Derinden... Ve kaygulu bir arslan gibi

Dolanırım değirmen direkleriyle dururum

Çıkamam yüreğimin kafesinden,

Nefesimden bile korkarım sensizken...

***

Bir su içerim ben eneraT...

Bir de asabi ellerinle kırdığın

Aniden bir perşembenin sokulganlığını...

EneraT… Ah eneraT! ...

Tırnak aralarında arama beni

Sor albümdeki en son kareye

Dur eneraT! Söyle nereye böyle yayanyapıldaşk? 

Yalnız ve çaresiz bırakıp beni böyle geriye?', '1/: Bir su içerim ben eneraT... Yalnız ve yağmur ormanı gözlerinden Avuçlarında uyurum cennet kuşu mırıltısıyla. EneraT… Ah eneraT! ... Bir ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/01-kiz-enerat-enerat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '01 Ben Öğretmenim', '01-ben-ogretmenim-ahmet-yozgat-h2t1l', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'a/:

Vurulan sensen, düşen sen

Eğer yardım istemişsen –veya istememişsen–

Kızıl kanda da olsa ellerim... 

Koşar gelirim

Çünkü ben öğretmenim! 

b/:

Benim üstümedir

En güzel şiirleri kalemin.

Erişilmez olurum yıldızların oralarda bir yerde,

Derde yanar, gama göynür yüreğimin her karesi.

Döğülen sensen, düşen ben

Sana erişebileceğim yerde dururum

Dünyam sen

Seni görürüm ensemde gözlerimden.

***

Sade benim üstümedir

En leylâk tonlu lacivert fotoğraflar

Yakada rozet... Elde pankartım ipek yolunda

Ama... Kızıl kanda da olsa ellerim

Koşar gelirim

Demişsen ki “Yetiş öğretmenim”

İşte ellerim... Ben öğretmenim

Çünkü ben seninim! Çağır gelirim! ...', 'a/: Vurulan sensen, düşen sen Eğer yardım istemişsen –veya istememişsen– Kızıl kanda da olsa ellerim...  Koşar gelirim Çünkü ben öğretmenim!...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/01-ben-ogretmenim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '01Haşiş Cemahiriyesini Melikesi Vildane+', '01hasis-cemahiriyesini-melikesi-vildane-ahmet-yozgat-x1yoa', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '1/:

Yasak bakışlarıma binip bir sabah

Kimsesiz ve habersizcesine...

Usulca dalıversem turkuvaz gözlerinin dibine,

Bekle beni Alamutta...

Ey Haşiş cemahiriyesinin melikesi Vildane...

***

Toza batsa toynağım Horasan yollarında yani ipekten...

Bir yorulsam, bir yorulsam ki sormayın,

Ilık Isfahan hamamlarında terlesem ah! 

Ve  bir sabah, selam sana Alamut! 

Vakit erken, Hasan Sabbah’ın henüz patlamamışken esrarı

Zamanıdır şimdi gizli işlerin sayın ki kaynar kurnaların önü kadın tarlası

Ki onların göğüsleri buram buram kevser sütü buhurdanı firdevsten. 

İşte, kıskanışım bundan seni herkesten...

Beşli çatma belikleri şahmaranım ey! 

Zamanıdır be, dalıversem turkuvaz gözlerinin dibine,

Ey Haşiş diyarının melikesi Vildane...

***

Sonra yine küheylan, yine doru ve yine yılkıdan aparılmış...

Ucu kırılmış bir Sarıkamış kılıcı, ustası palabıyıklı...

Yırtıp hayalimi bir çarşaf gibi dibine kadar Horasanın

Yasak, evet bilirim ki yasaktır Ademe cennet ama,

Arzu işte, Kamber diye bir adamdan hediye...

Kayalar mı doğurdu sizi ey yeşil yosunlar? Üfleyin yüreğime...

Yoksa omuz omuza şu kaçak harmanı dağlar...

Etmeyin bire yanık yüzlü ağalar. Etmeyin zalım beğler.

Gözlerim onsuz neyler bu nisanda ve Alamut’un pusunda? 

Onsuz n’ider bilemem ki ıpıssız gecelerim ey! 

Zamanıdır aslında yusyuvarlak bir burca usulca tünemenin,

Ah ki ah, yani bir dalıversem turkuvaz gözelerinin dibine,

Duy artık beni, Haşiş diyarının melikesi Vildane...

2/:

Alamut bir cinayete daha hazırlanıyordu sanırım,

Bir akşamüstüydü; ha karardı, ha kararacak dizlerim

Düş(ü)   yordum kat be kat. Yakaladı bakışlarım son anda

İstedim ki o anda... Haddanede, kızgın potalarda erisem

Yürüsem doludizgin... Sarp cebelde kaygan karı dizleyerek yürüsem…

Eylül hışırtısıyla mart havalarında bir turaç sürüsü.

Ve dikensiz arazilerde ardımsıra bir kısrak yaylası deli toynak

Yeleleri ulu ferman... Kuyrukları kırk bin kere düğümlü

Sonu ölümlü bir koridorda koşmanın arsızlığını bilen var mı aranızda? 

Ah be ah, yine aldı bakışlarımı haşişin esrik dumanı,

Tam karşımda şu an ve tomurcuk memeleri süt buhurdanı…

Marta durmuş toynakları zamansız şahlanmada acımasız fedaiyanın

Bu sıra kapı aralarında sekişen kızların döşleri telaş içinde

İşte, bu benim; Sabbah''ın taht odasında saklı yüreğim,

Zamanı be, o anda dalıversem turkuvaz gözlerinin dibine,

Ey Haşiş diyarının melikesi Vildane...

***

Bura gayya ve burada ben yanarım kime ne? 

Bile yanar bir mart akşamında ağustos... Yanar zemheri,

Fedaiyan, geri basın bre ve uzaklaşın Alamut''umdan,

Zalim bir emirle yakmayın düşlerimin boz bulanık karelerini,

Çözün ellerimi, bağlayın yüreğimi...

Yani etmeyin zalım ağalar... Etmeyin Sabbahoğlu beğleri...

Bırakın bozkırlara ciğerimi ve yedi katlı semaya çırpa çırpa uçurun beni,

Yoksa yosun tutmuş gözlerim... Onsuz neyler gözlerim ey! 

Özlerim Alamutun en daracık mazgalından bakan gözleri...

3/:

Horasan bir yana, Alamut bir yana yaslanır bu şiirde,

Kırılınca kalemim o an, esir düşer bakışlarım zafersiz bir cephede vay be! 

Olur biter her şey sonsuzluğa doğru koşan fettan bir savaşta yani...

Bir anamı özlerim, bir de turacı gökyüzünde; derim ki kendi kendime:

Tam zamanı, Alamutta bir kızıl akşam,

Aha şimdi zamanıdır, ışıklı bir kılıç ya da baldıranla sevişsem! 

Aksa canım... Sihirli nağmeler gibi vaha dibi gözbebeğine...

Hey be, neredesin; ses ver Haşiş diyarının melikesi Vildane...

***

Alamut ki bir esrik adamlar hayalidir, kızıl ve tam da ciğerden

Usul ve utangaç ve zalim yani... Itırlı yaban ağaçları yol kenarınca...

Kahverengi, ucu yanık tasvir gibi duvarlar boylu boyunca,

Baksam birer birer tüm cebel şeyhlerinin sağ gözlerine,

Salyangoz kıvrımı koridorlarında kalenin, yitirsem yüreğimi,

Haykırsam: Hey Vildane! ...

Ben burdayım... Yani Alamut’tayım! 

Olacak, olmalı kız, ben ki şu an asla yitmez bir umuttayım...

Etmeyin dağların kızıl gözlü ağaları... Etmeyin Haşhaşiyun beyleri...

Germeyin ufkuma öfkeli bedeninizi,

Ben ki amet yozgati yani mongolyan karahitaylarından,

Ellerinizi çekin Alamut kalesinin mazgallarından.

Yoksa gözlerim onsuz neyler? Neyler onsuz ey! 

Ya da bensiz neyler Vildane? 

Şiir olur virane...

***', '1/: Yasak bakışlarıma binip bir sabah Kimsesiz ve habersizcesine... Usulca dalıversem turkuvaz gözlerinin dibine, Bekle beni Alamutta... Ey ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":85,"source_url":"https://www.antoloji.com/01hasis-cemahiriyesini-melikesi-vildane-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '00 Asuman’a Postzamanlama: 000651', '00-asuman-a-postzamanlama-000651-ahmet-yozgat-0vgup', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nano Teknik Atlantis

x/:

Sisler sarmış başımı Ey Asuman…

Dumanlıyım... Esrik öylesine

Eski bir Katalan şarabını yudumlamalıyım

Veya ölmeliyim gere gere dünyamı

Veya o imkansız huruçta kalmalıyım

Veya kadim rahiplerin tutunup ellerine

Ya da son anda yosun kokan harmanilerinin

Nano metalik ve kabaralı peşine

Dolanmalıyım Asuman...

Yani Atlantis’in sonsuzluk tavafına dalmalıyım.

y/:

Sisler sarmış başımı Ey Asuman …

Uyanmalıyım... Öylesine mahmur ve esrik

Ya kurtulmalıyım devrilen antik kolonların kahrından

Ve kozmik hışmından ak delikli semaverlerin.

Uzun sözün nanosu Asuman,

İronik zeminlere yüzükoyun çakılan

Muğlak ve kader üzre

Kızılötesi bir aşkla çalkalanan okyanustan.

Ve köpüren öfkesinden yeri çivileyen dağların

Dönüp duru ter sızan enseme ya da

Kurtulmalıyım Asuman... 

Veya habire mağma gözelerinde yanmalı

Kebire dayanmalıyım…

Sisler sarmış başımı Ey Asuman …

Karşımda ipildeyen şu mutlak ışığa uzanmalıyım.

Yani delip imkansızın kalbini hapseden zırhı

Nano teknik Atlantis’e varmalıyım...', 'Nano Teknik Atlantis x/: Sisler sarmış başımı Ey Asuman… Dumanlıyım... Esrik öylesine Eski bir Katalan şarabını yudumlamalıyım Veya ölmeliyi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/00-asuman-a-postzamanlama-000651-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaybolan Kişi', 'kaybolan-kisi-tahmine-yildirim-qfc49', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hıçkıra hıçkıra ağlayan

kahkahalarla gülen

yürekten içten hüzünlenen

çilekeşler gibi gün geçiren

parasını sere serpe kullanan

karanlıklara kapanan

aydınlıktan nefret eden

kendi kendine konuşan

dünyayı gözü görmeyen

kendinden bile nefret eden

kırmızı gülü sevmeyen

dağ başından bağıran

sevmeyi aşağılık sayan

sevilmeyi bir hiç gibi gören

kendini kalabalıkta bile yalnız hisseden

pskiyatristleri kendine meken tutan

kimdir bu zatı muhterem varmı bunu bilen.....

                                                                    Kasım           1995', 'Hıçkıra hıçkıra ağlayan kahkahalarla gülen yürekten içten hüzünlenen çilekeşler gibi gün geçiren parasını sere serpe kullanan karanlıklara k...', ARRAY['Türk Edebiyatı','Şiir','Tahmine Yıldırım']::text[], 8.5, '{"poet":"Tahmine Yıldırım","poet_slug":"tahmine-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kaybolan-kisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Uyuyordun', 'sen-uyuyordun-kamil-soylemez-8j512', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözlerimi aklımla yordum

Uyuyordun...

Yüreğim sana açık

Rüzgarım telaşlı

Susuyordum 

Gönlüme yağıyordun

Yanağıma...

Gözüme yaş damlıyordun

Tenime zımpara

Kızarıyordum sen ateşim karşısında

Üşüyordum...

Ellerimi koltuklarıma koydum

Çözülmüyordun

Başında seni sorgulayanlara

Seviyorum ben diyordum 

Sen susuyordun

Girdabı oluyordun,içimdeki sevdamın

Dönüyordum aşkınla durmadan

Köy,köy,kasaba,kasaba gölgendim sana

Bir nehirdim....

Çılgın bir nehir

Sen sevda okyanusum

Sana ulaşmaktı,çırpınışım

Sana tutuldum

İçim yanıyor,dokunamıyordum

Gizemine takıldım

Gözlerine..

Dilin ince tenine

Sen duymuyor uyuyordun

Uyuyordun.....!', 'Gözlerimi aklımla yordum Uyuyordun... Yüreğim sana açık Rüzgarım telaşlı Susuyordum  Gönlüme yağıyordun Yanağıma... Gözüme yaş damlıyordun T...', ARRAY['Türk Edebiyatı','Şiir','Kamil Söylemez']::text[], 8.5, '{"poet":"Kamil Söylemez","poet_slug":"kamil-soylemez","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/sen-uyuyordun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bağrımdasın Derin Mavi', 'bagrimdasin-derin-mavi-kamil-soylemez-ujtri', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dalga,dalga sevdamsın bağrıma vuran

Derin mavi yaram…

Yosun kokulu sabahım

Sahilimsin, adımladığım

Bırakıp,giderim sen kıyılarında

Düş kurarım gelecek adına 

Sen ile koşaken buluttan kısraklar

Yılların son açan papatyasında

Turkuazın ağzı dolusuyla

Burukluğun altın vuruşu olur yokluğun ansızın

Bir yıldırım düşer 

Bir kiyahi ten rengi öper gözlerimi

Aldanırım sonra,aldanırım 

Çöl bedevilerinden bir tas suya

Zülüf teli düşürürüm çöl toprağına

Güneşse meyin kaynatmakta

Sen gelmediğin gün sabah ışığımla

Dağılır gonca gönül 

Bir girdap honisinde

Saydamın cam yeşili rengi düşer

Sen giysilerin rüzgar süzümünde

Özlemin gökkuşağı,alın yazım

Ah sevdam sen neler yaşattın bana

Daha neler yaşatacağında gelmiyor yakınıma

Deniz kabuğu

Kestanesi dikenleri bağrımda

Sen acımsın tatlı kaçığı yapanım

Deniz yıldızım...

Sen bağrımda yollanan sarı sandalım

Yeşilin tüm tonu sende

Kırmızının gelinciği

Papatyanın beyaz ve sarı sandalı

Benim içinde derin mavileri dolaşan

Benim beyaz yelkenim

Melteminle sarhoş edenim

Yeter desem,yeter şu ayrılık

Haydi çıkta gel derin mavi sevdam

Tan yeri ağarmadı sen yanımda olmadan

Bülbüllerim ötmedi,sensiz bu yerler yavan

Boşluğun bir anlamı olmalı

Yokluğun vardan ayrıcalığı

Sundurmasına durmuş bu gönül 

Sen sevdamın gönül yamacında

Çığlık,çığlık bir atmacanın

Bir kartalın yalçın kayalığında

Gönül işçisi bu yürek

Toprak kokar her yanı,yağmurda

Tırpan biçer yüreğim,sen sevdan ile dağlarda

Artık suskunluk düşsede zamanda

Düşürmek yok yüreğim firarda 

Çatlasada dudaklarım,öpmek yok başkasını

Su diye yalvarmak yok başka buselere

Son nefesimde olsa senin ellerinde ellerim

Bil ki kabülümdür,sen ince narin ellerin

Tut şimdilerde ellerimi uçurt derin mavim

Uçurt çocukluğumda uçurtmanın tentenesi yüreğim

Durulsun bu fırtına

Durulsun derin mavi bağrımda', 'Dalga,dalga sevdamsın bağrıma vuran Derin mavi yaram… Yosun kokulu sabahım Sahilimsin, adımladığım Bırakıp,giderim sen kıyılarında Düş kurar...', ARRAY['Türk Edebiyatı','Şiir','Kamil Söylemez']::text[], 8.5, '{"poet":"Kamil Söylemez","poet_slug":"kamil-soylemez","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/bagrimdasin-derin-mavi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdayı Çeken Ben Beni Çekense Sen Meleğim', 'sevdayi-ceken-ben-beni-cekense-sen-melegim-kamil-soylemez-l4087', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Düşlersem sen benimsin

Özlersem,küsersem benim

Sevdayı çeken ben

Beni çekense sen,meleğim

Sokaklar benim sen yokluğunda

sabahı uyandırırım gecenin koynundan

Seni ararım sonra,saatin ilk buçuğunda

Gözlerin,gamzelerin,gülüşün,ışığında

Bir koşuşturmayım şimdi istanbul da

En kalabalık saatin atımında

Silah atar gibi yürüyemem 

Gözlerim buğusu seni aramalarımdan

Nefes,nefese kalmalarım sen arayışımdan

Bir garip,hüzün su içer içim çıkrığından

Kimseleri benzetemem sana

Ağlarım ben aslında

Kimseler görmez

Sade ve sükutum cadde,sokak arasında

Cezaevi tutuklusu düşlerim

Bir idam sehbahası,bekleyen beni oysa

Yokluğun geçimsiz çığlığıyla

Bir keleşin patırtısı dağlarım

Bir dipcik acısı,sırtladığım

Kaburga kırılışı sancılarım olur benim

Kafama sıkılan mermi

Yüreğime işlemeli hançer

Ve sen kalemimsin asi 

He desen vurup,giderim bu şehri

Benim seni özlediğim gibi

Bilirim sen de özleyeceksin gidince beni

Ve sokaklar gaddar,zemheri

Bu şehri,bu teni ısıtan sen 

Yüreğimde daha her şey dün gibi 

Ve ana gibi sıcak

Bir okadar kucaksın,tenim devrimi

Sana neler söylesem

Unuturmusun beni, gerçekten

Unutabilirmisin sevgimizi

Gözlerimizi bıraktığımız derin maviyi

Çıkıp gelsen uyuyacak belki

Yakındır bilirim sen gelmezlerinde beni terk edeceği

İçimde şehirlerin saklı kente dönüşeceği

Şehirlerin kuşatılıp,yok edileceği yakın

Dağlarım kurşunlanıyor şimdi

Ve sokaklar ıslanıyor göz yalarımla

Bu can sensiz ölüyor,sonra

Şimdi sensiz karanlığım

Senin teninde aydınlık

Ve seninle bu can süslenecek

Tenim,çiçek,çiçek..

Ben sevda işçisiyim...

Sevda işçisi

Sevebilirmisin sende, seni ben gibi', 'Düşlersem sen benimsin Özlersem,küsersem benim Sevdayı çeken ben Beni çekense sen,meleğim Sokaklar benim sen yokluğunda sabahı uyandırırım g...', ARRAY['Türk Edebiyatı','Şiir','Kamil Söylemez']::text[], 8.5, '{"poet":"Kamil Söylemez","poet_slug":"kamil-soylemez","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/sevdayi-ceken-ben-beni-cekense-sen-melegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Boşuna Değilsin İstanbul', 'sen-bosuna-degilsin-i-stanbul-yavuz-bayram-caliskan-7h2l7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Güneşleri batırdığım boğaz,  gülüşümdür,

Altın boynuz Haliç, sesine gelişimdir,

Ayasofya tarih oluşumdur,

Sen boşuna değilsin İstanbul.

Trenler çekilir Haydarpaşa’dan,

Çiçek pasajında gelir sesler şişeden,

İstiklal caddesinde yürür insan neşeden,

Sen boşuna değilsin İstanbul.

Gemiler, suları, yarar durur,

Hisarlar, surlar, tarihi korur,

Âşıklar Gülhane’de hazlara varır,

Sen boşuna değilsin İstanbul.

Sularında martılarla, balıklar oynaşır,

İnsan seli birbirine kaynaşır,

Kin tutmaz, kar tutmaz, şehirlere yaraşır,

Sen boşuna değilsin İstanbul.

Marmara’da yüzer Kız kulesi,

Her iki yakada, hisarı, kalesi,

İhtişamlıdır Galata Kulesi,

Sen boşuna değilsin İstanbul.

Sultan Ahmet, Topkapı, Eyüp Sultan,

Fatih’le huzur bulur, Karaca Ahmet’te yatan,

Yıldızlardaki güzelliği içine katan,

Sen boşuna değilsin İstanbul.

Ata’mın yaşadığı Dolmabahçe’si,

Florya, Yeşilköy, yaşar hep sesi,

Sanki bir çiçeğin taze busesi,

Sen boşuna değilsin İstanbul.

Her bir değerin anlatmakla bitmez,

Asırların şehri İstanbul çağlarla yitmez,

Avrupa’ya, Asya’ya, dünyaya yetmez,

Sen boşuna değilsin İstanbul.', 'Güneşleri batırdığım boğaz,  gülüşümdür, Altın boynuz Haliç, sesine gelişimdir, Ayasofya tarih oluşumdur, Sen boşuna değilsin İstanbul. Tren...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/sen-bosuna-degilsin-istanbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yokluğun Renkleri', 'yoklugun-renkleri-muhammed-mehmet-gul-0r3zc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gün aşırı bir vakitte ufuk kızıl kızıldı

Yokluğa yolculuk apansız kapıma dayandı

Kaçmaya tedbir almaya bile gerek duymadım

***Gelişi öylesine pervasız öylesine ayan beyandı

Ortalık sütliman deyil kıpkırmızı yangın yeriydi

Ekmek yandı güller yandı denizlerde su yandı

Ben varlığımın peşinde doludizgin koşarken

***Bütün renkler sırayla yokluğa boyandı

Azıksız çıktığım yokluğun bu son seferinde

Gün doğuşuyla karşıma çıkmaz çöller uyandı

Yokluğun rüyasına yok yok diyerek yatarken

Şöyle bir maziye baktımda sadece bir andı.', 'Gün aşırı bir vakitte ufuk kızıl kızıldı Yokluğa yolculuk apansız kapıma dayandı Kaçmaya tedbir almaya bile gerek duymadım ***Gelişi öylesin...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Mehmet Gül']::text[], 8.5, '{"poet":"Muhammed Mehmet Gül","poet_slug":"muhammed-mehmet-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yoklugun-renkleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi yolculuk', 'mavi-yolculuk-nazan-i-zmirli-7v3u1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '18 mart öncesi

 ruhlar  sıkışmakta

 mavi   mora  dönmekte  usulca', '18 mart öncesi  ruhlar  sıkışmakta  mavi   mora  dönmekte  usulca...', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/mavi-yolculuk-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşka hasret katanım', 'aska-hasret-katanim-seref-ozturk-usta-l7o1s', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aşka hasret katanım

.....yüreğimdir 

........vatanın.

Gel demen 

.....sevmen gibi mi? 

........adamca.

Kavuşmak hasrete

.....kucaklaşmak vuslata 

........ son verir anca.

Bilsen

..... tuz buz olan 

........ gururumu

Düşünmezdin 

.....aşkta çöken 

........ onurunu.

Hakkımız yok

..... aşka eza etmeye

........ kalbe ceza kesmeye.', 'Aşka hasret katanım .....yüreğimdir  ........vatanın. Gel demen  .....sevmen gibi mi?  ........adamca. Kavuşmak hasrete .....kucaklaşmak vus...', ARRAY['Türk Edebiyatı','Şiir','Şeref Öztürk Usta']::text[], 8.5, '{"poet":"Şeref Öztürk Usta","poet_slug":"seref-ozturk-usta","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/aska-hasret-katanim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuğa Gülmek Yaraşır', 'cocuga-gulmek-yarasir-derya-akgun-dg45f', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '2006 Yılı Milli Eğitim Müdürlüğünün düzenlediği “Öğretmen “ konulu yarışmada ilçe 3.sü “Çocuğa Gülmek Yaraşır”(Şiir)      

Zümrüt Gözlü 

Tatlı Tuğberk''ime...

Çocuğa Gülmek Yaraşır

Dışarıda ayaz var; 

Ama benim yüreğim yanmakta,

Gözlerime uyku inmiş yavaş yavaş...

Beynim direnmekte inatla.

Gözlerimi kapıyorum,

Hayalin beni yormakta.

Yemyeşil gözlerinden akan yaşlar,

Zihnimi oymakta.

Niye ağlar bir çocuk? 

Gülmesi gereken en güzel çağında.

O güzel gözlerine,

Bu yaşlar hiç yakışmamakta...

Ağlama zümrüt gözlüm! 

Hiç bir zaman ağlama! 

Ağlayıp da yorgun yüreğimi dağlama! 

Sen bilemezsin yavrum,

Senin tek damla gözyaşın,

Benim yüreğimin yangınıdır.

Öyle bir alevdir ki o

Uykularımın karabasanıdır....

''Gülen'' sıfatı seninle güzelleşir.

'' Neşe'' ismi seninle özdeşleşir.

''Sevgi'' seninle yüceleşir,

''Gülmek''sizlerle eylemleşir.

Bırak gökler ağlasın

Toprak münbitleşsin diye.

Günahkarlar ağlasın günahlarına

Ama sen ağlama

Benim gıdam senin sevgin

Suyum gülüşündür.

Sen güldüğünde bahar gelir gönlüme

Güller açılır burcu burcu yüreğimde.

Dünya bir başka güzel olur senle,

bir nazenin yürek kanatlanır, bir martı neşesiyle.

Getir at kederlerinin tamamını bana,

Sen dayanamazsın ama; 

Ben dağ olur yine de dayanırım,

Senin için her acıya

Yüreğim asude bir liman olsun

Hem sana, hem diğer yavrularıma

Bir çocuğa gülmek yaraşır yavrum,

Dünyaya güneşin,

Çiçeğe rengin,

Anneye şefkatin

Öğretmene sınırsız sevginin,

Doğan her yeni güne umudun yaraşması gibi,

Sana da gülmek yaraşır.

Ve şunu da asla unutma:

''Dünya çocuğun gülüşü ile güzelleşir.''

Öğretmen bu güzellikle ölümsüzleşir.', '2006 Yılı Milli Eğitim Müdürlüğünün düzenlediği “Öğretmen “ konulu yarışmada ilçe 3.sü “Çocuğa Gülmek Yaraşır”(Şiir)       Zümrüt Gözlü  Tat...', ARRAY['Türk Edebiyatı','Şiir','Derya Akgün']::text[], 8.5, '{"poet":"Derya Akgün","poet_slug":"derya-akgun","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/cocuga-gulmek-yarasir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnancın Destanı...', 'i-nancin-destani-omer-golge-ny1yd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir başka parlıyordu o sabah doğan güneş

İnancın destanına şehadet etmek için

Şehitlerin kanları,karışarak sulara

Vurdu Çanakkale''ye aşılmaz çelik perçin

Yedi kat gökten inip...

Alem-i melekûtun günahsız sakinleri

Anlayıp ta Adem''e secdenin hikmetini

Hayretle seyrettiler o arslan Mehmet leri

Her biri, bir Hamza''ydı göğsündeki imanla

Gözlerinde Hayber''in Uhud''un anıları

Murteza''da oradaydı elinde Zülfikarla

Öldürerek ölümü imkansızlık içinde

Ebedi bir hayata orda adım attılar

Vatanın her yerinden o dağ gibi yiğitler

Bu asrın destanına kanlarını kattılar

Türkü''yle,Kürd''üyle,Laz''ıyla Çerkez''iyle

Yekpare vatan olup o günün sabahında

Mertliğin manasını dünya ya anlattılar

Bu gün Çanakkale''de gördüğün bütün âsâr

Hissetiğin o koku yüzüne vuran rüzgâr

Tekbir sesleri gibi hışırdayan yapraklar

Ölümsüz hayatların dünyasından fısıldar

Hatırlatırcasına,soluyan ölülere

Yaşam hakikatini,son derce mânidâr

Bir diriliş beklemekte bu mûbarek topraklar

Yeniden yudumlayıp,hürriyetin o doyumsuz tadını

Geçerek ölüm denen bu zorlu imtahandan

Yazıp Ârş-ı âlâ''ya inancın destanını 

Sen! bu vatanın,bu toprağın evladı

Sen! bu cehennem yürekli neslin yiğit ahvâdı

Eminim bozamazsın,asla bozmayacaksın

Ceddinin bu toprağa kanla yazdığı andı..', 'Bir başka parlıyordu o sabah doğan güneş İnancın destanına şehadet etmek için Şehitlerin kanları,karışarak sulara Vurdu Çanakkale''ye aşılmaz...', ARRAY['Türk Edebiyatı','Şiir','Ömer Gölge']::text[], 8.5, '{"poet":"Ömer Gölge","poet_slug":"omer-golge","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/inancin-destani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel ha gönül..', 'gel-ha-gonul-veysel-siltag-pnkkv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gel ha gönül havalanma, kalkıp yürüme.....

Gün olur sevdanı dağlar,  dağlar....

Dertlinin derdinden, dertsiz anlamaz....

Dertsiz anam olsa, boşuna ağlar....

Boran yağar gönül evine, kalırsın kışta....

Ayaz vurmuş sinene, donakalırsın yazda....

Maharet baştadır, değildir saçta....

Mertlik neylesin ki, zihni namerd olan puşta......

Dedim gönül sevdam yaramdır  kanayan....

Ruhum kapamış gözlerini, göremez önünü, bulamaz yolunu.....

Bir bilinmeyenin esiri olmuşum, gönlüm aşiyan.....

Dünü bilinmeyen ömrüm, bilemez elbet sonunu......', 'Gel ha gönül havalanma, kalkıp yürüme..... Gün olur sevdanı dağlar,  dağlar.... Dertlinin derdinden, dertsiz anlamaz.... Dertsiz anam olsa, ...', ARRAY['Türk Edebiyatı','Şiir','Veysel Sıltağ']::text[], 8.5, '{"poet":"Veysel Sıltağ","poet_slug":"veysel-siltag","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gel-ha-gonul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çanakkale zaferi', 'canakkale-zaferi-mikdat-bal-d6q76', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her şeyi hesaplayıp yurdumuzu böldüler

Bizi yok etmek için sürülerle geldiler

Türk’ü tanımadılar gafletlere daldılar

Mehmetçiği görünce kanı dondu kurudu

Mehmetçik şehit oldu vatanını korudu

Düşmanlar tekniğiyle işini kolay sandı

Her taraf cehennemdi ateş barut ve kandı

“Çanakkale geçilmez” o ne müthiş destandı

Can verdi Mehmetçikler vatanını korudu

“Ya ölüm Ya istiklâl” buydu şartı şurutu

Cephede her yer müthiş, kan barut kokuyordu

Mehmetçik mermisizdi süngüyü takıyordu

Ölüme emir almış dualar okuyordu

Taarruz için değil ölmek için yürüdü

Düşmana dehşet saldı vatanını korudu

İşte böyle ölümü ölümsüzlük bilmişler

Ne engin iman gücü, ölürkende gülmüşler

Anladı ki düşmanlar yanlış yere gelmişler

Onları aynı anda büyük korku bürüdü

Bizim şehitler ölmez onlar öldü çürüdü

Der Mikdatî askerin her biri bil ki zahit

Cengaverce savaştı  vatan uğrunda şehit

Kazanmayı bildiler imanlarıydı ahit

Şadolsun ecdadımız vatanını korudu

Ölen düşmanları da Mehmetçikler kürüdü', 'Her şeyi hesaplayıp yurdumuzu böldüler Bizi yok etmek için sürülerle geldiler Türk’ü tanımadılar gafletlere daldılar Mehmetçiği görünce kanı...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/canakkale-zaferi-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hocam..!', 'hocam-mehmet-goden-tfrlc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kalemini eline aldıran Kudret,

Yüreğine sevgi doldurmuş Hocam,

Kendi kendisine çıkan Gül''e ne kıymet! 

Verilmişki verilsin de hele Hocam.

+

Yoksulun varlısından,vardırki farkı,

Birileri dönderip,duruyor çarkı! 

Çıkarlara göz kapa, sen yeterki! 

Bu Dünya Cennetten iyidir Hocam.

*

Bize kalan sevmek oda ucuzu! 

Ya mahallenin yollusu, ya bakkalın kızı,

Felek vermiş eline gozu,Papazı,

Nimetleri haketmeyen,topluyor Hocam,

*

Yaşamaksa en altlarda bir yerde,

Kimse ''gık'' diyemez,erkeksen bir de! 

Güç iktidar onlarda Allah bizdende,

Yargıç karar bağlıyor aleyhte Hocam.

11.03.2006', 'Kalemini eline aldıran Kudret, Yüreğine sevgi doldurmuş Hocam, Kendi kendisine çıkan Gül''e ne kıymet!  Verilmişki verilsin de hele Hocam. + ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Göden']::text[], 8.5, '{"poet":"Mehmet Göden","poet_slug":"mehmet-goden","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hocam-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tut*yut', 'tut-yut-umit-tuna-qpf1d', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aşk canımı yaktı benim,

Bu yüzden üstün başım yanık kokar,

Her yerimde yanık izleri var! 

Kalbimi tutup sevip okşaman lazım,

Yanıklarımın üzerini bir merhem gibi örtmen gerek,

Cesaretin varsa elbet.

Çırpınan kalbimi tut, avut

Bir anda olsa geçmişi unut,

Cümleleri düğüm düğüm yut,

Cesaretin varsa,

Ellerimden tut! ...

ÇILGIN MUHASEBECİ', 'Aşk canımı yaktı benim, Bu yüzden üstün başım yanık kokar, Her yerimde yanık izleri var!  Kalbimi tutup sevip okşaman lazım, Yanıklarımın üz...', ARRAY['Türk Edebiyatı','Şiir','Ümit Tuna']::text[], 8.5, '{"poet":"Ümit Tuna","poet_slug":"umit-tuna","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/tut-yut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman kalmadı..!', 'zaman-kalmadi-mehmet-goden-2zre7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Öyle bir ateşki düştüm içine,

Yakıyorda suna boylum yakıyor,

Hayellerim zaman ile elele,

Akıyorda uzaklara akıyor,

°

Ne güzeldi daha dünkü çocukken! 

Şimdi yaş sorulsa! derimki erken,

Ecel bekler kapıda,bizim felekten,

Çaldığımız tatlı günler bitiyor,

*

Yüzüne bakıpta aynaya kızma! 

Derin izler vardır,kafaya takma! ,

Sarmaş dolaş bir bedende olupta,

Sevdalar yaşayacak an''lar bitiyor,

*

Büzüldüde tenimizde şu deri,

Zamanı kandırıp,dışımdan atsam kendimi,

Alemde tek benmiyim? bir görsem,hani! 

Sevip sevilmeden kimler gidiyor,

*

Kim geldi kim göçtü bu koca han''dan,

Yoğrulmuşuz! bastığımız topraktan,

Gemiler ayrılırken ''sessiz'' Limandan,

Candan, cananından kimler geçiyor.

21.02.2006', 'Öyle bir ateşki düştüm içine, Yakıyorda suna boylum yakıyor, Hayellerim zaman ile elele, Akıyorda uzaklara akıyor, ° Ne güzeldi daha dünkü ç...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Göden']::text[], 8.5, '{"poet":"Mehmet Göden","poet_slug":"mehmet-goden","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/zaman-kalmadi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine..!', 'yine-mehmet-goden-jiljm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yine..! 

Sıra sıra göçmen kuşlar uçsunlar

Baksınlar, anacığım yasta mı yine

İnip, birer birer hatır sorsunlar

Nasıl perişan mı, hasta mı yine.

+

Ağıt yakar görünce, göçen kuşlara

Türkü söylüyor mu dağa taşlara

Ak düşmüş mü, örme gibi saçlara

Bakın gözlerine, yaşta mı yine.

*

O türküyü duymaz, dağlar borandır

Kardadır şimdi daz, kış`ta virandır

Tahtırı Kösürü sis ve dumandır

Umudu hayali, puslu mu  yine.

*

Denize küskün mü, bakmaz maviye

Ne dertler çekmiş atmış sineye

Sorarsa,  oğlunu gelir seneye

Yolları gözlerken, yaslı mı yine. 

*

Kimler icat etmiş şu gurbet eli

Kimi mecnun etti, kimini deli

Yıllar yük vurdu da, eğdi ki beli

Değnek, bahçedeki dutdandır yine.

Mehmet Göden,Mayıs 2005.', 'Yine..!  Sıra sıra göçmen kuşlar uçsunlar Baksınlar, anacığım yasta mı yine İnip, birer birer hatır sorsunlar Nasıl perişan mı, hasta mı yin...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Göden']::text[], 8.5, '{"poet":"Mehmet Göden","poet_slug":"mehmet-goden","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yine-235-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Tat Var mı', 'bir-tat-var-mi-yusuf-onder-bahceci-g71i1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Senden ayrı yaşadığım bu Dünya''da,

Bir tat var mı, soruyorum şimdi sana,

Özlemle bakarım da geçtiğin yollara,

Senden ayrı yaşadığım bu Dünya''da,

Bir tat var mı, soruyorum şimdi sana.', 'Senden ayrı yaşadığım bu Dünya''da, Bir tat var mı, soruyorum şimdi sana, Özlemle bakarım da geçtiğin yollara, Senden ayrı yaşadığım bu Dünya...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/bir-tat-var-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Nasıl Sevmek', 'bu-nasil-sevmek-mehmet-sait-akkus-ac3ff', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben yanarım sen yanmassın

Ben sorarım sen sormassın

Ben ağlarım sen gülersin

Ben hüzünlüyken sen oynarsın

Bu nasıl sevmek anlamadım

Seni kalbime yazaeken

Sen suya yazarsın beni

Ben kuru dala konarken

Sen yeşil dala konarsın

Senin için uykusuz kalırken

Sen mışıl mışıl uyursun

Bu nasıl sevmek anlamadım

Ben burada kan ağlıyorum

Sen orada şarkılar söyle

Acılarını topluyorum şimdi

Bahçemdeki gülleri topla

Hasretinden kursağıma ekmek girmezken

Sen kuş sütü masalarda otur

Bu nasıl sevmek anlamadım

Ben senin için ölürken

Al çiçekleri ellerine mezarıma gel

Belki o zaman değerimi anlarsın

O zamanda çok geç olur.....', 'Ben yanarım sen yanmassın Ben sorarım sen sormassın Ben ağlarım sen gülersin Ben hüzünlüyken sen oynarsın Bu nasıl sevmek anlamadım Seni kal...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sait Akkuş']::text[], 8.5, '{"poet":"Mehmet Sait Akkuş","poet_slug":"mehmet-sait-akkus","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bu-nasil-sevmek-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Gözlerinle Görseydin', 'guzel-gozlerinle-gorseydin-yusuf-onder-bahceci-fra82', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Güzel gözlerinle, ne var sevdim deseydin,

Güzel gözlerinle bana hep ümit verseydin,

Güzel gözlerinle, sevdiğimi görebilseydin,

Güzel gözlerinle, ne var sevdim deseydin,

Güzel gözlerinle bana hep ümit verseydin.', 'Güzel gözlerinle, ne var sevdim deseydin, Güzel gözlerinle bana hep ümit verseydin, Güzel gözlerinle, sevdiğimi görebilseydin, Güzel gözleri...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/guzel-gozlerinle-gorseydin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küpelik söz-3', 'kupelik-soz-3-mehmet-sait-akkus-22qoh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her şeyi parayla satın alabilirsiniz

