INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiirlerim Dua İnan ki', 'siirlerim-dua-i-nan-ki-yusuf-onder-bahceci-h3e9n', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Herşeyinle sevdim seni,

Neden böyle oldu sanki,

Şiirlerim bir dua inan ki,

Herşeyinle sevdim seni,

Neden böyle oldu sanki...', 'Herşeyinle sevdim seni, Neden böyle oldu sanki, Şiirlerim bir dua inan ki, Herşeyinle sevdim seni, Neden böyle oldu sanki......', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/siirlerim-dua-inan-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Yağdı', 'ask-yagdi-piranli-zaza-dluxv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aşk dediklerini

Nisan yağmuru sanmıştım,

''Ahmak ıslatan''mış oysa; 

Anlayamadım...

Aşk yağdı,

Ben ıslandım; 

Ben ıslandım,

Sen yağdın; 

Çok geç anladım...

           16.03.2006

               Ankara', 'Aşk dediklerini Nisan yağmuru sanmıştım, ''Ahmak ıslatan''mış oysa;  Anlayamadım... Aşk yağdı, Ben ıslandım;  Ben ıslandım, Sen yağdın;  Çok g...', ARRAY['Türk Edebiyatı','Şiir','Piranli Zaza']::text[], 8.5, '{"poet":"Piranli Zaza","poet_slug":"piranli-zaza","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ask-yagdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur Altında Islandılar', 'yagmur-altinda-islandilar-dilek-hokkaomeroglu-m8hx0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Umarsız yaşamdan kalan alışkanlıklar

Geride iz bırakan sevdalar,

Umutlar.

Umarsız yıllardan kalanlar''a..............

Ne hoşsun bu gece

Dolunay gibisin.

Yakamozları sen boğuyorsun.

Yakamoz mavisinde gözlerin.

Karanlıklara son verdim.

Yüreğimin götürdüğü yere gidiyorum.

Hasretlerim özlemlerime.

Sevdaya gülle atıyorum.

Dökülüyor yaprak yaprak,

Anılar saçlarıma...

Tutup alnından öpüyorum 

Sevdamın...

Titrek üzgün hazan yaprağı

Yüreğim şimdi.

Dokunma! 

Parçalanacak sanki...

O şimdi bir yasemen

Alıyorum hapsediyorum gözlerime

Yaşasın diye...

Titreyen yaprak yeşile sevdalı

Gecede ay şahit sevdama...

Dudaklarımda heceler.

Ay karanlık geceler.

Sen varsın güzelim tek

O görkemli yıldızlarda parlayan.

Düşlerim şahit sevdama

Yıldızlar düşerken,

Avuçlarımdan avuçlarına

Ellerini tutuyorum.

Sen Ben Ve Sevdamız.

Yürüyoruz...

Gülüyoruz...

Etekler savruluyor

Esaret yürekler dünde kalıyor.

Kırıyor yürekler zincirleri,

Haykırıyor özgürlüğün dili

Sevdasına sargın.

Gözlerinde nem,

Yüreğinde elem,

Büyük sevdaya zafer.

Seni seviyorum...

Seni seviyorum.

Zİncirsiz...

Sevgisine muhtaç dillerin

Özgürlüğüne sarılıyor

Birde sözlerine...

Haykırıyor yürekleri...

Gecede ay

Avuçlarında yıldızlar

Islandılar...

Yakamoz yağmurları altında

Ölümüne el ele...

Koylarda  dalgalar alkışlıyor

Sevdalıları...

Ne tarih yazabilir

Ne başka bir yazı.

Yüreklere çizilmiş anı...

Ne çoğu 

Ne azı.

Onlar yağmur altında ıslandılar.

İkisi de mutluydular.

Gözlerinde mavi boncuk

İndi damla damla

Şahitti sevdalarına.

Onlar yağmur altında ıslandılar..

Lavlar aktı enginlere

Bir o yüreğe bir bu yüreğe

Salına salına geldi mutluluk

Bir kadehte içtiler

Kaldırımda sabahladı 

Bir tutam hüzün.

Yürekler bahar dalında

Yaprak misali....

Kapıdan baktı yalnızlık.

Giremedi yüreklerine.

Kadının elinde Mavi Gül

Erkeğin elinde Kırmızı

İki yürek yangın sevdalara,,

Rıhtımlarına yanaştılar.

Sessiz dalgaları dinlediler.

Gözlerinin renklerinde

Uykuya teslim...

Yarınlarının sıcaklığına sarıldılar...', 'Umarsız yaşamdan kalan alışkanlıklar Geride iz bırakan sevdalar, Umutlar. Umarsız yıllardan kalanlar''a.............. Ne hoşsun bu gece Dolun...', ARRAY['Türk Edebiyatı','Şiir','Dilek Hokkaömeroğlu']::text[], 8.5, '{"poet":"Dilek Hokkaömeroğlu","poet_slug":"dilek-hokkaomeroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":87,"source_url":"https://www.antoloji.com/yagmur-altinda-islandilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Gönlümün Tapusu', 'gonlumun-tapusu-yusuf-gencal-m2t89', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu yürek 

Niye coşkulu 

Sevdalara

Neden verdim 

Tapusunu gönlümün

Bilir misin

Duyar mısın

Anlar mısın

Bir hançer gibi

Vurdu da geçti yıllar

Hasretim hasret

Ne zamnadır da kederli

İki insan sohpeti sıcaklığı 

22/10/2002 k', 'Bu yürek  Niye coşkulu  Sevdalara Neden verdim  Tapusunu gönlümün Bilir misin Duyar mısın Anlar mısın Bir hançer gibi Vurdu da geçti yıllar ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Gençal']::text[], 8.5, '{"poet":"Yusuf Gençal","poet_slug":"yusuf-gencal","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gonlumun-tapusu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İkimizde bu evrende yalnız', 'i-kimizde-bu-evrende-yalniz-halil-colak-fc1if', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen ağaç olarak yanlız

Ben insan olarak yalnız

Sen çöl ortasında yalnız

Ben insanlar arasında yalnız

Senin etrafını karlar kaplamış

Beni mutsuzluk sarmış

Sen ağaç olarak yalnız

Ben insan olarak yalnız

İkimizde bu evrende yalnız

Halil Çolak 18.3.2006 Ankara', 'Sen ağaç olarak yanlız Ben insan olarak yalnız Sen çöl ortasında yalnız Ben insanlar arasında yalnız Senin etrafını karlar kaplamış Beni mut...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ikimizde-bu-evrende-yalniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'On Beş Yaşında', 'on-bes-yasinda-yakup-aydogan-89in1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir şiir yazdım on beş yaşında

Kimse beyenmedi ilk okuyuşta

Yorumlarken aşkı yalan dünyaya

Anladım şansım yokmuş

Aştan yana

Sevmiştim oysa seni en başta

Güvenmiştim yalanda olsa aşkına

Esir oldum beni vuran bakışlarına

Unutmalıyım galiba seni 

Geçte olsa', 'Bir şiir yazdım on beş yaşında Kimse beyenmedi ilk okuyuşta Yorumlarken aşkı yalan dünyaya Anladım şansım yokmuş Aştan yana Sevmiştim oysa s...', ARRAY['Türk Edebiyatı','Şiir','Yakup Aydoğan']::text[], 8.5, '{"poet":"Yakup Aydoğan","poet_slug":"yakup-aydogan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/on-bes-yasinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Hassasiyet', 'hassasiyet-yusuf-gencal-4h2qi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir başıma

Sokaklardayım

Serseri mayın gibi

Pat diye patlarım

Haksızlıklara

Akılsızlıklara

İki yüzlülüklere

Sevgisizliklere zaten.

01/03/2001 k', 'Bir başıma Sokaklardayım Serseri mayın gibi Pat diye patlarım Haksızlıklara Akılsızlıklara İki yüzlülüklere Sevgisizliklere zaten. 01/03/200...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Gençal']::text[], 8.5, '{"poet":"Yusuf Gençal","poet_slug":"yusuf-gencal","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/hassasiyet-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çanakkale Savaşında Dünya''yı Yendik', 'canakkale-savasinda-dunya-yi-yendik-yusuf-onder-bahceci-ag7xf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Biz Çanakkale Savaşında, bütün Dünya''yı yendik,

Biz Çanakkale Savaşında kaçyüzbin şehit verdik,

Biz Çanakkale Savaşında, Haçlıları, dize getirdik,

Biz Çanakkale Savaşında, bütün Dünya''yı yendik.

Eğer bilmiyorlarsa bilsinler, duysunlar bu gafiller,

Bunlar, Vatan, Millet, Devlet sevgisinden gafiller,

Bunların, aklı kıttır, akılsızdır, bahiller ve de afiller, 

Biz Çanakkale Savaşında bütün Dünya''yı yendik.

Ey Milletim üç, beş çapulcuya pabuç bırakmayın,

Yüce Atatürk''ün kurtardığı Vatan aziz bırakmayın,

Asil Türk Askerine saldıranları bir kıyıda saklayın,

Biz Çanakkale Savaşında bütün Dünya''yı yendik.

Çanakkale Savaşı Türkiye Cumhuriyetini kurtardı,

Ben sizlere ölmeyi emrediyorum diyerek kurtardı,

Bu Mehmetler, Ehli Salibe karşı Dünya''yı kurtardı,

Biz Çanakkale Savaşında bütün Dünya''yı yendik.', 'Biz Çanakkale Savaşında, bütün Dünya''yı yendik, Biz Çanakkale Savaşında kaçyüzbin şehit verdik, Biz Çanakkale Savaşında, Haçlıları, dize get...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/canakkale-savasinda-dunya-yi-yendik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Gelmedin', 'sen-gelmedin-cesim-der-m0nn7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Üzgün gözler bekler senin yolunu

Günler geçti sen gelmedin sevdiğim

Ayrılık hasreti büktü belimi

Yıllar geçti sen gelmedin sevdiğim

Ağrı’yla Erciyes geldi kavuştu

Yandı gönlüm feryat ile tutuştu

Yemene gidenler döndü buluştu

Kuşlar göçtü sen gelmedin sevdiğim

Gözlerim yollara bakıp yoruldu

Niye gelmiyorsun gönlüm darıldı

Baharda açılan çiçekler soldu

Yaprak düştü sen gelmedin sevdiğim

Ecel geldi CESİM bekler yolunu

Nihayet bir ömür buldu sonunu

Kara toprak çekti benim kolumu

Beden göçtü sen gelmedin sevdiğim', 'Üzgün gözler bekler senin yolunu Günler geçti sen gelmedin sevdiğim Ayrılık hasreti büktü belimi Yıllar geçti sen gelmedin sevdiğim Ağrı’yla...', ARRAY['Türk Edebiyatı','Şiir','Cesim Der']::text[], 8.5, '{"poet":"Cesim Der","poet_slug":"cesim-der","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sen-gelmedin-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herkesi Anlamak', 'herkesi-anlamak-yusuf-gencal-gl9kr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Herkesi anlamak

İsterken.

Anlaşılmaz oldum

Yoruldum.

02/05/2005', 'Herkesi anlamak İsterken. Anlaşılmaz oldum Yoruldum. 02/05/2005...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Gençal']::text[], 8.5, '{"poet":"Yusuf Gençal","poet_slug":"yusuf-gencal","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/herkesi-anlamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Susuz''um', 'susuz-um-cesim-der-j96mq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kısır Dağı yücelerden seslenir

Eteğinde koyun kuzu beslenir

Yayaların gelin gibi süslenir

Ne hoş olur dağın taşın Susuz’um

Beyaz patatesle namın anılır

Ala balığında suda salınır

Bendivan Suyu’nda şifa bulunur

Nerde senin dengin eşin Susuz’um

Öğretmen Okulu’n dillere destan

Baharın gelince ekilir bostan

Çeker seni canım ayrılmam dostan

Ne dumandır senin başın Susuz’um

Güz gelince kaz kesimi yapılır

Çermiğinde derman deva satılır

Etli hıngeline yoğurt katılır

Ne şirindir bulgur aşın Susuz’um

Cilavuz denince vardır efkârım

Tarım hayvancılık gelir kaynağın

Kışın hiç eksilmez tipiyle karın

Ne sert olur ayaz kışın Susuz’um

Güzeldir şelalen akıyor çayın

Susuz  diyemezler çünkü bol suyun

CESİMİ’yi sizde bu elden sayın

Ne eskidir senin yaşın Susuz’um', 'Kısır Dağı yücelerden seslenir Eteğinde koyun kuzu beslenir Yayaların gelin gibi süslenir Ne hoş olur dağın taşın Susuz’um Beyaz patatesle n...', ARRAY['Türk Edebiyatı','Şiir','Cesim Der']::text[], 8.5, '{"poet":"Cesim Der","poet_slug":"cesim-der","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/susuz-um-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O An', 'o-an-yakup-aydogan-zehjk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şimdi sensiz

Uzak diyarlarda

Tutsak duygularımla

Kimseninin bilmedigi hayalerimle

Bekleyecegim seni

Bilmedigim diyarlarda

Olmadı yapamadım sensiz

Buralarada tek başıma

Biliyorum gelmeyeceğini

Belkide hiç sevmedin

Ama bilki ben beklerim

Olsun sen beni sevme

Ben seni severim

Kopmuştum hayattan

Gitme diyemedim ardından

Gitigin o an', 'Şimdi sensiz Uzak diyarlarda Tutsak duygularımla Kimseninin bilmedigi hayalerimle Bekleyecegim seni Bilmedigim diyarlarda Olmadı yapamadım s...', ARRAY['Türk Edebiyatı','Şiir','Yakup Aydoğan']::text[], 8.5, '{"poet":"Yakup Aydoğan","poet_slug":"yakup-aydogan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/o-an-44-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölirem', 'olirem-huseyin-kotan-nus5h', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tahtacılardan aşşağı gelirem

Düşinirem gara gara

Bir elim cebimde,öbüründe cigara

Atarabası gidir ögümde,soğan yühli

Yer çelpeşik,çamur

Ahşamdan beri yağir ander yağmur

Köşeyi döndüm,o’ni gördüm

Atarabasının önünden geçti

Bene bakdi…

Off…gözleri ela sanki yanir

Ele tikildim galdım,ağzım açık

Herhal beni deli sanir…

Durdum galdım,dizlerim titirir…

Bir ösgürdüm,bir ösgürdüm…

Az galdi boğulim,o’na gurban olim

Anasının yanında gidir,cump cump

Benim yüreğim vurir gümp gü

Ne oldi bene? heç anlamadım.

Onnar gidir ben gidirem,peşlerini bırakmirem

Epey gettiler,bir fukaraya para verdiler

Neden sonra,bahçeli bir evden içeri girdiler

Ben galdim gapide…

İçeri giremirem,ele üşirem ele üşirem…

Ceryan direğine yaslandım

O ince yağmur,yağdi yağdi yağdi

Bende direginenbile paslandım…

Ondan sonra hergün oraya gettim

O gözlerin yüzünden,işi mişi terk ettim

Gece aklıma gelir,gahirem…

Sağıma soluma bahirem yok.sonra yatirem..

Alma bile yerken,gırmızısıni o’na verim diyirem

Ele içim yanir,ele içim yanirki mantıs gibi

Durmadan çay içirem.

Bazen evde teh galdımmi…

Otirirem birey ağlirem,sonra

Ne olacak bu halim,ben neydim diye

Vele hevle çekirem..

Yüzüme değilde,güliller dalıma

Bende hayrat ediremgendi halıma…

Ula elin gızi evde oturir

Sene davun degir? 

Senin neler çektiğini bilirmi? bilmir…

Sen neye üzilirsen,senin neyin diyirem

Gene en çok o’ni düşinirem.

Bizim orada bi’tanegehve var,

Sandalyeleri odundan,uzunca,ama dar

Arada bir gidirem,çay içirem…

Bir emi var orada,gapıya yakın oturir

Elindeki cigarayı bele çekir,çekir savurir…

Eski herif,yaşli…

Saçlari dökülmüş enli gaşli…

Bir gün; 

Selam verdim oturdum yanına

Boğuldum içtiği cigaranın dumanına

Dedim emmi gusura galma…

İster beni mehele al,ister alma

Durum bele bele,gidir görirem

Gece gündüz o’ni düşünirem,ölirem…

Şöyle yavaş yavaş,döndi yüzüme bakdi

Kısdikten yeni bir cigara daha yakdi

Dumanıni çekti içine,sonra dışarı savurdi

Kısdiği kaldırdi hersinen yere vurdi

Sandalyeden doğruldi,bir daha oturdi

Eyvah oğul,sen getmişsen, p…yemişsen

İster gül ister ağla,heç fargetmez 

O’ni alsanda,almasanda bu derdin bitmez

Ne diyim,ele zorki anlatmak

Yaşarken sararıp galkarken,boşluğa bakmak

Ne etsen ne yapsan derdin bitmez,

Canın bedende iken,aklın kar etmez

Allah vere, helel süt emmiş ola

Yoksa yandın gettin,hayatın maf ola

Benide benden alan bu derd idi

Kor olacak gözlerim,o gözleri niye gördi ki

İçimi yaktın,Allah sabır vere

Bu gayfede senede bir sandalye düşe

Bol bol ağla için açılır dedi…

Boynuni bühdi,gafasıni salladi,getti

Galdım masada,bir başıma

Neden sonra garson dikildi garşıma…

Bir şeyler öyrenip yapsaydın bari

Hesabi ödedim,çıktım dışari…

Ellerim cebimde,düşinirem gara gara 

Heç düşmez oldi dodağımdan cigara…

O gündür,bu gün oldi hele düşinirem

Bu ne zor derdimiş

O’ni görsemde,o’ni görmesemde

Ölirem…', 'Tahtacılardan aşşağı gelirem Düşinirem gara gara Bir elim cebimde,öbüründe cigara Atarabası gidir ögümde,soğan yühli Yer çelpeşik,çamur Ahşa...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Kotan']::text[], 8.5, '{"poet":"Hüseyin Kotan","poet_slug":"huseyin-kotan","theme":"Türk Şiiri","is_hero":false,"total_lines":88,"source_url":"https://www.antoloji.com/olirem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Çanakkale', 'sen-canakkale-cesim-der-c723s', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Anam kına yakıp saldı cepheye

Atam çizme giyip çıktı tepeye

Verdi hücum emri vurdu kahbeye

Geçilmez dağ oldun sen Çanakkale

Şanlı askerimiz otağı kurdu

Düşman inat ile direndi durdu

Verilmez çakala aslanın yurdu

Yeni bir çağ oldun sen Çanakkale

Ay ile yıldızlar şahidin oldu

Nice genç bedenler burada soldu

Gelibolu kızıl kan ile doldu

Tarihe şan oldun sen Çanakkale

Ak saçlı analar akıttı yaşı

Mehmedim vermedi bir çakıl taşı

Süngüyle ezildi haçlının başı

Bayrağa al oldun sen Çanakkale

Koca top mermisin sırtına aldı

Sürdü düşmanını denize çaldı

Dünya parmağını ısırdı kaldı

Aşılmaz yol oldun sen Çanakkale 

Biz kahraman Türk’üz vermeyiz vatan

Çanakkale Geçilmez der idi Atan

Tarihten ibret al ey kâfir utan

İkbale ad oldun sen Çanakkale

Şanlı askerimiz oldu muzaffer

Tarihte görülmez böyle bir zafer

Kefensiz yatıyor binlerce nefer

Şehide yad oldun sen Çanakkale

Bulgur gibi gülle başa yağarken

Her on sekiz mart’ta güneş doğarken

Anzak İngilizler kara bağlarken

Tarihe mal oldun sen Çanakkale

Bu savaş pek yaman kan seli dizde

Her zaman canlanır hatıran bizde

Nicedir yaşarsın yüreğimizde

Solmayan gül oldun sen Çanakkale

CESİM der ki Türk yurdudur burası

Bu topraklar atamızın mirası

Doksan yıldır sarılmadı yarası

Canımız içinde can Çanakkale', 'Anam kına yakıp saldı cepheye Atam çizme giyip çıktı tepeye Verdi hücum emri vurdu kahbeye Geçilmez dağ oldun sen Çanakkale Şanlı askerimiz ...', ARRAY['Türk Edebiyatı','Şiir','Cesim Der']::text[], 8.5, '{"poet":"Cesim Der","poet_slug":"cesim-der","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/sen-canakkale-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günah Defterim', 'gunah-defterim-yakup-aydogan-8tmef', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Günah defterimin ilk sayfasına baktım, okudum

Her satırından senin ismini buldum

Göz yaşlarım aktı, tüylerim ürperdi

Nasılda sevmiştim seni, durup kendime sordum

Meyhaneler dostum olmuş, meyler ahbabım

Bilmiyorum dünyada neydi günahım

Bir zalimin zulmünü ben çeker oldum

Bir gonca gül idim, dalımda soldum

Yıldızlardan fal baktım hergün kendime

Nice günahlar ekledim şu günah defterime

İsyan ettim, haykırdım gelmeyen ecelime

Yine günah yazdım şu günah defterime', 'Günah defterimin ilk sayfasına baktım, okudum Her satırından senin ismini buldum Göz yaşlarım aktı, tüylerim ürperdi Nasılda sevmiştim seni,...', ARRAY['Türk Edebiyatı','Şiir','Yakup Aydoğan']::text[], 8.5, '{"poet":"Yakup Aydoğan","poet_slug":"yakup-aydogan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gunah-defterim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*İkimiz', 'i-kimiz-yusuf-gencal-6n1h9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hayat kolay değil sevgilim

Yaşamak yasaktır sevdamızı

Birileri olur hep aramızda

Tek tabanca varya öyle

Namlusuna sürülmüş mermi gibi

temmuz sıcağı aşkımızın

Varmalıyız hedefine on ikiden

26/12/2001 k', 'Hayat kolay değil sevgilim Yaşamak yasaktır sevdamızı Birileri olur hep aramızda Tek tabanca varya öyle Namlusuna sürülmüş mermi gibi temmuz...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Gençal']::text[], 8.5, '{"poet":"Yusuf Gençal","poet_slug":"yusuf-gencal","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ikimiz-80-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İkiyüzlü', 'i-kiyuzlu-yusuf-gencal-7yoyh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kordan sıcaklığını

Almış eline güneş.

Bir akşam vakti

Aydınlatmak için

Öteki yüzünü dünyanın.

                       10/03/2005', 'Kordan sıcaklığını Almış eline güneş. Bir akşam vakti Aydınlatmak için Öteki yüzünü dünyanın.                        10/03/2005...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Gençal']::text[], 8.5, '{"poet":"Yusuf Gençal","poet_slug":"yusuf-gencal","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ikiyuzlu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönüyorum Artık', 'donuyorum-artik-yakup-aydogan-75d92', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni yaşlarımla büyütüm ben

Her gecen ardına bende

Bir şeyler kattım

Yoruldum uykusuz kaldım

Sıgınamadım bu kentede

Gitmek istedim sen ardımda

Doldum, taşıyorumben coğaldım çoğaldıkça

Doyamadım yapacak bişey kalmadı

Anlamsız umutlar bagladım yüregime

Kendimi sana sevdiremedim', 'Seni yaşlarımla büyütüm ben Her gecen ardına bende Bir şeyler kattım Yoruldum uykusuz kaldım Sıgınamadım bu kentede Gitmek istedim sen ardım...', ARRAY['Türk Edebiyatı','Şiir','Yakup Aydoğan']::text[], 8.5, '{"poet":"Yakup Aydoğan","poet_slug":"yakup-aydogan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/donuyorum-artik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Katiller', 'katiller-yusuf-gencal-meeas', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ey çokuluslu katiller

Kan sıçrıyor sofranıza kan

Ruh sağlığı bozuldu dünyanın

Akıttığınız kanların uğultusundan

10/04/2005k', 'Ey çokuluslu katiller Kan sıçrıyor sofranıza kan Ruh sağlığı bozuldu dünyanın Akıttığınız kanların uğultusundan 10/04/2005k...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Gençal']::text[], 8.5, '{"poet":"Yusuf Gençal","poet_slug":"yusuf-gencal","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/katiller-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cumhuriyetim', 'cumhuriyetim-cesim-der-pal5u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'nazlıca salınan bir atın yelesinde buldum ilkin seni

fırtınada bile özünü kaybetmeyendin

özgürlükten sen

aldım sırtıma vurdum kendimi şanlı yoluna

emeğin ruhuydun sen

büyüdü dünyam büyüklüğüne erişemedim ben

gözümün değdiği her yerdeydin

anamın akıttığı terde 

anamı yaşamda var edendin sen

haktın haklıyı sarmaladın

şereflice nefes almaktı adın

insanca var olmaktın

cumhuriyettin sen

titreyen bakışlarla seçmeyi 

teklikten çokluğa dönüşmeyi öğretendin

içime güveni fısıldayan rüzgar

atalarımın ömür tepsisiyle sunduğun nimettin

cumhuriyettin

sen

dibine ışık veren tek mum

ektiğim ekinde

başaklara vuran kızıllıkta

yurdumu yüceltensin cumhuriyetsin

doğacak her çocukla var olansın

memleketim kokansın

babamın kamburundaki küfede

toprağa karışan tohumda

çatlamış ellerde yaşam suyu olansın

cumhuriyetsin sen

bayrağımın ay yıldızından seksen senedir doğan güneş

Atatürk’ümün ebedi örtüsü

şaheseri

yurdumu ısıtansın

cumhuriyetsin sen', 'nazlıca salınan bir atın yelesinde buldum ilkin seni fırtınada bile özünü kaybetmeyendin özgürlükten sen aldım sırtıma vurdum kendimi şanlı ...', ARRAY['Türk Edebiyatı','Şiir','Cesim Der']::text[], 8.5, '{"poet":"Cesim Der","poet_slug":"cesim-der","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/cumhuriyetim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Ne yapacaksın', 'ne-yapacaksin-yusuf-gencal-32hzr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Vardiyan bitmiş

Orta yerindesin

Okyanusun

Yorgun kederli

Kamaranda bir başına

Yalnızlık yalnızlığı

Kovalar

Duvarlar sana bakar

Sen onlara

Boğulursun

Sıkılırsın

Tükürürsün 

İçine bu hayatın

İsyanlar

Umutlar

Karışmış

Kadeh olmuş

İçmeyip de 

Ne yapacaksın

Bir başına 

Bir başına gemidesin

20/04/1998k', 'Vardiyan bitmiş Orta yerindesin Okyanusun Yorgun kederli Kamaranda bir başına Yalnızlık yalnızlığı Kovalar Duvarlar sana bakar Sen onlara Bo...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Gençal']::text[], 8.5, '{"poet":"Yusuf Gençal","poet_slug":"yusuf-gencal","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ne-yapacaksin-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Farketmez', 'farketmez-i-lker-kesemen-9jve8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gülerdiler ona 

O aldırmazdı bunlara 

Gülen yüzünün yanında 

İçinde kanardı yarası hala 

Hayat farketmez onun için 

Artık umutları bitmiş 

Gözyaşı sel olup gitmiş 

Haline kimse aldırış etmemiş 

O herşeyin farkında imiş 

Herkeşi tartar değerlendirirmiş 

Ve suçu sadece 

Bir zalimi sevmekmiş 

Saygılarımla', 'Gülerdiler ona  O aldırmazdı bunlara  Gülen yüzünün yanında  İçinde kanardı yarası hala  Hayat farketmez onun için  Artık umutları bitmiş  G...', ARRAY['Türk Edebiyatı','Şiir','İlker Kesemen']::text[], 8.5, '{"poet":"İlker Kesemen","poet_slug":"i-lker-kesemen","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/farketmez-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutmak Kolay Olsa', 'unutmak-kolay-olsa-yakup-aydogan-wwphg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aşk varmı acaba

Aşk nedir dedigin oldumu hiç

Hiç yaşadınmı aşkın sen

Hiç acı çektinmi

Ağladınmı gecelerisen

Yumruk atınmı duvarlara

Unuta bildinmi

Unutmak istediklerini

Unutmak kolay olsaydı 

Ben hayatı unuturdum

Unutmak kurtuluş olsaydı

Ben seni çoktan unuturdum', 'Aşk varmı acaba Aşk nedir dedigin oldumu hiç Hiç yaşadınmı aşkın sen Hiç acı çektinmi Ağladınmı gecelerisen Yumruk atınmı duvarlara Unuta bi...', ARRAY['Türk Edebiyatı','Şiir','Yakup Aydoğan']::text[], 8.5, '{"poet":"Yakup Aydoğan","poet_slug":"yakup-aydogan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/unutmak-kolay-olsa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Serap Görüpte Kaldın Uykuda', 'bir-serap-gorupte-kaldin-uykuda-umut-gungor-jf6b1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir serap görüp kaldın uykuda,

Uyandığın zaman bana haber ver,

Bekleyen yürek var seni burada,

Hissettiğin anda bana haber ver.

Unutma bu poyrazın ardı fırtına,

Koskoca dünyayı alma sırtına,

Ne kadar dert varsa atıp ardına,

Koşmaya hazırsan bana haber ver.', 'Bir serap görüp kaldın uykuda, Uyandığın zaman bana haber ver, Bekleyen yürek var seni burada, Hissettiğin anda bana haber ver. Unutma bu po...', ARRAY['Türk Edebiyatı','Şiir','Ümüt Güngör']::text[], 8.5, '{"poet":"Ümüt Güngör","poet_slug":"umut-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bir-serap-gorupte-kaldin-uykuda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muhtelif Nükteler (8)', 'muhtelif-nukteler-8-mevlut-bicik-ep3yt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dâvetinize ederim teşekkür. Lâkin! 

Mars’a çıkacak enerji bizde ne gezer.

Biraz kızmış gibisiniz,olunuz sâkin,

Alacağınız bir abdest,öfkenizi ezer.

Ben bu yoruma vermiyecem cevab.

Süküt ile kazanacam ecir ve sevab.

Kardeşimin burnu riyâ kokusunu aldıysa,

Yalvaracam,yakaracam olucam tevvab.

Size cevab mı vereyim,yoksa susayım mı? 

Niye yaptın latîfe diye,nesfime kızayım mı? 

Yahu kardeşim! Bu ensar ile de baş edilmiyor,

Deyip’de,sessiz-sedasız bu siteden sızayım mı? 

Yahu biz bir acâib olduk,târihi de unuttuk.

Çağdaş olucaz derken,çok lisanlar yuttuk.

Bize bahçe diye arzedilen,çöplüklerde gezerken,

Gül zannıyla,özümüze batan dikenler tuttuk.

Aah kardeşim ah! Benimde yüreğim yanık.

Döner koltuklarda oturanların kanları donuk.

Rüşvet kuşunu yiye yiye,kuş gribine yakalanmışlar,

Olmuşlar şerefsizlerin evinde,şeref müsafiri gibi konuk.

Mevlüt Bicik

18.03.2006  saat  15.40

Esslingen', 'Dâvetinize ederim teşekkür. Lâkin!  Mars’a çıkacak enerji bizde ne gezer. Biraz kızmış gibisiniz,olunuz sâkin, Alacağınız bir abdest,öfkeniz...', ARRAY['Türk Edebiyatı','Şiir','Mevlüt Bicik']::text[], 8.5, '{"poet":"Mevlüt Bicik","poet_slug":"mevlut-bicik","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/muhtelif-nukteler-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelemesinki', 'gelemesinki-yakup-aydogan-0r2or', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kalbinde bir acı feryat

Gözleri senin için ağlar

Gelmeni bekler bu garib 

Gelmiyecegini bile bile

Gelemesinki o garibe

Gelmek istesen bile

İzin vermez kara toprak 

Senin o garibe gitmene', 'Kalbinde bir acı feryat Gözleri senin için ağlar Gelmeni bekler bu garib  Gelmiyecegini bile bile Gelemesinki o garibe Gelmek istesen bile İ...', ARRAY['Türk Edebiyatı','Şiir','Yakup Aydoğan']::text[], 8.5, '{"poet":"Yakup Aydoğan","poet_slug":"yakup-aydogan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gelemesinki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kavusmanın Gemileri', 'kavusmanin-gemileri-yusuf-gencal-zsn1y', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her yer deniz

Zifiri karanlık gece

Alargada gemidesin.

Hayali yastıkta

Bir kadın uyur.

Özlemler kudurur

Dudağı dudağına dokunur

Bir can olur canına.

                         15/11/2001', 'Her yer deniz Zifiri karanlık gece Alargada gemidesin. Hayali yastıkta Bir kadın uyur. Özlemler kudurur Dudağı dudağına dokunur Bir can olur...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Gençal']::text[], 8.5, '{"poet":"Yusuf Gençal","poet_slug":"yusuf-gencal","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kavusmanin-gemileri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülüm', 'gulum-yakup-aydogan-i3j3g', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gecenin ay parıltısında

Uzanmış yıldızları izlerim

Seni düşünürüm hergece

Seni sevmek ne güzel

Gözlerim dolar seni düşünürken 

Neden soracaksın gülüm

Seni kaybetmekten 

Kortugum için ağlarım

Erkekler ağlamaz derler

Kimdemise yalan söyler 

Erkeklerde ağlar gülüm

Ben senin için ağladıgım gibi', 'Gecenin ay parıltısında Uzanmış yıldızları izlerim Seni düşünürüm hergece Seni sevmek ne güzel Gözlerim dolar seni düşünürken  Neden soracak...', ARRAY['Türk Edebiyatı','Şiir','Yakup Aydoğan']::text[], 8.5, '{"poet":"Yakup Aydoğan","poet_slug":"yakup-aydogan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gulum-193-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaralı Bir Uzaklık', 'yarali-bir-uzaklik-goktu-kara-35xo0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'şen şakrak bir durumda idim

yaralı bir aşk geldi uzaktan

ne güzel uyuyordum

kandırıyordum kendimi

(aynı kıza iki kez aşık olunur mu?) 

üzüldüm

neşe vardı sahnede

(ali sunal''çok fazla yaklaşma bebek çok fazla büyüyebilir ''deyince  iki yaşlarında bir çocuk kahkahayı bastı salona) 

zira sevgi bana uzak olmalı

üzülmek istemiyorum...

leyli bir aşk geldi uzaktan

ezim ezim ezileyim', 'şen şakrak bir durumda idim yaralı bir aşk geldi uzaktan ne güzel uyuyordum kandırıyordum kendimi (aynı kıza iki kez aşık olunur mu?)  üzüld...', ARRAY['Türk Edebiyatı','Şiir','Göktu Kara']::text[], 8.5, '{"poet":"Göktu Kara","poet_slug":"goktu-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yarali-bir-uzaklik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baktırdığım Fallar', 'baktirdigim-fallar-yusuf-onder-bahceci-w8f9i', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gördüğüm her güzelde, gözlerim seni arıyor,

Ayrılığın acısıyla böyle hep sararıp ta soluyor,

Baktırdığım bütün fallar, ayrılık, ayrıldık, diyor,

Gördüğüm her güzelde, gözlerim seni arıyor,

Ayrılığın acısıyla böyle hep sararıp ta soluyor,', 'Gördüğüm her güzelde, gözlerim seni arıyor, Ayrılığın acısıyla böyle hep sararıp ta soluyor, Baktırdığım bütün fallar, ayrılık, ayrıldık, di...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/baktirdigim-fallar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğim Islanmaz Yanımda Olsan', 'yuregim-islanmaz-yanimda-olsan-umut-gungor-y24po', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yüreğim ıslanmaz yanımda olsan,

Beyaz hayalime kuş olup konsan,

Yapraklar misali dalımda donsan,

Kıyamaz çözerdim seni buzundan.

Üşümekten kurtulurdu bedenim,

Seni beklemeye bir çok nedenim,

Başıboş ırmakta kayıp gidenim,

Sensiz denizlere bırakma beni.

Seninle denize inip çıkardım,

Yosunun kökünü dipten budardım,

Senin için nice sular yutardım,

Sensiz kıyılara bırakma beni.', 'Yüreğim ıslanmaz yanımda olsan, Beyaz hayalime kuş olup konsan, Yapraklar misali dalımda donsan, Kıyamaz çözerdim seni buzundan. Üşümekten k...', ARRAY['Türk Edebiyatı','Şiir','Ümüt Güngör']::text[], 8.5, '{"poet":"Ümüt Güngör","poet_slug":"umut-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yuregim-islanmaz-yanimda-olsan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senle Başlar Herşey....', 'senle-baslar-hersey-murat-kilic-2-r4fug', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'günlerce bekledim pencereler küstü.

pembe panjurlar soldu,çiçekler solgun.

içimdeki heyecan yas evine dönüştü.

bu tarifsiz kederin sahibini biliyorsun.

………………….

senden bir melek yaratıp hülyaya daldım.

önce mahcubiyet oldun,içim yandı.

sonra mahrumiyet oldun,öylece kaldım.

gece gündüz dilim o hüzzam adını andı.

…………………

beklemekti belki de kader,belki sabır; 

yaşansa bile acıların en görkemlisi.

üst üste binse bile bir gün usanır,

ıstırabın olsa da en katmerlisi.

………………….

yetinmekti bir bakıma hayat bende.

bilirsin beni,küçük sevinçlerle büyürüm.

dünyalara sığmam bir kez gülsende.

bir an için yüzün durulsa,üzülürüm.

…………………

burada yangın var,işte tam burada.

durulmakta bilmiyor küllenmekte.

katar katar ümit var,yanmaya sırada.

yanarken sana,bil ki; bir ömür tükenmekte.

…………………

artık ümitsizim,çaresiz,bi haber.

sen! başın önde,sonra suskun sesin.

ümitsiz beklemeyle geçerken seneler,

anladım ki beni sevmeyeceksin.

…………………', 'günlerce bekledim pencereler küstü. pembe panjurlar soldu,çiçekler solgun. içimdeki heyecan yas evine dönüştü. bu tarifsiz kederin sahibini ...', ARRAY['Türk Edebiyatı','Şiir','Murat Kılıç 2']::text[], 8.5, '{"poet":"Murat Kılıç 2","poet_slug":"murat-kilic-2","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/senle-baslar-hersey-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yasaksız', 'yasaksiz-umut-engin-deniz-3i6hv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Senin üzüntün,

gözlerinde gördüğüm o mutsuzluk —

bıçak gibi saplanıyor

ta şurama.

"Bir şeyler yapsam," diyorum.

Umutlarını yeşertsem,

mutsuzluğunu unuttursam,

silsem tüm acılarını…

Biliyorum

içine kan olup akan gözyaşlarını.

Boğazın düğüm düğüm olduğunda

konuşamazken,

gülmenin ne kadar zor olduğunu.

Sihirli bir değnek olsa elimde,

unutturabilsem yaşanan çirkinlikleri.

Unutabilsen yakın geçmişi...

Sihirli bir değnek olsa elimde,

sen olsan yanımda.

Varlığımızla var olsak —

yasaksız.', 'Senin üzüntün, gözlerinde gördüğüm o mutsuzluk — bıçak gibi saplanıyor ta şurama. "Bir şeyler yapsam," diyorum. Umutlarını yeşertsem, mutsuz...', ARRAY['Türk Edebiyatı','Şiir','Umut Engin Deniz']::text[], 8.5, '{"poet":"Umut Engin Deniz","poet_slug":"umut-engin-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sihirli-degnek-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bedir''de Bende Olaydım', 'bedir-de-bende-olaydim-huseyin-kotan-mgz9k', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Önde Allah’ın Resulü

Sağı solu mümin dolu

Açıldı cihadın yolu

Bedir’de bende olaydım

Kuyuları kapattılar

Başında mevzi aldılar

Firdevs cennetin buldular

Bedir’de bende olaydım

Âlev saçan çöl üstünde

İki atlı yetmiş deve

Çocuklar girdi cepheye

Bedir’de bende olaydım

Cuma günü ay ramazan

Esti rüzgâr oldu hazan

Meleklerdi müşrik bozan

Bedir’de bende olaydım

Resul tek tek gösteriyor

Buraya düşecek diyor

Mihca’yı şehit veriyor

Bedir’de bende olaydım

Ali’de Ukub sancağı

Kuyu başıdır durağı

Hediyedir zülfükârı

Bedir’de bende olaydım

Ölümün ağzına girsem

Allah için cihad etsem

Ya Mansur Emit desem

Bedir’de bende olaydım

Şanlı rüzgâr üç kez esti

Ebu cehil gördü kastı

İbni Mes’ud başın kesti

Bedir’de bende olaydım

Önde Resul’ü Kibriy’a

Cibril binmiş beyaz ata

Kumandan Hakkı Safiya

Bedir’de bende olaydım

Ridası omuzdan düştü

Baba oğulla dövüştü

Yetmiş müşrik ölmüştü

Bedir’de bende olaydım

Başlarında beyaz sarık

Uçları arkadan sarkık

Kılıçlar kınından sıyrık

Bedir’de bende olaydım

Cibril’in sarığı sarı

Hamza, Ali, Habib yarı

Ömer’di dehşet durağı

Bedir’de bende olaydım

İşte Hamza, işte Ali,

Vuruşur aslan misali

Ashap olmuş iman seli

Bedir’de bende olaydım

Gönüller bedir’de açtı

Şehitler kanatsız uçtu

Hak’tan gelip Hakka göçtü

Bedir’de bende olaydım

Bedrin aslanları şanlı

Kılıcı, sancağı kanlı

Asırlardır halâ canlı

Bedir’de bende olaydım

Üveysiyim yolum Hak’tır

Müşriklerden korkum yoktur

Geylâni’de himmet çoktur

Bedir’de bende olaydım', 'Önde Allah’ın Resulü Sağı solu mümin dolu Açıldı cihadın yolu Bedir’de bende olaydım Kuyuları kapattılar Başında mevzi aldılar Firdevs cenne...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Kotan']::text[], 8.5, '{"poet":"Hüseyin Kotan","poet_slug":"huseyin-kotan","theme":"Türk Şiiri","is_hero":false,"total_lines":64,"source_url":"https://www.antoloji.com/bedir-de-bende-olaydim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul', 'i-stanbul-yakup-aydogan-877uv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'istanbul gündüz mahsumsun

Gece ise gardiyan

Dünyada bulunmaz eşsin 

İçindeki esrlerle

Sen bir strateji yerisin 

Sen vatanın kalbisin

Dedimya sana İstanbul

Sen düyanın göz bebegisin

İstanbulu İstanbul yapan nedir

İstanbul olmak kolaymı sence

Neden dünya seni peşinde

Neden söylesen

Söyleyemesinki konuşamasın dogruya

Sen sadece topraksın

Senin için cok can veren oldu

Kim senin için can vermez ki

Bu manzaran büyüler

Muhteşem kızkulen varya

İzlerim yüksek tepeden

Büyüler beni o güzeligin varya', 'istanbul gündüz mahsumsun Gece ise gardiyan Dünyada bulunmaz eşsin  İçindeki esrlerle Sen bir strateji yerisin  Sen vatanın kalbisin Dedimya...', ARRAY['Türk Edebiyatı','Şiir','Yakup Aydoğan']::text[], 8.5, '{"poet":"Yakup Aydoğan","poet_slug":"yakup-aydogan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/istanbul-409-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İkimizin Dünyası', 'i-kimizin-dunyasi-ayse-bakkalci-6e4wp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen dünya olsan,

Ben ay dede,

Kendimi sanıyorum,

Etrafında dönen bir yörünge.

Gökyüzünde gezen,

Küme küme bulut olsan,

Yağmur bulutu gibi,

Gelip yanında dursam.

Doğan yaz güneşi gibi,

Seni ısıtmak isterim,

Yaz yağmuru olup,

Hep seni ıslatayım derim.

Seni benzetirim gökyüzüne,

Kendimi bir yıldız,

Gezegenin olmak isterim,

O zaman ikimizin dünyası derim...', 'Sen dünya olsan, Ben ay dede, Kendimi sanıyorum, Etrafında dönen bir yörünge. Gökyüzünde gezen, Küme küme bulut olsan, Yağmur bulutu gibi, G...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Bakkalcı']::text[], 8.5, '{"poet":"Ayşe Bakkalcı","poet_slug":"ayse-bakkalci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ikimizin-dunyasi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taşlama', 'taslama-ufuk-bayraktar-lpeop', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'oğul:

''''çanakkale içinde vurdular beni''''

borcumu ödemedim ah

topuğuma sıktılar benim

of... gençliğim eyvah! 

kız:

''''çanakkale içinde aynalı çarşı''''

anne ben duruyorum aynaya karşı

siyah noktalar çıkmış yine ah! 

kırışıklıklar, gençliğim eyvah! 

nine:

''''çanakkale içinde bir kırık testi''''

o testiden niceleri su içti

bu gençlik bu hale nasıl düştü

ahhh! gençliğe eyvah!', 'oğul: ''''çanakkale içinde vurdular beni'''' borcumu ödemedim ah topuğuma sıktılar benim of... gençliğim eyvah!  kız: ''''çanakkale içinde aynalı ...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Bayraktar']::text[], 8.5, '{"poet":"Ufuk Bayraktar","poet_slug":"ufuk-bayraktar","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/taslama-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küstüm', 'kustum-necati-keceli-u2n0l', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gönülden, gönül’e sevgi ararken

    Küstürdüler beni bu cana küstüm

    Gördüğüm her dosta selam verirken

    Küstürdüler beni canana küstüm

    Sevgiye sarıldım şifadır diye

    Sevgim büyüdükçe döndüm deliye

    Dostum, arkadaşım sordu hediye

    Küstürdüler beni cihana küstüm

    Dünyaya sahipmiş hep yalan hile

    İçinde yaşanır zevk, sefa ile

    Biraz konuşunca bak düştük dile

    Küstürdüler beni lisana küstüm 

    Fitneler fesatlar çıkmış ortaya

    Zengini, fakiri koşar paraya

    Beni yatırsan da büyük saraya

    Küstürdüler beni ün, şana küstüm 

    Kalbimi karartı bunca savaşlar

    Her gün başımıza atıldı taşlar

    Kazığı atınca dost, arkadaşlar

    Küstürdüler beni talana küstüm

    Şu dünya malında, gözüm olmadı

    Hep aradı gönül, huzur bulmadı

    Yazıp söyleyecek sözüm kalmadı

    Küstürdüler beni zamana küstüm

    Necati KEÇELİ

    ADANA', 'Gönülden, gönül’e sevgi ararken     Küstürdüler beni bu cana küstüm     Gördüğüm her dosta selam verirken     Küstürdüler beni canana küstüm...', ARRAY['Türk Edebiyatı','Şiir','Necati Keçeli']::text[], 8.5, '{"poet":"Necati Keçeli","poet_slug":"necati-keceli","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/kustum-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dürüstler Nerde', 'durustler-nerde-ali-cengiz-turan-4530s', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dünya yuvarlakmış çember misali,

Ermişimiz var,dervişimiz var eli asalı,

Tepeden bakılıyoruz kurban misali,

Dürüstlükler nerde,dürüstler nerde? 

Dünya kurulalı durmaz dönermiş,

Sonsuz nimetini bizlere sunarmış,

Bilinen canlılara yaşayan insanlara,

Hak olanlar nerde haklar nerede? 

Etle kemik yapımız,ruh olursa yaşarız,

Bilinçli kuvvet ile her engeli aşarız,

Ruh ile kalp kararsa,riyakarlık ararsa,

O güzel aklın nerde.gören gözlerin nerde?', 'Dünya yuvarlakmış çember misali, Ermişimiz var,dervişimiz var eli asalı, Tepeden bakılıyoruz kurban misali, Dürüstlükler nerde,dürüstler ner...', ARRAY['Türk Edebiyatı','Şiir','Ali Cengiz Turan']::text[], 8.5, '{"poet":"Ali Cengiz Turan","poet_slug":"ali-cengiz-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/durustler-nerde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşünüyorum da', 'dusunuyorum-da-sevinc-kavuk-k19ac', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İletişim araçları hem çok hızlı

Hem de çok çeşitli haliyle

Televizyon, radyo, gazete, dergi, bilgisayar, multimedya, film, video, faks, modem, projeksiyon makinesi, slayt ve seçim becerisiyle “tepegöz” denilen saydam gösterici, fotoğraf makinesi, (teyp)     durağan görüntüleri sesle birleştirme, elektronik sufle aleti, tablolar, bir ses ve görüntü mozaik´i oluşturma, bildiri…düşünüyorum da 

Teknoloji mi önde mesaj mı? Yoksa bu

Bir multivizyon şov mu? Medya kuyumculuğu mu? 

…bir yeri işgale giden devletin hava ve deniz güçleri bunlar, ama ele geçirmek için kara birliklerinin oraya varması gerekli daha… bire bir ilişki gerekli yani ve sahne korkusunu yenme sohbeti gibi bir şey işte, ama: görüşleri ifade etmeye yeterlilik mi? 

Dinleyici gereksinimine yönelik ilgilendikleri sanılan ya da aynı konularda karşılıklı konuşma fırsatı…Bir de bir amaca yönelik ve provalı, bazen görsel işitsel malzeme desteli fikir ve kanıları duyurma fırsatı…düşünüyorum da 

Kontrollü bu etkiyi sağlamak günlük 

ve sıradan konuşmalarda yeterlilik mi? 

Bunun genel planı

Ana konu ve konuşma amacını 

Nasıl sergileneceğini saptama ve yapısı

Yani bir güvenlik duygusu kazanımı…

Yazı gibi konuşma taslağı…

Kısaca giriş, açıklama ve sonucu…

Her şey dünde güzel bugün 

Ve güzel bir yarına gül dikeceğim…

Gibi bir espri, bir öykü belki…

ve anımsanacak bir şey vermek açımlamaya, dağa tırmanan birinin slaytını seyrederken o serüveni de anlatıyor oluşu, etkilenim zevkine katılan o tadı düşünmek, akla ve duygulara seslenmek gibi iki retorik türünü kullanmak, ki ne yapalım olgular böyle diyerek değil, duyguya akıcı, ilginç ve ikna edicilikle olgu ve mantık temelinden tümdengelimsel ve tümevarımsal akıl yürütmeyi kullanmak, sonuç ise zaten başından belirli bir tekrarlama, heyecan yükselmesi ve gerilim artısı, doruğa ulaşmak

Yani, dile dikkat başlıyor tabii... Diksiyon becerisi.. Uzmanların jargon ve teknik deyimleri. Kaba argo çirkinliği. Aktif ve renkli fiillerle hayal gücü hareketi. Konuyu adıyla betimleme. Ve büyük zevk, nesne ve olayları birbiriyle karşılaştıran benzetme, analoji ve mecazlarla süsleme. Aslan, eşek hayvandır da, ama eşeği mi sevdiğim aslanı mı tercihim…“bir güzel söz söyleme sanatı, bir de güzel dinleme ve anlama sanatı, epiktekos”.

Ülkelerin dil renkliliğinden her biri… düşünüyorum da

Kaçıyla kontak kurabildiğim mi önemli? 

Kim ve ne oldukları araştırılmalı öyleyse…

Bir çok şey öğrenmiş olmak mı yeterli 

yoksa sıradan birilerine anlatmayı mı öğrenmek? 

Basit ve dolaysız şey anımsanır

İlginç ve canlı şey daha iyi anımsanır…

Zamlardan artık bıktık değil mi? 

Güya bu, kitleye canlı bir yakınlık…

Ama bana göre basit bir bönlük, sırtarma…

Eğitimci jargonun deneysel öğrenimi tercihi 

Anlatmak ve göstermek ayrışmazlığı…düşünüyorum da 

Geri-beslenim ne olacak? 

Kontrol bende mi? Prova yapmalı! 

Konuşma neticesi gösterecek harcanan emeğin değerini. Ama yine de ter akar buz gibi mimik, jest imdat diye kullanılır. Konuşurken fırsattır bunlar…Fuayelerde yüksek sesle yorum farklı…Fethe çıkış, “hayır yapmadım” denilmezlik..

Ne üzerine konuşmadık sanki yaşamda…

Kısmen paylaşmak istemediğimiz nedir ki…

Hatiple katibin arasındaki farkı düşünme

Müzik sanatı gibi ritmi, ahengi, ölçüsü, 

hatta bazen akort gerektiren melodisi de var…

düşünüyorum da

Ya yazılan elden çıkarsa? 

1976  Aachen anısı', 'İletişim araçları hem çok hızlı Hem de çok çeşitli haliyle Televizyon, radyo, gazete, dergi, bilgisayar, multimedya, film, video, faks, mode...', ARRAY['Türk Edebiyatı','Şiir','Sevinç Kavuk']::text[], 8.5, '{"poet":"Sevinç Kavuk","poet_slug":"sevinc-kavuk","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/dusunuyorum-da-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul', 'i-stanbul-huseyin-celik-m82ao', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Asrı saadettendi senin müjden; İstanbul,

Ta o günden kutsaldın, sevgiliydin, İstanbul.

Peygamberin hayalini, rüyasını süsleyen,

Ummandın, denizdin, seraptın İstanbul. 

O müjde ki ha İstanbul, ha Cennet.

Bu yüzdendi surlar önünde binlerce asalet.

Her biri kuşattı günlerce, aylarca seni, 

Fakat sen; etmedin ihanet

Varmalıydı o müjde, yerine varmalıydı,

O müjde Mehmet e, Türk e şan olmalıydı.

Fatih Sultan Mehmet''e armağan olmalıydı.

Ezan ve tekbir sesi, semaya dolmalıydı.

Ne kutsal bir davaydı, çünkü sende kutsaldın,

Adaletin beşiği inan sen olmalıydın.

Peygamberden Fatih''e bir Vatan olmalıydın.

İmanlı göğüslere, dolup ta taşmalıydın.

Sende yatar Evliyalar, Veliler. 

Sana hasret Peygamberler, Nebiler. 

Her zerrende diriliyor şehitler

Şüheda vatanı canım İstanbul.

Çan sesleri bitmeli, minarede ezanlar. 

İşte bu şanlı ordu, o tarihi yazanlar. 

Çalsında mehteranlar, inlesin borazanlar

Hesap veremez inan aramızı bozanlar.

Semt semt saysam, biter mi sendeki güzellikler? 

Sayfalara sığar mı sendeki özellikler? 

Sarayların bir cennet, camilerde ezanlar

Bu hoş sadayı söyler beş vakit müezzinler.

Anlatamam sende kötü bir taraf.

Ne fesatlık, ne düşmanlık ne de kin.

Değerini  biçemez en iyi  sarraf.

İstanbul elmas, inci İstanbul, zümrüt İstanbul.

Yedi düvel insanı, yetmiş iki milleti,

Yedi tepe üstüne inşa ettik biz seni,

Yedisinden yetmişe bütün millet hep seni,

Yedik, içtik, doyduk, kandık, aşkına yandık, İstanbul! 

Galata dan bir kuş gibi uçtuk Sarayburnu na,

Vatan diye sevdik seni, girdik sıcak koynuna.

Akif in dediği gibi, Yarab; bir Hilal uğruna,

Öldük, yandık, bittik, fakat tükenmedik İstanbul! 

Anlatmakla biter mi iki kıta cenneti? 

Tarih kokar buram buram her yeri.

Sırrını çözemedim öyle derin bilmece.

Hangi kitap ve lügat anlamadım İstanbul.

Yandın, bittin, kül oldun, tekrar tekrar dirildin.

Bir kar topu misali yuvarlandın irildin.

Ortasından boğazla sen ikiye ayrıydın,

İki kemer bağladık göbeğine İstanbul! 

Bağladık göbeğine iki kemer yol oldu.

Aşıkların sevindi sevdalılar şad oldu.

Sonbahar mevsiminde lalelerin hep soldu,

İlkbaharda açmasını bekliyoruz İstanbul! 

Dilim varmaz, incitemem ben seni. 

Ey İstanbul sende sevgi, merhamet

Bir şartım var bir kez görsem ben seni,

Şu sana aşığı bir kez mesut et.', 'Asrı saadettendi senin müjden; İstanbul, Ta o günden kutsaldın, sevgiliydin, İstanbul. Peygamberin hayalini, rüyasını süsleyen, Ummandın, de...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Çelik']::text[], 8.5, '{"poet":"Hüseyin Çelik","poet_slug":"huseyin-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/istanbul-410-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilseydi Nasıl Sevdiğimi', 'bilseydi-nasil-sevdigimi-yusuf-onder-bahceci-2uvjd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Eğer bilseydi kendisini nasıl sevdiğimi,

O yollarıma ölürdü, yollarıma gelirdi be,

Bilseydi düşünmeden, can vereceğimi,

O yollarıma ölürdü, yollarıma gelirdi be.

Şimdi kesin anlamıştır bilmeyen kalbi,

Eyvah, eyvah demiştir gülmeyen kalbi,

Onu çok seven bu kâlbi, Allah''ım verdi,

O yollarıma ölürdü, yollarıma gelirdi be.', 'Eğer bilseydi kendisini nasıl sevdiğimi, O yollarıma ölürdü, yollarıma gelirdi be, Bilseydi düşünmeden, can vereceğimi, O yollarıma ölürdü, ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bilseydi-nasil-sevdigimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaybolan Umitlere Gozyasim..', 'kaybolan-umitlere-gozyasim-haci-murat-ates-en023', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yitik bir sehir gibi anilarim 

Bir cocugun boynunu bukusu gibi 

Hep cikmaza girdi yarinlarim 

Oysaki ne umutlarla sevmistim seni 

Hayeller gercek olacakti 

Gozlerime gunes yeniden dogacakti 

Kalbimse senin sevginle cosacakti 

Sanma senin askina yaniyorum 

Senin icin aglamiyorum 

Kabyolan Umitlere Gozyasim... 

Oysaki ne cabalar sarfettim 

Bu gunlerde gecer dedim sabrettim 

Hatlarin oldu umursamadim 

Gozum kirpmadan affetim 

Inanmistim yarinlar icin umitlenmistim 

Kargasalar biter zamanla duzelir 

Beni benim sevdigim gibi sever demistim 

Sanma sana bu sitemlerim 

Senin icin yanmiyorum 

Yikilan hayellerime Gozyasim.. 

Simdi ise yanlizlikla savasiyorum 

Kendim sevdim kendim ettim 

Her seye gozyumdum biliyorum 

Inan sadece mutlu olmakti istegim 

Eller gibi bir yuva kurmakti dilegim 

Aksam eve gelince kapim acan olsun 

Sabah ise giderken savusturan olsun 

Kisacasi bir bekleyenim olsun istedim 

Ve kaderin oyununda yine yenildim 

Inan sana degil bu ozlemlerim 

Sana degil bu agitlarim 

Senin icin kahrolmuyorum 

Bosa Gecen yillarima Gozyasim.. 

B.U. 

Arnhem/ Elst. 

Tegen overde Alberthein. 

18.47.uur.', 'Yitik bir sehir gibi anilarim  Bir cocugun boynunu bukusu gibi  Hep cikmaza girdi yarinlarim  Oysaki ne umutlarla sevmistim seni  Hayeller g...', ARRAY['Türk Edebiyatı','Şiir','Haci Murat Ates']::text[], 8.5, '{"poet":"Haci Murat Ates","poet_slug":"haci-murat-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/kaybolan-umitlere-gozyasim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yasgan', 'yasgan-cagdas-yildiz-1o69g', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yastığım, yorganım olmuş

yorganım yastığım...

bir boyun bük,

bin kere üstünü ört istersen..

sırtımı sırtına verip de gözlerimi yumduğum; 

anlayacağın, 

yasganım olmuşsun..

elden gel

omzumuz omuz olsun...', 'yastığım, yorganım olmuş yorganım yastığım... bir boyun bük, bin kere üstünü ört istersen.. sırtımı sırtına verip de gözlerimi yumduğum;  an...', ARRAY['Türk Edebiyatı','Şiir','Çağdaş Yıldız']::text[], 8.5, '{"poet":"Çağdaş Yıldız","poet_slug":"cagdas-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yasgan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senli benli', 'senli-benli-cagdas-yildiz-j7aph', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'hadi al beni,

al senin olsun..

ellerini al da bak; 

belki biraz da ben bulursun...', 'hadi al beni, al senin olsun.. ellerini al da bak;  belki biraz da ben bulursun......', ARRAY['Türk Edebiyatı','Şiir','Çağdaş Yıldız']::text[], 8.5, '{"poet":"Çağdaş Yıldız","poet_slug":"cagdas-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/senli-benli-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koca Adam', 'koca-adam-cenk-aksal-1fntt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'son gelen de gitti ardından

bilinmeze doğru,

inanmadığın tesadüflerinin

kurbanı oldun,

bilesin son anında bile senin

doğrularının ardında durdum,

yürüdüğün yolda ben koştum,

ulaşamadığın yerlerde

ben oldum dostum,

şimdi iki metrelik bir yerde,

bizden uzaktasın,

bilesin ki:ben ve benim gibiler,

her an yanında dostum,

var olduğun yer isterimki,

nur içinde olsun,

yazdığım şiirler bitmeyecek,

adın hiç silinmeyecek,

sonsuza dek seninleyiz,

benim güzel dostum...

16/03/2006

yüreğimizdesin koca adam....', 'son gelen de gitti ardından bilinmeze doğru, inanmadığın tesadüflerinin kurbanı oldun, bilesin son anında bile senin doğrularının ardında du...', ARRAY['Türk Edebiyatı','Şiir','Cenk Aksal']::text[], 8.5, '{"poet":"Cenk Aksal","poet_slug":"cenk-aksal","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/koca-adam-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özgürlüğüm', 'ozgurlugum-cagdas-yildiz-oomcr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ardı ardına sıralanmış,

uykulu ağlamaklar geçerken penceremden,

hiç değilse; 

kol kola girmiş birikintilere,

çamur olmak geçiyor içimden...

çocuklarla oynaşıp,

umursamaz bir araba yardımıyla

sıçramak bembeyaz parkelere..

bir avuç küfürle kafa bulmak

neye yarar? 

burnumu yaslasam yaşamaya; 

buğulu bir set çekiyor dünyaya

derin nefeslerim...

her ne kadar, 

ayakta sevişip,

anadan doğma yüzdüysem de yatağında; 

yanaklarımın yağmurdan ıslandığı kadar özgürlüğüm..', 'ardı ardına sıralanmış, uykulu ağlamaklar geçerken penceremden, hiç değilse;  kol kola girmiş birikintilere, çamur olmak geçiyor içimden... ...', ARRAY['Türk Edebiyatı','Şiir','Çağdaş Yıldız']::text[], 8.5, '{"poet":"Çağdaş Yıldız","poet_slug":"cagdas-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ozgurlugum-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Dost/a', 'bir-dost-a-ahmet-turan-altunsu-8xukd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'hey dost! ..

ne demiştim ben? ..

gölgeme bak ve anla! 

saatlerin gece yarısına düştüğü `an`la

örtüşür kaygıları, pusuya yatan...

tıpkı bir sırtlan edasıyla 

avını beklerken yüreği sevinçle atan

bir mutantan çehre ile karşılaşırsın; 

işte öylesine alaycıl vedasıyla...

ah dost! ..

daha ne zaman anlayacaksın? ..

gün ışığında yarasa beklemekse maksadın; 

bekle, dur! 

avuçlarını yalayacaksın! 

velhasıl dost; 

bu değneğin iki ucu da bokludur...

heyhat! .. beklediğinle kalacaksın! 

ve unutma asla:

şeytan, daima yüksek topukludur! 

.......08.03.2006 / Ankara

.......Ahmet Turan Altunsu', 'hey dost! .. ne demiştim ben? .. gölgeme bak ve anla!  saatlerin gece yarısına düştüğü `an`la örtüşür kaygıları, pusuya yatan... tıpkı bir s...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Turan Altunsu']::text[], 8.5, '{"poet":"Ahmet Turan Altunsu","poet_slug":"ahmet-turan-altunsu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bir-dost-a-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nece .. Vardir Bizde', 'nece-vardir-bizde-yasar-gurlek-9y7ck', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sasarim  bu  ise,  utan  be  utan

Deveyi  hamuduyla  yutan

Sahtekarin elinden  tutan

Nece  ........   vardir  bizde

Soyup  sogana  cevirir

Haklilari  devirir

Coklarinca  sevilir

Nece  ........  vardir bizde

Haksiz yerde hakli olur

Akilsizin akli  olur

Ciceklere saksi olur

Nece .......   vardir  bizde

Yasar,i der  yapma  bunu

Aglatma  onu  sunu

Babasinin  cocugu

Nece ....... vardir  bizde

Yasar   gurlek 

18-03-2006

Rotterdam

Hollanda', 'Sasarim  bu  ise,  utan  be  utan Deveyi  hamuduyla  yutan Sahtekarin elinden  tutan Nece  ........   vardir  bizde Soyup  sogana  cevirir H...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Gürlek']::text[], 8.5, '{"poet":"Yaşar Gürlek","poet_slug":"yasar-gurlek","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/nece-vardir-bizde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir saniye', 'bir-saniye-emel-hicyilmaz-gmtv4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yalnız,

   Yalnızca bir saniye veriyorum sana! 

   Bana önce; 

   Çocuk olmayı öğreteceksin! 

   Sonra sırasıyla; 

   Koca bir budala,

   Aşık bir yürek,

   Bir sürü torun sahibi bir nine,

   Coşkun bir deniz,

   Bembeyaz bir bulut,

   Ürkek bir güvercin,

   Sadık bir dost,

   Şefkatli bir ana,

   Kırık bir kalem,

   Acılar içinde bir hasta,

   İdam sehpasındaki bir mahkum,

   Tuzağa düşmüş bir ceylan,

   Mutlu br gözyaşı,

   İsyankar bir dalga,

   Bardağa hapsolmuş çay kaşığı,

   Tuvalin tek tutar dalı; boya,

   Masanın dördüncü bacağı,

   Aldığın soluk,

   Yaprağın klorofili,

   Hayatın anlamı,

   Düşlerin güzelliği,

   Ateşin sıcaklığı

   Ve 

   Ayazın hazin sesi olmayı öğreteceksin! 

   Çok mu zor diyorsun? ! 

   Neden o bir saniyeyi,

   Gözlerime bakarak değerlendirmiyorsun?', 'Yalnız,    Yalnızca bir saniye veriyorum sana!     Bana önce;     Çocuk olmayı öğreteceksin!     Sonra sırasıyla;     Koca bir budala,    Aş...', ARRAY['Türk Edebiyatı','Şiir','Emel Hiçyılmaz']::text[], 8.5, '{"poet":"Emel Hiçyılmaz","poet_slug":"emel-hicyilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/bir-saniye-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Varsın', 'sen-varsin-vahit-kara-3pcrd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Amadeyim her sözüne bi perva,

Yegane sen varsın sen olacaksın.

Emvaç olsan, encamında ben varım,

Her girnemde hafi hafi sen varsın.

bilmem hicran mıdır bu aşkın sonu,

vaveylalar kaplıdır sılanın yolu,

leyalin ibtida-i badeyle dolu,

her kadeh bitişinde, dilde sen varsın...

                                  Vahit Kara', 'Amadeyim her sözüne bi perva, Yegane sen varsın sen olacaksın. Emvaç olsan, encamında ben varım, Her girnemde hafi hafi sen varsın. bilmem h...', ARRAY['Türk Edebiyatı','Şiir','Vahit Kara']::text[], 8.5, '{"poet":"Vahit Kara","poet_slug":"vahit-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sen-varsin-61-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ruhsuz Beden', 'ruhsuz-beden-saliha-gulenler-j15xp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben doğarken başlamadım yaşamaya,

Severken başladım! ! 

Sevgimdi hıpalanan hoyrat ellerde,

Yalandı mutluluğum çalıntı yüreklerde,

Yamalı sevdalardı...

Temiz sevgilerdi paylaşılan,

Dostluktu onlardan kalan.

Ve fesadın iğrenç elleri kopardı

Tüm güzellikleri yaşamımdan. 

Kör bir karanlığın kucağındayım şimdi...

Benden uzaklarda doğuyor güneş

Mevsimler değişiyor,

Mutluluklar yaşanıyor,

Sevdalar büyütülüyor.

Kuru bir ağaç dalı gibi ben

Ruhsuz bir beden

Anladım ki ölünce yok olmuyor insan

Ölmek bile sevgisizlikten..

Oysa ben sevebildiğim kadar mutlu,

Sevebildiğim kadar insan. 

Ve sevgiler yaşanıyor benden uzaklarda

Şimdi yalnızca ölüm mü oldu bana yaklaşan! !', 'Ben doğarken başlamadım yaşamaya, Severken başladım! !  Sevgimdi hıpalanan hoyrat ellerde, Yalandı mutluluğum çalıntı yüreklerde, Yamalı sev...', ARRAY['Türk Edebiyatı','Şiir','Saliha Gülenler']::text[], 8.5, '{"poet":"Saliha Gülenler","poet_slug":"saliha-gulenler","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ruhsuz-beden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün senin günün', 'gun-senin-gunun-belkis-eren-v5ojf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gün senin günün,

bugün  hüzün,gamlı bir karanlık.

Herkes uyuyor.Kuş uyuyor,yaprak uyuyor,karanlık uyuyor...

güneş ısrarlı ama bulutlar gizemini koruyor,

seçilmiyor bu esrarengiz sokaklar.

Sanki evren anlaşmış gibi

bulut güneşi,güneş ağacı,ağaç toprağı görmezden geliyor.

sır dolu gözlerini arıyorum,tutuyorum ellerini....

bulutun güneşi sarmaladığı gibi sarıyorum seni.

ararım seni havanın hüznünde,güneşin kalbinde

sen de ara beni kalbinin ritminde....', 'Gün senin günün, bugün  hüzün,gamlı bir karanlık. Herkes uyuyor.Kuş uyuyor,yaprak uyuyor,karanlık uyuyor... güneş ısrarlı ama bulutlar gizem...', ARRAY['Türk Edebiyatı','Şiir','Belkıs Eren']::text[], 8.5, '{"poet":"Belkıs Eren","poet_slug":"belkis-eren","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gun-senin-gunun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Garip Gezerim Boyle', 'garip-gezerim-boyle-yasar-gurlek-buc8s', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Cikmaz  oldun  sarayimdan  koskumden

Berduse  avareyim cane  askindan

Ne  farkim  kalmis,ki benim saskindan

Bi care ben garip gezerim boyle

Sendedir  anahtari  gonul  koskumun

Bilmedin kiymetini cane  benim askimin

Divaneyim  berdusem  cok  sasginim

Bi care  ben  garip  donerim  boyle

Hem sagimda hem solumda guller  aciyor

Burcusunu  miksini  sana  koku  saciyor

Cumle  alem duyup bana  aciyor

Bi  care  ben garip  yanarim  boyle

Yasar,i  tas  olup  cat  catlasinmi

Her  olur olmaza  pat  patlasinmi

Hep   senin  icin  gur  gurlesinmi

Bi care  ben  garip mazlumum  boyle

Yasar  Gurlek

18-03-2006

ROTTERDAM

HOLLANDA', 'Cikmaz  oldun  sarayimdan  koskumden Berduse  avareyim cane  askindan Ne  farkim  kalmis,ki benim saskindan Bi care ben garip gezerim boyle ...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Gürlek']::text[], 8.5, '{"poet":"Yaşar Gürlek","poet_slug":"yasar-gurlek","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/garip-gezerim-boyle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz bir gün', 'sensiz-bir-gun-belkis-eren-59bua', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gün senin günün,

bugün  hüzün,gamlı bir karanlık.

Herkes uyuyor.Kuş uyuyor,yaprak uyuyor,karanlık uyuyor...

güneş ısrarlı ama bulutlar gizemini koruyor,

seçilmiyor bu esrarengiz sokaklar.

Sanki evren anlaşmış gibi

bulut güneşi,güneş ağacı,ağaç toprağı görmezden geliyor.

sır dolu gözlerini arıyorum,tutuyorum ellerini....

bulutun güneşi sarmaladığı gibi sarıyorum seni.

ararım seni havanın hüznünde,güneşin kalbinde

sen de ara beni kalbinin ritminde....', 'Gün senin günün, bugün  hüzün,gamlı bir karanlık. Herkes uyuyor.Kuş uyuyor,yaprak uyuyor,karanlık uyuyor... güneş ısrarlı ama bulutlar gizem...', ARRAY['Türk Edebiyatı','Şiir','Belkıs Eren']::text[], 8.5, '{"poet":"Belkıs Eren","poet_slug":"belkis-eren","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sensiz-bir-gun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilirsin Ya Neyse', 'bilirsin-ya-neyse-i-kbal-cansiz-xx4n9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir çizgi çizilmiş eğri ve büğrü

Düzen dedikleri bu olsa gayrı

Sevgiye mezarı kazanlar aynı

Suç bizde mi onlarda mı bilemem

Bir laf atmışlar çağdaşlık diye

Mazluma vermişler hediye diye

Uşak ol hakkındır, yükseldin diye

Kanaat mı kabahat mı bilemem

Hakaretin adı olmaz, kesin irticacıdır

Bilmezler ki yediği ölü kardeş etidir

Nasıl bir kazanç ki, insanlığın sonudur

İnsanlık mı hayvanlık mı bilemem

Bir dizi hikaye bir dizi dümen

Yok kardeşim ben bunlara gelemem

Gerekirse başımı dahi esirgemem

İntihar mı şehadetmi bilemem

               İKBAL CANSIZ', 'Bir çizgi çizilmiş eğri ve büğrü Düzen dedikleri bu olsa gayrı Sevgiye mezarı kazanlar aynı Suç bizde mi onlarda mı bilemem Bir laf atmışlar...', ARRAY['Türk Edebiyatı','Şiir','İkbal Cansız']::text[], 8.5, '{"poet":"İkbal Cansız","poet_slug":"i-kbal-cansiz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bilirsin-ya-neyse-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmiyor', 'bilmiyor-sair-rasat-c6akr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu nasılbir iştir, bu nasıl çile 

Mutsuzluk ömrümden gitmek bilmiyor,

Beynim yüreğime hükmetmez olmuş,

İçimde bir hesap bitmek bilmiyor..

            İnsanlar halime dönüp bakmıyor,

            Haykırmak isterim sesim çıkmıyor

            Boğazımdfa bir şey düğümleniyor,

            Yaşlar gözlerimden akmak bilmiyor..

Neden her iş böyle her çile neden,

Zamanda düşmanım geçmiyor zaten,

Bir tek kulun yokmu gönülden seven,

Sevgiler gönlüme girmek bilmiyor..

              Sonu hiç gelmiyor acılar kervan, 

              Şansım dömüyor bu nasıl devran,

              Etrafım dört duvar etrafım zindan,

              Müebbetmi cezam bitmek bilmiyor....', 'Bu nasılbir iştir, bu nasıl çile  Mutsuzluk ömrümden gitmek bilmiyor, Beynim yüreğime hükmetmez olmuş, İçimde bir hesap bitmek bilmiyor..   ...', ARRAY['Türk Edebiyatı','Şiir','Şair Rasat']::text[], 8.5, '{"poet":"Şair Rasat","poet_slug":"sair-rasat","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bilmiyor-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hani Kardeştik', 'hani-kardestik-hasan-ozturk-2-hzga6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hani kardeştik,

Güzel günler görecektik.

Gün görmemiş umutları mı,

Ne cabuk soldurdun hani.

Saygı, barış, hoşgörü, 

Adına geldikçe kapına.

Hep bana gösterdin,

Aba altından sopa.

Yürürdük, 

İnönü Bulvarın''da,

Aklın fikrin varya,

Nedendir bilmem havada suda.

Sormadınmı sen kardeşine,

Söyle saçma sapan soruları.

Nereye bu gidiş bu yaşta.

Hangimiz kalıcı, söyle bana,

Şu fani dünyada.

Bir düşün, düşün ki,

Geçmişin gelsin aklına.

Kalbinde ahtı vefa varsa.

Saygın olsaydı emekten yana,

Unutmaz hatırlardın şimdi,

Sabaha kadar çalışıp,

Uğruna harcadığım

Son kuruşa.

Koymak imkansız oldu,

Zengin olunca elini vicdanına.

Bu gidiş söyle ne yana.

Sen hep derdin ya,

İnsanlar doğar büyür ölür.

Bende diyorum ki sana.

İnsanlar yaşarkende ölür.

Ölüden farkın yok yanım''da.

Yalnız yürüyorum Bulvar''da.

Vakitsiz gidersem bir gün.

Sakın ha dokunma salıma,

Gözlerim neyse ne de,

Zevk aldınmı

Yüreğimi acıtınca.

Bu kin bu şiddet bu hiddet.

Bu söylemler yakışmadı hiç sana.

Hakkımı helal etmek isterdim.

Bir bayram elini öpmek,

Yüzüne bakınca gülmek,

Çok isterdim çok ama,

Kalp kırılınca bir defa,

Sevemez artık birden sonra,

Agzınla kuş tutsanda,

Kardeşim var sayma...

.............................................

Diye yazmıştım sana,

Yinede atamıyorum,

Çektiğimiz dertler hatırına.

Duydum sorgulanıyormuşsun konakta,

Ben arka sokakta,

Yüregimi bölüp parçalasan''da.

Keyfim kaçık, 

Bir ağrı var başımda.

Git gel derken,

Yazmak istemedim.

Ellerin kelepçeli,

Yüzünden düşen bin parça.

Şimdi götürüyor mapusa,

Mavi boyalı araba.

Ben özgür sen göz altında.

Elimle sildim gözyaşımı.

Sen sırtımızdan vursan.

Sevğin bakimi bilmem,

Seni sevmiyorum desem.

Buğün mapustaki

İkinci günün,

Adına şafak tutuyorum.

Ziyaretinede gelemiyorum,

Soy adım''da tutmuyor.

Seni düşünmekten her gece,

Uykularım kaçıyor.

Bir paket siğara,

Bir şişe kolanya gönderdim.

Okul arkadaşım gardiyanla.

Çok çok özlüyorsundur.

Kavak ağacının gölgesini,

Ali amcanın dükkanını,

Cumartesiyi pazarı,

O tatlı saltanatı,

Sordum gardiyana,

Kimse geliyormu yanına,

Gelmiyor dedi bana,

Ah ah dedim iyi bak ona.

Şimdi gidiyordur zoruna.

Ağa paşa diyenlerin,

Acizler iki satır yazmaya.

Bu hayat zor geldi,

Evlat acısı gibi bana,

Diyormuşsun volta atıp koridorda.

Demeye dilim varmıyor ama,

Sana caputcu diyenler,

Kendilerine göre buldu ağa,

Biz ise seni soruyoruz,

Hala sağa sola.

Dün gece düşümde,

Bir futbol sahasında,

Kapalı spor salonu,

Dağ başında direkler,

Rüzgardan enerji üretiyordu.

Marketler zinçiri,

Cığ gibi büyüyordu.

Bir fabrika kuruldu,

Uzadı işsizlik kuyruğu.

Köprüler yıkılıyordu,

Fakir fukaraya,

Bir pusula veriliyordu.

Davul zurna çalıyordu.

Garipler oynuyordu.

Uyandım birdenbire,

Dışarda yağmur yağıyordu.

Ah dedim abim ah...

Mapusta iki yıl geçmek bilmedi.

Deri kemik kaldı.

Şekeride çok yükseldi.

Haksızlık ettim dostlara,

Pişmanım ha.......

Diyormuş oğlu söyledi.

Ve serbest bırakıldı,

Sokağa cıkmış dolaşmış,

Eski havayı aramış.

Öyle bir yanılmış ki.

Hayat gitmiş zoruna.

Kimse yanaşmıyormuş yanına.

Alkol siğaraya sarılmış.

Eve gitmiyormuş akşamları.

Meyhaneye takılıyormuş,

Çarşamba günü sızıp kalmış,

Köşedeki bakımsız parkta.

Kardeşi yetişmiş imdadına,

Sarılmış abisinin boynuna,

Helal et yiyenim,

Haydi bana hakkına.

Bir konuşma geçmiş,

İkisinin arasında.

Laflar gitmiş zoruna.

Abisi kıymış canına.

Abisi gidince,

O da küsmüş hayata.

Yaşanırmı bu kahırla,

Alıp götürdüler onuda,

Öyle namazından sonra,

Mezarlar oldu yanyana,

Ne yapıyor bilinmez,

İkiside öbür dünyada.

Hasan Öztürk  18.03.2006 Yatağan / Muğla', 'Hani kardeştik, Güzel günler görecektik. Gün görmemiş umutları mı, Ne cabuk soldurdun hani. Saygı, barış, hoşgörü,  Adına geldikçe kapına. H...', ARRAY['Türk Edebiyatı','Şiir','Hasan Öztürk 2']::text[], 8.5, '{"poet":"Hasan Öztürk 2","poet_slug":"hasan-ozturk-2","theme":"Türk Şiiri","is_hero":false,"total_lines":150,"source_url":"https://www.antoloji.com/hani-kardestik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canı Neyleyim', 'cani-neyleyim-sair-rasat-9lv8n', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne param ne pulum ne sevenim var, 

Haytımı sardı koca yalanla,

Çiçeğim soluyor açmaz goncalar, 

Gülbahçem kurudu canı neyleyim.

                Karalar bağlamış yazmıyor kalem,

                Derdimi dinlemez bakmaz ki alem,

                Hayatımı sarmış cümleten elem, 

                Gülbahçem kurudu canı neyleyim..

Gönlüm hasret kaldı biraz sevgiye,

Yazıın ortasında kışı neyleye, 

Gündüz bana küsmüş, ben gecelere,

Gülbahçem kurudu canı neyleyim,

Cananı kaybettim ömrü neyleyim...', 'Ne param ne pulum ne sevenim var,  Haytımı sardı koca yalanla, Çiçeğim soluyor açmaz goncalar,  Gülbahçem kurudu canı neyleyim.             ...', ARRAY['Türk Edebiyatı','Şiir','Şair Rasat']::text[], 8.5, '{"poet":"Şair Rasat","poet_slug":"sair-rasat","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/cani-neyleyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olsun gitsin', 'olsun-gitsin-mikdat-bal-z0bn7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yaşamaksa eğer nefes alışım

İşte yakıyorum kül olsun gitsin

Hareketse eğer gidiş gelişim

işte çıkıyorum yol olsun gitsin

Büyüsem de onun bunun gözünde

Bir şey olamadım dünya yüzünde

Biraz uyuduysam yarin dizinde

İşte akıyorum göl olsun gitsin

Madem yalan varı yoğu alemin

Ne gereği vardır bunca elemin

Bir türlü dolaşık açmaz çilemin

İşte bakıyorum hal olsun gitsin

Peşimden gelmez ya dünyanın malı

Felek kırıverdi bastığım dalı

Miktatî bulmadı bir parmak balı

İşte okuyorum Bal olsun gitsin

……. kurutun kökünü çal olsun gitsin', 'Yaşamaksa eğer nefes alışım İşte yakıyorum kül olsun gitsin Hareketse eğer gidiş gelişim işte çıkıyorum yol olsun gitsin Büyüsem de onun bun...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/olsun-gitsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ve', 've-ufuk-bayraktar-780k6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'biliyor musun

en sevdiğim kelime

''''ve''''dir benim.

aşk ve sen

sen ve hasret

hasret ve ben.

sen ve ben gibi mesela...', 'biliyor musun en sevdiğim kelime ''''ve''''dir benim. aşk ve sen sen ve hasret hasret ve ben. sen ve ben gibi mesela......', ARRAY['Türk Edebiyatı','Şiir','Ufuk Bayraktar']::text[], 8.5, '{"poet":"Ufuk Bayraktar","poet_slug":"ufuk-bayraktar","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ve-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül-Bülbül Karmaşası', 'gul-bulbul-karmasasi-saliha-gulenler-piy0j', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bülbül müyüm,gül müyüm,

Hala anlıyamadım.

Gül de açtı gönlümde,

Bülbül de ağırladım.

Gül olmam gerekirken,

Bülbül gibi şakıdım.

Hem bülbüle yar oldum,

Hem güle sevdalandım.

Ben hangisiyim ya,

Bir türlü bulamadım.

Aslına bakarsanız,

Bir seçenek daha var:

Dikeniyle tanırlar,

Yoktur fazla seveni,

Çok nazlı çiçek açar,

Çölde yaşayan kaktüs,

Bana daha çok uyar.', 'Bülbül müyüm,gül müyüm, Hala anlıyamadım. Gül de açtı gönlümde, Bülbül de ağırladım. Gül olmam gerekirken, Bülbül gibi şakıdım. Hem bülbüle ...', ARRAY['Türk Edebiyatı','Şiir','Saliha Gülenler']::text[], 8.5, '{"poet":"Saliha Gülenler","poet_slug":"saliha-gulenler","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gul-bulbul-karmasasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuşkum', 'kuskum-ahmet-nural-ozturk-lrsqx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'uzaklarda olman değil

uzak neresi bilmeyişim

belki de uzağı yakın

yakını uzak sanışım

bir tuzakta bir sarışınla yatışım

kuşkum', 'uzaklarda olman değil uzak neresi bilmeyişim belki de uzağı yakın yakını uzak sanışım bir tuzakta bir sarışınla yatışım kuşkum...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Nural Öztürk']::text[], 8.5, '{"poet":"Ahmet Nural Öztürk","poet_slug":"ahmet-nural-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kuskum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kösele Giyenler', 'kosele-giyenler-ahmet-mete-w6fq2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ne! ...

efendi, sen bilmez misin? 

tabii ya kösele giyenler bilirler elbet,

ezilir altında kum tanecikleri,

gelir çıtır çıtır yok oluşları.

her atşında adımını asfaltta yankı

tırank...

koridorlarda onla dolaşmak aykırı,

ben burdayım der soluk alışlarında.

haykırır defalarca ''ben varım'' diye.

parlarken yüzü vuran güneşle, 

onundur hoyrat caddeler,

............. çilekeş sokaklar.

aldırış etmez omzundaki yüke,

sırtlanır gider doğru hedefe.

giymemiş olan bilmez elbet.

dönüp bakanlara müsamahası yok; 

ödün vermez asaletinden,

kirletmez kendini haram bakışlarla,

kiristaldir yani özü...

olmak ya da olmamak; 

sorun değil onun için,

o kendini......

................ bilmesi gerekeni...

tek derdi var,

...................... o da:

................................ eskimek...? ? ?', 'ne! ... efendi, sen bilmez misin?  tabii ya kösele giyenler bilirler elbet, ezilir altında kum tanecikleri, gelir çıtır çıtır yok oluşları. ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Mete']::text[], 8.5, '{"poet":"Ahmet Mete","poet_slug":"ahmet-mete","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/kosele-giyenler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YALNIZLIK GÜZeLDİR...', 'yalnizlik-guzeldi-r-yasemin-cagla-my4ky', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '.yalnızlık güzeldirrrrr

Yalnızlığın en iyi yanı nedir bilirmisin? 

Hiç hayali olmuyor insanın,umudu da.

Hiç yatırıp gözlerini ıraklara,

Gelecek birini beklemiyor,

"O gelecekti, gelmedi" diye üzülmüyorsun.

Gidenlere "gitme kal" demiyorsun.

Hani mutlu olmak gibi bir çaban da olmuyor.

Bir şeyler umut edip beklemekte.

Ufacık şeylere sevinmekte.

Zaman geçsin diye voltada atmıyor insan gecenin anlına, anlına

Günleri saymıyor, saatlere bakmıyorsun.

Sükut hiç olmadığı  kadar altın oluyor.

Konuşmaya mecbur değilsin.

Mecbur değilsin gülmeye.

Mecbur değilsin başkaları için kendini heder etmeye.

Yalnızlık güzeldir yaşanan acıların ardından.

Geceye mahkumsun,mahkumsun sessizliğe.

Yalnızlık güzeldir ta ki ölüme.

Yalnızlık yolcusuyum taaa ki ölüme...', '.yalnızlık güzeldirrrrr Yalnızlığın en iyi yanı nedir bilirmisin?  Hiç hayali olmuyor insanın,umudu da. Hiç yatırıp gözlerini ıraklara, Gele...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Çağla']::text[], 8.5, '{"poet":"Yasemin Çağla","poet_slug":"yasemin-cagla","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yalnizlik-guzeldir-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiyi Hasret Besler', 'sevgiyi-hasret-besler-saliha-gulenler-exqhu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir düştün ki içime,

Yangın çıktı sanırsın.

Yüreğimden kabarıp,

Gözpınarımdan taşan,

İnci tanelerinin,

Her birinde sen varsın.

Varsın sel olup aksın,

Nasıl  söner bu yangın? 

Sana ait her şeyim,

Sevgi,umut,hasretim,

Onlar aktıkça yaşar.

Bir gün dinerse onlar,

Bil ki artık içimde,

Ne yangın,ne de seller,

Büyük bir kuraklık var.', 'Bir düştün ki içime, Yangın çıktı sanırsın. Yüreğimden kabarıp, Gözpınarımdan taşan, İnci tanelerinin, Her birinde sen varsın. Varsın sel ol...', ARRAY['Türk Edebiyatı','Şiir','Saliha Gülenler']::text[], 8.5, '{"poet":"Saliha Gülenler","poet_slug":"saliha-gulenler","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sevgiyi-hasret-besler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pişmanım', 'pismanim-tevfik-yasar-tekeli-rpwd2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ayrılık  öyle acı,  öyle acımasız ki

Gülüm, seni bırakıp geldiğime  pişmanım.

Aşkınsa öyle güzel,  öyle dayanılmaz  ki…

Ayrılık  oldu  diye  sevdiğime  pişmanım! 

Hiçbir şeyin tadı yok,  sensiz karanlık  her yer

Gönlümse gamla dolu, dert ki ölümden beter.

Bilmem bu can… bu beden nasıl tahammül eder? 

Öyle yaktın ki beni,  yandığıma pişmanım…

Her  güzelde hayalin, her iyide izin var.

En anlamsız köşede senin gülen yüzün var.

Gözlerimde gözlerin, yüreğimde sözün var

Ben şimdi o sözleri duyduğuma pişmanım…



Gülümsün! Kızma bana; sana değil sitemim.

Hasret ve bu gurbetten yaralıdır  yüreğim! 

İzin ver  bir göreyim… sonra iste öleyim,

Sensiz yaşamak ölüm… doğduğuma  pişmanım...', 'Ayrılık  öyle acı,  öyle acımasız ki Gülüm, seni bırakıp geldiğime  pişmanım. Aşkınsa öyle güzel,  öyle dayanılmaz  ki… Ayrılık  oldu  diye ...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Yaşar Tekeli']::text[], 8.5, '{"poet":"Tevfik Yaşar Tekeli","poet_slug":"tevfik-yasar-tekeli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/pismanim-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çalmasın Kapımı Postacı Artık', 'calmasin-kapimi-postaci-artik-tevfik-yasar-tekeli-qic3e', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çalmasın kapımı postacı artık,

İstemem hiç kimse bilmesin beni.

Kalayım ben böyle, hep kalbi kırık,

En tenha köşeler  söylesin beni …

Her mektup  bir haber veriyor  ama

Hepsi de  hicranla  bin gamla  dolu.

Teselli yok kesin; mahzun  ruhuma

Yok  hayatımın  sabit bir  yolu…

İstemem, istemem…istemem  kalsın,

Bana mektup verme… verme postacı

Gözlerim yollarda seni arasın,

Tattırma bana sen yeni bir  acı…

                                13     09     82    Tuzla/ İstanbul', 'Çalmasın kapımı postacı artık, İstemem hiç kimse bilmesin beni. Kalayım ben böyle, hep kalbi kırık, En tenha köşeler  söylesin beni … Her me...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Yaşar Tekeli']::text[], 8.5, '{"poet":"Tevfik Yaşar Tekeli","poet_slug":"tevfik-yasar-tekeli","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/calmasin-kapimi-postaci-artik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Ömür Muhasebesi', 'bir-omur-muhasebesi-tevfik-yasar-tekeli-z40oy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ölüm gelmez aklına insanoğlu şen iken

Bülbül susmaz öter hep  viran bağ  gülşen iken…

Lakin  hayat fanidir; ‘bugün’  var, ati meçhul

Bunu hiç düşünmeden yaşıyor  hayatı  kul.

Düzense işletiyor, o  zalim çarklarını 

Dolduruyor  insanlar küfrün tüm arklarını.

Gaye ne, hedefi ne?  Hiç bilmiyor pek çoğu,

Hep  boşluk hep uçurum; çoğunun varı yoğu.

Hedef  gösteriliyor tüm  dipsiz bataklıklar,

Irmaklar kurutulmuş, mezar olmuş yataklar…

Bir tarafta kahkaha,  öbür yanda  gözyaşı

Şeytanlar ve melekler layıkların  sırdaşı…

Akar sular  misali, şırıl şırıl bu hayat

Çoğu bilmez  gerçeği, geçer bir ömür heyhat…

Doğmak bugünse  eğer, yarın: ölüm demektir! 

İki  nefes  arası  koca  ömür  demektir

Kimine  tatlı hülya, kimine bir  hüsrandır,

Neticede bir ömür,  koca bir imtihandır…

Elbet vardır her günün bir sonrası, yarını…

Kim gayesin  bilirse...  o  görür  kazancını…', 'Ölüm gelmez aklına insanoğlu şen iken Bülbül susmaz öter hep  viran bağ  gülşen iken… Lakin  hayat fanidir; ‘bugün’  var, ati meçhul Bunu hi...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Yaşar Tekeli']::text[], 8.5, '{"poet":"Tevfik Yaşar Tekeli","poet_slug":"tevfik-yasar-tekeli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bir-omur-muhasebesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Hediye', 'son-hediye-tevfik-yasar-tekeli-pdylr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ölüme  varıyor  en  uzun  yollar,

Geçse de  her  anı  kahkahalarla…

Çaresiz  gidiyor,  bir bir  insanlar,

Yaşamak  bir  ümit  hoş anılarla..

Zaman bir değirmen, döndükçe ezen

Farkına  varmıyor insan talaşla.

Zaman ki: güldüren, zaman ki: ezen

İnsansa iç içe bu son savaşla...

Her şey  boş,   ölümlü;   baki kalan  yok.

Ne mal,  mülk,  şan,  şöhret … hepsi  hikaye.

Bir  sevgi  dünyaya... sanki sonu yok,

Bir kefen;  bir dua …  en son hediye.', 'Ölüme  varıyor  en  uzun  yollar, Geçse de  her  anı  kahkahalarla… Çaresiz  gidiyor,  bir bir  insanlar, Yaşamak  bir  ümit  hoş anılarla.....', ARRAY['Türk Edebiyatı','Şiir','Tevfik Yaşar Tekeli']::text[], 8.5, '{"poet":"Tevfik Yaşar Tekeli","poet_slug":"tevfik-yasar-tekeli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/son-hediye-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşasın Bulvarlar', 'yasasin-bulvarlar-tevfik-yasar-tekeli-lq0eg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Arnavut taşlarını söktük önce,

Maziye dekor oldu

Sütçü beygirlerinin nal sesleri…

Cumbalı evlerimiz ya müteahhitte 

Ya da… alevlerin pençesinde,

Çok yüksekte artık pencereler

Pembe sardunyalar ise çoktan soldu.

“Cümle kapıları”mız da yok şimdi,

önünde oturup sohbet ettiğimiz…

Ve  yok, sokaklarda 

Paylaştığımız  “Sevgilerimiz”…

Ya ölüyoruz şimdi  yapayalnız

Ya da öldürüyoruz birbirimizi…

        Yer kalmadı yeşile

Asfalt denen mezar  örtüsünden.

Kuşlar yok ki … şen nağmeleri olsun

Egzoz dumanından, motor gürültüsünden.

Çocuklara yasakladık kapı dışarı çıkmayı, 

“ cıss! ”  dedik yalınayak koşmaya toprakta…

Hastalıklı doğdu bebelerimiz; 

Alışamadı cam kafeslerde yaşamaya…

 şimdi                      

Ne selamlaşan insanlar var,

Fırsat bulup koşuşturmaktan.

Ne de oyun oynayan çocuklar yalınayak, başı kabak…

Öldü sonunda sokaklar…

Şimdi saltanat onlarda

Yaşasın   o      b u l v a r l a r... 

                                       Mayıs  99', 'Arnavut taşlarını söktük önce, Maziye dekor oldu Sütçü beygirlerinin nal sesleri… Cumbalı evlerimiz ya müteahhitte  Ya da… alevlerin pençesi...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Yaşar Tekeli']::text[], 8.5, '{"poet":"Tevfik Yaşar Tekeli","poet_slug":"tevfik-yasar-tekeli","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/yasasin-bulvarlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul Hatırası', 'i-stanbul-hatirasi-atilla-guler-iqmbn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'içine vuran bir boğaz türküsünün

laciverdine yazılmış gün

dilinde pelesenk sözcükler

incecikten düşer önüne şiir 

bir de balık ekmek iskelede

sesine karışan martı çığlıkları

cilveleşir uçuş arası dinmez enginlerde

telaşının devinimlerinde ezgisi şehrin

Arnavut kaldırımlı sokaklarında

yalınayak gezinir düşler

sabah akşam depreşir

sürüklenir bekleyişler

nargilenin marpucunda bırakırsın

duman duman yorgunluğu

beyaz vapurlarda yudumladığın

tavşan kanı çay sıcağında

tutar elinden sevdanın kızılı

uğruna yazılan şiirlerde

dinlenir haykırışı gözler kapalı

limanların sessiz çığlığında

seyreder düş gibi şehr-i destan 

hatıraların dört nala koşturduğu

dalgaların içinde oynaşır haşarı yakamoz

aşk toplanır dallarından İstanbul''un

teknelerinden atlar maviliklere sihri saatlerin 

ışığın yansımasında göz kırpar Kız Kulesi

her zerresi dolar soluklara efsanenin

yıldız yıldız yakar yandığınca gecelerde

dillenir peri kızı korkusuz Kanlıca’da

resitaller çağlarken sandallara vurup 

ardı arkası kesilmez fotoğrafların

sepya rengine vurulan damgasında

donar hayat … yangını durmaz

ıssız bir güneşten çalınan parçada

çağlar yedi kere sultanların dansı

yüreğe vurur yankısı tarihin

usulca uzanır yanıma bir İstanbul Hatırası

Mart  2006', 'içine vuran bir boğaz türküsünün laciverdine yazılmış gün dilinde pelesenk sözcükler incecikten düşer önüne şiir  bir de balık ekmek iskeled...', ARRAY['Türk Edebiyatı','Şiir','Atilla Güler']::text[], 8.5, '{"poet":"Atilla Güler","poet_slug":"atilla-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/istanbul-hatirasi-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Çağı da Yırtarım Ben', 'bu-cagi-da-yirtarim-ben-turgut-yildizan-5vqhj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kalbimden çıkarttım,

 İçimi ferahlattım derken

Beynime saplandı kıymık! 

Beynimden sökemeden 

İhanetlerin kıymığını; 

Kıydılar Azerime,

                      Çeçenime,

                                 Türkmenime,

Kan kusturdular Bosnalı kardeşime.

Feryatlar yankılandı gök kubbemde,

Uykularım zehir oldu,

Hayatım zehir! ...

Bildik iklimlerden rüzgar

Izdıraplı kardeş selamı getirir.

İşte o zaman 

Bir ağrı saplanır vicdanıma.

Vicdanım asırlardır sızlıyor zaten.

Çağlara sığmayan ben; 

                     Geceler boyu beynimi avutuyorum,

                     Acizliğimden sıyrılmaya çalışıyorum.

Bilenler biliyor ya! 

Kalemimle dertleşip,

Mısralarımla silkindikçe

Bu çağı da yırtarım,

Sevr paçavrasını da! ...', 'Kalbimden çıkarttım,  İçimi ferahlattım derken Beynime saplandı kıymık!  Beynimden sökemeden  İhanetlerin kıymığını;  Kıydılar Azerime,     ...', ARRAY['Türk Edebiyatı','Şiir','Turgut Yıldızan']::text[], 8.5, '{"poet":"Turgut Yıldızan","poet_slug":"turgut-yildizan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bu-cagi-da-yirtarim-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İ z k e s m e l e r...', 'i-z-k-e-s-m-e-l-e-r-zafer-zengin-etnika-67c5k', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '.

yongaların sazı ağır titrek elleriyle

elleri dilleriyle süzülürken yerinde

dilimin içine düşer sesin gelir keyfime

bir gider bir gelirsin düştüğün yere

zede’m kan kokar akşama

afili elleriyle tütün sarar şiir sayfalarına

şiirler kanar şehrin ortasında kedilerden yana

ıssızlık gelir yağmur basar şehri ah eşkıya

sen gelirsin akla şiir sarılır sen unutulur bir kere

bere’m can kokar sabaha

alnın aydın ışığı gülerde gül ezer öğlene

öğlenin elleri gündüz perde dil keserde

şarkı mırıldanır kocamış çocuklar şiirlerde

ses kesilir nefes açılır göğe elleriyle

kere’m can kokar gecede

öfkemin suyu var beni unutma ayrılıkta

unutulmak süs olmuş tarihin sayfasında

yazdıkça derin yerlerde kendi adına

sen düşer perdeye yıldız düşer içeriye

dere’m can kokar nefeste

09 02 2006 

.', '. yongaların sazı ağır titrek elleriyle elleri dilleriyle süzülürken yerinde dilimin içine düşer sesin gelir keyfime bir gider bir gelirsin ...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/i-z-k-e-s-m-e-l-e-r-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saatler ve Zaman', 'saatler-ve-zaman-nail-demir-25gv8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dertler bitip tükensin istenirken,

Mutluluklar sürüp gitsin isteriz...

Geçen saatler mi

 Yoksa ömrümüzün   eksilen yanı mı? 

Bilen varsa söylesin bana.

Ömür bedenin saatiymiş,

Kuruluysa  işler her zaman,

Gün gelir durur, işlemez olur.

Sonsuzlukta zamanın ne önemi varki zaten! 

Saat mi, can mı önemli bizim için; 

Tercih yapsan hangisidir senin için...? 

Hayat  filminin kahramanı biziz,

Ne dublör gerekli, ne kahraman isteriz.

Acı- tatlı ne değişik duygular yaşarız.

Rolümüzün hakkını başarıyla veririz.

Dakikalar, saatler

Günler ve haftalar...

Neler yaşarız  neler...

Unutur gideriz mutsuzlukları; 

Hayattan hep umut bekleriz.

Ulaşmak istediklerimizin,

Koşarız  peşinden.

Bazen  ulaşırız,

Bazen uzak düşeriz umduklarımızdan...

Olumsuzluklara  rağmen güzeldir hayat.

Güzeli  istemek,

Arzulamak  hedefimiz  olsun! 

                                2006', 'Dertler bitip tükensin istenirken, Mutluluklar sürüp gitsin isteriz... Geçen saatler mi  Yoksa ömrümüzün   eksilen yanı mı?  Bilen varsa söy...', ARRAY['Türk Edebiyatı','Şiir','Nail Demir']::text[], 8.5, '{"poet":"Nail Demir","poet_slug":"nail-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/saatler-ve-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sus/yüreğim...', 'sus-yuregim-selma-sengoren-qt9jo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Puslu çiğlerim 

Döküldü kar tanesiyle

Hasretini yazdım ummana

Güzel günlerin hatırına

Hayaline git,, diyemedim

Kelepçede yüreğim

Nefesimin sesiyle

Gülümseyen aşkının ruhuna

Meşale yaktım ufuklara

Ateşini küle,,çeviremedim

Poyraz oldu ümitlerim

Gözlerimin yangınıyla

Adını yazdım şimal rüzgarına

Sevda sayfasında hala gönlüm

Bir kalemde,, silemedim

	

Özlem  kesiği yüreğim

Nağmesine dokunur sözleriyle

Aşkını gömdüm baharıma

Bir gün daha geçti “gülüm”

Ömrüme dur,,diyemedim…', 'Puslu çiğlerim  Döküldü kar tanesiyle Hasretini yazdım ummana Güzel günlerin hatırına Hayaline git,, diyemedim Kelepçede yüreğim Nefesimin s...', ARRAY['Türk Edebiyatı','Şiir','Selma Şengören']::text[], 8.5, '{"poet":"Selma Şengören","poet_slug":"selma-sengoren","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sus-yuregim-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Namert Günü Bu Gün', 'namert-gunu-bu-gun-turgut-yildizan-znbaw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hayat böyle rezil

Kov kovabilirsen,

Her şamarda ezil

Sev sevebilirsen.

Asıl astar bozdu

Bil bilebilirsen,

Geçim derdi ezdi 

Gül gülebilirsen.

Sözün tadı buruk

Bak bakabilirsen,

Kolu kandı kırık

Çek çekebilirsen.

Bereketi gitti

Dol dolabilirsen,

Kıt kanaat bitti

Ol olabilirsen.

Namert günü bu gün

Dur durabilirsen,

Pişmanlıkla dövün

Vur vurabilirsen.

Mertlik nerde hani? 

Kız kızabilirsen,

Meydanlarda şimdi

Gez gezebilirsen.', 'Hayat böyle rezil Kov kovabilirsen, Her şamarda ezil Sev sevebilirsen. Asıl astar bozdu Bil bilebilirsen, Geçim derdi ezdi  Gül gülebilirsen...', ARRAY['Türk Edebiyatı','Şiir','Turgut Yıldızan']::text[], 8.5, '{"poet":"Turgut Yıldızan","poet_slug":"turgut-yildizan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/namert-gunu-bu-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul', 'i-stanbul-ali-kilic-kakiz-0w8ve', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ufkunda yükseliyor ne hoştur bu sedalar.

Güzelliğini süsler nağme nağme sevdalar. 

Gülümsedikçe durmaz  akıyor nuru letafet,

Göz kamaştıran kubbelerin başka bir zarafet. 

İhtişamla, bir uçtan bir uça tarih kokar durur. 

Bağrın da Süleymaniye, muhteşem bir gurur. 

Kıtalara sığmamış, deryalara taşmış meğer. 

Köşkleri yalıları, paha biçilmez bir değer. 

Yüreğimde sevdan var Eyüp Sultan ağlamasın.

Sen şühedanın maneviyat önderlerinin diyarısın.

Boğaz’da dalga dalga zamanın  nabzı vurur,

Her köşesini dönsem,önümde mağrur durur.

Sana aşık olan  gönüller yanıp tutuşur tüter. 

Seni gözü gibi koruyanların bize sevgisi yeter.

Güzelliğin eşsiz, ey yaren şehir, gül gülümse dur. 

Beni yakıp tutuşturan, sana götüren bu mudur.

Şairler sözün doğrusunu söyler kitapları açık, 

İstanbul’un kıymetini bil, saygı ile eğil birazcık..

Saklayamam gerçeği gönüller yeşerten dalsın. 

Göz yaşım kurumuyor sen ecdadımın mirasısın.

Haykır İstanbul haykır, tekbirler alsın her yanı. 

Unutma milletimin mihrakı, Sultan Mehmet hanı.

Çağlar boyu, hoşgörü üstün ahlakı taşıdılar. 

Şu mübarek ay yıldızlı bayrağı sana bıraktılar. 

Şerefli bir tarihsin seninle yaşar, seni anarım. 

Kudretsin ve ümitsin ruhlar da, seninle varım. 

18. 3.2006  Bruxelles', 'Ufkunda yükseliyor ne hoştur bu sedalar. Güzelliğini süsler nağme nağme sevdalar.  Gülümsedikçe durmaz  akıyor nuru letafet, Göz kamaştıran ...', ARRAY['Türk Edebiyatı','Şiir','Ali Kılıç Kakiz']::text[], 8.5, '{"poet":"Ali Kılıç Kakiz","poet_slug":"ali-kilic-kakiz","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/istanbul-411-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Ben sana layık değilim *', 'ben-sana-layik-degilim-zernisan-aydogan-nbafv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yasaklı sevdamsın benim

Yaram büyük hem çok derin

Derman bulunmaz bilirim

Ben sana layık değilim

Neden bana gönül verdin

Hayatını ben mahvettim

Dağı taşı aşıp geldin

Ben sana layık değilim

Gece gündüz içiyorum

Hayatımdan geçiyorum

Suçum nedir bilmiyorum

Ben sana layık değilim

Geziyorum Mecnun gibi

Eller bana gülüp geçti

Yaşama gücüm tükendi

Ben sana layık değilim 

                    2006/Erzurum

                       Zernişan', 'Yasaklı sevdamsın benim Yaram büyük hem çok derin Derman bulunmaz bilirim Ben sana layık değilim Neden bana gönül verdin Hayatını ben mahvet...', ARRAY['Türk Edebiyatı','Şiir','Zernişan Aydoğan']::text[], 8.5, '{"poet":"Zernişan Aydoğan","poet_slug":"zernisan-aydogan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ben-sana-layik-degilim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asker Ocağından Anneme', 'asker-ocagindan-anneme-fatih-demir-17tgz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '(Bu şiirimi kardeşim kadar seviğim bir arkadaşım adına yazdım)     

Bu şiirim sana, üzülme anne,

Burada ekmeği bölmekte varmış.

Oğlun nasıl diye, sakın düşünme,

Vatanın bağrını sevmekte varmış.

Burada, hep oğlun pişirir aşı,

Kolaysa ayıkla, pirinçten taşı,

Ne olur siliver, gözünden yaşı,

Yuvadan uzakta, kalmakta varmış.

Botlarım delindi, üstleri kaldı,

Yüzbaşım, Cavuştan ismimi aldı,

Daha yazacaktım ama, sirenler çaldı,

Burada rahatsız olmakta varmış.

Sözde baharaydı,benim düğnüm,

Saymakla geçmiyor, sayılı günüm,

Asker ocağında, yazılmış ölüm,

Tezkere beklerken ölmekte varmış....', '(Bu şiirimi kardeşim kadar seviğim bir arkadaşım adına yazdım)      Bu şiirim sana, üzülme anne, Burada ekmeği bölmekte varmış. Oğlun nasıl ...', ARRAY['Türk Edebiyatı','Şiir','Fatih Demir']::text[], 8.5, '{"poet":"Fatih Demir","poet_slug":"fatih-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/asker-ocagindan-anneme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerdeyim', 'nerdeyim-vahit-kara-2axmd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dağların başındayım Hızır,

Bir sevda düşündeyim işte,

Kuyularda Yusuf''um,ateşte İbrahim

Güvercin ağzında zeytin dalıyım,

Duy beni,yüreğindeyim işte.

Uçurumun kenarındayım Hızır,

Bir sevda düşü benim içimde.

Yokluğunu çekmekte hayat.

Karanlık geceler,parlayan yıldızlar adına,

Azgın denizler,yol vermez dağlar adına,

Al beni,elinin uzandığı yerdeyim işte.

Gölgemin peşindeyim Hızır,

Lokman''ın geçtiği yoldayım,bende.

Dağların kartalıyım, çöllerin aslanı,

Varlığın elinde bir zerreyim işte.

Toprağın oğluyum,çamur benim içimde,

Tut beni, yapılmazın düşündeyim işte.

Gözünün değdiği yerdeyim Hızır,

İlyas''la buluştuğun andayım işte.

Tabduk dergahında aşık Yunus''um,

Kal''a nın burcunda Hasan olurum.

Bir mermiyim namlusunda mavzerin.

Bir ağıtım anaların dilinde.

Gör beni, güneşin doğduğu yöndeyim işte.

Dermansız bir dertteyim, Hızır.

Yorgun düşlerinin esaretindeyim.

Şimal rüzgarları eser sineme doğru,

Ben hasretini çekerim,her günün sabahında,

Bir kor düşer yüreğime,

Bir ''of derim''karşıki dağlar oynar yerinden.

Sar beni, ağustos da üşürüm işte.

Bir garip mefkureye dalmışım Hızır,

Ölüm benim peşimde, sevda benim içimde.

Öteler öteler geçit vermiyor,

Yol nerde? Hızır, zaman neresinde? 

Düşman burda amma, dost neresinde? 

Verilmiş fermanımız, biçimiş kaftanımız,

kazılmış mezarımız, yazılmış günahımız.

Sor beni, yedi kat çukura düşmüşüm işte...', 'Dağların başındayım Hızır, Bir sevda düşündeyim işte, Kuyularda Yusuf''um,ateşte İbrahim Güvercin ağzında zeytin dalıyım, Duy beni,yüreğindey...', ARRAY['Türk Edebiyatı','Şiir','Vahit Kara']::text[], 8.5, '{"poet":"Vahit Kara","poet_slug":"vahit-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/nerdeyim-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '////////((((((((( Peygamberim canım benim )))))))) //////////////', 'peygamberim-canim-benim-abdulhamit-aydin-uvvdi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Peygamberimin güzel dili; 

	Anlatır iyiyi,sakındırır kötüyü

	Davet eder,

	Güzelliğe, doğruya, birliğe

	

	Peygamberimin güzel gözleri; 

	İster iyiye bakmayı, çevirtir kötüyü

	Sakalı ıslak ıslak olur,

	Hem ibadetten hem de ümmetinden

	Peygamberimin güzel yüzü; 

	İyileri nurlandırır, kötüleri uzaklaştırır

	Görmek ister,

	Her insan gibi benim şu yaralı yürek

	

	Peygamberimin güzel kalbi; 

	İyilikten coşar, kötülükten sızlar

	Sahip değilim o sevgi dolu  kalbe,

	Dertte, sevinçte, üzüntüde, mutlulukta

	Peygamberimin güzel ayakları; 

	İyiliklere koşan, kötülüklerden kaçan

	Getirirsin tüm ümmetine,

	Kardeşlik, insanlık, ilim

	Peygamberimin güzel kabri,

	Doldurur tüm ümmetleri

	İsterim kabrinde bir avuç toprak

	İsterim kabir ağacında bir yaprak', 'Peygamberimin güzel dili;  	Anlatır iyiyi,sakındırır kötüyü 	Davet eder, 	Güzelliğe, doğruya, birliğe 	 	Peygamberimin güzel gözleri;  	İste...', ARRAY['Türk Edebiyatı','Şiir','Abdülhamit Aydın']::text[], 8.5, '{"poet":"Abdülhamit Aydın","poet_slug":"abdulhamit-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/-peygamberim-canim-benim--siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acımasız umutlar!', 'acimasiz-umutlar-mehmet-goden-5w139', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Acımasız umutlar..! 

İşte; yine yüreğime perçinliyor  yalnızlığımı

-sensiz geçen günlerim.

Hapsoluyor içime yine,

-umutsuzluğun acımasızlığı.

Hissedersen varlığımı birgün! 

Ölüm döşeğinde gel yanıma

-gözlerinle gör yıkılmışın acısını.

Usulcacık ağla içinden

 Gözyaşlarınla yıkasınlar beni

Sende aynı hisleri taşıdıysan bir zaman:

-duyacaksın umutsuzluğun acısını.

...Kalbin buruk kalacak belkide.

Mehmet Göden,1978.', 'Acımasız umutlar..!  İşte; yine yüreğime perçinliyor  yalnızlığımı -sensiz geçen günlerim. Hapsoluyor içime yine, -umutsuzluğun acımasızlığı...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Göden']::text[], 8.5, '{"poet":"Mehmet Göden","poet_slug":"mehmet-goden","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/1-acimasiz-umutlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben.', 'ben-mehmet-goden-i3pp4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Rüzgarların savurduğu bir toz tanesiyim ben,

Berduşum yollarında sevginin,kapısına kul,

Olmuşum; aşkınla yabanlarda el,

Ya duy beni,ya gör artık

İçmeden sarhoş,içerim bomboş,

Gününü gün eden habersiz benden, 

Yoldaşıyım aşkı arayanın,

Kaderine ağlayanın,

Rüyalara  mazi,alınlara yazı,

Yıllar unuttursada sana,

Ben; 

Hala umudunu yeşerik tutan,

Senin bahar gibi dönmeni bekleyen,

O umutla yaşayan bir dal’ım ben.

12.08.80', 'Rüzgarların savurduğu bir toz tanesiyim ben, Berduşum yollarında sevginin,kapısına kul, Olmuşum; aşkınla yabanlarda el, Ya duy beni,ya gör a...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Göden']::text[], 8.5, '{"poet":"Mehmet Göden","poet_slug":"mehmet-goden","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ben-259-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Melisa', 'melisa-selami-aydemir-c6s3d', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'MELİSA

Sevdalar boğazlanıyordu sokaklarda

Acılar içinde yürekler bırakarak ardında

Yıkık bir kent gibi

Aşkın örgüsünü örüyorum

Aşkın türküsünü söylüyorum

Sevdalar kısık sesli ve mumlu odalarda 

Çığlıksız şiirlere abanıyordu

Şiirlerimi kendi sesimden okuyordum

Gökyüzünde bulutlarla dost oluyordum

Ellerimi uzatıyordum yıldızlara

Ama sevdalar eski sevda değildi

Şiirlerde eski şiir

Soluksuz kalıyordum aşklarımda

İç(-ki-)   li şiirler yazıyordum

Yaşamı anlamlandıran imgelerini hayatın…

Şimdi bir feryadım sokaklarda

Tüm bildiğin sokaklara yolum çıkıyor

Ve tüm barlara soluğum doluyor

Şimdi yüreğimin gökdelenleri tutsak 

Tüm marinada seni arıyorum.

Sokaklarını dolaşıyorum bu kentin

Bir tanıdık söz dinlemek

Bir tanıdık teselli bulmak umudu

Ve yalnızlığın içimdeki nüfusu ile

Bu kentte bir feryat gibi doluyorum.

Bu akşam bendeki tüm eşyalarını topladım

Suskun bakışlarını

Masum yüzünü yanıma aldım

Sokaklarındayım bu kentin

Adressiz yollardayım artık

Seni aradım solgun yüzlü insanların içinde

Ama sen yoktun

‘bir kaçak sigara kokusuydu aşk         

Issız kurak bir Adıyaman tütünü

Kotası henüz belirlenmemiş kenevir tohumu’', 'MELİSA Sevdalar boğazlanıyordu sokaklarda Acılar içinde yürekler bırakarak ardında Yıkık bir kent gibi Aşkın örgüsünü örüyorum Aşkın türküsü...', ARRAY['Türk Edebiyatı','Şiir','Selami Aydemir']::text[], 8.5, '{"poet":"Selami Aydemir","poet_slug":"selami-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/melisa-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir tanem,', 'bir-tanem-mehmet-goden-00d1a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gül dikensiz bende sensiz olamam,

Yanıma gel uzaklaşma varamam,

 Seni elde görmelere kıyamam,

Gelinciğim yabangülüm bir tanem

Yar gücüme gider oldu sözlerin,

Öyle bakma öldürüyor gözlerin,

Her Baharda kırda açan lalemsin,

Menekşemsin,narçiçeğim birtanem,

Öyle oldu yar yollarım bağlandı,

Aşk yüzünden ciğerimde dağlandı,

Ne güzeller gördü fakat konmadı,

Ben Arı’yım sen manolya,birtanem.

01.05.2001', 'Gül dikensiz bende sensiz olamam, Yanıma gel uzaklaşma varamam,  Seni elde görmelere kıyamam, Gelinciğim yabangülüm bir tanem Yar gücüme gid...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Göden']::text[], 8.5, '{"poet":"Mehmet Göden","poet_slug":"mehmet-goden","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bir-tanem-60-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mezar Taslari', 'mezar-taslari-gultekin-toga-7pcf2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Üç günlük,on yıllık, tarihi meçhul,

Ufaklı,irili mezar taşları,

Konup göçenlere en bariz delil,

Yanyana sıralı mezar taşları.

Her tarafi otlar ile sarılmış,

Sanki dikenlerle çelenk örülmüş,

Yağmur yemiş, Güneş değmiş,kırılmış,

Yıpranmış,bereli mezar taşları..

Şu yirmi yaşında şehid Sinan´ın

Şu doğduğu sabah göçen Mine´nin,

Şu da sekseninde Hacer ninenin,

Adları sıralı mezar taşları...

Dünün koşup gülenleri bunlar ha,

Selam verin ruhlar sizi dinler ha,

O´na doğru gider bütün yönler ha,

Bu yüzden yaralı mezar taşları..

Gidecek her canlı durmaz ki akın,

Belki çok uzakta belki çok yakın,

Bir gün Sentezi´nin başına dikin

Tipili,boralı mezar taşları,', 'Üç günlük,on yıllık, tarihi meçhul, Ufaklı,irili mezar taşları, Konup göçenlere en bariz delil, Yanyana sıralı mezar taşları. Her tarafi otl...', ARRAY['Türk Edebiyatı','Şiir','Gültekin Toga']::text[], 8.5, '{"poet":"Gültekin Toga","poet_slug":"gultekin-toga","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/mezar-taslari-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fundam', 'fundam-selami-aydemir-juivz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen özgürlüksün, 

sen bana bir yaşama sevinci

sen başını alıp gitmek istediğim

uzak bir kentsin.

İki dudağının arasında içimi sızlatan 

O bağlılığının izleri…

yaşadım en güzel şeysin.

Birlikte şarkı dinlerken

Sesinin yankısında…

aşk oluyor

İçimde kopan fırtınalar...

Baktığım pencerelerden 

Özgürlüğe kuş sürüleri havalanıyor

Uzak kentine otobüsler kalkıyor

Ve sen o uzak kenttesin

Seviyorum diyorsun ya 

Sesini incitmekten korkuyorum o an

Bir film şeridi gibi seninle başlıyor yaşamım 

Ve seninle bitecek olan…

İşte benim kentim sensin

Sensin Fundam

İçimde gün geçe daha kalabalıklaşan sen...', 'Sen özgürlüksün,  sen bana bir yaşama sevinci sen başını alıp gitmek istediğim uzak bir kentsin. İki dudağının arasında içimi sızlatan  O ba...', ARRAY['Türk Edebiyatı','Şiir','Selami Aydemir']::text[], 8.5, '{"poet":"Selami Aydemir","poet_slug":"selami-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/fundam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boş', 'bos-mehmet-goden-n5zkh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Akar iken gün gün hayat,

O günlerde birşeyler yap,

Geri kaldın yol tükendi,

Öğretmişler yan gelip yat.', 'Akar iken gün gün hayat, O günlerde birşeyler yap, Geri kaldın yol tükendi, Öğretmişler yan gelip yat....', ARRAY['Türk Edebiyatı','Şiir','Mehmet Göden']::text[], 8.5, '{"poet":"Mehmet Göden","poet_slug":"mehmet-goden","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bos-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '/////'''' (((Bir gece ansızın)))  ''////////', 'bir-gece-ansizin-abdulhamit-aydin-kbyho', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözümü kapadım, daldım hayale

Peygamberimi görme niyetiyle			

Bu gece hiç bitmesin				                 

Cananlar cananı gitmesin

Rüyamda düz ve aydınlık bir yol

Her yerden rahmet akıyor, bol bol			

Dünya ve ahiret senle kolay					

Sana uymamak ayıp bir olay

						

Güller efendisi Muhammed					

Cananlar cananı Nebi

Sultanlar sultanı Ahmed			

Alemler efendisi Habibi

Eksikliğin var vefatından beri				

İnsanlar perişan,insanlar serseri

Seni anıyor, her yerde melek

Seni arıyor, her aşık yürek 

Hareketlerinin hepsi yerli yerinde

Seni anlamak için düşünür derinde

Seni hayatımıza etsek rehber

Senden sonra oluruz, beşer-i ekber

Güller efendisi Muhammed

Cananlar cananı Nebi

Sultanlar sultanı Ahmed

Alemler efendisi  Habibi 

					

Anam,babam,canım hepsi sana feda

Sana demek kolay mı, bir el veda

Şanın,şerefin,cemalini süsledikçe

Gözlerim dalıyor, seni düşledikçe

						

Cihan oluyor, yeni bir cihan

Sensiz zor geçiyor bu imtihan

Kurtulmak için sarılmalı iki emanete

Sen ve Kur’an ile gideriz cennete	

                           ''''''  Peygambere aşık olan 

                                                         ve İslam birliğini bozmak                    

                                                     isteyen  düşmanlara''''''', 'Gözümü kapadım, daldım hayale Peygamberimi görme niyetiyle			 Bu gece hiç bitmesin				                  Cananlar cananı gitmesin Rüyamda düz...', ARRAY['Türk Edebiyatı','Şiir','Abdülhamit Aydın']::text[], 8.5, '{"poet":"Abdülhamit Aydın","poet_slug":"abdulhamit-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/bir-gece-ansizin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeter artık yeter', 'yeter-artik-yeter-mikdat-bal-10foh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yeter artık yeter eyleme hucüm

Anladım beş para etmiyorum ben

Ama önce söyle ne idi suçum

Onu öğrenmeden gitmiyorum ben

Demek ki sevmiştin pazara kadar

Söz verdiğin halde mezara kadar

Kıymetim de yokmuş beş para kadar

Artık ne dersen de yutmuyorum ben

Terkedip de beni saldıktan sonra

Kalemin eline aldıktan sonra

Kaldırıp da yere çaldıktan sonra

Sana söz vermiştim tutmuyorum ben! 

Sevenin nazını çile mi sandın

Seven sevdiğine  köle mi sandın

Beni mecnun bilip çöle mi sandın

O kadar da yanıp tütmüyorum ben

Mikdatî der hayat yürür de sensiz

Hareketin ani, hakaret densiz

Bir celsede infaz ettin nedensiz

Gerçek olan budur atmıyorum ben', 'Yeter artık yeter eyleme hucüm Anladım beş para etmiyorum ben Ama önce söyle ne idi suçum Onu öğrenmeden gitmiyorum ben Demek ki sevmiştin p...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yeter-artik-yeter-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömrün Sırrı', 'omrun-sirri-nail-demir-c715h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'D  eğersizi  değerli kılmak elimizde,

E  rişmek gerek mutluluğun tadına; 

M  anasını çözmek gerek hayatımızın,

 İ   nan  kendine, varoluşunun sırrını anla! 

R   abbim ne güzel yaratmış bizleri...! 

                                             2006(AKROSTİŞ ŞİİR)', 'D  eğersizi  değerli kılmak elimizde, E  rişmek gerek mutluluğun tadına;  M  anasını çözmek gerek hayatımızın,  İ   nan  kendine, varoluşunu...', ARRAY['Türk Edebiyatı','Şiir','Nail Demir']::text[], 8.5, '{"poet":"Nail Demir","poet_slug":"nail-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/omrun-sirri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diyemedim,', 'diyemedim-mehmet-goden-n1m3u', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gittinya o gündür canım sıkılır,

Derdimi kimseye açamadımki,

Gönül yaram dağlanır,içim burkulur,

Böyle çaresizce hiç ağlamadımki! ,

Hadi sil sileceksen kalbinden beni,

Hadi çek içlerinden iyilerini,

Yüzümmü güldüde o günden beri,

Artık gülüp oynamam neye yararki,

Bir ömür umutsuz ne ile geçer,

Gözümde tüten ayrılık ölümden beter,

Seni beni bilene bu gönül ne der,

Diyemem bittiğini  desem,neye yararki.

30.07.2002', 'Gittinya o gündür canım sıkılır, Derdimi kimseye açamadımki, Gönül yaram dağlanır,içim burkulur, Böyle çaresizce hiç ağlamadımki! , Hadi sil...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Göden']::text[], 8.5, '{"poet":"Mehmet Göden","poet_slug":"mehmet-goden","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/diyemedim-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizdedir', 'bizdedir-i-lhami-arslantas-j2idk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çeşm-i çırağıyız çarkı devranın,

Gül ehli bülbülün zarı bizdedir.

Boşuna yanar mı vicdanlı yürek,

Yol ehli insanın harı bizdedir.

Dermana koşarız yeri gelende,

Dağları aşarız geri gelende,

Çekeriz,taşırır zoru gelende,

Karınca gayreti varı bizdedir.

Tüm insanoğlunu bizden sayarız,

Baş tacı ederiz özden sayarız,

Herkesin sözünü sözden sayarız,

Gerçeği bilmenin kârı bizdedir.

Der ilhami yazdım işte kinaye,

Bilmektir insana en güzel paye,

Zannı taç etmeyiz yalanı gaye,

Her zaman cehennem narı bizdedir.

………………Fikri olmayanın carı sözdedir', 'Çeşm-i çırağıyız çarkı devranın, Gül ehli bülbülün zarı bizdedir. Boşuna yanar mı vicdanlı yürek, Yol ehli insanın harı bizdedir. Dermana ko...', ARRAY['Türk Edebiyatı','Şiir','İlhami Arslantaş']::text[], 8.5, '{"poet":"İlhami Arslantaş","poet_slug":"i-lhami-arslantas","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bizdedir-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Etmez,', 'etmez-mehmet-goden-ts2nh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Boşunamı coşar gönül coştumu

insan kötü güne saklar kadim dostunu,

Pazara çıkarınca riyakarın postunu,

Bir yüzüne bakan çıkmaz hayretmez

Dünya kime galmış geçende,

Bana düşen nefes kadar bir hisse,

Rabbim dememişmi? karıncaya bir fiske,

Vuran kulun canı bende beş para etmez.

14.11.2004', 'Boşunamı coşar gönül coştumu insan kötü güne saklar kadim dostunu, Pazara çıkarınca riyakarın postunu, Bir yüzüne bakan çıkmaz hayretmez Dün...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Göden']::text[], 8.5, '{"poet":"Mehmet Göden","poet_slug":"mehmet-goden","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/etmez-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilene,', 'bilene-mehmet-goden-n8n1b', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bazen acı lokma yedirir

Yutmasını bilene

Herşey taze lokum gibidir

Tatmasını bilene,

Her baharda gün olmamışlarda kar,

Yazın yakar güneş,Sonbahar yaprak döker,

Eşek Arısı şifa verir,sinek kilolarca yağ,

Sağmasını bilene,

Kalp kırma kırılsada gururun,

Kendinde olsun kusur,

Her sözü tartıpta söyle sen,

Doğru gider bulur,sahibini

Duymasını bilene.

Yapma kötülük istemez isen,

Kendine yapılmasım,

öfke ile kalkmak zorunlu oturmayı,

Öğretir hırsına yenilmeyi,

Bir şamar bir teneke baldan tatlı gelir,

Atmasını bilene.

Etrafa bakmaktan kalmıyor vakit,

Küsur görmez gözümüz,

Cebimiz nakit,

Kim kime muhtaç olur idi,

Uyuyana incitmeden,ikaz için,

Dürtmesini bilene,

Kapan kurulu mal mülk çok,

Sende çoğalt çalıp çırpıp mal tut

Kefende cep yok,isteyene yok,yok,

Bu hayatta.kefenine üst üste cep niyetine

Haramı, hakkı,dikmesini bilene

Cansız beden ne etsin malı mülkü

insanca yaşama hakkı olsaydı ülkü

Ayırmaz ecel geldi mi beyi züğürdü

Sevgi Cennei ayağa çeker

Sırt üstünde keyfiyle,etliye sütlüye karışmadan

Yatmasını bilene.

06.08.2002', 'Bazen acı lokma yedirir Yutmasını bilene Herşey taze lokum gibidir Tatmasını bilene, Her baharda gün olmamışlarda kar, Yazın yakar güneş,Son...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Göden']::text[], 8.5, '{"poet":"Mehmet Göden","poet_slug":"mehmet-goden","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/bilene-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bülbül.', 'bulbul-birol-i-scan-rg6tt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Evimizin bir köşesini dolduran bir çiçek gibi  doldururdu şen kafesin

Renklerinle nağmelerinle tüylerinle övünürdük a kuşum.

Tanrının bize armağanı gibi göremedik seni sahibin sandık ki ne yazık.

Yediğin kadar yem verdik su verdik.bazende unuttuk yokluk verdik.

Ne zamanki kesildi nağmelerin gocunduk küstük sana

Ötsene şakısana işte yemin işte suyun susma dedik.

Bizler ki  küçük kuşum yanında ne de küçükmüş kalbimiz.

Anlayamadık sanatını acını hasretini sılanı

 küçüklerden de küçükmüş vahdeti mevcudiyetimiz.', 'Evimizin bir köşesini dolduran bir çiçek gibi  doldururdu şen kafesin Renklerinle nağmelerinle tüylerinle övünürdük a kuşum. Tanrının bize a...', ARRAY['Türk Edebiyatı','Şiir','Birol İşcan']::text[], 8.5, '{"poet":"Birol İşcan","poet_slug":"birol-i-scan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bulbul-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalmadı,', 'kalmadi-mehmet-goden-52l1q', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Beklermisin’ ki? yolumu eskisi gibi

Gözyaşı akıtıp arasan beni,

Dönemem bilesin bende bu yengi,

Sana vereceğim umut koymadı,

Sen yine dolaş; kırlarda,

Bil sıcaklığn yok oldu kollarda,

Bir sebep arıyorum günlerde,

Sana duyacağım özlem kalmadı.

Maziye uğurladım o manasız yılları,

Aradım dar günümde o vefasız kulları,

Ayırdı kader birleşmeyen yolları,

Sana döneceğim; yüzüm kalmadı.,

17.06.1981', 'Beklermisin’ ki? yolumu eskisi gibi Gözyaşı akıtıp arasan beni, Dönemem bilesin bende bu yengi, Sana vereceğim umut koymadı, Sen yine dolaş;...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Göden']::text[], 8.5, '{"poet":"Mehmet Göden","poet_slug":"mehmet-goden","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kalmadi-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nedir Olanlar?', 'nedir-olanlar-mehmet-goden-efrtv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nedir kinin nedir nefret? 

Ölüm sanıldığındanda yakında,

Sarmış kötülük esir almış gaflet,

Ve,İnsan hiç bir şeyin farkında,

Söyle Yarına kim çıkar,

Kimin üstüne külfettir gülmek,

Kim bilirki yarına çıkar,

Zor olan kalpten,

....Ve, gerçekten sevmek! 

30.07.2003', 'Nedir kinin nedir nefret?  Ölüm sanıldığındanda yakında, Sarmış kötülük esir almış gaflet, Ve,İnsan hiç bir şeyin farkında, Söyle Yarına kim...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Göden']::text[], 8.5, '{"poet":"Mehmet Göden","poet_slug":"mehmet-goden","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/nedir-olanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım', 'canim-mehmet-sait-ulucay-7gvfi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gönlümün telinden inleyen seste

Bizim şarkımız söylenirdi canım

Sensiz gecelerde gördüğüm düşte

Duvaklı gelinim olurdun canım.

Dağlar dOruğunda eriyen karlar

Salkım söğütler, asırlık çınarlar

Edipler, şairler, cümle yazarlar

Kaderiniz birdir derlerdi canım.

Emekler yetmedi nazla edana

Sarardı yapraklar kara sevdana

Toprakta mı sarılacak can cana

Taze umutlara hasretim canım', 'Gönlümün telinden inleyen seste Bizim şarkımız söylenirdi canım Sensiz gecelerde gördüğüm düşte Duvaklı gelinim olurdun canım. Dağlar dOruğu...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sait Uluçay']::text[], 8.5, '{"poet":"Mehmet Sait Uluçay","poet_slug":"mehmet-sait-ulucay","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/canim-74-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olaydım!', 'olaydim-mehmet-goden-7gy87', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben niye sefilim böyle? 

Bir çakaldan pençe yemiş,Arslan gibi perişan,

Hiddetim! sineme ''mi vurayım,yoksa; 

Azgın seller gibi,etrafamı? 

Bir yudum su gibi aziz

Damlası kadar leziz

Olmayı isterim:rüzgarda uçuşan,

Bir toz tanesi kadar güçsüz,

Kum fırtınasında ise acımasız.

10.04.2003', 'Ben niye sefilim böyle?  Bir çakaldan pençe yemiş,Arslan gibi perişan, Hiddetim! sineme ''mi vurayım,yoksa;  Azgın seller gibi,etrafamı?  Bir...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Göden']::text[], 8.5, '{"poet":"Mehmet Göden","poet_slug":"mehmet-goden","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/olaydim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem Yagmurları Yıkasın Yanlızlıkları', 'ozlem-yagmurlari-yikasin-yanlizliklari-nurten-tarim-8lcmm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Özlem yagmurları yıkasın yanlızlıkları

Güz yapraklarından kaldırımlar aglamasın

Yürege düşen anılar can bulsun sevdalarda

Yoksullugun köküne turp suyu

İhanetlere gönül kapıları kilitli 

Vicdanları kapalı olmasın ademogulları

Topraktan yaratıldık diye çıkar uğruna çamurlaşmasın

Süslerle kapatılmasın alçakca davranışlar

Çıplak bir insanın utanç duygusuyla titresin

Zamanı haklı çıkarır asıl gerçekler

Türkülere konu olur günahsız dogan çocuklar', 'Özlem yagmurları yıkasın yanlızlıkları Güz yapraklarından kaldırımlar aglamasın Yürege düşen anılar can bulsun sevdalarda Yoksullugun köküne...', ARRAY['Türk Edebiyatı','Şiir','Nurten Tarım']::text[], 8.5, '{"poet":"Nurten Tarım","poet_slug":"nurten-tarim","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ozlem-yagmurlari-yikasin-yanlizliklari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seviyorum ya seni!', 'seviyorum-ya-seni-mehmet-goden-6sqls', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bana yaşattığın aşkı yaşadınmı? ,

Yıllar dolusu hasretle kucaklaşıp,

Kalbindeki kırıkları ayıkladınmı? ,

Veya....günler boyu ateşlerde yandınmı? 

Bunu hep yaşıyorum ben,

Gidip geliyorum iki dünya arasında,

Bir omuzlardayım,bir uykuda,

Herşey sana kurulduğu sürece,

Durumum olsada bilmece,

Nefes verip aldığım sürece,

Seni ölesiye seviyorum,

Aşk  kör bir kuyu gibidir,

Ne sonu var ne dibi,

Ben yine seni  seviyor ve özlüyorum,

Seni...ve....Sevgini.

19.02.2003', 'Bana yaşattığın aşkı yaşadınmı? , Yıllar dolusu hasretle kucaklaşıp, Kalbindeki kırıkları ayıkladınmı? , Veya....günler boyu ateşlerde yandı...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Göden']::text[], 8.5, '{"poet":"Mehmet Göden","poet_slug":"mehmet-goden","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/seviyorum-ya-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahtam', 'kahtam-mehmet-sait-ulucay-1ckym', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Rüzgarı garip, güneşi garip

Talihi garip, insanı garip

Lebi çatlamış toprağı garip

Bahtına kurban olduğum Kâhta’m

Hüznüm, kederim, göz aydınlığım

Ak şafağına bel bağladığım

Bahtına gizli gizli yandığım

Nefesim, suyum, ekmeğim Kâhta’m

Lütfu hoş, kahrı hoş, sevgisi hoş,

Nemrut’ta güneşin doğuşu hoş,

Kültürün, tarihin, mirasın hoş,

Kara sevdamın ateşi Kâhta’m

Ruhumdasın sen, divanem oldum

Benim Leyla’msın, mecnunun oldum

Bir tel saçının esiri oldum

Derdinle ölmek özlemdir Kâhta’m

Kara kuşuyum tepelerinin

Cenderesiyim köprülerinin

Tarih diliyim kalelerinin

Çocuklarımın umudu Kâhta’m', 'Rüzgarı garip, güneşi garip Talihi garip, insanı garip Lebi çatlamış toprağı garip Bahtına kurban olduğum Kâhta’m Hüznüm, kederim, göz aydın...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sait Uluçay']::text[], 8.5, '{"poet":"Mehmet Sait Uluçay","poet_slug":"mehmet-sait-ulucay","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kahtam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah gönül elinde ne kaldı?', 'ah-gonul-elinde-ne-kaldi-mehmet-goden-mae5t', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İstediğin ne gönül herşeyi aldın benden,

Pılımı pırtımı,serdim ayak altına,

Çiğnenir oldu gurur,bakışlarım mahzuni,

Sıfatımız  beş paralık,pul oldu canın bedeli

İndin aniden yüksek uçardın kuş gibi enginlere 

Sergi ettin şefkatini merhametin sonu ne? 

Bir bedende canın var birde kırık hayaller,

Sandım saygı tükenmez,sevgilerse ebedi.

14.03.2004', 'İstediğin ne gönül herşeyi aldın benden, Pılımı pırtımı,serdim ayak altına, Çiğnenir oldu gurur,bakışlarım mahzuni, Sıfatımız  beş paralık,p...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Göden']::text[], 8.5, '{"poet":"Mehmet Göden","poet_slug":"mehmet-goden","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ah-gonul-elinde-ne-kaldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duygu', 'duygu-abdulkadir-azakli-nkeer', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yine duygulandım,düşünüyorum.

Bu dünyenın halı ahvalı nice.

İnsanlar ilahi güç tanımıyor.

Maddıyata daldı kalpler iyice.

Sorduğunda herkes, islamım diyor.

Dil ile deyil kalb ile islam olmalı.

Camıye gidipte,namaz kılarsan.

Sözün ile özün, aynı olmalı.

Ya ilahı bize merhamet eyle.

Sensiz bu dünyada,var olamayız.

Aşkın kabimize yerleşmeyince.

Dünya sevgisinden kurtulamayız.', 'Yine duygulandım,düşünüyorum. Bu dünyenın halı ahvalı nice. İnsanlar ilahi güç tanımıyor. Maddıyata daldı kalpler iyice. Sorduğunda herkes, ...', ARRAY['Türk Edebiyatı','Şiir','Abdulkadir Azaklı']::text[], 8.5, '{"poet":"Abdulkadir Azaklı","poet_slug":"abdulkadir-azakli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/duygu-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karşılama', 'karsilama-eren-caglar-niron-2smob', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gidişinde sakladığım gözyaşlarım

Karşılayacaklar seni dönüşünde

Yüzümde yaşatmaya değer

Bir tebessümle', 'Gidişinde sakladığım gözyaşlarım Karşılayacaklar seni dönüşünde Yüzümde yaşatmaya değer Bir tebessümle...', ARRAY['Türk Edebiyatı','Şiir','Eren Çağlar Niron']::text[], 8.5, '{"poet":"Eren Çağlar Niron","poet_slug":"eren-caglar-niron","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/karsilama-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasihat', 'nasihat-mehmet-sait-ulucay-1ttf5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dünya pembe değil sandığın gibi

Her iklimde bin gizlenmiş yolcu.

Kanatır kalbini dikenler gibi

Yeşeren her çiçek koklanmaz yolcu.

Ateşten kemerdir sarmayasın ha

Aşkı tanımadan savuş git yolcu.

Tutkulara esir olmayasın ha

Tükenir ömrünün hasretler yolcu

Tuzaklar kurulu gittiğin yolda

Aşk masallarını dinleme yolcu

Her biri bir bela elleri kanda

Avcının tarına takılma yolcu.

Zülfü, perçemi yada gözlerin

Başından almasın aklını yolcu.

Cilveyi edayı tatlı sözleri

Bal deyip kanma zehirdir yolcu.', 'Dünya pembe değil sandığın gibi Her iklimde bin gizlenmiş yolcu. Kanatır kalbini dikenler gibi Yeşeren her çiçek koklanmaz yolcu. Ateşten ke...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sait Uluçay']::text[], 8.5, '{"poet":"Mehmet Sait Uluçay","poet_slug":"mehmet-sait-ulucay","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/nasihat-87-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbet Sıla Yolu', 'gurbet-sila-yolu-gultekin-toga-72ckf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Baki değil Dünya sana,

Meyil verme yalan işte,

Yaptın ise senin ile,

Hak ameldir gelen işte...

Yürü gönül alçaklardan,

Kaçamazsın gerçeklerden,

İbret olsun çiçeklerden,

Kuruyupta solan işte..

Tahtı yürek olsun Aşkın,

Ayrılır sevgiden şaşkın,

Servet,şöhret, saray,köşkün,

Bekliyor bir talan işte..

Sakın sanma yoktur ucu,

Bazen doldurmaz avucu,

Dünya bir han  sen de yolcu,

Düşünerek dolan işte,

Duysun nefsin kulakları,

Sınırlı kıl dilekleri

Kırık gönül,kul hakları,

Mezarına yılan işte

Kul doğarken ağlayandır,

Yürek hamur, ömür tandır

Şereflenmiş bir insandır,

Öldüğü an gülen işte,

Çeker maddi yöne Dünya,

Hoş gelir insana Dünya,

Sentez gurbet sana Dünya,

Ahirettir Sılan işte..', 'Baki değil Dünya sana, Meyil verme yalan işte, Yaptın ise senin ile, Hak ameldir gelen işte... Yürü gönül alçaklardan, Kaçamazsın gerçeklerd...', ARRAY['Türk Edebiyatı','Şiir','Gültekin Toga']::text[], 8.5, '{"poet":"Gültekin Toga","poet_slug":"gultekin-toga","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/gurbet-sila-yolu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ver bana!', 'ver-bana-mehmet-goden-lvqcz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yorgun düştüm bir nefes ver çırpınsın,

Bir kuşun kanat çırptığı gibi,

Ne dalgalar duysun.

Kıyılara vurduğumu,

Ne suyu beni ıslatsın.

Uzaklara götürsün beni yel ile boran,

Sende attın beni insan eli değmeyen,

Issız dağlara saldın,

Yoluma engeller koydun

İçime ızdıraplar,

 Söylemedim canın bedenden ayrıldığını

Hiç bahsetmedin,kimseler bilmediği varlığımı,

Bir sıcak elde dolanan,kanım idin,içimdeki can,

Bilmeki seni umarım sen öyle san! 

Bilemezsin! içimdeki umudu,nasıl sildi süpürdü,

Geçen yıllarımı ver bana,kalmasın sende,

Bir emanet,silik anınıda al,

ve..! peşime taktığın ecelide.

14.02.2004', 'Yorgun düştüm bir nefes ver çırpınsın, Bir kuşun kanat çırptığı gibi, Ne dalgalar duysun. Kıyılara vurduğumu, Ne suyu beni ıslatsın. Uzaklar...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Göden']::text[], 8.5, '{"poet":"Mehmet Göden","poet_slug":"mehmet-goden","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ver-bana-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneş Gülüşleridir Düşünce', 'gunes-gulusleridir-dusunce-mehmet-sait-ulucay-cdc4r', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir yalan ki,

Kan kusuyor gerçek

Güneş oklarına inat

Gölgeye sinmiş konuşmalar

Gür bağırmaların suskunluğunda

Dut yemiş bülbül gibi,

Yanlış denklemlerde gezinir

Paye ile düşünen aydınlarımız.

Ve,

Yalan yaşıyoruz

Irzı hançerlenir

En güzel kızımız özgürlüğün

Zincire vurulur düşünce

Yaranmak adına

Şer satışları başlanır

Satan yalancı, alan yalancı.

Ey düşünceyi fil sananlar

Bana verin güneş gülüşlerini

Gizlileredir korkum

Yeter yalan yaşadığımız.', 'Bir yalan ki, Kan kusuyor gerçek Güneş oklarına inat Gölgeye sinmiş konuşmalar Gür bağırmaların suskunluğunda Dut yemiş bülbül gibi, Yanlış ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sait Uluçay']::text[], 8.5, '{"poet":"Mehmet Sait Uluçay","poet_slug":"mehmet-sait-ulucay","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gunes-gulusleridir-dusunce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıllar,', 'yillar-mehmet-goden-jk1dd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yıllar ah o yıllar,

İz bırakır ardında,

Çok şey götürür alır,

Kolay vermez,

Pişmanlık parada etmez,

Bakar kalırsın öylece geçen  Zaman’a,

Şaşkın ve ürkek,

Senmiydin hırstan kendini birşey sanan,

Öylece dünyaya kalacak direk.

05.09.1999', 'Yıllar ah o yıllar, İz bırakır ardında, Çok şey götürür alır, Kolay vermez, Pişmanlık parada etmez, Bakar kalırsın öylece geçen  Zaman’a, Şa...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Göden']::text[], 8.5, '{"poet":"Mehmet Göden","poet_slug":"mehmet-goden","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yillar-46-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman!', 'zaman-mehmet-goden-lbukg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sararmış yapraklar bozulmuş bahar,

Döküyor içimden ömrümü zaman,

Birikti üst üste hasretli yıllar,

İtiyor itiyor uzağa zaman,

+

Işığı sönmeden o gözlerinin,

Birde benim için gülsün isterim,

Yaş akıtmasın boşuna üzüntü duyup,

Hislerime kuşlar şahit olsun isterim,

+

Kaderim taştan taşa vursa başımı,

Yaşamayı isterim senle aşkımı,

Yıllar aklar salsa siyah saçımı,

Hep ilk günkü gibi bilsin isterim.

13.09.1985', 'Sararmış yapraklar bozulmuş bahar, Döküyor içimden ömrümü zaman, Birikti üst üste hasretli yıllar, İtiyor itiyor uzağa zaman, + Işığı sönmed...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Göden']::text[], 8.5, '{"poet":"Mehmet Göden","poet_slug":"mehmet-goden","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/zaman-311-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarim!', 'yarim-mehmet-goden-te7f6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mendilim yere değdi,

Har hış gözüme geldi,

Şu belalı başıma

Sevdalım akıl verdi,

Atmalı yar atmalı,

Taç yerine takmalı,

Gelen geçen bakınca,

Canı cana katmalı.

Yaylaların ekini,

Attım kalbimdekini,

Oturup kalakaldım,

Kaybedince tekimi,

Su başı öbeklidir,

Yarim hoş beliklidir,

Alıp Kaçacağımda,

Kardaşı tüfeklidir.

22.11.1984', 'Mendilim yere değdi, Har hış gözüme geldi, Şu belalı başıma Sevdalım akıl verdi, Atmalı yar atmalı, Taç yerine takmalı, Gelen geçen bakınca,...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Göden']::text[], 8.5, '{"poet":"Mehmet Göden","poet_slug":"mehmet-goden","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yarim-51-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut,', 'umut-mehmet-goden-wb8w2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözleme yolları geçti,baharlar,

Açan çiçekte kalmadı,nergizde,

Menekşeyi aramışım,gül ağcında,

Her yabancıda kokunu,sıcaklığını

Olmadı ise ne derim belliki ayrı iki beden,

İki yaralı yürek geriye kalan,

Yalan imiş aşksız dünya çok yalan,

Sen ben herşey; yaşanan,yaşatılan.', 'Gözleme yolları geçti,baharlar, Açan çiçekte kalmadı,nergizde, Menekşeyi aramışım,gül ağcında, Her yabancıda kokunu,sıcaklığını Olmadı ise n...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Göden']::text[], 8.5, '{"poet":"Mehmet Göden","poet_slug":"mehmet-goden","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/umut-265-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çanakkalede Şehadet', 'canakkalede-sehadet-i-rfan-kayagil-sjmxi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Conkbayırında kaldın elbet sana felaket

Bir bilseydin burası bizim memleket

Türk tür Türk e tek rakip devlet.

Hep dışarıdan destekli büyük hiyanet

Yedi düvel, hepsi birden önümde

Unutmayız anarız  seni Anzak gününde.

Barıştan yana oldu  çabamız

Yurtta sulh, Cihanda sulh diye öğüt veren Atamız

Tarihten alsaydık ibret

Türkü, Kürdü bir Millet

Buna şahittir Çanakkale de  şehadet

Toprak rengi kızıllara boyandı

Yedi düvel hepsi birden dayandı

Bin yıl oldu, bu topraklar bize yazıldı

Her göz dikene, gürzle mezar kazıldı.

Çanakkale benim güzel vatanım

Fedadır sel olsa akan kanım

Ayrılık en büyük gaflet

Türkü, Kürdü bir Millet

Buna şahittir Çanakkale de şehadet.', 'Conkbayırında kaldın elbet sana felaket Bir bilseydin burası bizim memleket Türk tür Türk e tek rakip devlet. Hep dışarıdan destekli büyük h...', ARRAY['Türk Edebiyatı','Şiir','İrfan Kayagil']::text[], 8.5, '{"poet":"İrfan Kayagil","poet_slug":"i-rfan-kayagil","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/canakkalede-sehadet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Münacaat', 'munacaat-hasan-ulusoy-5vf7u', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şimdi yaralı gönüller 

Senden merhem bekliyor. 

Şimdi açıldı eller 

Dizler emekliyor. 

Buram buram sevda kokar 

Yüreklerde adın var. 

Ya ilahi emrin ile 

“şifa bulur yaralar” 

hep tutkunun idim... 

yolunun yolcularına 

hep imrenerek baktım 

sana yanık gönüllere. 

Bazen gelmek istedim 

Ben de geleyim dedim 

Nefis girdi araya 

Ben nerdeyim, menzil nere. 

Ümidime hazan vurdu 

İçimde şeytanın kurdu 

Şeytandan destek aldı 

Nefsim azdı kudurdu. 

Ya ilahi! Aklaşsın 

Ruhumdaki karalar... 

Resulün önümde kılavuz 

Kararan ruhuma ışık. 

Önümde gitsin ashab, 

Yoksa yolum karışık, 

Sana ermez ilahi... 

Şeytana yoldaş nefsim 

Fırsat vermez ilahi... 

Sen göster de göreyim 

Yolunu yolcularını 

Göstermezsen gözüm 

Dostun görmez ilahi... 

Bu gün kadir oldu gece 

Melekler saf saf inerken. 

El açan kullarına acı, 

Af etmeyi severken. 

Çalmam başka kapıyı 

Nasıl çalarım ilahi. 

İsyan, tuğyan, günah 

Yandım, yanarım ilahi... 

Kırk yıldır yabandayım 

Şimdi geldim kapına 

Yolun sorarım ilahi... 

Baktım, gördüm, her şey boş 

Sende kararım ilahi... 

Kovarsan da gitmem 

Başka yerde merhameti 

Nasıl ararım ilahi... 

Ya sadık et yolunda 

Sana sadık kul olayım 

Ya da bitmez zarım ilahi.... 

Ben kendimden bizarım ilahi....', 'Şimdi yaralı gönüller  Senden merhem bekliyor.  Şimdi açıldı eller  Dizler emekliyor.  Buram buram sevda kokar  Yüreklerde adın var.  Ya ila...', ARRAY['Türk Edebiyatı','Şiir','Hasan Ulusoy']::text[], 8.5, '{"poet":"Hasan Ulusoy","poet_slug":"hasan-ulusoy","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/munacaat-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiirsel dua', 'siirsel-dua-abdulkadir-azakli-8ps2u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Allah''ım ne olur yardım et bana.

Bütün kalbim ile,inandım sana.

Her zaman olmuşum,doğrudan yana.

Beni kendine dost,eyle Allah''ım.

Lüzümsuz işlerden,alı koy beni.

Her zaman kalbimle,anayım seni.

Dostlarımı eyle,seni seveni..

Beni kendine dost,eyle Allah''ım.

İstiyorum seni memnun edeyim.

Beni sevdiğinden,emin olayım.

Sevmediklerinden,uzak kalayım.

Beni kendine dost,eyle Allah''ım.

Yaşadığım sürece sihhat ver bana.

Dert veripde derman,aratma beni.

Bilmediklerimi,sen öğret bana.

Ben kendime veli,eyledim seni.', 'Allah''ım ne olur yardım et bana. Bütün kalbim ile,inandım sana. Her zaman olmuşum,doğrudan yana. Beni kendine dost,eyle Allah''ım. Lüzümsuz i...', ARRAY['Türk Edebiyatı','Şiir','Abdulkadir Azaklı']::text[], 8.5, '{"poet":"Abdulkadir Azaklı","poet_slug":"abdulkadir-azakli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/siirsel-dua-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karıncalar', 'karincalar-ahmet-agdere-vanmf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Karıncalar, ne olur gelmeyin üstüme üstüme

Şimdi süsleme vakti değil kolumu bacağımı

Karınca kararınca benim de yapacaklarım var

Gencecik yaşımda şenlendirmeyin ocağımı

En iyisi mi sizler şimdi usul usul yollanın

Ben de daha etli butlu olmak için yol alayım

Bu işten hem siz kârlı çıkarsınız hem de ben

Daha büyük şölenlerde görüşürüz karıncalar', 'Karıncalar, ne olur gelmeyin üstüme üstüme Şimdi süsleme vakti değil kolumu bacağımı Karınca kararınca benim de yapacaklarım var Gencecik ya...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ağdere']::text[], 8.5, '{"poet":"Ahmet Ağdere","poet_slug":"ahmet-agdere","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/karincalar-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herşeyin hazır!', 'herseyin-hazir-mehmet-goden-evmcf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gir gönüle bak seninle ne günümüz olacak,

Şu kalbime bir ışık ver sevdalara dolarız,

Tahtın hazır köşesinde Tac’ın gönlümde kafes,

Bilmem ne ömür yeter buna,nede nefes

Odalar lavantalı gelincikten  yastık,

Menekşeden takısı kır çiçeğinden yatak,

Kimsecikler giremesin kilit vur kapına,

Bilinmeyenden deklem kur,	

Sen gözünün içine bakabildiğine sor,

Hem söylebilmek hemde yaşamak zor,

İçinde saklayabilenler bilir,

Seni seviyorum  demek  yürek ister,

Yakar derinden sanarsınki bir Kor.

09.05.1987', 'Gir gönüle bak seninle ne günümüz olacak, Şu kalbime bir ışık ver sevdalara dolarız, Tahtın hazır köşesinde Tac’ın gönlümde kafes, Bilmem ne...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Göden']::text[], 8.5, '{"poet":"Mehmet Göden","poet_slug":"mehmet-goden","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/herseyin-hazir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüz Hatlarında Saklama Sevgini', 'yuz-hatlarinda-saklama-sevgini-nurten-tarim-ac46b', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yüz hatlarında saklama sevgini

Al kollarına 

Okşa saçlarımı

Dokundur dudaklarıma sımsıcak dudaklarını

Terimiz oluştursun derya denizi

Aşkımız yeşersın olsun ormanımız

Boş kalmasın gönlüm

Sevgin aydınlatsın yüreğimi

Tuğba gölüne akan pınarım

 Suyum ol ak içime

Ormanım ol dal budak sal yüreğime

Dünyamda cennet bakışlım', 'Yüz hatlarında saklama sevgini Al kollarına  Okşa saçlarımı Dokundur dudaklarıma sımsıcak dudaklarını Terimiz oluştursun derya denizi Aşkımı...', ARRAY['Türk Edebiyatı','Şiir','Nurten Tarım']::text[], 8.5, '{"poet":"Nurten Tarım","poet_slug":"nurten-tarim","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yuz-hatlarinda-saklama-sevgini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herşey seni anlatır,', 'hersey-seni-anlatir-mehmet-goden-3w847', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yazılan herşey seni anlatır

Her güzel söz gözlerini,

Yıkılan gurur acını,

Ve; içimdeki ismin hatıranı yaşatır,

	

Mehmet Göden,20.07.1978.', 'Yazılan herşey seni anlatır Her güzel söz gözlerini, Yıkılan gurur acını, Ve; içimdeki ismin hatıranı yaşatır, 	 Mehmet Göden,20.07.1978....', ARRAY['Türk Edebiyatı','Şiir','Mehmet Göden']::text[], 8.5, '{"poet":"Mehmet Göden","poet_slug":"mehmet-goden","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/hersey-seni-anlatir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Solan gençliğim,', 'solan-gencligim-mehmet-goden-0veg5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Mutluydum Dünyamda  umudumu bitirdi birden,

Ömür ile yarışa girdi gençliğim,

Sevemem sanmıştım ondan başkayı,

Bir gülden,bir nergisten bal almaya kalktı gençliğim,

Aç bak gözünü. Dünya nelerle dolu,

Bir sağa bir sola saptı gençliğim

Şaşırıp yolunu çok şeyler görüp,

Kendini kör yollara attı gençliğim,

Harcadı ele geçen her güzel günü,

Düne bakıp yarından yedi gençliğim,

Azgın sele benzettide kendi kendini,

Sonunuda küçük bir damlaya döndü gençliğim.

10.10.1980', 'Mutluydum Dünyamda  umudumu bitirdi birden, Ömür ile yarışa girdi gençliğim, Sevemem sanmıştım ondan başkayı, Bir gülden,bir nergisten bal a...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Göden']::text[], 8.5, '{"poet":"Mehmet Göden","poet_slug":"mehmet-goden","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/solan-gencligim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sözüm var!', 'sozum-var-mehmet-goden-xdk4q', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hiç kimseye takılmadan yaşayacağım

Ne al’ı al kabullenip,

Nede eğriye ses çıkaracağım,

Ve! Keyfim kaçmayacak,

Nedir şu kısa ömürde payıma düşen,

Kimlerden ne arda kalacak,

Kimseyle takas yapmayan,

Bir hayatı süreceğim.

Mehmet Göden,Eylül 2002.', 'Hiç kimseye takılmadan yaşayacağım Ne al’ı al kabullenip, Nede eğriye ses çıkaracağım, Ve! Keyfim kaçmayacak, Nedir şu kısa ömürde payıma dü...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Göden']::text[], 8.5, '{"poet":"Mehmet Göden","poet_slug":"mehmet-goden","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sozum-var-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suç Bende!', 'suc-bende-mehmet-goden-pstky', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ağla gözlerim yaşını içine akıt	

Kalp acısı gelir geçer,

Bıraktığı yığından,

Ömür yeli gelir geçer,

Dilerdim oda öyle,

Tutulupta yansaydı,

Umursamaz tavrına,

Ömrünü adasaydı,

Karşılıksız olsaydı,

Duyduğu bütün hisler,

Yaşanmaz böyle şeyle,

Büyük sabırlar ister,

Olmuşum ben tarumar,

Öylesine bir aşık,

Duygularım köreldi,

Aklım hepten karışık,

Sevmez olaydım keşke,

Onda kaldı herşeyim

Keyf iyi, gönül rahat,

Bende bütün kabahat,

19.02.03', 'Ağla gözlerim yaşını içine akıt	 Kalp acısı gelir geçer, Bıraktığı yığından, Ömür yeli gelir geçer, Dilerdim oda öyle, Tutulupta yansaydı, U...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Göden']::text[], 8.5, '{"poet":"Mehmet Göden","poet_slug":"mehmet-goden","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/suc-bende-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kur''an inancı', 'kur-an-inanci-abdulkadir-azakli-536e1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kur''anı bilipde anlayamazsan.

Verdiği mesajı kavrayamazsan.

Onun harıcinde,yollar ararsan.

Din tacırlarına köle olursun.

Din bezirganından,fayda beklenmez.

Okendinden başka,kimseyi sevmez.

Hayale dalmıştır,Gerçeği görmez..

Gerçeği görmeyen alım olamaz.

Eğer okuyorsan kur''an mealı.

Okuyanın mutlak,güzeldir halı.

Kur''ana uyarsan olursun veli.

Yalnız gerçekleri,görebilirsen.

Her insan kur''anı,okumalıdır.

Onun sözlerini,anlamalıdır.

Onda kendine,yol aramalıdır.

Başka kurtuluş yok,bilirsen eğer.', 'Kur''anı bilipde anlayamazsan. Verdiği mesajı kavrayamazsan. Onun harıcinde,yollar ararsan. Din tacırlarına köle olursun. Din bezirganından,f...', ARRAY['Türk Edebiyatı','Şiir','Abdulkadir Azaklı']::text[], 8.5, '{"poet":"Abdulkadir Azaklı","poet_slug":"abdulkadir-azakli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kur-an-inanci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitti..!', 'bitti-mehmet-goden-q4yh9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gülmezmi hiç kader yüze? 

Ömür gitti yollar bitti	

Yaslanacak herşey bitti

El verecek İnsan bitti.

Bu dünyada gözler şaşı

Bölsen sofrandanda aşı

Bir namazlık bu naaşı

Kaldırırlar ödev bitti.

Beni bulur yitirirmi

Susuz çölü geçirtirmi

Susamışım içirtirmi? 

İçem dedim umman bitti.

Bir bitmeyen bende gaflet

Beklesem rahmandan rahmet

Yağmaz olur neye hikmet

Birden yağsa herşey bitti.

Mehmet Göden,26.04.2004', 'Gülmezmi hiç kader yüze?  Ömür gitti yollar bitti	 Yaslanacak herşey bitti El verecek İnsan bitti. Bu dünyada gözler şaşı Bölsen sofrandanda...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Göden']::text[], 8.5, '{"poet":"Mehmet Göden","poet_slug":"mehmet-goden","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bitti-245-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bundan sonra..!', 'bundan-sonra-mehmet-goden-y84d4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sonra..! 

Kurduğumuz hayalin penceresinden bakarım,

Bakar dalarım ta uzağa,

Ne ses ne iz hatırlatır seni bana,

Kır düşen şakak ve kırık bir kalpten başka,

Ben o! olamam kalbinde kalan,

Ateşi olamam aşkının,kor olamam külünde,

Kahretme; hükmeden değilimki kaderime,

Olamam o candan öte,sevebilen,

Git yolumuz ayrı nasılsa,

Dönme bakma ardına bir kez ‘de olsa,

Acı veren ben değil hatıramız,

Neyi nasıl nereye koyabilirizki! bundan sonra.

Mehmet Göden,Ocak 2000.', 'Sonra..!  Kurduğumuz hayalin penceresinden bakarım, Bakar dalarım ta uzağa, Ne ses ne iz hatırlatır seni bana, Kır düşen şakak ve kırık bir ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Göden']::text[], 8.5, '{"poet":"Mehmet Göden","poet_slug":"mehmet-goden","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sonra-101-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yusuflar Kuyuya', 'yusuflar-kuyuya-yasar-tezel-v76q4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hani geçmiştin

Geleceğin,gençliğin

Kaybettin kardeşini

Davalar uçurumlarda

Gömleğini bulurlar

Yusuf kokar yollar

Ağlar Yakuplar

Bu uğurda

Nasıl kaybolur

Bel bağlanan umut

Hangi vaade kandılar

Gelip geçer makamlar

Sizi şahit tutarlar

Nice şehadete kalktı 

parmaklarınız,parmaklar

Melekler sayar

Geçmişe veda

A

B

Hakları hiçe sayarlar

Elveda

Herkes kendi yoluna', 'Hani geçmiştin Geleceğin,gençliğin Kaybettin kardeşini Davalar uçurumlarda Gömleğini bulurlar Yusuf kokar yollar Ağlar Yakuplar Bu uğurda Na...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Tezel']::text[], 8.5, '{"poet":"Yaşar Tezel","poet_slug":"yasar-tezel","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yusuflar-kuyuya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Etme!', 'etme-mehmet-goden-8pztl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dile verip rezil etme kendini,

Gizliyi gördüğün gözde eyidir,

Allayıp pullayıp sunma derdini,

Tartılıp söylenen sözde eyidir

14.02.2004', 'Dile verip rezil etme kendini, Gizliyi gördüğün gözde eyidir, Allayıp pullayıp sunma derdini, Tartılıp söylenen sözde eyidir 14.02.2004...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Göden']::text[], 8.5, '{"poet":"Mehmet Göden","poet_slug":"mehmet-goden","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/etme-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ödüm Kopuyor', 'odum-kopuyor-ali-uygun-8b2nx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ÖDÜM KOPUYOR

Yine saçlarına kızıl gülleri

Takacaksın diye ödüm kopuyor

Üzeri küllenmiş kalp ateşini

Yakacaksın diye ödüm kopuyor

Yüreğim tutuşur o bakışından

İçimdeki deniz hep gözyaşından

Bir sabah ansızın köşe başından

Çıkacaksın diye ödüm kopuyor

“Gelirim demiştin, hani seneye”

Anlamış değilim bu hasret neye

Yüreğimi koyup bir mengeneye

Sıkacaksın diye ödüm kopuyor

Aşkın çeşmesinden içmedim suyu

Gözlerim unuttu derin uykuyu

Ümitten yaptığım gecekonduyu

Yıkacaksın diye ödüm kopuyor

Faydası yok sakın, pişmanım deme

İhtiyaç kalmadı ilaca eme

Azgın bir sel olup gönül bahçeme

Akacaksın diye ödüm kopuyor

10.04.2005

 Tahir Siral tarafından 

Mahur makamında bestelendi', 'ÖDÜM KOPUYOR Yine saçlarına kızıl gülleri Takacaksın diye ödüm kopuyor Üzeri küllenmiş kalp ateşini Yakacaksın diye ödüm kopuyor Yüreğim tut...', ARRAY['Türk Edebiyatı','Şiir','Ali Uygun']::text[], 8.5, '{"poet":"Ali Uygun","poet_slug":"ali-uygun","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/odum-kopuyor-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilemedik!', 'bilemedik-mehmet-goden-co0l8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bilemedik zararları ziyanı,

Dost belledik yılanlarla çiyanı,

Boşa verdik ömür denen zamanı

Üzülüp kahretmek neyi getirir,

Getirirmi gür saçının telini,

Döksen içerinde topladığın selini,

Uzatsanda biçareyken kendi elini,

Çağlasan coşsan neyi getirir.

30.10.2004', 'Bilemedik zararları ziyanı, Dost belledik yılanlarla çiyanı, Boşa verdik ömür denen zamanı Üzülüp kahretmek neyi getirir, Getirirmi gür saçı...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Göden']::text[], 8.5, '{"poet":"Mehmet Göden","poet_slug":"mehmet-goden","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bilemedik-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Musluman', 'musluman-abdulkadir-azakli-cj8dm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ey musluman diye bilinen insan.

Bir hiç olduğunu sakın unutma.

Bu kisa ömrünle,fanı dünyada.

Cehalete düşüp,yolundan sapma.

Dünya''ya iyi bak,açık kör olma.

Ah ile vah ile,ömrün geçiyor.

Eğer gerçekleri,göremiyorsan.

Kıldığın namazlar,boşa gidiyor.

Allah''ı seversen,adaletli ol.

Adalet olmazsa,rahmetde olmaz.

İnsanlara karşı merhametli ol.

Merhamet olmazsa,imanda olmaz.

Evvela insan ol, sonra müslüman.

Kalbin ile dilin beraber olsun.

Dini menfaatın,için kullanma.

Allah''ın rahmeti, seninle olsun.', 'Ey musluman diye bilinen insan. Bir hiç olduğunu sakın unutma. Bu kisa ömrünle,fanı dünyada. Cehalete düşüp,yolundan sapma. Dünya''ya iyi bak...', ARRAY['Türk Edebiyatı','Şiir','Abdulkadir Azaklı']::text[], 8.5, '{"poet":"Abdulkadir Azaklı","poet_slug":"abdulkadir-azakli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/musluman-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözler', 'gozler-metin-soydeveli-wjrlk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir bakışın yaktı çaresiz özüm 

Şaşırdım feleğim bilemem sözüm 

Hissediyorum da gülecek yüzüm

Sevgiyle ömrüme GİRDİ gözlerin

Güldürmek isterim ömrümce yüzün

Dediğimde, evet olmuştu sözün

Kalmadı yüzünde silindi hüzün

Duvağın, telinle GÜLDÜ gözlerin

Mutluluk önceden kesin sezilmez

Bulunca yaşanır kimse bilemez 

Kelimelerle ifade edilmez

Yaşlar ucunda DOLDU gözlerin

Yıllar  hızla geçti kalmadı ilgi 

Sayende gönüller hüznü de bildi

Hüsrana uğradık  bitmişti sevgi

Herkes geldi geçti YOLDU gözlerin

Sandın dünya malı her şeye değer

Bilmedin, seven de unuturmuş meğer

Yakışmadı senin yüzüne keder

Gönül pencerene TÜLDÜ gözlerin

Bilemedi kıymet elinden kaydı

Mutluluğu zayi biçare kaldı

Kaderini kendi eliyle yazdı

Yuvasında ferin SOLDU gözlerin', 'Bir bakışın yaktı çaresiz özüm  Şaşırdım feleğim bilemem sözüm  Hissediyorum da gülecek yüzüm Sevgiyle ömrüme GİRDİ gözlerin Güldürmek ister...', ARRAY['Türk Edebiyatı','Şiir','Metin Soydeveli']::text[], 8.5, '{"poet":"Metin Soydeveli","poet_slug":"metin-soydeveli","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gozler-77-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sitem', 'sitem-sennur-cetin-9e7dy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mutluluğa hasret nemli gözlerim

Dertliyim kederliyim yaşamak istemiyorum

Tanıyamıyorum kendimi

Gözümde yaş gönlümde sonsuz hüzün

Her gece ağlarım kırgınlığım dağlardan yüce

Kalbim artık yaşamaya küskün

Kahredeceksin  kalacaksın sende birgün yalnızlığınla

Yokluğuma alışamayacak sende gözyaşı dökeceksin

Suçluyum çok çektirdim diyeceksin

Ne sarışını ne mavi gözlüsü

Güldüremeyecek asla yüzünü

Özleyecek hayalimi canlandıracaksın gözünde

Mutlu olamayacak ve

Ben yalnız seni sevmişim diyeceksin

22.11.1997', 'Mutluluğa hasret nemli gözlerim Dertliyim kederliyim yaşamak istemiyorum Tanıyamıyorum kendimi Gözümde yaş gönlümde sonsuz hüzün Her gece ağ...', ARRAY['Türk Edebiyatı','Şiir','Sennur Çetin']::text[], 8.5, '{"poet":"Sennur Çetin","poet_slug":"sennur-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sitem-240-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dinmez İhtiras', 'dinmez-i-htiras-metin-soydeveli-ky2hv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dinmez ihtiras, doymaz gözün gönlün  

Dünyalar senin olsa, genç çağında        

Cıvıl cıvıl aşk, delice yaşanır,              

Şakıyan bülbül gibi gül dalında          

Gönüller hoş yar  yanında olunca

Güller goncadır. Bülbüller aheste

Bahar güzel, can cananı bulunca

Samanlık seyran olur sevene

Duyarsın gönül  titreten bir mısra         

Satır satır eklemek gelir içinden            

Sarılırsın kağıda kaleme, hırsla             

Söylenmemiş ne kalmış aşka dair         

Hepsi söylenmiş, bul bulabilirsen         

Menzile varmış ok dinginliği var          

Yaprak bile kıpırdamaz  içimde          

Geçmiş coşkusu, küllenmiş bir har                  

Aşkın ifadesi başka biçimde                 

Ömür bu geçer bir ışık hızıyla              

Göçmek istersin, kolay değil ölmek!    

Gömelim desem ihtiraslarınla               

Dar gelir kabir, sığmazsın toprağa', 'Dinmez ihtiras, doymaz gözün gönlün   Dünyalar senin olsa, genç çağında         Cıvıl cıvıl aşk, delice yaşanır,               Şakıyan bülbü...', ARRAY['Türk Edebiyatı','Şiir','Metin Soydeveli']::text[], 8.5, '{"poet":"Metin Soydeveli","poet_slug":"metin-soydeveli","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/dinmez-ihtiras-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Eski Bayramlar', 'o-eski-bayramlar-serap-tepedelen-6ftzo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hani bayramlarımız vardı,renkli düşler içinde

Balonlar uçuşurdu göğün maviliğinde

Ellerimizde elma şekerleri,kâğıt helvalar,

Nerede saklandı o güzelim bayramlar? 

Tatlı bir telaş yaşanırdı gündoğumlarında

Birbirine yaslanmış nem kokan duvarlarda

Çoluk çocuk kucaklaşırdık sevgiyle

Fırlardık sokaklara cicili giysilerle.

Tek tek kapı çalmanın o zevki yok mu,

El öpüp para,şeker almışsın çok  mu? 

Naylon torbalara doldururken kesemizi

Yazlık sinemalarda alırdık nefesimizi.

Ah o bayramlar,eski bayramlar

Tatlı bir düş gibi geçmişte yaşananlar

Sevdadan bir yumak olmuştuk ailemle

Nasıl da bağlıydık yürekten birbirimize.

O eski düş,eski heyecan nerede? 

Nerede saklandı o güzelim bayramlar? 

Yalnızlığın kucağında ağlayan yaşlı kadın,

Çocuklarını bekler dargın gözlerle! 

(1997,Bursa)', 'Hani bayramlarımız vardı,renkli düşler içinde Balonlar uçuşurdu göğün maviliğinde Ellerimizde elma şekerleri,kâğıt helvalar, Nerede saklandı...', ARRAY['Türk Edebiyatı','Şiir','Serap Tepedelen']::text[], 8.5, '{"poet":"Serap Tepedelen","poet_slug":"serap-tepedelen","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/o-eski-bayramlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Debilerin Yükseliyorken İçimde…(Hayallerde Sen)', 'debilerin-yukseliyorken-i-cimde-hayallerde-sen-i-brahim-nazim-ulker-emph2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Elimde bir şemsiye,

Ve bir yelkenli yüreğimde; 

Yağmurlar yağıyor,

Açılıyorum ufuksuz denizlere,

Sensizliğin debisi yükseliyor içimde,

Seni düşündükçe …

Kaybolmuş yok ki rotam,

Nede yelkenim tamam,

Yırtık bir yelkenim var,

Ve bir sandalım tahtadan …

Hem cahilim, hem fakir; 

Atmışım kendimi görmeden hakir,

Bende üfler olmuş Sur’unu İsrafil…

Aşka kanıp kendimi Nuh sandım,

Yetmedi tahta sandalımı gemi yaptım,

Bende ki yangın-ı deryana saldım,

Boğulmaktayım, tutuşmaktayım ve yandım…

İçimde debilerin yükseliyor,

İçimde ölüm çanları çalıyor.

İsrafil  son kez Sur’unu üflüyor,

Sen, kıyametim kopuyor! 

Ve ruhum yenik düşüyor; 

Ufuksuz denizlerinde,

Kahverengi gözlerinde…

Ve uyanıyorum; 

Bir şemsiye elimde,

Yağmurlar yağıyor

Soluksuz yürüyorum…

                 İbrahim Nazım Ülker

                 Ocak-Mart 17 2006', 'Elimde bir şemsiye, Ve bir yelkenli yüreğimde;  Yağmurlar yağıyor, Açılıyorum ufuksuz denizlere, Sensizliğin debisi yükseliyor içimde, Seni ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Nazım Ülker']::text[], 8.5, '{"poet":"İbrahim Nazım Ülker","poet_slug":"i-brahim-nazim-ulker","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/debilerin-yukseliyorken-icimde-hayallerde-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değmez Bu Yaşa', 'degmez-bu-yasa-metin-soydeveli-yajob', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Neler gördük geçirdik, kolay mı geldik biz bu yaşa  

Hayat yolu boran, fırtına, aldırma  yağmur, yaşa    

Sil kederleri gönlünden, aldırma gönlünce yaşa  

Akıtma  incilerini değmez döktüğün bu yaşa', 'Neler gördük geçirdik, kolay mı geldik biz bu yaşa   Hayat yolu boran, fırtına, aldırma  yağmur, yaşa     Sil kederleri gönlünden, aldırma g...', ARRAY['Türk Edebiyatı','Şiir','Metin Soydeveli']::text[], 8.5, '{"poet":"Metin Soydeveli","poet_slug":"metin-soydeveli","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/degmez-bu-yasa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biricik Yavrum', 'biricik-yavrum-sennur-cetin-93fhd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Canımdan can verdiğim

Yavrum deyip bağrıma bastığım

Yüreğini yüreğime sardığım

Sevdikçe sevmeye doyamadığım

Alyanaklı bal dudaklı mis kokulum

Saçının her teline kurban olduğum

Anneciğim demenle nefes aldığım

Gözümün nuru biricik yavrum

Satırlar sana sevgimi anlatamaz

Sen benim can suyum birtanecik aşkımsın', 'Canımdan can verdiğim Yavrum deyip bağrıma bastığım Yüreğini yüreğime sardığım Sevdikçe sevmeye doyamadığım Alyanaklı bal dudaklı mis kokulu...', ARRAY['Türk Edebiyatı','Şiir','Sennur Çetin']::text[], 8.5, '{"poet":"Sennur Çetin","poet_slug":"sennur-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/biricik-yavrum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Sendeyim', 'bir-sendeyim-reyhan-tataroglu-t6sdg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'gözlerimden 

                                sonbahar yaprakları dökülüyor

                                bak! 

                                gözlerin bana gülüyor

                                yine hasret,yine hüzün

                                ne gündüzün güneşinde 

                                ne gecenin zifiri karanlığında

                                gitmez ki kör olmayasıca

                                yüzün

                                kalmadı artık

                                hayaline ihtiyacım

                                ben sana,ben sevdana

                                ben sevgine açım

                                sana muhtacım...

                                e''be yeşil gözlüm

                                söyletme beni

                                seyrederken

                                manzaralar kıskanırdı 

                                seni

                                yüreğinden gözlerine akseden

                                deseni

                                kaç asır oldu gideli

                                sen oralarda divane

                                ben buralarda deli

                                yok artık 

                                ayırmam gözümün önünden

                                çok ders aldım inan ki dünden

                                ne gökte,ne yerdeyim

                                ne ölüde,ne dirideyim

                                bir sendeyim,bir bendeyim

                                daha ne deyim...

                                aah! 

                                sınır tanımaz yürekteki yangınlar

                                feryatlar

                                ne bilirler ki beni

                                şirinler,ferhatlar

                                küskünüm

                                kokunu getirmeyen rüzgarlara

                                küskünüm

                                sensiz gelen baharlara

                                isterse 

                                sensiz bütün ömrüm geçsin

                                yaz sıcağında

                                isterse

                                sensiz bütün ömrüm geçsin

                                kış kucağında

                                sensiz 

                                hangi hayat beni seçerse

                                seçsin

                                yeter ki

                                senden alıkoymaktan

                                vazgeçsin

                                hani diyorum

                                ansızın çalsan kapıyı

                                desem ki

                                ''''kim o''''

                                 sadece alsan  nefes

                                ne enfes olurdu

                                değil mi

                                ne enfes...

                                yeşil gözlüm

                                kalubeladan sözlüm

                                ben sana vurgunum...

                                sevda özlüm...', 'gözlerimden                                  sonbahar yaprakları dökülüyor                                 bak!                             ...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Tataroğlu']::text[], 8.5, '{"poet":"Reyhan Tataroğlu","poet_slug":"reyhan-tataroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":64,"source_url":"https://www.antoloji.com/bir-sendeyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben İstanbul’da, İstanbul bendedir…', 'ben-i-stanbul-da-i-stanbul-bendedir-yusuf-ziya-leblebici-a8hwl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir martıyım Boğaz’daki kapıları geçip 

Marmara’ya giren…

İstinye’nin yokuşu, Sarıyer’in coşkusu

Kanatlarıma vururken

Bebek sırtlarından yayılır

Bir İstanbul kokusu…

Beni geçip de bulutlara yükselir

Ben İstanbul’da, İstanbul bendedir…

Kızkulesi, bu şehrin abidesi

Yaşanmış ve de yaşanacak sevdaların

Ayakta kalan şahidi…

Üsküdar Beşiktaşla bakışırken

Sirkeci Kadıköy’e göz kırparken

O Gözlerde bir kirpiktir Kızkulesi

Bir bulutum Marmara’da

Sandallar balık toplarken Kumkapı’da

Ayasofya yakınlaşıyor bana

Sultanahmet el sallarken

Mimar Sinan’ı hissediyorum derinden..

Hiç gitmemiş, asırlardır yerindedir

Ben İstanbul’da, İstanbul bendedir

İlahiler dolaşırken Eyüp Sultan’da

Bir aşk yaşanır mey’lerin sesinden

Asırlık taşlar dimdik dururken Balat’ta

Bir tarih sesi gelir Galata Kulesi’nden

Beyoğlu o tarihin içindedir

Ben İstanbul’da, İstanbul bendedir…

Sultanlar şehri, unutulur mu Şehremini

Topkapı’dır İstanbul kalesi

Ulubatlı’nın diktiği sancak

Mahşerde yıkılır ancak

İstanbul, bu kalenin gölgesindedir

Ben İstanbul’da, İstanbul bendedir.

Yeditepeli şehir,  şairlerin ilhamı

Şiirleri şiir yapan dizeler

İnip çıkarken notaları

Gönüller bir martı misali İstanbul’u gezer

Her göz kırpmada bu şehri öper…', 'Bir martıyım Boğaz’daki kapıları geçip  Marmara’ya giren… İstinye’nin yokuşu, Sarıyer’in coşkusu Kanatlarıma vururken Bebek sırtlarından yay...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/ben-istanbul-da-istanbul-bendedir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlk Bakışta', 'i-lk-bakista-yasar-tezel-k6osm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hoş bakışlarda takılı kaldı sevdam

Göz baharlarında yaşanası aşklar

Sürmelerinde  nazarlar kayboldular

Bebeğinde bir ben var yaşanmışlar

Bakma ruhum baktığını anlar', 'Hoş bakışlarda takılı kaldı sevdam Göz baharlarında yaşanası aşklar Sürmelerinde  nazarlar kayboldular Bebeğinde bir ben var yaşanmışlar Bak...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Tezel']::text[], 8.5, '{"poet":"Yaşar Tezel","poet_slug":"yasar-tezel","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ilk-bakista-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taşınmak', 'tasinmak-ozdemir-asaf-oyuv6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'TAŞINMAK

Taşınmak kadar

Hüzünlü bir kırık yoktur

Bir kopma bir yaralanma

Gizlenmiş bir hıçkırık yoktur

Şarkıları vardır ya büyük olayların

Taşınmanın da bir şarkısı olmalı dedik

Şimdi onu okuyalım

Şarkısını taşınanların

Çocuklar dikkat edin

Bir şey unutulmasın

Mangalın kapağı

Tuz kutusu

Teyzemin başörtüsü

Ihlamur torbası

Sürahinin örtüsü

Kırılmasın dikkat edin

Safran kavanozu

Çocuklar dikkat edin

(Şangır şungur) 

Ah kırılmasın

Kırılmasındı

Anneannemin lambası

(Kamyon sesi gelir) 

Her şey tamam mı

Her şey tamam

Anne her şey tamam

Tastamam

Ama babamın

Şu pencerede kalan

Bakışlarını

Alamadım bir türlü

Çakılmış köşesine

Alınmıyor alınmıyor

Babamın bakışları

Kırılmıyor da

Yerlere de düşmüyor

Orada

Duruyor hava gibi

Taşınmıyor anne

Babamın bakışları

Taşınmıyor

Desinler boşuboşuna

Güle güle', 'TAŞINMAK Taşınmak kadar Hüzünlü bir kırık yoktur Bir kopma bir yaralanma Gizlenmiş bir hıçkırık yoktur Şarkıları vardır ya büyük olayların T...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/tasinmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Ayna*', 'ayna-zeynep-sahin-vmjum', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kiralık gönlüme sığınan aşık

Çık artık! 

Tadilat var bu gönülde

Hem de her günde.

Seviyorum seni diyen gözden 

Ve git artık diyen sözden başka

Ne gördün bende.

Kalbimden çıkmaya üşenirsen

Sen bilirsin.

Enkazında gönlümün

Belki silinirsin.

O zaman keşke gitseydim dersin

Ama bilirdim beceremezdin.

Çünkü seven gözden daha doğru

Daha anlamlı söz yok bu dünyada.

Dil bir defada der “ seviyorum”

Gözler her saniyede haykırır aşkı.

Bilirim anlatır gözle ama ne acı

Sevdiğini bilerek yok etmek aşkı.', 'Kiralık gönlüme sığınan aşık Çık artık!  Tadilat var bu gönülde Hem de her günde. Seviyorum seni diyen gözden  Ve git artık diyen sözden baş...', ARRAY['Türk Edebiyatı','Şiir','Zeynep Şahin']::text[], 8.5, '{"poet":"Zeynep Şahin","poet_slug":"zeynep-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ayna-99-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel', 'gel-yucel-gursac-nb0pd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gel uyuma be güzelim

şimdi ütopik rüyalar görmenin zamanı değil

şu an sevişme vaktidir

hadi

kaldır eteğini, gel yanıma

hadisene sokul öteme..', 'Gel uyuma be güzelim şimdi ütopik rüyalar görmenin zamanı değil şu an sevişme vaktidir hadi kaldır eteğini, gel yanıma hadisene sokul öteme....', ARRAY['Türk Edebiyatı','Şiir','Yücel Gürsaç']::text[], 8.5, '{"poet":"Yücel Gürsaç","poet_slug":"yucel-gursac","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/gel-283-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Kim Bilir*', 'kim-bilir-zeynep-sahin-z0uhb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir gün pembeye çalarsa beyazın rengi

Öyle ya da böyle kâr etmezse arınmak 

Bir umut yitiyordur gönüllerde

Bir çiçek soluyordur yaban ellerde.

Güneş kızıl doğar da akşam beyaz batarsa 

Güzün aydınlık gökyüzü yazın kara olursa

Konuşursa bebeler susmuşsa ihtiyarlar

Bir cesaret doğuyordur yitik gönüllerde

Bir yıldız kayıyordur bilinmezlerde.

Sabrın taşı ayrılmışsa orta yerinden 

Selamet alıp başını gitmişse sonsuzluğa

Çaresiz  bir hıçkırık duyulur kimsesizden

Dile gelir duygular en çarpıcı yerinden.', 'Bir gün pembeye çalarsa beyazın rengi Öyle ya da böyle kâr etmezse arınmak  Bir umut yitiyordur gönüllerde Bir çiçek soluyordur yaban ellerd...', ARRAY['Türk Edebiyatı','Şiir','Zeynep Şahin']::text[], 8.5, '{"poet":"Zeynep Şahin","poet_slug":"zeynep-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kim-bilir-59-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'In Vivo', 'in-vivo-ozdemir-asaf-mqsdf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'IN VIVO

Pencerenden bakma denize,

İnanırsın güzel olduğuna maavilerin.

Renklerini kaybedersin

Uzaktan

Bir yatağın vardır senin, 

Seninledir,

Uyuyunca kaybedersin.', 'IN VIVO Pencerenden bakma denize, İnanırsın güzel olduğuna maavilerin. Renklerini kaybedersin Uzaktan Bir yatağın vardır senin,  Seninledir,...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/in-vivo-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karagözlüm', 'karagozlum-sennur-cetin-o0qiz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Günler sensiz geçmiyor

Sensizlik beni perişan etti 

Ey yüzüne bakmaya doyamadığım

Sana olan sevgim işte böyle benim 

Bu kadar saf bu kadar el değmemiş

Ve ağlamak kadar çaresiz

Kader be karagözlüm

Ama biliyorum ve diliyorum

Bu karanlık gecelerden sonra

Elbet birgün aydınlığa kavuşacağız

Sırf bu yüzden

Hayata ve kadere kalkan oluyorum

Öyle senden çok uzaklarda değilim

Belki sana senden daha yakın bir yerde

Seni bir anne duası kadar

Yüreğimle içten seviyorum

28.09.2005', 'Günler sensiz geçmiyor Sensizlik beni perişan etti  Ey yüzüne bakmaya doyamadığım Sana olan sevgim işte böyle benim  Bu kadar saf bu kadar e...', ARRAY['Türk Edebiyatı','Şiir','Sennur Çetin']::text[], 8.5, '{"poet":"Sennur Çetin","poet_slug":"sennur-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/karagozlum-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Delik deşik', 'delik-desik-reyhan-tataroglu-m3m3w', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'boşlukta gezerken

                                     fellik fellik

                                     aha! dedi

                                     buldum bir karadelik

                                     ''''günaydın''''

                                     derken bir ses

                                     biz gözlerini üfeledik', 'boşlukta gezerken                                      fellik fellik                                      aha! dedi                         ...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Tataroğlu']::text[], 8.5, '{"poet":"Reyhan Tataroğlu","poet_slug":"reyhan-tataroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/delik-desik-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*İstanbul Hepimizin*', 'i-stanbul-hepimizin-zeynep-sahin-onjh9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne senin ne benim

İstanbul hiç kimsenin…

Hem yalnızların

Hem gariplerin

Hem sevdalıların

Hem hiç kimselerin.

İstanbul ne senin 

İstanbul ne benim…

Aslında öksüz İstanbul 

Onda yaşayanlar gibi

Hasret kokar İstanbul

Deniz gibi gök gibi.

Sorsalar bana “ o sende ne” diye

Veremem cevabını bilmem ki niye.

Dargınım ben ona 

Ayrıyım ondan.

İçinde olsam da uzağım yaşamından.

Olmasaydı böyle 

Olmamış olsaydı bu ayrılık,

Hissedermiydim kendimi böylesi yenik

Benim demezmiydim

Onun demezmiydim.

Kalmazdım böylesi yetim.

Ben İstanbul’u kendine yar ettim,

Ve bittim.

Çünkü ben İstanbul’la bir şeydim,

İstanbul’la her şeydim.

İstanbul’la ben bendim.

İçimdeki hasretini nasıl da yendim.

Nasıl da ayırdım gönlümden İstanbul’u

Boğazı, denizi, kız kulesini

Kendimi ve herkesi

Nasıl da aldım İstanbul’dan 

Nasıl da çaldım! 

Şimdi İstanbul yenik

Şimdi İstanbul bitik.

Bir gün geri isterse bizden kendini

Güneşinin her sabah bizim için doğması şartıyla veririz geri

İsterse bizden kendini, söz almak isteriz ondan İstanbul hepimizin

Öyle mi? ...', 'Ne senin ne benim İstanbul hiç kimsenin… Hem yalnızların Hem gariplerin Hem sevdalıların Hem hiç kimselerin. İstanbul ne senin  İstanbul ne ...', ARRAY['Türk Edebiyatı','Şiir','Zeynep Şahin']::text[], 8.5, '{"poet":"Zeynep Şahin","poet_slug":"zeynep-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/istanbul-hepimizin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sürgünde Kaldı', 'surgunde-kaldi-bulent-boral-uwwry', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Anlatırlardı 

Dinlerdik

Buruşuktu yüzleri

Kırılmalar okunurdu

Sakınmalar dökülürdü

Asma köprülerden geçerlerken

Gözbebeklerinin salkımı sessizleşirdi

Dönemeçlerin hikayeleri o yüzlerde oluşurdu

Yaşlılık ve keder o çizgilerde buluşurdu

Anlatırlardı 

Dinlerdik

Yelkenlerin nefesi hep mayısı gösterirdi

Çiğdem kokardı yalnızlıklar

Kırlangıç seslerine karışırdı olasılıklar

Hüzün rüzgarları eserdi sonra

Dokunurduk geçmişin esrarına

Sorular sorardık

Yoktu yazılı tarihimiz

Yazdırılmamıştı

Anlatırlardı 

Dinlerdik

Ses verirdi tarih 

Konuşurdu

Bir haykırıştı belki bu 

Belki lacivert bir gerilimdi

Anlatırlardı 

Dinlerdik

Uzundu ömürleri

Doksana-yüze varırdı

Uzun ömürler onlarda saklı birer sırdı

Sustular sonra

Dinleyemedik

Çekildi sonrasız serin sular

Irmaklar boğuldu

Köprüler yıkıldı

Sustular 

Dinleyemedik

-Her ölüm erken ölümdü-

Onların dahada erkendi

Altmışına varmadan öldüler

Sürgünde kaldı mezarları

Düşleri yakılmış köylerde kaldı

Gülüşleri isli duvarlara asılı kaldı

Sustular 

Dinleyemedik', 'Anlatırlardı  Dinlerdik Buruşuktu yüzleri Kırılmalar okunurdu Sakınmalar dökülürdü Asma köprülerden geçerlerken Gözbebeklerinin salkımı sess...', ARRAY['Türk Edebiyatı','Şiir','Bülent Boral']::text[], 8.5, '{"poet":"Bülent Boral","poet_slug":"bulent-boral","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/surgunde-kaldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sağanak', 'saganak-metin-soydeveli-5z8w3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben nerede miyim? 

Arayıp bulamıyor musun beni? 

Yağmur olup aşk aşk

Üstüne yağıp ıslatıyorum seni.

Sen sıcaklığınla yaktıkça sinemi

Buharlaştırıyorsun beni

Uzun sürmüyor özleminle yoğunlaşmak

Tekrar boşalıyorum üzerine sağanak sağanak.', 'Ben nerede miyim?  Arayıp bulamıyor musun beni?  Yağmur olup aşk aşk Üstüne yağıp ıslatıyorum seni. Sen sıcaklığınla yaktıkça sinemi Buharla...', ARRAY['Türk Edebiyatı','Şiir','Metin Soydeveli']::text[], 8.5, '{"poet":"Metin Soydeveli","poet_slug":"metin-soydeveli","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/saganak-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte', 'i-ste-ozdemir-asaf-oajuf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İŞTE

Bir gözüm doygundur, yalan bakar.

Bir gözüm çocuktur, bilmez.

Bir gözüm dinleniktir, utanır.

Bir gözüm sevinmeyi bilmek için sevinmez.

Bir gözüm gördüğünce caygındır.

O bir gözüm altı olur, eksilmez.', 'İŞTE Bir gözüm doygundur, yalan bakar. Bir gözüm çocuktur, bilmez. Bir gözüm dinleniktir, utanır. Bir gözüm sevinmeyi bilmek için sevinmez. ...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/iste-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İ f ş a', 'i-f-s-a-metin-dikec-wnihy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '“Senin adın kabından dökülen ıtır gibidir”

                                     Neşideler Neşidesi/1.Bap



Ah ki; Sevsen neylerim 

Sevmesem ne

Yar olaydın

Nar olaydım

Yangınımdan devşirdiğin 

Kül olaydım

Ah ki; Dünya bir aykırı pazar

Var olaydın

Sır olaydım

Kimsenin almadığı

Kusur olaydım

Ah ki; sevdalanmak büyüdür derler

Kuş olaydın

Taş olaydım

Zamanın sarnıcında 

Düş olaydım…', '“Senin adın kabından dökülen ıtır gibidir”                                      Neşideler Neşidesi/1.Bap Ah ki; Sevsen neylerim  Sevmesem ne...', ARRAY['Türk Edebiyatı','Şiir','Metin Dikeç']::text[], 8.5, '{"poet":"Metin Dikeç","poet_slug":"metin-dikec","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/i-f-s-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekleyen Şarkı', 'bekleyen-sarki-ozdemir-asaf-ro0tt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sizin için yola çıkmış bir şarkı,

Düşünülmüş gözleriniz üstüne.

İçin-için yaratılmış bir şarkı,

Bırakılmış yollarınız üstüne.

Sizsiz sizi yaşanılmış bir şarkı.

Seslerini uzağınız derledi,

Sözlerini kulağınız derledi,

Anlamını dudağınız derledi,

Sizsiz size uzanılmış bir şarkı; 

Özlemini kucağınız derledi.', 'Sizin için yola çıkmış bir şarkı, Düşünülmüş gözleriniz üstüne. İçin-için yaratılmış bir şarkı, Bırakılmış yollarınız üstüne. Sizsiz sizi ya...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bekleyen-sarki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alacağım Var', 'alacagim-var-levent-ozgec-92ww5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '- - - - ALACAĞIM  VAR - - - -

Yüreğim ezilmişse gönül sohbet neylesin

İçimdeki yıllardan alacağım var benim! 

Yıkılan gururuma Rabbim sabır eylesin

Peşimdeki kullardan alacağım var benim! 

*                             *                                   *

Yıllar yılı başımda bir garip sevda döner

Şimşek olur kor olur şair gönlüme iner

Bu sevda alevlense göz yaşlarımla söner

Başımdaki hallerden alacağım var benim! 

*                              *                                   *

Umudum hayal oldu karanlığa dalıyor

Gördüğüm rüyaları korkularım sarıyor

Baharda saçlarıma kar zamansız yağıyor

Saçımdaki tellerden alacağım var benim! 

*                              *                                    *

Kalemim deli olsa duruşumla vakarım

Mısramı döktüğüm an taş yüreği yakarım

Ben böyle boşuna mı çıkmaz yola bakarım

Düşümdeki yollardan alacağım var benim! 

Düşümdeki yollardan alacağım var benim..! 

                                               M. Levent ÖZGEÇ', '- - - - ALACAĞIM  VAR - - - - Yüreğim ezilmişse gönül sohbet neylesin İçimdeki yıllardan alacağım var benim!  Yıkılan gururuma Rabbim sabır ...', ARRAY['Türk Edebiyatı','Şiir','Levent Özgeç']::text[], 8.5, '{"poet":"Levent Özgeç","poet_slug":"levent-ozgec","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/alacagim-var-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yitik Zamanlar', 'yitik-zamanlar-serap-tepedelen-vknzz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kaç gecenin ağırlığını hissetti yüreğim

Karanlık ve yalnızlık arkadaşım oldu.

Oysa onları hiç sevmezdim,

Hep ırak tutmuştum kendimden,

Öyle ki,beni kucaklayan, hep onlar oldu.

Mutsuz bir insan çehresiydi çehrem

Bakışlarım bomboş,beynim karmakarışıktı.

Güvendiklerim,sevgilim,yârenim kayboldu

Yitik zamanlardı geride kalan

Ve bir türlü bulamadığım.

Kaç kez sorguladım kendimi kimbilir

Yanlışı yapan ben miydim yoksa sen mi? 

İlk kez karşılaştım çözümü zor bulmacayla

Boşlukları doldurdum,yine de boş kaldı,

Neydi arayıp da bulamadığım? 

Yitik zamanlarda kaç kez aradım seni,

Oysa her saatte,her dakikada sen vardın.

Şimdi bir yerlerde,geç kalanların şarkısı çalıyor

Ve sen,hep o şarkının eşliğinde-melankolik bir tarzda-

Bir kadeh,bir kadeh daha içmenin mutluluğunu yaşıyorsun

Sen içtikçe sarhoş,

Ben içmeden sarhoş oluyorum.

Bir yerlerde ya da zamanın birinde

Ayrılacak yollarımız.

Biliyorum,ayrılmanın korkusu değil yaşadığım,

Yalnızlığın,karanlığın korkusu hiç değil,

Ben onları zaten dost edindim.

Ama inan ki sevgilim,her son,bir ilk''i getirir

Her ilk''in ardından yaşanan nedir? 

Belirsizlik beni huzursuz eden

Her belirsizlik içinde senin varlığın...

Kimbilir,belki bir yerlerde

Ya da zamanın birinde

Ayrılacak yollarımız.

Sana söyleyecek tek bir söz kalacak,

Dudaklarım mırıldanacak,

''Hoşçakal aşkım,

Yolun açık olsun! ''

 (2004,Bursa)', 'Kaç gecenin ağırlığını hissetti yüreğim Karanlık ve yalnızlık arkadaşım oldu. Oysa onları hiç sevmezdim, Hep ırak tutmuştum kendimden, Öyle ...', ARRAY['Türk Edebiyatı','Şiir','Serap Tepedelen']::text[], 8.5, '{"poet":"Serap Tepedelen","poet_slug":"serap-tepedelen","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/yitik-zamanlar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gibi', 'gibi-ozdemir-asaf-hees7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'GİBİ

Sözlüklerde aradım, yorgun, yıpranmış sözü; 

Zıtlarla benzerleri koynunda barındıran..

Tüm öbür sözcüklerle eş-anlam’lı: GİBİ’ydi.

Alıştığından kolay-benzetme’lere, gözü

(Komşusuna nur-topu bir oğlan kazandıran) 

Komşusunun karısında delikanlı gibiydi.', 'GİBİ Sözlüklerde aradım, yorgun, yıpranmış sözü;  Zıtlarla benzerleri koynunda barındıran.. Tüm öbür sözcüklerle eş-anlam’lı: GİBİ’ydi. Alış...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/gibi-64-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şey', 'sey-ozdemir-asaf-b4mnk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ŞEY

Bir gün sözlüğü açtım, ŞEY nedir diye baktım; 

Gördüm filozoflarla düşüp-kalkan bir kadın.

Ardından dediler ki sonra okuduklarım:

Bugün duruşması var ağır-ceza’da onun; 

- O, kimseye yaar-olmaz, ama inanma sakın -

Sığınmış, yatağında uyuyorken, dostunun

Ortağıyla, bir-olup, dostunu vuran kadın.', 'ŞEY Bir gün sözlüğü açtım, ŞEY nedir diye baktım;  Gördüm filozoflarla düşüp-kalkan bir kadın. Ardından dediler ki sonra okuduklarım: Bugün ...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sey-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Roman', 'roman-ozdemir-asaf-otgpi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ROMAN

Roman bir adamın adıdır.

Bir başka ada bakan,

Duysan-duymasan

Seni anmalıdır.

Roman bir adın yaşamıdır,

Başkalarınca da yaşayan; 

Okusan-okumasan

Sana uzanmalıdır.

Roman bir yaşamın anlamıdır,

Düşünmeden varılmayan; 

Anlasan-anlamasan

Sana bulanmalıdır.

Roman bir anlamın dağıdır,

Yarasız çıkılmayan; 

Korksan-korkmasan

Seni kuşanmalıdır.

Roman bir dilin dumanıdır,

Tüter evren sobasından; 

Üşüsen-ısınsan

Sönmeden yanmalıdır.', 'ROMAN Roman bir adamın adıdır. Bir başka ada bakan, Duysan-duymasan Seni anmalıdır. Roman bir adın yaşamıdır, Başkalarınca da yaşayan;  Okus...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/roman-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tam-Tam', 'tam-tam-ozdemir-asaf-jybm2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'TAM-TAM

Dördü ikiye bölenler

İki iki elde ederler.

Alırlar ikinin birini,

Öbürünü bırakıp bana

Nerelere giderler.

Üçü üçe bölenler

Üç bir elde ederler.

Üçlerden bir üç’den; 

Alırlar da üçün birini,

Neler düşünürler.

İkiyi ikiye bölenler

İki bir elde ederler.

Hangisidir bir tek,

Öbür bir buna ne der,

Neden belirlemezler.

Biri ikiye bölenler,

Beni sana bölerler,

Seni bana bölerler,

Aşkı sevgiye tam-tam,

Pay-pay bizi bize bölerler.', 'TAM-TAM Dördü ikiye bölenler İki iki elde ederler. Alırlar ikinin birini, Öbürünü bırakıp bana Nerelere giderler. Üçü üçe bölenler Üç bir el...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/tam-tam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belkide', 'belkide-sair-rusenali-inhv3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'aslında.., evet aslında neler veriyoruz bu hayata...

nefes veriyoruz, an veriyoruz, can veriyoruz

ama durup da bir baktığında siliniveriyoruz, yüzümüzden düşen bakışlarla,

hassas, isyankar, ne de masum adamlarız,

anlayanımız yok, anlaşanımız yok, 

mahkumuz işte zaman prangasına,

ayağımız elimiz nereye bağlı belli midir ki fersahlar aşalım,

gönül ister, göz görmez eksiği gediği

yaşamak var serde öyle ya da böyle işte

18 mart 06''', 'aslında.., evet aslında neler veriyoruz bu hayata... nefes veriyoruz, an veriyoruz, can veriyoruz ama durup da bir baktığında siliniveriyoru...', ARRAY['Türk Edebiyatı','Şiir','Şair Ruşenali']::text[], 8.5, '{"poet":"Şair Ruşenali","poet_slug":"sair-rusenali","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/belkide-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm', 'olum-ozdemir-asaf-wwdgt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ÖLÜM

Ölüm; ben onu çiçeklerle giderken gördüm.

Ölüm; ben onu yaşamları bilerken gördüm.

Obur doymazlıkların obur açlıklarında,

Ölüm; ben onu, varlıkları silerken gördüm.

Ama bir de yokluğun ve yüreğin önünde; 

Ölüm; ben seni utanç ile titrerken gördüm.', 'ÖLÜM Ölüm; ben onu çiçeklerle giderken gördüm. Ölüm; ben onu yaşamları bilerken gördüm. Obur doymazlıkların obur açlıklarında, Ölüm; ben onu...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/olum-281-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'AB ooo! ! (sokamazsınız bizi yılanlar sizi)', 'ab-ooo-sokamazsiniz-bizi-yilanlar-sizi-ahmetnecat-ucur-jjm1g', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Avrupa’nın birliği Avrupa’nın

Dibi delindi artık o kupanın

Hep istediğimi olsun papanın

Var mı kârı domuzdan kıl kapanın

Kim der size içinize kapanın

Neler var sanki içinde kapanın

Gerekir durmak dışında kapanın

Yok mu sanki senin de çok kapanın

Vardır ki bir düşündüğü papanın

Hele üyeliğe aday yapanın

Ver külahı al takkeyi kapanın

Farkı yok mu çapa ile sapanın

Deliğe yararı mı var tapanın 

Paslanması olmaz mı kör tapanın

Tapılmayacak yere hep tapanın

Gölgesi miyiz biz puta tapanın

Kalmasın yanına kâr suç yapanın

Olmaz mı kârı bizi üye yapanın

Tadı aynı mıdır pilavla lapanın

Ayıbı var bize ayıp yapanın

Yoksa taşların, lastikle sapanın

Olur mu faydası sana sapanın

Doyulmaz seyrine cici sıpanın

Peşinden gidilmez, Hak''tan sapanın

Dağıtılırken akıllar, kapanın

Sermayesi olmayalım kapanın

Bir değil ki bin bir çeşit kapanın

Niye girelim içine kapanın

Utanmak varken utanıp utanın

Maskarası olmayın Avrupa’nın

Kalacak mı üyesi Avrupa’nın

Koşmayalım peşinden Avrupa’nın

Yakındır yalvarması Avrupa’nın

Yalandır yakarması Avrupa’nın

Kurtludur makarnası Avrupa’nın

Kırıktır makarası Avrupa’nın

Ne  var elinde Avrupa’nın 

Üç papazla, iki kız Avrupa’nın

Kağıt istemez eli Avrupa’nın

Ful as okur canına Avrupa’nın

Var mı ki farkı bizden Avrupa’nın

Mühim olan TÜRKİYE, Avrupa’nın

Bitmez çakallıkları Avrupa’nın

Kapanına girmeyelim Avrupa’nın

                                                             Çanakkale zaferi münasebetiyle...', 'Avrupa’nın birliği Avrupa’nın Dibi delindi artık o kupanın Hep istediğimi olsun papanın Var mı kârı domuzdan kıl kapanın Kim der size içiniz...', ARRAY['Türk Edebiyatı','Şiir','Ahmetnecat Ucur']::text[], 8.5, '{"poet":"Ahmetnecat Ucur","poet_slug":"ahmetnecat-ucur","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/ab-ooo-sokamazsiniz-bizi-yilanlar-sizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gakkoşlar', 'gakkoslar-levent-ozgec-bjgwx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '- - - - GAKKOŞLAR - - - -

Gakkoşlar halayda hep başı çeker

Geriye kalınca AR gelir ona! 

Yiğitler terini serinde döker

Kırağı çalınca HAR gelir ona! 

*                     *                       *

Derin olur suyu hazar gölünün

Keban''da çözülür bütün kördüğüm

Çayda çıra derler bak bu gördüğün

Klarnet duyunca YAR gelir ona! 

*                      *                      *

Gakkoşun mekanı Harput''a bakar

Buzluk bağlarıyla gönlünü yakar

Bu güneş ilk defa doğudan batar

Gurbete varınca DAR gelir ona! 

Gurbete varınca DAR gelir ona..! 

                                  M. Levent ÖZGEÇ

                            Gönül Pınarı Kitabından', '- - - - GAKKOŞLAR - - - - Gakkoşlar halayda hep başı çeker Geriye kalınca AR gelir ona!  Yiğitler terini serinde döker Kırağı çalınca HAR ge...', ARRAY['Türk Edebiyatı','Şiir','Levent Özgeç']::text[], 8.5, '{"poet":"Levent Özgeç","poet_slug":"levent-ozgec","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gakkoslar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Bana Bak Yazamadıklarım Gözlerimde', 'sen-bana-bak-yazamadiklarim-gozlerimde-zeliha-bicer-rlbw0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben sana bakıyorum, sen yazdıklarıma

Ben seni dinliyorum yazdıklarında

Sen beni dinliyorsun yazamadıklarımda

Yazamadıklarım yaşadıklarım

Dilimin ucunda biriktirdiklerim

Sen bana bak, yaşamadıklarım gözlerimde.

Kalemim yazmış kendince yüreğimde

Yüeğimdeki sen e

Kurutmuş oymuş 

Kurtulmuş sonra hasretlerden

Onca izlerden yazılanlar

Sen bana bak, yazamadıklarım gözlerimde', 'Ben sana bakıyorum, sen yazdıklarıma Ben seni dinliyorum yazdıklarında Sen beni dinliyorsun yazamadıklarımda Yazamadıklarım yaşadıklarım Dil...', ARRAY['Türk Edebiyatı','Şiir','Zeliha Bicer']::text[], 8.5, '{"poet":"Zeliha Bicer","poet_slug":"zeliha-bicer","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sen-bana-bak-yazamadiklarim-gozlerimde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayrak', 'bayrak-mehmet-ali-cetin-4fzu6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni göklerden seçtik

Nazar değmesin diye

Seni göndere çektik

Başlar dik dursun diye

Şehadet şerbeti içtik

Eller değmesin diye

Senin altına girdik

Devlet bir olsun diye

Ay ve yıldızın beyazı

Ve üstündeki kan kırmızı

Al kanımızı renginin alına

Dosta düşmana söyle 

Türk milleti baş koymuş 

Bir yıldızın yoluna', 'Seni göklerden seçtik Nazar değmesin diye Seni göndere çektik Başlar dik dursun diye Şehadet şerbeti içtik Eller değmesin diye Senin altına ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Çetin']::text[], 8.5, '{"poet":"Mehmet Ali Çetin","poet_slug":"mehmet-ali-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bayrak-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ankara Yağmurlu', 'ankara-yagmurlu-arzu-bagriacik-8amxi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne garip: Dün çok yakınındaydım. 

Gelmedim; cesaretim yoktu. 

Sıradan bir gün geçirecektim, 

Bu defa sensiz olacaktım. 

Başaramadım. 

Her ne kadar başaramasam da 

Seni, tüm varlığınla yaşasam da 

Gelmedim 

Bir adım ötede olsan da... 

Metrelerce tel örgü vardı aramızda 

(Açık hava hapishanesi gibi) 

Eski sıcaklığınla, 

Sarılır mıydın acaba? 

Bugün Ankara yağmurlu; ben gibi... 

Kasvetli bir hava. 

Suçluyum biliyorum. 

Nedenim yok. 

Başaramadım, gelemedim, 

İçimdeki yaşları, 

Bugün Ankara anlatıyor sana. 

Kana kana göz yaşlarımı içiyor. 

Üzerindeki toprak... 

Ankara', 'Ne garip: Dün çok yakınındaydım.  Gelmedim; cesaretim yoktu.  Sıradan bir gün geçirecektim,  Bu defa sensiz olacaktım.  Başaramadım.  Her ne...', ARRAY['Türk Edebiyatı','Şiir','Arzu Bağrıaçık']::text[], 8.5, '{"poet":"Arzu Bağrıaçık","poet_slug":"arzu-bagriacik","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ankara-yagmurlu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '1 Anlar', '1-anlar-arzu-bagriacik-7m9l4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tan seyrinde. 

Adımlar yavaş, 

Nefes yakmalı. 

Ciğer parça, 

Mekan aynı. 

Savrulan ben; 

Derbeder.. 

Ankara', 'Tan seyrinde.  Adımlar yavaş,  Nefes yakmalı.  Ciğer parça,  Mekan aynı.  Savrulan ben;  Derbeder..  Ankara...', ARRAY['Türk Edebiyatı','Şiir','Arzu Bağrıaçık']::text[], 8.5, '{"poet":"Arzu Bağrıaçık","poet_slug":"arzu-bagriacik","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/1-anlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yolluk', 'yolluk-mehmet-orhan-sahin-eeibs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'zordur yolda yürümek tek başına 

yoldan anlayan birini ararsın yanına

tam buldum derken

yol dolaşır ayağına...', 'zordur yolda yürümek tek başına  yoldan anlayan birini ararsın yanına tam buldum derken yol dolaşır ayağına......', ARRAY['Türk Edebiyatı','Şiir','Mehmet Orhan Şahin']::text[], 8.5, '{"poet":"Mehmet Orhan Şahin","poet_slug":"mehmet-orhan-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yolluk-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlar 1', 'anlar-1-arzu-bagriacik-7fupe', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Loş,boş odam 

Elimde sigaram. 

Nefessiz takıldığım yalnızlığım. 

Vücudumdaki ağrılarım, 

Gözlerimdeki nem. 

Anlar,anılar. 

Gidiyorsun; kanar yüreğim 

Kal diyemem. 

Sende bende misin? 

2001 Ankara', 'Loş,boş odam  Elimde sigaram.  Nefessiz takıldığım yalnızlığım.  Vücudumdaki ağrılarım,  Gözlerimdeki nem.  Anlar,anılar.  Gidiyorsun; kanar...', ARRAY['Türk Edebiyatı','Şiir','Arzu Bağrıaçık']::text[], 8.5, '{"poet":"Arzu Bağrıaçık","poet_slug":"arzu-bagriacik","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/anlar-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlayamadım', 'anlayamadim-arzu-bagriacik-fhu92', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aniden aynaya koştum 

Yüzüme dokundum dokundum 

Farklıydı sanki! 

Ne vardı? 

Hiç anlayamayacağım… 

2002 Ankara', 'Aniden aynaya koştum  Yüzüme dokundum dokundum  Farklıydı sanki!  Ne vardı?  Hiç anlayamayacağım…  2002 Ankara...', ARRAY['Türk Edebiyatı','Şiir','Arzu Bağrıaçık']::text[], 8.5, '{"poet":"Arzu Bağrıaçık","poet_slug":"arzu-bagriacik","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/anlayamadim-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '1 Ardından', '1-ardindan-arzu-bagriacik-vegt5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Derviş misali… 

