INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rubai 5 (dilek)', 'rubai-5-dilek-murat-daglibeg-r9ub6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Parça parça olmuş milletim

Netsin bundan gayrı bileğim

Kan ağlasa çelik yüreğim

Mevla’m Kadirden tek dileğim

Özgürlüktür, özgürlük…     

sivas  2000', 'Parça parça olmuş milletim Netsin bundan gayrı bileğim Kan ağlasa çelik yüreğim Mevla’m Kadirden tek dileğim Özgürlüktür, özgürlük…      siv...', ARRAY['Türk Edebiyatı','Şiir','Murat Dağlıbeg']::text[], 8.5, '{"poet":"Murat Dağlıbeg","poet_slug":"murat-daglibeg","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/rubai-5-dilek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rubai 34', 'rubai-34-murat-daglibeg-ffgt8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Zulmü reddettiğim günden beri 

