INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Günün Hikayesi', 'bir-gunun-hikayesi-tevfik-yasar-tekeli-u79gg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir günüm daha bitti,  bitmeyen hayallerle

Avundu deli gönlüm, avundum sandı yine.

Bir seraba yapışıp ummana yelken açtı,

Aldattım deyip coştu, aldandı kandı yine...

Nice engeller aştı, nice yerler dolaştı

Kendi yaptı tasviri yine kendi ağlaştı.

Çok belayı def edip pek çoğuyla uğraştı

Sonunda yorgun düşüp uyudu daldı yine..', 'Bir günüm daha bitti,  bitmeyen hayallerle Avundu deli gönlüm, avundum sandı yine. Bir seraba yapışıp ummana yelken açtı, Aldattım deyip coş...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Yaşar Tekeli']::text[], 8.5, '{"poet":"Tevfik Yaşar Tekeli","poet_slug":"tevfik-yasar-tekeli","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bir-gunun-hikayesi-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'An 2', 'an-2-i-rfan-sari-2-lliam', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'AN - 2

güneş kopup geliyordu

yerinden

üstüme doğru...

Qertinıs ağzındaki tepedeyim

Navser sızağı

az ötesinde 

Yaşlı söğüdün. 

çıplak gözle bakıyorum

Kerpıle.

bir davul sesi 

kulaklarıma çarpıyor..

ana dilimle 

bir halı serili ovaya

ceviz kabuğunun

yeşili

fışkırmış toprağın

rahminden

sarı sarı

al al

dökülmüş derenin ağzına 

kır çiçekleri

birinci dublesinde

rakının

Cilonun karları başlıyor

kanatlanmaya 

gözlerime doğru 

ve dondurmacı dayı

düşüyor aklıma 

.........Türktü bilirsiniz! .

şimalden kesme kesme

kar getirirdi

boynuzsuz keçinin 

sütüyle

eviştirirdi bir yatakta 

yavruları

dondurma olurdu 

dolgun

...........cılız

................yumuk

....................... kıvrık

.............................dudaklara..

sonra 

ramazan sofraları

hafızamı

yakaladı

“Allah-u ekber”

ile 

saldırırdık

buz gibi suya

ardından

hurma

.........dolma

..............lahmacun

.................... çörek

.........................börek

.............................ve daha niceleri..

gün batarken 

jeneratör sesi

ışıktan

evvel girerdi 

evlerimizden içeri

el fenerine 

ıraktan sipariş ederdik

pili

gaz lambası için 

neft kuyruklarında yorulurdu

ayaklarımız

ve boşa giderdi

bütün masum dualarımız

..........bunları düşlerken

..........akşam

..........çöküyordu üstüme 

..........gömleğimin cebinde

..........kalmıştı ciğerparem

..........ve cep telefonumdan

...........yükseldi

..........‘allı turnam’

.................ben inerken ovaya 		

.............................''hoynarı''

..................................eşliğinde...

	

irfan sari

Kerténés

01 06 2005', 'AN - 2 güneş kopup geliyordu yerinden üstüme doğru... Qertinıs ağzındaki tepedeyim Navser sızağı az ötesinde  Yaşlı söğüdün.  çıplak gözle b...', ARRAY['Türk Edebiyatı','Şiir','İrfan Sari 2']::text[], 8.5, '{"poet":"İrfan Sari 2","poet_slug":"i-rfan-sari-2","theme":"Türk Şiiri","is_hero":false,"total_lines":84,"source_url":"https://www.antoloji.com/an-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şaşkın Doğa', 'saskin-doga-aytac-varol-qg238', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tavşan ile Kartal misali

Tanıdık birbirimizi

Gözleri zayıf

Kanadı kırık

Bir kartal gibi çığlıklar savurursun

Pusunmuş yuvanda

Yalçın kayalarda otlayan

Yurtsuz bir tavşan gibiyim

Ne senin beni avlamaya dermanın var

Ne de benim kaçmaya niyetim.

(1995)', 'Tavşan ile Kartal misali Tanıdık birbirimizi Gözleri zayıf Kanadı kırık Bir kartal gibi çığlıklar savurursun Pusunmuş yuvanda Yalçın kayalar...', ARRAY['Türk Edebiyatı','Şiir','Aytaç Varol']::text[], 8.5, '{"poet":"Aytaç Varol","poet_slug":"aytac-varol","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/saskin-doga-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '15Miniklerİçin:Baraj Kardeşe Şiir', '15minikleri-cin-baraj-kardese-siir-ahmet-yozgat-18bjf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '1/:

Birleşti,

Binlerce çeşme,

Ve kaynak ki on binlerce...

2/:

Uzun kulaklı bir tavşan gibi,

Seke seke başı karlı dağlardan,

Yarık dudaklı vadilerden tay gibi,

Akıp deli dolu bir hızla,

Baraja ulaştılar.

3/:

Bir araya toplaştılar,

Kalabalıklaştılar,

Kapaklardan taştılar.

4/:

Döndürüp pervaneleri,

İpil ipil elektrik oldular,

Çevremize ışık saçtılar,

Görevlerini bitiren sular,

Sakince uzaklaştılar...

5/:

Bakakaldık arkalarından biz,

Sanırım gerekir size,

Teşekkür etmemiz...', '1/: Birleşti, Binlerce çeşme, Ve kaynak ki on binlerce... 2/: Uzun kulaklı bir tavşan gibi, Seke seke başı karlı dağlardan, Yarık dudaklı va...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/15miniklericin-baraj-kardese-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Seferki Diğerleri Gibi Olmadı', 'bu-seferki-digerleri-gibi-olmadi-baris-sargin-2eltb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hani her zaman evden arkana bakmadan çıkarsınya

Nasıl olsa geri döneceğini bilerek

Bu seferki öyle değildi; 

Bu seferki uzun ve dönüşü çok sonraya bırakılmış bir çıkıştı

EVDEN

Hep derler ya eve erken gel diye çıkmadan önce

Bu seferki öyle değildi; 

Bu seferki insanın içini cız ettirecek şekildeydi

''Kendine iyi bak. Akıllı ol oğlumdu''', 'Hani her zaman evden arkana bakmadan çıkarsınya Nasıl olsa geri döneceğini bilerek Bu seferki öyle değildi;  Bu seferki uzun ve dönüşü çok s...', ARRAY['Türk Edebiyatı','Şiir','Barış Sargın']::text[], 8.5, '{"poet":"Barış Sargın","poet_slug":"baris-sargin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bu-seferki-digerleri-gibi-olmadi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağrıyor', 'agriyor-erdal-akkoyun-56wpg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İçim ağrıyor

inceden ve derinden

Canım yanıyor

Hiçbir ilaç para etmiyor

Ne yaptıysam geçmedi

Bu beni kahrediyor

Elimden birşey gelmiyor, ne yapayım

Vazgeçtim artık uğraşmayayım

En iyisi, kalkıp biraz dolaşayım', 'İçim ağrıyor inceden ve derinden Canım yanıyor Hiçbir ilaç para etmiyor Ne yaptıysam geçmedi Bu beni kahrediyor Elimden birşey gelmiyor, ne ...', ARRAY['Türk Edebiyatı','Şiir','Erdal Akkoyun']::text[], 8.5, '{"poet":"Erdal Akkoyun","poet_slug":"erdal-akkoyun","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/agriyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sohbet Eylesem..', 'sohbet-eylesem-nurdane-diken-f295a', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çıksam şu dağlara seyran eylesem

Yâr ile oturup sohbet eylesem.

Aşk tüten sözleri ona söylesem

Yâr ile oturup sohbet eylesem.

Bal olur dilinde şeker sözünde

Aşk yazar, aşk tüter sevgi gözünde

Dost''luklar bâkidir yaşar özünde

Yâr ile oturup sohbet eylesem.

Yâr elinden içmiş coşmuş deliyim

Çağlayarak akan aşkın seliyim

Muhabbetin sözün akan balıyım

Yâr ile oturup sohbet eylesem.

Kartal gibi yüksek yüksek uçarsın

Beni görmeden de gelip geçersin

Yolunu çevirip neden kaçarsın? 

Yâr ile oturup sohbet eylesem.

Ben bir bezirganım dost''luk satarım

Huzuru bulurum derdi atarım

Yalanı yutarım sözü tutarım

Yâr ile oturup sohbet eylesem.

Dost''la sohbetlere söze doyulmaz

Her sözü bilen de söze koyulmaz

Her dostum diyen de dostun sayılmaz

Yâr ile oturup sohbet eylesem....

01.03.06- 20.20- İst....', 'Çıksam şu dağlara seyran eylesem Yâr ile oturup sohbet eylesem. Aşk tüten sözleri ona söylesem Yâr ile oturup sohbet eylesem. Bal olur dilin...', ARRAY['Türk Edebiyatı','Şiir','Nurdane Diken']::text[], 8.5, '{"poet":"Nurdane Diken","poet_slug":"nurdane-diken","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sohbet-eylesem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '15Miniklerİçin:Doru Atım', '15minikleri-cin-doru-atim-ahmet-yozgat-34ois', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1/:

Ben küçük bir çiftçiyim...

Size uzak bir köydeyim.

Bir doru atım,

Bir de toprak evim,

Bütün servetim...

Ha unutmadan söyleyeyim,

Bir de küçük tarlam var,

Avuç içi kadar...

2/:

Ben küçük bir çiftçiyim...

Yılkıdan döner,

Doru atım yağan karla.

Bölüp bir büyük odayı,

Ortadan kalaslarla,

Kışı birlikte geçiririz,

Sıcacık odamda doru atımla...

3/:

Ben küçük bir çiftçiyim,

Yani sizin gibiyim...', '1/: Ben küçük bir çiftçiyim... Size uzak bir köydeyim. Bir doru atım, Bir de toprak evim, Bütün servetim... Ha unutmadan söyleyeyim, Bir de ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/15miniklericin-doru-atim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazdırmıyor', 'yazdirmiyor-mikdat-bal-43tj5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çok şeyler var yazılacak

Elim bana yazdırmıyor

Ne kafalar bozulacak

İlim bana yazdırmıyor

Çok insan var değil kerim

Yazmazsam ben ne ederim

Numaradan bilmem derim

Alim bana yazdırmıyor

Her şey bozuk her şey beter

Kargalar her yerde öter

Sert sert bakar tehdit eder

Zalim bana yazdırmıyor

Kalmadı da eski hızım

Hastayım hem rahatsızım

Son zamanlar arttı sızım

Halim bana yazdırmıyor

Gördüğüme kanım kurur

Devran böyle kervan yürür

İşine bak deyip durur

Delim bana yazdırmıyor

Mikdatî der söz oluyor

Nefis şeytan çözülüyor

Öyle kafam bozuluyor

Ölüm bana yazdırmıyor', 'Çok şeyler var yazılacak Elim bana yazdırmıyor Ne kafalar bozulacak İlim bana yazdırmıyor Çok insan var değil kerim Yazmazsam ben ne ederim ...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yazdirmiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '15Miniklerİçin:Türkan Abla', '15minikleri-cin-turkan-abla-ahmet-yozgat-wuov5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '1/:

Şu bizim Türkan abla,

Süpürür her sabah,

Mavi boyalı evinin önünü,

Temiz olsun diye sokaklar...

1a/:

Ya sizin de Türkan ablanız var mı? 

Varsa her sabah o neler yapar? 

1/:

Şu bizim Zeynep abla,

Çıkar her sabah,

Mavi boyalı camına,

Selamlasın diye insanlar...

2a/:

Ya sizin de Zeynep ablanız var mı? 

Varsa her sabah o neler yapar? 

1/:

Şu bizim Kiraz abla,

Dağıtır her sabah,

Rengarenk şekerler,

Sevinsin diye çocuklar...

3a/:

Ya sizin de Kiraz ablanız var mı? 

Varsa her sabah o neler yapar?', '1/: Şu bizim Türkan abla, Süpürür her sabah, Mavi boyalı evinin önünü, Temiz olsun diye sokaklar... 1a/: Ya sizin de Türkan ablanız var mı? ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/15miniklericin-turkan-abla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '15Miniklerİçin:Al Beni Uzay Amca', '15minikleri-cin-al-beni-uzay-amca-ahmet-yozgat-oblzr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '1/:

Yıldız yıldız gözleriyle,

Her gece tam saat onda,

Evimi gözetleyen uzay amca...

Beni de,

Bir yıldız say,

Koy göğün en uzak ucuna.

2/:

Güneşle gülümse bana,

Ay dede ile el salla,

Bu gece gel yanıma.

3/:

Yıldız yıldız gözleriyle,

Her gece tam saat on on ikide,

Penceremi gözetleyen uzay amca...

Beni de,

Al koynuna...

Kardeş eyle,

Binlerce yıldızınla.

4/:

Güneşinle gülümse,

Ay dede ile el salla,

Bu gece gir rüyama.', '1/: Yıldız yıldız gözleriyle, Her gece tam saat onda, Evimi gözetleyen uzay amca... Beni de, Bir yıldız say, Koy göğün en uzak ucuna. 2/: Gü...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/15miniklericin-al-beni-uzay-amca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bakışların', 'bakislarin-baris-sargin-rsn76', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözlerime baktığın o anı hiç unutmam

Bendeki külleri tekrar hayata geçiren 

O sıcak bakış

Şimdilerde hep seni arıyor gözlerim

Bu alev gene sensiz sönmekte 

Yanında olmama ve

Gözlerinde

Son bulmama izin ver', 'Gözlerime baktığın o anı hiç unutmam Bendeki külleri tekrar hayata geçiren  O sıcak bakış Şimdilerde hep seni arıyor gözlerim Bu alev gene s...', ARRAY['Türk Edebiyatı','Şiir','Barış Sargın']::text[], 8.5, '{"poet":"Barış Sargın","poet_slug":"baris-sargin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bakislarin-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm Sevdayı bitirmiyor', 'olum-sevdayi-bitirmiyor-aytac-varol-e3x79', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sarı sarı gül bana

dudağının kırmızısını unutalı çok oldu

sararmış yapraklarla ört üstümü

baharı beklemeden gel bana; 

sana dokunamadığım yılların hasretini

mezartaşımdaki adımın yanına yazmasınlar

yanak yanak gül bana

gamzelerinde kaybolduğum derinliği unuttum

yakılmış sevda mektuplarının külüyle ört üstümü

cevabımı beklemeden gel bana; 

sana bir daha yazamayacağım sevda sözlerini

teninin kokusunda toprağıma kazıyasın

çocuk çocuk gül bana

saçlarını savurup rüzgara

kollarımın arasına süzülüşünü özlüyorum

çorak topraklardan beter 

kısır yıllarımla ört üstümü

seviştiğin gecelerde gel bana; 

tenimde bir daha tadamayacağım diş izini

ısırdığın yemişin çekirdeğinde başucuma ekersin

özle özle gül bana

kavuştuğumuz ayrılıkların ilk anında

gözlerimizdeki parıltıyı hatırlarım

üzüntülerinin nedeni olduğum anılarla ört üstümü

daha çok güldüğün günler gel bana; 

etime kanıma hayat veren sesini

çürüyen kulaklarımla işittiğimi duyarsın

ölüm sevdayı bitirmiyor gülüm

etler, kemikler çürüyor toprağın altında

üstünde; 

sevişmeler, hasretler

ve sevda şiirleri yeniden yeşeriyor

doğan her yeni günde

sevda soluk alıp veriyor toprağın üstünde

yaşıyor yaşayan herşeyde.', 'sarı sarı gül bana dudağının kırmızısını unutalı çok oldu sararmış yapraklarla ört üstümü baharı beklemeden gel bana;  sana dokunamadığım yı...', ARRAY['Türk Edebiyatı','Şiir','Aytaç Varol']::text[], 8.5, '{"poet":"Aytaç Varol","poet_slug":"aytac-varol","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/olum-sevdayi-bitirmiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '15Miniklerİçin:Yeşilim Yeşil', '15minikleri-cin-yesilim-yesil-ahmet-yozgat-60ea0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '1/:

Yeşil kınasıyım dünyanın...

***

Gelince aylardan nisan,

Önce ovaları boyarım,

Sonra dağları...

Hani kına yakar ya,

Minik ellere analar,

Ardından gelir ya bayram...

2/:

Kınasıyım ben de dünyanın...

***

Gelince aylardan mayıs,

Önce ağaçları boyarım,

Sonra ormanları...

Gelir ardımdan,

Bayram gibi ilkbahar...', '1/: Yeşil kınasıyım dünyanın... *** Gelince aylardan nisan, Önce ovaları boyarım, Sonra dağları... Hani kına yakar ya, Minik ellere analar, ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/15miniklericin-yesilim-yesil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '15Miniklerİçin:Ufkumda Gezinen Tren...', '15minikleri-cin-ufkumda-gezinen-tren-ahmet-yozgat-fk2cv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1/:

Ufkumda gezinen tren...

Asıl frenlerine,

Dur göz bebeğimde.

1/:

Ufkumda gezinen tren...

Al beni lokomotifine,

Gezdir rüya ülkelerinde.

1/:

Ufkumda gezinen tren...

Sarkmam camından dışarı,

Korkma benden yana.

Asılmam gereksiz yere. 

Boyum zaten zor yetişir,

Frenlerine.

1/:

Ufkumda gezinen tren...

Merak etme ne olur? 

Kefilim her şeyime.', '1/: Ufkumda gezinen tren... Asıl frenlerine, Dur göz bebeğimde. 1/: Ufkumda gezinen tren... Al beni lokomotifine, Gezdir rüya ülkelerinde. 1...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/15miniklericin-ufkumda-gezinen-tren-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '15Miniklerİçin:Penceremin Demiri', '15minikleri-cin-penceremin-demiri-ahmet-yozgat-ndt22', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '1/:

Çizme dünyamı,

Penceremin demiri.

Ayırma kutu kutu,

Muhteşem manzaramı...

Güneşi bölme ortadan,

Ay dedeyi ayırma dörde,

Her kutuya bir yıldız yerleştirme.

2/:

Parçalama dünyamı,

Penceremin demiri.

Ayırma kutu kutu,

Muhteşem manzaramı...

Bırak koruma,

Hırsızlardan odamı...', '1/: Çizme dünyamı, Penceremin demiri. Ayırma kutu kutu, Muhteşem manzaramı... Güneşi bölme ortadan, Ay dedeyi ayırma dörde, Her kutuya bir y...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/15miniklericin-penceremin-demiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '15Miniklerİçin:Gazeteci Ağabeyler', '15minikleri-cin-gazeteci-agabeyler-ahmet-yozgat-vu9zz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '1/:

Gazeteci ağabeyler,

Yusyuvarlak bakarlar dünyaya,

Objektiflerinden makinelerinin.

2/:

Kare kare savaş görürler,

Kan görürler kutu kutu...

Gazeteci ağabeyler,

Her yanı haber görürler...

3/:

Gazeteci ağabeyler,

Dolaşırlar dünyayı,

Hiç istemeseler de,

Kare kare olay bulurlar,

Kan bulurlar kutu kutu...

Gazeteci ağabeyler,

Her yanda dertli insan bulurlar...', '1/: Gazeteci ağabeyler, Yusyuvarlak bakarlar dünyaya, Objektiflerinden makinelerinin. 2/: Kare kare savaş görürler, Kan görürler kutu kutu.....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/15miniklericin-gazeteci-agabeyler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '15Miniklerİçin:Ah Avcılar Avcılar', '15minikleri-cin-ah-avcilar-avcilar-ahmet-yozgat-pqj54', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '1/:

Ben bir küçük tilkiyim...

Sipsivri burunlu,

Ve süpürge kuyrukluyum.

2/:

Siz nasıl ki,

Severseniz keklik etini,

Yumurtasını bıldırcınların,

Ben de,

Hazzederim

Tavuğunkini...

3/:

Siz çıkarsınız ya,

Hani vadilere kelik vurmaya.

Adınız avcıya çıkar,

Ya da keskin nişancıya.

4/:

Ben de bazı geceleri,

Çıkarım tavuk avlamaya.

Adım çıkar hain tilkiye,

Ya da bir avcı tarafından vurulurum 

Adım adi hırsıza,

Canımsa göğe çıkar...', '1/: Ben bir küçük tilkiyim... Sipsivri burunlu, Ve süpürge kuyrukluyum. 2/: Siz nasıl ki, Severseniz keklik etini, Yumurtasını bıldırcınları...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/15miniklericin-ah-avcilar-avcilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '15Miniklerİçin:Silgi ile Kalem Kardeş', '15minikleri-cin-silgi-ile-kalem-kardes-ahmet-yozgat-9ojga', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '1/:

Kalemiyle yazar küçük Sabriye,

Siler lastik silgisiyle.

Ya da buna kalem yapar,

Silgi bozar da denir.

2/:

Ama silgisi ile kalemi Sabriye''nin

Ne küserler birbirlerine,

Ne de düşman olurlar.

Hatta,

İki kardeştir bunlar.

3/:

Kalem bilir ki,

Yanlış yaptığını bazen.

Silgi ise,

Doğruya dokunmayan bir dosttur,

Yalnız yanlışı bozan...', '1/: Kalemiyle yazar küçük Sabriye, Siler lastik silgisiyle. Ya da buna kalem yapar, Silgi bozar da denir. 2/: Ama silgisi ile kalemi Sabriye...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/15miniklericin-silgi-ile-kalem-kardes-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '15Miniklerİçin:Ya Takvim Yalansa', '15minikleri-cin-ya-takvim-yalansa-ahmet-yozgat-92vsc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '1/:

Bir sabah erken,

Uyandırdı beni.

Odamın duvarındaki,

Üç yüz yapraklı takvim.

2/:

''Merhaba,'' dedi usulca,

Birinci günüyle mart ayı:

''Müjde! '' dedi fısıltıyla,

''İlkbahar başladı.''

3/:

Bu güzel bir haberdi.

Görmek umudu ile,

Şeftalinin çiçeğini,

Tomurcuğuyla eriği,

Sıyırdım heyecanla perdeyi.

4/:

A aa! O da ne? 

Ne şeftalide çiçek,

Ne erikte tomurcuk...

Yollarda bata çıka yürüyen,

Onlarca üşüyen çocuk...

5/:

Yalan mı söyledi takvim acaba? 

Ya da yanıldı mı yoksa? 

Sordum anneme bu durumun nedenini.

Annem:

''Mart kapıdan baktırdı,

Yaba kürek yaktırdı.'' dedi.', '1/: Bir sabah erken, Uyandırdı beni. Odamın duvarındaki, Üç yüz yapraklı takvim. 2/: ''Merhaba,'' dedi usulca, Birinci günüyle mart ayı: ''Müjd...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/15miniklericin-ya-takvim-yalansa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ama İyi Ama İnsan', 'ama-i-yi-ama-i-nsan-omer-yasar-ozgodek-5mlzs', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hayat hakiki yeşil çam

Orada aktörlere keserler rol

Refik Ertuğrul, Ömer Kavur

Yönetirler filmleri

Bilmezler en büyük yönetmeni

Bana da kestin bir rol

Yükledin figüranlık

 Kadir İnanır, Cüneyt Arkın

Sert adamları yeşil çamın

Ama delikanlı,ama mert 

Ama iyi ama insan

Vay seni hayat

Çıkarmadın karşıma böyle  iki dost

Hep uğraştırdın beni kötü adamlarla

Keşke Bilal inci,

Erol taş gibi olsaydı onlarda

Kötü ama mert kötü ama yiğit 

Kötü ama insan

Çıkarttın karşıma hep 

Nuri Alço  Kenan Pars 

Yüze dost arkaya düşman 

Sinsimi sinsi

Haydi bunlara da razıydım

Büyük adamdı bunlar

Adamdılar 

Ya hu bir çapları vardı

Bir de… 

Mütecaviz coşkunu musallat ettin

Irzıma tasallut etti

Hayatta ortağım olmadı hiç

Kemal Sunal, İlyas Salman gibi

Şener Şen ile verdin

.Halit Akçatepe yi

Biri ‘’ağa’’ biri ‘’düdük necmi’’

Öttürüp çaldılar hep beni

Bir Hulisi Kentmen bir Kadir Savun

Bulamadım.

tutan olmadı benim elimden

Tarık akan,Kenan kalav 

Gibi de olamadım yakışıklı

Takamadım koluma bir 

Hale soygazi Gülşen  bubikoğlu

Hayatıma girmedi bir Türkan sultan

Olmadı fato

Gezip tozmakta istemezdim

Münir özkulla adile naşit gibi olsaydım mutlu

Nasıl yazıyorsun bu senaryoyu bilmem

Hem mert ediyorsun hem yoksul

Hep delikanlı,hep zayıf

Verseydin bana da 

Yılmaz Köksal gibi bir güç

Alay etseydim düşmanlarımla 

Söyleseydim son sözü

Sami hazinses’e benziyorum

Yok kimsem gidecek yuvam

Vardı yine onun Cevat Kurtuluşu

Kendisi gibi gariban 

Ama sevimli ama neşeli 

Ama iyi ama insan

Nejdet tosun gibi etmişsin beni

Neşeli güler yüzlü,ama dert babası

Gelen giden bende ağlıyor

Mahrum etmişsin benden ise bir omuzu

Senaryomda eksikti bir Neriman Köksal

Onu da verdin başıma 

Metin akpınar Zeki alasya 

Gibi bir arkadaş bulamadım

Bölemedik ekmeği 

Sallayamadık kaşığı aynı aşa

Aşkı anlatamadık birbirimize

Sarılamadık aynı yorgana

Ayarlayamadık  bir birimize iki kız	

 İdare edemedik birbirimizi işte

Bir gün bende ölecem

Ayhan Işık gibi

Musalla taşında anlayacaklar kıymetimi

Ama geç 

Koyacaklar dört kolluya 

Ağır ağır götürecekler son yolculuğuma

Görecem orada senaryomdaki dostlarımı

Bir iki damla göz yaşı akacak umarım

Resmimi koyarlar 

Tabutumun önüne belki

 Birkaç demet karanfil atsalar tamam

İstemem alkış

Gerek yok

Nutuk ise lüzumsuz

Koydular mı toprağın bağrına

Beni saracak hakikat 

Yazacaklar filmin sonuna

SON

Sadık dostum öpecek beni anlımdan

Alacak beni yaradan

Sonunda Sadri Alışık gibi 

Figüran Ömer de bulacak huzuru', 'Hayat hakiki yeşil çam Orada aktörlere keserler rol Refik Ertuğrul, Ömer Kavur Yönetirler filmleri Bilmezler en büyük yönetmeni Bana da kest...', ARRAY['Türk Edebiyatı','Şiir','Ömer Yaşar Özgödek']::text[], 8.5, '{"poet":"Ömer Yaşar Özgödek","poet_slug":"omer-yasar-ozgodek","theme":"Türk Şiiri","is_hero":false,"total_lines":95,"source_url":"https://www.antoloji.com/ama-iyi-ama-insan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağaç Misali', 'agac-misali-baris-sargin-xkzc3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ağaç gibi olmak İsterdim hep

İlk önce filizler açmayı

Sonra o güzel renklerle

Kendimi göstermeyi

Her şartta ayakta durmayı

Yıkılmadan hayata meydan okurcasına 

Her zorluğu atlatmayı

Bütün kötülüklere karşı herşeyimi kaybetsemde

Biliyorum ben tekrar filizlenip

Hayata inat bir tavırla

Her zamanki yerimde

Zorlukları bekliyiceğim.....', 'Ağaç gibi olmak İsterdim hep İlk önce filizler açmayı Sonra o güzel renklerle Kendimi göstermeyi Her şartta ayakta durmayı Yıkılmadan hayata...', ARRAY['Türk Edebiyatı','Şiir','Barış Sargın']::text[], 8.5, '{"poet":"Barış Sargın","poet_slug":"baris-sargin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/agac-misali-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '15Miniklerİçin:Küçük Bulut', '15minikleri-cin-kucuk-bulut-ahmet-yozgat-nnic5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '1/:

Küçük bulut,

Hangi tarlada yetişti? 

Ak pak pamuğun...

2/:

Hangi hallaç savurdu? 

Ufuklardan yukarı...

3/:

Küçük bulut,

Nereden bildin benim,

Güneşten yandığımı? 

4/:

Küçük bulut,

Üzerime serdin kuşlar gibi,

Gölgeli ve serin kanatlarını...', '1/: Küçük bulut, Hangi tarlada yetişti?  Ak pak pamuğun... 2/: Hangi hallaç savurdu?  Ufuklardan yukarı... 3/: Küçük bulut, Nereden bildin b...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/15miniklericin-kucuk-bulut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '15Miniklerİçin:Elim Sende', '15minikleri-cin-elim-sende-ahmet-yozgat-cpvpp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '1/:

Artık seninle,

''Elim sende'' oyunu,

Oynamak istemiyorum Kazime.

2/:

Ne zaman? 

''Elim sende'' oyunu oynasak,

Ve sen alsan elimi,

Sokakların arasında

Kaybolup gidiyorsun,

Hem de çok uzaklara...

3/:

Geride,

Seni beklerken ben,

Elsiz kalakalıyorum.

4/:

Bundan sonra seninle,

Yok bundan sonra seninle,

''Elim sende'' oyunu oynamak,

Geri dön gel de yanıma,

Oynayalım ''Elin bende'' oyunu...

Gör o zaman ne demek elsiz kalmak?', '1/: Artık seninle, ''Elim sende'' oyunu, Oynamak istemiyorum Kazime. 2/: Ne zaman?  ''Elim sende'' oyunu oynasak, Ve sen alsan elimi, Sokakların...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/15miniklericin-elim-sende-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevinçler Buz Çözer Gülüşünde', 'sevincler-buz-cozer-gulusunde-aytac-varol-7gghd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'l.

senin yüzün değil o,

sahte gülücüklerle maskelenmiş...

acemi oyunlarda sergilenen sen olamazsın

oyuncuları bitkin

ve rol yapmaktan yorgunsa gece

o gecenin dipsiz yalnızlığında

yüreğinin aynası yüzleri bulamazsın

aynı yastığa baş koyduğun

senden arınmış yalnızlığındır

selvi dalı gibi

içinin titreyip de

sıcağında avunduğun

dalgakıranın karanlık gölgesidir

bencil, dünsüz aşkların

ürkek sevgilisi

sen olmazsın.

ll.

ayışığını gelinlik gibi giyinmiş

saçından ayak tırnağına

hülyalı bir ışığa bezenmişsin

yalnızlıktan kararan gecede

aydınlık kurguların düşüsün

insanı insana düşman kılan

izi sürülmez yolların yolcusu

sen olamazsın

yüzündeki durgun suların saydamlığında

bir bir ele veriyor kendini

korkuların, edepli utangaçlığın

            -korkular ihanete bel bağlamışsa

	aldatılmanın buruk tadı

	geceden kalmışsa dilinde

	utangaçlığında

	ihanetin sanığını saklayamazsın

	bilesin! ..

oysa senin sevinçlerin 

buz çözer gülüşünde

ılık ılık

bir minik kuş gibi

dünyaları taşır dostlarının dalına

çürüyeni, kuruyanı yeniden yeşertirsin.

lll.

acılara, kahırlara açtık kapımızı

onmaz yaralar bitti yüreğimizin başında; 

'' Onu bulduk, mutluluğu bulduk ''

diyebilmek için

mutluluk; emanetçiye bırakılan

hırpani bir palto değilki

vakti zamanı gelince geri alasın.

Mutluluğu, 

anaların nasırlı ellerindeki sabrı olgunlaştırır.

yarına sevdalı yüreğin inanmışlığında yaşar mutluluk,

bir başına ayakta kalabildiğince; 

bir de

yangın yerine dönmüş yüreğin

gürül gürül çağlayan sevgilisinde.

damla damla bile verse 

gül dudağa kendini

hiç durma

kana kana iç

sorma '' gerisi nerde '' diye

deniz deniz içiyoruz birbirimizi

rüzgar rüzgar içiyoruz...

yine de

dostluğa,

bizleri yeniden yaratan

aşklara doymuyoruz.

doymuyoruz ya

insanız açlığımızda

(10.12.1993 - 03.08.1997)', 'l. senin yüzün değil o, sahte gülücüklerle maskelenmiş... acemi oyunlarda sergilenen sen olamazsın oyuncuları bitkin ve rol yapmaktan yorgun...', ARRAY['Türk Edebiyatı','Şiir','Aytaç Varol']::text[], 8.5, '{"poet":"Aytaç Varol","poet_slug":"aytac-varol","theme":"Türk Şiiri","is_hero":false,"total_lines":70,"source_url":"https://www.antoloji.com/sevincler-buz-cozer-gulusunde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '15Miniklerİçin:Yalnız Tekerlek', '15minikleri-cin-yalniz-tekerlek-ahmet-yozgat-jfptk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '1/:

Ben bir tekerleğim,

Yalnız ve kimsesiz...

Ve korkak biriyim.

2/:

Ben bir tekerleğim,

Ne zaman çıksam yola,

İlk çıktığım yeri,

Unutmayayım diye,

Ardımda uzun bir iz bırakırım.

3/:

Ben bir tekerleğim,

Kaybolursam yolda,

Takip edip izimi,

Gerisin geri,

Başladığım yere gelirim...

4/:

Buna tedbir diyor büyükler.

Ya siz ne diyorsunuz? 

Gerektiği hallerde,

Tedbir alıyor musunuz?', '1/: Ben bir tekerleğim, Yalnız ve kimsesiz... Ve korkak biriyim. 2/: Ben bir tekerleğim, Ne zaman çıksam yola, İlk çıktığım yeri, Unutmayayı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/15miniklericin-yalniz-tekerlek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalmadı', 'kalmadi-zeynal-yaman-w7a98', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çaldım zamanın demir kapısını

Başıma açılmadık iş kalmadı

Sarsmışım meğer kral yapısını

Peşime takılmadık keş kalmadı

Bari dedim bahçesinde oturam

Suyunu içip gülünü koklayam

Bizim usul bir de türkü tutturam

Başıma atılmadık taş kalmadı

Kanlarım karışmadan gözyaşına

Koşa koşa vardım çeşme başına

El vurmuş gibi musalla taşına

Su kurudu çeşmede yaş kalmadı

Arıya özenip konunca bala

Yakama yapıştı püsküllü bela

Bir güzeli sevdim gözleri ela

Baka baka bende flaş kalmadı

Hata bende diye döndüm işime

Zamaneler takıldılar peşime

Hangi günah yazılmışsa fişime

Dostlar azaldı arkadaş kalmadı

1994,Çankırı', 'Çaldım zamanın demir kapısını Başıma açılmadık iş kalmadı Sarsmışım meğer kral yapısını Peşime takılmadık keş kalmadı Bari dedim bahçesinde ...', ARRAY['Türk Edebiyatı','Şiir','Zeynal Yaman']::text[], 8.5, '{"poet":"Zeynal Yaman","poet_slug":"zeynal-yaman","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kalmadi-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Giz...', 'giz-bahri-kayaoglu-jcp15', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İğreti bir yalnızlık içinde

Solan bu çiçek örtüsü

Yeniden güvermez mi,

Yaza? 

- Güverir elbette.

Peki neden? 

Çıtım çıkmıyor.

Bildiğim halde şunu:

Yaşanan: İlkbahar ayı

Durum: İç açıcı güzellikte..

-Yok, galiba eskiyen benim

Her yenilikte...', 'İğreti bir yalnızlık içinde Solan bu çiçek örtüsü Yeniden güvermez mi, Yaza?  - Güverir elbette. Peki neden?  Çıtım çıkmıyor. Bildiğim halde...', ARRAY['Türk Edebiyatı','Şiir','Bahri Kayaoğlu']::text[], 8.5, '{"poet":"Bahri Kayaoğlu","poet_slug":"bahri-kayaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/giz-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '15Miniklerİçin:Şekeristan', '15minikleri-cin-sekeristan-ahmet-yozgat-2g4ep', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1/:

Al çocuk! 

Sana şeker getirdim.

-I-ıh! Almam.

2/:

Al çocuk! 

Sana oyuncak getirdim.

-I-ıh! Almam.

1/:

Al çocuk! 

Sana masal getirdim,

Kaf dağındaki masalistandan...

-....? ! Sağ ol canım amcam!', '1/: Al çocuk!  Sana şeker getirdim. -I-ıh! Almam. 2/: Al çocuk!  Sana oyuncak getirdim. -I-ıh! Almam. 1/: Al çocuk!  Sana masal getirdim, Ka...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/15miniklericin-sekeristan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah İstanbul!', 'ah-i-stanbul-turan-gokmenoglu-tg2cz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şimdi uzaklarda bir hayal gibi

Seni seninle anmak ne güzel

Çocukluğumdan gençliğe giden

Onyedi yaşlarımın baharındasın

İlk o çağlarda vuruldum

O çağlarımda tutundum sana

Küçücük bir valize sığışıverdi

Yoksulluk günlerimin her şeyi

Bir lise diplomam 

Bir kaç satırlık tavsiye mektubu

Okuyup adam olup

Dönecektim doğduğum yere...

İlk odam Fatih’te

Çarşamba’da Sinop Öğrenci Yurdu

Parasını zar zor denkleştirip

On yataklı bir odadayım

Gençliğimin kıpırtısı

Yuvadan uçup gelmenin hasreti

Koltuğumun altında

Bez ciltli Roma Hukuku dersleri

Açlığım tokluğum

Turan Emeksiz şehidinin yemekhanesi

Bir de Akdeniz Caddesi’nin küçük lokantası

Pazar sabahları marketten kokladığım

Tadımlık şarküteri ürünleri...

Cağaloğlu Yokuşu’nda ilk işim

Bakış Matbaası’nın kurşun harfleri

Bir yanımı sevdaların ördü

Bir yanımı uçsuz bucaksız güzelliklerin

Fatih’ten Kapalıçarşı’ya yürürdüm

Oradan Cağaloğlu Yokuşu’na

Ancak karnımı doyururdu harçlığım

Kağıt kokuları sindi içime

Tozları saçlarımı gümüşledi

Yarım gün matbaada işbaşı

Öğleden sonra okul sıraları

Böyle yürüdüm yollarını

Çocuktum

Sendin okulum...

Emirgan Korusu sevdalarımı gizler

Vapur dumanlarına sararım hasretini

Her kaldırım taşını çiğnedim

Her yaprağına dokundum yeşil yeşil

Her sabahında yeniden doğdum

Her akşamında daldım hülyalarına

Çoluk çocuğa karıştım

Hala sürmekte okulum

Hala sürmekte doğduğum yere özlemim

Hiç ayrılamayan sevdalılar gibiyiz

İkimiz....

Ah İstanbul! 

Nasıl da işlemişsin içime

Anamdan içtiğim ak süt gibisin

Her yanımı sarıp sarmalar sevgilerin

Her adım uzaklaştığımda koynundan

Ayaklarım gerisin geriye gelir

Sen unutamadığımsın

Yıllarca süren sevdamsın

Sen her şeyimsin

Nefes gibi, su gibi, hayat gibi

Ben neredeysem

Sen de içimdesin! .....

Göztepe, 17 Mart 2006', 'Şimdi uzaklarda bir hayal gibi Seni seninle anmak ne güzel Çocukluğumdan gençliğe giden Onyedi yaşlarımın baharındasın İlk o çağlarda vuruld...', ARRAY['Türk Edebiyatı','Şiir','Turan Gökmenoğlu']::text[], 8.5, '{"poet":"Turan Gökmenoğlu","poet_slug":"turan-gokmenoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":63,"source_url":"https://www.antoloji.com/ah-istanbul-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '15Miniklerİçin:Trafik Polisi Dursun Amca', '15minikleri-cin-trafik-polisi-dursun-amca-ahmet-yozgat-42qth', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '1/:

Trafik polisi Dursun bey amca,

Adın gibi öylece durursun,

Yolların ortasında.

2/:

Trafik polisi Dursun bey amca,

Yollarsın oyuncak araçlarını,

Bir o yanına kentin,

Bir bu yanına...

3/:

Trafik polisi Dursun bey amca,

Bir koşuda getirsem ben de,

Şuracıktaki evimizden...

Kendi oyuncaklarımı,

Birlikte oynasak,

Derim...

4/:

Trafik polisi Dursun bey amca,

Kıskançlık etmeden karıştırsak,

Birbirine oyuncaklarımızı...

Ha ne dersin?', '1/: Trafik polisi Dursun bey amca, Adın gibi öylece durursun, Yolların ortasında. 2/: Trafik polisi Dursun bey amca, Yollarsın oyuncak araçl...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/15miniklericin-trafik-polisi-dursun-amca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '15Miniklerİçin:Bizim Coğrafya', '15minikleri-cin-bizim-cografya-ahmet-yozgat-de5w3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '1/:

Bizim coğrafya,

Çekip dizinin dibine,

Öğretir kendimizi,

Sevine sevine bize...

2/:

Güzeller güzeli,

Bizim coğrafya...

Erciyes''in karı onda,

Ağrı''nın ilacı...

3/:

Her yanı bir başka renk,

Bizim coğrafya,

Bulamazsınız başka eşini...

Kırmızısı Kızılırmak''tan,

Yeşilırmak''ın yeşili...

4/:

Hazineler saklar bağrında,

Bizim coğrafya...

Serin serin yaylalar,

Bereketli ovalar onda...

5/:

Deniz ve su zengini

Bizim coğrafya...

Karadeniz gözünün karası,

Ak deniz akı gözlerinin,

Ege''si,

Marmara''sı...

6/:

Yan başımızda,

Bizim coğrafya...

Biz her nerede isek,

Bizim coğrafya da orada,

Hemde en baş köşede...', '1/: Bizim coğrafya, Çekip dizinin dibine, Öğretir kendimizi, Sevine sevine bize... 2/: Güzeller güzeli, Bizim coğrafya... Erciyes''in karı on...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/15miniklericin-bizim-cografya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sürgün', 'surgun-aytac-varol-6z0bz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sürgün oldum sevgilim

yürek menzilinden çıkıyorum

ak sayfalarımın rüzgar(ı)  gülü

gece ağrıyan yanım

gündüz düşüm

şiirde başlayan hüzünlü aşkın perisi,

vurgun yedim

derinime dalan basınçtan

düştü omuzdan bir dayanağım.

gizlide yanan hancıydım

şiirce konakladı gelip geçen

acı içinde kıvranan suretimiz

gerçeğin aynasına düşmeden

kırılıp dökülmeden sırrımız

aşka teslim edebilseydik kendimizi

şiire dönerdi gerçeğimiz.

kendi aklına çıldıran deli

ya da

şiirde kendini arayan da bulamayan dize gibi

bir yıldıza iç dökerek ağlamalı sabaha kadar; 

- ağla yüreğim ağla duyan O olsun -

hüzün besler, yürek direnir yanılsamalara

şairim ölür, şiirim ölmem

yaşar sevdam

bir dem sürer

ömürden de uzun.

(07.08.1995)', 'sürgün oldum sevgilim yürek menzilinden çıkıyorum ak sayfalarımın rüzgar(ı)  gülü gece ağrıyan yanım gündüz düşüm şiirde başlayan hüzünlü aş...', ARRAY['Türk Edebiyatı','Şiir','Aytaç Varol']::text[], 8.5, '{"poet":"Aytaç Varol","poet_slug":"aytac-varol","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/surgun-101-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '15Miniklerİçin:Mars da Satılık', '15minikleri-cin-mars-da-satilik-ahmet-yozgat-nywwa', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '1/:

Bu haftalık harçlığımı,

Peşin ver baba...

2/:

Bir parça arsa,

Alacağım kendime,

Bu gece Mars''tan...

3/:

Geçen hafta,

Jüpiter''den aldığım arsa,

Maalesef işgal edilmiş,

Duydum ki gecekonducularca...', '1/: Bu haftalık harçlığımı, Peşin ver baba... 2/: Bir parça arsa, Alacağım kendime, Bu gece Mars''tan... 3/: Geçen hafta, Jüpiter''den aldığım...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/15miniklericin-mars-da-satilik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '15Miniklerİçin:Gak Dedikçe', '15minikleri-cin-gak-dedikce-ahmet-yozgat-se3ca', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '1/:

''Gak'' dedikçe,

Şiir...

''Guk'' dedikçe,

Türkü...

İşte bütün gereksinimim.

2/:

Eğer istiyorsak çıkmak,

Karanlık dünyalardan,

Ve ulaşmaksa arzumuz,

Işıklı diyarlara...

3/:

''Gak'' dedikçe,

Şiir okumak gerek.

''Guk'' dedikçe,

Gerekir türkü çığırmak...', '1/: ''Gak'' dedikçe, Şiir... ''Guk'' dedikçe, Türkü... İşte bütün gereksinimim. 2/: Eğer istiyorsak çıkmak, Karanlık dünyalardan, Ve ulaşmaksa a...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/15miniklericin-gak-dedikce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '15Miniklerİçin:Pazartesi Satıyorum', '15minikleri-cin-pazartesi-satiyorum-ahmet-yozgat-g836l', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1/:

Haftalar alıyorum,

Nerede ve nasıl bulursam...

Sonra ayırıyorum,

Tek... Tek...

Silip silip parlatıyorum.

2/:

Tek... Tek... Ve özenle 

Parlattığım haftaları,

Çıkartıp yaşam pazarına,

İsteyene satıyorum.

3/:

Bozulmamışsa serisi,

Satışı kolay oluyor.

Eğer eksikse birisi,

Mesela,

Kaybolmuşsa pazartesi,

İşe yaramıyor gerisi...

4/:

Siz de kaybetmeyin günlerinizi,

Gecelerinizi boşa geçirmeyin,

Değerlendirin boş vakitlerinizi.

E mi? ...', '1/: Haftalar alıyorum, Nerede ve nasıl bulursam... Sonra ayırıyorum, Tek... Tek... Silip silip parlatıyorum. 2/: Tek... Tek... Ve özenle  Pa...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/15miniklericin-pazartesi-satiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mevsim sonu..', 'mevsim-sonu-bahri-kayaoglu-cav5q', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hayaller kar gibi eridi..

Artık umuttan da fayda yok.

Gerçi dünya tatlı ve hoş

Ama neyleyim,

Kalbim boş...', 'Hayaller kar gibi eridi.. Artık umuttan da fayda yok. Gerçi dünya tatlı ve hoş Ama neyleyim, Kalbim boş......', ARRAY['Türk Edebiyatı','Şiir','Bahri Kayaoğlu']::text[], 8.5, '{"poet":"Bahri Kayaoğlu","poet_slug":"bahri-kayaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/mevsim-sonu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '15Miniklerİçin:Nerede Koyun Gözlerim?', '15minikleri-cin-nerede-koyun-gozlerim-ahmet-yozgat-inw6g', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '1/:

Ben buradayım.

Nerede koyun gözlerim? 

Çiğdemlerim nerede? 

2/:

Gelse de yaşım kırka,

Çocukluğum burada,

Yani yanıbaşımda.

3/:

Ben buradayım.

Peki,

Nerede katır tırnağım? 

Nerede yalabuklarım? 

Yarpuzlarım nerede? ...

4/:

Omzumdadır çantam ile azığım,

Kazığım hazır elimde,

Daha yeni yontulmuş.

5/:

Ben buradayım.

Peki...

Nerede beyaz turplarım,

Nerede pembe şalgamlarım,

Pürçeklilerim nerede? ...

6/:

Çocukluğum burada,

Yani yanı başımda.

Peki,

Nerede murçalıklarım? 

Kuzukulaklarım hangi derede?', '1/: Ben buradayım. Nerede koyun gözlerim?  Çiğdemlerim nerede?  2/: Gelse de yaşım kırka, Çocukluğum burada, Yani yanıbaşımda. 3/: Ben burad...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/15miniklericin-nerede-koyun-gozlerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '15Miniklerİçin:Betonların Çocuğu', '15minikleri-cin-betonlarin-cocugu-ahmet-yozgat-a0gcl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '1/:

Mahallede kalan son arsaya da,

Kökünden söküp hayallerimizi,

Ve direklerini top kalemizin,

Diktiler bir bir,

İnşaatçı amcalar,

Kendi tuğladan hayallerini.

2/:

Soldu umutlarımızın gülü,

Sümbülü soldu rüyalarımızın.

Çimento çimento açıyor artık,

Eskinin boş arsalarında,

Onların sahte yeşil hayalleri.

3/:

Her Allah''ın günü,

Çukurlar kazılıyor,

Atılıyor temeller,

Kan ter içinde,

Boş olan her yere

Dikiliyor betondan kuleler...

4/:

Artık ne oyun kaldı,

Ne de oyun alanı.

Bu devir bizim için,

Televizyon zamanı...', '1/: Mahallede kalan son arsaya da, Kökünden söküp hayallerimizi, Ve direklerini top kalemizin, Diktiler bir bir, İnşaatçı amcalar, Kendi tuğ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/15miniklericin-betonlarin-cocugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '15Miniklerİçin:Çıtır Çıtır Ekmek', '15minikleri-cin-citir-citir-ekmek-ahmet-yozgat-hugh1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '1/:

Çıtır çıtırım...

Ta geceden başlar hayatım,

Başlar ateşler içinde...

Bu kısacık ömrüm,

Biter sabah sofrada.

2/:

Çıtır çıtırım...

Yayılır kokum tüm mahalleye,

Köpeklere, kedilere,

Bir haller olur,

En erkeninde sabahın.

3/:

Çıtır çıtırım...

Koşar komşular,

Kapışır beni.

Tükenmek üzereyim,

Bir varım, bir yokum...', '1/: Çıtır çıtırım... Ta geceden başlar hayatım, Başlar ateşler içinde... Bu kısacık ömrüm, Biter sabah sofrada. 2/: Çıtır çıtırım... Yayılır...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/15miniklericin-citir-citir-ekmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşünemiyorum', 'dusunemiyorum-ayse-adlim-csw5d', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Durmuş beynim

Düşünemiyorum

Kör oldum sanki

Göremiyorum

Bir ateş var içimde

Yakıyor beni iyice

Ne yapsam boş

Eriyorum gittikçe

Bugün düşünemiyorum

Yarın yazamayacağım

Kalbim de külleşince', 'Durmuş beynim Düşünemiyorum Kör oldum sanki Göremiyorum Bir ateş var içimde Yakıyor beni iyice Ne yapsam boş Eriyorum gittikçe Bugün düşünem...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Adlım']::text[], 8.5, '{"poet":"Ayşe Adlım","poet_slug":"ayse-adlim","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/dusunemiyorum-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '15Miniklerİçin:Amerikanya Diye Bir yer', '15minikleri-cin-amerikanya-diye-bir-yer-ahmet-yozgat-hiy6q', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '1/:

Amerikanya,

Deyince aklıma:

Degav... Degav! ...

Grav... Grav! ...

Geliyor ya.

Gülüyor gülüyorum.

Müstehakını versin Amerikanya...

1/:

Amerikanya,

Deyince aklıma,

Silahlı tepeden tırnağa,

Sığır güden kovboylar:

How... How! ...

Yehow... Yehow! ...

Geliyor ya.

Gülüyor gülüyorum.

Müstehakını versin Amerikanya...

1/:

Amerikanya,

Deyince aklıma,

Geniş kenarlı şapkalar,

At sırtında şerifler,

Tren soyan haydutlar:

Hurra... Hurra! ...

Tişow... Tişow! ...

Geliyor ya.

Gülüyor gülüyorum.

Müstehakını versin Amerikanya...', '1/: Amerikanya, Deyince aklıma: Degav... Degav! ... Grav... Grav! ... Geliyor ya. Gülüyor gülüyorum. Müstehakını versin Amerikanya... 1/: Am...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/15miniklericin-amerikanya-diye-bir-yer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '15Miniklerİçin:Sigarayı Vursalar', '15minikleri-cin-sigarayi-vursalar-ahmet-yozgat-b5018', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1/:

Sigara bizi vurmadan,

Sigarayı vursalar...

***

Neredeler? 

Dağı taşı dolaşan,

Attığını gözünden vuran,

Keskin nişancı avcılar...

Tavşanları vurdukları gibi,

Ya da dağlarda boz ayıları...

Neden doğrultup tüfeklerini? 

Sigarayı vurmazlar...

2/:

Sigara bizi vurmadan,

Vursalar ya onlar sigarayı...

***

Neredeler? 

Göz açtırmayan düşmana,

Toplu, tüfekli askerler,

Korudukları gibi,

İstanbul''u,

Ankara''yı,

Van''ı

Konya''yı ya da...

Neden korumazlar? 

Biz küçük çocukları...

Doğrultup tüfeklerini? 

Sigarayı da vurmazlar...

***

Sigara bizi vurmadan,

Sigarayı onlar vursalar ya...', '1/: Sigara bizi vurmadan, Sigarayı vursalar... *** Neredeler?  Dağı taşı dolaşan, Attığını gözünden vuran, Keskin nişancı avcılar... Tavşanl...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/15miniklericin-sigarayi-vursalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '15Miniklerİçin:Çocuklar Günü Nerde?', '15minikleri-cin-cocuklar-gunu-nerde-ahmet-yozgat-k4poa', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '1/:

Günlerden bir gün,

Anneler günü...

Bir diğer günün ise,

Sahibidir babalar.

2/:

Neden yoktur diye? 

Merak ederdim doğrusu,

Biz çocuklara ait bir gün...

3/:

Oysa,

Duydum ki,

Deliye her gün bayrammış,

Tüm bayramlarsa biz çocuklara...', '1/: Günlerden bir gün, Anneler günü... Bir diğer günün ise, Sahibidir babalar. 2/: Neden yoktur diye?  Merak ederdim doğrusu, Biz çocuklara ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/15miniklericin-cocuklar-gunu-nerde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '15Miniklerİçin:Buzdolabım Eskimo', '15minikleri-cin-buzdolabim-eskimo-ahmet-yozgat-3qdus', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '1/:

Buz dolabım Eskimo...

O... o... o! ...

Soğutur yemekleri,

Etleri,

Balıkları

Yani soğutur,

Eskimo''m her bir şeyi.

2/:

Buz dolabım Eskimo.

O... o... o! ...

Dondurur yemekleri de,

Etleri de, balıkları da

Yani dondurur,

Eskimo''m her bir şeyi de,

Neden gücü yetmez? 

Ne soğutur,

Ne dondurur kendini.

3/:

Merak bu ya,

Sordum anneme.

Dedi ki bana:

''Terzi dikemez söküğünü.''

Ya da,

''Mum ışık vermez dibine.''

4/:

Annemin sözlerinden, 

Pek bir şey anlamadım.

Ama yine de,

Bilgiç bilgiç başımı salladım...', '1/: Buz dolabım Eskimo... O... o... o! ... Soğutur yemekleri, Etleri, Balıkları Yani soğutur, Eskimo''m her bir şeyi. 2/: Buz dolabım Eskimo....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/15miniklericin-buzdolabim-eskimo-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '15Miniklerİçin:Kemerimin Işılak Tokası', '15minikleri-cin-kemerimin-isilak-tokasi-ahmet-yozgat-jo21e', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '1/:

Ben bir kemer tokasıyım.

Sağlam deridenim.

Işılak demirdenim.

2/:

Ben bir kemer tokasıyım.

Nereli miyim? 

Sayın ki Karabük,

Veya İskenderun,

Ya da ta Divriği''denim...

3/:

Ben bir kemer tokasıyım.

İliklerim,

O yakayı bu yakaya.

Yani İstanbul''u İstanbul''a,

Çanakkale''yi Çanakkale''ye...

4/:

Ben bir kemer tokasıyım.

Sayın ki iliklerim,

Geceyi gündüze,

Gündüzü geceye...

5/:

Ben bir kemer tokasıyım.

Yaptığım bunca işle,

Size örnek olmalıyım...', '1/: Ben bir kemer tokasıyım. Sağlam deridenim. Işılak demirdenim. 2/: Ben bir kemer tokasıyım. Nereli miyim?  Sayın ki Karabük, Veya İskende...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/15miniklericin-kemerimin-isilak-tokasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '15Miniklerİçin:Ben Bir Gül Değilim', '15minikleri-cin-ben-bir-gul-degilim-ahmet-yozgat-233ti', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '1/:

Annem:

''Gülüm.'' diye seviyor beni.

Babam:

''Gülüm benim.'' diye.

Ninem:

''Güllerin hası.''

Dedem:

''Güllerin şahı.''

2/:

Ben:

''Yeter! '' diyorum.

Yani gül olmak,

İstemiyoruuuum...

Siz ''Gül'' dedikçe bana,

Altıma gübreliyorum.', '1/: Annem: ''Gülüm.'' diye seviyor beni. Babam: ''Gülüm benim.'' diye. Ninem: ''Güllerin hası.'' Dedem: ''Güllerin şahı.'' 2/: Ben: ''Yeter! '' diyoru...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/15miniklericin-ben-bir-gul-degilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çile', 'cile-zeynal-yaman-ipkkd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Garibim sazımın telleri çile

Istırap bestemin güftesi çile

Topraktan yoğrulmuş nâçiz vücudum

Vücut hamurumun mayası çile

Gaspedilmiş aşkın azap çiçeği

Kahreden bülbülün nağmesi çile

Feryat etmekte ruh yanmakta gönül

Gönül ateşinin alevi çile

Ey Zeynel! Ne kahredersin kendine

Bak, fâni dünyanın varlığı çile

1987,Ordu', 'Garibim sazımın telleri çile Istırap bestemin güftesi çile Topraktan yoğrulmuş nâçiz vücudum Vücut hamurumun mayası çile Gaspedilmiş aşkın a...', ARRAY['Türk Edebiyatı','Şiir','Zeynal Yaman']::text[], 8.5, '{"poet":"Zeynal Yaman","poet_slug":"zeynal-yaman","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/cile-46-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '15Miniklerİçin:Şiire Paydos', '15minikleri-cin-siire-paydos-ahmet-yozgat-1sz42', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '1/:

Bütün çocukların,

Rengarenk dünyasını,

Eğer gösteremiyorsam şiirimde,

Bir... Bir...

***

Artık,

Şiire paydos,

Yazmayacağım şiir...

1/:

Bütün büyüklerin,

Pörsümüş ilgisini,

Çekemiyorsam eğer şiirimde,

Bir... Bir...

***

Artık,

Şiire paydos,

Yazmayacağım şiir...', '1/: Bütün çocukların, Rengarenk dünyasını, Eğer gösteremiyorsam şiirimde, Bir... Bir... *** Artık, Şiire paydos, Yazmayacağım şiir... 1/: Bü...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/15miniklericin-siire-paydos-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gül geziye gurbet  Düştüm İstanbulda', 'bir-gul-geziye-gurbet-dustum-i-stanbulda-hamdi-oruc-vap8l', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir Gül geziye gül not  Düştüm İstanbulda

Ecdadımın hatıralarını yaşatan şehir

Tek sende yaşıyorum rüyada gibi

İstanbul yoksa gurbetsin dünya

Mavi gözlü İstanbul''a doyulmuyor

Tarih kokuludur İstanbul

Aklıma kazımışım İstanbulu

İstanbul''dan ayrılmak ölüm

Her sabah ağlıyorum bakıp bakıp fotoğraflarına

Aklıma kazımışım İstanbulu

Minarelerinde elif var İstanbulun 

Minarelerinde hep elif olsun İstanbul...

Kubbeler su deposu sular İstanbul''u

Yıllar yılı

İstanbul gül şehir

İstanbul bal şehir

İstanbul yar şehir

Güller içinde bir

Aklıma kazımışım İstanbul''u

Ecdadımın hatıralarını yaşatan şehir bu

Ona aşkım gece ay,gündüz güneş 

Tek onda yaşıyorum rüyada gibi 

Öpülesi taşı toprağı

Mavi gözlüm İstanbul''a doyulmuyor

Güle  vatan İstanbul...

Minarelerinde elif...

Çocuktum ilk tanıştığımda 

Işık ışık minareleri

Mavi gözlüm İstanbul 

Damarda kan gezer gibi 

Geziyorum sokaklarında 

Bal içiyorum sokaklarında

İstanbulum o

Yedi tepeli  cennet... 

Yedi tepe yedi şeker 

Ortaköy lokum, şeker 

Ortaköy''de üç dinin mabedi yükselmiş 

Günde beş vakit ezanlar göklerde uçar 

Boğazda su okyanuslara sevda çeker 

Emirğanda yeşil ve mavi akar gönle 

Emirğanda uzar ağaçlar huzura 

Hisarın duvarlarında tarihten gülücükler 

Kimse girmesin İstanbulla arama

Sultanahmet 

Cennetin merkezi 

Bir sigara yakıp derin hesaplara dalan insanlar 

Sokratın aklını karıştıran insanlar 

“Kırk kulplu kazan İstanbul “diyip gelen insanlar 

Eli yüzü nurlu gözleri ışık insanlar 

Pervaneleri Sultanahmet’in 

Kimse girmesin İstanbulla arama

Bir yaz günü gezdim İstanbul’u 

Yaz gününün sıcaklığı uyutmuş güvercinleri 

Bir camii avlusunda 

Gönlüm uyanık

Gönlüm yanık

Her gün gemiler ümitlere gider

Uyandırmayın uyusun İstanbul 

Tek İstanbul uyur en güzel uykuları 

Ve bulutlar selamlayarak ayrılıyorlar İstanbul’u 

Mezarlıklarını denizini,camii’lerini... 

Kimse girmesin İstanbulla arama

Bir gün  ayrılır mıyım İstanbul’dan 

Ayrılırsam

Gözlerim bulutlar gibi ayrılırım 

Ne zaman ayrılsam İstanbul’dan 

Çantam İstanbul dolu 

Alırım mezarlıklarını 

Denizini 

Camiilerini...

Minarelerinde hep elif olsun İstanbul

Elifli gökler mavi 

Bahar değil yeri yeşerten

Gönlümün güzelliklerinde uyu İstanbul

Kimse girmesin İstanbul''la arama

Bu gün', 'Bir Gül geziye gül not  Düştüm İstanbulda Ecdadımın hatıralarını yaşatan şehir Tek sende yaşıyorum rüyada gibi İstanbul yoksa gurbetsin düny...', ARRAY['Türk Edebiyatı','Şiir','Hamdi Oruç']::text[], 8.5, '{"poet":"Hamdi Oruç","poet_slug":"hamdi-oruc","theme":"Türk Şiiri","is_hero":false,"total_lines":76,"source_url":"https://www.antoloji.com/bir-gul-geziye-gurbet-dustum-istanbulda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Anlaşılmaz', 'ask-anlasilmaz-mehmet-can-1p40a', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'kuş kanatlanır

yaprak düşer

rüzgar eser öylesine

toprak kokar bazı zamanlar

zaman değişir

aşk hep anlaşılmaz olur

tüm mevsimlerde', 'kuş kanatlanır yaprak düşer rüzgar eser öylesine toprak kokar bazı zamanlar zaman değişir aşk hep anlaşılmaz olur tüm mevsimlerde...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Can']::text[], 8.5, '{"poet":"Mehmet Can","poet_slug":"mehmet-can","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ask-anlasilmaz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelsen', 'gelsen-tulay-i-cen-qua9y', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gelsen yine,

Acsam  koynumu sana.

Özlemini gidersem kokunla.

Mutluluğu getirsen,,

Kaybetiğim mutluluğu.

Doğan güneş gibi,

Isıtsan,çözsen  yüreğimdeki

Buzları..

Eritsen sıcaklığınla.

Pişmanlığım değilsin

Olmayacasın,

Gönlümdeki umudum,

Yüreğimdeki hasretim...

Karanlık olan  rüyalarımı,

Yıldızların ışığı gibi.

Aydınlatsan..! 

Hayalim değil,gerceğim ol..

Yarınlarım geleceğim ol.

Gelsen yine.

Acsam koynumu sana.

Ah,Ah.! 

Sabret diyorsun.sabret....', 'Gelsen yine, Acsam  koynumu sana. Özlemini gidersem kokunla. Mutluluğu getirsen,, Kaybetiğim mutluluğu. Doğan güneş gibi, Isıtsan,çözsen  yü...', ARRAY['Türk Edebiyatı','Şiir','Tülay İçen']::text[], 8.5, '{"poet":"Tülay İçen","poet_slug":"tulay-i-cen","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/gelsen-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gittin', 'gittin-banu-askin-f870q', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gittin...

Demek sen bana gitmek için gelmişsin...

Bitirdin...

Onca hayali,umudu,beni..

Ne oldu gittin diye? 

Kurtuldunmu içindekilerden? 

Unutmaki,kendin hep seninle...

Yüreğim,düşlerim ve sevgim hep sende...

Özlemek ayrılığın ta kendisiymiş anladım...

Ve biliyorumki herşey için çok geç sevdiğim..

Çok geç.....

(20.05.2005/02.05)', 'Gittin... Demek sen bana gitmek için gelmişsin... Bitirdin... Onca hayali,umudu,beni.. Ne oldu gittin diye?  Kurtuldunmu içindekilerden?  Un...', ARRAY['Türk Edebiyatı','Şiir','Banu Aşkın']::text[], 8.5, '{"poet":"Banu Aşkın","poet_slug":"banu-askin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gittin-125-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Aşk Lafta Erimez', 'her-ask-lafta-erimez-abdulkadir-karaca-ku1im', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sen bu şehirden gidince 

güneş gözlerinde gidince

değersizleşiyor İstanbul

seni sensiz anlatmanın anlamsızlığı 

iki kelimeyi bir araya getiremiyorum 

bak yine yutkundum hevesimi

söyleyemiyorum

seni ne kadar çok özlediğimi

her aşk lafta erimiyor

ben bitiremiyorum beynimde seni

üç beş günlük bir aşkı bitirir gibi

gönderemiyorum aşkını dönülmez sürgünlere

zindanlarımda binlerce aşk çürüten ben

ellerinde çürüyorum

lanet olsun

sana bunları söyleyemiyorum

aşk lafta erimez

sen beni sana uzak ve acıyan bildiğin kadar

ben acınacak haldeyim halbuki

aşkın kalbime mezar

yıllanmalı bu aşk yılların mayasında

yokluğuna tutunmak çabasında yok oluyorum

sen bu şehirden gidince

cüzamlı bir kadına dönüşüyor İstanbul

iğrenmemek elde değil

şiir yazamıyorum ne sana

nede istanbula

lafta erirse

çekip vuracağım şerefimi

bu aşk biterse benden yana 

keseceğim kendi  nefesimi

alma gözlerini gözlerimden

sana bakıpta ağlamamak mümkün mü

bundandır  o geceki gözyaşım

acım  cinnet geçirmiş gördün mü

sana zararsız,boğazlayacak kendini

erimek

bir öpüşünden sonra kazındı aklıma

en anlamlı sözcüğüm oldu

seni şifrelerken buldum yaşam kelimemi

her aşk lafta erimez

kurcalama benden olan anlayacak yazdığımı

bir yara bıraktın kalbime silinmez

sen bu şehirden gittikçe

sızım sızım hissettirecek kendini

ne tuhaf bir şiir bu

ama inan yazan beynim değil

kalbime söz geçirebilseydim

sen bu şehirden gittiğin an silerdim seni

neleri bilir bu şairde bir seni bilmez

seni artık sevmiyorum desem de bil

her aşk lafta erimez

20.03.2006', 'sen bu şehirden gidince  güneş gözlerinde gidince değersizleşiyor İstanbul seni sensiz anlatmanın anlamsızlığı  iki kelimeyi bir araya getir...', ARRAY['Türk Edebiyatı','Şiir','Abdülkadir Karaca']::text[], 8.5, '{"poet":"Abdülkadir Karaca","poet_slug":"abdulkadir-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/her-ask-lafta-erimez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul', 'i-stanbul-melike-yurtsever-ay9s9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her sokağı, 

Başka bir sevdaya şahittir,

İstanbul’un! 

Beyoğlu’nda deli dolu âşıklar…

Fatih’te gizlice mektuplaşanlar…

Kaldırımlarında tutkulu yalnızlar,

Ki onlardır,

Köşe başlarında,

Tesadüfî bakışlarda,

Yeni heyecanlar arayanlar.

İstanbul’a bakarsan anlarsın,

O da âşıktır! 

Her yanı ışıldar, baharla,

Üzülür, ağlar ayrılınca.

Bazen, kış güneşidir,

İstanbul’a küçük bir kıvılcım çakan,

Yazın  o tatlı heyecanını hatırlatan.

Ama,

İstanbul’a sorsan,

AŞK yalan…

Sevda YAVAN…', 'Her sokağı,  Başka bir sevdaya şahittir, İstanbul’un!  Beyoğlu’nda deli dolu âşıklar… Fatih’te gizlice mektuplaşanlar… Kaldırımlarında tutku...', ARRAY['Türk Edebiyatı','Şiir','Melike Yurtsever']::text[], 8.5, '{"poet":"Melike Yurtsever","poet_slug":"melike-yurtsever","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/istanbul-417-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek...', 'sevmek-banu-askin-4azch', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevmek boğulmak mıdır kentlerin soğuk ışıklarında? 

Vazgeçmek midir hayattan? 

Tükenmek midir soluksuz? 

Yaşlanmak mıdır gün,gün? 

Dönen dünyaya ayak uyduramamak mıdır? 

Yoksa kapatıp yorgun gözleri,

yalnızlığı sindirmek midir ruha? 

Sisli bir akşam bitimi sevginin tanımını yapmakta zorlanıyorum...

Oysa bir çırpıda çıksın isterdim dudaklarımdan...

Ellerinden tutup uçurmak isterdim gökyüzüne..

Ve özgür,

ve hoyrat,

ve savunmasızlığımız diz boyu..

Gözlerine düşürmemek isterdim acıyı,

Dudaklarından tebbessümü hiç eksiltmemek,

her doğan gün yeniden başlamak yaşamaya

ve sınırsızca aşka...

Yelkenler açmak en güzel umuda ve kopmak tam hayatın ortasında...

Nedensiz ve sorgusuz,

Yalansız ve dolansız......', 'Sevmek boğulmak mıdır kentlerin soğuk ışıklarında?  Vazgeçmek midir hayattan?  Tükenmek midir soluksuz?  Yaşlanmak mıdır gün,gün?  Dönen dün...', ARRAY['Türk Edebiyatı','Şiir','Banu Aşkın']::text[], 8.5, '{"poet":"Banu Aşkın","poet_slug":"banu-askin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sevmek-153-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul ve Ben', 'i-stanbul-ve-ben-melike-yurtsever-ce8sa', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İstanbul şimdi üzgün, neden diye sormayın.

Belki gökyüzü, aylardır gri olduğu için.

İstanbul belki de, baharlarını özlemiştir…

Ben hiç korkmadım İstanbul’dan,

Ne de kendime bir düşman gördüm! 

Biliyorum ki İstanbul da,

Benim gibi hicran dolu…

Bacalarında tüten duman,

Bir imdat çağrısı! ..

Her gece terkediyorlar onu,

Ama o hiç kin beslemedi.

Sabah ayazında tek başına üşüdü,

Ve yıldızsız geçirdi,

Bazı geceleri…

Onun yerinde olsa başka biri,

Çoktan terketmişti beni! 

Bir dilek ağacıdır, 

İstanbul’un her sokağı.

Âşıklar mutluluk umar,

Balkonlarından nice ümit sarkar,

Ama bazen tepen atar,

Kızarsın İstanbul’a! 

Tekmelersin kaldırımlarını,

İstanbul,

Gücenme bana! 

Çaresizim,

Çatacak başkası yok ki…

O ise, 

Çoktan öldü,

Bu şehir aldı onu benden,

Bir kış günü…', 'İstanbul şimdi üzgün, neden diye sormayın. Belki gökyüzü, aylardır gri olduğu için. İstanbul belki de, baharlarını özlemiştir… Ben hiç korkm...', ARRAY['Türk Edebiyatı','Şiir','Melike Yurtsever']::text[], 8.5, '{"poet":"Melike Yurtsever","poet_slug":"melike-yurtsever","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/istanbul-ve-ben-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul: Başkenti Hayatın', 'i-stanbul-baskenti-hayatin-ali-yusuf-aydin-k8vve', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İstanbul şiiridir kendi ahvalinin.

Her parçası bir dize,

ve kafiyedir her zerresi diğerine.



Kız Kulesi, denize bekçi Üsküdar’da.

Galata’ya emanet Eminönü’nde vapurlar.

Martılar, göz kulak balıklara.

Simitlerin susamı, İstanbul’dan dökülür Marmara’ya.



Sultanahmet’de tarih sızıyor tramvay raylarından.

Cağaloğlu kitap dolu.

Topkapı tekmil veriyor tarih sayfalarına

ve kahverengi yapraklar dökülüyor Gülhane’de ayak uçlarıma.

Polisler, farkında artık ceviz ağaçlarının(!)       



Eski kitap kokusu sızdırıyor Beyoğlu’nda sahaflar.

İstiklal Arnavut bir köprü Beyoğlu’ndan Galata’ya.

Bir keşmekeştir coğrafyası; 

Kitapçılar, müzikçiler, mızıkacılar

ve piyangocu kız köşe başında.

Sesi; karışmış kahrolsunlara.



Tophane’de nargile fokurtusu kulaklarımda.

Dolmabahçe yolundan selam olsun Ata’ya.

Varsın deprem olsun! 

Hazır kıta, kıpırdamaz büyük kapıda Mehmet jandarma.

Boğaz taht kurmuş Ortaköy’de 

Avrupa’dan Asya’ya.

Her vapur bir ada kıtalar arası 

İstanbul ile çevrili dört bir tarafı.



Vapurların düdüğünü şahadet sesi bölmekte 

Eminönü’nde,

Üsküdar’da,

Kadıköy’de,

Kabataş’da



B

o

y  gösterisinde Çamlıca.



Bebek sahiline kurulmuş bir bank İstanbul

Seyir eylerken kendini; 

Gölgeler raks ediyor Boğaz’ın  mavisinde.

Gündüz gözüyle göreyim diye erkenden doğuyor ay burada.

İstanbul saklıyor göçmen kuşlar küçücük kanatlarına.

Ve kıyıda konsolosluğu dövüyor dalgalar.



Bir balık, demir atmış tam Bebek’de kıyıya.

Bir kıtanın bir kıtaya nispet varlığı karşımda.

Aracı malum; Boğaz Köprüsü ki bir düğümdür İstanbul’a.

Hisar, kafasını uzatmış da dinliyor kulağımda türküyü.

Kulağımda ne varsa dilime kayıyor.

Bir türkü   y  ü  r  ü  y  o  r    gönlüme

içinde İstanbul saklı.

Gariptir; Orhan Veli geliyor aklıma

gözlerim kapalı.



İstanbul’dayım işte 

başkenti hayatın

ve kahve kokusu Mısır Çarşısında...



Kainat kol kola İstanbul’da.

Doğu-batı,

Asya-Avrupa...

İmam ile papaz oturuyor yan yana,

can cana

bazı bir iftar sofrasında,

bazı Aya Sofya ortasında.

Eller semada,

dudaklarda  bir dua,

Bir şahadet türküsü; 

barış gelsin cihana.



İstanbul’dayım işte

başkenti hayatın

ve kahve kokusu Mısır Çarşısı’nda...



Eyüp’de Haliç; uyur Boğaz’ın koynunda.

Fatiha’lar okunur yukarıda; 

Pier Loti yokuşunda.

Göğü  bir başka deler minareler; oradan bakınca.

Rumca, Ermenice türküler çığırtkanıdır, cumbalı evler Balat’da.

Ha......la.....ken

..... va....nır.........Yeni Cami’de güvercinler; 

dilimde bir türkü, 

kulağımda davetkar bir ses; boğaz üfler semaya:

‘’Haydi Boğaz’a gi

..........................di

........................... yo

...............................ruz  Boğaz’a’’

Oltalar tırmıklarken iskelede denizi; 

karşıda; Avrupa’ya uzaaaanan bir semttir Sirkeci.

Kulaklarımda bir mehteran marşı,

sokak sokak, cadde cadde minyatürüdür İstanbul’un 

Beyazıt içinde Kapalı Çarşı.

Her  köşesi başka bir hava,

her zerresi başka bir tat nakşeder damarlarıma.

İstanbul bir esti mi 

Boğaz damlar, tarih çarpar yanaklarıma.

İstanbul’dayım işte

başkenti hayatın

ve kahve kokusu Mısır Çarşısı’nda...', 'İstanbul şiiridir kendi ahvalinin. Her parçası bir dize, ve kafiyedir her zerresi diğerine. Kız Kulesi, denize bekçi Üsküdar’da. Galata’ya e...', ARRAY['Türk Edebiyatı','Şiir','Ali Yusuf Aydın']::text[], 8.5, '{"poet":"Ali Yusuf Aydın","poet_slug":"ali-yusuf-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":91,"source_url":"https://www.antoloji.com/istanbul-baskenti-hayatin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnız ben sevmiştim', 'yalniz-ben-sevmistim-huseyin-ozcan-sb0vc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ben bu şehirde tanımıştım seni,					

bu şehrin akşamlarında akıttım sana hasret gözyaşlarımı..		

bu şehir teskin etti,senin yokluğuna isyanımı,				

ben bu şehrin  şehadetiyle sevmiştim seni….					

					

zaman oldu kalabalıklarına karıştım seni ararken,			

kayboldum….					

zaman oldu tenha sokaklarında dolaştım  gecenin kör vakti,		

bulamadım……..					

ben bu şehirde bir tesadüfle bulmuştum seni,				

seni yine bu şehirde kaybettim…..					

					

sana sitem etsem sen suçsuzsun,					

şehir e kahretsem şehir günahsız,					

aslında ne şehrin kabahati var,ne de sensiz  vefasız.			

bütün kahırlar ve sitemler kendime,					

yalnız ben sevmiştim….kendim gibi yalnız…..				

yalnız ben sevmiştim karşılıksız,					

aslında biliyordum,					

senin beni sevmen imkansız….					

					

sen şimdi yoksun ya,					

ben şimdi senin gelmediğin yerlerdeyim,				

nerden bileydim ki gittiğini….', 'ben bu şehirde tanımıştım seni,					 bu şehrin akşamlarında akıttım sana hasret gözyaşlarımı..		 bu şehir teskin etti,senin yokluğuna isyanı...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Özcan']::text[], 8.5, '{"poet":"Hüseyin Özcan","poet_slug":"huseyin-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yalniz-ben-sevmistim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm?', 'olum-melike-yurtsever-m4d6f', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Farzet ki az sonra öleceksin,

Can çekilecek hücrelerinden,

Her yanın buz kesecek,

Bilinmeyen bir yer seni saracak…

Unutma! 

Ölüler ne kadar çok olsa da,

Mezarlar hep, 

Tek kişiliktir.

Ve sen de, herkes gibi,

Yalnız kalacaksın…

Zaman kavramın değişecek belki,

Ama yaşadığın her güzel şey,

Yüzünde huzurlu bir gülümseme doğuracak.

Belki, kimleri sevdiğini

Hatırlamayacaksın.

Ama birisi seni hep anacak…', 'Farzet ki az sonra öleceksin, Can çekilecek hücrelerinden, Her yanın buz kesecek, Bilinmeyen bir yer seni saracak… Unutma!  Ölüler ne kadar ...', ARRAY['Türk Edebiyatı','Şiir','Melike Yurtsever']::text[], 8.5, '{"poet":"Melike Yurtsever","poet_slug":"melike-yurtsever","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/olum-282-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Esmer Kız’ a', 'esmer-kiz-a-tunahan-ermihan-8wg9h', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ceplerime doldurdum 

Yaşlarımdan miras sevda kırıklıklarını 

Geldim yamacına 

Eyy kahve gözlerine alemleri sığdırmış olan 

Sen ne latif ne yüce gönüllüsün bilirim ben 

Bir başı bin dertli geldimse de kapına 

Bilirim salmasın artık sen beni yaban hayatlara 

Gözlerim kör, tenim yanık ve topal yürekliyim

Ben sen gibi gülün yanında ancak bir dikenim

Kanar her yanım acır içim

Bir dokunsan ölmeyi de bilirim 

Huzur içerisinde

Eyy şahsı latif 

Eyy ab-ı hayat 

Ve eyy derdimin dermanı

Bir tebessümüne kavuşmak uğruna 

Ne çok yandım sensiz gecelerde

Tüm taşlarımı döktüm eteklerine

Çırılçıplak karşındayım 

Bir dokun yüreğime 

Bin öleyim dizlerinde

20.03.2006 17:10:18', 'Ceplerime doldurdum  Yaşlarımdan miras sevda kırıklıklarını  Geldim yamacına  Eyy kahve gözlerine alemleri sığdırmış olan  Sen ne latif ne y...', ARRAY['Türk Edebiyatı','Şiir','Tunahan Ermihan']::text[], 8.5, '{"poet":"Tunahan Ermihan","poet_slug":"tunahan-ermihan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/esmer-kiz-a-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nevroz Ateşi', 'nevroz-atesi-fatma-guven-az3tb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nevrozlar açar gönlümün baharında,

Gökyüzünden kar iner,

Güneş açar yeniden,

Topraktan buhar  yükselir.

Yeni umutlara gebe tan ışımaları.

Çağırır esrikleşen dağların dorukları.

Kırmızılar; ateşlesin kanını,

Yeşil; umudu yeşertsin yüreğinde,

Sarı; ruhunun dinginliğini söylesin,

Sevdan; beyazlığın saflığında.

Zılgıtlarla gel can dost,

Tilililer çınlatsın dört bir yanı.

Filizle Nevroz ateşiyle yaşamı.', 'Nevrozlar açar gönlümün baharında, Gökyüzünden kar iner, Güneş açar yeniden, Topraktan buhar  yükselir. Yeni umutlara gebe tan ışımaları. Ça...', ARRAY['Türk Edebiyatı','Şiir','Fatma Güven']::text[], 8.5, '{"poet":"Fatma Güven","poet_slug":"fatma-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/nevroz-atesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalmaz Kararım', 'kalmaz-kararim-yusuf-onder-bahceci-rnrzp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir gün çıkıp geleceksin diye, diye hayaller kurarım,

Kendi ayrılmadı, zorla ayırdılar diye, şiirleri yazarım,

Nerede sana benzer birini görsem, inan ki ağlarım,

Kalmaz bir kararım, Yeri Göğü Yaratan''a yalvarırım', 'Bir gün çıkıp geleceksin diye, diye hayaller kurarım, Kendi ayrılmadı, zorla ayırdılar diye, şiirleri yazarım, Nerede sana benzer birini gör...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kalmaz-kararim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni seviyorum', 'seni-seviyorum-ayse-adlim-01mvp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Razıyım Senden gelene

Şükrederim her halime

En iyiyi bilensin

En güzeli görensin

Tek yalvardığım

Tek sığındığım

Tek sevdiğimsin

Seni seviyorum 

Asla isyan etmiyorum

Derdim varsa 

Kendi hatamdan

Dermanı Senden diliyorum

Seni seviyorum dağlarda

Seni seviyorum kırlarda

Seni seviyorum ağaçlarda

Seni seviyorum insanlarda

Seni seviyorum yavrularımda

Seni seviyorum kocamda

Seni seviyorum kendimde

Beni sevdiğin için seviyorum

Beni duyduğun için seviyorum

Beni ağlattığın için seviyorum

Seni seviyorum Allah''ım

Ruhumdaki yeşili

Koruduğun için seviyorum', 'Razıyım Senden gelene Şükrederim her halime En iyiyi bilensin En güzeli görensin Tek yalvardığım Tek sığındığım Tek sevdiğimsin Seni seviyor...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Adlım']::text[], 8.5, '{"poet":"Ayşe Adlım","poet_slug":"ayse-adlim","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/seni-seviyorum-349-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kârlar Yağdı Saçlarıma', 'k-rlar-yagdi-saclarima-yusuf-onder-bahceci-brqvi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kârlar yağdı saçlarıma bak hayattan neler beklerken,

Yolunda toprak oldum bak, güllerimiz böyle solarken,

Kırdılar testimizi, sular yavaş, yavaş, yavaş dolarken,

Kârlar yağdı saçlarıma bak hayattan neler beklerken,', 'Kârlar yağdı saçlarıma bak hayattan neler beklerken, Yolunda toprak oldum bak, güllerimiz böyle solarken, Kırdılar testimizi, sular yavaş, y...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/karlar-yagdi-saclarima-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sordum Dünyayı', 'sordum-dunyayi-tuncay-akdeniz-8twmz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kaşımın altında,gözler yan yana,

Düşündüm dünyadan,ne kalır bana.

Hayat dersi verir,dünya insana.

........Neyi var neyi yok,sordum dünyayı,

........Bükülmez dediler,çeliktir yayı

Şu gören gözlerin,seyrine bakar,

Arının balından,bir ibret çıkar.

Sular bile kendi,yönünce akar.

........Neyi var neyi yok,sordum dünyayı,

........Bin bir deresinden akıyor suyu.

Bu gidişat beni,bir gün yoracak,

Var mı dünyasında,baki kalacak 

Her gün söndürüyor nice bin ocak

.........Neyi var neyi yok,sordum dünyayı,

.........Kanunu değişmez böyledir huyu. 

Ne kadar yaşasam,bükülür belim,

Bir gün solacaktır,dalında gülüm.

Her canlının sonu,biliriz ölüm.

.........Neyi var neyi yok,sordum dünyayı,

.........Bir avuç topraktır o gözün payı.

Kul Tuncayım  başım,kar ile duman,

Kendine güvenme,el senden yaman.

Kimseye kalmıyor devrân-ı zaman.

........Neyi var neyi yok,sordum dünyayı,

........Üstü açık dibi derin bir kuyu', 'Kaşımın altında,gözler yan yana, Düşündüm dünyadan,ne kalır bana. Hayat dersi verir,dünya insana. ........Neyi var neyi yok,sordum dünyayı, ...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sordum-dunyayi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gül', 'bir-gul-yakup-aydogan-ugiyr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne zaman sana yaklaşmaya kalksam,

Ne zaman seninle yan yana gelsek,

O zaman ürkek bir ceylan gibi kaçtın,

Oysa ki ben ne kadar saf ve temiz,

Bembeyaz bir aşkla sevdim seni.

Tıpkı bir kar tanesinin saflığıyla sevdim.

Ne olurdu sen de sevseydin,

Beni bir gün güldürseydin,

Beni sarp bir kayalığın önüne itmeseydin.

Vakit geç değil beni hala kurtarabilirsin,

Bu kayalığın önünden çekebilirsin.

Sen beni kurtarmasan da bu kalbim,

Hala seni sevmeye devam edecek,

Öldüğümde bile kavuşacağımız anı bekleyeceğim.

Eğer bir gün mezarlıktan geçersen,

Bil ki üstünde kırmızı bir gül açmış mezar,

Bil ki o benim mezarımdır.

O kırmızı gül sana armağanımdır.', 'Ne zaman sana yaklaşmaya kalksam, Ne zaman seninle yan yana gelsek, O zaman ürkek bir ceylan gibi kaçtın, Oysa ki ben ne kadar saf ve temiz,...', ARRAY['Türk Edebiyatı','Şiir','Yakup Aydoğan']::text[], 8.5, '{"poet":"Yakup Aydoğan","poet_slug":"yakup-aydogan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bir-gul-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elveda Gülüm', 'elveda-gulum-yakup-aydogan-263kc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir gece sen uyurken,

Yalnızlık şarkısı söyleyip

O hiç bilmediğim sokağın

O hiç bilmediğim evinin önünden geçeceğim.

Ama sen görmeyeceksin...

Bir sabah,

Yine karşılaşacağız seninle,

Yine merhaba deyip, konuşacağız belki de,

İçimdeki sana dokunmak arzusunu,

Dizginleyeceğim kendi elimle,

Hayalinde tutacağım ellerini,

Ama sen hissetmeyeceksin...

Bir akşam üstü,

Bir kadeh koyacağım masama,

Bir de senin için...

Kadehinle dertleşeceğim,

Hatta alacağım yanıma,

Ona seni sevdiğimi söyleyeceğim,

Ama sen bilmeyeceksin...

Bir gün,

Gideceğim bu şehirden,

Bütün güzellikler seninle kalacak.

Sonra arkama dönüp

Sana ''Elveda gülüm'' diyeceğim,

Ama sen duymayacaksın...', 'Bir gece sen uyurken, Yalnızlık şarkısı söyleyip O hiç bilmediğim sokağın O hiç bilmediğim evinin önünden geçeceğim. Ama sen görmeyeceksin.....', ARRAY['Türk Edebiyatı','Şiir','Yakup Aydoğan']::text[], 8.5, '{"poet":"Yakup Aydoğan","poet_slug":"yakup-aydogan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/elveda-gulum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kâlbinle Bir Görsen', 'k-lbinle-bir-gorsen-yusuf-onder-bahceci-1ryyh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevipte alamazsan, seviyorum diyemezsen, eremezsen,

Buruk bir tad, buruk bir lezzetdir, seviyorum diyemezsen,

Önder''im be, sen istediğin kadar, böyle mısraları dizsen, 

Nâzlı yârim ben öldükten sonra hergün mezarıma gelsen,

Ruhum sana bakar, Mevlam izin verir kâlbinle bir görsen....', 'Sevipte alamazsan, seviyorum diyemezsen, eremezsen, Buruk bir tad, buruk bir lezzetdir, seviyorum diyemezsen, Önder''im be, sen istediğin kad...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kalbinle-bir-gorsen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '10 ''Hu! '' de ve Kapaklan 1+', '10-hu-de-ve-kapaklan-1-ahmet-yozgat-3dxgg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '1/:

Ya Yakhya! 

Dokunma Meryem''ine Yarusalem''in...

Bil ki meyveye durma anı gelmiştir çorak diyarda,

Ay ışığından izindir sana ey kavruk adam, git.

Ama sakındığın gölgen iz bırakır sanma,

Suların zemini dahi oynak yüzünde. Yine de yürü! ...

Bakarsın gözlerinin ıslaklığını tanır yağmurlu bulut.

Saklama cenaze alayında karadutlarını ağaçların.

Belki de güzelliğine yanmıştır Kara Ali ölümün,

Ben ve bütün geçmişim bilmeyiz, Nedir aşkın lisanı? ...

Onu kendine sormak gerek ölüler zenatkarının.

Belki de saklanmış çirkinliklerde aşk vardır. 

Kim bilebilir yazgını esrarını? 

Eğer ya Yakhya masallardan geliyorsa esriktir,

Bütün şiirler, beyit yurdu yüreklerde.

Beynimizdeki bahçe ağaçlarının yavrusu ise,

İrem bağımızdadır Babil''den bu yana. 

Sakın beyaz çiçeklerini kirletme sabahın,

Mora keser çünkü ak çarşaf ve gökyüzü,

Alacakaranlık şafakta geri dönmemecesine,

Eğer koygun bir geceye açarsa yürek hududunu,

Kaçağa keser aşk ve ışk''ın seyyahları omuz omuza.

Haksızlıktır biliriz ki karşılıksı sevdalar o diyarı kenan''da, 

Ve gelip de gidecek kanat bulamamak Babil''e oysa.

Yani ya Yakhya bil ki, geridekilerini alamamanın acısı arkadan,

Ve önden gelir yaşamın ğöğ ekini.

Öteki kendini,

Bırakmıştın ya vaktin son karesinde bir kozmik düğün öncesi,

Bağırıyordum gördün ya, Ya Yakhya,

İşte böyle bir kaçkın eyvahı içerek yani.

Oysa daha çok yanacak mağma vardı son hudutta,

Ya da ateş fışkıran kuyu-yu gayya...

İşte böyle asayiş ey Yakhya.

Haydi! 

Hu de ve kapaklansana...', '1/: Ya Yakhya!  Dokunma Meryem''ine Yarusalem''in... Bil ki meyveye durma anı gelmiştir çorak diyarda, Ay ışığından izindir sana ey kavruk ada...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/10-hu-de-ve-kapaklan-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '10 ''Hu! '' de ve Kapaklan 2', '10-hu-de-ve-kapaklan-2-ahmet-yozgat-oo74n', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1a/: 

Ey çöllere hükmeden adam...

''Hu! '' de ve kapaklan... 

Ya Yakhya! Ben de o analardan birinin öksüzüyüm. Dilsizim say ki. Lalım. Elsizim. Adak ekmeklerini kendi ellerinle yedir bana. Kandır aç zamanlarımı. Kendir ek saçlarımın bozlaklı sokaklarına. Eski zamanlardan develerin sırtında an taşı. Arayayım denklerini. Aranayım. Üç gözlü insanlar kentindeki tapınakta bulayım seni. Şakirdin olayım istemesen de. Her septembır günü adanan kurbanın var mı? Ona banayım işaret parmağımı gürleyerek. On iki oymağını simgeleyen on iki kutsal ekmek midir bana yedirdiğin? Bileyim. Nedir dediğin? Dibine kadar anlayayım. Kağnılarla inanlı taşıyayım Kaf dağlarından. Analarından izin alayım koşuşan çocukların. Zeytin ve sedir kozalağı sunayım senin adına. 

Omuzlarına iğde dalı asayım. 

1b/:

Ya Yakhya! ...

Senin için yas tutayım.

Ben de bileyim Ya Yakhya,

Sırrını uzaklardaki maveranın.

Bileyim ve iman edeyim söğütlerin canına. 

Sanırım çöl ağlar kendi bahtına,

Her devri dehrde güneş ağlar ışığını. 

Annelerse kendi Yakhya''sına ağlar.

Sense mühürle enfusi sırlarını,

Mührü Süleyman''ımla ateşte kızartarak.

Dön ve hönkür semadaki yanık yüzlü sarışın aya...

''Amin'' de ve çekil ya Yakhya.', '1a/:  Ey çöllere hükmeden adam... ''Hu! '' de ve kapaklan...  Ya Yakhya! Ben de o analardan birinin öksüzüyüm. Dilsizim say ki. Lalım. Elsizim...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/10-hu-de-ve-kapaklan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülümse İstanbul', 'gulumse-i-stanbul-yakup-aydogan-n33ug', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çok oldu görüşmeyeli İstanbul

Kokunu almayalı çok oldu

Artık haritalardan bakabiliyorum sana

Acaba hala aynı mısın? 

Hala yaşıyor musun İstanbul? 

İzmirden çıktım yola bugün

Bugün bambaşka bir gün

Başka bir zaman, başka bir sabah

Ben giderken ağlıyordun istanbul

Hala ağlıyor musun? 

Gülümse İstanbul, gülümse bana

Hadi kalk artık uyansana

Cıvıl cıvıl olmanı istiyorum

Aç gözünü İstanbul

Seni görmeye geliyorum...', 'Çok oldu görüşmeyeli İstanbul Kokunu almayalı çok oldu Artık haritalardan bakabiliyorum sana Acaba hala aynı mısın?  Hala yaşıyor musun İsta...', ARRAY['Türk Edebiyatı','Şiir','Yakup Aydoğan']::text[], 8.5, '{"poet":"Yakup Aydoğan","poet_slug":"yakup-aydogan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gulumse-istanbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '10 Kara Alisi Acemi Kisra''nın 1', '10-kara-alisi-acemi-kisra-nin-1-ahmet-yozgat-lv5b3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '1/:

Ya Yakhya! 

Dokunma Meryem''ine Yarusalem''in...

İşte vurgun yayla ve işte vurgun çöl

Şimdi gezinir usta eller Gobi''nin yüreğinde.

Ki o eller ki,

Zaman zaman arz kutürü avındadır,

Bazen de şıhablar önünde cennet kaçkını.

Her yanı yara beredir 

Kara madde ile pansumanı yapılmış,

Kapışılmış bir mezat tezgahında,

Eğri hurma dalından yayı,

Ve aslan sırımından kirişi...

Ya kara Alisi Acemi Kisranın? 

Hüsranın haznedarıdır o,

Ellerinden anti madde saçılır,

Taberiya gölünün bereketli derununa,

Her yerinde bir tandır açılır

Zenzibar''ın göz alan saraylarının,

Dökülür cümle ''Harbiya! '' diyenleri.

Yani kara Alilerin kirli elleri,

Birer gayya ağzıdır

Dökülense bu vadiye vahşi çağlayandır.

Yalandır geçmişe dair destan yazanlar 

Çünkü dızmanların tek içecekleri kandır

Ya da ateş fışkıran kuyu-yu gayya

Ey Yakhya...', '1/: Ya Yakhya!  Dokunma Meryem''ine Yarusalem''in... İşte vurgun yayla ve işte vurgun çöl Şimdi gezinir usta eller Gobi''nin yüreğinde. Ki o el...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/10-kara-alisi-acemi-kisra-nin-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '10 Kara Alisi Acemi Kisra''nın 2', '10-kara-alisi-acemi-kisra-nin-2-ahmet-yozgat-vbxu4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '1a/: 

Ay takla atar. 

Zöhre kararır çıra isinde. 

İsminde ''el'' olan onları aklar.

''Hu! '' de ve kapaklan... 

Ey Yakhya de, aklından geçen aklanma nasıldır? Doğurur mu doğruluk sahte vilayetlerin hududunda? Vicdan ve adalet sözcükleri seğirir mi hiç? Yürür mü sabaha karşı mesela? Arnavutça''da nasıl söylenir put yontucularına lanet? Aynı kökten türetilmiş canlı Adem''in nesi olur? Ya da benim nem olur Bahira? Sözcüklerin tahıllar arasında nedir karşılığı? Kaç ölçektir buğday Babil''de? Alfa kaç gözlüdür? Alfabenin ilk harfi olan adamın ikinci harfi kaçıncı harftir genel anlamda? Beta kaç çocuk babasıdır? Ya da omega kimin kocasıdır? Başlangıç simgesi olarak kullanılırsa kaç hücresi vardır cifirin? Ters öküz başı nasıl seslenir yandaşlarına? 

Dön ve hönkür semadaki yanık yüzlü sarışın aya...

''Amin'' de ve çekil ya Yakhya.', '1a/:  Ay takla atar.  Zöhre kararır çıra isinde.  İsminde ''el'' olan onları aklar. ''Hu! '' de ve kapaklan...  Ey Yakhya de, aklından geçen akl...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/10-kara-alisi-acemi-kisra-nin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoksun Bende', 'yoksun-bende-sair-darknesslady-9n7iq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir sen vardın içimde senden öte

Sevgiyle, özlemle, hasretle,

Sabırla büyüttüğüm...

Bir sen vardın içimde senden öte 

Her  kavgada içimden

Bir parçasını alıp götürdüğün...

Bir sen vardın içimde

her sözünle gün be gün 

öldürdüğün...

Hani bir sen vardı ya içimde

Arama artık onu... Bulamazsın bende.', 'Bir sen vardın içimde senden öte Sevgiyle, özlemle, hasretle, Sabırla büyüttüğüm... Bir sen vardın içimde senden öte  Her  kavgada içimden B...', ARRAY['Türk Edebiyatı','Şiir','Şair Darknesslady']::text[], 8.5, '{"poet":"Şair Darknesslady","poet_slug":"sair-darknesslady","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yoksun-bende-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '10 Ateş Fışkıran Kuyuyu Gayya 1', '10-ates-fiskiran-kuyuyu-gayya-1-ahmet-yozgat-sfvsw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '1/:

Ya Yakhya! 

Dokunma Meryem''ine Yarusalem''in...

Yazdan kalma bir andır bu şehir,

Ya da kehribarıdır yasak sevdaların. 

Sarhoşlar oturursa üzüm damlalarının ekvatoruna, 

Ağaç gölgesinden vaz geçer mi çöl kaçkını? 

Kaç defa sonbahar görürsün bilinmez? 

Ama doğanın farkındadır yaprakların bilgesi. 

Gurbet akşamlarında üşümüşse,

Ve titremeye durmuşsa sensiz zamanlar,

Bazen bir kırağı saçlarına,

Bazen de ak düşer bahtına saharada...

Ya da ateş fışkıran kuyu-yu gayya.

Ey Yakhya...', '1/: Ya Yakhya!  Dokunma Meryem''ine Yarusalem''in... Yazdan kalma bir andır bu şehir, Ya da kehribarıdır yasak sevdaların.  Sarhoşlar oturursa...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/10-ates-fiskiran-kuyuyu-gayya-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '10 Ateş Fışkıran Kuyuyu Gayya 2', '10-ates-fiskiran-kuyuyu-gayya-2-ahmet-yozgat-sf6d9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '1a/: 

Sen başındasın her daim sırça burçların,

Bense son sayfalarındayım seyahatimin.

Burada tozlarına bulanırım,

Ve öğütlerinin koygun beyitlerine.

Dalgalar bilmez ki,

Denizin ve aşkın bittiğini.

Benim ağladığımı anlamaz ki,

Kara Ali ve sahilde kumlar,

Vahalarda hurmalar yanmaya durur aşkla.

Tandırlar yüreğimi sürgüne yollar.

İşte o sıra kor olurum mülteci diyarlarda.

Ya da ateş fışkıran kuyu-yu gayya...

Ey Yakhya...

1b/: 

''Amin'' de ve çekil Ya Yakhya. 

Ey kenan''ı nurla sıvayan asil. Mavi kan. Majestik... Böyle zamanlarda dururum çadırımın eşiğinde. Bir yanımda karım durur. Diğer yanında evlatlarım. Beşiğinde ağlamada kimi. Kimi kendi aşığ oyununu oynamada. Dalarım ufuklara. Aslında ufuklar bana dalar. Yalar kulaklarımı o kuzeyli barak. Oturarak dinleriz. Hepimiz. Yani bütün çadır ehli. Ya da ehli zaman. Ne zaman Yakhya? Ne zaman yırtılır kibir? Kubur ne zaman deşilir. İranice''de ''öyle olsun'' anlamına gelen sözcüğü anımsarım. Ya sen? Duaların sonunda beni anar mısın? Ya da Adem''i anımsar mısın? Öyleyse ''Hu! '' de ve kapaklan... 

1c/:

Bilirim bütün çöller ağlar kendi bahtına. 

Annelerse kendi Yakhya''sına ağlar.

Dağlar uğunur,

Ya Yakhya! ...

Çağlar nehirler...

Her şey akar artık kendi mecrasında.

Artık sen de ''Amin'' de ve çekil Ya Yakhya.', '1a/:  Sen başındasın her daim sırça burçların, Bense son sayfalarındayım seyahatimin. Burada tozlarına bulanırım, Ve öğütlerinin koygun beyi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/10-ates-fiskiran-kuyuyu-gayya-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '10 Bir Palaska Deliğidir Yaşamak 1', '10-bir-palaska-deligidir-yasamak-1-ahmet-yozgat-5am19', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1/:

Ya Yakhya! 

Dokunma Meryem''ine Yarusalem''in...

Umuduna eğilmek zordur harp yetimlerinin. 

Zamanın tek çıkar yoludur,

Kurumak gün ışığında. 

Dilekler tuttuğumuzda ölüm üstüne, 

Bileklerimiz utanır ya intiharından.

Umutlarımız varsa eğer dillenir çiçekler, 

Can suyu umar bizden diktiğimiz fikirler. 

Oysa hiç bitmeyen ve solmayan, Bir koygun ağıttır,

Zalimin ve Kara Ali''nin anıları...

Pencere köşelerinde yer tutan suret, 

Utanır içten içe...

Düşler kaç gece, 

Saklı kalabilir ki uykunun meydanı siyasetinde? 

Dalar ve yanarız deneyimsiz hayallere,

Daldığımız yer bir yaşanmamış yaşamdır,

Bir palaska deliğidir ya da...

Veya ateş fışkıran kuyu-yu gayya...

Ey Yakhya...', '1/: Ya Yakhya!  Dokunma Meryem''ine Yarusalem''in... Umuduna eğilmek zordur harp yetimlerinin.  Zamanın tek çıkar yoludur, Kurumak gün ışığınd...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/10-bir-palaska-deligidir-yasamak-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıllar Sonra Anladım Çaresizliğimi', 'yillar-sonra-anladim-caresizligimi-yusuf-onder-bahceci-y7trm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yıllar sonra anladım çaresizliğimi, ümitsizliğimi,

Eller ayırdı biliyorum, Allah''ımın, bana verdiğini,

Bütün Dünya bir araya gelse bilemez çektiğimi,

Yıllar sonra anladım çaresizliğimi, ümitsizliğimi....', 'Yıllar sonra anladım çaresizliğimi, ümitsizliğimi, Eller ayırdı biliyorum, Allah''ımın, bana verdiğini, Bütün Dünya bir araya gelse bilemez ç...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yillar-sonra-anladim-caresizligimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '10 Bir Palaska Deliğidir Yaşamak 2', '10-bir-palaska-deligidir-yasamak-2-ahmet-yozgat-42hnh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '1a/: 

Kimdir adil olan? 

Salayım kendimi onun adaletli çayırlarına. 

Put yontucusu Harentik''e uğrayayım. 

Son putunu da kırayım. 

Aklamak nedir kirli nehirleri? 

Ve avlamak ebabilleri, anlayayım. 

Nasıl olur dans etmek zamanlarla? 

''Amin'' de ve çekil Ya Yakhya. 

Ey Yakhya sana göre neye denir kıyamet diye? Tüm insanlar günah işlemiş midir mesela? Ve ilahi gazaba uğrayıp mahkûm olmuşlar mıdır cehennemde gayyaya? Ne var ki şu anda ellerinde zaafiyet. Kazan kaynatmada canibi kumkumaların? Sorarım hep kendime: Kendileri uğruna uğuldayan dağların, neden ağlamaz bulutların uğruna? Bu bir sorunsa... ''Hu! '' de ve kapaklan... 

1b/:

Ya Yakhya! ...

Kim bakar bu konuya? 

Çöl ağlar kendi bahtına. 

Annelerse ağlar kendi Yakhya''sına. 

Ya Yakhya Beg, günahsız bir yaşam sürmüşse havariler öperim ellerinden ve kertenkele dilli kemerlerinden. Çünkü cezalarını çekmek için Kenan''da ölmüş olan, bilirim böyle ister. Şarap sıkıcısı iman ederse eğer... Ne olur dersin? Şıra sirkeye döner Ya Yakhya. Belki de bu cezayı çekilmiş sayar sahibi zaman. İman edenleri doğru ve suçsuz kabul eder mi onu bilmem. 

1c/:

Başka bir deyişle Yakhya, sen sen değilsin 

Cehennem söner mi mesela duysa adını? ... 

Unutma ki denizler de ölür. 

Tuzlu ve acı Lut olur yalvaç pınarı. 

Ancak denizler ölse de su umut olur.

Ne olsun daha? 

''Amin'' de ve çekil Ya Yakhya.', '1a/:  Kimdir adil olan?  Salayım kendimi onun adaletli çayırlarına.  Put yontucusu Harentik''e uğrayayım.  Son putunu da kırayım.  Aklamak ne...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/10-bir-palaska-deligidir-yasamak-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '10 Güneşte Çivilenip Kalmak 1', '10-guneste-civilenip-kalmak-1-ahmet-yozgat-re02p', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '1/:

Ya Yakhya! 

Dokunma Meryem''ine Yarusalem''in...

İstedim ki dudaklarından geçsin katarım, 

Yürüsün söz yüklü kafilelerle...

Uzun bir kışın sıcak yüzünü bilir üşüyen, 

Yani kurtlara sormak gerek karın türküsünü. 

Der ki karla beslenen bilge:

''Yorganı sıcak olmaz,

Zemheride yatanın...''

Yani Ya Yakhya uzakların,

Sessizliğine aldanmak şanıdır gezginlerin

Yakınları ıssız kılmazsa yavan bir öykü... 

Şimdi çocuklar bile çileyi tanır. 

Yaşlı şerbetler içer beşiğinde bebeler.

İlk kez dediğini sandığın alfabede bile, 

Her şeyin sonuncusundadır aslında,

Her harfin yanağındaki kara ter.

Sil gözlerini sen de Kara Ali, 

Temmuzun yutucu eteğiyle.

Ve adının solmasın parlak zehebi,

Güneşte çivilenip kalarak.

Işığa aldanarak ya da,

Veya ateş fışkıran kuyu-yu gayya

Ey Yakhya...', '1/: Ya Yakhya!  Dokunma Meryem''ine Yarusalem''in... İstedim ki dudaklarından geçsin katarım,  Yürüsün söz yüklü kafilelerle... Uzun bir kışın...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/10-guneste-civilenip-kalmak-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Can Arkadaşım', 'can-arkadasim-yakup-aydogan-h9kmw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'O yıllarda her şey viran

O yıllarda her şey dağınıktı

Hayat hep siyah beyaz akardı

Akşamları langırt bilardo kavgalarını

Hep çalıkuşu kıraathanesi saklardı....

Çiçekli bakkal önündeki.... sohbetlerimize

Tek tanık...yıldızlar vardı..

Kuyruklusu...saman yolu olanı...

Ben hep.....tek başına olanları......

Silik duranları seçer.....sonrada....

Şiirler yazar...şiirler okurdum......

Dertlerimizi arşa çıkarır....

Ağlamaklı halimize naralar atar

Kahkahalarımızı yetmişikinci sokaktan

Yüzyirmialtıncı sokağa salardık...

Bu durumdan....

Kimileri şikayetçi..kimileri halimize imrenirdi...

İmrenirdi,,ya,,,

Hatırlarmısın hayallerimizi

Cepte metelik yoktu.....

Yolda duran külüstür otomobillere

Kurduğumuz hayalleri

Hani? ...tavuklar bile kümes yapmazdı

Sağı solu altı üstü pas ve çürük içindeki

Kırmızı otomobili....

Yada ayaklarımızın içinin kar suyundan vıcık vıcık olduğunu 

İliklerimize kadar donup titreye titreye dolaştığımızı

Hani bir sevda üstüne yazdıklarımızı

Sonrada üç beş bira ile seni esir aldığımı 

Söyle koçum bir daha bir daha söyle diye hıçkırıklara boğulduğumu

Sonrası yüzyirmialtıncı sokaktaki hicran naralarımı

Kırdığım üstüme başıma dökülen o bira şişelerini...

Sabahlara dek voltaladığımız site yıldızın taşlı tozlu sokaklarını hatırlarmısın? ....

Yollardaki maymunluklarımızı kahkahalarımızı

Ya köşedeki ağlamaklı hallerimizi 

İçimize kan kustuğumuz o tatlı acı dolu acayip duygularımızı

Karlar altında ki şehrin....sadece ay ışıgında ki o muhteşem halinde

Kurduğumuz masmavi...bembeyaz o çok temiz masum hayallerimizi....

Hatırlamazmısın....tabiki hatırlarsın.....bunlar bizim en güzel yıllarımızdı.....

Arabesk bilir ama pek dinlemezdin......

ta ki....o yüreğinin ortasındaki yangın volkanlara dönüştüğü ana kadar...

ah! ...kardeşim......biz bu yüzden mi hep dertler insanı olduk.....ha...

dertler insanı.....sen ben hep bu yüzden derdimizden olduk dertler insanı

dinmek bilmeden kanayan yürek yaralarımız bizi çok üzdü....

bu anlarda hep birlikte olur...birlikte sorgulardık....duygularımızı...

birden eserdi...bir gece yarısı yada sabaha karşı..hiç farketmez..yürürdük..

az uzda değil iki saat sonra hep o mekan orası hep öyle kaldı.....

ulus heykel....civarı bizi iyi bilirdi....esasında....sadece telefon kulübeleri...tanırdı..çok ağıtlarımıza tanık olmuşlar....telefonu sert kapamamıza alışmışlardı....

nede olsa onlar soğuk kış günlerinde sığındığımız küçük kulübeler

aşk fısıltıları söylediğimiz.....en şeker villalarımızdı.....kulübe palas,

sonrası....hep aynı hikaye kırık kalpler sokağı yüzyirmialtıncı sokak....., 

bir aşşağı bir yukarı.....ay ışığında ki türkülerimiz...şarkılarımız

türlü türlü masum hayallerimiz.....

_____Hatırlarmısın can arkadaşım birbirimize sığınışlarımızı...........

artık nerdeyse şafak söker...biz ayrılmak istemezdik

ne tuaf....şimdi bir çay içmeye vakit ayırmıyoruz...

o soğuk kış günlerinde önce beni eve bırakır...

sonra sen salınırdın....şirintepeye doğru...

arkandan kaybolana kadar sana bakardım....

bilirdim aslan gibiydin..bir şey olmazdı...

ama ben yinede endişelenir....sabah ilk iş sana uğrardım.....

hemen tok olup olmamamı saymaz...ekmek kızartır yağ ve peynir sürerdin.....

üf! ..ne güzel olurdu....valla hiç hayır demezdim.....

üstüne bir demlik çay az gelirdi...

sonrası malum...hayallerimiz başlardı...

aşklarımızı anlatır....garipliğimizi hiçe sayılmışlığımızı sorgular dururduk...

hiç ayrılmazdık....ben sende sen bende kendimizi unutur dururduk...

aslında en hoşumuza gidende buydu....

can kardeşim bu yanlarımızla...bu günlere geldik....

sadece biz biliriz...cidden zor geldik..

öldük öldük dirildik.....

çok aç kaldık hep sustuk hiç söylemedik.... 

ne derin mevzudur bu....

bunu bir sen bir de ben iyi biliriz....

yıllar böyle birbirini kovaladı gitti...

ben hercaice yaşarken...sen izdivaya çekilmiş...

kendi halinde..kendi doğrularınla....birlikte yaşıyordun...

biliyormusun bu halin...en sevdiğim...en doğru yanındı...

seninle ne çok şeyler paylaştık..duygu sellerinde ne çok boğulduk...

ne çok güldük..ne çok ağladık....ne çok yandık....

az isyan etmedik kadere......

yaşadıklarımızı...ne kalın romanlar anlatır..nede benim yazacağım.....binlerce dizeler.....

biliyorum..biliyorsun....yazsam....hayat yetmez...

ve yıllar bizi sürükledi...bugünlere getirdi....

hani az feleğin çemberinde,,,,

değirmen taşı misali...un ufakta etmedi değil....

neyse can kardeşim...yaşadıklarımız...bir tesadüften ibaretmi? ..yoksa kaderin bir cilvesimi? ..bilmiyorum..

tek bildiğim şu an yanımda olman.......

sana isyan kaldırıyor...sana kahrediyorum...

böyle mi olmalıydık...Allahaşkına nerdesin ya,,,

duysana sesimi kafamı taşlara duvarlara vuracağım...

söyle..... buraları dağıtsam kaç yazar? ....ha..

ölüyorum..ANLASANA? ...

Eriyorum bitiyorum görsene

Dağıldım gidiyorum nerdesin

Nerdesin can arkadaşım

Koptum darmadağın oldum....

Bu kadar duyarsız olmana katlanamıyorum...

Hırsımdan şimdi..çatlayacağım

Görsene kardeşin kan kardeşin ölüyor

Sarılsana boynuma ağlama desene

Budala mahvoluyorum görmüyormusun

Beni senden başka kim anlar

Kim anlar gözyaşlarımı yüreğimi

İçimdeki yangınlarımı söyleeee...kim kim..? ..anlar

Anlamıyormusun bu büyük...depremi..........

Bittim! ! ! BİTTİ! ........

İçimdeki.....artçı sancıları anlamıyormusun...

Darmadağın perişanım şimdi...............

Ne soranım ne sırdaşım...nede teselli veren

Bu merhemsiz derdin...dermanı olan yok..

Ay ışığında...yıldızları sayacağım...şiirler okuyup ağlayacağım kimsem yok......

Yalan insanlar.....gibi....yoksa..yoksa.......yok...yok....

Anla artık.......gözlerime bak....

Yürüyüşüme,,sessizliğime 

Karşında eriyişime...

Sesimin titrekliğine kulak ver

Bazen ani çıkışlarımdan....hiddetimden anla

Bitiyorum...kör....gör artık....kardeşin ölüyor...

Bak şimdi yoksun....bu sen olamazsın

Ne oldu sana? ...

Hani beni anlayan tek sen vardın

Hani ilk adımdan sonrakini bir sen bilirdin

Nerdesin? ... kahretsin nerdesin? .....

Bak bu duvarlar hafif kalıyor...un ufak oldular

İsyanım çılgınlığım bir türlü dinmiyor

Döksene kafamdan aşşağı buz gibi suları

Gör bee...artık ölüyorum gör artık

Biliyormusun.....kimseyi senden başka kimseyi yanımda istemiyorum

Bugün yanımda sen olmalısın evet sen...sen olmalısın

AMA YOKSUN YOKSUN KAHRETSİN

Duyarsız nedir senin sorunun

Bir derdin mi var 

Benden önemlimi benden ilerimi

Bak yaşayan ceset gibiyim....

Mahvoluyorum.....mahvediyorsun...

Halen görmüyorsun....can çekiştiğimi

Sana olan düşkünlüğümü bilmiyormusun

Bu sen olamazsın....bu benim can kardeşim olamaz...

Yok yok sen bendende dertlisin....

Ben kendimi unuttum....

Söyle nedir derdin...anlat ben yanında olurum....

Vallahi billahi benim bir şeyim yok..

Umursama...takma kafana...

Ben hep böyle ajitasyon takılan

Bunalım adamın tekiyim..

Ben duyguların adamı

Yalnızın derbederin tekiyim...

Bitti bende duygular...

Artık yalnız acılar var...

Böyle iç çektiğime bakıp...öyle durma

Sana dayanamam...ağlama...ağlama

Bak bende ağlamıyorum...

İkimizde dimdik ayaktayız

Sonsuza dek birlikte omuz omuza yanyanayız...

Canız kanız kardeşiz kankardeş.......

ALLAH, ALLAH dayanamıyorum......', 'O yıllarda her şey viran O yıllarda her şey dağınıktı Hayat hep siyah beyaz akardı Akşamları langırt bilardo kavgalarını Hep çalıkuşu kıraat...', ARRAY['Türk Edebiyatı','Şiir','Yakup Aydoğan']::text[], 8.5, '{"poet":"Yakup Aydoğan","poet_slug":"yakup-aydogan","theme":"Türk Şiiri","is_hero":false,"total_lines":157,"source_url":"https://www.antoloji.com/can-arkadasim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '10 Güneşte Çivilenip Kalmak 2', '10-guneste-civilenip-kalmak-2-ahmet-yozgat-04qkv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '1a/: 

Her diyarda türkü söylenir. 

Duyan duyar o davudi sesi. 

''Uyan'' denir her devri fetrette gafillere. 

Ey Yakhya in sarayının mermer merdivenlerinden. Fillere yem at yıldız çayırlarından. Aslanların musuluna fil eti... Ya da taş at Ebrehe üzerine. Bin birinci ebabil olarak. Esinlenme kısmında kalsın savların ama. Karalanmış kağıtların lordu Opdaselam için bir unvan olarak kullanılan bir sözcük bul. Sadık kim? Sadakat ne? Güvenilirlik uzak bir uluyuşu mudur muhariplerin? Ya da kılıçların şıkırtısı mı? O da değil. Bu da değil kanımca. Çünkü Yakhya... Her şey ikinci anlamındadır aslında. Bu durumda ''Hu! '' de ve kapaklan... 

1b/:

Ya Yakhya! ...

Kanla paraf edilir antlaşma.

Sulh kendini yer acıkırsa,

Harpse her daim tok tutar,

Kanla beslenen sürüleri.

Kanımıza ekmek doğranır bir daha... 

''Amin'' de ve çekil Ya Yakhya.

Uzatma ey çöllerin serdarı bey oğlu bey

Artık sen de çekil ''Amin'' de de...', '1a/:  Her diyarda türkü söylenir.  Duyan duyar o davudi sesi.  ''Uyan'' denir her devri fetrette gafillere.  Ey Yakhya in sarayının mermer mer...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/10-guneste-civilenip-kalmak-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasıl Unutursun', 'nasil-unutursun-erdal-ozkan-79ynd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Biz ikimiz bir bütünüz

Al yüreğim sende dursun

Birlikte geçti ömrümüz

Beni nasıl unutursun

Bak yollarda izlerim ver

Bulutlarda gözlerim var

Her şarkıda sözlerim var

Beni nasıl unutursun

Gecelerde sırdaşım var

Yağmurlarda gözyaşım var

Öyle büyük bir aşkım var

Beni nasıl unutursun

Her şeyine razıyım ben

Kaderinde yazıyım ben

Silinmez bir maziyim ben

Beni nasıl unutursun.', 'Biz ikimiz bir bütünüz Al yüreğim sende dursun Birlikte geçti ömrümüz Beni nasıl unutursun Bak yollarda izlerim ver Bulutlarda gözlerim var ...', ARRAY['Türk Edebiyatı','Şiir','Erdal Özkan']::text[], 8.5, '{"poet":"Erdal Özkan","poet_slug":"erdal-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/nasil-unutursun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuş Kanadında', 'kus-kanadinda-damla-guven-fdf07', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sen hiç birşey bilmiyorsun; 

ne tren yolunda ağlayan o kadını,

ne o kadının valizinin aslında bomboş olduğunu...

sen ne biliyorsun! 

sadece gitmeyi bilirsin sen,

uzayan yollarda kaybolmayı,

yitip bitmeyi... 

sonra ansızın geri dönersin.

sen özlemeyi bilir misin? 

hiç özledin mi birini delice? 

hasret her gece gözlerinin içine baktı mı 

bir ilaç şişesinden? 

bilmiyorsun işte hiç birşey? 

sen sadece özlenirsin değil mi? 

özlem nedir diye sorsalar bu gelir aklına.

sen sevmeyi de bilmezsin,

en son ne zaman sevdin birini koşulsuz? 

ne zaman onun elleri oldu ellerin 

ve ne zaman onun gözleriyle uyudun? 

sen sadece sevildin. 

o yüzden hiç bilmedin birini sevmenin tadını,

hep bir kuş kanadıydı senin yüreğin. 

en son ne zaman konudun birinin omzuna? 

hep uçup gittin nereye gittiğini bilmeden 

ve her uçuşunda 

havalandı benim de yüreğim.

ama kırıktı kanatlarım,

ben uçamadım....', 'sen hiç birşey bilmiyorsun;  ne tren yolunda ağlayan o kadını, ne o kadının valizinin aslında bomboş olduğunu... sen ne biliyorsun!  sadece ...', ARRAY['Türk Edebiyatı','Şiir','Damla Güven']::text[], 8.5, '{"poet":"Damla Güven","poet_slug":"damla-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/kus-kanadinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '10 Astokriş Ararım Dizelerde 1', '10-astokris-ararim-dizelerde-1-ahmet-yozgat-5kobf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '1/:

Ya Yakhya! 

Dokunma Meryem''ine Yarusalem''in...

Ben hala bu şiirde saklı bir yürek peşindeyim, 

Bir astokriş ararım dizelerin başucunda.

Ağlıyor olacağım bel ki de Samanyolunda, 

Bulduğunda sen beni kırkıncı ayında ölümümün.

Bir dilektir ki tutulmuştur,

Zamanın ve insin ilk harfinde, 

Dünyanın üzerine doğan güneştir yaşamın özü,

Dağların özü ise şiirdeki aşktır.

Aşkın arkasında saklanmak tembel tembel,

Yakışmaz yakamozlu vadilere. 

Durursa mekansız bir zaman da,

Aman demek boştur.

Kara Ali''nin icraatı sonlanır,

Puslu bir vaha gibi dalar coğrafyaya, 

Yarar da ulaşır yüreğine kaderin şişi.

Geçtiği sislerden güneşler derer belki,

Belki de aşarak sıra dağlar doruğundan,

Varır yazgımız ikimizin,

Karanlık ve sakin yamaçlarına yüzümüzün. 

En olmadık aşkları içerek gider yürekler, 

Aşk bir şarkı gibi simetriktir, 

Ve kendi ezgisi üstünde ilerler.

Dalar en zayıf yerinden sabaha.

Ya da ateş fışkıran kuyu-yu gayya

Ey Yakhya...', '1/: Ya Yakhya!  Dokunma Meryem''ine Yarusalem''in... Ben hala bu şiirde saklı bir yürek peşindeyim,  Bir astokriş ararım dizelerin başucunda. ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/10-astokris-ararim-dizelerde-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '10 Astokriş Ararım Dizelerde 2', '10-astokris-ararim-dizelerde-2-ahmet-yozgat-h8o03', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '1a/: 

Devir Kerem devriydi. 

Yani herkes kendi kendine tutuşmada. 

Ve küllerinden doğmada her ins. 

Ve kaknüs. 

Yani simurg kuşu...

''Hu! '' de ve kapaklan... 

Aslan yeleli savaşçıların serdarının zamanında yaşamadık ki biz. Zümrüdüanka olalım. Ya Yakhya, hepimiz birer dövme kılıçlı savaşçı ya da ay boynuzlu kurbanız savaşlarda. Gün gelir olur olan. Halkıyla yaptığı tekellüm eskir Roma valisinin. Eski antlaşmadır elden ele dolanan kasımpatı çiçeği. Eski Ahit''se adı üstünde işte: Eski ahit. Kurban edilen her koyun helal değildir kanımca. Hayvanların kanıyla yürürlüğe girmiştir her savlaşma. Karsanya ülkesi bilir bunu Ya Yakhya. Çıkış nere peki? ... Bu tünel ne kadar ıslık çalar? Kimin için bükülür büklüm büklüm? De bildiğini. Bulutların saçlarını tarayan tarakdar erbabıdır işinin. Tarakdarın eli seğirir. İnsanlarla yaptığı yeni antlaşmayı tanımaz Romalılar. Kendi kanını akıtarak yürür Lut''ta bedevi sürüleri. 

1b/:

Ya Yakhya! ...

Elleri kınadır. 

Kandır gözleri.

Koymuştur onlar kendi adlarını. 

Ve göbeklerini kendileri kesmiştir. 

O sebepledir göklerin suskunluğu. 

Ay iki kez takla atar zaman yolculuğunda. 

Zöhre kararır çıra isinde güzelleşme uğruna. 

İsminde ''el'' olan onları aklar bir kez daha. 

Sen de ''Amin'' de ve çekil Ya Yakhya.', '1a/:  Devir Kerem devriydi.  Yani herkes kendi kendine tutuşmada.  Ve küllerinden doğmada her ins.  Ve kaknüs.  Yani simurg kuşu... ''Hu! '' d...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/10-astokris-ararim-dizelerde-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '10 Kara Ali Örs Başında 1', '10-kara-ali-ors-basinda-1-ahmet-yozgat-42wmz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '1/:

Ya Yakhya! 

Dokunma Meryem''ine Yarusalem''in...

Yutar bir gün kendini bu kudurgan seller.

Koyar göğsüne başını babasız çocuk,

Yüreğini dinler uzaktaki ıslı-ıssız vadinin.

Kendinin yüreğiyse atanda tanda,

Bir yanda kesme taştır zulüm,

Ölüm ise akşamdan önce aparat

Yani tütün altı kahvaltı öncesi.

Gölgesi düşman herkesin aslımna,

Kara Ali ise örs başında,

Öfkesini yıkmış,

İki kaşının arasındaki vadiye,

Şerareler kanatlanmada yeyip yer çekimini

Kendi hekimini yaralamada derman.

Say ki o anı ateş fışkıran kuyu-yu gayya...

Ey Yakhya...', '1/: Ya Yakhya!  Dokunma Meryem''ine Yarusalem''in... Yutar bir gün kendini bu kudurgan seller. Koyar göğsüne başını babasız çocuk, Yüreğini di...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/10-kara-ali-ors-basinda-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '10 Kara Ali Örs Başında 2', '10-kara-ali-ors-basinda-2-ahmet-yozgat-2s9nn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '1a/: 

Zamandır her boyutun ikizi.

Onun yüzündendir ay her ay bir kez döner,

Kendi ekvatorunda...

Çöllerse ağlar kendi bahtına. 

Anneler kendi Yakhya''sına ağlar.

Gün gelir sütliman olur Atlantik. 

Anlaşır çölle deniz...

Anlamıssan ''Hu! '' de ve kapaklan... 

Ya Yakhya, o antlaşma sandığını iyi sakla. Kumran mağaralarına göm. Ya da Lokman mağaralarına gizle. Ezoterik bir gizemle kapat ağzını. Testere dişi savaşçıların tanıklık çadırının ve ilk tapınmalarının en kutsal yerinde bulunan mermerleri kır. On Buyruğun yazılı olduğu taş levhalarla çevir avlunu. Kutsal emanetlerini kutsa. Ama ölçüdür çabuk kaçar. İçinde korunduğun sandık sadece emanettir sana Ya Yakhya. Acemi''ceyi unut. Antik çağda Gecerland''ın kuzeydoğusundaki bölgede türkü yakardı bir rahip ya... Bul onun kutsal notalarını. Çünkü orada oturan bir Tamil halkının konuştuğu konulardır burada yazılanlar. Tamiller o yüzden Elbasan beyi oldular. Bastılar eski vilayetleri. Etleri doğradılar.

Çöl ağlardı orada kendi bahtına. 

Anneler de ağlaşır kendi Yakhya''sına.

Dön ve hönkür semadaki yanık yüzlü sarışın aya...

''Amin'' de ve çekil ya Yakhya.', '1a/:  Zamandır her boyutun ikizi. Onun yüzündendir ay her ay bir kez döner, Kendi ekvatorunda... Çöllerse ağlar kendi bahtına.  Anneler kend...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/10-kara-ali-ors-basinda-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '10 Ölüm Zenaatkarına Teslimiz 1', '10-olum-zenaatkarina-teslimiz-1-ahmet-yozgat-mj6nv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '1/:

Ya Yakhya! 

Dokunma Meryem''ine Yarusalem''in...

Yağmurda ıslanan yürek bilir saçak altını.

Bir donmuş sevgili ateşe aşık olur.

Yabancı bir adam gibiysen bu son kentte, 

İçindeki kendine yoldaşlık edebilirsin. 

Yağmurları suçlamak bize mi düşmüş, 

Nisana saygısızlık sayılır karı kutsamak. 

Sormadan açılan kapıyı sahipsiz sanmak,

Ölüm zenaatkarına teslim olmaktır. 

Arkasında ne saklar bilinmez ay ve zöhre,

Leylekler geliyorsa göçünden aşkla, 

Bacaların hazırlanması yakın sayılır. 

Gökyüzünden düşen maviler ve kuş kanatları, 

Yaralı her yüreği mora boyar Ya Yakhya.

Anlatabilseydi seni dudağımın beyleri, 

Kendi tuvalinde şakağım şakısaydı,

Gölgeleri silinmiş olurdu ölüm beyinin. 

Bir asimetrik çizgi olurdu çizdiği,

Çiçeklerin renklerine banardı,

Elindeki son sultan fermanını. 

En çok arılar banar oysa,

Sonbahar akşamlarına...

Aşık olan her yürek bir güneşe döner,

Bir de yanık yüzlü sarışın aya. 

Ya da ateş fışkıran kuyu-yu gayya

Ey Yakhya...', '1/: Ya Yakhya!  Dokunma Meryem''ine Yarusalem''in... Yağmurda ıslanan yürek bilir saçak altını. Bir donmuş sevgili ateşe aşık olur. Yabancı bi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/10-olum-zenaatkarina-teslimiz-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulutlara Sor Söylesin', 'bulutlara-sor-soylesin-yusuf-onder-bahceci-eqz9b', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Senin için ağlıyorum vefasız gözlerimden bilirsin,

Senin için ağlıyorum hayırsız sözlerimden bilirsin,

Senin için ağlıyorum çaresizim çaresizim bilirsin,

Senin için ağlıyorum şu bulutlara bir sor söylesin......', 'Senin için ağlıyorum vefasız gözlerimden bilirsin, Senin için ağlıyorum hayırsız sözlerimden bilirsin, Senin için ağlıyorum çaresizim çaresi...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bulutlara-sor-soylesin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '10 Ölüm Zenaatkarına Teslimiz 2', '10-olum-zenaatkarina-teslimiz-2-ahmet-yozgat-thl2d', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1a/: 

Çöllerin koynunda uyuyan adam duy beni. 

Kefeni yırt.

''Hu! '' de ve kapaklan... 

Ya Yakhya! ...

Aryanice''ye benzeyen bir dilde okunur şiirimizin kriptosu. Başka lisanı unut. Bil ki... Yamalı bohçalar kahininin zamanında Kimmerya dulları Tahrani''ce yerine genellikle benim dilimi konuşurlardı. Şiir söyler ve cumbalardan bakışırlardı süzüm süzüm. Bekleşirlerdi gecenin yorgan altında. Mırıl mırıl dilleri kadim bir yazgıya bata çıka ilerlerdi. Sonra geldiği yönü unuturlardı. Ya Yakhya, neden işaret koymadın karanlıkların koynuna? Ve neden oymadın ışığın gözesini? Sıyırmadın neden soğuyan küllerini mağma diyarının? Zaman mı? Her zaman yetecek kadar vardır. Yani tam vaktidir şahmaranların gözünde yol almanın. Yürü ve ardınca yürüyelim. Gözümüze ışıktan kınalar sürünelim. Ellerimize sürme çekelim Hadramut''ta. Kara bir dutta bulalım aradığımız gözbebeklerimizi. Ne olsun daha? 

Ya sen Ya Yakhya? 

Devam mı susmaya? ...

Bilirim çöl ağlar kendi bahtına. 

Anneler kendi Yakhya''sına ağlar.

El sıkış zamanın muhafızıyla,

Artık sen de ''Amin'' de ve çekil Ya Yakhya.', '1a/:  Çöllerin koynunda uyuyan adam duy beni.  Kefeni yırt. ''Hu! '' de ve kapaklan...  Ya Yakhya! ... Aryanice''ye benzeyen bir dilde okunur ş...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/10-olum-zenaatkarina-teslimiz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '10 Bhutan Ülkesi Bir Daha Ölür 1', '10-bhutan-ulkesi-bir-daha-olur-1-ahmet-yozgat-pcl1c', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '1/:

Ya Yakhya! 

Dokunma Meryem''ine Yarusalem''in...

Zamana yolculuk planlayan Hızır''a danışır.

Kozmik meyveleri beyninin rafına dizer,

Hızır’a danışan bahçevan...

İliştirmelisin Ya Yakhya,

Şahsi meyveni kanatçığına bir Ebrehe ebabilinin.

Uzatma yolunu çöl bedevilerinin vahalardan. 

Sonraki sayfalara dalarak da girilir,

Şiir tutup kaldırır yerden hepimizi. 

Ve sen de kendini arayarak,

Bulursun içindeki ıssız çıkmazlarda.

Ya da ateş fışkıran kuyu-yu gayya.

Ey Yakhya...', '1/: Ya Yakhya!  Dokunma Meryem''ine Yarusalem''in... Zamana yolculuk planlayan Hızır''a danışır. Kozmik meyveleri beyninin rafına dizer, Hızır’...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/10-bhutan-ulkesi-bir-daha-olur-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül', 'gonul-erdal-ozkan-ryk4n', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Her güzelde hevesin var

Uslanmadın gitti gönül

Aşık olup sevesin var

Yaşlanmadın gitti gönül

Sevgilere hiç doymadın

Yetmezmi diye sormadın

Ben yoruldum sen durmadın

Dinlenmedin gitti gönül

Bir zaman taze gonca gül idim

Yıprattın beni şimdi çürüdüm

Sen hep uçtun bense yürüdüm

Beklemedin gitti gönül

Bu feryadım aman değil

Söylediğim yalan değil

Zaman eski zaman değil

Anlamadın gitti gönül.', 'Her güzelde hevesin var Uslanmadın gitti gönül Aşık olup sevesin var Yaşlanmadın gitti gönül Sevgilere hiç doymadın Yetmezmi diye sormadın B...', ARRAY['Türk Edebiyatı','Şiir','Erdal Özkan']::text[], 8.5, '{"poet":"Erdal Özkan","poet_slug":"erdal-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gonul-156-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '10 Bhutan Ülkesi Bir Daha Ölür 2', '10-bhutan-ulkesi-bir-daha-olur-2-ahmet-yozgat-vexcu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '1a/: 

Yamalı bohçalar kahininin zamanındaydık,

Kimmerya dulları Tahrani''ce yerine,

Benim dilimi konuşurlardı genellikle. 

Konuşur ve ağlaşırlardı.

Şiirlere kulp takarlardı elemden.

Kutup erirdi acılarını içerek.

Her engerek önce kendine akıtırdı zehrini.

Ben günah tüten ellerimi açardım.

Racalar mozolelerine hanımlarıyla gömülürdü.

Bhutan ülkesi her gün bir daha ölürdü.

Artık sen de ''Amin'' de ve çekil Ya Yakhya. 

1b/:

Kahramanlar selam durmada sana bak.

Selam al, ''Hu! '' de ve kapaklan... 

Ya Yakhya sana armağandır burada yazılanlar. Hatta Karakurum''da taşlara kazılanlar ruhsal armağanlardır. Kavmine geçmişten kalanlardır. Asya illeri şahittir buna. Bugünkü Anadolu türkü yakar üstüne. Ege bölgesi zeybek oynar ardından. Ayartıcı Şeytandır beni yalanlayacak olan ancak. Bal neye denir? Baal nedir? Baalbek nerenin vilayetidir? Sustun işte. Dinle. Eski Kenanlıların taptığı bir puttur Baal mesela. Baba büyük harfle yazıldığı zaman gerçek anlamındadır. Yani oğlunun yanındadır. 

Ayrıca Ey Yakhya Oğlu Yakhya,

Bunlar sana da,

Benim oğluma da aslında...

Artık sen de ''Amin'' de ve çekil Ya Yakhya.', '1a/:  Yamalı bohçalar kahininin zamanındaydık, Kimmerya dulları Tahrani''ce yerine, Benim dilimi konuşurlardı genellikle.  Konuşur ve ağlaşır...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/10-bhutan-ulkesi-bir-daha-olur-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '10 Özel Yasamızın Hammurabisi 1', '10-ozel-yasamizin-hammurabisi-1-ahmet-yozgat-emxxc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '1/:

Ya Yakhya! 

Dokunma Meryem''ine Yarusalem''in...

Hala yoksan ölüm zenaatkarının,

Yarınki listeyi icraatında,

İlerlediğin yol üstünde emniyettesindir.

Kurallardaki bomboş koridorlara,

Lacivert gölgeni düşüremezsin.

Uğraşma Ya Yakhya! 

Çünkü yayılırsa karanlık

Gölgelerin kanına ekmek basılır,

Asılır bir fikir daha meydanı siyasette,

Kara Ali''nin gürgen darına. 

Öylece sensiz kalır son fotoğraf karesi,

Soğuk bir güneşe yanar bütün anılar. 

Ağustos ezgileri yakılmaz zemheride,

Yanarız mor ağızlı bir kahıra.

Ya da ateş fışkıran kuyu-yu gayya.

Ya Yakhya! ...', '1/: Ya Yakhya!  Dokunma Meryem''ine Yarusalem''in... Hala yoksan ölüm zenaatkarının, Yarınki listeyi icraatında, İlerlediğin yol üstünde emniy...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/10-ozel-yasamizin-hammurabisi-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '10 Özel Yasamızın Hammurabisi 2', '10-ozel-yasamizin-hammurabisi-2-ahmet-yozgat-m8u8n', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '1a/:

Bu bölüm sürgüne dairdir. 

Babil kralı Nebukatnezar''sa kendi destanının Gılgameş''i. Özel kanununun Hammur abi''si yani. İ.Ö. bir yılda yontuldu taşlar. Başlar vuruldu. Duruldu bulanık sullar. Tunç kendi zamanında eridi. Biz ise devrildik ömrümüzün sonunda. Hayatının kırk birinci yılında ne olmuştu? Anımsa. Kırık mızraklıların başkentini zaptetmişti tabiidir ki büyük baban. Sararmış kağıtlar kentini ele geçirense sendin. Kendin verdin bilcümle kararını tarihin.

''Hu! '' de ve kapaklan... 

Yani attın kadim sayfalara bir çentik. 

Doldu zamanın kırbası zafer dilimiyle.

Gelimiyle sevindirdi son oğlun. 

Atlar yemlendi ışıktan ve mağmadan. 

Delirdi muharipler sevdalarıyla yatıp.

Artık...

Sefer vaktidir.

Sabaha yakın bir sırada...

''Amin'' de ve çekil Ya Yakhya.', '1a/: Bu bölüm sürgüne dairdir.  Babil kralı Nebukatnezar''sa kendi destanının Gılgameş''i. Özel kanununun Hammur abi''si yani. İ.Ö. bir yılda y...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/10-ozel-yasamizin-hammurabisi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adını Sen Koy', 'adini-sen-koy-ercan-tekin-hdynp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir his var içimde 

Bir titreme var 

Tüm vücudumum derinlerin de 

Üşütüyor beni havada sıcak hâlbuki

Kıpır kıpır tarifi yok bu heyecanın

Nedir ki bu 

Aşk değil kesinlikle

Adını sen koy 

Evet, nedir bu duygunun sebebi 

Neden üşüyor çarpan yüreğim sıcak havada 

Yağmur da yok neden titriyor

Adını sana bıraktım Yelda 

Adını sen koy bu tarifsiz titremenin 

Bu tarifsiz hissin adını sen koy sana bıraktım...', 'Bir his var içimde  Bir titreme var  Tüm vücudumum derinlerin de  Üşütüyor beni havada sıcak hâlbuki Kıpır kıpır tarifi yok bu heyecanın Ned...', ARRAY['Türk Edebiyatı','Şiir','Ercan Tekin']::text[], 8.5, '{"poet":"Ercan Tekin","poet_slug":"ercan-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/adini-sen-koy-51-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '10 Anam, Babam ve Şamil 1', '10-anam-babam-ve-samil-1-ahmet-yozgat-1z32a', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1/:

Ya Yakhya! 

Dokunma Meryem''ine Yarusalem''in...

Ağaçlar kutlu meyvelere dursun.

Ürününü yapraklarıyla örten incirdir, 

Ağacın güneşle güreşmek için çırpınışı boşadır

Farkını arama yaşadığın benzer karelerin,

İçindeki galaktik galeride Ya Yakhya, 

Biz hep böyleydik anam, babam ve Şamil, 

Ama görmüyorduk kamil olanı insanda.

Kendi ciğerimizden sızan aslanı tilki diye,

Gömüyorduk ölümün galerilerine.

Bana öğrettiklerin aslında özüydü kaselerin, 

İnsan kendinin öğrencisi olmalıymış meğerse. 

İstediğidir Kara ölüm zenaatkarının,

Bir doğanın arkadaşlığı ölenle... 

Eğer kalmışsa yüreğinde bir parça mavi,

Kırık gözyaşlarına bulamalısın onu. 

Islanman mukadderdir çünkü nisanda,

Burada bir insanda saklıysa aradığın, 

Bulunması pek güç demektir.

Çünkü gülüşüne salıncak diye kurulan,

Darı Kara Ali''dir. 

Binen uzağa gidemez,

Yükselemez kevser diyarına.

Her yol önce girer karanlıklara...

Ya da ateş fışkıran kuyu-yu gayya.

Ey Yakhya...', '1/: Ya Yakhya!  Dokunma Meryem''ine Yarusalem''in... Ağaçlar kutlu meyvelere dursun. Ürününü yapraklarıyla örten incirdir,  Ağacın güneşle gür...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/10-anam-babam-ve-samil-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlham perim', 'i-lham-perim-ayse-adlim-wyz5d', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dertlerim sıra sıra

Bekler durur

Dilimin ucunda

Dökülmek ister

Satır satır

Önümdeki şu kağıda

O eski ilham perim

Neredesin

Hani nerde

Girsen ah kalbime

Büğü yapsan

Kalemime

Ucunda dertlerim

Sıralansa

Dize dize', 'Dertlerim sıra sıra Bekler durur Dilimin ucunda Dökülmek ister Satır satır Önümdeki şu kağıda O eski ilham perim Neredesin Hani nerde Girsen...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Adlım']::text[], 8.5, '{"poet":"Ayşe Adlım","poet_slug":"ayse-adlim","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ilham-perim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoksun', 'yoksun-damla-guven-u1kee', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yine akşam oldu. 

Ayrılık vakti vurdu çoktan 

Beni, bizi... 

Sol yanımda ince bir sızı başladı yine 

Gel desen, 

Hiç durmam. 

Hayır gelemem! 

Uzatsan ellerini 

Tutamam.... 

Gitmek zorunda mısın? 

Bilmiyorum... 

Yollar bu kadar uzak mıydı biz küçükken de? 

Hatırlamıyorum... 

Gözyaşlarım can çekişiyor kirpiklerimde 

Görmüyorsun... 

Sessiz bir çığlık boğazımda düğüm düğüm olmuş 

Duymuyorsun... 

Yorganın altına girmişim ısınmak için, 

Uzayan geceleri biriktirmişim ellerimde. 

Yoksun, bilmiyorsun...', 'Yine akşam oldu.  Ayrılık vakti vurdu çoktan  Beni, bizi...  Sol yanımda ince bir sızı başladı yine  Gel desen,  Hiç durmam.  Hayır gelemem!...', ARRAY['Türk Edebiyatı','Şiir','Damla Güven']::text[], 8.5, '{"poet":"Damla Güven","poet_slug":"damla-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yoksun-149-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '10 Anam, Babam ve Şamil 2', '10-anam-babam-ve-samil-2-ahmet-yozgat-a3au5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '1a/: 

Dön ve hönkür semadaki yanık yüzlü sarışın aya...

''Amin'' de ve çekil ya Yakhya.

Kim geçirdi mazlumları sırattan? 

Çölde cennet kuşlar ve halkın ileri gelenleri nerelere tünedi? Kim önüne gelenlerini zadeganın, Babil''e götürdü süre süre? Ay yılında kenti yıkanları anımsa Yakhya. Halkın çoğunu ve tabii ki çadır ehlini dirilt dolunayda efsun ile. Sen de Babil''e sür öküz tapıcılarını. Mor zülflü amazonların tara enselerini. Orada dur. ''Hu! '' de ve kapaklan... Kızların kaldıkları hanları talan eden sen olma Ölü Deniz sahilinde. Çünkü oranın yıldızı beştir. Seninse dört daha güneşin. Yıllık yaz her hasat sonunda. Ki bize kaynak olsun. Dönem dönem ağla güneşin saçağına konarak. Babil''i iyi tanı sesinden. Ensesinden vurmak olmaz tutsakları. Yani affet onları. Sürgün yeri olacaktır belki ileri de bir kez daha diarı Babil. Örneğin milemyumun kucağında. Sen mazlum olarak bilirsin ya Süleyman evlatlarını... Oysa onlar Beyazıt mültecisi olarak olarak anılırlar. 

''Ka'' ve ''Ta'' ne anlatır bir düşün ta derunundan. 

Baskfilhin kimdir sence? 

Tabii ki kâhinlerin başı. 

Lejyon metreslerinin dinsel önderi ya da.

Artık sen de ''Amin'' de ve çekil Ya Yakhya.', '1a/:  Dön ve hönkür semadaki yanık yüzlü sarışın aya... ''Amin'' de ve çekil ya Yakhya. Kim geçirdi mazlumları sırattan?  Çölde cennet kuşlar ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/10-anam-babam-ve-samil-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '10 Bulanık Akar Siriderya 1', '10-bulanik-akar-siriderya-1-ahmet-yozgat-xphbo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '1/:

Ya Yakhya! 

Dokunma Meryem''ine Yarusalem''in...

Kentin kulaklarında üreyen,

Meryem''e dair utangaç iftiralardır.

Bir fidandır işin aslı,

İlahi bir eski zaman musikisi gibi,

Ağır ve aksak ve usuldan ilerler çölde.

Dalarsın ya kendi gözlerime, işte öyle. 

Aşkın ayak ucunda damla damla sevinç,

Kesme taşlarla örülen bir dudak evi... 

Yüreğimdeki devi bir dalga koparır da,

Döver ya boğazını coğrafyanın 

Ve serin dalgaları Lut''un, 

Korkar küçük bir türkü o an, 

Ve kaçar gider dağlara, 

Ya da ateş fışkıran kuyu-yu gayya...

Ey Yakhya...', '1/: Ya Yakhya!  Dokunma Meryem''ine Yarusalem''in... Kentin kulaklarında üreyen, Meryem''e dair utangaç iftiralardır. Bir fidandır işin aslı, İ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/10-bulanik-akar-siriderya-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '10 Bulanık Akar Siriderya 2', '10-bulanik-akar-siriderya-2-ahmet-yozgat-2hn0k', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '1a/: 

Onlar bir yoz klandır. 

Yalandır kimi zaman. 

Bazen de zulumatı harbiyandır. 

Bayağı işler icra edenler Yerusalem kuytularında. Bilir misin kimlerdir? Pak olmayan iç çamaşırı giyerler onlar. Murdardır bir saat önceleri. Sonraları mı? Benim kılıncım kesmez bu suali Ya Yakhya. Artık sana kalır gerisi tarih cildinin. Aslan yeleli savaşçılar serdarı Yakhya... Kutsal yasasına uydur kentin, bozbulanık akan Siriderya''yı. Ay ağarır o zaman. Kın saklar kılıncını. Beelzebub beyi sineklerin anasıdır bana sorarsan. Anlamını bulmalısın onun konuştuğu lisanın. Her gelen Beelzebub''tan azık alamaz kıtlıkta da olsa bu ilde. Kalır açlığı ile baş başa. Kalır ve dalar. Lut''a... ''Hu! '' de ve kapaklan... Bu kıymadır kendi kendine. Eski kentin testere dişli savaşçılarının hışırtısını duymamız bu nedenledir. Beelzebul yüksek yerlerin boyasıdır. İstin adlı bir Filist putuna taktıktan sonra yak bu kasabayı daha iyi kanımca. 

Alaylı bir isimdir Merih.

Çünkü Karsanya ülkesinde ayvalar sarışındır.

Şalgamlar mavisi gökyüzünün.

Her imame kendi tespihini dizer,

Gezer bir seyyah,

Dünyanın ekvatoru üstünde,

Elleri cebinde,

Ateşler içinde...

Sen de ''Amin'' de ve çekil Ya Yakhya.', '1a/:  Onlar bir yoz klandır.  Yalandır kimi zaman.  Bazen de zulumatı harbiyandır.  Bayağı işler icra edenler Yerusalem kuytularında. Bilir ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/10-bulanik-akar-siriderya-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anasini Gormemis,HIKAYELI', 'anasini-gormemis-hikayeli-yasar-gurlek-nfff4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yillar  once  memet amca  gelmis  buraya

Evlenmek  icin  yarisip  girmis  siraya

Bir  oglu birde  kizi olmus  amcanin

Kizi alip kacip gitmis  burdan silaya

Beatrixsi    getirmis   burda    oyuna

Kizi alip kacmis burdan  varmis  koyune

Coban etmis aynuru  kuzu   koyuna

Anasini gormemis  agliyor  aynur

Yas kemale gelince  evlenip  gitmis

Sanmayinki  aynurun  hasreti  bitmis

Ana olunca anasini dahada cok bilmis

Anasini gormemis  yaniyor  aynur

Hani varya kanallarda  arar bulurlar

Aynur demis  gidip sorayim belki ararlar

Anami canimi bana bulurlar

Anam  anam diye  agliyor  aynur

Aglayarak seyrettim dostlar ben  bunu

Insan kaybediyor inanin suurunu

Buldular anasini   garip  aynurun

Anacim anacim diye sizliyor aynur

Telefonla  katildi ana dil bilmez

Tekerlekli sandelyedeymis oraya gelmez

Garip aynurun yuzu hic gulmez

Anam  anam diye  bagiryor  aynur

Dedilerki birde kardesin cikti

Adi tomas imis aynur canindan bikti

Zalim memet  emmi  nasilda yaktin

Anne  anne  diye  bagiriyor  aynur

Sevgili  dostlar,  televizyonda  serap ezgu  porograminda

Izledim etkilendim, boyle  bir  sey  yazmak istedim  sizlerle 

Paylasiyorum,

Hikayesi  yillar  once  avusturyaya  gelen  mehmet ismindeki

Vatandasimiz,  burada  beatrixs  isminde  bir  bayanla  tanisip  evlenir,

Bir  kizi  olur, anlasamamazliktanmidir  yoksa  baska bir  sebeb tenmidir  bilinmiyor  kizini  alip  turkiyeye   kacar,  kizi  koyde  buyur  fakat  bu  arada

Beatrixs  hamiledir  ama  memet  emminin  haberi  yoktur   bundan  kadinin  birde  oglu  olur,  ne  aci  dostlar ,

Kiz  buyur  evlenir  iki  cocugu  olur  bir  gun  karar  verir, annemi  arayacagim  der, ve  serap  ezgu  ye  telefonla  muracat  eder,   katilir   anasi  bulunur  avusturyada,   aci  olan  ise  ana  kiz  bir  bir  lerini  anlamiyor   kiz  turkce   anada  almanca  biliyor,  tercuman yardimiyla   gorusurler,hani  nerde  anadili,

Hep  derler   ya   anadilini  konusuyor  diye  oysaki  aynur  baba  dilini  konusuyor   tomas  ise  ana dili  olan  almancayi  konusuyor  ne  anaylan   nede  baba  bir   kardesi  tomaslan  anlasamayan   aynura  inanin cok  uzuldum,

Yillarin  getirdigio  tahribat   ana  sakatlanmis  gelemiyor  kardesi  ise

Burda  yetismis  bizim  kulturumuz  yok  onlarda  belki  gelir  gorurum diyor  uzuldum  aynura  sabir  diliyorum  saygilarimla….

Yasar   Gurlek

Rotterdam   20-03-2006

HOLLANDA', 'Yillar  once  memet amca  gelmis  buraya Evlenmek  icin  yarisip  girmis  siraya Bir  oglu birde  kizi olmus  amcanin Kizi alip kacip gitmis...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Gürlek']::text[], 8.5, '{"poet":"Yaşar Gürlek","poet_slug":"yasar-gurlek","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/anasini-gormemis-hikayeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '10 Bin Ölçek Filist Arpası 1', '10-bin-olcek-filist-arpasi-1-ahmet-yozgat-sp8w8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1/:

Ya Yakhya! 

Dokunma Meryem''ine Yarusalem''in...

Annemin avuçlarından sağılan iffet,

Damağının tavanındansa merhameyi göklerin.

İşte öyle bir şefkatli zamanda, 

Damlar da bir sevecen nini,

Kurak dudağıma göklerden uyku indirir.

Temmuzda sızan bulut teridir.

Dağlar o güzel yüzünü yeşile boyar. 

Çığlarla yırtar yangınların ateşten yüzü, 

O anda bende kalan yalnızca ölüm zenaatıdır.

Ki bulur ve alır Kara bir adam. 

Belki de yüreğimdeki heyelandır korku sandığım.

Hüznü müdür yakalnmış yalanların, 

Yoksa isyanı mı bilinmez gerçeğin? 

Söz ağlar ve akışır bir ağız diyarına.

Ya da ateş fışkıran kuyu-yu gayya...

Ey Yakhya...', '1/: Ya Yakhya!  Dokunma Meryem''ine Yarusalem''in... Annemin avuçlarından sağılan iffet, Damağının tavanındansa merhameyi göklerin. İşte öyle ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/10-bin-olcek-filist-arpasi-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '10 Bin Ölçek Filist Arpası 2', '10-bin-olcek-filist-arpasi-2-ahmet-yozgat-7w2rp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '1a/:

Kralları laldır oranın. 

Ya çöl beyi, 

Ey Yakhya de diyeceğini Beelzebub''a. 

Şeytan kendi anlamında kullanır kimi zaman isimlerimizi. Belirtisi silinir anti maddenin. Ey Yakhya de bizlere çok kez ne yenir burada akşamları? Et mi? Etse ne eti? İns mi, cins mi? Bak. Birinin ağzı kanar bu sıra. Ey Yakhya sil kanını insanoğlunun. Hadramut tarafından gönderildiğini gösteren hurmayı sun oğullarına. mucize anlamında kullan yediklerini. Benliğini yok et atların. 

İnsanın ise kendindenliğini. 

Ey Yakhya hizmetten çok himmet bekleriz senden. 

Dünyasal kimliğinden hiçbir şey. 

Enfusundan ise derya deniz.

Ve ölç.

Bin ölçek Filist arpası daha. 

''Amin'' de ve çekil Ya Yakhya.', '1a/: Kralları laldır oranın.  Ya çöl beyi,  Ey Yakhya de diyeceğini Beelzebub''a.  Şeytan kendi anlamında kullanır kimi zaman isimlerimizi. B...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/10-bin-olcek-filist-arpasi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Üzülme Kârgülü', 'sen-uzulme-k-rgulu-yusuf-onder-bahceci-fxfmi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kârda açan güller, hayata nasıl direnirler,

Hayat çok acımasızdır, güller dahi bilirler,

Kâlbi kırık olanlar sevenleri özden bilirler,

Sen üzülme kârgülü sen güllerin en güzeli....

Kardeşime.....', 'Kârda açan güller, hayata nasıl direnirler, Hayat çok acımasızdır, güller dahi bilirler, Kâlbi kırık olanlar sevenleri özden bilirler, Sen ü...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sen-uzulme-kargulu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '10 Şeşber ve Kılınç ve Gaddare 1', '10-sesber-ve-kilinc-ve-gaddare-1-ahmet-yozgat-x87jg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '1/:

Ya Yakhya! 

Dokunma Meryem''ine Yarusalem''in 

Onulmaz panikteki her yaralı serçe

Belki de son avıdır avlanan her yüreğin 

Öksede bıldırcındır şimdi muallak taşı

Milat kilisesinin tuzağında turaç...

Aç ve sefildir yansıyan Lut toplayıcılarını,

Kapıcıların o yüzden artırır,

Ondandır Gassani kralının aşka ütezlenmesi.

Herkesi sever de şeşber ve kılınç

Yalnızca kendini tutan eli görünce ufukta,

Ta kabzasından kızarır

Kara Ali''dir elleriyle yıldız aşılayan

Ölümü gülerek karşılayan,

Coğrafyada noktalı virgül,

İki nokta üst üstedir tarikhi Merduban''da

Yani sanki ateş fışkıran kuyu-yu gayya

Ey Yakhya...', '1/: Ya Yakhya!  Dokunma Meryem''ine Yarusalem''in  Onulmaz panikteki her yaralı serçe Belki de son avıdır avlanan her yüreğin  Öksede bıldırcı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/10-sesber-ve-kilinc-ve-gaddare-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '10 Şeşber ve Kılınç ve Gaddare 2', '10-sesber-ve-kilinc-ve-gaddare-2-ahmet-yozgat-1s2qd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '1a/:

''Amin'' de ve çekil Ya Yakhya. 

Arzulan tendir.

Ne olsun daha? 

Ya Yakhya vur kendini kumlara,

Kumsal vahalara ya da...

Nefsini tatmine uğraşmak boştur der aziz Kabluman. Her Kuds''e yönelen kutsal mı sanırsın? Baksan tanırsın öz varlığını iyiliğin. Gözdür. Yalan onun işi olamaz. günaha eğilimli olanlarıda kutsamalısın. bedensel tabiatı doğramalısın ilkbaharlar. Benzetme kendini ne bana, ne de ruhsal bir gerçeği açıklamak üzere yanına gelene. O her kimse. Söyle benim de selamımı. onun için anlatılan öykü taddır hala damağımızda. Mesel ise de inanır Urumeli. Masal ise de. De ona. Bizim bölgenin kralı Grekçe''de Tetrarhis''tir. Yani terhis olmamış asker. Siviliyattan bittabi. Filist adına küçük bir bölge ihdas etmek ister bağlıların. 1b/:

Ya Yakhya! ...

Her kimse oranın üzerinde yetkili kılınan,

Kralı ve vekilharcını kutsa. 

Ve sal tez elden Saba''ya aşk kuşunu. 

Ama gönülden yani isteyerek. 

Ayrıca Hüdhüd''ü seyis kıl yüreğine. 

büyük atalarını diz tespih ipine. 

Ya Yakhya, çizgi kaşlı bilge,

Nedir ulusunun iki kaşı arasında ki dövme? 

Şahmaran mı meliki yılanistanın? 

Yoksa tılsımlı bir yalan mı? 

Eski çağlarda yaşamış bir bilge mi yoksa? 

Sor bunu belli başlı muhariplere,

Din ve devlet adamlarına. 

Ve on iki oğluna danış.

Kim varsa daha...

''Amin'' de ve çekil Ya Yakhya.', '1a/: ''Amin'' de ve çekil Ya Yakhya.  Arzulan tendir. Ne olsun daha?  Ya Yakhya vur kendini kumlara, Kumsal vahalara ya da... Nefsini tatmine ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/10-sesber-ve-kilinc-ve-gaddare-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '10 Türkü Irlarız Çimerken Niye? 1', '10-turku-irlariz-cimerken-niye-1-ahmet-yozgat-jk22t', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '1/:

Ya Yakhya! 

Dokunma Meryem''ine Yarusalem''in...

Uçuşur ya turnalar kentin saçlarında, 

Geç kalmanın hırsıyla hışırdamada,

Kanatların tılsımlı telleri.

Ve kaçtır kuşlara inat,

Kalemler karalar aşkı meydanlarda.

Kendimizin kırdığımızı bilmez yüreğimiz, 

Sarışın sayfalardan kanımız akar.

Bir terli omza yaslanarak bu ağustos gecesi,

Ağlamak gelir Ya Yakhya,

Benim ve havarilerin içinden. 

Yorgunluk atılır mı dingin yataklara? 

Yanınızda yatıyorsa ölümün zenaatkarı. 

Ağlıyorsa alem çağlardan beri, 

Bil ki sudan bir boşluğun içindesindir.

Son bir kez daha geriye bakmak yetmez,

Karaları görmek için puslar içinde. 

Giderir mi hasreti sallanan eller? 

O eller ki,

Bazen sevdayı,

Kimi zaman ölümü derer ürün olarak.

Ya da ateş fışkıran kuyu-yu gayya.

Ey Yakhya...', '1/: Ya Yakhya!  Dokunma Meryem''ine Yarusalem''in... Uçuşur ya turnalar kentin saçlarında,  Geç kalmanın hırsıyla hışırdamada, Kanatların tıls...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/10-turku-irlariz-cimerken-niye-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '10 Türkü Irlarız Çimerken Niye? 2', '10-turku-irlariz-cimerken-niye-2-ahmet-yozgat-wffkj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '1a/: 

Ey Yakhya can nedir? 

insanın yaşamasını sağlayan enerji mi? ve ölümle vücuttan ayrılan madde dışı varlık biz miyiz? Yani kimiz? Nereden gelip, hangi yöne gideriz? Neden şiirler yazarız yalanlara sığınıp? Türkü ırlarız çimerken şehvetimizin ardından? Ya Yakhya, Cehennemi anlat bağlılarına. Ey Yakhya''nın halifesi olan adam... Neden susarsın sen? Şeytan ve kötü ruhlar konuşurken yakışır mı bu hal? İçin için hazırladığımız yangını körükle boş bir vaktinde. Ve Put yontucusu Harentik''in kır son putunu da. Müjdesini reddeden ney atmıştır yabana bilir misin? insanların da gideceği yok aslında Yerusalem''e. O zaman beklesinler sonsuz ceza yerini. İz de türkü ırlarız çimerken. 

1b/:

Cennet ne peki? 

Ey Yakhya topla çadır ehlini.

Sağ elinin ayasına bayram gününde. 

Çiz hududunu devler yemiş coğrafyayı. 

Banmak için mürekkep mi? ... 

Var ya kanımız.

''Hu! '' de ve kapaklan... 

Seninle Ya Yakhya,

En yakınımız sahrada ölümdür

Meleklerin bulunduğu yer ise damdır bize. 

Hepimize ışıklı muştu sun artık. 

Tüm gerçek çıksın orta yere diyarı Kenan''da. 

Yamalı bohçalar kahini uğunsun acısından. 

Bakıp bakıp yıldızlara yuvarlansın kezzibana. 

Dayansın Lut''un kenarına çolak eliyle. 

İnanlılarının canı yansın kendi odlarında. 

sonsuz sevinç uçuşsun ebabil olup. 

Kutsal ve günahkar Babil olup bu kutlu kent... 

Sim latalı hakim olup hükmetsin tüm diyara. 

Cananın içinde yaşayacağı yer aklansın. 

Cinler düğün kursun Süleyman''ın uğruna. 

Göze görünmeyen sevdalar ağsın. 

Seylan''a insin Adem.

Ne olsun daha? ...

''Amin'' de ve çekil Ya Yakhya.', '1a/:  Ey Yakhya can nedir?  insanın yaşamasını sağlayan enerji mi? ve ölümle vücuttan ayrılan madde dışı varlık biz miyiz? Yani kimiz? Nered...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/10-turku-irlariz-cimerken-niye-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '10 Dızmanlar Tarihi 1', '10-dizmanlar-tarihi-1-ahmet-yozgat-u6hip', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1/:

Ya Yakhya! 

Dokunma Meryem''ine Yarusalem''in 

Yürek tuzağının şah avı Palastin kekliğidir

Tekliğidir bu gerçek sokak tarihçilerinin.

Bekçilerinin insafına düşer mabedi miladın,

Adın anılmazsa daralır yüreklerde odalar,

Aşkına açılmaya namzet... 

Uçar ardıç kokulu sevdiceği muhariplerin

Ve uçar bilcümle zangoçların gönül kuşu

Şimdi çırpışmanın en güzel çağı mı? Bilmem

Karalar karası Ali ise,

Geçeği dızmanlar tarihinin

Her kahinin yalanı yakar kendini,

Ve tabiidir ki ona yürekten vurulanları,

Yarınları bilmek harcı mıdır? 

Kenan''da açılan her üçüncü gözün? 

Ya da on birinci boyutu asal gerçeğin

Uçan ardıç kokulu sevdiceği muhariplerin

Vurulur ve düşerler kendi teşneliklerine,

Yuvarlanılan yer aşk ve şehvet değildir kanımca... 

Ama sanki ateş fışkıran kuyu-yu gayya...

Ey Yakhya...', '1/: Ya Yakhya!  Dokunma Meryem''ine Yarusalem''in  Yürek tuzağının şah avı Palastin kekliğidir Tekliğidir bu gerçek sokak tarihçilerinin. Bekç...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/10-dizmanlar-tarihi-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '10 Dızmanlar Tarihi 2', '10-dizmanlar-tarihi-2-ahmet-yozgat-jd6y1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '1a/: 

Ey Yakhya! 

Yontuları kırma vaktidir. 

Hizmet erbabına yapılır diyarında. 

Kem söz eden etmiştir. 

Ne denir ardından kaçanların. 

Hiç. 

Kaçmıştır işte. 

1b/:

Ya da her gidişte vardır bir hayır. Kötü ruhtur, yanacaktır. Kendine tutsak Ya Yakhya! ...Olanı özgür kılamazsın uğraşma boşuna ayın arka yüzünü göreceğim diye. Hem ne diye göstermez ay arkasını. Kötü bir durum mudur? ruhun denetimi yoksa insan da içini dönemez sana. Dene istersen. Altında bulunan postu canlandır kerametinle. Cinli bir beldeye uğra bir aralık. Kendi cinine tutsak olan kardeşlerini çağır. Cüzamlılarla oynaş. Grekçe''de ne demektir lepra. Sor bilenlere. Nertas diye çevrilen sözcüğün anlamını ara kamusta. Hansen basilinin kanına gir. Nedenini sor ona o filfilli melodinin. Bir yabaninin şarkısıdır belki de.

Duy ve dinle.

''Hu! '' de ve kapaklan yere... 

Sen de eşlik et muhariplere,

Kapanan kapıların önünde.

Hatta uzan Alamut kalesine,

Fedailerin aşkını izle.

''Amin'' de ve çekil Ya Yakhya.', '1a/:  Ey Yakhya!  Yontuları kırma vaktidir.  Hizmet erbabına yapılır diyarında.  Kem söz eden etmiştir.  Ne denir ardından kaçanların.  Hiç....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/10-dizmanlar-tarihi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '10 Çul ve Kül Kardeş Kılındı 1', '10-cul-ve-kul-kardes-kilindi-1-ahmet-yozgat-6819r', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '1/:

Ya Yakhya! 

Dokunma Meryem''ine Yarusalem''in...

Dualar kıyamına dursun şükran için. 

Ve umut diye beklenen baldıranı karşıla. 

Son atlılar az sonra geçecekler,

Kıyamet kilisesinin duvarlarını ardından,

Koşumları kana kesmiş olarak,

Ve kabaralarını şakırtadarak...

Evet, bak ve dinle...

Geçtiler işte... 

O atlılar bir çiçek kopardılar, 

Can yaylalarından incitmemek için,

Yüreğinde duyduğun karaca meleyen karacayı. 

Nal sesleri ondandır flu,

Ve belki de ondandır kantarma zaferleri,

Tarihe gark olarak uzaklaşmada. 

Seni içine çağırıyordur gerçek Ya Yakhya,

Belki de içini sana... 

Sevdiğini söylediğin zaman susacak kahır,

Ve susacak kentin çalınan tunç çanları. 

Neden iplik kopar döşünde? 

Duyduğun zaman Kara Ali''nin ününü,

Eski bir arkadaşa seni bağlayan,

Neden yanar damarın onun öldüğünü? 

İşte öyle bir andır,

Düşmüşüz dara...

Ya da ateş fışkıran kuyu-yu gayya.

Ey Yakhya...', '1/: Ya Yakhya!  Dokunma Meryem''ine Yarusalem''in... Dualar kıyamına dursun şükran için.  Ve umut diye beklenen baldıranı karşıla.  Son atlıla...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/10-cul-ve-kul-kardes-kilindi-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel hadi', 'gel-hadi-ayse-adlim-mxmx3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çık da bir yerlerden gel hadi

Kanayan yarama derman ol hadi

Bu akşam tam sana göreyim

Yasaksız saatlaere koş hadi

Dur yok,  git yok,  yeter yok bugün

Geldiğine değecek, naz yok bugün

Söz vereceksin, isterim yalnız

Kendime güvenim hiç yok bugün', 'Çık da bir yerlerden gel hadi Kanayan yarama derman ol hadi Bu akşam tam sana göreyim Yasaksız saatlaere koş hadi Dur yok,  git yok,  yeter ...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Adlım']::text[], 8.5, '{"poet":"Ayşe Adlım","poet_slug":"ayse-adlim","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gel-hadi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '10 Çul ve Kül Kardeş Kılındı 2', '10-cul-ve-kul-kardes-kilindi-2-ahmet-yozgat-f0d9y', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '1a/: 

''Amin'' de ve çekil Ya Yakhya. 

kal olduğun yerde. 

Hastalığından derman sağ. 

Sedef çıkart içindeki ummandan. 

ve zehirli mantar pişir göl civarında. 

Çadırlara konuk ol selam vererek. 

Tanıklık çanını çal aşk ile. 

Çarmıhları kırdır işbilir dülgerlere. 

Ya Yakhya her suçlunun öldürülmek zorunda olup olmadığını bir kez daha düşün. Amacıyla pratiğini karşılaştır yandaşlarının. Çivilendiğin yerden yekinme zamanıdır. Herkes kendi biçimindekileri sever derler ya. Ben inanırım amma sen inanma. Kur darağacını asma kimseyi. Çul ve külü kardeş kıl. Ateşin ardınca yürü. Kıldan yapılmış kaba dokumaysa çul, nasıl kardeş kılınır ateşle? Haklısın ama. Sen bunu becermelisin kanımca. İşte o zaman Yakhya''sındır, Ya Yakhya. Eski çağlarda çekiç dişi savaşçılar tövbe eder eder de bozarlarmış. Ya da büyük acı işareti olarak bileklerini çizerlermiş. ''A'' biçiminde. Çul giyerlermiş yoksul sufiler. ve üzerlerine kül serperlermiş karda uyurken. Bırak şimdi çulu ve külü. dağılmış olanlar topla yörene. Öncelerini öteleme ki zaman sana tutunsun. Karantina kadınlarının dışından geçir yolunu. Diğer ulusların arasında yaşayan yandaşlarını yadsıma. Onlar da kardeşindir. Eşindir. Akranındır. Kimmerya dullarının tümü için kullanılan ifadeleri sök at ari lisanından. 

1b/:

Ya Yakhya, ''Hu! '' de ve kapaklan... 

Daha sonra otur ve ağla. 

Mazlumlar için tabii ki. 

Çeşitli ülkelere dağıt şakirtlerini. 

Türkün ırlansın lal ülkelerde. 

Şarap sıkıcısı kendi tatsın sıktığını. 

İnanlılar için de şıranı kendin hazırla. 

Kullanıldığını anla da... 

''Amin'' de ve çekil Ya Yakhya.', '1a/:  ''Amin'' de ve çekil Ya Yakhya.  kal olduğun yerde.  Hastalığından derman sağ.  Sedef çıkart içindeki ummandan.  ve zehirli mantar pişir...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/10-cul-ve-kul-kardes-kilindi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiirlere Yazmak Seni', 'siirlere-yazmak-seni-ugur-i-pek-x2h36', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şiirlere Yazmak Seni 

Melike''ye,

Paylaşmayı çok isteyip de

Paylaşamadığım onca zamanlarda

Son pişmanlığın gelip geçtiği

Karanlıklar içinde terkedilmiş bir garda gibiyim

Mutlu muydum sahi

Belki de mutluluk rolünde bir yolcu

Seninle aynı trene binmiş öylece gidiyorduk

Telefonum çaldığında hala gidiyorduk

Zaman zaman sarsılarak

Bazen de küçük molalar ardımızda

Ama şimdi zorunlu bir duruş yaptık

Sarmak için film şeridini geriye

Sardıkça hüzünlendim

Hüzünlendikçe ağladım

Gelip geçen anıların ardından

Kedi tırmalaması kavgalarımız

Kanamaya yüz tutmuş çizikler içindeyim

Dalga dalga alev alev kızıllığın gölgelediği

Beni benden alan utangaç tebessümlerin

Kadınlıkla çocukluğun arasına sıkışmış

Akşam kaçamakları gibi

Seni seviyorum kocacığım

Anlarsınya.......

Çapkın göz kırpışların umarsızca

Ve daha neler neler

Şiirlere yazmak seni

Bulutlara resmetmek ne zor

Ama zorlukları severim bilirsin

Seni sevdiğim gibi zor kadın

Uğur İpek, Çayırova, 20.08.2004', 'Şiirlere Yazmak Seni  Melike''ye, Paylaşmayı çok isteyip de Paylaşamadığım onca zamanlarda Son pişmanlığın gelip geçtiği Karanlıklar içinde t...', ARRAY['Türk Edebiyatı','Şiir','Uğur İpek']::text[], 8.5, '{"poet":"Uğur İpek","poet_slug":"ugur-i-pek","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/siirlere-yazmak-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '10 Budur Gök Coğrafyası 1', '10-budur-gok-cografyasi-1-ahmet-yozgat-7vxpz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '1/:

Ya Yakhya! 

Dokunma Meryem''ine Yarusalem''in...

İki aşk ehlinin toprağı örülür buralarda,

Şakaklarda ter çiçek toplaması zangoçların,

Oyalanmasıdır kıyamet kilisesi tarihinde.

Bir zafer kuşudur yürekler avlamak kadar,

Köpüklü savaş kanı daisterler.

İnanılmazsın Ya Yakhya,

Ve ''seviyorum.'' demek kadar ırmak suyu.

Anlamsızsa yaşamsa havari dışı yaşam,

Bir daha mavi semalara çıkıp izleme bizi.

Temaşa eyleme kendini çimenlerin dibinde,

Çırp tependeki tozları ki yıldızlar ışılasın. 

Düşüncen arı duru balkasın kitabında,

Sevdaların zifafında terlesin.

Rüzgarlarla dansa kalkarsa ölümün zenaatkarı,

Ya yok olmaya namzettir saltanat,

Ya da şefkatli duygular ağlamaya.

Denize serpiyorsa şimdi bir anka, 

Kaf dağında bile güldüğü anıları,

Ve kişioğullarının yasını,

Belki de dumanlı öyküleri yiyemediğindendir.

Rüzgarlar dağıtır ya semaya bir atlı,

Kalır ya gerilerde saman ve kül,

Ve bir tutam kahır...

İşte öyle bir coğrafyadır bize kalan,

Ya da mirası ankanın Yakhya''ya.

Veya ateş fışkıran kuyu-yu gayya.

Ey Yakhya...', '1/: Ya Yakhya!  Dokunma Meryem''ine Yarusalem''in... İki aşk ehlinin toprağı örülür buralarda, Şakaklarda ter çiçek toplaması zangoçların, Oya...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/10-budur-gok-cografyasi-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '10 Budur Gök Coğrafyası 2', '10-budur-gok-cografyasi-2-ahmet-yozgat-b7cgp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1a/: 

''Hu! '' de ve kapaklan... 

Budur gök coğrafyası. 

En hası budur güneş kültünün. 

Bütünün peşinden koşan ayrıntıyı kaçırır. Ya Yakhya demem sen değil tabii. Herkes torun değildir dedesine. Oğlunun soyundan gelen albız da çıkar. Melekül tavs da... İsmail''de... Şahittir tarih. Tevarih tanık... Yansın yıldızların saltanatını bilemeyen. Evlat da olsa. Yani yanan müneccim çıkarsın külahını. Sarkıtmasın yıldız ışığı püsküllerini yüreklerin sahillerine. Onlara inanmasın uluslar. Son gemiye binsinler tufanda. Kahır demleyen keşişler otursunlar seyyarelere. Yudumlasınlar kendi kanlarını. Ve kahırlarını... Burada olmayanlar, olmadıklarına yansınlar yarının erkeninde. Dillerde bal ıslansın. Konuşmak ihtiyacıdır ya kişinin. Bir cümle kursun herkes. Kutsal ruhun etkisiyle hiç öğrenmediği bir dilde konuşma yetisi kazansın lal diller. Din bilginleri kutsal metinleri ırlasınlar ağır aksak ve usuldan. Ağlasınlar. 

1b/:

Ey Yakhya sen de bize. 

Günah mıdır kutsal yazıları kopya etmek? 

Ya da yorumlamak? 

Ve sihir öğretmek şakirtlere.

Tılsımla uğraşmak Babil''e mi hastır sadece? 

Mor zülflü amazonlar neden keserler göğüslerini? 

Bilmeli mi bunları din adamları? 

Veya kahinler? 

''Amin'' de ve çekil Ya Yakhya.', '1a/:  ''Hu! '' de ve kapaklan...  Budur gök coğrafyası.  En hası budur güneş kültünün.  Bütünün peşinden koşan ayrıntıyı kaçırır. Ya Yakhya de...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/10-budur-gok-cografyasi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şahinler Yılmaz', 'sahinler-yilmaz-yusuf-onder-bahceci-jo1d5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şahinler göklerde süzülürler şahinler yılmaz,

Şahinler mert olur kardeşim şahinler yılmaz,

Anasından şahin doğan, kargaya avlanmaz,

Şahinler göklerde süzülürler şahinler yılmaz,

Şahinler mert olur kardeşim şahinler yılmaz...

Kardeşime....', 'Şahinler göklerde süzülürler şahinler yılmaz, Şahinler mert olur kardeşim şahinler yılmaz, Anasından şahin doğan, kargaya avlanmaz, Şahinler...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sahinler-yilmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nadasa Bırakılmış Aşklar', 'nadasa-birakilmis-asklar-ugur-i-pek-lgwx2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Nadasa Bırakılmış Aşklar 

Sen gözlerimde yakamozu denizin

Kır çiçeklerinin kokusu sinmiş saçlarında

Yokolup öylece gitmişim 

Bilirmisin geceleri soğuk üstelik yalnızlığın değmiş

Hayal bile edemeyeceğin kadar karanlık

Uzaklarda çok uzaklarda

Belkide evrenin sonsuzluğunda

Bir kara delik sensizliğim

Ağlamak nafile

Bilsem evet bilsem geri getirecek seni

Gözyaşlarımı Rapunzelin saçları gibi sunarım sana

Bugün de yoksun

Dün de yoktun

Belki yarın da olmayacaksın

Yakıyor beni yokluğun alev alev

Her geliş gidişin bir ölüm

Bir bağbozumu sonrası hayatım

Kırık dallar ve nadasa bırakılmış harap aşklar gibi

uğur ipek/12.01.2005', 'Nadasa Bırakılmış Aşklar  Sen gözlerimde yakamozu denizin Kır çiçeklerinin kokusu sinmiş saçlarında Yokolup öylece gitmişim  Bilirmisin gece...', ARRAY['Türk Edebiyatı','Şiir','Uğur İpek']::text[], 8.5, '{"poet":"Uğur İpek","poet_slug":"ugur-i-pek","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/nadasa-birakilmis-asklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '10 Firavun Pazarında Mezat 1', '10-firavun-pazarinda-mezat-1-ahmet-yozgat-edca3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '1/:

Ya Yakhya! ...

Dokunma Meryem''ine Yarusalem''in...

Yağlı çıra gibi tutuşursa bu kent,

Tam siyaset yüreğinden, vay ki vay! 

Bir kök sevgi getirsen de Ya Yakhya,

Saba melikesinden, 

Artık ocakları tutuşturamazsın. 

Sonbaharın arta kalanı süpürür seni, 

Renklerinden resim yapılmaz ki zemherinin.

Ertesi günde yanacağını bilen şakirt,

Kırba kırba su taşır ciğerinde tabii ki.

Ama bunca suyu yüklenemez yürekler. 

Sevdakarlar bu günden hazırlar ateşini,

Kolayca tutuşalım diye aşkın eline. 

Yıldızları sökmez miydin omuzlarından? 

Karanlıktan korkmasan Ya Yakhya

Ağlar durursan alt ucunda gecenin,

Dostların da sana katılır o son uçuşta,

Ama ya dost olmayanların? 

''Hu'' de ve huruç et korkuların burcundan,

Dağlarsın yüreğindeki dağları yoksa. 

Rüzgarların önünde koştur kısrağını. 

Ya da ardına takıl göç katarının.

Kendi ıslaklığını kurutamayan göz tembel, 

Kendine sevdalı yürek bataklık sayılır. 

gözlerinde büyüyen yabani ve barbar otlarını 

Buda ki her ilkbaharda gümrahlaşsın aşk. 

Ama bizi unutarak sonbaharda mezata çıkarma,

Pazarında firavunlar savurganlığının,

Yani yakma harlarda.

Ya da ateş fışkıran kuyu-yu gayya.

Ey Yakhya...', '1/: Ya Yakhya! ... Dokunma Meryem''ine Yarusalem''in... Yağlı çıra gibi tutuşursa bu kent, Tam siyaset yüreğinden, vay ki vay!  Bir kök sevgi ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/10-firavun-pazarinda-mezat-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babama', 'babama-serkan-aloglu-fov3e', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çocuktum anlamadım geçen o mutlu günleri

Oyun oynar,bisiklet binerdim yaz günleri

Bizde olamaz,gelmez ve bilmeyiz derdim

Ama oldu,geldi ve bildim.

Tam onbeşindeyken birdaha kutlamadım yaşgünleri.

Takdir-i İlahi dedim sual sorulmaz

Ağlamakla çöller sulanmaz

Ne hikmettir ki beni buldu

Babam en güzel gün bildiğim yaşgünümde

Hayata gözlerini yumdu.', 'Çocuktum anlamadım geçen o mutlu günleri Oyun oynar,bisiklet binerdim yaz günleri Bizde olamaz,gelmez ve bilmeyiz derdim Ama oldu,geldi ve b...', ARRAY['Türk Edebiyatı','Şiir','Serkan Aloğlu']::text[], 8.5, '{"poet":"Serkan Aloğlu","poet_slug":"serkan-aloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/babama-53-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '10 Firavun Pazarında Mezat 2', '10-firavun-pazarinda-mezat-2-ahmet-yozgat-b10br', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '1a/: 

Ya Yakhya! ...

Ne anlamındadır sahipsiz kuyulardan su çekmek 

Ve demlemek yürek harıyla? ... 

Dipsiz derinlikler bizi çağırdığında Ya Yakhya... 

Hatta kötü ruhların hapsedildiği yer adımızı andığında... 

Yok mu senden medet? Doğruluk ve günahsızlık tekelinde midir senin? . Kutsal olma Ya Yakya. ''Amin'' de ve çekil. Durumu bir bilene sor. Doğru bir ilişkiye gir. Ve onun gözünde erdemli bir yaşam sür. Durumu bize de anlat sonunda. Ayrıca aklamak bize düşmez fahişeleri. Dünya Ey Yakhya, her şeyin müsebbibi. De üç anlamda kullanılan şey nedir? Evren, insanlık ve kutsal metinler midir? Baş kekitiyorsun. İnsanlarını yorma ey bilge başı. ''Hu! '' de ve kapaklan... Açık ve netlik yakışır sana Ey Yakhya. Ya şakirtlerin baş kaldırmasıyla oluşan günahlı ortama ne demeli? Susmalı ve bir şey söylememeli ha! Egemeni tut ensesinden dersem ben... Bu dünyanın Şeytanını yere çal çölde. Ejderhaları sal üstüne. Şeytanını yen son savaşın. ekmeğini bölmek için bekleme yoksullar sokağında. Karalanmış kağıtların lordu Opdaselam''ı oku ama inanma. İnanlılarının başını çek çölü yara yara. Yanlış kentlerin planlayıcısına Salamon mabedini ısmarlama. 

kral Kermani''nin ölümünü an.

Bunun için bile olsa sakın ha! 

Siyaset meydanlarında toplama oğullarını. 

Birlikte ekmek bölüp yemelerini öğütle kızlarına. 

Ya Yakhya! ...

Rabbin Sofrasına çök. 

Ama az ye. 

Doymadan kalk daha. 

''Amin'' de ve çekil Ya Yakhya.', '1a/:  Ya Yakhya! ... Ne anlamındadır sahipsiz kuyulardan su çekmek  Ve demlemek yürek harıyla? ...  Dipsiz derinlikler bizi çağırdığında Ya ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/10-firavun-pazarinda-mezat-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ambulans', 'ambulans-reyhan-tataroglu-qwa1o', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'acildi...

                                    ''''dört ay sonra gel''''

                                    dedi dün

                                    ölüm 

                                    daha merhametliymiş

                                    ziyaretine geldi

                                    ertesi gün

                                    selası okundu

                                    cenazesi kalktı

                                    bugün

                                    başımız sağolsun....', 'acildi...                                     ''''dört ay sonra gel''''                                     dedi dün                            ...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Tataroğlu']::text[], 8.5, '{"poet":"Reyhan Tataroğlu","poet_slug":"reyhan-tataroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ambulans-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '10 Babil''de Kan Demleyen Çaydanlık 1', '10-babil-de-kan-demleyen-caydanlik-1-ahmet-yozgat-v7p6z', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1/:

Ya Yakhya! 

Dokunma Meryem''ine Yarusalem''in...

Bekaret sorularını sildin mi dilinden? 

Yanıtlar yiter sorular kuşkulu ise, 

Beynimden de sensiz katarlar geçebilir 

O katarlar ki dem taşırlar,

Babil''de kan demleyen çaydanlıklara.

Şiirlerini de yerler, 

Acıkan her bir muharip edebiyatta.

Sana ve bana ve hurma ehline,

Balı boş beyit kovanları kalır. 

Yakarlar bir aralık ayazında, 

Beylerin otoritesini cengaverler.

Kaç kilo çeker ki cesaret? 

Saltanat dediğin zebercet kaç kırattır? 

Bilmiyorum hangi sultan,

Yıldızların kaç yaşında olduğunu bildi? 

Ya da sensiz gezen havariler 

Kaç şiirin arasından geçtiler Translübnan''da? 

Yazıldı ağaç dallarına ve yapraklarına

Özümseme tarihi ölüler erbabının.

Son anı da kayıp giderse kuburlar alemine,

Göç mevsiminde vahanın yanar cidarı,

Haramilere tutsak düşer hurmaelinde bir kahya,

Ya da ateş fışkıran kuyu-yu gayya

Ey Yakhya...', '1/: Ya Yakhya!  Dokunma Meryem''ine Yarusalem''in... Bekaret sorularını sildin mi dilinden?  Yanıtlar yiter sorular kuşkulu ise,  Beynimden de...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/10-babil-de-kan-demleyen-caydanlik-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '10 Babil''de Kan Demleyen Çaydanlık 2', '10-babil-de-kan-demleyen-caydanlik-2-ahmet-yozgat-k1tmh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '1a/: 

Ya Yakhya! ...

Bir mekansız mekan kurulur.

Kırık saatler toplanır bir bir. 

aranır onların ayarlayıcısı.

dam aralarında bulunur mülteciler.

Suskun ve titrek ve delimsirek biraz da..

Hıçkırarak vurulur zamanın kaçkınları. 

Koom diye bir derebeyinin adıdır fısıldanan.

Fısıldanır ve yayılır şimdilerde bu illerde.

''Hu! '' de ve kapaklan... 

Kimdir, kimendir? 

Necidir, nececedir? 

Bir bilene sorulur zaman.

Halbuki vakit vardır daha

''Amin'' de ve çekil Ya Yakhya. 

Aman vermez egemen derbentler yol başlarında. İsyan başlar yüreklerde günü gelince. İnce bir ağıt kopar hançeresinde ölümün. Yel eser. Bir fırtınadır ki aşk en beklenmedik yerinden kopar. Herkes kendisiyle ilgili müjdeyi yakalama sevdasına düşer. Suları yaymakla görevlendirdiğin kişi kendi içer bütün ummanı Ya Yakhya. El koymak boşunadır boş kırbalara. Yetkili yıldızlarını bilemeyen müneccim el yordamındadır ancak. İnanlıların, izini süremez yıldız namelerinin fırtınalı diyarlarında yüreklerinin. Bir kişiyi kutsamak ya da bir göreve atamak bilgelik ister. 

İçin dışın gibi olmalı derim ben. 

Ya sen? 

Eğer saygınlıksa bahşettiğin,

 Ya Yakhya ''Amin'' de ve çekil.', '1a/:  Ya Yakhya! ... Bir mekansız mekan kurulur. Kırık saatler toplanır bir bir.  aranır onların ayarlayıcısı. dam aralarında bulunur mültec...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/10-babil-de-kan-demleyen-caydanlik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömrümüz Gibidir', 'omrumuz-gibidir-ugur-i-pek-fc943', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ömrümüz Gibidir 

Günler geçer bir bir

Taneler dökülür kum saatinden

Gündüz gece olur, gece gündüz

İlkbahar, yaz, sonbahar derken kış

Ömrümüz gibidir

Bazen yemyeşil bazen de hüzün yaprakları

Her akan tane,

Birbirini kovalayan yelkovan akrep

Dönen tekerlek

Kilometre sayacı

Aldığımız nefes

İçtiğimiz sigaranın havaya savrulan dumanı

Önemsemediğimiz o mausun her tıkı

Ömrümüz gibidir

Yırtılırcasına kopartılan takvim sayfaları

1967...1999, 2000 ve nihayet 2001

Acımasızca geçti yıllar

Saçımızda kırlar ya da çizgiler yüzümüzde

Gönlümüzde fırtınalar

Ne kadar çok şey yaşamışız

Ne kadar mutluluk ne kadar umutsuzluk

Sevgiler gelmiş geçmiş günlerce

Bazen anlık sevişmeler kalmış griliklerde

Gülümsemişiz belli belirsiz

Gözyaşlarımız timsah misali

Sıkıntılar, sevinçler binmiş dönme dolaba

Bir aşağıya bir yukarıya

Umutlar saatin sarkacına asılmış

Bir sağa bir sola

Bir sağa bir sola

sağa sola

Çırpınmak boşuna

Yürüyoruz hatta artık koşuyoruz öyle ya da böyle

O bildiğimiz kaçınılmaz sona

Uğur İpek, 05/01/2001 saat: 08:30 Çayırova', 'Ömrümüz Gibidir  Günler geçer bir bir Taneler dökülür kum saatinden Gündüz gece olur, gece gündüz İlkbahar, yaz, sonbahar derken kış Ömrümüz...', ARRAY['Türk Edebiyatı','Şiir','Uğur İpek']::text[], 8.5, '{"poet":"Uğur İpek","poet_slug":"ugur-i-pek","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/omrumuz-gibidir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '10 Boşluğa Dökülür Ölüm 1', '10-bosluga-dokulur-olum-1-ahmet-yozgat-aknm5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '1/:

Ya Yakhya! 

Dokunma Meryem''ine Yarusalem''in...

Gözlerimizin sessizliğindendir,

Su içmezliğimiz sevdakar tandır odlarında. 

Öfkemizin zehri de akar sukunetin damarına,

Karar vermişse zadegan harbe...

Sonra bir karanlık yalazdır kentte,

Ve dam başlarında kendi türküsünü ırlayan.

İşte o an, 

Her beyitte yuvarlanır göklerden zilzal,

Boşluğa dökülür ölüm zenaatkarının, 

Sabaha karşı etkinliğinin hışmı. 

Yıldızlar kar topu gibidir Ya Yakhya, 

Ve sonra ben diz çökerim aşk ile,

Topun ulaştığı vadinin zeminindeki vahaya. 

Kendi kader harmanıma halay kurarım.

Tutun halakanın ucundan Havariler,

Sizedir ağız dolusu daveti gök ehlinin.

Ve bir gün hepimiz yanarız alaycı aşklara. 

Nefes dileneceğimiz günlerin ayak sesidir,

Kurt uluması sandığımız sedalar.

Ve ölüm denen atlı kadar,

Zalim ve de büyük değildir illet,

Zenaatkarın darağacında okuduğu türkü ise,

Başardığımızı göreceğimizin muştusudur. 

Ve göreceğimiz zilletin varsayımıdır. 

Yakındır yeniden doğumumuz,

Ya da anamızın haznesinden içeri, 

Yani kutlu rahme tekrar huruç edişimiz.

O huruçtur belki de tek kurtuluş Ya Yakhya,

Ya da ateş fışkıran kuyu-yu gayya...

Ey Yakhya...', '1/: Ya Yakhya!  Dokunma Meryem''ine Yarusalem''in... Gözlerimizin sessizliğindendir, Su içmezliğimiz sevdakar tandır odlarında.  Öfkemizin zeh...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/10-bosluga-dokulur-olum-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '10 Boşluğa Dökülür Ölüm 2', '10-bosluga-dokulur-olum-2-ahmet-yozgat-j0be7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '1a/: 

Otur.

Bağdaşını yay.

Bir dost dize daya dizkapağını.

Sonra o kişinin üzerine ellerini koy. 

En Kutsala ant ver. 

Yeri tanık tut hakikata.

Gökleri serin tut yatağında... 

Önceleri ve sonrayı sor bir bir rastladığın herkese. Tanıklık çadırında ağırla düşlerini. sonraları da en sona bırak. Kediler babalarının kentindeki tapınakta yer al. Yer alanlarla kaynaş etle tırnak olarak. ve yalnız baş kâhinin yanına sokul. onun yılda bir kez girebildiği en kutsal bölmelere uğra. Eski Antlaşmaları tara sedef tarağınla. Tozlarını serp ölü denize. Ey Yakhya... Aslan yeleli savaşçılar serdarı... Kralın aracılığıyla kır putları. Ki dirilmesinler bir daha. ''Amin'' de ve çekil Ya Yakhya. Filist halkıyla yaptığın düğünde raks etmek isteriz biz de. Kutsal Yasaya uymak ya da. Küpeşteye dayanan her antlaşma Karsanya ülkesinin tanığıdır. Çıkış yoksa ya? Put yontucusu Harentik''ten önce yazılmış olan Karsanya ülkesi tarihi bağlamaz bizi ama mevcut bağı çözecek olan sensin. 

1b/:

Ya Yakhya! ...

Kıptilerin kitapları açıklar her sırrı. 

Onu kim okur? 

Eski Ahit ya da Ahdi Atik... 

işte bütün mesele bundan ibaret. 

Eski Antlaşma neden eskidir peki? 

Hala geçerli midir eskimişse? 

Veya...

''Hu! '' de ve kapaklan... 

Filist Kitabın ilk kısmıysa senin öykün... 

Ya bizimki nereye kazınır Hamurabi? 

Yer mi kaldı ki daha? 

''Amin'' de ve çekil Ya Yakhya.', '1a/:  Otur. Bağdaşını yay. Bir dost dize daya dizkapağını. Sonra o kişinin üzerine ellerini koy.  En Kutsala ant ver.  Yeri tanık tut hakika...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/10-bosluga-dokulur-olum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '10 Bir Harami Baldıran Kusacak 1', '10-bir-harami-baldiran-kusacak-1-ahmet-yozgat-de113', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '1/:

Ya Yakhya! 

Dokunma Meryem''ine Yarusalem''in...

Ya dağlar da ağladığından utanırsa? 

Ovalar haberdarsa kış diye bir ölümden? 

Ya Yakhya misalini anlaşılır ver bizlere,

Yağmurlardan ve sevdadan oku.

Biliriz ıslatır her daim sevdalı yüreği,

Gözlerin içeri ağlaması.

Köklerin toprağa sarılan eli ise 

Gevşeyecek zamanın son palamarcısının elinde. 

Geçmişini toprağa gömen şakirt ise aranır, 

Tabanını yere ilikleyen ağaçlar gibi.

Gözlerin ağlayanı ise kızarır,

İçeri de ağlasa, dışarı da uğunsa.

Şiirin burasında olan olacak, 

Bir harami baldıran kusacak Ya Yakhya

Çiçeğin biri yeni bir pembe üretecek

Derunundaki boyahanesinde hamarat...

Sen ünleyeceksin, geleceğin dillenecek.

Yaprağı da sen mişsin gibi yiyecek bir at. 

Yeşereceksin yeniden perdelerin ardında.

Öyleyse kapaklan yere yüzü koyun beg oglu,

Şarkılarda parlayan yıldızın gözünü öp. 

Çünkü ömrü bir notacıktır tüm seyyarelerin, 

Ulaşamayacaktır kimse sabaha.

Ya da ateş fışkıran kuyu-yu gayya

Ey Yakhya...', '1/: Ya Yakhya!  Dokunma Meryem''ine Yarusalem''in... Ya dağlar da ağladığından utanırsa?  Ovalar haberdarsa kış diye bir ölümden?  Ya Yakhya m...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/10-bir-harami-baldiran-kusacak-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '10 Bir Harami Baldıran Kusacak 2', '10-bir-harami-baldiran-kusacak-2-ahmet-yozgat-sy8sa', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '1a/: 

Eyvandır ki...

Ehli Suffa oturur.

Ve şiir okur enfusi bir hançereden.

Ardıç sütunlarla desteklenmiştir ya,

Benzemez Şehinşah saraylarına.

Yani bilin ki, 

Bir tarafı açık galeridir sevda.

O yüzden açıktır her vurguna. 

Yel eser mesela, su üfürür. 

Ferisiler tarihi yeniden kazır. 

Ya Yakhya! ...

''Eskiye ait ne varsa yanmalı der,'' bir harami. Durur da yol başında. Yanmalı bence de soğuk yürekler. Ya da zemheride türkü çığıran ozanların dudakları. İşte o zaman... Paralı askerler son kuruşlarını da alırlar Dara''dan. Yani vekilharçlar işlerini başarmışlardır defteri icmalde. Sen de... ''Amin'' de ve çekil Ya Yakhya. De biçimciliğin zararını şakirtlerine. Ve tutuculuğun ziyankarlığını. Bir mezhep kurmaksa tuluemlin kur haydi. Tarikatsa tarik... Fısıkh bayramını kutal Ey Begler oğlu Beg Yakhya. Mayasız Ekmek bayramını tavsiye et açlara. önder olarak da ilk sen ye o ekmeği. Geğir. Her acıktığında çekinme. De yöre çiftçilerine. Toprağı derin kazsınlar daha... 

''Amin'' de ve çekil Ya Yakhya. 

Anılan adına bir takı daha kat. 

Bu bayramda öptürme eteğini. 

Lejyon metreslerini de yadsıma. 

Onları da kat mayasız törenlerine.

Önlerine etek kapat.

''Hu! '' de ve kapaklan...', '1a/:  Eyvandır ki... Ehli Suffa oturur. Ve şiir okur enfusi bir hançereden. Ardıç sütunlarla desteklenmiştir ya, Benzemez Şehinşah sarayları...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/10-bir-harami-baldiran-kusacak-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '10 Yakamozlara Atılan İmza 1', '10-yakamozlara-atilan-i-mza-1-ahmet-yozgat-6z2tj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1/:

Ya Yakhya! 

Dokunma Meryem''ine Yarusalem''in...

Bir gün sen de anlarsın Ya Yakya, 

Yalanla gerçeğin üvey kardeşliğini. 

Yüreğim yakında gideceksin biliyorum. 

Kendi vilayetinin Kara Ali''sinin,

Babadan kalık ezberine yanarak.

Herkes gibi sen de,

Son bir türkü ırlayacaksın, 

Ve ateşten püsküller takacaksın omzuna. 

Bir günde kaybolan krallar gibi değil ki,

Senin şakaklardaki saltanatın Ya Yakhya. 

Kendini kelebek sanman boşunadır. 

Yakamozlara atılan imza ayın keyfine kalır. 

Bir süzme kadar saltanat göze aittir.

Sözün saltanatı ise cümle cümle uzar. 

Taş kadar sessizce gömüleceksek hepimiz 

Piramitlerin dibine şiirlerimizle mumyalanarak,

Ilık yaz akşamlarını ayaz gibi duyarız. 

Donduracak gibi gelir iliğimizi,

O dağ köuündeki minik sevdamız.

Oysa ben ve sen çeliklerin özündeniz.

Mavisiyle karılmıştı bize gökyüzü,

Gecelerden süne süne sabaha.

Ya da ateş fışkıran kuyu-yu gayya

Ey Yakhya...', '1/: Ya Yakhya!  Dokunma Meryem''ine Yarusalem''in... Bir gün sen de anlarsın Ya Yakya,  Yalanla gerçeğin üvey kardeşliğini.  Yüreğim yakında g...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/10-yakamozlara-atilan-imza-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '10 Yakamozlara Atılan İmza 2', '10-yakamozlara-atilan-i-mza-2-ahmet-yozgat-afelh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '1a/: 

Hasırda yatar mütevazılık.

Azık çökelekse aç kalı begler.

Ama ya iliği kurumuşlar? ...

Azıt bütün ebabillerini Yakhya.

Katıl sen de özgür katarlara.

Bak aya...

Dünyaya bağlı da olsa,

Berduşluktan ödün verir mi? 

 Katıl havariler arasına mesela. Roma''da sürdürdükleri kölelik yaşamından kurtuldukları günü kutla yoksul askerleriyle İsa''nın. Özel bir elbise diktir bana da. Lata gibi. Som sırma ve zehebten. bir kutlama şöleni yapalım ardından Babil işgalcilerinin. Kurban edilmiş kuzuları bağışlayalım. Mayasız ekmek yenirse, Karsanya ülkesinde ihraç edelim. Manat kazanalım. Çıkış nere? Demedin hala Ya Yakhya. Bu bayramı çocuklara verelim. Hamursuz bayramında et yiyelim. Kaldırırsa midemiz kan içelim. Vurup atlara kendimizi Karsanya''yı işgale yeltenelenelim. Olsun. Ne çıkar? İşgalci barbarlar olarak da bilinelim. Geleceği bildir bize Yakhya. Her olanı yazdır tarihine. Gelecek masallarda anlatılsın çocuklara. Put satıcısı Lardestek''i kınalayalım. Ey Yakhya ne dört anlamda kullanılır? Yer ve gök ve cen ve ceh... Yer yuvarlağını çevreleyen havaküre olmasa? ... Uzay dolsa karanlık madde ile. Nedir ki salt sahihin bulunduğu mekan? gözle görülmeyen aleme bakın ey amalar. (Tabii ki ''A''lar şapkalı burada.)  Gökteki yedi kandil bize klavuzdur ey ins. Testere dişli savaşçılarsa hızarda zulüm. Ey Yakhya saygıyı göstermek için geldiler alaca atlarıyla Temuriler. Çıkalım kozamızdan. Yalelli ile karşılayalım Temuri beglerini. Zılgıt çekelim. 

1b/:

Ya Yakhya! ...

''Hu! '' de ve kapaklan... 

Geldiler saf saf beklediklerin. 

Ve en iyi efsaf... 

Durun ve kudurun ey kurtlar. 

Aslanlar katıldı kervana. 

Genellikle böyle olur kutlu öyküler. 

Son sözcüğünü söylemez önder. 

Eratsa karınca kesilir vadilerde. 

Ama palasını kullanmaktan kaçınır ay. 

Güneş saklar kasaturasını. 

Bunun yerine gökler yağmur ağlar. 

Seyyareler sevda uğunur.

Yerler yumulur maşlakhasına. 

İnsanlar koşuşur bir vahaya.

Sen de ''Amin'' de ve çekil Ya Yakhya.', '1a/:  Hasırda yatar mütevazılık. Azık çökelekse aç kalı begler. Ama ya iliği kurumuşlar? ... Azıt bütün ebabillerini Yakhya. Katıl sen de öz...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/10-yakamozlara-atilan-imza-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sis', 'sis-suleyman-koca-ivzhc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sis her taraf sis

Ne yana baksam aynı

Tüm evler ve eşya hapis.

Mis her taraf mis

Ne yana baksam aynı

Tüm toprak ve hava halis.', 'Sis her taraf sis Ne yana baksam aynı Tüm evler ve eşya hapis. Mis her taraf mis Ne yana baksam aynı Tüm toprak ve hava halis....', ARRAY['Türk Edebiyatı','Şiir','Süleyman Koca']::text[], 8.5, '{"poet":"Süleyman Koca","poet_slug":"suleyman-koca","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sis-44-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '10 Kezzabi Tarihine Hizmet 1', '10-kezzabi-tarihine-hizmet-1-ahmet-yozgat-8c412', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '1/:

Ya Yakhya! 

Dokunma Meryem''ine Yarusalem''in...

Bil ki dokunan kurur kalır toprağa.

Yer ruhunu alır cümle halaskaranın.

Bunu sana orada da soracaklar Ya Yakhya, 

Hem de ateş lisanı ile... 

Söylemişti oysa büyük büyük ataların, 

Bu türkünün birinci dizesini ayan beyan.

''Yan ey insücin yüreğinin alazında,'' diye 

Sana yazgını hediye olarak sunmuşlardı,

Ayın doğduğu ilk günkü doğum gününde.

Hem de Ya Yakhya,

Asla unutmayacağın bir kadim lisan ile.

Birlikte dinleyelim, çök de yanıma,

Ölüm erbabının Kobtik zevk inlemesini.

Dinle kendi sesini! 

Hatırla atların tırnak türküsünü,

Parmakların kırıksa da alkış tut, 

Ellerinden kes umudunu,

Ama kesme beni geleceğe bağlayan,

Zeheb zincirini, köle gibi görünsem de.

Şiir yazmaya çalışman Begoglubek

Bil ki hayra alamet değildir, 

Kezzabiler tarihine hizmettir aslında.

Oysa sen eskiden böyle değildin.

Bazı baharlardan daha türkü kokardın,

Ve kimi nisanlardan daha yağmurluydun.

Öyleyse Ya Yakhya Beg niye şiir? 

Niye çiğnenmek demir kabaralara? 

Ya da ateş fışkıran kuyu-yu gayya...

Ey Yakhya...', '1/: Ya Yakhya!  Dokunma Meryem''ine Yarusalem''in... Bil ki dokunan kurur kalır toprağa. Yer ruhunu alır cümle halaskaranın. Bunu sana orada d...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/10-kezzabi-tarihine-hizmet-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '10 Kezzabi Tarihine Hizmet 2', '10-kezzabi-tarihine-hizmet-2-ahmet-yozgat-slprn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '1a/: 

Çölün begi...

Ya Yakhya! ...

''Hu! '' de ve kapaklan... 

En yüce dağlar da eğilir. 

Bir zilzal kopar tozlar arasında. 

Olan olur surelerin sonunda bir kez daha.

Şerare gibi ifadeler kullanır süvariler.

Nal dökerler ayak ucundaki sabaha.

''Amin'' de ve çekil Ya Yakhya. 

Bil ki... Mavi boşuna deildir mavi. Ve bulutların gölgesi... Göklerin egemenliği yerde işte böylr iz sürer. Yakhya''nın ggemenliği ise göğün dizi dibinde büyütür fidelerini. Göksel egemenliktir yürekleri en saf yerinden yakalayan. Ey Yakhya''nın oğulları ve kızları... Doğrulun ve kalkın kınınızda. Gaddarelerinize su verin kendi kanınızla. Egemenliğinizi aramayın Karsanya''da, Taskaban''da ve Kuyaban''da. Görevli inanlılara şerbetler sunun balınızdan damıtıp. Kapatıp tarihin ardını hayalinize bakın. Yakhya''nın çadırında toplanın aşk ile. Şakirtler topluluğunda azm varsa sağılır ilim, amazon memelerinden. Olanak toplama ve dağıtma adaletin işiyse adres doğrudur. 

Haydi herkes işinin başına. 

Ben dahilem saflarınıza.

''Amin'' de ve çekil Ya Yakhya.', '1a/:  Çölün begi... Ya Yakhya! ... ''Hu! '' de ve kapaklan...  En yüce dağlar da eğilir.  Bir zilzal kopar tozlar arasında.  Olan olur sureler...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/10-kezzabi-tarihine-hizmet-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '10 Pirinç Dişili Savaşçılar 1', '10-pirinc-disili-savascilar-1-ahmet-yozgat-0n95k', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '1/:

Ya Yakhya! 

Dokunma Meryem''ine Yarusalem''in...

Bulutlarda boğulan Begim suyun sesidir,

Gözden süzülense seslerin suyu...

Bir derin kuyudur ateşistanda gayya

Ey Begleroglu Yakhya Beg... 

Uçarı anılarını boşalt diplere, 

Ve karşılıksız verdiğimiz şakaklarımıza,

Ter sür bir parça alıp Şeria''dan. 

Hayallerimizde ara bizim artıklarımızı, 

Katar kanatlarında yuvarla apak kartopunu,

Gül kokusuna bulat başını ankaların. 

Hani seriyordun ya uykularını,

Samanyolundaki yıldız yataklarında,

Bir eylül lisanıyla ünler analar başucunda,

Kendi analarından ödünç aldıkları ninnilerini.

O analardır ki yalnız koymazlar,

Evlatlarını, yani seni ve beni... 

Yaprakları yaşamının kefareti saymalısın,

Yaymalısın bu durumda seccadeni,

Seyyareler harmanında bir yere.

''Hu! '' de ve kapaklan... 

Yine gelir sanma aynaya unuttukların. 

Geçen her akşamın suretini çiz yeter,

Ya da son akşam yemeğinin panoramasını,

Kıyamet kilisesinin duvarlarına. 

Tuzunu senle paylaşan her havariye inanma, 

İnsanlar da bazen sırtlanlara imrenir,

Kimileri de kaplan vicdanıyla bakarlar,

Yoksul ve yalın yaşama...

Ya da ateş fışkıran kuyu-yu gayya...

Ey Yakhya...', '1/: Ya Yakhya!  Dokunma Meryem''ine Yarusalem''in... Bulutlarda boğulan Begim suyun sesidir, Gözden süzülense seslerin suyu... Bir derin kuyud...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/10-pirinc-disili-savascilar-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '10 Pirinç Dişili Savaşçılar 2', '10-pirinc-disili-savascilar-2-ahmet-yozgat-te8xh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '1a/: 

Çeşitli işlere bakan kişi özünü ihmal edermiş. 

Görünüm kişinin aynasına yansıyandır. 

Gönül gözüyle görülense arkasıdır aynanın. 

Ya da herkes kendi gözleriyle görmeli,

Suretlerdeki olağanüstü görüntüleri. 

Herkesin göğü görmesi şart değildir bence. 

Rüyet ne peki? . 

1b/:

Ya Yakhya! ...

''Hu! '' de ve kapaklan... 

Gözetmen kim? 

Yerelse kilimler değer taşır ilmiklerinde. 

İnanlılar topluluğunun önderlerinden Şerif''tir bu gelen ayın yanında. Karalanmış kağıtların lordu Opdaselam''in zamanından yani. Akdeniz halklarının ortak diliydi oysa bizim şarkımızın lisanı. Ey Yakhya antik çağda nasıl dövüldü demir? Ve bolat dağı çevresinde yaşamış halkların nasıl yumuşadı yürekleri? Zor soru bunlar. Yanıtlayamaz herkes. Bu yüzden ''Hu! '' de ve kapaklan... Dinle bak! Pirinç dişili savaşçılar dansa durdular yine. Duyduğun tepişme sesi ondandır. Burada olmayanlarda şahittir bu iddiama. Gün, bu gün değildir. Tarihin ortasındaki devri fetrettir. Ey Yakhya de o günün deyimini. Şarap sıkıcısının tekrar gelip gelmeyeceğini bağ diyarına. Dünyayı yargılayacağın vakti kıyama kaldır. Zamanı gelin et zemine. Günahı öğüten değirmenler kur. Ey Yakhya''ya baş kaldırımsıyla ünlenen Karsanya ülkesi artık sen de teslim ol aşka. 

1c/:

Ya Yakhya! ...

Tekvini üzüm fıçılarında damıttık. 

İnsanı kırptık saçlarından başlayarak.

Artık sen de ''Amin,'' de ve git.

İronik adımlarla...

1d/: 

Ey Yakhya''nın buyrukları,

Ve onları yerine getirmez olan ins ve cin... 

Son sözüm sizedir son sayfasında,

Şahsi heredot günlüklerimin. 

Bu durum günahtır der oturup postu üstüne,

Saçlarından kına damlayan anam. 

Ya da yazık olarak tanımlanır kamusta.

Bakın ve kıyama kalkın: 

''Amin'' dedi ve kendi dünyasına çekildi Yakhya.', '1a/:  Çeşitli işlere bakan kişi özünü ihmal edermiş.  Görünüm kişinin aynasına yansıyandır.  Gönül gözüyle görülense arkasıdır aynanın.  Ya ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/10-pirinc-disili-savascilar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söyle', 'soyle-ayse-adlim-kbfk7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Birşey söyle

Sevgiyi, duyguyu

Aşkı, tutkuyu

Seni anlatsın

Birşey söyle

Özlemi, gurbeti

Ölümü, hasreti

Beni anlatsın

Birşey söyle

Kuşkuyu, heyecanı

Pişmanlığı, vicdanı

İkimizi anlatsın', 'Birşey söyle Sevgiyi, duyguyu Aşkı, tutkuyu Seni anlatsın Birşey söyle Özlemi, gurbeti Ölümü, hasreti Beni anlatsın Birşey söyle Kuşkuyu, he...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Adlım']::text[], 8.5, '{"poet":"Ayşe Adlım","poet_slug":"ayse-adlim","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/soyle-76-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birgün Derler Ne Çok Sevmiş', 'birgun-derler-ne-cok-sevmis-yusuf-onder-bahceci-g0o5k', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir gün derler o fani idi yârdan ayrıldı eridi,

Bir gün derler ne çok sevmiş nasıl sevmiş,

Bir gün derler ne çok sevmiş cânın vermiş,

Bir gün derler duyulur birgün derler elbette...', 'Bir gün derler o fani idi yârdan ayrıldı eridi, Bir gün derler ne çok sevmiş nasıl sevmiş, Bir gün derler ne çok sevmiş cânın vermiş, Bir gü...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/birgun-derler-ne-cok-sevmis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Sabah Uyandığında...(5)', 'bir-sabah-uyandiginda-5-rafet-uylas-a3q8l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir sabah uyandığında hatırlayacak mısın? 

Hani sizin evde bir düğme kutusu vardı…

Annen telden çamaşırları toplayıp, 

Yeşil sabun kokusunu odanın dört köşesine

Tertemiz yaydıktan sonra,

Soğuktan çatlamış ellerinle, hiç birini atlamadan,

Bastıra bastıra ütülemiş gibi katlayıp,

Yırtık, sökük, düğmesiz ve yıpranmış olanları ayırırdı ya.

İşte ondan sonra başlardı bayram sevincine benzer bir şeyler içinde.

Düğme kutusu ortaya çıkıp, odanın ortasına yayılınca

Rengarenk anılar, kurşuni acılar, kapkara yokluk kaplar dört yanı.

Neler vardır düğme kutusunda neler? 	

Ah unutulamaz o gördüğün minicik imgeler. 

Hep düşünürsün…

Hani küçücük keseciklerdeki karacaotları nasıl da nazardan korumuşlar seni yıllarca,

Bir de İğneci Ayşe’nin, neden hala saklandığına akıl erdiremediğin, döktüğü kurşunları. 

Peki şu koca koca palto düğmelerini hatırlamıyor musun? 

Bir sabah okula bir amca gelmişti. Sen de adını yazdırmıştın 

Babası fakir çocukların listesine 

Niyetin sadece ilk kez yeni palto giymekti ama

Baban nasıl da kızmıştı fakir miyiz biz diye.

Fakiriz işte, fakiriz diyordun içinden haykırıp, baban kızdıkça.

Nasıl kabul ettirebilirdin,

Nasıl anlatabilirdin babana…

Söyleyebilir miydin? İlk kez yeni palto giydiğini… 

Karıştırmaya başlayınca düğmeleri,

Anneni işinden alıkoydun diye nasıl yiyordun şaplağı popona? 

Çok keyifliydi ama değil mi? 

Neler var içlerinde neler, 

Akıl oradan oraya geziyor anılar girdabında.

Bir gömlek düğmesi sünnetini,

Küçücük bir renkli düğme annenin doğum günün için ördüğü yeleği,

Okula başlarken giydiğin ilk önlüğü,

Her şeyi ama her şeyi, küçücük bir düğme kutusuna nasıl da sığdırıyoruz değil mi? 

Bir sabah uyandığında hatırlayabilecek misin? 

Düğme kutularının dünden bugüne bizlere neler taşıdığını?   04.02.2006', 'Bir sabah uyandığında hatırlayacak mısın?  Hani sizin evde bir düğme kutusu vardı… Annen telden çamaşırları toplayıp,  Yeşil sabun kokusunu ...', ARRAY['Türk Edebiyatı','Şiir','Rafet Uylaş']::text[], 8.5, '{"poet":"Rafet Uylaş","poet_slug":"rafet-uylas","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/bir-sabah-uyandiginda-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*-Dön Dansöz Dünya Dön, Ziller Elinde,-*', 'don-dansoz-dunya-don-ziller-elinde-i-lker-unlu-5kkfs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şimdi uzaklardasın! 

Ellerimizde yine inadına,

Ateşiyle yenilenen bir cigara; 

Kilometrelere isyanlardayız...

Engel mi bunlar yürek birliğine söyle? 

Dağlar araya girince,

Kalpler yine aynı atar mı böyle? 

Dön Dansöz Dünya dön, ziller elinde,

Bir bizi döndüremedin yalan melodinde...

Sende o yürek varoldukça,

O kalp sende böyle attıkça,

Kahpeliklere verdiğimiz her ödül,

O koca yüreğinin bir kaybı değil; 

Kahpeliklerin darağacı olacaktır günü gelince...

Dön Dansöz Dünya dön, ziller elinde,

Karşımıza çıkardığın tüm kahpelikler senin çevrende....

Yerine konulur mu bir Allah kulu? 

Bu Candaşlık hiç emanet edilir mi? 

Söyle araya dağlar girse de,

Tek dal cigara yalnız içilir mi? 

Delikanlılığın kâğıda,

Mertliğin suya yazıldığı bu dünya da,

Dostluk ne ki? Yenilir mi içilir mi? 

Dön Dansöz Dünya dön, ziller elinde,

Seni durduracak iki yürek var şarjörümde! ! ! 

İlker ÜNLÜ

20 Mart 2006

00.30', 'Şimdi uzaklardasın!  Ellerimizde yine inadına, Ateşiyle yenilenen bir cigara;  Kilometrelere isyanlardayız... Engel mi bunlar yürek birliğin...', ARRAY['Türk Edebiyatı','Şiir','İlker Ünlü']::text[], 8.5, '{"poet":"İlker Ünlü","poet_slug":"i-lker-unlu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/don-dansoz-dunya-don-ziller-elinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güler', 'guler-nergis-unlucay-epqqq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gül savaşında bir er 

Usuldan sokulur gibi konuşan

Ve okşanır yersiz kalmışlıklar

Bir an sonrasını düşler 

İnanır gibi

Mutlu son; 

Son bile olsa mutlu der gibi

Bakışında dursun uykusuz tanıklıklar

Ve ben

Bazen sadece seyirciyim

Anlatan olsam bile', 'Gül savaşında bir er  Usuldan sokulur gibi konuşan Ve okşanır yersiz kalmışlıklar Bir an sonrasını düşler  İnanır gibi Mutlu son;  Son bile ...', ARRAY['Türk Edebiyatı','Şiir','Nergis Ünlüçay']::text[], 8.5, '{"poet":"Nergis Ünlüçay","poet_slug":"nergis-unlucay","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/guler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Diyorum Çocuk', 'sana-diyorum-cocuk-nergis-unlucay-717fm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Deniz içmiş yakamoz kokuyordu

Korktum yorulur mu çocukluğu

Tezatlığı kadar varlığı

Acelesi sığmazken ömrüne 

Çakılı kalabilirdi masumane bir sevgiye

Tuttu hoyrattı

Kopardı mı yosunu

Ağlama bak 

Uyudu ay bile', 'Deniz içmiş yakamoz kokuyordu Korktum yorulur mu çocukluğu Tezatlığı kadar varlığı Acelesi sığmazken ömrüne  Çakılı kalabilirdi masumane bir...', ARRAY['Türk Edebiyatı','Şiir','Nergis Ünlüçay']::text[], 8.5, '{"poet":"Nergis Ünlüçay","poet_slug":"nergis-unlucay","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sana-diyorum-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Borcum Olsun', 'borcum-olsun-ruhsel-bariscimen-yzsll', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sana; 

Bir ask borcum olsun

Duygularimi aynı tutamadıgım için...

Kendime; 

Bir hayat borcum olsun

Sana takilip

Günlerimi mahvettigim için...

Dostlarima; 

Bir merhaba borcum olsun

Ortadan kayboldugum günler için...

Tanrima; 

Bir can borcum olsun

Yasama yeniden baslamak

Istedigim için...

Hayat! ...

Sana hiç bir borcum yok

Senden sadece

Alacaklarimi istiyorum...', 'Sana;  Bir ask borcum olsun Duygularimi aynı tutamadıgım için... Kendime;  Bir hayat borcum olsun Sana takilip Günlerimi mahvettigim için......', ARRAY['Türk Edebiyatı','Şiir','Ruhsel Barışçimen']::text[], 8.5, '{"poet":"Ruhsel Barışçimen","poet_slug":"ruhsel-bariscimen","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/borcum-olsun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Uzaklardayken;', 'sen-uzaklardayken-ahmet-sayan-7jvoe', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen uzaklardayken; 

Ben sensiz karanlığın ayaz gecelerinde,

Hırçın fırtınaların tokatladığı rüzğarlarda savruldum.

Çivisi çıkmış kaldırımları çiğnedim fütursuzca,

Buzları kırdım, aldırmadım yokluğunun sessizliğine,

Azgın soğukta montuma gömüldüm,

Köşebaşlarında dikildim, soğuğa inat,

Aldırmadım kimsesizliğime, boşvermişliğime,

Yalnızlığıma adım attım delicesine,

Ayak izleri bıraktım zamanın bahtına,

Saçlarım savrulurken rüzğarın beyaz yelesinde,

Bırakmadım kara ayaza inat, buz kesilen ellerimden,

Ellerin titrerken verdiğin tesbihi,

Işıklar düşerken yaşlanmış yollar üzerine,

Kara tekme attım, sinirimi alırcasına,

Savurdum soğuk ellerimle yaptığım kar yumağını,

SEN uzaklardayken; 

Ben gözlerine şiirler yazdım.

Bir bakışta mahpus bırakıp,

Sevda prangaları vurduğun,

Hasreti vagon vagon yüklediğin gözlerine,

Hançer yaraları bırakırken yüreğime,

Yaralarıma kül bastım.

Kanayan yerlerime sevgin yerine,

Acıyı tattırdığın ızdırap saatleri bastım.

Aldırmadım yinede,

Aldırmadım Sensizliğin acısına,,

Yalnızlığıma yazdım, duman kokan boş odamda,

Hüzzamlı duyguların buğusunda tatlı bir koku,

Taze tütmüş, dumanı üstünde,

SEN uzaklardayken; 

Ben yıldızların kayışını seyrettim.

Gökyüzünün bağrından kopup karanlığa dalışını,

Bir çift gözden dökülen iki damla yaş,

Yanaklardan akarken aldırmadan,                                                                                               Aldırmadan sildiğin çiğ tanesi gibi,

Akıp gittim zamanın içinden.

Titredim soğuğun çıplak ellerinde,

Şimdi uzat ellerini taçmahal yıldızlara,

Tutabildiğin yıldızların. görebildiğin uzakların,                                                                                                                 En delikanlı yüreğinde ben varım.....', 'Sen uzaklardayken;  Ben sensiz karanlığın ayaz gecelerinde, Hırçın fırtınaların tokatladığı rüzğarlarda savruldum. Çivisi çıkmış kaldırımlar...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Sayan']::text[], 8.5, '{"poet":"Ahmet Sayan","poet_slug":"ahmet-sayan","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/sen-uzaklardayken-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kavuşamayız Biz', 'kavusamayiz-biz-ruhsel-bariscimen-ci7es', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Deli gibi akan bir nehir

Bir yanında sen

Bir yanında ben...

Uzatsak ellerimizi

Tutacak gibiyiz birbirimizi...

Nehri geçmeyi denesek

Azgin sular bogacak bizi...

O nehir; 

Delice akıp giden

Hayat timsali

ve o hayatin

Bir yakasında sen

Karsıyaka''sın da ben...

Bosuna çabalama birtanem

Asla yollarımız kesisip

Kavusamayız biz...', 'Deli gibi akan bir nehir Bir yanında sen Bir yanında ben... Uzatsak ellerimizi Tutacak gibiyiz birbirimizi... Nehri geçmeyi denesek Azgin su...', ARRAY['Türk Edebiyatı','Şiir','Ruhsel Barışçimen']::text[], 8.5, '{"poet":"Ruhsel Barışçimen","poet_slug":"ruhsel-bariscimen","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kavusamayiz-biz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerçek Sevdalar....', 'gercek-sevdalar-ahmet-sayan-tk16v', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben ne sevdalar tanıdım.

Görkemli burçlar gbi görünüp,

En ufak bir sarsıntıda yıkılıp virane olan.

Hayata inatlaşırcasına uzanan eller,

Tunçtan duvar gibi kenetlenmiş parmaklar,

Aldatma ve aldatılmanın uğradığı sahillerde,

Aldatılmanın acısıyla parçalanan sevdalar.

Ben sevdalar tanıdım.

Umudun ışığı, karanlık dünyanın güneşi.

Ve sevdaları kiletlemişler kapılar ardına,

İhaneti vermişler anahtar diye,

Ya unut yada savaş.

Savaşı hatırlatır sevdalar,

Karmakarışık düşünce askerlerinden,

En rütbelisini, en korkusuzunu ve en vefalısını,

Yüreğini avuçlarına bırakarak seçebilmektir.

Gerçek sevdalardır insanı yaşatan,

Hayatı mutlu kılıp,

Hüzünlere kırmızı kartı gösteren.

Hiç kaza yapmamışlardır,

Doğanın en güzel kokularını,

Bilinmezlerin ötesini,

Sessizliğin sesini onlar duymuşlardır.

Altın tepside sunulanlara inat,

Bir yavru ceylanın gözyaşlarında,

Umutsuzluğun zifiri karanlığı içinde,

Görmesini bilmişlerdir.

Her sonbahar gelişinde,

Yapraklar rüzğarla son  vedayı yaşarken,

Onlar  yeniden filizlenip,

Hayat olmuşlardır.

Fırtınalarla, sislerle buğulan dağların,

Zirvelerini şaha kaldırışı gibi,

Huzur dolu liman, deniz,

Karşılıklı saygı, tükenmezlikte adibe olmuşlardır.

Bazen formüldür, denklem denklem,

İksirdir, mutluluğun büyüsü,

Yetmeyen kelimeler yığını arasında,

Anlatılmazda tanımsızdırlar.

Anlatabilmek sevdanı, kelimleri serebilmek yollarına,

Kelimelerin bittiği, anlamını yitirdiği yerde,

Gözlerini konuşturmak, sessiz ve derinden,

Haykırmaktır sevdalar.

Atmışlardır ihanet anahtarını,

Sevmeyi bilmeyenlere inat,

Sevdayı oyuncak zannederek,

Kendini mecnun yada leyla sananlara,

Hepsine hepsine inat,

Yüreklerini bırakıp sevdiklerinin avuçlarına

Sevdalarını boyunlarına takıp,

Künye yapanlardır.

Gerçek Sevdaları Tadanlar.

Al be GÜLÜM yüreğimi avuçlarına bırakıyorum,

Her şey sende artık, 

İster SEV ister at

Bilki bu yürek SENİN için yaşar....', 'Ben ne sevdalar tanıdım. Görkemli burçlar gbi görünüp, En ufak bir sarsıntıda yıkılıp virane olan. Hayata inatlaşırcasına uzanan eller, Tunç...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Sayan']::text[], 8.5, '{"poet":"Ahmet Sayan","poet_slug":"ahmet-sayan","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/gercek-sevdalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum...', 'seni-seviyorum-ahmet-sayan-jdonm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu gece yıldızları seyrediyorum.

Biliyorum benden çok uzaktalar,

Sadece elimi uzatıp,

Yüreğimle tutmak istiyorum.

Dalıyorum gecenin karanlığına,

Bulutsuz bir düşlere,

Her şeyimi kaybedercesine,

Karanlığın yüreğine dalıyorum.....

Gözlerim, gözlerim nemleniyor.

Acı sarıyor benliğimi,

Tanımsız düşüncelere yükleniyorum.

Ezilip kalıyorum altında,,,

Anlamıyorum biliyormusun? 

Artık kendimi bile tanımıyorum,

Acıyormuyum? 

Yada sensizliğin bağrınamı dalıyorum.

Biliyorum yoksun yanımda,

Ne ellerin ellerimde, nede gözlerin,

SENİ SEVİYORUM

Bütün kalbimle haykırıyorum.

Ya SEN

Beni seviyormusun,

Yada zamansız düşüncelerle sevmeyi becerebiliyormusun? 

Neden çökmediğimi biliyormusun? 

Veya isyan etmediğimi,

Dakikaları sayıklayıp, saniyeleri yoklarken

Neden katlandığımı hiç düşündün mü? 

Duyabildinmi haykırışlarımı? 

Bunları çözebiliyor musun? 

Belki bunlar SENİN için boş,

Belki düşünmeye değmez,

Ama benim için...........

Anladın mı? 

Yüreğimin derdi,

Bileğimin gücü

Neden katlandığı mı? 

Çünkü

SENİ

     SEVİYORUM...........', 'Bu gece yıldızları seyrediyorum. Biliyorum benden çok uzaktalar, Sadece elimi uzatıp, Yüreğimle tutmak istiyorum. Dalıyorum gecenin karanlığ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Sayan']::text[], 8.5, '{"poet":"Ahmet Sayan","poet_slug":"ahmet-sayan","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/seni-seviyorum-350-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sende neyim?', 'sende-neyim-ruhsel-bariscimen-xitll', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İçimin

Resmini bile çeksem

Çıkan sen olacak...

Sen ben de 

Bu kadar ben iken

Ben sende neyim söyle...', 'İçimin Resmini bile çeksem Çıkan sen olacak... Sen ben de  Bu kadar ben iken Ben sende neyim söyle......', ARRAY['Türk Edebiyatı','Şiir','Ruhsel Barışçimen']::text[], 8.5, '{"poet":"Ruhsel Barışçimen","poet_slug":"ruhsel-bariscimen","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sende-neyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vazgeçilmezim', 'vazgecilmezim-yasar-akbas-r5hj5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Koyunun kuzusun sevdiği gibi

Bende seni seviyorum anla be

Bu aşk beni götürse de kabir’e

Vazgeçemem sevdim seni anla be

Şu gönül neyine tutkundur bilmem

Bağlanmışım başka yere gidemem

Dünyayı verseler sensiz istemem

“Seven yürek” farklı olur anla be

Dertlerin çoksa da kaçıp gidemem

Ölümlere götürse de yok demem

Yansa canım neden,niçin,”vah” demem

Mert aşkları yiğit olur anla be

Bir gülüş,her şeyim almaz mı benden

Şu gönül çok şey mi istiyor senden

Muhannet olsan da vazgeçmem senden

“Ata aşkı” yaman olur anla be

Anahtar dilindir hünerin göster

Hünerler her zaman marifet ister

Kerem etsen dertlerimiz tüm biter

Gerçek sevgi kıymetlidir anla be

Sevgiler “vefadır” korunmak ister

Sevdalar rahmettir gözyaşı besler

Akbaş’ın ilacı  “vuslattır” ister

Evlat dedim sevdim seni anla be

                      

                                    10.12.2004', 'Koyunun kuzusun sevdiği gibi Bende seni seviyorum anla be Bu aşk beni götürse de kabir’e Vazgeçemem sevdim seni anla be Şu gönül neyine tutk...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Akbaş']::text[], 8.5, '{"poet":"Yaşar Akbaş","poet_slug":"yasar-akbas","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/vazgecilmezim-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızım', 'yalnizim-ruhsel-bariscimen-8h6aw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yuregim; 

Cam kırıklarıydı

Sen gezdikçe

Kanattın bir yerlerini

Acıdı yandı canın...

Beni ise kan tuttu

Silinmez izler kaldı...

Simdi sen de yoksun! ..

Ben yalnızım...', 'Yuregim;  Cam kırıklarıydı Sen gezdikçe Kanattın bir yerlerini Acıdı yandı canın... Beni ise kan tuttu Silinmez izler kaldı... Simdi sen de ...', ARRAY['Türk Edebiyatı','Şiir','Ruhsel Barışçimen']::text[], 8.5, '{"poet":"Ruhsel Barışçimen","poet_slug":"ruhsel-bariscimen","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yalnizim-90-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret', 'hasret-yasar-akbas-f2ilb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hasretin demir atmış,yorgun,yaşlı  gönlüme

“Dantel” gibi işlenmiş,kutsal aşklar özüme

Oysa hayrım kalmamış,benim kendi kendime

Dün dolu  bir “han “ iken,evim barkım boşalmış

Birkaç kare fotoğraf,duvar da anı kalmış

Bel ki daha varsa da vuslata uzak yıllar

Bir gün sizi getirir,sevgili,güzel yollar

“Gül şene” döner san ki  o muhannet  zamanlar

Dün dolu bir han iken,evim,barkım boşalmış

Birkaç kare fotoğraf,duvarda anı kalmış

İnsanlar hep tek imiş,çoluk çocuk olsa da

Sevenler uğurlanıp,gözyaşıyla kalınca

Gurbet ile sılanın,farkı yokmuş aslında

Dün dolu bir “han” iken,evim barkım boşalmış

Birkaç kare fotoğraf,duvarda anı kalmış

Hayatımız gerçeği “hamı  tatlı” acıymış

Onlardan geçirtmeyen içilmeyen tadıymış

Her şey menzile varır,son olurmuş Akbaş’ım

Dün dolu bir “han” iken,evim,barkım boşalmış

Birkaç kare fotoğraf duvarda anı kalmış

                                  

                                        10.09.2000', 'Hasretin demir atmış,yorgun,yaşlı  gönlüme “Dantel” gibi işlenmiş,kutsal aşklar özüme Oysa hayrım kalmamış,benim kendi kendime Dün dolu  bir...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Akbaş']::text[], 8.5, '{"poet":"Yaşar Akbaş","poet_slug":"yasar-akbas","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/hasret-347-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alışacağım', 'alisacagim-hasan-ekrem-314tz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir şarkı vardı hani,

Bilmem çok mu geçti üzerinden? 

Hayal meyal hatırımda sözleri,

İsyan eden kalbimi diye başlar,

Ve yazık “sev yeter” diye biterdi,

O şarkıyı ilk senden duymuştum.

Ve bir şarkıcı vardı,

O eski melodiyi söyleyen,

O günler hiç sevmediğim,

Kalın ve boğuk sesli..

O günlerde sen vardın benim için,

Defalarca söyledim ve söyleyeceğim,

Sen; gülen,şen,sevecen..

Ve sen seviyorsun diye sevdim,

Senin sevdiğin her şeyi,

O boğuk sesi, mehtaplı geceleri,

Hasretin varken yaşanmayan şehri,

Ve en nihayet isyan eden kalp,

Geceler boyu çınlayan sev yeter’i.

Seninle unuttuğum dertleri ve kederleri

Senin için dinledim.

Oysa artık yoksun sen,

Sadece kulağımda halen sesin,

Ve dilimde yeni melodiler,

Sensizliğe inat, yine o boğuk ses,

Kolay olmayacak diyor, unutmak sensiz yaşamak,

Ekliyor sonra,bu şehirde ne varsa hepsi sana benziyor.

Burası yanlış,benzemiyor ki,o sensin işte..

Parklar, yollar, duraklar ve aklına ne geliyorsa,

Bir de bu şehir….,artık seviyorum bu şehri,

Bu şehir bana okulu hatırlatıyor,

Okul sınıfı, sınıf dershaneyi, dershane ise,

Yazmıyorum gerisini ama değişen bir yer var,

Pendik ise artık o günleri,

O günler ise seni,

Seni sevmeye başladığım ilk günleri..

Öyle iyi, öyle içten, öyle sevgi doluydun ki,

Seni sevmemek Tanrı’ya haksızlık olurdu..

Anlaman lazım.

Sonra hep düşündüm,

Sevgi neden, nasıl biter diye,

Duvarı nem, insanı gam çökertirmiş,

Buldum sonunda,

Aşkı da yalan..

Her şeye rağmen yine de,

En mutlu anlarım,

Senin yanında, seninle geçenlerdi,

Varlığınla dolu olanlardı.

Ve bitti şimdi.

Tek şey var senden kalan,

O boğuk sesli adam ve son şarkısı,

Alışacağım…', 'Bir şarkı vardı hani, Bilmem çok mu geçti üzerinden?  Hayal meyal hatırımda sözleri, İsyan eden kalbimi diye başlar, Ve yazık “sev yeter” di...', ARRAY['Türk Edebiyatı','Şiir','Hasan Ekrem']::text[], 8.5, '{"poet":"Hasan Ekrem","poet_slug":"hasan-ekrem","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/alisacagim-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aklı Eren -Aşiret Hikayeleri-', 'akli-eren-asiret-hikayeleri-halil-yilmaz-kujjh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çobanın biri,

Sabah erkenden,

Davar gütmek için; 

Çıkmış evden.

Karşılaştığı bir ayı,

Hırçın mı hırçın:

Çobanı parçalamış:

Gövde ayrı bir yerde,

Kafa beraberinde

Alıp inine gitmiş.

Akşam olmuş; 

Çoban yok.

Derken gece…

Toplanmış aşiret,

Çıkmış aramaya.

Günün ilk ışıklarıyla,

Bulunmuş çoban

Nihayet…

Fakat o da ne? 

Gövde var, kafa yok

Beraberinde.

Çözerse bu işi elbet,

Ağamız çözer diye; 

Çıkmışlar aşiretin, 

Aklı erenine.

“Söyle bakalım gelin”

Demiş aklı eren.

“Kocan, sabah

Çıkarken evden,

Kafası var mıydı”? 

Düşünmüş gelin,

Düşünmüş derin, derin…

“Sabah kahvaltı ederken,

Yoğurt damlamıştı çenesine.

Çenesi vardı bilirim,

Lakin hatırlayamıyorum:

Kafası, yapışık mıydı? 

Değil miydi bedenine.”

“Akılsız”, demiş aklı eren:

“Bizim gelinde akıl yok.

Şayet hatırlayabilseydi,

Kocası çıkarken evden:

Kafası, var mıydı? 

Yok, muydu bedeninde? 

Gerisi kolay olurdu, 

Çözerdim şimdi hemen.”

Mart 2006', 'Çobanın biri, Sabah erkenden, Davar gütmek için;  Çıkmış evden. Karşılaştığı bir ayı, Hırçın mı hırçın: Çobanı parçalamış: Gövde ayrı bir ye...', ARRAY['Türk Edebiyatı','Şiir','Halil Yılmaz']::text[], 8.5, '{"poet":"Halil Yılmaz","poet_slug":"halil-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/akli-eren-asiret-hikayeleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevemiyorum işte...', 'sevemiyorum-iste-omer-resad-erhkh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Su akıyor yatağında.

Trenlere biniyorum.

Yemek vagonlarında içiyorum.

Fabrikalar, rafineriler önünden geçiyorum,

Ateş kulelerine minik kalbine bakıyorum.

Camdan dünyayı seyrederek,

Vapulara biniyorum.

Boğaz yüzümü ılık ılık okşuyor,

Saçlarım titriyor bir dokunuş bekliyor.

Bazen sokaklardayım yürüyorum.

Bazen oturuyorum konşuyorum insanlarla,

Konuştuğumuza benzer şeylerden...

Ellerinden bile tuttuğum oluyor.

Elinden tutuklarımın gözlerine de bakıyorum.

Hatta taa içine bile...

Ama olmuyor işte

Baktığım vagon pencerelerinde

Senin yansıyan görüntün olmayınca

Ateş kulelerine adlar vermeyince,

Rüzgarda fena değil ama,

Yüzümü okşayan senin ılık tenin olmayınca

Olmuyor olmuyor işte.

Sevemiyorum sevemiyorum

Aldatıyorum kendimi, 

Vagonları, vapurları, sokakları

Anılarımı, yokluğunu.

--

Biri anlatmıştı. Otuz sene oluyormuş sigarayı bırakalı. Otuz sene hiç ağzına bile sürmemiş. Ama bu kadar sene sonra bile zaman zaman yemeklerden sonra canı çekiyormuş. Böyle oluyormuş demek, bir şarkıyla güzel bir manzarayla, bir kokuyla veya ufak bir gülüşle çekiyormuş insan sevdiğini içine. Bunlar alışkanlık yapıyormuş. Bırakamıyormuş insan. Sonun keder olduğunu bilse kedere susuyormuş. 

--

Yan yüreğim yan.

Yan geçmişe, sevdiklerine ve gidenlere.

Sevemeden kal  işte böyle,

Kavruk olduğun yerde.', 'Su akıyor yatağında. Trenlere biniyorum. Yemek vagonlarında içiyorum. Fabrikalar, rafineriler önünden geçiyorum, Ateş kulelerine minik kalbi...', ARRAY['Türk Edebiyatı','Şiir','Ömer Reşad']::text[], 8.5, '{"poet":"Ömer Reşad","poet_slug":"omer-resad","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/sevemiyorum-iste-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanmadan Olmaz', 'yanmadan-olmaz-huseyin-kotan-pnp8u', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gül pembesi beyaz ipektir tenin

Geniş göğüslüsün, kuvvetli elin

Hak’tan  sürmelidir siyah gözlerin

Okudum fermanı yanmadan olmaz

Kirpikler uzunca gür’dür sakalın

Ümmete Sünnet’tir her türlü halın

Kur’an-ı hakimdi bütün hayatın

Okudum fermanı yanmadan olmaz.

Muhteşem sıralı,inciden diş’in

Gelmemiş cihana bulunmaz eşin

İki cihanın da güneşi sensin

Okudum fermanı yanmadan olmaz.

Edep’le Ravza’na varayım dedim

Eşiğen yüzümü süreyim dedim

O gül cemâlini göreyim dedim

Okudum fermanını yanmadan olmaz.

Doldurur Ravza’nı nur’dan ışıklar

Göz yaşı döküyor gârip aşıklar

Dolansın ruh’uma gül sarmaşıklar

Okudum fermanı yanmadan olmaz

Bedir’de açılan ellere kurban

Cibril’le söyleşen dillere kurban

Beytinde’de yeşeren güllere kurban

Okudum fermanı yanmadan olmaz

Uhud’da kanayan yarana kurban

Mi’râ’ca yükselip varana kurban

Habib’im deyipte verene kurban

Okudum fermanı yanmadan olmaz

Üveys-‘î Kadir-î aşıktır sana

Bir lâhza nazarın erişse bana

Değişmem bu anı iki cihana

Okudum fermanı yanmadan olmaz', 'Gül pembesi beyaz ipektir tenin Geniş göğüslüsün, kuvvetli elin Hak’tan  sürmelidir siyah gözlerin Okudum fermanı yanmadan olmaz Kirpikler u...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Kotan']::text[], 8.5, '{"poet":"Hüseyin Kotan","poet_slug":"huseyin-kotan","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/yanmadan-olmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baba Gogor Neki', 'baba-gogor-neki-huseyin-kotan-h346v', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aylardan nisan toprak çok ıslak

Yerlerde çürümüş bir sürü yarpak

Acımasız gar’ın altında çok galmış

Mevsimin hasretiyle yırtılıp yarılmış

Yorgun bir günün sonunda evime geldim

Hane sakinlerine selamımı verdim

Gız mutfakta uğraşir,hanımın elinde tentene

Yalan ürüzgarı başladı,herif gelsene hele

Lise bitirmiş elinde bir guti

Düğmesine basanda dıd diye ses gelir ne köti

Uzandım baktım oğlum bu nedir? 

Sen neyinnen uğraşırsen dergilerin nerdedir? 

Babacığım buna TETRİS diyorlar

Şimdi gençler hep bununla oynuyorlar

Göz ucuyla baktım üstü bomboş bir ekran

Alt tarafında üç düğme durir yan yana

Oğlan birine basdi,dıd diye bir ses yayıldi

Yukarıdan dörtlü bir kare en alt tarafa bayıldi

Sonra üçlü,ikili,tekli gelir hayınnan

Usta parmaklar çalışır vay vayınan

Bir heyecan bir heyecan sormayın getsin

Sofra gurulmuş,oğlan yemeği netsin

Evladım bırak onu gel de ye yemeğini

Sonra anlatayım sana eski günlerimi

Gaşığı götürürken isteksizce ağzına

Sordum oğlum “AŞŞIH”nedir? düşüverdi tuzağıma

Hani televizyonda saz çalıyorlar ya o değil mi? 

Lokma düşti elimden,gülim mi? ağliyim mi? 

Oğlum ona aşık derler,şimdiki halk ozanı

Ahh…bir elime geçirsem lehçemi bozanı

Hıı…dedi oğlan…baba aşşıh nedir? 

Hanım yandan söylenir hele yemeğinizi yiyin

Peşgun gahsın ortadan,ne söylersez söyleyin

Hızlı hızlı yendi yemek,sofra ortadan kalktı

Sabırsız oğlan şüpheyle yüzüme baktı

Baba…aşşıh nedir? 

Bir elim belimde öbür elim cebimde

Tutulaydı dilim aklıma nerden geldi hemende

Attım elimi omzuna,salona götürdüm

Zora düşmüştüm hani,kesik kesik ösgürdüm

Oğlum sana gençliğimi anlatayım dinle

Anlasanda anlamasanda sözümü kesme

Bu şehri Erzurum’da güzel günler var idi

İnsanları dadaş sokakları dar idi

Bizler geniş bacalarda toz toprakta oynardık

Cığızlanan insanları adamdan hiç saymazdık

Maziye daldı aklım,gözlerim buğulandı

Yıllar öncesi gençliğim hayalimde canlandı

Baharın ilk müjdesi,garlar yeni erimiş

Gavak mahallesi bacaları azdan az yeşermiş

Yerlerden buğ çıkıp,göğe doğru yüskelir

Cevriye ablagilin Cevdet aşşahtan gelir

Neşesi yerinde belli hınzır hınzır gülir

Oğlum aşşıh oynirmisen? 

Sende bu oyuni heç bilmirsen

Hemen ilk gıcığıni verdi

Gel seninle “ŞEG”oyniyah dedi

Bak üstüme gonuşma

Sende ileri adım atma

En kötü aşşıh’ı seçtim yan yana goyduk

Elimizde “ENEKELER”bir o bir ben gondurduk

Ben dipci oldum,cevdet’de yancı

Başladı bende heyecanlı bir sancı

Üç adım öteye gondi,aşığım nesen? 

Sessizce cevap verdim doldurim fesen

Aşığı çiğ geldi,bende azcık dipten uzağa

Yavaşça gondum çukurca bir tuzağa

Aldı enekeyi baş ve işaret barmağında dönderdi

İleri yarım bir adım attı,aşşıhlara gönderdi

Tak! Diye bir ses duyuldu

Tikili aşşıhlar bozuldi töy oldi

O’nun enekesine töy! 

Gitti bizim bir aşşıh vey! 

Sık sık aşşıhları sayirem mala malam yuduzmadım

Gınali leppez enekeyi sayılana gatmadım

Gara yelin tozları hep üstümüze gondi

Kıkırik kesilen parmaklar soğuktan dondi

Eller “GOGOR”bağlamış,”HIMİKLER”akir

Gelen herif geçen gari hep bize bakir

Aşimdi tandır olsa ayaklarımızı sallasak

Eritsek gurşunlari enekeyi nallasak

“MAZANNİ”ler görindi,yanımıza geldiler

ikimizin etrafını bir güzel çevirdiler

Eldeki aşşıhları ceplerimize doldurduk

Ağrıyan belimizle ağır ağır doğrulduk

Gardaş! çuri! gaç adım

Bunlar aşşıh çurlıyacak annadım

yeddi adım bir gaya

Gözler yere çevrildi gaya aramaya

Garışacak ortalık,hır çıkacak besbelli

Enekemi değiştirdim ortası telli

Cevdet…Cevdet seni yere giresen

Baban eve geldi köteğin var bilesen

Cevriye abla tırhıştan bağırdi,canımızı gurtardi

Aşşıh oyununun devamı ertesi güne galdı

Gün anasına guşlar yuvasına gavuşdi

Mazanniler vazgeçdi başımızdan savuşdi

Segirde segirde ESATOĞLU çesmesine vardık

Alacalı ellerimizi yıkamaya başladık

Eski hanın duvarına cakkıl dayali

İç içe duran helkelerin gulpları gırmızıynan boyali

Yaşlı çeşme elede cıl cıl akir

Suyun değdiği yerler alav alav yanir

Su daşıya daşıya omuzlar hep çökerdi

Cakkılla beceremeyenler çoğusuni tökerdi

Uyşan ayağımi indirdim divandan

Esneyen oğlana yavaşça baktım yandan

İşte “AŞŞIH”budur oğlum biz bele oynardık

Gece rüyasını görür,oynamaya doymazdık

Manidar manidar baktı oğlan yüzüme 

Şu suali ekledi en son sözüme

BABA…GOGOR NE Kİ?', 'Aylardan nisan toprak çok ıslak Yerlerde çürümüş bir sürü yarpak Acımasız gar’ın altında çok galmış Mevsimin hasretiyle yırtılıp yarılmış Yo...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Kotan']::text[], 8.5, '{"poet":"Hüseyin Kotan","poet_slug":"huseyin-kotan","theme":"Türk Şiiri","is_hero":false,"total_lines":112,"source_url":"https://www.antoloji.com/baba-gogor-neki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çanakkale Şehitlerine! ! !', 'canakkale-sehitlerine-saim-bastik-ofsm3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bugün 18 mart 2006; Çanakkale zaferinin 91.yıldönümünü gururla kutluyoruz.Kanlarını tepelerden denize kadar akıtıp bu toprağı vatan yaparak bize bırakanları rahmetle,minnetle ve hasretle anıyor onlara binlerce şükranlarımızı sunuyoruz.Sonra…Sonra bu günümüze dönüyor,bugünümüze bakıyor,utanıyor ve ağlıyoruz…

Şimdi; Şimdi Yahya çavuş,Seyit onbaşı ve diğer şehitler çıkıp karşımıza dikilse biz onlara ne diyeceğiz? 

-Kusura bakmayın,siz boşuna kan verdiniz,can verdiniz, onca yıl cephede kalanlar boş yere beklediler,bakın artık biz değiştik bundan sonra askerlik yapmak herkesin kendi vicnanına bağlı ister yapar,ister yapmaz mı diyecğiz! Yoksa… Yoksa,şehitlik ve gazilik artık demode oldu onların da kaldırılması için hazırlık yapıyoruz mu diyeceğiz! 

Şimdi; Şimdi Mustafa Kemal ve arkadaşları karşımıza dikilseler onlara ne cevap vereceğiz? 

-İyi ki hayatta değilsiniz,eğer hayatta olsaydınız sizin hakkınızda da çete kurmaktan iddaname hazırlar sizi mahkûm ettirirdik mi diyeceğiz! Yoksa; Yoksa buvatanı savunmak ve sınırlarımızı korumak için bir sürü cephede boşuna uğraştınız,bakın biz değiştik sınırlarımızı sizin savaştıklarınıza devrediyoruz mu diyeceğiz! 

Ya istiklâl şairimiz Mehmet Akif Ersoy ile yüz yüze gelmiş olsak ona ne diyeceğiz? 

-Akif baba hani sen”Bir hilâl uğruna yarab ne güneşler batıyor” demişsin  ya  çok ayıp etmişsin! Bak şim di biz hilal ile haçı birleştirmek için diyalog başlattık,dinler bahçesi açıyoruz,haçlılar ne derse bir dediklerini iki etmiyoruz mu diyeceğiz! 

Evet; bugün memleketin idaresini elinde bulunduranların ve onların işbirlikçilerinin yaptıklarına bakarsak ne yazık ki bunların denilmesi gerekiyor….Ama biz Türk Milliyetçileri ve ülkücüleri diyoruz ki; 

Onlar kimin neslidir bilmiyoruz ama,Biz Asım’ın nesliyiz,her ne pahasına olursa olsun yurdumuzu çiğnetmiyeceğiz.Hilâlin yerine haçı getirmeye çalışanlara inat biz o hilali gönderden indirtmiyeceğiz,bu vatanı böldürtmiyeceğiz, SİZE SÖZ…SİZE YEMİN…Bizim değiştirilecek eğreti gömleğimiz yok! 

Bizim gömleğimiz bayraktır,vatandır bunlar da bizim kefenimiz olur…

Varlığımız Türk Varlığına Armağan Olsun…Ne mutlu TÜRK’üm diyene……..

18/03/2006', 'Bugün 18 mart 2006; Çanakkale zaferinin 91.yıldönümünü gururla kutluyoruz.Kanlarını tepelerden denize kadar akıtıp bu toprağı vatan yaparak ...', ARRAY['Türk Edebiyatı','Şiir','Saim Bastık']::text[], 8.5, '{"poet":"Saim Bastık","poet_slug":"saim-bastik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/canakkale-sehitlerine-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanrı Huzuru', 'tanri-huzuru-abdullah-oral-gpp6u', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'TANRI HUZURU

İnsanlık borcunu hiç ödemeyen

Hemi kıt akıllılar hem de çoklar

Başkasına tahammül edemeyenler

Nasıl kendisine sadakat bekler

Cihat için yanıp durdukça bağrı

Sanır ki bir tek kendisi doğru

Ki ondan dır insan katline çağrı

Günde beş vakit Us! ta saklım haklar

Üretene düşman hiç üretmemiş

Yiyip içtiğine aklı yetmemiş

Bir gün insan hakkı diye gitmemiş

Tanrı huzurunda aradım yoklar

Din iman diyerek saltanat sürmüş

Bazen koyun kuzu it olup ürümüş

Her dem zenginlerle fakiri vurmuş

Vurguni yem bilmem puşt neyi saklar.', 'TANRI HUZURU İnsanlık borcunu hiç ödemeyen Hemi kıt akıllılar hem de çoklar Başkasına tahammül edemeyenler Nasıl kendisine sadakat bekler Ci...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Oral']::text[], 8.5, '{"poet":"Abdullah Oral","poet_slug":"abdullah-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/tanri-huzuru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Var olan 1', 'var-olan-1-abdullah-oral-huhig', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çalışmak ne kadar önemli is

                                                        Mücadelede o kadar gereklidir

                                                                                      A Oral.

                                VAR OLAN   1

Fabrikalarda köylerde

Sokaklarda alanlarda

Emektir var olan

En kutsal değerdir emek

          Düşünceyle birleşirSosyalizm doğar

                     

Kim demiş sosyalizm Öldü diye 

İşte biz ölmedik

Ölümler boy verdikçe

Yaşarız yüreklerde Sevda sevda

Gün gelir apansız bir gecenin 

Karanlığı çatlatan Şafaklar gibi doğar

                            Düşüncelerim

Düşünüyor diye Öldürülüyoruz

              Ama yılmıyoruz

Sosyalizm bir düşüncedir ölmez.

Ey ellerini yüreğimde

Kanayan yaraya basmış katiller

Sizin gücünüz yetmez

Öldürmeye sosyalizmi

Sömürüden alır gücünü

Kolay mı, sömürünün olduğu yerde

                             Sosyalizm ölsün.

Yürürüm başım dik boyun eğmem

Bir proleterim ben ben kolay ölmem..', 'Çalışmak ne kadar önemli is                                                         Mücadelede o kadar gereklidir                           ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Oral']::text[], 8.5, '{"poet":"Abdullah Oral","poet_slug":"abdullah-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/var-olan-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gardiyan!', 'gardiyan-mesut-ozturk-rdbsn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gülmeyen suratsız insanlar topluluğu var önümde,

Elimdeki mektuba bakıyorum adres doğru mu diye? 

Katılaşan kalbinin yüzüne yansıyan haliyle,

Evet, ne istiyorsun diye, seslendi gardiyan? 

Bakmayın bana öyle, ben katil değilim,

Meraklanmayın, adi hırsız hiç değilim,

Suçum Türk olmak mı? Belki de, emin değilim,

Hapise girme vakti geldi! diye bağırdı gardiyan? 

Ne olursa olsun? Tutuklamışlardı beni dinlemeden,

Avrupanın en pis hapishanesine neydi beni getiren? 

Konuşmaya gittiğim yerde, beni de mahkum eden,

Ellerini kaldır, seni arayacağım dedi gardiyan! 

Ara, sor, ama dinle beni önce, anlatayım derdimi,

Yeter be! kesin artık! Kusturmayın öfkemi,

5 euro için hapis mi yatılır? Söyletmeyin beni,

Tamam, fazla vaktim yok, hadi anlat dedi gardiyan! 

Ben, bu hesabı ödedim bir yanlışlık olmalı,

Makbuz elimde, yatacak mahkum mu kalmadı? 

Üçüncü kez ödettiniz, illahaki avukat mı olmalı? 

insan hakları nerde kaldı? Almanya değil mi yoksa Avrupalı? 

Ters ters baktı, söylendi,  sıktı çaresizce dişini,

Telefona sarıldı, aradı yetkisi olan birisini,

Ne olduysa yumşattı birden sesini,

Serbestsin gidebilirsin dedi gardiyan!', 'Gülmeyen suratsız insanlar topluluğu var önümde, Elimdeki mektuba bakıyorum adres doğru mu diye?  Katılaşan kalbinin yüzüne yansıyan haliyle...', ARRAY['Türk Edebiyatı','Şiir','Mesut Öztürk']::text[], 8.5, '{"poet":"Mesut Öztürk","poet_slug":"mesut-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gardiyan-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Var Olan 2', 'var-olan-2-abdullah-oral-s18nj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Var olan  2

Kuşkusuz öldürebilirsiniz beni

      Ama düşüncelerim

           Her doğan bebekle

             Yeniden yeşerecek

                 Ülkemin her bir yerinden

Zemheri sonrası kardelen gibi

                            Çatısız gecekondulardan

   Sömürü çarkı gibi çalışan fabrikalardan

                             Düşer gelirim yollarına özgürlüğün

Yaşarım inat olsun diye

Bombalar parçalasa da yüreğimi

Yaşar düşüncelerim

Ülkemin dört bir yanında

Ezilen sınıfımda yaşar

Gün gelir Kırsaldan Ağa ırgatından 

                     Üç çocuklu Ayşe kadından.

Kestiğiniz filizler gibi boy verir düşünce

                                            ..

Sizler ister asın kesin beni 

Bir nehir gibi akarım

Yolumdan dönmem

Bir proleterim ben ben kolay ölmem', 'Var olan  2 Kuşkusuz öldürebilirsiniz beni       Ama düşüncelerim            Her doğan bebekle              Yeniden yeşerecek               ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Oral']::text[], 8.5, '{"poet":"Abdullah Oral","poet_slug":"abdullah-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/var-olan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zilan Türküsü', 'zilan-turkusu-halil-yilmaz-cqnha', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Değmeyin dostlar yarama; 

Bu Zilan’ın türküsüdür.

Altında maksat aranmaz, 

Gerçek hayat öyküsüdür.

Ağrı sele boğmuş gözün,

Kan ceset dolunca düzün…

Nice yakmış ateş, közün. 

Ateşler yandı Zilan’da.

İsyan ama niçin isyan; 

Arsız yanlış eder beyan, 

Kimi atlı kimi yayan,

Yiğitler yandı Zilan’da.

Satılmış beyin elinde,

Sahipsiz hayat selinde, 

Körpe yavrusu belinde,

Gelinler yandı Zilan’da.

Yol alırken öze doğru, 

Hakkı olan söze doğru,

Matem indi göze doğru,

Gözler kanadı Zilan’da. 

Ağladı dağ ayrılmaya,

Kıymadı düz sarılmaya,

Yol gider mi varılmaya? 

Yollar varmadı Zilan’da. 

Çoluk-çocuk, kadın-erkek,

Hasta-yaşlı, körpe bebek; 

Yaşamaktı bütün dilek…

Dilek tutmadı Zilan’da. 

Eritmiş Ağrı’m karanı, 

Matem vurmuş pınarını,

Felek yüklemiş kahrını, 

Ecel kolladı Zilan’da. 

Pusuya yatmış hainler,

Dere inler, tepe inler…

Ayrımıydı sanki dinler, 

Tek din İslam’dı Zilan’da.

Gök gürledi, yer inledi,

Mermiler ah dinlemedi… 

Ana yavrusunu görmedi, 

Hasretler yandı Zilan’da. 

Birleşmedi körpe eller, 

Tarif etmez günü sözler, 

Hasret gidermedi gözler, 

Mahşer canlandı Zilan’da.

Kıyıldı binlerce cana; 

Hemi cana hem canana. 

Namusu kirlemiş ana; 

Kirler utandı Zilan’da. 

Kaçan yavru süngülendi, 

Kanıyla Zilan güllendi…

Bu Zilan azdır dendi, 

Zilan silindi Zilan’da.

Gün çekildi utancından, 

Dereler aktı kanından, 

Taviz vermez inancından,

Onlar yandı Zilan’da. 

O gün başka inler Ağrı; 

Alev alev yanar bağrı, 

Zilan’ına eder çağrı, 

Cevap gelmedi Zilan’da.

Kokuşmasın tenler diye, 

Sular dönüyor deliye, 

Gelir mi dost kelepçeye? 

Bentler kırıldı Zilan’da. 

Bin dokuz yüz otuz yılı,

Temmuz ayı yaktı eli,

Kesildi söz ister dili, 

Sözler tutmadı Zilan’da 

Ezberlenmiş o türküler; 

Mazlum söyler zalim dinler… 

Her türküye maya derler: 

Türküler kaldı Zilan’da 

                    Mayıs 1997', 'Değmeyin dostlar yarama;  Bu Zilan’ın türküsüdür. Altında maksat aranmaz,  Gerçek hayat öyküsüdür. Ağrı sele boğmuş gözün, Kan ceset dolunca...', ARRAY['Türk Edebiyatı','Şiir','Halil Yılmaz']::text[], 8.5, '{"poet":"Halil Yılmaz","poet_slug":"halil-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":73,"source_url":"https://www.antoloji.com/zilan-turkusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Var Olan 3', 'var-olan-3-abdullah-oral-xvz25', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Var olan  3

Öldürebilirmişsiniz? 

Selviyi kesseniz dibinden

Ölmez yanılmayın sakın

Bir selvi kesseniz Binlerce filiz sürer

Kökünden söküp atmalısınız

Koparmalısınız topraktan.

Ama gücünüz yetmez buna

Milyonlarca selvi filizlendi

Umut umut bu ülkede

Bitirmeye çalışırken Selvileri

Sizler ey kokuşmuş düzenin

                         Kirli yüzlüleri

Sizler tükeneceksiniz..

Kokuşmuş düzeniniz

Yıkacak sizleri

Baskılar sömürüler

Yaşatacak sosyalizmi

Yaşama sevdası saracak

Tüm benliğimizi

İşte o gün doğacağım yeniden

Bir proleterim ben Ben kolay ölmem', 'Var olan  3 Öldürebilirmişsiniz?  Selviyi kesseniz dibinden Ölmez yanılmayın sakın Bir selvi kesseniz Binlerce filiz sürer Kökünden söküp at...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Oral']::text[], 8.5, '{"poet":"Abdullah Oral","poet_slug":"abdullah-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/var-olan-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Var Olan 4', 'var-olan-4-abdullah-oral-tthyg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Var olan 4

Orakta çekiçte ben varım

Başakları toplarım orakla

Alın terim kokar çekicimin sapı

Mengene ağzında

İşkencede kalır sevdam

Kaynak makinesiyle puntalanmış

                           Yaşama direncim

 Kolay kopmaz

Torna aynasına sıkışmış gözlerim.

Tavlanan çelik değil

Yüreğimdir ocaklarda

Tavlandıkça kızaran 

Kızardıkça kızıllaşan

Meneviş rengi sevdalardayız

O gün geldiğinde pul pul dökülür 

Nasırlı ellerden sevda 

Aşktan ve sevgiden yana 

Doğar sosyalizm Güneşim

Tanyeri ağartan

Kızıllığıyla doğar

                           ilk ışıkla doğacağım yeniden 

O günü görecektir benden gelen 

Bir proleterim ben Ben kolay ölmem', 'Var olan 4 Orakta çekiçte ben varım Başakları toplarım orakla Alın terim kokar çekicimin sapı Mengene ağzında İşkencede kalır sevdam Kaynak ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Oral']::text[], 8.5, '{"poet":"Abdullah Oral","poet_slug":"abdullah-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/var-olan-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Var Olan 5', 'var-olan-5-abdullah-oral-mv7ie', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Var olan  5

Uçaklarda ben varım 

Uydularda ben

Bastığınız toprakta ben

Kara sapanın sapında ben varım 

Buğdayların başaklarında ben..

Üreten benim

Yaratan ben

Nasırlı ellerim bilir

Lokomotiflerde teker

Gemilerde motorum ben 

Maden ocağında

Katledilen emek

Tanklarda paletim ben

Makinelinin ateş kustuğu tetiğim 

Potalarda eritilen maden

Kolay mı madeni çeliğe dönüştürmek

İşlemek boy boy

Panzerlerde bağlı cıvatayım ben.

Namluda mermiyi patlatan iğneyim

Çekilmeye hazır tetiğim ben

Bir proleterim ben Ben kolay ölmem.', 'Var olan  5 Uçaklarda ben varım  Uydularda ben Bastığınız toprakta ben Kara sapanın sapında ben varım  Buğdayların başaklarında ben.. Üreten...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Oral']::text[], 8.5, '{"poet":"Abdullah Oral","poet_slug":"abdullah-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/var-olan-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Var Olan 6', 'var-olan-6-abdullah-oral-u9r0n', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Var olan 6

Yattığınız yatakta ben varım

İçtiğiniz çayda ben

Mısırda, buğdayda ben varım

Zeytinde, şekerde ben

Demlendiğiniz rakıda ben varım

Sigaranın tütününde ben

Varolan benim...

Nasırlı ellerde sancı ben

Attığınız her adımda ben varım

Gecekonduların kuytularında ben

Doğuda katledilen yürek benim

Sanayide yok sayılan emek ben

Köyde ben

Şehirde ben 

İşkencede ben 

Ölümlerde ben

Namlunun ucunda

Kurşun benim

Polisin önünde hedef ben

Bir proleterim ben

BEN KOLAY  ÖLMEM', 'Var olan 6 Yattığınız yatakta ben varım İçtiğiniz çayda ben Mısırda, buğdayda ben varım Zeytinde, şekerde ben Demlendiğiniz rakıda ben varım...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Oral']::text[], 8.5, '{"poet":"Abdullah Oral","poet_slug":"abdullah-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/var-olan-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neresi İstanbul?', 'neresi-i-stanbul-hamza-cobanoglu-zxy6p', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İstanbul! Ah İstanbul yine kayboldun gözlerimde,

Girmek istedim de buz gibi, masmavi denizine,

Islatmadan bıraktın beni kasvetli matemine.

İstanbul, yine kayboldum bıraktığın yerde.

Beyatlı’dan Fazıl’a ne buldular sende,

Ya da neydi aradıkları yıllar boyu

Ekmek peşindeki martılardan 

Ve şehvet içine düşmüş mahlûkattan

Nasıl da zevk aldılar? 

Kuytularında koklaşan yapmacık sevdalılar,

Ve göbeğinde yaşayan, sebepsiz kalmış insanlar,

Dolmabahçe, Tophane'' ymiş, Sultanahmet,

Aksaray’ dan Laleli ’ye akan; günah üstüne günah.

Ne biçim bir sevdadır, besledik yıllar boyu

Boğazın pasağına girmiş milyonlar

Zevkten dört köşe sarhoş kızlar, kanı deliler

İstiklâl’de Beyazıt’ta dolaşır yetim herifler.

Aniden bastırıyor İstanbul’da yağmur

Bir sürü ahmak sırılsıklam yollarda

Kaldırımlar kayıyor ayaklarım altında

Yollar ıslak, saçlar ıslak, gözler ıslak...

Okmeydanı, Cerrahpaşa, Kadıköy,

Solgun yüzler, donuk gözler, acı sözler

Kapkara kesilmiş dehşet içinde güzellikler.

Yürekleri masum yüzlü çocukların,

Ağlıyor aslında, keder içinde keder.

Kızkulesi deniz içine mahpus,

İçinde bir kız yatar güzelliğine mahpus,

Galata’ dan atlayıp fırtınalı denizlere; 

Ölü canlar, sönmüş canlar, zavallılar...

Aç kaldım, susuz kaldım, aşksız kaldım,

Sabahları bırakıp gecelerine daldım,

Tophane'' yle Ortaköy’de dem aldım,

Boşa zaman harcadım, boşa kürek salladım.

Eh İstanbul şimdi kızgınım sana,

Ama korkarım ışıklar senden yana

Prangalar oramda, buramda, şuramda,

Kör düğümler atılır Hisar’dan Bostancı’ya.

İstanbul! Ah İstanbul yine kayoldum gözlerinde

Haliç’te, Karaköy’de, Boğaziçi’nde

Bir garip sükut içinde 

Kayboldum İstanbul, kayboldum gözlerinde.', 'İstanbul! Ah İstanbul yine kayboldun gözlerimde, Girmek istedim de buz gibi, masmavi denizine, Islatmadan bıraktın beni kasvetli matemine. İ...', ARRAY['Türk Edebiyatı','Şiir','Hamza Çobanoğlu']::text[], 8.5, '{"poet":"Hamza Çobanoğlu","poet_slug":"hamza-cobanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/neresi-istanbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuş', 'kus-adem-baser-nuuwx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kuş

Güneşin doldurduğu odamın

Karşısında ki ağaçta  yuvalanan

Kuş gibi olmayı arzu etsem de çoğu  zaman; 

Erkeklikten el veririm vazgeçerim,

Vurulup düşme  korkusundan..', 'kuş Güneşin doldurduğu odamın Karşısında ki ağaçta  yuvalanan Kuş gibi olmayı arzu etsem de çoğu  zaman;  Erkeklikten el veririm vazgeçerim,...', ARRAY['Türk Edebiyatı','Şiir','Adem Başer']::text[], 8.5, '{"poet":"Adem Başer","poet_slug":"adem-baser","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kus-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-adem-baser-3q4hi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen

Bir sarhoş için şarap neyse

Benim  için sende öylesin

Senin gönlün yaban ellerdeyse

Garip gönlüm buna neylesin

Sonbahar  bir yaprak için nasılsa

Zayıf kalbim için yokluğun öyle

Eğer bir gün  gidişin hasılsa

Dayanabilir mi kalbim  söyle?', 'Sen Bir sarhoş için şarap neyse Benim  için sende öylesin Senin gönlün yaban ellerdeyse Garip gönlüm buna neylesin Sonbahar  bir yaprak için...', ARRAY['Türk Edebiyatı','Şiir','Adem Başer']::text[], 8.5, '{"poet":"Adem Başer","poet_slug":"adem-baser","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sen-791-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arkadaş', 'arkadas-adem-baser-nuh8v', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Arkadaş

Çizik ve eski masamın üstünde

Kalemlerim kitaplarım birde yapraklı takvimim

En büyük oyuncaklarımdır benim,

Çünkü gün boyu hiç birini elimden düşürmem

Penceremden görünen yaşlı ıhlamur ağacı ise

Sadece  sallanır gün boyu; 

Bir sağa bir sola bir sağa bir sola……', 'Arkadaş Çizik ve eski masamın üstünde Kalemlerim kitaplarım birde yapraklı takvimim En büyük oyuncaklarımdır benim, Çünkü gün boyu hiç birin...', ARRAY['Türk Edebiyatı','Şiir','Adem Başer']::text[], 8.5, '{"poet":"Adem Başer","poet_slug":"adem-baser","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/arkadas-121-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hapis...', 'hapis-cengiz-suslu-6diym', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Burası; ..cezanın yuva dediği..

Bedeni buz gibi hapis kardeşim

Ne; ..eksik..ne,..fazla bedel verdiği

Kokusu suç gibi hapis kardeşim

          Sabahın köründe iki cümle ses

          Sayım var maltada dizilsin herkes

          İnsanın burnundan aldığı nefes,

          Dört duvar içinde hapis kardeşim

Koğuşta..tüm mevcut otuzdört kişi

Çoğunun hırsızlık dışarda işi

Kiminin eli yok,kiminin dişi

Sağlamda..çürükte..hapis kardeşim

           Ranzalar…üç katlı,hepsi demirden

           İnsan kokuları gelir derinden..

           Kemiği,iliği birbirlerinden

           Sinsice ayırır hapis kardeşim

Ortada sac soba..kahveden rengi

Müebbete mahkum..belinden eğri

Her cisim bizimle aynı kaderi

Yaşıyor...burası hapis kardeşim

             Bir duman cigara,hasrete mektup

             Dudağa süzülen yaşını yutup

             Titreyen ellerde umudu tutup 

             Yarına..merhaba hapis kardeşim

Çaresiz...her gece…sabaha kadar

Bir soba başında yirmi kişi var

Bir cigara söner..birisi yanar

Uykular..ışığa hapis kardeşim

            Yıldızlar semada sönerken..tek-tek

            Kalp ürekek..göz ürkek..bedenler ürkek

            İstediğin kadar yok-a kürek çek

            Halatlar..babaya hapis kardeşim

Aşkına eşkiya gencecik bir zat,..

Sırtına yüklemiş,pişmanlık kat-kat

Bedeni..ruhunu etmiyor azat

Çare..kafeslerde hapis kardeşim

             Cümleler tükenir..suskunluk çöker

             Bakışlar..bugünle yarını diker

             Çözülür..bedenler,hep teker-teker

             Bir hece…ses..burda hapis kardeşim

Duvarlar..ölçülmüş,biçilmiş kaya..

Dev gibi dikilmiş! ..Yerden havaya

Suçsuzum desende tutuklusun ya..

Niyetin..ha-temiz..ha-pis kardeşim

               Kimisi..zavallı! ..Küsmüş Allah’a

               Kimi..anasına..,kimi babaya             

               Kimisi..bir resmi basmış bağrına

               İman..inanç..sevgi hapis kardeşim

Küskünlükle dolu bu gönül hanem

Sabır..ve şükür...bir tek bahanem

Eşime-dostuma ettiğim sitem..

Dilimde,kalbimde..hapis kardeşim

                Ayvalıktan bir dost! ..Adı; ..Mustafa

                Sivilde balıkçı...takılmış ağa

                Yirmi sene yemiş,bitmemiş hala..

                Bu bayramda burda hapis kardeşim

Hey..Gardiyan! Getir müddetnamemi

Kaç gün cezam kaldı,söyle süremi

İstersen ateşle dağla derimi

Acılarda..burda hapis kardeşim

                 Arif dede,ellibeşini geçmiş

                 Buraya esrarı çekmekten gelmiş

                 Niyet satmak değil,yalnız içmekmiş

                 Bir yudum..zevkine hapis kardeşim

Sus be rüzgar! ..Susta yatayım

Ömürden bir günü daha atayım

Bu hayatın.. Anasını satayım

Gündüzler..geceye hapis kardeşim

                 Gün gelip.. esaret elbet bitecek 

                 Ettiğim dualar..göğe erecek

                 Acımda..sızımda…orda bitecek

                 Şeytan..imanımda hapis kardeşim

Bana kuvvet veren..Allah-İnancım

Üç yiğidim..birde gönül ilacım

Hayırlısıyla..görmek-amacım

İmana sınavdır hapis kardeşim..

16.12.2001(Ramazan bayramı..1.gün)

Cengiz Süslü', 'Burası; ..cezanın yuva dediği.. Bedeni buz gibi hapis kardeşim Ne; ..eksik..ne,..fazla bedel verdiği Kokusu suç gibi hapis kardeşim         ...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Süslü']::text[], 8.5, '{"poet":"Cengiz Süslü","poet_slug":"cengiz-suslu","theme":"Türk Şiiri","is_hero":false,"total_lines":78,"source_url":"https://www.antoloji.com/hapis-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benzetmek gibi olmasın…', 'benzetmek-gibi-olmasin-cengiz-suslu-sq1cq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Koca bir hayattı bıraktığımız 

Ardımızda..Ateşe verip yaktığımız

Ne bitmemiş yol kaldı yüreğimizde

Nede mutluluk…Azda olsa yaklaştığımız

Hep umut besledim…Birini öldürüp,..

…birini dirilttim.Yeni baştan

Ateşlenen her acımı,sabırla söndürüp,..

…bir-bir meyvesini topladım,kuru ağaçtan

Hissettiğim hayatı yaşamak değildi

Yorgunluğumda..Nefes almak vermekti

İsyanım kabarıp gönül kafesimi doldurduğunda

Bir damla gözyaşın sızımı dindirdi

Koparıp bütün inançlarımın halatlarını

Elimi uzatmak istediğimde enginlere…

Bu sefer irademin savaşını,.. 

…bitiremedim…İman derinliğinde…

Her başlangıcın bir sonuna inanarak

Kabuğuma çekilip sindirdim arzularımı

Artık her şeyi oluruna bırakarak

Yokluğuna peki deyip,susturdum korkularımı

..

Şimdi ben yaşanmamış bir sevdanın

Vurgun yemiş sersemi..Acılarını seven adam

Sondaki başlangıcı bekleyen…Durgun..denizler gibi,…

Benzetmek gibi olmasın..yaram…

2004

Cengiz Süslü', 'Koca bir hayattı bıraktığımız  Ardımızda..Ateşe verip yaktığımız Ne bitmemiş yol kaldı yüreğimizde Nede mutluluk…Azda olsa yaklaştığımız Hep...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Süslü']::text[], 8.5, '{"poet":"Cengiz Süslü","poet_slug":"cengiz-suslu","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/benzetmek-gibi-olmasin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eller', 'eller-mehmet-i-limen-xfsct', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yüreğimi verdiğim eller

Avuçlarında yüreğimi ezer

Sıkar patlatırcasına, ah o eller

Taze bir yaranın kabuğunu kaldırır,

Ateş kırmızı, sıcak, kor gibi bir yara,

Sıcağından kendide köz olan

Bembeyaz, ince, zarif 

Tutulası, öpülesi eller.

Eller ufak, maharetli

Gözümdeki yaşı silen,

Göz yaşımın sebebi eller

Beni benden geçiren 

Yüreğimi verdiğim eller,

Ellerin...', 'Yüreğimi verdiğim eller Avuçlarında yüreğimi ezer Sıkar patlatırcasına, ah o eller Taze bir yaranın kabuğunu kaldırır, Ateş kırmızı, sıcak, ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet İlimen']::text[], 8.5, '{"poet":"Mehmet İlimen","poet_slug":"mehmet-i-limen","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/eller-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Unut', 'beni-unut-seval-kemertas-v5l3g', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yarım bıraktım aşkı

şarkıların inleyen nağmesinde

içimde bir sonbahar

ne yağmur diniyor ne rüzgar

öfkenin kedere sarıldığı

bu mahsun saatlerde

yenik düşüyorum hayatın hilesine...

sen elveda deyip giderken

ardından baktım sessizce

yelkenler ipini kopardı

kalbimin sahilinden

acı ayaz gibi oturdu içime

üşüyen duygularım koptu 

en ince yerinden

hasret konakladı gözlerime

sanki cehennem ateşleri yağdı üstüme

şimdi sen beni anlat

yürüdüğün sokaklara

ben unutmuşum beni nasıl olsa

senin hayatın olmak adına

sen de unut mavi sevdam

beni unut! ..

yine canımın içinde saklarım seni

sen içini rahat tut

unut beni göz bebeğim

beni unut! ...

19/08/2003', 'yarım bıraktım aşkı şarkıların inleyen nağmesinde içimde bir sonbahar ne yağmur diniyor ne rüzgar öfkenin kedere sarıldığı bu mahsun saatler...', ARRAY['Türk Edebiyatı','Şiir','Seval Kemertaş']::text[], 8.5, '{"poet":"Seval Kemertaş","poet_slug":"seval-kemertas","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/beni-unut-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haberin var mı..? (Şarkı sözü)', 'haberin-var-mi-sarki-sozu-cengiz-suslu-zi4wg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu benim seçimim olmadı inan

Doğmadan kalbime yazılmış sevdan

Bu garip ateşe düştüğüm o an

Kaçmadım sarıldım haberin varmı

Şimdi bu alemin tam ortasında

Tutuklu misali her voltasında

Kur-an’ın İncil’in her sayfasında

Hastayım yastayım haberin varmı

Bir sen kaldın inan benim düşümde

Hep gözyaşımdasın hep gülüşümde

Dudaktan kalbime her girişinde

İçimi dağladın haberin varmı

Cengiz Süslü   1999', 'Bu benim seçimim olmadı inan Doğmadan kalbime yazılmış sevdan Bu garip ateşe düştüğüm o an Kaçmadım sarıldım haberin varmı Şimdi bu alemin t...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Süslü']::text[], 8.5, '{"poet":"Cengiz Süslü","poet_slug":"cengiz-suslu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/haberin-var-mi-sarki-sozu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ateşe Düştüm', 'atese-dustum-seval-kemertas-cbyrh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'yitirdim kimliğimi

bu kentin sokaklarında

bilmiyorum kimim

adım ne...

içimde buz gibi bir cehennem yalnızlığı

her gün bir öncekinden bin beter halde

kahır kahır bir kış yağıyor üzerime...

hayallerim bile ızdırap veriyor artık

topyekün firarda bütün sevmelerim

sahipsiz bir sevda

derin bir ahhh oldu acıyor içimde

ve ben tep tenhayım

ve ben üşüyorum alabildiğine...

düşleri eskimiş bir yüreğim şimdi

acım damla damla akıyor gözlerimden

bütün sevinçlerim kırgın

bütün haykırışlarım suskun

acılar yankılanırken yüreğimde

kitapsızca bir aldanışın zehri

kanıyor gülüşlerimde...

12/05/2004', 'yitirdim kimliğimi bu kentin sokaklarında bilmiyorum kimim adım ne... içimde buz gibi bir cehennem yalnızlığı her gün bir öncekinden bin bet...', ARRAY['Türk Edebiyatı','Şiir','Seval Kemertaş']::text[], 8.5, '{"poet":"Seval Kemertaş","poet_slug":"seval-kemertas","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/atese-dustum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gece Son Defa', 'bu-gece-son-defa-seval-kemertas-vep4e', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bu gece son defa

geleceğim rüyalarına

son bir kez daha

dokunacağım duygularına, 

yara bere içinde kanayan bir kalp

darmadağın bir hayat bırakacağım

hiç tutamadığım

o sımsıcak avuçlarına...

yüreklerimizin amansız çarpışması

yaşadığımız büyük kargaşa

yanılgılar, 

düş kırıklılları 

benimle birlikte bitecek

ve sen uyanırken

dingin, gururlu aydınlık bir sabaha

ben bir kez daha yenileceğim

mağlup olacağım sana...

artık..ayrılığın o zehirli tadı

sarmalayacak  yaralarımı, 

yırtıcı, yabanıl bir hayvan gibi

yenik düştüğüm köşede

kabuslar içinde kıvranacağım

kendi kendimi kanatacağım belki de...

bilinmez kaç ödünç alınmış gün daha

bu çığlık acıyacak içimde

kaç sancı saplancak yüreğime

iki büklüm olacağım yine

iliçtiğim hayatın bıçak sırtı sokaklarına, 

incecik, verem bir yalnızlkla

serilecek anarşist ruhum

ve ben yok olacağım

siren sesleriyle ağlarken gece...

06/05/2003', 'bu gece son defa geleceğim rüyalarına son bir kez daha dokunacağım duygularına,  yara bere içinde kanayan bir kalp darmadağın bir hayat bıra...', ARRAY['Türk Edebiyatı','Şiir','Seval Kemertaş']::text[], 8.5, '{"poet":"Seval Kemertaş","poet_slug":"seval-kemertas","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/bu-gece-son-defa-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdim..', 'sevdim-yasar-tezel-a0dlc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben hep seninle sensizliği sevdim

Sende sevdiğim her türlü ezgiler

Busene kondurulmuş gülü sevdim

Sevdim seni tarifsiz hissedişlerle

Sebebi yok bu sevginin,gözlerin

Davetkar bakışlarını nazını sevdim', 'Ben hep seninle sensizliği sevdim Sende sevdiğim her türlü ezgiler Busene kondurulmuş gülü sevdim Sevdim seni tarifsiz hissedişlerle Sebebi ...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Tezel']::text[], 8.5, '{"poet":"Yaşar Tezel","poet_slug":"yasar-tezel","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sevdim-71-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çanakkale Şehitlerimiz', 'canakkale-sehitlerimiz-hasan-ozturk-2-d4k2p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Doksandört yıl önce Çanakkale''de,

Geride bırakıp da ana yar aşkını,

Boğaz da donanmaları durduran,

Ulusal güçlere, meydan okuyan,

Ömrünü cephede dolduran şehitlerimiz.

Ellerini kazma kürek yapan.

Savunmak için, siperler açan,

Ya istiklal, ya ölüm adına,

Aç, susuz, uykusuz kalan,

Vatan aşkıyla yanan, şehitlerimiz.

Arıburnu, Kumkale, Gelibolu da.

En ağır silahlara karşı,

Türk süngüsüyle zafer kazanan,

Çanakkale geçilmez diye,

Dünya da tarih, yazan şehitlerimiz.

Yüreğimizde yaşar, yüzdoksanbin kişi,

Ebedi hatıradır, isimleri, resimleri.

Bu vatanın, bu bayrağın bekçisi.

Sonsuza kadar sizinledir, Türk gençi.

Ruhunuz şad olsun Çanakkale Şehitleri.', 'Doksandört yıl önce Çanakkale''de, Geride bırakıp da ana yar aşkını, Boğaz da donanmaları durduran, Ulusal güçlere, meydan okuyan, Ömrünü cep...', ARRAY['Türk Edebiyatı','Şiir','Hasan Öztürk 2']::text[], 8.5, '{"poet":"Hasan Öztürk 2","poet_slug":"hasan-ozturk-2","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/canakkale-sehitlerimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayret Sana…MP3 Formatında sanatcı BUSE den dinlemek için tıklayın', 'hayret-sana-mp3-formatinda-sanatci-buse-den-dinlemek-icin-tiklayin-cengiz-suslu-2e9ui', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dün gece bir sen vardın benim yanımda

Dün gece ateş gibi  canocağımda

Dün gece kan gibi damarlarımda

Dolaşıp durdun içimde hayret sana

Hayret hani çıkmayacaktın ya karşıma.ah...

Hayret hani girmeyecektin rüyalarıma

Bir daha hatırlatmayacaktın sevdanı bana

Bir kerede sözünde dur hayret sana

2003

Cengiz Süslü

Müzik ve aranje:Ceyhun Celik

Okuyan sanatcı:Buse (İlk Albüm) ..Canlı-Canlı

Firma:Dirlik müzik&film

Stüdyo:DFM Company', 'Dün gece bir sen vardın benim yanımda Dün gece ateş gibi  canocağımda Dün gece kan gibi damarlarımda Dolaşıp durdun içimde hayret sana Hayre...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Süslü']::text[], 8.5, '{"poet":"Cengiz Süslü","poet_slug":"cengiz-suslu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/hayret-sana-mp3-formatinda-sanatci-buse-den-dinlemek-icin-tiklayin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Simsiyah Bir İhtilal', 'simsiyah-bir-i-htilal-muhammed-mehmet-gul-ufjfh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '*Açarsam gözlerine bir daha kapılarımı 

Eminimki hınçla yağmalayacaksın durmadan

Gözlerimi ve bütün gördüklerimi varımı

Biliyorum yağmalayacaksın birşey sormadan

*Açarsam gözlerine bir daha kapılarımı 

*****Ben Osmanlıdan kalan gizlenmiş son muhkem kale

*****Sen hala sevdalısın simsiyah bir ihtilale

*Açıldığında tüm kapılar başlayan talandı

Yanılgıydı apaçık yenilgiydi benimkisi

Gerisi buhran gerisi imtihan ve gerisi yalandı

Günlerce kurşun gibi göğsümde taşıdım ye''si

*Açıldığında tüm kapılar başlayan talandı

*****Yürüdüm ayaklarımda bukağı boynumda lale

*****Yürüdüm dört yanı kuşatılmış bir istikbale

*Vakitsiz istilaydı bu zindanlarda kaldım

Gönül şehrime bak taş üstünde taş bırakmadın

Umutsuzca zamanın ötesine haber saldım

Nice ağıtlar yaktım gözümde yaş bırakmadın

*Vakitsiz istilaydı bu zindanlarda kaldım

*****Sonunda sürdün savurdun beni şimale

*****Düşürdün ruhumu tarifi imkansız melale', '*Açarsam gözlerine bir daha kapılarımı  Eminimki hınçla yağmalayacaksın durmadan Gözlerimi ve bütün gördüklerimi varımı Biliyorum yağmalayac...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Mehmet Gül']::text[], 8.5, '{"poet":"Muhammed Mehmet Gül","poet_slug":"muhammed-mehmet-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/simsiyah-bir-ihtilal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cemile Düzgün, Ahmet Yozgat Ve Sevinç Kavuk', 'cemile-duzgun-ahmet-yozgat-ve-sevinc-kavuk-mustafa-aslan-2-b9xwp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Cemile annem sen büyüklerden de büyüksün,

Sen sanki boynumda tasidigim bir yüktün,

Bana en güzel ögüttün,

Manevi annem oldun, beni sen güldürdün.

Ögretmenlik yaptin, yillarini verdin,

Sen kendini sadece bana degil, bütün insanlara sevdirdin,

Annem anlat bana neolursun senin yok mu hiç derdin,

Hep benim gibi gençlerle ilgilendin,

Sen belkide gönüllerde hep tektin.

Ben sevemiyorum, kendini bana annem gibi sevdirdin.

Seni annem gibi sevecegim, sonu ölüm olsada.

Ahmet abim, sen benden de dertlisin,

Yeni tanidim seni ama gönlümde tam yerindesin,

Abilginde hep birincisin,

Sen gönüllerde en güzel sairsin,

Abimsin.

Seni anlatmak güçtür benim dilimde,

Sakin ola yanlis arama sana olan sevgimde,

Abim oldun, öyle kalacaksin sonsuzca yüregimde,

Belki de yeni bir aci oldu yüregimde,

Korku oldun gözlerimde,

Uyuyamaz oldum, seni düsünürken gecelerimde.

Sevinç ablam, sen canimsin,

Canimdan bir büyük parçasin,

Her yazdigim siirimde yanimdasin,

Hep kanimdasin.

Yorumlarinla beni sevindirdin,

Yazdigin mesajlarla beni havalarda gezdirdin,

Benim hiç ablam yok, ama biliyorum simdi sen varsin,

Verdigin ögütlerle sairligimdeki ustasin,

Sen birtanesin, canimsin.

Siirlerinde gördüm bazi gerçekler,

Dertlisin, ama derdini bir anda silebilirsin,

Sen kendi derdini degilde, baskalarinin dertdine dertlisin.

Ya ablam sana kelime bulamiyorum,

Tek kelime ile sen bir meleksin.

Tarih Ve Saati: 20-03-2006	19:50

Not: Bu yazdigim siiri, bu sitede yeni tanimis ve canimdan çok sevdigim 3 kisiye armagan ediyorum. Okumanizi Tavsiye Ederim.', 'Cemile annem sen büyüklerden de büyüksün, Sen sanki boynumda tasidigim bir yüktün, Bana en güzel ögüttün, Manevi annem oldun, beni sen güldü...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aslan 2']::text[], 8.5, '{"poet":"Mustafa Aslan 2","poet_slug":"mustafa-aslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/cemile-duzgun-ahmet-yozgat-ve-sevinc-kavuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğuyordu Güneş', 'doguyordu-gunes-sukran-besisik-tugiu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şanlı mazinin muhteşem zaferlerine denk,

Bir düzine zafer kazanıncaya dek,

İman aşkıyla şahlanarak,

Bendine sığmayan sel gibi coşarak

Hızır ile eşleşti o büyük kahraman.

Ağlıyordu Sarıkamış, Kars, Ardahan,

Erzincan, Erzurum olmuştu perişan.

Yakıp yıkıyordu alçak düşman.

Haddini bilmeyene bildirmek gerekti,

O sanki gökten inmiş melekti.

Bindokuzyüzyirminin otuz Ekim''i

Onbeşinci kolordu, o büyük komutan,

Şahlanarak kırıyor esaret zincirini.

Dalgalanıyor bayrağımız

Kars Kalesi burçlarında.

Doğuyordu güneş, ağrıyordu tan.

Elinde meşale imanlı ordu,

Korudu bu güzel yurdu.

Pırıl pırıl güneş, gülüyordu sema,

Zafer sarhoşluğunda dağ, taş, ova.

Kazım Karabekir Paşa''ya ithaf, 5 Şubat 2002', 'Şanlı mazinin muhteşem zaferlerine denk, Bir düzine zafer kazanıncaya dek, İman aşkıyla şahlanarak, Bendine sığmayan sel gibi coşarak Hızır ...', ARRAY['Türk Edebiyatı','Şiir','Şükran Beşışık']::text[], 8.5, '{"poet":"Şükran Beşışık","poet_slug":"sukran-besisik","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/doguyordu-gunes-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keşke Esebilse', 'keske-esebilse-volkan-yoruc-qeseg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kaderler düşlendikçe yaşansa

Her yaşanmayla renge bürünse

Kırmızıya yeşile maviye

Renkten renge 

Bir nefesle bir görüşte sımsıkı elele

Öylece ömürden sürse

Bitmemecesine

Hayaller düşlendikçe gerçekleşse

Sevgiler damlasa gönüllere

Adı aşk olsa

Ve meltem bile keşke o yöne esebilse 

Keşke', 'Kaderler düşlendikçe yaşansa Her yaşanmayla renge bürünse Kırmızıya yeşile maviye Renkten renge  Bir nefesle bir görüşte sımsıkı elele Öylec...', ARRAY['Türk Edebiyatı','Şiir','Volkan Yoruç']::text[], 8.5, '{"poet":"Volkan Yoruç","poet_slug":"volkan-yoruc","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/keske-esebilse-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deveci', 'deveci-hasan-ozturk-2-8uqjd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dağ demez taş demez,Yükü alır sırtına,

Bir kızarsa, sakın yaklaşmayın yanına.

Deve kinci, sever güreşi,güreş yürek işi,

Çek deveci develeri, burası deve memleketi.

Yıkılmadı duruyor deve damlarımız,

Eskiden deveyle göç etmiş atalarımız.

Yörüktür aslımız, devecidir namımız,

Çek deveci develeri, burası deve memleketi.

Yarın meydanda görsün, deveyi hamutla yutanlar,

Deveden birşey kapsın, yanlış düzen tutanlar.

Eğlensin muhabbete doysun, dostlar düşmanlar.

Çek deveci develeri, burası deve memleketi.', 'Dağ demez taş demez,Yükü alır sırtına, Bir kızarsa, sakın yaklaşmayın yanına. Deve kinci, sever güreşi,güreş yürek işi, Çek deveci develeri,...', ARRAY['Türk Edebiyatı','Şiir','Hasan Öztürk 2']::text[], 8.5, '{"poet":"Hasan Öztürk 2","poet_slug":"hasan-ozturk-2","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/deveci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne yazar…(Şarkı sözü)', 'ne-yazar-sarki-sozu-cengiz-suslu-lwh5d', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gönlümün gözünden son düşen sensin

               Bir daha karşıma çıksan ne yazar

               Bu kahpe kavgada sen beni yendin

               Sarılıp teselli etsen ne yazar

               Ne yazar çok sevdim desen ne yazar

               Ne yazar değiştim desen ne yazar

               Ağlasan ne yazar gülsen ne yazar

               Bahar geçti gitti gelsen ne yazar

               Bir damla su idin süzülüp gittin

               Bir vardın bir yoktun sır oldun bittin

               Bıçak gibi gelip kemiğe yettin

               Pişman oldum desen bile ne yazar

               Bitmez sandığın gün aslında dündü

               Zamanla semada yıldızlar  söndü

               Feleğin dişlisi çark etti döndü

               Yeniden denesek desen ne yazar

               Arkadaş kalalım desen ne yazar

               Cengiz Süslü            1996', 'Gönlümün gözünden son düşen sensin                Bir daha karşıma çıksan ne yazar                Bu kahpe kavgada sen beni yendin          ...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Süslü']::text[], 8.5, '{"poet":"Cengiz Süslü","poet_slug":"cengiz-suslu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ne-yazar-sarki-sozu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tüm yönler Allah’adır...', 'tum-yonler-allah-adir-cengiz-suslu-bw4w7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Akıl bendini zorlar

Yol yine Allah’adır

Ezel-i kurcalarlar

Ebet-de Allah’adır

Zaman görünmez ağaç

Meyveleri icattır

Sırrı çözen ilim de..

Bilim de Allah’adır

Bilinen ve bilenler

Her şeyin farkındadır

Sual cevapla gelir

Çözümde Allah’adır

Bir labirent düşünün

Tek giriş çıkışlıdır

‘O’nun lügat’ına bak

Tüm yönler Allah’adır

Cengiz Süslü   2005', 'Akıl bendini zorlar Yol yine Allah’adır Ezel-i kurcalarlar Ebet-de Allah’adır Zaman görünmez ağaç Meyveleri icattır Sırrı çözen ilim de.. Bi...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Süslü']::text[], 8.5, '{"poet":"Cengiz Süslü","poet_slug":"cengiz-suslu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/tum-yonler-allah-adir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabah...', 'sabah-tugba-ozgur-ao88c', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'SABAH...

gözlerime uyku girmez

seni düşünüyorsam

sözcükler dilime gelir de

bir türlü konuşamam

gözlerim tavanda 

tek kelime etmeden kendime bile

sabahı bulduğum

çok olmuştur benim

sabah ezanlarının 

hiçbirşeyde olmayan tınısı

bozduğunda bu sessizliği

düşünceler dinginleşir

hayaller sahnesi perde kapatır

ve bu kez

huzuruma ortak ederim seni

birlikte dinleyip 

huzur''un tasavvufunu

birlikte görüp

şehrin uyandığını

birlikte kapatırız gözlerimizi

güzdün ve geceye inat...', 'SABAH... gözlerime uyku girmez seni düşünüyorsam sözcükler dilime gelir de bir türlü konuşamam gözlerim tavanda  tek kelime etmeden kendime ...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Özgür']::text[], 8.5, '{"poet":"Tuğba Özgür","poet_slug":"tugba-ozgur","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sabah-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şehir', 'sehir-tugba-ozgur-insdw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ŞEHİR

Gökyüzü yarılıyordu

yürekteki korkular ayyuka çıkmış

kim dayanabilirdi? ? ? 

kim karşı koyabilirdi

ruhların bayramı bugeceye

kimse düşünmedi kendinen başkasını

gün doğduğunda çıktı

bütün endişeler saklandıkları yerden

bu kimin çığlığı

kimin öfkesydi

hangi günahın bedeliydi

aslında herkes biliyordu

herkes payına düşeni üstlenmişti

gözler kanlanmıştı

sözler saklanmıştı

kabullenilmişti başa gelen herşey

ışıklı şehirler ödedi bedelini büyük günahlarının

ışıkları söndü

güzelliği söndü

gece söylenen şarkılar

sessizliğe büründü

ihtiyacı olan zamanı sabırla bekledi şehir

korkular bastırıldı

acılar unutuldu

yeniden giydi en güzel elbisesini

yeniden aydınlattı şehir kalbini

ve yeniden aşıklar edindi', 'ŞEHİR Gökyüzü yarılıyordu yürekteki korkular ayyuka çıkmış kim dayanabilirdi? ? ?  kim karşı koyabilirdi ruhların bayramı bugeceye kimse düş...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Özgür']::text[], 8.5, '{"poet":"Tuğba Özgür","poet_slug":"tugba-ozgur","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sehir-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk tüketiyordu...', 'ask-tuketiyordu-tugba-ozgur-vszu3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'AŞK TÜKETİYORDU

Anlatılmaz bir aşktı bu

ne kalemler vardı yazmaya

ne ifadeye yetecek sözcükler...

tek taraflımıydı yoksa karşılık buluyorda

buluyorda bilmiyormuydu seven yürek

birine çıkar,birine aşk...

birine bağımlılık,birine ihanet...

belkide ölümüe aptallıktı

müstehcendi,çırılçıplaktı

anadan üryan..çünkü

aşk giyinemiyordu tozpembe elbisesini

siyah bir mateme dönüşüyordu buluşma şölenleri

tüm planları bozyordu

sabahın üçünde uykular kaçırıyordu

ağlatıyordu bıkmamacasına

gözler uykuyla mükafat bulmuyordu

evet aşktı bu

belki ölümüne aptallık

ama değişmiyordu adı

bir kalpte bitsede 

diğerinde yaşıyordu

ama aşk tüketiyordu...', 'AŞK TÜKETİYORDU Anlatılmaz bir aşktı bu ne kalemler vardı yazmaya ne ifadeye yetecek sözcükler... tek taraflımıydı yoksa karşılık buluyorda ...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Özgür']::text[], 8.5, '{"poet":"Tuğba Özgür","poet_slug":"tugba-ozgur","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ask-tuketiyordu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akışkan Zaman', 'akiskan-zaman-hurrem-yalcin-ot6xd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Akışkandı zaman

Ayrılıkların gölgesine

Taht kurmuş

Zalimin

Acımaz / Acıtamaz

Yüreği / Yüreğimi

Durağan zamanlara hasret

Karanlık aynalara bakar 

gözlerim…

Benden izinsiz...

20 Mart 2006 / İst...

.', 'Akışkandı zaman Ayrılıkların gölgesine Taht kurmuş Zalimin Acımaz / Acıtamaz Yüreği / Yüreğimi Durağan zamanlara hasret Karanlık aynalara ba...', ARRAY['Türk Edebiyatı','Şiir','Hürrem Yalçın']::text[], 8.5, '{"poet":"Hürrem Yalçın","poet_slug":"hurrem-yalcin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/akiskan-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeşil ll', 'yesil-ll-tugba-ozgur-lazxw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'gözlerinde kayboluyorum

yemyeşil bir muamma gözlerinde...

seviyorum seni! 

bir de ''seni seviyorum'' deyişini

aklımı çeliyor bakışların

ve ismini koyamadığım

yeni yetme aşk heveslerimiz

çıkarıyor sevdayı seyrinden

yatağından taşan nehir gibi

yükseliyor alıyor içine

diriliyor tek tek

ölmüş aşklar mezarına gömülen duygular

yenileniyor,tazeleniyor

bir daha ölmemek için

bizi daha güçlü kuşatıyor bukez

varlığına alıştıkca

vazgeçilmezim oluyorsun

soruyorum kendime

''kıyısına varamadığım aşk''a saplanmak

giyinmek tozpembe elbisesini

bu kadar kolay

bu kadar çabuk oluyormuydu? ''

içimde bir ses haykırıyor

''aşk bu

zaman kavramı onun için yok

haftaalrdan,aylardan,senelerden soyut

bazen ansızın geliyor

ya da hiç çıkmıyor kristal korunağından

çünkü bulamıyor onu tuz buz edecek 

bir çift yeşil göz''

ilk kez inanıyorum şanslı olduğuma

aşığım ben diyorum çünkü

gözlerinde kayboluyorum

yemyeşil bir muamma gözlerinde', 'gözlerinde kayboluyorum yemyeşil bir muamma gözlerinde... seviyorum seni!  bir de ''seni seviyorum'' deyişini aklımı çeliyor bakışların ve ism...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Özgür']::text[], 8.5, '{"poet":"Tuğba Özgür","poet_slug":"tugba-ozgur","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/yesil-ll-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yokluğunla gelen...', 'yoklugunla-gelen-tugba-ozgur-sxsn0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'YOKLUĞUNLA GELEN...

Anlatamadığım bir boşlukta dönüyor başım

yokluğun sızıyor içime

kanıma karışıp damarlarımda dolaşıyor yalnızlık

korkuyorum bu yokluktan

ama direniyorum! 

direnişlerim öpüyor alnımı

hasta ruhum ayaklanıyor -belkide son kez! -

yokluğumun çıkardığı isyanı bastırmak istiyor

direnişlerime destek olmak istercesine...

biriktiriyorum yokluğunda olanları

sıraya diziyorum tek tek

sonra ''bazılarını anlatmamak daha iyi olur''

deyip unutuyorum

anıların bazılarıda intihar edip

kendiliğinden yok oluyor

bir soru var zihnimde

aklıma zarar,ruhuma intihar bir soru! ...

''seni ilk günki kadar özlüyormuyum''

çok isterdim koşulsız ''EVET'' demeyi

ama düşünüyorum

gidişinin ilk günleri kadar acımıyor içim

içimi acıtan; hasretinin artık içimi acıtmaması! 

belkide yokluğuna direnişim soğuttu içimi

ya da bir acıya alışkanlık olasılığı...

acısını senden çıkardığım olumsuzluklar

dahada büyüyor gözümde

onları umursadığımdan değil

seni üzmeme sebep oldukları için! ! 

ama sen beni böyle sevdin

sevinçlerim,acılarım,heyecanalrım

hep taşkın olmuştu

şimdi susuyorum

neden sustuğumu kim nereden bilecek? ! ! ! 

heran seni hatırlamak için hep kendimle meşgulüm

bakışını,gülüşünü,küskün ifadeni

ilk bakışda sevgini anladığım gözlerini

unutmamak için hafızamla uğraşıyorum hep

güçlü görünüp,büyük zorluklar yaşıyorum aslında

yine de kimseye belli etmiyorum

beni o dimdik başımla hatırlasınlar istiyorum

eskiden öyleydim ama

şimdi sadece güçlü ''ben''i oynuyorum

sandığın gibi değil sahteleşmedim

sadece yokluğunda alınmış bir önlem bu

hiçbir işe yaramasa da! ...

ne zaman aynaya baksam

orada tek başımalığımı gördüğüm zaman

yalnız kaldığım gerçeği

çivi gibi çakılıyor beynime

belki bana bunu hatırlatan

yüzümdeki solgunluk

çünkü sen gittiğinden beri bakmıyorum kendime...', 'YOKLUĞUNLA GELEN... Anlatamadığım bir boşlukta dönüyor başım yokluğun sızıyor içime kanıma karışıp damarlarımda dolaşıyor yalnızlık korkuyor...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Özgür']::text[], 8.5, '{"poet":"Tuğba Özgür","poet_slug":"tugba-ozgur","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/yoklugunla-gelen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaderim...', 'kaderim-tugba-ozgur-vd0nf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'KADERİM…

Nedir benden istediğin? ? ? 

Neden bu yollarımdaki karanlık sis ve kan kokusu? ? ? 

Neden denizin en hırçın dalgaları  hep bana? ? ? ? 

Neden gökyüzü üstümde parçalanırcasına? ? ? 

Nedir gözlerimin bitmek bilmeyen bu uykusu? ? ? 

Üzerime örttüğün bu kara örtü ne? 

Gözlerime çektiğin bu mil niye? ? ? 

Kaderim…nedir benden istediğin? ? ? 

gözlerimdeki ateş söndü…

saçlarımdaki rüzgar dindi…

yüzümdeki ışık karanlığa çehrelendi.

ne umut kaldı artık ne de yaşama isteği! 

Kaderim… nedir benden istediğin? ? ?', 'KADERİM… Nedir benden istediğin? ? ?  Neden bu yollarımdaki karanlık sis ve kan kokusu? ? ?  Neden denizin en hırçın dalgaları  hep bana? ? ...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Özgür']::text[], 8.5, '{"poet":"Tuğba Özgür","poet_slug":"tugba-ozgur","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kaderim-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duygu Kuşatması', 'duygu-kusatmasi-gultekin-toga-4n3ev', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir mengene gibi almış içine,

Sıkar beni bilmediğim duygular..

Yüreğimin ateş dolmuş içine,

Yakar beni bilmediğim duygular..

Her devir yer vermiş İbni Sebe´ye,

Şüpheyle inanan düşmez şüpheye,

Tutar vicdanımla muhasebeye,

Çeker beni bilmediĞim duygular..

Ah duygular..nerelere koşturur? 

Med vaktinde deniz gibi coşturur,

Sicim sicim gözlerimden taştırır,

Döker beni bilmediğim duygular..

Tebessüm ettirir türlü belaya,

Döndermez yönünü basit,kolaya,

Seve,seve girdaplaşmış çileye,

Sokar beni bilmediğim duygular..

Sentezi,sizlama ağıtlar gibi,

Davran da yaşama,kağıtlar gibi,

Bedrin aslanları yiğitler gibi,

ÇIkar beni bilmediğim duygular..', 'Bir mengene gibi almış içine, Sıkar beni bilmediğim duygular.. Yüreğimin ateş dolmuş içine, Yakar beni bilmediğim duygular.. Her devir yer v...', ARRAY['Türk Edebiyatı','Şiir','Gültekin Toga']::text[], 8.5, '{"poet":"Gültekin Toga","poet_slug":"gultekin-toga","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/duygu-kusatmasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Terket cehennemimi...', 'terket-cehennemimi-tugba-ozgur-sh4t3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'takip etme yolumu

karanlığa çıkacak,

gelme artık arkamdan

yollar seni yutacak

bak ışık yok

güneşi yok dünyamın

sessizliğe güvenme

vakti gelir çığlığın

uyan derin uykundan

gör benim gerçeğimi

kurtar benden kendini

terket cehennemimi

arkana bakmadan git

terket cehennemimi

gör benim gerçeğimi

terket cehennemimi

gözlerimde sevinç yok

umudum karanlıkta

sözlerim zehirli ok

çıkamam aydınlığa

eski dostum yalnızlık

kalbim katran karası

yok içimde saydamlık

bu kalbimin yarası

uyan derin uykundan

gör benim gerçeğimi

kurtar benden kendini

terket cehennemimi

arkana bakmadan git

terket cehennemimi

gör benim gerçeğimi

terket cehennemimi', 'takip etme yolumu karanlığa çıkacak, gelme artık arkamdan yollar seni yutacak bak ışık yok güneşi yok dünyamın sessizliğe güvenme vakti geli...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Özgür']::text[], 8.5, '{"poet":"Tuğba Özgür","poet_slug":"tugba-ozgur","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/terket-cehennemimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yar', 'yar-namik-atasoy-6zcxe', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yolun ortasındayım,yorgunum artık yar,geçti deli çaglarım,durgunum artık yar.

Eskittik umutları,mavinin rengi silik,sensiz akşamlar yitik,şafaklar solgun artık yar.

Taze baharlar kışa döndü,döndü yeşillerim sarıya,mutluluk dündü bugündü derken,hayal oldu sensiz yarınlar yok artık yar.

Matemine kurşun sıktım,ölüm yaşamak kadar uzak,düşüncesi akla zarar,sensiz olmak imkansız artık yar.

Eli tetikte sensiz gecelerin,namlunun ucundayım,deli fişek gibi kayacak yüreğime,sana dilek yıldızlar,bekliyorum bir bilinmezliğin ortasındayım,sensiz uykular yok artık yar.

Gülüşlerimi aldılar,düşlerimi çaldılar,yaktılar yıktılar,sensiz ölmek yok artık yar.

Tökezledim sadece,düşmedim,yolun ortasındayım yorgunum artık yar,geçti deli çağlarım,durgunum artık yar.

Korkuyorum ardıma bakamam,sensiz önümü göremem,durmaya cesaretim yok,yürümeye mecalim,sensizliğe sabrım yok artık yar.

Birkez olsun vefayı anımsa,sevdaya çal yüzünü,bitsin artık çile sürgünü,bir satır olsun dönüşünü kaderime yaz,yorgunum artık yar,tut ellerimden,duy feryadımı,gel artık gel ne olur,sensiz yaşamak yok yar..', 'Yolun ortasındayım,yorgunum artık yar,geçti deli çaglarım,durgunum artık yar. Eskittik umutları,mavinin rengi silik,sensiz akşamlar yitik,şa...', ARRAY['Türk Edebiyatı','Şiir','Namık Atasoy']::text[], 8.5, '{"poet":"Namık Atasoy","poet_slug":"namik-atasoy","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yar-93-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çanakkale', 'canakkale-yusuf-ter-ef107', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çocukluğumda  okumuştum

Tarih kitabında

“Çanakkale geçilmez” diye

Tarihi  yaşıyorum

Çanakkale zaferinde

Mustafa Kemal Paşa’nın

Onurlu, bağımsız yaşamak için

Ölmeyi emrediyorum ölenlere

Ayakları çarıklı,

Yırtık elbiseli insanlara

Düşman dövüyor mazlum vatanı

Şehidimin kanı  düşüyor toprağın her karışına

Irkı dini  bıraktık bir yana

“Geçilmez Çanakkale”  haykırışları duyuluyor

Top mermileri dövüyor siperleri

Nineler, dedeler evde bırakmışlar torunlarını

Savunmak için vatani evlatları ile omuz, omuza 

Top mermileri dövüyor mazlum vatanı

Kefene sarılmamış yiğitler

Ölümü emreden komutan

Ölümüne vuruşuyorlar

Ağlamak yasak,  zafer sancağı dikilene dek

Haydi yiğitler 

Her köşesinden 

Nakış nakış 

Kaldır başını

Saldır düşmana 

Postal delik, delik 

Ayağında çarık  ayaklar yarık, yarık

Korkusuzca

Savundular mazlum vatanı

Denizler  dalgası

Boğuyor düşmanı

“Çanakkale geçilmez” 

Tarih boyu başı dik ulusum

Kanla yazdılar tarihi.

Yusuf Ter 19.03.06

Saat 23.04 İsviçre', 'Çocukluğumda  okumuştum Tarih kitabında “Çanakkale geçilmez” diye Tarihi  yaşıyorum Çanakkale zaferinde Mustafa Kemal Paşa’nın Onurlu, bağım...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ter']::text[], 8.5, '{"poet":"Yusuf Ter","poet_slug":"yusuf-ter","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/canakkale-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece nöbeti...', 'gece-nobeti-tugba-ozgur-vs3ep', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sen beni nitihar odalarına terk edeli

gözlerimden geçen bulutlara emanetsin

karanlıklar giydirsende üzerime

gece nöbetlerimi bile bile gelmesende

sen,seni gördüğüm yıldızlara emanetsin

beni yalnız bıraktığın yolun ayrımındayım şimdi

sensiz olup

yokluğunu kabullenerek devam edeceğim

-içimde yolun sonu aydınlık umudu taşıyarak-

içimdeki seni yoldaş ederek kendime devam edeceğim

-yolun sonunun yalnızlık koğuşlarına vardığını bilerek-

atamıyorum içimdeki sevgiliyi

ve devam ediyorum

her yeri sen olan,hep sen kokan

ama olmayışınla karanlıklaşan yoluma

acıyor içim kanıyor, tükeniyorum ama devam ediyorum

bu bile hoşuma gidiyor

senin için acıması içimin,

kalbimin kanaması,tükenişlerim..

senin için olduğunu bildiğim herşey hoşuma gidiyor

hayallerim güç veriyor bana

gözlerimi her kapatışımda geliyorsun yanıma

sarılıyorum sımsıkı,kokluyorum doyasıya

saçlarıma dokunuyorsun

çok özlediğim cümleler duyuyorum

SENİ SEVİYORUM diyorsun...ağlıyorum...

sen daha gözyaşlarımı silmeden

gözyaşlarımın yüzümdeki sıcaklığıyla uyanıyorum

ve gece nöbetleri sensiz devam ediyor...', 'sen beni nitihar odalarına terk edeli gözlerimden geçen bulutlara emanetsin karanlıklar giydirsende üzerime gece nöbetlerimi bile bile gelme...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Özgür']::text[], 8.5, '{"poet":"Tuğba Özgür","poet_slug":"tugba-ozgur","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/gece-nobeti-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonsuz', 'sonsuz-tugba-ozgur-r2lhn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Büyük bir sahneye çıkıp

kısa bir öykü anlattın

sessizce geldin ve giderken de

bozmadın bu sukuneti

şimdi deli edici yalnızlıklardayım

gözlerim uykuyu

benliğim huzur''u unutalı çok oldu

alışamıyorum yokluğuna

olmayışına ve hiç olmayacağına

geri dönmeyeceğine alışamıyorum

bakışlarını saklıyorum kendime

sözlerinden ve gözlerinden arta kalanı

bir bir hatırlayıp biriktiriyorum

kurutulmuş çiçek gibi

dağılmasından,yok olmasından delice korkarak

değerli bir mücevher gibi

seyretmeye doyanamayarak saklıyorum

senden tek hatıra anılarımı..

yaşarken değerini bilmediğim herşeyin

her anın pişmanlığını tek tek yaşıyorum

seni yaşamaktan

beni yaşamandan kaçışlarımı

böyle cezalandırıyorum

bile bile yalnızlığa itiyorum kendimi

boş sokaklardan geçiyorum

sonunu getiremediğim mektuplar yazıyorum

bazen karşıma alıp seni 

saatlerce anlatıyorum

dünyanın adaletsizliğini

sen benim için bitmedin

sana yazdığım mektuplar gibi bitmeyecek

ve sonsuz olacaksın...', 'Büyük bir sahneye çıkıp kısa bir öykü anlattın sessizce geldin ve giderken de bozmadın bu sukuneti şimdi deli edici yalnızlıklardayım gözler...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Özgür']::text[], 8.5, '{"poet":"Tuğba Özgür","poet_slug":"tugba-ozgur","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/sonsuz-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyüme Çocuk', 'buyume-cocuk-serap-tepedelen-q6m4r', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Büyüme çocuk,

Büyümeye özenme.

Sen büyüdüğün an adım adım

Bilsen nelere erecek aklın

Ve seni,

Neler bekliyor neler

Bilesin çocuk,

Yaşamak

 Hep çocuklukta güzel! 

(1989,Devrek/Zonguldak)', 'Büyüme çocuk, Büyümeye özenme. Sen büyüdüğün an adım adım Bilsen nelere erecek aklın Ve seni, Neler bekliyor neler Bilesin çocuk, Yaşamak  H...', ARRAY['Türk Edebiyatı','Şiir','Serap Tepedelen']::text[], 8.5, '{"poet":"Serap Tepedelen","poet_slug":"serap-tepedelen","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/buyume-cocuk-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Anneciğim*', 'annecigim-zeynep-sahin-nkraf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'O güzel gözündeki manalı bakış 

O güzel sözündeki hülyalı akış

Kalbimin içinde eriyen sevgi

Sanma bir gün biter ah anneciğim.

Gözüne girmeyen uykular bitsin.

Sözünü bilmeyen cahiller gitsin

Yolunda çoğalan hüzünler bitsin

Bitsin artık yeter ah anneciğim.

Kalbim bir pusula yönü kuzeyde 

Gönlüm ilerlerde zaman sevgide

Çoğalan hüzünlerin doruğu bizde

Yavaş yavaş eriyen kar gibi annem.

Sesimi duyurdum tüm ufuklara 

Çoğalan yankı gibi durmuyor annem

Garipler diyarında olduğu gibi 

Bize de kader gülmüyor annem…', 'O güzel gözündeki manalı bakış  O güzel sözündeki hülyalı akış Kalbimin içinde eriyen sevgi Sanma bir gün biter ah anneciğim. Gözüne girmeye...', ARRAY['Türk Edebiyatı','Şiir','Zeynep Şahin']::text[], 8.5, '{"poet":"Zeynep Şahin","poet_slug":"zeynep-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/annecigim-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyüdük(1)', 'buyuduk-1-serap-tepedelen-trbeq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tan yeri ağaranda,

Elimizde bohçamız,

Bir somun ekmek ve katığımız

Çıktık yola.

Düşleri aldık önümüze,

Umutları kattık yüreğimize

Yürüdük...Yürüdük...

Tan yeri ağaranda,

Biz,bodur boylu çocuklar

İnadına,daha bir hırsla,yorulmadan

Büyüdük...Büyüdük..

(1994,Bursa) .', 'Tan yeri ağaranda, Elimizde bohçamız, Bir somun ekmek ve katığımız Çıktık yola. Düşleri aldık önümüze, Umutları kattık yüreğimize Yürüdük......', ARRAY['Türk Edebiyatı','Şiir','Serap Tepedelen']::text[], 8.5, '{"poet":"Serap Tepedelen","poet_slug":"serap-tepedelen","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/buyuduk-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayrak', 'bayrak-necati-cavdar-1tet3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Devlete   kızıp   bayrağımızı  indiriyorsunuz

                                   Siz, hiç uğruna kendinizi kandırıyorsunuz...



Bayramlarda, savaşlarda

Düğünlerde, üzüntüde, kıyamda

Her  coşkuda her heyecanda

Elde, başta, en yüksekte

Semboldür, milli ruhtur...

Zannetmeyin; devletindir, bayrak

Bayrak; histir, ruhtur, devlet; hadimi

Bayrak inince;  devlettir biten

Koruyan halktır, halk yücelten

Yönetim; koruyamaz, bazen indirir

Halk; sahip çıkar, en yücelere  çektirir...

Zira bayrak; devlet değil, milletin sembolüdür

Millet; devletsiz durur, bayraksız olmaz.

Ey devlet, sen koruyamazsan çekil! ... 

O; millet kanındandır, millet; indirtmez

Buluşmaktayken Gökbayrak’la Albayrak

Yanan en son ocağı; millet,  söndürtmez...



                                                      Ankara - 1996', 'Devlete   kızıp   bayrağımızı  indiriyorsunuz                                    Siz, hiç uğruna kendinizi kandırıyorsunuz... Bayramlarda, s...', ARRAY['Türk Edebiyatı','Şiir','Necati Çavdar']::text[], 8.5, '{"poet":"Necati Çavdar","poet_slug":"necati-cavdar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bayrak-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalvarış', 'yalvaris-omer-ziya-soyyigit-topdk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aşkına yandır

Ey kerim Allah

Derde boyandır

Ey kerim Allah

Kemter kulum ben

Gani sultan sen

Sarayın bu ten

Ey kerim Allah

Gafleti kaldır

Tevhide daldır

Ne güzel haldır

Ey kerim Allah

Fail kim bildir

Mevsufu bildir

Mevcudu bildir

Ey kerim Allah

Göster cemalin

Bildir kemalin

Lutfet visalin

Ey kerim Allah

Ömer bir keda

Zatına feda

Duyur bir seda

Ey kerim Allah

26 Mayıs 1981', 'Aşkına yandır Ey kerim Allah Derde boyandır Ey kerim Allah Kemter kulum ben Gani sultan sen Sarayın bu ten Ey kerim Allah Gafleti kaldır Tev...', ARRAY['Türk Edebiyatı','Şiir','Ömer Ziya Soyyiğit']::text[], 8.5, '{"poet":"Ömer Ziya Soyyiğit","poet_slug":"omer-ziya-soyyigit","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yalvaris-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Sana Selam Yolluyorum*', 'sana-selam-yolluyorum-zeynep-sahin-d6vu9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Heybetli mor dağlardan 

Yapayalnız ağaçlardan

Akıp giden şu yollardan

Sana selam yolluyorum

Telaş yüklü bulutlardan 

Sevinçle batan güneşten

Sessiz akan ırmaklardan

Sana selam yolluyorum

Sonu meçhul masallardan

Güzde açan çiçeklerden

Hasret kokan anılardan

Sana selam yolluyorum

Hızlı geçen zamanlardan

Bütün yalnız boş anlardan

Bilinmeyen tüm hislerden 

Sana selam yolluyorum

İsyan eden yüreklerden

Acı dolu gülüşlerden

Sevgiyle parlayan gözlerden

Sana selam yolluyorum 

Bütün gerçek sevgilerden

Bütün gerçek ilgilerden

Sığındığım doğrulardan

Sana selam yolluyorum', 'Heybetli mor dağlardan  Yapayalnız ağaçlardan Akıp giden şu yollardan Sana selam yolluyorum Telaş yüklü bulutlardan  Sevinçle batan güneşten...', ARRAY['Türk Edebiyatı','Şiir','Zeynep Şahin']::text[], 8.5, '{"poet":"Zeynep Şahin","poet_slug":"zeynep-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sana-selam-yolluyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Agrıma gidiyor', 'agrima-gidiyor-adem-korkmaz-cqdlz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Unutulabilirim,yok da sayılabilirim

Siz neden unuttunuz dualarım.

Her şey kabulüm de

Sizin unutmanız ağrıma gidiyor.

Kalleş bir savaşın tam ortasında

Yüzüme bile bakmadan gül gidiyor

Ağrı dağı kadar yalnız

Erciyes dağı kadar suskun gençliğim  bitiyor

Hangi sabahı bahar sansam

Kara kış geliyor çiçeklerim küsüyor

Terk edilmek yok sayılmak kabulümde

Dost senin suskunluğun ağrıma gidiyor

Yaşamak denilen senaryosuz filmde

Hüzün sahnelerini oynamak seyircileri ağlatmak

Ve her daim kaybetmek kabulümde

Biçareliğin yılışması ağrıma gidiyor.

Bir bedduanın başlangıcında

İşte orda gözlerin kadar yeşil

İhanet geliyor

Ne yüzüme bakıyor,ne hatırımı soruyor

İşte orda sırtımdan vuruyor,

Yalnızlığın paslanmış tortularıyla yaşamak kabulümde

İhaneti umursamaman ağrıma gidiyor,

Cennet sağım düşüyor,cehennem soluma

Beddualar yollarımı tıkıyor

Bütün yönler TEK''e çıkıyor

Bu masaldan sıyrılıp ta hayatı bulamıyorum,

Saçlarımın dökülmesi kabulümde

Yetmez gibi birde aklara bürünmesi  ağrıma gidiyor

Bahtımı çepeçevre sarmış hayaller

Geleceğim omuzlarımda sendeler

Fırtınalarımı durduramıyorum

Zincirlerine vurunca hüzünler beni

İşte o zaman yakıyor avuçlarımdaki ateş

Zamanı durduramıyorum

Kıpkızıl bir intihar

Sırıtıyor yanı başımda

Geceler gençliğimi yağmalıyor,

Düşlerime sığınıyorum,

Tıkıyor o anda boğazıma heveslerimi,

Tüm dünya bir tarafta; 

Sen ve gözlerin diğer yanda; 

Ben her şeyi elimin tersiyle itip "O"na gidiyorum

Ah! ... Sen kabul etmiyorsun.

Ağrıma gidiyor…

Şimdi bu şehir sana sen bu şehire emanet! 

Sabah olmadan gitmek kabulümde

Soğuk kaşlarının tavrı ağrıma gidiyor.

Bak yine sevdama kar yağıyor.

Sabah delirmiş,gece küs! 

Yetiş sevdiğim coğrafyam yanıyor! 

Bu yalvarışım yangınıma değil! 

Sev diye verdiğin kalbinde yanıyor.

Benden yağmurunu esirgemen kabulümde

Gözlerimin taa içine bakıp ta

Yangınımı görmezden gelmen

Ağrıma gidiyor…

Neye acıyorum biliyor musun? 

Bu beden bir gün toprak olduğunda

Ve toprağında papatya çiçekleri filiz saldığında

Sen bu çiçekleri  narin ellerine alıp ta

Umursamayıp koklamadan atacak olman ağrıma gidiyor.

Gurbet sağıma düşüyor,yokluk soluma.

Ezan,vatan ve kan kırmızısı bayrak

Hepsi senden yana düşüyor.

Ey sen! Sevdiğim! .

Kayıtsız,umursamadan ölmek kabulümde

Sensizlik ve gözlerinden bir an mahrum olmak 

Ağrıma gidiyor…', 'Unutulabilirim,yok da sayılabilirim Siz neden unuttunuz dualarım. Her şey kabulüm de Sizin unutmanız ağrıma gidiyor. Kalleş bir savaşın tam ...', ARRAY['Türk Edebiyatı','Şiir','Adem Korkmaz']::text[], 8.5, '{"poet":"Adem Korkmaz","poet_slug":"adem-korkmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":69,"source_url":"https://www.antoloji.com/agrima-gidiyor-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyüdük(2)', 'buyuduk-2-serap-tepedelen-52w0k', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'En umarsız gecelerin kısır döngülerinde

Yüreğimize kilit vurmuşken,

Acılarımızı paylaşmışken aşlarımızla,

Bileklerimizde kelepçe,

Özgürlük türküsünü mırıldandık.

Ezilmişlerin dünyasına isyan ederken

Susmadık,

Vargücümüzle bağırdık.

Karanlığa inat,

Geriliğe inat,

Ellerimizde ak bir güvercin

Göğün maviliğinde uçurduk.

Önce ekmeğimizi aldılar elimizden,

Sonra umutlarımızı...

Düşlerimizi en tatlı yerinden böldüler kara bıçaklarla

İmgelerimizi bile kirlettiler,

Aldırmadık.

Aydınlık isteyen yüreğimizi susturdular,

Güzel olan ne varsa silip süpürdüler.

Parça parça edilirken yüreğimiz

Her bir parçası atılmışken bir köşeye

Ağlamamızı beklediler

Yalvarıp yakarmamızı

Yenilmedik.

Bire iki,ikiye üç,üçe dört

Birleştik,kenetlendik.

Bizler,sevda yüklü çocuklar

Onurlu ve dimdik

İnadına,daha bir hırsla

Yürüdük...Yürüdük...

(1997,Bursa)', 'En umarsız gecelerin kısır döngülerinde Yüreğimize kilit vurmuşken, Acılarımızı paylaşmışken aşlarımızla, Bileklerimizde kelepçe, Özgürlük t...', ARRAY['Türk Edebiyatı','Şiir','Serap Tepedelen']::text[], 8.5, '{"poet":"Serap Tepedelen","poet_slug":"serap-tepedelen","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/buyuduk-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mücevher sayılırsın', 'mucevher-sayilirsin-esin-cinar-g2zlj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mücevher sayılırsın 

Ne kadar isterdim

Hareketsiz durmanı

Bağrında gezinirken

Sessizce bakınmanı

Bilirim yapamazsın

Sen rahat duramazsın

Benim dilediğimce

Sessizce bakamazsın

Benden çok sevdiğin var

Varlığın onunla yar

Bana sevgini bozar

Çıksa en ufak rüzgar

İşte o zaman ağlar

Sahiller ve ufuklar 

Ve hırsını eritir

Kumsallarla kayalar

Tekrar uysallaşırsın

Hırstan uzaklaşırsın

Tıpkı bir kadın gibi

Mücevher sayılırsın

Esin Çınar

(14.08.2004/20.03.2006)', 'Mücevher sayılırsın  Ne kadar isterdim Hareketsiz durmanı Bağrında gezinirken Sessizce bakınmanı Bilirim yapamazsın Sen rahat duramazsın Ben...', ARRAY['Türk Edebiyatı','Şiir','Esin Çınar']::text[], 8.5, '{"poet":"Esin Çınar","poet_slug":"esin-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/mucevher-sayilirsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul'' um', 'i-stanbul-um-abdulkadir-kaymak-iv8n0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İstanbul göz bebeğim

Bir karış toprağına öleyim

Sen atalarımın armağanısın

Minarelerinle

Saraylarınla haliç’ inle

Sana baktıkça

Osmanlıyı görürüm

Sana baktıkça

Anamı, babamı

Evladımı görürüm

Sen bir emanetsin bende

Dedemden kalan

İstanbul’um

Seni dağınla taşınla sevdim

Seni fatihin şehri

Seni türküm ülkesi

Ülkem içinde ülkemsin

Sana aç gözlerle bakan

Namusuma bakmış gibidir

Seni benden almak isteyen

Beni 

Benden almış gibidir

İstanbul’um

Gözümün nuru

Sakındığım

Senin için azmı şehit verdik

Senin için azmı ağladık

Senin için 

Azmı savaştık

Seni koruyamasam eğer

Seni savunamasam

Lanet olsun

O zaman ağlasam ne çare

Dövünsem ne

Ölüm olurum

Sen benden gidersen

Leyla nın mecnuna olan askı

Azdır benim sana olan aşkımdan

İstanbul’um 

Tek servetim

Malım, mülküm, canım

Sana feda olsun

Bilirim ki sen gidersen

Vatanım gider

Bilirim ki 

Sen gidersen

Ben ölürüm', 'İstanbul göz bebeğim Bir karış toprağına öleyim Sen atalarımın armağanısın Minarelerinle Saraylarınla haliç’ inle Sana baktıkça Osmanlıyı gö...', ARRAY['Türk Edebiyatı','Şiir','Abdulkadir Kaymak']::text[], 8.5, '{"poet":"Abdulkadir Kaymak","poet_slug":"abdulkadir-kaymak","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/istanbul-um-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Âkıl bin BÜKEYR (RA)', 'kil-bin-bukeyr-ra-abdullah-yasar-erdogan-ituh4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '(Bedir şehidlerinden, Can Şehidlerim: 2) 

    Âkıl  bin  BÜKEYR   (RA) 

Baba adı; Ebü’l-Bükeyr diye bilinir,

Annesine de; Afrâ bint Ubeyd denilir,

Hazrec kabilesi Beni Neccar soydandır,

İlk bey’at edenlerdendi yiğit Âkıl’im.

O Âkıl’ın gerçek adı da “Gafil” idi,

Hac için geldiği Mekke’de evlenmişti,

Bükeyr bin Abülyâlil ki O’nun eşiydi,

İlk iman  edenlerdendi yiğit Âkıl’im.

Müslüman olunca O’nun adı değişmiş,

Râsûlullah O’na, “Âkıl” adını vermiş,

O, Dârülerkam’ın evinde bey’at etmiş,

İlk iman  edenlerdendi yiğit Âkıl’im.

Habeşistan’a hicret edenlerle oldu,

Medine hicretince hanece bulundu,

O, Mücezzir bin Ziyad ile kardeş oldu,

İlk iman  edenlerdendi yiğit Âkıl’im.

Bedir Savaşı’nda kahramanca vuruşur,

Mâlik bin Zübeyr eliyle şehid olmuştur,

O artık Cennete kanatlanan yolcudur,

Selamlar olsun sana Akıl bin Bükeyr’im. 

Şair: Abdullah Yaşar Erdoğan', '(Bedir şehidlerinden, Can Şehidlerim: 2)      Âkıl  bin  BÜKEYR   (RA)  Baba adı; Ebü’l-Bükeyr diye bilinir, Annesine de; Afrâ bint Ubeyd de...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yaşar Erdoğan']::text[], 8.5, '{"poet":"Abdullah Yaşar Erdoğan","poet_slug":"abdullah-yasar-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/akil-bin-bukeyr-ra-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Abdullah bin Amr bin Harâm (RA)', 'abdullah-bin-amr-bin-har-m-ra-abdullah-yasar-erdogan-bbj2y', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '(Uhud Şehitlerinden, Can Şehidlerim: 3) 

             -Uhud’un ilk şehidi- 

    Abdullah  bin Amr bin Harâm (RA) 

Adı; Ebû Câbir Abdullah bin Amr bin Harâm,

El-Ensâri Es-Selâm; diye bilinir,

Beni Seleme kabilesi lideridir,

Aslan yürekli Abdullah bin Amr bin Harâm.

İkinci Akabe bey’atı’nda gelmişler,

Harâm, Bera bin Marur ile birlikteler,

Kabilesini Resûle teslim etmişler,

Aslan yüreklidir, yiğittir o güzelim.

O, Bedir Savaşı’nda bir destan yazmıştı,

Düşmanlar üzerine korkusuz varmıştı,

Her yaptığını Allah aşkıyla yapmıştı,

Hakk sevdalısı Abdullah bin Amr bin Harâm.

Uhud günü oğlunu çağırıp söylemiş,

“Ey Cabir bin Abdullah artık zaman gelmiş,

Uhud’un ilk şehidi olacağım” demiş,

Dileği olan Abdullah bin Amr bin Harâm.

“Oğlum! Altı kızımın tek kardeşi sensin,

Onlar ki, devamlı himayende bilesin,

Borçlarımda senin tarafından ödensin,”

İki cihanı kurtarmak erdem yiğidim.

Uhud’a varılmadan münafıklar koptu,

Selül; Uhud’ta savaşmak istemiyordu,

Adamlarını savaştan geri çekiyordu,

Korkak tarihe leke düşürür yiğidim. 

Abdullah bin Harâm, ikna edemez onu,

Haykırır yüzüne münafık olduğunu,

Söylenir onlara beddua okuduğu,

Yiğitler tarihe nam düşürür yiğidim.

Savaş başladığı anda, aldı bir darbe,

Cansız yere serilmişti, o büyük gövde,

O, Uhud’ta nail oldu ilk şehidliğe,

Yiğitler tarihe şan düşürür yiğidim. 

Müşrikler kestiler O’nun kulaklarını,

Sonra da biçtiler bütün uzuvlarını,

Savaş sonrası hüzün kaplar Müslüman’ı,

Korkak tarihe leke düşürür yiğidim. 

Uhud’ta yeteri kadar kefen bulunmaz,

Kabir eşecek yiğitlerin kolu kalkmaz,

Şehidlerin hali insanlığa yakışmaz,

Yiğitler tarihe nam düşürür yiğidim.

O’nun eniştesi Amr bin Cemûh da şehit,

İkisi de aynı mezara olmuş defin,

Omuz omuza yatmaktaymış iki yiğit,

Yiğitler tarihe şan düşürür yiğidim. 

Kırk yıl sonra sel suyu bozmuştu mezarı,

Başka yere taşıdılar o yatanları,

İki cesette yokmuş beden bozulması,

Korkak tarihe leke düşürür yiğidim. 

Onlar Allah ve Resûl aşkıyla koşmuşlar,

İşte bu nedenle tenleri bozulmazlar,

Allah adına koşanlar, asla yorulmazlar,

Yiğitler tarihe nam düşürür yiğidim.

İKİ HADİS: 

1- “Sakın şehitler için ölü demeyiniz.” 

2-  Rasûlullah der ki; “ Allah’ın Resûlü de şahittir ki;  siz kıyamet günü Allah’ın huzurunda şehit olarak haşrolunacaksınız.” Sonra yanındakilere dönerek:  “ Bunları (şehitleri)  ziyaret ediniz. Kendilerine selam veriniz. Allah’a yemin ederim ki; kim bu dünyada selam verirse, kıyamette bu aziz şehitler kendilerine mukabil selam vereceklerdir...” buyurmaktadır. 

Şair: Abdullah Yaşar Erdoğan', '(Uhud Şehitlerinden, Can Şehidlerim: 3)               -Uhud’un ilk şehidi-      Abdullah  bin Amr bin Harâm (RA)  Adı; Ebû Câbir Abdullah bi...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yaşar Erdoğan']::text[], 8.5, '{"poet":"Abdullah Yaşar Erdoğan","poet_slug":"abdullah-yasar-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/abdullah-bin-amr-bin-haram-ra-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senkolik', 'senkolik-sabahattin-hizmetli-iykad', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni kim enjekte etti

	Damarlarıma alev alev! ..

	Ne zaman, nerede,

	Bilemiyorum.

	Kan yerine,

	Sen dolaşıyorsun bedenimde.

	Artık dayanamıyorum ateşine….', 'Seni kim enjekte etti 	Damarlarıma alev alev! .. 	Ne zaman, nerede, 	Bilemiyorum. 	Kan yerine, 	Sen dolaşıyorsun bedenimde. 	Artık dayanamıy...', ARRAY['Türk Edebiyatı','Şiir','Sabahattin Hizmetli']::text[], 8.5, '{"poet":"Sabahattin Hizmetli","poet_slug":"sabahattin-hizmetli","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/senkolik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Sahte Bir Hikaye*', 'sahte-bir-hikaye-zeynep-sahin-9xfyl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir nurdu onun gördüğü kalbinde

İlk bakışında bile çok şeyler hissettiği.

Üzerinden bir hayli zaman geçti yine de 

Yetinmesini bildi hissettiği o çok şeylerle.

“Ne zamana kadar” diye sorarsam içimden; 

Ta ki mahşere kadar silemedi içinden.

Bir azalma olmuştu, bunu bilmişti fakat

Bilemedi ne kadar kaybetti o sevgiden.

Sayılmıyordu çünkü bilinmiyordu zarar

Bilinmedi de hesap günü gelip çatana kadar.

Kafası karışıp ta artık aklı almazken

Bir ipucu yakaladı kalbinin derininden

Aklı sıra bir nurdu kalbinde gördüğü şey

Gördüm sanmıştı ama yinede yanılmıştı 

“Yanılmadım” diyerek son bir çaba sarf etti

Sarf ettiği son çabayı Hak, katında reddetti 

O zaman hatırladı nerde olduğunu o an

Biraz kımıldamaya bile takati kalmamıştı 

Alaca karanlıkta saatini aradı. 

Kafası karışıp ta  artık aklı almazken

“Çok geç” dedi derinden ses son perdeyi kaparken

Perdeler kapanınca ışıklar da sönünce 

Yalnız gerçekler vardı o an gördüklerinde

Hani sahneydi ya bu gerçekte neyin nesi 

Akıl almaz kulunun sahte bir hikayesi…', 'Bir nurdu onun gördüğü kalbinde İlk bakışında bile çok şeyler hissettiği. Üzerinden bir hayli zaman geçti yine de  Yetinmesini bildi hissett...', ARRAY['Türk Edebiyatı','Şiir','Zeynep Şahin']::text[], 8.5, '{"poet":"Zeynep Şahin","poet_slug":"zeynep-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sahte-bir-hikaye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeşillim', 'yesillim-sabahattin-hizmetli-v8q79', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yeşil yeşil bakıp

	Yeşertme beni.

	Sonra karışmam,

	Filizlenir,

	Tüm benliğini sararım

	Sımsıkı...', 'Yeşil yeşil bakıp 	Yeşertme beni. 	Sonra karışmam, 	Filizlenir, 	Tüm benliğini sararım 	Sımsıkı......', ARRAY['Türk Edebiyatı','Şiir','Sabahattin Hizmetli']::text[], 8.5, '{"poet":"Sabahattin Hizmetli","poet_slug":"sabahattin-hizmetli","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yesillim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sakın Evlenme Evlenme', 'sakin-evlenme-evlenme-omer-ziya-soyyigit-ohq7w', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hayat zormuş meğer dostum

Sakın evlenme evlenme

Gürcistan''ı bulur postun

Sakın evlenme evlenme

Sultanlıktır bil bekarlık

Nede büyük fedakarlık

Yapamazsan sahtekarlık

Sakın evlenme evlenme

Karı bakmak kolay sanma

Aç gözünü sen aldanma

Kimsenin sözüne kanma

Sakın evlenme evlenme

Papuç ister, çorap ister

Dünyan olsun harap ister

Gözün dolsun turap ister

Sakın evlenme evlenme

Başa çıkmak kolay değil

Bir gün değil bir ay değil

Hayat çekilir yay değil

Sakın evlenme evlenme

Kumanyalar bir bir biter

Ay başı burnumda tüter

Hanım horoz gibi öter

Sakın evlenme evlenme

Bir de çocuk derdi başlar

Gözlerinden akar yaşlar

Yetmez dostum bu maaşlar

Sakın evlenme evlenme

Ziya yaptı görevini

Uyandırdı dostum seni

Eğer dinler isen beni

Sakın evlenme evlenme

14 Nisan 1981', 'Hayat zormuş meğer dostum Sakın evlenme evlenme Gürcistan''ı bulur postun Sakın evlenme evlenme Sultanlıktır bil bekarlık Nede büyük fedakarl...', ARRAY['Türk Edebiyatı','Şiir','Ömer Ziya Soyyiğit']::text[], 8.5, '{"poet":"Ömer Ziya Soyyiğit","poet_slug":"omer-ziya-soyyigit","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/sakin-evlenme-evlenme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Köy Var Uzakta', 'bir-koy-var-uzakta-eyup-gok-6ozdx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gördüklerimizi söylesek mi kıra? 

Dağlarımı sayalım birde sıra sıra? 

Sırlarımızı paylaştığımız deniz kıyısı

Alıp götürsün diye rüzgar, aşk acısını

Patikadan geçip köye vardınmı? 

Köy kahvesine girip selam verdinmi? 

Gönülleri hoş eden kahvelerini içip

Gözlerine baktınmı karşılarına geçip? 

Erken kalkmış ahali gözler çakmak

Beraber söyle sen de olsada çapak

Türküler sağılır, canlar ağıtlarda

Türlü öyküler vardır bu hayatlarda

Suları hep akar nedense oluk oluk

İnsanlarının sıcaklığına inadına soğuk

Her evden görünüyor mezarlık, neden? 

Giyilecek son elbise unutulmasın diye kefen

O köyden bilirmisiniz en son an

Suyun serinliğidir hatırımda kalan

Gözlerdedir ne varsa söylenecek

Bilirim ki yollarımız hep gözlenecek.', 'Gördüklerimizi söylesek mi kıra?  Dağlarımı sayalım birde sıra sıra?  Sırlarımızı paylaştığımız deniz kıyısı Alıp götürsün diye rüzgar, aşk ...', ARRAY['Türk Edebiyatı','Şiir','Eyüp Gök']::text[], 8.5, '{"poet":"Eyüp Gök","poet_slug":"eyup-gok","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bir-koy-var-uzakta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünler Geride Kalan', 'dunler-geride-kalan-sabahattin-hizmetli-axk58', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir yaprak daha düştü duvarda ki takvimden,

Sessizce yol almakta ömür son durağına.

Karşı koymak imkansız yolcuyuz istemeden,

Hiç durmadan giderken ömrün son durağına.

Kırma sevdiklerini üzme sakın bilerek,

Kimseler bilemez ki çıkar mıyız yarına.

Gönül bahçelerine hep gül fidanları ek,

Hiç durmadan giderken ömrün son durağına.

Dünler geride kalan şimdi birer hâtıra,

Bir rüzgar esti geçti koptu yaprak dalından.

Dönüp şöyle bir baksan neler gelir hatıra,

Hiç durmadan giderken ömrün son durağına.

Sanki bir bulut geçti kayıp oldu ufukta,

Yıllar böylece gitti giden yıllar ardına.

Torun sahibi oldu dünkü çoluk çocuk da,

Hiç durmadan giderken ömrün son durağına.', 'Bir yaprak daha düştü duvarda ki takvimden, Sessizce yol almakta ömür son durağına. Karşı koymak imkansız yolcuyuz istemeden, Hiç durmadan g...', ARRAY['Türk Edebiyatı','Şiir','Sabahattin Hizmetli']::text[], 8.5, '{"poet":"Sabahattin Hizmetli","poet_slug":"sabahattin-hizmetli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dunler-geride-kalan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '**Öğüt**', 'ogut-asude-gediz-lqow2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'asi nehirdin çağladın yıllarca

mağrur salınırdın  güneşle,söndün

umudun yıldız yıldızken ufukta 

yokluğuna büründün

nasılda ses getirirdin kayadan

pusulada tek yöndün

bütün aşkları yükleyip şimal rüzgarına

izlerine gömüldün

ay ışığında serenat toplardın kulaklarından

gökkuşağı mavisini dondurdun

bütün dalları silkeledi toprak

yokluğundan kafes ördün

kapın çorak toprağa aralık

yaşamın yılgın, susuzluğun doygun, 

bırak güneşe buzulları

kır zicirini sevdanın 

kalan ömrüm! ... sana öğüdüm

bahar can çekişirken hazanda

GÖNLÜM...Sana ÖĞÜDÜM', 'asi nehirdin çağladın yıllarca mağrur salınırdın  güneşle,söndün umudun yıldız yıldızken ufukta  yokluğuna büründün nasılda ses getirirdin k...', ARRAY['Türk Edebiyatı','Şiir','Asude Gediz']::text[], 8.5, '{"poet":"Asude Gediz","poet_slug":"asude-gediz","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ogut-49-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Emine Gülişan', 'emine-gulisan-omer-ziya-soyyigit-gyb51', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Emine Gülişan bağımın gülü

Mevlam Gülişan''ı edepli eyle

Durmadan şakıyan gönül bülbülü

Mevlam gülişanı edepli eyle

Nazlı bir çiçektir, gonca gül gibi

İpek kanatlıdır, kelebek gibi

Naziktir, kibardır hem sümbül gibi

Mevlam gülişanı edepli eyle

Cin gibidir bir şey kaçmaz gözünden

Kaz deyince gölü anlar sözünden

İçindeki anlaşılır yüzünden

Mevlam gülişanı edepli eyle

Sevgi nedir hep o öğretmiş bana

Nüfuz etmiş onun sevdası cana

Bedeldir o benim için cihana

Mevlam gülişanı edepli eyle

Ziya ona mağlup olmuş mutludur

Onun ile her zamanı kutludur

Onun istikbalinden umutludur

Mevlam gülişanı edepli eyle

15 Nisan 1981', 'Emine Gülişan bağımın gülü Mevlam Gülişan''ı edepli eyle Durmadan şakıyan gönül bülbülü Mevlam gülişanı edepli eyle Nazlı bir çiçektir, gonca...', ARRAY['Türk Edebiyatı','Şiir','Ömer Ziya Soyyiğit']::text[], 8.5, '{"poet":"Ömer Ziya Soyyiğit","poet_slug":"omer-ziya-soyyigit","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/emine-gulisan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Aşka Vurgunum*', 'aska-vurgunum-zeynep-sahin-ubope', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben sana değil, aşka vurgunum

Güzel sözlere değil, aşk dolu dizelere...

Konuşmadan bakışlarla kalbe değen göze vurgunum.

Ben sana değil, hasrete vurgunum.

Candan kucaklamalara değil, dağlanan beş parmağa...

Sımsıcak nefese, silinen yaşlara, okşanan saçlara vurgunum.

Ben sana değil, yaşanmamış heveslere, gençliğe, coşkuya, 

Gözü kara o en sıcak kora; 

Aşka vurgunum.', 'Ben sana değil, aşka vurgunum Güzel sözlere değil, aşk dolu dizelere... Konuşmadan bakışlarla kalbe değen göze vurgunum. Ben sana değil, has...', ARRAY['Türk Edebiyatı','Şiir','Zeynep Şahin']::text[], 8.5, '{"poet":"Zeynep Şahin","poet_slug":"zeynep-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/aska-vurgunum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olur', 'olur-tastan-ciralar-bfnrq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çalışıp ter döken zengin olana

Dursam selamına can versem olur

Hoşgörü kültürde engin olana

Yürekle birlikte kan versem olur

Yunus Mevlana’yı pir görseler hoş

Özünü dergâha gir görseler hoş

Dünyayı dolaşıp hür görseler hoş

Huzura varışa şan versem olur

İzlerinde bile kalmasın ahlar

Karanlıklar bitsin açsın sabahlar

Yok olsun mermiler sussun silahlar

Bölüşsem lokmamı nan versem olur', 'Çalışıp ter döken zengin olana Dursam selamına can versem olur Hoşgörü kültürde engin olana Yürekle birlikte kan versem olur Yunus Mevlana’y...', ARRAY['Türk Edebiyatı','Şiir','Taştan Çıralar']::text[], 8.5, '{"poet":"Taştan Çıralar","poet_slug":"tastan-ciralar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/olur-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bazı Şeylerin Nedeni Olmaz', 'bazi-seylerin-nedeni-olmaz-cafer-yilmaz-6dpyq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bazı şeylerin nedeni olmaz, bilirsin.

neden hayattayım demekle aynı

''neden sen? '' sorusu...

serseri bir yaprağın kapılmışlığında

oradan oraya savrulurken

aranırken çürüyecek bir toprak

rüzgara da soramazsın neden diye...

bazı şeylerin nedeni olmaz, bilirsin.

kaptırırken o gözlere kendini

binlerce cilt şiir yazmak gelir içinden

sayfalarca anlatmak...

açılırsın umman denizlere farkında olmadan

boğulursun.

sonra bir gemi geçer kıyından

kurtarmak adına seni

oysa sen boğulurken bile mutlusun...

bazı şeylerin nedeni olmaz, bilirsin.

sabırsızca koştururken hayatta,

durmaksızın, nefes almaksızın...

beklemekten ve bekletilmekten nefret ederken üstelik,

öyle bir zevkle beklersin ki saatlerce,

her anı mutlu bir anı olur

konar ellerine...

bazı şeylerin nedeni olmaz, bilirsin...

serseri bir kurşun gibi

gelir seni bulur aşk denen meret.

yıkılırken toplanır insanlar

az önce yüzüne bakmayan insanlar...

kaybedilmişlikte kavuşmaktır aşk oysa.

yeni bir hayattır mesela...

tetiği çeken ele merhaba.....

                                   20-03-2006', 'bazı şeylerin nedeni olmaz, bilirsin. neden hayattayım demekle aynı ''neden sen? '' sorusu... serseri bir yaprağın kapılmışlığında oradan oray...', ARRAY['Türk Edebiyatı','Şiir','Cafer Yılmaz']::text[], 8.5, '{"poet":"Cafer Yılmaz","poet_slug":"cafer-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/bazi-seylerin-nedeni-olmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Osman2', 'osman2-omer-ziya-soyyigit-09jjg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Osman güzel oğlum tatlımı tatlı

Yeşil bir kelebek, nurdan kanatlı

Gönlümün fatihi, küheylan atlı

Rabbim Osmanımı kemale erdir

Çok zeki yaratmış onu Mevlası

Kalbimin derinlerinde sevdası

Şu dertli gönlümün odur safası

Rabbim Osmanımı kemale erdir

Çok vakurdur Fedaimin bakışı

Nede hoştur kaşlarını çatışı

Hele onun uzanıpta yatışı

Rabbim Osmanımı kemale erdir

Özü sözü nur gibidir, berraktır

Sanki baharda açılan yapraktır

Yaprak neki o nurdan bir topaktır

Rabbim Osmanımı kemale erdir

Ben sevmişim Rabbim sende sev onu

Önü gibi hayırlı olsun sonu

Ziya herdem söyleyecektir bunu

Rabbim Osmanımı kemale erdir

15 Nisan 1981', 'Osman güzel oğlum tatlımı tatlı Yeşil bir kelebek, nurdan kanatlı Gönlümün fatihi, küheylan atlı Rabbim Osmanımı kemale erdir Çok zeki yarat...', ARRAY['Türk Edebiyatı','Şiir','Ömer Ziya Soyyiğit']::text[], 8.5, '{"poet":"Ömer Ziya Soyyiğit","poet_slug":"omer-ziya-soyyigit","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/osman2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağıstan 2', 'dagistan-2-murat-daglibeg-hht92', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dağıstan’ın güzelleri 

Sallar gümüş beşikleri

Burca sancak dikenleri 

Dağıstan’ın koç erleri

Yarenleri, erenleri

Allah için sevenleri

Dağıstan’ın belleri

Yüksekçedir her yeri

Çakılmış duruyor sanki

Semanın direkleri

Soğuk suyu buz gibi 

Karın rengi tuz gibi

Zümrüt yeşil çimenleri

Dağıstan’ın her yeri 

Sayılmıyor güzellikleri

SİVAS/ŞARKIŞLA 08.02.02', 'Dağıstan’ın güzelleri  Sallar gümüş beşikleri Burca sancak dikenleri  Dağıstan’ın koç erleri Yarenleri, erenleri Allah için sevenleri Dağıst...', ARRAY['Türk Edebiyatı','Şiir','Murat Dağlıbeg']::text[], 8.5, '{"poet":"Murat Dağlıbeg","poet_slug":"murat-daglibeg","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dagistan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay Dolanırken Nevroz’a', 'ay-dolanirken-nevroz-a-suna-aras-g4fju', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ay dolanır ten nevroz’a

Sevince toprak aşktır çoğalan

Yüzünün ıslak tuzuna

Oğul verir…

Silah çatmalarından düşen kurşunla

Acısı perçemine büyür alnın 

Her bir tarafı uçurum…

Yüreği üzülen dağdır zulümler

Sarrafıdır efelenir…

Uygunsuz fermanlar dalar geceyi

Beslenir acın yorar düşleri.

Utanan yanımdır Yeşilyurt

Kirletilir sakalları Hitler’li bir hışımla 

Ödül layıktır karama

Yüreğim üşüyüp ufalansa da

Durur dirence dizlerin

Toprağa düşürdüğüm öfkeme oğul

Kuşun sektirir gözlerin

Ölümüne emin

Düşer damlarına Diyarbakır’ın

Ve parlar ateş…

Ve ateş…

Ateşin çocuklarını doğurur

Sevdaya eş.

Gül diyor ölüme Nevroz

Açan, uğunan üç renkte

Gel ki…

Yenik bir insanlıktır onur

Güneşte bir parça buz

Cehennem Halepçe’de.

Sindirilmiş duyguların basılmış akşamları

Var mıdır arkası umutların

Bu ihanetin de özüne

Mutlak bir yanılgıyla dirimimi ağulayan

Ayağa kalkmıyorum önünde insan.

Umar saydığın dağlara yürürken bahar

Armağanlaşır yeşile…

Çözülür saçlarına sevda

Çiçekler sarı açar…

Gül yüzlü muhabbetler kurulur 

Zilan’ın deresinde

Mizgin taşır özgürlüğe gelinim

Mizgin taşır özgürlüğe.

Mizgin: (Kürtçe)  Müjde', 'Ay dolanır ten nevroz’a Sevince toprak aşktır çoğalan Yüzünün ıslak tuzuna Oğul verir… Silah çatmalarından düşen kurşunla Acısı perçemine bü...', ARRAY['Türk Edebiyatı','Şiir','Suna Aras']::text[], 8.5, '{"poet":"Suna Aras","poet_slug":"suna-aras","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/ay-dolanirken-nevroz-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dil', 'dil-murat-daglibeg-7tdyk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dünyada tek sermayeni

Unutma öz dilini 

Yoksa kaybedersin öz benliğini

Düşünemezsin fikrini

Söyleyemezsin zikrini

Dil giderse

Kargaşa başlar, kavga başlar

Tarihin sayfalarına seni kim yazar

Bilir misiniz? Sulanmayan çiçek solar 

Sonrada özüne kargalar konar

Anlamazsınız oyar da oyar

Benliğinden aşağı bir nesne sızar

Zannetme ki yaran kanar

Bedenin işi kendi kuyusunu kazar

Bir milletin nabzı ancak dili ile atar

Dili ile doğar, dili ile yaşar

SİVAS 09.02.02', 'Dünyada tek sermayeni Unutma öz dilini  Yoksa kaybedersin öz benliğini Düşünemezsin fikrini Söyleyemezsin zikrini Dil giderse Kargaşa başlar...', ARRAY['Türk Edebiyatı','Şiir','Murat Dağlıbeg']::text[], 8.5, '{"poet":"Murat Dağlıbeg","poet_slug":"murat-daglibeg","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/dil-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rubai 10', 'rubai-10-murat-daglibeg-nw2d6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Koparmışlar bizleri toprağımızdan 

Bahseder şimdi dedeler o kutsi diyardan 

Kökümüz kesildi, kaldık bir gövde 

Kapıldık zulmün seline gideriz meçhule

 SİVAS 04.03.02', 'Koparmışlar bizleri toprağımızdan  Bahseder şimdi dedeler o kutsi diyardan  Kökümüz kesildi, kaldık bir gövde  Kapıldık zulmün seline gideri...', ARRAY['Türk Edebiyatı','Şiir','Murat Dağlıbeg']::text[], 8.5, '{"poet":"Murat Dağlıbeg","poet_slug":"murat-daglibeg","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/rubai-10-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyt 5', 'beyt-5-murat-daglibeg-pckqk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yine gözün kanlı, yine mi yaşlı? 

Yine bağrın gamlı, yine mi yaslı? 

Sivas 2002', 'Yine gözün kanlı, yine mi yaşlı?  Yine bağrın gamlı, yine mi yaslı?  Sivas 2002...', ARRAY['Türk Edebiyatı','Şiir','Murat Dağlıbeg']::text[], 8.5, '{"poet":"Murat Dağlıbeg","poet_slug":"murat-daglibeg","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/beyt-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşlı', 'yasli-murat-daglibeg-prdz4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kat kat parsellenmiş alınlar 

Feri gitmiş gözlerimde sis var

Bedenim hissiz sanki duvar 

Ruhsuz beden ancak bu böyle yaşar

Kış mı geldi saçlarımda kar

Üşüyorum be sar beni, sar

Sarsan da kar etmez hep zarar 

Şu garibin halini kim sorar

Bu hal ile hallenen ancak halimden anlar

İçten içe bir yer kemirilir ve sızlar

Sorsanız içten içe odsuz ne yanar

Yanan yürektir, gözlerim de duman var

Üç günlük dünya  -gibisi fazla- kumar

Kim kaybetmiş ki iksiri herkes arar 

Bulunmaz en sonda dostlar bir kuyu kazar

Yün yatağa benzemiyor ama herkes yatar

Aklına gelir miydi yorgan olacak 

Üzerine bastığın topraklar

Mezar taşında da şu iki üç kelime yazar

Bir fatiha okuyun kurtulayım -ki ben günahkâr-

Ne gafillik bu birisi mevta ruhuna ağıt yakar 

Bununla da bitmez bizim evde matem var

Sivas 10.02.02', 'Kat kat parsellenmiş alınlar  Feri gitmiş gözlerimde sis var Bedenim hissiz sanki duvar  Ruhsuz beden ancak bu böyle yaşar Kış mı geldi saçl...', ARRAY['Türk Edebiyatı','Şiir','Murat Dağlıbeg']::text[], 8.5, '{"poet":"Murat Dağlıbeg","poet_slug":"murat-daglibeg","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/yasli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akıldan Geçenle', 'akildan-gecenle-tastan-ciralar-px6l0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Akıldan geçenle tezata düşme

Sözünde nasılsan hep öyle görün

Arsa tapun yoksa temeli eşme

Gelmesin iş başa çıkmasın sorun

Selâmlarda bile farklı seda var

Söz sohbet hitapta ayrı eda var

Musalla taşında sonsuz veda var

Daima hatırda saygıyla durun

Aynı ortamları paylaşıyoruz

Acı tatlı ortak gün yaşıyoruz

Çıkarlar uğruna yol şaşıyoruz

Bir doğruda son karara oturun

Önce beyinlere yükleyin yetki

Gelin güzelliğe ekleyin katkı

Kırılıp ayrışma öyle berbat ki

Ayaklardan başa selâm götürün

Dinle dersin övmüş yaratmış Allah

Yürekten tam öyle isterim billah

Değişken yüzlüden bıktım illellah

İğne sana şiş Taştan’a batırın', 'Akıldan geçenle tezata düşme Sözünde nasılsan hep öyle görün Arsa tapun yoksa temeli eşme Gelmesin iş başa çıkmasın sorun Selâmlarda bile fa...', ARRAY['Türk Edebiyatı','Şiir','Taştan Çıralar']::text[], 8.5, '{"poet":"Taştan Çıralar","poet_slug":"tastan-ciralar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/akildan-gecenle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Efendim', 'efendim-omer-ziya-soyyigit-cuelk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben ezelden sevmişim

Seni candan efendim

Kendime dost seçmişim

Seni candan efendim

Bir soydan bir kandanız

Bir ruhtan, bir candanız

Aşıkındır bendeniz

Sana candan efendim

Sonsuzdur itimadım

Seninledir muradım

Dağı, taşı aradım

Seni buldum efendim

Bahçeyi, bağı gezdim

Ovayı, dağı gezdim

Cümle otağı gezdim

Sana geldim efendim

Sadakat var sözünde

Şefkat dolu özünde

Yürüyorsam izinde

Senin lutfun efendim

Ağlasam güldürürsün

Aşk ile doldurursun

Sevince öldürürsün

Diriltirsin efendim

Ziya yansın, kül olsun

Senin sevginle dolsun

Bu canım feda olsun

Sana bin kez efendim

21 Nisan 1981', 'Ben ezelden sevmişim Seni candan efendim Kendime dost seçmişim Seni candan efendim Bir soydan bir kandanız Bir ruhtan, bir candanız Aşıkındı...', ARRAY['Türk Edebiyatı','Şiir','Ömer Ziya Soyyiğit']::text[], 8.5, '{"poet":"Ömer Ziya Soyyiğit","poet_slug":"omer-ziya-soyyigit","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/efendim-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hep Böyle Kal!', 'hep-boyle-kal-serap-tepedelen-ka9c4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kıskandım seni çocuk,

Oyunlarını,misketlerini,giysilerini...

Kıskandım da inan,

Bir köşede oturup tırnaklarımı yedim kıskançlıktan.

Omuz silkişini kıskandım,

Umursamazlığını,dostluğunu,

sımsıcak yürekler dolusu saflığını.

İmrendim sana çocuk,

Geçmişe özlem duydum sana bakınca

Parça parça ettim yüreğimi

Ettim de toparlayamadım parçaları bir türlü

Renkli balonlarını kıskandım,

Düşlerini,umutlarını

Çektim aldım hırsla senden

Aldım da koydum yanıbaşıma

Kendime yakıştıramadım,

Utandım.

Ah çocuk,

Onca kıskanırken ben seni,

Sense büyümeye özendin.

Neden? 

Büyümek o kadar yakın ki sana,

Uzatsan elini,tutuvereceksin.

Ama ben,

İstesem de yüz kere,milyon kere

Geçmişe dönemem,

Çocuk olamam.

N''olur bir kerecik geçiversem

Geçmişin süzgeçinden

Dönemem.

Bana öylesine uzak ki

Seksekler,birdirbirler,o gökkuşağı örneği düşler...

Kıskandım seni çocuk.

Bırak,büyümeye özenme

Sen sevgiden örülmüş çemberini eline al,

Ve büyüme çocuk,

Hep böyle kal! 

(1996,Bursa)

.', 'Kıskandım seni çocuk, Oyunlarını,misketlerini,giysilerini... Kıskandım da inan, Bir köşede oturup tırnaklarımı yedim kıskançlıktan. Omuz sil...', ARRAY['Türk Edebiyatı','Şiir','Serap Tepedelen']::text[], 8.5, '{"poet":"Serap Tepedelen","poet_slug":"serap-tepedelen","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/hep-boyle-kal-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Şiir*', 'siir-murat-daglibeg-rxalo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir mısra şiir dile gelsin diye 

Ol cezbeden bir zerre tatmak gerek

İnceden inceye her şey anlatılsın diye 

Ol kaktüsü şefkat ile sevmek gerek

Bir mısra şiir yazmak için

İlham kaynağını bulmak gerek 

Aşk çanağını doldurup

Bir kalemi sevmek gerek

Daha sonra ol cazibeden sarhoş olup

Kalemi çanağa daldırmak gerek 

Aşk şarabına bulanıp

Bir kâğıt üzerinde raksetmek gerek

Sivas 25.04.02     murad-i', 'Bir mısra şiir dile gelsin diye  Ol cezbeden bir zerre tatmak gerek İnceden inceye her şey anlatılsın diye  Ol kaktüsü şefkat ile sevmek ger...', ARRAY['Türk Edebiyatı','Şiir','Murat Dağlıbeg']::text[], 8.5, '{"poet":"Murat Dağlıbeg","poet_slug":"murat-daglibeg","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/siir-155-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yurdum', 'yurdum-murat-daglibeg-a68wd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen ağlama yurdum 

Gözü yaşlı kuzun var

Sen yakınma yurdum 

Ciğerimde sızın var

Dağında taşında 

Yolunda yokuşunda 

Yazında kışında

Çil çil alın terim var

Soluk soluk nefesim 

Kırbaç yedim örselendim 

Kalleşçe vuruldum pes etmedim

Toprağında kanım var

Dallarda ötüşür kuşlar

Şırıl şırıl çağlayan ırmaklar

Dudaklarda şarkılar

Sazında telim var

Sivas 24.02.02', 'Sen ağlama yurdum  Gözü yaşlı kuzun var Sen yakınma yurdum  Ciğerimde sızın var Dağında taşında  Yolunda yokuşunda  Yazında kışında Çil çil ...', ARRAY['Türk Edebiyatı','Şiir','Murat Dağlıbeg']::text[], 8.5, '{"poet":"Murat Dağlıbeg","poet_slug":"murat-daglibeg","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yurdum-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Usandık', 'usandik-murat-daglibeg-jzlpv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sesimi duy hemşerim 

Ne kadar uzak olsam da leşkerim 

Öz yurdunu işgal ile meşgul iken kefere

Sen meçhule karışmak üzere olan, katıl bu nefere

Hasımlar gün geçtikçe çoğaldı, düşman ezeli

Sessiz kalma, yoksa yurdunda kalırlar ebedi

Ölmeden önce,

Ölmemek için ölür müsün binlerce kere 

Katılır mısın hürriyetin için bu son sefere

Dünya yüzünden Kafkas halkı yok mu olsun 

Vakti gelen gül gibi Kafkasya’da mı solsun

Unutma bir gün ırkın muhacir diye anılır 

O çok sevdiğin yurdun Hicretistan diye yazılır

Sanma ki yurdundan uzaklarda rahat edersin 

Vatanında şehit olmayan, viranelerde gebersin

Dur bekle! Bir iki çift lafım var 

Sende katıl aramıza olalım koca bir duvar 

Kuvvet doğar birlikten, kenetlenmekten

Usandık gayri hırpalanmaktan, örselenmekten 

Sivas 01.03.02', 'Sesimi duy hemşerim  Ne kadar uzak olsam da leşkerim  Öz yurdunu işgal ile meşgul iken kefere Sen meçhule karışmak üzere olan, katıl bu nefe...', ARRAY['Türk Edebiyatı','Şiir','Murat Dağlıbeg']::text[], 8.5, '{"poet":"Murat Dağlıbeg","poet_slug":"murat-daglibeg","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/usandik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Ben Var Benden Zİyade', 'bir-ben-var-benden-zi-yade-fatih-cinar-bv0ao', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sen sende değil

sen benim içimdeymişsin

ben aynalarda seni gördüm

gökte nafile aradığım senmişsin

sen sende değil

sen benim canımdaymışsın

ben nafile canan aradım

meğer cana sen cananmışsın', 'sen sende değil sen benim içimdeymişsin ben aynalarda seni gördüm gökte nafile aradığım senmişsin sen sende değil sen benim canımdaymışsın b...', ARRAY['Türk Edebiyatı','Şiir','Fatih Çınar']::text[], 8.5, '{"poet":"Fatih Çınar","poet_slug":"fatih-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bir-ben-var-benden-ziyade-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben neyim', 'ben-neyim-murat-daglibeg-6ul4m', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben neyim 

Karanlık gecede bir karartı

Pervasız gönüllerde taneyim

Uzak diyarlarda bitmez sıla 

Yüreklerde pareyim 

Ben neyim 

Umuda giden bir yolcu 

Umutsuz bir burcu

Bozkırlarda yaban 

Işığa bakan amayım

Ben neyim 

Asırlar da bir an 

Kafalarda bir zan 

Olmazdan önce bir kan 

Ben neyim 

Deryada bir damla 

Çöllerde bir kara nokta

Gönüllerde yara 

Bulunmayan çareyim 

Ben neyim 

Özünden uzak bir sığıntı 

Ismarlama bir yığıntı

Çözümsüz bir bağıntı 

Ben neyim 

Sarmaş dolaş bir yumak

Ruhum biçare sunak 

Dilim damağım kurak

Mevsiminden önce yeşeren başak

Ben neyim 

Bağrımda bir umur

Somur babam somur

Alın yazım “dokuz doğur”

Kıraç bedenimi yoğur

Ben neyim 

Ben duyguların esiri 

Olayların tesiri 

Özden ayrıldığımdan beri

Unutamadım o kutlu mabedi

Unutamam, kalacak hep ebedi

Sivas 12.05.02', 'Ben neyim  Karanlık gecede bir karartı Pervasız gönüllerde taneyim Uzak diyarlarda bitmez sıla  Yüreklerde pareyim  Ben neyim  Umuda giden b...', ARRAY['Türk Edebiyatı','Şiir','Murat Dağlıbeg']::text[], 8.5, '{"poet":"Murat Dağlıbeg","poet_slug":"murat-daglibeg","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/ben-neyim-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sultanım', 'sultanim-omer-ziya-soyyigit-pmdmt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir kadeh nuş ettim bezm-i ezelde

Safalar getirdi bana sultanım

O lezzet var iken ağızda dilde

Bülbüle döndürdü beni sultanım

Ne gücüm var idi nede kuvvetim

Lal olmuştu bütünüyle kudretim

Aşikar olmuş idi mürüvvetim

Seni candan sevmiş idim sultanım

Coşuyordum, coşkun akan sel gibi

Açıyordum ilkbaharda dal gibi

Sözlerinde lezzet vardı, bal gibi

Kovanımın sahibiydin sultanım

Noldu bilmem pınarıma, bulandı

Dallarımda hep baykuşlar dolandı

Sanki o tatlı sözlerim yalandı

Yıllarımı heba ettim sultanım

Zaman zaman parlıyordu lem''alar

Semalardan geliyordu damlalar

Yanıyordu, hiç sönmeden lambalar

Görmüyordu benim gözüm sultanım

Kararmış kalbime saldın Ziya''yı

Talim ettin hem edebi hayayı

Buldum şükür, özlediğim safayı

Yine lutfeyledin bana sultanım

21 Nisan 1981', 'Bir kadeh nuş ettim bezm-i ezelde Safalar getirdi bana sultanım O lezzet var iken ağızda dilde Bülbüle döndürdü beni sultanım Ne gücüm var i...', ARRAY['Türk Edebiyatı','Şiir','Ömer Ziya Soyyiğit']::text[], 8.5, '{"poet":"Ömer Ziya Soyyiğit","poet_slug":"omer-ziya-soyyigit","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sultanim-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyt 6', 'beyt-6-murat-daglibeg-00hzs', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bizler ümit bağlamadık yaban bağına

Hor bakmadık yaşadığımız Kaf Dağına

Sivas 2002', 'Bizler ümit bağlamadık yaban bağına Hor bakmadık yaşadığımız Kaf Dağına Sivas 2002...', ARRAY['Türk Edebiyatı','Şiir','Murat Dağlıbeg']::text[], 8.5, '{"poet":"Murat Dağlıbeg","poet_slug":"murat-daglibeg","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/beyt-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dumanlı Dağlar', 'dumanli-daglar-fatma-guven-harqd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yol verin de geçem dumanlı dağlar,

Yavrum da benden bir haber umar,

Ses verdim de sesime karışır rüzgar,

Yol verin de geçem dumanlı dağlar,

Kınalı kuzum hasretimden ağlar.

Mor menevşe,nergiz,sümbül açılır,

Benim yüreğime de yaralar açılır,

Koyun kuzu da birbirinden seçilir,

Yol verin de geçem dumanlı dağlar,

Gurbet elde yavrum benim ağlar.

Türlü işler de gelirmiş bu başa,

Söylemeyin halimi kavum,gardaşa,

Yüreğimdeki közüm de döndü bir ataşa,

Yol verin de geçem dumanlı dağlar,

Gurbet elde benim yavrum ağlar.', 'Yol verin de geçem dumanlı dağlar, Yavrum da benden bir haber umar, Ses verdim de sesime karışır rüzgar, Yol verin de geçem dumanlı dağlar, ...', ARRAY['Türk Edebiyatı','Şiir','Fatma Güven']::text[], 8.5, '{"poet":"Fatma Güven","poet_slug":"fatma-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/dumanli-daglar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Susmasan', 'susmasan-volkan-yoruc-ljyq8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Susmasan

Hep konuşsan, anlatsan

Hayat olsan, kader olsan

Ömürdeki son durak olsan

Susmasan

Hep anlatsan, karanlığımı aydınlatsan

Yolum olsan, yordamım olsan

Usuldan fısıldasan

Maziden girip yarına aksan

Yani benle olsan, yanımda kalsan

Hiç susmadan kalbimde dursan

Dilesem gerçekleşirmi? 

İstesem gelirmi? 

Düşlesem bilirmi? 

Anlatsam dinlermi?', 'Susmasan Hep konuşsan, anlatsan Hayat olsan, kader olsan Ömürdeki son durak olsan Susmasan Hep anlatsan, karanlığımı aydınlatsan Yolum olsan...', ARRAY['Türk Edebiyatı','Şiir','Volkan Yoruç']::text[], 8.5, '{"poet":"Volkan Yoruç","poet_slug":"volkan-yoruc","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/susmasan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ruhumu Giydirip / Bedenimi Soydum', 'ruhumu-giydirip-bedenimi-soydum-guler-atas-qnl8j', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hava sıcaktı..rüzgar yoktu..

Sakin duru bir akşamdı

Dediğini yaptım eyyy sevgili

Açtım gözümü aştım gönlümü

Serçeydim bir gül dalında

Tutunmaya çalışan duygularına

Titredim

Sonbahar vurmuş yaprak gibi

Ayağına diken batmış serçe gibi

Kasabının elinde masum kuzu gibiydim

Titredim eyyy sevgili titredimm

hisset istedim

Bedenimi  beynimden ayırıp

Kalbimi evde bırakıp

Alıp sahte renklerimi gittim

Ruhumu giydirip,soydum bedenimi

Hisset istedim hisset

dağılmış  yürek nasıl olurmuş

Ben ateşte kavururken bu aşkı

Hisset istedim canın yansın istedim

Bedenini giydirip ruhunu soy istedim

Çırılçıplak olsun bütün gecelerin

Dediğini yaptım eyyy sevgili

Durgun bir geceye fırtına ektim

Saldım gök yüzüne çığlıklarımı

Bu sabah ilk işin gök yüzüne bakmak olsun

Bir bulut görürsen bilki

Gözümün yaşıdır içindeki

Az güneş görürsen

Bilki soğuyor içim

Yakarsa bu kış günü gözlerini güneş

Bilki yanmışım alevidir yansıyan

Dediğini yaptım eyyy sevgili

Ruhumu giydirip soydum bedenimi..

               20 /03/2006', 'Hava sıcaktı..rüzgar yoktu.. Sakin duru bir akşamdı Dediğini yaptım eyyy sevgili Açtım gözümü aştım gönlümü Serçeydim bir gül dalında Tutunm...', ARRAY['Türk Edebiyatı','Şiir','Güler Ataş']::text[], 8.5, '{"poet":"Güler Ataş","poet_slug":"guler-atas","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/ruhumu-giydirip-bedenimi-soydum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hani Sevgiliydik', 'hani-sevgiliydik-tastan-ciralar-zp7gs', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hani sevgiliydik kusursuz yardık

            Bir yüzün gündüzken biri gece mi

            Birbirini seven çok bahtiyardık

            O ruh bedeninde bir bilmece mi

            Dünü geçti sayan yarına koşan

            Dil yürek uyumsuz farklı konuşan

            Cismine benzemez gölgesi düşen        

            Arlı edepli mi şanın yüce mi

           ‘’Bu ağız benimse ne olsa derim

            Ne istersem onu öyle söylerim

            İster otururum ister giderim’’

            Bu davranış söz ve sohbet hece mi

             Ben Taştan’dım ne şöhrettim ne ündüm             

             Özümü sözüme döktüm de sundum

             Bilinen yazıyken nasıl okundum

             Hintçe, Arapça mı, İbranice mi', 'Hani sevgiliydik kusursuz yardık             Bir yüzün gündüzken biri gece mi             Birbirini seven çok bahtiyardık             O ruh ...', ARRAY['Türk Edebiyatı','Şiir','Taştan Çıralar']::text[], 8.5, '{"poet":"Taştan Çıralar","poet_slug":"tastan-ciralar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hani-sevgiliydik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benimkisi', 'benimkisi-kemal-demirhisar-d6451', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sensizligin kuruttugu bu colde yasamak iste benimkisi,

Gercek olmayan dusler icinde hayal kurmak, tek basina oturup gunlerce aglamak iste.

Aksamin karanligindan sabahin ilk isiklarina kadar seni sayiklamak,

Seni, sensizlikle yasamak iste benimkisi.

Gokyuzundeki yalanci bulutlara uzanmak, her deneyisinde tekrar ve tekrar hayal kirikligina ugramak iste

Gozlerinden suzulen her damla yasla hayati anlamak,

Hayat denilen o seyin bir avuc yalandan ibaret oldugunu anlamak iste benimkisi.

Seni sevmek iste benimkisi, senin beni sevmedigini bilmek ve yinede, YINEDE seni sevmek iste benimkisi.

							''K''', 'Sensizligin kuruttugu bu colde yasamak iste benimkisi, Gercek olmayan dusler icinde hayal kurmak, tek basina oturup gunlerce aglamak iste. A...', ARRAY['Türk Edebiyatı','Şiir','Kemal Demirhisar']::text[], 8.5, '{"poet":"Kemal Demirhisar","poet_slug":"kemal-demirhisar","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/benimkisi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '4 Mevsim', '4-mevsim-adulera-ayza-vlt00', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ve sen

Yıllardır nerde idin

Düştüm görmedin

Sevdim ölmedin

Sövdüm görmedin

İçtim sen

Ve sen duymadın

Dalsın sen

Yeni bahar  dalı

Ne rüzgarlar gördünde

Bir tanesi kırılmadı

Tutundum o dalına

Ama  bittim

Gücüm kalmadı

Ve sen

Nerdeydin şimdiye kadar

Sevdim olmadı

Sarardım solmadı

Sen yaz güneşi idin

Bir gün olsun bahtın

Kararmadı

 Sen ben

Kıştı yagan ne idi bilemem

Ölürüm  ayazlarda da

Senden geçemem

Sen sonbahar

Bahtım gibi

Ahtım gibi

Evlenecegim yarim gibi

Sonbahar son karar

Sanki yeniden uyanır gibi', 'Ve sen Yıllardır nerde idin Düştüm görmedin Sevdim ölmedin Sövdüm görmedin İçtim sen Ve sen duymadın Dalsın sen Yeni bahar  dalı Ne rüzgarla...', ARRAY['Türk Edebiyatı','Şiir','Adulera Ayza']::text[], 8.5, '{"poet":"Adulera Ayza","poet_slug":"adulera-ayza","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/4-mevsim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Icinden Gelen Ses', 'icinden-gelen-ses-kemal-demirhisar-jn2xe', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gun basliyor yine, sabahin ilk isiklari,

Aksamdan kalma korku, ve gozyaslari,

Hayal dunyamin hayalet insanlari,

Kaybolup gittim artik, unuttum o diyarlari.

Sensiz gecen bir gun, ve bir gun daha,

Olmayacagini bile bile niye bu izdirap, bu caba,

Sensiz birbirini kovalayan her saniye, her dakika.

O gunu hatirlatiyor huzunle bana.

Oyunun kuralini bilmiyorsan hic bosuna baslama,

Sonunda kaybeden sen olacaksin, sonra oturup aglama,

Kendi gozyaslarinda bogulsan bile kimse seni duymayacak,

Hayat dedigin bu arkadas, kendini bosuna aldatma! 

					''K''', 'Gun basliyor yine, sabahin ilk isiklari, Aksamdan kalma korku, ve gozyaslari, Hayal dunyamin hayalet insanlari, Kaybolup gittim artik, unutt...', ARRAY['Türk Edebiyatı','Şiir','Kemal Demirhisar']::text[], 8.5, '{"poet":"Kemal Demirhisar","poet_slug":"kemal-demirhisar","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/icinden-gelen-ses-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ve Sen', 've-sen-kemal-demirhisar-y1rj9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'VE SEN

Sensiz gecen gunler ve geceler,

Zamansiz acan guller ve menekseler,

Aksamin ardindan gelen derin dusunceler,

Ve SEN.

Yuzundeki tebessum, saclarindaki sari,

Gozlerinden yayilan o muhtesem parilti,

Kaygilarla dolu hayatin kucuk oyunlari,

VE SEN

Olumden korksan orda isin ne? 

Olumden korksam senle isim ne? 

Geride biraktigim aylarda ve gunlerde, 

Yine sen VE SEN

				''K''', 'VE SEN Sensiz gecen gunler ve geceler, Zamansiz acan guller ve menekseler, Aksamin ardindan gelen derin dusunceler, Ve SEN. Yuzundeki tebess...', ARRAY['Türk Edebiyatı','Şiir','Kemal Demirhisar']::text[], 8.5, '{"poet":"Kemal Demirhisar","poet_slug":"kemal-demirhisar","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ve-sen-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erirmiydin ki?', 'erirmiydin-ki-veysel-alkan-uyhtf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben seni hep sevdim,vazgeçemedim.

Biraz da sen sevsen,erirmiydin ki? 

Vefasız kalbinle,başedemedim.

Biraz da sen etsen,erirmiydin ki? 

Kalbime saplanan,bakışın oktu.

Uğruna ömrünü,adayan çoktu.

Ben seni sevdim de,karşılık yoktu.

Biraz da sen görsen,erirmiydin ki? 

Nasıl bir kaderdin,nasıl kısmettin? 

Aşkı arttırmadın,umut eksilttin.

Yüreği kavuran,sonsuz hasrettin.

Biraz da sen gelsen,erirmiydin ki? 

Çektiğim acıyı,kimse anlamaz.

Böyle bir yaraya,merhem bulunmaz.

Çaresi tek sendin,başkası olmaz.

Biraz da sen versen,erirmiydin ki? 

Yokluğun denk geldi,boş bir anıma.

Azrail kandırdı,girdi kanıma.

Geç kaldın! ,sensizlik yetti canıma.

Biraz da sen girsen,erirmiydin ki?', 'Ben seni hep sevdim,vazgeçemedim. Biraz da sen sevsen,erirmiydin ki?  Vefasız kalbinle,başedemedim. Biraz da sen etsen,erirmiydin ki?  Kalbi...', ARRAY['Türk Edebiyatı','Şiir','Veysel Alkan']::text[], 8.5, '{"poet":"Veysel Alkan","poet_slug":"veysel-alkan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/erirmiydin-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anne 2', 'anne-2-omer-ziya-soyyigit-wpvsi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şefkat ve sevgiyi elden bırakma

İntizar eyleme oğluna anne

Babı merhametin bağlı olmasın

Beddua eyleme sevgili anne

Sırtında gezdirdin onu yıllarca

Yemedin yedirdin, çok defalarca

Ömrün artıyordu ona bakınca

Söylesene, öyle değil mi anne? 

Uykuyu terk eder gece kalkardın

Çalı çırpı toplar ateş yakardın

Belki saatlarca beşik sallardın

Türlü türlü ninni söylerdin anne

Nısfulleyle kadar onu beklerdin

Yavrum ağlıyor mu diye dinlerdin

Şüphe yok canından fazla severdin

Bağrına basardın kuzunu anne

Kundakta, beşikte sonra döşekte

Çekilerek gitti, durdu eşikte

Bir gün ağlamıştı hem, bitişikte

Demiştin evladım yürüdü, anne

Attığı her adım sence bir devlet

Anne söylemesi büyük saadet

Gülüp oynayışı membai kuvvet

Oldu senin için bilirim anne

Kalbinin kapısı ona açıktı

Aşk-ı mahabbeti kalbini yaktı

Gelip ellerini boynuna taktı

Koklayıp bağrına basardın anne

Soğukta üşüdün, sıcakta yandın

Bir an ah! demeden nasıl dayandın

Yalan sözlerine dahi inandın

Hayır, öyle değil, demedin anne

Yıllarca bekledin büyümesini

Büyüyüp büyüyüp evlenmesini

Çekerdin nazını, her cilvesini

Yüzüne vurmazdın suçunu anne

Canım anneciğim, hakkın büyüktür

Rızanı kazanmak ise çok güçtür

Bedduanı almak en büyük suçtur

Asi evladını affeyle anne

Evletmek istedin kabul etmedi

Gösterdiğin doğru yoldan gitmedi

Çok yalvardın fakat o dinlemedi

Suçludur evladın affeyle anne

Avare olmuşum, gezerim dilde

Kalmadı dermanım ayakta, elde

Ah edip söylerim o günler nerde

Yandı tüttü Ömer, affeyle anne

16 Haziran 1958', 'Şefkat ve sevgiyi elden bırakma İntizar eyleme oğluna anne Babı merhametin bağlı olmasın Beddua eyleme sevgili anne Sırtında gezdirdin onu y...', ARRAY['Türk Edebiyatı','Şiir','Ömer Ziya Soyyiğit']::text[], 8.5, '{"poet":"Ömer Ziya Soyyiğit","poet_slug":"omer-ziya-soyyigit","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/anne-2-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerinden', 'gozlerinden-mustafa-erdem-5pjh9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözlerini rüyalarda ararım

		gözlerin

		         ileri doğru geniş

		         aşağı doğru derin

		         bulutlar kadar yüksek

yıllara

binlerce şekil çizmiş gözlerin

ve can üflemiş her şekile

her şekil bir rüya görmüş

milyarlarca rüya

milyarlarca şekil

her şekil hareket eder

		       ileri

			aşağı

			       yukarı

yürürler hep arpa boyu yollar

şekiller birbirine karışır

şekiller birbirinden ayrılır

şekiller ağırlaşır

gözyaşından süzerler güneşi	

renkler görür şekiller

		       siyah –

			     beyaz

renkler utanır gözlerinden

fırtınalarla kumlar

		dolar şekillerin yüzlerine

iniltiler gelir halka halka

		mehlikâ mehlikâaa

şekiller göremez bir göz kumlardan

milyarlarca şekil milyarlarca

		damla akıtır

			  varsa gözlerinden

mehlikâaa

	gözlerinden

göster gözlerini mehlikâ

		firak gözlerinden

dokun ellerinle mehlikâ

		yaşlar gözlerinden

		

	mehlikâaa

		gözlerinden

			(09.05.2003-Midyat)', 'Gözlerini rüyalarda ararım 		gözlerin 		         ileri doğru geniş 		         aşağı doğru derin 		         bulutlar kadar yüksek yıllara bin...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Erdem']::text[], 8.5, '{"poet":"Mustafa Erdem","poet_slug":"mustafa-erdem","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/gozlerinden-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bendeki ben', 'bendeki-ben-huseyin-sonmez-fupt6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ruh bir yerde,

Beden bir yerde,

Düşmüşüm,

Onulmaz bir derde,

Hiçbir derman

Kalmadı bende.

Şu aciz bedende.

Gözlerime inmiş perde,

Bir ışık bulursam

Ben sende,

Sendeki o yerde,

Acaba kurtulur muyum? 

Bendeki bende...', 'Ruh bir yerde, Beden bir yerde, Düşmüşüm, Onulmaz bir derde, Hiçbir derman Kalmadı bende. Şu aciz bedende. Gözlerime inmiş perde, Bir ışık b...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sönmez']::text[], 8.5, '{"poet":"Hüseyin Sönmez","poet_slug":"huseyin-sonmez","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bendeki-ben-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Vatana Yadigarsın İstanbul', 'bu-vatana-yadigarsin-i-stanbul-seyfet-bozcali-0r3xw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bin dört yüz elli üçten bu güne,

Bu vatana yadigarsın İstanbul.

Ezanla eşleşir arşta minare,

Resulümden ümmete bir müjdesin İstanbul....

Fatihin göz ağrısı tüm dinlerin dergahı,

Turiste mekan olmuş Sultan Ahmet meydanı.

Anılmadan geçilmez Ulubatlı Hasanı,

Güzel Eyüp Sultanda bir mabetsin İstanbul...

Bir zamanlar ülkemi işgal için gelenler,

Selamlayarak geçer boğazlardan gemiler,

Gözyaşında duayla hoca Akşemsettinler,

Yedi tepe üstünde bir kalkansın  İstanbul...

Fatihinle bizlere yeni bir çağ atlattın,

Mağrur kokan Bizansı sonsuz tarihe attın.

Şanlı tarihimize büyük şerefler kattın,

Maneviyatla yüklü bir bulutsun İstanbul...

Yere batan sarayın gizemi sende saklı,

Çamlıca tepesinden görünüşün çok farklı.

Yuşa Peygamberinde senin bağrında saklı,

Kutsal amenetlerle  bir umutsun İstanbul...

Gerdanlık gibi süsler yakasını denizler,

İki aşık gibidir,Beykoz ile Üsküdar.

Onbeş milyon insana bir çok olanak sunar,

Çaresize çaresin,bir sevgisin İstanbul...

Halicinde cınlıyor halen nalın sesleri,

Sanayiye katkısı güldürür çok yüzleri.

Şaire ilham olur,yazdırır dizeleri,

Tüm Dünyanın gözünde sen başkasın İstanbul...

Martılar özgür uçar,bestelenir şarkılar,

Altın boynuz halicin,düşmana çaka satar.

Tarih kokar bağrında,Topkapılar,hisarlar,

Allahın bir lütfusun,bu millete İstanbul...

Kucak,kucağa yaşar ormanıyla denizi,

Medineden  gelen o Ashabın ayak izi,

Hep bağrına basarsın,sahipsizi,öksüzü,

İşsizime aş,ekmek bir ümitsin İstanbul...

Bir kere gören gözler yine istiyor  seni,

Muhteşem görünümün coşturur  gönülleri,

Bu şair Seyfetinde sanadır duaları,

Gururla şehidime bir mekansın İstanbul...

        21.03.2006', 'Bin dört yüz elli üçten bu güne, Bu vatana yadigarsın İstanbul. Ezanla eşleşir arşta minare, Resulümden ümmete bir müjdesin İstanbul.... Fat...', ARRAY['Türk Edebiyatı','Şiir','Seyfet Bozçalı']::text[], 8.5, '{"poet":"Seyfet Bozçalı","poet_slug":"seyfet-bozcali","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/bu-vatana-yadigarsin-istanbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adalet', 'adalet-huseyin-sonmez-udqq3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir deri bir kemik garibim aç,

Yıllarca arar derdine ilaç,

Tanrım adaletin nerede? 

Olmasın kimse kimseye muhtaç.', 'Bir deri bir kemik garibim aç, Yıllarca arar derdine ilaç, Tanrım adaletin nerede?  Olmasın kimse kimseye muhtaç....', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sönmez']::text[], 8.5, '{"poet":"Hüseyin Sönmez","poet_slug":"huseyin-sonmez","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/adalet-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yükselmek', 'yukselmek-huseyin-sonmez-77wui', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kısacık ömrü,

Basit değersiz kılma! 

Çalış,mücadele et,yılma! 

Bulunduğun yerden

Yükseklere çık.

Hep aynı yerde

Kalma.', 'Kısacık ömrü, Basit değersiz kılma!  Çalış,mücadele et,yılma!  Bulunduğun yerden Yükseklere çık. Hep aynı yerde Kalma....', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sönmez']::text[], 8.5, '{"poet":"Hüseyin Sönmez","poet_slug":"huseyin-sonmez","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yukselmek-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek', 'sevmek-huseyin-sonmez-cz7o2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çirkinlikler arasından

Güzellikler görmeli,

İyiliği,dürüstlüğü

Nakış gibi örmeli.

Zalimlerle

Dolu olsa da dünya.

Yaradılanı

Hoş görmeli

Sevmeli...', 'Çirkinlikler arasından Güzellikler görmeli, İyiliği,dürüstlüğü Nakış gibi örmeli. Zalimlerle Dolu olsa da dünya. Yaradılanı Hoş görmeli Sevm...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sönmez']::text[], 8.5, '{"poet":"Hüseyin Sönmez","poet_slug":"huseyin-sonmez","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sevmek-154-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sorabes...', 'sorabes-kashmir-art-fyfbh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Heptapygron da sesini aradım bu gece

Pilonlarıma ışık serpen sesini

Susuzdu saçlarına dudaklarım

dudaklarına  Sorabes...

Gece zehir gibi,gurbet gibi doldu içime

Heptapygron da seni aradım

seni ve rüyalarımı

rüyalarını Sorabes...

Saatler yürümüyor

Çarmıha gerilmiş bir zaman

Ben zamana,ben sana.ben sana

sana Sorabes...

Sensiz,yıldızlarım kapkara

Güneşim senle batıyor

günlerdir,aylardır,yıllardır,asırlardır

uykusuzum Sorabes...

Ve sen! 

Sana  hiçbir şey vermeyecek olan

insanların arasındasın

Onlar sensiz de yaşar Sorabes...

Ne havasısın onların,ne suyu

Benimkisi dipsiz kör bir kuyu

Heptapygron da havasız kaldım

bunaldım Sorabes...

Alacağım bir nefes

sensin Sorabes...

Gel,gel,gel gel.............

Bir kez! 

Alayım son bir nefes Sorabes...', 'Heptapygron da sesini aradım bu gece Pilonlarıma ışık serpen sesini Susuzdu saçlarına dudaklarım dudaklarına  Sorabes... Gece zehir gibi,gur...', ARRAY['Türk Edebiyatı','Şiir','Kashmir Art']::text[], 8.5, '{"poet":"Kashmir Art","poet_slug":"kashmir-art","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/sorabes-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boğaziçi''nde Sabah', 'bogazici-nde-sabah-munevver-erilmez-phmk8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Deniz ilâhi  bir uykuda uyumakta,

Erguvanlar açmış Boğaz''da.

Bülbüller,güllerle koklaşmakta

Paşabahçe Koy''u mezbelelik olsa da,

Erguvanlar tüm gücüyle direnmekte,

Sanki denizle kucaklaşmakta.

Vazgeçemediğim sevgili,

Ey güzel İstanbul''um; 

Seyrine doyamadığım Boğaziçi,

Beykoz,Bebek,Kanlıca

Sana zulüm değil! 

Bakım gerek,şanlıca.', 'Deniz ilâhi  bir uykuda uyumakta, Erguvanlar açmış Boğaz''da. Bülbüller,güllerle koklaşmakta Paşabahçe Koy''u mezbelelik olsa da, Erguvanlar t...', ARRAY['Türk Edebiyatı','Şiir','Münevver Erilmez']::text[], 8.5, '{"poet":"Münevver Erilmez","poet_slug":"munevver-erilmez","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bogazici-nde-sabah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Camın Ettiği', 'camin-ettigi-serap-tepedelen-j8em6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir elinde yağlı ekmek,

Bir elinde çomak

Toprağı karıştırıyor bir şey ararcasına

Gözleri çakmak çakmak.

Biraz daha kazdı toprak altını

İşte,bir şey parladı,

Bir cam kırığı.

Ne güzel,ışıl ışıl! 

Birden,cam elini kesti.

Artık güzel değil o,

Pis,kaka.

Hırsla fırlattı camı yere,

Çocuk ağladı.

(1981,Bursa)', 'Bir elinde yağlı ekmek, Bir elinde çomak Toprağı karıştırıyor bir şey ararcasına Gözleri çakmak çakmak. Biraz daha kazdı toprak altını İşte,...', ARRAY['Türk Edebiyatı','Şiir','Serap Tepedelen']::text[], 8.5, '{"poet":"Serap Tepedelen","poet_slug":"serap-tepedelen","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/camin-ettigi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluluk', 'mutluluk-ahmet-ziya-pektas-exphu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çocuk,

Güldü.

Tozlu giysileriyle,

Ne kadar da uyumluydu.

Güneşin teninde bıraktığı desen.

Ne umurundaydı dünya,

Ne de,

Çıplak ayaklarına batan onca diken.

Belki de mutluluğun,

Bir şeker parçasında olduğunu,

Bir tek oydu bilen.

                                                    17/01/2006', 'Çocuk, Güldü. Tozlu giysileriyle, Ne kadar da uyumluydu. Güneşin teninde bıraktığı desen. Ne umurundaydı dünya, Ne de, Çıplak ayaklarına bat...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ziya Pektaş']::text[], 8.5, '{"poet":"Ahmet Ziya Pektaş","poet_slug":"ahmet-ziya-pektas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/mutluluk-141-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlamadılar', 'anlamadilar-huseyin-sonmez-p5z9c', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yazı yazdım.

Yazdıklarımı anlamadılar.

Söz söyledim

Sözlerimi dinlemediler,

Konuşmadım sustum.

Oturup bekledim.

Anladım ki boşmuş

Hayattan beklediklerim..', 'Yazı yazdım. Yazdıklarımı anlamadılar. Söz söyledim Sözlerimi dinlemediler, Konuşmadım sustum. Oturup bekledim. Anladım ki boşmuş Hayattan b...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sönmez']::text[], 8.5, '{"poet":"Hüseyin Sönmez","poet_slug":"huseyin-sonmez","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/anlamadilar-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kesit', 'kesit-serap-tepedelen-46i8r', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Katırın üstünde bir çocuk,

Elinde yedi ekmek.

Sevdayı,

Bir somun gibi 

Paylaşmak gerek.

(1983,Bitlis)', 'Katırın üstünde bir çocuk, Elinde yedi ekmek. Sevdayı, Bir somun gibi  Paylaşmak gerek. (1983,Bitlis)...', ARRAY['Türk Edebiyatı','Şiir','Serap Tepedelen']::text[], 8.5, '{"poet":"Serap Tepedelen","poet_slug":"serap-tepedelen","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kesit-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceler', 'geceler-ahmet-ziya-pektas-91mlk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yine sabah oluyor.

Kuş cıvıltıları sardı odamı.

Güneşin ilk bakışları çarptı pencereme.

Eridi gecenin camdaki slüeti.

Geceyle başlayan dostluk,

Gündüze dönüşen kin vardı bende.

Başlarken odamın dışında hayat,

Geceyle buluşmaya varıyor gözlerim.

Sırf başlayan güne inat.', 'Yine sabah oluyor. Kuş cıvıltıları sardı odamı. Güneşin ilk bakışları çarptı pencereme. Eridi gecenin camdaki slüeti. Geceyle başlayan dostl...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ziya Pektaş']::text[], 8.5, '{"poet":"Ahmet Ziya Pektaş","poet_slug":"ahmet-ziya-pektas","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/geceler-154-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Merhaba Sebebim', 'merhaba-sebebim-reyhan-tataroglu-nj2gs', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sessizce,sensizce çöktüm yere

                           yaslandım duvara

                           yakmadım anam bir sigara

                           hani taa.. iç ceplerime kadar 

                           bakarda,dökülen tütünleri

                           gösterirdin avucunda

                           şimdi bulamazsın anam 

                           en ücra ucunda

                           tam on iki yıl oldu

                           yüreğim kaç kere boşaldı 

                           kaç kere doldu

                           sensizlikte...

                           biliyor musun anam 

                           hani

                           pantolonlarımıza,ceketlerimize

                           çoraplarımıza vurduğun yamalar

                           vardı ya...

                           giyerken çok utanırdım

                           ama 

                           ben seni yamalarından tanırdım

                           hele o naylon çorap atıklarından

                           ördüğün takkalar vede püskülü...

                           sen hala goncasın 

                           ey! gönlümün gülü  

        

                           her aynanın karşısına geçtiğimde

                           ''''efem'''' derdin

                           oysa  ben eşkiyadan beterdim

                           ne zaman yanlış bir iş yapsam

                           hemen sezerdin

                           adeta her an benle gezerdin

                           ana yüreği işte...

                           düşünüyorum da 

                           hiç hasta olmadığın bir günün geçmedi

                           sanırım rahatlık seni seçmedi

                           eee... kolay değil

                           beş erkek,üç kız

                           doğmadan ölenler 

                           sayılı sayısız

                           kaldıramadı seni bu hayat

                           kandıramadı seni heyhaat! 

                           ellerindeki yarıklar 

                           her gün kaşıntıdan kanardı

                           hangi merhemi kullandın ise

                           hepside derdine  yanardı

                           sırtına konulan beze sarılı

                           sıcak bir tuğla

                           kuluncuna bekçi

                           aldırmazdın 

                           ezan vakti kalkardın

                           tandıra yolcu

                           sac derdi''''hoşgeldin ekmekci''''

                           hani vardı ya

                           başında bürük

                           sırtında kahverengi atkı

                           bereketin sembolüydü adeta

                           berekete katkı

                           senden sonra

                           ne kimseler aldı 

                           ne de kimseler taktı

                           laf aramızda anam...

                           herkes giyinmeyi bıraktı

                           nefes alıp veremezken

                           bizi görüp göremezken

                           hatırlarım da 

                           canınla pazarlıktaydın

                           üç gün kaldı

                           çarşamba,perşembe,cuma

                           diye saydın

                           dönüpte baktın bana

                           bakmasaydın

                           niçin baktın ki ana

                           ''''sana da sana da bir şey yapamadım ''''

                           derken

                           dedim ''''gitme ne olur anam, daha çok erken''''

                           ve gidiverdin

                           perşembeden cumaya 

                           rahmet çökerken

                           senden sonra

                           çok avare gezdim

                           anlamsızdı sensiz herşey 

                           hayatımdan bezdim

                           tam sekiz yıl ayrı yaşadım 

                           kendi dünyamda

                           arasıra da olsa 

                           senle rüyamda...

                           seni unuttum sanma 

                           unutmadım...hatta

                           her gün kucağımdasın

                           baş ucumda

                           yatarken saçlarını okşuyorum

                           öpüyorum,dualar okuyorum

                           ismin dilimde,ellerin avucumda

                           sen bendesin,sen yavrucuğumda

                           seni seviyorum...', 'sessizce,sensizce çöktüm yere                            yaslandım duvara                            yakmadım anam bir sigara               ...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Tataroğlu']::text[], 8.5, '{"poet":"Reyhan Tataroğlu","poet_slug":"reyhan-tataroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":94,"source_url":"https://www.antoloji.com/merhaba-sebebim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğan Güneş', 'dogan-gunes-filiz-ocakoglu-wgf4p', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben nankör bir sevdanın

Uslanmaz bekçisiyim

Gururumdan eğilmese de başım

Yıllar boyu dört duvar arasında

Senin eserindir yalnız kalışım…

Sanmaki yoktu benim de

Kanatlarımda bahar rüzgarları 

Mis kokulu yediverenler

Bir kuşa bir kurda yem atar gibi

Savururken en masum duygularımı

Ben doruğundaydım baharlarımın…

Sen hiç yalnız kalmadın ki

Kırılmadı ki ben gibi kolun kanadın

Aslında ben sana hiç kıyamadım 

Sırf sen üzülme diye

Ben kör oldum çoğu zaman

Duymadım, dokunmadım sevinçlerine

Toyluğundan gelen heveslerine

Bazen bir bebek gibi sarmalarken

Bazen bir ana sabrıyla sustum

Ele düşmana karşı kan kusarken…

Vicdanının açtığı zalim yaralarını bile

Ben değil miydim iyi eden

Ruhumun acımasız isyanına inat

Sana senden daha çok anlayışlı şefkatimle…

Bu gün hiç yaşanmamış gibi

Hatırlamıyorsun değil mi

Zamanın verdiği fırsatla

Sana dünü bana bir ömrü

Kabus eden hikayemizi…

Şimdi istemiyorum artık bir şey

Nafile benim için tüm davetlerin

Sende kalsın bundan böyle

Bahar kokulu rüzgarlarım

Yedi veren güllerim…

İster kokla,  ister savur

İstersen at dört bir yana, bana ne

Ben yalnızlığımın 

Kırgın köşesinde

Yorgun ama başım yine dik

Elimde tüfengimle 

Son kez nöbetindeyim…', 'Ben nankör bir sevdanın Uslanmaz bekçisiyim Gururumdan eğilmese de başım Yıllar boyu dört duvar arasında Senin eserindir yalnız kalışım… San...', ARRAY['Türk Edebiyatı','Şiir','Filiz Ocakoğlu']::text[], 8.5, '{"poet":"Filiz Ocakoğlu","poet_slug":"filiz-ocakoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/dogan-gunes-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anılardan Kesinti', 'anilardan-kesinti-serap-tepedelen-n5g1n', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Nasıl unuturum çocukluğumu,

Babamın sımsıcak bakışlarını? 

O küçücük kâğıtlara sardığı

İkibuçuk liralık cep harçlıklarımızı.

Anılarımın en köşesinde kalmış

Dondurmacı Recep Amca''nın sesi

Uzatırdım da elli kuruşu

Tepeleme yığdırırdı külâhlara.

Ya o tenekeci nine? 

Her hafta sonu uğrardı mahalleye

O ne içten dualar,ne içten dilekler...

Bir beş kuruş,bir on kuruş

Ne istersen ver,

Gönlünden kopanı alırdı tenekeci nine.

Nasıl unuturum,

Bayram harçlığı on liramı

Tenekesine attığımı? 

Yoksa sömürülen duygularım mıydı? 

Bahçe Çıkmazı''na güneş doğduğunda

Soluğu alırdık sokaklarda

''Haydi uyanın tembeller! 

Bugün dokuz kiremit günüdür''

Bu,sabahın köründe bizi uyandıran,

Emine''nin sesidir.

Akşamın alacasında

Çocuk sesleri hâlâ çınlardı sokaklarda

Binbir güçlükle girerdik eve

Usumuzda oyunların tadı,

Yorgun bedenimizle

Gecenin karanlığında

Sokulurdık anamızın kucağına.

Şimdi, o bedenler ki,

Yaşam kavgasında değil mi? 

Sizleri hep anımsıyorum çocukluğum.

Sokağımın parke taşları,

Tatlı sohbetli kadınları,

Ahşap evler,sıcak dostluklar

Neredesiniz şimdi? 

(1985,Rize)', 'Nasıl unuturum çocukluğumu, Babamın sımsıcak bakışlarını?  O küçücük kâğıtlara sardığı İkibuçuk liralık cep harçlıklarımızı. Anılarımın en k...', ARRAY['Türk Edebiyatı','Şiir','Serap Tepedelen']::text[], 8.5, '{"poet":"Serap Tepedelen","poet_slug":"serap-tepedelen","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/anilardan-kesinti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul', 'i-stanbul-mevlude-demir-utqyg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dünya  sende  gördü,yeşilin, denizin  güzelliğini,

Sultanlara   ana  kucağı    oldun.

Neler   geldi, neler  geçti  başından,

Dimdik  ayakta    durdun.

Medeniyetlerin    düşleyipte, elde  edemediği,

Aşıkların, yiğitlerin   kalesi.

Bir   başkadır   istanbul.

Seninle    baş  başa   nefes  almak,

Sabahları  kuş   sesleriyle   uyanmak,

Hele  boğazda   seni    seyre     dalmak,

Özlenen    bir  sevda   masalısın.

Sensiz  olmaz  düşlerim,ülkemin   gözbebeği.

Dillerde  destan,  şarkılarda  sen varsın.

Son  sefer   vapurundan   birdaha   seyredeyim,

Belkide  görmem  seni,gemi  kalkar   bu  limandan.', 'Dünya  sende  gördü,yeşilin, denizin  güzelliğini, Sultanlara   ana  kucağı    oldun. Neler   geldi, neler  geçti  başından, Dimdik  ayakta ...', ARRAY['Türk Edebiyatı','Şiir','Mevlüde Demir']::text[], 8.5, '{"poet":"Mevlüde Demir","poet_slug":"mevlude-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/istanbul-419-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Amansız Bir Sayrılık da Olsa...', 'amansiz-bir-sayrilik-da-olsa-melih-coskun-ckj0w', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözlerine baktığım her kızda 

Seni arıyorum 

Elifi çalınmış bir alfabeyim,

Ne başlangıcım var

Ne de sonum, 

Yağmuru çalınmış bir bulutum 

İçime döküyorum gözyaşlarımı

Hangi hayatın bahçesine sığar ki 

Düşlerimde açan yarının kızıl gülü 

Söyle bana ey güzel

Hayatın bize biçtiğinden 

Daha fazlasını yaşamak hangimizin harcı 

Oysa ölüm dediğin iki türkülük yol olsa da

İnadına söylemek isterdim

Sınırlar içindeki sınırsızlığımdın sen benim

Tek bakışında saklıydı sanki kainatın bütün sırrı

Seni sevmek hem eksik kalmak 

Hem fazla olmaktı hayattan...   

Nereden bileceksin ey ırmak bakışlı kız

En güzel şiirlerin sensizliğe yazıldığını 

Acı çekmenin bağrında yakıldığını türkülerin

Diyeceğim şu ki 

Aşk amansız bir sayrılık da olsa

Ey sevgili

Ölümüm yalnızca onun elinden olsun isterdim...

2006

www.melihcoskun.com', 'Gözlerine baktığım her kızda  Seni arıyorum  Elifi çalınmış bir alfabeyim, Ne başlangıcım var Ne de sonum,  Yağmuru çalınmış bir bulutum  İç...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/amansiz-bir-sayrilik-da-olsa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiddet Denizi''nde', 'hiddet-denizi-nde-oktay-oksuzoglu-3mmso', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kıskançlık nöbetleri cinnete dönüşünce

olumsuzluk zırhına bürünür her düşünce

dünlerde filizlenmiş bütün güzelliklerin

tadına doyulmadan yaşanan o günlerin

esamesi okunmaz ki hiddet denizinde…', 'Kıskançlık nöbetleri cinnete dönüşünce olumsuzluk zırhına bürünür her düşünce dünlerde filizlenmiş bütün güzelliklerin tadına doyulmadan yaş...', ARRAY['Türk Edebiyatı','Şiir','Oktay Öksüzoğlu']::text[], 8.5, '{"poet":"Oktay Öksüzoğlu","poet_slug":"oktay-oksuzoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/hiddet-denizi-nde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hemşehrim', 'hemsehrim-guner-kaymak-5397j', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İki gözüm iki çeşme 

Kan ağlıyorum hemşehrim

Kurban olam yaram deşme

Kan ağlıyorum hemşehrim

Terk etti candan sevdiğim

Sırt çevirdi dost bildiğim

Olmadı hiç bir dileğim

Kan ağlıyorum hemşehrim

Dert sorun bitmiyor baştan

Yüreğim değilki taştan

Fayda yok kavim kardaştan

Kan ağlıyorum hemşehrim

Halimi gören acıyor

Yaram içerden kanıyor

Ozan Güner Kahr oluyor

Kan ağlıyorum hemşehrim

Ozan Güner Kaymak

Amsterdam 20.03.2006', 'İki gözüm iki çeşme  Kan ağlıyorum hemşehrim Kurban olam yaram deşme Kan ağlıyorum hemşehrim Terk etti candan sevdiğim Sırt çevirdi dost bil...', ARRAY['Türk Edebiyatı','Şiir','Güner Kaymak']::text[], 8.5, '{"poet":"Güner Kaymak","poet_slug":"guner-kaymak","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/hemsehrim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canlı kalkan osman', 'canli-kalkan-osman-abdulvahap-altay-6mig9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '**CANLI KALKAN OSMAN**

                istanbuldan gelip bağdat''a koşan,

                bombalar altında sipere yatan, 

                ıraklının acısını yüreğinde yaşayan,

                şebin kara hisarlı bir canlı kalkan.

                         çocuk katledilirken ben yatamam diyordu, 

                         o anı hatırlayıp gizliden ağlıyordu, 

                         her uçak geçişinde havaya fırlıyordu,

                         şimdi bomba yağacak insan ölecek diyordu.

                kitap yazmak için mardin''e gelmişti,

                yer olarak bir mağara seçmişti,

                her insan sevdiği kadar yaşar demişti,

               onun insan sevgisi beni etkilemişti. 

                         gazeteciydi o hemde çok yaman,

                         zalimin zülmüne vermedi aman,

                         selamettin, faruk, erdoğan,osman,

                         ırak işğal edilsede onlar kahraman,

                    

                                                                  a.vahap altay

            20-7-2003', '**CANLI KALKAN OSMAN**                 istanbuldan gelip bağdat''a koşan,                 bombalar altında sipere yatan,                  ıra...', ARRAY['Türk Edebiyatı','Şiir','Abdulvahap Altay']::text[], 8.5, '{"poet":"Abdulvahap Altay","poet_slug":"abdulvahap-altay","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/canli-kalkan-osman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağılan Bir Gün Ortası Vurgununda Son Sözler Düştü Camdan İçeri', 'dagilan-bir-gun-ortasi-vurgununda-son-sozler-dustu-camdan-i-ceri-atilla-guler-jw88u', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yaşama vurulan bir damganın dağılmış mürekkebine sürdüm yüzümü

...hüzün okşadı saçlarımı

/özgür

bir

büyücüyüm

ben/

...göz yaşlarımda saklarım sevgileri

ağlamam

zamanı yok sayıp vurdum yolları sırtıma

gümüş renkle bağlandı çizgileri yüzümün

her çizgide derin bir iz yaşam

nerede…deli gençliğim

sarhoş günlerin sığınağında unuttum gözlerimi

sözlerimden hiç haber yok

her sancının ardından doğan düşlerimi salıverdim göklere

toz pembeydi umutlarım

sabaha güneş çıkar

martılar! bana da uğrayın

kanadınıza değen bir damla denizin hasretinde yüreğim

en deli özlemlerin içinde hep aşk

gece örtse de güneşin yüzünü

uçabildiğince yükseklerde düşlerimin el sürülmemiş masumiyeti

bir ışık huzmesinde kaybolup güneşle sevişen bir rüzgar ötesinden ses verdi

…a ş k /bir güvercinin kanatlarında

uzan…tut ellerimden

kanıma vuran umarsız yalnızlığın son demlerinde savrulan bir damla

ö m r ü m

uzağımda

seyrediyor 

d ü ş l e r i m', 'yaşama vurulan bir damganın dağılmış mürekkebine sürdüm yüzümü ...hüzün okşadı saçlarımı /özgür bir büyücüyüm ben/ ...göz yaşlarımda sakları...', ARRAY['Türk Edebiyatı','Şiir','Atilla Güler']::text[], 8.5, '{"poet":"Atilla Güler","poet_slug":"atilla-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/dagilan-bir-gun-ortasi-vurgununda-son-sozler-dustu-camdan-iceri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine bahar gelecek', 'yine-bahar-gelecek-mustafa-sargin-3c2yo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen sevmesen yine severler

sen gitsen sevenim yine gelir

gülünecek varsa sana gülerler

boyun bükülecek varsa sana bükerler

bilirsin sende kalleşe nederler

sensizde geçer bağrımda seneler

bilki yine bahar gelecek

yanan kül iken suyu döktün

açan goncayken dalımı büktün

yolun sonuna varmışken döndün

nefret dolu kalbin var

sevginin zalimi olsan bile

bilki yine bahar gelecek', 'Sen sevmesen yine severler sen gitsen sevenim yine gelir gülünecek varsa sana gülerler boyun bükülecek varsa sana bükerler bilirsin sende ka...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Sargın']::text[], 8.5, '{"poet":"Mustafa Sargın","poet_slug":"mustafa-sargin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yine-bahar-gelecek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üşüyorum', 'usuyorum-nur-demirciler-0ydu6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'üşüyorum,

yokluğunun ayazında, 

yine yalnızım,

incinen gururumla...

bir tebessüme yükleyip,

atarım sandım derdi kederi,

dünyayı aldatsa da insan,

kandıramaz  kendini...

Ne bir başka sevda aldı yerini,

ne de tutan var üşüyen ellerimi,

unutmak istiyorum, sadece unutmak,

kaçamak gözlerle bakıp gözlerime,

o kızıl akşamdaki gidişi,

ve eğilmez, bükülmez sandığım,

kırılan gururumu,

unutmak istiyorum,

solgun gelincikler gibi,

yerle bir serilişi,

yalnız geçen günleri, geceleri.

ve ısıtabilmek içimi...

20/03/2006

İstanbul', 'üşüyorum, yokluğunun ayazında,  yine yalnızım, incinen gururumla... bir tebessüme yükleyip, atarım sandım derdi kederi, dünyayı aldatsa da i...', ARRAY['Türk Edebiyatı','Şiir','Nur Demirciler']::text[], 8.5, '{"poet":"Nur Demirciler","poet_slug":"nur-demirciler","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/usuyorum-87-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güllerin Bedduası Var', 'gullerin-bedduasi-var-celal-unal-b6wzm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Döktün yaprağımı kırdın dalımı

Viran ettin  benim duygu bağımı

Dalların sana bedduası var,

Açmadan soldu sümbülüm,lalem 

Gözlerimden eksilmez oldu 

Bir gün olsun nem,

Güllerin sana bedduası var

Ta uzaklardan koşup gelmiştim sana

Sevdan yüreğim de kor, yana,yana,

Yolların sana bedduası var.', 'Döktün yaprağımı kırdın dalımı Viran ettin  benim duygu bağımı Dalların sana bedduası var, Açmadan soldu sümbülüm,lalem  Gözlerimden eksilme...', ARRAY['Türk Edebiyatı','Şiir','Celal Ünal']::text[], 8.5, '{"poet":"Celal Ünal","poet_slug":"celal-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gullerin-bedduasi-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yar gidiyor', 'yar-gidiyor-sevinc-atan-spofn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Cân-evimden can gidiyor,

Hem şafak, hem tan gidiyor.

Kal dediğim an gidiyor,

Gitme dedim yar gidiyor.

Bakmıyor hiç benden yana.

Saramadım kana kana.

Benzeri gelmez cihana,

Gitme dedim yar gidiyor.

Bahçesine umut ektim.

Yollarına setler çektim.

Canımdan can verecektim.

Gitme dedim yar gidiyor.

Tutamadı ellerimi.

Deremedi güllerimi.

Dindirmedi selledrimi,

Gitme dedim yar gidiyor.

Cismidir giden sonunda.

Yer ayırdım tam yanında,

meleklerin kucağında,

Gitme dedim yar gidiyor...

8/2/2006-Ankara

-Sn.Yaşar Günaydın''a- ithafdır.', 'Cân-evimden can gidiyor, Hem şafak, hem tan gidiyor. Kal dediğim an gidiyor, Gitme dedim yar gidiyor. Bakmıyor hiç benden yana. Saramadım ka...', ARRAY['Türk Edebiyatı','Şiir','Sevinç Atan']::text[], 8.5, '{"poet":"Sevinç Atan","poet_slug":"sevinc-atan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yar-gidiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Prematüre Aşk', 'premature-ask-melik-cagri-kucukyildiz-wpon4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kadın bilmiyor neler olduğunu,

karnındaki şişlik hızla büyüyor.

Neden.

Kusuyor olabildiğince de,

şişlik bir türlü çıkmıyor dışarı.

…

Kadın şaşkın,6.günde.

Bu kadar kısa sürede

nasıl ve neden.

Midesi bulanıyor da,

akl(ı) lık ve hoşlanıyor bundan.

Kadın bitkin, bir hafta geride.

Aynaya bakıyor.

 Issız kahverengi adalarda,

iki beyaz okyanusun ortasında,

Ken(di) kenli kumsalında görüyor eşkiyayı.

Kadın sancılı, daha 8.gününde.

Erken doğum olacak galiba,

şişlik bir şişe kırmızı şarap,akıyor. 

Yaşar mı, yaşa(t) maz mı…

Keş(ke) fin olmasa bebeğine. 

Adam gamlı, doğum gününde.

Bir gün daha bekleyemedi.

Doktor dedi:

Prematüre bir aşkınız oldu, öldü.

nEe..? 

Kadın uyandı.

Yüreği yanmadı. 

Dedi:

Hazır değil(im) dim zaten.

(21\03\3006

Karacabey)', 'Kadın bilmiyor neler olduğunu, karnındaki şişlik hızla büyüyor. Neden. Kusuyor olabildiğince de, şişlik bir türlü çıkmıyor dışarı. … Kadın ş...', ARRAY['Türk Edebiyatı','Şiir','Melik Çağrı Küçükyıldız']::text[], 8.5, '{"poet":"Melik Çağrı Küçükyıldız","poet_slug":"melik-cagri-kucukyildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/premature-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '1 Hayat', '1-hayat-arzu-bagriacik-0v2qu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Renkler görebildiğince değil, 

Gönül gözüne görünen renklerdeyse; 

İç pencereni açtığında ışığa koşarak,çoşarak 

Aktıysan maskelilere inat,

Kır bahçesini lüneparka çevirip renklendirmişsindir 

Eh bir de hayata inat........

20.03.2006 Ankara', 'Renkler görebildiğince değil,  Gönül gözüne görünen renklerdeyse;  İç pencereni açtığında ışığa koşarak,çoşarak  Aktıysan maskelilere inat, ...', ARRAY['Türk Edebiyatı','Şiir','Arzu Bağrıaçık']::text[], 8.5, '{"poet":"Arzu Bağrıaçık","poet_slug":"arzu-bagriacik","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/1-hayat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendi zindanımı yaratmışım seninle…', 'kendi-zindanimi-yaratmisim-seninle-nur-demirciler-o14vg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kendi zindanımı yaratmışım seninle…

Seninle daldım uykulara,

Ya yanımdaydın, farzettim…

Ya da rüyama girmeni bekledim.

Geceler hasretleri ezer geçerdi belki böylece…

Kimi zaman,

Kendi kendimle konuştum,

Dinleyen sen varsın,  farzettim

Seninle uyandım her yeni güne.

İşe beni sen bırakırdın, farzettim…

Tüm gün çalan her telefona

sensin sanıp, sarıldım...

iş çıkışı, beni alan hiç olmadı,

ama ben hep bekledim...

işin çıktı diye, farzettim…

yalan söyledim seni merak edenlere,

olsun ne kaldı ki geceye? 

Çok geç fark ettim…

Kendi zindanımı yaratmışım seninle…

Hapsettim bir ömrü boş yere...

22/03/2006

istanbul', 'Kendi zindanımı yaratmışım seninle… Seninle daldım uykulara, Ya yanımdaydın, farzettim… Ya da rüyama girmeni bekledim. Geceler hasretleri ez...', ARRAY['Türk Edebiyatı','Şiir','Nur Demirciler']::text[], 8.5, '{"poet":"Nur Demirciler","poet_slug":"nur-demirciler","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kendi-zindanimi-yaratmisim-seninle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkusuzca Yaşamak', 'korkusuzca-yasamak-serap-tepedelen-fnwzn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne yollardan geçtik biz

Aşılmaz denen dağları aştık

Kimi an geldi,kanattık tırnaklarımızı

Kimi an,delicesine haykırdık.

Bir yürek yarattık yüreğimizin içinde

Yüreklice,korkusuzca yaşadık.

(1994,Bursa)', 'Ne yollardan geçtik biz Aşılmaz denen dağları aştık Kimi an geldi,kanattık tırnaklarımızı Kimi an,delicesine haykırdık. Bir yürek yarattık y...', ARRAY['Türk Edebiyatı','Şiir','Serap Tepedelen']::text[], 8.5, '{"poet":"Serap Tepedelen","poet_slug":"serap-tepedelen","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/korkusuzca-yasamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çıkış', 'cikis-abdulvahap-ates-lc4a1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yarabbim öyle bir durumdayım ki,

Kimseye derdimi açamıyorum.

Günümü,gecemi kaplar bendeki,

İlençten bir türlü kaçamıyorum.

Olmazlar ısırır hayallerimi,

Dua dua uyuşmuş ellerimi,

Masamı donatıp emellerimi,

Bir kadehe koyup içemiyorum.

Geceleri gündüzleyen dertlerim,

Bahtsızlığa buğzeden lanetlerim,

Sen fikirli,ruhsuz ibadetlerim,

Rabbime içimi dökemiyorum.

Her akşam elveda diye bir mektup,

Kararım bir artı,bir eksi kutup,

Atiyi doğru bir yere oturtup,

Yeni bir oluşum biçemiyorum.

Eşyam bavulumda tünedi hicret,

Pranga ayakta çözülmez illet,

Ya tasayı öldür,ya aklı kirlet,

Ne keskin sırattır geçemiyorum.

Çıkmak  istiyorum havsalalardan,

Hayatı süsleyen safsatalardan,

Sonsuza pencere uçurumlardan,

Uçmak istesem de uçamıyorum.

Saplanır gözlerim kör noktalara,

Çareler dayanır hep olmazlara,

“Bir çıksam” diyorum şu omuzlara,

Ardımdan ne derler seçemiyorum.', 'Yarabbim öyle bir durumdayım ki, Kimseye derdimi açamıyorum. Günümü,gecemi kaplar bendeki, İlençten bir türlü kaçamıyorum. Olmazlar ısırır h...', ARRAY['Türk Edebiyatı','Şiir','Abdulvahap Ateş']::text[], 8.5, '{"poet":"Abdulvahap Ateş","poet_slug":"abdulvahap-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/cikis-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sesini duymak çok güzeldi', 'sesini-duymak-cok-guzeldi-durdu-mehmet-dalkanat-r1g3r', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sesini duymak çok güzeldi…

Yanaklarımı okşuyordu sanki,

Ipılıktı nefesin…

Sevgiyle dolu bir yaşam fısıldıyordu …

Kelimelerle çizdiğim solgun ve belirsiz siluetin,

Gerçekten sesini duymak çok güzeldi ama…

Hele o artistik evetlerin yok mu..

Hala yankılanıyor kulaklarımda…

Issız ve görkemli bir vadide,

İki elim ağzımda…

Sevdaaaaa diye avazım çıktığı kadar bağırdığımda…

Geriye bana dönen binlerce sevda gibi..

Hala çınlıyor işte kulaklarımda…

Kelimelerle sevişmek…

Kardan  adam yapmak gibi bir şey…

Soğuk ve karlı bir kış gününde…

Kardan adam yapmanın,

Sıcaklığı ne kadarsa,

İşte o kadar sıcak…

Ben burnuna bir havuç yerleştireyim derken…

Sen gözlerine siyah bir kömür gömmeye çalışırken…

Bakıyorsun gün akşam oluyor…

Onu ortada bırakıp gidiyoruz. Öylece…

Sabaha ya kalıyor ya kalmıyor…

Bazan da hiç başlayamıyoruz…

Ya aşırı sıcaktan…

Ya aşırı soğuktan...

Biliyormusun...

Sesini duymak çok güzeldi ama…

Gerçekten…', 'Sesini duymak çok güzeldi… Yanaklarımı okşuyordu sanki, Ipılıktı nefesin… Sevgiyle dolu bir yaşam fısıldıyordu … Kelimelerle çizdiğim solgun...', ARRAY['Türk Edebiyatı','Şiir','Durdu Mehmet Dalkanat']::text[], 8.5, '{"poet":"Durdu Mehmet Dalkanat","poet_slug":"durdu-mehmet-dalkanat","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/sesini-duymak-cok-guzeldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurtuldum!', 'kurtuldum-burhanettin-akdag-fvdz8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözümü açtım dünyaya, kendim istemezken 

Ağladım başlarda, bir şeyden anlamazken 

Sorguladım bakındım alemin içre dikkatle

Tüm güzelliğiyle, zirvesini doyumsuzluğun

___Seyreyledim, gördüm! 

Birazcık büyüdüm, istemesem de bedenen

Serpildi aklım, durduramasam da hızını

Algıladım mekanda, canlıyı cansızlardan 

Yakaladım farkımı, hem de ayrıcalığımı 

___Hissettim, yaşadım! 

Uzattım kulağımı iyice, işin aslın bilene 

Sordum büyüklere, yol ve yordamını gidişin

Danıştım, görüştüm, hep istişare ettim 

İzledim çok dikkatlice, nicedir doğrular 

___Düşündüm, anladım! 

Koydular önüme, yıktılar yaldızlı ciltleri 

Döktüler beynime, yüz binlerce sayfaları 

Adetlerce kitapları, yazılanları her telden 

Düşündüm, araştırdım, sorguladım inceden

___Okudum, öğrendim! 

Biraz daha daldım derinliklerine hayatın

Birazcık da, farklı düşündüm yaşananları 

Tefekkür eyledim, fikrimle zikir eyledim 

Ağladım, iki büklüm oldum geceler boyunca 

___Araştırdım, buldum! 

Şaşırdım yollarımı, çoğunluk hallerimle 

Kaybettim yönümü, hem sağımı hem solumu 

Doğru yoldan saparak, tosladım duvarlara 

Düştüm kapkaranlık dehlizlere, devrildim 

___Sarardım, soldum! 

İnatsa inat, durmadan devam ettim inadıma 

Dönmedim geriye yanlışlarımdan, yanıldım 

Öyle bir çarpıldım ki, o çok bilmişliğimle 

Battıkça battım, boğuldum, daraldım nefessiz 

___Doğrandım, paralandım! 

Neler çektim dost bildiğim ellerin elinden 

Yıkıldım, çok düştüm gafletin çukurlarına 

Süründüm yerlerde, ağır ödedim akılsızlığımı 

Tükendim sessizliğinde gecelerin, karardım. 

___Çaresiz kaldım, yandım! 

Aradım nedenlerini, nasıl ve niçin’lerimin 

Düşümdüm, soruşturdum aslını fani hayatın 

Kaldırdım kalp gözümü gökyüzüne, inceledim 

Buldum sırrı bütün yıldızlarda, nakış nakış 

___Ölçüp biçtim, tarttım! 

Uzattım yüreğimi, tutundum sıkıca MEŞALE’ye 

Hakikatin sırları, indi birer birer gönlüme 

Aydınlandı ilminin ışığıyla, bütün yollarım 

Açıldı tüm kapılar ardına kadar, âlem-i manâda 

___Sığındım kudrete, kurtuldum! 

(20.02.2006)', 'Gözümü açtım dünyaya, kendim istemezken  Ağladım başlarda, bir şeyden anlamazken  Sorguladım bakındım alemin içre dikkatle Tüm güzelliğiyle,...', ARRAY['Türk Edebiyatı','Şiir','Burhanettin Akdağ']::text[], 8.5, '{"poet":"Burhanettin Akdağ","poet_slug":"burhanettin-akdag","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/kurtuldum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Kaç Kadınsın', 'sen-kac-kadinsin-huseyin-yuk-0r6wo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen kaç kadınsın

ya  da  kaç  kadın senin yerini doldurabilir.

Sen niye  bu kadar çoksun

Kimse çokluğuna sığmıyor sığamiyor.

Sadece seni  sevmek kaç kadını sevmeye eş değer biliyormusun..

alana  eirene için yazdım', 'Sen kaç kadınsın ya  da  kaç  kadın senin yerini doldurabilir. Sen niye  bu kadar çoksun Kimse çokluğuna sığmıyor sığamiyor. Sadece seni  se...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Yük']::text[], 8.5, '{"poet":"Hüseyin Yük","poet_slug":"huseyin-yuk","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sen-kac-kadinsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldızlara Koşmak', 'yildizlara-kosmak-orhan-eren-uncu-j3udm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir gün bir çiçek açacak

Yorulmuş yüreğinde

Bir güvercin

Sevgiden yoksun durmuş beklerken

Cam kenarında

Yıldızlara koşmak isteyeceksin

Zaman olacak

Bir beyaz güverin, camın kenarına konacak

Güneşten korkmadan,

Sudan kaçmadan

Al mendil düştü

Yorulmuş yüreğinden

Bir beyaz güvercin cam kenarına konacak

Kanadın da saklı yürek sıkmaları

Al kurdeleyle süslü

Bir güvercin konacak cam kenarına

Edası, taklalarında gizli

Saf ve duru, az hırçın

Alıp gidecek seni

Ve sen

Yıldızlara uçmak isteyeceksin

Hoplayıp yıldızları tutmak

Sende, sende ışık olup gideceksin

Yüreğinde bir çiçek açacak

Ve sen bir yıldız olacaksın

21.03.2006

01.53', 'Bir gün bir çiçek açacak Yorulmuş yüreğinde Bir güvercin Sevgiden yoksun durmuş beklerken Cam kenarında Yıldızlara koşmak isteyeceksin Zaman...', ARRAY['Türk Edebiyatı','Şiir','Orhan Eren Uncu']::text[], 8.5, '{"poet":"Orhan Eren Uncu","poet_slug":"orhan-eren-uncu","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/yildizlara-kosmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaybolsam', 'kaybolsam-hatice-guler-5prt4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kara bulutlarin ağırlığınca

Yağsam,sel olup aksam

Karışsam rahmet deryasına

Görmesem,duymasam

Bilmesem,hissetmesem

Duygulu satırları yazmasam

Baharım olamayan yarin

Bir başkasına akışını

Bir daha bir daha yaşamasam

Hasret deryasında

Bir damla gözyaşımda

Sensizliğime

Umutlarıma

Sevdama

Sarılıp kaybolsam..', 'Kara bulutlarin ağırlığınca Yağsam,sel olup aksam Karışsam rahmet deryasına Görmesem,duymasam Bilmesem,hissetmesem Duygulu satırları yazmasa...', ARRAY['Türk Edebiyatı','Şiir','Hatice Güler']::text[], 8.5, '{"poet":"Hatice Güler","poet_slug":"hatice-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kaybolsam-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vefasız Sevgili', 'vefasiz-sevgili-i-lhan-altin-4mksl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen, bir yürek boyu benden uzak sevdam

Tutamadığım zamanlarda tek hecem, sevgilim

Vedasız ayrılıklarla ağır yaralı yüreğimde

Kan kırmızı duvarlarımı süsleyen

                                                   Vefasız sevgilim...

Son damlası akmışken gözpınarlarımın,

Yüreğimin sahipsiz sokakları yağmura doymuşken,

Adımlarımda kaybolan umutlarımın sebebi...

Bir avuç sensizlik kala son nefese,

Yürüyorum, bir yürek boyu uzanan cançekişlerimden,

Vedasız terkedilmiş  zamanlara, sensizliğime...

Her daim derinlere düşen, çırpındıkça bölünen,

Sevdalı yüreğime biriken birikintilerinle,

Sensizlik vurmuş kıyılarına hüzün denizlerimin,

Yoksulluğumun kırıntılarından aldığım son nefeslerimde

Tek hece sevdalıyım ben yine güzelliğine...', 'Sen, bir yürek boyu benden uzak sevdam Tutamadığım zamanlarda tek hecem, sevgilim Vedasız ayrılıklarla ağır yaralı yüreğimde Kan kırmızı duv...', ARRAY['Türk Edebiyatı','Şiir','İlhan Altın']::text[], 8.5, '{"poet":"İlhan Altın","poet_slug":"i-lhan-altin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/vefasiz-sevgili-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmurum', 'yagmurum-nazli-duman-kd57k', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'rüyamısın, hayalmi,yoksa sadece masalmı

dinleyip,dinleyip bıkmadığım

geceler sesini bazen getirir bana

duyarım derinlerden buğulu titrek narin sesini

gözlerin.. gözlerin hiç gelmedi buralara

takılmış kalmış tek bir noktaya

gözlerin,gözlerin takılmış ellerine

ne yazıyor ellerin sevdiceğine

bazen takılır gözlerin saatlerce ellerine

parmaklarına 

içine tarih kazınmış,ismi yazılmış,seni ona bağlamış

sanmaki sadece bir halkaymış onun adı aşkı sana yasaklamış.', 'rüyamısın, hayalmi,yoksa sadece masalmı dinleyip,dinleyip bıkmadığım geceler sesini bazen getirir bana duyarım derinlerden buğulu titrek nar...', ARRAY['Türk Edebiyatı','Şiir','Nazlı Duman']::text[], 8.5, '{"poet":"Nazlı Duman","poet_slug":"nazli-duman","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yagmurum-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Turkuaz dinletileri 3', 'turkuaz-dinletileri-3-i-brahim-kilinc-90wgi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dostum Turan vurdu sazın teline,

Şahlandı Turkuaz dinletileri.

Keder gitti, neşe geldi yerine,

Şahlandı Turkuaz dinletileri.

Güzel şiirlerle can kattı cana,

Kırk yıllık birikim çıktı meydana,

Herkes hayran kaldı dostum Ceylan''a,

Şahlandı Turkuaz dinletileri.

Cemal Safi ile coştu gönüller,

Unutulmaz anı o mavi güller,

Sevdaya uzandı şiirle yollar,

Şahlandı Turkuaz dinletileri.

Kağıdı kalemi kaldırmış rafa,

Komediye döner dilinde cefa,

Taşlamayla dizdi bizleri safa,

Şahlandı Turkuaz dinletileri.

Dostum Ayşegül''e Çetin Hocama,

Yeğenim Gökçe''ye, Zuhal bacıma,

İlgisiz kaldım da gitti gücüme

Şahlandı Turkuaz dinletileri.

Sanat için çaba özünde vardı,

Kahkaha da vardı, hüzün de vardı,

Gayret Mustafa''nın gözünde vardı,

Şahlandı Turkuaz dinletileri.

Rağbet olmasa da imza gününe,

Turkuaz''ın gölge düşmez ününe,

Asınca bayrağı sahne fonuna,

Şahlandı Turkuaz dinletileri.

Can dostlarım Zerrin, Ali ve Tülin,

Her zamankinden de gayretli bugün,

Bir iki siteme olsak ta üzgün,

Şahlandı Turkuaz dinletileri.

Refik kardeşimin emeği de var,

Asena''dan geldi bugün şarkılar,

Sibel''den bir türkü dinlemek te kâr,

Şahlandı Turkuaz dinletileri.

Gurbet Meleği ve eşi de geldi,

Bize yol gösteren şefkatli eldi,

Rahatsızlık duyan tek Aysel Al''dı,

Şahlandı Turkuaz dinletileri.

Bağlama Cengiz''den çekim Özgür''den,

Satışlar Merih''ten kaset Güngör''den,

Mısralar gönlümden döküldü birden,

Şahlandı Turkuaz dinletileri.', 'Dostum Turan vurdu sazın teline, Şahlandı Turkuaz dinletileri. Keder gitti, neşe geldi yerine, Şahlandı Turkuaz dinletileri. Güzel şiirlerle...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Kılınç']::text[], 8.5, '{"poet":"İbrahim Kılınç","poet_slug":"i-brahim-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/turkuaz-dinletileri-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özledim Seni', 'ozledim-seni-sevinc-kavuk-9sx0d', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Özledim seni desem ne fayda

Biliyorum gönlümü:

Kalbin çok güzel sevgilim

Beni düşün ve kalbini dinle

İkimizden 

Şarkılar söyleyecektir sana…

Ben de

Özledim seni

Boynunu öpmek avuçlarımda 

Hapsetmek istiyorum

Sıcaklığını göğüslerinin… 

Seni düşünüyor

Hep en güzel şarkıyı

Seçerek mırıldanıyorum 

Güzelleşiyor

Ve daha duygulu

Deniz dalgaları eşliğinde…

Diyerek okşayacağını

Öyle de seviyorum seni...

Mart  2006', 'Özledim seni desem ne fayda Biliyorum gönlümü: Kalbin çok güzel sevgilim Beni düşün ve kalbini dinle İkimizden  Şarkılar söyleyecektir sana…...', ARRAY['Türk Edebiyatı','Şiir','Sevinç Kavuk']::text[], 8.5, '{"poet":"Sevinç Kavuk","poet_slug":"sevinc-kavuk","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ozledim-seni-46-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostlar..(Şarkı sözü)', 'dostlar-sarki-sozu-cengiz-suslu-o03ht', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Benim ağlamaya hiç mecalim yok

N’olur biraz rahat bırakın dostlar

Artık..teselliye bilin karnım tok

Beni biraz benle bırakın dostlar

Bir hayırsız yare,gönül verirken

Ömrümden an-be-an yıl silinirken

Yoktunuz bir ölüp bir dirilirken

Beni bana düşman etmeyin dostlar

Umut deryasında bir aptal aşık

Yüreği çarmıhta aklı karışık

Aşıkken hayatla varmı barışık

Bana düşman gibi bakmayın dostlar

Cengiz Süslü     1998', 'Benim ağlamaya hiç mecalim yok N’olur biraz rahat bırakın dostlar Artık..teselliye bilin karnım tok Beni biraz benle bırakın dostlar Bir hay...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Süslü']::text[], 8.5, '{"poet":"Cengiz Süslü","poet_slug":"cengiz-suslu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/dostlar-sarki-sozu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Üstad', 'i-ki-ustad-i-brahim-kilinc-1xjam', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ufku aydınlatan nurlar solmaya,

Safi''den, Ceylan''dan ilham almaya,

Niyetlendim ben de çırak olmaya,

İki üstad bugün burda buluştu.

Onlarla yaşıyor veznimiz hece,

Örnek oluyorlar binlerce gence,

Ne zor oldu sabah bilsen dün gece,

İki üstad bugün burda buluştu.

Zor iki ustanın yanında durmak,

Bir yanlış yapmadan doğru söz bulmak,

Bize kısmet oldu plaket vermek,

İki üstad bugün burda buluştu.', 'Ufku aydınlatan nurlar solmaya, Safi''den, Ceylan''dan ilham almaya, Niyetlendim ben de çırak olmaya, İki üstad bugün burda buluştu. Onlarla y...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Kılınç']::text[], 8.5, '{"poet":"İbrahim Kılınç","poet_slug":"i-brahim-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/iki-ustad-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mor geceler (Şarkı sözü)', 'mor-geceler-sarki-sozu-cengiz-suslu-6dmcc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir başka gecenin koynunda beni

Bulursan sevgilim,sakın şaşırma

Mateme bürünmüş bu bedenimi

Görmeden geçip git boşver,aldırma

Bir nefeslik..canım kaldı dilimde

Bir ALLAH’ı birde seni heceler

Günah olmasaydı ölüm dinimde

Çoktan vuracaktı bu mor geceler

Mor geceler…,şu mor geceler

Cana susamışlar,katil geceler

Mor geceler,,,bu kor geceler

Cenneti vadeder şu mor geceler

Bir yıldız sevgilim oldu her gece

Okşadı tenimi sevdi kendince

Dediki; süzül gel bana sessizce

Sevdandan yanacak bu mor geceler

2005

Cengiz Süslü', 'Bir başka gecenin koynunda beni Bulursan sevgilim,sakın şaşırma Mateme bürünmüş bu bedenimi Görmeden geçip git boşver,aldırma Bir nefeslik.....', ARRAY['Türk Edebiyatı','Şiir','Cengiz Süslü']::text[], 8.5, '{"poet":"Cengiz Süslü","poet_slug":"cengiz-suslu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/mor-geceler-sarki-sozu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir ve Newroz', 'siir-ve-newroz-vedat-koparan-okm86', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hazan düşer ağaç keser buz keser 

Gözyaşım öbek öbek geceye düşer

Gülüşünle gözyaşım sevince döner 

Bir ben üşür gece sensizliği böler

Gün şiir, yanan newroz ateşi günüdür 

Dallarımızda inci yaprağımız titrer

Hey eğ başını zaman tüneli 

Bak yanıyor Nevroz ateşim

Mart gelendir kapıyı delen 

Ne gürzdür ne alaz yalayan rüzgâr

Çağrısı candan kardeşliği 

Acısı tarihin derin denizlerin

Bu kış üşümesinde iki ateş düşer 

Yaşam alanına newroz ve şiir 

Bahara sancılı andır doğuma az kala 

Etekleri uçuşan mevsimin

“………….Şiir

Ne  gönül eğlencesi

Ne de

……Birinin gülmecesi

Şiir yumruk, şiir balyoz

Şiir Zülfikar 

Mazlumun boynunu törpüleyenlere karşı

Şiir Pir sultan Boynuna ilmeği kendi takan” (İlhami Arslantaş)

—Ver Alnını Al Anlımı Şaşa Kalma Artık-(Yaşar Doğan)

21 Mart Özgürlük Aydınlık Ateşi Ve Şiir Günümüz Kutlu Olsun

Bitmedi…Vedat Koparan 21.03.2006', 'Hazan düşer ağaç keser buz keser  Gözyaşım öbek öbek geceye düşer Gülüşünle gözyaşım sevince döner  Bir ben üşür gece sensizliği böler Gün ş...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/siir-ve-newroz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
