INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nazarlık', 'nazarlik-serpil-balcik-ygx9p', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'nazarlık onun gözleriydi

ona nazar deymezdi

o huzur vaadinde bakışı

davetkar dalgalanışı

kem gözlere meze değildi

ölümün gözleri maviydi.

MART 2002', 'nazarlık onun gözleriydi ona nazar deymezdi o huzur vaadinde bakışı davetkar dalgalanışı kem gözlere meze değildi ölümün gözleri maviydi. MA...', ARRAY['Türk Edebiyatı','Şiir','Serpil Balçık']::text[], 8.5, '{"poet":"Serpil Balçık","poet_slug":"serpil-balcik","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/nazarlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok Seviyorum Ben', 'cok-seviyorum-ben-sevinc-kavuk-qmedc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '““Akıl

 Akıl akıl olsaydı adı gönül olurdu

Gönül gönlü bulsaydı bozkırlar gül olurdu.

Necip Fazıl Kısakürek““  (Ruhunuz şâd olsun büyük Üstad)         

Akıl, gönül gözüne inebilmeyi şaşıdı

Gözler, bakarken takılmaya çakıldı

Yürek, coşkuda çarparken fırdöndü oldu

Gönül, gönlü bulmaya artık tansığa d/adandı

Ad mahzun, yetim acılı, fakirlik mekanı sanki

Gülün adı gönül, gönlün diye konuşuluyor daha

Hem o koşu bu kuşu ve bir de dile getiriş var ama

Sorunlara ad vermeyi bile şaşıdık sorma…

Yeterlik ayıbına gibi bozkır örnek sunulmuş 

Uyanışa Allah ihtarı olduğu gariptir, yetmemiş

İnsanlığa bir insan daha katılır ümidine işte

Ezelden beri söylenilen güzelliğe o güzelliğinde

Sunduğun bu enfes sanat, bu enfes Usta emeğin

Şiir de sanat, şiir de Allah bulabilen Üstad ile

Kabirde cennet saltanatına bina olur inşallah 

Hep dünyamızı kusursuzca çok seviyorum ben…

Mart  2006 

(sanat, bunu etigi içine sığdırır mı bilmiyorum, ama ben duygumu onlara nasıl ileteceğimi bilmiyorum, onlarla hâlâ yaşadığımızı...tarih sayfaları da yazılıyor işte, öyle bir tür gibi içimde yaşatmak, belki duyar yardım kanatlarını vatanıma, dünya aşkına açarlar...ümidim diye... hep ve her geçmişi dünleri ile bugüne şimdisiyle bir varlığın yarına kalabilecek halini düşünüyorum...)', '““Akıl  Akıl akıl olsaydı adı gönül olurdu Gönül gönlü bulsaydı bozkırlar gül olurdu. Necip Fazıl Kısakürek““  (Ruhunuz şâd olsun büyük Üsta...', ARRAY['Türk Edebiyatı','Şiir','Sevinç Kavuk']::text[], 8.5, '{"poet":"Sevinç Kavuk","poet_slug":"sevinc-kavuk","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/cok-seviyorum-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sesimdeki sen', 'sesimdeki-sen-omer-kekec-1fbnh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yanlızlığımda birsen varsın birde sensizliğim.

Birgün gelipde gördüğünde beni,

anlayacaksın seni ne çok sevdiğimi.

Geçmişdeğil, bugün bile dünde,bütün ömrümde.

Her''an seni yaşıyorum, her''anımın içinde.

Hiç gitmemiş gibi.

Birgün gelipde gördüğünde beni.

Göreceksin yanlızlığımda kendini ve yanlızlığımla beni.

Söylemek istersen duymak istediğimi.

Yada duymak istersen söyleyeceklerimi.

Öyleyse dinle beni. ve sesimdeki seni.



  (17-4-1999  İsviçre)', 'Yanlızlığımda birsen varsın birde sensizliğim. Birgün gelipde gördüğünde beni, anlayacaksın seni ne çok sevdiğimi. Geçmişdeğil, bugün bile d...', ARRAY['Türk Edebiyatı','Şiir','Ömer Kekeç']::text[], 8.5, '{"poet":"Ömer Kekeç","poet_slug":"omer-kekec","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sesimdeki-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaçak', 'kacak-cengiz-suslu-dcg6v', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nereye kaçtıysam düştü peşime

Bir türlü bıkmadı,yılmadı sevdan

Bazen türkü olup düştü sesime

Adını dilimden silmedi sevdan

Neyleyim bir kere sevmişim seni

Siyah-beyaz olmuş hayatın rengi

Ben kölen olmuşum sende efendi

Usanıp özgürlük vermedi sevdan

Her gece gözyaşı yaktı koynumu

Hasretin sokulup sardı boynumu

Daha ne diyeyim anla durumu

Bir kere yüzüme gülmedi sevdan

Cengiz Süslü         1996', 'Nereye kaçtıysam düştü peşime Bir türlü bıkmadı,yılmadı sevdan Bazen türkü olup düştü sesime Adını dilimden silmedi sevdan Neyleyim bir kere...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Süslü']::text[], 8.5, '{"poet":"Cengiz Süslü","poet_slug":"cengiz-suslu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kacak-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç Sırası Değil', 'hic-sirasi-degil-muammer-erturan-x1ho2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Nerede bulmalı da seni...

Nerede bulmalı da...

Nerede...

Ne yapmalı da sana...

Ne yapmalı da...

Ne...

İş mi bu seninki...

İş mi bu...

İş mi...

Hiç sırası değil sensizliğin...

Hiç değil...

Hiç...

(24 Haziran ''95)', 'Nerede bulmalı da seni... Nerede bulmalı da... Nerede... Ne yapmalı da sana... Ne yapmalı da... Ne... İş mi bu seninki... İş mi bu... İş mi....', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hic-sirasi-degil-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostca..', 'dostca-cengiz-suslu-r15xe', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İki dostuz bir şişede

İçip sarhoş olacağız.

Efkarları birer, birer

Döküp berduş olacağız

Kadehleri yere vurup,

Dosta düşmana kurulup

Kâh ağlayıp, kâh durulup

Kendimizi bulacağız.

Birimiz sekiz de, on da

Birimiz sabah kuşlukta

Beyhude geçen zamanda

Ömrü seyre dalacağız.

Sözlerimiz hep aynı söz

Özlerimiz hep aynı öz

Gönlümüzde hep aynı köz

Tutuştukça yanacağız.

Bazen aynı cigaradan

Cepte kalan son paradan

Utanılacak yokluktan

Mertçe paylaşacağız.

Aynı tenden, aynı kandan

Aynı ecdadın şanından

Alında ter kılıç kalkan

Hep sırt sırta duracağız.

Bazen tersten eser rüzgar

Gönül olacak tarumar

Göz yaşı gizlice akar

Ona mendil tutacağız.

Ekmeği katıksız yiyip

Abayı yamalı giyip

Namerdi mertçe devirip

Allah’a kul olacağız.

Dostuz ya ele inat

Dostluğumuza kanaât

Bazen jokey bazen de at

Olup öyle koşacağız.

Kader bu ya yollar farklı

Hayatın virajı çarklı

Bir iskemle üç ayaklı

Az kaldı ki olacağız.

Bir gün bir güzel fettan

İyide kötüde haktan

Alır aklımızı baştan

Belki ona kanacağız.

İçimizde doğru adam

Diyecek bize ulan

Özün de, sözün de yalan

Başı öne koyacağız.

Az kaldı ömrü bitirdik

Eğriyi doğruya getirdik

Dostluğu ahrete yetirdik

Hep “Sultan”a bakacağız.

Gardaş deyişimde cismim

Bir büyükten gelir ismim

Senin canın benim tenim

Musallada sanacağız.

Dostluğu aşkla yaşamak...

Ateşle sevişip yanmak

O ulvi duyguyu tatmak

Ölümsüzlük sanacağız

          

Herkes desin dost budur

Üşütmeyen post budur

Dostluk ALLAH yoludur

İnan şehit olacağız

Arkamızda kalacaklar

Bizden örnek alacaklar

Adam olacak torunlar

Bizde gurur duyacağız

Biz giderken yollar aydın

Yüzler aydın,gözler aydın

Düzgün bir nesil bırakın

Mahşerde buluşacağız

Teraziden şaşarsanız

Yanlışa alışırsınız

Kabire hak taşırsınız

Yandım anam diyeceğiz

Dost candanda eftal deriz

Hayatı onla severiz

Çıkmadan son nefesimiz

Dost ölmedi bileceğiz

Bir gün,iki düşer bire

Birde bölünür ikiye

Emanetler başüstüne

Başlara taç yapacağız

Yanlış var-ya,birgün yanlış

Elmanın içine dalmış

Elma bitmiş sapı kalmış

Doğruyu hak bileceğiz

Birgün hesap sorar ALLAH

Cevap veremeyiz VALLAH

Hadi ha gayret BİSMİLLAH

HAK’tan tam not alacağız

1999

Cengiz Süslü', 'İki dostuz bir şişede İçip sarhoş olacağız. Efkarları birer, birer Döküp berduş olacağız Kadehleri yere vurup, Dosta düşmana kurulup Kâh ağl...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Süslü']::text[], 8.5, '{"poet":"Cengiz Süslü","poet_slug":"cengiz-suslu","theme":"Türk Şiiri","is_hero":false,"total_lines":94,"source_url":"https://www.antoloji.com/dostca-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Kadehten Sonra', 'son-kadehten-sonra-muammer-erturan-cgafd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gitmemeliydin…

Bırakmamalıydın elimi bugün 

daha dün tanıdığın 

sayrının tekine

el ayak olacaksın diye

böyle kötürüm

kılmamalıydın gülüm... 

Gitmemeliydin... 

Etmemeliydin

eylememeliydin

komamalıydın beni bir başıma, 

dedim ama dinletemedim 

kaldıracak hâlde değilim 

sensizliği bugün... 

Gitmemeliydin...

Gittin ama...

Sorumlu değilim o zaman 

kırılan dökülenden 

son kadehten sonra... 

(12 Haziran ''95)', 'Gitmemeliydin… Bırakmamalıydın elimi bugün  daha dün tanıdığın  sayrının tekine el ayak olacaksın diye böyle kötürüm kılmamalıydın gülüm... ...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/son-kadehten-sonra-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni yaşamak', 'seni-yasamak-elazigli-mustafa-kaya-qaip6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'siz,

duygularımı alt üst eden

değil misiniz..

ve gün boyu aklıma

gelen,

korkularımı beynime 

işleyen,

hasretin dayanılmaz kıvrımlarını

heceleten

sabahları zor geceleri

geçiren

güzelliğini Süreyya yıldızına

gizleyen

siz değil misiniz..? 

uykulara dalıp dalıp

görürüm diyerek,

seni yaşamak ne güzeldir

bilemezsiniz…

seninle hayatım

her şeydir artık.

elimde fotoğrafın

konuşmuyor

susuyorsun.

olsun,

geziyor uykularımda hayalin 

geziyor avuçlarımda  buselerin

geziyor gülen  yüzünde  kahve gözlerin…

Mustafa kaya

20.03.2006 / Üsküdar

www.mustafakaya.net/frm', 'siz, duygularımı alt üst eden değil misiniz.. ve gün boyu aklıma gelen, korkularımı beynime  işleyen, hasretin dayanılmaz kıvrımlarını hecel...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/seni-yasamak-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Abasıyanık', 'abasiyanik-muammer-erturan-l56d5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Az önce duştan çıktın

şimdi kahvaltıdasın...

Elin ayağın dolaşıyor

derse yetişme telaşı içinde...

Arada bir gözlerin dalıyor

gayri ihtiyari

belli belirsiz bir gülümseme

dudaklarında,

ben geçiyorum aklından

ve tanıştığımız o an

ve ilk itiraf

ve ilk kırışımız zincirleri

herşeye ve herkese karşın...

Dur hele şimdi! 

Sırası değil bunların...

Yapacak çok iş var

düşünecek çok şey başka

kırkını aşkın

abasıyanık bir adamın dışında...

O,

bekler nasılsa...

(2 Haziran ''95)', 'Az önce duştan çıktın şimdi kahvaltıdasın... Elin ayağın dolaşıyor derse yetişme telaşı içinde... Arada bir gözlerin dalıyor gayri ihtiyari ...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erturan']::text[], 8.5, '{"poet":"Muammer Erturan","poet_slug":"muammer-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/abasiyanik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiirler kalacak', 'siirler-kalacak-cemal-simsek-jqelm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu acımasız hayat yolunda

Şiirler yazmaya çalışıyoruz durmadan. 

Meydan okurcasına tüm zorluklara

Aşk kalsın,Sevda kalsın dünyaya

Ayrılmasın sevği dolu kalpler

Kolay olsun tüm zorluklar

Gidince öbür dünyaya

Mısralarımız kalsın arkamızda.

Mal mülk neye yarar 

Götüremiyoruz yanımızda

Bir adımız kalacak

Mezar taşımızda

Birde şiirlerimiz

Sararan sayfalarda.', 'Bu acımasız hayat yolunda Şiirler yazmaya çalışıyoruz durmadan.  Meydan okurcasına tüm zorluklara Aşk kalsın,Sevda kalsın dünyaya Ayrılmasın...', ARRAY['Türk Edebiyatı','Şiir','Cemal Şimşek']::text[], 8.5, '{"poet":"Cemal Şimşek","poet_slug":"cemal-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/siirler-kalacak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuvvet ''''O''''..(Kısa bir ayrılık bu sevgili babacığım)', 'kuvvet-o-kisa-bir-ayrilik-bu-sevgili-babacigim-cengiz-suslu-g35jg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kısa bir ayrılık bu matem doluda olsa..

Zamanın kadranını durduracak kuvvet ''''O''''.

Görünmezler görünmeye başlarsa posta-posta

Ruh uçuşur boşlukta koruyacak kuvvet ''''O''''

     Her denklem..tabiatta bir formülden ibaret

     Her formül denklemlerden varolan bir zürriyet

     Doğum ve yaşam gibi ölümde bir nihayet

     Ebed-i bir hayatı..diriltecek kuvvet ''''O''''

Gelene hep hoş geldin..gidene,ah..vah..yanmak

Billurdan su yerine,kirli çamuru banmak

Gerçeğe bakar- isek doğduğunda ağlamak.

Ağlayan tüm gözleri güldürecek kuvvet ''''O''''

     Kıvrılmış bir zincir bu..iki ucundan tutsak..

   ''''Hükümdar''''ne diyorsa,işte hep o olacak

     Derken halkalardan biride sıyrılacak

     Kısa bir ayrılık bu.Nihayet son bulacak

  

 Hasret gönülleri kavuşturan kuvvet ''''O''''

13.10.2004

Atıf: Sevgili babama (Bir fatiha rica ediyorum)  

Cengiz Süslü', 'Kısa bir ayrılık bu matem doluda olsa.. Zamanın kadranını durduracak kuvvet ''''O''''. Görünmezler görünmeye başlarsa posta-posta Ruh uçuşur boş...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Süslü']::text[], 8.5, '{"poet":"Cengiz Süslü","poet_slug":"cengiz-suslu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kuvvet-o-kisa-bir-ayrilik-bu-sevgili-babacigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanrı''ya Şükür -Şaraba Şiir[51]', 'tanri-ya-sukur-saraba-siir-51-i-lhan-keskinoz-cg38i', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '51 şarap önce gözümü yakar

sonra burnumu,

sonra da ağzımı. 

–galiba çok susadım yine.

suya susadığımda doyuyorum da

şaraba susuzluğumdan doyamıyorum.

Tanrı''ya Şükür -Şaraba Şiir

teoforos', '51 şarap önce gözümü yakar sonra burnumu, sonra da ağzımı.  –galiba çok susadım yine. suya susadığımda doyuyorum da şaraba susuzluğumdan doy...', ARRAY['Türk Edebiyatı','Şiir','İlhan Keskinöz']::text[], 8.5, '{"poet":"İlhan Keskinöz","poet_slug":"i-lhan-keskinoz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/tanri-ya-sukur-saraba-siir-51-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akif', 'akif-necati-cavdar-7puxk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Akif; divanesi, vicdani, sesi bütün milletin

Ötelere mesaj veren bayragi nurlu ufuklarin

....................

Yandi ciger bir ömür izmihlale aglayarak

Dalgalanir ümitle Akif olur, ufuklarda bayrak

..........', 'Akif; divanesi, vicdani, sesi bütün milletin Ötelere mesaj veren bayragi nurlu ufuklarin .................... Yandi ciger bir ömür izmihlale...', ARRAY['Türk Edebiyatı','Şiir','Necati Çavdar']::text[], 8.5, '{"poet":"Necati Çavdar","poet_slug":"necati-cavdar","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/akif-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nevruz denilen bu bayram bizim', 'nevruz-denilen-bu-bayram-bizim-halil-colak-afa8l', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Baharın gelişini bize müjdeler

Nevruz Türkün bayramıdır bizim

Kırgızistan ta,Azerbaycan da

Kutlarız coşkuyla bayram bizim

Türk’ün  yurdu olan Özbekistan da

Şahinler yuvası Afganistan da

Ata yurdumuz  olan Türkmenistan da

 Kutlarız coşkuyla bayram bizim

Kazakistan’ın her bir köşesinde

Hindi kuş dağlarının ta tepesinde

Kafkas dağlarının erişilmez zirvelerinde

Kutlarız coşkuyla bayram bizim

Makedonya’sında,Bosna hersek inde

Tuna’nın, elbenin,mericin boylarında

Türkün talihsiz esir Karabağ''ında

Kutlarız coşkuyla bayram bizim

Kerkük'' ünde,Süleymaniye'' sinde

Musul’ unda garip Telafer’inde

Romanya’sında,Bulgaristan’ında

Kutlarız coşkuyla bayram bizim

İstanbul’unda Erzurum’un yaylarında

Diyarbakır’ın o güzel surlarında

Çukurova''nın güzel toros dağlarında

Kutlarız coşkuyla bayram bizim

Dadaşından İzmir’in efelerine

Ankara’nın seğmenlerine

Karadenizin zümrüt kıyılarında 

 Kutlarız coşkuyla bayram bizim

Kızından al Anadolunun kızanına

Yaşı Ellisinden al yaşı yüz yirmisine

Halaylar çekeriz onu kutlarız 

Nevruz denilen bu bayram bizim

Halil Çolak 21.3.2006 Ankara', 'Baharın gelişini bize müjdeler Nevruz Türkün bayramıdır bizim Kırgızistan ta,Azerbaycan da Kutlarız coşkuyla bayram bizim Türk’ün  yurdu ola...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/nevruz-denilen-bu-bayram-bizim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Af', 'af-necati-cavdar-w1whm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sabah uyanan binlerce insan; 

Af diye kalkar.

Analar yavrusunu af diye sallar

Bebekler; af diye uyur, af diye aglar.

Af ki; ümittir, yasama kadar,

Binlerce pisman göz, af diye bakar.

Yüzlerce yavuklu rüyaya afi katar,

Nice kalpler af diye atar.

Af ki; isiktir, af ki nefestir af ki soluktur.

Af düslemez ise binlerce insan,

Ne ümidi kalir, ne geçer zaman

Artik af edin beyler; büyüklüktür aman.

Oturmus; boynu bükük karsima ihtiyar,

Af sözü duysa ne kadar olur bahtiyar.

Sabah gazete açilir “af”,

Demlenir çaylar içilir “af”

Radyo dinlenir; 

Tutulur nefesler, durur kalpler af. 

              

                                Ulucanlar Medrese-i Yusufiye -        1983', 'Sabah uyanan binlerce insan;  Af diye kalkar. Analar yavrusunu af diye sallar Bebekler; af diye uyur, af diye aglar. Af ki; ümittir, yasama ...', ARRAY['Türk Edebiyatı','Şiir','Necati Çavdar']::text[], 8.5, '{"poet":"Necati Çavdar","poet_slug":"necati-cavdar","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/af-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Olur', 'ah-olur-necati-cavdar-0bhux', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kimi aglar kimi daglar can olur

Can olur kimi aglar kimi saglar

Gönül kirar yürek yakar karalar

Gönülden candan sever de yar olur 

Hakikaten baglanir da can olur

Gelin misali aglar da kar olur

Can olur yar olur da kalkan olur

Gönül kirar yüreklere dert olur

Can yakma gönüllere ah olur

Her güzele sir verme bela olur

Iyilik yap isik ver Çerag olur

                       2.10.1997', 'Kimi aglar kimi daglar can olur Can olur kimi aglar kimi saglar Gönül kirar yürek yakar karalar Gönülden candan sever de yar olur  Hakikaten...', ARRAY['Türk Edebiyatı','Şiir','Necati Çavdar']::text[], 8.5, '{"poet":"Necati Çavdar","poet_slug":"necati-cavdar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ah-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlamak, anlaşılmak', 'anlamak-anlasilmak-necati-cavdar-ilgqn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Anlamak, anlasilmak.

Çabalamak,

Cevap vermek neye.

Bilmek bilinmeyeni

Görev; 

Bildirmek en bilineni

                       05.04.1995

                        Maltepe -Ankara -13.00', 'Anlamak, anlasilmak. Çabalamak, Cevap vermek neye. Bilmek bilinmeyeni Görev;  Bildirmek en bilineni                        05.04.1995       ...', ARRAY['Türk Edebiyatı','Şiir','Necati Çavdar']::text[], 8.5, '{"poet":"Necati Çavdar","poet_slug":"necati-cavdar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/anlamak-anlasilmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
