INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Gözlerine Yazdım', 'guzel-gozlerine-yazdim-yusuf-onder-bahceci-se07a', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Güzel gözlerine yazdım bu şiirleri bu şiirleri,

Seni nasıl methedeyim şiir yetmez nesirleri,

Nesirler de bir şey değil, kâlbim dir esirleri,

Güzel gözlerine yazdım bu şiirleri bu şiirleri...', 'Güzel gözlerine yazdım bu şiirleri bu şiirleri, Seni nasıl methedeyim şiir yetmez nesirleri, Nesirler de bir şey değil, kâlbim dir esirleri,...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/guzel-gozlerine-yazdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Afyonlu rüya', 'afyonlu-ruya-i-rfan-sari-2-qj62c', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Afyonlu rüya

Rüya,

Rüya misali

Çökerken şehrimin

Aklına...

Ben on yedinci

Yaşımın çılgın bir yerindeydim.

___sarmalasam toprağa

yeşili,

sokaklara kırmızı hakim olurdu

suyu dahi keserdi bıçak

ve ölürdü mantığım.

___ben pencereden yürürdüm 

___________________şehre,

şehir,çakırkeyf

bardakların dibine otururdu.

___daldan düşen yapraklarla

aşk şarkılarına 

ağlardık...

___ne zaman kaçarsa

evlerinden ışık

sigaramın ateşi

__________________parlardı

sonra,

umudum uyurdu

afyonlu bir kızın yastığında.

___öksürüğüm dumanı

paramparça ederdi

ve hırlardı göğsüm

gece karanlığında

bir başına.

___bir başına dolanırdı

evlerin bittiği yerde.

Kurbağalar bağırışlarına

Gömülürdü.

Karagözlü geceyle

Uzadıkça uzardı 

Muhabbet....

___ve anlamlaşırdı birden

alışık görünümler.

Sabah,ekmek kokusuna

Boğulurdu...

Oysa her sabah aynı fırın

Alev alev kızarırdı.

Heyecanlanırdı sarı saçlara karşı

Kirpikler.

Yalnızlığım ordulaşırdı,

___oysa iki uslu

ve uysal

______suskunun

ayak seslerinden oluşurdu 

aşk! ...

ve durgunlaşırdı

nehir gibi akan

yüreklerinde gurur.

Şubatta üşüyen,

Temmuzda terleyen,

Unutulmayacak rüyalar

Unutulmayacak anlar

İçinde geçti

O yıllar...

İrfan sari(yetkili şair) 

Edirne/1”2.03.1995', 'Afyonlu rüya Rüya, Rüya misali Çökerken şehrimin Aklına... Ben on yedinci Yaşımın çılgın bir yerindeydim. ___sarmalasam toprağa yeşili, soka...', ARRAY['Türk Edebiyatı','Şiir','İrfan Sari 2']::text[], 8.5, '{"poet":"İrfan Sari 2","poet_slug":"i-rfan-sari-2","theme":"Türk Şiiri","is_hero":false,"total_lines":63,"source_url":"https://www.antoloji.com/afyonlu-ruya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Yoksun Yanımda', 'sen-yoksun-yanimda-ahmed-yasin-jkwzz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'SEN YOKSUN YANIMDA

Sensiz bir ağustos gecesi daha	

Yine sen yoksun yanımda

Sigara külleri dökülmüş her tarafa

Nereye baksam senden yalan bir hatıra

Artık şiirde yazamıyorum küstüm satırlara

	

Sen neymişsin be başımın belası

Artık sevmeme orucuna başladım

İnsanlardan nefret

Sorulmuş sorulara da yorgun bir evet

Yalnız dağlarda yalnız bir mahkûm

Yalnızlığımı kaybettim 

Altın arar gibi yalnızlığı arıyorum

Sendeki günlerimi hatırlıyorum

Ne de garip geçmişti 

Bir akşam simidini paylaşırken 

Veya saçların avucumda batan güneşleri seyrederken

Vicdanım yüreğime hesap sormazken

Ellerinle ağzımı koyduğunu ne de iştahlı yemiştim

Yine uslanmaz bir çocuk oluvermiştim

Annemden şikâyetler işitirken

Yine parmaklarımı ısırdı diye

Ne yapaydım

Annem kini gevezeliğimden

Senin kini belki de tatlı bir muhabbetimden

Ah, ah yıllar sonra anladım

Simit aldığımız hasan amca yok

Oturduğumuz yere tinelcilerden başkası yok

Fatma teyze de öldü

Artık mahallenin dedikodusunu kim yapacak bilmiyorum

Hani Rüstem’in kızı Ahmed’de günlü var diye

Milletin kahve sohbetinin konusu olmuştuk

O zaman kadından ama da kızmıştık

Hani bir daha babama bir şey söylerse pencereden atarım demiştin

Kadın kendisi düştü o zaman sen gitmiştin

Sizin eve yeni kiracılar gelmiş

Eski anılarım diye sizin pencereye de bakmıyorum

Yeni kiracıların iplik fabrikasında çalışan bir kızları var

Annem baktığımı görse Vallahi gözlerimi oyar

Yine konuşmaya başlar

Oğul bu pencere sevdaları sana olmaz yar diye

Oysa ben okuldan çıkıp elimi kolumu salaya, salaya eve gelirken

Muhtar eminin orada bir birimize çarpmıştık

Düşeni toplamak gibi

Bir portakal hadisesinden sonra tanıştık

Sen pazarda yeni aldığın portakalları

Ben ise ne yazıldığı beli olmayan sayfaları

Düşürdük sokağın ortasında

Sen Rüstem’in kızı gurbet

Ben ise gariban anamın oğlu Ahmed

Ertesi gün 

Hafta sonu pencereyi siliyordun

Yarım kalmış şiiri tamamladıktan sonra

Sizin pencerenin orasına bakmıştım

Benden saklayamadığın gözlerin

Yarinki şiirimin başlığı olmuştu

Vazgeçmem gözlerinden diye

Bizimkisi öyle işte

Erken girmeye başladık pazar günlerine

Onlarda yetmedi 

Büyüklerimizi kandırdığımız gecelere başladık

Sen babana mesai yapıyorum diye

Ben ise arkadaşlara çalışmaya gidiyorum derdim anneme

Geceleri deniz sahilinde yakalamaya çalışırdık

Ve şiirler okurduk ikimiz 

Dursun dediğimiz gecelere

Sensiz geceleri kovuyorum artık

Sağ olsun babamın bir emeklik maaşı vardı

Geçinip duruyorduk 

Okulu bitirdiğimde mühendis olup annemi saraylarda yaşatacaktım

Ama şiir yazma sevdasını bırakmadım

Matematik defterime bile şiir yazardım

Ne yapalım okullu bitiremedim

Ama yine anemi saraylarda yaşattım

Hayata değil şiirlerimde yaşattım

Mısralarda annemi saat 10’larda kaldırdım

Kahvaltı hazırlattırmadım

Bakkal ada göndermedim

Hizmetine koydum birkaç cariye

Annem sarayda yaşamanın tadını çıkarsın diye 

Beklide baban bu yüzden 

Abrasıyla bizi toza bırakan cemilin oğluyla evlendirmişti

Babasının bir apartmanı

Birde her gazete alış verişimde kahrolduğum bakkalı

Eh işte mahallenin zengini sayılırdı

Ve bir ağustos gecesi daha

Yine sen yoksun yanımda

İsmini yazıyorum yaslandığım her duvara

İsyan ediyorum sana okuduğum her mısraya

Bir Vanya gibi kavuşmasam da mutluluklar dilerim sana

Bir buruk sevgiyse arkanda bıraktığın

Kopardığın sazın telleri de  benim

Bir umutsuz sevgiyse sattığın

Bunları sana yaza da benim

                                                    Yasin Kızılırmak', 'SEN YOKSUN YANIMDA Sensiz bir ağustos gecesi daha	 Yine sen yoksun yanımda Sigara külleri dökülmüş her tarafa Nereye baksam senden yalan bir...', ARRAY['Türk Edebiyatı','Şiir','Ahmed Yasin']::text[], 8.5, '{"poet":"Ahmed Yasin","poet_slug":"ahmed-yasin","theme":"Türk Şiiri","is_hero":false,"total_lines":95,"source_url":"https://www.antoloji.com/sen-yoksun-yanimda-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgilim Sibiryaya Yine Sürgün', 'sevgilim-sibiryaya-yine-surgun-ahmed-yasin-cx0l0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'SEVGİLİM SİBİRYA’YA SÜRGÜN

Ağaçların yapraklarını dökmeye başladığı bir gün

Yarım kalmış sevgilerde ise hüzün

Bırakılmışlığın ardında ben ise

Sevgilim Sibirya’ya yine sürgün

Ve acı ne diye

Kendime sorduğumda

Demir parmaklıkların

Kokuşmuş ranzaların

Yetişmek isteyip de yetişemediğim

Sevgilileri hapseden hapishane duvarları

Benimle güneşsiz bir günde belalı arkadaşlığı

Yine acıların bir avuç dünyama hükmettiği bir an

Kardeşliğin kokuşmuş bardaklarda aranırken

Mutluluğu bırakılmış sevgide ararken

Acıların yıkılmış odların şubesi

Sokakların titrek lambasının dostu bendim

Sibirya sürgünün bana yazacağı mektupları okumayacağım

Gitmişliğin anlamı olmasın diye

Çarşaflı sokakların deresine uğramayacağım

Yorgunluğum çamura karışmasın diye

Sibirya’nın yıldızlarına bakarken

Sevgiliyi sormuşum her gelenden

Kanadı kırılmış kartala

Yüzü solmuş bestekâr fidana

Sibirya’daki sürgünü sormuşum

                                    Yasin Kızılırmak', 'SEVGİLİM SİBİRYA’YA SÜRGÜN Ağaçların yapraklarını dökmeye başladığı bir gün Yarım kalmış sevgilerde ise hüzün Bırakılmışlığın ardında ben is...', ARRAY['Türk Edebiyatı','Şiir','Ahmed Yasin']::text[], 8.5, '{"poet":"Ahmed Yasin","poet_slug":"ahmed-yasin","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/sevgilim-sibiryaya-yine-surgun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sağırlar Bile Duydu', 'sagirlar-bile-duydu-yusuf-onder-bahceci-y8ke3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yazdığım bu şiirleri sağırlar bile duymalı,

Yazdığım bu şiirleri, okuyanlar, ağlamalı,

Bu şiirleri duygulu olan, olanlar anlamalı,

Yazdığım bu şiirleri sağırlar bile duymalı.

Merak etme Gülüm, sağırlar bile duydu,

Yazdığım her satırlar, kafiyeyle doluydu,

Önder''de senin gibi bir Allah''ın kuluydu,

Yazdığım bu şiirleri, sağırlar bile, duydu.', 'Yazdığım bu şiirleri sağırlar bile duymalı, Yazdığım bu şiirleri, okuyanlar, ağlamalı, Bu şiirleri duygulu olan, olanlar anlamalı, Yazdığım ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sagirlar-bile-duydu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Takıldın Yirmibeşine', 'takildin-yirmibesine-hasan-yildiz-g7eh5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ağarmış şakaklarım benzim solmakta,

Ben eski sevdan değilim,ömür dolmakta

Sen takıldın kaldın kaldın yirmibeşine

Ben nasıl takılayım senin peşine

Bende hazan,sende bahar olmakta

Attım demirleri gözlerinin körfezine

Ay ışığında sevişiriz,yakamozlarla

Bilmem,hangi mevsimdesin-bende sonbahar

Sen açılmışsın uçsuz deryalara-siya siya

Ben dövmekteyim sahilleri-ağlıya ağlıya

Ey geçmişe asılı kalan yiğitler

Ne besteler yazıldı ne beyitler

Bizi unutmayın canlı şahitler

Kimimiz leyla kimimiz mecnun.

01,11,2004', 'Ağarmış şakaklarım benzim solmakta, Ben eski sevdan değilim,ömür dolmakta Sen takıldın kaldın kaldın yirmibeşine Ben nasıl takılayım senin p...', ARRAY['Türk Edebiyatı','Şiir','Hasan Yıldız']::text[], 8.5, '{"poet":"Hasan Yıldız","poet_slug":"hasan-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/takildin-yirmibesine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zühâl Yıldızı', 'zuh-l-yildizi-yusuf-onder-bahceci-72010', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çoban Yıldızını bilirim, çobanlara, yolunu gösterir,

Kutup Yıldızını bilirim Kutup Yıldızı Kuzeyi gösterir,

Samanyoluna bakarım, düşünürüm, beni söyletir,

Zühâl Yıldızı gizemlidir bilmem derdi nedir, nedir...

Sitede ki Kardeşime....', 'Çoban Yıldızını bilirim, çobanlara, yolunu gösterir, Kutup Yıldızını bilirim Kutup Yıldızı Kuzeyi gösterir, Samanyoluna bakarım, düşünürüm, ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/zuhal-yildizi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Mehmet Yılmaz', 'ben-mehmet-yilmaz-mehmet-yilmaz-ak-yt5qx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Benin ruhum denizlerdeki köpüklerde gizli

gözlerimi kapattığımda içimden kuşlar geçer

kanat sesleriyle bulutlara karışırım

Saatlerin sustuğu vakit 

hissederim gecenin beni alıp götüren romantizmini

Bulutların gerisinde ben varım

yağmurumu ağlayacak

yeşil ovalara,bereketli topraklara koşarım

Kalplerin gizli odalarını pekçok kez dolaşmış,

saf sevgiyi arayan bir gezginim

Yalnızlık duygusunu

şarap gibi içen bir mecnunum,

uçsuz bucaksız çöllerde

Kendi kumsalımın yakamozlu mehtabında,

inandığım tüm güzellikleri gerçekleştirmeye

ve zamanın büyülü akışında

sevginin o eşsiz gücünü her zaman yaşamak için

kendime söz vermiş romantik bir serseriyim

Duygularım taştığında

elinde mutlaka kağıt kalemi olan bir şairim

Hayatın tüm çirkinliklerine rağmen

içimdeki küçüğü boşa gitmeyecek paylaşımlara açan

bir yaramazım

Her gün ölmek nedir bilmeyen,

devamlı yenilenen

yanıp sönen,bulutsu,manevi dünyamın kapısında

bana yakın olanları içeriye buyur ettiğim 

her zaman için güzel insanların

ikinci bir şansı olduğuna inandığım

bir evsahibiyim

Ve sürekli ararım sıradışı olanı

düne saygı duyarım,yarına ise inanırım

yaşam sevincim coşkulu bir ırmaktır

kalbimden kalplere

Sonbahar kokusunu getirirken yeni yılın tazeliğini

ağlarım bir daha şimdi olmayacak diye

Kimse göremez gözyaşlarımı

onlar değeri bilinmeyen pırlantalardır

kalbime akıttığım

Zaman yaşadığım şu andadır

ve yaşam zevk aldıkça

ve farkına vardıkça daha güzel (02.07.99)', 'Benin ruhum denizlerdeki köpüklerde gizli gözlerimi kapattığımda içimden kuşlar geçer kanat sesleriyle bulutlara karışırım Saatlerin sustuğu...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Yılmaz Ak']::text[], 8.5, '{"poet":"Mehmet Yılmaz Ak","poet_slug":"mehmet-yilmaz-ak","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/ben-mehmet-yilmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömrün Hazanda', 'omrun-hazanda-murat-duman-td0wi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '02. ÖMRÜN HAZANDA

Seneler geldi geçti, ömür denen kazanda,

Gülmesini denedim, sakın gülme dediler,

Güneşe el uzattım, tutamadım hazanda,

Almasını denedim, sakın alma dediler…

Akşam oldu arındım, sabah oldu büründüm,

Gam yükü çeke çeke, yıllar var ki; süründüm,

İçimde ki; düşmana, kılıç kalkan göründüm,

Silmesini denedim, sakın silme dediler,

Sırla bezenmiş dünya, çözeyim diye geldim,

Yaşarken şu âlemde, yolumu zor buldum,

Gönüller bahçesinde, her dalı çiçek bildim,

Yolmasını denedim, sakın yolma dediler…

Durmak nedir bilmedim, gezdim şu evrende,

Günüm güne uymadı, dolanırken devranda,

Sen seni bul ey miskin, yol şaşırdın çevrende, 

Bulmasını denedim, sakın bulma dediler…

Murat Duman dön de bak, akıp giden günlere

Kıymetini bil günün, aldanma sen dünlere

Adım adım giderken, ömür denen sonlara,

Kalmasını denedin, sakın kalma dediler… 

                                       202006 ANKARA.', '02. ÖMRÜN HAZANDA Seneler geldi geçti, ömür denen kazanda, Gülmesini denedim, sakın gülme dediler, Güneşe el uzattım, tutamadım hazanda, Alm...', ARRAY['Türk Edebiyatı','Şiir','Murat Duman']::text[], 8.5, '{"poet":"Murat Duman","poet_slug":"murat-duman","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/omrun-hazanda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Deli Muammer', 'bir-deli-muammer-yusuf-onder-bahceci-b8p18', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bizim Köyün bir delisi, Deli Muammer,

Ona deli diyemezsin, Velidir ne haber,

O çok sevmiştir gözleri dalar da gider,

Bizim Köyün bir delisi, Deli Muammer.

Deli diyenlere gülüp, gülüp te geçiyor,

O Hak''kın Delisi, kâlbi Hakkı seçiyor,

Dünya malı önemlimi deyipte geçiyor,

Bizim Köyün bir delisi, Deli Muammer....

Sitede ki Kardeşime....', 'Bizim Köyün bir delisi, Deli Muammer, Ona deli diyemezsin, Velidir ne haber, O çok sevmiştir gözleri dalar da gider, Bizim Köyün bir delisi,...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bir-deli-muammer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aç bana kalbini', 'ac-bana-kalbini-nuri-gokhan-sonsel-g3kx6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aç  bana  kalbini, söyle  gerçek  hislerini,

Sende  ben  gibi  gururlu, çekingen  misin? 

Aç  bana  kalbini, bence  zarar  yok,

Karanlık  bir  gecede  olmasın…

Anlatamıyorsa… güzel  dudaklar, 

O  yeşil  zeytin,  gözler  anlatsın.

Aç  bana  kalbini, haykır  artık sevdanı,

Bir  mehtaplı  gecede, yıldızlar  şahit olsun.

Aç  bana  kalbini,  ez  artık  gururunu,

Seviyorsan  ben  gibi, paylaşalım  bu aşkı.

Aç  bana  kalbini, söyle  hissettiklerini,

Nefret  ediyorum  de…seviyorum  de..

Bana  bir  şeyler  söyle,  söyle  hissettiklerini.

Neden  engin  dağları, denizleri  aşamıyor  da,

Kahrolası  gururun  önüne,  bir  set  çekemiyorsun.

Benimle  hayatı  paylaşmak  için, cesaretin  yok güzelim,

Çünkü  aramızda,  dağlar  denizler  değil…

Senin o kahrolası,  gururun  var…', 'Aç  bana  kalbini, söyle  gerçek  hislerini, Sende  ben  gibi  gururlu, çekingen  misin?  Aç  bana  kalbini, bence  zarar  yok, Karanlık  bi...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ac-bana-kalbini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlamıyorum', 'anlamiyorum-nuri-gokhan-sonsel-lt9sl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '.

Neden ağlıyorsun, sen yeşil yaprak,

Niçin üzgünsünüz, filizlenen çiçekler.

Yaa sen gönlümdeki büyümüş, o ulu çınar,

İnanın… ben sizi anlamıyorum.

Neden bu kadar katı, merhametsizsin hayat,

Niçin sert esersin, dağlardaki rüzgarlar? 

Ya sen…içimdeki, o bitmeyen fırtına,

Nedir istediğiniz, sizi anlamıyorum.

Neden gecelerimde, parlayan yıldız söndü,

Niçin bütün bulutlar, ıslatıyor her yeri.

Ya sen…içimdeki, o kaybolan umutlar,

Anlamıyorum…sizi anlamıyorum.

Neden kalbimde isyan, gözlerimde sen varsın,

Nedir sana bu hasret, neden bunca beklemek.

Yaa  sen…içimde yanan, o bitmeyen arzular,

Nedir beklediğiniz, inan anlamıyorum.

Geçen her bir saniye, özür borçlusun hayat! 

Sen yok ettin tükettin, bütün hayallerimi.

Bana en büyük ceza, ondan ayrı kalmaktı,

Sende bunu başardın, neden anlamıyorum.

Kurumayan gözyaşım, seni anlamıyorum,

Boşuna yanan yürek, seni anlamıyorum.

Değer miydi sevmeye, bunca çile çekmeye,

Anlamıyorum  Gökhan…seni  anlamıyorum..', '. Neden ağlıyorsun, sen yeşil yaprak, Niçin üzgünsünüz, filizlenen çiçekler. Yaa sen gönlümdeki büyümüş, o ulu çınar, İnanın… ben sizi anlam...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/anlamiyorum-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annem', 'annem-nuri-gokhan-sonsel-7hghn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çok  korkuyorum, ne  olur  ellerimi  tut,

Kolların  boynuma, dolansın  annem…

Okşasın  gülüşün, yüzümü  bir  an,

Daima  sevgine, muhtacım  annem….

Hasretim sesine, hiç  duymadım ki,

Özledim  yüzünü, görmedim annem…

Ümitle  bekledim, dönersin  diye,

Unuttun beni  sen, gelmedin  annem….

Yavrum  diyen  sesini, hiç  duyamadım,

O  mis  gibi kokunu, bilmedim  annem….

Dizinde  bir  kez, oturamadım,

Yanağına  öpücük, konduramadım.

Kalbimdeki  resmini, solduramadım, 

Cennette  rahat  uyu, sevgili  annem.', 'Çok  korkuyorum, ne  olur  ellerimi  tut, Kolların  boynuma, dolansın  annem… Okşasın  gülüşün, yüzümü  bir  an, Daima  sevgine, muhtacım  a...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/annem-148-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkı Ben bilirim', 'aski-ben-bilirim-nuri-gokhan-sonsel-ah88s', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aldatma  boş  sözle, kendi  kendini,

Aşk  denilen  duyguyu, sen  bilemezsin.

Belki  bir gün  bulursan, dengi  dengini,

Dizlerin  tutmaz  olur, yürüyemezsin.

Aşk  gibi  bir  kelime,  düşmüş  diline,

Kalbinde  hissedip, söyleyemezsin.

Aldanma  saçımın, beyaz  teline,

Aşkı  ben  bilirim…sen  bilemezsin.

Aşk  ateş  gibidir, seveni  yakar,

Tutuşturur  kalbini,  söndüremezsin.

Gülerek  karşından, seyredip  bakar,

Hiç  aşık  olmadın  ki, sen  bilemezsin.

Aşkın  karşısında, eğilir  başlar,

Dilin  damağın  kurur, seslenemezsin.

Nefesin  duyulmaz, kalbin  yavaşlar,

Ben  bilirim  bu  aşk’ı, sen  bilemezsin.', 'Aldatma  boş  sözle, kendi  kendini, Aşk  denilen  duyguyu, sen  bilemezsin. Belki  bir gün  bulursan, dengi  dengini, Dizlerin  tutmaz  olu...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/aski-ben-bilirim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Osmangazi de Garip Ömer', 'osmangazi-de-garip-omer-yusuf-onder-bahceci-hmbll', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bursa Osmangazi de, bir garip Ömer,

Besbelli yârin kaybetmiş delice döner,

Girdiği bütün sokaklar çıkmaza döner,

Bursa Osmangazi de, bir garip Ömer,

Besbelli yârin kaybetmiş delice döner....

Site de ki Kardeşime....', 'Bursa Osmangazi de, bir garip Ömer, Besbelli yârin kaybetmiş delice döner, Girdiği bütün sokaklar çıkmaza döner, Bursa Osmangazi de, bir gar...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/osmangazi-de-garip-omer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkımızı saklayalım', 'askimizi-saklayalim-nuri-gokhan-sonsel-vpk0m', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözlerinden  yayılan, o  büyülü  dalgalar,

Kalbimde  bir  kıvılcım, olur  beni  yaralar.

Dolaşırken  el ele, hiç  bitmesin  isterim,

Kalbimizde  aşk   dolu, bu  mutlu  dakikalar.

Sanki  binlerce  kalp, gökyüzüne  yükseldi,

Yıldızlarla  buluşup, kalbimize  yerleşti.

Ne  bir  sızı  kalmıştı, ne  gözlerde  bir damla  yaş,

Akıverdi  içime,  AŞK…yavaş, yavaş.

Sevdalıydı  doğada, bütün  kuşlar  çiçekler,

Sevdalıydı  güllere, rengarenk  kelebekler.

Aydınlıktı  gökyüzü, parlıyordu  geceler,

Kalbimizde  bir  fısıltı, aşk…aşk  diye  heceler.

Saklayalım  sevdamızı, hiç  kimseler  bilmesin,

Seneler  tükensin  de,  aşkımız  tükenmesin.

Seni  çok seviyorum, hem  vallahi, billaha,

Ellerimiz  ayrılmasın, kavuşurken  Allah’a.

N.Gökhan SONSEL', 'Gözlerinden  yayılan, o  büyülü  dalgalar, Kalbimde  bir  kıvılcım, olur  beni  yaralar. Dolaşırken  el ele, hiç  bitmesin  isterim, Kalbimi...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/askimizi-saklayalim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Kalsın', 'bana-kalsin-nuri-gokhan-sonsel-1bm3w', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bahar, idim, güze  erdim,

Güzelliğe, gönül  verdim.

Kötülüğe, yüz  vermedim,

Neden  dersen…bana  kalsın.

Aşkı  desen, çok  kez  tattım,

Hiç  kimseyi  aldatmadım.

Üzdüm  ama, ağlatmadım,

Neden  dersen…bana  kalsın.

Hep  dertliydi,garip  başım,

Aktı  durdu,hep  gözyaşım.

Çok  az  oldu, arkadaşım,

Neden  dersen….bana  kalsın.

Gökhan  Sonsel,benim  adım,

Hiç  bir  kula, kul  olmadım.

Gerçek  bir  dost, bulamadım,

Neden  dersen, bana  kalsın.

Şiir  yazdım, senelerce,

Mısra, mısra, hece, hece.

Hayat  komik, bir  eğlence,

Neden  dersen ….bana  kalsın.

Hayatımın, budur  özü,

Sakınmadım, hiç  bir  sözü,

Sevdim  yalnız,  yeşil  gözü,

Neden  dersen…bana  kalsın.', 'Bahar, idim, güze  erdim, Güzelliğe, gönül  verdim. Kötülüğe, yüz  vermedim, Neden  dersen…bana  kalsın. Aşkı  desen, çok  kez  tattım, Hiç ...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bana-kalsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben neyim?', 'ben-neyim-nuri-gokhan-sonsel-xbc0w', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben:  masmavi   denizlerle  çevrili,

Issız-sessiz,yalnız  bir  adayım.

Kökleri  gür, yaprakları  yemyeşil,

Çiçekleri  çok  renkli, ulu  bir  ağacım.

Ben:  içimdeki  fırtınada,ceviz  kabuğu  gibi, 

Sürüklenen, dümensiz-kaptansız  bir  gemiyim.

Dönülmez  bir  alemin, sonsuz   karanlıkların,

Daima  raks eden,gönül  semazen’iyim.

Ben:  göklerde kaybolmuş, bir  umut ışığı  gibi,  

Dünyaya  kilitlenmiş, bir  gezegen.

İçimdeki  depremle, yıkılmış  bir  virane,

Kendi  dünyasında yaşayan,  bir  divaneyim.

Ben: gönlü  sevgiyle  dolu, garip  bir  aşık,

Acılara, ızdırab’a, yalnızlığa  alışık.

Daima  dost  canlısı, düşmanıyla  barışık,

Rüyalar  aleminde, dertsiz  biriyim.

Ben: kendinde  ihtilaller  yaratan,

Hıçkırığını, kahkahayla  kapatan.

Çiçeklerle  bezenmiş, sevda  bahçesinin  bekçisi,

Bütün  gönüllerin…AŞK  mihrabıyım.

N.Gökhan SONSEL', 'Ben:  masmavi   denizlerle  çevrili, Issız-sessiz,yalnız  bir  adayım. Kökleri  gür, yaprakları  yemyeşil, Çiçekleri  çok  renkli, ulu  bir ...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ben-neyim-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çünkü Seviyorum', 'cunku-seviyorum-ziya-kara-yhil6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Her ne kadar kıskanmıyorum

Kıskanmam desem de

Kıskanıyorum yine de

Çünkü seviyorum

Unutursan unuturum

Unuttuğuna göre

Unuttum desem de

Kendimi kandıram ki

Çünkü seviyorum

Evimde, odamda, yatağımda

varsın yoksun önemli değil

Önemli olan yüreğimdesin

Çünkü seviyorum

Sevgi senelerle bitip tükenmez

Sevmesini bilince

Bana göre canan

Candan önce

Çünkü seviyorum

Delice ve kendimce', 'Her ne kadar kıskanmıyorum Kıskanmam desem de Kıskanıyorum yine de Çünkü seviyorum Unutursan unuturum Unuttuğuna göre Unuttum desem de Kendi...', ARRAY['Türk Edebiyatı','Şiir','Ziya Kara']::text[], 8.5, '{"poet":"Ziya Kara","poet_slug":"ziya-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/cunku-seviyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seslenen Yürek', 'seslenen-yurek-yusuf-onder-bahceci-tavy4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yıllardır seslenen yüreklere nasıl bir aksi seda,

Adı, seslenen yürek, sevdiği için bükülür bilek,

Devamlı düşünür, içinden çıkamaz, eder dilek, 

Adı, seslenen yürek, sevdiği için bükülür bilek...

Sitede ki Kardeşime', 'Yıllardır seslenen yüreklere nasıl bir aksi seda, Adı, seslenen yürek, sevdiği için bükülür bilek, Devamlı düşünür, içinden çıkamaz, eder di...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/seslenen-yurek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben ve sen', 'ben-ve-sen-nuri-gokhan-sonsel-3p0qh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'BEN

                                             

Aşkımı söylesem, yalvarsam sana,

Belki de darılır, küsersin bana.

Kaldırır başını, diker tavana,

Sen benim aşkımla, alay edersin.

Kapında yalvarsam, naz ile niyaz,

Kalbim duracak gibi, yüzüm bembeyaz.

Umurunda değil ki, elinde bir saz,

Çalar da benimle, alay edersin.

Ne bir sesim duyulur, Nede bir sözüm,

Utanırım karşında, kızarır yüzüm.

Bağrıma kitlenmiş, o güzel gözün,

Bakar da benimle, alay edersin.

                  SEN

Bir gün âşık olursan, benimkinden az,

Ağlayıp inlersin, sen avaz, avaz.

Senin de sesin kısılır, yırtılır boğaz,

Ne kadar kırılsam da, saygı duyarım.

İçinde bir alev, gözlerinde yaş,

Anlarsın aşk neymiş, sen yavaş, yavaş.

Kıskanırsın kalbinde, soğuk bir savaş,

Sen aşkı tanıdın ya… Saygı duyarım.

Kaçar tüm uykuların, sararır yüzün,

Ruhunda yüzlerce… Binlerce hüzün.

Ağlamaya başladı mı,  o güzel gözün,

Aşk denilen duyguya, saygı duyarım.', 'BEN                                               Aşkımı söylesem, yalvarsam sana, Belki de darılır, küsersin bana. Kaldırır başını, diker t...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ben-ve-sen-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cennet Hurisi', 'cennet-hurisi-murat-duman-attk4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Cennet Hurisi

Asude güzelin, bağına girdim,

Kandırdı arzumu, dillere verdi,

Gizli cevherini, özünden derdim,

Dindirdi arzumu, güllere verdi…

Şahin bakışında, duyguyu sezdim,

Sevgi sahilinde el ele gezdim,

Doyumsuz aşkını, kalbime yazdım,

Söndürdü hüznümü, sellere verdi…

O Cennet hurisi, cana can katar,

Gizemli bakışı, aşka gül atar,

Yemyeşil gözleri, ruhuma yatar,

Döndürdü başımı, yellere verdi… 

Bahşili dağında, çiçekler açar,

Yağmur uykusunda, kendinden geçer,

Gönül pınarından, badeler içer,

Dindirdi hasreti, yollara verdi…

Kaderin emrine, karşı durulmaz,

Destursuz güzelin, gülü derilmez,

Murat köle olur, asla yorulmaz,

Yandırdı nefsimi, küllere verdi…

                        14.02.2006 ANKARA', 'Cennet Hurisi Asude güzelin, bağına girdim, Kandırdı arzumu, dillere verdi, Gizli cevherini, özünden derdim, Dindirdi arzumu, güllere verdi…...', ARRAY['Türk Edebiyatı','Şiir','Murat Duman']::text[], 8.5, '{"poet":"Murat Duman","poet_slug":"murat-duman","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/cennet-hurisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni bensiz bıraktın', 'beni-bensiz-biraktin-nuri-gokhan-sonsel-m5vaf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Günlerdir  yolunu, bekledim senin,

Güneşin battığı, o ıssız yerde.

Avuçlarımda ateş,  gözlerde hüzün,

Gelmedin bir tanem, beni bensiz bıraktın.

Çatladım toprak gibi, kurudum yaprak gibi,

Düştüm  kızgın çöllere…

Benim bu  halimi,  sen bile, bile,

Acımadın bir tanem, beni bensiz bıraktın.

Bir bahar rüzgarı  gibi, esiverdin kalbime,

Yıldızlarla el ele, seni  ve sevgimi  aradım.

Yıllar geçti aradan, kanadı  bu  yüreğim,

Bulamadım bir tanem, beni bensiz bıraktın.

İnan ki sevmekten, pişman değilim,

Ben zaten kendimi, adadım sana.

Eriyip  giderken, bu son yolculuğuna,

Bıraktın bir tanem, beni bensiz bıraktın.

Özledim bir tanem, o hoş sesini,

Özledim bir tanem, sıcacık nefesini.

Yazamadan ben sana, aşk bestesini,

Gittin bir tanem gittin, beni bensiz bıraktın. 

N.Gökhan SONSEL', 'Günlerdir  yolunu, bekledim senin, Güneşin battığı, o ıssız yerde. Avuçlarımda ateş,  gözlerde hüzün, Gelmedin bir tanem, beni bensiz bırakt...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/beni-bensiz-biraktin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Kadar Özgürsün Sevince', 'ne-kadar-ozgursun-sevince-mehmet-yilmaz-ak-uvzcf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne kadar özgürsün sevince

Ne kadar kendinsin yalnız kalınca

Dünya küçük hayallerin büyük

Düşün her isteğin yerine geliyormu

Her istediğinde tutabiliyormusun kalplerdeki büyüyü

Takılıp kaldıkmı dünyaya

Yoksa zincirlerini kırabilirmiyiz

Bedenlerin demir kapılarını

Bazen bilinmiyor yolların nereye çıkacağı

Ama yüreğinde inancın gücü varsa

Sınırları olurmu özgürlüğün,sevginin

Kafanı kaldırıp baktığında

Parlayan aya,yıldızlara

Hissedermisin acaba orada da 

Birilerinin sana baktığını

Ve o birilerinin de

Senin gibi düşündüğünü

Seni merak ettiğini (07/99)', 'Ne kadar özgürsün sevince Ne kadar kendinsin yalnız kalınca Dünya küçük hayallerin büyük Düşün her isteğin yerine geliyormu Her istediğinde ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Yılmaz Ak']::text[], 8.5, '{"poet":"Mehmet Yılmaz Ak","poet_slug":"mehmet-yilmaz-ak","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ne-kadar-ozgursun-sevince-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Olsaydın', 'benim-olsaydin-nuri-gokhan-sonsel-ssauw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tanısaydım  ben  seni, uzun  yıllar  öncesi,

Gönlümde  bir  krallık, sen  kalbimin  ecesi.

Siyaha  boyanmazdı, hiç  bir  aşkın  gecesi,

Bir tanem  sen  benim….bende  senin  olsaydım.

Doldurmazdı  kalbimi, erkenden  bunca  sızı.

Doğardı  mehtap  gibi, aşkın  kutup  yıldızı.

Aşkla  boğardım seni, gönlümün  farklı  kızı,

Bir tanem  sen  benim…bende senin  olsaydım.

Sana  ben  her  dakika, canım  sevgilim  derdim,

Eksilmezdi  artardı, bin  kat  fazla  severdim.

Ben  seninle  ağlayıp, yalnız  senle  gülerdim,

Bir tanem  sen  benim…bende  senin  olsaydım.

Öperdim  ben  her  sabah, o  gül  dudaklarını,

Okşardım  saçlarınla, pembe  yanaklarını.

Ağlatmaz güldürürdüm,  o  göz kapaklarını,

Bir tanem  sen  benim…bende  senin  olsaydım.

Hep  aşk  ile  yaşardım,  seninle  uzun  yıllar,

Dökülse  hiç  kalmasa, başımda  beyaz  kıllar.

Yok  olurdu  uzayan, bitmez  sanılan  yollar,

Bir tanem  sen  benim…bende  senin  olsaydım.

Ben  aşkımla  yazardım, her gün  sana  bir  şiir,

Sana  sevgi  sunardım, başka  şık  mümkün  değil.

Taşarda   sel  olurdu, sevdam  azgın  bir  nehir,

Bir tanem  sen  benim…bende  senin  olsaydım.', 'Tanısaydım  ben  seni, uzun  yıllar  öncesi, Gönlümde  bir  krallık, sen  kalbimin  ecesi. Siyaha  boyanmazdı, hiç  bir  aşkın  gecesi, Bir ...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/benim-olsaydin-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hay aleylim', 'hay-aleylim-bestami-kurtulus-6let2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'dedem nasıl oturursa mindere 

öyle kurulmuş

sırtını yaslamış yamaca 

uzanıp ayak ucunda evliyanın

kaydı kayacak bir telaşı umursamaz 

yeşilinden hayata öyle aşkla tutunmuş 

Kitab’ın kalbine gömülü mazi

anadolu emzikli bebeydi 

dizlerinde 

düştü kalktı nice zelzele

hala durur taş taş üstüne

kim bilirse kıymetim 

gelsin

o baş üstüne

taş sokaklar serin kuytular

feryat figan bir müezzin

ve sabahın alacasında 

bir takunya sesi geçer sokaktan

gün sıcacık ekmek gibi doğar

yanık fırından

altın tasta kuru güller

sonra dut var 

incir, zeytin, nar

bulgur deyip geçme 

elde ne hünerler var

her evin bir asması

alt başında bir havuş

pirinç ocağın üstünde

bir kazan kaynar

hay aleylim aleylim

nasıl bir diyara 

hangi cennet rüyaya girdim

affan dedenin memleketindeyim

ve duanın ucunda kapalı gözlerim

ve şirince baharında 

çocukluk hüzünlerim', 'dedem nasıl oturursa mindere  öyle kurulmuş sırtını yaslamış yamaca  uzanıp ayak ucunda evliyanın kaydı kayacak bir telaşı umursamaz  yeşili...', ARRAY['Türk Edebiyatı','Şiir','Bestami Kurtuluş']::text[], 8.5, '{"poet":"Bestami Kurtuluş","poet_slug":"bestami-kurtulus","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/hay-aleylim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Selam Sana Turhan Emmi', 'selam-sana-turhan-emmi-yusuf-onder-bahceci-zpooj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Selam sana kardeşim, Turhan Emmi Turhan Toy,

Baktım şöyle özgeçmişine, beni senin yerine koy,

Ben de İşletme mezunu sende, bende memurum,

Memleketler yakındır, herhalde, hemşerin olurum,

Selam sana kardeşim, Turhan Emmi Turhan Toy,

Baktım şöyle özgeçmişine, beni senin yerine koy...', 'Selam sana kardeşim, Turhan Emmi Turhan Toy, Baktım şöyle özgeçmişine, beni senin yerine koy, Ben de İşletme mezunu sende, bende memurum, Me...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/selam-sana-turhan-emmi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim güzel çiçeğim', 'benim-guzel-cicegim-nuri-gokhan-sonsel-yxl5o', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Denizler  kadar  derin, o masmavi  gözlerin,

Bulutlar  kadar  beyaz, yumuşacık  ellerin.

Kalbimde  demet, demet, içinde  binlerce  renk,

Buram,buram  sevda  kokan, taptaze  güzel  çiçek.

Bilmeyene  sanki  inat, aşık  olmak  büyük  sanat,

Deli  gönlüm  uçmak  ister, melek  gibi  takmış  kanat.

Hem  sevincim  hem  acımsın, yaşamaya  inancımsın,

Hasta  olan  şu  gönlüme,şifa  veren  ilacımsın.

Sen  benim  özümdesin, dilimde  sözümdesin,

Ağlarken  hicranımda,gülerken  yüzümdesin.

Gezdiğim  her  mekanda,senden  bir  iz  bulurum,

İçimi  sevdan  yakar,eriyip  kaybolurum.

Benim  güzel  çiçeğim, yatarken ben dizinde,

Güneş  parlar  yüzünde.

Yıldızlar  hayal  olur, kaybolur  gökyüzünde..

O  ipeksi  saçlarının,tiryakisi  olmuşum,

Sanki yalnız ben seni,sevmek  için doğmuşum.

Ver  elini  gidelim, hülyalı  rüyamıza,

El ele  tutuşarak,biz  kendi  dünyamıza.

Kimseler  karışmadan, bu derin sevdamıza,

Kalk gidelim  sevgilim,  biz  hayal  dünyamıza.

Ve  seninle  el ele ….mutlu  bir  çift  olalım.', 'Denizler  kadar  derin, o masmavi  gözlerin, Bulutlar  kadar  beyaz, yumuşacık  ellerin. Kalbimde  demet, demet, içinde  binlerce  renk, Bur...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/benim-guzel-cicegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Gelsin', 'o-gelsin-mehmet-yilmaz-ak-jpsw8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dökülecek içimde birikenler 

Yüzlerce kuş gibi bi karaltı olacak nefes alış verişlerim 

Ve ben kaybolacağım kendim olana dek 

Bir rüzgar sanki anılar ve bense bir yelkenli 

Sürükleniyorum durgun sularda azgın dalgalara 

Az ötemde beliriveriyor sahipsiz düşlerim 

Onlara dokunup gözyaşımı bırakıyorum 

Çocuksu elleriyle sarıyorlar beni 

Ve yakamoz özlemiyle bir rüya ya dalıyorum 

Her taraf göz kamaştıran büyüsüyle sevgiyi çağırıyor 

Duyulmuyor çığlıkların 

Gözlerimi açamıyorum 

Beklediğim gelene dek açmıyorum 

O gelsin 

Ellerimi alsın ellerine 

Uyandırsın beni 

Uyanmak istiyorum', 'Dökülecek içimde birikenler  Yüzlerce kuş gibi bi karaltı olacak nefes alış verişlerim  Ve ben kaybolacağım kendim olana dek  Bir rüzgar san...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Yılmaz Ak']::text[], 8.5, '{"poet":"Mehmet Yılmaz Ak","poet_slug":"mehmet-yilmaz-ak","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/o-gelsin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyhude Yere', 'beyhude-yere-nuri-gokhan-sonsel-fi97f', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Saat  şimdi  4.20, gecenin  karanlığı,

Yağmurlar  matem  tutmuş, ağlıyor  gibi.

Gözlerini  aradım, yağmur  damlalarında,

Sıcaklığını  düşündüm, beyhude  yere.

Hüzünlenmiş  bulutlar, hıçkırmaya  başladı,

Şimşekler, çığlık, çığlık   haykırdı.

Susun  dedim  susun… bari  siz   ağlamayın,

Akmasın  gözyaşınız, sakın  beyhude  yere.

Dile geldi  bulutlar, nasıl  biz  ağlamayız,

Bizde çok  üzgünüz, o  geri  gelmeyecek.

İstese de   dönemez, çıktığı yolculuktan,

Artık  sende  bekleme, onu  beyhude yere.', 'Saat  şimdi  4.20, gecenin  karanlığı, Yağmurlar  matem  tutmuş, ağlıyor  gibi. Gözlerini  aradım, yağmur  damlalarında, Sıcaklığını  düşünd...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/beyhude-yere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sudan Çıkan Balık Gibi', 'sudan-cikan-balik-gibi-mehmet-yilmaz-ak-6pw8j', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'dün gece sen uyurken 

ben bi yolculuğa çıktım 

zaman ve mekanın dışında kendi okyanusumun rüzgarlarıyla 

rotası bilinmez düşlerime kapılıp kayboldum 

ve sonra yakamozlarında seyrettim kendimi 

her baktığımda başka olan bulutlar gördüm 

ve onları çocukluğumdaki uçurtmalarım gibi yönlendirmek istedim 

ama sanki ipler koptu ellerim kanadı 

gece lambasının asfaltı öpen hüznünde geri geldim 

sudan çıkan balık gibi', 'dün gece sen uyurken  ben bi yolculuğa çıktım  zaman ve mekanın dışında kendi okyanusumun rüzgarlarıyla  rotası bilinmez düşlerime kapılıp k...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Yılmaz Ak']::text[], 8.5, '{"poet":"Mehmet Yılmaz Ak","poet_slug":"mehmet-yilmaz-ak","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sudan-cikan-balik-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmem farkında mısın', 'bilmem-farkinda-misin-nuri-gokhan-sonsel-ksbvf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'O ela gözlerinin, kapılmışım seline,

İnan kurban olurum, saçının her teline. 

Benim bir parçamsın sen, her zaman yanımdasın,

Seni çok  sevdiğimin, bilmem farkında mısın? 

Sabahın güneşinde, gecenin karasında,

Baktığım her noktada, senden bir iz bulurum.

Ağacın yeşilinde, baharın dallarında,

Çiçeğin kokusunda, senden bir renk bulurum.

Sıcacık ellerinde, müşfik tatlı dilinde,

O  ela gözlerinde, ben sevdayı bulurum.

Şiirin hecesinde, şarkıların sesinde,

Yaşamın ötesinde, yine seni bulurum.

Ben dünyaya gelirken, belki şanslı doğmuşum,

Aranan güzelliği, çünkü sende bulmuşum.

Sen benim canımdasın, sen benim kanımdasın,

Seviyorum seni ben, bilmem farkında mısın? 

Bu şiir, eşime ithaf edilmiştir.

N.Gökhan SONSEL', 'O ela gözlerinin, kapılmışım seline, İnan kurban olurum, saçının her teline.  Benim bir parçamsın sen, her zaman yanımdasın, Seni çok  sevdi...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bilmem-farkinda-misin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül', 'gul-yasar-tezel-l52vx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'gamzesi goncayı okşar

dudağı öpücük kuşu

yokuşu tırmandırır duruşu

dalında seyri sevdim

sallanır edalı yok korkusu

örtüsüne bürünmüş uslu

inandığı gibi dimdik durur

zikrinde dilini sevdim', 'gamzesi goncayı okşar dudağı öpücük kuşu yokuşu tırmandırır duruşu dalında seyri sevdim sallanır edalı yok korkusu örtüsüne bürünmüş uslu in...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Tezel']::text[], 8.5, '{"poet":"Yaşar Tezel","poet_slug":"yasar-tezel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gul-417-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmiyorum', 'bilmiyorum-nuri-gokhan-sonsel-o49qb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bilmiyorum nedendir, bana  bir  haller oldu,

Gönül bahçemde açan, bütün güllerim soldu.

Şiir yazmak istedim, engel oldu heceler,

İçime doldu birden, en karanlık  geceler.

Kötü  günler  geçirdim, acıdan daha acı,

Kendine köle yaptı, şu  hayatın kıskacı.

İsterdim ki kollarım, her zaman seni sarsın,

Ağlıyorum işte ben, büyüklük  bende kalsın.

Bana mektup  göndermiş, bir de  resim  koymuşsun,

Gözleri bulamadım, demek ki  kaybolmuşsun.

Dinle  bir tanem dinle, dinle şu sessizliği,

Bir defa da sen ben ol, düşün bu sensizliği.

Ne haldeyim bir tanem, sen bunu bilmiyorsun,

Yalvardım  yakardım da,  sen geri dönmüyorsun.

Ben sevginle yaşarken, hiç de mutlu olmadım,

Anladım ki gerçek bir, sevgili bulamadım.

Açacak  gonca  güldüm, dallarımı koparttın,

Sevda denen duyguya, ben kapımı kapattım.

Sanma ki ben sevdanla, kahrolup ölüyorum,

Çoktan unuttum seni, bak artık gülüyorum..', 'Bilmiyorum nedendir, bana  bir  haller oldu, Gönül bahçemde açan, bütün güllerim soldu. Şiir yazmak istedim, engel oldu heceler, İçime doldu...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bilmiyorum-69-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kasırgalar Esti', 'kasirgalar-esti-yusuf-onder-bahceci-ffv6l', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sabah kalktığımda havada bulut, mulut yoktu,

Şöyle bir gökyüzüne baktım, gökyüzü umut tu,

Öğleden sonra bir fırtına çıktı, umutları kuruttu,

Sadece fırtınamı Gül kasırgalarda esti tozuttu...', 'Sabah kalktığımda havada bulut, mulut yoktu, Şöyle bir gökyüzüne baktım, gökyüzü umut tu, Öğleden sonra bir fırtına çıktı, umutları kuruttu,...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kasirgalar-esti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir ben ağlamıyorum', 'bir-ben-aglamiyorum-nuri-gokhan-sonsel-ybyz3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gecenin  ortasında, gökyüzü  ağlıyordu,

Billurlaşmış  damlalar, düşerken  yeryüzüne. 

Sensizliğin  acısı, çökerken   yüreğime,

Bir  ben  ağlamıyordum… birde  suskun  dudaklar.

Güneş  şaşkın  ve  mahzun, mehtap  bundan  habersiz,

Yıldızlar  soruyorlar,gece  neden  çok  sessiz? 

Gözyaşları kurumuş, susmuş hıçkırık sesi,

Boğazına düğümlenmiş, duyulmuyor nefesi. 

Gençlik  mevsimi  bitti,şimdi  artık  sonbahar,

Mehtabın  ömrü  bile, gece  sabaha  kadar.

Diyor ki  Gökhan  Sonsel, bütün  sevgiler  ağlar,

Seven  kalpler  konuşsun, sussun yalan dudaklar', 'Gecenin  ortasında, gökyüzü  ağlıyordu, Billurlaşmış  damlalar, düşerken  yeryüzüne.  Sensizliğin  acısı, çökerken   yüreğime, Bir  ben  ağl...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-ben-aglamiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gün', 'bir-gun-nuri-gokhan-sonsel-20g9f', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir  gün  gelecek, sende   yaşlanacaksın,

Yüzüne  yılların, yorgunluğu  sinecek.

Güvenme gençliğine, sende  paslanacaksın,

O  yeşil  gözlerinden, yaşlar  inecek.

Bir  gün  gelecek, anılar da,  terk edecek,

Unutacaksın, geçmişte  yaptıklarını. 

Tüm   güzelliğini, zalim  yıllar  yok  edecek,

Hatırlamayacak  erkekler, sana  taptıklarını.

Bir  gün  gelecek, yaklaşacak  gecelerin  gölgesi,

Gelecekten  umut   yok, sanma   vardır  çaresi.

Etrafında  dost  kalmadı, tükettin  sen  herkesi,

Açlığından  yem  yapacak, seni  fındık faresi.', 'Bir  gün  gelecek, sende   yaşlanacaksın, Yüzüne  yılların, yorgunluğu  sinecek. Güvenme gençliğine, sende  paslanacaksın, O  yeşil  gözleri...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-gun-164-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırak', 'birak-nuri-gokhan-sonsel-27res', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bırak  artık  dokunma,  uyuyan yüreğime,

Uyanır da içimde,  bir iz’in kalmış sanır.

Yaralanan kalbime,  saplanan hançerini,

Unutur da gönlümde, ateşin yanmış sanır.

Huzur bırakmadın ki, ne duygumda ne bende,

Bırak  beni  ne olur,  yine kendi halimde.

Ne kadar git desem de,  bu sadece dilimde,

Dünyayı unutur da, seni mehtabım sanır.

Zehir gibi tattırdın, bu hayatın tadını,

Kimselere duyurmadım,  yine de feryadımı.

Bırak artık hiç sorma,  şu garibin halini,

Hasreti unutur da, geri dönmüşsün sanır.', 'Bırak  artık  dokunma,  uyuyan yüreğime, Uyanır da içimde,  bir iz’in kalmış sanır. Yaralanan kalbime,  saplanan hançerini, Unutur da gönlüm...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/birak-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitecek Hüzün', 'bitecek-huzun-nuri-gokhan-sonsel-lx86r', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aşk çiçeklerim, gonca, gonca,

Gülde hasret, sende sevda.

Dün gece, hayal bahçemde,

Can çekişen, bülbülü gördüm.

Ilık, ılık esecekse rüzgarlar,

İlkbahar, dudaklarda kahkaha.

Bahçemde, kopunca fırtınalar,

Ben, mevsim,mevsim ölürüm.

Gözlerinde nem, kalbinde hüzün,

Hazırlamış valizini, yine sonbahar.

Solmasın sararmasın, o güzel yüzün,

Bitecek bu hasret, dönünce bahar.

Açacak gelincikler, gönül bahçemde,

Gülecek kahkahalarla, ağlayan yüzün.

Gül’üne bülbüller, şarkı söylerken,

Bitecek bu ayrılık…bitecek hüzün.', 'Aşk çiçeklerim, gonca, gonca, Gülde hasret, sende sevda. Dün gece, hayal bahçemde, Can çekişen, bülbülü gördüm. Ilık, ılık esecekse rüzgarla...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bitecek-huzun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuklar Ağlamasın', 'cocuklar-aglamasin-nuri-gokhan-sonsel-bzlir', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kiminin  anası  yok, kiminin  babası  yok,

Kimi  köprü  altında, giyecek  abası  yok.

Kimi  çocuk  yurdunda,bir   çatının  altında,

Karınları  doysa da, sevecek  kimsesi  yok.

Ne olur  ki   onları, bazen  ziyaret   etsek,

Küçücük  bir  hediye, sevgimizle  götürsek.

Çocuk  sevgiyle  büyür, kendimizden  bilelim,

İçimizde  sımsıcak, sevgiyi  götürelim.

Niçin  geldi  dünyaya, onlar  mı  istemişti,

Sanki  doğurun  diye, telgraf mı  çekmişti.

Çocuk  daima  masum, kimden  doğarsa  doğsun,

Sevgimizi   paylaşalım, çocuklar  ağlamasın.

Toplumun  hatasını, niçin  bunlar  çekecek,

Sokaklarda  binlercesi,yok  olup  da   gidecek.

Uzatalım  çocuklara, tertemiz  elimizi, 

Kurtaralım  bu  hayattan, sunarak   sevgimizi.

İstiyor mu  sanırsın, kötü  insan  olmayı,

Her gün  tiner  koklayıp, toplumdan  dışlanmayı.

Ne olur  ki  bir  parça, aşımızı  paylaşsak,

Okutsak  adam  etsek, başımıza  taç  yapsak.

Hem  insanlık  görevi,  hem  dinlerin  gereği,

Bir  kere  bir  dinleyin, bu  onların   dileği.

Açlık  sefalet  zulüm, kaderleri   olmasın,

Ağlamasın  çocuklar…çocuklar  ağlamasın.', 'Kiminin  anası  yok, kiminin  babası  yok, Kimi  köprü  altında, giyecek  abası  yok. Kimi  çocuk  yurdunda,bir   çatının  altında, Karınlar...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/cocuklar-aglamasin-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni ara', 'beni-ara-sair-ozo-21-o6d2w', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kuytu köşelerde yalnız dolaşan 

Yaşamına küsmüş hali perişan

Duygularına kanıp aşkından tutuşan 

Birini görürsen beni hatırla 

Rüyayı bırakıp gerçeği arayan 

Kendini sadece sevgisine adayan 

Hayatında mutluluğu tadamayan 

Birini görürsen beni ara', 'Kuytu köşelerde yalnız dolaşan  Yaşamına küsmüş hali perişan Duygularına kanıp aşkından tutuşan  Birini görürsen beni hatırla  Rüyayı bırakı...', ARRAY['Türk Edebiyatı','Şiir','Şair Özo_21']::text[], 8.5, '{"poet":"Şair Özo_21","poet_slug":"sair-ozo-21","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/beni-ara-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '01Beynimdeki Sürrealist Yasaklar', '01beynimdeki-surrealist-yasaklar-ahmet-yozgat-65wyy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '1/:

Aynalar… 

Açık olun bana karşı.

Sathınıza yayılan buhur düşmanım

Ama uzanmalı asam hayalimdeki gün sarısına

Çıkıp bir kısrak terkinde

Kapısından doludizgin sivri fiziğin

Uzanmalı dudaklarım iştah ile

Ve hamarat parmaklarımın kınalı ucu

Beynimdeki sürrealizm yasaklarına.

2/:

Aynalar… 

Açık olun karşınızdakine karşı.

Kan kuyusu kazmayın şakaklarıma

Kırk satır istemem... Kırk katır verin

Düğümleyin atların kuyruklarına

Sevdalarımı gerin... Üstüne denizlerin

Kaldırın öpüşmelerimden karanlık kavramları

Sabırsız yüreğime Elemtere kurşunları damıtın

Hırsımın sivri ve Ferhatöldüren kayalarına

Batırın kan kırmızı sevdalarımı

Ve yol verin haramiler

Yorgun hicretimin mayalarına...

3/:

Aynalar… 

Ne zaman görüş günü öteki benin

Ya da tepetaklak dönüşü... Ne zaman aritmetiğin? 

5743’ün sırrıdır çaldığım azık

Artık ne gergin zülüfler zapteder beni

Ne de o kutba bağlı kozmik demirkazık

Kırk satır istemem... Kırk katır verin.

Çekilin Habeş’imin puslu yolundan

Boşaltın atların ölümsüz yularını

Beni cazipperest kederlerimin dehlizine yollayın

Sevdalarımı gerin Sirenler denizinde

Hacıbatmaz kalyonumun serenlerine.

Ve yol verin haramiler

Umutlu hicretimin umutkar ellerine…', '1/: Aynalar…  Açık olun bana karşı. Sathınıza yayılan buhur düşmanım Ama uzanmalı asam hayalimdeki gün sarısına Çıkıp bir kısrak terkinde Ka...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/01beynimdeki-surrealist-yasaklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değilim', 'degilim-nuri-gokhan-sonsel-iwpet', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sakın bahsetme, geçmiş günlerden,

Ben senin artık, avın değilim.

Mayamız killi, topraktan bizim,

Koklanıp da seçilen, kavun değilim.

Geçmiş mazide kalsın, sen bu güne bak,

Ayağını süsleyen, nalın değilim.

Seninle küçücük, bir aşk yaşadık diye,

Bir ömür boyu senin, malın değilim.

İkimizin de yolu, çoktan ayrıldı,

Her an arkandan gelen, kulun değilim. 

Bırak ta her şey, geçmişte kalsın,

Koleksiyonuna  ilave, pulun değilim.

Bende diğer erkekler gibi, aşık olmuşsam,

Hiçbir zaman  uğruna, ölen değilim.

Geçti gitti yaşanan, o güzel günler,

Ben sana yine aşığım ama,kölen değilim.

                                              ELVEDA', 'Sakın bahsetme, geçmiş günlerden, Ben senin artık, avın değilim. Mayamız killi, topraktan bizim, Koklanıp da seçilen, kavun değilim. Geçmiş ...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/degilim-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '01 Doru Dağdaki Gemiye Şiir', '01-doru-dagdaki-gemiye-siir-ahmet-yozgat-s577i', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '1/:

Yemekse aslolan,

Kendi doğurduğun elemlerini...

Ve zaferlerle  taçlanan başını a yar

Uzat ellerini... Yeşil koynuma.

Dağlara ta doru dağlara... 

Sevda ile kolkola.

***

Denizimin bulutlu bereketini

Bula... Durmadan çalkalanan sefinesinde

Yürekleri sağır, taşlaşmış korsanların

İçip... Bileklerinden sızan kutsi borcunu

Dayanıp sırtını küpeşteye

Ve göyaşına bulanmış yelkene sinip

Dağlara… Ta doru dağlara.

Özlem ile kolkola.

2/:

Dilberî denizlerin tek cömert eli

Okşuyor bak rüzgardaki yelemi anam gibi.

Bildik yağmurlar dağlıyor işte

Geceleyin göllerin gizemli ürpertisini.

Gör ey gözüm! Duy beynim! ...

Sirenler adımı haykırmada tuzlu sularda

Geciken düğününe deniz kızının

Hayıflanan kan yağıyor hediye

Tuz banıyor şiirim... Kalbinin bozkırlarına

Ve sunuyor altıgen tas içre

Afrodizyak ve müsekkin şerbet ekvator sıcağında

Teslim olan davaların kırık kargılı süvarisine.

Son zamanda dağlara ta dağlara…

Ölüm ile kolkola...

Dilberî suların tek cömert eli

Dağlarımı yalnız koma ne olur? 

Aşkıma acıkmış denizlerine ula! ...', '1/: Yemekse aslolan, Kendi doğurduğun elemlerini... Ve zaferlerle  taçlanan başını a yar Uzat ellerini... Yeşil koynuma. Dağlara ta doru dağ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/01-doru-dagdaki-gemiye-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '01 Sevdakâr Randevu', '01-sevdak-r-randevu-ahmet-yozgat-ir54f', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1/:

Zamanım dar dağlar elleşmeyin... 

Acele işim...

***

Randevum sevdam ile bu anın eşiğinde

Onun için saçlarım arpa tarlası

Ve ellerim terazi burcunda sabırsız yonca

Bilirim yüreğimdeki kardelenler zamansız

Ondandır işte derdimin ortağı dağlar

Gözlerimle... Gülüşüm... Ölümümde...

***

Ondandır işte kankardeşim dağlarım...

Oturup yolbaşlarına bu dem ben

Düğünümde halay halay ağlarım

Acele işim... Randevum sevdakâr

Ben sevdakârım…

2/:

Elleşmeyin zamanım dar dağlar,

Yol verin yorgun küheylanıma.

Kılıç kırığı taş yonganızla. 

Toynağımı yontmayın...

***

Sen ferman dinlemez, yol kesen bulut.

Ve bilirim zirveleriniz kaçak yuvası

Yol verin boynu bükük şiirlerime artık

Gelin heceleri ağlatmayın ortalık yerde

Basın bağrınıza... Kvramlardan oyduğum taşı

Güneşimle yaldızlansın otlukbeliniz

Uçurun kuşumu uzaklara ıssız seherde

Yüreğime divit misali bansın

Bansın ter ve çorak kokan elleriniz..

***

Zamanım dar dağlar

Bekletmeyin ağlarım

Acele işim...Randevum sevdakâr,

Ben sevdakârım…

3/:

Zamanım dar dağlar... Çekilin! 

Bilir misiniz dar zamanları? 

Nedir iki elin kana kesmesi? ...

Aldanmayın gözlerimden yağan karlara

Tesellimin kaynağıdır yaylaların ağıtları

Ve derunî tandırlarımdan göz kırpan ateş

Temmuza tutsak olan kışlara hayıflanmayın

Zaman içre aslanlar da alışır sıcak sulara

Bir banar... Bir diker gözünü zirvenize eş

Ola ki uzanırsa bakırdan döğdürdüğümüz pençelerimiz

Kış artığı ve savaş bozgunu rüzgarlara

Ve martta kardelen sevdalara

Ve darlara yağlı urgan olan yelelerimiz...

Onun için yüreğimiz yangın harmanı

Gözlerimiz ağlamaklı ak bulut.

O ki son umuttur yüreğimizin alt yanı

Dokunmayın omzumuza şimdi ağlarım

Acele işim...Randevum sevdakâr,

Ben sevdakârım…', '1/: Zamanım dar dağlar elleşmeyin...  Acele işim... *** Randevum sevdam ile bu anın eşiğinde Onun için saçlarım arpa tarlası Ve ellerim tera...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/01-sevdakar-randevu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Gözlerin Aklıma Geliyor', 'guzel-gozlerin-aklima-geliyor-yusuf-onder-bahceci-aoio9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Güzel gözlerin aklıma geliyor, gözlerimden yaş iniyor,

Beni seven dostlarım, çok meraklı güya seni soruyor,

Sen ellere gidelidir benim yüzüm gülmüyor gülmüyor,

Güzel gözlerin aklıma geliyor, gözlerimden yaş iniyor.

Şöyle bir bakayım dedim, albümlerde solan resmine,

Gözlerim dalıp, dalıp gitti kulak verdim suların sesine,

Allah''ım, ne olur sabır ver, sabır ver, bu naçiz eserine,

Güzel gözlerin aklıma geliyor, gözlerimden yaş iniyor.', 'Güzel gözlerin aklıma geliyor, gözlerimden yaş iniyor, Beni seven dostlarım, çok meraklı güya seni soruyor, Sen ellere gidelidir benim yüzüm...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/guzel-gozlerin-aklima-geliyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '01 Al Karanlık Yut Beni', '01-al-karanlik-yut-beni-ahmet-yozgat-7p114', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '1/:

Karanlıktır… Işıkları yaktıran

Hele loy loy! Yaktıran oy! ...

***

Gözlerimden yağmur yağar göklere

Çoban yıldızına silerim yanağımın terini

Örter hırçın çığlığını çayırlar saçlarımın

Nisansı nefesiyle karanlığın ağzında

Dudağımda martılar çığlık çığlığa

Şakağım alaca şafak...

Puslu bir mevsim örter başımı

Atarım adımımı sahibim karanlıklara.

***

Gece damlar... Karanlık sızar…

Yıldızların sarışın yalnızlığına.

Ellerim zifre banar beyaza uzanmak için.

Sorar gözlerim... Neredesin oy? 

Yüreğimin aradığı... Lahuti elinde kandil

Ve teslimiyet sızan bir arka koy

Hele loy loy loy! ...

2/:

Nerdesiniz aydınlıklar? 

Söyleyin kitabın orta yerinden, nerde? 

Hele loy loy, nerede? 

***

Çöller bataklık çağırır dört mevsimin enince

Kuruyan damağımda bir tutam çayır yeşerir

Çileye dolanır hayalimin artığı sevda kırığım

Arzular oyar cevherini zebercet ocağının

Açın kafesimi Allah aşkına dağlar

Kamaşsın gözlerim 

Isırgan aydınlıklarla...

***

Al karanlık yut beni

Bilirim sahibim gecelerdir... 

Işıkları yaktıran lahuti can kardeşimde.

Zifirin erimeyen orta yerinde

Sorar gözlerim oy oy! 

Halay kurar parmaklarım arka yüzümde

Hele loy loy loy! ...', '1/: Karanlıktır… Işıkları yaktıran Hele loy loy! Yaktıran oy! ... *** Gözlerimden yağmur yağar göklere Çoban yıldızına silerim yanağımın ter...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/01-al-karanlik-yut-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düştüm', 'dustum-nuri-gokhan-sonsel-dl0su', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Daha  dün, ergendim,

Zevk-ü  sefaya, düştüm,

Olgunluğa, eriştim,

Derd-i  devaya, düştüm.

Çırpınıp, debelerken,

Büyük belaya, düştüm.

Fasl-ı  Saba, okunurken,

Birden, neva’ya düştüm.

Rüzgar gibi, eserek,

Büyük vahaya,düştüm.

Hayatımı, boş geçirdim,

Sonsuz, hataya düştüm.

N.Gökhan SONSEL', 'Daha  dün, ergendim, Zevk-ü  sefaya, düştüm, Olgunluğa, eriştim, Derd-i  devaya, düştüm. Çırpınıp, debelerken, Büyük belaya, düştüm. Fasl-ı ...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/dustum-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '01 Vurmayın Cemâl’imi Kahpeler', '01-vurmayin-cem-l-imi-kahpeler-ahmet-yozgat-4sn3g', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '1/:

Hüzünlü gül düştü düşlerime,

Nisanın on beşinde sevdamın...

***

Doruğu gönendi Kaf dağımın masalda.

Sermayesi sevda olan pınarlar

Harladı rüyamın tarlalarına.

Sümbüller musallada demet demet ağladı... 

Turaçlar uçtular telek-tefek kabiristanda

Çiğ düştü hüznümün çorak yurduna

İstikbalin düşlerine gül düştü...

***

Belki gül değildi gelinler,

Düşen sümbül döşlü Cemâl’di... 

Vurulansa turaçlar diyarı Ürgüp

Mavzerdeki el zemheride buz...

Yürek kaskatı,

Dudaklar susuz Deşti Kebir’di sayın ki

Ya da, “Seçemedim sekişinden kıratı.”

2/:

Yani sayın ki gelinler,

“Arpa ektim biçemedim.”

Kan bürüdü düşümün yeşil yüzünü.

Gelinler ağıda durdu, yüreğim onlarla bile

Vurulan sümbül döşü Cemâl’in. 

Kavrulansa turaçlar yurdu Ürgüp...

Vallah, “Seçemedim sekişinden kıratı.”

Tetiği ısıran zulümkar parmak

Ağustosta harlı nâr

Yürek mi? ... Onu sormayın gelinler

Bileğim gibi kaskatı

Yani, “Seçemedim sekişinden kıratı.”', '1/: Hüzünlü gül düştü düşlerime, Nisanın on beşinde sevdamın... *** Doruğu gönendi Kaf dağımın masalda. Sermayesi sevda olan pınarlar Harlad...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/01-vurmayin-cemal-imi-kahpeler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kursağımdaki sevincim', 'kursagimdaki-sevincim-sair-ozo-21-j35me', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Uyku girmedi gözüme  bu gece 

Hep seni düşündüğümdendi

Yer arıyorum rutubetli odamda 

Kursağımdaki sevincimle

Biliyorum ki benim ki bir özlemdir 

Senin için sarılıyorum kalemime 

Birşeyler yazmak istiyorum ikimiz için

Gülüşünü hissediyorum dizelerimde', 'Uyku girmedi gözüme  bu gece  Hep seni düşündüğümdendi Yer arıyorum rutubetli odamda  Kursağımdaki sevincimle Biliyorum ki benim ki bir özle...', ARRAY['Türk Edebiyatı','Şiir','Şair Özo_21']::text[], 8.5, '{"poet":"Şair Özo_21","poet_slug":"sair-ozo-21","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kursagimdaki-sevincim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Gönül', 'ey-gonul-nuri-gokhan-sonsel-t91cc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ey  Gönül 

Ey   Gönül! 

 O  Seni  Unutup, Gelmezse  Eğer,

Acılar  Çekecek, İnleyecektin.

Sevdalı  Şarkılar, Türküler  Dizip,

Bir  Ömür  Boyu, Bekleyecektin.

Günlerce  Bir  Haber, Gelmedi  Diye,

Sevdanla  Yanarak, Kavrulacaktın.

Aradan  Haftalar, Yıllar  Geçince,

Sen  O’nu  Unutup, Kurtulacaktın.

Hani  Yüreğin  Bu  Aşkı, Unutacaktı,

İçindeki  Bu  Hasret, Avutacaktı.

Bir  Kuş  Kalbi  Gibi, Çırpınacaktı,

Sevdiğini  Unutup, Kurtulacaktın.

Uzaklaşan  Kalbine, Ses  Verir  Gibi,

Yüreğinden  Sevdayı, Devirir  Gibi.

Bir  Takvim  Yaprağı, Çevirir  Gibi,

Sen  Bu  Aşkı  Unutup, Kurtulacaktın.

                                                          Ne  Oldu? ..', 'Ey  Gönül  Ey   Gönül!   O  Seni  Unutup, Gelmezse  Eğer, Acılar  Çekecek, İnleyecektin. Sevdalı  Şarkılar, Türküler  Dizip, Bir  Ömür  Boyu...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ey-gonul-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceler.  iki', 'geceler-iki-nuri-gokhan-sonsel-y8lo9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Geceler  çok  güzeldir, karanlık  olsa  bile,

Şair’e  ilham  verir, yıldızlar  güle, güle.

Geceler  ayaz  olur, gök kubbenin  altında,

Aşıklar  hayal  kurar, olmaz  bile  farkında.

Geceler  dinlendirir, derdi-gam’ı  dağıtır,

Geceler  hüzünlüdür,sevenleri  ağlatır.

Geceler  bir  başkadır, yıldızlarla  yüzülür,

Geceler  bitmek  bilmez, dertli  olan  üzülür.

Geceler  romantiktir, hey şey  bir  anda  biter,

Geceler  aşk  vaktidir, üstünü…örter  gider.

Geceler  ninni  söyler, yorgunları  uyutur,

Geceler  dalgın  olur, bir  çok  şeyi  unutur.', 'Geceler  çok  güzeldir, karanlık  olsa  bile, Şair’e  ilham  verir, yıldızlar  güle, güle. Geceler  ayaz  olur, gök kubbenin  altında, Aşıkl...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/geceler-iki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel', 'gel-nuri-gokhan-sonsel-j2avw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevdiğimi  biliyorsan,

Bana, güzel  yüzünle gel.

Anlamazsan, sen bu  aşkı,

Kır  çiçeğim,hüzünle  gel.

Sevda  nedir,bilmiyorsan,

Öğren  nedir, bilince  gel.

Gönlüm  yorgun, üzme beni,

Gözyaşımı, silince gel.

Madem  şimdi, gelmiyorsun,

Bari  gece, düşümde gel.

Kalbim  sensiz, üşüyünce,

En  son  yaprak,düşünce  gel.

Aşk  ateşim, küllenmeden,

Sevmek nasıl, bilirken  gel.

Yaşanmıyor, sensiz hayat,

Son anımda…ölürken gel.', 'Sevdiğimi  biliyorsan, Bana, güzel  yüzünle gel. Anlamazsan, sen bu  aşkı, Kır  çiçeğim,hüzünle  gel. Sevda  nedir,bilmiyorsan, Öğren  nedir...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gel-285-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme', 'gitme-nuri-gokhan-sonsel-ee915', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Neden  gözlerin  nemli,

Söyle..niçin  ağladın? 

Kendine  bunca  yıldır, 

Bir  dost mu  bulamadın…

Yüzün pek  solgun  göründü,

Kırdılar mı  kalbini? 

Neden  böyle, üzgünsün,

Anlat…bana  derdini.

Gülüm  isen, ben  diken’im,

Gemim  isen, ben  yelkenim.

Dertlerine,ortak  benim,

Ben  dostunum, be  güzelim…

Mutlu  olmak  istiyorsan,

Yüreğini, ısıt da  ver.

Sevinçlerin, sende  kalsın,

Dertlerini… bana  gönder.

Ağlama  bir tanem, böyle  sakın  ağlama,

İstemem  gözlerinde, en  ufacık  bir  nem’i

Ben  seni  seven …tek  dostunum,

Gitme…gitme…sende  terk  etme  beni..

                                          Ne  Olur…Ne  Olur  gitme…', 'Neden  gözlerin  nemli, Söyle..niçin  ağladın?  Kendine  bunca  yıldır,  Bir  dost mu  bulamadın… Yüzün pek  solgun  göründü, Kırdılar mı  k...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gitme-168-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baharda Aşk Başlar', 'baharda-ask-baslar-yasar-tezel-58wzh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kır çiçeğimsim 

Tutam tutam papatyalar

Seviyor sevmiyor

Kalbimde yersiz korkular

Her bahar yaşanan

Çiğdemlerle başlayan aşklar

Duygular nisan yağmurundalar

Islanır sağnağında aşıklar

Aşk baharda başlar', 'Kır çiçeğimsim  Tutam tutam papatyalar Seviyor sevmiyor Kalbimde yersiz korkular Her bahar yaşanan Çiğdemlerle başlayan aşklar Duygular nisa...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Tezel']::text[], 8.5, '{"poet":"Yaşar Tezel","poet_slug":"yasar-tezel","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/baharda-ask-baslar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güller de ağlar', 'guller-de-aglar-nuri-gokhan-sonsel-mqtvv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sonbahar  geri geldi, sarartıp  yoncasını,

Döktü  senin  gönlünün, en  renkli  goncasını.

Bu  mevsim  ki  yaralayıp, kanatacak  kalbini,

Kimseler  bilmeyecek, bu  perişan  halini…

Duymayacak  hiç  kimse, sevda  şarkılarını,

Kahredip de  susarken …senin  intizarını.

Dayanamazsın  bülbül…sen  kışın  gecesine,

Bir  gün  yenik  düşersin…ölümün  pençesine.

Gel  gidelim  be  bülbül, rüzgarlar  sert  esiyor,

Senin  sesin  kısılmış, nefesin  kesiliyor.

Gidilecek o  yerde, akşam  güneş  batmıyor,

O  kadar  çok  güzel  ki…burayı  aratmıyor.

Hele   mevsim  değişsin, tekrar  geri  dönersin,

Sevdiğin  her bir  güle, yine  şarkı  söylersin.

Gel  gidelim  be  bülbül,  uzun  etme…gidelim,

Güller  tekrar  açınca, ikimiz  bir  dönelim. 

Bülbül  beni  duymuyor, için, için  inliyor,

Güller  nefes  almadan, konuşmayı  dinliyor.

Hıçkırıklar  içinde, gitmem….diye   bağırıyor,

Bahçedeki  tüm  güller, sevincinden  ağlıyor.

Güller  artık   mutludur, yaş  akarken  gözünden,

Aşk   yemini   etmişti ….dönmüyor   bak  sözünden 

İşte  gerçek  aşk  budur ….bülbül  aşık  gülüne,

Gönlünde   sevdasıyla …meydan  okur  ölüme.

N.Gökhan SONSEL', 'Sonbahar  geri geldi, sarartıp  yoncasını, Döktü  senin  gönlünün, en  renkli  goncasını. Bu  mevsim  ki  yaralayıp, kanatacak  kalbini, Kim...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/guller-de-aglar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülnihal’im', 'gulnihal-im-nuri-gokhan-sonsel-bwdhj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Küçücük bir kız vardı, yılların ötesinde,

Zarafet ve güzellik, sevgi vardı sesinde.

Gözleri ışıl, ışıl, dostluk vardı yüzünde,

Minicik bir kuş  gibi, hayatın pençesinde.

O dostluğun kanatsız, perisi gibi,

Masumiyet ve saflığın, simgesi idi.

Her mısrada konuşan, şiirin dili,

Gül Nihal ‘im bir tanem, sırdaşım idi.

Ağlama içimde, sızlayan yürek, 

Sen o’nu  geri,  getiremezsin.

Hüznünde birikmiş, bu gözyaşını,

Ne yapsan kurutup, bitiremezsin. 

Haberi duydum, çılgına döndüm,

Yalandır demiştim, bin bir umutla.

Sanma ki Nihal, sen tek başına,

Seninle beraber, ben o gün öldüm.

Sana sesleniyorum, ey karanlığın dehlizi,

O’nu  aldıysan eğer, durulsun artık,

Sükut bulsun, şu ölümün denizi.', 'Küçücük bir kız vardı, yılların ötesinde, Zarafet ve güzellik, sevgi vardı sesinde. Gözleri ışıl, ışıl, dostluk vardı yüzünde, Minicik bir k...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/gulnihal-im-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üç ay', 'uc-ay-sair-ozo-21-ohlzy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Üç ay geçti aradan,sorarsın diye bekledim

İçimdeki özlemi sevgiyle yoğurdum 

Ancak bu kadar dayanabildim

Geçen zamanda senin için nelere katlanmadım ki

Hırçınlığımda senin için yumdum gözlerimi 

Ancak yinede benim için bir kıyım değildi

Oysa sen olanları çoktan unutmuştun

Üç ayda bir selamı bile çok görmüştün bana', 'Üç ay geçti aradan,sorarsın diye bekledim İçimdeki özlemi sevgiyle yoğurdum  Ancak bu kadar dayanabildim Geçen zamanda senin için nelere kat...', ARRAY['Türk Edebiyatı','Şiir','Şair Özo_21']::text[], 8.5, '{"poet":"Şair Özo_21","poet_slug":"sair-ozo-21","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/uc-ay-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mahkum', 'mahkum-sevgul-kilicaslan-o2fd5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni  sensiz yaşarken.. Kime isyan edeyim..

Beni sensiz bırakan kaderime mi..? 

Gözlerine mahkum eden sana mı? 

Tutsağın oldum.. Senden kopamıyorum..

Ne yapsam seni unutamıyorum..! 

Kalbime hapsettim ben seni…

İstemem artık beni sevmeni..

Ne kadar özlesem de seni...

Kör ettim gözlerimi; 

Görmesinler diye seni..

Sevdamızın uğruna.. Bu Can''ı harcadın..

Kurtuluşu sen.. Bensizlikte yaşadın..

Ne kadar..

Bensizliğe mahkum etsen de kendini..

Bir gün firarı‘ı yaşayacaksın..

Kalbimde ki hapishaneye..

Gönüllü Tutsak olacaksın..

http://www.kircicekleri.com/mahkum.html

http://www.sevgulce.com/sevgul/index.htm', 'Seni  sensiz yaşarken.. Kime isyan edeyim.. Beni sensiz bırakan kaderime mi..?  Gözlerine mahkum eden sana mı?  Tutsağın oldum.. Senden kopa...', ARRAY['Türk Edebiyatı','Şiir','Sevgül Kılıçaslan']::text[], 8.5, '{"poet":"Sevgül Kılıçaslan","poet_slug":"sevgul-kilicaslan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/mahkum-55-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hakkım değil mi', 'hakkim-degil-mi-nuri-gokhan-sonsel-r0erc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Saçlarının  rengini, alev  sanmış  yanmıştım, 

Gözlerinde  kocaman, zümrüt  saklı  sanmıştım.

Gitme  ne olur   bu  gece, yanımda  kal  bir tanem,

Gül  yüzünü  koklamak, sevmek  hakkım  değil  mi? 

Seni  ne  çok  sevmiştim, bunu  hiç  anlamadın,

Ne  bir  selam  gönderdin, nede  bir  gün  aradın.

Alışmadım  bir  tanem, inan  ki  sensizliğe,

Mahkum  ettin  sen  beni, bu  derin  sessizliğe.

Benden uzak  dışımda, ne  varsa  benden  öte,

Sevdam  beni  sürükledi, ardımdan  ite, ite.

Kırılmış  kanatlarım, uçamadım  bir tanem,

Sevdalı bir kuş gibi, uçmak hakkım değil mi? 

Yalancısın diyorsun, hiç  yalan  söylemedim,

İnan ki  senden  başka, hiç  kimseyi  sevmedim.

Gözlerime  bakarsan, hemen  bunu  anlarsın,

Dudaklar  yalan  söyler, gözler  yalan  söylemez.

Yıkılsam  paramparça, kanatlanıp da  uçsam,

Birken  kendi  kendimde, yine  binlerce  olsam.

Ve  sadece  kendime, kendim  için  ağlasam,

Bu  kadar da  gözyaşı, benim  hakkım  değil  mi? ...', 'Saçlarının  rengini, alev  sanmış  yanmıştım,  Gözlerinde  kocaman, zümrüt  saklı  sanmıştım. Gitme  ne olur   bu  gece, yanımda  kal  bir t...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hakkim-degil-mi-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayal Bahçemde', 'hayal-bahcemde-nuri-gokhan-sonsel-bx0pc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bülbül  gayet  neşeli, güller  goncayla  dolmuş,

Renk  değiştirmiş  laleler, çiğdemler  gelin  olmuş.

Süslenmiş papatyalar,yeni  bir  gün bitiyor,

Benim hayal  bahçemde,bütün  kuşlar  ötüyor.

Geceler dans  vaktidir, her  çiçekten  gelecek,

Kırlangıç  ve  sinekler, hep el  ele  verecek.

Ateş  böcekleri,  aydınlatacak   pist’i,

Çekirgeler  bu  gece, öğretecek  tvist’i…

Kelebekler  raks  edip, bütün  gece  uçacak, 

Karıncalar  durmadan, yiyecek  taşıyacak.

Ağustos böcekleri, kalırlar  mı  hiç  geri,

Şarkılar  söyleyecek, inletecek  her  yeri.

Doğa  mutlu  mu  mutlu, mehtabıyla  gülüyor,

Şimdi  sabah  olacak, bunu  herkes  biliyor.

Yalnız  akşam  sefası, dönüyor  uykusuna,

Benim  hayal  bahçemin, en  tenha  kuytusuna.

Sarmaşıklar  göz göze, rengarenk  açacaklar,

Bir  haftalık  yavrular, çırpınıp  uçacaklar.

Güneş  tekrar  batınca,kaybolacak  ışıklar,

Benim  hayal bahçemde,dolaşacak aşıklar.', 'Bülbül  gayet  neşeli, güller  goncayla  dolmuş, Renk  değiştirmiş  laleler, çiğdemler  gelin  olmuş. Süslenmiş papatyalar,yeni  bir  gün bi...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hayal-bahcemde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birlik Olalım', 'birlik-olalim-sacide-yaylaz-wuulw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bahar bayramı bu gün

Doğsun güneş yurduma

Yeşersin bağım,bahçem

Açsın rengarenk çiçekler

Yürekler coşsun çağlasın

Bahar bayramım bu gün

Çalsın davullar çalsın sazlar

Oynansın horonlar,

Çekilsin  halaylar

Tutulsun, kenetlensin eller

Yaşanmasın acılar

Akmasın gözlerden yaşlar

Bileklere kelepçe yerine 

Takılsın papatyadan halkalar

Sen,ben,o olmasın

Biz olalım birlik olalım 

Söylensin türküler 

Yaşayalım özgürce

Bahar bayramı bu gün', 'Bahar bayramı bu gün Doğsun güneş yurduma Yeşersin bağım,bahçem Açsın rengarenk çiçekler Yürekler coşsun çağlasın Bahar bayramım bu gün Çals...', ARRAY['Türk Edebiyatı','Şiir','Sacide Yaylaz']::text[], 8.5, '{"poet":"Sacide Yaylaz","poet_slug":"sacide-yaylaz","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/birlik-olalim-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herkesin Bir Derdi Var', 'herkesin-bir-derdi-var-yusuf-onder-bahceci-34b7i', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Görmezmisin günebakanlar bile Güneşe bakar,

Herkesin, bir derdi vardır, dertleri, kâlbine akar,

Herkeste bir telaş, herkes kendi derdine bakar,

Herkesin, bir derdi vardır, dertleri, kâlbine akar...', 'Görmezmisin günebakanlar bile Güneşe bakar, Herkesin, bir derdi vardır, dertleri, kâlbine akar, Herkeste bir telaş, herkes kendi derdine bak...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/herkesin-bir-derdi-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç düşündün mü', 'hic-dusundun-mu-nuri-gokhan-sonsel-vkw7g', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hayat  neden  acımasız …hiç  düşündün  mü? 

Düşündün mü…geçen  her bir saniyenin, sendeki  önemini? 

Yırt  parçala  at  artık içindeki   perdeleri,

Yok  et ve  bitir….bu  karanlık  geceleri.

Evvela  gözlerinde,karanlık  aydınlansın,

Tatlı  bir  tebessüm, aydınlatsın  yüzünü.

Sonra   yavaş, yavaş  tatlı  bir  gülücük iniversin kalbine

Sanki bir güneş  gibi, aydınlatsın  içini…

Yeni  doğmuş  bir  bebeğin, bütün duygularını,

Dudağında  beliren, sahtesiz  tebessümü.

Gelecekten  ümidi   ve  sanki  bu  sabah,

Yeniden …yeniden  doğmuş  gibi,

e  hiç  bir  zaman,  mutsuz  olmamış  gibi,

Mutlu  olmayı, acaba  hiç  düşündün  mü? ...

İlkbaharda  canlanan,  doğayı   düşün,

Taptaze   açılmış,  bütün   gülleri  düşün.

Dalları  çiçeği, yaprağı  düşün

Ve  bir  daha…bir  daha…kendini  düşün.

Ne  olur  ilk  defa…mutlu  olmayı  düşün.

İçinde  büyüyen  filizi  düşün, 

Yıldızı  mehtabı, güneşi  düşün.

Seni  çok  seven,  eşini  düşün,

Kahrolup  üzülen dostları…dostları  düşün.

Haline  gülecek, düşmanı  düşün,

Ve  içinde  bir  yerde,  mutlu  olmayı  düşün.

Karar  ver  kahkahaya, hıçkırık duyulmasın,

Karar  ver  mutluluğa, yüzün  artık  solmasın.

Karar  ver  aydınlığa, hayatın kararmasın,

Ve  içinde  geceler, zindan  olup  kalmasın.

Gülmek  sana  yakışıyor   Gökhan! ...

Tekrar  eskisi  gibi….gülmeyi   düşün…', 'Hayat  neden  acımasız …hiç  düşündün  mü?  Düşündün mü…geçen  her bir saniyenin, sendeki  önemini?  Yırt  parçala  at  artık içindeki   per...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/hic-dusundun-mu-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anammmmm ! ! ! !', 'anammmmm-mevlut-bicik-p4goq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Cennet gizlenmiş senin ayağının altında.

Senin rızan makbûl’dür,Rabbimin katında.

Hep senin duânla ayakta kaldım,yıkılmadım,

Cennete giderken,al benide yanıbaşında,atında.

Bütün  (ana)  lara sevgiyle,hürmetle ithâf olunur.

Mevlüt Bicik

21.03.2006  saat  12.33

Esslingen', 'Cennet gizlenmiş senin ayağının altında. Senin rızan makbûl’dür,Rabbimin katında. Hep senin duânla ayakta kaldım,yıkılmadım, Cennete giderke...', ARRAY['Türk Edebiyatı','Şiir','Mevlüt Bicik']::text[], 8.5, '{"poet":"Mevlüt Bicik","poet_slug":"mevlut-bicik","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/anammmmm-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masalımsın', 'masalimsin-sevgul-kilicaslan-6b1mz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni..Senden çok sevdim..

    Bunu sen bilmedin.

Gitme diye yalvardım..

     Beni hiç dinlemedin.

Beklemekle geçti,bu yıllarım..

Seni özlemekten, agardı bak saçlarım

Yollarına bakmaktan,tükendi gözyaşlarım..

Agzımdan cıkmadı hiçbir zaman

Ne beddua..Ne ahım..! ! 

Ömrümün  hazanında..

Tutundugum dalımsın

Her zaman bu bedenim de..

Taşıdıgım canımsın..

Sen benim okudugum,

                  en guzel kitabımsın…

    Her gece anlattıgım…

                       Aynı masalımsın..! !', 'Seni..Senden çok sevdim..     Bunu sen bilmedin. Gitme diye yalvardım..      Beni hiç dinlemedin. Beklemekle geçti,bu yıllarım.. Seni özleme...', ARRAY['Türk Edebiyatı','Şiir','Sevgül Kılıçaslan']::text[], 8.5, '{"poet":"Sevgül Kılıçaslan","poet_slug":"sevgul-kilicaslan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/masalimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzün Çiçeğim', 'huzun-cicegim-nuri-gokhan-sonsel-fd1az', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bilmem hatırlar mısın? ...denize hakim bir tepede eviniz…

Bahçenizde…asmalar, akasyalar, mor sümbüller,

Dağlarda güller ve bülbüller vardı.

Kor gibi yakan gözlerin, çıplak ayakların,

Mağrur bakışın, sen ve ben.

Bir de içimizde, hiç tükenmeyen…sevdamız vardı.

Daha yaşın o zaman, on beş bile değildi,

İnatçı mı inatçı bir yapın, ama sağlam bir bedenin,

Dudaklarda gülücük, kalbimizde…aşk vardı.

Bilmem hatırlar mısın? ...ceviz ağaçlarını? ..

Hani…ellerimiz boya içinde kalır da, kumlarla ovalardık.

Ya…balık tuttuğumuz, o küçücük körfezi? ...

Yağmur yağdığı zaman, toprak…

Buram, buram kokar, buhar, buhar tüterdi…

Şimdi ne oldu o güzelim, geri gelmez günlere? 

Zaman mı çok değişti, yoksa bizler mi değiştik? ...

Aradan yıllar geçti, aşkımız unutuldu, 

Gerçekten unutuldu mu dersin? 

O bitmeyen sevdamız, o yanan yüreğimiz..

Edilen aşk yemini unutuldu mu? ...

Bilmiyorum ne dersin? gerçekten …unutuldu mu? 

Bir akşam bir araba yanaştı…satılmıştı eviniz,

Satılmıştı o bitmeyen sevdamız…satılmıştı bitmişti…

Üç kuruşa dünyamız…gayet iyi hatırlıyorum,

Gözlerin yaşlı, mağrur bakışın bedbin,

Çökmüştü omuzların…

Terk edip gidiyordun, gidiyordun…

Sanki uçarcasına, benden kaçarcasına…

Duydum hemen evlenmişsin…mutlu bitmemiş sonun…

Eşin seni terk etmiş, almış çocuklarını…

İncitmiş seni, kırmış hassas kalbini.

Anlaşıldı yok etmiş, sendeki tüm benliği,

İçin, için bitirmiş, sendeki güzelliği…

Gözlerinde gülücük, hüzünlere karışmış,

Hüzün çiçeği gibi, aynı…benimki gibi.

Ne olur ağlama, benim hüzün çiçeğim,

Ne olur ağlama…ağlama…

Ağlatma beni, hüzün çiçeğim….', 'Bilmem hatırlar mısın? ...denize hakim bir tepede eviniz… Bahçenizde…asmalar, akasyalar, mor sümbüller, Dağlarda güller ve bülbüller vardı. ...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/huzun-cicegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimdeki Duygular', 'i-cimdeki-duygular-nuri-gokhan-sonsel-0wzp2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bulutlarla perdelenmiş, batan akşam güneşi,

Koyu bir gölge düşmüş, içimdeki geceye.

Kalbimdeki rüzgarlar, dalga,dalga yükselmiş,

Sarmış bütün ruhumu, içimdeki fırtına.

Gökyüzü matem tutmuş, efkarlanmış bulutlar,

Karanlığa mahkum olmuş, içimdeki yıldızlar.

Her damla sele dönmüş, götürmüş bedenimi,

Atmış bir kör kuyuya, içimdeki yağmurlar.

Sonra sana rastladım, kalbim bomboştu benim,

Birden yeşeriverdi, içimdeki duygular,

Ortasından ayrıldı, yırtıldı bu perdeler,

Aydınlığa kavuştu, içimdeki karanlık.', 'Bulutlarla perdelenmiş, batan akşam güneşi, Koyu bir gölge düşmüş, içimdeki geceye. Kalbimdeki rüzgarlar, dalga,dalga yükselmiş, Sarmış bütü...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/icimdeki-duygular-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçük Umutlar 3', 'kucuk-umutlar-3-yahya-ozcan-ftmjn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne kuytularda ağla,

Nede ıslansın yüreğin gözyaşlarıyla

Ama olsun yinede güneşimiz.

Hem dünyamızı hem yüreğimizi 

Hem ısıtsın hem aydınlatsın diye

.................................................................', 'Ne kuytularda ağla, Nede ıslansın yüreğin gözyaşlarıyla Ama olsun yinede güneşimiz. Hem dünyamızı hem yüreğimizi  Hem ısıtsın hem aydınlatsı...', ARRAY['Türk Edebiyatı','Şiir','Yahya Özcan']::text[], 8.5, '{"poet":"Yahya Özcan","poet_slug":"yahya-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kucuk-umutlar-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçük Umutlar 4', 'kucuk-umutlar-4-yahya-ozcan-4ru5n', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ya sen fazlasın bu şehre,

Ya da bu şehirler çok fazla,

Ya unutmalı ya da yakmalı,

Ama yinede isyanlar çok fazla

Zor, çok zor....

Yaşamak zor, sevmek zor,

Ama yinede ölmek çok fazla

.........................................................', 'Ya sen fazlasın bu şehre, Ya da bu şehirler çok fazla, Ya unutmalı ya da yakmalı, Ama yinede isyanlar çok fazla Zor, çok zor.... Yaşamak zor...', ARRAY['Türk Edebiyatı','Şiir','Yahya Özcan']::text[], 8.5, '{"poet":"Yahya Özcan","poet_slug":"yahya-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kucuk-umutlar-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnan Bana…', 'i-nan-bana-nuri-gokhan-sonsel-fnzqg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her  sabah  yalnız  uyandığımda, istiyorum ki,

Şu  sabahın  köründen, gece  yarılarına  kadar,

Bülbüller  senin  için  ötsün, şarkılar  söylesin,

Aşkımı  fısıldasın…mahşere  dek…inan  bana…

Her  ismini  anışta, boğazım  boğum, boğum  oluyor,

Her  ismini  anışta, haykırmak…haykırmak  istiyorum..

Sevdiğimi  duyurmak  için…inan  bana…

Seni  her  hayal  edişte, saçlarının  kokusunu,

O  masmavi  gözlerini  özlüyor.yüzlerce  kez…

Yüz binlerce  kez,  ölüyorum,  ölüyorum…ölüyorum, 

                                                                   inan  bana.. 

Burada  değişen bir  şey  yok …güneşin  doğuşu

Yine  eskisi   gibi, kuşların  ötüşü  hiç  değişmedi.

Yalnız  değişen  bir  ben  varım, daha  çok,  daha  çok,

Daha  çok  seviyorum,  daha çok….inan  bana…

Yalnızlığımı  martılarla  paylaşıp, 

Sana  selam  gönderdim,

Bu   rıhtımdan  kalkan, her  gemiyle, 

Öpücükler  gönderdim,  geldi mi  sana? 

Ölüm  sende… seninle  güzel…inan …inan  bana…', 'Her  sabah  yalnız  uyandığımda, istiyorum ki, Şu  sabahın  köründen, gece  yarılarına  kadar, Bülbüller  senin  için  ötsün, şarkılar  söyl...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/inan-bana-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen ve Ben', 'sen-ve-ben-sevgul-kilicaslan-jz237', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Beni dertlerin deryasında bırakan

Zamansız aşk kapımı kapatan

Gönül sayfamdan geriye kalan

Hatırlayınca yüregimi sızlatan 

Sensin..sen

Ne vardı, böyle çekip gidecek

En güzel yerinde bu aşkı bitirecek

Bilemezdim gözlerim sana hasret dünya ya veda edecek

Seni mahşer de bile bekleyecek olan

Benim..ben', 'Beni dertlerin deryasında bırakan Zamansız aşk kapımı kapatan Gönül sayfamdan geriye kalan Hatırlayınca yüregimi sızlatan  Sensin..sen Ne va...', ARRAY['Türk Edebiyatı','Şiir','Sevgül Kılıçaslan']::text[], 8.5, '{"poet":"Sevgül Kılıçaslan","poet_slug":"sevgul-kilicaslan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sen-ve-ben-182-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçük Umutlar 5', 'kucuk-umutlar-5-yahya-ozcan-cmdyj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gidişim olmaz artık

Dönüşlerdeyim....

Ayrılıklar yok artık

Senin sevginleyim,

Ne yalnız bırakırım seni,

Nede kaybolurum sinsice.

İstediğin buysa eğer,

Aradığın mutluluk bende...

................................................', 'Gidişim olmaz artık Dönüşlerdeyim.... Ayrılıklar yok artık Senin sevginleyim, Ne yalnız bırakırım seni, Nede kaybolurum sinsice. İstediğin b...', ARRAY['Türk Edebiyatı','Şiir','Yahya Özcan']::text[], 8.5, '{"poet":"Yahya Özcan","poet_slug":"yahya-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kucuk-umutlar-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnanma Sakın', 'i-nanma-sakin-nuri-gokhan-sonsel-x17lj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Unuttum  demiştim, yıllar  öncesi,

Ayrıldık  ikimiz, bir  yaz  gecesi.

İçimde  kanarken,aşkın  pençesi,

Unuttum  desem de, inanma  sakın.

Unuttum  demiştim, güzel  yüzünü, 

Unuttum  demiştim, yeşil  gözünü,

Unut  gitsin  sende, bu  son sözümü,

Unuttum  desem de,  inanma sakın.

Unuttum  demiştim, bakışlarını,

Unuttum  demiştim, bahar kokunu.

Kalbimde  saklarken, aşkın okunu,

Unuttum  desem de, inanma  sakın.

Unuttum  demiştim, mutlu günleri,

Unuttum  demiştim, şarkılarını,

Hissederken  sesinin,yankılarını,

Unuttum  desem de, inanma sakın.

Unuttum  demiştim, anılarımı, 

Unuttum  demiştim, senin  adını.

Ne  olur   bir tanem, duy  feryadımı,

Unuttum  desem  de,inanma  sakın.

N.Gökhan SONSEL', 'Unuttum  demiştim, yıllar  öncesi, Ayrıldık  ikimiz, bir  yaz  gecesi. İçimde  kanarken,aşkın  pençesi, Unuttum  desem de, inanma  sakın. Un...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/inanma-sakin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostunu Öğrenmek İstersen', 'dostunu-ogrenmek-i-stersen-yusuf-onder-bahceci-k5oge', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sakın param yok deme, aç gez ama tok sallan,

Sakın malım çok deme, az savur, çokça kazan,

Dostu öğrenmek istersen, eşşeğini bir istesen,

İnan eşşek ahırda yok derse eşşek anırır bilsen...', 'Sakın param yok deme, aç gez ama tok sallan, Sakın malım çok deme, az savur, çokça kazan, Dostu öğrenmek istersen, eşşeğini bir istesen, İna...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/dostunu-ogrenmek-istersen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstemiyorum', 'i-stemiyorum-nuri-gokhan-sonsel-d8r24', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yalvarman  yakarman, nafile  bana,

Bin  acı  bin  cefa, çektirdin  bana.

İstemem  git  artık , çok  uzaklara, 

Ben  senin  aşkını, istemiyorum.

Sen  gittiğinde, mevsim  bahardı,

Geçmişten  bu  güne, anılar  kaldı.

Şefkat ’e  sevgiye, lüzum  kalmadı,

Ben  senin  aşkını, istemiyorum.

Sanma ki muhtacım, ben  artık sana,

İstemem  ellerini, avuçlarımda.

Yeter ki  bir iz,kalmasın  bana,

Ben  senin aşkını, istemiyorum.

Ben  sana  gelmiştim, koşarcasına,

Yüreğim  bu  tenden,çıkarcasına.

Terk  edip  giderken, kaçarcasına,

Ben senin  aşkını, istemiyorum.', 'Yalvarman  yakarman, nafile  bana, Bin  acı  bin  cefa, çektirdin  bana. İstemem  git  artık , çok  uzaklara,  Ben  senin  aşkını, istemiyor...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/istemiyorum-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yolcudur Sevdam', 'yolcudur-sevdam-sevgul-kilicaslan-ne41m', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir gun bu dunyadan giderken

         olecegime degil..

Bir daha seni goremeyecegime

         yanarim..

Son nefesim de yine adini anarim

Bir kez daha seni hayal ederek

    Gozlerimi kaparim...

Benim icin,sakin uzulme..! 

 Gulup gec,benim halime..

    Askimi; gomdum ben kalbime..! 

Yolcudur SEVDAM

Benim ile kabrime..! ! 

www.sevgulce.com/sevgul/id4.htm', 'Bir gun bu dunyadan giderken          olecegime degil.. Bir daha seni goremeyecegime          yanarim.. Son nefesim de yine adini anarim Bir...', ARRAY['Türk Edebiyatı','Şiir','Sevgül Kılıçaslan']::text[], 8.5, '{"poet":"Sevgül Kılıçaslan","poet_slug":"sevgul-kilicaslan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yolcudur-sevdam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsterdim', 'i-sterdim-nuri-gokhan-sonsel-tpqti', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ellerini,ellerimde,

Gözlerini, gözlerimde.

Dizlerini, dizlerimde,

           bilmek  isterdim.

Sevinçleri, yüzümüzde,

Sevdamızı, özümüzde.

Sadakat ’ı, sözümüzde,

           görmek  isterdim.

Kalbimizin, neşesini,

Fısıldayan, aşk  sesini.

O  sıcacık,nefesini,

      duymak  isterdim.', 'Ellerini,ellerimde, Gözlerini, gözlerimde. Dizlerini, dizlerimde,            bilmek  isterdim. Sevinçleri, yüzümüzde, Sevdamızı, özümüzde. S...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/isterdim-56-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektuplar-103 30/04/0001', 'mektuplar-103-30-04-0001-mahzun-doga-33xy3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', ''' Sabrım Mine Terbiyesi / günahlarım terbiyesizlik.''

Kalbin üstümde ilahi rahmetin

sesin eda-i mukaddes

varlığın melek-i aşk

hasretin sine-i millet 

Ve bunlar üstüne ben

demek ki

rahmet-i ilahine

zahmet-i Kâbil eylemişim

demek ki ben

kelam-ı mukaddesine

suç-u lisan eylemişim

Ve şimdi

ve artık

ve sonsuza dek

kızarık sözler yaptım kendinden kendime

döktüm bu illet kalabalığım üstüne

o rabarba ki

aşkın kötü sesleri

şeytani felaket

o sözler ki

hasretin edebsizliği

O sözler 

o sesler

ki

cehennemdeler

ve artık

ve sonsuza kadar', ''' Sabrım Mine Terbiyesi / günahlarım terbiyesizlik.'' Kalbin üstümde ilahi rahmetin sesin eda-i mukaddes varlığın melek-i aşk hasretin sine-i...', ARRAY['Türk Edebiyatı','Şiir','Mahzun Doğa']::text[], 8.5, '{"poet":"Mahzun Doğa","poet_slug":"mahzun-doga","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/mektuplar-103-30-04-0001-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeniden  bir', 'yeniden-bir-nuri-gokhan-sonsel-rmzcz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yeniden  yazacağım  şiirlerimi,

Mısralar  taptaze  doğsun  diye.

Öyle  konuşturacağım  ki, kelimeleri,

Senden hiç  bir  şey, kalmasın  diye.

Şarkılar  yazacağım, her  satırda,

Besteler  dizeceğim, karanlıklara.

Öyle  notalar, bulacağım  ki,

Senden  bir  eser, kalmasın  diye.

Resimler  çizeceğim, elimden  geldiği dek,

Tuvalimde  renkler, birbirine  karışsın.

Öyle  çizgiler, çekeceğim  ki,

Senden  bir  hatıra, kalmasın  diye.

Yeniden  yazacağım, romanlarımı,

Değişik  tipler, yaratacağım.

Öyle  bir  konu, bulacağım  ki,

Senden  bir  anı, kalmasın diye.', 'Yeniden  yazacağım  şiirlerimi, Mısralar  taptaze  doğsun  diye. Öyle  konuşturacağım  ki, kelimeleri, Senden hiç  bir  şey, kalmasın  diye....', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yeniden-bir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hata', 'hata-ayten-ozlem-yesilcali-6d35g', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Her insan hata yapar bende bir hata yaptım…

Nedenini sorma bana anlatırsam sende üzülürsün.

Sevgisizlik de yalnızlık de ne dersen dee.

Bazen insan tatlı birkaç kelime duymak ister ya.

Al işte bende duyduğum o birkaç tatlı kelimeye kandım.

Belki de yıllardır  duymadığım o tatlı sözlere..

Anla be dostum,kardeş,kızım..

Anlayın beni,bende insanım benimde bazen boşluklarım olur..

Bunun için beni yargılamayın kınamayın

Beklide siz haklısınız demir gibi bir yürek var bende; 

Bunu sizde gördüğünüz için yadırgadınız.

Ama bilin ki insan insandır her zaman güzellikleri sever.

Ne bilirim ki karşımdakinin kişiliksizliğini.

Nasıl anlarım nasıl…

Ben hep sevgide yanlışı yaşadım…

Aklımı belki başımdan aldı da gitti o tatlı nağmeler.

Hiç kimse yaşamayan biri bilemez yalnızlığı.

İşte dile düşmek istemez sem de kalitesiz insanların yüzünden.

Düşersin böylece.

Hata yaptım hatamı anladım tek bildiğim bundan böyle yalnızlık

Tek sevgilim var benim oda içkim ve sigaram

Onlardır benim kaderim..

Hayatta dost yok sevgili yok candan seven yok.

Ben yine gecenin karanlığında döneyim yansızlığıma

Şiirlerim yalnızlığımdır benim kaderim.

Eller ne derse desin 

Ben hep ağlarım kaderim belli

Bende hata yapabilirim insanım çünkü', 'Her insan hata yapar bende bir hata yaptım… Nedenini sorma bana anlatırsam sende üzülürsün. Sevgisizlik de yalnızlık de ne dersen dee. Bazen...', ARRAY['Türk Edebiyatı','Şiir','Ayten Özlem Yeşilçalı']::text[], 8.5, '{"poet":"Ayten Özlem Yeşilçalı","poet_slug":"ayten-ozlem-yesilcali","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/hata-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karar Veremiyorum', 'karar-veremiyorum-nuri-gokhan-sonsel-jl4md', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir tanem…

Soğuk  rüzgarlar  gibi, ne  olur  bugün esme,

Yaralı  bir  kuş  gibi, hapis  kaldım  kafeste.

Belki de  sen haklısın, inan  bilemiyorum,

Ağlamak mı  gülmek mi, karar  veremiyorum.

Kendim gibi sanırdım, kalbindeki  sancıyı,

Anladım ki  hiç  tatmadın, sen bu  buruk  acıyı.

Benden çok  uzaklardasın, sana  eremiyorum,

Ağlamak mı  gülmek  mi, karar  veremiyorum.

Sevgi  gönlünde  değil, dudağındaymış  meğer,

Yanardın  kavrulurdun, aşkı  bilseydin  eğer.

Bir tanem  çok  yorgunun, sitem  edemiyorum,

Ağlamak mı  gülmek mi, karar  veremiyorum.

Bende  sabır  tükendi, sen  şaşkına  döndürdün,

Bir tanem  hem  ruhumu, hem  aşkımı  öldürdün.

Bence  bu  aşk  burada  biter, seni   bilemiyorum,

Ağlamak mı  gülmek  mi, karar  veremiyorum.

Kaynarken  taşım, taşım,akarken  bu  gözyaşım,

Söyle  benim  Bir tanem, göğe  erdi  mi  başın.

Başka  bir  aşk  istemem, artık  sevemiyorum,

Ağlamak mı  gülmek  mi, karar  veremiyorum.', 'Bir tanem… Soğuk  rüzgarlar  gibi, ne  olur  bugün esme, Yaralı  bir  kuş  gibi, hapis  kaldım  kafeste. Belki de  sen haklısın, inan  bilem...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/karar-veremiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadınım diyenlere', 'kadinim-diyenlere-ayten-ozlem-yesilcali-6qiyt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne diyeyim bilemedim nasıl anlatayım kendimi

Ben bir ana dolunun bağrından kopan kimsesizim

Süslü sözler söyleyemem sadece içimden geleni konuşanım

Ne bir kimseden kötülük beklerim nede ben kötülük yaparım

Sabahlarım şu gurbete, ana diye sarıldım şarkılara yar diye 

Dinledim ezgileri.

 Can diye sarıldım insanım diyen yılanlara

Gurbet acı hayat insafsız kader zalim

Ne kadarda dersek kaderi kendimiz yazarız

Yalan küllüm yalan

Ne kaderi kendimiz yazabiliriz nede istenmeyenlere karşı çıkabiliriz

Sadece kendimize yaparız en büyük iyili gide kötülüyü de 

Bilseydik kötülük nerde iyilik kimde yaparmıydık

Sanmam 

Sevği diye sarılırı mıydık  yılanlara çıyanlara kapılır mıydık

Erkeğim diyen erkek müsvete sine

Dinler miydik  yalan oldu benim ömrüm ü

Yazar mıydık yaşadıklarım ızı

Neler yaşadım nelerle uğraştım gurbet elde kadere yenilmemeyi

Ama nafile

Biz özümüzü yaşadık can 

Temiz saf yalansız riyasız kadere boyun eğdik

Anadolu inansın saflığıyla temiz ligiyle

Gurbet kadınını yaşadık kadınlığımızla

Bir özümüzden insan istedik hayatımızda

Onu bile yaşatmadı ağız tadıyla felek

Ayrı koydu anadan babadan yoldaştan

Kader dedik çekildik

Yazgı dedik ezildik yetmedi mi felek

Yetmedi mi biz Anadolu insanına çektir diğin

Haykıramayız biz içimiz de ki isyanı

İsyanımız şiirlerimizde gizli

Türkülerimizde saklı

Çok mutsuzum güvenmem artık kimseye 

Anadolu kadını değil sadece tüm kadınım diyenlere şiirim

İçinde kendinden bir şeyler bulanlara', 'Ne diyeyim bilemedim nasıl anlatayım kendimi Ben bir ana dolunun bağrından kopan kimsesizim Süslü sözler söyleyemem sadece içimden geleni ko...', ARRAY['Türk Edebiyatı','Şiir','Ayten Özlem Yeşilçalı']::text[], 8.5, '{"poet":"Ayten Özlem Yeşilçalı","poet_slug":"ayten-ozlem-yesilcali","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/kadinim-diyenlere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kazan Doğurur mu', 'kazan-dogurur-mu-yusuf-onder-bahceci-kgepg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kazanın doğurduğuna inananlar, öldüğüne de inansınlar,

Kazan hiç doğurur mu be hayalperest, menfaatperestler,

Kul hakkı yiyen keresteler ağaç yaş iken eğilirdi bilseler,

Kazanın doğurduğuna inananlar, öldüğüne de inansınlar,

Kazan hiç doğurur mu be hayalperest, menfaatperestler...', 'Kazanın doğurduğuna inananlar, öldüğüne de inansınlar, Kazan hiç doğurur mu be hayalperest, menfaatperestler, Kul hakkı yiyen keresteler ağa...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kazan-dogurur-mu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canımın Canı', 'canimin-cani-sevgul-kilicaslan-jygtu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu mektubu sana kalbime pil takıldıgı hastaneden yazıyorum.. Ölürsem sakın üzülme.. Çünkü “Ölmek bize yakışır,,

Sensiz bu kalp tekrar atmayı başarır mı..? 

İçinde senin sevdan olmayan boş bir kalbi taşımak, 

Benim bu Canıma yakışır mı..? 

Bu Can her şeyi ile seni yaşıyor, Nerdesin..? 

Canımın canı.. Diye haykırıyor.. 

Sen bu Canımın son nefesisin.. 

Sen olmayınca  boğuluyorum... 

Nefes alamıyorum..! ! 

Bu Can.. En küçük hücresine kadar, seni yaşıyor.. Nerdesin..? ''Canımın canı ''  diye haykırıyor..

 Unutma..! ! ! 

Canımın son nefesisin, sen olmayınca   boğuluyorum..! ! 

BİLİYORUM.. ÖLECEGİM…

AMA SON NEFESİMDE…

Yine

“SENİ SEVİYORUM”…

DİYECEGİM…', 'Bu mektubu sana kalbime pil takıldıgı hastaneden yazıyorum.. Ölürsem sakın üzülme.. Çünkü “Ölmek bize yakışır,, Sensiz bu kalp tekrar atmayı...', ARRAY['Türk Edebiyatı','Şiir','Sevgül Kılıçaslan']::text[], 8.5, '{"poet":"Sevgül Kılıçaslan","poet_slug":"sevgul-kilicaslan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/canimin-cani-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektuplar-104 01/05/0001', 'mektuplar-104-01-05-0001-mahzun-doga-pvyr7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '''Masum değiliz hiçbirimiz...''

Masum değilizken daha biz

sen

masumine!', '''Masum değiliz hiçbirimiz...'' Masum değilizken daha biz sen masumine!...', ARRAY['Türk Edebiyatı','Şiir','Mahzun Doğa']::text[], 8.5, '{"poet":"Mahzun Doğa","poet_slug":"mahzun-doga","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/mektuplar-104-01-05-0001-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu gün İstanbul kadar yaşlıyım', 'bu-gun-i-stanbul-kadar-yasliyim-seyit-ahmet-duzen-03ey1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu gün İstanbul  kadar yaşlıyım.

Yeni doğmuş bir bebe kadar umarsiz

Kaçırdığım trenin ardından baka kalirken

Küsmüşüm herşeye ansız; 

Haydarpaşaya, terenlere, raylara, seferlere.

Sana bambaşka...

Bu gün İstanbul kadar yaşlıyım

Tarih kadar hüzünlü ve tekerrür bekleyen

Sevdiğim kızı kaçırmışlar, kız  kulesine mahkum

Padişahım aşka, sevdaya olur mu hiç ferman? 

Galatadan izlerim Üsküdarı korkakca

Çek kürekleri kayıkçı, yüzelim zindana

Bu gün İstanbul kadar yaşlıyım

Bütün kadınlar kadar işveli ve genç.

Gözlerimden, bir yosma süzülerek geçmekte

Hazlarimi yarip,toyluğuyla bakışlarımdan düşüyor

Çilveli gülümsüyor; hayata, denize, insanlara

Bana bambaşka,,,

Bu gün İstanbul kadar yaşlıyım

Göründüğü gibi görünen,olduğu gibi ben.

Yüzümde derin vapur izleri, ekmek kırıntıları

Martı sesleri acı çığlığımı  bastırmakt

Balıklarımı çalıyorlar, çocuklarımı iskeleden

O, ağzı alkol kokan akşamcı amcalar

Bu gün İstanbul kadar yaşlıyım

Anıtlar kadar anı, heykeller kadar soğuk...', 'Bu gün İstanbul  kadar yaşlıyım. Yeni doğmuş bir bebe kadar umarsiz Kaçırdığım trenin ardından baka kalirken Küsmüşüm herşeye ansız;  Haydar...', ARRAY['Türk Edebiyatı','Şiir','Seyit Ahmet Düzen']::text[], 8.5, '{"poet":"Seyit Ahmet Düzen","poet_slug":"seyit-ahmet-duzen","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/bu-gun-istanbul-kadar-yasliyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırık Bahar Dalları', 'kirik-bahar-dallari-nuri-gokhan-sonsel-qa3oq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Henüz daha vakit erken,dolaş güzel sende gez,

Tat zevkini bu hayatın, giden gün geri gelmez.

Bülbüller şarkı  söyler, güller  ise  naz bilmez,

Zannetme ki aşk ateşi,nihayetsiz hiç sönmez.

Dolsun gönlün aşk  ile, güzelliğin bitmeden,

Sevdiğine sıkı sarıl, bir  kenara  itmeden.

Seneler merhametsiz, takvim kopup bitmeden,

Bil hayatın değerini, gençlik elden gitmeden.

Anlamadan bitecek, hayatının  en güzelim  yılları,

Ne bir gül kalacak, ne papatya, ne gelincik alları.

Buruk  bir  mutluluk kalacak, çözebilsen sırları,

Mümkün değil çiçek açmaz, kırık bahar dalları.

Şimdi daha zaman varken, çıkart gençlik  tadını,

Sonra  vakit  çabuk  geçer, kullan bu imkanını.

İhtiyarlık bir başlar  ki… unutursun adını,

Kimse kalmaz etrafında, duymazlar  feryadını.

Hayatını iyi  yaşa, feda et  sen…malları,

Sakın  boşa geçirme, bu  muhteşem yılları.

Bir gün  bembeyaz  olunca,saçının tüm kılları,

Zannetme ki  çiçek  açar, kırık  bahar dalları.', 'Henüz daha vakit erken,dolaş güzel sende gez, Tat zevkini bu hayatın, giden gün geri gelmez. Bülbüller şarkı  söyler, güller  ise  naz bilme...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kirik-bahar-dallari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kötü Diyeceksin Bana', 'kotu-diyeceksin-bana-nuri-gokhan-sonsel-4ybed', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Duyduğum her şarkıda sen…

Her satırda sen… Her notada sen.

Sanki sen varsın, aldığım her nefeste,

Hayatımda,  aşımda, suyumda, sadece sen varsın.

Ama… Kötü diyeceksin bana…

Bir gün kötü diyeceksin, belki bana,

Bulutlar solgun,  üzgün uçuşuyorken,

Kalbinde bir nefret, ufuklar gibi,

Yüreğinde yanan ateş, külleniyorken. 

Kötü diyeceksin bana, biliyorum...

Düşünemezsin hiç bir zaman, solan umutlarımı,

Göremezsin, içime akan, kanlı gözyaşlarımı.

Bilemezsin,  kapanmayan göz kapaklarımı 

Ve sen bana yine… Kötü diyeceksin biliyorum.

Bir gün çekip gideceğim, belki de buralardan,

Ölüm gibi sessiz, susacağım mahşere dek.

Hiç bir zaman, söylemeyeceğim seni sevdiğimi,

Ve sen bana yine… Kötü diyeceksin biliyorum.

Kavrulmuş toprakta yetişen, bir çiçeksin sen,

Gönlü engin denizler gibi,  boy, boy dalgalı.

Bir gün beni ararsan, tam kalbinde bulacaksın,

Ve biliyorum ki bana… Kötü demeye utanacaksın.', 'Duyduğum her şarkıda sen… Her satırda sen… Her notada sen. Sanki sen varsın, aldığım her nefeste, Hayatımda,  aşımda, suyumda, sadece sen va...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kotu-diyeceksin-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçücük Bir Ada', 'kucucuk-bir-ada-nuri-gokhan-sonsel-2z8ig', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Küçücük bir ada var, şimdi hayallerimde,

Tertemiz berrak deniz,  yakamozlar içinde.

Doğan her bir martıya, birer isim bulurum,

Uzanırım kumlara,  gömülür kaybolurum.

Uzanan geniş sahil, o kadar çok güzel ki,

En usta ressamların, çizdiği tablo gibi.

Boşa giden zamanı, yaşanmamış sayarım,

En haşmetli kayaya, şiir yazar oyarım.

Ufukta güneş doğar, duvak, duvak  açılır,

Bulutlar küme, küme, dolaşır gökyüzünde.

Yıldızlarla dost olur, mehtapla kaynaşırım,

Onlarla bütün gece, sırrımı paylaşırım.

Dilimde tuzlu tadı,  yediğim balıkların,

Ayağıma dolaşır, parçalanmış yosunlar.

Dalında olgunlaşmış, kırmızı böğürtlenler,

Ellerimi kanatır, çalılıkta dikenler.

Kıyıyla kucaklaşır, dalgalı engin deniz,

Barınamaz  limanda, balıkçı tekneleri.

Sonra  deniz  durulur, teker, teker geçerler,

Hayalde yaşattığım, o yelkenli gemiler.

Derinden bir ses gelir,  Gökhan! ...diye fısıldar.

Uyanırım yok olur, bu  renkli hatıralar.

Seraba karışmıştır, denizim dalgalarım, 

Elimde beyaz mendil, usul, usul ağlarım.', 'Küçücük bir ada var, şimdi hayallerimde, Tertemiz berrak deniz,  yakamozlar içinde. Doğan her bir martıya, birer isim bulurum, Uzanırım kuml...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kucucuk-bir-ada-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Zaman', 'ne-zaman-nuri-gokhan-sonsel-s99qz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne   zaman, bir  göl  görsem,

Minicik  çocukluğum…

Ne  zaman, bir  gül  görsem,

Gençliğimi  hatırlarım.

Ne  zaman,  şimşekler  çaksa,

Delicesine  korktuğum…

Ne  zaman, yağmur  yağsa,

Sen  gelirsin  aklıma.

Ne  zaman, bahar  gelse,

Kokunu  hatırlarım.

Ne  zaman, gece   olsa,

Beraberce  gezdiğim….

Ne  zaman, mehtap  olsa,

Seni  ilk  öptüğüm,

Ne   zaman, yaprak  düşse,

Hep  seni  hatırlarım.', 'Ne   zaman, bir  göl  görsem, Minicik  çocukluğum… Ne  zaman, bir  gül  görsem, Gençliğimi  hatırlarım. Ne  zaman,  şimşekler  çaksa, Delice...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ne-zaman-67-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerede', 'nerede-nuri-gokhan-sonsel-1gkmt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nerede yeşilken, altın gibi sararan,

Zümrüt gibi parlayan, o güzelim yapraklar.

Nerede çiçek bahçelerim, tomurcuk güllerim,

Şırıl,şırıl akan, pınarlarım şelalelerim.

Özledim seninle yüzdüğüm, hayal denizlerimi,

Kumruların öpüşüp seviştiği, çınar yok olmuş.

Gönlüm gibi kırılmış kalemim, titriyor elim,

Yalnızım, dümensiz, yelkensiz, tekne gibiyim.

Ruhumda bin bir keder, gönlümde elem,

Esmeyecek mi artık, içimde meltem.

Ne bir ülkem, ne bir beldem, olamaz benim,

Uçsuz-bucaksız çöllerde, serap gibiyim.

Nerede kızıllaşan, zindanlaşan akşam,

O güzel buram,buram, renkli çehreler.

Maziye mi karıştı, ben mi bilemem,

Güneş kadar parlak, o eski kahkahalar.

Güneş bir gün doğacak, yeşerecek yapraklar,

Yine mutlu insanlar, hep yeniden doğacak.

Artık belim bükülmüş, kar yağarken saçıma,

Ben kaybettiğim alemi, yeniden bulacağım.

Bulut,bulut olacak, o eski hatıralar,

Küme,küme dönecek, yine göçmen kuşları.

Altın ışıklardan tabiatın, ördüğü taç,

Tutam,tutam, demet,demet, başkasının olacak.', 'Nerede yeşilken, altın gibi sararan, Zümrüt gibi parlayan, o güzelim yapraklar. Nerede çiçek bahçelerim, tomurcuk güllerim, Şırıl,şırıl akan...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/nerede-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O hala gülüyordu', 'o-hala-guluyordu-nuri-gokhan-sonsel-x63lv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ufak   tefek  bir  kadındı, ateş  böceği  gibi,

Kabuğunda  kurumuş, yok  olmuş  bitmiş  sanki.

Yağışlı  bir  havanın, kurşuni  rengi   vardı,

Öyle  perişandı  ki…o’na  her  renk  uyardı..

Güzel  günler görmüştü,kürklerle  bürünmüştü,

Nice  zengin  erkekler, uğrunda  dövüşmüştü.

Bütün halkın  gözdesi, gerçek  bir  yıldız  idi,

Çok  güzel  bir  kadındı, sanki  Afrodit  gibi.

Seneler  merhametsiz, yıllar  o’nu  tüketti,

Sahte  olan  dostları, birer,  birer  terk  etti.

O  koca   bir  sanatçıydı, ismi  hala  dillerde,

Kapısında  beklenirdi, orkideler, güllerle.

Ne  bir   evi  kalmıştı, nede  bir  tek  mücevher,

Kuru  bir  lokmaya, muhtaç  kaldı  bu  cevher.

Her   şeyin   bir  sonu  var, yaşanmış  biliyordu,

Gözyaşları kurumuş … o  hala  gülüyordu.

Gözleri  elmas  gibi , alaylıydı  dudaklar,

Yüzündeki   çizgiler, binlerce  sırrı   saklar.

Çok  iyi  biliyordu, sokaklarda  ölecek,

Kimse sahip   çıkmayınca…belediye  gömecek.

Bütün  ömrü  boyunca, nice  roller  oynamış, 

Ama gerçek  anlamda, hiç de  mutlu  olmamış.

Rengi  kaçmış  kurumuş, can  verip  ölüyordu,

O  çok  büyük  sanatçı, geçmişe gülüyordu. 

CAHİDE SONKU’NUN ANISINA', 'Ufak   tefek  bir  kadındı, ateş  böceği  gibi, Kabuğunda  kurumuş, yok  olmuş  bitmiş  sanki. Yağışlı  bir  havanın, kurşuni  rengi   vardı...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/o-hala-guluyordu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaçak', 'kacak-yakup-i-lhan-h2hrq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sen, yalnızlık,

sığdıramayacaksın hiçbir sevdayı valizine,

almayacak hiçbir boşluk senin yaralı sevda haritalarını.

Sen, hep boş valizle seyahat edeceksin.

Bütün boş döneceksin sevdalarından,

Bir aşktan ötekine, sonra diğerine,

Sileceksin ömrünün izini her seferinde.

Entarinde kalmayacak hiçbir sevda kokusu,

Kil, sabun değmeden yunacaksın; 

Ellerini, bütün sevda yerlerini..

valizinde sadece sen olacaksın.

Çünkü sığmayacak hiçbir ayrılık,

Çünkü hiçbir sevda.

hep kaçacaksın sen,

Bir aşktan başka bir şehre.

Adım başı seni göreceksin.

Kendini bulacaksın verilen her aşk molasında,

Kimseler bilmeyecek seni,

Ne seni ne de sevda yerlerini,

Çünkü sen sevda,

Çünkü sen ayrılık,

Çünkü sen hep kaçak….', 'sen, yalnızlık, sığdıramayacaksın hiçbir sevdayı valizine, almayacak hiçbir boşluk senin yaralı sevda haritalarını. Sen, hep boş valizle sey...', ARRAY['Türk Edebiyatı','Şiir','Yakup İlhan']::text[], 8.5, '{"poet":"Yakup İlhan","poet_slug":"yakup-i-lhan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kacak-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Benim Olsun', 'o-benim-olsun-nuri-gokhan-sonsel-0dhit', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dün  akşam  bakarken, penceresinden,

Kalbimi  götürdü, komşunun  kızı.

Beynimden  sanki, bir  damar  koptu, 

Yayıldı  içime, derin  bir sızı.

Başımı  kaldırdım, baktım  göklere,

Yıldız  el ele  ve  demet, demet. 

Çok  garip,  bir  duyguya  kapıldım,

Aşk  denilen  bu  duygu, yalancı  cennet.

Sanki  bir  melodi, o  güzel  sesi,

Bahardan  bir  parçaydı,  sıcak  nefesi.

Gözleri  yeşil, yeşil,  birer  zeytin  tanesi,

Kimselerle  paylaşamam… o  benim olsun.

Saçları  kahverengi, bir  ipek  gibi,

Dudakları küçücük, mercimek  gibi.

Uzatırken   sanki …  öpecek  gibi,

Kimselerle  paylaşamam…o  benim olsun. 

Yüzünde gülücük, tatlı  bir  mana,

Minicik  ellerini, uzattı  bana.

Aşkı   içerken, biz  kana, kana,

Kimselerle  paylaşamam….o  benim  olsun.', 'Dün  akşam  bakarken, penceresinden, Kalbimi  götürdü, komşunun  kızı. Beynimden  sanki, bir  damar  koptu,  Yayıldı  içime, derin  bir sızı...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/o-benim-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eger bir gün', 'eger-bir-gun-sevgul-kilicaslan-a31rq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Eğer bir gün…

Sevmek istersen..                     

Önce kendini sev..                              

Daha sonra da

İstersen BENİ…! 

Ama BENİ; 

Beni sever gibi degil..

Kendini sever gibi..

SEVMELİSİN…! 

Çünkü..

BEN..

Seni öyle              

SEVDİM…! !', 'Eğer bir gün… Sevmek istersen..                      Önce kendini sev..                               Daha sonra da İstersen BENİ…!  Ama BEN...', ARRAY['Türk Edebiyatı','Şiir','Sevgül Kılıçaslan']::text[], 8.5, '{"poet":"Sevgül Kılıçaslan","poet_slug":"sevgul-kilicaslan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/eger-bir-gun-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdalar Günden Güne Yeşermeli', 'sevdalar-gunden-gune-yesermeli-huseyin-erdogan-33hcm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'güvendir aşk ve sevginin temeli

bence sevgi sevgiyle beslenmeli

sevdalar günden güne yeşermeli

şüpheler çıkarsa ortaya birer birer

aşk büyük olsa da bir günde bile söner

sevenin yüreği bir anda hazana döner 

bir tek çiçek bile açmaz olur gönüller

sevdiğinin elini artık tutmaz olur eller

gönlümdeki yollara diken ekme sakın

bana diken batsa söyle sen acımaz mısın? 

kalbimdeki pınar kurursa bir gecede canım

sen sevgi olup bir ırmak gibi akmaz mısın? 

sevdiğim bil ki ben bir sevgi adamıyım

çöllerde bile seni hiç sevgisiz bırakır mıyım? 

eğer sen böyle soru işaretleriyle yaşarsan

söyle ben ömrümce acılar içinde kalmaz mıyım? 

yokluğunda senin sevdanla yanmaz mıyım? 

ben yaşarken bile mezarlarda yatmaz mıyım? 

şiirim ben sensiz kalırsam ölümü tatmaz mıyım? 

                                                 21.03.2006

                                             Hüseyin Erdoğan', 'güvendir aşk ve sevginin temeli bence sevgi sevgiyle beslenmeli sevdalar günden güne yeşermeli şüpheler çıkarsa ortaya birer birer aşk büyük...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sevdalar-gunden-gune-yesermeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olamazsın Ki..', 'olamazsin-ki-nuri-gokhan-sonsel-zb087', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ruhundan  ruhuma, umut  akmadan,

Gözlerin  gözlerimi, fazla  yakmadan.

Sen  bana   bir   defa, bile   bakmadan

Sen  benim  sevgilim, olamazsın  ki.. 

Gecenin   karanlığını, almış  gözlerin,

Bana  öyle   bakma, sonra  özlerim.

Sana  tuhaf  gelirse, bazı  sözlerim,

Sen  benim  sevgilim,  olamazsın  ki..

Gönderdiğin  mesajı, daha  dün  aldım,

Hakkımda  yazdıklarına, şaşırdım kaldım.

Sevdanın  zehrini, kalbime   saldım,

Sen  benim  sevgilim, olamazsın  ki… 

Uykusuz  bıraktığın, gecelerimi,

Yarım  kalan  rüya  ve  düşlerimi.

Geri  vermezsen, bunca  çektiklerimi,

Sen  benim  sevgilim, olamazsın  ki…', 'Ruhundan  ruhuma, umut  akmadan, Gözlerin  gözlerimi, fazla  yakmadan. Sen  bana   bir   defa, bile   bakmadan Sen  benim  sevgilim, olamazs...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/olamazsin-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onlar Öyle Dediler', 'onlar-oyle-dediler-nuri-gokhan-sonsel-9x8vx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir tanem…  Ağaca –dala, yaprağa sordum,

Mevsimlerin ötesi, baharındır dediler.

Gül’e, çiğdem’e, mor menekşeye sordum,

Yediveren güllerin, dallarıdır dediler. 

Yazdığım şiirlere, şarkılarıma sordum,

Mısralara sığmayan, o aşkın’dır dediler.

Benimle batan güne,  esen yellere sordum,

Seherde öten bülbülün, çilesidir dediler.

Yıldızlara ay’a,  birde güneş’e sordum,

Yolunu gözlediğin, o’dur dediler.

Günlere aylara, yıllara sordum,

Özlediğin sevgili, bu’dur dediler.

Sensiz geçen karanlık, gecelerime sordum,

Seni aydınlatan,  mehtabındır dediler.

Ağlayan gözlerime, yanan yüreğe sordum,

Senin kara sevdanın, ilacıdır dediler.

                  

                      Ben demedim sevdiğim,

                      Onlar… Onlar, öyle dediler.', 'Bir tanem…  Ağaca –dala, yaprağa sordum, Mevsimlerin ötesi, baharındır dediler. Gül’e, çiğdem’e, mor menekşeye sordum, Yediveren güllerin, d...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/onlar-oyle-dediler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen ağla', 'sen-agla-yakup-i-lhan-j62db', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen ağla,

 çünkü ağlamakta

Gülmek gibi yakışıyor yüzüne

Bırak göz yaşlarını ilk bahar yağmurlarına

Sen ağla, ağlamakta gülmek gibi yakışıyor gözlerine,

Sen ağla,

Bütün ıslat yüreğini, yüzünü,

Sen ağla, çünkü; 

Sen ne zaman ağlasan

Sen ne zaman gülsen

Bir bahar çocuğu doğuyor gözlerine,

Her anı hüzün bir bahar çocuğu,

Gözleri nemli bir çocuk belki,

Sen ağla,

Çünkü:

Ağlamakta gülmek gibi yakışıyor yüzüne.

Sen ağla, yoksa gözlerin,

Yoksa o bahar çocuğu,

Yoksa ben yoksa,

Öleceğim……

Sen ağla, bırak bütün ıslaklığı; 

Akasyalara, erik dallarına, papatyalara….

Yoksa ben, yoksa o bahar çocuğu yoksa; 

Erik dalları, yoksa papatyalar; 

Ölecek…….

							23/02/2005

							çarşambba', 'Sen ağla,  çünkü ağlamakta Gülmek gibi yakışıyor yüzüne Bırak göz yaşlarını ilk bahar yağmurlarına Sen ağla, ağlamakta gülmek gibi yakışıyor...', ARRAY['Türk Edebiyatı','Şiir','Yakup İlhan']::text[], 8.5, '{"poet":"Yakup İlhan","poet_slug":"yakup-i-lhan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/sen-agla-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnadına', 'i-nadina-yakup-i-lhan-g6z5p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yürüyorum, dur duraksız,

kaldırımlar yorgun,

şehir ayaklarımda ufalanıyor.

Her adımda bir hayat; 

Doğuyor ve ölüyor.

Sokaklar çığlık çığlığa,

Rüzgar,

Anlamsız fısıldıyor ve her defasında bir parçamı alıyor elimden.

Rüzgar, yaramaz bir çocuk,

Savuruyor, dağıtıyor yalnızlığımı, alıp götürüyor.

Yürüyorum, sensiz ve ıslak,

Yağmur ve rüzgar; tek dost senden sonra,

Kaldırımlar, boş sokaklar düşman belledi

Artık beni.

Sensiz sığmıyorum hiçbir aralığa,

Kabul etmiyor hiçbir sokak sensiz beni.

İnadına yağmur,

İnadına rüzgar

Ve ben inadına yürüyorum.

Biliyorum kaldırımlar ağlıyor,

Biliyorum her bir adımda ölüyor bir hayat,

Biliyor ve yürüyorum.

Rüzgar, damarımda,

Kanımda ince bir sızı

Dünya eziliyor, ayaklarımın altında,

Bilsem de her adımda öldüğümü sensiz,

Korkmuyorum ve 

inadına yürüyorum', 'yürüyorum, dur duraksız, kaldırımlar yorgun, şehir ayaklarımda ufalanıyor. Her adımda bir hayat;  Doğuyor ve ölüyor. Sokaklar çığlık çığlığa...', ARRAY['Türk Edebiyatı','Şiir','Yakup İlhan']::text[], 8.5, '{"poet":"Yakup İlhan","poet_slug":"yakup-i-lhan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/inadina-50-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel İstanbul', 'guzel-i-stanbul-ramazan-karatas-35kge', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Asırlar önce müjdelemiş peygamberim

Ona salatı, selamlar gönderelim

Bu cennet vatanın kıymetini bilelim

Peygamber müjdeli güzel İstanbul

Tarihi şan''la, şeref''le anan

Nice zaferden, zafere koşan

Atam Fatih''den bize armağan

Tarihin şahidi güzel İstanbul

Galata''dan uzansın haliçe eller

Sultan Ahmetten yükselir Allahu ekber

Bağrında yatar nice alimler, kamiller

Ulemalar şehri güzel İstanbul

Denizler''le süslenmiş her bir yanın

Konağı olmuşsun milyonlarca insanın

Nede yakışmış türbesi Eyyüp Sultan''ın

Sultan''lar diyarı güzel İstanbul

Öyle şirinsinki, sevenler bilir

Sevdikce insanın sevesi gelir

Taşın, toprağın altın diye anılır

Şirinler, şirini güzel İstanbul

Şair, Ramazan''ım ne kadar yazsan şiir

Anlatmakla bitmez bu koca şehir

Daha nice kalemler, mürekkepler tükenir

Anlatmakla bitmezsin güzel İstanbul', 'Asırlar önce müjdelemiş peygamberim Ona salatı, selamlar gönderelim Bu cennet vatanın kıymetini bilelim Peygamber müjdeli güzel İstanbul Tar...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Karataş']::text[], 8.5, '{"poet":"Ramazan Karataş","poet_slug":"ramazan-karatas","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/guzel-istanbul-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Hatıram Olsun', 'sana-hatiram-olsun-nuri-gokhan-sonsel-4mo20', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bahar neden ağladı, neden ıslak topraklar,

Gizli bir sırrı mı var, konuşmuyor yapraklar.

Dağlarda yağan karlar, yavaş,  yavaş  eriyor,

Esen ılık  rüzgarlar, senden haber veriyor.

Getiriyor kokunu, o bembeyaz bulutlar,

Ağaç da bütün kuşlar, sanki sevdamı kutlar.

Geceler daha güzel, yıldızlar daha parlak,

Sen dönünce bir tanem, hayat güzel olacak.

Tomurcuklar gül oldu, duygu çiçeği açtı,

Bir tanem sen gelmedin, kış  mevsimi  yaklaştı.

Hani haber  göndermiş, geleceğim demiştin,

Bende sana  inanmış, delice sevinmiştim.

Anladım ben bir tanem, neden ıslak topraklar,

O’nlar da matemde ki, konuşmuyor  yapraklar.

Biliyorlar bir tanem, sen hiç gelmeyeceksin,

Beklerken ben sabırla, aşkı  öldüreceksin.

Deniz  dalgalarında,  yankılanırken sesim,

Sor bakalım bir tanem, Gökhan şimdi nerdesin? 

Hayatım sona erdi, huzura erdi başım,

Sana hatıram olsun, akan bu son gözyaşım.', 'Bahar neden ağladı, neden ıslak topraklar, Gizli bir sırrı mı var, konuşmuyor yapraklar. Dağlarda yağan karlar, yavaş,  yavaş  eriyor, Esen ...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sana-hatiram-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen beni sever miydin', 'sen-beni-sever-miydin-nuri-gokhan-sonsel-d3ooh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevdiğimi, bulutlara  yazsaydım,

Hayalini,dağa  taşa  kazsaydım.

Denizleri  yarsam, sana  yol  açsam,

Saçların  dağılmasın  diye,

Rüzgarları  durdursam,

            Sen beni  sever miydin? 

Aşk bahçelerine,alsam  götürsem,

Bir  kelebek  olup,eline  konsam.

Bir  kırmızı  gül  olsam, beni  koklasan,

Bir  bahar rüzgarı  olsam, seni okşasam,

         Sen  beni  sever miydin? 

Sen  gül’üm, ben  bülbül  olsam,   

Dallarda, hep  aşkımı  haykırsam.

Ferhat  olsam,dağları yarsam,

Yollarına  düşsem, mecnunun  olsam,

          Sen  beni  sever  miydin?', 'Sevdiğimi, bulutlara  yazsaydım, Hayalini,dağa  taşa  kazsaydım. Denizleri  yarsam, sana  yol  açsam, Saçların  dağılmasın  diye, Rüzgarları...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sen-beni-sever-miydin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen ve Ben. iki', 'sen-ve-ben-iki-nuri-gokhan-sonsel-mx6pr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben, azgın  dalgalarla  boğuşan,

Tahtaları  çürümüş, eski  bir  gemi…

Sen,şimal  yıldızı  gibi  parlayan,

Kıyıdaki, deniz  feneri…

Ben, yolunu  şaşırmış, bir  deniz  kuşu,

Sen, avını  yakalamış, kartal  gibisin.

Ben, renklerle  uğraşan, basit  bir  ressam,

Sen, çoktan  resmi  çizilmiş, sergilerdesin.

Ben, içine  kapanmış, dalgın  bir  şair,

Sen, besteler  yapan, ünlü  birisin.

Ben, karanlığa  alışmış,garip  bir  kişi,

Sen, parlak  ışıklar  saçan, güneş  gibisin.

Sordular  seni  benden,acep  neyindir? 

Gecen mi,  gündüzün mü, yoksa  mehtabın mıdır.

Baktılar  ki  göklerden, düşen  yağmurlarına,

Anladılar  ki… sen  benim, hüzün  bulutlarımsın.', 'Ben, azgın  dalgalarla  boğuşan, Tahtaları  çürümüş, eski  bir  gemi… Sen,şimal  yıldızı  gibi  parlayan, Kıyıdaki, deniz  feneri… Ben, yolu...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sen-ve-ben-iki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Gittiğin Zaman', 'sen-gittigin-zaman-nuri-gokhan-sonsel-qqr0x', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'SEN GİTTİĞİN ZAMAN 

               Beni terk edip de sen… gittiğin zaman,

               sensiz yalnız kalıp da... bittiğim zaman.

Yüreğimde bir  hüzün, gözlerimde nem vardı,

Kalbimde özlediğim, senden hatıra vardı.

Karanlıktı gökyüzü, ağlıyordu geceler,

Çözülmüyor bu gece, karışmış bilmeceler. 

Ne bir dilim ekmeğim, ne dolapta aş vardı,

Ağladım bütün gece, gözlerimde yaş vardı.

Ne bir dost sesi vardı, ne odada bir nefes,

Kalbimi sıkıştırdı, göğsümdeki bu kafes.

Caddeleri seyrettim, pencere kenarında,

Duvarlarla konuştum, sen yoktun ki yanımda.

Ne bir ateşim vardı, ne yanan bir ışığım,

Anladım ki ben sana, sırılsıklam aşığım.

Mehtap çıkmış bu gece, yıldızlar göz kırpıyor,

Sevdalı sarı güller, bülbüle naz yapıyor.

Tüm bitkiler çiçekler, arılar gülümsüyor,

Bu sabah döndüğünü, sanki hepsi biliyor.

Güneş sevgilim gibi, ışıklarla sarıyor,

Yok olan tüm dostlarım, artık beni arıyor.

Gökyüzü aydınlandı, ağlamıyor geceler,

Çözülüyor sevgiyle, bütün bu bilmeceler.

               Beni  sen  affedip …döndüğün zaman,

               Sevginle ruhumu…ördüğün zaman…', 'SEN GİTTİĞİN ZAMAN                 Beni terk edip de sen… gittiğin zaman,                sensiz yalnız kalıp da... bittiğim zaman. Yüreğimde...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sen-gittigin-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sizin İçin', 'sizin-i-cin-mehmet-ali-sahin-dmlst', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ansanız da olur, anmasanız da

Sizin için yazdım şiirlerimi

Alsanız da olur, almasanız da

Sizin için yazdım şiirlerimi

Kırarım vurdukça gönül telimi

Gözlerimden akan aşkın selimi

Ne olur yıkmayın hayallerimi

Sizin için yazdım şiirlerimi

Mazlumun hayatta nedir ki işi

Sevginin dünyada bulunmaz eşi

Ufukta batarken akşam güneşi

Sizin için yazdım şiirlerimi

Bağrımı yakıyor hasretin yeli

Mehmet Ali suskun söylemez dili

Bazen üzüntülü bazen neşeli

Sizin için yazdım şiirlerimi', 'Ansanız da olur, anmasanız da Sizin için yazdım şiirlerimi Alsanız da olur, almasanız da Sizin için yazdım şiirlerimi Kırarım vurdukça gönül...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Şahin']::text[], 8.5, '{"poet":"Mehmet Ali Şahin","poet_slug":"mehmet-ali-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sizin-icin-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Başkası', 'senden-baskasi-nuri-gokhan-sonsel-i33w7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne olur her gece, bütün gündüzlerimde,

Yalnız seni hissedeyim, sadece benliğimde.

En güzelini yaşadığımız, mutlu günlerimizde,

Kalbime girmesin, senden başkası…

Bahar gülleri gibi, açılırsın gönlümde,

Büyülersin inan sen, yaşarsın hayalimde.

Bütün saadetim sende, hep senin ellerinde,

Kaderim olmasın, senden başkası…

Yarınları bu gün yap, yine yüce sevginle,

Bitmesin hiç istemem, yaşıyorum seninle.

Güneşin en parlak ışığı, bana sunulsa bile,

Gözlerime girmesin, senden başkası...

Bir tek sende bulurum, ben sadece kendimi,

Ayrılıklar yakmasın, dikkat et yüreğimi,

Almasın kimseler, senden ümitlerimi,

Tutmasın elimi, senden başkası…

İçim dolmuş bir defa, senin özünle,

Hiç kimseler göremez, seni benim gözümle.

Uyurken her gece, başım senin dizinde,

Sevmesin istemem, senden başkası…', 'Ne olur her gece, bütün gündüzlerimde, Yalnız seni hissedeyim, sadece benliğimde. En güzelini yaşadığımız, mutlu günlerimizde, Kalbime girme...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/senden-baskasi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'N'' için?', 'n-icin-yusuf-mete-tekel-uxs7p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yırtık ayakkabılar,  içine dolmuş sular,

Uyuyan vicdanlarımızı uyandırmak için.

Bağlı gözler, ceplere uzanan eller,

Kaybettiğimiz yardım severliğimizi aramak için.

Maskelenmiş ruhlar, randevumuzu bekleyen hanımlar,

Kendimize saygımızı kaybettiğimizi haykırabilmek için.

Mendilcilik oynamakta canlarım, uzanan bebiş eller, 

Halimize ağlayan ruhlarımızın gözyaşları için.

Yürek kaldırmaz, tirit misali jiletlenmiş canlar,

Komedi sandığımız dramayı gösterebilmek için.

Parmaklıklara tutunmuş, ah katil eller,

En güzeli, sabrı bilmediğimiz için.

Gecenin ortasında, titrek çığlıklar,

Vicdanımıza tıkadığımız kulaklarımız için.

Kıyamadığım kambur nineler, açılan titrek eller,

Altında ezildiğimiz nefsimizi hafifletmek için.

Çevresi etten duvar, içinde yalnızlıklar,

Benimseyerek kendimize yabancılaştığımız için.

Delilere eş, uyuşturulan benlikler,

Çaresizliğimizi düşünmeyi bir an erteleyebilmek için.

İşte içinizde! İçten feryatlar,

Roller değişebilir olduğu için.

Üstüne giymiş geceyi, çöpleri yoklayan eller,

Kaybettiğimiz vicdanımızı bulmak için.

Amansız çark, bitmeyen rutin koşuşturmalar,

Bu faturaları ödemekten korktuğumuz için.

Damıtılmış asmalar, hoşluk içinde bilinçler,

Hafızamızın sahnesine katlanabilmek için.

Affınıza sığındım, yaptığım bunca hatalar,

Kavramlarımızın içi boşaltılmış olduğu için.

Vicdan kapınızın eşiğinde, açtığım eller,

Kaybettiğimiz değerlere dokunabilmek için.

Ancak duyumsamadan, yazabildiğim bu mısralar,

İçin için içim parçalandığı için.

Derinlemesine, sorgulamadığım bu içinler,

Umut güzel şey amma benimkisi azaldığı için..', 'Yırtık ayakkabılar,  içine dolmuş sular, Uyuyan vicdanlarımızı uyandırmak için. Bağlı gözler, ceplere uzanan eller, Kaybettiğimiz yardım sev...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Mete Tekel']::text[], 8.5, '{"poet":"Yusuf Mete Tekel","poet_slug":"yusuf-mete-tekel","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/n-icin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Tanıdığımda', 'seni-tanidigimda-nuri-gokhan-sonsel-5o85e', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Biliyor  musun ki…seni  tanıdığımda,

Hoş  kokulu  saçların, pembeydi  dudakların,

İncecik  parmakların, avucunda  nem  vardı.

Işıl  ışıldı gözün, merhabaydı  ilk  sözün,

Fevkalade  bir  yüzün, sesinde  hüzün  vardı.

O  akşam  ben  uykusuz, belki  biraz  durgundum,

Gözün  gözüme  değdi, gitti  bu  yorgunluğum.

Ellerin  ateş  gibi, yanağında  ben  vardı,

Dışarıda  bir  fırtına, kiremitte kar  vardı.

Ayağında  pantolon, üstünde  kaban  vardı,

Tanıştığımız o  anda…ateş  bacayı  sardı.

Ne  müthiş  bir  duyguydu, sanki  bir  rüya sandım, 

Elim  sobaya  değmiş…  canım  yandı  uyandım.

Rüyalarda  olsan  da…hep  ben  seni  aradım,

Tükenmeyen  duyguma, bir   nokta  koyamadım.

Şehir   şehir   dolaştım, belki  bulurum  diye,

Hayalden  bir  başka  şey, kalmadı  hiç  geriye.

Sana  bir  isim  buldum, ismini  bilmiyordum, 

Gönlümde  yaşa  diye…sevda  adını  koydum.

Bir  daha  hiç  görmedim, bir  daha  hiç  gelmedin,

Gelsen de gelmesen de, artık  sevdamsın  benim.

Gittiğin  her  bir  yerde, aşkımı  taşıyorsun,

İnan  bana  sevgilim, sen  her  zaman  benimle…

Ömrüm  bitene  kadar, sen  bende  yaşıyorsun.', 'Biliyor  musun ki…seni  tanıdığımda, Hoş  kokulu  saçların, pembeydi  dudakların, İncecik  parmakların, avucunda  nem  vardı. Işıl  ışıldı g...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/seni-tanidigimda-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İntihar', 'i-ntihar-umit-tuna-dauf9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İntiharın eşiğine gelmişse yüreğim,

Seni istiyorsa ellerim,

Gönlüm hala deli divaneyse,

Bu gönül seni ister ben neyleyim.

Aklıma geldiğin her an,

Yüreğimde zelzele,

Ellerimde titreme,

Beynimde gerileme,

Varsa! 

Kalbim seni ister ben neyleyim.

Seni hep sevdim ve seveceğim,

Uğruna intihar edeceğim,

Belki beni ölünce seversin diye,

Mezarıma bekleyeceğim! ...

ÇILGIN MUHASEBECİ', 'İntiharın eşiğine gelmişse yüreğim, Seni istiyorsa ellerim, Gönlüm hala deli divaneyse, Bu gönül seni ister ben neyleyim. Aklıma geldiğin he...', ARRAY['Türk Edebiyatı','Şiir','Ümit Tuna']::text[], 8.5, '{"poet":"Ümit Tuna","poet_slug":"umit-tuna","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/intihar-53-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin İçin Yaşadım', 'senin-i-cin-yasadim-nuri-gokhan-sonsel-qiana', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dolu, dolu  yaşamıştım, bu  yalancı  dünyayı,

Senden  başka  hiç  bir  yerde, bulamadım  sevdayı.

Nasıl  Mecnun  Leyla’sının,hayaliyle  yaşamışsa,

Bende  senin için  yaşadım, senin için  bir tanem.

Dolaştı  gönül  kuşu, bir  gün  başıma  kondu,

Bunca  sevda  arasında, ne  ilkti  nede  sondu.

Değişti  tüm  yaşantım, kalbime  kokun  sindi,

Ben  seninle yaşadım, senin  için  bir tanem.

Kötü  ve  güzel  günler, hayatın  bir  parçasıydı,

Umarsızdı  deli  gönlüm,hep  böyle  yaşasaydı.

Bilemezdim  değerini, belki  çoktan  ölürdüm,

Ben  seninle  yaşadım, senin  için  bir tanem.

Sana  gitme  diyorum, yalnız  bırakma  beni,

Erirde  yok   olurum, bir  kar  tanesi  gibi.

Susar  dudaklarımda, son  kahkaha  son  gülüş,

Ben  seninle  yaşadım, senin  için  bir tanem.', 'Dolu, dolu  yaşamıştım, bu  yalancı  dünyayı, Senden  başka  hiç  bir  yerde, bulamadım  sevdayı. Nasıl  Mecnun  Leyla’sının,hayaliyle  yaşa...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/senin-icin-yasadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adını İstanbul Koydum', 'adini-i-stanbul-koydum-mehmet-ozer-dd1qp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yeni bir sevgili buldum

Adını İstanbul koydum…

Denizden aldım gözlerinin rengini

Martılardan kaş yaptım

Sürmeli gözlerinin üzerine

Ve köprüleri kullandım

Dudaklarını  öperim niyetine

Dolaştık gezdik biraz

Üsküdar da çay molası verdik

Sonra baktık karnımız acıktı

Haliç’te ekmek arası

Kafaları çekelim dedik

Ver elini Beyoğlu’nun arka sokakları

Sonra çıktık Taksime 

İki sevgili el ele diz dize 

Anlatmaya başladık 

Tüm dert ve sıkıntılarımızı

O kalabalıktan şikayetçi

Ben yalnızlıktan

O kirlilikten bıkmış

Ben kirli insanlardan

O aşkı özlemiş

Ben unutmayı….

Yeni bir sevgili buldum

Adını İstanbul koydum

Saklasın istedim beni gecelerden

Kimleri saklamadım ki dedi

Kuru ekmeğime aş olsun dedim

Kimleri doyurmadım ki dedi

Sadece benim ol dedim

Kimseye gösterme yüzünü

Kapat kapılarını

Dünyanın dört bir yanına

Ağlamaklı oldu gözleri

Seni aldattım dedi

Kiminle demeye fırsat bırakmadan

Sen ve seninle beraber 

Yüzlerce sevgili

Girdi gönül kapımdan içeri

Hiçbirini geri çevirmedim

Hepsini en az senin kadar sevdim…

Yeni bir sevgili buldum 

Adını İstanbul koydum...

Her camisinde ayrı ayrı dua ettim

Sadece benim olsun diye

Öyle  deli sevdim ki seni…

Yeni bir sevgili buldum

Adını İstanbul koydum…', 'Yeni bir sevgili buldum Adını İstanbul koydum… Denizden aldım gözlerinin rengini Martılardan kaş yaptım Sürmeli gözlerinin üzerine Ve köprül...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Özer']::text[], 8.5, '{"poet":"Mehmet Özer","poet_slug":"mehmet-ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/adini-istanbul-koydum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Seni Çoktan Unuttum', 'ben-seni-coktan-unuttum-mehmet-ali-sahin-b9vn0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Arama sorma boşuna

Ben seni çoktan unuttum

Mendil verme göz yaşıma

Ben seni çoktan unuttum

Karışma benim işime

İnce giyip de üşüme

Girme artık kız düşüme

Ben seni çoktan unuttum

Mehmet Ali bir çırayım

Alevlere sarılayım

Boş kalsın gönül sarayım

Ben seni çoktan unuttum', 'Arama sorma boşuna Ben seni çoktan unuttum Mendil verme göz yaşıma Ben seni çoktan unuttum Karışma benim işime İnce giyip de üşüme Girme art...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Şahin']::text[], 8.5, '{"poet":"Mehmet Ali Şahin","poet_slug":"mehmet-ali-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ben-seni-coktan-unuttum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıra Kendinde mi...', 'sira-kendinde-mi-i-brahim-ethem-bingul-10qe3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gülme komşuna gelir sana da

Deme arkadaş

Gülünmeyecek gibi değil ki durumun...

Yıllarca ördün o çorapları

Ellerin başına, acımasızca

Şimdi sıra kendine mi? ..

Uyanacaksın bir sabah

Uykunun en tatlı yerinde

Başında bin desenli çorap ile...

Şimdi bakıp bakıp 

Gülünmezde ne yapılır

Senin gibisinin şu haline...

www.iebingul.com', 'Gülme komşuna gelir sana da Deme arkadaş Gülünmeyecek gibi değil ki durumun... Yıllarca ördün o çorapları Ellerin başına, acımasızca Şimdi s...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sira-kendinde-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdalı Kelimeler', 'sevdali-kelimeler-nuri-gokhan-sonsel-jbrve', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ilık  tatlı bir  baharın, renkleri  var  yüzünde,

Geceler  daha  parlak, o  simsiyah  gözünde.

Dudağında  bir  tebessüm, sevgi  vardı  sesinde,

Koyu  kahve  saçlarını, toplardı   ensesinde.

İçimizde  bir  kor  vardı, sebebini  bilmezdik,

Yudum, yudum  sevdayı, içerek  serinlerdik.

Kalbimizde  aşk  vardı,sevginin  ötesinde,

Biz   el ele   dolaştık,  bu  gönül  bahçesinde.

Hayat  senle  güzeldi,  gençlik  senle  güzeldi,

Kurduğumuz  tüm  hayaller, sevdamızla  güzeldi.

Kalmamıştı  acımız, kalmamıştı  kederler,

Kalbimizde  çığlık, çığlık, sevdalı  kelimeler.

Tek, tek  yapraklar  koptu, en  güzel  günler  bitti,

Saçlarımız  bembeyaz, bu gençlik  elden  gitti.

Bitmedi  bu  aşkımız, tükenmedi  hülyamız,

Çünkü….ölürken  bile, sürecek  bu  sevdamız. 

Belki  öldükten  sonra … böyle de  devam  eder,

Kaybolmadı  içimde, sevdalı  kelimeler.', 'Ilık  tatlı bir  baharın, renkleri  var  yüzünde, Geceler  daha  parlak, o  simsiyah  gözünde. Dudağında  bir  tebessüm, sevgi  vardı  sesin...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sevdali-kelimeler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Yağmuru', 'sevgi-yagmuru-nuri-gokhan-sonsel-xycrn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dinle bir tanem dinle,  şu kalbimin sesini,

Seninle var olurken, duyarsın neşesini.

Benim aşkım tertemiz, billurdan daha duru,

Gözlerimden akan yaş, coşan sevgi yağmuru.

Sevgimizin rüzgarı, sert esiyor dağlarda,

Kuşlar neşe içinde, bahçelerde bağlarda.

Soruyorlar bir tanem, bana binlerce soru,

Bekliyorlar sabırla, bizden sevgi yağmuru.

Suskun durma bir tanem, aşkını söyle bana,

Böyle boş bir sessizlik, yakışmıyor ki sana.

Yapraklar boyun eğmiş, topraklar hala kuru,

Serinlemek zamanı, yağsın sevgi yağmuru.

Çok  mutluyum bir tanem,  şimdi yorgun değilim,

Seviyorsun anladım,  sevinçten ölmeliyim.

Ağlamıyorum artık, bak gözlerim kupkuru,

Aşkımızın üstüne, yağsın sevgi yağmuru.', 'Dinle bir tanem dinle,  şu kalbimin sesini, Seninle var olurken, duyarsın neşesini. Benim aşkım tertemiz, billurdan daha duru, Gözlerimden a...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevgi-yagmuru-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni', 'seni-mehmet-ali-sahin-v874s', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dağ başında avcı olsam

Al ile avlasam seni

Çiçeğinde arı olsam

Bal ile tavlasam seni

Gök yüzünde kamer olsam

Kalbe giden damar olsam

İnce bele kemer olsam

Sıkıca bağlasam seni

Mehmet Ali kulun olsam

Gezindiğin yolun olsam

Ağzındaki dilin olsam

Yürekten dağlasam seni

16.3.2004', 'Dağ başında avcı olsam Al ile avlasam seni Çiçeğinde arı olsam Bal ile tavlasam seni Gök yüzünde kamer olsam Kalbe giden damar olsam İnce be...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Şahin']::text[], 8.5, '{"poet":"Mehmet Ali Şahin","poet_slug":"mehmet-ali-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/seni-60-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevginin Analizi', 'sevginin-analizi-nuri-gokhan-sonsel-y2qwc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bazen bir sevgi bulursun, sevgilerin içinde,

Bu sevgi seni sarar, çok ayrı bir biçimde.

Yükselir dalga, dalga, rüzgarlarla buluşur,

Bazen de sevgi biter, zıt kutuplar oluşur.

Sevgi  yüksek enerji,  fazla versen şok olur,

Düşürürsen voltajını, birden bire yok olur.

Sevgi sırrı paylaşmak, sevgiyle kucaklaşmak,

Sevginin dili olmaz, mühim olan anlaşmak.

Sevgi  duygu selidir, özveri güven ister,

Sevgi bir tebessüm, daima dostluk ister.

Bazı özel günlerde, küçücük bir hediye,

Verelim ki inanılsın, inanılsın sevgiye.

Sevgi ayrı aşk ayrı,  cinsellik başka terim,

Birbirine karışmasın, aman dikkat edelim.

Aşk gözleri kör  eder, kötülük göremezsin,

Sevda düşer kalbine,  görür de bilemezsin.

Anne evladı sever, canından da daha çok,

Anne gibi  bulunmaz, bir sevdalı çünkü yok.

Sevgiler olmasaydı, bir millet olur muydu,

Bayraklar dalgalanır,  göklerde durur muydu? .

Sevgi güzel bir duygu, sevelim sevilelim,

Bizi seven her kimse, kıymetini bilelim.

Sevgi gerçekse eğer, saf olur temiz olur,

Sevmesini  bilenler, sonunda mutlu olur.', 'Bazen bir sevgi bulursun, sevgilerin içinde, Bu sevgi seni sarar, çok ayrı bir biçimde. Yükselir dalga, dalga, rüzgarlarla buluşur, Bazen de...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sevginin-analizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Çok Seviyorum.', 'seni-cok-seviyorum-nuri-gokhan-sonsel-idqst', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu  sevda kanser  gibi,  sarmış  hücrelerimi,

Zerrecikler halinde,  yerleşmiş yüreğime.

Beni  bir tek  anlayan, sırlarımı  döktüğüm,

Derdimi  paylaştığım, senden başka kim var ki? 

Şiirlerimde konum, benim ilham perimsin,

Sen benim bir tanemsin, sen benim her şeyimsin.

Geçen her bir  dakika,  geçen her bir  saniye,

Seviyorum bir tanem, seni çok seviyorum.

Seni bir an göremez, sesini duyamazsam,

Buharlaşır bedenim, çıkarım gökyüzüne.

Bir an saman yolunda, yıldızlarla beraber,

Bakarım yeryüzüne, hep seni düşünürüm.

Ben bu duygu yükünü, taşır avuçlarımda,

Yalnız senin kalbine, bunu yerleştiririm.

Üzülmeni  istemem, silerim ellerimle,

Senin ezelden parlak, yemyeşil  gözlerini.

Sen  güllerden çok güzel, bir nadide çiçeksin,

Nasıl  sevemem  seni,  sen benim bir tanemsin.

Ellerin ellerime, biraz değdiği zaman,

İnan sanki yanarım, kavrulurum ben o an…

Gelecekte bir gün ben, eğer sensiz ölürsem,

Sevdamla kefenlensin, o  gün cansız bedenim.

Meleklerin elinde, bulunan defterimde,

Sevdalı bu diyerek, günahlarım silinir.

Girersem ben cennete, orda seni beklerim,

Sen bensiz yapamazsın, ben ise de hiç sensiz.

Buluşuruz bir tanem, aşkımız devam eder,

Sevdalı kalbinle gel, fazla bekletme beni.', 'Bu  sevda kanser  gibi,  sarmış  hücrelerimi, Zerrecikler halinde,  yerleşmiş yüreğime. Beni  bir tek  anlayan, sırlarımı  döktüğüm, Derdimi...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/seni-cok-seviyorum-116-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kefaletsiz ''Kİ''', 'kefaletsiz-ki-yusuf-mete-tekel-yet7w', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevda ki istemez yüreğim.

Yoldaş ki istemez yolum.

Bağır ki istemez hıçkırıklarım.

Güneş ki istemez gecem.

Ben ki hüznüm,

Yalnızlığımı isterim.

Varlık ki istemez yoksulluğum.

Nefes ki istemez darlığım.

Pınar ki istemez yangınım.

Cennet ki istemez canım.

Ben ki yusufum,

Cehennem kuyuları isterim.

Sahil ki istemez denizim.

Ölçü ki istemez tabiatım.

Dinginlik ki istemez canım.

Varlık ki istemez yoksunluğum.

Ben ki ikiyim,

Hiçliğimi isterim.

Bir aşk ki kanatlanmakta benliğim.

Bir ant ki gülümsemekte derinlerim.

Bir yücelik ki titremekte her yerim.

Bir savaş ki buharlaşmakta kirlerim.

Yokluğun ki nefsim,

Sonrası zaferim.', 'Sevda ki istemez yüreğim. Yoldaş ki istemez yolum. Bağır ki istemez hıçkırıklarım. Güneş ki istemez gecem. Ben ki hüznüm, Yalnızlığımı ister...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Mete Tekel']::text[], 8.5, '{"poet":"Yusuf Mete Tekel","poet_slug":"yusuf-mete-tekel","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kefaletsiz-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soruyorlar Kim Diye', 'soruyorlar-kim-diye-nuri-gokhan-sonsel-aa8w1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Soruyorlar  dostlarım, bu  bir tanem  kim  diye,

O  kalbimde  yaşayan, uzun  manzum  bir  hikaye.

Çok  değerli bir  sevgili, kalemimin  ucunda,

Yazdığım  şiirlerde, her  zaman baş  ucumda.

Zaman   gelir   kızarım, öfke  ile  karışık,

Zaman  gelir  överim, o  buna  hep  alışık.

Bazen  o  kalbimin, en  nadide   köşesi,

O  benim  gonca   gülüm, şiirimin  neşesi.

O  benim  hoş  kokulu, her  zaman  taze gülüm,

Doğaya  pes  etmeyen, çile  çeken  bülbülüm.

O  benim  beklediğim, çağırdığım  sevgili,

Ne darılır  ne  küser, nede  unutur  beni.

O  aşkı  iyi  bilir, sevda  ile  doğmuştur,

Yazdığım  her  heceye, o  yardımcı  olmuştur.

Deniz  olur  dağ  olur,yankılanır  yanımda,

O   benim  bir tanemdir, o  sadece  canımda.

Sesi  öyle  tatlı  ki, billurdan  daha  duru,

Her  zaman  hüzün verir, gözleri  hala  kuru.

Saçı  gözü  ne  renktir, vallahi   bilmiyorum,

O  benim  ilham   perim, ben on’u  seviyorum.', 'Soruyorlar  dostlarım, bu  bir tanem  kim  diye, O  kalbimde  yaşayan, uzun  manzum  bir  hikaye. Çok  değerli bir  sevgili, kalemimin  ucun...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/soruyorlar-kim-diye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasıl Unutayım', 'nasil-unutayim-mehmet-ali-sahin-027ps', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir meleksin sen gözümde

Yalan yoktur bu sözümde

Gece gündüz hep dizimde

Öpücükle büyüteyim

Benler vardır gerdanında

Her zaman olsan yanımda

Gel seni güzel koynumda

Ninnilerle uyutayım

Gel diyorum gelmiyorsun

Sev diyorum sevmiyorsun

Bir öpücük vermiyorsun

Gönlüm neyle avutayım

Mehmet Ali dert var bende

Tek bir nefes kalmış tende

Şeytan tüyü var kız sende

Söyle nasıl unutayım

17.3.2004', 'Bir meleksin sen gözümde Yalan yoktur bu sözümde Gece gündüz hep dizimde Öpücükle büyüteyim Benler vardır gerdanında Her zaman olsan yanımda...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Şahin']::text[], 8.5, '{"poet":"Mehmet Ali Şahin","poet_slug":"mehmet-ali-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/nasil-unutayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Merak Etme', 'merak-etme-mehmet-ali-sahin-k8sdu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Haşin haşin bakıyorsun

Gözlerinden bildim  seni

Ciğerimi yakıyorsun

Yüreğimden sildim seni

Resimlerini yakayım

Dönüp külüne bakayım

Gönül dosyama takayım

Hışım ile deldim seni

Mehmet Ali ne yapayım

Bu dosyayı kapatayım

Bu da benim aslan payım

Merak etme sevdim seni

19.3.2004', 'Haşin haşin bakıyorsun Gözlerinden bildim  seni Ciğerimi yakıyorsun Yüreğimden sildim seni Resimlerini yakayım Dönüp külüne bakayım Gönül do...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Şahin']::text[], 8.5, '{"poet":"Mehmet Ali Şahin","poet_slug":"mehmet-ali-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/merak-etme-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayallerimde ki İstanbul', 'hayallerimde-ki-i-stanbul-sezgin-ozpinar-ng15s', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben küçük bir çocukken, dedem

Anlatırlardı hep bana İstanbul’u,

Şarkılar sözler yazıldı hep onun için,

Hayallerimdeki İstanbul için,

Ben küçük bir çocukken,dedem

Yedi tepe üzerinde kurulmuş,

İstanbul’u anlatırlardı hep,

Hayallerimdeki İstanbul’u

Ben küçük bir çocukken, dedem

Anlatırdı, Fatih Sultan Mehmet’in

İstanbul’u ne zorluklarla aldığını hep,

Hayallerimdeki İstanbul’u', 'Ben küçük bir çocukken, dedem Anlatırlardı hep bana İstanbul’u, Şarkılar sözler yazıldı hep onun için, Hayallerimdeki İstanbul için, Ben küç...', ARRAY['Türk Edebiyatı','Şiir','Sezgin Özpınar']::text[], 8.5, '{"poet":"Sezgin Özpınar","poet_slug":"sezgin-ozpinar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hayallerimde-ki-istanbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güncel Beyitler 94', 'guncel-beyitler-94-huseyin-avdic-8xjhm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'E$cinsel Evlilik! 

Evlenerek(!)  me$ruiyet kazanamaz e$cinseller ve lezbiyenler.

Hak evlilik kar$i cinsledir, Hakk''a uymali uygunsuz ciftle$enler.

Berlin, 20 Mart 2006.', 'E$cinsel Evlilik!  Evlenerek(!)  me$ruiyet kazanamaz e$cinseller ve lezbiyenler. Hak evlilik kar$i cinsledir, Hakk''a uymali uygunsuz ciftle$...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/guncel-beyitler-94-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Susmasını Öğrendim', 'susmasini-ogrendim-nuri-gokhan-sonsel-i4fw4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Biliyorsun bekliyordum, bir gün geri dönmeni,

Hani bana söz vermiştin, nasıl aldattın beni? 

Anladım ki gönül kuşum, sen beni düşünmedin,

Gönül sustu yürek sustu, susmasını öğrendim.

Günler bitti yıllar geçti, sen sözünü tutmadın,

Ne kadar acı çeksem, tek bir gün unutmadım.

Bu kadar da kalpsizliğine, bir mana veremedim,

Güneş sustu yıldız sustu, susmasını öğrendim.

Sana mektuplar yazdım, bir cevap alamadım,

Bir tek resmin kalmıştı, o’nu da bulamadım.

Anladım ki gönül kuşum, sen beni hiç sevmedin,

Kalem sustu kâğıt sustu, susmasını öğrendim.

Sana telefon ettim, bir erkek sesi çıktı,

Sesimdeki bu heyecan, sanki bir hıçkırıktı.

Soramadım gönül kuşum, soğuk, soğuk terledim,

Kalbim sustu dilim sustu, susmasını öğrendim.

Dediler ki komşuların, o geçen yıl evlendi,

Sanki sen bir oyuncaktın, o seninle eğlendi.

Bilemedim gönül kuşum, belki tahmin etmedim,

Evren sustu hayat sustu, susmasını öğrendim.', 'Biliyorsun bekliyordum, bir gün geri dönmeni, Hani bana söz vermiştin, nasıl aldattın beni?  Anladım ki gönül kuşum, sen beni düşünmedin, Gö...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/susmasini-ogrendim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öldür', 'oldur-mehmet-ali-sahin-vbn6l', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Benim kanayan yaramı

Durdur durdurabilirsen

Acı çektirme yar bana 

Vurdur vurdurabilirsen

Takatım yok yürümeye

Kalp başladı çürümeye

Kemiklerim erimeye

Sardır sardırabilirsen

Mehmet Ali yara bende

İnanırım derman sende

Bir nefesim kaldı tende

Öldür öldürebilirsen

26.2.2004', 'Benim kanayan yaramı Durdur durdurabilirsen Acı çektirme yar bana  Vurdur vurdurabilirsen Takatım yok yürümeye Kalp başladı çürümeye Kemikle...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Şahin']::text[], 8.5, '{"poet":"Mehmet Ali Şahin","poet_slug":"mehmet-ali-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/oldur-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şarkı Gibisin', 'sarki-gibisin-nuri-gokhan-sonsel-3jyfh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir  sen  vardın  içimde, birde  beyaz  zambaklar,

İlk günün  ışıkları  gibi, kirlenmemiş  sabahlar.

Serinlikte  erkenden, açılırken  goncalar, 

Sen  içimde  çok eski, mahur  şarkı  gibisin        

Oturarak  kumlara, dalgalarla  tanıştım,

Bembeyaz  köpüklerle, uzun,uzun   konuştum.

Geçen  yıl  ben  seni, yine  burada  bulmuştum,

Sen  yeni  bestelenmiş, hüzzam  şarkı  Gibisin.

Sen değil  miydin  bu  sabah, gördüğüm  güzel,

Yoksa  yine  mi…yine  mi…o  eski  rüya? 

Uçarken  gönlümde,  mutluluk  kelebeği,

Sen  dilimde  nihavent, şarkı  gibisin.

Sen  benim  bir tanem, sen  benim  gönül  kuşum,

Seviyorum  seni  ben, aşkınla  ben  sarhoşum.

Sen  benim  geçmiş  mazim, sen  benim  geleceğim,

Sen  benim  en  son  bestem, hicaz  şarkı  gibisin.

Güllerden  daha  güzel, mor  gelincik  olur mu,

Dalgalanmayan deniz, hiç  sahile  vurur  mu.

Bu  gönlüm  seni  görür, duygulanmaz  durur  mu,

Sen  içimde  son  şarkım, bestenigar  gibisin.', 'Bir  sen  vardın  içimde, birde  beyaz  zambaklar, İlk günün  ışıkları  gibi, kirlenmemiş  sabahlar. Serinlikte  erkenden, açılırken  goncal...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sarki-gibisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğren', 'ogren-sezgin-ozpinar-72xbf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevmeyi öğren; Kendini sevmeyi öğren,

Anneni,Babanı sevmeyi öğren,

Eşini,çocuklarını,evini sevmeyi öğren,

Akrabalarını,Komşularını sevmeyi öğren,

İşini,aşını sevmeyi öğren,

İş arkadaşlarını sevmeyi öğren,

Sahip olduğun imkanları sevmeyi öğren,

Şükretmeyi öğren,

Hayvanları, çiçekleri sevmeyi öğren,

Doğayı sevmeyi öğren,

İnsanlarla yardımlaşmayı öğren,

Paylaşmayı öğren,

Duygusuz olma! Hissetmeyi öğren,

Zalim olma! Şefkati öğren,

Tembel olma! çalışmayı öğren,

Hain olma! sadakati öğren,

Öğren ki cahillerden olma,

Anla ki ilgisizlerden olma,

Çalış ki tembellerden olma,

İnan ki inkarcılardan olma...!', 'Sevmeyi öğren; Kendini sevmeyi öğren, Anneni,Babanı sevmeyi öğren, Eşini,çocuklarını,evini sevmeyi öğren, Akrabalarını,Komşularını sevmeyi ö...', ARRAY['Türk Edebiyatı','Şiir','Sezgin Özpınar']::text[], 8.5, '{"poet":"Sezgin Özpınar","poet_slug":"sezgin-ozpinar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ogren-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tükendim', 'tukendim-nuri-gokhan-sonsel-keyx9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sanki bir  yaz  yağmuru, sevda  senin  gönlünde,

Anımsanacak  kadar, sevilmedim  bir tanem.

Kalbimde  çırpınışlar, beynimde  bir  uğultu,

Senin  için  tükendim…tükendim  ben bir tanem.

Kaybetmiştim  yolumu, bu  kör  akşamlarında,

Gözlerinin  ışığı, aydınlattı  bir tanem.

Yükselirken  göklerde, bu  ışık  perde,perde,

Sevgim  tükenmedi  hiç…tükendim  ben  bir tanem.

Kanattı  tüm  dalların,kanattı  dikenlerin,

Seni  gülüm  sanmıştım, değilmişsin  bir tanem.

Seni  bülbülden  fazla, bin  kat  fazla  sevmiştim,

Sevdama  yazık  oldu….tükendim  ben  bir tanem.

Ağaçlarda  söylenirken, hep  sevdalı   türküler,

Şimdi  kuşlar  sustular, benim  için  bir tanem.

Seni   bana  unutturan,ölüm  denen  bu  uyku,

Geldi  sensiz  ansızın…..tükendim  ben  bir tanem.', 'Sanki bir  yaz  yağmuru, sevda  senin  gönlünde, Anımsanacak  kadar, sevilmedim  bir tanem. Kalbimde  çırpınışlar, beynimde  bir  uğultu, Se...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/tukendim-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Eski Günler', 'o-eski-gunler-sezgin-ozpinar-l0wvu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'O eski günleri hatırlamak isterdim,

O eski günleri anlatmak isterdim,

O eski günleri tekrar yaşamak isterdim,

O eski günler anılarımdan çıkmıyor hiç,

O eski günleri yaşamayı öyle isterdim ki,

O eski yerleri gezmek isterdim ki,

O eski evimizi gitmek isterdim ki,

O eski barakamızı görmek isterdim ki,

O eski yıllar nasıl geçti bilmeden,

O eski günler nasıl geçti bilmeden,

O eski saatler nasıl geçti bilmeden,

O eski aylar nasıl geçti bilmeden,', 'O eski günleri hatırlamak isterdim, O eski günleri anlatmak isterdim, O eski günleri tekrar yaşamak isterdim, O eski günler anılarımdan çıkm...', ARRAY['Türk Edebiyatı','Şiir','Sezgin Özpınar']::text[], 8.5, '{"poet":"Sezgin Özpınar","poet_slug":"sezgin-ozpinar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/o-eski-gunler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muhtelif Nükteler (9)', 'muhtelif-nukteler-9-mevlut-bicik-tqyx8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kardeşim akıllı geçinen biz büyükler,

Çocukların yapmadığı,hataları yapıyoruz.

Çocuklarımızı ememiyen kahpe sülükler,

Her tarafımızdan emiyorda,biz bakıyoruz.

Efendiler! Namaz kılarken telefona değil,

Dönün, tekrar-tekrar kalblerinize bakın.

Seytanın vesvesesine teslim ol vede eğil,

Sonrada namaz kıldım,zannetmeyin sakın.

Kalıp namazda,kâlb ise seyâhat’da iken,

Telefonun sesi,müziği bunun yanında hiç kalır.

Müslümânın kalbinin etrafını sarmışken diken,

Kılınan namazdan,nefisden başka kim zevk alır.

Görünce manzarayı aklım ve dimağım durdu.

Orası medenî zannedilen,yamyamların yurdu.

Dağlarda gezen kurtlar bile,bunlardan daha medenîdir,

Görünen resim bunların vicdansızlığını zirveye vurdu.

Günahsız insan tevbeye ihtiyaç duymaz.

Bu halde olmakta, sünnetüllah’a uymaz.

Ínsanoğlu günah-sevab ekseninde gezer,durur,

Allah’dan ümid kesip’de olmamalı aymaz.

Mevlüt Bicik

21.03.2006  saat  13.10

Esslingen', 'Kardeşim akıllı geçinen biz büyükler, Çocukların yapmadığı,hataları yapıyoruz. Çocuklarımızı ememiyen kahpe sülükler, Her tarafımızdan emiyo...', ARRAY['Türk Edebiyatı','Şiir','Mevlüt Bicik']::text[], 8.5, '{"poet":"Mevlüt Bicik","poet_slug":"mevlut-bicik","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/muhtelif-nukteler-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uğurlar Olsun', 'ugurlar-olsun-nuri-gokhan-sonsel-nnolp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kapılmıştım aşkının, sevda seline,

Âşıktım saçının, her bir teline.

Ayrılamazdım yanından, bir tek gün bile,

Terk edip gittin, uğurlar olsun.

Değmezmiş uğruna, döktüğüm yaşa,

Değmezmiş bağrıma, bastığım taşa.

Sonunda gelirmiş, ayrılmak başa

Değmezmiş sevmeye, uğurlar olsun.

Değmezmiş uykusuz, gecelerime,

Yazdığım şiirde, hecelerime.

Yazmakla bitmez ki, nicelerine,

Değmezmiş sevmeye, uğurlar olsun.

Değmezmiş bir ömrü, bağladığıma,

Pınarları kurutup, ağladığıma.

Hani… aşk sözü, vermiştin bana,

Değmezmiş sevmeye, uğurlar olsun.

Hâlbuki ne kadar, sevmiştim seni,

Okşardım elimde, hep ellerini.

Yok, ettin giderken, hayallerimi,

Dönme bir daha, uğurlar olsun.

Değmezmiş sana, verdiğim değer,

Karanlığa karıştı, buluştuğumuz yer.

Bir gün pişman olur da, dönersen eğer,

İstemem aşkını, uğurlar olsun.', 'Kapılmıştım aşkının, sevda seline, Âşıktım saçının, her bir teline. Ayrılamazdım yanından, bir tek gün bile, Terk edip gittin, uğurlar olsun...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ugurlar-olsun-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seviyorum Diye', 'seviyorum-diye-mehmet-ali-sahin-9cwri', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gel beraber yüksekleri gezelim

Duygulandırıyor kayalar beni

Ne gerek var al dudağa güzelim

Sürme, öldürüyor boyalar beni

Yanına yaklaşsam elin vermiyor

Saçını okşasam telin vermiyor

Öpmek istiyorum dilin vermiyor

Seviyorum diye oyalar beni

Söyle hakkımdaki sözü duysunlar

İstiyorsan gözlerimi oysunlar

Yalanım var ise kabre koysunlar

Talkın sırasında duyalar beni

10.11.2001', 'Gel beraber yüksekleri gezelim Duygulandırıyor kayalar beni Ne gerek var al dudağa güzelim Sürme, öldürüyor boyalar beni Yanına yaklaşsam el...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Şahin']::text[], 8.5, '{"poet":"Mehmet Ali Şahin","poet_slug":"mehmet-ali-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/seviyorum-diye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutmak mı?', 'unutmak-mi-nuri-gokhan-sonsel-6xe0p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aramızda, dağlar olsa, 

Sır vermeyen, yollar olsa,

Geçmiş uzun, yıllar olsa,

Unutmak mı, mümkün değil sevdiğim.

Gönlümün sana, aktığı yerde,

Sensiz acıyı, tattığı yerde.

Akşam güneşinin, battığı yerde,

Unutmak mı, mümkün değil sevdiğim.

Sen gideli, yıllar oldu hastayım,

Gülmek bana, haram oldu yastayım.

Kavuşmamız sadece, bir varsayım,

Unutmak mı, mümkün değil sevdiğim.

Nasibim ayrılmakmış, gülemem artık,

Son bir defa görmeye, gelemem artık.

Senden başkasını da, sevemem artık,

Unutmak mı, mümkün değil sevdiğim.

Aşk yıldızlarının, olduğu yerde,

Kalbimin sevdayı, bulduğu yerde.

Her gece mehtabın, doğduğu yerde,

Unutmak mı,mümkün değil sevdiğim.

Sevdamın su olup, aktığı yerde,

Dizinde başımın, yattığı yerde.

Güneşin imrenip, baktığı yerde,

Unutmak mı, mümkün değil sevdiğim.

Ümitler tükenip, yittiği yerde,

Gönlümün kuş olup, gittiği yerde.

Ruhumun eriyip, bittiği yerde,

Unutmak mı, mümkün değil sevdiğim.', 'Aramızda, dağlar olsa,  Sır vermeyen, yollar olsa, Geçmiş uzun, yıllar olsa, Unutmak mı, mümkün değil sevdiğim. Gönlümün sana, aktığı yerde,...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/unutmak-mi-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unuttum', 'unuttum-nuri-gokhan-sonsel-epq0x', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yorgun  düştü  şu gönlüm, ne  olur  anla  beni,

Yaşıyor  muyum   neyim, ben  kendim de  unuttum.

Beni  üzmekse  maksadın, gelme  bana  git  artık,

Sevmeyi  sevilmeyi, ben  gülmeyi  unuttum.

Üzme  beni  bir tanem, o kadar  halsizim  ki,

Güneş   battı  ve  doğdu, ben  günleri  unuttum.

Mevsimler  teker,teker, eriyerek  yok olmuş,

Mevsimlerin  adını, ben   dünyayı   unuttum.

Gelmek  istemiyorsan  gelme, unuturum adını,

O  güzel  gözlerinle, ben  yüzünü  unuttum.

Sen  yokken   bir tanem, bir   tek  unutmadığım,

Sana  olan  sevdamı, öldürmeyi  unuttum.

Sen  aşkı  bilmiyorsan, ben  nasıl  öğreteyim,

Bildiğim  bir  çok  şeyi, zaten  çoktan  unuttum.

Sen  benim    bir tanemdin, yaşama   sevincimdin,

Sensiz  nefes  almayı, yaşamayı  unuttum.', 'Yorgun  düştü  şu gönlüm, ne  olur  anla  beni, Yaşıyor  muyum   neyim, ben  kendim de  unuttum. Beni  üzmekse  maksadın, gelme  bana  git  ...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/unuttum-55-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yedi Kardeş', 'yedi-kardes-oktay-baykurt-l2bw1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'biz yedi kardeştik

yetmiş mahalleli şehrin kedileri

fare parodilerinin jönleriydik

deniz kokmazdı ağzımızda

vurdum duymaz dertler doyururdu karnımızı.

kepekli havalarda hayyallenir

soğuk kırıntıları yapardık kemikten kayıklarımızı

ipotekli çöp bidonlarımız vardı,bir gecelik

bir gün göz boyar ertesi gün diz bükerdik

kediydik işte yedi bıyıklı

kah sahipsizliğin anyasında geçerdi zaman

kah çocuk taşlarının konyasında

yine de vardık işte köpeklere inat

yaşasın kurtarıcımız erik dalları.', 'biz yedi kardeştik yetmiş mahalleli şehrin kedileri fare parodilerinin jönleriydik deniz kokmazdı ağzımızda vurdum duymaz dertler doyururdu ...', ARRAY['Türk Edebiyatı','Şiir','Oktay Baykurt']::text[], 8.5, '{"poet":"Oktay Baykurt","poet_slug":"oktay-baykurt","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yedi-kardes-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unuttum desem', 'unuttum-desem-nuri-gokhan-sonsel-amf4c', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Unuttum  desem, inanır mısın ? 

 Senin  güzel  yüzünü…

 Unuttum  desem, o yeşil  gözlerini…

 Unuttum  desem, sevdalı  bakışları,

 Unuttum  desem, senin  bahar  kokunu.

                         Bana  inanır mısın? ..

 Unuttum  desem, inanır  mısın? 

 Mutlu  geçen  günleri…

 Unuttum  desem, sevdiğim şarkıları..

 Unuttum  desem, adanın  çamlarını,

 Unuttum  desem, fayton  sefalarını.

                        Bana  inanır mısın? ...

 Unuttum  desem, inanır mısın? 

 Artık  senin   adını…

 Unuttum  desem, gençlik anılarımı.

                         Bana inanır mısın? ...', 'Unuttum  desem, inanır mısın ?   Senin  güzel  yüzünü…  Unuttum  desem, o yeşil  gözlerini…  Unuttum  desem, sevdalı  bakışları,  Unuttum  d...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/unuttum-desem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vasiyet', 'vasiyet-nuri-gokhan-sonsel-9gmvu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir  Tanem…

Gökyüzü aniden, çökecek bir gün,

Bu yorgun kalbim ve omuzlarıma.

Melekler gelecek, duracak yüreğim,

Beni ve sevdamı alıp,  alıp…götürecekler.

Cesedim girmeden, o kara topraklara,

Toprağım karışsın, sararmış  yapraklara.

O gün fatiha gönder, yalnız o gün hatırla,

Mezarıma bir gül  dik, nazik parmaklarınla.

Yine bu günkü gibi, göremeden yüzünü.

Hoş kokunu duymadan, özleyeceğim seni.

Gelme benim bir tanem, uğrama mezarıma,

Yokluğuna katlanırım, seni unutmasam da.

Benim için yas tutma,  eğlen kendi gönlünce,

Yeniden mi doğacağım, sanki sensiz ölünce.

Mezar taşı  istemem, özgür olsun bedenim,

Kimseler bulamasın, varsa gelip  gidenim.

Yalnızca birinci yıl, bir keman eşliğinde,

Bana şarkılar söyle, sen yine bildiğince.

Bir daha hiç  uğrama, beni hiç hatırlama,

Bu sana vasiyetim, aşkımın hatırına.', 'Bir  Tanem… Gökyüzü aniden, çökecek bir gün, Bu yorgun kalbim ve omuzlarıma. Melekler gelecek, duracak yüreğim, Beni ve sevdamı alıp,  alıp…...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/vasiyet-56-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Olayım Ben!', 'son-olayim-ben-yusuf-mete-tekel-6hndy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Annem annem! 

Ettiğin dualar kabul oldu,

Bak aslan oğlun geldi, annem.

Yalnız ben değil arkadaşlarım da geldi,

Onlara seni anlattım, elini öpmek istediler, annem.

Kaçamak bir bakış da sevdiğime,

Bak sana papatyalar da getirdik, annem.

Kardeş kardeşe silahlarla çelik çomak oynadığımız kırlardan,

Biraz benim biraz da kardeşimin kanıyla sulanan papatyalar,annem.

Sen üzme tatlı canını, 

Oyun kalleş olsa da yüreklerimiz kardeş, annem.

Ah! Neden ağlarsın ki

Dedim ya oyun kalleş, annem.

Bak babama, beyazlar içinde ne de şen,

Koklasana beni, yavrum, yusufum desene, annem.

Oh! Şöyle,seni ne çok özledim,

Hep bu anı beklemedik mi! daha çok sarıl,annem.

 Sarıl çiğeri yanık annem sarıl,

Gidiyor herkes, kıskandılar bizi, annem.

Ağacın duldasındaki utangaç sevdamı da çağır,

Artık ayrılık yok, hep burdayım annem.

Ağlama, bak artık kanımda akmıyor,

Bak bir elimi babam tutmuş, gülümsüyor annem.

Hadi diğer elimi de sen tut,

Çocukluğumdaki gibi, annem.

Ağlama, bak artık zaman da akmıyor,

Hadi gülüm gülümse, gülümse annem.

Annem annem..', 'Annem annem!  Ettiğin dualar kabul oldu, Bak aslan oğlun geldi, annem. Yalnız ben değil arkadaşlarım da geldi, Onlara seni anlattım, elini ö...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Mete Tekel']::text[], 8.5, '{"poet":"Yusuf Mete Tekel","poet_slug":"yusuf-mete-tekel","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/son-olayim-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanılgı', 'yanilgi-salim-kanat-fnxjp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne kadar haklıysa

Malthus teoride

Aksini ispat için

Ben varım pratikte

Çok güzel izleniyor sizin oralar

Burada çok net manzaralar

İçimde gezinen mısralar

Terk ediyor beni sen aklıma gelince

Ve başlıyor eyvah

Bitimsiz âfetler

Biliyorum

Teori nasıl geçerse hayatı es

Şiir de öyle geçer duyguları teğet

Bu da olmasa artık

Geriye kalan

Matematik kesinliğinde ''sefalet''

(Ocak 2006)', 'Ne kadar haklıysa Malthus teoride Aksini ispat için Ben varım pratikte Çok güzel izleniyor sizin oralar Burada çok net manzaralar İçimde gez...', ARRAY['Türk Edebiyatı','Şiir','Salim Kanat']::text[], 8.5, '{"poet":"Salim Kanat","poet_slug":"salim-kanat","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yanilgi-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur', 'yagmur-nuri-gokhan-sonsel-7qjt9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ilık bir yağmur var dışarıda,

Sen  yağıyorsun.

Çatlamış dudaklarımı sen,

Sen ıslatıyorsun.

Yerler nemli, ağaç ıslak, 

Kalbim ise, sırılsıklam.

Kurutmadan gözyaşımı,

Sen nereye bir tanem, nereye  gidiyorsun? ..

Ağlamasın bu  dört  mevsim,  gökler yine hıçkırmasın,

Dön artık  bir tanem, gözlerime kan dolmasın.

İsterse fırtınayla, bulutlar yere insin,

Götürsün sel suları, hasretim sona ersin. 

İsterse ağaçlar, ta..kökünden sökülsün,

Kabarsın taşsın deniz, ovalara dökülsün.

İsterse deprem olsun, bütün dünya yıkılsın,

Hayat beni bağlamaz…sen olmayınca.

Söyle bana bir tanem,  ne zaman geleceksin,

Nasıl bir giysiye bürünüp, sen geri döneceksin? 

Belki ılık bir yağmur mu,  belki bir kar tanesi mi,

Nasıl dönersen dön bir tanem…sakın unutma beni. 

İster yine bir yağmur ol, içime  akarak  gel,

İster kaynar bir buhar ol, kalbimi yakarak gel.

İster ağlat, ister  güldür, yüzüme bakarak  gel,

Gel artık,  gel  bir tanem, sakın  unutma  beni.', 'Ilık bir yağmur var dışarıda, Sen  yağıyorsun. Çatlamış dudaklarımı sen, Sen ıslatıyorsun. Yerler nemli, ağaç ıslak,  Kalbim ise, sırılsıkla...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yagmur-281-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızım', 'yalnizim-nuri-gokhan-sonsel-63quw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sıcaklar  bunalttı, yağmur  Islattı,

Hastalandı gönlüm, günlerce  yattı.

Sözde  olan  dostlarım, beni  aldattı,

Yalnızım  bir tanem…yalnızım sensiz.

Ne gelen  var  ne  giden, nede  telefon  eden,

Bir  kusur  mu   işledim…acep   bilmeden? 

Bir  defa da  sen ara sor,ömrüm  bitmeden,

Yalnızım   bir tanem…yalnızım  sensiz.

Karardı  gökyüzü, bulut  ağladı,

İçimdeki  bu acı, yaktı   dağladı.

Kesildi  yağmurlar, yaprak  sarardı,

Yalnızım  bir tanem…yalnızım  sensiz.

İçimdeki  ateşin, rengi  gül  gibi,

Ufalttı   eridim , kaldım  kül  gibi.

Seninle  Veda’ mız, sanki  dün  gibi,

Yalnızım   bir tanem…yalnızım  sensiz.

Bir gün  bana  dönmene, yoksa  bir  ümit,

Yaşamam   imkansız, uzun  bir  vakit.

Öldür   beni  bir tanem,   öldür  öyle  git,

Ölmekten  beterim ….yalnızım  sensiz.', 'Sıcaklar  bunalttı, yağmur  Islattı, Hastalandı gönlüm, günlerce  yattı. Sözde  olan  dostlarım, beni  aldattı, Yalnızım  bir tanem…yalnızım...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yalnizim-91-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık İçime,çöktü bu akşam', 'yalnizlik-i-cime-coktu-bu-aksam-nuri-gokhan-sonsel-axafc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yollarda  bekledim,dönüp  gelmeni,

Gözlerimde  bir  buğu, özledim  seni.

Çok  fazla  beklettin,dönmedin geri,

Yalnızlık  içime, çöktü  bu  akşam…

Gelmedin  dün  gece,sen  yine  yoksun,

Sabahlara  kadar, yandı  ışığım.

Bilmedin  çektiğim,bu  acıları,

Görmedin  halimi, sana  aşığım.

Elimde  hatıra, bir  küçük  resmin,

Her  zaman  kalbimde, saklayacağım.

Bir  zaman  geçer de,dönmezsen  eğer

O resme  bakarak, ağlayacağım.

Seninle  güzeldi, aşk  ve  zarafet,

Sana  güller  almıştım,her  gün  bir  demet.

Gelmedin  bir  tanem, unuttun  demek,

Yalnızlık içime, çöktü  bu  akşam.

Elimde  güllerle, kaldım  yollarda,

Yağmurlar  içimi, ıslattı  bu  gün.

Beklemek  seni, boş  bir  teselli,

Kendimi  aldattım…aldattım bu gün.', 'Yollarda  bekledim,dönüp  gelmeni, Gözlerimde  bir  buğu, özledim  seni. Çok  fazla  beklettin,dönmedin geri, Yalnızlık  içime, çöktü  bu  a...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yalnizlik-icime-coktu-bu-aksam-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yollarımız Ayrı', 'yollarimiz-ayri-nuri-gokhan-sonsel-9qonf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dolaşsam  güzelim, ben  diyar, diyar,

Bulamam  bilirim,senden  güzel  yar.

Henüz  ilkbaharsın, bense  sonbahar,

Seninle  aramızda, çok  yaş  farkı  var.

Saçlarıma  ak  düştü, bak  yüzüm solgun,

Bedenim kocamış, kalbim  çok  yorgun.

Bu  yaştan  sonra  da, yiyemem  vurgun,

Sen  başka  yola  git … ben  başka  yola.

Sen  nisansın  güzelim, bense  aralık,

İstemem  ucuz  aşkı, üç  beş  paralık.

Bana  artık  yakışmaz, bu  maskaralık,

Sen  ayrı  yola  git…ben  ayrı  yola..

Güzel  tatlı  sözlere, adanma  sakın,

Bu  ihtiyar  ömrümün, bitmesi  yakın.

Bitmeden  güzelliğin, bu  saltanatın,

Sen  ayrı  yola  git…ben  ayrı  yola.', 'Dolaşsam  güzelim, ben  diyar, diyar, Bulamam  bilirim,senden  güzel  yar. Henüz  ilkbaharsın, bense  sonbahar, Seninle  aramızda, çok  yaş ...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yollarimiz-ayri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adı Yok Sevdamın', 'adi-yok-sevdamin-harun-kuscu-xh4gj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gezdim gördüm durdum hayat dediğin

Feleğin çarkında gezinmek imiş

Dünya dardır diye sanıp gittiğin

Meçhulden meçhule ince yol imiş

Adı yok sevdamın geriye kalan

Senden esen rüzgar içime dolan

Bir tek seni sevdim ötesi yalan

Kıvranıp yandığım etten kul imiş

İsyan değil ya rab ah çekişlerim

Sadece kendime serzenişlerim

Masiva ya kanıp günah işledim

Anladım ilk emrin rabbin bul imiş

Harun Kuşcu

Silifke/mersin

21.03.2006 Salı', 'Gezdim gördüm durdum hayat dediğin Feleğin çarkında gezinmek imiş Dünya dardır diye sanıp gittiğin Meçhulden meçhule ince yol imiş Adı yok s...', ARRAY['Türk Edebiyatı','Şiir','Harun Kuşcu']::text[], 8.5, '{"poet":"Harun Kuşcu","poet_slug":"harun-kuscu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/adi-yok-sevdamin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorgunum Yıllar', 'yorgunum-yillar-nuri-gokhan-sonsel-biv3e', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nasıl çabuk geçtiniz, bilmedim yıllar,

Kâh sevinçli-hüzünlü, sırdaşım yıllar.

Beni siz yıpratıp, hep koşturdunuz,

Sizlerle yarışamam, yorgunum yıllar.

Çocukluğum-gençliğim, bir anı oldu, 

Yaşattığın tecrübenin, bir yanı oldu.

Yüzüme hediyen, çizgiler doldu,

Yorgunum inanın… Yorgunum yıllar.

Beni hiç serinletmedi, senin suların,

Zaten hep elindeydi, benim yularım.

Bana ne verdiniz ki, şimdi sorarım,

Benden almaktan başka, yorgunum yıllar.

Gençliğimi-gücümü, benden aldınız,

Neden beni kedere, hüzne saldınız? 

Bu beden bu yüke, dayanır mı sandınız,

Dayanacak gücüm yok, yorgunum yıllar.', 'Nasıl çabuk geçtiniz, bilmedim yıllar, Kâh sevinçli-hüzünlü, sırdaşım yıllar. Beni siz yıpratıp, hep koşturdunuz, Sizlerle yarışamam, yorgun...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yorgunum-yillar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahtım', 'bahtim-mesut-sutcu-wjgzu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yollardayım, akşama yakın.

Her yol kendine götürüyor

Sonu aynıymış meğer yolların

Kalbim hep uzaklara yürüyor.

Akşam saçlarını verdi bana

Kızıllığı bağrıma düştü

Gözlerin kaybolmadan daha

Yarama hançerler üşüştü

Bahtım bakışlarına tutsak

Yalnızlığıma kaç asır biçtin

Bu can ne zaman kurtulacak

Ölümlerden bana neyi seçtin.', 'Yollardayım, akşama yakın. Her yol kendine götürüyor Sonu aynıymış meğer yolların Kalbim hep uzaklara yürüyor. Akşam saçlarını verdi bana Kı...', ARRAY['Türk Edebiyatı','Şiir','Mesut Sütçü']::text[], 8.5, '{"poet":"Mesut Sütçü","poet_slug":"mesut-sutcu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bahtim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yudum yudum sevda', 'yudum-yudum-sevda-nuri-gokhan-sonsel-790of', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yağmurlar altında, biz dans ederken, 

Güller tomurcuklanmış, ötmüş bülbüller.

Menekşelerle bezenmiş, aşk kadehinden,

Yudum, yudum içtik, biz bu sevdayı.

Kırlarda çiçekler, senin bağrında açmış,

Kovanda tüm arılar, bize polenler yapmış.

Koklamışlar bu aşkı, baharda kelebekler,

İçirmişler bizlere, yudum, yudum sevdayı.

Anıların  bırakmaz, bu sevdanın peşini,

Bir gün dönüp  dolaşıp, mutlaka geleceksin.

Dudaklarıma dolan, ilk aşkın sevincini,

Kadehlere doldurup, sen bana vereceksin.

Mehtap seninle doğdu, seninle batmayacak, 

Yıldızlar hiç bir gece, uykuya yatmayacak.

Binlerce ömür bitse, aşkımız bitmeyecek,

Biz gönülden içmiştik, yudum,yudum sevdayı.

Sevda ne seninle, nede benimle doğdu,

Bu dünya var olmadan, aşk  icat oldu.

Mecnun çöllere düştü, hep  aradı Leyla’yı,

Onlar doğmadan içmiş, yudum,yudum sevdayı.', 'Yağmurlar altında, biz dans ederken,  Güller tomurcuklanmış, ötmüş bülbüller. Menekşelerle bezenmiş, aşk kadehinden, Yudum, yudum içtik, biz...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yudum-yudum-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğime Saplanır', 'yuregime-saplanir-nuri-gokhan-sonsel-oa2zr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Göz kapaklarımın, ardındaki gizli nehir,

Yorgun olan gönlüme, her gece akar durur.

Korkusuna uğradığım, bu karanlık geceler,

Hançer, hançer olur da, yüreğime saplanır.

Yıldızların altında, söylenirken türküler,

Gönlümün ızdırabı, her gece artar durur.

Sevdamızın acısı, karanlıkla bilenir,

Hançer, hançer olur da, yüreğime saplanır.

Zamanı yitirmişim, esmiyor ki rüzgarlar,

Dertlere tutsak oldum, beni zincire vurur.

Doymuyor ki acıya, kalbimdeki  damarlar,

Hançer, hançer  olur da, yüreğime saplanır.

Bu çaresizlik bana, sanki bir kurşun sıkar,

Can evimden yaralar, her gün öldürür durur.

Bu kapkara talihim, solmuş güllere benzer,

Hançer, hançer olur da, yüreğime saplanır.', 'Göz kapaklarımın, ardındaki gizli nehir, Yorgun olan gönlüme, her gece akar durur. Korkusuna uğradığım, bu karanlık geceler, Hançer, hançer ...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gökhan Sonsel']::text[], 8.5, '{"poet":"Nuri Gökhan Sonsel","poet_slug":"nuri-gokhan-sonsel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yuregime-saplanir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyaz Martı', 'beyaz-marti-miyaser-gulsen-8bq0u', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Beyaz Martı

Beni kanadına al

Uçur sonsuz mavi ülkene

Belki ümitlerimi toplarız

Belki de yitirdiğim hülyalarımı buluruz

Şimdi kurşun yemiş gibi zorda yüreğim

Bir gülün dikeni kadar acımasız duygulara

Bir yağmur katresi kadar berrak duygularımı savur

Beyaz Martı

Bulutları ört kederlerimin üzerine

Kederlerimi uyut

Gözlerime bak

Gözlerimdeki yıldızları say

Çünkü,

Yıldızların sayısı kadar özlem ektim  yüreğime

Ben bir yudum pembe düş içmedim

Pembelerden topla bana

Siyahları at kuytulara

Beyaz Martı

Al beni kanadına

Uçur beni sonsuz mavi ülkene

Sevgi diyarına

Uçur beni

Uçur çook uzaklara..', 'Beyaz Martı Beni kanadına al Uçur sonsuz mavi ülkene Belki ümitlerimi toplarız Belki de yitirdiğim hülyalarımı buluruz Şimdi kurşun yemiş gi...', ARRAY['Türk Edebiyatı','Şiir','Miyaser Gülşen']::text[], 8.5, '{"poet":"Miyaser Gülşen","poet_slug":"miyaser-gulsen","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/beyaz-marti-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Yoldur Kadın / Liman Değil', 'bir-yoldur-kadin-liman-degil-orhun-basat-10fxs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '- hep aynıdır yalnızlığın kimliğindeki resim 

                                            ve resmin yanındaki isim – o benim.. -

1 (sıkıntı kapısı)    

plastik kaplı bir kimliğim 

içimde üç beş mermi ve hiçliğim

tenimde tipi boran 

begonvil yapraklarında bir kadın ismi 

uykularımdan doğan

2 (ön bilgi ve soru)    

yoksan /  korkarım sana geç ölmekten 

tarifsiz ve tarifesiz bir çığlık geçer içimden 

bir gece / uykunda birileri çekiştirirse bir yerlerinden

bil ki / duan kabul olmuş 

seni yaşıyorum can çekişirken

sonra sor kendine

hangi yüzündeyiz aşkın

ben kime ağlarım 

sen nerede üşürsün  / nerelerin üşür 

hangi kimliğe sevda düşürürsün 

kaç tene yazılır adın

3 (küresel ısınma)    

kaçıncı cümleydi boğulduğum

hangi kirpiğin saplandı günüme

hangi ağaç kurudu sesimde / bilmiyorum 

şaşırır yapacağını sevda yeniği us 

pusu kurar sözdeki pus 

son sözlerim dilimde

söz deyip geçme / sözüm ağır taşıyamıyorum..

son gün de  batıyor iklimimde 

4 (dilekçe)    

sana birikmek istedim / içimin bir yerlerinde

ve içine anlatmak bunları 

gözlerinde bulmak / dudaklarında yitirip uykuları 

belki bir gece yarısı 

belki sabah suları 

5 (aritmi)    

ritim bozukluğu gibi yürüdüm  / kudurgan ve yırtık

yanımda kadın gözleri gecenin ve spermanın ruhu 

göğsünde bembeyaz bulut yoğunluğu ayrılık

lakin kış tohumu düşen her yaprak 

bembeyaz ve çizgisiz 

bir intihar tohumu bırakır avuçlarıma 

kara bir günde biterken biz

6 (biberon)    

üçüncü memesi yaşamın / sen 

beni bilemezsin 

ve gelmediğin yerden gidemezsin.. 

nar ekşisi sevdalar şimdi 

ben karıştım içine / sen artık sen değilsin 

şiirin sessizliğindeyim bu ikindi

7 (asıl söylem)    

özürlü bir güne merhabadır / sensiz uyanmak 

acımasızca zamanı vurmak 

hıncahınç sana  geliyordum belki 

aklımda 35 lik bir rakı ve o yaşlarda bir kadın

kov cümle anıları  /  geceleri yıldızlarla ov

benden arın / yak yarınları

kalmaya çalışan cümle anıları sil 

söylememek daha zor bazen 

ama bil ki 

bir yoldur kadın / liman değil..

21. 03. 06 (“ öğretmem sana geceyi, ışığı yakar giderim ” masalını dinlerken..)', '- hep aynıdır yalnızlığın kimliğindeki resim                                              ve resmin yanındaki isim – o benim.. - 1 (sıkıntı ...', ARRAY['Türk Edebiyatı','Şiir','Orhun Basat']::text[], 8.5, '{"poet":"Orhun Basat","poet_slug":"orhun-basat","theme":"Türk Şiiri","is_hero":false,"total_lines":62,"source_url":"https://www.antoloji.com/bir-yoldur-kadin-liman-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Benden Alır Bu Şehir', 'seni-benden-alir-bu-sehir-talip-isik-1wutv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'her sabah mavi gözlerinle

uyanır çiçekler

hırçın denizler alır seni benden

gece uzar yol uzar

yüz yıl gibi gelir mevsimler

ve yeniden yorumlanır

aşklarımız

karlı kış akşamlarında

zincirlere vurulur ellerim hoyrat

seni benden alır bu şehir

alır götürür

gecenin kuytularına

sana yorgun gelir kelimeler

şehirler büyür

aşk yorar sevda yorar

nazlı bir şiir dolaşır

sokaklarımızda

bu serencam yüreğimizde sevgili

ay nasıl doğar

züleyha nasıl tutulursa

kara sevdalara

bir şiir seni benden alır

alır götürür

gecenin kuytularına

çocuklar üşür damarlarımızda

ırmaklar üşür

bir yıldız kayar avuçlarımızdan

denizler üşür

kırmızı bir gökyüzü

düşer toprağa

ve her baharda

kanayan bulutlar sürülür gözlerimize

ayrılık türküleri okunur

rüzgarla savrulur sevgilerimiz

hercai yağmurlar alır seni benden

alır götürür

gecenin kuytularına', 'her sabah mavi gözlerinle uyanır çiçekler hırçın denizler alır seni benden gece uzar yol uzar yüz yıl gibi gelir mevsimler ve yeniden yoruml...', ARRAY['Türk Edebiyatı','Şiir','Talip Işık']::text[], 8.5, '{"poet":"Talip Işık","poet_slug":"talip-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/seni-benden-alir-bu-sehir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şekiller', 'sekiller-mehmet-can-zmas6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kaybettim gökyüzündeki şekilleri

Her buluta ayrı anlam vermeyi unuttum

Çiçekleri görmez oldu gözlerim

Renklerin ışıklarına takılmaktan..

Bir çağlayan vardı içimde..

Çağlayarak akan

Kahpe ihanete kurban gitmeden

Dayanmak

Sabır

Acı

Tükenmek

İnadına yaşamak derken

Kurşun yarası ihanet  bilmecelerinden

Yorulmak ne demek

Ölüm ötesi..

Beyin fırtınası

İntikam

Kan

Lanet olsun diyerekten

Vazgeçmek..

En güzeli hala yol bitmemiş demek

En güzeli yine

Anlamlı gülmek..', 'Kaybettim gökyüzündeki şekilleri Her buluta ayrı anlam vermeyi unuttum Çiçekleri görmez oldu gözlerim Renklerin ışıklarına takılmaktan.. Bir...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Can']::text[], 8.5, '{"poet":"Mehmet Can","poet_slug":"mehmet-can","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sekiller-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Elinde Yorgun Yüreğim', 'ask-elinde-yorgun-yuregim-talip-isik-n8nun', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'hasretin kurşun gibi düşer zamana

kelimeler hoyrat ikindilerde 

çağırır seni

gözlerim sıcak bir nefes gibi

tutulur sevda nöbetlerine

seni sevmek adına

ayrılığa isyan dağlara sabır ektim

ve katran 

ve zift gibi

toprağın tenine ilaç

yağmura hüzün sardım

adını isyan koydum aşkın

çiçeklerden önce

ayrılığı çektim içime', 'hasretin kurşun gibi düşer zamana kelimeler hoyrat ikindilerde  çağırır seni gözlerim sıcak bir nefes gibi tutulur sevda nöbetlerine seni se...', ARRAY['Türk Edebiyatı','Şiir','Talip Işık']::text[], 8.5, '{"poet":"Talip Işık","poet_slug":"talip-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ask-elinde-yorgun-yuregim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oruspuluk', 'oruspuluk-mehmet-can-mn1ak', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Oruspuluk ruhunda varmış derler

Gözleri kan çanağı

Yalan yalan yalanoğlu yalan

Hiç kızarmaz yanağı.

İhanet kol gezerken ruhunda

Yalan yine dayanağı', 'Oruspuluk ruhunda varmış derler Gözleri kan çanağı Yalan yalan yalanoğlu yalan Hiç kızarmaz yanağı. İhanet kol gezerken ruhunda Yalan yine d...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Can']::text[], 8.5, '{"poet":"Mehmet Can","poet_slug":"mehmet-can","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/oruspuluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İade-i Gül', 'i-ade-i-gul-talip-isik-nobhz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'gece ve yalnızlık vardı

kırmızı bir gül uzanmıştı düşlerime

zülüflerinde güneş sarısı

bulutlar

sevdam oy! 

yanmışsam sevda denizlerine

vurulmuşsam yüreğimden

aynalarda kırılmışsa ellerim

yalnızlığım büyüyen bir karanlık olup

dağıtmışsa saçlarını

biliyorum yine ayrılık yazılacak

ayrılık yarı ölmektir çünkü

partire c’est mourir un pue

akşam nasıl çöküyorsa gözlerime

iade-i gül ile giriyorum düşlerine

biliyorum yine ayrılık yazılacak

kara trenler geçecek sevdalardan

hani demiştim ya mevsimler büyüyecek

çiçeklerle güllerle karşılanacağız

sevdam oy! 

onulmaz acılarla

hiç kavuşmadan ölmek mısralarda

henüz yazılmamış bir şiirin ön sözünde

güneşi ve aşkı yorar gibi

vuslattan önce ayrılığı yaşamak ne zor

iade-i gül ile

yazılmamış bir şiirin önsözüyle

giriyorum düşlerine

korkulu bekleyişler ve gül kurusu

yalnızlığımla', 'gece ve yalnızlık vardı kırmızı bir gül uzanmıştı düşlerime zülüflerinde güneş sarısı bulutlar sevdam oy!  yanmışsam sevda denizlerine vurul...', ARRAY['Türk Edebiyatı','Şiir','Talip Işık']::text[], 8.5, '{"poet":"Talip Işık","poet_slug":"talip-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/iade-i-gul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beş Kırmızı Gül Gördüm', 'bes-kirmizi-gul-gordum-miyaser-gulsen-fogd5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Beş Kırmızı Gül gördüm

Dizilmişler yan yana

Goncaları içinde

Beş tane Kırmızı Gül

Sanki yanan beş kandil

Nur saçıyor her yana

Beş Kırmızı Gül gördüm

Ne büyük bir tevafuk

Onyedi Mart akşamı

Al gömlekler giydiler

Gururla  selam durdu

Gururla karşıladı

Çanakkale''de yatan

Onbinlerce şehitler

Beş Kırmızı Gül gördüm

Ağlama küçük çocuk

Baban onlardan biri

Baban şehit goncası

O, Cenette açacak

Ağlama küçük çocuk

O beş Kırmızı Gülü

Peygamber koklayacak

Gözlerden şimdi akan

Yaş değil inan dua

En büyük mükafatı

Elbette verir Hüda.', 'Beş Kırmızı Gül gördüm Dizilmişler yan yana Goncaları içinde Beş tane Kırmızı Gül Sanki yanan beş kandil Nur saçıyor her yana Beş Kırmızı Gü...', ARRAY['Türk Edebiyatı','Şiir','Miyaser Gülşen']::text[], 8.5, '{"poet":"Miyaser Gülşen","poet_slug":"miyaser-gulsen","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/bes-kirmizi-gul-gordum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayalinle Avunurken', 'hayalinle-avunurken-belgin-turan-ylp3w', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne çok isterdim,

Arada bir aklıma gelmeni,

Yine arada bir seni özlemeyi,

Bazen canımın çekmesini,

Ve bazen içimin erimesini,

Sen böyle gönlüme kurmuşken mesken,

Gizli dehlizlerinde ben kaybolmuşken,

Ve bana benden daha yakın olmasaydın,

Bilmem olur muydu? Bir günüm aydın.

İçimi yaralayan bu sevdam yüz akım,

Hiçbir şey söyleme elem benim hakkım.

Bir yara bin yara olur, acı bir sözünde,

Ben küçültmem yaratığım devi gözümde,

Yaşasa da bu can bin bir hüzün özünde,

Ah! Ne olurdu? O sıcaklığın,

Bedenimi usulca eritmeseydi,

Hayatımı cömertçe verip ellerine,

Bir kapanmadığım kaldı dizlerine,

Sevgilim koy şimdi yerin diplerine,

Ara sıra anımsasaydım,

Sensiz her saliseyi saymasaydım,

Mutlu olur muydu? Ağlayan yüreğim,

Kalp de olur muydu? O zaman dileğim,

Ellerim boş, gönlüm boş, öyle bomboş,

Bilmem içmeden olur muydum? Bir hoş.

Belgin Turan                    03.01.2006', 'Ne çok isterdim, Arada bir aklıma gelmeni, Yine arada bir seni özlemeyi, Bazen canımın çekmesini, Ve bazen içimin erimesini, Sen böyle gönlü...', ARRAY['Türk Edebiyatı','Şiir','Belgin Turan']::text[], 8.5, '{"poet":"Belgin Turan","poet_slug":"belgin-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/hayalinle-avunurken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyaz Düşler', 'beyaz-dusler-talip-isik-mucfa', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '.

en içli yağmur kokuları

geçiyor bahçelerimizden

beyaz düşler

pembe rüyalar çağırırken

bölünüyor uykularımız

ve çarmıha geriliyor insanlar

orta doğunun kaygısız

iklimlerinde

dinmiyor acılarımız ey sevgili

bir ateş büyütüyor yüreğimizi

damarlarımızda pusatsız geceler

siyah güneş yağmurları

kanayan yanlarına toprağın

kırağılar sürüyor

dermansız şiirler

sarılıyor yaralara

.

dergilerimizde aşk şiirleri

kitaplarımızda hüzün senfonileri

alacakaranlığında akşamın

uzun bir sürgünü yaşıyor gibi

mermiler geçiyor

bir çocuğun parlayan

gözlerinden

damarlarımızda pusatsız geceler

beyaz düşler pembe rüyalar', '. en içli yağmur kokuları geçiyor bahçelerimizden beyaz düşler pembe rüyalar çağırırken bölünüyor uykularımız ve çarmıha geriliyor insanlar ...', ARRAY['Türk Edebiyatı','Şiir','Talip Işık']::text[], 8.5, '{"poet":"Talip Işık","poet_slug":"talip-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/beyaz-dusler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessiz Veda', 'sessiz-veda-mesut-sutcu-ljs7q', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Derin derin sustuk ikimiz de

Duvarlar bozmadı bu sessiz akşamı

Halatlar çözülünce içimizde

Yüklendi yürekler her bir gamı

Ayrılık akrebin kıskacında

Dilinin zehri birikti ucunda

Kıyamet! Saatin bilmem kaçında

Dur demenin artık yoktu anlamı

Vurulan gözlerimde bir yumak kan

Yaşlar kopuverdi daha ağlamadan

Ardından kan gibi düştüğüm zaman

Tuzlarla sardım sensiz yaramı', 'Derin derin sustuk ikimiz de Duvarlar bozmadı bu sessiz akşamı Halatlar çözülünce içimizde Yüklendi yürekler her bir gamı Ayrılık akrebin kı...', ARRAY['Türk Edebiyatı','Şiir','Mesut Sütçü']::text[], 8.5, '{"poet":"Mesut Sütçü","poet_slug":"mesut-sutcu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sessiz-veda-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçin için', 'i-cin-icin-yusuf-mete-tekel-guvt5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İçin  için  içimde

İçin içimde

