INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ablalık en güneşli   Özlemdi onda', 'ablalik-en-gunesli-ozlemdi-onda-hamdi-oruc-fiey9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ablalık en güneşli   Özlemdi onda

Aklıma geldikçe ağlarım

Mezarını gül bildim ablamın

Ablalık en güneşli   özlemdi onda

O benim ablam

O gül abla o gül abla

