INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayatin yokuslari', 'hayatin-yokuslari-ulya-erkman-xe6wg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Guzel gunlerden baska hayat  nedir? 

Inisli cikisli yokuslar degil midir? 

Her cagda degisiktir yokuslar

Maksat yokuslari yenmektir

Boylece huzura kavusuup

Nes''eli sevincli gunlari hissetmektir

Cocuktan baslayalim

Sinifini muhakkak  gecmeli

Iste onun ufacik yokusu

Ama cikmaya gayret etmeli

Bazan belki yardim ister

Yakinlari yardim etmeli

Ama cocuk kendisi becermeli

Hayat yokuslari nasil cikilir ogrenmeli

Genclere gelince 

Enerjiktirler

Degisik yokuslari bir hamlede 

Cikmak isterler

Kimisi becerir cikar yokusu

Kimisi belki yardim bekler

Cikinca yokusu onlerinde artik

Nes; eli huzurlu rahat gunler

Orta yasa gelince

Iki kisidirler belki bu sefer

Yokuslar biraz daha diktir

Beraber cikmak isterler

Biri duserse oteki tutar kolundan

Azmedip. yenilmek istemezler

Bu cagda baska yokuslarda cikar

Beraberce, yorulsalar da gayret ederler

Yaslilik caginda Yokuslar belki azalmistir

Daha alcak zor degildir

Yine de guclerine gore cikacaklardir

Bazanda isi oluruna birakip

Rahat etmege bakacaklardir

Belki de yakinlari halletsin deyip

Hayatlarinin yorgunlugunu cikaracaklardir

Hangi cagda olursa olsun

Asilmasi zor yokuslar cikilinca

Guzel huzurlu gunler basliyacaktir

Yeni yokuslar belirecektir omrumuz boyunca

Kah cikacagiz kah kalacagiz orada belki

Degmezmi cabaya arkasi guzel gunler olunca

Hayat bu yokussuz olmuyor

Yasariz sevincli huzurlu gunler 

Yokuslar son bulunca', 'Guzel gunlerden baska hayat  nedir?  Inisli cikisli yokuslar degil midir?  Her cagda degisiktir yokuslar Maksat yokuslari yenmektir Boylece ...', ARRAY['Türk Edebiyatı','Şiir','Ulya Erkman']::text[], 8.5, '{"poet":"Ulya Erkman","poet_slug":"ulya-erkman","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/hayatin-yokuslari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fani bu dünya', 'fani-bu-dunya-mikdat-bal-043ps', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bu sevda yolunda izimiz kalsın

Geliver güzelim fani bu dünya

Sen benim gözümde şekersin balsın

Gülüver güzelim fani bu dünya

baş tacı eyledim gönül verende

Nice güller aldım bağın derende

Gönlüm ateş doldu sevgin girende

Biliver güzelim fani bu dünya

Ah çekip karalar bağlıyor musun? 

Sen de benim gibi çağlıyor musun? 

Gözlerin nemli mi ağlıyormusun? 

Siliver güzelim fani bu dünya

Her türlü nefretten arınıp da gel

Sevgiyle bürünüp karınıp da gel

Gelinlikliğin kefen sarınıp da gel

Ölüver  güzelim fani bu dünya', 'bu sevda yolunda izimiz kalsın Geliver güzelim fani bu dünya Sen benim gözümde şekersin balsın Gülüver güzelim fani bu dünya baş tacı eyledi...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/fani-bu-dunya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık', 'ayrilik-omer-ziya-soyyigit-cm660', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hey canlar, canandan haber mi geldi? 

Söyleyin o yare hiç eğlenmesin

Bu hicran bu firak bağrımı deldi

Söyleyin o yare hiç eğlenmesin

Yıllarca bekledim hiç usanmadan

Dumanmı görünür ateş yanmadan

Ölürsem yazıktır sana kanmadan

Söyleyin o yare hiç eğlenmesin

Yetsin artık bunca çektiğim hasret

Takatim tükendi, kesildi gayret

İstemem dünyayı, istemem ahret

Söyleyin o yare hiç eğlenmesin

Ben ben diye diye gitmek istemem

Bunca varlık varken ölmek istemem

Perdei esrarı delmek istemem

Söyleyin o yare hiç eğlenmesin

Görüştük ezelde, ayrı değiliz

Biliyorum elbet gayri değiliz

Ümitliyiz, ancak layık değiliz

Söyleyin o yare hiç eğlenmesin

Görmek istiyorum vechini ayan

Duymak istiyorum lafzını beyan

Ziya aç gözünü gafletten uyan

Söyleyin o yare hiç eğlenmesin

9 Mayıs 1981', 'Hey canlar, canandan haber mi geldi?  Söyleyin o yare hiç eğlenmesin Bu hicran bu firak bağrımı deldi Söyleyin o yare hiç eğlenmesin Yıllarc...', ARRAY['Türk Edebiyatı','Şiir','Ömer Ziya Soyyiğit']::text[], 8.5, '{"poet":"Ömer Ziya Soyyiğit","poet_slug":"omer-ziya-soyyigit","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ayrilik-351-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yuvarlağın Köşeleri-Konumuz Düşünmek-Etika-Birinci Bölüm-94', 'yuvarlagin-koseleri-konumuz-dusunmek-etika-birinci-bolum-94-ozdemir-asaf-0aqfy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'KONUMUZ DÜŞÜNMEK-ETİKA-94

“Düşkuran”ın adresini istediler benden:

Tarih Caddesi, Kahramanlık Yılları Mahallesi, Teknik Gelişim Sokağı, Konfor Apartımanı, İyi İşler Katı, Güvenç Dairesi.', 'KONUMUZ DÜŞÜNMEK-ETİKA-94 “Düşkuran”ın adresini istediler benden: Tarih Caddesi, Kahramanlık Yılları Mahallesi, Teknik Gelişim Sokağı, Konfo...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/yuvarlagin-koseleri-konumuz-dusunmek-etika-birinci-bolum-94-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şükür Mevlaya Mevlaya', 'sukur-mevlaya-mevlaya-omer-ziya-soyyigit-n89bs', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Cemali yare meftunum

Şükür mevlaya mevlaya

Bu sevda ile mecnunum

Şükür mevlaya mevlaya

Serapa dost ayan oldu

Bütün esrar beyan oldu

Gönül kur''an ile doldu

Şükür mevlaya mevlaya

''Veennelkuvvetelillah''

Tecelli eyledi vallah

Eriştik vahdete billah

Şükür mevlaya mevlaya

Zuhur etti sıfatullah

Göründü semme vechullah

Helake erdi gayrullah

Şükür mevlaya mevlaya

Ziya gark oldu envare

Bakıp mest oldu hem yare

Yok artık meyli ağyare

Şükür mevlaya mevlaya

10 Haziran 1981', 'Cemali yare meftunum Şükür mevlaya mevlaya Bu sevda ile mecnunum Şükür mevlaya mevlaya Serapa dost ayan oldu Bütün esrar beyan oldu Gönül ku...', ARRAY['Türk Edebiyatı','Şiir','Ömer Ziya Soyyiğit']::text[], 8.5, '{"poet":"Ömer Ziya Soyyiğit","poet_slug":"omer-ziya-soyyigit","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sukur-mevlaya-mevlaya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
