INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babasiz Yasayanlara', 'babasiz-yasayanlara-mustafa-aslan-2-ni5l5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Evlatlar babalarini hep hatirlamak istedikleri gibi hatirlarlar,

Her yanlisini göz önünden silip, dogrularini ararlar,

Her bakislarinda, her düsüncelerinde bir kez degil bin kez yanarlar,

Her gece sessizce babasiz geçen günlere kanarlar,

Evlatlar hiç durmadan yürekten aglarlar,

Belkide gözlerini son kez baba hasretiyle yumarlar.

