INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yuvarlağın Köşeleri-Sevgi İle Sevgiye Karşı-Etika-Birinci Bölüm-127', 'yuvarlagin-koseleri-sevgi-i-le-sevgiye-karsi-etika-birinci-bolum-127-ozdemir-asaf-chsfe', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'SEVGİ İLE SEVGİYE KARŞI-ETİKA-127

