INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yuvarlağın Köşeleri-Sevgi İle Sevgiye Karşı-Etika-Birinci Bölüm-129', 'yuvarlagin-koseleri-sevgi-i-le-sevgiye-karsi-etika-birinci-bolum-129-ozdemir-asaf-v0q1o', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'SEVGİ İLE SEVGİYE KARŞI-ETİKA-129

Aşkın sana doga gereğince verildiğini sanma.... Sen hayvan değilsin.

Doganın sana aşk gereğince verildiğini sanma... Sen hayvan değilsin.

Doga ölümde, insan aşkda uludur.', 'SEVGİ İLE SEVGİYE KARŞI-ETİKA-129 Aşkın sana doga gereğince verildiğini sanma.... Sen hayvan değilsin. Doganın sana aşk gereğince verildiğin...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yuvarlagin-koseleri-sevgi-ile-sevgiye-karsi-etika-birinci-bolum-129-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rubailer…..VII', 'rubailer-vii-sevinc-kavuk-68hwh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hep adımlarım sana yönelik

Hem tüm benliğimle üstelik

Ben kimim ve sen kim olabiliyorsun ki hâlâ 

Daha birbirimizi anlayamadık isek... 

Mart 2006

dünya varlığının sağlığı bize muhtaç

özürlü durumlardı bu bilgi için amaç

kaya benzerliği kadarınca ol yamaç

insanlığa kazanılacak yine de inanç', 'Hep adımlarım sana yönelik Hem tüm benliğimle üstelik Ben kimim ve sen kim olabiliyorsun ki hâlâ  Daha birbirimizi anlayamadık isek...  Mart...', ARRAY['Türk Edebiyatı','Şiir','Sevinç Kavuk']::text[], 8.5, '{"poet":"Sevinç Kavuk","poet_slug":"sevinc-kavuk","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/rubailer-vii-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel', 'guzel-vahit-kara-t86xg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözlerin vardı ki, denizden güzel,

O denizde bendim sevdana yüzen.

Gecemi aydınlatan bir yakamoz,

Ay ışığında bendim kendimden geçen.

Gözlerin vardı ufuklar delen,

Sözlerin vardı, yürekten seven,

Kirpikler gönlüme bir oktu değen,

O gönlümü delen okların güzel.

Birde kalbin vardı, içinde sevgi,

Bitip tükenmeyen engin denizdi,

Sandalı ben oldum poyraz devirdi,

Devrilen sandalda, hatıran güzel.

Dudakların vardı, bala değişmem,

Dünya nimetine cana değişmem,

Vurup öldürsen, senden vazgeçmem

Ölüm döşeğinde sözlerin güzel.

Kader mahkumuyum, sevdadan yana,

Sevip terk edildim, ben yana,yana

İçin kanımdan siz kana,kana

Can tenden uçarken, hayalin güzel

Bende sevdim bir zamanlar gönül hırsızı,

Bu bana kadermiş,alın yazısı,

Sende çekme vahit,gönül yarası,

Kara sevda çeken gönüller güzel

						06.06.1998', 'Gözlerin vardı ki, denizden güzel, O denizde bendim sevdana yüzen. Gecemi aydınlatan bir yakamoz, Ay ışığında bendim kendimden geçen. Gözler...', ARRAY['Türk Edebiyatı','Şiir','Vahit Kara']::text[], 8.5, '{"poet":"Vahit Kara","poet_slug":"vahit-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/guzel-90-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
