INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yuvarlağın Köşeleri-Hayvanlarla Aramızdaki-Etika-Birinci Bölüm-172', 'yuvarlagin-koseleri-hayvanlarla-aramizdaki-etika-birinci-bolum-172-ozdemir-asaf-hh6xo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'HAYVANLARLA ARAMIZDAKİ-ETİKA-172

