INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yuvarlağın Köşeleri-Yitirmek-Kazanmak-Etika-Birinci Bölüm-178', 'yuvarlagin-koseleri-yitirmek-kazanmak-etika-birinci-bolum-178-ozdemir-asaf-rpjru', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'YİTİRMEK-KAZANMAK-ETİKA-178

