INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dokunmayın Bana!', 'dokunmayin-bana-nur-demirciler-uzuoe', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben sadece izlerim,

Uzaktan bir iki söylerim.

Söz verdim babama,

Ama,

Nerde benim geleceğim,

İşte yine başlıyor,

Aynı film oynuyor.

Birileri bölüyor,

Diğeri çanak tutuyor,

Olup bitene kim karşı,

Kabak başına patlıyor.

Hani senin vicdanın? 

Bu sefer taban kazınıyor,

Bu bahar ki temizlik,

Hiç birine benzemiyor...

“Yazıyor, yazıyor”

“kıymetli olan gizlenir”

gizlemeyen,

gidebilir….

22/03/2006

İstanbul', 'Ben sadece izlerim, Uzaktan bir iki söylerim. Söz verdim babama, Ama, Nerde benim geleceğim, İşte yine başlıyor, Aynı film oynuyor. Birileri...', ARRAY['Türk Edebiyatı','Şiir','Nur Demirciler']::text[], 8.5, '{"poet":"Nur Demirciler","poet_slug":"nur-demirciler","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/dokunmayin-bana-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşayamadan 1', 'yasayamadan-1-kamil-at-cpvqj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çoğu insanlar 

yönlendirilir

Doğar ve ölürler...

O zaman

Mezarına şöyle yazılsa

Yanlış olmasa gerek:

Doğdular ve öldüler

Yaşayamadan...', 'Çoğu insanlar  yönlendirilir Doğar ve ölürler... O zaman Mezarına şöyle yazılsa Yanlış olmasa gerek: Doğdular ve öldüler Yaşayamadan......', ARRAY['Türk Edebiyatı','Şiir','Kamil At']::text[], 8.5, '{"poet":"Kamil At","poet_slug":"kamil-at","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yasayamadan-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gece Aşkı Sende Unuttum', 'bu-gece-aski-sende-unuttum-candan-sevinc-e5mxq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu gece aşkı sende unuttum

Kayboldu gözbebeklerimdeki coşku

Birlikteliği sevdayı sende unuttum

Kalmadı ellerimdeki o masum koku

Sende unuttum denizimin mavisini

Ayaklarımdan yukarı vurmadı dalgalar

Suskunluğun hiç böyle değmemişti

Gecelerde saklı kor ateş kadar

Sende unuttum türkülerin nağmelerini

Dört mevsim de güldü geçti

Kışı tatmamıştım hiç bu kadar

Uzak bakışların beni yanındayken seçti

Bu gece aşkı sende unuttum

Kahroldu dilim gözlerim soldu

Geçit vermedi caddedeki ışıklar

Bak gençliğimde ellerinde yokoldu.', 'Bu gece aşkı sende unuttum Kayboldu gözbebeklerimdeki coşku Birlikteliği sevdayı sende unuttum Kalmadı ellerimdeki o masum koku Sende unuttu...', ARRAY['Türk Edebiyatı','Şiir','Candan Sevinç']::text[], 8.5, '{"poet":"Candan Sevinç","poet_slug":"candan-sevinc","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bu-gece-aski-sende-unuttum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmeyene Sorulur mu', 'sevmeyene-sorulur-mu-i-rfan-kayagil-ubycb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ağlıyor gök kubbe

Benim gibi aşık mı ne

Her aşkın sonu

Delinir mi? 

Biz eledik unumuzu 

Bir bak dibi görünür mü? 

Kim kaldı kalbur üstünde

Su aldı, sel götürdü

Ne keremden ne Aslıdan

Ara iz bulunur mu? 

Gitti gidenler nafile

Bu diyarda durulur mu? 

Tavşan dağa aşık

Koşar durur yorulur mu? 

Yanar yürek külhan ise

Buzdan köşke konulur mu? 

Aşık olan elbet anlar

Sevmeyene sorulur mu?', 'Ağlıyor gök kubbe Benim gibi aşık mı ne Her aşkın sonu Delinir mi?  Biz eledik unumuzu  Bir bak dibi görünür mü?  Kim kaldı kalbur üstünde S...', ARRAY['Türk Edebiyatı','Şiir','İrfan Kayagil']::text[], 8.5, '{"poet":"İrfan Kayagil","poet_slug":"i-rfan-kayagil","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sevmeyene-sorulur-mu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Abdulkadir Geylani', 'abdulkadir-geylani-halit-ozduzen-vmpiq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Muhammed neslinden, Şah-ı Veliden,

Gonca Hüseyin’den, gül Fadime’den,

Zarif ve inceden, nurdan bir beden,

Sultanlar sultanı pir Abdulkadir.

Abidler içinde bir Abdulkadir.

	Hasan-el Basri’nin irfan yolundan,

	Bağdatlı Cüneyd’in aşkın kolundan,

	İrem bağlarının eşsiz balından,

	Sultanlar sultanı pir Abdulkadir.

	Aşıklar içinde şir Abdulkadir.

Kırklar, Yedilerin sultanı sensin,

Gavslar meclisinin imamı sensin,

İlim deryasının ummânı sensin, 

Sultanlar sultanı pir Abdulkadir.

Arifler içinde mir Abdulkadir.

	Erenler bezminde dergâh kurulur,

	Tüm veliler divanında bulunur,

	Hama erlerinden yolun sorulur,

	Sultanlar sultanı pir Abdulkadir.

	Lütfunla rüyama gir Abdulkadir.', 'Muhammed neslinden, Şah-ı Veliden, Gonca Hüseyin’den, gül Fadime’den, Zarif ve inceden, nurdan bir beden, Sultanlar sultanı pir Abdulkadir. ...', ARRAY['Türk Edebiyatı','Şiir','Halit Özdüzen']::text[], 8.5, '{"poet":"Halit Özdüzen","poet_slug":"halit-ozduzen","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/abdulkadir-geylani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dört Büyük Gavsullah', 'dort-buyuk-gavsullah-halit-ozduzen-j00c6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bağdat’tadır türbesi, her yandadır gölgesi,

  Ona evlat olanın, tez açılır perdesi,

  Ah Geylâni, Geylâni can Geylâni, Geylâni

  Âlemlerin sultanı Abdulkadir Geylâni 

  Nurânidir nurâni Abdulkadir Geylâni

 Âlemlerin sultanı Abdulkadir Geylâni 

 	Basra’dadır türbesi, her yandadır gölgesi,

  	Ona evlat olanın, arşa çıkar nefesi,

  	Ah Rufâi, Rufâi can Rufâi, Rufâi

  	Âriflerin sultanı Seyd Ahmed-el Rufâi

 	Nurânidir nurâni Seyd Ahmed-el Rufâi

  	Âriflerin sultanı Seyd Ahmed-el Rufâi

  Tanta’dadır türbesi, her yandadır gölgesi,

  Ona evlat olanın, çabuk olur meyvesi, 

  Ah Bedevi, Bedevi can Bedevi, Bedevi

  Âşıkların serveri Seyd Ahmet-el Bedevi

   Nurânidir nurâni Seyd Ahmet-el Bedevi

  Âşıkların serveri Seyd Ahmet-el Bedevi

  	Dusuk’tadır türbesi, her yandadır gölgesi,

  	Ona evlat olanın, nurla dolar kafesi,

  	Ah Dusuki, Dusuki can Dusuki, Dusuki

  	Âşıkların mâşuki Seyd İbrahim Dusuki

 	Nurânidir nurâni Seyd İbrahim Dusuki

 	Âşıkların mâşuki Seyd İbrahim Dusuki', 'Bağdat’tadır türbesi, her yandadır gölgesi,   Ona evlat olanın, tez açılır perdesi,   Ah Geylâni, Geylâni can Geylâni, Geylâni   Âlemlerin s...', ARRAY['Türk Edebiyatı','Şiir','Halit Özdüzen']::text[], 8.5, '{"poet":"Halit Özdüzen","poet_slug":"halit-ozduzen","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/dort-buyuk-gavsullah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senle Anlam Buldu Şiirim Sözüm', 'senle-anlam-buldu-siirim-sozum-umut-gungor-dtdhm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Senle anlam buldu şiirim sözüm,

Açıldı dünyaya şu iki gözüm,

Şiire döküldü yüreğim özüm,

Başladı kalemim seni yazmaya.

Çağlatıp yüreği aşka koşturdun,

Her şiirde inan beni coşturdun,

Ne güzel gülüşün şimdi hoşdurdun,

Başladı kalemim seni yazmaya.

Yaşanan sevginin şiiri güzel,

Yazdığım şiirler hep sana özel,

Sürecek bir ömür ebet ezel,

Başladı kalemim seni yazmaya.

Sabır boncuğunu elde sayarken,

Sen şiir olup kalbime yağarken,

Gitme diyecek oldum daha erken,

Başladı kalemim seni yazmaya.', 'Senle anlam buldu şiirim sözüm, Açıldı dünyaya şu iki gözüm, Şiire döküldü yüreğim özüm, Başladı kalemim seni yazmaya. Çağlatıp yüreği aşka ...', ARRAY['Türk Edebiyatı','Şiir','Ümüt Güngör']::text[], 8.5, '{"poet":"Ümüt Güngör","poet_slug":"umut-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/senle-anlam-buldu-siirim-sozum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
