INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yuvarlağın Köşeleri-Yaşamak Ölmek-Etika-İkinci Bölüm-104', 'yuvarlagin-koseleri-yasamak-olmek-etika-i-kinci-bolum-104-ozdemir-asaf-91ntv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'YAŞAMAK ÖLMEK-ETİKA-104

Ne kadar çok olursa o kadar ölmek kolay.

Ne kadar ölmek olursa o kadar saymak kolay.

Ne kadar saymak olursa o kadar bilmek kolay.

Ne kadar bilmek olursa o kadar anlamak kolay.

Ne kadar anlamak olursa o kadar unutmak kolay.

Ne kadar unutmak olursa, o kadar yaşamak kolay.

Bunun için o kadar zor

Kolay yaşamak.', 'YAŞAMAK ÖLMEK-ETİKA-104 Ne kadar çok olursa o kadar ölmek kolay. Ne kadar ölmek olursa o kadar saymak kolay. Ne kadar saymak olursa o kadar ...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yuvarlagin-koseleri-yasamak-olmek-etika-ikinci-bolum-104-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çemen ekmek', 'cemen-ekmek-reyhan-tataroglu-vl6y7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'çemenci idi...

                                  ekmek arası

                                  iki buçuk lira yarısı

                                  bir kaç küçük iskemle

                                  laleten bir masa

                                  kırık döküktü kasa

                                  üzerinde 

                                  her zamanki pardüsü

                                  ne gösterişi var,ne süsü

                                  demirden bardaklar

                                  dolu,boş sürahiler

                                  müşterinin 

                                  biri gelir, biri gider

                                  nesineydi bu itibar...

                                  içeride

                                  uçuşan sinekler

                                  kapıda

                                  kabuk kemiren inekler

                                  görünüşü

                                  biraz köhne,biraz gizemli

                                  mırıldanıyordu gözleri nemli

                                  kazanmak değildi gayesi

                                  para

                                  olmak istemiyordu sadece

                                  fukara

                                  muhtaçlık yoktu

                                  kitabında

                                  hizmet vardı Hak 

                                  tadında

                                  kokusu alınmazdı hiç çemenin

                                  tadına doyulmazdı yemenin

                                  bakmazdı dikkatlice

                                  kimsenin yüzüne

                                  değildi kibirden...

                                  ki dalıyordu birden

                                  ne verirlerse alır

                                  ne alırlarsa verirdi

                                  okurken kitabını erirdi

                                  masanın altında idi kitap

                                  nasihatlarla,ibretlerle dolu hitap

                                  sanırım buydu onu cezbeden

                                  Hu''şunun içindeydi cazibeden

                                  başında takke

                                  beyaz yüzünde sakal

                                  hem seyre dal

                                  hem de çemen al...', 'çemenci idi...                                   ekmek arası                                   iki buçuk lira yarısı                        ...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Tataroğlu']::text[], 8.5, '{"poet":"Reyhan Tataroğlu","poet_slug":"reyhan-tataroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/cemen-ekmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sefer', 'sefer-mehmet-akkin-n6v4c', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yansın bu dünya dönecekse derinden

Oynasın halk''ı ahali yerli yerinden

Yok ise zerre mutluluk

Döndüğü her seferinden

Ne sen ne ben nede cümle alem

Yansın bu dünya dönecekse derinden

Yıldızlar ağlasın kederinden

Yok ise zerre mutluluk

Döndüğü her seferinden

Yansın bu dünya dönecekse derinden', 'Yansın bu dünya dönecekse derinden Oynasın halk''ı ahali yerli yerinden Yok ise zerre mutluluk Döndüğü her seferinden Ne sen ne ben nede cüml...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akkın']::text[], 8.5, '{"poet":"Mehmet Akkın","poet_slug":"mehmet-akkin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sefer-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mikdat Bal İbrahim Coşar 8. MSN Atışması', 'mikdat-bal-i-brahim-cosar-8-msn-atismasi-mikdat-bal-0cdzd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hayalin gözümde tütüyor artık 

Sanki oldun bize el arkadaşım 

Sana gönül kapım her zaman açık 

Gel gönül yerini al arkadaşım. ………..İ.Coşar

Az kaldı bu hasret bitiyor artık

Sabret, bundan emin ol arkadaşım

Bunca özlem, hasret yetiyor artık

Geliyorum bekle gül arkadaşım………M.Bal

Bilirim seni de yakıyor hasret 

Olmuyor bir türlü kavuşmak kısmet 

Seninle bütündür bendeki haslet 

Şu zalim gurbeti del arkadaşım. …..İ.Coşar

Küller ateş almaz hasret yakar mı

Yandı benim çıram sakız kokar mı? 

Dostlarım sılada yola bakar mı? 

Şimdi bekler beni yol arkadaım……M.Bal

O güzel günleri anar yanarım 

Kavuşma umudu, kanar yanarım. 

Hasreti sabıra banar yanarım 

Kokunu getirir yel arkadaşım …..İ.Coşar

Geliyorum artık bileti aldım

Az daha sabreyle geldim ha geldim

Uzun zaman oldu gurbette kaldım

Hasret sorsan bende bol arkadaşım….M.Bal

Hep öğüt, nasihat gelirdi dilden 

Şimdi hep yalnızım, ne gelir elden 

Dertleşir dururum, diktiğin güllen 

Ver artık yüküme bel arkadaşım. …..İ.Coşar

Beşikten mezara eyle nasıhat

Sana saadetle dilerim sıhhat

Ömür baştan sona sürekli cihat

Viran gönüllere dol arkadaşım……Mikdat Bal

Coşari der her an arar gözlerim, 

Gelmek istesem de gitmez dizlerim, 

Sana hasrettendir sitem sözlerim, 

Bekletme kendini, gel arkadaşım…….İ.Coşar

Mikdatî der dostum vuslat yakındır

Selam saygı hürmet bu da hakkındır

Kendine iyi bak dertten sakındır

Seni seviyorum bil arkadaşım…….M.Bal', 'Hayalin gözümde tütüyor artık  Sanki oldun bize el arkadaşım  Sana gönül kapım her zaman açık  Gel gönül yerini al arkadaşım. ………..İ.Coşar A...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/mikdat-bal-ibrahim-cosar-8-msn-atismasi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül kurusu sevdalara', 'gul-kurusu-sevdalara-erdogan-tugsuz-hyek1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gül kurusu sevdalara 

Tutup yağmurlar yağarken, 

Gelip de kuşlar konmaz benim gül bahçeme, 

Sen umrumda değil çeker giderim diyorsun, 

Git o zaman geriye kalanla ben idare ederim, 

Çok türküler söyledim 

Sen kaçını duydun ki 

Şimdi ayrılık için ağıtlar istiyorsun, 

Öldüreceğim seni demiştin 

Hani bir gün yapamaz demiştim ya 

Bak işte gidiyorsun.', 'Gül kurusu sevdalara  Tutup yağmurlar yağarken,  Gelip de kuşlar konmaz benim gül bahçeme,  Sen umrumda değil çeker giderim diyorsun,  Git o...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Tuğsuz']::text[], 8.5, '{"poet":"Erdoğan Tuğsuz","poet_slug":"erdogan-tugsuz","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gul-kurusu-sevdalara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gec kalmadan gel', 'gec-kalmadan-gel-serpil-maglicoglu-90wmr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bana gercek yüzünü göster

Gösterebilirsen eger

Bana gercek sözünü söyle

Söyleyebilirsen eger

Bana gerceklerini getir

Getirebilirsen eger

Ey gidi sevgili

            Gec kalmadan gel

            Gelebilirsen eger', 'Bana gercek yüzünü göster Gösterebilirsen eger Bana gercek sözünü söyle Söyleyebilirsen eger Bana gerceklerini getir Getirebilirsen eger Ey ...', ARRAY['Türk Edebiyatı','Şiir','Serpil Maglicoglu']::text[], 8.5, '{"poet":"Serpil Maglicoglu","poet_slug":"serpil-maglicoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gec-kalmadan-gel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
