INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Esintisi', 'gonul-esintisi-mesut-karaca-ppvcu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hayata adanmış sevgiler vardır gönlümüzde.

Gönlümüzden gelir gözümüzden akan yaşlar.

Teselliye yer kalmamıştır artık.

Gündüz bulutlardan, gece yıldızlardan sordum seni.

Hem de tek dostum onlarmış gibi.

Ve günlerce yalvardım rabbime: ''güneş doğmasın'' diye.

Benim gönlümün ateşi bana yetti.

Gayr-ı güneşe ne gerek kaldı.

Söyle gönlümün sultanı.

Sen hiç sordun mu beni? 

Aradın mı nereye gittiği belirsiz vagonlarda? 

Çığlık çığlık haykırışlarda...', 'Hayata adanmış sevgiler vardır gönlümüzde. Gönlümüzden gelir gözümüzden akan yaşlar. Teselliye yer kalmamıştır artık. Gündüz bulutlardan, ge...', ARRAY['Türk Edebiyatı','Şiir','Mesut Karaca']::text[], 8.5, '{"poet":"Mesut Karaca","poet_slug":"mesut-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gonul-esintisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üç Şiir Üç Farklı Son-1', 'uc-siir-uc-farkli-son-1-birsen-ates-bras7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'parlıyordu gözleri ayın

ışıklarını salarken geceye

inmiş denizlere sevgiyle

inadına ışıltılı bir yakamoz 

sorsam alır mıydı koynuna 

ah huzurla dolsam bir uyusam

gün ağardığında mavide uyansam 

su üstüne şiirler yazsam silinmese

usulca martılar geçse şiirlerimden

dizelerim ay ışığında saklansa 

yıkasam yalnızlığımı hüzünlerimde 

onarabilir miydi zaman

hayatım geçerken ellerimden

19.03.06', 'parlıyordu gözleri ayın ışıklarını salarken geceye inmiş denizlere sevgiyle inadına ışıltılı bir yakamoz  sorsam alır mıydı koynuna  ah huzu...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/uc-siir-uc-farkli-son-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Git artık', 'git-artik-serap-ozkan-4accl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'şimdi nasıl bahar olur

nasıl açar çicekler

ve nasıl güler gözlerinde

terkedilmiş bebekler.

yok yok yok

lanetlemedim insan yanımı

hala sıcak tutarım 

kabuk bağlasada yaramı

lanetlemedim gidişini

beklemiyorum dönüşünü

şimdi mevsim solgun

içimde kalmışsa bir yanım ölgün

elbet gece gelir çalar kapımı

usulca açar, saçar acımı

gece dolar odama,yakarım sigaramı

yakarım aydınlatırım odamı

sen ışığını al git

git

git artık

bekleme beni

savdım kendimi.', 'şimdi nasıl bahar olur nasıl açar çicekler ve nasıl güler gözlerinde terkedilmiş bebekler. yok yok yok lanetlemedim insan yanımı hala sıcak ...', ARRAY['Türk Edebiyatı','Şiir','Serap Özkan']::text[], 8.5, '{"poet":"Serap Özkan","poet_slug":"serap-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/git-artik-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kabadayı Mustafa.', 'kabadayi-mustafa-veysel-alkan-qybl4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mustafa''da var,cehalet.

Her fikire muhalefet.

Tanıştığım güne,lanet! 

Kaba adam,kabadayı.

Ha Mustafa,ha da ayı.

Dili uzun,kısa boyu.

Kalbi kötü,bozuk huyu.

İnsanmıdır acep soyu? 

Kaba adam,kabadayı.

Ha Mustafa,ha da ayı.



Ne vicdan var,ne de değer.

Daralınca,hemen söver.

Dayak yemez,daim döver.

Kaba adam,kabadayı.

Ha Mustafa,ha da ayı.



Herkes kötü,o hep iyi.

Beğenmiyor hiç kimseyi.

Kendin sayar,cihan beyi.

Kaba adam,kabadayı.

Ha Mustafa,ha da ayı.

Çok konuşur,çok şomağaz.

Dili tutmaz,bir boşboğaz.

Sinirlenip,sıkar boğaz.

Kaba adam,kabadayı.

Ha Mustafa,ha da ayı.

Her olaya,zıplayandır.

Haklıları,haklayandır.

Tahammülü zorlayandır.

Kaba adam,kabadayı.

Ha Mustafa,ha da ayı.

Olur olmaz,durduk yere.

Adam dövüp,serer yere.

Olmaz,olur ona göre.

Kaba adam,kabadayı.

Ha Mustafa,ha da ayı.



Şu Mustafa ne yamanmış? 

Namı,dillere dolanmış.

Çoluk çocuk bile,yılmış.

Kaba adam,kabadayı.

Ha Mustafa,ha da ayı.', 'Mustafa''da var,cehalet. Her fikire muhalefet. Tanıştığım güne,lanet!  Kaba adam,kabadayı. Ha Mustafa,ha da ayı. Dili uzun,kısa boyu. Kalbi k...', ARRAY['Türk Edebiyatı','Şiir','Veysel Alkan']::text[], 8.5, '{"poet":"Veysel Alkan","poet_slug":"veysel-alkan","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/kabadayi-mustafa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umuttu İstanbul', 'umuttu-i-stanbul-umran-aldic-mnkeq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gece kondu mahallesinin 

Tek  odalı  bir  evinde  açtı  gözlerini  dünyaya.

Zor  bir  doğum  olmuştu  annesi  için:

Baba  kapıda  donmuştu  beklerken.

Ama  işte  sonuç  oğlu  olmuştu. 

Gururla  dikildi  İsmail  çavuş.

Öyle  derlerdi  ona  İsmail  çavuş  lakabıydı  bu.

Tokat  ın  Erbağ  ilçesinden  gelmişti.

İstanbul  umut  diyerek  taşı  toprağı  altın  bilerek.

Çok  çabuk  öğrendi  söylenenlerin  masal  olduğunu.

Ah  köyde  olsa  bir  soğan  kırardı:

Bir  tas  tarhana  çorbası  ve  yufka  ekmeği; 

Oysa  burası  aahh  burası  adı  büyük  İstanbul.

Her  şey...  allahın  suyu  bile  parayla  burda.

Zeynosuna  baktı  doğumdan  sonra  yorgun  bitap`

Hamallıktan  başka  iş  bulamamıştı  İsmail  çavuş.

Köydeki  itibarıda  yoktu  hani  3  nesilden  sonra

Doğan  tek  erkek  çocuk  olması  önemli  değildi  burda.

Çocuk  doluydu  yalınayak  perişan,  koşturan  çamurlu  sokaklar da.

Diploma  istiyordu  çaldığı  her  kapı,  meslek  diyordu  nereye  gitse  iş  için.

Onda  hiç  biri  yoktuki  bunların,  gücü  vardı  kuvveti  ve  dürüstlüğü.

İki  sokak  ötede  cadde  bölmüştü  gece  konduyla,

Zenginlerin  oturduğu  siteyi,  orası  cennet  burası  cehennemdi  sanki.

Oğluna  baktı!  tek  yavrusuna  ve  tekrar  dikildi  gururla.

Yeni  bir  can  bir  nefes  dedi;  umut  dedi.

İnşallah  İstanbul  gibi  boş  çıkarmaz  ümitlerimi.

Okutacağım   oğlumu  büyük  adam  olacak,

Diploması  olacak,  hiç  kimse  tepeden  bakmayacak  ona.

İstanbul  aaahh  İstanbul  masmavi  deniziyle,  gerdanlık  gibi  köprüsüyle

Gökyüzüne  uzanan  çok  minareli  camileriyle,

Belki de  kimsenin  duymadığı  ezan  sesleriyle,

Asırlardır  her  ırkın  her  devletin  gözdesi  rüyası; 

Türkiye  nin  her  ilinin  en  güzeli  umudu  İstanbul.

İzin  ver  ALLAHIM  izin  ver  bu  kuluna,

Tokat lı  ismail  çavuşun  oğluda  girsin.

Girsin  insan  sıfatına  beyler  gibi  yürüsün.

Cebinde  diploması  İstiklal in  ortasında...

Yıllar  geçmişti  bu  duanın  üzerinden.

Şimdi  İsmail  çavuşun  oğlu  diploması  cebinde,

Sarıyer de  bir  kır  kahvesinde   oturmuş; 

Babasını  ve  onun  umutlarının  gerçek  olduğunu

Düşünerek  gururla  dikildi  babası  gibi.

Ama  onun  bildiği  bir  şey  daha  vardı  fazladan; 

İstanbul'' u  yenmek  için  bir  değil  bin  diploma  yetmezdi.

O  gene  aynı  şu  mavi  deniz'' deki  kıyıya  vuran,

Dalgaların  bir  damlasıydı,  İstanbul  için.

Ne  eksik  ne  fazla  sadece  bir  damla.

Önce  hafif  bir  ıslaklık  sonra  kuruyup,

İzi  bile  kalmamış  binlerce,  milyonlarca  damla  gibi.

Asırlık  kaldırımda........', 'Gece kondu mahallesinin  Tek  odalı  bir  evinde  açtı  gözlerini  dünyaya. Zor  bir  doğum  olmuştu  annesi  için: Baba  kapıda  donmuştu  ...', ARRAY['Türk Edebiyatı','Şiir','Ümran Aldıç']::text[], 8.5, '{"poet":"Ümran Aldıç","poet_slug":"umran-aldic","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/umuttu-istanbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serçe Yüreğim', 'serce-yuregim-umran-aldic-mi1tt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kapkara  bulutlar  dolarya  bazen,

Kararır  gökyüzü  bir  sıkıntı  çöker.

Terlersin  buram  buram  üşürken.

Yağmuru  özler  toprak  ağaçlar.

Sonra  birden  şimşekler  çakar,

Boşalır  yağmur  gökler  haykırırken.

Gözgözü  görmez  giderken.

İşte  onun  gibi,  boşaldı  yüreğim.

Aktı  sanki.....

Gülün  üstüne  düşen  bir  çiğ  damlası  gibi.

Oysa  ne  kadar  mutluydu  uçarken.

Gökyüzünde  bembeyaz  martı  gibi.

Dalıp  çıkardı  köpüklü  dalgalara,

Havada  yakalardı  atılan  simitleri.

Ama  yok  dur......bir   serçeydi  yüreğim.

Yeni  öğrenmiş  uçmayı  düşerken  yuvadan.

Öyle  gamsız  öyle  cesaretli,

Bir  ok  lastiği  kalbini  delene  kadar.', 'Kapkara  bulutlar  dolarya  bazen, Kararır  gökyüzü  bir  sıkıntı  çöker. Terlersin  buram  buram  üşürken. Yağmuru  özler  toprak  ağaçlar....', ARRAY['Türk Edebiyatı','Şiir','Ümran Aldıç']::text[], 8.5, '{"poet":"Ümran Aldıç","poet_slug":"umran-aldic","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/serce-yuregim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektuplar-105 02/05/0001', 'mektuplar-105-02-05-0001-mahzun-doga-aoq2t', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne zor

ikimiz de duramıyoruz yerimizde

ve koşamıyoruz

ikimiz de parçalanıyoruz

durduğumuz yerde

birleşemiyoruz

Zor

ikimiz de

uzanamıyoruz

yetişemiyoruz hiçbir yerimize

bir noktamız kadar bile değişmiyoruz birbirimize

Ne zor

bu kadar ilerlemişken insaniyet

ilerleyemiyoruz birbirimize hiç

biz iki insan

Ne çok zor

ikimiz de

varız

ikimiz de yokuz', 'Ne zor ikimiz de duramıyoruz yerimizde ve koşamıyoruz ikimiz de parçalanıyoruz durduğumuz yerde birleşemiyoruz Zor ikimiz de uzanamıyoruz ye...', ARRAY['Türk Edebiyatı','Şiir','Mahzun Doğa']::text[], 8.5, '{"poet":"Mahzun Doğa","poet_slug":"mahzun-doga","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/mektuplar-105-02-05-0001-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektuplar-106 03/05/0001', 'mektuplar-106-03-05-0001-mahzun-doga-hpiy7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aha şuramda bir sesin var

ki düşmez hiçbir yerimden

sürekli ağlar

ki susmaz hiçbir yerimde

aha şuramda işte

şuramda

O sesin var

aha şimdi yine

başımı yere eğer

yer çöker

öbür tarafından çıkar yerin

canı cehenneme atılır

bütün yıldızlar çöker

gece yine benim olur

ve o sesin

ve kapkara bir karanlık

Aha tam şuramda

koca bir ağrı ordusu

can çizen yaralı

can çıkaran

ve öldürmeyen

aha o sesin

bu şiirin tam şurası', 'Aha şuramda bir sesin var ki düşmez hiçbir yerimden sürekli ağlar ki susmaz hiçbir yerimde aha şuramda işte şuramda O sesin var aha şimdi yi...', ARRAY['Türk Edebiyatı','Şiir','Mahzun Doğa']::text[], 8.5, '{"poet":"Mahzun Doğa","poet_slug":"mahzun-doga","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/mektuplar-106-03-05-0001-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadınım', 'kadinim-gozem-basak-hh4mv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Uzak diyarlardaki başak saçlı kadınım,

Sen yaşadığım hayat,

Sen aldığım nefes,

Sen duyduğum tek sessin.

Uzak diyarlardaki ceylan gözlü kadınım,

Sen dudağımdaki özlem türküsü,

Sen yüreğimdeki umut busesi,

Sen yalnızlığımın tek tesellisi.

Uzak diyarlardaki selvi boylu kadınım,

Sen geçmişimin tarihi,

Sen bugünümün yaşanmışlığı,

Sen geleceğimin merakısın.

Uzak diyarlardaki kadınım,

Sen sevilmeden sevmeyi öğreten,

Aşk acısı, hasret nedir belleten,

Sen aklı firar ettiren,

Sen bedenim, ruhum, aklımsın

Geçmişim, bugünüm, yarınımsın

Sen bu dünyada yaşadığım hayat,

Ahirette vereceğim hesapsın.', 'Uzak diyarlardaki başak saçlı kadınım, Sen yaşadığım hayat, Sen aldığım nefes, Sen duyduğum tek sessin. Uzak diyarlardaki ceylan gözlü kadın...', ARRAY['Türk Edebiyatı','Şiir','Gözem Başak']::text[], 8.5, '{"poet":"Gözem Başak","poet_slug":"gozem-basak","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kadinim-84-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlatamıyorum', 'anlatamiyorum-fethi-aslan-yhyde', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Anlatamıyorum,

birer birer boğazıma tıkanıyor kelimeler.

Geceler uzuyor,

karanlıklar uzuyor

Güneş doğmak bilmiyor.

Aklımda  beni sana getirecek 

bütün adresler kayboluyor,

anlatamıyorum……

Anlatamıyorum,

siyaha  dönüyor maviler.

Gidişlerinin ayazı

yaşartıyor gözlerimi.

Özlemlerin depremi

sarsarıyor yüreğimi

anlatamıyorum........

Anlatamıyorum,

bir yitik hasret,

bir yitik sevda.

Bilsen, nasıl yakar yüreğimi

kor bir ateş misali.

Öyle müşkül bir iş ki,

ben anlatamıyorum.

Ne bu sevdayı,

ne de bu hasreti.', 'Anlatamıyorum, birer birer boğazıma tıkanıyor kelimeler. Geceler uzuyor, karanlıklar uzuyor Güneş doğmak bilmiyor. Aklımda  beni sana getire...', ARRAY['Türk Edebiyatı','Şiir','Fethi Aslan']::text[], 8.5, '{"poet":"Fethi Aslan","poet_slug":"fethi-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/anlatamiyorum-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayal miydin?', 'hayal-miydin-birsen-ates-x8emi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sarıydı rengin

buğulu bir camın ardından

bakar gibiydi gözlerin

yüzün yapışmış ruhuma

öylesine sendeyken

nefesini vermiş ölümde

bilemedim

ben hala dünde kalan 

acılar da savrulurken

avunurken 

sen beni hiç düşünmedin

ardına bakmadan gidiverdin

bir rüyamıydı gördüğüm

yoksa hayal miydin

23.03.06', 'sarıydı rengin buğulu bir camın ardından bakar gibiydi gözlerin yüzün yapışmış ruhuma öylesine sendeyken nefesini vermiş ölümde bilemedim be...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/hayal-miydin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erguvani', 'erguvani-nur-ela-2ylkt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yine sisli sabahlar

Yine gam

Yine hüzün sardı

/sapsarı



Oysa bahar gelmemiş miydi gözlerinden. 

Erguvanlar açmamış mıydı dudaklarımda ve Sen 

Gizli salıncaklar kurmamış mıydın kirli mavi göklere



Yel değirmenlerine savaş açmıştık da 

Denizleri toplamamış mıydık? 



İşte/ 

Avuçlarıma bırakılan

Kanatsız kuşlar

Şimdi neyin nesi? 





NurEla', 'Yine sisli sabahlar Yine gam Yine hüzün sardı /sapsarı Oysa bahar gelmemiş miydi gözlerinden.  Erguvanlar açmamış mıydı dudaklarımda ve Sen ...', ARRAY['Türk Edebiyatı','Şiir','Nur Ela']::text[], 8.5, '{"poet":"Nur Ela","poet_slug":"nur-ela","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/erguvani-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimdeki nöbetçi', 'i-cimdeki-nobetci-aslan-koyuncu-jxn6w', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Her tarafa hükmeder..Herşey  o''ndan sorulur...

İçimdeki nöbetçi..Ne uyur..ne yorulur...', 'Her tarafa hükmeder..Herşey  o''ndan sorulur... İçimdeki nöbetçi..Ne uyur..ne yorulur......', ARRAY['Türk Edebiyatı','Şiir','Aslan Koyuncu']::text[], 8.5, '{"poet":"Aslan Koyuncu","poet_slug":"aslan-koyuncu","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/icimdeki-nobetci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni derde saldın gönül - Kâmil Durmuşoğlu''nun ''''Aklım Yere Serdin Gönül'''' şiirine nazire', 'beni-derde-saldin-gonul-k-mil-durmusoglu-nun-aklim-yere-serdin-gonul-siirine-nazire-mikdat-bal-vcm9s', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir güzele aşık edip

Beni derde saldın gönül

Kapısına eşik edip

Yerden yere çaldın gönül

Aşk nârında pişirerek

Gözlerimi şişirerek

Vesveseye düşürerek

Beni benden  aldın gönül

Hissetmeyip sezemezken

Sen karada gezemezken

Gölde bile yüzemezken

Deryalara daldın gönül

Bu diyardan göç çıkalım

Hadi artık kaç bakalım

Beyaz oldu saç sakalım

Sen on beşte kaldın gönül

Ters tutunca mercekleri

Göremedin çiçekleri

Anlayınca gerçekleri

Kederlerle doldun gönül

Yakınların el dediler

Ölülerin gel dediler

Yeter artık öl dediler

Saçlarını yoldun gönül

Hep oynadın bana oyun

Vefasızlık imiş huyun

Süründürdün yüzü koyun

Beni zayıf buldun gönül

Mikdatî’yim yaktın beni

Mağlüp ettin yıktın beni

Sattın beni ektin beni

Ben ağlarken güldün gönül', 'Bir güzele aşık edip Beni derde saldın gönül Kapısına eşik edip Yerden yere çaldın gönül Aşk nârında pişirerek Gözlerimi şişirerek Vesveseye...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/beni-derde-saldin-gonul-kamil-durmusoglu-nun-aklim-yere-serdin-gonul-siirine-nazire-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '(Tahlil) HECE ŞİİRİ üstüne Can Kardeşime Açık Mektup-1', 'tahlil-hece-si-i-ri-ustune-can-kardesime-acik-mektup-1-mustafa-ceylan-bzjzf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Can Kardeşim MERHABA,

HECE ŞİİRİNDEN NOTLAR….:

ÖNCE bir binanın projesi-iskeleti gibi HECE ŞİİRİ’nin de projesine –iskeletine bakalım, olur mu? 

DİYELİM ÜÇ kıtalık şiir yazacağız. İşte projesi:

………………………………..a

………………………………..b

………………………………..a

………………………………..b

xx

………………………………..c

………………………………..c

………………………………..c

………………………………..b

xx

………………………………..d

………………………………..d

………………………………..d

………………………………..b

işte bu kadar.

Buradaki a,b,c,d ler KAFİYE’lerdir. KAFİYE NEDİR dersen. Kafiye: mısra sonlarındaki ses benzerlikleridir. Yani (acı,bacı,öcü veya gül,tül,bülbül yada  bak,yak,tak,çak,ak,çık,çek,ek,tek gibi)     tamam mı? 

En çok KAFİYEDE hata yapar şairler. O da şundan: Kafiyeyi KÖK’ ten değil de EK’ ten yaparlar. O bir hatadır. Yani, (GİTTİM-GELDİM kelimelerinin ikisi de TİM-DİM le bittiği halde KAFİYE DEĞİLDİR. Çünkü KÖKten değil, ekten yapılmış oluyorlar. Bu iki kelimenin kökleri GİTMEK ve GELMEK’tir değil mi? İkisi de MEK LE BİTTİĞİ HALDE git ve gel kelimelerinde UYUM yoktur, yani KAFİYE değildirler. Şairlerin yaptığı ÖNEMLİ HATA BUDUR. Sadece türkü ve şarkı sözlerinde bu hoş görülebilir. ALDIM-SATTIM kelimeleri de aynen öyledir. AL ve SAT kelimeleri birbirine uymaz, kafiye değildirler yani. Oysa AL’ın kafiyeleri al,dal,sal,bal,hal,kal,ol,dol vb olduğu gibi SAT’ın kafiyeleri de Sat,at,yat,hat,kat,mat,çat vb dir.

Bak kardeşim,

KAFİYE ÖNEMLİ. KAFİYE:Kelimeleri kesip parçalamak yada Kelimelerle DANS etmektir.

DANS etmek dedim de bak bir iki örnek veriyim sana. KIRTASİYE kelimesini keselim KIRT ve ASİYE olur demi? Mesela KALABALIK kelimesini keselim KALA ve BALIK olur, ya da

DÜNYA kelimesinin önüne bir kelime ekleyelim DÜNYA…GÖRDÜNYA…Gör kelimesini ekleyince bak değişti. DÜŞERİM kelimesiyle dans edelim DÜ ve ŞER’İM(Dü=iki demek, ŞER=Kötü demek; veya DÜŞ, ER’im yaptık DÜŞ=rüya, hayal demek ER=asker DEMEK DEĞİL Mİ? BAKAN kelimesini keselim BAK ve AN oluyor değil mi? 

Yani can kardeşim, yolda gördüğün levhaları, yazıları, okuduğunu, işittiğini hep kes, biç, oyna KELİMELERLE…BUNU ALIŞKANLIK HALİNE GETİR. Göreceksin bak neler bulacaksın ve TÜRKÇE’mizin ne kadar zengin olduğunu öğreneceksin.

BALIK kelimesinin önüne bir kelime ekleyelim KALA yı ekleyelim. Ne olur? KALABALIK değil mi? Al, sana şahane üç kafiye: BALIK / KALABALIK / ALIK

Aynen böyle olduğu gibi COŞAR / KOŞAR/ TAŞAR/AŞAR/ŞAŞAR/BAŞAR/YAŞAR vb. kelimelerde Ş ortada ses veren harftir. 

Neyse ileride bu konuya daha DETAYLICA gireceğiz.

Asıl konumuza gelelim.

ÜÇ KITALIK PROJEMİZE… Projemiz şöyleydi değil mi? 

………………………………..a

………………………………..b

………………………………..a

………………………………..b

xx

………………………………..c

………………………………..c

………………………………..c

………………………………..b

xx

………………………………..d

………………………………..d

………………………………..d

………………………………..b

DEMEK Kİ, birinci kıtanın İLK SATIRINDAKİ SON KELİME ile 3. satırındaki son kelime KAFİYE olacak, (a ve a işaretli)  

Aynen öyle 2. satırdaki son kelime ile 4. satırdaki son kelime kafiye olacak demektir.(b ve b işaretli)  

DEMEK Kİ, ikinci kıtaya bakalım, 1,2,3 satırlar (c,c,c işaretli)     birbiriyle kafiyeli olacak 4. satırı ise BİRİNCİ KITANIN SON SATIRI İle KAFİYELİ olacak

Ve DEMEK Kİ, üçüncü kıtaya bakalım aynen 2. kıta gibi, 1,2,3. satırlar (d,d,d işaretli)    birbiriyle kafiyeli olacak 4. satırı ise BİRİNCİ KITANIN SON SATIRI ile KAFİYELİ olacak.

İşte PROJE-yani ŞİİR BİNASININ iskeleti bu. Anladık mı? 

İSTERSEN buraya kadarı dön bir daha oku.

Şeklimiz bu işte:

 ………………………………..a

………………………………..b

………………………………..a

………………………………..b

xx

………………………………..c

………………………………..c

………………………………..c

………………………………..b

xx

………………………………..d

………………………………..d

………………………………..d

………………………………..b

Örnek verecek olursak

Bu vatan toprağın kara BAĞRINDA

Sıradağlar gibi DURANLARINDIR

Bir tarih boyunca onun UĞRUNDA

Kendini tarihe VERENLERİNDİR

Bak bu ilk kıtada BÜYÜK HARFLE yazdığım BAĞRINDA-UĞRUNDA (a,a)     ve DURANLARINDIR-VERENLERİNDİR(b, b)  

Şimdi kinci kıtasına bakalım

Tutuşup kül olan OCAKLARINDAN

Şahlanıp köpüren IRMAKLARINDAN

Hudutlarda gaza BAYRAKLARINDAN

Alnına ışıklar VURANLARINDIR.

Burada BÜYÜK HARFLE yazdığım OCAKLARINDAN,IRMAKLARINDAN,BAYRAKLARINDAN(c,c,c)     iken son satır VURANLARINDIR (b)     olmuştur. Yani BİRİNCİ KITADAKİ -DURANLARINDIR,VERENLERİNDİR  ve burada da VURANLARINDIR olmuştur, değil mi? 

Gelelim 3. kıtaya

Ardına bakmadan yollara DÜŞEN

Şimşek gibi çakan, sel olup TAŞAN

Huduttan hududa yol bulup KOŞAN

Cepheden cepheyi SORANLARINDIR

Evet, gördün mü, aynen 2. kıta gibi DEĞİL Mİ? 

İşte bu kadar PROJE miz,….

DEVAM EDECEK…', 'Can Kardeşim MERHABA, HECE ŞİİRİNDEN NOTLAR….: ÖNCE bir binanın projesi-iskeleti gibi HECE ŞİİRİ’nin de projesine –iskeletine bakalım, olur ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":86,"source_url":"https://www.antoloji.com/tahlil-hece-siiri-ustune-can-kardesime-acik-mektup-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taşlara iz bırakır sevgin', 'taslara-iz-birakir-sevgin-elazigli-mustafa-kaya-4dvrh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'koparılan bir çiçek gibi

boynu eğik

hayat gülücüğün durmuş..

oysa,

bir çakıl taşı bile sevinir

sevgini alsın yeter. 

bakışın iz bırakır taşa

sıcaklığını alsın yeter

yeniden hayat bulur toprak

ne zaman ellerin değse.

gönül suyuna,

sevinir çiçeklerin.

her kelimede dirilir

açar rengarenk

su olur…güneş olur

okşayan sözlerin.. 

ve,

bir hazan yaprağı hüznün,

baharı kışa çevirir.

oysa,

çöller yeşertir,

gamzelerinle bir tebessümün.

Mustafa kaya

20.03.2006 / Beykoz

www.mustafakaya.net/frm', 'koparılan bir çiçek gibi boynu eğik hayat gülücüğün durmuş.. oysa, bir çakıl taşı bile sevinir sevgini alsın yeter.  bakışın iz bırakır taşa...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/taslara-iz-birakir-sevgin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerze''de Yanmak!', 'gerze-de-yanmak-tarik-sahin-p4gro', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hiç bu kadar 

Yanmamıştı Gerze.

Ne 56 da alev alev,

Ne de 2006 da,

Yan yana evlerinde.

Şubat’ın 13’üne.

Hiç bu kadar 

Yanmamıştı Gerze.

13''ünden 14 Şubatına, 

Sana yandığım kadar! 

                                          (13.02.2006-Gerze/SİNOP)', 'Hiç bu kadar  Yanmamıştı Gerze. Ne 56 da alev alev, Ne de 2006 da, Yan yana evlerinde. Şubat’ın 13’üne. Hiç bu kadar  Yanmamıştı Gerze. 13''ü...', ARRAY['Türk Edebiyatı','Şiir','Tarık Şahin']::text[], 8.5, '{"poet":"Tarık Şahin","poet_slug":"tarik-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gerze-de-yanmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bozuk piskoloji', 'bozuk-piskoloji-ayten-ozlem-yesilcali-hperv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '00546………mehabet haktı.

Adı üstünde mehabet..

Fakat burada bile sindirilmiş özlemler istekler var..

Karşısındakinin ne şartlarda çalışmakta oldugunu bilmeden.

Acırım erkektim diye geçinen insanlarımın haline..

Görmüyor ya karşısındaki onu tanımıyor ya sahte bir isim

Yaşı kemale ermiş sesinden belli, ama 28 yaşındayım der.

Bilmez ki karşısındaki sesinden algılar gerçek yaşını.

Ama o yaşın o sahte ismin özünde yatan dışa vurulmamış,

Arzular istekler,sapıklıklar..

Entel mi ne dedikleri çarpık düşünceler..

Oysa çogu bilmez belki bu entel’in anlamını.

Karşısındaki telefonun diğer ucundaki ne anlatır zavallı

Ablamı gördüm gizliden âşık oldum, ben şimdi hayal ederek; 

Sen ablam ol, yengem ol der, sapık arzusunu yerine getirmek için

Azgının suyu akaraktan anlatır.zavallı..

Telefonun diğer ucundaki, önce şoka girer ve kendinden; 

Erkeklerden nefret eder.

Acaba acaba benin kardeşlerimde de bu varmı diye düşünmeye başlar.

Ama çalışmak zorunda ekmek parasını kazanmak zorunda.

Yada benim ülkemin delikanlıyım diyen erkekleri.

O zavallıların her telefonu açışında acaba arayan tanıdıkmı,

Şimdiki ne konuşacak düşüncesiyle korkarak telefon u açtıklarından 

Haberiniz varmı..

Hiçmi iyi bir sohbet eden yokmu  diye düşünen kadınlarımız..

Ya karısıyla beraber arayan beyler,beyefendiyim diye geçinenler.

Toplumumuzda bu kadar çokmu ikibacak arasını düşünenler..

Örf adet gelenek bitmiş.

Yazık çok yazık insanlarımızın piskolojisi bu kadarmı bozulmuş.

Yokmu içlerinde efendileri

Var tabiî ki sadece sizi biraz sapıklardan kurtarmak için aradım.

Hayat hikayenizi anlatın yada bu insanların hali ne olucak

Onlardan konuşalım.sizde mecburiyeten buradasınız biliyorum,

Diyen beyefendiler…

Ya gel sana iş vereyim diyenler..

Buluşup kötü emellerine telefonda degil gerçekte sahip olmak isteyenler.

Yazık yazık diyorum erkeğim diyen bireyler

Ne yazık ki piskiyatri tedavi görmesi gereken çok insanımız var

Ama onlar sadece delilerin piskiyatri tedavisi görmesi gerektiğini sanırlar

Aslında deli dedikleri onlardan, insaflı daha kişilikli.

Ya orada çalışan biçare bayanı düşünen varmı..

Acaba ne zorlukla o muhabet hatında çalışıyor.

Unutmayın,belkide o sizin kan bağınız olan biridir', '00546………mehabet haktı. Adı üstünde mehabet.. Fakat burada bile sindirilmiş özlemler istekler var.. Karşısındakinin ne şartlarda çalışmakta o...', ARRAY['Türk Edebiyatı','Şiir','Ayten Özlem Yeşilçalı']::text[], 8.5, '{"poet":"Ayten Özlem Yeşilçalı","poet_slug":"ayten-ozlem-yesilcali","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/bozuk-piskoloji-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mehtapsız Gecede Aşkı Çağırma', 'mehtapsiz-gecede-aski-cagirma-umut-gungor-v8pf1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ağaç kökü derinlerde kök tutar,

Mehtapsız gecede aşkı çağırma,

Samanyolu mehtap ile saf tutar,

Sinirlenip yıldızlara bağırma.

Ağlarım diyerek veda etmedim,

Uzakta sanma senden gitmedim,

Dalgalar savurdu yine yitmedim,

Mehtapsız gecede aşkı çağırma.', 'Ağaç kökü derinlerde kök tutar, Mehtapsız gecede aşkı çağırma, Samanyolu mehtap ile saf tutar, Sinirlenip yıldızlara bağırma. Ağlarım diyere...', ARRAY['Türk Edebiyatı','Şiir','Ümüt Güngör']::text[], 8.5, '{"poet":"Ümüt Güngör","poet_slug":"umut-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/mehtapsiz-gecede-aski-cagirma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diyamın', 'diyamin-ayten-ozlem-yesilcali-cuyep', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Siverek’in kelok mehlesinde bizi büyütün.

Örf adetlerimizi bize  çok güzel öğretin.

Siverek analarının acı çeken cefa görenlerindendin.

Sen benim yüreğimin derinliklerinde siverek’i

İstanbul dada yaşatın DİYAMIN…

Daykamın.gözelamın.

Aba derdi herkes sana bizde dahil. 

Siverek’te acın eziyetin bitmedi.

Bizleri daha iyi yaşatmak için geldik istanbula.

Ama hep içinde yaşadı Siverek.

Senle az geceler anlatmadık Siverek küçelerini; 

Düğünlerimizi,darbukacı kör remoyu.

Bakal apo kündürü

Şeşnanları,az dinlemedik şükrü izol’un ezğilerini.

 Seni şimdi okadar çok arıyorumki anam

Daha çok erkendi aramızdan ayrılman.

Felek bırakmadı sana siverek’i daha güzel yaşatayım.

Gidecegim anam senin için Siverek e

Kalasına çıkacagım.

Koçali baba türbesine senin için dua okuyacagım.

Kelok mehlesini doya doya gezecegim.

Sende beni seyredeceksin.

Heyran anam can anam.', 'Siverek’in kelok mehlesinde bizi büyütün. Örf adetlerimizi bize  çok güzel öğretin. Siverek analarının acı çeken cefa görenlerindendin. Sen ...', ARRAY['Türk Edebiyatı','Şiir','Ayten Özlem Yeşilçalı']::text[], 8.5, '{"poet":"Ayten Özlem Yeşilçalı","poet_slug":"ayten-ozlem-yesilcali","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/diyamin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Vefasız Yüzünden', 'bir-vefasiz-yuzunden-mehmet-ali-sahin-3fvu0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seller gibi akışım

Bataklığa çöküşüm

Böyle boyun büküşüm

Bir vefasız yüzünden

Mecnun gibi oluşum

Sararıp da soluşum

Dermansız da kalışım

Bir vefasız yüzünden

Dertten kurtulmaz başım

Gözümden akar yaşım

Melil mahsun bakışım

Bir vefasız yüzünden

Mehmet Ali ağlarım

Yüreğimi dağlarım

Geçti gençlik çağlarım

Bir vefasız yüzünden', 'Seller gibi akışım Bataklığa çöküşüm Böyle boyun büküşüm Bir vefasız yüzünden Mecnun gibi oluşum Sararıp da soluşum Dermansız da kalışım Bir...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Şahin']::text[], 8.5, '{"poet":"Mehmet Ali Şahin","poet_slug":"mehmet-ali-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-vefasiz-yuzunden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlama Sevdiğim', 'aglama-sevdigim-mehmet-ali-sahin-15ekk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Mektup atıp sitem eyleme bana

