INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Keman Sesi AnımsatırTenini', 'her-keman-sesi-animsatirtenini-ahmet-nural-ozturk-8j2e7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'hangi şarkı dilime düşse

bir köşesinde bulurum seni

nağmelerinde erir gider yalnızlığım

her keman sesi anımsatır tenini

seni unutmak öyle kolay mı ki...', 'hangi şarkı dilime düşse bir köşesinde bulurum seni nağmelerinde erir gider yalnızlığım her keman sesi anımsatır tenini seni unutmak öyle ko...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Nural Öztürk']::text[], 8.5, '{"poet":"Ahmet Nural Öztürk","poet_slug":"ahmet-nural-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/her-keman-sesi-animsatirtenini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geldiler', 'geldiler-fazilet-sayilan-peker-li9oz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bana ilk gelişindi

senle ben baş başa

yalnızdık.

geldiler

duydular,gördüler

ağzımızda acı tatlar

yanan içimize eklenen

sağanak korkusu

senle ben yalnız

değildik

eş, dost,komşu

geldiler

gelecekler 

             korkusu

bırkamadılar bizi

yalnız

geldiler

ses kısılması

el titremesi

yürek çarpıntısı

geldiler hemen.', 'bana ilk gelişindi senle ben baş başa yalnızdık. geldiler duydular,gördüler ağzımızda acı tatlar yanan içimize eklenen sağanak korkusu senle...', ARRAY['Türk Edebiyatı','Şiir','Fazilet Sayılan Peker']::text[], 8.5, '{"poet":"Fazilet Sayılan Peker","poet_slug":"fazilet-sayilan-peker","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/geldiler-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonradan Görme', 'sonradan-gorme-i-brahim-yavuz-oidqe', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni köyden ben ne diye getirdim 

Dillerimden düşmez oldu âhu zar

Gençliğimi yiye yiye bitirdin

Kör olası yaktın beni Gülizar

Gelir gelmez geçmişini taşladın

Yavaş yavaş sigaraya başladın

Komşulara dedikodu aşladın

Kör olası yaktın beni Gülizar

Bağrın açık eteğini kısalttın

Moda değil diye beşlini sattın

Hani söz vermiştin çamura yattın

Kör olası yaktın beni Gülizar

Hanım oldun uzadı mı boyların

Köyde yoktu böyle kötü huyların

Çok gevşedi çenendeki yayların

Kör olası yaktın beni Gülizar

Ötmez oldu erkeklerin borusu

Geldiğime pişman oldum doğrusu

El aleme olduk alay konusu

Kör olası yaktın beni Gülizar

Hem yazlığımız var hem de katımız

Her gün biraz daha kaçtı tadımız

Sonradan görmeye çıktı adımız

Kör olası yaktın beni Gülizar

Biraz kendine gel boyalı kafa

Kötü örnek oluyorsun etrafa

Yemek yapmayı da kaldırdın rafa

Kör olası yaktın beni Gülizar

İpler koptu sosyeteye teslimiz

Hele düşün neydi bizim aslımız

Çocuk istemedin bitti neslimiz

Kör olası yaktın beni Gülizar

Kardeşlerin sana sahip çıkmazlar

Geri dönsek yüzümüze bakmazlar

Bu halinle seni köye sokmazlar

Kör olası yaktın beni Gülizar', 'Seni köyden ben ne diye getirdim  Dillerimden düşmez oldu âhu zar Gençliğimi yiye yiye bitirdin Kör olası yaktın beni Gülizar Gelir gelmez g...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Yavuz']::text[], 8.5, '{"poet":"İbrahim Yavuz","poet_slug":"i-brahim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/sonradan-gorme-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecemin Karanlığı', 'gecemin-karanligi-murtaza-ekici-s2gym', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gülmeyi yok saydım gözlerimde nem

İnanki yaşamam seni yok bilsem

Geceyi göğsünde sabah eylesem

Gün doğar gecemin karanlığına

Gerçeği hayalden ayırabilsem

Gönlümü sevginle doyurabilsem

Zamanı lehime çevirebilsem

Gün doğar gecemin karanlığına

Böyle dert mi olur hep sıra sıra

Harcadım ömrümü bitiyor süre

Seninle bir günüm dönse asıra

Gün doğar gecemin karanlığına

Murtaza bu işin sırrına erdi

Seninle birlikte olmaktı derdi

Mutluluk seninle olunan yerdi

Gün doğar gecemin karanlığına', 'Gülmeyi yok saydım gözlerimde nem İnanki yaşamam seni yok bilsem Geceyi göğsünde sabah eylesem Gün doğar gecemin karanlığına Gerçeği hayalde...', ARRAY['Türk Edebiyatı','Şiir','Murtaza Ekici']::text[], 8.5, '{"poet":"Murtaza Ekici","poet_slug":"murtaza-ekici","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gecemin-karanligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatıran Olsun', 'hatiran-olsun-mete-yildiz-paiub', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'HATIRAN OLSUN

Anladım benimle olamaz cismin,

Daima dilimde olacak ismin,

Fazla şey istemem boydan bir resim,

Madem gidiyorsun hatıran olsun.

Canımdan gayrısın ne istersen al,

Sağ mısın bileyim bari haber sal,

Gülüver aklımda tebessümle kal,

Madem gidiyorsun hatıran olsun.

Hayalimde bari misafirim ol,

İstersen gelirsin bulursun bir yol,

Mutluluktan uçar, gülerim bol bol,

Madem gidiyorsun hatıran olsun.

Aklımdan çıkmıyor yanakta beni,

İsmine bir şiir yazmıştım yeni,

Hiç değilse bari masum buseni,

Madem gidiyorsun hatıran olsun.

Senden başkasına dokunmaz bu el,

Asma suratını karşı çıkma gel,

Ne olur sevgilim saçından bir tel,

Madem gidiyorsun hatıran olsun.

Seninle geçerken gecem, gündüzüm,

Varsında kalmasın gözümde gözün,

Giderken ardında bir tatlı sözün,

Madem gidiyorsun hatıran olsun.

Soldu gül yağmur yok havalar kurak,

Ayrıldık seninle aramız ırak,

Seni hatırlatan bir şeyler bırak,

Madem gidiyorsun hatıran olsun.

Beklerim cevap yok benim çağrıma,

Doktor bulamadı ilaç ağrıma,

Ümit yok hançeri sapla bağrıma,

Madem gidiyorsun hatıran olsun.

Peşinde Mecnunum, Kerem, Yunusum,

Burası son durak noktayı kosun,

Yalnızlık Allahın beni de yosun,

Sararsa sarsın gör bayramın olsun.

		Mete YILDIZ', 'HATIRAN OLSUN Anladım benimle olamaz cismin, Daima dilimde olacak ismin, Fazla şey istemem boydan bir resim, Madem gidiyorsun hatıran olsun....', ARRAY['Türk Edebiyatı','Şiir','Mete Yıldız']::text[], 8.5, '{"poet":"Mete Yıldız","poet_slug":"mete-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/hatiran-olsun-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nevruz', 'nevruz-murtaza-ekici-7f6re', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dostluk duygusudur temelde yatan

Bu değil mi bizi ayakta tutan? 

Kini ve nefreti bir yana atan

Kardeşin kardeşi sözüdür nevruz.

Doğanın yeniden dirilmesidir

Yeşilin toprağa serilmesidir

Bağların bir daha örülmesidir

Türklüğün baharı, yazıdır nevruz.

Gelecek nesile tohum ekilir

Burçlara yeniden bayrak dikilir

Horonlar tepilir, halay çekilir

İnsanların, gülen yüzüdür nevruz.

Kuşlar vatanına göç etmektedir

Mânâlar, maddeyi hiç etmektedir

Sevdayı başlara taç etmektedir

Odunun ateşe, közüdür nevruz.

Nevruz birliktelik, nevruz barıştır

İnsanlığı kucaklayıp sarıştır

Hasretleri yok edecek yarıştır

Sevginin sembolü, özüdür nevruz.', 'Dostluk duygusudur temelde yatan Bu değil mi bizi ayakta tutan?  Kini ve nefreti bir yana atan Kardeşin kardeşi sözüdür nevruz. Doğanın yeni...', ARRAY['Türk Edebiyatı','Şiir','Murtaza Ekici']::text[], 8.5, '{"poet":"Murtaza Ekici","poet_slug":"murtaza-ekici","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/nevruz-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrıcalık', 'ayricalik-mete-yildiz-76e61', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'AYRICALIK

Seni yaratırken hak adaleti şaşırmış,

Gözlerine, kaşına inci gibi dişine,

Peri mi melek misin güzelliği taşırmış,

Bayıldım gülüşüne, kurbanım gelişine.

Başkalarından kırpmış inan sana eklemiş,

İtiraz hakkı mı var sırasını beklemiş,

Terazi bir tarafa ağır basmış belli ki,

Görüyorsun adalet hep seni desteklemiş.

Bizden yana olunca karşı çıkmayız elbet,

Ayrıcalık besbelli boy pos bu ne asalet,

Geçmişim bir tarafa ölürsem de gam yemem,

Hayatımda bu sefer bizden yana adalet.

Bana bakan gözlerin penceremin sırçası,

Kirpiklerin ok gibi kaşların ay parçası,

Ah ne yapsam neylesem karşı koyamıyorum,

Sana hayır demek ya halt etmenin Farsçası.

Böyle güzel var mıdır gezmişler yıldızları,

Ant içmiş kafa tutmuş kalp çelen hırsızları,

Anlamışlar dengini âlemde görmeyince,

Düşman olmuşlar sana kâinatın kızları.

Tanrı mı şaşırmıştır yoksa böyle mi gerek,

Çıkıverdin karşıma bak sevdim bilmeyerek,

Dünyada tek dileğin nedir diye sorsalar,

Tereddütsüz adını söylerim senin direk.

Ne derlerse desinler bırakamam peşini,

Seni bana yazmış hak bulmuşum ben eşimi,

Dünyanın en şanslısı elbette ki benmişim,

Bir kez daha anladım tanrı bilir işini', 'AYRICALIK Seni yaratırken hak adaleti şaşırmış, Gözlerine, kaşına inci gibi dişine, Peri mi melek misin güzelliği taşırmış, Bayıldım gülüşün...', ARRAY['Türk Edebiyatı','Şiir','Mete Yıldız']::text[], 8.5, '{"poet":"Mete Yıldız","poet_slug":"mete-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/ayricalik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırdımsa Affet', 'kirdimsa-affet-murtaza-ekici-creyt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yaşlar hiç akmasın ahu gözünden

Çiçekler yer bulsun gülen gözünden

Haddini bilmeyen dilim yüzünden 

Mızrab ile sazın telini kırdım.

Sürç-i lisan ettik hatamız büyük

Affolunmaz ise kalkmaz ki bu yük

Her yer kırık dökük, her taraf oyuk

Gül bahçesindeki gülümü kırdım.

Affetmek büyüklük yüce sözünü

Yerine getir de yakma özümü

Eller ne bilir ki benim sızımı

Ben kendi elimle elimi kırdım.

Aslıhan isminin asaletine

Hoşgör insanları kul niyetine

Kapılıp ortamın rehavetine

Tutundum dediğim dalımı kırdım.', 'Yaşlar hiç akmasın ahu gözünden Çiçekler yer bulsun gülen gözünden Haddini bilmeyen dilim yüzünden  Mızrab ile sazın telini kırdım. Sürç-i l...', ARRAY['Türk Edebiyatı','Şiir','Murtaza Ekici']::text[], 8.5, '{"poet":"Murtaza Ekici","poet_slug":"murtaza-ekici","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kirdimsa-affet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Kelimede Sır Var', 'her-kelimede-sir-var-yusuf-onder-bahceci-js646', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şiirdir işte neticede, her kelimede sırlar var nice,

Biz, gönülden okur, gönülden yazarız, işte netice,

Her şey ayan, beyan olur cân ve hesabın verince,

Şiirdir işte neticede, her kelimede sırlar var nice...', 'Şiirdir işte neticede, her kelimede sırlar var nice, Biz, gönülden okur, gönülden yazarız, işte netice, Her şey ayan, beyan olur cân ve hesa...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/her-kelimede-sir-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarım Kalan Şiir', 'yarim-kalan-siir-fazilet-sayilan-peker-hp6fb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'hep aklımda bir şiir 

başı var,sonu yok

bir kuşluk vakti

uyandırdım seni

istemeden.

Saati kuran ben

değildim,bilmem

kaçıncı kez zamansız 

çaldı acı acı

bir siren sesiydi

aldı götürdü seni

onulmaz uzaklara

ne zaman akar

ne akrep döner

                 geriye

gittin! 

bir saniye sarkacı

olup geldin

ardından gelen

                  ihanetin

sonu gelmez

bu şiirin.', 'hep aklımda bir şiir  başı var,sonu yok bir kuşluk vakti uyandırdım seni istemeden. Saati kuran ben değildim,bilmem kaçıncı kez zamansız  ça...', ARRAY['Türk Edebiyatı','Şiir','Fazilet Sayılan Peker']::text[], 8.5, '{"poet":"Fazilet Sayılan Peker","poet_slug":"fazilet-sayilan-peker","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yarim-kalan-siir-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelecek', 'gelecek-murtaza-ekici-64b87', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Uzaklık adının kalmaz eseri

Gün gelir tükenir gözünün feri

Aşk için dökmezsen alnından teri

Sanma giden günler geri gelecek

Yenik düşme sahte dostun fendine

Kabarınca sular sığmaz bendine

Bir fırsat tanısan kendi kendine

Sana senden öte biri gelecek

Vakit hasıl olup gitsen sürgüne

Sevgiden yük etmemişsen terkine

Kim bilir, belki de geçen hergüne

Bakıp ağlamanın yeri gelecek', 'Uzaklık adının kalmaz eseri Gün gelir tükenir gözünün feri Aşk için dökmezsen alnından teri Sanma giden günler geri gelecek Yenik düşme saht...', ARRAY['Türk Edebiyatı','Şiir','Murtaza Ekici']::text[], 8.5, '{"poet":"Murtaza Ekici","poet_slug":"murtaza-ekici","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gelecek-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendini Zorla mı Sevdireceksin', 'kendini-zorla-mi-sevdireceksin-yusuf-onder-bahceci-829rl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne yani, seni sevmeyene kendini mi sevdireceksin,

Senin onurun var kardeşim kendinimi ezdireceksin,

Böyle fazla şiir yazma belkide Milleti bezdireceksin,

Ne yani, seni sevmeyene kendini mi sevdireceksin...', 'Ne yani, seni sevmeyene kendini mi sevdireceksin, Senin onurun var kardeşim kendinimi ezdireceksin, Böyle fazla şiir yazma belkide Milleti b...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kendini-zorla-mi-sevdireceksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelir', 'gelir-murtaza-ekici-aipq8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şair yaşadıkça yazarmış meğer

Güneş güzellere, ay bana doğar

Duygular depreşir ruhumu boğar

Bugünden dünüme dönesim gelir

Hasretin yakarken susuzluk hiçmiş

Su diye aşkını yıllarca içmiş

Benim denen gençlik elimden uçmuş

Daha yaşayamam ölesim gelir

Yapraklar döküldü hasret yelinden

Ne gelirse gelsin senin elinden

Sevdiğini duysam bir kez dilinden

Bu canı ikiye bölesim gelir', 'Şair yaşadıkça yazarmış meğer Güneş güzellere, ay bana doğar Duygular depreşir ruhumu boğar Bugünden dünüme dönesim gelir Hasretin yakarken ...', ARRAY['Türk Edebiyatı','Şiir','Murtaza Ekici']::text[], 8.5, '{"poet":"Murtaza Ekici","poet_slug":"murtaza-ekici","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gelir-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çığlar Uçmuş Üstüme', 'ciglar-ucmus-ustume-murtaza-ekici-j8tdp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kalbim sana aşina, dualar senin için

Hayallerim boşlukta, düşlerimin damı yok

Hasreti yumaklayıp yanarken  için için

Bugünü çoktan sildim, yarının anlamı yok.

Elim açıkken semaya, dudaklardan dökülen

Sana ait duayı yok saymanın zamanı

Bunca uğraşa rağmen ilmek ilmek sökülen

Kaybolan duyguları çok saymanın zamanı.

Zemheri kışı değmiş bahçemdeki güllere

Bahardan ümit kesik, yazı görmek imkânsız

Bendeki sensizliği anlatamam ellere

Çığlar uçmuş üstüme sana varmak imkânsız.', 'Kalbim sana aşina, dualar senin için Hayallerim boşlukta, düşlerimin damı yok Hasreti yumaklayıp yanarken  için için Bugünü çoktan sildim, y...', ARRAY['Türk Edebiyatı','Şiir','Murtaza Ekici']::text[], 8.5, '{"poet":"Murtaza Ekici","poet_slug":"murtaza-ekici","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ciglar-ucmus-ustume-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitirdi', 'bitirdi-murtaza-ekici-a8mlc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dağ başında karım erimedi hiç

Nereye baktıysam, ne yaptıysam suç

Hep dünde yaşadım, yaşım bilmem kaç! 

Gözlerin kalbimde buzu bitirdi.

Sevda pınarıydım suyum içtiler

Kalbimi yol yaptım gelip geçtiler

En sonunda unutmayı seçtiler

Baharı beklerken yazı bitirdi.

Rüzgârın dalıma ne zaman değdi? 

Açmamış tomurcuk boynunu eğdi

Duygular beynime gerilen ağdı

Çokları görmeden azı bitirdi.

Hırslar galip geldi, duyguyu ezdi

Sevgi sindi, mânâsızlık kol gezdi

Şekiller değişti, her şeyi bozdu

Kabuktan vazgeçtik özü bitirdi.

Bir anlam kalmadı senli günlerde

Birliktelik mâzi oldu dünlerde

Herkes başka yerde, ayrı yönlerde

Ben diyen benlikler bizi bitirdi.', 'Dağ başında karım erimedi hiç Nereye baktıysam, ne yaptıysam suç Hep dünde yaşadım, yaşım bilmem kaç!  Gözlerin kalbimde buzu bitirdi. Sevda...', ARRAY['Türk Edebiyatı','Şiir','Murtaza Ekici']::text[], 8.5, '{"poet":"Murtaza Ekici","poet_slug":"murtaza-ekici","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bitirdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zor Tarif', 'zor-tarif-murtaza-ekici-8cd91', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bugünde yaşarken dünü bilmezsin

Mevsimler değişir günü bilmezsin

Bırak el-âlemi seni bilmezsin

Zamansız sevgiyi tarif etmek zor

Yaşamı o varken var olur bilen

Bir matkap misali kalbimi delen

Gece uykusunu ikiye bölen

Amansız sevgiyi tarif etmek zor

Günler bir tarafa saat yıl olur

Bunca bekleyişler biter kül olur

Tütecek sanırsın o alev alır

Dumansız sevgiyi tarif etmek zor', 'Bugünde yaşarken dünü bilmezsin Mevsimler değişir günü bilmezsin Bırak el-âlemi seni bilmezsin Zamansız sevgiyi tarif etmek zor Yaşamı o var...', ARRAY['Türk Edebiyatı','Şiir','Murtaza Ekici']::text[], 8.5, '{"poet":"Murtaza Ekici","poet_slug":"murtaza-ekici","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/zor-tarif-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasıl Anlamadın', 'nasil-anlamadin-yusuf-onder-bahceci-lz5su', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ey sevdiğim, seni, seni seviyorum diyemedim sana,

Ama sen, seni seven gözlerimden de mi anlamadın,

Ey sevdiğim senin için cân veririm diyemedim sana,

Ama sen, sen benim sözlerim den de mi anlamadın...', 'Ey sevdiğim, seni, seni seviyorum diyemedim sana, Ama sen, seni seven gözlerimden de mi anlamadın, Ey sevdiğim senin için cân veririm diyeme...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/nasil-anlamadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıbrısa Özlem', 'kibrisa-ozlem-murtaza-ekici-uo4gm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hâtıralar bir bir gelseler dile

Dostuna bir haber salması güzel

Bedenler burada olsalar bile

Gönüllerin sizde kalması güzel

Gemikonağı’na, Güzelyurt’una

Derman olabilsem senin derdine

Özlem duyar gönlüm herbir ferdine

Sevgilerin daim olması güzel

Girne’nin denizi kollayışına

Ananın yavruyu okşayışına

Yandım senin bende olmayışına

Senden yana nefes alması güzel

Akdeniz’de süzülerek bakışın

Derinden çağlayıp coşkun akışın

Bir sevda uğruna beni yakışın

Seninle hülyaya dalması güzel

Yüreğim bir bülbül, sense bir gülşen

Bendeki yerini bir bilebilsen

Murtaza’m seninle bir ruh, bir beden

Benliğini sende bulması güzel', 'Hâtıralar bir bir gelseler dile Dostuna bir haber salması güzel Bedenler burada olsalar bile Gönüllerin sizde kalması güzel Gemikonağı’na, G...', ARRAY['Türk Edebiyatı','Şiir','Murtaza Ekici']::text[], 8.5, '{"poet":"Murtaza Ekici","poet_slug":"murtaza-ekici","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kibrisa-ozlem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haberin Olsun', 'haberin-olsun-murtaza-ekici-pu5f7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni düşünerek ağardı saçım

Cezasını sen ver sevmekse suçum

Anlasana artık ben sensiz hiçim

Sevda boyun büktü haberin olsun

Her şey anlamsızdır göz perdesinde

Sensiz yaşanılan gün ertesinde

Bilesin kış değil yaz ortasında

Ağaç dalın döktü haberin olsun

Şimdi dargın olmuş kanat kök ile

Yaşar mı sanırsın açlar tok ile

Doğrulmak imkânsız bunca yük ile

Dizler yere çöktü haberin olsun.', 'Seni düşünerek ağardı saçım Cezasını sen ver sevmekse suçum Anlasana artık ben sensiz hiçim Sevda boyun büktü haberin olsun Her şey anlamsız...', ARRAY['Türk Edebiyatı','Şiir','Murtaza Ekici']::text[], 8.5, '{"poet":"Murtaza Ekici","poet_slug":"murtaza-ekici","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/haberin-olsun-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DiLâRâ', 'dil-r-oguz-duzgun-crys6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yangınlar sönüyor gözlerinde yâr! 

Endişe bağımın dikenli gülü

Peşinden koşuyor cümle dost, ağyâr

Dilârâ ömrümün ateş sürgünü! 

Peşinden koşuyor cümle dost ağyâr

Merdiven tükenir yolunda yanar

Yürekler kıyamda aşk ihtilâlde

Seni tadan ruhlar sonsuza kanar

Nedir cemalinde bu feryat perde? 

Seni tadan ruhlar sonsuza kanar

Gönüller yangında ruhlar alevde

Titrek bakışların dondurur beni

Dilârâ insanlık aşka grevde

Kini söndürmeye gönder bûseni

Dilârâ insanlık aşka grevde

Karanfiller üzgün, kardelen deli

Papatyalar, nergisler sanki firarda

Yırtıyor umudu yokluğun eli

Şimdi kuş uçmuyor İrem bağlarda

Yırtıyor umudu yokluğun eli

Zülfüne dolanmış asırlar cânım

Bir çöz saçlarını salınsın evren

Her mevsim akıyor senin’çin kanım

Dilârâ dersini Leylâ’dan öğren

Her mevsim akıyor senin’çin kanım

Pâyimâl hayaller kusuyor seni

Âşıklar perişan, sazlar perişan

Sattın üç kuruşa gül endam teni

Leylâm’a Aslıma kimmiş karışan? 

Sattın üç kuruşa gül endam teni

Göz yaşların sinmiş gece bağrına

Duymuyor hiç kimse sessiz şarkını,

Dilârâ girmişsin lal diyarına

Karanlık bilmez ki senin farkını

Dilârâ girmişsin lal diyarına

Televizyon ağlıyor, dergiler yasta

Çeşmine şeytanlar zehir katıyor

Sunulmuş günahlar altından kapta

Gidiyor Dilârâ ömür gidiyor

Sunulmuş günahlar altından kapta', 'Yangınlar sönüyor gözlerinde yâr!  Endişe bağımın dikenli gülü Peşinden koşuyor cümle dost, ağyâr Dilârâ ömrümün ateş sürgünü!  Peşinden koş...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Düzgün']::text[], 8.5, '{"poet":"Oğuz Düzgün","poet_slug":"oguz-duzgun","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/dilara-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasıl İhanet Ettin', 'nasil-i-hanet-ettin-yusuf-onder-bahceci-9xyps', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir zamanlar sevdiğimdin sana nasıl güvendim,

Seni sevdiğimi, gözlerimden bilirsin, zannettim,

Seni sevdiğimi, biliyordun be, nasıl ihanet ettin,

Bir zamanlar sevdiğimdin sana nasıl güvendim.', 'Bir zamanlar sevdiğimdin sana nasıl güvendim, Seni sevdiğimi, gözlerimden bilirsin, zannettim, Seni sevdiğimi, biliyordun be, nasıl ihanet e...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/nasil-ihanet-ettin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Susturma Beni', 'susturma-beni-murtaza-ekici-ifw7r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Asalet askıda, kişilik kayıp

Herşey mübah oldu kalmadı ayıp

Küfürlü hitabı güzellik sayıp

Gülenler yanında susturma beni

Dibekler atılmış, değirmen yelsiz

Diken hüküm sürer bahçeler gülsüz

Namus konusunda sağır ve dilsiz

Olanlar yanında susturma beni

Olmazlar uğruna hayaller kurup

İyiye, doğruya kılıç savurup

Haksızlık nezdinde saflara durup

Gelenler yanında susturma beni

Bastırdım duygumu hiçi hiçine

Yaradandan deyip attım içime

Yaşamak uğruna başka biçime

Girenler yanında susturma beni

Dert ona çok uzak, bilmez cefayı

Hep maddeden yana yormuş kafayı

Yetimin hakkıyla zevki sefayı

Sürenler yanında susturma beni

Murtaza’yım çok şey azmış temelden

Hergün bir şeyleri sildik emelden

Sıra gelip sorulurken amelden

Soranlar yanında susturma beni', 'Asalet askıda, kişilik kayıp Herşey mübah oldu kalmadı ayıp Küfürlü hitabı güzellik sayıp Gülenler yanında susturma beni Dibekler atılmış, d...', ARRAY['Türk Edebiyatı','Şiir','Murtaza Ekici']::text[], 8.5, '{"poet":"Murtaza Ekici","poet_slug":"murtaza-ekici","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/susturma-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çim Adam', 'cim-adam-tulay-sustam-n67qo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'teni

toprak kokuyordu

dizlerimden sıyırdım

ince çorabımı

gömdüm gövdemi

kum tanelerinin arasına

gözyaşım düştü

cansız saçlarına

bana doğru açtı gözlerini

baharın resmini çizgi gözbebeklerime

uzandım çimenlerin üzerine

beni bu halimle

bostan korkuluğu sanmayın', 'teni toprak kokuyordu dizlerimden sıyırdım ince çorabımı gömdüm gövdemi kum tanelerinin arasına gözyaşım düştü cansız saçlarına bana doğru a...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/cim-adam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ahu Gözlüye', 'ahu-gozluye-murtaza-ekici-42r7r', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni her görüşte yaram kanardı

Buz keserdi dilim, sözüm donardı

Gönlümde kor bitmez ateş yanardı

Yanan bu ateşi söndüremedim

Gözleri ahuydu, kaşlarıysa yay

Sensiz geçen günü yaşamadım say

Seni kaybedersem vay hâlime vay

Kalpleri üst üste bindiremedim

Ağaç su almazsa gölge vermezmiş

Göz onu görürmüş başka görmezmiş

Sevgi yükün dağıtırmış dermezmiş

Gönül perdesini indiremedim

Hep olumsuz yönde dönüyor çarkım

Susuz değirmenden kalmadı farkım

Yaşamadan yana değil ki korkum

Seni yok saymayı sindiremedim

Sevabı hiç saydı, günahı tarttı

Sevgiler azaldı, acılar arttı

Sensizlik gönlümün zarını yırttı

Kanayan yarayı dindiremedim', 'Seni her görüşte yaram kanardı Buz keserdi dilim, sözüm donardı Gönlümde kor bitmez ateş yanardı Yanan bu ateşi söndüremedim Gözleri ahuydu,...', ARRAY['Türk Edebiyatı','Şiir','Murtaza Ekici']::text[], 8.5, '{"poet":"Murtaza Ekici","poet_slug":"murtaza-ekici","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ahu-gozluye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Garip Yusufçuk', 'bir-garip-yusufcuk-murtaza-ekici-jimkw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevgisi yalandır sitem edenin.

Dönüşü yok bırakıp da gidenin.

Deprem gibi sarsılırsa bedenin,

Hiçbir şey yerinde kalmaz Yusufçuk.

Kurallar katıdır, çizgiler ince.

Günler aya döner sana gelince.

Çeşmeler akarken kendi halince,

Senin testin niye dolmaz Yusufçuk.

Sevgiler anlamsız gelmeden dile.

Bülbüller misali yanmadan güle.

Dün geçmişte kaldı yarında bile,

Hayallerin gerçek olmaz Yusufçuk.

Gün geçtikçe değişirken benliğin.

Ne endamın kalır ne güzelliğin.

Seni tarif eden her özelliğin,

Dost denilen dostlar bilmez Yusufçuk.

Yusuf vatanında garip dururken.

Ömrü insanlığı serip dururken.

Dost için gülşeni derip dururken,

Kendi bir gül bile almaz Yusufçuk', 'Sevgisi yalandır sitem edenin. Dönüşü yok bırakıp da gidenin. Deprem gibi sarsılırsa bedenin, Hiçbir şey yerinde kalmaz Yusufçuk. Kurallar k...', ARRAY['Türk Edebiyatı','Şiir','Murtaza Ekici']::text[], 8.5, '{"poet":"Murtaza Ekici","poet_slug":"murtaza-ekici","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bir-garip-yusufcuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceleri Uyur Sanma', 'geceleri-uyur-sanma-yusuf-onder-bahceci-7gb64', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şimdi senden ayrıyım, yıkık gönül sarayım,

Geceleri uyur sanma her gece yalvarayım,

İki Cihan Serveri, ben sana kurban olayım,

Şimdi senden ayrıyım, yıkık gönül sarayım...', 'Şimdi senden ayrıyım, yıkık gönül sarayım, Geceleri uyur sanma her gece yalvarayım, İki Cihan Serveri, ben sana kurban olayım, Şimdi senden ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/geceleri-uyur-sanma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Memleketime', 'memleketime-murtaza-ekici-7tl74', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Cennetten bir köşe Göksün ovası.

Buram buram sevgi kokan havası.

Tarihe dayanır mertlik davası,

Memleketim Maraş, köy Yeniyapan.

Hasret kaldım bahçendeki güllere.

Muhabbeti önde tutan dillere.

Yok sayıp da atma yaban ellere.

Beni de kendinden say yeniyapan.

Tahammül göstermez gayrılıklara.

Katlanamaz oldum ayrılıklara.

Kulağın tıkama haykırıklara,

Beni, sen yerine koy Yeniyapan.

Vakit gelip yüklemeden yükümü.

Rüzgar dalım kırdı söktü kökümü.

Mevsim güze döndü, yaprak dökümü,

Birlikte olunsun soy Yeniyapan.

Murtaza uzaklık el olmak değil.

Gaye ayrı gidip yol almak değil.

Sana kem bakana sevgiyle eğil,

Dünya kime kaldı vay Yeniyapan.', 'Cennetten bir köşe Göksün ovası. Buram buram sevgi kokan havası. Tarihe dayanır mertlik davası, Memleketim Maraş, köy Yeniyapan. Hasret kald...', ARRAY['Türk Edebiyatı','Şiir','Murtaza Ekici']::text[], 8.5, '{"poet":"Murtaza Ekici","poet_slug":"murtaza-ekici","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/memleketime-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aldatmaca...', 'aldatmaca-i-brahim-ethem-bingul-jy4ge', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bakmayın siz havanın neşesiz durduğuna

Belki sitem, belki de rol yapıyor aslında

Bahar geldi, yâr gibi sarıldı o boynuna

Ama hâla bizlere kış taklidi yapmada...

www.iebingül.com', 'Bakmayın siz havanın neşesiz durduğuna Belki sitem, belki de rol yapıyor aslında Bahar geldi, yâr gibi sarıldı o boynuna Ama hâla bizlere kı...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/aldatmaca-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öldüğümü bil', 'oldugumu-bil-bayram-sapci-4fmdg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sana canım deyip sarılamazsam

İsmini dudaklarıma andıramazsam

Yüreğimi aşkınla yandıramazsam

İşte o zaman öldüğümü bil

Gözüm açtığımda seni görmezsem

Sıcak nefesini hissedemezsem

Yanımdayken bile özleyemezsem

İşte ozaman öldüğümü bil

Kollarım kırılıp seni sarmazsa

kulaklarım sağır sesin duymazsa

Yar deyip sevdiğim benim olmazsa

işte o zaman öldüğümü bil

Gece tükenmeyip sabah olmazsa

Yıldızlar solmayıp güneş doğmazsa

Baharım gelipte güller açmazsa 

İşte o zaman öldüğümü bil

Kadehlerde zehir senle içmezsem

Ölümün yolunu senle seçmezsem

Sırat köprüsünden senle geçmezsem

İşte o zaman öldüğümü bil

Gençliğim uğrunda feda etmezsem

Bin güzelin içinden seni seçmezsem

Yalnızlığa senle veda etmezsem

İşte o zaman öldüğümü bil', 'Sana canım deyip sarılamazsam İsmini dudaklarıma andıramazsam Yüreğimi aşkınla yandıramazsam İşte o zaman öldüğümü bil Gözüm açtığımda seni ...', ARRAY['Türk Edebiyatı','Şiir','Bayram Şapcı']::text[], 8.5, '{"poet":"Bayram Şapcı","poet_slug":"bayram-sapci","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/oldugumu-bil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aynalar', 'aynalar-fazilet-sayilan-peker-43x0q', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ikide bir gözüme sokup durmayın

yüzümdeki jilet yırtığını yılların

yanaklarımın iki yanında iki çekül

çeker durur yere doğru

kaldırdıkça dik başımı

suyunu kaybetmiş toprak

tenimde faça derin darbe

çizdim kardiyografimi 

yüzümün coğrafyasında

sildim alnımdaki yazıyı

yeniden yazdım aydınlık

ötekinin kapısını çaldım

eğreti masalarda acı çayım

suskunluğum boğazımda

sıkar kaç düğüm

yeni yetme nereden bilsin

ölümü soluyan çocuğun

sayarken kaburgalarını akbaba

yüreğim afrika

ucuz iş,yoğun emek

topraktan fışkıran zenginlik

amerikaya

nükleer bomba iftira

çıplak ayak,aç beden.

canlandı yeniden

keskin balta kırk kabil

en eski meslek

inleyen kara çarşaf

yüreğim asya.', 'ikide bir gözüme sokup durmayın yüzümdeki jilet yırtığını yılların yanaklarımın iki yanında iki çekül çeker durur yere doğru kaldırdıkça dik...', ARRAY['Türk Edebiyatı','Şiir','Fazilet Sayılan Peker']::text[], 8.5, '{"poet":"Fazilet Sayılan Peker","poet_slug":"fazilet-sayilan-peker","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/aynalar-63-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayrağı Yere Düşürme', 'bayragi-yere-dusurme-murtaza-ekici-064wr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sana uzanan el kırılmaz mı hiç

Başımızdan belâ durulmaz mı hiç

Hainler pusudan yorulmaz mı hiç

Yok sayıp deme ki cahil cühelâ

Olmasın soysuzlar başına belâ

Olmayan beyinden nefret silinmez

Senin demen ile vatan bölünmez

Bayrağıma söz atana gülünmez

Yok sayıp deme ki cahil cühelâ

Olmasın soysuzlar başına belâ

Ne kanın döküldü, ne canın gitti

Yeter yaptıkların canına yetti

İki soysuz bayrağına ne etti

Yok sayıp deme ki cahil cühelâ

Olmasın soysuzlar başına belâ

Helâk et Yâ Rabbi asi soyunu

Can çıksa da değiştirmez huyunu

Tek taraflı oynuyorlar oyunu

Yok sayıp deme ki cahil cühelâ

Olmasın soysuzlar başına belâ

Her fırsatta kaldırıp da başını

Sallama atamın mezar taşını

Silmek geç olmasın gözün yaşını

Yok sayıp deme ki cahil cühelâ

Olmasın soysuzlar başına belâ

Bayrak benim canım, benim kefenim

Onda sarılıyken çürümez tenim

Simge bilir onu ruhum, bedenim

Yok sayıp deme ki cahil cühelâ

Olmasın soysuzlar başına belâ

Söyle Sütçü İmam ne için öldü

Ecdadım bu yurdu ne ile aldı

Aslan yatağına çakallar daldı

Yok sayıp deme ki cahil cühelâ

Olmasın soysuzlar başına belâ

Murtaza kahrından taş kesilmekte

Yağlı urgan boğazında ilmekte

Dünya bizi Türk olarak bilmekte

Yok sayıp deme ki cahil cühelâ

Olmasın soysuzlar başına belâ', 'Sana uzanan el kırılmaz mı hiç Başımızdan belâ durulmaz mı hiç Hainler pusudan yorulmaz mı hiç Yok sayıp deme ki cahil cühelâ Olmasın soysuz...', ARRAY['Türk Edebiyatı','Şiir','Murtaza Ekici']::text[], 8.5, '{"poet":"Murtaza Ekici","poet_slug":"murtaza-ekici","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/bayragi-yere-dusurme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Kendine Gelmezsen', 'sen-kendine-gelmezsen-murtaza-ekici-xfbi4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen bayrağı ne sandın kendin bilmez çapulcu

Ta eskiye dayanır bunların bozuk ucu

Başkasına uşaklık densizliğin sonucu

Sen kendine gelmezsen ben seni getiririm

Kendi kanında boğar soyunu bitiririm

Biz bu kadar şehidi senin için vermedik

Bilesin yıllar yılı hiç esaret görmedik

Bayrak bize kutsaldır paspas diye sermedik

Sen kendine gelmezsen ben seni getiririm

Kendi kanında boğar soyunu bitiririm

İstiklâl Marşı size neyi hatırlatıyor? 

Kim bu kan emiciler, ne alıp ne satıyor? 

Bu bayrağın uğrunda ne güneşler batıyor

Sen kendine gelmezsen ben seni getiririm

Kendi kanında boğar soyunu bitiririm

Nasıl bir yaşayış bu soysuzluk soylu kalır

Eşeğe yular taksan bunlardan insan olur

Bugün olmasa bile yarın ettiğini bulur

Sen kendine gelmezsen ben seni getiririm

Kendi kanında boğar soyunu bitiririm', 'Sen bayrağı ne sandın kendin bilmez çapulcu Ta eskiye dayanır bunların bozuk ucu Başkasına uşaklık densizliğin sonucu Sen kendine gelmezsen ...', ARRAY['Türk Edebiyatı','Şiir','Murtaza Ekici']::text[], 8.5, '{"poet":"Murtaza Ekici","poet_slug":"murtaza-ekici","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sen-kendine-gelmezsen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suların Sesinde Ne Duyarsın', 'sularin-sesinde-ne-duyarsin-yusuf-onder-bahceci-6zhf6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Cânlar cânını bulsan bu cânın feda olsun,

Ballar balını bulsan kovanın yağma olsun,

Uzat gönül testini testi hep ihlasla dolsun,

Cânlar cânını bulsan bu cânın feda olsun.

Durgun akar suların sesinde ne duyarsın,

Sular mecraya akar, bundan, ne anlarsın,

Gezdiğin her yerde, Hâk''kı nasıl yayarsın,

Durgun akar suların sesinde ne duyarsın.', 'Cânlar cânını bulsan bu cânın feda olsun, Ballar balını bulsan kovanın yağma olsun, Uzat gönül testini testi hep ihlasla dolsun, Cânlar cânı...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sularin-sesinde-ne-duyarsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baba', 'baba-murtaza-ekici-sp31i', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kasketi başında baston elinde

Uzaklardan yola düştün mü baba? 

Sevgi yüreğinde adı dilinde

Aşılmaz yolları aştın mı baba? 

İyi bak kendine, emanet cana

Uğramasın sakın kem gözler sana

Yudum yudum değil hep kana kana

Hasret şerbetini içtin mi baba? 

Soğuktan ellerin dondu mu senin? 

Kurumuş yaprağa döndü mü tenin? 

Yaşan görünürken canlı bedenin

Dünyadayken kefen biçtin mi baba? 

Birer birer çıkarttın mı yükünü? 

Derine gizlermiş ağaç kökünü

Sırtına yükleyip sevgi yükünü

Gönül köprüsünden geçtin mi baba? 

Oturup birlikte kurmadık dengi

Yapmak istedikçe bozduk ahengi

Her gülün başkadır kokusu, rengi

Gönüller gülünü seçtin mi baba?', 'Kasketi başında baston elinde Uzaklardan yola düştün mü baba?  Sevgi yüreğinde adı dilinde Aşılmaz yolları aştın mı baba?  İyi bak kendine, ...', ARRAY['Türk Edebiyatı','Şiir','Murtaza Ekici']::text[], 8.5, '{"poet":"Murtaza Ekici","poet_slug":"murtaza-ekici","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/baba-64-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buz Da Yanar', 'buz-da-yanar-fazilet-sayilan-peker-8anmi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'erendiz güneşe dönüyor

ben sana

aramızda kaç ışık yılı

ben sana dönüyorum

sen tüm yıldızlara

buz da yanar suya

                    dönüşmeden

dokunursa güneş

buharı bile görünmeden

buz da yanar

ben sana dönüyorum

kaç bin ışık yılı öteden.', 'erendiz güneşe dönüyor ben sana aramızda kaç ışık yılı ben sana dönüyorum sen tüm yıldızlara buz da yanar suya                     dönüşmede...', ARRAY['Türk Edebiyatı','Şiir','Fazilet Sayılan Peker']::text[], 8.5, '{"poet":"Fazilet Sayılan Peker","poet_slug":"fazilet-sayilan-peker","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/buz-da-yanar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Geleceğim İzmir...', 'sana-gelecegim-i-zmir-emel-cetin-k4ap0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sekize on varken saat, gireceğim sabahına 

Bornova’nın o enfes başından 

Güneş’ten hemen birkaç saat sonra 

Sana geleceğim İzmir… 

Otuz kırk lira, artık ne atabilirsem kenara 

Önce bir bilet alacağım İzmir diye gişeden 

Nicedir ardından baktığım otobüsün 

Bakacağım içinden… 

Sana geleceğim İzmir, 

Mart sonu, Nisan başı artık ne zamansa 

Ne zaman tak ederse canıma özlemin 

Düşeceğim yollarına… 

Geleceğim İzmir, söz 

Denizin gönlüme yazılmış nazar. 

Kapanmaya görsün bana düşmüş bir çift göz 

Düşümde bile kalemim seni yazar… 

Önce Alsancak’tan Kordon’a koşacağım 

Sonra, Şirince şarabını içip coşacağım 

İnciraltı''nda sarhoş balık tutacağım 

Narlıdere’nin dizinde yatacağım… 

Karşıyaka vapurunla geçerken Konağa 

Martılara gevrek, çiğdem satacağım… 

Gece çömelip balkonuna, yine seni yazacağım. 

Otuz kırk lira, artık ne atabilirsem kenara 

Mart sonu, Nisan başı artık ne zamansa 

Ne zaman tak ederse özlemin canıma 

Düşeceğim yollarına… 

Sekize on varken saat, gireceğim sabahına 

Bornova’nın o enfes başından… 

Güneş’ten hemen birkaç saat sonra 

Sana geleceğim İzmir…', 'Sekize on varken saat, gireceğim sabahına  Bornova’nın o enfes başından  Güneş’ten hemen birkaç saat sonra  Sana geleceğim İzmir…  Otuz kırk...', ARRAY['Türk Edebiyatı','Şiir','Emel Çetin']::text[], 8.5, '{"poet":"Emel Çetin","poet_slug":"emel-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/sana-gelecegim-izmir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deremem', 'deremem-murtaza-ekici-yqann', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sarı saçlarını dökme yüzüne

Hüzün dolu gözlerini göremem

Ateşi kor edip atma özüme

Ben sensizken muradıma eremem

Felek her şeyimi benden alsa da

Can sendedir beden toprak olsa da

Her yanım menekşe, gülle dolsa da

Ben sensizken gülleri de deremem

Hep bir özlem ile yanarken içim

Anla artık beni, ben sensiz hiçim

Günahlar silinse, affolsa suçum

Ben sensizken cennete de giremem', 'Sarı saçlarını dökme yüzüne Hüzün dolu gözlerini göremem Ateşi kor edip atma özüme Ben sensizken muradıma eremem Felek her şeyimi benden als...', ARRAY['Türk Edebiyatı','Şiir','Murtaza Ekici']::text[], 8.5, '{"poet":"Murtaza Ekici","poet_slug":"murtaza-ekici","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/deremem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boşuna Taş Atmıyor', 'bosuna-tas-atmiyor-yusuf-onder-bahceci-jm2ua', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Boşuna taş atmıyor, bu çapulcular, para alıyorlar,

Parayı her şey zannedip nasıl, nasıl kullanılıyorlar,

İşleri bitince, birileri tarafından, yabana atılıyorlar,

Boşuna taş atmıyor, bu çapulcular, para alıyorlar.

Adama para versen, taş atma değil göbek atar,

Para için taş atma değil namusunu bilene satar,

Aldığı paralarla belki de birileriyle yer, içer yatar,

Boşuna taş atmıyor, bu çapulcular, para alıyorlar.', 'Boşuna taş atmıyor, bu çapulcular, para alıyorlar, Parayı her şey zannedip nasıl, nasıl kullanılıyorlar, İşleri bitince, birileri tarafından...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bosuna-tas-atmiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Olsan', 'sen-olsan-murtaza-ekici-dvfzh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Rüzgâr olur senden yana eserdim

Ne kızardım ne gücenir, küserdim

Azrail’le selâmı da keserdim

Bir gece kapımı çalan sen olsan

Gül bir kez tebessüm etse bülbüle

Yanıp tutuşarak düşmezdi dile

Bir daha gözümü kırpmazdım bile

Her gece uykumu bölen sen olsan

Kalpler büyülenir haz alır sözden

Bakışlar değişir, sevgiler özden

Uzaklık mefhumu silinir gözden

Ansızın çıkıp da gelen sen olsan', 'Rüzgâr olur senden yana eserdim Ne kızardım ne gücenir, küserdim Azrail’le selâmı da keserdim Bir gece kapımı çalan sen olsan Gül bir kez te...', ARRAY['Türk Edebiyatı','Şiir','Murtaza Ekici']::text[], 8.5, '{"poet":"Murtaza Ekici","poet_slug":"murtaza-ekici","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sen-olsan-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uçuk kaçık düşler', 'ucuk-kacik-dusler-nazan-i-zmirli-vz3n0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'uçuk  düşlerim

pembeye   boyadı

karlarımı.

tüm  kaçıklıklarım

pamuk   şeker 

tadında 

sende  saklı.

......uçuk

...............kaçık

........................düşler

sende ki  ben

bende ki   sende

donmakla   erimek

noktasında   gizli  kaldı.

23.03.2006-uçuk kaçık-', 'uçuk  düşlerim pembeye   boyadı karlarımı. tüm  kaçıklıklarım pamuk   şeker  tadında  sende  saklı. ......uçuk ...............kaçık ...........', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ucuk-kacik-dusler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamansız Göç', 'zamansiz-goc-murtaza-ekici-ya8ym', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ZAMANSIZ GÖÇ

Bir bahar günüydü çekip giderken

Ansızın hayata veda ederken

Feryatlar yükseldi vakit çok erken

Giden hiç duymadı ağlayanları

Göz kapandı sonsuz uykuya daldı

Benim dedikleri dünyada kaldı

Son bir defa daha hüsrana saldı

Varlığına ümit bağlayanları

Birer birer söndü yanan ışıklar

Can dostum saçıma düşürdü aklar

Görmedi gözleri, duymaz kulaklar

Kendi için yürek dağlayanları

Murtaza sakınmaz gözün budaktan

Ne gelirse gelsin razıyım Hak’tan

Rabbim defalarca uyardı çoktan

Yalan ile gönül eyleyenleri

Dünyayı ahrete yeğleyenleri', 'ZAMANSIZ GÖÇ Bir bahar günüydü çekip giderken Ansızın hayata veda ederken Feryatlar yükseldi vakit çok erken Giden hiç duymadı ağlayanları G...', ARRAY['Türk Edebiyatı','Şiir','Murtaza Ekici']::text[], 8.5, '{"poet":"Murtaza Ekici","poet_slug":"murtaza-ekici","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/zamansiz-goc-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Rengi', 'askin-rengi-fazilet-sayilan-peker-o7e83', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'aşkın ömrü üç harf

gökkuşağı üzerinde

gezerken kanatlanır

maviden başlar

pembe de uçar

renkten renge

girer de insan

morarıverir birden

üç harf yedi renk 

sönüverir hemen

ardından gelen

siyah mı beyaz mı

orası sana kalmış.', 'aşkın ömrü üç harf gökkuşağı üzerinde gezerken kanatlanır maviden başlar pembe de uçar renkten renge girer de insan morarıverir birden üç ha...', ARRAY['Türk Edebiyatı','Şiir','Fazilet Sayılan Peker']::text[], 8.5, '{"poet":"Fazilet Sayılan Peker","poet_slug":"fazilet-sayilan-peker","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/askin-rengi-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayatın Yarısı', 'hayatin-yarisi-murtaza-ekici-fkw2i', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'HAYATIN YARISI

Dertler yumak yumak sıkıntı bitmez

Etrafında döner uzağa gitmez

Sana ulaşmağa derman, güç yetmez

Hergün biri doğar, birisi gider

Tatmadan hayatın yarısı gider

Bir yudum suyumsun, bir lokma aşım

Bu deli sevdadan kurtulmaz başım

Kalbimde sevgin var, yürekte hısım

Aslı yok yaylanın sürüsü gider

Tatmadan hayatın yarısı gider

Güz mevsimi geldi bozduk bağları

Beynimize gerdik bütün ağları

Nice sırla dolu sıra dağları

Azıcık tırmansan gerisi gider

Tatmadan hayatın yarısı gider

Hep seni yâd ettim iyi dilekle

Hiç barışık olamadım felekle

Sevdaları elesem de elekle

Ufağı kalır da irisi gider

Tatmadan hayatın yarısı gider', 'HAYATIN YARISI Dertler yumak yumak sıkıntı bitmez Etrafında döner uzağa gitmez Sana ulaşmağa derman, güç yetmez Hergün biri doğar, birisi gi...', ARRAY['Türk Edebiyatı','Şiir','Murtaza Ekici']::text[], 8.5, '{"poet":"Murtaza Ekici","poet_slug":"murtaza-ekici","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/hayatin-yarisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adam Gibi', 'adam-gibi-murtaza-ekici-lzmjt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Uğruna ölmeyi hiç sayar bu can

İçim kan ağlıyor, sen gülüyor san

Kokunu içime çektiğim zaman

Sana adam gibi bir gelebilsem

Hanem hep borç dolu, yok alacağım

Sen yok dersen ben de yok olacağım

Sen benim bu günüm ve geleceğim

Seni adam gibi bir sevebilsem

Her şeyim ortada tıpkı gün gibi

Seni tanıdığım sanki dün gibi

Senin olduğunu sandığın gibi

Adam gibi adam bir olabilsem

Ekici hayata olsaydın tâbi

Sevgi riyakârdır, yaşamak harbi

Yalnız senin için atan bu kalbi

Sana adam gibi bir verebilsem', 'Uğruna ölmeyi hiç sayar bu can İçim kan ağlıyor, sen gülüyor san Kokunu içime çektiğim zaman Sana adam gibi bir gelebilsem Hanem hep borç do...', ARRAY['Türk Edebiyatı','Şiir','Murtaza Ekici']::text[], 8.5, '{"poet":"Murtaza Ekici","poet_slug":"murtaza-ekici","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/adam-gibi-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzün Üstüne', 'huzun-ustune-murtaza-ekici-65pf1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sensiz her yer viran köşk olsa neyler

Kalp seni düşünür, dil seni söyler

Sensiz yaşamaya ölmeyi yeğler

Düşersem kalkamam yüzüm üstüne

Yok olur sevgiler duygu kalmazsa

Saz kendince çalmaz mızrap olmazsa

Senden yana beklediğin almazsa

Birikir duygular hüzün üstüne

Bir çözseydim seni benden edeni

Varlığını benden alıp gideni

Taşıyamaz olur ayak bedeni

Bilesin çökerim dizim üstüne

Murtaza’yım hepten senin olmasam

Senin varlığını bende  bilmesem

Her şeyi bırakıp sana gelmesem

İnanki dönerim sözüm üstüne', 'Sensiz her yer viran köşk olsa neyler Kalp seni düşünür, dil seni söyler Sensiz yaşamaya ölmeyi yeğler Düşersem kalkamam yüzüm üstüne Yok ol...', ARRAY['Türk Edebiyatı','Şiir','Murtaza Ekici']::text[], 8.5, '{"poet":"Murtaza Ekici","poet_slug":"murtaza-ekici","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/huzun-ustune-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hapis Duygular', 'hapis-duygular-murtaza-ekici-2p3m9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir cami avlusuna

Bıraksam bedenimi.

Geçmiş yıllara inat

Var olan kimliğimi.

Tel örgülerle çevrili gelincik tarlasında,

Özgürce kanat çırpan kelebekler misâli.

Ben seni kucaklasam tutunsam dallarından,

Yasemen kokusundan,

Buram buram koklasam.

Hapis duygularımı,

Bilmem nerede saklasam

Her saatin seni gösterdiği bir günde,

Zamanın en kuytu yerinde,

Her şeyi arkanda bırakıp,

Geldiğin ben olacaksam,

Sakın geç kalma e mi? 

Dağlar üstüme geliyor,

Korkuyorum rüyâlardan.

Her gün bir hücrem ölüyor,

Yasaklı aşk mahpusunda.

Ak düşmüş saçlarımın hatırına binaen

Üstüme yorgan yapsam yıllanmış duyguları

Seni alıp koynuma,

Gece sessizliğinde meleklerle ağlaşsam

Sessiz çığlıklarımı rüzgârlarla paylaşsam

Bir cami avlusuna

Bıraksam bedenimi

Öksüz bırakmaktan korkarım

Senin bendeki sevgini.', 'Bir cami avlusuna Bıraksam bedenimi. Geçmiş yıllara inat Var olan kimliğimi. Tel örgülerle çevrili gelincik tarlasında, Özgürce kanat çırpan...', ARRAY['Türk Edebiyatı','Şiir','Murtaza Ekici']::text[], 8.5, '{"poet":"Murtaza Ekici","poet_slug":"murtaza-ekici","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/hapis-duygular-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İmkansız', 'i-mkansiz-fazilet-sayilan-peker-q4fs5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bal rengi irislerinde

çırpınırken yüreğim

batar cam kırıkları

dikenli sözler kelepçe

geçit vermez ellerime

ahraz dilim dönmez

yengeçler teğet geçer

akrepler sinsice

ne nisan yağmuru

ne kelebek uçuşu

kanadı kırık kırlangıç

''hastalıklı duygu''

tütün bassam yarama

geçer mi?', 'bal rengi irislerinde çırpınırken yüreğim batar cam kırıkları dikenli sözler kelepçe geçit vermez ellerime ahraz dilim dönmez yengeçler teğe...', ARRAY['Türk Edebiyatı','Şiir','Fazilet Sayılan Peker']::text[], 8.5, '{"poet":"Fazilet Sayılan Peker","poet_slug":"fazilet-sayilan-peker","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/imkansiz-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bedrin Arslanları', 'bedrin-arslanlari-yusuf-onder-bahceci-nhahz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Allah korusun bir Ulus böyle yok olacakken,

Ne diyordu Vatan Şairi ahmak iyi dinle bak,

Bedrin Arslanları ancak bu kadar şanlı idi,

Evet, Bedrin Arslanları ancak bu kadar şanlı idi,

Ey fitne, fesat, sen ne biçim insansın, durmazsın rahat,

Sana şimdi bir ceza, git evinde, rahat, rahat yat,

Evet, Bedrin Arslanları ancak bu kadar şanlı idi,

Onlar da bunlar dı, bunlar da onlar dı,

Kurtuluş Savaşında Bedrin Arslanları vardı....', 'Allah korusun bir Ulus böyle yok olacakken, Ne diyordu Vatan Şairi ahmak iyi dinle bak, Bedrin Arslanları ancak bu kadar şanlı idi, Evet, Be...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bedrin-arslanlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Canım', 'o-canim-tahmine-yildirim-rs573', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Canım herşeyim

gözümün ışığı

sevgiminde canı

o canım herşeyim

Hayatımın aydınlığı

gözümün feri

gönlümün en güzel yeri

o canım bitanem

Sesini bile duymak

yetiyor içime

can veriyor kanıma

canım fedadır ona

o canım güzelim......

                                                       10.05.1995', 'Canım herşeyim gözümün ışığı sevgiminde canı o canım herşeyim Hayatımın aydınlığı gözümün feri gönlümün en güzel yeri o canım bitanem Sesini...', ARRAY['Türk Edebiyatı','Şiir','Tahmine Yıldırım']::text[], 8.5, '{"poet":"Tahmine Yıldırım","poet_slug":"tahmine-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/o-canim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün git', 'bugun-git-osman-fatih-qnmqp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hala zamanın varken git

sana daha fazla bağlanmadan 

Sabah olmadan

Akşam boğmadan yalnızlığımı,Git! 

Ellerimi bırakacağın gün bugün git! 

Giderken ardına bakmayacağım

Adını bir ömür anmayacağım

Söylediğin son sözü unutup,

Son mısranı yazacağım gün bugün,git! 

Bekleyenin varken git,

Nefesin varken git,

Hevesin varken git,

Gidip de dönmeyeceğin gün bugün git! 

Bu kez dur yok,gitme yok,

Ardına dökülecek damla yaş yok.

Bu son kaçış yalnızlığına

Son yalan, söylenen uğruna.

Duvarlara haykıra haykıra

Seni sevmiyorum dedidiğim gün bugün git!', 'Hala zamanın varken git sana daha fazla bağlanmadan  Sabah olmadan Akşam boğmadan yalnızlığımı,Git!  Ellerimi bırakacağın gün bugün git!  Gi...', ARRAY['Türk Edebiyatı','Şiir','Osman Fatih']::text[], 8.5, '{"poet":"Osman Fatih","poet_slug":"osman-fatih","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bugun-git-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öylesine', 'oylesine-mustafa-tas-7v2ef', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir sevdaydı.

Ölümsüzdü ya da öyle sanmıştım.

Ne karanlıklardan korkardım ne de yalnızlıklardan

Ta ki bir nefesim kesildi

İnanmak değildi bu  yaşamın son  anına

Ölüyordum.

Gözlerinde boğulurken sen, sadece bakıyordun

Öylesine

Hiç bir tepkin yoktu taş kesilmiştin

Bense ittiğin o uçurumda tutunmak için bir dala,

Ta uzaklara

Kayboldum ya da kaçtım doğrusu

Ama gözlerin hiç kaybolmadı yaşamımdan

Her gün öldüm

Her gün kaçtım

Bir sevdaydı

Uzun ayrılıklara gebe

Sonu olmayan her gün yeni bir filiz

Tadı yoktu,dokunsam kırılırdı.

Direndim olmadı.

Kaçtım yeniden

Sensiz...

Başka cümlelerin özneleriyle.', 'Bir sevdaydı. Ölümsüzdü ya da öyle sanmıştım. Ne karanlıklardan korkardım ne de yalnızlıklardan Ta ki bir nefesim kesildi İnanmak değildi bu...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Taş']::text[], 8.5, '{"poet":"Mustafa Taş","poet_slug":"mustafa-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/oylesine-78-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Sözler-44', 'guzel-sozler-44-huseyin-erdogan-sestp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '''Sevgi; şırıl,şırıl akan bir pınardır...Yürek de en önemli kaynağıdır''

                                                                            23.03.2006

                                                                        Hüseyin Erdoğan

''Kıskançlık; zehirli bir ok gibidir...Eğer,saplanırsa yüreğe insanı eritir, aşkı ve sevgiyi hızla öldürür,diğer hasetleri de güldürür''

                                                                               23.03.2006

                                                                           Hüseyin Erdoğan

''Aşk; her sabah değişik renklerde açan,her gün farklı kokan çiçeklerden oluşan bir bahçedir...Aralarından bir tekinin bile kuruması,bahçenin solması ve tehlike sirenlerinin çalması demektir...Buna dikkat etmek de sevenlerin en baştaki görevidir...''

                                                                               23.03.2006

                                                                             Hüseyin Erdoğan', '''Sevgi; şırıl,şırıl akan bir pınardır...Yürek de en önemli kaynağıdır''                                                                      ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/guzel-sozler-44-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aynı yalnızlık', 'ayni-yalnizlik-osman-fatih-6sfa8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen giderken de acımıştı,

Durur yaran

Kadeh kader yanar hala,

Ne zaman yalnızlığımla içsek

Kaybolsak diplerinde dalgaların

Tutsak nefesimizi,

Son bir nefes alsak beraberce

Ve vursak kıyılarına ıslak ıslak

Kalbimdeki yaran kanar hala... 

Ömür biter zaman biter gün biter

Sonra susarım sana

Yine konuşur suskunluğum

Sonra susarım sana

Yine vurur dalgaların susuzluğuma..

Sonunda hep aynı kalabalık

Aynı yalnızlık..', 'Sen giderken de acımıştı, Durur yaran Kadeh kader yanar hala, Ne zaman yalnızlığımla içsek Kaybolsak diplerinde dalgaların Tutsak nefesimizi...', ARRAY['Türk Edebiyatı','Şiir','Osman Fatih']::text[], 8.5, '{"poet":"Osman Fatih","poet_slug":"osman-fatih","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ayni-yalnizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ettiler', 'ettiler-zeynal-yaman-fqk9o', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dün dedenle dedemi vuran eller

Bugün seni bana düşman ettiler

Fitne okunu salıp Şark''ın bağrına

Kardeşi kardeşe yaban ettiler

Tütmesin diye İslâm''ın ocağı

Her hain plâna iman ettiler

Önce paramparça ettiler ümmeti

Sonra yavaş yavaş talan ettiler

Akan kanlar bizim değilmiş gibi

Bir de suçlu diye ilan ettiler

Her şeyimizle benzedik Batı''ya

Bu sefer de âleme tan ettiler

Bir türlü yaranamadık şu dünyaya

Hakkımızda hep suizan ettiler

Ey Zeynel! gel deşme sen bu yarayı

Bak, seni bile ağlağan ettiler

1992-Çankırı', 'Dün dedenle dedemi vuran eller Bugün seni bana düşman ettiler Fitne okunu salıp Şark''ın bağrına Kardeşi kardeşe yaban ettiler Tütmesin diye ...', ARRAY['Türk Edebiyatı','Şiir','Zeynal Yaman']::text[], 8.5, '{"poet":"Zeynal Yaman","poet_slug":"zeynal-yaman","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ettiler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülümse...', 'gulumse-reyhan-tataroglu-vbfc3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'gül kokmazsın 

                                             oturmakla 

                                             çiçekci dükkanında

                                             gel görde bak! 

                                             gül

                                             ne güzel kokar

                                             dalında', 'gül kokmazsın                                               oturmakla                                               çiçekci dükkanında      ...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Tataroğlu']::text[], 8.5, '{"poet":"Reyhan Tataroğlu","poet_slug":"reyhan-tataroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/gulumse-82-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgisizlik', 'sevgisizlik-osman-fatih-7b85o', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bırak yansın ellerin avuçlarımda 

Sanki hiç gitmeyecekmiş gibi 

Sımsıkı tut ellerimi 

Sımsıkı sarıl bana 

Kokun salınsın dokunuşlarıma..

Parmaklarımda teninin yumuşaklığı,

Gözlerimde gözlerinin mavisi kalsın..

Gök mavi deniz mavi ve gözlerin mavi

Seni sensiz yaşatan izmir yansın..

Gidersen eğer bir gün,

Güneş doğar mı sanırsın saçlarının renginde..

Deniz, gözlerin kadar mavi,

Martılar tenin kadar beyaz kalır mı bu şehirde..', 'Bırak yansın ellerin avuçlarımda  Sanki hiç gitmeyecekmiş gibi  Sımsıkı tut ellerimi  Sımsıkı sarıl bana  Kokun salınsın dokunuşlarıma.. Par...', ARRAY['Türk Edebiyatı','Şiir','Osman Fatih']::text[], 8.5, '{"poet":"Osman Fatih","poet_slug":"osman-fatih","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sevgisizlik-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '01(Şerefsiz Diyarın Kızı) Takhzamen’e', '01-serefsiz-diyarin-kizi-takhzamen-e-ahmet-yozgat-xe3xy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '1/:

Ben...

Bencileyin sen...

Ve sencileyin o…

Sayın ki üç yüz kişiydik

Asabi ateş şahablarının eşiydik...

Şerefsiz teberlere karşı durduyduk.

1/a:

Ben

Bencileyin sendik zamanın kıstağında, 

Ve sencileyin o muyduk? Bilmem…

Say ki üç yüz kişiydik ya ikimiz Takhzamen,

Hemen kapatmıştın gözlerini sabra yenik düşerek.

Bir gün hani ne çekilmişti etlerimiz,

Ne de bizdik çekilerin aşkın karadeliğine...

Yani bir tarih sevişmesinde anımsar mısın? 

Kabaralı yüzleriyle şakağımızın kuzeydoğu cenahından,

Şahmaran gözlü muharipler inmişti,

Mavi kan ve sarışın terlerle sarmaşarak.

Bencileyin sendik zamanın kıstağında, 

Bize yakışan da vuruşarak ölmekti kancık siperlerinde,

Kararımız buydu ve kesindi ve sondu ve...

Geve geve Hindistani havlican köklerini,

Şerefsiz teberlere karşı durduyduk.

Gözucuyla dalıp ihtimal deryasına Takhzamen,

Biçmiştik kefenini çıplak ruhumuzun

Musallalar yontup zemherinin izinde,

Evet... Evet...

Takhzamen (şerefsiz diyarın kızı) 

Vicdansız teberlere karşı durduyduk.

Kendimizi güneşlere vurduyduk...

1/b:

Ben...

Bencileyin sen...

Ve sencileyin o…

Bir sevişmenin oldu bitti tarihinde

Teraziye sevdamızı vurduyduk...

***

Aşk zamanının en Everesti’ndeydi kalbimiz,

Ellerimiz, organik Lut çukurunda,

Yıldırım soluklu atlara binmiş,

Yalın süvari,

Yani şeşber ve ok ve yay ve sadak...

Nallarımızın altına hayallerimizi yayarak,

Sayarak imameye kadar doksan dokuz çeken,

Sırat köprülerini ateş iksirli yaylaların...

Tam o anın,

Hatta belki de yarının,

Ve dünyanın bilmem kaçıncı meridyeninde,

Neler tekellüm ederlerdi şair ehli hakkımızda? 

(Gaipten bir ses :) 

Takhzamen ve sen! ... 

(Yani şerefsiz diyarların kızı ve oğlu) 

İşte buz kesen kanın tutuştuğu andı,

Yandı bilcümle sırata dizilen tespih taneleri ve ehli aşk. 

Sivriltilmişti çünkü yongası arsız şüphenin artık,

İzansız, gezinmişti ilk yazında tuzlu yılların.

İzbe gölgesinde bıçak çekip kuşkuya yüreğimize

Bir şaşkın teraziye sevdamızı vurduyduk.

Evet... Evet...

Takhzamen (şerefsiz diyarın kızı) 

Vicdansız teberlere karşı durduyduk.

Yani kendimizi güneşlere vurduyduk.

(Kudurduyduk) ...

2/:

Ben (miydim?) 

Bencileyin sen (miydim yoksa?) 

Ve sencileyin o (Muyduk?) …

Sayın ki üç bin kişiydik bu hesab dairesince.

İnce bir frekansta asabi ateş bozonların eşiydik...

2/a...

(Mutlaka)  Ben...

(Muhakkak)  Bencileyin sen...

Ve (muhakkik)  sencileyin o…

Her bir günün hesabını sorduyduk.

***

Aşk zamanının en Everesti’ndeydi kalbimiz,

Mevsimlerimiz yalamıştı gündüzün dudağını

Gecelerin kanatları yolunmuştu hani ya

Dağlar, yaylalara bile diz çöküp dinlemişti bizi.

(Açıktan bir ses :) 

(Gaipten bir ses :) 

Takhzamen ve sen! ... 

(Yani şerefsiz diyarların kızı ve oğlu) 

Her bir günün hesabını sorduyduk.

Evet... Evet...

Takhzamen (şerefsiz diyarın kızı) 

Vicdansız teberlere karşı durduyduk.

Yani kendimizi güneşlere vurduyduk.

(Kudurduyduk) ...

2/b...

Ben (dim orada ayakta duran) 

Bencileyin sen (din Araf’ta uyuyan) 

Ve sencileyin o (idi herşeye damga vuran) …

(Gaipten bir ses :) 

Takhzamen ve sen! ... 

(Yani şerefsiz diyarların kızı ve oğlu) 

Düşlediğimiz ülkemizi kurduyduk

Tarihin nihayete erdiği rıhtımda yanyanaydık ikimiz.

Bendim. Bencileyin senin omzundaydı bulutlu başım,

Yaşım ışık gibi ağarmıştı.

Ve sencileyin anıların bitişiydi uzun tarih senaryoları

Yolları nal izleriyle damgalanmış kan deryası kesmişti,

Esmiş ve talan etmişti sevdanın hendek harbinde yeller,

Yerler işkembesindekileri kusmaktaydı hala.

Yani her şey bir anlık...

Sonunda teslim oldu şeşberlere tutsaklık

Matemlerin eteğine ak düştü

Dağıldı istkbal dağları acıların üstüne,

Düşlediğimiz ülkemizde kuruduyduk.

İncirlerin çorak düzüne gözyaşı düştü...

Evet... Evet...

Takhzamen (şerefsiz diyarın kızı) 

Vicdansız teberlere karşı durduyduk.

Her bir günün hesabını sorduyduk.

Bir şaşkın teraziye sevdamızı vurduyduk.

Yani kendimizi güneşlere vurduyduk.

(Kudurduyduk) ...

Ancak,

Söndü bütün yıldızları aşk ehlinin.

Madde bir pulsarın gözüne düştü...', '1/: Ben... Bencileyin sen... Ve sencileyin o… Sayın ki üç yüz kişiydik Asabi ateş şahablarının eşiydik... Şerefsiz teberlere karşı durduyduk...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":121,"source_url":"https://www.antoloji.com/01-serefsiz-diyarin-kizi-takhzamen-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '01 Gönül Tandırında Yaktım Kendimi', '01-gonul-tandirinda-yaktim-kendimi-ahmet-yozgat-jlgy2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '1/:

Yakıp alemin kasvetini bitirdim

Göynümün tandırında bir sabah...

***

Ellerim,

Ellerim kavruldu Fırat selinde,

Bir şadıman rahip sürmeledi topuklarımı.

Ucu yanık asasını Musa’nın,

Diktim çorak toprağına umur görmüş döşümün.

Bir kervan yekindi göz pınarlarımdan sepken ile,

Bir kervan ki güneşlerden sağılmış,

Ve bağlamış yularını gelecek bir cidara.

Bir seyrek merhamet vahasında ömrümün,

Kendimi yaydım bağdaşımın altına.

Ve seyre...

Ve seyre daldım yangınını Leyla’nın

Göynümün harlı tandırında bir sabah...

2/:

Çıkageldi çakmak çakmak bir sufi taş devrinden,

Lime lime dilinmiş urbası ibrişimdi aslında.

Koştum ardınca ve diz urup bıraktığı arkadaki izine,

Sırrına erem diye yalvardım.

Ve seyre...

Ve seyre daldım yangınını kibrimin,

Göynümün taş devri  tandırında bir sabah...

Güneş çavdı, ben uyandım.

Kulaklarım uyandı ebedi suskunluğa.

Çatladı incirilinde dudaklarım bengisular yutkunup,

Billahsız baltalarla doğrayıp azgın uyluklarımı,

Teri temiz volkanların zirvesine yaslandım.

Ve yakıp... 

Ve yakıp tüm alemin sancısını bitirdim,

Göynümün atomik tandırında bir sabah.', '1/: Yakıp alemin kasvetini bitirdim Göynümün tandırında bir sabah... *** Ellerim, Ellerim kavruldu Fırat selinde, Bir şadıman rahip sürmeled...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/01-gonul-tandirinda-yaktim-kendimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İntihar', 'i-ntihar-osman-fatih-mb299', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yavaşça baktım boşluğa..

Ya biri itmeliydi beni; 

Ya da ben düşmeliydim çaresizce..

Kimse üstüne alınmamalıydı 

Bu gidişin sebebini..

Gitmeliydim.

Sessizce ve sebepsizce,

''Senin gibi..''', 'Yavaşça baktım boşluğa.. Ya biri itmeliydi beni;  Ya da ben düşmeliydim çaresizce.. Kimse üstüne alınmamalıydı  Bu gidişin sebebini.. Gitmel...', ARRAY['Türk Edebiyatı','Şiir','Osman Fatih']::text[], 8.5, '{"poet":"Osman Fatih","poet_slug":"osman-fatih","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/intihar-54-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '01 Yüreğimi Eze Eze Merdina Kız', '01-yuregimi-eze-eze-merdina-kiz-ahmet-yozgat-izd7e', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '1/:

Hava aşık ve gamlı...

Dumanlı bir güzergahta soluk soluğayım...

Çığlık çığlığa kaçışan gizem yüklü lokomotiflerin,

Su yerine kan ve ateş aldığı en son istasyonda,

Varla yok arası bir adresteyim...

Devriyeler durdurdular gözlerimi nedense? 

En sığ düzleminde ebruli ufkun.

Hapsedildim betondan kafeslere bir haziran ayında.

Ağzımı yani isyanımı kapatan o kanlı elin,

Bileğine dağlı karanfiller bağladım.

Ağladım... Ağladım,

Tuzlu suyla sulansın diye kıraç kavramlar.

Diz çöktüm uçan rahlesine zamanın,

Sonsuzluğu gözlerinden dinledim.

***

Ben bunları senin için ay kız Merdina,

Yüreğimi eze eze söyledim...

2/:

Pus var havada...

Dumanlı bir güzergahta soluk soluğayım...

Eksi 273 derecede yaşamı mahlukatın,

Yorgun bir atın iliği titremekte...

Ben buz kesmekteyim çığlık çığlığa...

Bir ateş fırtınası o an göz kırptı,

Altı yüz sekseninci aşk mevsiminin kalp çatlağından.

Raksetti hokka ve divit üstündeki bulutsu kitabın.

Zifiri öfkeler saçıldı durup dururken ortalık yere,

Vuruldu en arsız darbe muhkem temeline zamanın...

Ellerde kanlı balyozla devriyeler,

Ve dudaklarda kinle dolu o an...

Ağzımı yani isyanımı kapatan o kanlı elin,

Bileğine dağlı nilüferler bağladım.

Ağladım... Ağladım,

Bir şaşkın sineğin kanadına tutunup

Sonsuzluğun sırrını heceledim.

***

Ben bunları senin için ay kız Merdina,

Yüreğimi eze eze söyledim...

3/:

Kainat ah çekmede...

Dumanlı bir güzergahta soluk soluğayım...

Yanımdan ateşler içinde kalp yüklü hecinler yürümekte,

Bir kısrak ateşler içinde titremekte,

Ben örselenmekteyim...

Balçıkla yıkadılar aşk ameleleri güneşin saçlarını

Mil çekildi Yedikulede gözlerine kara kitabın

Ve kırkkanat ötedeki çayında kahırla demleyen adamın…

Bizans’ın uğursuz zindanında hapsedip özgürlüğü,

Kör bir kuyuya lime lime doğradılar Kenan’da,

Düşleri dillendiren gönlümün Yusuf’unu.

Kafesleri kapandı asırlık aslanların

Savruldu fermanlar hışmın rüzgarıyla can cana

Ne Yusuf’a tutundum,

Ve ne de Kenan’a bir yararım dokundu firavun tarihinde.

Mütevazı ve on üçüncü hamur bir sayfanın kenarına yapışıp,

Tutsak özgürlüğün tadıyla raksettim kehkeşan aralığında.

Kasıp gemini gönlümdeki kıratın,

Naylon gülistanlar merkezine eyledim.

***

Ben bunları senin için ay kız Merdina,

Yüreğimi eze eze söyledim...', '1/: Hava aşık ve gamlı... Dumanlı bir güzergahta soluk soluğayım... Çığlık çığlığa kaçışan gizem yüklü lokomotiflerin, Su yerine kan ve ateş...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":62,"source_url":"https://www.antoloji.com/01-yuregimi-eze-eze-merdina-kiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '01 Şimdi Uzaklardayım Hısım', '01-simdi-uzaklardayim-hisim-ahmet-yozgat-ra96y', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1/:

Daha dün gibiydin be hısım,

Hareli gözlerinin izi üstümde daha…

Kokun altın renkli Muş tütünü misali

Bulut bulut üzerime yağmur sağmada.

Gezinip durmada gölgesiz atıyla önümde

Saçlarıma ördüğün doyumsuz hatıralar...

***

Doğruldun mu? 

Sen doğruldun mu yatağından mesela? 

Koca koca sıradağlar susardı elpençe durup,

Diz vurup otağının önünde Himalayalar,

Mersiyenin gözüne gül ekerdi...

***

Çok, çok özlüyorum seni be hısım! 

Hasret ile doğranıyor etlerim,

Ellerim bileğini kavrıyor puslar içinde,

Belki de soyut hayallerimle avunmadayım.

Yani kanlı taraklarla taranmaktayım ateşler banyosunda,

Çünkü sana fersah fersah uzaklardayım...

2/:

Daha dün gibiydin be hısım,

Dicleler akardı şakaklarından sakin ama vakar ile…

Dolanır ve yadellerde türküler dizerdin hasret teline.

Köprüler kurardın Ağırnaslı Sinan misali,

Bir gönülden ötekine uçardın.

Durup durup bıyığını burardın dumanlı iklimlerde.

Elindeki asırlık asan en yaşlı çınardandı.

Vurdunmu yüreğindeki fideleri toprağın şah damarına,

Bir çiğidin orman olup biterdi.

***

Göresim...

Çok göresim geldi seni be hısım! 

Özlem ile doğranıyor etlerim,

Ellerim mızrap mızrap gezinmede aşk döşünde,

Say ki Karacoğlan ile Firengistandayım.

Yani kanlı taraklarla taranmaktayım dilbilmez ülkelerde,

Çünkü sana fersah fersah uzaklardayım...

3/:

Daha bu gün gibisin be hısım...

Bir elin yağda,

Öbürü samanyolunda yıldız toplamadaydı…

Saçların bıldırcın olur uçuşurdu kızgın nefesimizde

Yapayalnızdın yağmurdan süt sağan dağlar misali.

Salladın mı memleket kokulu elini mesela,

Çığlık çığlığa ebabil sürüleri konardı omuzlarına...

***

Dönmen...

De hele dönmen bu kadar zor mu be hısım? 

Volkanik hasretlerle doğranıyor etlerim,

Ellerim alıştığı hazları soruyor alfabeyi içerek.

Yedi kat yer altında bin kez daha katlanıyor mekanım.

Yani kanlı taraklarla taranmaktayım mağmalar denizinde

Çünkü sana fersah fersah uzaklardayım,

Mezardayım...', '1/: Daha dün gibiydin be hısım, Hareli gözlerinin izi üstümde daha… Kokun altın renkli Muş tütünü misali Bulut bulut üzerime yağmur sağmada....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/01-simdi-uzaklardayim-hisim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiçbirşeyin', 'hicbirseyin-osman-fatih-dg1cc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hayal ettiğimden ötede olamayacaksın, 

Senden bildiğim tek gerçek hayatındaki bir anlık karen olacak boşluğuma baktığın, 

Siyah beyaz…

………

………

Bilmeni istedim dün gece

Son kez duy istedim.

Henüz kimse gerçekten terk etmeden seni..

Yokluğunda,

Her saniye yeni yakıştırmalar yapıyorum sana, eskilerini atıyorum, 

Yanlışlarını silip düzeltiyorum isimsiz mektuplarda...”

“Hiçbirşey”inle benim oluyorsun, oysaki her şeyinle uzaktayken,

Hayaline durmadan aşık oluyorum adını koyamadığım sonsuz denizlerinde,

Daha da yakın oluyorsun, uzak durdukça bana…

Kaybedemiyorum seni,kaybettiğim gibi kendimi,

Gecelerime teninin rengi vuruyor

Sabahlar yokluğundan daha uzakmış öğreniyorum her gece

Yine güneş doğuyor yokluğunda 

sen olmuyorsun yanımda..

“Hiçbir” şeyinle benim oluyorsun, 

Oysaki sen her şeyinle uzaktayken; 

Ben hayaline durmadan âşık oluyorum..', 'Hayal ettiğimden ötede olamayacaksın,  Senden bildiğim tek gerçek hayatındaki bir anlık karen olacak boşluğuma baktığın,  Siyah beyaz… ……… …...', ARRAY['Türk Edebiyatı','Şiir','Osman Fatih']::text[], 8.5, '{"poet":"Osman Fatih","poet_slug":"osman-fatih","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/hicbirseyin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne oldu bugun! [BAHAR]', 'ne-oldu-bugun-bahar-yasar-gurlek-lwh9i', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne  oldu bugun! 

Topraktan  aldim   kokuyu,

Sari mavi beyaz,kardelenler gordum

Anladimki  artik! bahar  basliyor,

Kuslar  bile  bir  baskayi   bugun,

Roterdamda  maas  nehrinin, kenarinda

Martilarin  suzulusude,  bir  baskaydi  bugun

Kisacasi!    Anladimki  bahar  geliyor,

Gelsin  hos  geldin bahar, ciceklerini  ac,

Kokunu  sac,  her   bir  yana,

Mesut  olsun  insanlar,  mutluluk  getir  onlara

Banami  ben bir  sey  istemiyorum,

Huzur  ol  yeter………

23-03-2006

ROTTERDAM

HOLLANDA', 'Ne  oldu bugun!  Topraktan  aldim   kokuyu, Sari mavi beyaz,kardelenler gordum Anladimki  artik! bahar  basliyor, Kuslar  bile  bir  baskayi...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Gürlek']::text[], 8.5, '{"poet":"Yaşar Gürlek","poet_slug":"yasar-gurlek","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ne-oldu-bugun-bahar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '00 Asumana Postağlama: 00587', '00-asumana-postaglama-00587-ahmet-yozgat-4ohvb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Amma da Zor Günlerdi Nesliha

1/:

Amma da zor günlerdi ha...

Sana göre Asu ha? ...

***

Tarih, korka korka zaferler fısıldardı yüreğime

Oysa anadan sağırdı kulağım benim

Ne yazık duymadı, gün ışığını sabah zamanı, 

Bir yanı ay aydınlık, diger yanı zifir; 

Yüzünde pençe pençe kir... 

Şaşıracaksın ama o bakire ay lohusaydı Asu ha,

Yıldızları, tenhaları kollayıp al basmıştı samanyolunda 

Yani gözyaşına hamileydi gökyüzü

Henüz doğmamıştı sirius, kavramlar rıhtımına

Buz gibiydi sıcak çölleri tırmalayan yıldırımlar

Ve de çığlık çığlığa kaderimin yarısı...

Çöktü arzın, arzi tarihine bir karabasan,

Cehlin ve cehaletin ürkütücü geceyarısı...

2/:

Amma da zor günlerdi ha...

Sana göre Asu ha? ...

***

Bir ateş çakalı uluyordu dağlar ardında, 

3''e, 5 vardı zaman kader kadranında...

Yabanî ve kırçılsakalını sıvazlayıp

Habire can sunuyordu ateşe, ateşgedenin biri

O canlarsa çaresiz yanmadaydı Parsiler ananesinde,

Metalik bir tel gibi gerilmişti acının azgın kolları, 

Yolları sel ve mesel basmıştı...

Bir baştan öbür başa bütün coğrafyaya uzanmadaydı

Karanlığı çizen bir ressam yıldızları boyamadaydı

Henüz sürmelememişti dağları güneşin Yemeni sarısı

Buz gibiydi sıcak çölleri tırmalayan kaçkın şahaplar

Ve de peş peşe... 

Dehrin ve Cehaletin ürkütücü geceyarısı...

3/:

Amma da zor günlerdi ha...

Sana göre Asu ha? ...

***

Ummanlar içmeye durmuştu arta kalan organik kiri.

Sırmalı harmanisini sıyırıp bileklerine

Kanlı allerini yıkıyordu sahilde ateşperestin biri.

Kadim soylularsa zındanlarda boğazlanmadaydı.

Yağmur ve rutubet içinde yekinip kanından paslı kılınçlar,

Doyumsuz canları mantıksız rituellerde doğramadaydı.

***

Tarih, korka korka fısıldadı Haçova’yı yüreğime.

Hotin''de bir genç adam buruşturdu muşmulasını,

Kararı karardı bu demden geri, 

Onun her yeri som reddiye mersiyesiydi, 

Elleri kılıç kösüresiydi...

Oysa ta doğuştan sağırdı kulağım benim.

Ama vallahi duymadaydı:

Bakireler çariçesi ay lohusaydı Nesliha.

Yıldızları al al basmıştı samanyolu’nda kaldırımlara

Gözyaşına hamileydi gökyüzü

Henüz doğmamıştı güneş, kavramlar kıvrımına...

4/:

Amma da zor günlerdi ha...

Sana göre Asu ha? ...

***

Uğursuz ve ürkütücüydü ötüşü ikircik kuşlarının.

Biteviye ağıtlara oturmuştu hayalleri annelerin,

Yüreklerini yaslayıp direklerine kara çadırın,

İki ellerinin parentezinde kareköktü beyinleri.

Işıklı yaralar harmanıydı döşleri ise...

Güneşi kendi kanlarıyla harlandıran cengaverlerin,

Temrenleri nurdan bir ummana aşk zerkindeydi.

Gözlere yaş taşıyan Bağdat bezirganları ise

Develerin sırtını acılı damgalarla dağlamadaydı.

Çöl kızları ve vahalar suylarını çekmişti sabaha karşı,

Ve gümrah göller öksüzdü günbatımında.

Taş bağırlı kumlar bile Gobi’de ağlamadaydı...

***

Dedim ya tarih korka korka fısıldadı son zaferi yüreğime.

Oysa kalubealadan beri sağırdı kulağım benim,

Ama vallahi duymadaydı:

Bikri mühürlü bakire ay lohusaydı Nesliha

Yıldızları al al basmıştı samanyolu’nda bir peri.

Gözyaşına hamileydi gökyüzü

Henüz doğmamıştı güneş, kavramlar iklimine...

5/:

Amma da zor günlerdi ha...

Sana göre Asu ha? ...

***

Zeytin ve incir yetiştiriyordu bir hayalci rençber,

Kuzeydeki o gümrah yaylada her nisan sağılanda.

Ancak zeytinler ağlamada siyahi ve tuzlu, 

Ve bir de incirler ağlamadaydı kitabın Tin babında

Tarlalar mayıslar sayısınca bereket doğurmadaydı ama

Mağşuş gönüllerde kurtlar ulumadaydı dağlardan inip.

Bir kuşluk vaktinde zoraki ıhtığı yerden

Kalkıp ağır, aksak ve usangaç...

Şerik develer malî hülyalar taşımadaydı.

Şatolarında şaklatıp parmağını kusurlu lordlar,

Mahzun ciğerleri baldıranlarla dağlamadaydı...

***

Tarih fısıldadı korka korka yüreğime aşk zaferini...

Oysa son sevdamdan beri sağırdı kulağım benim

Ama vallahi duymadaydı:

Bakire ay lacivert vadisinde henüz lohusaydı Nesliha

Yıldızları al kızları basmıştı samanyolu’nda,

Gözyaşına hamileydi gökyüzü,

Henüz doğmamıştı güneş, kavramların sırtına...

6/:

Amma da zor günlerdi ha...

Sana göre Asu ha? ...

***

Âmâ babalar kapıp kazmayı bir define arefesinde,

Mağdur sandıklar dizip yer altına töre gereği

Ya da kumların kalbine aysız çöl ve ağıt gecelerinde…

Vah ki vah! 

Üzüm gözlü kızlar ağlamadaydı

Yaylalara acı

Ovalara kin

Sitemkâr dağlara kar yağmadaydı

Dedim ya tarih fısıldadı yüreğime ilkin

Oysa sağırdı kulağım benim

Ama vallahi duymadaydı:

Bakire ay lohusaydı Nesliha

Yıldızları al basmıştı samanyolu’nda

Gözyaşına hamileydi gökyüzü

Henüz doğmamıştı güneş kavramların sırtına...

7/:

Amma da zor günlerdi ha...

Sana göre Asu ha? ...

***

Dizleri üstüne düşüp Kenan ilinde kıyamet kilisesinin zangocu,

Yani küflenmiş rahibi ihtiyar ve ihmalkâr ihtimallerin,

Bitmeyen umutla ihatalı kasvet deryasını

Mahmur istikbâle rehine taşımadaydı.

***

Korkak tarih fısıldadı yüreğime Ferhat’ı taşelinde.

Oysa sağırdı kulağım Şirinden beri benim

Ama vallahi duymadaydı Nesliha:

Annem ay lohusaydı asuman içre ve ziyalı

Yıldızları al perileri basmıştı samanyolu’nda.

Gökyüzü mavi bir şemsiye gibi sürûra gebe,

Ufuklar çizgi çizgi ışımadaydı...

***

Tarih zoraki fısıldadı yüreğime Nesliha seni.

Oysa sağırdı az evvelki bir andan beri kulağım benim

Ama vallahi duymadaydı Nesliha: 

Kaynanam ay lohusaydı bir aybaşı vaktinde,

Yıldızları al kanlar basmıştı samanyolu’nda

Gülyaşına hamileydi gökyüzü

Doğuyordu güneş, ışıklı kavramların sırtına...', 'Amma da Zor Günlerdi Nesliha 1/: Amma da zor günlerdi ha... Sana göre Asu ha? ... *** Tarih, korka korka zaferler fısıldardı yüreğime Oysa a...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":147,"source_url":"https://www.antoloji.com/00-asumana-postaglama-00587-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçim Boşalır', 'i-cim-bosalir-nergis-unlucay-see3j', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bachmann yanar yalnızlığında

Şampanyalarla uyku ilaçlarını karıştırır Marilyn 

Veli bir kanalizasyon çukuruna düşürür imgelerini

Freud çözümsüzlüğüne tökezleyip atar pencereden inançlarını

Van Gogh kulağını kesmiştir

Kimse duyamaz artık bizi

İçim boşalır', 'Bachmann yanar yalnızlığında Şampanyalarla uyku ilaçlarını karıştırır Marilyn  Veli bir kanalizasyon çukuruna düşürür imgelerini Freud çözüm...', ARRAY['Türk Edebiyatı','Şiir','Nergis Ünlüçay']::text[], 8.5, '{"poet":"Nergis Ünlüçay","poet_slug":"nergis-unlucay","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/icim-bosalir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '01 Sokağın Kızı Tennimey’e Destan', '01-sokagin-kizi-tennimey-e-destan-ahmet-yozgat-h08v9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '1/:

İncecik ve bir yağmur sonrası,

İzanım dururdu sokak başında,

Ben esiri olurdum elâlarının...

Ey Tennimey...

Alnımdaki çıkmaz sokağın kızı...

***

Yorulurdu nisan olup sürdüğüm küheylanlar,

Hafakanlar beynimde, yüreğimde ala yılanlar...

İlkbaharım olurdu her yağmur ardından o sokağın kızı.

 Hızı, aşktan da beri... 

Sonun başlangıcıydı fakire bu an, bilirdim, 

Nisan kuşu ötüşlüydü yüreği onun zira... 

Erken doğardı aynına ateş ve kavuniçi güneşli sabahları

Akşamları, elini kınalardı aşkın ekavatorundan

Teriyle karıp gül kokulu harcını Sinan kemerlerinin

Güneşe pırıltılı destanlar örerdi ilkbaharlarda,

ucuna tuğ olurdu cengaver temrenlerinin, 

Ve bir lahuti "Huğ! " dudaklarında...

***

Ay macup, 

Kız dingin  bir çıkmaz sokak günahının ardından,

Göğsıra bakan bulutları delirtince uslanırdı saçları,

Uçları damla damla iznsız ter damlaları,

Dağları uça uça

Stepleri basa basa öpülür kundak.

Apak bir öfkenin anarşist örgüleri Che Che çözülür

Testereler doğrardı terkisini tayların.

Ve dudakları dürülürdü istasyon akşamlarının,

Çıkmaz sokaklar bir daha garkolurdu Hispanik sevdalara, 

Amansız kayalara bindirirdi Dragut kalyonları....

***

Sonra durur du tarih, 

O da durur du o da...

Ufuklara garkolan grup güneşi gibi

O da oda ayrılırdı günahlar cins cinse, 

Görüntüsü vururdu nedense döşünden yükselen Tienşan’lara.

İzanı donar ve dururdu sokak başında tayların

Ben esiri olurdum onun ıslak elâlarının... 

Belalarının üstesinden gelmek de kimin haddi? 

İZira ikbaharım olurdu her ıslak günahımın ardından o sokağın kızı 

Bir yıldızı ttar ve bağlardı püsküllerine

Beynimde açılan yabani kafeslerin kapanırdı gözleri o an

Ütopik aslanın ruhu -köleliği bile reddeden-

Kelepçenin teslim olup tenine yeleleri yolunmuş...

Sevdager savaşımı kemirip orta yerinden

Yok edip zaferlerin bilcümle olasılığını

Erken doğururdu lacivert hilâli yaz akşamları. 

Bir de ıslak günahımın ardından o sokağın kızı... 

2/:

Sulu sepken ve bir yağmur sonrası,

Kanım donar ve dururdu sokak başında,

Ben esiri olurdum elâlarının...

Ey Tennimey...

Alnımdaki çıkmaz sokağın kızı...

***

Ama... 

Kaldırım başında tırnağını kemirirdi bir kıskanç lama

Bahçevanım gül dererdi susuz çöl coğrafyasında,

Arkasında organik dişli testeresi dururdu anın.

İzanım dururdu benimse sokak başında

Ben esiri olurdum elâlarının...

***

Her dağda bir Ferhat-ı külünkdar,

İlkbaharım olurdu her Kerem etkinliğin ardından o sokağın kızı. 

Çınarlar dökende yaprağını sonbaharın eteğine,

Terlerdi dağları kucaklayan eylülün gümüş sapı

Yazılırdı metalleri eriten bileklerin intihar şiirleri

Öfkeli fırınların alevleri boşanırdı kanıma

Estirirdi etekleri Everest’i bir daha ha bir daha

Tuvalini boyardı gözlerinin açık ela renginden.

Kasten unutulmuş bir hudut köyünün hızı

Kasvet ören geçmişini bir çırpıda getirip

Çakardı varoşuna can çeken kanlı kahpe metropolün, 

Ve o sokağın kızı...

***

Bastırdığım izanım dururdu sokak başında,

Ben esiri olurdum elâlarının...

İlkbaharım olurdu her Şirin aralığında sokağın kızı

Lakin her ne olsa da kafasında komşunun

Erken doğardı anasından karalı alınyazısı...

***

Sulu sepken ve bir yağmur sonrası,

Kanım dondu ve durdu zamanın en başında,

Ben kurbanı oldum elâlarının hey! ...

Ey Tennimey...', '1/: İncecik ve bir yağmur sonrası, İzanım dururdu sokak başında, Ben esiri olurdum elâlarının... Ey Tennimey... Alnımdaki çıkmaz sokağın kız...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":86,"source_url":"https://www.antoloji.com/01-sokagin-kizi-tennimey-e-destan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '01 Sırlı Bir Yolculuktur Bizimkisi', '01-sirli-bir-yolculuktur-bizimkisi-ahmet-yozgat-ipxjy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'A/:

Nereye uzar döşüne diz urduğum bu yollar? 

Bu yollar hey! …

***

Tutup yakasından gri geçmişi

Neden kaldıramaz ağır bahtımı? 

Damarları çatlayan kollar ne yapar? 

Ve nerede kol gezer yüreğmden verulduğum turaçlar? 

Kırk bin haramiler ki tutmuş çölleri.

Çekilin hey veledi zina dölleri savulun! 

Gümrah vahalardan su sızmıyor dışarı yufka yerinde

Boz bulanık bir manzara usulca ve utangaç,

Yapışırken tuvaline ömrümün...

Genişlemiş aleyhine gündüzün

Koynu dolu, tehlikeli geceler ve kehkeşanlar...

Nereye uzar? 

Döşüne diz urduğum bu yollar? 

B/:

Neden bitmez dağların bahtına batan sancı? 

Vah vah! Kemikleri sızlıyor kabrinde uyuklayan,

Sağlığında sahrayı mekan tutan mecnunlar.

Düşmanın döşeğinde unutup öz geçmişi

Ne yapar mutlu yatan Leylalar? 

Çekilin hey veledi zinalar savulun! 

Neden şehla bakar rüyama sızan hain yıldız? 

Çökmüş kaldırımı yol vermiyor yoksul kervana,

On binleri omzunda taşıyan o hain şehirler.

Nehirler gezinirken iştahla sol yanımda

Uğursuz kavramların ürettiği çuvaldız,

“Bela artık” arkadaş zaman ile tokalaşan elimle

Tükenen dakikalar bırakırken yerine

Beni ve kara smokinli o kanperest vampiri

Nerde kaldı söyleyin sihirli yıldız? 

Ve kefaletimi alan o hancı

Neden bitmez? 

Soylu dağların döşüne batan sancı?', 'A/: Nereye uzar döşüne diz urduğum bu yollar?  Bu yollar hey! … *** Tutup yakasından gri geçmişi Neden kaldıramaz ağır bahtımı?  Damarları ç...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/01-sirli-bir-yolculuktur-bizimkisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '01 Günah Eken İhtiyar', '01-gunah-eken-i-htiyar-ahmet-yozgat-wtgbk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1/:

Kara geceyi imsaka ilikliyordu usulca

Geçmişine günah eken ihtiyar…

***

İniltisini bıçaklayıp yedi yerinden

Acılı pişmanlık ekiyordu seccadesine

Yüreğinin burçları onun…

Tespih tespih kızarıyordu parmak uçları,

Yer yüzünü sunuyordu semaya yüreğinden siniyle.

***

Geçmişine günah eken ihtiyar 

Pişmanlık denizinde yıkanıyordu…

Höykürüyordu eyvahın atına binip 

Ve çöküp dizinin dibine teslimiyetin

Dünlerini geviş geviş getirip

Karanlık çukurlara ve geçmişine tükürüyordu.

Hönkürüyordu geçmişine günah eken ihtiyar.

2/:

Geçmişine günah eken ihtiyar

Tırmalayıp gecenin siyah yüzünü

Işığa ulaşmaya çabalıyordu…

Bidayetinde gecenin bağdaş kurup ibrişimler üstüne

Geçmişine günah eken ihtiyar

Devirip tespih tespih anılarını ipek yoluna

Karanlık ve nükleer fırınlarda kavuruyordu.

Kuruyan dudaklarına dualar sürüp

Anılarını mezarının karanlık çukuruna savuruyordu.

Yalvarıyordu geçmişine günah eken ihtiyar.

3/:

Geçmişine günah eken ihtiyar...

Döndürüp çaresizliğin kapısından yönünü

Umudun hududuna dayanıyordu.

Kara geceyi düğme düğme ilikleyip sabaha

Günahını tövbeler ateşinde dağlıyordu.

Bağdaş kurup imsakın sahillerine

Mütemadiyen ağlıyor... 

Geçmişine günah eken ihtiyar ağlıyordu...', '1/: Kara geceyi imsaka ilikliyordu usulca Geçmişine günah eken ihtiyar… *** İniltisini bıçaklayıp yedi yerinden Acılı pişmanlık ekiyordu sec...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/01-gunah-eken-ihtiyar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rulet', 'rulet-nergis-unlucay-k10fw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kırmızı ya da siyah

Bu rulet 

Oynadığım anlar boyu

Ne zaman ifşa etti rus olduğunu

Ölüm kalım 

Kırmızı ya da siyah

Ölüm kokar iki renk de son tetikte', 'Kırmızı ya da siyah Bu rulet  Oynadığım anlar boyu Ne zaman ifşa etti rus olduğunu Ölüm kalım  Kırmızı ya da siyah Ölüm kokar iki renk de so...', ARRAY['Türk Edebiyatı','Şiir','Nergis Ünlüçay']::text[], 8.5, '{"poet":"Nergis Ünlüçay","poet_slug":"nergis-unlucay","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/rulet-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '01 Asılan Umudumdu', '01-asilan-umudumdu-ahmet-yozgat-jl398', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '1/:

Zavalı bir sir söğüt dalına astılar,

Kara lordlar aydınlık umudumu...

***

1/a:

Oysa bir ömürlük zamanın fırçasıyla

Işıklı tuvallerin yeşertmiştim bağrında.

Kendimi günde bin kez

Dikenli tarlalarda acıyla doğurmuştum.

Azgın sahilinde Akdeniz’in

Antik bir teknede Hacer’den kalan

Taşların hamurunu alaya alan kendimi

Bengisu ve hayat güneşiyle yoğurmuştum.

Göklere kırk bir kapı çizip

Anahtarlar yontmuştum som ve 24 ayar altından

Yarınıma kırk konaklık temeller kazıp

Gül ekmiştim bugünden aşiyanıma.

Ve hicret edip alaimisemada unuttuğum rüyalarıma

Bırakmıştım geride masum vatanımı, öksüz yurdumu...

1/b:

Minnacık bir söğüt dalına astılar,

Koca koca lordlar incecik umudumu...', '1/: Zavalı bir sir söğüt dalına astılar, Kara lordlar aydınlık umudumu... *** 1/a: Oysa bir ömürlük zamanın fırçasıyla Işıklı tuvallerin yeş...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/01-asilan-umudumdu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '01 Anarım O Eski Ustamı Özlem İle', '01-anarim-o-eski-ustami-ozlem-i-le-ahmet-yozgat-5i316', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '1/:

Anarım yüreğime mermer anıtlar kuran,

Işıklı üveyikler çırpınır emek verilmiş derinliğimde,

Anarım kendimi yeni baştan yontan ustamı...

***

Sevgi çeker…

Fırat’ımdan sevgi çeker bengidolabım.

Fısıldar hücrelerime bildik adını,

Zebercetten biçimlenmiş dudağının ucuyla...

O dolapleyin Yunus ve ışkperver,

Ve Nazımleyin emekseverdir,

Çorak tarlasına akıtır beynimin cansuyunu.

Yıkarım kafiyeden oluşmuş eski dağları 

Anarım ustamı yüreğime aynalı anıtlar kuran...

***

Türkü döker…

Bir nazlı feliks türkü döker üstüme.

O eski ustanın esrik kokusunu,

Ve mermerlerde çınlayan madeni sesini duyarım:

“Tanı kendini ey Mahmut oğlu Yozgatlı ahmed! ”

Henüz soğumamış kendi külünden çıkıp

Gümüşî bir örs üstünde döğülür sesi:

“Ve de tanı kendini! ”

Kıta kıta kaşınır sağ ayası avcumun

Saatımın kurulur boşalan zembereği

Yüreğimin boyasıyla yenilerim

Ustamın parmak ucundaki erişilmez ereği.

2/:

Sağ gözüm seğirir mütemadiyen.

Ustamın yayılır omzuma mentollü harmanisi.

Sığırcıklar ve serçeler suya iner irisime her akşam.

Demir dağlar teslim olur ateşime Ergenekon’unda şiirin 

Cevval bir ceylan olur sıçrarım…

Anarım yüreğime ipek anıtlar kuran ustamı,

Kutsarım Sinani köprüler kuran emektarım yılları.

Bir zehep zamanda binip kıvılcımlarına sevdamın

Ustamın çeliği uslandıran sabır suyunu içip

Uzak diyarlardan serçe döşlü türküler ısmarlarım.

Hamur kokan bin evleklik ellerini öperim

Can verip karakışta ateşe

Utancı emziren şüphemi birleyip binle

Cehennemî tandırlara dökerim,

Anarım yüreğime ipek anıtlar kuran ustamı.

Ekerim genç yüreklere Yunus’u ve Nazım’ı...', '1/: Anarım yüreğime mermer anıtlar kuran, Işıklı üveyikler çırpınır emek verilmiş derinliğimde, Anarım kendimi yeni baştan yontan ustamı... ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/01-anarim-o-eski-ustami-ozlem-ile-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '01 Bir Göç Günlüğü', '01-bir-goc-gunlugu-ahmet-yozgat-arh1k', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '1/:

Terkettim sevdamı bir göç öncesi ağalar…

Usul, ağır ve aksak...

***

Önümde zeheb belikli küheylan katarları

Arkamda gri dumanları minyatür hanedanımın

Avuçlarımda çangıl çangıl çok hörgüçlü mayalar

Kaşlarım yaprak dökmeye meftun

Dudaklarımda acı bir bozlak sesi

Terkettim sevdamı bir göç öncesi...

***

Ben ki tevellüdüm dokuz yüz elli beş,

Hamur elli bir Hafize’den olma,

Koma beni yollarda ey yüreğim,

Ko gitsin sevdiğim bu haini korlara...

2/:

Nakışlı semeri devemin ağalar bana tek kalan…

Usul, ağır ve aksak...

***

Hindi kenevirlerden burulmuş anıların yuları,

Salkım saçak dolanmada bozaran tevellüdüme

Yüzüm zahmetin sonbaharına dönük

Arkamda ise can çekişen minnacık bir ilkbahar

Dilim dilim doğurmada ufuklar ayazı ve karı

Ve memesinden ağu sızan mart hınzırını

Sürmede menzilsiz bir yolculuk uzamada zor zaman

Nakışlı semeri devemin bana tek kalan...

***

Ben ki tevellüdüm dokuz yüz elli beş,

Hamur elli bir Hafize’den olma,

Koma beni yollarda ey yüreğim,

Ko gitsin sevdiğim bu haini korlara...

3/:

Aşiret usul usul akmada kör vadide ağalar…

Usul, ağır ve aksak...

***

Bir ana, bozlak örmede dağların ayaklarına

Arkadaysa ölümü katre katre içen hasretlik

Önümde, eflatun gölgesi can çekişen güneşin

Yavaş yavaş geçmede dağları yutan yürek

Ve üfürmede az yaşanan bir kaderi nadide

Aşiret usul usul akmada kör vadide...

***

Ben ki tevellüdüm dokuz yüz elli beş,

Şerbet dilli bir Hafize’den olma,

Koma beni yollarda ey yüreğim,

Ko gitsin sevdiğim bu haini korlara...

4/:

Bulutlar matem tükürmede ağalar ütümüze habire…

Usul, ağır ve aksak...

***

Yeşil  donlu umutlar -ki burmuyor kolanını-

Ve son kırıntı düşüyor nakışlı yaylalardan

Arkada mevlanamsı tespih çeken yolboyu

Ön cenahta ise kozmoğrafyada pişmiş tuğlası bitmiş

Kuyrukları yolunmuş pusulasız turaçlar

Daylak develerin adımları ulaşmada kabire

Bulutlar matem tükürmede üstümüze habire...

***

Ben ki tevellüdüm dokuz yüz elli beş,

Sizin köylü bir Hafize’den olma,

Koma beni yollarda ey yüreğim,

Ko gitsin sevdiğim bu haini korlara...', '1/: Terkettim sevdamı bir göç öncesi ağalar… Usul, ağır ve aksak... *** Önümde zeheb belikli küheylan katarları Arkamda gri dumanları minyat...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":63,"source_url":"https://www.antoloji.com/01-bir-goc-gunlugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul Kendi Şiir', 'i-stanbul-kendi-siir-nurcemal-ozturk-8j507', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '''İstanbul''a şiir yaz'' dediler ya,yazamam

İstanbul kendi şiir,mısrasını bozamam.

Kâinatın sultanı,peygamber övmüş onu

O''nun sözü üstüne bir tek cümle dizemem.

Peygamber müjdesidir İstanbul,milletime

Onu anlatmak için yetmez cümle,kelime.

Sahabe onun için çölleri aşmadı mı? 

Şehit olup surların dibine düşmedi mi? 

Onun uğrunda kimler,kimler savaşmadı ki

Nice çölleri geçip,kıtalar aşmadı ki.

Alparslan kapı açtı Malazgirt''den içeri

İstanbul hasretiyle hücum etti ileri.

En büyük velilere beşik olmuş İstanbul

Cennet taamlarına kaşık olmuş İstanbul.

Kolaydır İstanbul''a aşk şiirleri yazmak

Gül bahçesi misali,sokaklarında gezmek.

İstanbul''lu olunmaz Boğazda gezmek ile

İstanbul anlatılmaz medhiye dizmek ile.

İstanbul''u anlamak Fatih Sultan olmaktır

Akşemseddinler gibi,uğrunda ağlamaktır.

En büyük velilere beşik olmuş İstanbul

Cennet taamlarına kaşık olmuş İstanbul.

İstanbul''u bu gözle seyretsin,seyredenler

Görmesini bilene İstanbul neler söyler.', '''İstanbul''a şiir yaz'' dediler ya,yazamam İstanbul kendi şiir,mısrasını bozamam. Kâinatın sultanı,peygamber övmüş onu O''nun sözü üstüne bir t...', ARRAY['Türk Edebiyatı','Şiir','Nurcemal Öztürk']::text[], 8.5, '{"poet":"Nurcemal Öztürk","poet_slug":"nurcemal-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/istanbul-kendi-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '01 Irgat Kasım Manzarası', '01-irgat-kasim-manzarasi-ahmet-yozgat-pqydw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '1/:

Yaman yakıyordu ırgatbaşı...

Teri akıyordu toprağın

Ve Kasım’ımın kanı…

***

Türküsünü tutup ucundan

Göçürdüğü kökün yerine

Toprağa kakıyordu…

Kem talihli Kasım’ım bulutlara,

Bulutlarsa yere bakıyordu.

2/:

Yaman yakıyordu altunî güneş...

Çöküverip tereğine

Ter kokulu kasketin…

Sıcaktan kaçıyordu ırgatbaşı...

Çabası boşunaydı

Açıkta kaynatıyor güneş

Gölgede yakıyordu…

Kasım’ım dürüp gözlerini fersiz, çaresiz

Ölü koyunlar gibi bir bana,

Bir de kem talihine bakıyordu...

3/:

Yaman yanıyordu ırgat Kasım’ım...

Bir soluk çekip yorgun cıgarasından,

Kavrayıp cefasını çapanın

Ve itip kasketini Çukurova’dan daha geriye

Güneşe inat,

Aksine ırgatbaşının...

Vurup kahverengi toprağa hıncile,

Ve vurup kem talihine,

Atılır çaresiz ileriye...', '1/: Yaman yakıyordu ırgatbaşı... Teri akıyordu toprağın Ve Kasım’ımın kanı… *** Türküsünü tutup ucundan Göçürdüğü kökün yerine Toprağa kakıy...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/01-irgat-kasim-manzarasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '01 Zamanı Döven Demirci Ustası', '01-zamani-doven-demirci-ustasi-ahmet-yozgat-l87ia', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1/:

O zamanı döven bir demirci...

Örsündeyse ahir zamanların en genci…

***

Son günlerinden…

Kasımın el artığı günlerinden daha atak

Ve daha haşmetli antik asırlardan

Tek tek dövüp yapraklarını takvimin

Hayırhah kavramlar koyuyordu yolculuk için azığıma.

Zamanı döven demirci,

Çifte su veriyordu kanıma...

2/:

Zamanı döven demirci...

Sağında çelebi çıraklarının en genci...

***

Son imbiğinden…

Süzüp imbiğinden en eski ve usta sözlerin

Buzdan kaselere damıtıp ömrünü şahın

Örsünde bir tutam kasvet ve bir kulaç hırsla

Hüzünlü muskalar diziyordu yaylalar enindeki alnıma.

Zamanı döven demirci,

Çifte su veriyordu kanıma...

3/:

Zamanı döven demirci...

Körüğünde Süleymanların en genci...

***

Derin derin… 

Çekip derin derin körük misali akciğerine

Üfleyip yoksul şiirlere sevdalı bilgiçliğiyle

Bindirip ocağından atlayan çıngılara

Esrik türküler dolduruyordu kan ve etten sahanıma.

Zamanı döven demirci,

Çifte su veriyordu kanıma...', '1/: O zamanı döven bir demirci... Örsündeyse ahir zamanların en genci… *** Son günlerinden… Kasımın el artığı günlerinden daha atak Ve daha ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/01-zamani-doven-demirci-ustasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '01 Kentin Alınyazısı', '01-kentin-alinyazisi-ahmet-yozgat-kvxx2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '1/:

Kaldırımda ürkek ve ipinceydi,

Kentin alınyazısı sabit coğrafyasında...

***

Keten kundaklı dağlar doğuyordu

Güneşlerin ardından bir yağmur sonrası.

Nal toplayan yollarda bir terkos sağanağı,

Hıca hınç günah yıkamada metalik künklere.

Mahpuslarda en sivrisinden,

Ve kör odalarında evlerin,

Pörsümüş çarşamba sığınağı...

***

İlk kez ilikliyordu arzularını şehir

Kabaralı bir kaçkın potinin kopçalarına.

Çakmak çakmak çakıyordu pencerelerinden

Ve lağımlarından akıyordu öfkeli deterjanlar.

2/:

Aslında uysal ve uyuz,

Ve gözleri âmâ olan bir fareyi andıran

Kozmik genlerinde bir arslan barındıran

Kırmızı kiremitli geleneklerim...

Örtüp çatısını

Ve kepenklerini iğdiş edilmiş kavramların,

İnzivaya kırk bir kere dürülmüş bir yosma gibi

Öylesine karlı ve ateşli bir kış günü,

Kehribarlar sıçratıp hüznün avuçlarına bir bir

Kardelen emsali beyaz yorganına bürünüp

Dalıvermişti tarihin kış uykusuna

Asırlık ihtiyarlar gibi uysal ve pörsük...

***

O civan şehir...

İlk kez ilikliyordu tasmalı arzularını 

Kabaralı bir kalçanın şehevi kopçalarına.

Çakmak çakmak çakıyordu pencerelerinden

Ve lağımlarından akıyordu öfkeli deterjanlar…', '1/: Kaldırımda ürkek ve ipinceydi, Kentin alınyazısı sabit coğrafyasında... *** Keten kundaklı dağlar doğuyordu Güneşlerin ardından bir yağm...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/01-kentin-alinyazisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soğuk Bir Mart Gecesiydi', 'soguk-bir-mart-gecesiydi-bilal-aydinli-17mvl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Soğuk bir mart gecesiydi

İliklerime kadar üşümüş,titriyordum

Sevgilinin her hecesiydi,içimi kanatan

Hem üşüyor hem ağlıyordum

Dalgalar kıyıda ne varsa yıkıp savuruyordu

Sevgilinin benim yüreğimi yıktığı gibi

Küçük tekneler kayboldu gitti suların altında

Tıpkı benim küçük umutlarım gibi

Artık kokusunu daha iyi alıyorum

ölümdü, eceldi bu gelen

Azrailin sesini duyuyordum

Titremem geçti,alev alev yanıyordum

Ölüm sıcak gelirmiş insana

Burnunda kan kokusu,içinde intihar korkusu

İnsan severken ölürmüş aslında

İşte bu ölümlerin en kötüsü

Ey sevgili duy sesimi,ben gidiyorum

Bilinmez bir yola yürüyorum

Senin uğruna değil ama

Soğuk bir mart gecesinde,sensizlikten ölüyorum', 'Soğuk bir mart gecesiydi İliklerime kadar üşümüş,titriyordum Sevgilinin her hecesiydi,içimi kanatan Hem üşüyor hem ağlıyordum Dalgalar kıyıd...', ARRAY['Türk Edebiyatı','Şiir','Bilal Aydınlı']::text[], 8.5, '{"poet":"Bilal Aydınlı","poet_slug":"bilal-aydinli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/soguk-bir-mart-gecesiydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz Özlemi', 'deniz-ozlemi-altug-guler-559tr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Taşınma telaşına duşmuş bir Ankara''ya oturmuşuz

Yüze yüze sığınacak liman arıyoruz

Gordüğümüz ağaçlara inanmıyoruz artık

Onları denizin yetiştirmediğini biliyoruz

Ağaclar, inanılmaz ağaçlar

Bekleyip ağladığımıza gülüyorlar

Çam değil bunlar cam ağaçları 

Kırık iğneleri susuzluğumuza batıyor

Her yanımız çıplak, battığını duyuyoruz

Susuyoruz, konuşmuyoruz

Susuyoruz, içecek deniz arıyoruz

(Ankara, Mart 2006)', 'Taşınma telaşına duşmuş bir Ankara''ya oturmuşuz Yüze yüze sığınacak liman arıyoruz Gordüğümüz ağaçlara inanmıyoruz artık Onları denizin yeti...', ARRAY['Türk Edebiyatı','Şiir','Altuğ Güler']::text[], 8.5, '{"poet":"Altuğ Güler","poet_slug":"altug-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/deniz-ozlemi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '01 Satılmış’ı Sattılar', '01-satilmis-i-sattilar-ahmet-yozgat-qbq41', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '1/:

Sitemlerle öpüştü kumları sahillerin

Bulutlar cahil ve korkak bir eda ile gülümsedi.

Simli yorganının kıyısından utangaç

Şehir, esrik denizlerdeki çürük teknede sarhoş

Gaflet dokuyordu varoşların tezgahı

Yarım tiner kokuyordu damarım benim ise...

***

Öte yanı kandı…

Satılmış’ı sattılar en arka çıkmazda.

Adım adım karardı arka sokaklar,

Beyoğlu yandı,

Acıyla nikahlandı yüksek kaldırım...

2/:

Uhu’landı sıkıca hayat ölüme

Lime lime ayrıldı mimarisi kaderin

Tuzlu telveyi döktüler dudaklarına onun

Ve erdemi içen kansız yolların taşlı aralığına.

Geceler çatılmış kaşlarıyla düşüyordu ardına

Gündüzün kovaladığı gri hüzünlerin.

Sindi çıplak yarasa gibi geceye yüksek kaldırım

Neonların gamalı nabzı hopladı

Kent neşelendi, çok mutlu sandı evlatlarını

Ama aldandı…

Satılmış’ı sattılar Dolapdere’de,

Karaköy yandı,

Ölümle sevişti Pera’nın vandalları...', '1/: Sitemlerle öpüştü kumları sahillerin Bulutlar cahil ve korkak bir eda ile gülümsedi. Simli yorganının kıyısından utangaç Şehir, esrik de...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/01-satilmis-i-sattilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '01 Gri Banliyöde Kırmızı Rüya', '01-gri-banliyode-kirmizi-ruya-ahmet-yozgat-59i4y', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '1/:

Bir banliyöde unuttu yedi renkli rüyasını

Saldırgan bir öykü gibi acar ve asabî

Yarmaları gözleriyle ısırıp

Düzlerle an be an evlenerek…

***

Bir banliyöde unuttu rüyasını,

Vurgununu hayalinde severek.

2/:

Anası azık diye bir ayçöreği koymuştu

Günde bir öyününe hasretinin

Yavuklusu ise yarım ve yanık yürek…

***

Bir banliyöde unuttu rüyasını,

Yüreğindekinin adını söyleyerek.

3/:

Bilmediği düşlere girip kaçak ve usulca

Hayallere don giydirip uzun mesailerde

Bayat somunları geveleyerek…

***

Bir banliyöde unuttu rüyasını,

Demir tekerlekler altında bir puslu sabah,

Acılı bozlaklar söyleyerek...', '1/: Bir banliyöde unuttu yedi renkli rüyasını Saldırgan bir öykü gibi acar ve asabî Yarmaları gözleriyle ısırıp Düzlerle an be an evlenerek…...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/01-gri-banliyode-kirmizi-ruya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '01 Uzandık Kitabın Buhurdanına', '01-uzandik-kitabin-buhurdanina-ahmet-yozgat-ej6oj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '1/:

Zeytinlere ak düştü,

İçin için ağladı sürgün incirler...

***

Bir utangaç kuşluk peçesini sıyırdı

Bizler uzandık kitabın buhurdanına

Esrik bir mevsimin kan kalesinde.

Yıldız içip avuç avuç

Rüzgârların yelesine yapışıp

Boş yere inledi ince ve derinden

Üstü mübarek ama altı boş diller

İçin için ağladı sürgün incirler...

2/:

Zeytinlere ak düştü,

Anası ağladı hünsa tayların…

***

Uzandık kapılıp vurgun yemiş  tekneye

Ve hasret ören mercanların iline

Yuvarlak kemerli mimarîsinde arsız özgürlüğün

Ardından maviye bulayıp karasını sarışın kevkeblerin

Atılıp ötelerin gergin ve hırslı yayından

Kavgası kozmik tuvallerin Greki arenasında

Ve sevişmesi toprağa yakın

Dışı mukaddes ama o içi boş gönüller ile

İçin için ağladı sürgün incirler...

3/:

Zeytinlere ak düştü.

Teker teker yuvarlandı kavramlar...

***

Dolandı gözyaşını mucizevi ekvator

Kervanların kutsal yükü çöplüklere boşaldı

Ve uzak ve çorak ülkelerin yavan gönlüne

Boş yere kavradı yeri

Dışı kutsal ama ayası boş eller…

İçin için ağladı sürgün incirler.

Ağladık bizler...', '1/: Zeytinlere ak düştü, İçin için ağladı sürgün incirler... *** Bir utangaç kuşluk peçesini sıyırdı Bizler uzandık kitabın buhurdanına Esri...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/01-uzandik-kitabin-buhurdanina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '00 Asuman’a postyağmurlama: 00051', '00-asuman-a-postyagmurlama-00051-ahmet-yozgat-bjbch', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1/:

Yağmuruna yandım Asuman…

***

Gökler gürül gürül şimdi,

Suyun kaderini kıraat etmede, 

Evrende, bir kelebek kanadını çırpmış olmalı... 

Solmalı ezeli rengi insani ezberin, 

Derin bir yola evrilmeli yazgısı suyun,

Duyun bu sesi ey naturel yeşiller, 

Ve durun duaya teslimen Hakk''a... 

Duyuyor ve duruyorum bu dizede ben iştimaya, 

Tekellümün dağarcığı delinmiş gibi akmaya teşne,

Baktı işaretin kızları heveler penceresinden mavi derinliğe, 

Çorak şakaklarımdan sızdı artan acılar

Çırak sayılıp kadim kavramların izbesine yollandım o an,

Kana kan şimdi, suya su ya da sele sel! 

Şafaklar aynel yakin el sallamada,

Kamada kan izi, bakraçta su, vadide sel... 

Ağır uykusunu bölüp ibis kuşları

Antik ve günahperest fetişleri paralamada

***

Çevir durma! ...

Çevir sayfasını mevsimlerin Asuman

Bak hamile hurmalar sancıya durmuş

Bağdat’a giden kervanlarım göründü

Zılgıt çekmede günah kârlı bezirgânlar...

2/:

Yağmuruna yandım Asuman…

***

Bulutların beyazladı kara saçımı

Bak Arabistan şimdi kum ağlamada

Kösnük hurmalar bile neden hünsa bir bilsen

Çünkü ebabiller Ebrehe’ye zakkum gülü atmada

Samarra’nın kubbeleri örtmede güneşleri

“Ya halife! ” Demede Leylalar bir ağızdan

Ben oyum bilesin ey Asuman

Oysa sen o değilsin beli...

3/:

Yağmuruna yandım Asuman…

***

Kuşluk çanı tuğla kulede usul usul çalmada

Develerim çölleri yüklenip sırt sırt

Güneşe aydınlık zamanlar taşımada

Şakağına uzak değil güllerin

O eski ve kızıl kınalı Yesrib diyarı

Ve tespih diye seni çeken sufiler.

***

Aç hokkanı sürmele gözlerimi Asuman

Kına sür avcuna kutsal kapların

Seni çırpsın kanadında ankası diyarı Kaf’ın

Ve dudağından bal sızan gümrah hurmalar...

4/:

Yağmuruna yandım Asuman…

***

Sürüp kozmik kısrakların kaybolmaya yüz tutan eski izini

Ve takılıp peşine ulular ulusu bir kervanın

Gözlerim güneşte kavrulmada Asuman

Döndürüp kanlı Haleb’in arka yüzünü

Mızraklı muhafızlar kapıları omuzlamada…

Yarılsın işkembesi,

Savrulsun yıldızlardan ışıklı saman

Ve aç bin hörgücünden ilkini

Sahibi Salih olan devenin

Sade senin yağmuruna yandım Asuman

Yağmuruna ıslandım iliklerime kadar... 

***', '1/: Yağmuruna yandım Asuman… *** Gökler gürül gürül şimdi, Suyun kaderini kıraat etmede,  Evrende, bir kelebek kanadını çırpmış olmalı...  S...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":66,"source_url":"https://www.antoloji.com/00-asuman-a-postyagmurlama-00051-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '01 Bir Tren Garında Islandım Sana', '01-bir-tren-garinda-islandim-sana-ahmet-yozgat-7hj7s', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '1/:

Gürgen oturaklarla ısırılıp

Kurutup verimli vakitlerimi

Ardda kalanların önlerinden başlatıp

Demir paraleller sürerek dağ doruklarından

Nokta nokta teğet değip soğuk istasyonlara

Buharlı bir lokomatif gibi yorgun, aç, susuz

Ve nefes nefese ulaşıp diyarı sevdana

Bir tren garındaydım,

Islandım sana...

2/:

İleride bir yerlerdeydi güneşim sanki

Dağların yırtığında salt ipekten turaç ağları örüp

Düşüp upuzun izlerine Divriği develerinin

Ve ironik işaretlerine kalbimin çekimiyle

İçip çakıl taşlarını yağlı kesişmezlerin

Buharlara uzanıp inadına ve sırtüstü

Türküler ekerek paslı yollara

Bir tren garındaydım,

Islandım sana...

3/:

Çisentin konuştu penceremle evvela

Ardından katarlarla sözlendim

Belenip yarmalarda ak kürtüklere

Ve yaktığın ateşler ayasında dört nala

Apoleti bakırdan bir gar şefinin düdüğüyle silkinip

Üzgünüm, yorgun dudaklarım dayandı sona

Bir tren garındaydım,

Vuruldum sana...', '1/: Gürgen oturaklarla ısırılıp Kurutup verimli vakitlerimi Ardda kalanların önlerinden başlatıp Demir paraleller sürerek dağ doruklarından ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/01-bir-tren-garinda-islandim-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '01 Yoldaşımla Yaman Yolculuktayım', '01-yoldasimla-yaman-yolculuktayim-ahmet-yozgat-0e95b', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '1/:

Kulaç atıp zamanlar aralığından

Dayandık irisine kutuptaki maddenin

Üst yanımız ışık ve kandı...

Yüreğimizi bulutlara bağlayan dar koridorlar

Sevdalı baltalarla doğrandı.

Ben yandım yoldaş,

Seninle yolculuk ne de yamandı? ...

***

Düştü avucumdan toprağa ateş

Önümsıra uzanan bezgin ve lime lime ıstarlara asılıp

Silah silah sürgün dokuyan fenerler yandı

Kemirip ruhumu avlayan kapanları tek tek

Umudun ak serçeleri uçup arkadaş maviler havalandı.

Ben yandım yoldaş,

Seninle yolculuk ne de yamandı? ...

2/:

Yoldaşımın dokunup alnındaki gözüne

Rüyasına nokta düştüm demirden

Devrildi kavramların mahpus kulesi

Sabır doğruldu taş döşeli yerinden

Sabırsızca uykusundan uyandı.

Ben yandım yoldaş,

Seninle yolculuk ne de yamandı? ...

***

Saçlarımız sulu sepken ışıkları içmede

Dizkapaklarımız ise bir savaştan gelmiş gibi yaralı

Asabî paçalarımızsa masif ve ateşler içinde kızıl kandı

Yoldaşımla kolkola alfabenin döşünde

Her adımda yedi adım atarak

Çentik düşüp mevsimin şafağına ta geceden

Tabanımız çivi çivi doruklara uzandı.

Ben yandım yoldaş,

Seninle yolculuk ne de yamandı? ...

***

Yoldaşım yıldızlardan ejder sütü sağmada

Dört yanımız çeşit çeşit yabani hayvanlardı

Ben yandım yoldaş,

Seninle yolculuk ne de yamandı? ...', '1/: Kulaç atıp zamanlar aralığından Dayandık irisine kutuptaki maddenin Üst yanımız ışık ve kandı... Yüreğimizi bulutlara bağlayan dar korid...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/01-yoldasimla-yaman-yolculuktayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '01 Hummalı Hatıralar', '01-hummali-hatiralar-ahmet-yozgat-sb5qx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '1/:

Medet ya hakikat! 

Medet ey bencileyin insanlar...

Nerdesiniz ölümüne sevdiğim doru tenli kadınlar? 

***

Anıların hummasına tutulup

Takılmak var ya bir yazertesi...

Aç kanatlarını İrem’in sitemkar ebabili

Bekleyen bencileyin mabedin eşiğinde

Ne içinde kıymıklı ömrün koşarcasına

Ne de dışında ayazlarla sarmalanıp zemheride

Sisler ortasında ince ve uzun siluetimi içerek

Yok olmak hummasında anılar okyanusunun

Medet ya hakikat! 

Medet ey süt süzen şeffaf vildanlar.

Nerdesiniz ölümüne sevdiğim doru tenli kadınlar? 

2/:

Medet ya hakikat! 

Medet ey geceleri puanlayan eski ustalar…

Nerdesiniz ölümüne sevdiğim doru tenli kadınlar? 

***

Ve anılara kayıt tutan kalemdar

Kestirmeden süzülüp

Ve tüneyip sivri taşlarına eski kuşlukların

Sıtmalarla titreyen omzumu uzatıp geçmişe

Şakağımdan sızan ışık damlalarını sunmak

Bulut bir çamçak içinde lordlara

Dingin denizlerde kayıp o yazertesi

Damgalanmak esrik kapısında hummanın

Medet ya hakikat! 

Medet ey sınırları bekleyen yaşlı gılmanlar…

Nerdesiniz ölümüne sevdiğim doru tenli kadınlar?', '1/: Medet ya hakikat!  Medet ey bencileyin insanlar... Nerdesiniz ölümüne sevdiğim doru tenli kadınlar?  *** Anıların hummasına tutulup Takı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/01-hummali-hatiralar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kubbe', 'kubbe-altug-guler-tl781', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bak burası dünyanın çatısı

Bu elleri dünyanin, benimkiler değil

Benim ellerim başımın üstünde, ayaklarım altımdan kayıp gidiyor

Ayaklarım altımdan gidiyor, ellerim üstümden

Gidip duruyoruz, 

Karman çorman yokoluyoruz

Bu kadarcık işte dunya, amuda kalkıp yürüyoruz', 'Bak burası dünyanın çatısı Bu elleri dünyanin, benimkiler değil Benim ellerim başımın üstünde, ayaklarım altımdan kayıp gidiyor Ayaklarım al...', ARRAY['Türk Edebiyatı','Şiir','Altuğ Güler']::text[], 8.5, '{"poet":"Altuğ Güler","poet_slug":"altug-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kubbe-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Kuş Kadar Olamadım', 'bir-kus-kadar-olamadim-munevver-senol-kz66r', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her sabah balkonumda gugukçuk, gugukçuk diye öten.

                         Yusufcuk kuşu, senin bir adın da kumru değil mi? 

                         Eşine ne kadar bağlı sadık bir kuşsun ki sen.

                         Verdiğim yemi bile yanlız yiyemiyorsun.

                         Gugukçuk gugukçuk diye öterek onu çağırıp

                         O kırmızı boncuk gibi gözlerinle nede güzel bakıyorsun.

                          Çokta insancıl bir kuşsun yemi yerken kaçmıyorsun.

                           Eşini gaganla sevip hep başını okşuyorsun.

                           Birde ona nağme yapıp gugukçuk, diye ötüyorsun.

                           Muhabbetinize imrenmedim dersem yalan söylerim.

                           Ne yazık ki, bir kumru kuş kadar bile olamadım ben.

                           Ammaa, ben treni çoktan kaçırdım BOŞVERR.

                           Sizdeki mutluluğu artık yavrularımıza dilerim.

                            Benim güzel kumrularım yarın gene gelin emi? 

                            Ben burdayım sizi beklerim', 'Her sabah balkonumda gugukçuk, gugukçuk diye öten.                          Yusufcuk kuşu, senin bir adın da kumru değil mi?                ...', ARRAY['Türk Edebiyatı','Şiir','Münevver Şenol']::text[], 8.5, '{"poet":"Münevver Şenol","poet_slug":"munevver-senol","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bir-kus-kadar-olamadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '01 Yedi Adamın Yedi Öyküsü', '01-yedi-adamin-yedi-oykusu-ahmet-yozgat-wmxzl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '1/:

Yağmur adalet üzre yağıyordu

Islanıyorduk ahmakçasına yedimiz...

***

Yedi yol sıçrıyordu yedimizin önünde

Ve şerareler öpüyordu dizkapaklarını yedimizin

Yedi yaşımıza dek apaktık...

***

Kanıyordu… 

Boyalı kelebeklerin kanıyordu yıldızlı kanatları 

Sanal testereler harmandalına çökmüştü bir harmanda

Yedi yerinden dem tutuyordu yapraklar

Yadellerde yollar çatallanıyor

Yedi çata ayrılıyordu…

***

Ben diye biri; 

Yedi kez diz vurup üstündeki göklere

Yere çaktım çarmıhını beynimin

Ve öptüm yedi seçenekli kaderi kaş arasından

Kozmik efendilere “Lordum teslimim” dedim

İnanın yaptım imkansız olanı

Kendimi yedim...

2/:

Yedi çata ayrılıyordu tek yüzlü toprak

Yağmurun yağışı gayrı nedense,

Adaleti atmıştı kenara paslı zincirler gibi.

Yedimizin altısını çağırdı toprak iştahla,

Ta şafak atanda yedi tane yıldız.

***

Ve ben diye biriydim…

Kaldım yalnız ve yedi horantalı hanedanımla

Düştüm mısraların yedi yönlü labirentine

Tek başıma ve yedi kalem beynimle...

***

Çalıyordu…

Saatler çalıyordu marşını acı ölümün

Yedi bağlı botlarım kana bulanıyordu çamur yerine

Yedi kere yuvarlanıyordum yolları bir uçtan diğerine

Ve yedi kere bıçaklanarak sağ küreğimden.

Yağmur habire çeviriyordu Önümü arkama

Ve önümdeki takvim yapraklarını yedi kere.

Seller böğürüyordu,

Böğürüyor ve yedi kez yutuyordu kaderini.

Ve kendisini doğuran lohusa yaprakları yedi yerinden...

***

Ben diye biriydim…

Bu bilgelikle yedi kere kutsadım toprakları…

Yedi yere döktüm yedi lüleden kanımı kaselere

Öptüm kaderi yedi kaşı arasından

Kozmik efendilere “Lordum teslimim” dedim

Ve yaptım imkansız olanı

Kendimi yedim...

3/:

Yedi kez öpülüyordum alnımdan ilk durakta

Biz yedi adamdık çünkü.

Yüklenip altımızın kaderini birimiz

Düştük mısraların yedi gözlü labirentine

Yedi yol uzanmada şimdi sırt üstü

Ve yedi kere çağırmadaydı kendimi beynim.

Yedi koldan çekildim albasan bulutlara

Yedi kaderi yaşamak üzre tek başıma

Karıma yedi çentik attım

Gözümü tuzlasın diye terim...

***

Ben diye biriydim…

Yedi kutsal senaryoyu yedi kez yaşayıp düşlerimde

Öptüm kaderi kaş arasından yedi kez.

Kozmik efendilere “Lordum teslimim” dedim

Ve yaptım imkansız olanı

Ben diye birini yedim...', '1/: Yağmur adalet üzre yağıyordu Islanıyorduk ahmakçasına yedimiz... *** Yedi yol sıçrıyordu yedimizin önünde Ve şerareler öpüyordu dizkapak...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":70,"source_url":"https://www.antoloji.com/01-yedi-adamin-yedi-oykusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '01 İçtim Bir Tutam Güzelavrat Otu', '01-i-ctim-bir-tutam-guzelavrat-otu-ahmet-yozgat-vbphb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1/:

Bir temmuz ikindisiydi.

Pıtrak pıtrak yıldız ve cana batan ışıktı...

***

Yanıbaşımda yatan loğusa bir dilberdi,

Gözlerinde yağmur artığı bir nisan sürmesi...

Esmer dağ kızları yağıyordu saçlarıma apansız

Bir çobanaldatan mıydı öten uzaklarda bilmem? 

Belki de amazonlar hücumdaydı şahdamarımda.

***

Eşeleniyordu…

İbisler eşeleniyordu gözümün irisinde

Bir sarmaşık dolanıyordu arsız bir kükremeyle bileklerime

Ve içimdeki barok işlemeli dağarcık

Giriyordu şekilden şekle…

***

Vakit tamamdı sanırım! 

Çömelip bir temmuz seccadesine

Şiir ördüm deştizamandan bana miras kalan ipekle

İbisler eşeleniyordu gözümün irisinde.

Onların gerisinde pus ve buhur...

“Güzelavrat otu” içmiş gibicesine...

2/:

Bir kıyamet ikindisiydi.

Pıtrak pıtrak yıldız ve cana batan ışıktı...

***

Sanal şekliyle haki bir rahip somutlaştı önümde

Harmanisi sanırsam som sevdandandı

Çıkartıp boynundaki simli ve bir fenomen olan duayı

Secdelere kapandı seccademde

Sanal şekliyle haki bir rahip somutlaştı önümde.

***

Mor kısraklar eşindi samanyolunda ak sekilerle

Kıvılcımlar uçuştu ufkunda öksüzlerin

Baş kaldırdı heybemden kırık kavramlar

Büründü on bin şekle…

***

Vakit tamamdı sanırım

Bir temmuz seccadesine çömelip

Şiir ördüm deştizamandan bana miras kalan ipekle

Mor kısraklar eşindi samanyolunda ak sekilerle…

Onların gerisinde pus ve buhur...

“Güzelavrat otu” içmiş gibicesine...', '1/: Bir temmuz ikindisiydi. Pıtrak pıtrak yıldız ve cana batan ışıktı... *** Yanıbaşımda yatan loğusa bir dilberdi, Gözlerinde yağmur artığı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/01-ictim-bir-tutam-guzelavrat-otu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '01 Açıldı Güllü Kapı', '01-acildi-gullu-kapi-ahmet-yozgat-1wsp7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '1/:

Attı şafak, 

Hönkürdü sahib-i zeman, 

Açıldı baharın güllü kapısı…

İlk ben çırptım ateş kokan kanatlarımı,

Alaz, kor ve dumanlar diyarında...

Arkamdan mor zülüflü gılmanlar...

Dağlar teker teker

Sözler alaz içinde esrik

Ve yılgın bir göçün arta kalan damlası,

Savulun bre arsız zamanların katili hissiz dızmanlar, 

Savrulun alazlı yelde zebercet tınazkarı, 

Açıldı baharın güllü kapısı,

Şükür ki açıldı aşk,

Sevdaların pandorasının kapakçığı açıldı.

2/:

Şakladı kırbaç, 

Tınladi bir kadim lir, 

Açıldı baharın süslü kapısı…

Aç rüzgarlar aralayıp kalbimin yaşmağını

Ve bulutlardan kozmik haber dolu heybeyi

Sundu zamanların emzirdiği toprağa

Kıraç kahkülü ipeklendi sitemin

Ve doğrandı geçmişin kasvet tüten yapısı

Savulun bre kösnük zamanların katili hissiz albızlar

Açıldı baharın süslü kapısı,

Açıldı azami bir aşk,

Sevdaların pandorasının kapakçığı açıldı.

*', '1/: Attı şafak,  Hönkürdü sahib-i zeman,  Açıldı baharın güllü kapısı… İlk ben çırptım ateş kokan kanatlarımı, Alaz, kor ve dumanlar diyarın...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/01-acildi-gullu-kapi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '01 Yüreğim Delikanlı', '01-yuregim-delikanli-ahmet-yozgat-11w9c', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '1/:

Yaşlı bedenin delikanlı yüreği

Uzattı gözlerini bir türkünün üstüne...

***

Elleri badem çiçeğiydi.

Şakağının sahilinde durmuşta o balıkçı

Ağlıyordu her gece, her nedense

Utangaç ve esrik duygularını karanlıkta usulca

Bir yemen hançeri gibi sivriltip 

Canına bandığı dolunayların

Bir yoksul düş gibi titreyen

Ve delikanlı yüreğinin kerevetine

Yatırdığı cesedine öylece

Can denizinde cilveli

Ve dalından koparılmış ham meyveyi

Yalnızlığın acıkmış duygularına ısırtıp

Yaşlı bedenin

Dedenin

Ve ebenin

Ve de tüm huma kuşlarının şimdi

Delikanlı yüreği esmede ezoterik gülistanında evrenin...

2/:

Yaşlı bedenin delikanlı yüreği

Uzattı gözlerini bir türkünün üstüne...

***

Gözleri kiraz çiçeğiydi,

Elleri badem yaprağı fıstıki yeşil...

Yoruldu da yol üstüne oturdu.

Atlılar geçti kasavetinin ayak ucundan

Bu acundan

Yaşlı bedenin delikanlı yüreği geçti.

Bir nazlının ardından

Katılıp katarına telli özlemin

Yamalı türküler sokup ıslık cebine

Bata çıka içindeki çöllerin ta dibine

Ne bulduysa harmanında Leyla’nın

Alıp yanına

Tuz doğrayıp kanına

Ve bırakıp geride mahrem özgürlüğünü

İnce bir teslimiyet içindeyken çöl

“Öl artık yaşlı adam” dedi kendi kendine usulca

Ve kıydı canına...', '1/: Yaşlı bedenin delikanlı yüreği Uzattı gözlerini bir türkünün üstüne... *** Elleri badem çiçeğiydi. Şakağının sahilinde durmuşta o balıkç...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/01-yuregim-delikanli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gösterge Acısı', 'gosterge-acisi-altug-guler-6jv7l', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'I

Yüklüce bir kamyon taşır sessizliğimizi

Arkasında koşan çocuklar yok

Durduğumuz yer tam da durulacak bir yer

Okuyalım, yiyelim, ölelim burada

Ama çocuklar yok, kimse yok

Böyle aydınlık bir yere oturmuşuz işte

Böyle de kimsesiz duruyoruz

Iki adım atsak, iş oluş eylem bildireceğiz

Atmıyoruz, sessiz sessiz duruyoruz

Sıkışmış bir sevginin patlayışına tanık oluyoruz

II

Patlamak uzayın her köşesine dokunmayı getirir

Bu patlamak susuz bir patlamak, 

Önüne çıkan herşeyi içiverir

Yayılmaktan durulmaya geçerken bütün moleküllerim

Bu sefer şu üstümüzdeki bulut patlıyor

Saklanıp göç edip üstümüzde yarılıyor

Her bir damlası bile aşktan bu kadar sersemlemiş

Hepsi üstüme düşerken,

Seni gösteriyorum,

İbresi sona dayanmış bir göstergenin acısıyla

(Ankara, Mart 2006)', 'I Yüklüce bir kamyon taşır sessizliğimizi Arkasında koşan çocuklar yok Durduğumuz yer tam da durulacak bir yer Okuyalım, yiyelim, ölelim bur...', ARRAY['Türk Edebiyatı','Şiir','Altuğ Güler']::text[], 8.5, '{"poet":"Altuğ Güler","poet_slug":"altug-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/gosterge-acisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '01 Zaman Galerisinde Aşk', '01-zaman-galerisinde-ask-ahmet-yozgat-comby', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '1/:

Güleç yüzlü zamanlarla öpüştüm

Uzanıp dizlerine sıradağların…

***

Yüreğimde harlanan yekpare sevda

Topuğundan tutuşturdu ince belli taşları

Keman olup dudağı mevsimlerin

Gülkurusu türküleri ayırıp tel tel

Yeşille sürmeledi gelecek yarınların

***

Güleç yüzlü zamanlarla öpüştüm

Uzanıp dizlerine sıradağların.

2/:

Soylu rüzgarlarla girdim zifafa

Elimde duman saçlı bir kamçı...

***

Terkimdeyse unuttuğum tacı lordların …

Zaman galerilerinde gündüz gibi ışkları içerek

Yitirdiğim dünleri kovaladım bir süre

El yakan mevsimler ağladı az ardımda

Ben aslında kaçan bir kovalayandım

Yıldızlar doğurdu gökler kilim nakışlı

Karanlıkve yutucu ağzı yabanıl yamaçların

Hasret buhurlandı sonbaharlarda

Katran karası kazanında kasım ayının

Bindiğim küheylan ise kızıl ve yekpare kandı

Gecenin gündüzü boğduğu yerde 

Yetiştim katarların ardından ve katıldım safa

Gri renkli tampon pasajlara uzandım...

***

Soylu rüzgarlarla girdim zifafa

Elimde duman saçlı bir kozak kamçı…

3/:

Bir pulsar galerisinde tesadüfen tutundum

Yelesi ateş olan ışığın kısrağına…

***

Yularına kozmik boncuk dizdim çömelip

Uygun adım yürüyen haspa haftaların

Şımarık ve kırık havalar üfleyen günler

Yumuldu gözlerime birer birer iştahla

Bir yumak misali dolayıp ibrişim saatleri

Yalın veya mekansız bir diyarda yeniden açtım

Sabit ve boz bakışlı bir rahibe rastladım

Mekanını çantasında taşıyan

Öpüştüm güleç yüzlü ışıkla

Aktı dudaklarıma yürüdüğüm yolların kanı

Teslim ettim sahibine zamanı zamanında...

***

Bir pulsar galerisinde tevafuken tutundum,

Yelesi ateş olan ışığın kısrağına…', '1/: Güleç yüzlü zamanlarla öpüştüm Uzanıp dizlerine sıradağların… *** Yüreğimde harlanan yekpare sevda Topuğundan tutuşturdu ince belli taşl...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/01-zaman-galerisinde-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yargısız İnfaz', 'yargisiz-i-nfaz-murat-duman-nncrt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yargısız İnfaz                                      

Oturup karşıma, el gibi bakma,

Yüzünün halinden, perişan oldum,

Yargısız infazla, ilmeği takma,

Yüzünün halinden, perişan oldum…

                            Hele celallenme, otur yanıma,

                            Nefsine yenilip, girme kanıma,

                            Bir kez beni dinle, kıyma canıma,

                            Gözünün selinden, perişan oldum…

Dinlemeden beni, hançeri vurma,

Şu seven kalbimi, sebepsiz kırma,

Bilmeden, görmeden, günaha girme,

Sazının telinden, perişan oldum…

                             Renginden anladım, bu aşkı bitir,

                              İstersen kefensiz, mezara yatır,

                              Yaralı kalbimi, yanında götür,

                              Sözünün elinden, perişan oldum…

Ne söylesem bilmem, söz benim dersin,

Git de mutluluğu, gururun versin,

Muradın feryada, ummana ersin,

Özünün yelinden, perişan oldum…

                                    13.03.2006 ANKARA', 'Yargısız İnfaz                                       Oturup karşıma, el gibi bakma, Yüzünün halinden, perişan oldum, Yargısız infazla, ilmeğ...', ARRAY['Türk Edebiyatı','Şiir','Murat Duman']::text[], 8.5, '{"poet":"Murat Duman","poet_slug":"murat-duman","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yargisiz-infaz-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '01 Anam Ve Ateşin Zifafı', '01-anam-ve-atesin-zifafi-ahmet-yozgat-0tyue', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '1/:

İri iri yanıyordu.

Volkanlara sabitlenen kurtların gözü...

***

Ve iri iri yanıyordu

Gözleri, eşkiya sorgulayan bir yargıç gibi

Yalazlarla dans ediyordu anamın.

İri iri yanan tandıra bakıyordu ağlamaklı

Bir çıngı sıçrıyordu uzaya sekr durumunda

Bir yıldız kayıyordu saçından

İri iri yanan anamın gözleri ateşten resimler, 

Bozbulanık bozlaklar

Ve doludizgin şiirler çiziyordu dört koldan,

Babama sunmak için...

2/:

İri iri bakıyordu anamın seyyareli şakağı

Sanki tarhana vurmamıştı da kara kazana

Acılı geçmişini kaynatıyordu

Bir köşesinde ömrünün kendisi suskun

Ötekisinde lacivert gölgesi oynaktı

Ve orta yerde takvimleri yakan ateşti zalim

Küllerden güller fışkırıyor zira

Ve iri bir feliks yavrusu doğuyordu çığlık çığlığa

Anam ateşten güller devşiriyordu...

Babama sunmak için...

3/:

İri iri kabarıyordu deveran...

Anamın basireti burulmuş boğa misali yutkun

Tarhananın öfkesi çivi çiviydi Sümerelinde

Kızıl pelerinini çeviriyordu gürgeni piramit kalıplarının

Ve alınyazısı eviriyordu ateş zebanileri

Gözlerinde perilerle dans eden meşe

Sanki çalı çırpıyı değil de

Israrla elemlerini atıyordu anam ateşe...

Belki de ondan alev gülleri devşiriyordu

Anamın gözleri ateşten resimler, 

Bozbulanık bozlaklar,

Ve doludizgin şiirler çiziyordu dört koldan...

Babama sunmak için...

Bana sunmak için ise tarhana kaynatmada...', '1/: İri iri yanıyordu. Volkanlara sabitlenen kurtların gözü... *** Ve iri iri yanıyordu Gözleri, eşkiya sorgulayan bir yargıç gibi Yalazlarl...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/01-anam-ve-atesin-zifafi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '01 Şehzadem Hala Yeraltındaydın', '01-sehzadem-hala-yeraltindaydin-ahmet-yozgat-z62fi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1/:

Şehzadem...

Aylardan ya temmuz,

Ya da yedi kolu süreyya yıldızıydı...

Ben anamın rahminde beştaş oyunundaydım,

Yani yeni inmiştim babamın belinden barakama.

Arkama sarımsak, önüme soğan ekilmemişti daha.

Yıl dokuz yüz elli beşiydi milattan öncenin,

Gecenin ayak ucunda,

Başucundaydım gündüzün...

***

Şehzadem...

Akasyalar şıkırdım şıkırdımdı

Yan yatan temmuz sabahında…

Şehzadem,

Kalubeladan beri yeraltındaydın sen

Henüz maviye çalıyordu anamın ak sütü

Gökyüzü pamuk pamuk köpürüyor

Ve çalınan mavisine bakıp türkü ağlıyordu

Oysa bendim o garip türküleri dokuyan

Çıkıp çıkıp orta yerinden bozlaklarımın

Ondandı ağıtlı gözleriyle bozkır yiğitlerinin

Sitemkâr yüreğimi avuçlaması...

***

Şehzadem...

Hala yeraltındaydın sen…

İbrahim’im cenbiyye vuruyordu o kadim taşa

Sevdanın ırgatları bir cıgara nefeslenip

Bir ilkbahar ilmikliyorlardı kozmik kışa...

2/:

Az evvel doğranmıştı elem

Kanına Kerem’in ve tüm sevda ırgatlarının…

***

Şehzadem...

Masif taştan ve kandan oyma bir mağarada,

Yani yeraltındaydın sen

Boylu boyunca uzanıp yanıma

On kurşun atımı aydos çeken kırlarda

Sahtiyan urbalı ve dağlı bir uğru

Soğuk ateşlere banıyordu dudaklarımı

Sakin şaklatıyordu ağzını anam ve avradım

Oysa erotik bir ilkbahardı yürek ıstarlarında dokunan

Hınzır zirvelerine kosnük dağların

Bense en haki yeşilinden bozlak çekiyordum

Ve hiyeroglif motifler döşüyordum üstümdeki kumaşa

Sevdanın ırgatları bir cıgara nefeslenip

Bir ilkbahar ilmikliyorlardı kuantik kışa...

Şehzadem...

İnanmasan da hala yeraltındaydın sen…

3/:

Uzakta bir deryada iskele alabandaydı, 

Yani Babil’de itler uluşuyordu

Dinleyip dinleyip mübarek ezanları…

Şehzadem...

İnandın sonunda sanırım hala yeraltındaydın sen

Sevdanın ırgatları bir cıgara nefeslenip

Bir ilkbahar ilmikliyorlardı ya gnostik kışa

Davul zurna ise Köroğlan ezgisi vuruyordu

Ben mütemadiyen sevda demliyordum

Heybem şiirle doluyordu lebalep

Irgatlarsa gün yorgunuydu

Şehzadem...

Maalesef hala yeraltındaydın sen

Ak çiçekler ve yorgun ırgatlar

Habire soluyor

Soluyor

Soluyordu...

Durmuştu akasyalar Çorum halayında en başa

Sevdanın ırgatları bir dudak nefeslenip

Bir ilkbahar ilmikliyorlardı Vildani aşka

Şehzadem hala yeraltındaydın sen,

Ama benim sevişme vaktim gelmişti…', '1/: Şehzadem... Aylardan ya temmuz, Ya da yedi kolu süreyya yıldızıydı... Ben anamın rahminde beştaş oyunundaydım, Yani yeni inmiştim babamı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yozgat']::text[], 8.5, '{"poet":"Ahmet Yozgat","poet_slug":"ahmet-yozgat","theme":"Türk Şiiri","is_hero":false,"total_lines":72,"source_url":"https://www.antoloji.com/01-sehzadem-hala-yeraltindaydin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İslamın Güneşi H.Z Muhammed', 'i-slamin-gunesi-h-z-muhammed-murat-duman-hg468', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '1                                        

Putlara son vererek, küfre zehir içtiren,

Kâinatın nebisi, Muhammed Mustafa’dır, 

Cennetin kapısını haznedara açtıran,

İki cihan serveri, Muhammed Mustafa’dır…

   2   

O bir rahmet kapısı, kula şefaat kılan,

Köleliğe son verip, müminlerde can bulan,

Öksüz ile yetimin, gözlerinden hem silen,

Âlemin efendisi Muhammed Mustafa’dır…

3

Yaratmadan dünyayı, sevgiyle yaratılan,

Medine savaşında, dünyası karartılan,

Ticaret yapmak için, kervanlara katılan,

Nebiler efendisi, Muhammed Mustafa’dır…

4

Peygamberlik mühürü, altın harfle kazılan,

Ümmetinin derdine, gece gündüz üzülen,

Semaya yükselerek, gönüllere süzülen,

Miraca vasıl olan, Muhammed Mustafa’dır…

5

Yarab aciz kalmışım, yazmıyor ki; kalemim,

Bir meczubun elinden, artar gider elemim,

Cehaletin yurduna, eksik olsun selamım,

Cahilli kurtaracak, Muhammed Mustafa’dır…

5

Yalnız ona ümmetim, olurum ona turab,

Dil bilmez ilimsizim, sen kurtar beni yarab,

Muhammed’in yolunda, şu canım olsun harap,

Murat’ın mihmandarı, Muhammet Mustafa’dır…      

                                             04.02.2006 ANKARA', '1                                         Putlara son vererek, küfre zehir içtiren, Kâinatın nebisi, Muhammed Mustafa’dır,  Cennetin kapısın...', ARRAY['Türk Edebiyatı','Şiir','Murat Duman']::text[], 8.5, '{"poet":"Murat Duman","poet_slug":"murat-duman","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/islamin-gunesi-h-z-muhammed-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Devran (Mâniler 2)', 'devran-m-niler-2-zeynal-yaman-nm8yn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kara kara bulutlar

Suya düştü umutlar

Gözde ithal tavuğu

Fitne-yalan yumurtlar 

Neden böyle dünyamız

Uçtu gitti hülyâmız

Maymun oldu baş tacı

Yılan-çıyan rüyamız

Milli devlet yerildi

İpler yâda verildi

Asırlık çınarımız

Kökten yere serildi

Nasıl oldu bilinmez

Bizim olan sevilmez

Küfür açtı bayrağı

Bayrak için ölünmez

Ne denir bu gidişe

Sokak sokak...

İffet mizah olunca

Kadın-erkek afişe

Köşe dönmek hüneri

Sıktırıyor kemeri

Eşekler sultan oldu

Sırtımızda semeri

Bu ne biçim illettir

Ziyan olan millettir

Devran böyle giderse

Başa gelen zillettir

1988-Çatalca', 'Kara kara bulutlar Suya düştü umutlar Gözde ithal tavuğu Fitne-yalan yumurtlar  Neden böyle dünyamız Uçtu gitti hülyâmız Maymun oldu baş tac...', ARRAY['Türk Edebiyatı','Şiir','Zeynal Yaman']::text[], 8.5, '{"poet":"Zeynal Yaman","poet_slug":"zeynal-yaman","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/devran-maniler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '**Yalan DÜNYA*', 'yalan-dunya-zernisan-aydogan-eyazl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Nasıl seveyim  ki ben seni dünya

Gündüzüm bir başka gecem bir başka

Boşlukta sallanıyor bu yüreklerin

Gerçeğin bir yanda.yalan bir yanda

İnsanlar acıyla yoğrulmuş durmuş

Bir lokma ekmeğin peşinden koşmuş

Olan gariplere yetime olmuş

Zenginin bir yanda.fakir biryanda

Gülüşler hüzünlü bakışlar donuk

Neşeler tükenmiş nerde mutluluk

Türlü türlü dertler ile yoğrulduk

Tebessüm bir yanda.hüzün biryanda

Ömür dediğimiz bir kısa yolmuş

Neşeyle.hüzünle dertle doluymuş

Bu dünyadan göçüp gidenler çokmuş

Ölenler bir yanda.sağlar biryanda

Yalan dünya senden bıktım usandım

Süslü püslü cazibene aldandım

Başımı çevirip çevreme baktım

Doğrular bir yanda.yanlış biryanda

                     23.3.2006 /  Erzurum

                                  Zernişan', 'Nasıl seveyim  ki ben seni dünya Gündüzüm bir başka gecem bir başka Boşlukta sallanıyor bu yüreklerin Gerçeğin bir yanda.yalan bir yanda İns...', ARRAY['Türk Edebiyatı','Şiir','Zernişan Aydoğan']::text[], 8.5, '{"poet":"Zernişan Aydoğan","poet_slug":"zernisan-aydogan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yalan-dunya-44-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doyamadım', 'doyamadim-nevin-aydogan-yf6hz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yaşamak istiyorum

sevgiye doyamadım

neşeye, mutluluğa doyamadım

Yaşamak istiyorum

Gözlerim doluyor bir anda

ömrüm geçiyor

Hiç birşeye doyamadım,

doyamadan öleceğim...

                    10 eylül 1979', 'Yaşamak istiyorum sevgiye doyamadım neşeye, mutluluğa doyamadım Yaşamak istiyorum Gözlerim doluyor bir anda ömrüm geçiyor Hiç birşeye doyama...', ARRAY['Türk Edebiyatı','Şiir','Nevin Aydoğan']::text[], 8.5, '{"poet":"Nevin Aydoğan","poet_slug":"nevin-aydogan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/doyamadim-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-sefika-celik-1vayp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Biliyor musun? 

Ben seninle yeniden hayata bağlanıyorum.

Sanki uçurumun kenarındayım,

Sıkı sıkı tutunmuşum taşlara

Bir dal arıyorum elimi uzatacak

İşte sen uzatıveriyorsun ellerini bana.

Ve hem hayata hem sana erişmenin mutluluğunu duyuyorum.

Anlam kazanıyor bazı şeyler,ki bu şeylerin içinde yaşama isteğide var.

Gökyüzünün mavi olduğunu o an hissediyorum.

Denizin o eşsiz ferahlığı o an vuruyor yüzüme.

Herşey bitiyor sen başlıyorsun sanki

Sen, sen, sen,

Senle başlayıp senle bitiyorum.

Aldığım nefesin adına senin ismini veriyorum.

Acı çekiyorum yüzüne her baktığımda

Öyle bir acı ki boğazımı yakıyor 

Seni seviyorum diye bağırmak istiyorsun tüm dünya duysun.

Ama sesim çıkmıyor kendimden bile saklıyorum seni. 

					                          (23.03.06)', 'Biliyor musun?  Ben seninle yeniden hayata bağlanıyorum. Sanki uçurumun kenarındayım, Sıkı sıkı tutunmuşum taşlara Bir dal arıyorum elimi uz...', ARRAY['Türk Edebiyatı','Şiir','Şefika Çelik']::text[], 8.5, '{"poet":"Şefika Çelik","poet_slug":"sefika-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sen-795-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutulmuş', 'unutulmus-nevin-aydogan-gt3k0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Unutmak var

özlemli bir yol sonunda

Kavuşmak var; hiç tadılmamış

Bir şarkı geliyor aklıma

çok dinlenmiş, ağlanmış

yeminler edilmiş üzerine

ama... unutulmuş.

                

                   11 eylül 1980', 'Unutmak var özlemli bir yol sonunda Kavuşmak var; hiç tadılmamış Bir şarkı geliyor aklıma çok dinlenmiş, ağlanmış yeminler edilmiş üzerine a...', ARRAY['Türk Edebiyatı','Şiir','Nevin Aydoğan']::text[], 8.5, '{"poet":"Nevin Aydoğan","poet_slug":"nevin-aydogan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/unutulmus-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilinmezki', 'bilinmezki-nevin-aydogan-3k3zc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tüm bekleyişler sonunda

gün olur kapkara umutsuzlukta

pişmanlık başlar ayrı dünyalarda

Bilinmezki; 

sonsuzdur her bekleyiş

boşunadır pişmanlık, ağlayış

duyguların bittiği yerde

bir sondur o

biten her yaşam gibi...', 'Tüm bekleyişler sonunda gün olur kapkara umutsuzlukta pişmanlık başlar ayrı dünyalarda Bilinmezki;  sonsuzdur her bekleyiş boşunadır pişmanl...', ARRAY['Türk Edebiyatı','Şiir','Nevin Aydoğan']::text[], 8.5, '{"poet":"Nevin Aydoğan","poet_slug":"nevin-aydogan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bilinmezki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Emanet ediyorum', 'emanet-ediyorum-ayse-adlim-4399q', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevdiklerimi

Sana emanet ediyorum

Kendimi de

Şefkatini, sevgini

Bizden esirgeme

Varsın takmayayım

Telli duvağını

Varsın olmayayım

Asker anası

Varsın yarım kalsın

Dünyanın tadı

Yeter ki Sen iste

Sana boynum 

Kıldan ince

Korku değil

Heyecan içimde

Giyinir gelinliğimi

Gelirim seve seve', 'Sevdiklerimi Sana emanet ediyorum Kendimi de Şefkatini, sevgini Bizden esirgeme Varsın takmayayım Telli duvağını Varsın olmayayım Asker anas...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Adlım']::text[], 8.5, '{"poet":"Ayşe Adlım","poet_slug":"ayse-adlim","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/emanet-ediyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sitemkar', 'sitemkar-abdulhakim-ozturk-k9fxk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'SİTEMKAR

Dostlar meclisinde maddiyat olmaz

Temeli manevi duygu kaybolmaz

Gönül dostlarının çiçeği solmaz

Tahrip edilince sitem ederim.

İyi günde çokmuş seni anlayan

Kötü günde yoktur seni arayan

Anladım ki kalmamış dosta ağlayan

Mazide geçen günlere sitem ederim.

Kararsızlıkların tümü dünyada

Umutsuzluk meydanı rüyada

Yarını olmayan durur bir köşede

Manevi yol tahrip edilince sitem ederim.

Aramızda uzun sıra dağlar

Hasretin günlümü dağlar

Haberin almazsam yüreğim ağlar

Arayıp sormazsan sitem ederim.

		Abdulhakim ÖZTÜRK

			2006', 'SİTEMKAR Dostlar meclisinde maddiyat olmaz Temeli manevi duygu kaybolmaz Gönül dostlarının çiçeği solmaz Tahrip edilince sitem ederim. İyi g...', ARRAY['Türk Edebiyatı','Şiir','Abdulhakim Öztürk']::text[], 8.5, '{"poet":"Abdulhakim Öztürk","poet_slug":"abdulhakim-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sitemkar-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* Bana Gitmek Göründü *', 'bana-gitmek-gorundu-i-brahim-dikmen-2-z5npx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dün gece

seni gördüm sahilde

bir yabancıyla 

geziyordun el ele

içimden

birşeyler koptu o'' an

seni ah! 

seni başkasıyla görünce

Aşk''a! 

iki damla yaş döküldü

gözlerim

karanlığa gömüldü

yüreğim

acılara büründü

bu şehirden

artık bana

gitmek göründü.

23/03/2006', 'Dün gece seni gördüm sahilde bir yabancıyla  geziyordun el ele içimden birşeyler koptu o'' an seni ah!  seni başkasıyla görünce Aşk''a!  iki d...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Dikmen 2']::text[], 8.5, '{"poet":"İbrahim Dikmen 2","poet_slug":"i-brahim-dikmen-2","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bana-gitmek-gorundu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türküler', 'turkuler-yusuf-ter-bt17x', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İki dağ arası geçit 

bir nehir, coştukça coşuyor

Avuçlara sığmıyor düşler.

Ne şiirler söylüyor toprak. 

Ne de üzerini  örtüyor türküler. 

yeşermiş çayır, çimen,

Börtü böcek bayrama durmuş

Nehir, 

Yırtılmıyor büyüyor,

İçimizdeki çocuk gibi.

Kırlangıçlar gebe, 

Sıvıyor çamuru.

Ne şiirler söylüyor toprak. 

Ne de üzerini  örtüyor türküler. 

Yusuf Ter 23.03.06

Saat 00:15 İsviçre', 'İki dağ arası geçit  bir nehir, coştukça coşuyor Avuçlara sığmıyor düşler. Ne şiirler söylüyor toprak.  Ne de üzerini  örtüyor türküler.  ye...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ter']::text[], 8.5, '{"poet":"Yusuf Ter","poet_slug":"yusuf-ter","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/turkuler-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bunlar Neyin Peşinde', 'bunlar-neyin-pesinde-yusuf-onder-bahceci-d5olz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni seven gözlerim ağlasa ne olur ağlamasa ne,

Benim kâlbim ağlıyor, sen nerden bileceksin kele,

Etrafıma toplanmış bir sürü düzenbaz hepsi vekile,

Vekile sırıtıyor, sırıtmalarında bilene var, binbir hile.

Bu insanlar neyin peşinde kimin eli kimin cebinde,

Adam rahat edemiyor neden bir türlü meskeninde,

Gasp edenleri gasp etmek mi gerekir bedenin de,

Benim kâlbim ağlıyor, sen nerden bileceksin kele.', 'Seni seven gözlerim ağlasa ne olur ağlamasa ne, Benim kâlbim ağlıyor, sen nerden bileceksin kele, Etrafıma toplanmış bir sürü düzenbaz hepsi...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bunlar-neyin-pesinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıyaslama', 'kiyaslama-ayse-adlim-xbedz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Benim sevgim ölçülmez

Hiçbir değerle

Ne bir soruya cevap

Ne de ölümle

Kıyaslama sakın

Başka biriyle', 'Benim sevgim ölçülmez Hiçbir değerle Ne bir soruya cevap Ne de ölümle Kıyaslama sakın Başka biriyle...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Adlım']::text[], 8.5, '{"poet":"Ayşe Adlım","poet_slug":"ayse-adlim","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kiyaslama-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Hiç Ablam Olmadı ki', 'benim-hic-ablam-olmadi-ki-bilal-aydinli-2sik1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Soğuk ilkokul sıralarında tanıştım bu kelimeyle

Arkadaşlarım, öğretmenim beni ablam okula getirdi

Saçlarımı ablam taradı,ödevimi ablam yaptı derlerdi

Ben de sınıfın en arka sırasında saatlerce ağlardım

Benim hiç ablam olmadı ki

Marketin önünden geçerken,bir abla kardeşine sakız,şeker alırdı

Benim sakız alacak  ablam hiç olmadı

Eve gidince saatlerce ağlardım,gözyaşımı silen olmazdı

Saçlarımı okşayacak bi ablam olmadı

Annesiz babasız büyüdüm,abla nedir bilmedim

Saçlarımı babaannem ördü, ödevimi dayım yaptı

Ne saçlarım ne ödevim, arkadaşlarımın ki kadar güzel olmadı

Okula giderkende ağladım saatlerce

Benim hiç ablam olmadı ki', 'Soğuk ilkokul sıralarında tanıştım bu kelimeyle Arkadaşlarım, öğretmenim beni ablam okula getirdi Saçlarımı ablam taradı,ödevimi ablam yaptı...', ARRAY['Türk Edebiyatı','Şiir','Bilal Aydınlı']::text[], 8.5, '{"poet":"Bilal Aydınlı","poet_slug":"bilal-aydinli","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/benim-hic-ablam-olmadi-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlamazlar', 'anlamazlar-ayse-adlim-05sdg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne anlar

Ağaçların sesinden

Kuşların ötüşü

Kavuran güneş

Dökülen terden

Gecenin karanlığı

Pırıl pırıl gökyüzü

Ay ışığı

Ne anlar bunlardan

Hiç hasret çekmeyen', 'Ne anlar Ağaçların sesinden Kuşların ötüşü Kavuran güneş Dökülen terden Gecenin karanlığı Pırıl pırıl gökyüzü Ay ışığı Ne anlar bunlardan Hi...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Adlım']::text[], 8.5, '{"poet":"Ayşe Adlım","poet_slug":"ayse-adlim","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/anlamazlar-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kitapsiz Yaaaaaaar', 'kitapsiz-yaaaaaaar-yasar-gurlek-o2c23', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aglamami yanmami istemezdin yaaaaaaar

Neden simdi bu dunyayi eyledin daaaaaaar

Ne yalanlar uydurup soylersin  yaaaaaaar

Yokmu sende hic utanma birazcikde aaaaaaar

Hani  beni  seviyordun sevmezdin baska

Yalanlarla  nasilda,  dustum!   bu    aska

Cok duskundum guzelim sevgiye  meske

Yokmu sende hic utanma vijdansiz yaaaaaaar

Dolar iken kollarini   benim  boynuma

Cok inandim guvendim geldim  oyuna

Lanet   olsun  senin    aslin   soyuna

Yokmu  sende hic  utanma insafsiz  yaaaaaaar

Yasar! i  ye  dolastirdin  derdi  belayi

Unutturdun silada   bacim   anayi

Bilmeden  sevmisim  gozu  elayi

Yokmu  sende hic  utanma kitapsiz  yaaaaaaar

23-03-2006

ROTTERDAM

HOLLANDA', 'Aglamami yanmami istemezdin yaaaaaaar Neden simdi bu dunyayi eyledin daaaaaaar Ne yalanlar uydurup soylersin  yaaaaaaar Yokmu sende hic utan...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Gürlek']::text[], 8.5, '{"poet":"Yaşar Gürlek","poet_slug":"yasar-gurlek","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kitapsiz-yaaaaaaar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güncel Beyitler 96', 'guncel-beyitler-96-huseyin-avdic-ex18j', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dönen Ve Dönü$en Dünya

