INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doruklardan Bakayım', 'doruklardan-bakayim-yusuf-onder-bahceci-5shj9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'En yüksek dağ hangi dağ sorayım da çıkayım,

Doruklardan sevdiğime bir bakayım, bakayım,

Doruklar da Hak''ka yakın olup çok yalvarayım,

En yüksek dağ hangi dağ sorayım da çıkayım,

Doruklardan sevdiğime bir bakayım, bakayım...', 'En yüksek dağ hangi dağ sorayım da çıkayım, Doruklardan sevdiğime bir bakayım, bakayım, Doruklar da Hak''ka yakın olup çok yalvarayım, En yük...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/doruklardan-bakayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ateşine Yandım Yâr', 'atesine-yandim-y-r-tulay-sustam-92yzm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'âh o kirpiklerin 

gözlerinin sarmaşığı

bilirim! ...

tutunmasam 

gözlerinden yıldız gibi kayarım 

âh o dudağın

tenimin yanan ateşi

bilirim! ...

öpmesem 

güneş gibi batarsın

geceme yağmur gibi yağarsın

âh o gamzelerin

elmacık kemiğinin gecekondusu

bilirim! ...

dokunmasam

direksiz ev gibi yıkılırsın

yüreğimi bir çığın altında bırakırsın

ateşine yandım yâr! ...

bensiz kapama gözlerini

kirpiklerinin birbirine değişi 

yüreğimde bir fırça darbesi', 'âh o kirpiklerin  gözlerinin sarmaşığı bilirim! ... tutunmasam  gözlerinden yıldız gibi kayarım  âh o dudağın tenimin yanan ateşi bilirim! ....', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/atesine-yandim-yar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anla', 'anla-zahide-handan-erengil-yund2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yıllar var ki unutmadım,

Sevgini içimden atamadım.

Saygı gösterdim aşkın anısına,

Aldırmadım kanayan yarasına.

Uydum koyduğum yasaklara.

Açmadım kalbimi yeni aşklara.

Çabalarken unutmak için,

Neden çıktın,karşıma niçin? 

Değişmeyen huyunla kendine has,

Herşey yine eski hamam,eski tas.

Yaşanan güzel günlerin hatırına,

Çek hayalini karşımdan allah aşkına,

Gittikçe uzaklaşsın yankılanan sesin,

Kaybolsun hafızamdan ismin silinsin.

Bu sevda ikimizi de yordu,

Uzlaşmak, unutmak en iyi yoldu,

Karar ver gönlüm,canıma yetti,

Anla diyorum anla, bu sevda bitti.', 'Yıllar var ki unutmadım, Sevgini içimden atamadım. Saygı gösterdim aşkın anısına, Aldırmadım kanayan yarasına. Uydum koyduğum yasaklara. Açm...', ARRAY['Türk Edebiyatı','Şiir','Zahide Handan Erengil']::text[], 8.5, '{"poet":"Zahide Handan Erengil","poet_slug":"zahide-handan-erengil","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/anla-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mübarek olsun...', 'mubarek-olsun-reyhan-tataroglu-f7vlm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bugün

                                      başka mutluyum

                                      bugün

                                      başka bir sevinç

                                      yine hutbede

                                      ''''Sen''''

                                      ben,Sende bir hiç', 'bugün                                       başka mutluyum                                       bugün                                      ...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Tataroğlu']::text[], 8.5, '{"poet":"Reyhan Tataroğlu","poet_slug":"reyhan-tataroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/mubarek-olsun-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acıya Saplanan', 'aciya-saplanan-i-brahim-soyalar-9d4hc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Miğferinde kan var sevgili düşman… 

Daha dün ihtirasla sevgilini sarıyordu

Beni vuran, bedenimi parçalayan,

Başımı gövdemden ayıran ellerin…

Şefkatle okşardı çocuklarının başını,

Yürekli sevmelerin derin sıcaklığında.

Alnından süzülerek inip pıhtılaşmış kan

Aslında yanıp kül olan yüreğinin sızısı,

Biliyorum evet, ne desende görüyorum

Sende insansın, diğerleri de olduğu gibi,

Seninde bir çift gözün, nasırlı iki elin

Çarpan tek bir yüreğin var benim gibi.

Unutamayıp sığdıramadığın hasretlere

Avuçlarında erittiğin kor sevdaların, 

Seninde boynuna sarılan çocukların var

Biliyorum, aynı duygulardasın sende,

Seni benim, beni de senin karşına çıkaran                   

İblislere karşı dengesi kıt yeryüzünde.

Hangi köhne duvarda bıraktın hayallerini

Hangi meyhanelerde tükettin umutlarını,

Biliyorum gözünün bebeğini oyarken ben                                              

Kararttığım kendi geleceğim farkındayım,                 

Aslında kendi ruhumu satıyorum şeytana

Karanlık gecelerinde şu kirli zamanın.

Soluksuz bırakıp ta bedenimin derininden

Kanlı ciğerimi yerinden sökerken sen,

Yüzüme vurduğun her öldürücü darbede

Aynı gözyaşını döküyorsun benim gibi,

Yolunu gözleyen aileni düşünüyorsun hep    

Eşini, çocuklarını, ananı, babanı, kardeşini…

Anlayabilseydin, zaten bir anlayabilseydin

Bizi bize kırdıran bu düzenin sömürüsünü, 

Birbirimizi boğazlatan hasta duyguyu

Seninle iki çift laf ediyor olurduk dostça,

Muhtemelen mavi renge çalan dalgalarda

Günbatımı, deniz kıyısında muhabbette.

Bana zulmederken imkânsız işkencelerde

Başucumda vururken cansız bedenime,

Vicdanın ne kadar rahat bilemiyorum

Basıp geçerken postallarınla cesedime,

Rahat uyuyabilecek misin ayaz gecelerde

Kâbusların yalnız bırakacak mı seni hiç.

Ama sen sabırlı ol, hiç merak etme…

Issızlığın içinde kör kurşunun izinde,

Birisi az ötede aynı benim siluetimde 

Üzerinden basıp geçecek hayatının,

Hey sen düşman… Haydi durma…

En son bıraktığın yere git hayallerinin.', 'Miğferinde kan var sevgili düşman…  Daha dün ihtirasla sevgilini sarıyordu Beni vuran, bedenimi parçalayan, Başımı gövdemden ayıran ellerin…...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Soyalar']::text[], 8.5, '{"poet":"İbrahim Soyalar","poet_slug":"i-brahim-soyalar","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/aciya-saplanan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Sevdiğim 2', 'benim-sevdigim-2-sahin-yilmaz-o9isc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İster Ayşe, ister Selma,

Evvela insan olmalı.

Yanakları kızıl elma,

Kaşları keman olmalı.

Vatana, millete aşık,

Bir de sallamalı beşik,

Gözlerinde dokuz ışık,

Kalbinde iman olmalı.

Türklük şerefiyle dolup,

İslamî terbiye alıp,

Yaratana teslim olup,

Ne şek, ne güman olmalı.

Kurmak için mutlu hane,

Ter dökmeli tane tane.

Evinde şefkatli anne,

Düşmana yaman olmalı.

Allah’ın emrini duyup,

Kelleyi koltuğa koyup,

Emr-i bil marufa uyup,

Kitabı Kur’an olmalı

Yanlış şeyler ünlemeden,

Cahilleri dinlemeden,

Koşmamalı anlamadan,

Elinde ferman olmalı.

Emredince kutsal dini,

Feda eylemeli canı,

Damarında Türk’ün kanı,

Tam bir Müslüman olmalı.', 'İster Ayşe, ister Selma, Evvela insan olmalı. Yanakları kızıl elma, Kaşları keman olmalı. Vatana, millete aşık, Bir de sallamalı beşik, Gözl...', ARRAY['Türk Edebiyatı','Şiir','Şahin Yılmaz']::text[], 8.5, '{"poet":"Şahin Yılmaz","poet_slug":"sahin-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/benim-sevdigim-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Detay', 'detay-zati-erbas-tl6ln', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hep şiir olmaz birazda seramik sunmak istedim size

sevgiyle kalın', 'Hep şiir olmaz birazda seramik sunmak istedim size sevgiyle kalın...', ARRAY['Türk Edebiyatı','Şiir','Zati Erbaş']::text[], 8.5, '{"poet":"Zati Erbaş","poet_slug":"zati-erbas","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/detay-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüzleşme', 'yuzlesme-i-brahim-soyalar-kxebn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Acıların üstüne kan bastığında

Dağılırsın serpilirsin derinlere,

Omzunda ağır yük kaldıramazsın.

Uçup giden ellerinden ötelere

Yanından süzülen yumuşaklığı,

Uzanıp aşkı yakalayamazsın.

Gençliğin savrulur beyazlıklara

Çırpınarak uzatırsın ellerini,

Kırılır dalların tutunamazsın.

Ummadığın bir anda ve yerde

Zaman gelir yüzleşirsin kendinle,                       

Hüzünle sevdanda donuklaşırsın.', 'Acıların üstüne kan bastığında Dağılırsın serpilirsin derinlere, Omzunda ağır yük kaldıramazsın. Uçup giden ellerinden ötelere Yanından süzü...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Soyalar']::text[], 8.5, '{"poet":"İbrahim Soyalar","poet_slug":"i-brahim-soyalar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yuzlesme-111-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eve Dönüş Hikayesi', 'eve-donus-hikayesi-kiymet-sonmez-hntif', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gece yürünmez oldu sokaklarda,

Çıkmak zorunda kalırsanda,

Gözü dönmüş kişiler,

Bıçak çekiyorlar sokak ortasında,

Delikanlı olduklarını sanıyorlar bu zavallılar,

Kendi yüreksizliklerine bıçakla destek buluyorlar,

Uyuşturucudan yalpalıyorlar yürürken,

Ama sokakta insanlara bıçak çekiyorlar.

Para bulmak için,

Elindeki naylon torbaya saldırıyor,

Ne olacaksa içinde gecenin o vaktinde

Yanında gezdirdiğin köpeğe saldırıyor,

O ona dişini bile göstermediği halde

Tekme atmaya kalkıyor birden,

Kendimi önüne atıyorum,

Delikanlımısın sen diye haykıyorum,

Birden bıçağı çıkarıyor,

Asıl korkak sensin diyorum,

Kendi başına yapamadığını bıçakla yapmaya çalışıyorsun,

Adam  birden bıçağı beline soktu,

Ve özür diledi benden,

Evet özür diledi.

Birden o saldırgan adam,

Süklüm püklüm biri oldu.

Yanındaki arkadaşı aldı götürdü onu.

Gerçekten Allah korudu bizi.

Bu gece eve dönüşümüz böyle oldu.

Belki dönemeyebilirdikte....

‘’Büyük şehirlerde artık önlenemez hale gelmiş, uyuşturucu, bunun sebep olduğu kapkaç herkesin hayatını tehdit eder hale gelmiştir.Günün her saatinde nerde karşınıza çıkacağı belli değil, sade vatandaşın buna nasıl önlem alacağı ise hiç belli değil. Onlarda bıçak vs mi taşıyacak yanlarında.Güzelim ülkemde bir nefes almak için sokağa çıkamadıktan sonra....’’', 'Gece yürünmez oldu sokaklarda, Çıkmak zorunda kalırsanda, Gözü dönmüş kişiler, Bıçak çekiyorlar sokak ortasında, Delikanlı olduklarını sanıy...', ARRAY['Türk Edebiyatı','Şiir','Kıymet Sönmez']::text[], 8.5, '{"poet":"Kıymet Sönmez","poet_slug":"kiymet-sonmez","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/eve-donus-hikayesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecelik Aşk', 'gecelik-ask-yasar-tezel-t9di6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Geceyi öpüşlerimizde gizemler

Tüm renklerin dilinde gece

Görünmezi görür,renkler çözülünce

Yarasaları sırtımızda taşırız

Açlık hislerimizide alır

Korkular,rüyalarımızı sel alır

Duyulmaz hep karanlığa ağlayışlarımız

Unutulmuşlar dünde kalır

Geceyle aşkımızda biter

Gecesi olmayan yer benim ülkem', 'Geceyi öpüşlerimizde gizemler Tüm renklerin dilinde gece Görünmezi görür,renkler çözülünce Yarasaları sırtımızda taşırız Açlık hislerimizide...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Tezel']::text[], 8.5, '{"poet":"Yaşar Tezel","poet_slug":"yasar-tezel","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gecelik-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine Ankara Sokakları', 'yine-ankara-sokaklari-tahir-korkut-080yv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yine hüzünlü bir gece

Yıldızlar hayata küsmüş

Hepsi bir yere saklanmış

Ve yine ben dostlarım

Yine Ankara sokakları

Yine dolaşıyorum parklarda

Karanlık ve sessiz bir yerde

Yetersiz kalan ay ışığında

Benim tek barınağım

Yine Ankara sokakları

Yine dertleşiyoruz onla

Her zamanki gibi dinliyor

Hep sessiz kalıyor

Ama beni tek anlayan

Yine Ankara sokakları

Kimi yeri neşe bucağı

Kimi yeri dert ocağı

Kimi yeri pislik tuzağı

Hepsini bir arada tutan

Yine Ankara sokakları

                               

Evsiz çocukların yuvası

Kimsesizlerin pusulası

Yalnızların buluşma sahası

Gariplerin tek safhası 

Yine Ankara sokakları', 'Yine hüzünlü bir gece Yıldızlar hayata küsmüş Hepsi bir yere saklanmış Ve yine ben dostlarım Yine Ankara sokakları Yine dolaşıyorum parklard...', ARRAY['Türk Edebiyatı','Şiir','Tahir Korkut']::text[], 8.5, '{"poet":"Tahir Korkut","poet_slug":"tahir-korkut","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yine-ankara-sokaklari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Saba  Başlar', 'ask-saba-baslar-yasar-tezel-3j8ny', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aşık şafağın seheri ağlar

Doyasıya derinliğine kadar

O bizi okadar sevmiş ki

Aynı terennümlerde zikrimiz

Semahında öyle bir aheng

Bitmesin seyrinde dinleniriz

O nefsin düşmanını sevmiş ki

Aynı terennümlerde zikrimiz', 'Aşık şafağın seheri ağlar Doyasıya derinliğine kadar O bizi okadar sevmiş ki Aynı terennümlerde zikrimiz Semahında öyle bir aheng Bitmesin s...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Tezel']::text[], 8.5, '{"poet":"Yaşar Tezel","poet_slug":"yasar-tezel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ask-saba-baslar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bebek', 'bebek-yasar-tezel-m0miw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gülteninden salkım saçak

Kaç çocuk ağlarak doğacak

Umut edip beklediğim

İpe un serilmiş

Karşılıksız yele verilmiş

Bebek yüzlü çocuksu rüyalar

İstediğim biliyorsun

Oğlan olsun kız olsun

Bu duyguyu tanırsın

Daha ne dyeyim

Mevlam gönlünü yapsın', 'Gülteninden salkım saçak Kaç çocuk ağlarak doğacak Umut edip beklediğim İpe un serilmiş Karşılıksız yele verilmiş Bebek yüzlü çocuksu rüyala...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Tezel']::text[], 8.5, '{"poet":"Yaşar Tezel","poet_slug":"yasar-tezel","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bebek-64-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Başka...', 'senden-baska-i-brahim-ethem-bingul-0z4zg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seviyorum yaralarımı...

Düşününce bana kattıklarını

İç dünyamı nasıl kuşattığını...

Onlarca şeye darılıp, küsüp

Bu küskünlüklerle hayata bakmayı

Senden başka kim öğretebildi bana...

Yüreğimdeki sızılarla

Ve sırtımda bıçak yaralarıyla

Nefes alabilmeyi, yaşama sanatını

Senden başka kim öğretebildi bana...

www.iebingül.com', 'Seviyorum yaralarımı... Düşününce bana kattıklarını İç dünyamı nasıl kuşattığını... Onlarca şeye darılıp, küsüp Bu küskünlüklerle hayata bak...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/senden-baska-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şimdi Aşk Zamanı...', 'simdi-ask-zamani-baris-aluk-lmcu5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Uyandığında yorgun adam; bakıp gecenin karanlığına doğru, hatırlamaya çalıştı bu duvar dibinde ne zamandır baygın yattığını. Şimdi ne yapacağını ya da saatin kaç olduğunu...

Nedir zaman denen kelepçe

ve her zaman bilir mi hiç uyumayan

yaşamın tüm gerçeklerini? 

Ben aşka yumdum gözlerimi...

Yürüdü nereye gittiğini bilmeden. Bir süre sonra önce bir cadde ve cadenin ilerisinde bir otobüs durağı buldu. Kimseler yoktu etrafta ya da o öyle sanıyordu. Durak tabelasında gitmek isteyebileceği yöne giden bir otobüsün adını aradı ve sonunda sevinçle ''işte'' dedi. ''Gelmesini beklemeliyim burada''...

Her solukta içine dolan ayaz

Buzula dönüyordu içinde biraz.

Adam bilmeden kaçırdığını son otobüsü beklemeye başladı, gecenin karanlığını delen durak aydınlatmasının ölgün ve sarı ışığı altında. Bekledi; bekledi ve ayaklarında güç kalmayınca anladı ki, umutsuzluk çoktan takmıştı yakasına gülsüz dikeni...

Geriye yürüdüm tüm yanlış sapakları

toplayarak her yol ayrımında

geçmiş hatalarımda yitirdiklerimi

dur burada yolcu, topla kendini...

Ve bir anda caddenin kör köşesinden, yararcasına gecenin ağır karanlığını, yaklaşan ışığı gördü. Beklemiyordu bu geleni ama hissetti içinde çakan kıvılcımı. Baktı önce önünde duran arabanın penceresinden kendine bakan büyülü gözlere...

- ''Ben aşka gidiyorum, götürebilirim eğer istersen'' dediğinde ölebilirdi sevincinden. 

İşte o an anladı ki; kalbinde çakan kıvılcım alev alacaktı birazdan. Aşk önünde duruyordu. Soyunup tüm geçmiş zaman acılarını üzerinden, oturdu yanına en çıplak bedeniyle. 

- ''Tamam'' dedi. 

- ''Hazırım, soyunduklarım kalsın geçmişimin bu durağında.''

İşte o kız; 

yoldaş olmuştu yoluna, can olmuştu, cankız olmuştu canına. Ve ikisinin dilinden aynı anda döküldü sözcükler:

- ''Şimdi aşk zamanı... Öp beni...''

Daha çok yol var ileriye yürünecek...

(24.03.2006)   Beyoğlu', 'Uyandığında yorgun adam; bakıp gecenin karanlığına doğru, hatırlamaya çalıştı bu duvar dibinde ne zamandır baygın yattığını. Şimdi ne yapaca...', ARRAY['Türk Edebiyatı','Şiir','Barış Aluk']::text[], 8.5, '{"poet":"Barış Aluk","poet_slug":"baris-aluk","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/simdi-ask-zamani-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyaz Sayfa', 'beyaz-sayfa-yavuz-bayram-caliskan-6j123', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kanatlandı acılı geceler,

Gün sabaha dönerken,

Sokaklarda kaldı hasret, 

Birde gönlümde.

Ben eğer yaşıyorsam,

Yine çiçek bahçelerinde sarmaşıklar büyüteceğim,

Umutlarımı  şiirlere dizeceğim.

Limana yine gemiler yanaşacak,

Kapı önlerinde boynu bükük kalmayacağım.

Nihavent şarkıları dökeceğim asfaltlara

Dudaklarıma uzanan güne ''Gel'' diyeceğim.

Trenler çekilecek katarlarla,

Aldanmıyorsam ben karanfilleri kokluyor olacağım.

Kulaklarımda baharın sesi,

Yine aşkın  emrinde,

Utanmadan.

Pınarları damlatarak yudumlayacağım.

Buzlu  kışları unutacağım.

Buğulanıyor olsa da pencereler,

Ben gözlerimi kaçıracağım.

Uykusuz dalgalar, yalnız sahiller bitecek,

Beyaz sayfa bana ödül olacak.

Elleri bekleyeceğim, gözlerden önce,

Senin mi diyeceğim, benim mi? 

Akşamlar kıvılcımlarıyla mısralaşacak.

Ne  benim kahrım olacak düne,

Ne  senin ağrını taşıyacağım bu güne. 

Anıları düşüneceğim yaşattığın.

Yanılgılar düşmeyecek denizlere,

Bu sefer sen kazanamayacaksın.

Aşksız kalsam da tenhalarda bırakılsam da,

Islıklanmayacağım, beyaz sayfalarda,

Gözbebeklerimde ay ışığı yalnızlığım,

Doğan güne teslim ve ben yeniden doğuyorum.

http://www.geocities.com/siirhan68/', 'Kanatlandı acılı geceler, Gün sabaha dönerken, Sokaklarda kaldı hasret,  Birde gönlümde. Ben eğer yaşıyorsam, Yine çiçek bahçelerinde sarmaş...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/beyaz-sayfa-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oy Gülüm Gülüm', 'oy-gulum-gulum-i-sa-tekin-gc900', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Oy gülüm gülüm

Seni görünce

Yüreğimde gül açtı

Seni sevdikçe

Sevgi güllerim açtı

Oy gülüm gülüm

Sensiz karanlık gecelerde

Hasretlik ölüm

Geceler zulüm

Bırakıp gidemem gülüm

Sonunda olsada ölüm

Sensiz olamam yüreğimdeki gülüm

Oy gülüm gülüm

Hasret dolu gecelerde

Yüreğime kan düştü

Gül bülbülsüz

Ben sensiz olamam

Oy gülüm gülüm

Sensiz hayat ölüm

Yüreğimin gülü

Sen umut

Umudum sensin gülüm', 'Oy gülüm gülüm Seni görünce Yüreğimde gül açtı Seni sevdikçe Sevgi güllerim açtı Oy gülüm gülüm Sensiz karanlık gecelerde Hasretlik ölüm Gec...', ARRAY['Türk Edebiyatı','Şiir','İsa Tekin']::text[], 8.5, '{"poet":"İsa Tekin","poet_slug":"i-sa-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/oy-gulum-gulum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dijital Bunalım -ıı-', 'dijital-bunalim-ii-tahsin-ozmen-6ea3p', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'paslı bir tren garının unutulmuş anonsuyum ben

rayların arasında sıkışmış eski bir yaz akşamı

çocukluğumun cebinde gazoz kapağı sesleri

ve annemin balkonundan sarkan fesleğen kokusu

şehir dediğin biraz egzoz biraz yalnızlık

biraz da yağmurdan sonra parlayan asfalt değil mi

hangi sokağa çıksam yüzüme kapanıyor çocukluk

hangi sokağın adını değiştirseler adresini kaybediyor çocukluğum

hangi vitrinde dursam içeri giremiyor kalbim

bir adam tanıdım

kravatını düğümlerken boğazına yıllar dolanıyordu

sabah sekiz vapurunda çay içip ülke kurtarırdı

akşam olunca eve bir poşet ekmek ve yorgunluk

oğlu bilgisayar başında başka bir kıtaya göçmüş

kızı aynalarda filtre arıyordu yüzüne

aynı evde dört ayrı yalnızlık büyütüyorlardı

aynı mutfaktan beslenip ayrı uçurumlardan düşüyorlardı

akıllı ekranlar açık

kimsenin birbirine sesi yoktu

kimsenin kimseye dokunuşu yoktu

eskiden mahalleler vardı

kapı önü sandalyeleri

çekirdek kabukları

ikindiden akşama uzayan dedikodular

bir kadın bir tabak dolma götürürdü komşuya

bir çocuk düşüp dizini yaralasa

tüm sokağın canı yanardı

kimsenin zili korku gibi çalmazdı

şimdi herkesin kapısında kamera

herkes birbirinden korunuyor

parmak iziyle açılıyor hayat

parmak uçlarıyla dokunuyoruz dünyaya

herkes kendi hücresinin gardiyanı olmuş

sanki insan insandan kaçarken

kendinden kurtulabilecekmiş gibi

apartman boşluklarında yankılanan matkap sesleri

bir halkın sabrını kemiriyor yavaş yavaş

üst katta biri durmadan sandalye çekiyor geceye

alt katta bir genç geleceğini hesaplıyor kaygıyla

yaşlı bir kadın ilaçlarını sayıyor

karşı komşu her sabah takım elbisesiyle çıkıyor

sanki birazdan büyük bir devrim başlatıp

dünyayı düzeltecekmiş gibi

oysa öğle arasında oturup parkta

kuşlara simit atan çocukları kıskanıyor gizlice

şehir büyüdükçe küçülüyor gökyüzü

çocukken damlarda yıldız sayardık

şimdi göğe bakınca reklam panosu görüyoruz

bir bankanın kredisi

bir telefon markasının yeni yüzü

bir mutluluk taklidi

cam kulelerin arasında sıkışmış ay

utanıyor görünmeye rüzgar esmeye

ve şehirler genişledikçe daralıyor insanın ruhu

teknoloji geliştikçe küçülüyor insanın kalbi

eskiden bir mektup gelirdi

yüreğimiz ağzımızda beklerdik günlerce

şimdi saniyeler içinde ulaşıyor her şey

ama kimse kimseye varmıyor

parmaklarımız cam ekranlara değiyor yalnızca

bir yüzü okşamayı unuttuk çoktan

bir arkadaşın omzunda ağlamayı

bir sofrada sessizce oturmayı

bir dostun sessizliğini dinlemeyi

bir cenazede omuz omuza susmayı

bir kadın gördüm metro çıkışında

saçlarında acele vardı

topuklu ayakkabılarıyla yetişmeye çalışıyordu hayata

çantasında yarım kalmış düşler

iki kredi kartı

bir de kimseye göstermediği çocukluk resmi

gülümsedi telefona bakarken

ama gözleri başka bir mevsimdeydi

zemheri ayazından kalma bir gurbet vardı gözlerinde

dediler ki itibar

daha lüks arabalara binmektir

dediler ki başarı

daha yüksek katlara çıkmaktır

cam kuleler diktiler göğe doğru

her katında biraz daha eksildi nefes

asansör aynalarında çoğaldı kibir

sekreter kahvelerinde eridi gençlik

ve bir müdürün masasının altında

bir temizlik işçisinin bel ağrısı kaldı

oysa bir kasabanın kıraathanesinde

tek kanallı televizyonda maç izleyen adamların

bir tütün tabakasını birbirine uzatışı kadar sahici değildi hiçbir şey

ne borsalar

ne dijital paralar

ne uluslararası zirveler

ne de üç dil bilen yalnızlıklarımız

bazı sessizlikler vardır

dinledikçe eski bir pikabın iğnesi gibi acıtır insanın içini

babam mesela

elleri tütün kokardı

susarak severdi bizi

bir nasihat verecek olsa önce uzun uzun susar göğe bakardı

onun susuşu dünyanın bütün nutuklarından daha ağırbaşlıydı

annem

evin içinde bir gölge gibi incitmeden yaşardı

yuvanın en derin sükutuydu

elleri un ve sabun kokardı

söyleyemediklerini tencere içlerine saklardı

bir bakışıyla evdeki her şeyi yerli yerine koyan o eski ağırbaşlı adamlardandı dedem

çok konuşmaz her şeyin zamanını beklerdi

evi gözleriyle idare ederdi

alnındaki her çizgi bu toprağın sabır atlasıydı sanki

söküklerimize bile dualar diken

babaannemse

dünyanın bütün gürültüsüne rağmen

seccadesine kapanıp

fısıltıyla Tanrısına ulaşan en zarif susuştu

o dilsiz ömrü

çocukken pek anlamazdım

şimdi ne zaman bir hüzün çökse içime aynalarda onların sükutunu dinlerim

bir berber dükkânında öğrendim zamanı

duvarda sararmış futbolcu posterleri

cam kenarında kolonya şişesi

ve sürekli aynı haberi anlatan ihtiyarlar

bir ülke bazen yalnızca

saç traşı bekleyen insanların sabrıdır

kahvehanelerde memleket kurtarılırdı

üniversite kantinlerinde devrim konuşulurdu eskiden

şimdi herkes yurtdışı başvurusu soruyor birbirine

vize kuyruğunda bekliyor umudunu

hangi ülke daha kolay açılır rüyalara

hangi ülke daha az kırar insanı

hangi şehir daha özgür kılar ruhu

oysa insan bavuluna ne koyarsa koysun

kendini geçiriyor sınırdan

içindeki mülteciyi taşıyor her yere

bir çocuk gördüm lunaparkta

bozuk para soruyordu dönme dolap için

annesi uzaktan “bir dahakine” dedi

çocuk sustu

işte büyümek biraz da budur

içindeki dönme dolabı ertelemek

gece yarısı hastane koridorlarında

otomata sıkışmış kahveler kadar acı var

bir hemşire gözlerini ovuşturuyor nöbet arasında

genç bir doktor reçeteye yetişmeye çalışıyor

sedyeler geçiyor durmadan

ve insan anlıyor

hayat dediğimiz şey

birbirini tanımayan insanların

birbirine mecbur oluşu biraz da

gece olunca hastanelerin ışıkları başka yanıyor

acil servis kapılarında bekleyen insanlar

aynı korkunun akrabası oluyor orada

bir annenin dudağında dua

bir babanın cebinde eksik para

bir doktorun gözünde uykusuzluk

ve sedyeler

durmadan gidip geliyor ölümle yaşam arasında

ben en çok otogarlara üzülüyorum

herkesin bir yere yetiştiği

ama kimsenin tam olarak varamadığı yerlere

çay bardaklarında soğuyan umutlara

muavin seslerine

kimsenin içindeki özlemi sığdıramadığı bavullara

valizlerde taşınan memleket kokularına

bir zaman sonra

herkes kendi sessizliğinin kurbanı oluyor

herkes kendi enkazının mimarı oluyor

kırdığımız kalpler dönüyor dolaşıyor

ses olup çarpıyor duvarlara

kimse tamamen haklı değil çünkü

kimse tamamen masum da

ve aşk

ah o eski tramvay gibi gelen aşk

şimdi reklam panolarında unutulmuş

bir indirim kampanyası kadar kısa ömürlü

oysa bir zamanlar

bir mendilin ucuna bağlanırdı insanın kalbi

eskiden birini görünce kalbi hızlanırdı insanın

şimdi algoritmalar eşleştiriyor yalnızlıklarımızı

kimin kimi seveceğini algoritmalar belirliyor

bir kahve içiliyor

birkaç fotoğraf çekiliyor

sonra herkes kendi ekranına geri dönüyor

şimdi gökdelenlerin arasında

göğe bakacak kadar boşluk arıyoruz

bir ağacın altında oturunca suçlu hissediyoruz

çünkü dünya sürekli koşmamızı istiyor

durursak eksileceğiz sanıyoruz

yavaşlarsak geride kalacağız

oysa bazen durup düşünmek kendini bulmaktır

yeniden insan olmaktır

mezarlıklarda dolaşmayı severim

çünkü en dürüst mahalle orası

kimse kimseye rol yapmıyor

bir taş ustası tanımıştım

mezar yazısı yazıyordu yıllardır

“en çok genç isimlerde titrer elim

en çok çocuk mezarlarında körelir keskim” demişti.

geçen gün bir parkta

yaşlı bir adam güvercinlere su bırakıyordu

elleri titriyordu biraz

ama yüzü sakindi

o an anladım

dünyayı hâlâ tamamen kaybetmemişiz

insanlığı tamamen gömmemişiz

bir sokak müzisyeni gördüm metro girişinde

kimse dönüp bakmıyordu

adam yine de çalıyordu kemanını

çünkü bazı insanlar alkış için değil

içindeki yangın sönmesin diye yaşar

çünkü hâlâ

bir çocuk annesine sarılınca

bir işçi eve ekmek götürünce

bir öğrenci harçlığından kitap alınca

bir sevgili saçını kulağının arkasına atınca

bir yabancı yol tarif ederken gülümseyince

bir şeyler filizleniyor içimizde

ve belki bütün mesele budur

betonun çatlağından sızan bir çiçek gibi kalabilmek

ezilerek de olsa yeşerebilmek

çünkü dünya

bizi taşa çevirmek için döndükçe

bir yerlerde hâlâ

ince ruhlu insanlar yaşıyor sessizce

bir gün bütün tabelalar sönecek

telefonlar kapanacak

hesaplar silinecek

modalar geçecek

ve geriye yalnızca

birbirimizin ruhunda bıraktığımız iz kalacak

o yüzden

bir gün yolun düşerse yorgun bir şehre

kapat telefonunu;

bir kediyi sev

bir huzur evini ziyaret et

bir simit al martılara at

bir çocuğun başını okşa

bir çiçeği kokla

bir ağacı kucakla

göğe bak uzun uzun

ve kimsenin görmediği bir yerde

kalbini çıkar cebinden

biraz havalandır', 'paslı bir tren garının unutulmuş anonsuyum ben rayların arasında sıkışmış eski bir yaz akşamı çocukluğumun cebinde gazoz kapağı sesleri ve a...', ARRAY['Türk Edebiyatı','Şiir','Tahsin Özmen']::text[], 8.5, '{"poet":"Tahsin Özmen","poet_slug":"tahsin-ozmen","theme":"Türk Şiiri","is_hero":false,"total_lines":240,"source_url":"https://www.antoloji.com/denizler-yandi-tanrim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırakıp gitsen bile-', 'birakip-gitsen-bile-mikdat-bal-yjhos', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bırakıp gitsen bile, gönlümden çıkamazsın

O kurulu  dünyayı bir elde yıkamazsın

Severiz birbirini, sen benden bıkamazsın

Ağlama ağlatırsın, gitmenin sözü olmaz

Her şey tekerrür eder,inan sevgi de böyle

Kanatma yüreğimi bana tatlı söz söyle

Gidemezsin, bendesin, söylediğin her şeyle

Ağlama ağlatırsın, gitmenin sözü olmaz

Kadere ınandık da, boyun eğdin kedere

Eğer bunu anlarsan aşılır bu badire

Bu buhran geçicidir, Allah hayır getire

Ağlama ağlatırsın, gitmenin sözü olmaz

Birbirine yazıldık felekte, kaderdeyim

Sokaklar elin olsun, bilir misin nerdeyim

Bir yere gidemezsin, her gittiğin yerdeyim

Ağlama ağlatırsın, gitmenin sözü olmaz

Ebedi sevgimizi, gözyaşına bulama

Ağlamak üzereyim, gözlerimi sulama

Kalbini kırmış isem biraz üzgün ol ama

Ağlama ağlatırsın, gitmenin sözü olmaz

Mikdat der bu ağlayış bir mutluluk öncesi

O senin gözyaşların baş tacımın incisi

Gel artık barışalım gölümün birincisi

Ağlama ağlatırsın, gitmenin sözü olmaz

.', 'Bırakıp gitsen bile, gönlümden çıkamazsın O kurulu  dünyayı bir elde yıkamazsın Severiz birbirini, sen benden bıkamazsın Ağlama ağlatırsın, ...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/birakip-gitsen-bile-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliye Mektuplar  SENSİZ ÖLEMEM', 'sevgiliye-mektuplar-sensi-z-olemem-olgun-ekinci-kjpo4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '…………… Sensizliğin, sessizliğinin kaçıncı gününde olduğumu hatırlamaya çalışırken göğsüme düşen ağır şiddeti ölçülmez sancıların bedenimde volkanik patlamalar yarattığı anların içindeyim ve alkol komasında uyuşturmak, sancılarımı kadehlere gömmek istiyorum… Ki geçici çözümler üretkenliğinden sabah ki öksürük nöbetlerine taşımaya çalışıyorum sancılarımın çözümsüzlüğünü… 

…………… En çok ilk sigarayı yakınca başlayan ve o an yıllarca sürecek gibi ve sürmekte olan öksürüklerimde malarımı, utansam da içime akıtıyorum aksatmadan kızılcık şerbeti içmiş gibi kıvranmalarımı…Geçmiyor kör olası nöbetler, içten içe ve içime akıyor, yakıyor boğazımdan, gırtlağımdan bağırsaklarıma doğru yol alırken şeridini değiştirmeyen, eğitimli ülkelerin sürücüleri gibi seyahatlerinde ve sanki her gün aynı saatte aynı ritimde devam eden… Ve çocukluğumun radyolarında her gün aynı saat ve dakikada başlayan radyo tiyatrosu gibi… Sabahın o anlarında kaç insanın nefretini kazanıyorum bu şekilde bilmiyorum ama onlarda yıllardır suskunluklarından, gasp edilen haklarına dirençsizliklerinden, çarşıda esnaftan, pazarda pazarcıdan, otobüslerde muavinlerden, ellerini tükürükleyerek aldıkları kağıtlara gıda maddelerine salgılarını bulaştıran, paketleyen esnafa tepkisizliklerinden benim nefretimi kazandıklarını bilmiyor ve hiçbir zaman asla bilemeyecekler… 

…………… Vitamin yüklü yiyecek ve içecekler eksilmiyor günümden ama nafile biliyorum yetmeyecek direncime, adım adım ve gün be gün yaklaşıyorum insan oğlunun soğuk nefes, benimse yaklaşmak istediğim sonsuzluğa ve sessiz, sesinsiz geçen günlerde ulaşmak istediğim ebediyete… Ne ki ölüm, ne ki çekip gitmek, bir mikrop daha eksilecekse evrenden, gitmek onurla ve yalın mantıklı benim için, mantığına ters düşse de senin, benden önce ölmeye hakkın yok söylemine rağmen senin… Çocukluğumda garipser, sorgulardım komşu kadın ve erkeklerin ölmek istiyorum söylemlerine, şimdi hak veriyorum kendime yakıştırdığım sonsuzluğa… Olmadığın evrenin farklı meridyenlerinde, farklı iklimlerde soluklandığımız aynı renk sevdamız solmadı, soldurmadım, besledim yine… 

……………Tanklar geçiyor paletlerinin ağırlığını üzerimde bırakarak toprak bir zemin oluyor, kalkamıyorum onca ağırlığı def edip… Benden önce ölemezsin, hakkın yok buna söylemin düşünce ağırlıklar altındaki usuma çırpınıyor, doğruluyorum toprağa akıtarak gözyaşlarımı, susuz kalmasın diye bereketli topraklar… Kalkıyor sendeliyorum durmaya çalıştığım anlarda öksürük dalgası titretiyor, savuruyor tankların iz yaptığı toprak yol üzerinde… Bir çeşme arıyorum öksürmekten çağlayanlar akıtan gözlerimi yıkamak, yanaklarımdan boynuma yol alan izleri silmek için, çeşmesiz gelişen kentlerin yoksulluğu düşüyor yüreğime… Nehir kenarında, eriyen kar sularının yeşilden, maviden kahverengi renge dönüştürdüğü mikroplu suyla serinletiyorum yüzümü ve mora dönüşen gözlerimin altındaki halkaları… 

…………… Az ilerde ağacın altında birbirlerine sarılmış, dünyadan kopmuş sevgilileri görüyor, gıpta ediyorum sevdalarına, bir taş kaydırıyorum suyun yüzeyinde çocukluğumdan bugüne uzanan…. Kaybediyorum taşın izini, siluetini, gidişini, kaç metre ileriye fırlattığımı… Oysa yazdığım bir mektubu koyup, mantarla tıkayıp sana yollamak isterdim taş yerine bir şişede ve en kısa sürede deniz olmayan kentine nehir çoşkusunda… Şişeyi kırmadan açar, yıllarca saklardın sevdamızın gizeminde, o kimsede olmayan ve olmayacak olan güçlü hafızana gelen tarihi not ederek… Titrek yazılmış satırlardan anlardın olişkonun öksürük nöbetlerinde yazdığı satırları ve bilirim iki damla yaş düşer okurken, tuttuğun mektubun ucunu bırakmadan, sarılarak, nedenini benim bildiğim… Direniyorum, direneceğim, sigaradan, alkolden, hava kirliliğinin yarattığı karbon monoksitli havaların bedenimde yaratacağı tahribatlara… Yakışmaz bana, sevdama, yarınımıza aşksız, yurtsuz ölümler… 

…………… Put kesiliyorum, sus oluyorum… Sana susuyorum… Senin susuyor olman sessizlik, benim susuyor olmam sevdana acıkmışlığım susuzluğum… Yine susuyorum sana damlaya hasret susuz toprakların kıvranmışlığı ve acıkmışlığının nöbet sancılarında… Öksürük ne ki geçiyor öğle saatlerinde, sana susamışlığımda, geçiyor gibi oluyor kıvranırken yaşanmayan yaşamışlığım geliyor aklıma, portre çizmek istiyorum geçmişe dair kalem kırılıyor, tablo yırtılıyor, canlandırmak istediğim yaşam flu oluyor, kısa süren rüzgar gibi esiyor geçiyor… Gece çizmek istiyorum gözlerim görmüyor, bir türlü çizilemiyor yaşanmayan yaşanmışlıklar ve sesler duyuyorum gaipten soluduğum her anının içinde; Onsuz ölemezsin… Onsuz ölemezsin… Ölemem… Sensiz Ölemem… Sana doymadan, bize verdiğim sözlerin her birini tek tek yerine getirmeden ölmem… Ölemem… Sensiz ölemem… Sensiz ölmem… Sen olmadan asla… 

17.3.2006 - Adana', '…………… Sensizliğin, sessizliğinin kaçıncı gününde olduğumu hatırlamaya çalışırken göğsüme düşen ağır şiddeti ölçülmez sancıların bedenimde vo...', ARRAY['Türk Edebiyatı','Şiir','Olgun Ekinci']::text[], 8.5, '{"poet":"Olgun Ekinci","poet_slug":"olgun-ekinci","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sevgiliye-mektuplar-sensiz-olemem-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kolay Olmadı', 'kolay-olmadi-mustafa-bilgili-jl9zp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni öyle çok,öyle çok sevmiştimki,

Çıldıracak gibiydim,gittiğin zaman,

Unutamam sanmıştım,unuttum işte,

Sensizliğe çareler aradım durdum,

Unutmak kolay olmadı,lakin gönlümü,

Avutamam sanmıştım,avuttum işte,

Bir destan olmuştu,ismin dilimde,

Bir volkan olmuştu,aşkın kalbimde,

Yanık bıraktığın bu kor ateşi,

Söndüremem sanmıştım,söndürdüm işte,

Hiç alışkın değildim,ben yokluğuna,

Dayanamam sanmıştım,o zor hasretine,

Bir çılgınlıkmış meğer,benim yaptığım,

Gönlümdeki fırtınalar dindi bak,

Sayende kaybettiğim gerçek dostları,

Döndüremem sanmıştım,döndürdüm işte,

Kalbimde yaktığın,o kor ateşi,

Söndüremem sanmıştım,söndürdüm işte.

                                                                    24.09.1997', 'Seni öyle çok,öyle çok sevmiştimki, Çıldıracak gibiydim,gittiğin zaman, Unutamam sanmıştım,unuttum işte, Sensizliğe çareler aradım durdum, U...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Bilgili']::text[], 8.5, '{"poet":"Mustafa Bilgili","poet_slug":"mustafa-bilgili","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kolay-olmadi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşünceyi Yakalayan Adam – Düz Yazı', 'dusunceyi-yakalayan-adam-duz-yazi-naime-erlacin-rgte5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir mektup aldım geçenlerde. Uzunca süredir unuttuklarımı yeniden hatırlatıyordu bana. Oldukça iyi tanıdığımı sandığım Dostoyevski ve Camus’nün dünyalarından gelen ılık bir esinti gibiydi. 

İlginç olan tarafı Dostoyevski’nin az bilinen veya az okunan bir yapıtından; “Yer Altından Notlar”dan bahsediyor olmasıydı. Yapay entellektüelizmin bir anlamda hicvedildiği eserden yani… Onu okuduğumdan bu yana çok zaman geçmişti. Belleğimi bir hayli kurcalamak zorunda kaldım. Bir tür yılgınlığın, kaçışın ve kendi kabuğuna çekilmenin hikâyesi değil miydi? Sanırım öyleydi.  Dostoyevski’nin tanınmış büyük romanlarından önceki dönemde yazılmıştı. Büyük Dostoyevski’nin doğuş ve derin ahlaki-felsefi konulara girişinden hemen önceki “gebelik” zamanının bir ürünüydü. Düşündüm biraz. Bu eseri günümüzde önemli kılan neydi peki? Sanıyorum toplumsal yaşamın bugün vardığı; değerlerin evrenselleştiği; post- modernizmin insan yaşamı üzerine bir kâbus gibi çöktüğü noktayı yazar yıllar öncesinden hissetmişti. Ve tepkisel olarak doğan zorunlu kaçışları işaret ediyordu… 

“Yer Altından Notlar”, şimdi bana bir haykırış sesi ve güçlü bir çığlık gibi geliyor. Dostoyevski’den günümüze kadar uzanan kocaman uyarıcı bir çığlık…

Ve Camus. İnsanın tek başına olmasının utanılacak bir şey olduğunu söyleyen Camus… Bu da beni ana konu olan yalnızlığa geri getiriyordu. “Yalnızlık” olgusu üzerinde düşündüm bir süre. Gerçek yaşamda yalnızlığa pek inanmam ancak düşüncenin hâkim olduğu ortamlarda yalnızlığın oldukça yararlı olduğunu söyleyebilirim. “Seçilmiş ve tercih edilmiş” bir tür yalnızlıktan söz ediyorum. Düşünür ve üretirken yalnız olmakla yaşam yalnızlığı farklı şeylerdir. Kişi, yeri geldiğince aradaki sınırın bir o tarafına, bir bu tarafına atlamayı bilmek zorunda. Hem gerçek yaşamın kalabalığında, hem de düşünsel anlamdaki yalnızlıkta çoğalmak mümkün ama gereksinim duyduğumda, “seçilmiş” yalnızlığıma sığınır ve severim onu. Eldiven gibi giyerim üzerime. Asla törpülemez ve acıtmaz. Seçim yaparken düşünmek lazım… Ve sormak; “Neyi, ne kadar ve nasıl kaldırabiliriz? ” Kısacası, ne ölçüde baş edebiliriz? Yalnızlık bir tür kaçış veya çoğalma yolu mu, sığınılacak bir liman veya bir intihar mıdır? 

Bence herkes kendi yalnızlığını mercek altına koyup şöyle bir incelemeli. Bu konuyu anımsatan bir mektup almadan önce hatta! Mektup kimden mi geliyordu? İşte onu söylemeyeceğim sizlere.  Düz yazı ve düşünce yazıları yazmayan, ama benim okumaktan büyük keyif aldığım birinden geldiğini belirtebilirim. Çünkü O, düşüncenin kendisini yazıyor ve düşünceyi, benim özlediğim süratte yakalayabiliyor. 

“Düşünceyi Yakalayan Adam”, yalnızlığıma sığındığımda bana yol arkadaşı olan biri…

Onlar da lazım hayatta… 

Anlam adına! 

(24 Mart 2006)', 'Bir mektup aldım geçenlerde. Uzunca süredir unuttuklarımı yeniden hatırlatıyordu bana. Oldukça iyi tanıdığımı sandığım Dostoyevski ve Camus’...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/dusunceyi-yakalayan-adam-duz-yazi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Hey Dersim', 'sen-hey-dersim-baran-demir-tq2to', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gün olur hasret kokar 

Bu dağlar sevda misali

Çocukça çığlıkları içine alarak

Bazen kardelenleri

İnsanın suratını kesen

Soğuğa inat dimdik bakar gök yüzüne

Bazen de hırcın akan munzur

Bazen alabildiğince sakin

Bu doğası yansımış

İçinde barındırdıklarına

Asidir başkaldırır 

Yılgınlık olmaksızın 

Yangınlara göğüs geren

Meşe ormanları gibi

İnadına yeniden yeşerir

Üzerine düşen onca acıya

Aldırmadan barındırır

Dersimi gücenmeden

Sen hey dersim

Nasılda asırlardır onurla bakarsın dünyaya

Bazen acılar düşsede yüreğine

İçinde barındırdığın herşey sana çekmiş

Asi,onurlu ve güzelim yürekleri

Sende bu topraklarda doğmuş

Munzur dan beslenmiş 

Hey dersim güzeli 

Bak onurla dünyaya

Çünkü onurlu toprakların 

Asi çocuğusun sen', 'Gün olur hasret kokar  Bu dağlar sevda misali Çocukça çığlıkları içine alarak Bazen kardelenleri İnsanın suratını kesen Soğuğa inat dimdik b...', ARRAY['Türk Edebiyatı','Şiir','Baran Demir']::text[], 8.5, '{"poet":"Baran Demir","poet_slug":"baran-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/sen-hey-dersim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Yaban Kumrusu... Düz yazı', 'yaban-kumrusu-duz-yazi-naime-erlacin-5fnr8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sisli bir yalnızlık gibidir ölüm... 

Bilinmeyenin içinde tek başına yitmek, kaybolmak...

Ve yeniden doğmak şairin dilinde... 

Pir-ü pak, taptaze, dipdiri…

Ölmek hangi hesabı sonuçlandırıyor, düşündün mü hiç? O ki doğumdan önce de vardı. Ondan geldik; ona gideriz hepimiz. Ah bu korkularımız! İntihardan ne sık söz ederiz. Yaşamaktan ürktüğümüz için midir dersin? Yenilgiler cehenneminde yanmaktan korktuğumuzdandır belki. Birileri gerçekleştirmiş diye ne çok kıskanırız onları. Ama yapılmaz... Yapamayız. Bu yüzden de söze ve sözün anası şiire dokunur ellerimiz. 

Sen kırık ötüşler bırakırsın evrene... 

Bizler, ''söz''lenir ve söyleriz...

Bu kış yaşamdan yine ayrı düştün. Ne kadar da benzemiyoruz birbirimize. Benim bir eşim var; senin yok. Onu arıyorsun sabahları balkona astığın çığlıklarla... Bense suskunluğumda, yaradılış anında vaat edilmiş olan sözümü... Susmak da bir tür konuşmaktır, biliyor musun? Şakımayı öğrenemedin lakin bağırarak bir ün bırakıyorsun sonsuza. Ben, içimin boşluğuna saldığım sözcüklerle anlatıyorum meramımı... Ölümü, hayatı, aşkı ve sevda karası hüzünleri “söz”lüyorum oradaki ''ben''lerle. İpine tutunduğum bir uçurum var. Sen görmüyorsun. İniyor çıkıyorum durmadan. İniyor, çıkıyorum… İnan ellerim kanıyor ama yılmıyorum. Kimi gün bir dağ ateşinde yanmayı seçiyorum. Küllerden yine yaratmak için kendimi...

Anlamazsın sen. Sana ölüm, kalbin durması demek... Açlıktan, sayrılıktan; belki de vicdansız bir kedinin pençelerinde inleyerek... Hayattan kopardığın anlam, yalnızca eylem ile sınırlı. Veya eylemsizlikle... Hâlbuki yazan kişi eylemsiz de anlamlayabilir, özüyle anlamlandığı gibi... Gördün mü, ne kadar farklıyız! 

En fazla kaç boyutta yolculuk edebilirsin? Üç, dört, beş? Ruhumun koyaklarında dolaşırken, “ödünç alınmış büyülü âlemlerde, ‘n’ sayıda boyuta hükmediyorum” diye övünsem şimdi, darılır mısın? Gidilmemiş göç yolların var senin, sıcak ülkelere uzanan katar katar özlemlerin... Beni sorma hiç. Asırlarca önce evcilleştim. Evcilleştirdiler ve sözü keşfettim böylece. Diğer kuşlardan farklıyız biz. Göçemediğimiz sürece mekânsal kısıtlanmalar, iç yolculuklar aracılığıyla özlemlerin patlamasına neden olur. 

Sen haykırırsın, ben söylerim…

Biraz dert yansam, dinler misin? Âdemoğlu sözün değerini bilmiyor artık. Yaşam ve ölümün iç içe’liğini… Neden içimizde intihar ettiğimizi bıkmaksızın ve neden her satır ve mısra ile ana rahmine geri dönüp, orada bir kez daha yunup yıkanmak istediğimizi… Dışa vurdular çünkü. Hemen hepsi dışa vurdu. O denli berbat evcilleştiler ki, safi “dış” oldular! Hasreti, ayrılığı, sevdayı unutmuş gibi görünüyorlar. Şairin ölüm özlemini de bilmiyor onlar. İnsana dair ne varsa külliyen unutuldu…

Üzülüyorum yaban kumrusu. Zarf ile mazruf birbirine karıştı epeydir. İzlediklerinden utanır oldu sözüm. Ve sol yanım budanıyor gün geçtikçe. Hiç değilse bunu anlayabilirsin. Evrensel bir duygudur. Eşini kaybettiğinde hissettiğin acıdan farkı yok inan.

Örselenmiş yüreğimi sana bağışladım. Anlat bana şimdi, bu yarayı nasıl kanayacağım? 

..............................

-(S’İMGE Kültür Edebiyat Seçkisi: Mart – Nisan Sayısı – 2006) 

-(http://borgesdefteri.blogspot.com/) 

-(http://blogcu.com/nimo/)', 'Sisli bir yalnızlık gibidir ölüm...  Bilinmeyenin içinde tek başına yitmek, kaybolmak... Ve yeniden doğmak şairin dilinde...  Pir-ü pak, tap...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yaban-kumrusu-duz-yazi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Yastıkta Kocayın', 'bir-yastikta-kocayin-murat-duman-wrihj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'BİR YASTIKTA KOCAYIN

Sırrınızı açıp da,kimseye dert yanmayın,

Mutluluk çok pahalı,ucuz olur sanmayın,

Karar verin bire bir, el sözüne kanmayın,

Ömür boyu birlikte,bir yastıkta kocayın…

	

Ufak tefek sorunlar,bazen olur ya hani,

Aranızda tartışın,üzmeyin tende canı,

Her zaman hatırlayın,sizleri yaratanı,

Ömür boyu birlikte,bir yastıkta kocayın…

Her zaman bolluk olmaz,sofra yavan kurulur,

Ömür denen bu yolda, sevenler de yorulur,                                                                                

Sular bulansa bile, bir gün gelir durulur,

Ömür boyu birlikte,bir yastıkta kocayın…

Aldanmayın dünyaya,acımadan soldurur,

Sorunlar bazen aşar,duyguları öldürür,

Bırakmayın sevgiyi,sevgi sizi güldürür,

Ömür boyu birlikte,bir yastıkta kocayın… 

Murat duman söz eyler,fidanlara gül gerek,

Yuva kuran çiftlere,özü ballı dil gerek,

Sevginin temeline, bozulmayan yol gerek,

Ömür boyu birlikte,bir yastıkta kocayın…

21.3.2000 ANKARA', 'BİR YASTIKTA KOCAYIN Sırrınızı açıp da,kimseye dert yanmayın, Mutluluk çok pahalı,ucuz olur sanmayın, Karar verin bire bir, el sözüne kanmay...', ARRAY['Türk Edebiyatı','Şiir','Murat Duman']::text[], 8.5, '{"poet":"Murat Duman","poet_slug":"murat-duman","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bir-yastikta-kocayin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkını test eder misin?', 'askini-test-eder-misin-nurten-hidiroglu-q9phg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Uzak.......

Ne kadar uzak? 

Yakın......

Ne kadar yakın? 

Baktığın ama görmediğin yerde.

Dokunduğun ama hissetmediğin tende.

Bıçak sırtı gibi bir noktada,

Duruyorsa sevgin.

Bir nefes gibi yakınken bile,

Buz kesiyorsa kalbine uzanan ellerin.

Ölü soğukluğu yaşıyorsa dokunuşlardaki tenin.

Sözcükler havada kalıyor,

Ortak paydada buluşamıyorsa bir türlü.

İki kişilik koca bir yalnızlığı paylaşıyorsanız birlikte,

Uzak.....

Çok uzaktır sana.

Hiç ummadığın bir anda, 

Bir şarkıyla süzülüyorsa odana.

Darma duman ediyorsa seni,

Davetsiz,cüretkar hayali.

Bir bakışı bir sözü,

Kuruluyorsa aklına,mıhlanıyorsa ruhuna.

Hep gardını almışken hayata

Öylesine bir dokunuşu bile,

Tüm savunma duvarlarını yerle bir ediyorsa.

Bir öpücüğü, bin sevişmeye değişiyorsan eğer.

Tüylerin diken-diken,

Yüreğin ağzında bekliyorsan çalacak telefonları.

Onu her düşündüğünde,

Serin sular ferahlatıyorsa içini.

Tüm güzellikleri onunla,

Sadece onunla paylaşmak istiyorsa yüreğin.

Yerinde duramıyor,

Bir yerlere sığamıyorsa bedenin.

Yakın....

Çok yakındır sana.', 'Uzak....... Ne kadar uzak?  Yakın...... Ne kadar yakın?  Baktığın ama görmediğin yerde. Dokunduğun ama hissetmediğin tende. Bıçak sırtı gibi...', ARRAY['Türk Edebiyatı','Şiir','Nurten Hıdıroğlu']::text[], 8.5, '{"poet":"Nurten Hıdıroğlu","poet_slug":"nurten-hidiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/askini-test-eder-misin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şükran Annem', 'sukran-annem-neslihan-ergin-dfqk3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Onun aydınlık siması, bendeki huzurun aynası

Dualarını eksik etmeden yaşayan yüreğimin halısı

Mahçup sözlerime güvenen doğruların anası

Biliyorum dövündüğün canların kaygısı

Sen içimdesin canımın yongası...

Uğurlu geldin, mutluluğa erdim

Zor kapıları usulca araladın, oyunları yendim

Sıcak iklimlerden geldi sesin, hazanları terkeyledim

Yaradan aşkıyla dolu kalbin, mucizesine erdim

Gönlü deniz kadar derinim

Sözleri su kadar azizim

Dergahı tüm insanlara annemin...

Zümrütün hediyesi mavi kutu, sevgisinden bildiğim.../...

Canım manevi annem Şükran Günay''a...

mucize kelebek/2006', 'Onun aydınlık siması, bendeki huzurun aynası Dualarını eksik etmeden yaşayan yüreğimin halısı Mahçup sözlerime güvenen doğruların anası Bili...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Ergin']::text[], 8.5, '{"poet":"Neslihan Ergin","poet_slug":"neslihan-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sukran-annem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekleyeceğim', 'bekleyecegim-metin-yalti-rer1z', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bekleyeceğim 

- 

Sabah kalktığında 

Erikleri çiçeğe durmuş göreceksin 

Bahar gelmiş diyeceksin 

Gülümseyeceksin. 

Güneşi benimle kucaklamak 

Yeşile özlemini gidermek 

Gözlerimde 

Erimek, yitmek için 

Bana gelmek isteyeceksin 

Bir demet hercai menekşe içinde 

Kan kırmızı gül olmuş yüreğim 

Gelmezsen solacak 

Sevdiceğim. 

Bekliyeceğim. 

24/3/06', 'Bekleyeceğim  -  Sabah kalktığında  Erikleri çiçeğe durmuş göreceksin  Bahar gelmiş diyeceksin  Gülümseyeceksin.  Güneşi benimle kucaklamak ...', ARRAY['Türk Edebiyatı','Şiir','Metin Yaltı']::text[], 8.5, '{"poet":"Metin Yaltı","poet_slug":"metin-yalti","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bekleyecegim-49-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensin', 'sensin-ramazan-ozuturk-lgbzj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kardeş kültüründe yalnız bir portre

Çerçeve yanıyor, ağlayan sensin

Sınırın nerede, ölçmüyor metre

Rakamlar kanıyor, ağlayan sensin

Kaybolmuş ezginin yanık notası

Gündönümü geldi, oyna kafkası

Yedi iklim çökmüş, sisli havası

Bulutlar yanıyor, ağlayan sensin

Kilim aynı kilim ve aynı desen

Senin gönlünde ben, bende ise sen

Gülmek ne oluyor, göz yaş dökerken

Yağmurlar yanıyor, ağlayan sensin

Çiçek hüzün açar sevgi dağında

Mutluluk ararız bilgi çağında

Kaybolur umutlar ışık hızında

Saatler yanıyor, ağlayan sensin

Bize ip dayanmaz ince bükünce

Tükenmez soyumuz, bir bir ölünce

Allah''tan başkası olmaz güvence

Gönüller yanıyor, ağlayan sensin

Özütürk der, özlem kokar şiirler

Anlayamaz bizi çörtük fikirler

Gönülde meşale, dilde zikirler

Hak için yanıyor, ağlayan sensin', 'Kardeş kültüründe yalnız bir portre Çerçeve yanıyor, ağlayan sensin Sınırın nerede, ölçmüyor metre Rakamlar kanıyor, ağlayan sensin Kaybolmu...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Özütürk']::text[], 8.5, '{"poet":"Ramazan Özütürk","poet_slug":"ramazan-ozuturk","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sensin-72-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ezildi Yüreğim', 'ezildi-yuregim-aydin-guler-incwi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Vurdular onu! ...

Dağ çiçekleri vardı ellerinde

henüz koklayamadığı.

Usunda,

Ak-pak hayalleri

Daha yaşayamadığı.

Vurdular onu! ...

Bir ay karanlığında

Tamda zamana,

Işık tutmaktayken aydınlığı.

Vurdular onu! ...

Çok ta  genç yaşında

Daha henüz paylaşamadığı

İnsanca duygularla

Ak hayallerini,kana buladılar.

Hemde; 

Hiç ummadığı bir anda

A p a n s ı z 

Vurdular onu,

EZİLDİ   YÜREĞİM.....', 'Vurdular onu! ... Dağ çiçekleri vardı ellerinde henüz koklayamadığı. Usunda, Ak-pak hayalleri Daha yaşayamadığı. Vurdular onu! ... Bir ay ka...', ARRAY['Türk Edebiyatı','Şiir','Aydın Güler']::text[], 8.5, '{"poet":"Aydın Güler","poet_slug":"aydin-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ezildi-yuregim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GeCE yaNIĞI', 'gece-yanigi-gul-yazganarikan-yob72', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Anlamı daralıyor hayatın 

Gece boğuklaşarak yavaş yavaş

Çöküyor omuzlarıma

Boşladı beni aşk kaç bahar geçti

Bir ağrı gibi oturuyor yokluğu şakaklarıma

Bir buğu gibi pencereye vuruyor geçmiş

Buluntu yaşanmışlıkları çiziyorum 

Parmaklarımla

Çıkın ediyorum sözlerini 

Çınlayışı sesinin vurdukça kulaklarıma

Çirkefçe çiseliyorsun gözlerimden

Debelenip duruyorum karanlığımda

Döküntü aşklar döllenmesin yüreğimde diye

Kaç kilit vurdum kapılarıma...

Gece yanığısın sen 

Derinliği depreşen 

Göğsümde açılan 

Bir gizli yamasın....

Bitmez bu kanayış 

Bin yama yapsam bile

Kanıksamıyor yüreğim söküyor yine

Gidişin ruh göçü bedenimden

yokluğun paslı bir hançer

Döndür ne olur beni kendime

Sen de dön gel...

Oluk oluk akıyor ömrüm

Zaman  sürtük 

zaman yosma 

Yapışmış saçlarıma hasretin

Sürüklüyor uçurumlara

Bir sen şahdamarım, bir sen

Ah bir çıkıp gelsen

Şerbet olur döktüğüm gözyaşları

Bir sıcak şarap olur, bağrıma

Tutmuyor artık göğsüm yama...

Gel karış yine... 

Gece yanığına...', 'Anlamı daralıyor hayatın  Gece boğuklaşarak yavaş yavaş Çöküyor omuzlarıma Boşladı beni aşk kaç bahar geçti Bir ağrı gibi oturuyor yokluğu ş...', ARRAY['Türk Edebiyatı','Şiir','Gül Yazganarıkan']::text[], 8.5, '{"poet":"Gül Yazganarıkan","poet_slug":"gul-yazganarikan","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/gece-yanigi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gördüm', 'gordum-tastan-ciralar-sdzz1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tek amacın hizmet olsa da yurda

Herkesi kendince bakıyor gördüm

Şeytana nasihat verecek türde

O hırsla yazıyor okuyor gördüm

Beslenme sağlıkta yaşam güvensiz

Tüketen zavallı üreten densiz

Para göz karartmış yürekler kansız

Mevtanın canına okuyor gördüm

Duyarsızlık aldı başı gidiyor

Yasa uygulayan bilmem ne diyor

Çoban uyutmaya devam ediyor

Kavalın sesine akıyor gördüm

Örümcek misali kurar ağını

Geçirir baharla kışlık çağını

Tuttukça ballanan beş parmağını

Aç göz boğazına tıkıyor gördüm

Cins tohumlar yetiştirip durdular

Hedef tutturmaya çok koşturdular

Mevsim geldi toprağını sürdüler

İnatla ekiyor dikiyor gördüm

Çok sat çokça kazan ne olur olsun

Günah sevap yazan ne olur olsun

Değişmez çan ezan ne olur olsun

Kendi mihrabına çıkıyor gördüm', 'Tek amacın hizmet olsa da yurda Herkesi kendince bakıyor gördüm Şeytana nasihat verecek türde O hırsla yazıyor okuyor gördüm Beslenme sağlık...', ARRAY['Türk Edebiyatı','Şiir','Taştan Çıralar']::text[], 8.5, '{"poet":"Taştan Çıralar","poet_slug":"tastan-ciralar","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gordum-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Artık buluşmayacağız', 'artik-bulusmayacagiz-hasan-yildiz-hgod0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Biliyormusun nartanem,

bu son gecem,bu şehirde,

Biliyormusun, nurtanem,

bu son dokunuşum sana

Biliyormusun,kartanem

Bu son sözlerim; iyi dinle......

birtanem,,,,

artık birlikte olmayacağız,

ellerini tutamayacağım

gizli gizli buluşmayacağız.

Bu son yalanın ailene karşı,

artık buluşmayacağız.

1987-Bandırma

24-03-2006', 'Biliyormusun nartanem, bu son gecem,bu şehirde, Biliyormusun, nurtanem, bu son dokunuşum sana Biliyormusun,kartanem Bu son sözlerim; iyi din...', ARRAY['Türk Edebiyatı','Şiir','Hasan Yıldız']::text[], 8.5, '{"poet":"Hasan Yıldız","poet_slug":"hasan-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/artik-bulusmayacagiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Antrapoz', 'antrapoz-mehmet-akkin-3zwag', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Arkadaşlar benim yaşım kırk oldu bu sene

Seneye bana ve yeni yaşıma 

Maaşallah çekersiniz kısmetse

Nirvanayı hiç bulamadım ama...

Epey yokuş çıktım ne hikmetse

Eh. iniş artık bundan sonra yolumuz

Zatende bilemeyiz gibi geliyor

Ne zaman geldik bu ömrün sonuna', 'Arkadaşlar benim yaşım kırk oldu bu sene Seneye bana ve yeni yaşıma  Maaşallah çekersiniz kısmetse Nirvanayı hiç bulamadım ama... Epey yokuş...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akkın']::text[], 8.5, '{"poet":"Mehmet Akkın","poet_slug":"mehmet-akkin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/antrapoz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul Tesbihi', 'i-stanbul-tesbihi-alper-yilmaz-1umko', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '10 milyonun ayakları altındasın,

70 milyonun başları üstünde…

Kimisinin “Büyük Fikir”inin merkezi,

Evvelce Konstantin’in görkemli şehri,

Şimdi Sultan Fatih’in kudretli fethisin…

Camilerin ezanı,şadırvanı,minaresi,

Kiliselerin çan sesi,keskin mimarisi,

Havraların altı-köşe yıldızı,ayini…

Müslimi veya gayrimüslimi,

Yer yüzünün hemen bütün milletlerisin…

Ey  şehr-i İstanbul; dünyanın incisi,

Şanlı ülkemizin göz bebeği…

Tevfik’in  sisi,kötü kadını; 

Yahya’nın azizisin,şiirlerinin ve şehirlerinin sultanı; 

Hani dinlermiş ya bir garip Veli  seni gözleri kapalı,

Doğrudur; epey zaman oldu ben onu yapalı.

Tren,vapur,insan yığını sesi hem de martı,

Ne hoş olur mevsimlerin,ayların; temmuzu,ocağı,martı…

Can damarısın İstanbul bu toprağı kanlı ülkenin,

Uyan artık vatandaş,o şehir ki senin şanlı ülkenin! 

Bilmezsin kıymetini var olan hazinenin,

Geçmişlerin hayaliydi bu “büyük” şehir,

Rüyayı gerçek kıldı senin sancaktar Fatih’in.

Hicaz’dan haşmetine hadis makbul buyurdu,

İki cihan serveri Peygamber Efendimiz; 

Bütün beldeler farkında senin,hitapları:”Efendimiz! ”.

Duy beni İstanbul,duy beni! 

Bilinir ki dayanılmazsın,çekilmezsin ama,

İnsanlar sana harekette; kimi göçe,kimi taşına.

Çünkü yedi tepeye kurulmuşsun; 

Oturmuşsun vatanın mihenk taşına.

Ey fevkalşehir İstanbul,o güzelliğin uğruna

Az mı kanlar aktı senin toprağına,taşına.', '10 milyonun ayakları altındasın, 70 milyonun başları üstünde… Kimisinin “Büyük Fikir”inin merkezi, Evvelce Konstantin’in görkemli şehri, Şim...', ARRAY['Türk Edebiyatı','Şiir','Alper Yılmaz']::text[], 8.5, '{"poet":"Alper Yılmaz","poet_slug":"alper-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/istanbul-tesbihi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Gözlerini Açınca', 'gun-gozlerini-acinca-firat-caliskan-6v9lv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gece güne şafakla seslenirken 				

Gün gözlerini açtı						

Bitirdik herşeyi o andan sonra yarına hiç bir şey bırakmadık		

Azıcık umuttan gayrı					

Onuda kuru somunlara katık yaptık					

Düşündüm dönüşüme utandım					

Bir zamanlar haline üzüldüğüme üzüldüm şimdi			

Utandı gökyüzü, hüzün yağdı, ağladı hatta sabahlar			

İçime çöktü titreyen ayaz					

Avazım çıktığı kadar sustum						

Gülerken yada ağlarken belkide soğanlar kıyarken 			

Karmaşık; anlayacağın meçhul bir duygunun ifadesi 		

Sadece tuzlu dudağında uyurken 					

Zamanın piçleri							

Ben gözlerimi yumacağım inadına sana ve senin gibi kahpe dünyaya', 'Gece güne şafakla seslenirken 				 Gün gözlerini açtı						 Bitirdik herşeyi o andan sonra yarına hiç bir şey bırakmadık		 Azıcık umuttan ga...', ARRAY['Türk Edebiyatı','Şiir','Fırat Çalışkan']::text[], 8.5, '{"poet":"Fırat Çalışkan","poet_slug":"firat-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gun-gozlerini-acinca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aysız bir gecede kalem çizikleri', 'aysiz-bir-gecede-kalem-cizikleri-omer-faruk-girgin-8et48', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'aysız bir gecede 

karanlığa çiziyorum seni ve her şeyi

belki de hayatım tükenirken arıyorum acıların sebebini 

ve yaşamın uyanışını hissetmek istercesine

elimde bir kalemle

uçmak

uçmak istiyorum 

tıpkı yeşil bir yaprak gibi.

ve sonra

  …ne varsa unutmak

sulara yazdığım mektupları

mısralarımındaki kayıp şiirleri

ve belki de içimden çözerken ölümle yaşamanın çelişkisini

yine bıkmadan çiziyorum

üzerine çığ düşen mevsimlere seni

sonu ölümlü yolları 

anlaşılmaz işaret levhalarına belki 

o, sen olan ki bir kadın.! 

belki baharı anımsatıyorsun

ağzında sakladığın bal gibi söylenmeyecek sözleri 

bense bunları bekleyen

donuk çimenli bahçelerde oynaşan belki  zavallı bir deli

belki de yüreğinde hayallerini düşürmüş bir ölü

belki  uçsuz zamanların sonsuz yolculuklarında büyüyen

fakat şimdi kendi imhasını yakan bir adam gibi...', 'aysız bir gecede  karanlığa çiziyorum seni ve her şeyi belki de hayatım tükenirken arıyorum acıların sebebini  ve yaşamın uyanışını hissetme...', ARRAY['Türk Edebiyatı','Şiir','Ömer Faruk Girgin']::text[], 8.5, '{"poet":"Ömer Faruk Girgin","poet_slug":"omer-faruk-girgin","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/aysiz-bir-gecede-kalem-cizikleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nisanın Hüzünlü Yüzü', 'nisanin-huzunlu-yuzu-murat-ozenli-ni9gj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Nice şiirler yazıldı nisana

İçinde insan sıcaklık ve bahar kokuları vardı

Bilmezdi kimse nisanın hazin yüzünü

Yalnızlık dolu gecelerini,

Yanımda olmayışın mıydı kalbimi dağlayan

Yoksa doğum günümde  terketmen miydi

Nisanda aşka koşardı insanlar

Bense yalnızlığıma 

Nisan Ben Ve Hazin Yanlızlığım

Ben aslında nisanda hazin yalnızdım

Hazin yanlız olan bendim yine Nisanda', 'Nice şiirler yazıldı nisana İçinde insan sıcaklık ve bahar kokuları vardı Bilmezdi kimse nisanın hazin yüzünü Yalnızlık dolu gecelerini, Yan...', ARRAY['Türk Edebiyatı','Şiir','Murat Özenli']::text[], 8.5, '{"poet":"Murat Özenli","poet_slug":"murat-ozenli","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/nisanin-huzunlu-yuzu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elma Dersem Çıkın', 'elma-dersem-cikin-firat-caliskan-yrfic', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ey anılar ben geldim					

Hani talan ettiğin, herşeye masumca gülümseyen o masum çocuk	

Tüm çirkinliklerini geceye saklayan o yıllar burdayım işte 		

Yüzleşmekten korkmuyorum artık sizden				

Benden çaldıklarınızı almaya geldim					

Bizi mutluluğa gebe bıraktığın o günleri unutmadım			

Hani hayalini bile kuramadığım umutlar geri döndüm nerdesiniz		

Defalarca düşüp dizlerimi kanattığım yinede koşmaktan bıkmadığım	

bozuk sokaklar hani çocukluğum					

Damda yıldızlarla daldığım serin uykular				

ve serçelerin uyandırdığı toprehan kokulu sabahlar ben geldim		

Kahvaltıya sıcak ekmeği yetiştirmek için verdiğim masum mücadelem 	

Saklambaç oynadığım arkadaşlarım ve çocukluk heyecanlarım		

Ben geldim nerdesiniz 						

Elma dersem çıkın', 'Ey anılar ben geldim					 Hani talan ettiğin, herşeye masumca gülümseyen o masum çocuk	 Tüm çirkinliklerini geceye saklayan o yıllar burdayı...', ARRAY['Türk Edebiyatı','Şiir','Fırat Çalışkan']::text[], 8.5, '{"poet":"Fırat Çalışkan","poet_slug":"firat-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/elma-dersem-cikin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gücümü Yitirdim', 'gucumu-yitirdim-umit-tuna-ht72h', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sana vermiştim ben yüreğimi,

Kimseyi sevmemiştim sen gibi,

Yürekten vurulmuştum sana,

Aşkım dilimde değil kalbimdeydi ama.

Sana anlatmaya cümleler yetmedi,

Gözlerimden demi belli değildi? 

Seni sevdiğim,

Bu aşk için ölmeyi istediğim.

Kavuşacağımız günü bekledim,

Senden sadece kalbini istedim,

Gözlerindi beni sana mahkum eden,

Peşinden sürükleyen.

Ne olur dön bana geri,

Diyemem artık ben,

Tüm gücümü yitirdim ben,

Sil başdan her şeye bir daha başlayamam ben,

Gururumu bir kez daha sana,

Çiğnetemem ben! ...

ÇILGIN MUHASEBECİ', 'Sana vermiştim ben yüreğimi, Kimseyi sevmemiştim sen gibi, Yürekten vurulmuştum sana, Aşkım dilimde değil kalbimdeydi ama. Sana anlatmaya cü...', ARRAY['Türk Edebiyatı','Şiir','Ümit Tuna']::text[], 8.5, '{"poet":"Ümit Tuna","poet_slug":"umit-tuna","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/gucumu-yitirdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adı Kaderdi', 'adi-kaderdi-firat-caliskan-1ejjk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Güneş doğmuştu esmerliğimize biçare			

Silinmesi imkansız yaralar bıraktı					

Ve bile bile günahlardan zevk aldık	

				

Tanrının kırbacı yararken sırtımızı 					

Ümitsizlikten uyuştuk						

Ve ulaşılmaz hayallere dalmadı yürekler	

			

Tanrının kırbacından yinede kurtulamadı ruhlarımız			

Doğrunun doğruluğunu yanlışlarda bulana kadar			

Hepsi kaderdi	

				

Mükemmel yazılmış bir senaryoyu					

Provasız ve suflesiz oynuyorduk					

Herkesin rolü belliydi 						

Oynamama şansın yok 						

Müthiş bir galada (Mahşer)        						

en iyiler en kötüler seçilecekti 					

Adı kaderdi.', 'Güneş doğmuştu esmerliğimize biçare			 Silinmesi imkansız yaralar bıraktı					 Ve bile bile günahlardan zevk aldık	 				 Tanrının kırbacı ya...', ARRAY['Türk Edebiyatı','Şiir','Fırat Çalışkan']::text[], 8.5, '{"poet":"Fırat Çalışkan","poet_slug":"firat-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/adi-kaderdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Herşeyim', 'ben-herseyim-firat-caliskan-zcxgl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aşk benim, mutluluk benim						

Ben esmer tenli sevgilinin alnında boncuk boncuk duran terim		

Gözbebeklerindeki hasretin ta kendisiyi			

Türkülerdeki sitem, gurbetteki sıla özlemiyim				

Ben romanlardaki gizemli kişi, şiirlerdeki kafiyeyim			

Ömür boyu hayal edilen yaşam 				

Her gece görülmek istenen rüyayım					

Ben her ana''nın doğurmak istediği çocuk				

Her çocuğun istediği düşüm					

Her akşam yoldaşım yalnızlara, çöllerde serabım kervanlara		

Bazen şairlere ilham, ressamlara modelim ben			

Belki duyulmak istenen bir çift tatlı sözüm				

Belki arıların aradığı çiçekteki özüm					

Ben herkesin görmek, duymak, 					

hissetmek istediği güzel olan herşeyim', 'Aşk benim, mutluluk benim						 Ben esmer tenli sevgilinin alnında boncuk boncuk duran terim		 Gözbebeklerindeki hasretin ta kendisiyi			 Tü...', ARRAY['Türk Edebiyatı','Şiir','Fırat Çalışkan']::text[], 8.5, '{"poet":"Fırat Çalışkan","poet_slug":"firat-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ben-herseyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bak Ha', 'bak-ha-tastan-ciralar-jvchj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Güç kuvvetin varsa başla işine

Yorulduğun yerde bak kalırsın ha

Dost sandığın şeytan salar peşine

Umduğundan hava bak alırsın ha

Çıkma karanlığa yoksa fenerin

Zikzak yapma gibi var mı hünerin

Sığın himaye bul düşünme derin

Ödün kopar yazık bak ölürsün ha

Mirasyedi tarzı yaşam düşkünü

Giden gitti dilen akıl şaşkını

Uğurla fırsatı çağır kuşkunu

Daha beter derdi bak bulursun ha

Gezindiğin yolda kimse mi yoktu

Uyurgezer çarptın şafak mı söktü

Emeksiz mahsulün yaprak mı döktü

Köklerin oyulur bak kurursun ha', 'Güç kuvvetin varsa başla işine Yorulduğun yerde bak kalırsın ha Dost sandığın şeytan salar peşine Umduğundan hava bak alırsın ha Çıkma karan...', ARRAY['Türk Edebiyatı','Şiir','Taştan Çıralar']::text[], 8.5, '{"poet":"Taştan Çıralar","poet_slug":"tastan-ciralar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bak-ha-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gölge', 'golge-firat-caliskan-9nyhx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yüzü yıkıldı adamın							

çıkınca aniden karşısına						

Korktu, görmezlikten geldi						

Yürüdü boş sokakta						

Gülümsedi sonra korkunun etkisiyle					

Farkına varmadı önce					

Onun ardından geldiğini görmemişti					

Dönünce gördü						

İrkildi ve yine güldü ağlamakla karışık					

Gölgesine', 'Yüzü yıkıldı adamın							 çıkınca aniden karşısına						 Korktu, görmezlikten geldi						 Yürüdü boş sokakta						 Gülümsedi sonra korkunun...', ARRAY['Türk Edebiyatı','Şiir','Fırat Çalışkan']::text[], 8.5, '{"poet":"Fırat Çalışkan","poet_slug":"firat-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/golge-60-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliye Mektuplar  SAKLI SEVDA', 'sevgiliye-mektuplar-sakli-sevda-olgun-ekinci-vdhtt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '…………… Seni kendime sakladım… Sesin titretirken tenimde sevda tellerini, damarlarıma dalga dalga yayılıp egemenliğini ilan ederken aşkın kurtuluş savaşlarında… Karışmasın başka seslere, onların gürültülü senfonisizliğinde ritim tutmayan anlamsızlıklara bulaşmasın, yitmesin diye kendime sakladım sesini önce… 

…………… Erguvan renkli gelirken tınıların, ayları güne, günleri de dakikalara bölerek sakladım seni saniyelerimde… İçimde titreyen melodileri saniyelerle çarpıp sensiz geçen günlere ekledim, özlemler biriktirip çoğalttım sana doğru, biriksin, şarıl şarıl aksın diye… Derman olmayan gecelerde sesini çoğaltıp damlalarca içime akıttım yalnızlığımın duvarlarında ses geçirmez yalıtımla, benden başkası duymasın diye… Dayanamam seni görmemişliğimde sesini paylaşmaya, kıyamam zerresinin araya gitmesine, yaşamayanlar bilmez yüzünün gül cemalini görmeden, sesinin aya vuran şavkının eşsizliğine… Bilmezler, bilmesinler her gece ay doğduğunda şavkına besteler yollayıp sevdalar astığımı, yüzünü sana dönüp yansıtsın diye sessiz siluetimi… Sesleriyle sevenlerin tensel buluşmasıdır keşfedilmemiş dinlerin ayini ve gizem dolu perilerin diyarında, egzotizminde, saklanan sevdaların dışa vurumudur en güzel güneşin batımında…

……………Vadilerinde enternasyonal aşklar doğurmuş, gizeminde, yaşanmamış sevdaya kanat çırpmaya hazırlanan, asırlardır yuvasından çıkmayan ismi bilinmeyen bir çift kuş havalanıyor semalarında, el ele, diz dize uçmayı, kanat çırpmayı öğreniyorlar yaşanmamış sevdalarının acemiliğinde, tensiz flört eden sesleri kayboluyor, anılar, yaşanmamış güzelliklerin ebruli demetlerini bırakıyorlar bastıkları her adım, çırptıkları her kanatın ardında iz bırakarak… Sevdalarıyla buluşan sevgilerinin ışığında doğan bin bir renkli gökkuşağını geriyorlar kanat çırptıkları zirveden, el sallayan sevdalarına dair yeryüzünün peri dolu bacalarına… 

…………… Telepati ile duyumsamamıydı yaşanmış zannedilen doyumsuz anlar, kıyısı olmayan kulaç attıkça aynı noktada kaybolduğumuz azgın dalgalarla boğuşmak mıydı, derinliğinde yediğimiz vurgun… Gerçeğine döndüğümüz hayatın ayak üstü şekerlemelerinde ki netleşmeyen rüyalar diye tanımladım hep ve geçici ve ne zaman tekrar sesin gelse suskunluğumla örtüyorum tınılarını, zarar görmesin diye dünyevi dış etkilerden… Şimdi ne zaman bir kadın sesi duysam farklı notalar ekleyip, anlam yükleyerek çoğaltıyor, binlerce ses üretip dinliyorum sessizliğinde… Aralarında sana benzeyen tek ses bile olmuyor, çoğalttığım tınılarını yüreğimden çıkarıp seviyor, okşuyor, dinliyor gizliyorum yine sevdamın suskun ve saklanmışlığında… 

…………… Artık sana gelmelerimdeki pembe mutlu sancıların, dönüş yolundaki çekilmez kramplarını yarı yolda bırakarak gördüğüm her renkli nesneyi gözlerim pembeye boyuyor. Sakladıklarım griden dönüştüğü rengin ahengiyle saklı kalan sevdalara öncülüğünü ilan ediyor geçtiğim tepe, dağ, yollardan… Vadi, ovalar, nehirlerden… Köy, kasaba, kentlerden… Yol, otoyol, tali yollardan… Yüzyıllık yalnızlık ve suskunluğunu yırtan, parçalayan yanardağ gibi kükrüyor, korkutuyor akacağı sevdasız kalan toprakları… Bu kentin sınırlarında hapsolan, cebimde sakladığım çocukluğumu karlı kentine gelirken rengarenk giydiriyorum sana sevdirmek, serçe parmağının sıcaklığını hissettirmek, şımartmak için… Meleksi yüreğinin perili ellerinde dokunuşu hissetsin, çıksın kabuğundan, saklı sevdasından, korunaklı sevdana ulaşsın diye… 

……………Pusula icat edildiği günden beri yönümü şaşırdım hep güneşin doğuşu-batışı ile yönlendirmedim kendimi hatalarımda… Oysa doğudan doğan güneş sende batardı, alır, saklar, ısıtırdın yüreğini yüzyıllardır sunmak için sıcağını… Karanlık, puslu, sisli, tipili, yağmurlu günlerde doğmayan o güneş hep senin içinde sakladığın sevginin çeperlerindeydi… Göstermezdin kimseye, korkar, ürkek ceylan gibi sekerek yürürdün düşürmemek için, gözlerine yansırken ışığı, böyle havalarda siyah gözlüklerinle saklardın, kadife saçlarına yansır da fark ederler diye saçlarını toplar, uzun berenin içine gizlerdin güneşlerini… Çocukluğumun sakladığım sevdalarına giydirdiğin özenle sakladığın güneş doğdu…Yeniden doğdu.. Sevdamıza dair, 

saklı sevdamıza dair… Güneşinle aydınlandı SAKLI SEVDAMIZ… 

20.3.2006 - Adana', '…………… Seni kendime sakladım… Sesin titretirken tenimde sevda tellerini, damarlarıma dalga dalga yayılıp egemenliğini ilan ederken aşkın kurt...', ARRAY['Türk Edebiyatı','Şiir','Olgun Ekinci']::text[], 8.5, '{"poet":"Olgun Ekinci","poet_slug":"olgun-ekinci","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sevgiliye-mektuplar-sakli-sevda-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göç Var', 'goc-var-firat-caliskan-pw1sm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Suların durulmadığı,hasretin hiç bitmediği 				

ve göz yaşının sel olup aktığı bir diyardı.			

Emeklerini toprağa ekip ekmeklerinin topraktan alan insanlardı		

Kayıp bir zamanda					

kayıp duyguların türküsünde eller çırpılırdı				

Bir hatun gördüm; dudakları kan kırmızı, elleri çatlak			

Gözlerinde tükenmişliğin izi						

ve çocuklarda umutsuzluğun krizi				

Dillerinde bozuk bir aksan 						

Yarınlarını bilmezmiş burda insan					

Hepsi bir değişik duyğulu, 						

hepsi bir değişik hayalli						

Kimse gelecek güzel günlere inanmıyor			

Söylenen türkülerde bu anlatılıyor					

Dünya yalan, yaşam yalan, düşler yalan				

Birtek gerçekleri geçmişleriydi akılda kalan 				

Ve düğünlerde unutulmuşluğun halayı çekilir				

Çileler akla gelir						

Unutulmuşluğun hatılanması bir başka bahara ertelenir			

Düğün biter herkes kendi kabuğuna çekilir				

Gökkuşağının tekrar renkleneceği				

Kırların çiçekleneceği, diyarın özlemi bu				

Sevdaların türkü olduğu bir diyarın özlemi				

Ancak hepsi hayaldi 					

terk ediyorladı yarınlarının tohumunu serptikleri topraklarını		

Uğruna öldükleri, ağlayıp güldükleri yere dönüp bakıyorlardı		

Yarınlar yok, geçmiş talan olmuş					

Hayal yok, güzel günler yok 					

Sadece göç var', 'Suların durulmadığı,hasretin hiç bitmediği 				 ve göz yaşının sel olup aktığı bir diyardı.			 Emeklerini toprağa ekip ekmeklerinin toprakta...', ARRAY['Türk Edebiyatı','Şiir','Fırat Çalışkan']::text[], 8.5, '{"poet":"Fırat Çalışkan","poet_slug":"firat-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/goc-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Kalbime Sordum', 'seni-kalbime-sordum-hasan-i-yigun-lt4zu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen hiç kalbinle konuşur musun bir tanem? 

Ben ara sıra konuşurum

Seni kalbime sordum

Onsuz olmaz, dedi

Neden diye sordum

Onsuz yaşamın anlamı olmaz ki

Diye cevap verdi

Şimdi ben beynimle

Kalbim arasında bocalıyorum

Ne seninle, ne de sensiz  yapamıyorum...', 'Sen hiç kalbinle konuşur musun bir tanem?  Ben ara sıra konuşurum Seni kalbime sordum Onsuz olmaz, dedi Neden diye sordum Onsuz yaşamın anla...', ARRAY['Türk Edebiyatı','Şiir','Hasan İyigün']::text[], 8.5, '{"poet":"Hasan İyigün","poet_slug":"hasan-i-yigun","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/seni-kalbime-sordum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbetten Mektup', 'gurbetten-mektup-firat-caliskan-js9iv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İnsanları bir başka oluyo buraların				

Allahım her türlüsünden burda senin gulların				

Kimi oğlanlar gız gibi oluyo, kimi gızlar oğlan gibi giyiniyo		

İnan bayrağımızı görmesem burasına başka ülke diyecem		

Hökümet daireleri yalnız bizim kasabanınki gibi çalışıyo			

Memur beğler böğün get yarın gel deyo			

Sokaktaki insanları saymakla bitmiyomuş herkes köyünden buraya göçüyomuş.						

Burdaki yüskek apartumanları bi görseniz ''bütün köy buraya sığarız'' dersiniz.								

Bide beni burda dolandırdılar sana bir tarla bulduk deyip paramı çarptılar.	

Topçu sahasıymış meğersem çok geç anladım				

Karakoldaki posbıyıklı kosmer bey yardımcı oldu dolandırıcıları sonradan buldu.								

Ancak paramı yemişlerdi alamadım anlayacağınız cebim boş züğürt kaldım	

Kosmer bey bana bir iş buldu çalışmaya başladım			

günlerce yer süpürüp tabak yıkadım					

Çok şükür karnım tok sırtım pek şimdi				

Allah razı olsun kosmerden hızır gibi yetişti				

Bizim bir memleketliynen tanıştım, artık onda kalıyom			

Ev kirasının yarısını o, yarısını ben ödüyom				

Kendisi beledyede çok möhüm bir çöpçü başıymış beledye reisininde en gral arkadaşıymış						

Gerçi ben inanmıyom ama neyse					

Buranın yiyecekleri heç düzgün değil be ana				

Süte su katanmı istersin, kasapta eşek eti satanmı 			

Senin yemeklerini özledim be ana şöyle gözel bir pilav yanında koca bir tas tarhana								

neler vermezdimki buz gibi soğuk bir ayrana				

Eeee az kaldı yakında dönüyom köye 				

Hani dedimya dönmem artık,sevmiyom buraları diye			

İnanki çok zormuş dayanamıyorum artık ana 				

Nefes alamıyorum sanki, daralıyo yüreğim burda			

Valaa bizim ahırın tezek kokusu bilem buranınkinden temiz		

Ellerinden öperim sağlıcakla kalın hepiniz.', 'İnsanları bir başka oluyo buraların				 Allahım her türlüsünden burda senin gulların				 Kimi oğlanlar gız gibi oluyo, kimi gızlar oğlan gib...', ARRAY['Türk Edebiyatı','Şiir','Fırat Çalışkan']::text[], 8.5, '{"poet":"Fırat Çalışkan","poet_slug":"firat-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/gurbetten-mektup-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umutlar Sınırsız', 'umutlar-sinirsiz-firat-caliskan-i2h3q', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Alfebenin yetersizliği kabahatiydi					

sevginin tanımını yapmaya					

Kelimeler gizli rollerde oynuyordu					

Ümitler hep yarınlarda saklıydı					

Hayaller gökkuşağı renginde 					

Unutulmuşluk hatırlanmaya gebeyken					

Ve sevgiler tükenirken					

Umutlar sınırsız							

İçinden çektiğin bir ah''tı 					

Beni böyle yıkan belki					

Belkide unutulan bir günahtı						

Acı çekerken, 						

döktüğüm gözyaşları sınırsız', 'Alfebenin yetersizliği kabahatiydi					 sevginin tanımını yapmaya					 Kelimeler gizli rollerde oynuyordu					 Ümitler hep yarınlarda saklıy...', ARRAY['Türk Edebiyatı','Şiir','Fırat Çalışkan']::text[], 8.5, '{"poet":"Fırat Çalışkan","poet_slug":"firat-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/umutlar-sinirsiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uc Haller', 'uc-haller-mehmet-akif-gulhan-sg1et', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yığ odunları üst üste

Kümbet olsun önümde

Ver ateşe kendi ellerinle

Bağla ellerimden at içine 

Sadece yıldızları öpeyim

Kapansın dünya gözüme

Gizli arzular,hayaller kalsın

At onları da nem kokan 

Sandıklar içine

O eski şarkıları çal bana

Bestekarı bilinmeyen

Alıcısı hiç olmayan şarkıları

Kapanayım ben bir tarafı boş yastıklara

Başımın yanan ateşi

Sarsın tüm bedenimi

Gözümden akan yaşı koklayayım

İçinde sen varsın diye

Mehmet Akif Gülhan 24.03.2006 Saat 13.37', 'Yığ odunları üst üste Kümbet olsun önümde Ver ateşe kendi ellerinle Bağla ellerimden at içine  Sadece yıldızları öpeyim Kapansın dünya gözüm...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Gülhan']::text[], 8.5, '{"poet":"Mehmet Akif Gülhan","poet_slug":"mehmet-akif-gulhan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/uc-haller-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sus....', 'sus-hatice-guler-zbvnh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sus....Rüzgar esme artık deli deli

Körükleme kor halindeki yüreğimi

Benim yangınım bana yeter

Benim derdim bana yeter

Sus...Kulaklarıma ulaşan ses

Sus...Hissettiğim sıcak nefes

Sus...Dalgalanma beynimde

Kalbimde yaşadığın yeter.

Sus...Gözlerimdeki ışıltı

Sus...Yıldızımdaki pırıltı

Sus...Yağma üzerime sevdiğim

Yüreğimdeki otağın yeter

Sus...Geceme dolan aydınlığım

Sus...Bedenimi yakan güzelliğin

Sus...Sızma gönlümden hayallerime

Anılarımda yaşadığın yeter..', 'Sus....Rüzgar esme artık deli deli Körükleme kor halindeki yüreğimi Benim yangınım bana yeter Benim derdim bana yeter Sus...Kulaklarıma ulaş...', ARRAY['Türk Edebiyatı','Şiir','Hatice Güler']::text[], 8.5, '{"poet":"Hatice Güler","poet_slug":"hatice-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sus-67-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk bir çeşit', 'ask-bir-cesit-mustafa-sargin-3yo5k', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aşk bir çeşit

sanalı bin çeşit

gerçek aşkın

tarifi yok

misali ben

o yoksa ben yokum', 'Aşk bir çeşit sanalı bin çeşit gerçek aşkın tarifi yok misali ben o yoksa ben yokum...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Sargın']::text[], 8.5, '{"poet":"Mustafa Sargın","poet_slug":"mustafa-sargin","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ask-bir-cesit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sene Bilmem Kaçta', 'sene-bilmem-kacta-firat-caliskan-5zeyf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tarih beni yazıyor, ben tarihi yaşıyorum				

Sene bilmem kaçta						

O zamanlar kasetler revaçta 				

Sokaklar suç mahalliydi					

Abilerimin dinlediği şarkılar neydi,niye gizliyorlardı			

Duvarlara neden yazı yazıyorlardı					

Anlamak zordu o anlarda 						

ve biz küçüktük							

								

Biz küçükken oyunlar daha zordu					

Makaradan ve telden kamyon yaparlardı				

O zamanlar askercilik oynanırdı 					

elerde silahlar ve mutlaka birileri ölürdü 				

Sonra oynumuz bozulur sokaklara sahici askerler dolurdu

Bunları anlamakta zordu 						

ve bizler küçüktük								

Sene bilmem kaçta ozamanlar kitaptalar revaçta		

Küçük beyinlerimiz yeni yeni birşeyleri anlıyordu			

Sokaklar kaynıyordu					

Konuşmak yasak, şiirler yasaktı				

ve abilerim kaçaktı				

								

Tek kanal izlenirdi televizyonda				

ve pazar günleri çizgi filmi beklerken					

bir işkenceydi senfoni orkestrası konserleri				

Gece sokağa çıkma yasağı vardı					

Saz çalmak, türkü söylemek suçtu 					

Bu yüzden nice kalem kırıldı, nice ozan kan kustu								

Sene bilmem kaçta					

Yılmaz GÜNEY filmleri revaçta					

Ve biz büyüyorduk herşeye rağmen	

								

O zamanlar malborolar kaçaktı				

Kendi dilini konuşmakta yasaktı, ne olduğunu açıklamakta					

Biz çocukken,						

hapishane önlerinde uzun bekleyişler vardı				

Görüşlerde aylık hasretler bir saat''e sığardı								

Sene bilmem kaçta						

Uzun saçlar revaçta yinede biz küçüktük				

Serseri takılmak, tespih sallmak, nara basmak geçmişte kaldı		

İspanyol paça modaydı, ve blue jeanler kaçaktı 								

								

Sene bilmem kaçta tarih beni yazıyordu ben tarihi								

(Bir arkrabamın anlattığı ve beni çok etkileyen bir anısından esinlendim)', 'Tarih beni yazıyor, ben tarihi yaşıyorum				 Sene bilmem kaçta						 O zamanlar kasetler revaçta 				 Sokaklar suç mahalliydi					 Abilerimi...', ARRAY['Türk Edebiyatı','Şiir','Fırat Çalışkan']::text[], 8.5, '{"poet":"Fırat Çalışkan","poet_slug":"firat-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/sene-bilmem-kacta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şeytanın Çocukları', 'seytanin-cocuklari-ahmet-agdere-2a5ki', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sizler aşkı hiç bilmediniz

Karanlık düşlerinizin ardında 

Çelik çomak oynadınız sevdiklerinizle

Gökler gürlettiniz bir öpücük ardından

Hilkatlerinizden doğan şeytani bir güdüyle

Kağıtlar kalemler kirlettiniz hiç uğruna

Denizlerine açıldınız korsan gemilerinizle

Kim bilir kaç korsanın tecavüzüne uğradığını

Hiçe saydığınız o masum mavi suların

Sizler aşkı hiç mi hiç bilmediniz

Düşlerinizde gezerken kırmızı başlıklı kız

Onun kırmızı başlığını düşlediniz, güzelliğinin yanında

Sizler hep kirlenmiş sulardan içtiniz

Yanında dururken tertemiz memba

Ah! Ah! Ah! .. Bu kadar ahmaksınız sizler! 

Şeytanın çocukları! 

….…şeytanın çocukları! 

……………..sizler aşkı hiç bilmediniz,

….………….......................bilemeyeceksiniz!', 'Sizler aşkı hiç bilmediniz Karanlık düşlerinizin ardında  Çelik çomak oynadınız sevdiklerinizle Gökler gürlettiniz bir öpücük ardından Hilka...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ağdere']::text[], 8.5, '{"poet":"Ahmet Ağdere","poet_slug":"ahmet-agdere","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/seytanin-cocuklari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir de Bakarsın', 'bir-de-bakarsin-yusuf-onder-bahceci-y08an', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hep tûli emeller peşinde, gezip durursun,

Ayağının altında mazlumları ezip durursun,

Ne kadar, günah işledin se, onu bulursun,

Bir de bakarsın, ölüm ansızın, gelivermiş.

Herkes ölür, ben ölmem mi, zannedersin,

Ölürde kara yere girmemmi zannedersin,

Gel etme kardeş, kendine, yazık edersin,

Bir de bakarsın, ölüm ansızın, gelivermiş.

Hemen koştururlar camiye salanı verirler,

Cami etrafında gezenlere tatlını yedirirler,

Senin kıyamadığın libasları fakire verirler,

Bir de bakarsın, ölüm ansızın, gelivermiş.

Münker, Nekir gelir de hesabını görürler,

Cennetlik mi, Cehennemlik mi iyi bilirler,

Cennetliksen gözün aydın kardeş derler,

Bir de bakarsın, ölüm ansızın, gelivermiş....', 'Hep tûli emeller peşinde, gezip durursun, Ayağının altında mazlumları ezip durursun, Ne kadar, günah işledin se, onu bulursun, Bir de bakars...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-de-bakarsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akıl Değil Nasihat', 'akil-degil-nasihat-turan-tuncer-sdz9h', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'AKIL DEĞİL NASİHAT

Demir olsan, taş olsan

Sana şekil verirdim

Biraz âkil olsan

Senden feyiz alırdım

Yüklemişsin sermayeni 

Bir bacaksız kediye

Dinleyeyim ben seni

Ama söyle ne diye? 

Ağustos güneşine sen ateşler yakarsın

Kar üstüne diken eker, ekmek diye bakarsın

Kaza değil seninki, sen düpedüz sakarsın

İnadınla kalp kırar, sen dünyaları yıkarsın

Söylemedilermi sana, büyük sözü dinle diye

Aynı suda iki kez sakın yıkanma diye

Gece olup kapanma, güneş gibi doğ 

Çiçeksiz ağaçlara, hiç bahar gelmez diye

''Kuşçuyum'' aklım, senin aklına ermez

Kin doğuran gecelere, sabah hiç gelmez

Etrafına bir bak, bu nasihati kim verir sana

Seni eşşek görenler, menfaatsiz ot bile vermez.

20 Mart 2006 /İst

Alkadraz_Kuşcusu', 'AKIL DEĞİL NASİHAT Demir olsan, taş olsan Sana şekil verirdim Biraz âkil olsan Senden feyiz alırdım Yüklemişsin sermayeni  Bir bacaksız kedi...', ARRAY['Türk Edebiyatı','Şiir','Turan Tuncer']::text[], 8.5, '{"poet":"Turan Tuncer","poet_slug":"turan-tuncer","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/akil-degil-nasihat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '.G ö m ü', 'g-o-m-u-zafer-zengin-etnika-enk30', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '. 

hatırlatma; talanı bekler gömü

.

güzel şeyler diyoruz

gülmüyor çiçeklerin

ısmarlama hüznün yüzü

bir vakti gecenin

dar vakti yüreğinin

ne yana koysam ellerimi

çenem keskin bıçak

yanağım yanağını tutmayacak

..

diyorum ki güzel şeyler dile

benim için yalvarma tanrıya

kendini dokuyan ellerimle

düşlerimi satıyorum çocuklara

ufkunu gönder buralara

satıldı maviler kalmadı çocuklara

...

ele gelmeden gidiyorlar

bir kaşa dokunmak gibi

gözden öpmek gibi değil bu

hep tatlı vedalarda olmuyor

içinin bir yerine gömüyorsun

ardından şubat ayazları

mart yangınları

nisan sağanakları

ağlamak için bekler işte çocuklar

çocuklar yağmurları

....

sonra yağmur yağıyor

toprağın kabarması gibi

kabarıyor yürekte

bir çiçek ekiver

baharı bekleme

güzde olsa

bir çiçek dikiver gözlerime

hani umut olsun diye...

22 02 2006 / nokta sonrası serüven.

.', '.  hatırlatma; talanı bekler gömü . güzel şeyler diyoruz gülmüyor çiçeklerin ısmarlama hüznün yüzü bir vakti gecenin dar vakti yüreğinin ne ...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/g-o-m-u-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuklar', 'cocuklar-firat-caliskan-nvvki', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kalabalıkların içinde sessiz bir feryad var 			

Hiç bir zaman duyulmayan veya duyulupta kulak asılmayan

Kimi mendil satıyor, 						

Kimi ayakkabı boyuyor						

Her biri yaşamın eteğinin bir ucundan tutmuş				

Ve acımasız hayatın rüzgarıyla savruluyor				

Bilyelerini hiç bilmedikleri bir sandığa kilitmişler			

tıpkı umutları gibi						

Uçurtmalarını gökyüzünün maviliklerine bağlamışlar 			

tıpkı sevinçleri gibi						

Kiminin yüzü trafik ışıklarının lambalarına bağlı bir şekilde gah gülüyor, gah üzülüyor								

Kimileri de sattıkları mendile umutsuzluğun ve çaresizliğin resmini çiziyor	

Küçük bedenlerine büyük bir yük yükleniyor				

Yani onlar hayatı sokakta tanıyor					

Bazısı, vicdansızlığın ve kibirliğin bulaştığı arabaların camını silerken çabucak                                                                                                                    Hiç düşünmüyorlar düşlenmesi gereken sevinçlerini			

Hiç biri kuramıyor hayalini ve gelecek güzel günlerini			

gerçekten onlara o kadar uzakmıydı herşey				

yoksa, bu dengesiz dünyada untulmuşlarmıydı				

Çirkefleşmiş ayakkabılara yüreğinin boyasını sürüyor		

Ve gözbebeklerinin ışıltısını görene kadar parlatıyor		

yinede onlar hiç bir gün yılmıyorlar				

Gelecek güzel günler ve sevgi dolu bir yaşam için		

Her sabaha yeni bir umutla gözlerini açıyorlar				

Ve galiba onlar çocuklar!', 'Kalabalıkların içinde sessiz bir feryad var 			 Hiç bir zaman duyulmayan veya duyulupta kulak asılmayan Kimi mendil satıyor, 						 Kimi aya...', ARRAY['Türk Edebiyatı','Şiir','Fırat Çalışkan']::text[], 8.5, '{"poet":"Fırat Çalışkan","poet_slug":"firat-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/cocuklar-54-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mâniler 3', 'm-niler-3-zeynal-yaman-5jaja', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Erim erim erittiler

Ruhumuzu yürüttüler

Zemherinin soğuğunda

Cesetleri çürüttüler

Nakış nakış dokuttular

Maymunname okuttular

Dalda çürür artık meyve

Asrımızı kokuttular

Ferhat''ın elinde kazma

Şirin''in başında yazma

Bu gidişle dağ delinmez

Dağları koruyor yazma...

Bakır tutmazsa kalayı

Bir mangır etmez alayı

Millet çalışsın didinsin

Köstebeklere balayı...

Eserinden eserinden

Kim övünür eserinden

Ruhlarımızı yonttular

Hristiyan keserinden

Ateş yanar köz çıkarır

Zeynel sözün göz çıkarır

Sözlerini duyan papaz

Türlü türlü söz çıkarır

Çankırı-1990', 'Erim erim erittiler Ruhumuzu yürüttüler Zemherinin soğuğunda Cesetleri çürüttüler Nakış nakış dokuttular Maymunname okuttular Dalda çürür ar...', ARRAY['Türk Edebiyatı','Şiir','Zeynal Yaman']::text[], 8.5, '{"poet":"Zeynal Yaman","poet_slug":"zeynal-yaman","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/maniler-3-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eğitim Cehalet Alır', 'egitim-cehalet-alir-turan-tuncer-1zydh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'EĞİTİM CEHALET ALIR

Sana baktım da her sırra daim, nail oldum, 

Hata etmişim tanımakla seni, nadim oldum,

Bir içi güzel insan arar idim, yanıldım sürü buldum

Sayende, koca şehirde yoz mallara çoban oldum..

Keşke aynalar içinde olsada daim bakabilsen

Baktığında, aynada hep kendini görebilsen

Diliini tutabilsende, anlatanı bir dinleyebilsen

Baki kalan eşşeklik, bak senden uzak kalacak..

Okumakla, ilimle yok bu işin hiç bir alakası

Başta akıl taşımayan, olur zevzek yalakası

Alim olsan ne yazar, yoksa edebinin plakası

Ahlakını iyi ile aşıla, kalmamış suretinin rabbiyalesi

Milletin sabrı tükenecek, bozulacak sıfatının terekesi

Kalem aciz sana karşı koyamaz, hiç direnemez

Kağıt ne yapsın, senin yezid olduğunu bilemez 

Yazdıklarını okuyan pişman olur, tanıdığı güne

Lânet eder sadece elinden başka bir şey gelmez 

Selam veren, selamından utanır ama geri dönemez

''Kuşcuyum'', artık sana nasihatten bıktım usandım

Sen yine aynı kafa değişmezsin bir sende yanıldım

Vazgeçtim ben, zaten  geldim yolun sonuna dayandım

Pişireyim seni derken unuttum kendimi ateşlerde yandım

20 Mart 2006 /İst

ALkadraz_Kuşcusu', 'EĞİTİM CEHALET ALIR Sana baktım da her sırra daim, nail oldum,  Hata etmişim tanımakla seni, nadim oldum, Bir içi güzel insan arar idim, yan...', ARRAY['Türk Edebiyatı','Şiir','Turan Tuncer']::text[], 8.5, '{"poet":"Turan Tuncer","poet_slug":"turan-tuncer","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/egitim-cehalet-alir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir ben ayaktayım', 'bir-ben-ayaktayim-hasan-yildiz-z7cha', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bütün şehir uyuyor,

bir ben ayaktayım

Birde; 

martılar,

sabahın ilk ışıkları sinmekte

İstanbul sokoklarına.

Akşamdan kalmış,yanık kokulu

çöp yığınları ve onlarla haşır-neşir

kedi ve köpekler..........

Bir ben ayaktayım

birde ekmek param

son nefeste cıgaram,

emişiriz, dudak dudağa

O, illetini döker içime,

Ben hiddetimi savururum

lacivert dumanıyla........

24-03-2006', 'Bütün şehir uyuyor, bir ben ayaktayım Birde;  martılar, sabahın ilk ışıkları sinmekte İstanbul sokoklarına. Akşamdan kalmış,yanık kokulu çöp...', ARRAY['Türk Edebiyatı','Şiir','Hasan Yıldız']::text[], 8.5, '{"poet":"Hasan Yıldız","poet_slug":"hasan-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bir-ben-ayaktayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığı Çakarsın Yüreğine', 'yalnizligi-cakarsin-yuregine-turan-tuncer-bcf1i', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'YALNIZLIĞI ÇAKARSIN YÜREĞİNE

İnsan için yaşamak, 

kuşun kanadında bir deli rüzgâr

Sevgi yoksa içinde,

yaşamak salt nefes almak.

Hayata, diyecek neyin var? 

Alt alta koy, gündüzleri, geceleri 

ayrılıkları ve kavuşmaları,

çarp, böl, topla, çıkar

yarım hayat etmez, sonuç sıfır çıkar

Koyu mavi gökyüzü, güneş koyu mavi

Beyazların teslim olur da, gecenin mavisine

Umutlar kaybeder beyazını

yarınlar hep lacivert.

Sevmiyorsan! 

Nefret te etme, 

bir yerlerde umudun kalsın

yarınları bırakma, tek başına.

Düşünülmüyorsan bir gülüşün içinde,

Varlığını dert etme, sen hiç yoksun

Sevgi yoksa içinde, 

sen, hiç olmadın demektir.

Yalnızlığı çakarsın yüreğine,

Paslanmış umutlarınla

Yudumladığın sevgiler emanettir üstünde

Gülüşlerin gözlerinde emanet

Grilerin tecavüzüne uğrar da, beyazların

Gözünde büyür yaşamak, ağır gelir

Yalnızlık sağdığın gecelerde, üstüne.

Gitmek en kolaydır, arkanı dönmekle başlar

Yalnızlıklar sağarsın, sevmelerin gül memelerinden

Her gece yeni dendenler koyarsın

umutsuzluklarına.

Hüzzam makamı yalnızlıklarda

Sende, artık bir tek yalnızlığa 

parola sorulmaz, bütün kalelerin düşer de 

Kapıların viran kalır 

Bütün keşkeler yüreğinde

24 Mart 2006 /İst

Alkadraz_Kuşcusu', 'YALNIZLIĞI ÇAKARSIN YÜREĞİNE İnsan için yaşamak,  kuşun kanadında bir deli rüzgâr Sevgi yoksa içinde, yaşamak salt nefes almak. Hayata, diye...', ARRAY['Türk Edebiyatı','Şiir','Turan Tuncer']::text[], 8.5, '{"poet":"Turan Tuncer","poet_slug":"turan-tuncer","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/yalnizligi-cakarsin-yuregine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Sağsın Ya', 'sen-sagsin-ya-yusuf-onder-bahceci-vx5om', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Soluk alabildiğim şu Dünya''da sen sağsın ya,

Karalara bürünen yeryüzün de, sen sağsın ya,

Matem tutulan mevsimlerim de sen sağsın ya,

Yaradan''a bunun için, şükür, şükürler ederim...', 'Soluk alabildiğim şu Dünya''da sen sağsın ya, Karalara bürünen yeryüzün de, sen sağsın ya, Matem tutulan mevsimlerim de sen sağsın ya, Yarada...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sen-sagsin-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevişmek Öyle', 'sevismek-oyle-mehmet-can-mn2uu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aşk sihirli kelime

Sevilmek öyle

Sevişmek öyle

Haksızmıyım

Söyle….', 'Aşk sihirli kelime Sevilmek öyle Sevişmek öyle Haksızmıyım Söyle…....', ARRAY['Türk Edebiyatı','Şiir','Mehmet Can']::text[], 8.5, '{"poet":"Mehmet Can","poet_slug":"mehmet-can","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sevismek-oyle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulutlarla Aşk', 'bulutlarla-ask-atilla-guler-laym1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sararan parmaklarımın arasından

düştü

sessizliğimin

son

saniyesi

sille tokat canına okudum yalnızlığın

kül

rengi

gözlerinde

söndürdüm

son

sigaramı

tutuklu kalan tüm duyumsamalarım kanat taktı

her

biri

bir

buluta

aşık

şimdi', 'sararan parmaklarımın arasından düştü sessizliğimin son saniyesi sille tokat canına okudum yalnızlığın kül rengi gözlerinde söndürdüm son si...', ARRAY['Türk Edebiyatı','Şiir','Atilla Güler']::text[], 8.5, '{"poet":"Atilla Güler","poet_slug":"atilla-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bulutlarla-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayakkabı', 'ayakkabi-sumer-kucuk-sp3zi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kilo elli taşırım

Kilo yetmiş taşırım

Kilo seksen taşırım

Kilo doksan yüz ve üzerini

Taşırım ama gel bana sor 

Bu durum bana çok kor', 'Kilo elli taşırım Kilo yetmiş taşırım Kilo seksen taşırım Kilo doksan yüz ve üzerini Taşırım ama gel bana sor  Bu durum bana çok kor...', ARRAY['Türk Edebiyatı','Şiir','Sümer Küçük']::text[], 8.5, '{"poet":"Sümer Küçük","poet_slug":"sumer-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ayakkabi-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul da...', 'i-stanbul-da-mustafa-coskun-kale-qhxid', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yaşanmamış

 Komplekslerim var

Benim orda..,

Bırakın kaybolayım

Bu şehrin bağrında...

Ninnileri söylendi,

Destanından bahsedildi bana 

Büyüleriyle büyülendiğim,

Yaşanan aşklarıyla; 

Tütsülendiğim,

Güzeli,güzellikleriyle

Efsunlandığım

İstanbul’u..; 

Verin nolur! 

Verin! Verin! bu şehri bana..

Sanki ezelden bilirmişcesine

Kaybolayım  şehirde,

Şehirse  bende...

Verin bana yitiğimi,

Peşime düşmeden...

Ben,İstanbul da; 

Şöyle bir kaybolayım...

Kaybolmalıyım,

Ben,İstanbul da...

(24.03.2006)', 'Yaşanmamış  Komplekslerim var Benim orda.., Bırakın kaybolayım Bu şehrin bağrında... Ninnileri söylendi, Destanından bahsedildi bana  Büyüle...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Coşkun Kale']::text[], 8.5, '{"poet":"Mustafa Coşkun Kale","poet_slug":"mustafa-coskun-kale","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/istanbul-da-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıllardır Bekliyorsun', 'yillardir-bekliyorsun-yusuf-onder-bahceci-v8gfz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yıllarca bekliyorsun istasyonda gelecek treni,

Tamam geliyor diyorlar, bir haber, tren rötarlı,

Kafan bozuluyorda hep böyle oluyor diyorsun,

Yıllarca bekliyorsun, istasyonda gelecek treni.

Biz alışmışız be böyle beklemeye beklemeye,

Beni boşver sen de, benim yârim beklemeye,

Hep kendimi dinlerim, hay kâlbim, teklemeye,

Biz alışmışız be böyle beklemeye beklemeye...', 'Yıllarca bekliyorsun istasyonda gelecek treni, Tamam geliyor diyorlar, bir haber, tren rötarlı, Kafan bozuluyorda hep böyle oluyor diyorsun,...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yillardir-bekliyorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıl payı', 'kil-payi-reyhan-tataroglu-6v3x9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'herşeyi

                                     vurma akıla

                                     akıl ne yapsın

                                     kırk kıla', 'herşeyi                                      vurma akıla                                      akıl ne yapsın                                ...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Tataroğlu']::text[], 8.5, '{"poet":"Reyhan Tataroğlu","poet_slug":"reyhan-tataroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kil-payi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tenha kadın', 'tenha-kadin-hatire-nurgul-kiwn6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Geceni sehere

seheri geceye telesdirir

susar– 

dudaklarına kadar

küser– 

bakışlarından bile

öylece yaşar günleri

unudar mevsimleri

ah...ne kadar beklese de

yollar geriye boş döner

uykulardan hayata

gözlerinde yaş döner

sükut dolanır gölgesine

izler onu addım–addım

yalnız

karanlıkla öpüşür tenha kadın.', 'Geceni sehere seheri geceye telesdirir susar–  dudaklarına kadar küser–  bakışlarından bile öylece yaşar günleri unudar mevsimleri ah...ne k...', ARRAY['Türk Edebiyatı','Şiir','Hatire Nurgül']::text[], 8.5, '{"poet":"Hatire Nurgül","poet_slug":"hatire-nurgul","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/tenha-kadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalebe', 'kalebe-hatire-nurgul-ay4g3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'O gün bakışlar açacak şeheri–

bir az titrercesine.

Orda baş meydanda 

insan izdihamı

baş alıb gidicek 

uzaklara doğru.

Güneşin şüaları yorulacak

ayak zerbinden

Ve sen

itkin düşen sağ kolunun 

yokluğunu bile 

duymayacaksın.

Bir elli yapışıb 

bayrağın eteyinden

doyunca– doyunca 

ağlıyacaksın.', 'O gün bakışlar açacak şeheri– bir az titrercesine. Orda baş meydanda  insan izdihamı baş alıb gidicek  uzaklara doğru. Güneşin şüaları yorul...', ARRAY['Türk Edebiyatı','Şiir','Hatire Nurgül']::text[], 8.5, '{"poet":"Hatire Nurgül","poet_slug":"hatire-nurgul","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kalebe-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lal kızın sevgisi', 'lal-kizin-sevgisi-hatire-nurgul-c2ckt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'belki de 

sevgi sükutdur

sevmek ise 

benim kimi sessizlik

arabir 

ağlamak istiyorum

ve dilimle tatmak

«sevirem» sözünü

ah, bir duyura bilsem 

boyat sesimi.', 'belki de  sevgi sükutdur sevmek ise  benim kimi sessizlik arabir  ağlamak istiyorum ve dilimle tatmak «sevirem» sözünü ah, bir duyura bilsem...', ARRAY['Türk Edebiyatı','Şiir','Hatire Nurgül']::text[], 8.5, '{"poet":"Hatire Nurgül","poet_slug":"hatire-nurgul","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/lal-kizin-sevgisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güncel Beyitler 98', 'guncel-beyitler-98-huseyin-avdic-gh1k5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Insan Maymundan Türemez! 

Maymundan degil, maymundan sonra topraktan yaratmistir Allah insani.

Bu halkedi$te müsvedde yapmistir yüce Halik, maymun denen varligi.

Berlin, 12 Mart 2006.', 'Insan Maymundan Türemez!  Maymundan degil, maymundan sonra topraktan yaratmistir Allah insani. Bu halkedi$te müsvedde yapmistir yüce Halik, ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/guncel-beyitler-98-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güncel Beyitler 99', 'guncel-beyitler-99-huseyin-avdic-p8isx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Insanin Yapilisi

Insanin asli degil, insan müsveddesidir maymun denen yaratik.

Evrimle degil, mustakil yapimla halketmistir insani yüce Hâlik.

Berlin, 15 Mart 2006.', 'Insanin Yapilisi Insanin asli degil, insan müsveddesidir maymun denen yaratik. Evrimle degil, mustakil yapimla halketmistir insani yüce Hâli...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/guncel-beyitler-99-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstek', 'i-stek-ramazan-ozuturk-ycne3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Güneşim ol, sevdalım ol

Damla damla içime dol

Kalbimin parselleri bol

Islanma, can evimde kal

Kollarımın incisi ol

Dallarımın  meyvesi ol

Gel, davamın sevdası ol

Ayrılma, can evimde kal

Gelinimin vatanı ol

Şah damarımın kanı ol

Öz yurdumun fidanı ol

Darılma, can evimde kal

Bayrağımın direği ol

Şu harcımın küreği ol

Gökte yıldızlar beği ol

Alçalma, can evimde kal

Milletimin türküsü ol

Bu dünyanın öyküsü ol

Milyonların ülküsü ol

Yenilme, can evimde kal

Kardeşimin senedi ol

Varlığının muradı ol

Bu yolların sıradı ol

satılma, can evimde kal

Yoldan sapana rehber ol

Allah yolunda nefer ol

Kazanılan bir zafer ol

Hiç yılma, can evimde kal

Hürriyetin aşığı ol

Helal aşın kaşığı ol

Bütün işlerin sağı ol

Hiç solma, can evimde kal

Nimetlere bereket ol

Maddelere hareket ol

Öz vatanına rahmet ol

Hiç susma, can evimde kal

Mazlumun sırtına çul ol

Yaratan Allah''a kul ol

Yazılan mektuba pul ol

Kaybolma, can evimde kal

Sadık dostuna destek ol

Çelme atana köstek ol

Kardeşlik için gerek ol

Bölünme, can evimde kal

Riyakar olma, mertçe ol

Yağdanlık değil, sertçe ol

Neyine gerek Türkçe ol

Kırılma, can evimde kal

Özütürk der, gel, kucak ol

Türkiye''mize bucak ol

Özgürce tüten ocak ol

Hiç sönme, can evimde kal', 'Güneşim ol, sevdalım ol Damla damla içime dol Kalbimin parselleri bol Islanma, can evimde kal Kollarımın incisi ol Dallarımın  meyvesi ol Ge...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Özütürk']::text[], 8.5, '{"poet":"Ramazan Özütürk","poet_slug":"ramazan-ozuturk","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/istek-46-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ataşına Düştüm Yâr', 'atasina-dustum-y-r-tulay-sustam-fvf4a', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bıraksaydın ellerimi

düşecektim

gözlerinin çukuruna

güneşin saçından süzülen

bir damla yağmurla 

susuzluğum dinecekti

istemedin 

/

istemedim yokluğu...

oysa

kirpiğinin ucuna dizmiştim

bütün yıldızları

yokluğunda hepsi intihar etti 

ataşına düştüm yâr! ...

yokluğun benim çoğul yalnızlığım

nereye gidersen git! ...

bırakma çocuk ellerimi

başımın düştüğü yer

...omzun olsun...



(yalnızlığım benim çoğul türkülerim.)   * Can Yücel', 'bıraksaydın ellerimi düşecektim gözlerinin çukuruna güneşin saçından süzülen bir damla yağmurla  susuzluğum dinecekti istemedin  / istemedim...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/atasina-dustum-yar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok Şaşarım', 'cok-sasarim-yusuf-onder-bahceci-xg14u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çok şaşarım şu insanlara her biri ayrı alem,

Kimisi, Umre''ye gider, kimisi turneye gider,

Çok şaşarım şu insanlara her biri ayrı alem,

Kimi turnayı gözünden vurur kimi de vurulur.', 'Çok şaşarım şu insanlara her biri ayrı alem, Kimisi, Umre''ye gider, kimisi turneye gider, Çok şaşarım şu insanlara her biri ayrı alem, Kimi ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/cok-sasarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıraya Koyup Ses vermemiş-Ey İlahi', 'siraya-koyup-ses-vermemis-ey-i-lahi-recep-uslu-hsgaj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sıraya koyup ses vermemiş

Beni dünya dinleye

Meshep edip el vermemiş

Sazım inim inim inleye

Boy verip soy vermemiş

Herkes gelsin peşimden

Ne yapacağımı bilemem ben

Unutuluyorum şimdiden.

Ses vermemiş,söz vermemiş

Yemeğime tuz vermemiş

Gönlümden geçer konak

Bekci kulübesi vermemiş.

Boy verip soy vermemiş

Herkes gelsin peşimden

Gidiyorum sessiz sessiz

Yürteğime buz vermemiş.

Bir eşim var güzeller güzeli

Gelip ona naz vermemiş

Bindim sırtına gidiyorum

Yerde isteğim hız vermemiş.

Şükür derim bende olana

Bakarım ben kızla oğlana

Yeminliyim doğuştan yalana

Doğruya gitmeye diz vermemiş.

Ağlayacak gözüm yok,isteyecek yüzüm

Ben hem kendime hem tanrıya küsüm

Aykırı mı geçtim,yan mı baktım

Her yandan çok öksüzüm.

Uslu şaşırdı dediğin bilmez

Ezilmekle,üzülmekle isteğin gelmez

Affetmek,sevmek büyük lütuf

Sevenle sevilen hişbir zaman ölmez.

31.05.2002', 'Sıraya koyup ses vermemiş Beni dünya dinleye Meshep edip el vermemiş Sazım inim inim inleye Boy verip soy vermemiş Herkes gelsin peşimden Ne...', ARRAY['Türk Edebiyatı','Şiir','Recep Uslu']::text[], 8.5, '{"poet":"Recep Uslu","poet_slug":"recep-uslu","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/siraya-koyup-ses-vermemis-ey-ilahi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İyi Aklımı Kaybetmedim', 'i-yi-aklimi-kaybetmedim-yusuf-onder-bahceci-5oiev', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni kaybettim de, iyi aklımı, aklımı, kaybetmedim,

Seninle ne konuştumsa bilemedim seni kaybettim,

Neden sen de bir şeyler demedin, neden demedin,

Seni kaybettim de, iyi aklımı, aklımı, kaybetmedim,

Seninle ne konuştumsa bilemedim seni kaybettim...', 'Seni kaybettim de, iyi aklımı, aklımı, kaybetmedim, Seninle ne konuştumsa bilemedim seni kaybettim, Neden sen de bir şeyler demedin, neden d...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/iyi-aklimi-kaybetmedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keşke Amatör Kamera Çekseydi', 'keske-amator-kamera-cekseydi-yusuf-onder-bahceci-v3czw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Keşke amatör bir kamera çekseydi seyretseydin,

Seni benden nasıl ayırmışlar, şimdi bir görseydin,

Vay alçaklar vay, vay demek böyleymiş deseydin,

Keşke amatör bir kamera çekseydi seyretseydin,

Seni benden nasıl ayırmışlar, şimdi bir görseydin...', 'Keşke amatör bir kamera çekseydi seyretseydin, Seni benden nasıl ayırmışlar, şimdi bir görseydin, Vay alçaklar vay, vay demek böyleymiş dese...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/keske-amator-kamera-cekseydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Analar ACILARA Gebe', 'analar-acilara-gebe-cigdem-altinoz-wqk3r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Analar acılara gebe

Sancılar 

Bıçak bıçak işler kemiğe

Analar

Büyüyemeyen 

 - bebelere gebe

Sorgular gözleri bebelerin

Düşerken 

 - kor alevler başlara

Uzanan eller çaresiz

Özgürlük

-   kelepçeli 

Görünmez 

 - düğmelere basan 

-   kirli parmaklar

Aymazlık içinde

Anlamsız 

ve arsız 

-    hırslara gebe

Resimlere yazılırken 

Sessiz çığlıklar

Zûlme kapanır gözler

Eğilir başlar 

Ne ki 

Başa geçen çuvallar 

Utanç

Yürekte başlar

Adı garip, kendi garip

.......ve çırılçıplak

Sırıtırken şeytanın en beteri

Yığılmış etlerin

Altında kalmış ahlâk

Sıyrılıp  örtüsü

Hoyratça 

- kirletilirken beden

Ebu Garip bekçilerinin

Salyası akar

Ahh…

Bunu ancak

Çeken anlar

Analar 

Filistin’de

Felluce’de

Kabil’de

……….hep acılara gebe…

isimsiz 

sahipsiz

büyüyemeyen çocuklara

kırılacak fidanlara

utançlara

utançlara

utançlara

analar

hep 

acılara gebe', 'Analar acılara gebe Sancılar  Bıçak bıçak işler kemiğe Analar Büyüyemeyen   - bebelere gebe Sorgular gözleri bebelerin Düşerken   - kor alev...', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Altınöz']::text[], 8.5, '{"poet":"Çiğdem Altınöz","poet_slug":"cigdem-altinoz","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/analar-acilara-gebe-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Böylemi Olacaktık', 'boylemi-olacaktik-elif-aktan-tjhtx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu hasret kapımızı ne çabuk çaıldı gitti,

Söyle sevdiğim söyle,böylemi olacaktık.

Mutluluğa doymadan her şey bir anda bitti,

Söyle vefasız söyle,böylemi olacaktık......

Sevgimiz çok yüceydi parçalandı bir anda,

Umutlarım hep soldu takat kalmadı canda,

Sanırdım büyük sevgi bir tek bizde cihanda,

söyle hayırsız söyle, böylemi olacaktık....

İsyanım sana değil gözden akan yaşıma,

Seninle paylaştığım bir kaç lokma aşıma,

Taştan taşa vurduğum o talihsiz başıma,

Söyle ne olur söyle,böylemi olacaktık....

Gözyaşlarım hiç böyle çaresizce akmadı,

Kolum kanadım kırık ateşinde yakmadı,

Delice sevdiğimde maziye bir bakmadı,

Söyle Allah''ım bizde böylemi olacaktık.....

                                                        NİSAN.1999/E.AKTAN

(yürek yangını ne demek ben bilirim tabii severken ayrılmayıda)', 'Bu hasret kapımızı ne çabuk çaıldı gitti, Söyle sevdiğim söyle,böylemi olacaktık. Mutluluğa doymadan her şey bir anda bitti, Söyle vefasız s...', ARRAY['Türk Edebiyatı','Şiir','Elif Aktan']::text[], 8.5, '{"poet":"Elif Aktan","poet_slug":"elif-aktan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/boylemi-olacaktik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göçmen Kuşlara Döndüm', 'gocmen-kuslara-dondum-yusuf-onder-bahceci-gh2ik', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Senden ayrılınca göçmen kuşlara döndüm,

Sadece göçmen kuşlar mı, ölüye döndüm,

Gövelek tutmuş gibi nasıl nasıl da döndüm, 

Senden ayrılınca göçmen kuşlara döndüm...', 'Senden ayrılınca göçmen kuşlara döndüm, Sadece göçmen kuşlar mı, ölüye döndüm, Gövelek tutmuş gibi nasıl nasıl da döndüm,  Senden ayrılınca ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gocmen-kuslara-dondum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'El Bilsin! ! !', 'el-bilsin-saim-bastik-wnwo4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ey vefasız yad’a saldın başımı

Yokluğun bir hançer deler döşümü

Senin için akıttım göz yaşımı

Sen bilmedin, karıştığı sel bilsin.

Sensiz tutmaz oldu ayağım elim

Adını anarken kurudu dilim

Kaç defa dalında soldu hep gülüm

Sen bilmedin,şu kuruyan dal bilsin.

Kalbin yosun tutmuş,inandım,sahi

Hep bana gönderdin sitemi ahı

Çok bekledim pencerede sabahı

Sen bilmedin,sana gelen yol bilsin.

Ben yoluna adamıştım ömrümü

Ölür isem sen kazarsın kabrimi

HARÎMÎ''yim; kıymetimi, kadrimi

Sen bilmedin,ne diyeyim el bilsin.

23/03/2006', 'Ey vefasız yad’a saldın başımı Yokluğun bir hançer deler döşümü Senin için akıttım göz yaşımı Sen bilmedin, karıştığı sel bilsin. Sensiz tut...', ARRAY['Türk Edebiyatı','Şiir','Saim Bastık']::text[], 8.5, '{"poet":"Saim Bastık","poet_slug":"saim-bastik","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/el-bilsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '** Eylül Ve Yollar *', 'eylul-ve-yollar-ali-riza-atasoy-dhkap', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '-Merhum Ergun Aytaç''ın ardından-

Fecrin alacakaranlığında ağlıyor gül,

Şimdi gezinirken hüzün bahçelerinde Eylül.

Bir veda şarkısının ahengiyle,

Masmavi gökyüzünü duru şafakları,

Kar mavisi kirpikleri kuşatmış sevgilinin.

Guruba akseden solgun rengiyle,

Sonuna yaklaşmaktayız bir hüzün mevsiminin.

Uzun ve beyaz bir vadide yol alırken,

Nafile gençliğim,

Her iklimde ayrı izler bıraktım.

Ey elest bezminde tanıştığım sevgilim,

Sana ne kadar da uzaktım.

Gözlerinden düşerken birkaç billur yaş,

Omuzlarında yük ve heybeleriyle,

Yolcular gidiyor yavaş yavaş.

Küçülüp kaybolan gölgeleriyle,

Gönülleri Tanrı''ya sırdaş.

İz sürdüm peşlerinden adım adım,

Ben yürüdüm, yolculuk buysa eğer,

Ömrümü bu sonsuz yollara adadım.

Eylül, şaşkınlığımın diğer adıymış meğer.

Ya da öbür yüzüyle sevdiğim ince kadın.

Eylül sır dolu cazibe, şuh bir gülüştür,

Yaşanmış sevdaları anlatan.

İnce ve kıvrımlı yollardan süzülüştür,

Garip yolcuları ağlatan.

Eylül, ölümden de öte düştür.

Fecrin alacakaranlığında ağlıyor gül,

Bilmem hangi ömre nihayet için gelmiş,

Şimdi hüzün bahçelerinde gezinen Eylül.

             (Muradiye, 21.09.2002)', '-Merhum Ergun Aytaç''ın ardından- Fecrin alacakaranlığında ağlıyor gül, Şimdi gezinirken hüzün bahçelerinde Eylül. Bir veda şarkısının ahengi...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Atasoy']::text[], 8.5, '{"poet":"Ali Rıza Atasoy","poet_slug":"ali-riza-atasoy","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/eylul-ve-yollar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan Hakları Var', 'i-nsan-haklari-var-yusuf-onder-bahceci-15en9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bunlar nasıl askere, polise böyle taş atar,

Bunların eli yaslansın, nasıl da, taşlar atar,

İnsan hakları var, polisler taş atana bakar,

Bunlar nasıl askere, polise böyle taş atar,

Bunların eli yaslansın, nasıl da, taşlar atar...', 'Bunlar nasıl askere, polise böyle taş atar, Bunların eli yaslansın, nasıl da, taşlar atar, İnsan hakları var, polisler taş atana bakar, Bunl...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/insan-haklari-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
