INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret', 'hasret-isik-german-ersoy-ot8sh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir an 

Gözgöze geldiler

Garda,

Sonra hasretle

Sarıldılar...

Ve de tam öpüşecekken

Yüzleri kızardı

Vazgeçtiler...', 'Bir an  Gözgöze geldiler Garda, Sonra hasretle Sarıldılar... Ve de tam öpüşecekken Yüzleri kızardı Vazgeçtiler......', ARRAY['Türk Edebiyatı','Şiir','Işık German Ersoy']::text[], 8.5, '{"poet":"Işık German Ersoy","poet_slug":"isik-german-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/hasret-351-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olduğum yerde', 'oldugum-yerde-mikdat-bal-yx8xg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Zifiri karanlıkta, gece sabaha karşı

Aklıma vurduğunda, döndüm olduğum yerde

Öyle bir bağırdım ki sesim titretti arşı

İsmini çağırmıştım andım olduğum yerde

Kendimi öyle yalnız hissettim aynı anda

Halbuki hayalinle mevcut idin her yanda

Ruhum daralıverdi çıkıyordu bu can da

Döşümde Azraili sandım olduğum yerde

Ufuklarına baktım cenup ile şimalin

Zeval kaçınılmazdı erdiğinde kemalin

Ağladım dolu dolu, hayalimde cemalin

Gözlerime mendili bandım olduğum yerde

Mikdatî der ağlarım, artık bir daha gülmem

Mendili atıverdim göz yaşlarımı silmem

Seneler hasretini unutturur mu bilmem

Gönlüme ateş düştü yandım olduğum yerde', 'Zifiri karanlıkta, gece sabaha karşı Aklıma vurduğunda, döndüm olduğum yerde Öyle bir bağırdım ki sesim titretti arşı İsmini çağırmıştım and...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/oldugum-yerde-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kim Demiş', 'kim-demis-isik-german-ersoy-5pk4j', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kim demiş

Ülkemiz 

Fakir diye

Dilencilerimizin  bile

Bankalarda

Binlerce doları var', 'Kim demiş Ülkemiz  Fakir diye Dilencilerimizin  bile Bankalarda Binlerce doları var...', ARRAY['Türk Edebiyatı','Şiir','Işık German Ersoy']::text[], 8.5, '{"poet":"Işık German Ersoy","poet_slug":"isik-german-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kim-demis-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocukluğum', 'cocuklugum-zekiye-yavuz-hq1rz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çocukluğum düşlerim

Olmadı hiç bebeğim

Buldum mu çatal çubuk

Bir de kol yapmak lazım

Anneme götürürdüm güzel annem benim

Sarardı onları bir bez parçasıyla

Sonra bir de kafa suratını sen boya

İki göz bir ağız

İşte sana mutluluk

Oysa şimdi öyle mi 

Yüreğini ver sen de

Servetini döksen de

Hep boşlukta bir gençlik

Avrupalı olduk ya', 'Çocukluğum düşlerim Olmadı hiç bebeğim Buldum mu çatal çubuk Bir de kol yapmak lazım Anneme götürürdüm güzel annem benim Sarardı onları bir ...', ARRAY['Türk Edebiyatı','Şiir','Zekiye Yavuz']::text[], 8.5, '{"poet":"Zekiye Yavuz","poet_slug":"zekiye-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/cocuklugum-62-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sigara Belası', 'sigara-belasi-guner-kaymak-z6ddt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sigaradan öldü binlerce insan

Niye içiyoruz diyen olmadı

Yetmiş iki hastalığa yol açan

Bu illeti kimse anlayamadı

İştahin kesilir yemek yiyemen

Nefesin daralır yol yürüyemen

Ciğerlerin çürür hiç fark edemen

Millet bu gerçeği anlayamadı

Meraktan geliyor bunun kaynağı

Çoğunun kesildi kolu bacağı

Nicesinin söndü evi ocağı

Dönüp arkasına bakan olmadı

Yel alır dumanı yakıp içerken

Parayı el alır sana satarken

Öksürük uyutmaz gece yatarken

Millet vurdum duymaz hiç aldırmadı

İçmeyen içenden zarar görüyor

İçmeyene bile duman geliyor

Seni düşmanına muhtaç ediyor

Bu acı gerçeği gören olmadı

Yazık ki sararmış solmuş dudaklar

İçine girmiş çökmüş yanaklar

Sanki kınalıdır eller parmaklar

Uçurum başında geri dönen yok

Kadını erkeği içiyor bunu

Bunu içenlerin hazindir sonu

Bu sigara bence bizans oyunu

İnsanlar uykudan uyanamıyor

Kapağında yazar ölüm saçıyor

Millet bile bile bunu içiyor

Bırakamam diyen yalan söylüyor 

Bu millet gerçeği anlayamadı

Oldukça da  berbat ağır kokusu

Dumandan tıkanmış nefes borusu

Derhal bırakmaktır bence dogrusu

Bu millet gerçeği anlayamadı

Sigara içenden  mağdur olurum

Yanımda içerler fena olurum

Yüzüme üflerler sinir olurum

Kazılan kuyuyu kimse görmüyor

Ozan Güner Kaymak 

Amsterdan 27.03.2006', 'Sigaradan öldü binlerce insan Niye içiyoruz diyen olmadı Yetmiş iki hastalığa yol açan Bu illeti kimse anlayamadı İştahin kesilir yemek yiye...', ARRAY['Türk Edebiyatı','Şiir','Güner Kaymak']::text[], 8.5, '{"poet":"Güner Kaymak","poet_slug":"guner-kaymak","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/sigara-belasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimdeki öteki', 'i-cimdeki-oteki-elazigli-mustafa-kaya-jisjw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yine

sokaklara düştüm

karanlık…yarı aydınlık

gün boyu yalnızlık

sarınıp kendime yürüdüm.

güneş küsmüş

hiç açmamış.

hayallerimin denizine

dalıyorum

ıslık çalıyor rüzgar

geniz yakıcı yosunu tadıyorum.

görmediğim bir yüz

duymadığım bir ses

arıyorum.. 

kalabalıklar,..kalabalıklar…

sis bulutları gibi.

bütün sınırları yok eden

ruh gözüm.

su değmiş ateş sanki,

karardım

öksüz kaldım.

aralık kışına,

karlara 

yalınayak basmış gibi

üşüyor bedenim.

yağmur ve soğuk,

sonsuz  gökler de 

bahara  dönüşmeyi beklerken,

kendi karanlığını acıtan 

ay ışığı sevgilim,

rüzgarlara verir kederini

tenimi üşütür hüznü

bundandır,

kan ağlıyor içimdeki öteki …

Mustafa kaya

25.03.2006 / ÜSKÜDAR

www.mustafakaya.net/frm', 'yine sokaklara düştüm karanlık…yarı aydınlık gün boyu yalnızlık sarınıp kendime yürüdüm. güneş küsmüş hiç açmamış. hayallerimin denizine dal...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/icimdeki-oteki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değişiyorum', 'degisiyorum-i-brahim-burak-gogus-z49db', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yavaş yavaş karışıyorsun kanıma 

Damarlarımdan akan kan aynı değil artık

Hergün biraz daha sen oluyor erkekliğim,

Hergün biraz daha dişi, biraz daha anaç.

Tenim tenine deydiğinden beri böyleyim.

Belki de 

Bu yüzden bütün gitmelerim

Gitmeliyim; 

Çünkü sen olmadan da seni sevmeleyim.

Uzaklarda,

Toprağın başka  başka koktuğu yerlerde

Başka başka insanlarda çoğalmalıyım; 

Çoğalmalıyım ki

Bende bütün insanlığı görmelisin; 

Görüp

Sende çoğalmalısın

Çoğaldıkça 

Toprağın başka başka koktuğu yerlerde

Başka başka insanlarda 

Beni sevmelisin.

Nisan 1998.', 'Yavaş yavaş karışıyorsun kanıma  Damarlarımdan akan kan aynı değil artık Hergün biraz daha sen oluyor erkekliğim, Hergün biraz daha dişi, bi...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Burak Göğüş']::text[], 8.5, '{"poet":"İbrahim Burak Göğüş","poet_slug":"i-brahim-burak-gogus","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/degisiyorum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Şey Bittikten Sonra', 'her-sey-bittikten-sonra-mehmet-sait-akkus-dba2e', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevsende olur,sevmesende olur

Kalsanda olur, kalmasanda olur

Bilsende olur, bilmesende olur

Benim yüreğimi yaktıktan sonra

Arasanda olur,aramasanda olur

Sorsanda olur,sormasanda olur

Dilesende olur,dilemesende olur

Benim ümitlerim bittikten sonra

Yaşasam olur,yaşamasam olur

Görsende olur,görmesende olur

Anlasan olur,anlamasan olur 

Benim duygularım öldükten sonra', 'Sevsende olur,sevmesende olur Kalsanda olur, kalmasanda olur Bilsende olur, bilmesende olur Benim yüreğimi yaktıktan sonra Arasanda olur,ara...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sait Akkuş']::text[], 8.5, '{"poet":"Mehmet Sait Akkuş","poet_slug":"mehmet-sait-akkus","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/her-sey-bittikten-sonra-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelde Bir Bak', 'gelde-bir-bak-mehmet-sait-akkus-qz4r5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dertlerinle büyüttüğüm

Sevdan için öldğrdüğüm

Senin için büyüttüğüm

Gelde bir bak sevdalara

Senin için acılara

Tuz ektim yaralara

Senin için yarınlara

Gelde bir bak ne yapmışım

Acın bile tatlı gelir

Yar karşıdan atlı gelir

Senin için farklı gelir

Sevdana yandığım günler

Senin için hüzünlüdür

Ateşine gönüllüdür

Senin için hep süslüdür

Gelde bir bak yüreğime', 'Dertlerinle büyüttüğüm Sevdan için öldğrdüğüm Senin için büyüttüğüm Gelde bir bak sevdalara Senin için acılara Tuz ektim yaralara Senin için...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sait Akkuş']::text[], 8.5, '{"poet":"Mehmet Sait Akkuş","poet_slug":"mehmet-sait-akkus","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gelde-bir-bak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muhabbetten Vecde', 'muhabbetten-vecde-zeynep-yildirim-gycwh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şiir manayı okuyucuda buldu

Gönül hakikati sevgilide buldu

Onun deryasında muhabbete erdi

Gel dost muhabbetten vecde gidelim', 'Şiir manayı okuyucuda buldu Gönül hakikati sevgilide buldu Onun deryasında muhabbete erdi Gel dost muhabbetten vecde gidelim...', ARRAY['Türk Edebiyatı','Şiir','Zeynep Yıldırım']::text[], 8.5, '{"poet":"Zeynep Yıldırım","poet_slug":"zeynep-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/muhabbetten-vecde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayranıyız Biz', 'hayraniyiz-biz-ali-balliktas-hldsz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gönüller şehrinde malımız çoktur,

Böyle bir pazarın dükkanıyız biz.

Bizim inancımız yolumuz haktır,

Ali evladının hayranıyız biz.

Bizim ulumuzun her sözü aktır.

Bize uymayanlar bizden uzaktır.

Aşktan başkasına meylimiz yoktur,

Can ile cananın kurbanıyız biz.

Bizim kilerimiz haramı almaz.

Aksini yapanlar bizimle kalmaz.

Kin tutmayız bizde düşmanlık olmaz,

Cem olur kırkların meydanıyız biz.

Kimdir bu MAZLUMİ böyle söyleyen.

Bizden değil zıkkım lokmalar yiyen.

Bir lokmayı binler ile binleyen,

O ulu Hünkar''ın cananıyız biz...', 'Gönüller şehrinde malımız çoktur, Böyle bir pazarın dükkanıyız biz. Bizim inancımız yolumuz haktır, Ali evladının hayranıyız biz. Bizim ulum...', ARRAY['Türk Edebiyatı','Şiir','Ali Ballıktaş']::text[], 8.5, '{"poet":"Ali Ballıktaş","poet_slug":"ali-balliktas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hayraniyiz-biz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Artık Gelmesen de Olur-1', 'artik-gelmesen-de-olur-1-sahin-erturk-hgohu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sayamadım kaç yıl oldu

Hasretinden beynim durdu

Gözyaşlarım beni boğdu

Artık gelmesen de olur

(27.03.2006)', 'Sayamadım kaç yıl oldu Hasretinden beynim durdu Gözyaşlarım beni boğdu Artık gelmesen de olur (27.03.2006)...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/artik-gelmesen-de-olur-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir İstanbul Şarkısı', 'bir-i-stanbul-sarkisi-abbas-yurt-qzdxu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir İstanbul Şarkısı

Bir İstanbul şarkısı,

Dolanır hep dillerde.

Yankılanır beynimde,

Alır götürür beni...

Alır götürür benliğimi,

Anlatılmaz duyguların derinliklerine! 

Hüzünlenir gönlüm! ...

Hüzünlenir pervasızca...

Heyhaaat...Hey! 

Bu şarkı; 

Geçmişten bugüne 

Nice sevdaları fısıldar

Kulaklarımı yırtarcasına

Ruhumun benliğine.

Bu şarkı; 

Nice sevdalıların 

Hikâyesini yazar

Masmavi Boğaz’ın

Martı sesleriyle çınlayan

Kız Kulesi’nin 

Sevdayı haykıran sularına.

Bu şarkı; 

Peygamber’in sözlerini

Eyüp Sultan kültürünün zenginliği,

Karaca Ahmet’in gizemiyle

Bir mozayik güzeliğinde

Ayasofya, Sultan Ahmet ve Süleymaniye’nin

Gök kubbelerinde sunar bizlere.

Bu şarkı; 

Yıldırım Bayazıt’ları,

Fatih Sultan Mehmet’leri,

Ak Şemsettin’leri,

Kanuni Sultan Süleyman’ları,

Mimar Sinan’ları,

Hazerfan Çelebi’leri

ve daha nicelerini anlatır! 

Tarihten bugüne...

Kuşaktan kuşağa...

Geçmişten geleceğe...

Bir köprü olur gönüllere.

Bu şarkı; 

Bir tutkuyu, bir sevdayı, bir özlemi

Dile getirir sevdalıların gönlünde.

Bu tutku İstanbul tutkusudur,

Bu sevda İstanbul sevdasıdır,

Bu özlem İstanbul özlemidir.

Bu şarkı, bir İstanbul şarkısıdır

İstanbul’u anlatır nağmeleriyle! 

Bir İstanbul şarkısı

Söylenir hep dillerde.

Bir İstanbul şarkısı 

Yankılanır hep beynimde.

Alır götürür beni,

Sevdanın doruklarına! 

Tir tir titretir ruhumu

Atar Boğaz’ın mavi sularına

Huzur bulur bedenim

Ruhumla beraber sonsuza dek

Bir İstanbul şarkısında...

Bu İstanbul şarkısında.

                     26.03.2006

                    Abbas YURT', 'Bir İstanbul Şarkısı Bir İstanbul şarkısı, Dolanır hep dillerde. Yankılanır beynimde, Alır götürür beni... Alır götürür benliğimi, Anlatılma...', ARRAY['Türk Edebiyatı','Şiir','Abbas Yurt']::text[], 8.5, '{"poet":"Abbas Yurt","poet_slug":"abbas-yurt","theme":"Türk Şiiri","is_hero":false,"total_lines":63,"source_url":"https://www.antoloji.com/bir-istanbul-sarkisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzele Bak Güzele', 'guzele-bak-guzele-sahin-erturk-3pvjg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yeni yetme gencecik

Selvi gibi incecik

Huri sanki Ayşecik

Güzele bak güzele

Ceylan gibi bakıyor

Güneş gibi yakıyor

Yüreğime akıyor

Güzele bak güzele

Manken sıfır yanında

Doğruluk var kanında

Tıpkı Anzer tadında

Güzele bak güzele

Zeytin gibi gözü var

Baldan tatlı sözü var

Yüreğimde közü var

Güzele bak güzele

(17.07.1978) 

KARABORSA SEVGİ adlı

5.nci şiir kitabımdan', 'Yeni yetme gencecik Selvi gibi incecik Huri sanki Ayşecik Güzele bak güzele Ceylan gibi bakıyor Güneş gibi yakıyor Yüreğime akıyor Güzele ba...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/guzele-bak-guzele-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'El Sıkışmak', 'el-sikismak-recep-uslu-89ffa', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yan yan yürüdüm

Bu sabah

Yayan yürüdüm.

O da yürüdü.

Köpüre köpüre,yeleleri dikerek

Gözleri kızartarak

Kuyruğu sallayarak

Yürüdüm.

O da yürüdü.

Dikine,dikine

Geldim üzerine

O da benim üzerime geldi.

Öyle bir yerde durduk ki...

Bir adım atsam onu çiğneyeceğim

O bir adım atsa beni çiğner

O da gelmedi,ben de gitmedim.

İkimizde zarar görmedik.

Barış sa bu eger

Bir başka bahara

Bir başka zamana

Bir başka kıyıya

Kaldı.

El sıkışmamız.

22.07.1999-Ünye', 'Yan yan yürüdüm Bu sabah Yayan yürüdüm. O da yürüdü. Köpüre köpüre,yeleleri dikerek Gözleri kızartarak Kuyruğu sallayarak Yürüdüm. O da yürü...', ARRAY['Türk Edebiyatı','Şiir','Recep Uslu']::text[], 8.5, '{"poet":"Recep Uslu","poet_slug":"recep-uslu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/el-sikismak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen..', 'sen-tarik-teke-2784f', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen gülen gözlerimdeki ışık

Mutluluk dolu sözlerimdeki perimdin

Günlerim seninle başlar

En unutulmaz anlarımı seninle yaşardım.

Güneş bile senin yanımda olmadıgın gün

İçimi ısıtamazdı

Sen benim yaşam kaynagım,herşeyimdin

Ve işte sen gittin,ben bittim..

Hiç bu dünyada varolmamış gibi

Adeta hiç dogmamış gibi

Yaşamdan silindim..

                                                    şubat/2005', 'Sen gülen gözlerimdeki ışık Mutluluk dolu sözlerimdeki perimdin Günlerim seninle başlar En unutulmaz anlarımı seninle yaşardım. Güneş bile s...', ARRAY['Türk Edebiyatı','Şiir','Tarık Teke']::text[], 8.5, '{"poet":"Tarık Teke","poet_slug":"tarik-teke","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sen-800-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İyilik Meleği', 'i-yilik-melegi-erdal-akkoyun-et3kb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben bir iyilik meleğiyim

Mutlulukla beslenirim 

Aşkla kalplerde coşarım

Sevgiyle ebediyen yaşarım

Parlar ışığım sizlerle

Mutluluğum gökkuşağı rengiyle

Sizi bırakıp gitmem

Yüzleriniz hep güldükçe

Güneş ufukta doğdukça

Sevgiler hiç bitmedikçe

Gönülleri aydınlatırım

İyiler hiç bitmedikçe', 'Ben bir iyilik meleğiyim Mutlulukla beslenirim  Aşkla kalplerde coşarım Sevgiyle ebediyen yaşarım Parlar ışığım sizlerle Mutluluğum gökkuşağ...', ARRAY['Türk Edebiyatı','Şiir','Erdal Akkoyun']::text[], 8.5, '{"poet":"Erdal Akkoyun","poet_slug":"erdal-akkoyun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/iyilik-melegi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herkes Sevemiyor', 'herkes-sevemiyor-yusuf-onder-bahceci-9w5x8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ilık, ılık esen Meltemlere sordum seni,

Acaba, acaba düşünüyor mudur beni,

Kulağıma fısıldadı çok uzaklarda dedi,

Sanki, sanki ben bilmiyormuşum gibi.

Yağan yağmurlara sordum seni, seni,

Nasıl, nasıl acaba, neşesi yerinde mi,

Bir damla, yaşım gibi, teselli etti beni,

Senin sevgin ona fazla be, fazla dedi.

Doğan Güneş''e sordum sordum seni,

Acaba sevgim ısıtıyormudur ki kâlbini,

Gel sen sen umudunu yitirme be dedi,

Herkesler sevemiyor senin, senin gibi....', 'Ilık, ılık esen Meltemlere sordum seni, Acaba, acaba düşünüyor mudur beni, Kulağıma fısıldadı çok uzaklarda dedi, Sanki, sanki ben bilmiyorm...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/herkes-sevemiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tövbe', 'tovbe-hasan-yildiz-9ffou', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hayalin geçerken gözlerimin önünde.

bir damla yaş döküldü,bitkin göz pınarımda,

Yağmur özlemi çeken,çatlamış topraklar gibi,

dudaklarım.

Ey yar! ! ! ! ! ! 

Çölde açan bir gül olsan,

seni yaşatmak için; hep ağlardım.

bir bulut olup,alırdım gölgeme,

Ah......seni anlatabilseydim,söz dinlemez gönlüme,

anlatabilseydim.......

Tövbeler olsun,senden ayrılırsam,bir daha......

Tövbeler.......

1994 Edirne

27-03-2006', 'Hayalin geçerken gözlerimin önünde. bir damla yaş döküldü,bitkin göz pınarımda, Yağmur özlemi çeken,çatlamış topraklar gibi, dudaklarım. Ey ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Yıldız']::text[], 8.5, '{"poet":"Hasan Yıldız","poet_slug":"hasan-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/tovbe-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köşkte Yangın (Sesimdeki Kuğu)', 'koskte-yangin-sesimdeki-kugu-ayten-colakoglu-m6f0l', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '.

pencerelerimden sarkan sardunyalar intihar ediyor

Mozart’ın çocukluğu ağlarken kuytularımda

içimdeki köşk gürültüyle yanıyor

ahşaptı, yanan adamların öptüğü anılar

özgür bırakılırken şimdi çatı katındaki diğer yanım

sokağa dökülüyorum, basmayın üzerime

annemin hatıra defterindeki adımı kurtarıyorum

babamın imzasını çalarken kırmızı hayatların ceplerinden

ateşi örtün üzerime

alevler köşkü terk ederse mumları yakacağım yeniden

şömineye kibrit atıp ateşle barışacağım

sen ahşabımı ıslat, köşkümü ateşten arındır

külleri ben temizlerim! ..

.

Sesimdeki Kuğu / Hayal Yayınları 2004

.', '. pencerelerimden sarkan sardunyalar intihar ediyor Mozart’ın çocukluğu ağlarken kuytularımda içimdeki köşk gürültüyle yanıyor ahşaptı, yana...', ARRAY['Türk Edebiyatı','Şiir','Ayten Çolakoğlu']::text[], 8.5, '{"poet":"Ayten Çolakoğlu","poet_slug":"ayten-colakoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/koskte-yangin-sesimdeki-kugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Ölmez Diyeceğim', 'sevgi-olmez-diyecegim-yusuf-onder-bahceci-sb1ek', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu karşılıksız sevda uğruna, lime, lime, olsam,

Aşıkların dilinden hiç düşmeyen kelime olsam,

Ay gibi parlayan yüzüm solsa solan gül olsam,

Yine seni seveceğim, sevgi ölmez diyeceğim...', 'Bu karşılıksız sevda uğruna, lime, lime, olsam, Aşıkların dilinden hiç düşmeyen kelime olsam, Ay gibi parlayan yüzüm solsa solan gül olsam, ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sevgi-olmez-diyecegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimsesiz Eylül (Sesimdeki Kuğu)', 'kimsesiz-eylul-sesimdeki-kugu-ayten-colakoglu-shas8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '.

bahçemizdeki ağaçları devirerek geldi eylül

boşluğumuzun kapısını çalmadan

adımızı sormadan geldi

çantasında blues kokan bir sonbahar

barok aryalar yankılandı içimizde

sokağımızda ‘kimse’ler gezinirken

yorgun bir güvercin gagası penceremizde

‘içinizde kimse yok mu’ dercesine...

.

Sesimdeki Kuğu / Hayal Yayınları 2004

.', '. bahçemizdeki ağaçları devirerek geldi eylül boşluğumuzun kapısını çalmadan adımızı sormadan geldi çantasında blues kokan bir sonbahar baro...', ARRAY['Türk Edebiyatı','Şiir','Ayten Çolakoğlu']::text[], 8.5, '{"poet":"Ayten Çolakoğlu","poet_slug":"ayten-colakoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kimsesiz-eylul-sesimdeki-kugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çılgının dostu...', 'cilginin-dostu-reyhan-tataroglu-2zyhm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'çılgın 

                                    bir düşünce...

                                    kimse sahiplenmez

                                    ''''çılgınca'''' der...

                                    iplenmez', 'çılgın                                      bir düşünce...                                     kimse sahiplenmez                            ...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Tataroğlu']::text[], 8.5, '{"poet":"Reyhan Tataroğlu","poet_slug":"reyhan-tataroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/cilginin-dostu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerimi Kapatıyor Ağlıyorum.', 'gozlerimi-kapatiyor-agliyorum-yusuf-onder-bahceci-c1j1e', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yıllar oldu soramadım hâlini ahvalini,

Hâk nasıl yaratmış, senin gibi zalimi,

Nere dönsem, seni gören gözlerimi,

Gözlerimi kapatıyorum ve ağlıyorum.

Güzel gözlerine bakmanın bedeli mi,

Hâlimi sor bakalım akıllımıyım delimi,

Evvel, gözlerime gülerdin, bu beli mi,

Gözlerimi kapatıyorum ve ağlıyorum.

Bu böyle, nereye kadar, sürüp gider,

Sevgin kâlbimde sürgün sürer gider,

Artık hiç bakmıyorum, eller neler der,

Gözlerimi kapatıyorum ve ağlıyorum.', 'Yıllar oldu soramadım hâlini ahvalini, Hâk nasıl yaratmış, senin gibi zalimi, Nere dönsem, seni gören gözlerimi, Gözlerimi kapatıyorum ve ağ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gozlerimi-kapatiyor-agliyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hesap Yarım Kaldı', 'hesap-yarim-kaldi-yusuf-onder-bahceci-pu29h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hesap yarım kaldı, hesabı göremedik, hesab ödemedik,

Herkesler bir şeyler dedi inan ki gerçek dost göremedik,

Sevdik alamadık ayrıldık çok ağladık bir vefa göremedik,

Hesap yarım kaldı, hesabı göremedik, hesab ödemedik...', 'Hesap yarım kaldı, hesabı göremedik, hesab ödemedik, Herkesler bir şeyler dedi inan ki gerçek dost göremedik, Sevdik alamadık ayrıldık çok a...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/hesap-yarim-kaldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırdım', 'kirdim-lokman-hamitoglu-7a237', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'KIRDIM

İnsanlığa kalleşçe vuran güçlerin

Tankıyla tüfeğini topunu kırdım! 

Zulümü nimet diye yazan ellerin

Elini kalemini ucunu kırdım! .. 

Kendini tanrı sanan leş yiyicinin

Gururuyla kibrini şek’ini kırdım! 

Darvin’i rehber yapan şaş bilimcinin

Bilgisini aklını şevkini kırdım! .. 

Kendi halkından korkan konumluların

Makamla mevkisini forsunu kırdım! 

Kendi halkını kıran firavunların

Şer ağzıyla burnunu dizini kırdım! .. 

Pireyi berber yapan düzenbazların

Aynasıyla camını azmini kırdım! .. 

Deveyi tellal yapan hokkabazların

Davulla zurnasını sesini kırdım! .. 

                  Lokman HAMİTOĞLU', 'KIRDIM İnsanlığa kalleşçe vuran güçlerin Tankıyla tüfeğini topunu kırdım!  Zulümü nimet diye yazan ellerin Elini kalemini ucunu kırdım! ..  ...', ARRAY['Türk Edebiyatı','Şiir','Lokman Hamitoğlu']::text[], 8.5, '{"poet":"Lokman Hamitoğlu","poet_slug":"lokman-hamitoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kirdim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-zati-erbas-6wte1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'iki 

yüzü 

keskin 

bir 

