INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Barışı Karşılayan Çiçek Kan', 'barisi-karsilayan-cicek-kan-babur-pinar-efuwq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yağmurun yüreğindeki acıyı sağarak

rüzgar kan getiriyor hışırdayan sesinde

Antik bir şarkıya alkış tutuyor

tahrip edilmiş hayat

Kentin üç no.lu güney antresinde 

nehrin ağzındaki yaraya tutunarak

kan kusuyor

barış resminde vurulan at

Siz derin uykudasınız

Gözlerinizin ferinde kurtçuklar

ateşliyor kesik damarların büyüsünü 

Gemici feneri kafatasınız

belli belirsiz ışık veriyor uzağa küskün

Siz duymuyorsunuz çığlığı

Rüzgar dingin bir sesle fısıldıyor

nehirden getirip sokağa bıraktığı

“Fırat kenarında yüzen kayıklar

Anam ağlar yarim beni sayıklar” türküsünü

Sandallar son seferden elleri boş dönerek

ağrısını kuma bırakıyor

Hiç anlamıyorsunuz belli

suçunu kabul eden afatın

ceviz ağacına söylediklerini

Hemen yanıbaşınızda hergün

iğdiş edilmiş ormanın sesine sinerek

petrolün şehvetiyle sürüyor yangın

Acıtan yük dolduruyor meydanı

Çıplak ağaçların yüzüne sıçrayan kanı

öyküsüz kuşlar içiyor görmüyorsunuz

Ve zehir oluyor kuşların kursağında su 

Gözleriniz yoksul gözleriniz kan çanağı 

Halksınız ölmüyorsunuz

Değirmenle barışık rüzgarın uğultusu

buğdayın türküsünü dolamış diline 

İçtiğiniz şarap yediğiniz ekmek kan

Her yeri kan tutmuş yattığınız döşek kan

Hissetmiyorsunuz aptal ıslatan sağanağı

Taş tanrıların savaşta yitirdiği sırsınız

Kasırganın habercisi kara gürültü

kapatmış kulaklarınızı sağırsınız

Duymuyorsunuz gölgelerin serin hüznünü

Suya düşmüş barışı karşılayan çiçek kan

Birazcık çevirseniz başınızı göreceksiniz

toprağa acı veren savaşı

Gözleriniz bakmaktan çatladığında anlayacaksınız belki

Rüzgarın hesapsız kanlı yakarışı

komşu ülkenin yüreğinden 

söküp getirdiğini', 'Yağmurun yüreğindeki acıyı sağarak rüzgar kan getiriyor hışırdayan sesinde Antik bir şarkıya alkış tutuyor tahrip edilmiş hayat Kentin üç no...', ARRAY['Türk Edebiyatı','Şiir','Babür Pınar']::text[], 8.5, '{"poet":"Babür Pınar","poet_slug":"babur-pinar","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/barisi-karsilayan-cicek-kan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilekler', 'dilekler-oktay-oksuzoglu-rmtl0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Renkleri canlandırıp yaşama anlam katan

olumsuzluk zırhını parçalayıp dağıtan

huzur dolu göklerde yıldızlardan yansıyan

ışıkları alnından şevkle öpesim gelir.

Beşparmak Dağları’nın dertli yamaçlarına

Mesarya Ovası’nın kupkuru bağlarına

Girne sahillerinin yaşlı çukurlarına

karanfiller, lâleler, güller dikesim gelir.

Yeryüzünün yüz akı bu cennet köşesinde

bahar meltemlerinin mest eden nefesinde

türkü türkü yansıyan sazların tok sesinde

çaresiz insanlarla hep ağlayasım gelir…', 'Renkleri canlandırıp yaşama anlam katan olumsuzluk zırhını parçalayıp dağıtan huzur dolu göklerde yıldızlardan yansıyan ışıkları alnından şe...', ARRAY['Türk Edebiyatı','Şiir','Oktay Öksüzoğlu']::text[], 8.5, '{"poet":"Oktay Öksüzoğlu","poet_slug":"oktay-oksuzoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dilekler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deveyi Hamuduyla Götürenler', 'deveyi-hamuduyla-goturenler-yusuf-onder-bahceci-hkgz9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Develeri hamuduyla götürenler, götürenler,

Mezar çukuruna neleri neleri götürebilirler,

Allah''ını, Peygamber''ini bilenler, iyi bilirler,

Develeri hamuduyla götürenler, götürenler,

Mezar çukuruna neleri neleri götürebilirler...', 'Develeri hamuduyla götürenler, götürenler, Mezar çukuruna neleri neleri götürebilirler, Allah''ını, Peygamber''ini bilenler, iyi bilirler, Dev...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/deveyi-hamuduyla-goturenler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çıkışını Bulamadım Tünelin', 'cikisini-bulamadim-tunelin-yusuf-onder-bahceci-co69s', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir türlü aşamadım be Gülüm, sevda yokuşunu,

Gözlerim yaşlı takip ettim sevdanın yokoluşunu,

Bir o yana döndüm bir bu yana döndüm çıkışını,

Çıkışını bulamadım, bir türlü, bu ayrılık tünelinin...', 'Bir türlü aşamadım be Gülüm, sevda yokuşunu, Gözlerim yaşlı takip ettim sevdanın yokoluşunu, Bir o yana döndüm bir bu yana döndüm çıkışını, ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/cikisini-bulamadim-tunelin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Hayatımın Kadını', 'hayatimin-kadini-bekir-gedikoglu-4an6w', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Uyuyan gönlümün kapsını çaldın

Kimseye sormadan içeri daldın

Aşkı bilmezdim bana tanıttın

Gönlümün dermanı sen oldun artık

Bakmazdım birine korkar idim ben

İnadına baktın gözlerime sen

Artık tutacaksın benim elimden

Yazgımın fermanı sen oldun artık

Güzeli görünce tutulur dilim

Halbuki seninle bülbül gibiydim

Nasıl geçti zaman fark edemedim

Dilimin bağını çözen sen oldun

Seni tanıdığım tesadüf müdür? 

Anımsayacağım en güzel gündür

Seninle yarınlar mutlu günümdür

Artık hayatımın kadını oldun

Ankara, 27 Mart 2006', 'Uyuyan gönlümün kapsını çaldın Kimseye sormadan içeri daldın Aşkı bilmezdim bana tanıttın Gönlümün dermanı sen oldun artık Bakmazdım birine ...', ARRAY['Türk Edebiyatı','Şiir','Bekir Gedikoğlu']::text[], 8.5, '{"poet":"Bekir Gedikoğlu","poet_slug":"bekir-gedikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hayatimin-kadini-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yapma kızım sevme sakın', 'yapma-kizim-sevme-sakin-sefika-celik-x66yq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yapma kızım sevme sakın

Bak çok üzülürsün,.

Çok yanar yüreğin

Ardından bakakalırsın

Yapma kızım sevme sakın.

Yapma kızım sevme sakın.

Karşılıksız birşeye kapılma

Sonu olmayan bir yola girme 

Kaybolacağın sokaklara sapma 

Yapma kızım sevme sakın.

Onlar sevdayı oyuncak gibi kullanırlar

Başı güzeldir sonu ayrılık

Öyle bir hale düşersin ki.

Yapma kızım sevme sakın

Acınacak duruma gelme.

Bir kadının en büyük silahı güzelliği

En zayıf noktası duygusallığı.

Yapma kızım sevme sakın

Seni incitmesinler

Gözyaşlarını akıtmalarını istemiyorum.

Beni dinle sevme kızım.

				(27.03.06)', 'Yapma kızım sevme sakın Bak çok üzülürsün,. Çok yanar yüreğin Ardından bakakalırsın Yapma kızım sevme sakın. Yapma kızım sevme sakın. Karşıl...', ARRAY['Türk Edebiyatı','Şiir','Şefika Çelik']::text[], 8.5, '{"poet":"Şefika Çelik","poet_slug":"sefika-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yapma-kizim-sevme-sakin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayıp mı Sevmek', 'ayip-mi-sevmek-yusuf-onder-bahceci-34yop', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Herkes kendine baksın be, ayıp mı sevmek, sevmek,

Sevdiği uğruna gerekirse de, cânını vermek, vermek,

Senden ayrılalı yıllar oldu sanki boynumda yağlı ilmek,

Herkes kendine baksın be, ayıp mı sevmek, sevmek...

Ayıp diye böyle oldu...', 'Herkes kendine baksın be, ayıp mı sevmek, sevmek, Sevdiği uğruna gerekirse de, cânını vermek, vermek, Senden ayrılalı yıllar oldu sanki boyn...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ayip-mi-sevmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dikkââââââât! !', 'dikk-t-turan-tuncer-449up', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'DİKKÂÂÂÂÂÂT

İçimde fırtınalar, 

Duygularım kudurgan,

Bir ihtilâl daha var yüreğimde.

Yıkılmışlığım, salt gidişlere değil

İçimde göçebe kuşların fener alayı,

Karanlığı yakar bakışlarında.

Işıklarım, umutlarım tutsaktır artık,

İçimde ayrılıkların resmi geçidi

Bütün yarım aşklar tören adım

Dikkââââââât! 

Yakında ayrılık var! 

Arsızdır yüreğim, nice aşklar yaşadım 

Ayrılıklarım kadar uzun olmadı

Çok kadınlar sevdim, isimsiz, kimliksiz

Gün karanlıktı, yüzleri bile olmadı

Kadınlar, her biri yeni bir aşk demekti

Kadınlar, her biri yeni acılar demekti

Kadınlar, ayrılıklara açılan liman kapısı

Kadınlar, tüm acıların doğurgan anası

Gözlerimde fırtınalar,

Düşlerim vurgun yemiş arsız dalgıç.

Bir ihtimâl daha var gözlerimde,

Bütün gün aydınlıklarını yakıp karanlıklara

Güneşi tutuşturabilmek 

İçimdeki ateşle, 

Belki çözülür yüreğinin buzları

Dikkââââââât! 

Yüreğimde kanama var! 

Bütün baharlarım göç tutmuş karakışlara

Salt alaca kuşlar çiçeksiz dallarımda

İçimde geceleri yakarım, 

Güneşin yokluğunda, 

Tükenen umutlarıma

yakılacak güneşte kalmadı gözlerinde

Gözlerin yok 

Bütün renkler bende siyah artık.

27 Mart 2006 /İst

Alkadraz_Kuşcusu', 'DİKKÂÂÂÂÂÂT İçimde fırtınalar,  Duygularım kudurgan, Bir ihtilâl daha var yüreğimde. Yıkılmışlığım, salt gidişlere değil İçimde göçebe kuşla...', ARRAY['Türk Edebiyatı','Şiir','Turan Tuncer']::text[], 8.5, '{"poet":"Turan Tuncer","poet_slug":"turan-tuncer","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/dikkaaaaaaat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gaz', 'gaz-ayse-adlim-i6irn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Daha uçağa bindiğim anda pişmanlık kemirmeye başlamıştı içimi. Almancı olmak için de geç kalmıştım, geri dönmek için de.

Havaalanına indiğimden beri her şey yabancıydı bana. Nereye baksam değişik şeyler görüyordum. Evler, sivri sivri çatılar, tahta merdivenler, küçücük odalar, hele de yağmurlar.  Dinmek bilmeyen, beni güneşe hasret bırakan yağmurlar.

Hiç dışarı çıkmıyordum. Biri beni çevirir, bir şey  sorar, cevap vermem gerekirse diye korkuyordum. Akşama kadar otuyordum annemle evde. Bizim için tek değişiklik, babamın işten gelmesi ve birlikte alış-verişe gitmek oluyordu. Dışarıda ilk öğrendiğim, tranvaya nasıl binildiği oldu. Bir de evet (ya) , hayır (nayn)   ve anlamıyorum (niht ferşteyn)   kelimelerini öğretti babam.

-Eğer ben işteyken biri kapıyı çalar da Almanca bir şeyler söylerse, niht fersteyn dersiniz.

diye öğütlerdi.

O güne kadar hiçbir Alman kapıyı çalmadı, ben de hiç kimseye niht fersteyn demedim. Yine sıradan bir gündü. Annem mutfakta uğraşıyor, ben de tv seyrediyordum. Bu arada merdiven başından gelen sesler dikkatimi çekti.. Birden kapıya hızlı hızlı vurulmaya başlandı. Gidip kapıyı araladım. Uzun boylu sakallı bir genç adam heyecanla bir şeyler söyledi. Anlamadım tabi.

-Niht fersteyn 

dedim ve kapıyı geri örttüm.

Ben örter örtmez tekrar kapıya vurmaya başladı. Açtım, yine aynı adamı görünce önemli bir şeyler olduğunu anladım. Adam eliyle karşı daireyi göstererek bağırıyordu.

-Gas, gas

Kapıyı iyice açıp baktığımda karşı evin kapısından fışkıran simsiyah dumanları gördüm. Eli yüzü kapkara olmuş bir genç aniden evin içine daldı. Hareketlerinden su almak istediğini anladım. Hemen bir kova verip banyoyu gösterdim. Sonra annemle birlikte ben de su taşımaya başladım. Yangın mutfaktaydı. Ocakları gaz kaçırıyordu, nefes almak çok zordu. Ateş kısa süre sonra söndü ama gaz kaçağı devam ediyordu. Genç sarışın bir kız camları açmamızı işaretledi. Görevliler geldiğinde gazın kesilmesini sağladılar ve herkes sakinleşti.

Komşularımızı işte o gün tanıdım. Aralarında İtalyan da vardı, Türk de vardı. Ama hiçbir zaman Gesi''deki gibi samimi, içten ilişkiler olmadı aramızda. Zaten ben Almanca bilmiyordum, istesem de o samimiyeti kuramazdım. Almanca öğrendim ama zamanla bu soğuk davranışlara ben de alıştım. Ya da öyle sandım. Yoksa bugün burda olmazdım.', 'Daha uçağa bindiğim anda pişmanlık kemirmeye başlamıştı içimi. Almancı olmak için de geç kalmıştım, geri dönmek için de. Havaalanına indiğim...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Adlım']::text[], 8.5, '{"poet":"Ayşe Adlım","poet_slug":"ayse-adlim","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gaz-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şu Bir Bardak Şarapta XV', 'su-bir-bardak-sarapta-xv-i-brahim-balci-mermh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Beşerin hafızası, malülmüş nisyan ile

Ne de çabuk unuttun, aşkınım diye diye

Şu bir bardak şarapta, ihanet buldu ruhum

Sen ki ey iffetli kadın,kadim bir İskaryot’sun

Daha dün geyik idin,şimdi halımda motif

Ana-atandan miras,sözlerin cins-i latif

Şu bir bardak şarapta, hulya’ya daldı ruhum

Sen ki ey sende gizli, kadim kutsallığıyla Huş’sun

Beşer bendim, sense göksel melekut içre

Esirgeme şerbetini, elindeyim işte biçare

Şu bir bardak şarapta, Lazarus gördü ruhum

Sen ki ey  göksel dişi, kulandaki kuzusun', 'Beşerin hafızası, malülmüş nisyan ile Ne de çabuk unuttun, aşkınım diye diye Şu bir bardak şarapta, ihanet buldu ruhum Sen ki ey iffetli kad...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Balcı']::text[], 8.5, '{"poet":"İbrahim Balcı","poet_slug":"i-brahim-balci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/su-bir-bardak-sarapta-xv-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yol Ayrımı..', 'yol-ayrimi-melih-baki-cmbwk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şu çılgın rüzgarın,

Önünde..

Sürüklenip giden,

Toz  bulutu.

Benim Yüreğim.

Bir bahar esintisini

Beklerken.! 

Kendimi

Kara bulutlarda gördüm.

Ne zaman

Aşk ateşine

Dokunsa şu elim,

Yanmıştır.! benim

Yorgun yüreğim.

Şimdi...

Dalından kopmuş..! 

Bir tohum gibi,

Şu çılgın rüzgarın önünde...

Benim sürüklendiğim yol.

Umuda

Yolculuk..

Mayıs/2000 Adana

(Ağla Yüreğim Dağlar da Ağlar.şiir ktp.Karahan yy.2005/Adana)', 'Şu çılgın rüzgarın, Önünde.. Sürüklenip giden, Toz  bulutu. Benim Yüreğim. Bir bahar esintisini Beklerken.!  Kendimi Kara bulutlarda gördüm....', ARRAY['Türk Edebiyatı','Şiir','Melih Baki']::text[], 8.5, '{"poet":"Melih Baki","poet_slug":"melih-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/yol-ayrimi-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kafa Yormasınlar', 'kafa-yormasinlar-yusuf-onder-bahceci-234hd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kargasekmez dağlarında, yalnız başına gezen,

Nereden, ılık bir rüzgâr es se, sevdiğini, sezen,

Ayrıldığı günden bu güne yalan Dünya''ya küsen,

Kimdir, kimdir diye sormasın, kafa yormasınlar.

Buradayım burada, hasret, gurbet ve nefret var,

Sevdiğinden ayrılanlara, neler, faydalar, sağlar,

Sadece Önder''mi ki, sevdiği de, her gün ağlar,

Kimdir, kimdir diye sormasın, kafa yormasınlar....', 'Kargasekmez dağlarında, yalnız başına gezen, Nereden, ılık bir rüzgâr es se, sevdiğini, sezen, Ayrıldığı günden bu güne yalan Dünya''ya küsen...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kafa-yormasinlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çırpındım', 'cirpindim-umit-tuna-a6hpc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Temiz bir havuza atladım,

Bedenim gibi ruhumu da

Bu havuzda yıkadım,

Çırpındım zor oldu başardım,

Şimdi yalnızım.

Kimse yok hayatımda,

Günahlarımdan arındım,

Kendimi pakladım,

Artık yalnızım,

Ben kendime aşığım! ...

ÇILGIN MUHASEBECİ', 'Temiz bir havuza atladım, Bedenim gibi ruhumu da Bu havuzda yıkadım, Çırpındım zor oldu başardım, Şimdi yalnızım. Kimse yok hayatımda, Günah...', ARRAY['Türk Edebiyatı','Şiir','Ümit Tuna']::text[], 8.5, '{"poet":"Ümit Tuna","poet_slug":"umit-tuna","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/cirpindim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Menofis''i Beklerken', 'menofis-i-beklerken-nergis-unlucay-etyp5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Daldırıyor ellerini bakışıma,

Çekip çıkarılacak ne kaldıysa,

Bilmediğimi mi biliyor aksim? 

Düşen gölgeler,

İlle de düşer tenimden

Ve anlam içte durduğu kadar. 

Harfleri okşuyorum,

Elimden gelen bu sadece,

Söz susuyor,

Susuyorum durmadan her türlü,

Ağzımı dayıyorum kelimelere,

Tükürüyorum bir lamanın doğallığında

Ve seçim hakkımı soracak rüyalar tanrısının, 

Ezberini bozmaya provalı 

Kırmızı diyorum her soruya.', 'Daldırıyor ellerini bakışıma, Çekip çıkarılacak ne kaldıysa, Bilmediğimi mi biliyor aksim?  Düşen gölgeler, İlle de düşer tenimden Ve anlam ...', ARRAY['Türk Edebiyatı','Şiir','Nergis Ünlüçay']::text[], 8.5, '{"poet":"Nergis Ünlüçay","poet_slug":"nergis-unlucay","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/menofis-i-beklerken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kucugum Benim', 'kucugum-benim-i-brahim-ethem-uzun-1zepm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevgilim benim

Sorarlarsa

Bir gun 

Hic tereddut etme

Onlara soyle

Butun kibirinle

Beni cok seviyor

Beni cilginca seviyor

Beni olumune seviyor

Kucugum benim

Sorarlarsa

Bir gun

Nicin kisalttin diye

Uzun ipek sacini

Aylarca terbiye ettikten sonra

Onlara soyle

Butun kibirinle

Cunku sevdigim

Kisa seviyor

Karanfil kokulum benim

Sorarlarsa

Bir gun

Neden uzun giyiniyorsun diye

Bu yakici yaz gunu

Onlara soyle

Butun kibirinle

Cunku sevdigim

Beni kiskaniyor

Prensesim benim

Dansederken  muzigin sesiyle

Varligimiz

Nagmeler

Isiklar

Duygular

Goz yaslari

Kelebegim gokyuzune ucuyor

Agir agir dansimiz devam ediyor

Sevgimiz goguslerimizin arasinda uyuyor

Omuzlarima soyle

Butun kibirinle

Beni cok seviyor

Beni cilginca seviyor

Beni olumune seviyor

Askim benim

Konusurlarsa 

Bir gun

Benim icin

Onun kosku yok

Onun  koleleri yok

Onun korumalari yok

Evet elimde yok tatlim

Yumusak seker boynuna takacak ince kolye bile

Onlara soyle

Butun kibirinle

Sevdigim 

Ilk ve son askim

Beni cok seviyor

Beni cilginca seviyor

Beni olumune seviyor

Bu bana yetiyor', 'Sevgilim benim Sorarlarsa Bir gun  Hic tereddut etme Onlara soyle Butun kibirinle Beni cok seviyor Beni cilginca seviyor Beni olumune seviyo...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Uzun']::text[], 8.5, '{"poet":"İbrahim Ethem Uzun","poet_slug":"i-brahim-ethem-uzun","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/kucugum-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayseri', 'kayseri-sahabeddin-erzurumluoglu-1gg65', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Karlı dağlarında kevenlerinle,

Gesi bağlarında sevenlerinle,

Bütün çağlarında yarenlerinle,

Her daim gündemde olan Kayseri..

Çalışkan insanın dünya markası,

Başarısız olmak hayal arkası,

Sanatta hep önder güçlü fırkası,

Her dönem özünde kalan Kayseri..

Misafir ardından yaşlar dökerler,

Sıkıntı etmeden kahır çekerler,

Hakikat söylersen boyun bükerler,

Her zaman gönülden gülen Kayseri..

Zayıfı görünce derin ağlayan,

Düşmana gelince hemen çağlayan,

Ticaret denince özden parlayan,

Her şartta işini bilen Kayseri..

Erişilmez serin rüyalarına, 

O coşku dolusu hülyalarına,

İlim kokan üstün deryalarına,

Sevgiyi yüreğe salan Kayseri..

Coştukça coşuyor sevginin seli,

Cehaletin sende kırıldı beli,

Tertemiz tüccarın sağlamdır eli,

Sevmiyorum diyen yalan Kayseri...', 'Karlı dağlarında kevenlerinle, Gesi bağlarında sevenlerinle, Bütün çağlarında yarenlerinle, Her daim gündemde olan Kayseri.. Çalışkan insanı...', ARRAY['Türk Edebiyatı','Şiir','Şahabeddin Erzurumluoğlu']::text[], 8.5, '{"poet":"Şahabeddin Erzurumluoğlu","poet_slug":"sahabeddin-erzurumluoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kayseri-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasretini Avutuyorum İçimde', 'hasretini-avutuyorum-i-cimde-huseyin-erdogan-wzwpl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bu gün pırıl pırıl bir hava var İstanbul''da

Pendik''ten seyrediyorum Marmara''yı Adalar''ı

birdenbire yine sen düşüverdin aklıma

sen yoksun ya bir kramp girdi her yanıma

sensin diye hayal ettim sahile vuran dalgaları

gözlerimle okşadım durdum saçlarını

seninle süsledim gün boyunca dünyamı

sen diye kokladım bahçelerdeki sardunyaları

senin kokun diye çektim içime esen rüzgarları

yokluğunu bir kez daha hissediyorum yüreğimde

iliklerime kadar hasretini avutuyorum içimde

özlemin bu alemde bitmek tükenmek bilmese de

şiirim bil ki bir tek seni seveceğim hem de ömrümce

                                                          27.03.2006

                                                      Hüseyin Erdoğan', 'bu gün pırıl pırıl bir hava var İstanbul''da Pendik''ten seyrediyorum Marmara''yı Adalar''ı birdenbire yine sen düşüverdin aklıma sen yoksun ya ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/hasretini-avutuyorum-icimde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kâlbim Söz Dinlemiyor', 'k-lbim-soz-dinlemiyor-yusuf-onder-bahceci-y8j41', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben değil seni çok seven kâlbim, kâlbim söz dinlemiyor,

Hislerim akla galip geliyor neden sevdim demedin diyor,

Çok sevdiğim güzel, vallahi kendisi, kendisi terketmiyor,

Ben değil seni çok seven kâlbim, kâlbim söz dinlemiyor...', 'Ben değil seni çok seven kâlbim, kâlbim söz dinlemiyor, Hislerim akla galip geliyor neden sevdim demedin diyor, Çok sevdiğim güzel, vallahi ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kalbim-soz-dinlemiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir kuytu', 'bir-kuytu-bestami-kurtulus-aohfv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'pür neşe açıp kanatlarını

bandırasız bir yelkenli martı 

süzülüp koynunda marmaranın

çipil dalgalarıyla bata çıka

tutunacak bir taş arıyor

ve dudaklarından

o bir türlü başını hatırlayamadığı

her seferinde yalnız nakaratından

çekiştire çekiştire söylediği

saçlarına dolanmış şarkılardan

biri daha dökülüyor

tutkular hangi tepesine saklandı

bu şehrin neresinde kabahat

bahar gelince ayaklandı

iki kol iki kanat

seviştikten sonra

ölecek bir kuytu arıyor', 'pür neşe açıp kanatlarını bandırasız bir yelkenli martı  süzülüp koynunda marmaranın çipil dalgalarıyla bata çıka tutunacak bir taş arıyor v...', ARRAY['Türk Edebiyatı','Şiir','Bestami Kurtuluş']::text[], 8.5, '{"poet":"Bestami Kurtuluş","poet_slug":"bestami-kurtulus","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bir-kuytu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayaklarımız çıplak', 'ayaklarimiz-ciplak-bestami-kurtulus-zml4g', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'cıvıltılar var ruhu çözer asumanda

yeşerirse bir bahar yeşermeli

yaşam en umulmadık kıpırtısında 

gürbüz, deli ve neşeli

ayaklarımız çıplak 

gül güneşlerde çıktı sular toprağa 

aklı kaynağında genzi hıçkırık

sen şırıltı duyarsın kopan figanı

daha dün bir çocuk gibi hevesli 

bu gün yüreği darmadağınık', 'cıvıltılar var ruhu çözer asumanda yeşerirse bir bahar yeşermeli yaşam en umulmadık kıpırtısında  gürbüz, deli ve neşeli ayaklarımız çıplak ...', ARRAY['Türk Edebiyatı','Şiir','Bestami Kurtuluş']::text[], 8.5, '{"poet":"Bestami Kurtuluş","poet_slug":"bestami-kurtulus","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ayaklarimiz-ciplak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Işır Gözlerinde', 'gun-isir-gozlerinde-vedat-koparan-ubqlw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Acabaların beynimizi kemirmesine izin vermek 

Başını yastığa koyup uykunun gelmesini beklemek

Senle senden öteleri o anlarda düşünüp düşlemek 

Bilir misin yürek atımım ne zor sensiz sabaha ermek

Bitip tükenirken ağır kurşun grisi gece 

Yokluk hamuru girerken şekilden şekle

Bil ki duyulan içimdeki ürperti 

Bana verdiğin titreme sensizliği

Çiğnenirken ateş çemberi onurun abidesi 

Boynu eğik hüzün içinde sevgi çiçekleri

Kentim sessiz, soğuk, yalnız ve uzak kenttir şimdi

Öyle bozuğum ki sensizliğe ağlar hüznün heykeli

Direnç ordularımla irisine her gidiş gelişimde

Yakınlaşır uzak zamanlar gün ışır gözlerinde.

Yanarken ten üşümelerde yokluk denizinde

Bir yanım zemheride bir yanım çöl sıcağında

O gece düştüm yoluna kayboldum koca kentte 

Oysa akmak isterdim seninle geceden sabaha

Bitmedi…

Vedat Koparan 26.03.2006', 'Acabaların beynimizi kemirmesine izin vermek  Başını yastığa koyup uykunun gelmesini beklemek Senle senden öteleri o anlarda düşünüp düşleme...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gun-isir-gozlerinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ekmek Parası', 'ekmek-parasi-salih-erdem-gbi1n', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Feryat etmez hâlden bilir dillerim

Gurbetteymiş bizim ekmek parası

Taşı deler terden kazma ellerim

Bahttan çalar yerim ekmek parası

Nasibin bul aç mezara yatılmaz

Evladın yer hile hurda katılmaz

Şeref onur her pazarda satılmaz

Özen göster helâl ekmek parası

Onun için terki diyar eylerim

Zor türkümü ona yakar söylerim

Alamazsam ben o yâri neylerim

Gözüm yaşı akar ekmek parası

Gömlek tulum giyen elin kirinde

Ömrü küren yolun alın terinde

Her bir meslek kutsal yerli yerinde

Çalış hak et kazan ekmek parası

Yok olmasın saçın başın yoldurur

Ambar deler yanlış yola daldırır

Edep namus hayâ hepten kaldırır

Başın yere eğer ekmek parası

Oku yavrum onun yolu zorlaştı

Talipli çok rakiplerin gürleşti

Geç de kalma güne geçim darlaştı

Erken kalkan bulur ekmek parası

Erdemoğlu bitmez ki hiç kavgası

Dava aşk meşk değil varlık davası

Ayağın denk al kazan kul sevdası

Açar eli ele ekmek parası

Düşmez katta yankı bulur sedası

17.10.2005 05.45 – 09.50 AYDIN', 'Feryat etmez hâlden bilir dillerim Gurbetteymiş bizim ekmek parası Taşı deler terden kazma ellerim Bahttan çalar yerim ekmek parası Nasibin ...', ARRAY['Türk Edebiyatı','Şiir','Salih Erdem']::text[], 8.5, '{"poet":"Salih Erdem","poet_slug":"salih-erdem","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/ekmek-parasi-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'At Üstünde Ezo Gelin', 'at-ustunde-ezo-gelin-tulay-sustam-tisel', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'elleri kınalı bir aşk çağırır beni

içimde halay çeker duygular

gecesi gündüzüne eşitlenir sevginin

toprağa tohum eker güz gülleri

bir sevda türküsü

alır götürür başımdaki dumanı

duvağı iner Ezo Gelinin

zılgıt çalar barış güvercinleri

bayramın seyranına karışır yalnızlık

eteğine kor düşer başı dik dağın

gel gör ki Anam ellere karışırım...', 'elleri kınalı bir aşk çağırır beni içimde halay çeker duygular gecesi gündüzüne eşitlenir sevginin toprağa tohum eker güz gülleri bir sevda ...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/at-ustunde-ezo-gelin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Az Bekle Sen', 'az-bekle-sen-yusuf-onder-bahceci-6qjcm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözlerin dalıp, dalıp gidiyor, ta uzaklara,

Nasıl da yanarsın düştüğün bu tuzaklara,

Seni benden aldılar, sevdamız, uzakara,

Gözlerin dalıp, dalıp gidiyor, ta uzaklara.

Vicdansız olanlardan herşey bekle sen,

Bir yazı, bir satır görürsen, az beklesen,

Bu yazılan şiirler boş, boş değil bilirsen,

Gözlerin dalıp, dalıp gidiyor, ta uzaklara.', 'Gözlerin dalıp, dalıp gidiyor, ta uzaklara, Nasıl da yanarsın düştüğün bu tuzaklara, Seni benden aldılar, sevdamız, uzakara, Gözlerin dalıp,...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/az-bekle-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbimde Aradığımı Mehtabında Bulduğum Yer', 'kalbimde-aradigimi-mehtabinda-buldugum-yer-kiymet-sonmez-67av6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yollarında iki sıra manolyalar,

Koklamaya kıyamazsın,

Cumbalı evler,

Pencereleri dantel perdeli,

Kapı önlerinde kadınlar, çocuklar,

Çiğdem çıtlatırlar.

Ve kavaklar,

Ilık rüzgarda bile yapraklarını sallar,

Arada unutmayasınız diye döker devamlı yapraklarını

Taze bardacık diye bağıran bir satıcı,

Hani siz incir diye bilirsiniz.

Kıtır kıtır üzümleri de  cabası

Pazar kahvaltıları için babalar,

Boyoz ve gevrek fırınına koşarlar,

Gevrekçi fırınından kumru almayıda unutmazlar,

Mis gibi tulum peyniri yanında,

Yazın  kahvaltı yapılır balkonlarda,

Karşı komşu ile sohbette unutulmaz bu arada.

Ve saat kulesi,

Herkesin buluşma yeri.

Kordon boyu birde,

Seyrine doyum olmaz,

Bankın üstüne oturdunmu,

Zamanı unutursun adeta,

O hafiften dalgalı denize bakarken,

Küçük piknikler de yapılır orda,

Çayını içersin, denize karşı yudum yudum.

Faytonlar geçer bir bir,

Kordonu dolaştırırlar bir boydan bir boya

Kemeraltı unutulurmu hiç.

Çığırtkan gibi bağıran seyyar satıcılar,

Herşeyi bulabileceğin bir yer.

Çarpışa çarpışa yüreyerek alışveriş yaparsın,

Ama orasıda kalabalık güzel.

Ordan Hisarönüne gelirsin,

Her türlü kitabı bulabileceğin,

Balkonuna ekebileceğin çiçekler alırsın,

Caminin önüne kurulmuş tezgahlarda

Fuara gidersin ordan da,

İsteyen yürüyüş yapar,

İsteyen koşu,

Kimide piknik yapar,

Hepsini birden gezdinmi,

Alsancak,Kahramanlar, Basmane''yi gezmiş olursun,

Hepsini bitiremezsin bir günde yorulursun

Hele fuar zamanları.....

Ne güzel olurdu.

Gazinosu, lunaparkı, çaybahçeleri, tiyatroları,

Paraşüt kulesi.

Kelimeler yetmiyor anlatmaya İzmir’im

Seni çok seviyorum.

Nereye gidersem gideyim,

O burcu burcu kokunu özlüyorum

Döndüğümde de 

İçime çekiyorum doyasıya

Denizi, güneşi,

İnciri,üzümü

Herşeyi bolca vermiş Yaradan

Ne mutlu bana,

İzmir’liyim,

Ve hala İzmir’de yaşıyorum.

Kalbimde aradıklarımı,

Mehtabında bulduğum,

İzmir’im seni çok seviyorum..', 'Yollarında iki sıra manolyalar, Koklamaya kıyamazsın, Cumbalı evler, Pencereleri dantel perdeli, Kapı önlerinde kadınlar, çocuklar, Çiğdem ç...', ARRAY['Türk Edebiyatı','Şiir','Kıymet Sönmez']::text[], 8.5, '{"poet":"Kıymet Sönmez","poet_slug":"kiymet-sonmez","theme":"Türk Şiiri","is_hero":false,"total_lines":64,"source_url":"https://www.antoloji.com/kalbimde-aradigimi-mehtabinda-buldugum-yer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırak...', 'birak-elif-betul-ozturk-vjwtd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Evet ne var,

Sanki yalan söylemişsem.

Zaten herkes kendini kurtarmak peşinde.

Sanki ne var,

Kendime bukadar zarar vermişken.

Hadi sen kendi düşlerinde yüz,

Beni bana bırak...

Gülmez,güldüremez,gülmezler onlar.

Aşka inanmaz,onla oyun oynarlar.

Gitme,gel sen,

Benim tarafımda kal.

Kendini kendine bırak...

Biz bir nefeslik aşklara mahkumuz.

Bir kaç saniyeliktir mutluluğumuz.

O da bitecek biliyoruz.

Sen ver elini bana,

Onları kendi haline bırak...', 'Evet ne var, Sanki yalan söylemişsem. Zaten herkes kendini kurtarmak peşinde. Sanki ne var, Kendime bukadar zarar vermişken. Hadi sen kendi ...', ARRAY['Türk Edebiyatı','Şiir','Elif Betül Öztürk']::text[], 8.5, '{"poet":"Elif Betül Öztürk","poet_slug":"elif-betul-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/birak-44-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni mi Korudular', 'seni-mi-korudular-yusuf-onder-bahceci-d6gqg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bunlar seni benden mi korudular, korudular,

Bunlar yolkesici gibi oldular, seni korudular, 

Bunlar işi inada bindirdiler beni soldurdular,

Bunlar seni benden mi korudular, korudular...', 'Bunlar seni benden mi korudular, korudular, Bunlar yolkesici gibi oldular, seni korudular,  Bunlar işi inada bindirdiler beni soldurdular, B...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/seni-mi-korudular-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sırra Kadem Tahtası', 'sirra-kadem-tahtasi-tarkan-sucikar-qpmbm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Rüyalar sırra kadem tahtası

Hayat hayatın son lahzası

Sensizlik ve milyonlarca fazlası

Üzerimdeyken üşüyorum...

Hasret buz dağından bir kule

Nefret haşlanmış pişmiş kelle

Ellerinde çok çok uzun bir telle

Beni sıkıyorsun ölüyorum...

Ölüm sihirbazlar kralı

Yüzün beyazlarla karalı

Benliğimi afakanlar saralı

Hep seni...

Yine seni düşlüyorum...', 'Rüyalar sırra kadem tahtası Hayat hayatın son lahzası Sensizlik ve milyonlarca fazlası Üzerimdeyken üşüyorum... Hasret buz dağından bir kule...', ARRAY['Türk Edebiyatı','Şiir','Tarkan Suçıkar']::text[], 8.5, '{"poet":"Tarkan Suçıkar","poet_slug":"tarkan-sucikar","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sirra-kadem-tahtasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masum Gözler', 'masum-gozler-yusuf-onder-bahceci-6zwik', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni benim gibi seven, seven varsa beri gelsin,

Seni sevdim oldun elin, seven varsa beri gelsin,

Hâni, o verilen sözler, kâlbim yanar, ateş közler,

Çekip gitti ellere, masum, masum bakan gözler...', 'Seni benim gibi seven, seven varsa beri gelsin, Seni sevdim oldun elin, seven varsa beri gelsin, Hâni, o verilen sözler, kâlbim yanar, ateş ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/masum-gozler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessizliğimle Başbaşa', 'sessizligimle-basbasa-canan-karadeniz-la2mt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sessizim bu günlerde

Hemde çok sessiz...

Sözlerim kayıp, 

Yüreğim bomboş 

Rüzgar önüne katmış beni,

Savurur oradan oraya.

Sormam nereye neden diye

Bilemem sorularımın cevabını

Gözlerim yaşlı,

Durmaksızın akan bir nehir gibi

Soğuk ve donuk.

Sakin bir müzik sesi kulağıma gelen

Yumuşak ve derinden okşarcasına.

Sıcak ve koruyan bir el yanıbaşımda.

Mırıldanan dudaklarımdan

Dökülen sözcüklere kulak veren,

Bir nefes.

Dedimya sessizim bu günlerde

Durgun mavilikte yürümeye

Çalışan çaresiz bir yolcu.

Köhne yaşamdan arta kalan

Bir damla mutluluk gözyaşı

Aradığım

Dedimya sesizim bu günlerde......', 'Sessizim bu günlerde Hemde çok sessiz... Sözlerim kayıp,  Yüreğim bomboş  Rüzgar önüne katmış beni, Savurur oradan oraya. Sormam nereye nede...', ARRAY['Türk Edebiyatı','Şiir','Canan Karadeniz']::text[], 8.5, '{"poet":"Canan Karadeniz","poet_slug":"canan-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sessizligimle-basbasa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğine Takılıp Kaldı', 'yuregine-takilip-kaldi-canan-karadeniz-6yd1h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yüreğine takılıp kaldı

Boğazına düğümlenmiş bir sarmaşık misali

Uzadıkça içinden çıkılmaz sözcükler sürüsü sanki

Büyüdükçe tıkandı dudaklar

Akıp durdu kendi içinde

Duyulmadı, fısıltılar halinde yol aldı

Öyle çoğaldıki hücreleri sardı

Yayılan bir virüs gibi

Tan anlatış hazırlanırken

Düşünceleri dökmeye yol vermişken

O çoktan göğün maviliğine ulaşmıştı

Sarmaşık dolandı boynuna

Baş ucunda duran gözyaşları

Satırlara eşlik halinde

Dansa geçmişti hüznün çığlığında', 'Yüreğine takılıp kaldı Boğazına düğümlenmiş bir sarmaşık misali Uzadıkça içinden çıkılmaz sözcükler sürüsü sanki Büyüdükçe tıkandı dudaklar ...', ARRAY['Türk Edebiyatı','Şiir','Canan Karadeniz']::text[], 8.5, '{"poet":"Canan Karadeniz","poet_slug":"canan-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yuregine-takilip-kaldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonuna Kadar Gideceğim', 'sonuna-kadar-gidecegim-yusuf-onder-bahceci-zgvi4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sonuna kadar gideceğim, ben bu yolun,

Yolun sonu çıkmazlara girsede, girsede,

Kafama koydum, söyleceğim kelimeleri,

Ezberliyorum Gülüm, şimdiden heceleri...', 'Sonuna kadar gideceğim, ben bu yolun, Yolun sonu çıkmazlara girsede, girsede, Kafama koydum, söyleceğim kelimeleri, Ezberliyorum Gülüm, şimd...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sonuna-kadar-gidecegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayal Meyal', 'hayal-meyal-tarkan-sucikar-wekjf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Rüyalarımı bir hayalet çaldı dostlarım

Gerçeğin kendisinden kopan bir hayal

Buhayal yüzünden ürkek bakışlarım

Bu hayal yüzünden hayal meyal...

Yolunu kaybetmiş dediler rüzgar

Buyursun bu gece bize gelsin

Yeter aynaların ettiği nazar

Bütün aynalar bu gece dize gelsin...', 'Rüyalarımı bir hayalet çaldı dostlarım Gerçeğin kendisinden kopan bir hayal Buhayal yüzünden ürkek bakışlarım Bu hayal yüzünden hayal meyal....', ARRAY['Türk Edebiyatı','Şiir','Tarkan Suçıkar']::text[], 8.5, '{"poet":"Tarkan Suçıkar","poet_slug":"tarkan-sucikar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/hayal-meyal-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendi çıkmazında', 'kendi-cikmazinda-canan-karadeniz-gotix', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bilmek anlatamamak

Acıyı yaşamak söyleyememek

Ayıbı içinde paylaşmak

Bedene gömmek kederi

Gizlemek herkesten

Unutmayı başarmak

Unutamamayı sorgulamak

Zaman acımıyor

Senin ona acıdığın kadar

Yaşatanlara ne oldu...', 'Bilmek anlatamamak Acıyı yaşamak söyleyememek Ayıbı içinde paylaşmak Bedene gömmek kederi Gizlemek herkesten Unutmayı başarmak Unutamamayı s...', ARRAY['Türk Edebiyatı','Şiir','Canan Karadeniz']::text[], 8.5, '{"poet":"Canan Karadeniz","poet_slug":"canan-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kendi-cikmazinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçmişe aralık', 'gecmise-aralik-canan-karadeniz-xlii2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Geçmişi şöyle bir araladım

Dün gece tam uykuya dalacakken

Önce gözyaşlarım sıraya girdi

Anlattılar birer birer damlalar halinde

Baktımki ömrümün yarısını çalmışlar benden

Mendilim yetişti imdadıma

Ardından yanaklarım konuştu çoşkuyla

Dost eli gibi yanıbaşımda

Gülüşüyle hep koruyan bir melek gibi

Oda olmasa halim harapmış 

Anladım

Dudaklarım zorlamasa sözcükleri

Zincirleme kaza kaçınılmaz ölesiye

Duyduğum sözler boş

Davranışlar fütursuzca sergilenmekte

Ben yine aynı ben

Bende kalan hüzün ertesi serinlik

Mutluluğun gölgesinde yatarken

Ellerime vuran ayışığı beni selamlarken

Gece mavisi çoktan yıldızların beyazına boyanmış

Sessizlik kaplar içimi 

Huzur benim yanıbaşımda uykuya dalarken', 'Geçmişi şöyle bir araladım Dün gece tam uykuya dalacakken Önce gözyaşlarım sıraya girdi Anlattılar birer birer damlalar halinde Baktımki ömr...', ARRAY['Türk Edebiyatı','Şiir','Canan Karadeniz']::text[], 8.5, '{"poet":"Canan Karadeniz","poet_slug":"canan-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/gecmise-aralik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sefil', 'sefil-tarkan-sucikar-u8kr2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir güzele sevdalandım gözü yeşil mi yeşil

Bir hayata alıştım çok güzel ve çok sefil...', 'Bir güzele sevdalandım gözü yeşil mi yeşil Bir hayata alıştım çok güzel ve çok sefil......', ARRAY['Türk Edebiyatı','Şiir','Tarkan Suçıkar']::text[], 8.5, '{"poet":"Tarkan Suçıkar","poet_slug":"tarkan-sucikar","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/sefil-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeniden Doğuş', 'yeniden-dogus-canan-karadeniz-f7pj9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gün bitiyor güneşin alaca kızıllığında

Ay ışığı yerini alırken,

Yıldızların pırıltısı sarıyor gözlerimi

Sesler yükseliyor yüreğimin derinliğinde

Çağlayan ırmaklar kadar soğuk

ve hızlı,

Alev gibi yakıcı ve sıcak

Kıpır kıpırım yağmurun hızına karşın

Dur yok, durak yokken koşuyorum

Dağların eteklerine

Yeşile sarılıp,

Ağaçlara şarkılar söylüyorum

Hayatın gülümsemeleri arasında

Sıra bende çoşkuda

Sıra bende kederin ertesinde

Sıra bende yaşların bitiminde

Çiçekler elimde mis kokularıyla

Dağıtıyorum tüm hüzünlerin 

Üzerine doğru

Parıltısı gözlerimde güneşin

Yeniden doğuş gibi

Hayata sarılış.

Yeniden tutunmak umudun sabahında

Yeniden yeniden...', 'Gün bitiyor güneşin alaca kızıllığında Ay ışığı yerini alırken, Yıldızların pırıltısı sarıyor gözlerimi Sesler yükseliyor yüreğimin derinliğ...', ARRAY['Türk Edebiyatı','Şiir','Canan Karadeniz']::text[], 8.5, '{"poet":"Canan Karadeniz","poet_slug":"canan-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yeniden-dogus-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Son Nefesimsin', 'benim-son-nefesimsin-canan-karadeniz-n4w7w', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir sözdü,dudaklarımdan kağıda dökülen

Bir anlık öfke ertesinde.

Aşkın kalbimde 

Yaşatan sen,

Büyüten yine sen sevgilim.

Satırlar yaşla beslendi,

Aşkının ardından dökülerek

Sevdana kapılıp gidiyorum,

Aklım sen,ruhum sendeyken.

Yolum belirsiz sensizken

Rüyalarımda kayıp

Uykusuz gecelerimde.

Susuzum çölün ortasında kalmış mecnun misali

Ayrılamam sevdanın pençesinden

Kopamam gülümün kokusundan

Gözlerine esirim,

Sözlerine aşık.

Sözlerim acı dolu, 

Sana yazılan satırlarda

Buse konduramadan dudaklarına,

Sıcaklığını son defa hissedemeden

Gidiyorum,

Aşkın yüreğimde

Ben seninleyim 

Son nefesim gelene dek', 'Bir sözdü,dudaklarımdan kağıda dökülen Bir anlık öfke ertesinde. Aşkın kalbimde  Yaşatan sen, Büyüten yine sen sevgilim. Satırlar yaşla besl...', ARRAY['Türk Edebiyatı','Şiir','Canan Karadeniz']::text[], 8.5, '{"poet":"Canan Karadeniz","poet_slug":"canan-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/benim-son-nefesimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerinde Kayboldum', 'gozlerinde-kayboldum-canan-karadeniz-kyu98', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözlerinde kaybolmanın sarhoşluğu

Savururken,

Saçlarının renginde buldum kendimi

Ben sendeyim sevdanın büyüsünde

Sevdam çoktan senin ellerinde 

Tutunmuş sarmaşık misali sarmalanmış

Bedenim kilitli bedenine

Bırakmazki sevginin çoşkusunda

Kokun dağlarda çiçeklerle bezenmiş

Rüzgar seni arar yana yakıla

Ay geceye umutla doğar

Seni görmenin beklentisinde

Gece bir başka hoş

Güneş bir başka ışıltılı 

Seni andığım her an

Seni düşülediğim her saniye

Gözlerinde kayboldum sevgilim

Gözlerin gözlerim

Ellerin ellerim bundan sonra

Ben senim bundan böyle

Sende ben

Aşkının gözbebeğinde..', 'Gözlerinde kaybolmanın sarhoşluğu Savururken, Saçlarının renginde buldum kendimi Ben sendeyim sevdanın büyüsünde Sevdam çoktan senin ellerin...', ARRAY['Türk Edebiyatı','Şiir','Canan Karadeniz']::text[], 8.5, '{"poet":"Canan Karadeniz","poet_slug":"canan-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/gozlerinde-kayboldum-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir sevda istiyorum', 'bir-sevda-istiyorum-asim-kisbet-4dhmf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir gönül istiyorum beni sürgünden alsın

  Bir sevda istiyorum hasretime son versin

  Bir sabah istiyorum hazanım bahar olsun

  Çile yüklü geceme bir sevda istiyorum

       Bir beste istiyorum şarkımızı söylesin

        Bir dua istiyorum seni bana eylesin

        Cana can istiyorum sevildiğini bilsin

         Yıllarca küllenmeyen bir sevda istiyorum

                 Bir takvim istiyorum mevsimler bahar olsun

                  Bir rüzğar istiyorum sancılarımı alsın

                 Bir umut istiyorum kara yazgımı silsin

                  Tenimde can olcak  bir sevda istiyorum', 'Bir gönül istiyorum beni sürgünden alsın   Bir sevda istiyorum hasretime son versin   Bir sabah istiyorum hazanım bahar olsun   Çile yüklü g...', ARRAY['Türk Edebiyatı','Şiir','Asım Kısbet']::text[], 8.5, '{"poet":"Asım Kısbet","poet_slug":"asim-kisbet","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-sevda-istiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ana Okulu', 'ana-okulu-mustafa-zincirkiran-slnmb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir sevgi bahçesi şefkat yuvası

İnsanın gönlüne ferahlık verir.

Yoğunlaşır orda çocuk duası

İnsanın gönlüne ferahlık verir.

Tomurcuk güllüdür misler kokulu

Oyuncak dünyalı hayâl dokulu

İlk göz ağrımızdır ana okulu

İnsanın gönlüne ferahlık verir.

Papatya sınıfı, gül var lâle var

Oyunlardan ront var, bazen bale var

Kürşat var,  Nidasu, bir de Hâle var

İnsanın gönlüne ferahlık verir.

Güvenlidir baba ocağı kadar

Sıcacıktır anne kucağı kadar

Öğrenci sevilir çocuğu kadar

İnsanın gönlüne ferahlık verir.

Çocukta hîle yok, kopya bilmezler

Gülerseniz güler, yoksa gülmezler

Haber onlardadır, kolay vermezler

İnsanın gönlüne ferahlık verir.

Müdiremiz bilge, hata barınmaz

Melek Hanım melek, kanat görünmez

Gülten Hanım çalışkandır erinmez

İnsanın gönlüne ferahlık verir.

	

Eğitime bu okulda başlanır

Çocuk bilim kültür ile işlenir

Behlül de kaydolsa inan hoşlanır

İnsanın gönlüne ferahlık verir.', 'Bir sevgi bahçesi şefkat yuvası İnsanın gönlüne ferahlık verir. Yoğunlaşır orda çocuk duası İnsanın gönlüne ferahlık verir. Tomurcuk güllüdü...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Zincirkiran']::text[], 8.5, '{"poet":"Mustafa Zincirkiran","poet_slug":"mustafa-zincirkiran","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ana-okulu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anladım&Ağladım', 'anladim-agladim-umit-tuna-zsifh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Daha bıyıklarım bile terlememişti,

Ellerim hiçbir sevgili eline değmemişti,

Aşkı tertemiz bir duygu bilirdim,

Aşk üzerine nasihatler dinler,

Şiirler okurdum.

Aşk dediler bana,

Yaşamadan anlayamazsın,

Ağlamadan ağlatamazsın,

Heyecandan

Avuçların terlemeden o duyguyu yaşayamazsın,

Korkuyordum ben aşktan,

Ya sonunda kaybeden ben olursam.

Gün geldi bıyıklarım terledi,

Yüreğim her güzele gönül verdi,

Ellerim sevgili eline değdi,

Dudaklarım dudaklarıyla birleşti,

Aşk beni uçuruma sürükledi,

Anladım! 

Artık aşk bir menfaat ilişkisiydi,

Sevişmek vazgeçilmezdi! ...

ÇILGIN MUHASEBECİ', 'Daha bıyıklarım bile terlememişti, Ellerim hiçbir sevgili eline değmemişti, Aşkı tertemiz bir duygu bilirdim, Aşk üzerine nasihatler dinler,...', ARRAY['Türk Edebiyatı','Şiir','Ümit Tuna']::text[], 8.5, '{"poet":"Ümit Tuna","poet_slug":"umit-tuna","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/anladim-agladim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgilim', 'sevgilim-mehmet-ali-sahin-vt01u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Saatler bile değişti

Eski çamlar bardak oldu

SEVGİLİM

Ben nasıl değişmem ki

Aklım fikrim sende kaldı

SEVGİLİM

Gelmiyorsun ki gönlüm eyleyim

Sen yoksun ya kimlere ne söyleyim

Tek istede yollarında öleyim

Bak aşkından toprak oldum

SEVGİLİM', 'Saatler bile değişti Eski çamlar bardak oldu SEVGİLİM Ben nasıl değişmem ki Aklım fikrim sende kaldı SEVGİLİM Gelmiyorsun ki gönlüm eyleyim ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Şahin']::text[], 8.5, '{"poet":"Mehmet Ali Şahin","poet_slug":"mehmet-ali-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sevgilim-109-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Kaldım', 'ben-kaldim-murat-polat-2-ny5qe', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Öylece bırakmıştı beni,

Yada ben öylece kalmıştım.

Gencecik yüreğimi almıştı,

O gitti...Ben kaldım.

Dayandım uzun yıllar,

Sevmelere bile kalkıştım.

Karmakarışıktı herşey,

Aklım gitti ben kaldım.

Her yer yalan, dolandı,

Sevgiler göstermelik,

Ne ben onlara dayandım, ne...

Herkes gitti ben kaldım.

Tükettikçe herşeyi,

Yerine birşey koymadan.

Hazıra can dayanmadı,

Herşey bitti ben kaldım.

Bunca terkediş, bunca kaybediş

Her insanda, yaşanmışta

Kendimden bir parça bıraktım.

Geriye ne kaldı? 

Geriye ben kaldım.

Ben eksildikçe çoğalanım...

                             27 Mart 2006', 'Öylece bırakmıştı beni, Yada ben öylece kalmıştım. Gencecik yüreğimi almıştı, O gitti...Ben kaldım. Dayandım uzun yıllar, Sevmelere bile kal...', ARRAY['Türk Edebiyatı','Şiir','Murat Polat 2']::text[], 8.5, '{"poet":"Murat Polat 2","poet_slug":"murat-polat-2","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ben-kaldim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eyvah', 'eyvah-sennur-cetin-a5dr3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hayalidir,ümididir gerçek sevenlerin 

Elmanın öbür yarısını bulmak 

Leyle ile Mecnun 

Kerem ile Aslı yaşamıştır 

Böyle imrenesi sevdaları 

Buldum sevdamı 

Evet ömür boyu diyorsun 

Birde görüyorsun ki 

Elmanın bir tarafı sarı 

Mum gibi sararıp soluyor 

Öbür yarısı kırmızı elma 

karşında boğa kesiliyor böğürüyor 

Ümitler kararmış yüreğim yanıyor 

Hani o güzelim tertemiz hayallerim 

Eyvah bir yuva daha yıkılıyor.

13.09.1997', 'Hayalidir,ümididir gerçek sevenlerin  Elmanın öbür yarısını bulmak  Leyle ile Mecnun  Kerem ile Aslı yaşamıştır  Böyle imrenesi sevdaları  B...', ARRAY['Türk Edebiyatı','Şiir','Sennur Çetin']::text[], 8.5, '{"poet":"Sennur Çetin","poet_slug":"sennur-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/eyvah-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özledim Seni', 'ozledim-seni-mehmet-ali-sahin-e2zek', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gece demem gündüz demem ararım

Hasretinle alev alev yanarım

Ancak senin busen ile kanarım

Ne olur bekletme özledim seni

Bulmak için dere tepe aşarım

Boz bulanık seller gibi coşarım

Ancak senin havan ile yaşarım

Ne olur bekletme özledim seni

Mehmet Ali bu çileler dolmuyor

İnan ki güzelim sensiz olmuyor

Başkaları hiç halimi bilmiyor

Ne olur bekletme özledim seni', 'Gece demem gündüz demem ararım Hasretinle alev alev yanarım Ancak senin busen ile kanarım Ne olur bekletme özledim seni Bulmak için dere tep...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Şahin']::text[], 8.5, '{"poet":"Mehmet Ali Şahin","poet_slug":"mehmet-ali-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ozledim-seni-48-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yokoluş 3', 'yokolus-3-ozay-saglam-32csc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '542

YOKOLUŞ 3

Kaç bakalım böyle köşe bucak benden

Nereye varacak bu kaçışın

Sus bakalım böyle lal dilsiz ol bana

Nereye

Ne zamana kadar sürecek bu susuşun

Bakma benden tarafa ben olmayayım

Çevir başını

Bensiz olsun görüşün

Nereye kadar kaçacak bakalım bu anlamsız bakışın

Yakamozlara gebe 

Tümü birden

Ve sen

Ve bu kaçış

Uzak tuzak

Ve bu susuş

Tuzla buz

Bu yan bakış bu kaş çatış

Kırışıklıklar

Kırıklar 

Bu işin içinden çıkılmaz travmalar bu yok oluş bu yok kalış.', '542 YOKOLUŞ 3 Kaç bakalım böyle köşe bucak benden Nereye varacak bu kaçışın Sus bakalım böyle lal dilsiz ol bana Nereye Ne zamana kadar süre...', ARRAY['Türk Edebiyatı','Şiir','Özay Sağlam']::text[], 8.5, '{"poet":"Özay Sağlam","poet_slug":"ozay-saglam","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yokolus-3-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Türküm', 'ben-turkum-rahmi-kenger-x3ja0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tarih denen geçmişe Orta Asya''da yazıldım, 

Yazı yoktu bir zaman, kayalara kazıldım, 

Düşmanım çogaldıkça savaşlardan haz aldım, 

Ben Türk''üm beyler, ALLAH''ıma hamdolsun. 

Savaşlarda Kürşat gibi düşmanlara gürledim, 

Barış oldu şamanca dogruları söyledim, 

Semerkant Buhara''da bahçeleri belledim, 

Ben Türk''üm beyler, ALLAH''ıma hamdolsun. 

Asya bana dar geldi, Horasan''a yürüdüm, 

Yeni yurtlar edinip filizlenip büyüdüm, 

Pek çok devlet kurdum, ben her zaman hüridim, 

Ben Türk''üm beyler, ALLAH''ıma hamdolsun. 

Islamla şereflenip hak yoluna girdim ben, 

Irkıma laf söyletmem atama söz verdim ben, 

Gelecek yakın artık, Turanımı gördüm ben, 

Ben Türk''üm beyler, ALLAH''ıma hamdolsun. 

Rahmi Asya''dan geldi anayurda yerleşti, 

Dünyada Türk soyu tarih ile özleşti, 

Bütün boylar toplanıp hak yolunda birleşti, 

Ben Türk''üm beyler, ALLAH''ıma hamdolsun.', 'Tarih denen geçmişe Orta Asya''da yazıldım,  Yazı yoktu bir zaman, kayalara kazıldım,  Düşmanım çogaldıkça savaşlardan haz aldım,  Ben Türk''ü...', ARRAY['Türk Edebiyatı','Şiir','Rahmi Kenger']::text[], 8.5, '{"poet":"Rahmi Kenger","poet_slug":"rahmi-kenger","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ben-turkum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Memurun Çilesi', 'memurun-cilesi-mehmet-ali-sahin-o5ryf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Arabın çilesi petrol bulunca

Zencinin çilesi azat olunca

Delinin çilesi yalnız kalınca

Biter demişlerdi inanmamıştım

Mahpusun çilesi günü dolunca

Kuşların çilesi serbest olunca

Aşığın çilesi yari bulunca

Biter demişlerdi inanmamıştım

Hastanın çilesi iyi olunca

Bülbülün çilesi gülü bulunca

Memurun çilesi ancak ölünce

Biter demişlerdi inanmamıştım', 'Arabın çilesi petrol bulunca Zencinin çilesi azat olunca Delinin çilesi yalnız kalınca Biter demişlerdi inanmamıştım Mahpusun çilesi günü do...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Şahin']::text[], 8.5, '{"poet":"Mehmet Ali Şahin","poet_slug":"mehmet-ali-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/memurun-cilesi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlamsız Geceler', 'anlamsiz-geceler-seyfettin-bilal-ozluk-ctzu4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Devrik cümleler kuruyorum anlamsız gecelerimde

Soru işaretleri peşin sıra kelimelerin arasına dalıyor

Çıkarmak birşey ifade etmiyor noktaları

Herşey yarım kalıyor sen yokken

Düşüncelerim girdaplaşıp dibe çekiyor

Fırtına öncesi sessizlik yaşıyorum içimde

Dur demem lazım biliyorum fırtınaya inat

Durmuyor yellerim sen yokken

Dönmedin bugünde yoksun neredesin

Bırakma yalnızlığımda beni benimle

Alışmamışım yokluğunu hissediyorum yalnızım

Hayat anlamsız sen yokken

Dön gittiğin gibi geri gel

Seviyorum sevgim seninle gitmedi

Usanmaz deli yürek titrer heyecanlanır

Sözlerim boş anlamsız kaldı yine sen yokken...', 'Devrik cümleler kuruyorum anlamsız gecelerimde Soru işaretleri peşin sıra kelimelerin arasına dalıyor Çıkarmak birşey ifade etmiyor noktalar...', ARRAY['Türk Edebiyatı','Şiir','Seyfettin Bilal Özlük']::text[], 8.5, '{"poet":"Seyfettin Bilal Özlük","poet_slug":"seyfettin-bilal-ozluk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/anlamsiz-geceler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimdir Şair', 'kimdir-sair-i-brahim-yavuz-t7irh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şairdir en güzel hisleri duyan

Kağıttır, kalemdir, hecedir şair

İster erkek olsun isterse bayan

Gönüllerde prens ecedir şair

Aydın olan gerçekleri görendir

Gafil olan sinirleri gerendir

Kâmil olan halka umut verendir

Yüreği güzelse yücedir şair

Saygı duymalıdır inanca dine

Asla düşmemeli nefrete kine

Sahip olmalıdır kendi nefsine

Barışçı değilse cücedir şair

Çekinmeden çıkar söyler sözünü

Hiçbir kuvvet yıldıramaz gözünü

Görür bu dünyanın gerçek yüzünü

Sanma ki perdedir peçedir şair

Korkutup yıldırıp sındırıyorsa

Yelkenleri suya indiriyorsa 

Göz boyayıp insan kandırıyorsa

O zaman kara bir gecedir şair

Çirkin, kötü, yanlış varsa yermeli

Gerçekleri göz önüne sermeli

İnsanlara doğru fikir vermeli

Yeri geldiğinde hocadır şair', 'Şairdir en güzel hisleri duyan Kağıttır, kalemdir, hecedir şair İster erkek olsun isterse bayan Gönüllerde prens ecedir şair Aydın olan gerç...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Yavuz']::text[], 8.5, '{"poet":"İbrahim Yavuz","poet_slug":"i-brahim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kimdir-sair-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir anı', 'bir-ani-sennur-cetin-m49o4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sarayburnunun eşsiz güzelliğinde

Seyrediyordum dalgın balıkçıları

Birşey düğümlendi boğazıma

Mazide kalmış birşeyi hatırladım o an

Yalnızdım ve sen yoktun yanımda 

Her zamanki gibi garip tesellisi yaptım

Olsun varsın ihaneti maziye gömersin 

Rahmetli dersin oldu bitti dedim

24.08.2005', 'Sarayburnunun eşsiz güzelliğinde Seyrediyordum dalgın balıkçıları Birşey düğümlendi boğazıma Mazide kalmış birşeyi hatırladım o an Yalnızdım...', ARRAY['Türk Edebiyatı','Şiir','Sennur Çetin']::text[], 8.5, '{"poet":"Sennur Çetin","poet_slug":"sennur-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bir-ani-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülümseyen dünyam :) :)', 'gulumseyen-dunyam-nazan-i-zmirli-85a4d', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'karanlıklar

yaşanmazsa

ayın  feri

yıldızların  yönü

farkedilmez  ki.

karanlıklar 

yaşanmazsa

gülümseyen 

bir gün

özlemle

beklenmez

gülümseyen

bir dünya için

emek 

verilmez ki

yaratmaya  çalıştın

ve 

yarattın..! ! 

aşk''a   savaş   açsanda

gülümsetmeyi   başardığın 

gülümsediğin   dünya   yeter

bana   :)    :)    :)    :)    :)    :)    :)    :)    :)    :)    :)    :)    :)    :)    :)    :)    :)    :)

ben  gülümsemeyi  sen  de  ögrendim

anlamında 

ay  /  güneş  /  yıldız 

saklı. 

adı; 

dünya

ya da 

kendine  değin

gülümseyen

dünya

dünyam olsa.

27.03.06-gülümseyen dünyam-', 'karanlıklar yaşanmazsa ayın  feri yıldızların  yönü farkedilmez  ki. karanlıklar  yaşanmazsa gülümseyen  bir gün özlemle beklenmez gülümseye...', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/gulumseyen-dunyam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kelimeler', 'kelimeler-funda-sag-t5vci', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kelimeler herşeyi anlatmasaydı

konuşur, yazarmıydım hiç? 

Susmak güç olsaydı, 

böyle güçlü olurmuydum hiç? 

Dinleyen olsa,

Olsada anlasa

Böyle çabalarmıydım hiç?', 'Kelimeler herşeyi anlatmasaydı konuşur, yazarmıydım hiç?  Susmak güç olsaydı,  böyle güçlü olurmuydum hiç?  Dinleyen olsa, Olsada anlasa Böy...', ARRAY['Türk Edebiyatı','Şiir','Funda Sağ']::text[], 8.5, '{"poet":"Funda Sağ","poet_slug":"funda-sag","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kelimeler-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İtinayla Çizilir', 'i-tinayla-cizilir-asima-azra-1o6cy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir kızıl elmayı pay edercesine

aşkı da hudutlarla ayırdınız

bıçak bile kahredip üzülmekte

lokmalar yüreğime dizilmekte…

İbadet sandığınız bu katliamı

hangi kitaba bakıp kayırdınız

günah defterleriniz düzülmekte

cennet ayağınızda ezilmekte…

Söyle ey sırdaşım dört duvar odam

gövdenize kazıdığım bu adam

………….itinayla hücreme çizilmekte!', 'Bir kızıl elmayı pay edercesine aşkı da hudutlarla ayırdınız bıçak bile kahredip üzülmekte lokmalar yüreğime dizilmekte… İbadet sandığınız b...', ARRAY['Türk Edebiyatı','Şiir','Asima Azra']::text[], 8.5, '{"poet":"Asima Azra","poet_slug":"asima-azra","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/itinayla-cizilir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bembeyaz Açtım Kanatlarımı Göklere', 'bembeyaz-actim-kanatlarimi-goklere-atilla-guler-tsv5u', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bembeyaz açtım kanatlarımı göklere

gücümün yettiğince

keyifle uyandı sabah yüreğime

özgür bıraktığım saçlarımı

denizler üzerinde

efil efil okşadı rüzgar

şarkılar söyledim bulutlara

vokal yaptı uçurtmalar

rengarenk

usulca süzüldü yanıma güneş

ben başlattım ateşi gözlerimle 

bembeyaz açtım kanatlarımı göklere

dünya döndü!', 'bembeyaz açtım kanatlarımı göklere gücümün yettiğince keyifle uyandı sabah yüreğime özgür bıraktığım saçlarımı denizler üzerinde efil efil o...', ARRAY['Türk Edebiyatı','Şiir','Atilla Güler']::text[], 8.5, '{"poet":"Atilla Güler","poet_slug":"atilla-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bembeyaz-actim-kanatlarimi-goklere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlıklar Kraliçesi', 'yalnizliklar-kralicesi-umit-tuna-6kzl7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yüzünü görmediğim anlarda seviyorum seni,

Neden mi? 

Bana söylediğin yalanlar,

Oynadığın oyunlar o zaman aklıma gelmiyor.

Tutamıyorum kendimi

İşte o zaman seviyorum seni,

Göz göze geldiğimizde içim acısa da,

Nefretim ağır basıyor,

Görünce sevemiyorum seni.

Uzak dur benden,

Yaklaşma bana,

Ben ki,

Kaç yalnızlıkla savaştım,

Alışırım buna da.

Yüzünü görmediğim anlarda seviyorum seni,

Sen sen yalnızlıkların kraliçesi,

Ben bende bu dünyanın en çılgın muhasebecisi.

Yaklaşma bana,

Yüzünü görmediğim anlarda aşığım sana! ...

ÇILGIN MUHASEBECİ', 'Yüzünü görmediğim anlarda seviyorum seni, Neden mi?  Bana söylediğin yalanlar, Oynadığın oyunlar o zaman aklıma gelmiyor. Tutamıyorum kendim...', ARRAY['Türk Edebiyatı','Şiir','Ümit Tuna']::text[], 8.5, '{"poet":"Ümit Tuna","poet_slug":"umit-tuna","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yalnizliklar-kralicesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Toprak Olan Kız...', 'toprak-olan-kiz-i-brahim-ethem-bingul-3myt0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yaşı on yedi

Bahar kız

Baharı göremeden

Solan kız...

Bir şırıngalık zevk uğruna

Özendirilen o bataklıkta

Gençliğine doymadan

Toprak olan kız...

Yaşı on yedi

Bahar kız

Baharı saramadan

Toprağa sarılan kız...

www.iebingul.com', 'Yaşı on yedi Bahar kız Baharı göremeden Solan kız... Bir şırıngalık zevk uğruna Özendirilen o bataklıkta Gençliğine doymadan Toprak olan kız...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/toprak-olan-kiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yurduma Öz Eleştiri', 'yurduma-oz-elestiri-sahabeddin-erzurumluoglu-gz2gv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bereket fışkıran toprağı yaktık

Suları kirletip mikroplu aktık

Çevre konusunda sınıfta çaktık

Hayvanlar kaçıyor bizim diyardan

Kırmızı Bibere boyayı kattık

Doğal dondurmaya süt tozu attık

Cevizli sucuğu şekerli sattık

İnsanlar kaçıyor bizim diyardan.

Göç yolunda kuşun suyunu kestik

Sazlığı ateşe vererek estik

Dağlarda ormanı epeyce kestik

Martılar kaçıyor bizim diyardan.

Sigorta var diye kibriti çaldık

Zengin olmak için ihale aldık

Allah’tan korkmadan harama daldık

Tartılar azıyor bizim diyarda.

Dostlar acı söyler doğru sözleri

Hatasından döner gören gözleri

Gerçek yiğitlerin sağlam özleri

İnsanlık uçuyor bizim diyarda…', 'Bereket fışkıran toprağı yaktık Suları kirletip mikroplu aktık Çevre konusunda sınıfta çaktık Hayvanlar kaçıyor bizim diyardan Kırmızı Biber...', ARRAY['Türk Edebiyatı','Şiir','Şahabeddin Erzurumluoğlu']::text[], 8.5, '{"poet":"Şahabeddin Erzurumluoğlu","poet_slug":"sahabeddin-erzurumluoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yurduma-oz-elestiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkuyorum', 'korkuyorum-sefika-celik-pxujs', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bakamıyorum gözlerine 

Korkuyorum kaybolurum sende diye

Korkuyorum ben sende kaybolurken,

Sen başkasını seversin, 

Ben sendeyken,sen başkasında olursun diye.

Ellerine dokunmak istiyorum.

Korkuyorum yine

Çekersin, istemezsin belki diye.

Ellerim titrer dayanamam böylesine.

Seni seviyorum demek istiyorum

Ya kelimeler takılırsa boğazıma.

Korkuyorum ya konuşmadan daha, 

Sesim çıkmaz olur söyleyemem diye.

Korkuyorum seni kaybetmekten çok korkuyorum.

Ben sende yaşamak isterken,gitmenden korkuyorum.

Beni sevmemenden,bu sevgiyi yalnız yaşamaktan çok korkuyorum.

Sensizlikten çok korkuyorum.

	

					(Sultanbeyli-27.03.2006)', 'Bakamıyorum gözlerine  Korkuyorum kaybolurum sende diye Korkuyorum ben sende kaybolurken, Sen başkasını seversin,  Ben sendeyken,sen başkası...', ARRAY['Türk Edebiyatı','Şiir','Şefika Çelik']::text[], 8.5, '{"poet":"Şefika Çelik","poet_slug":"sefika-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/korkuyorum-141-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doktor Beye Teşekkür', 'doktor-beye-tesekkur-abdullah-odabas-psyv6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '(Yarb.Dr.Fahrettin Alpaslan Bey''e) 

Kıymetli doktor Fahrettin Beye,         	

Ne kadar teşekkür eylesem azdır,        	

Canlara can katar hünerli eller,        	

Ne kadar teşekkür eylesem azdır,        	

Ameliyat anında kahraman olur,          	

Besmele ile hastaya bıçağı vurur,       	

Derdin nerede ise arayıp bulur,         	

Ne kadar teşekkür eylesem azdır,      

Bütün hastalara şefkatle bakar,

Sönmüş ocakları yeniden yakar,

Kimisi yatar kimisi çıkar,

Ne kadar teşekkür eylesem azdır,

Şifa hastanesinin şifa sembolü,

Dolaşsan Ankara, İzmir hem İstanbul''u,

Hoş sohbet tatlı dil et hasbihali,

Ne kadar teşekkür eylesem azdır,

Meftuni der gözle gördüm bu hali,

Doktor beyin cihanda yok emsali,

Erzurum şehrinin tek iftihari,

Ne kadar teşekkür eylesem azdır,', '(Yarb.Dr.Fahrettin Alpaslan Bey''e)  Kıymetli doktor Fahrettin Beye,         	 Ne kadar teşekkür eylesem azdır,        	 Canlara can katar hü...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Odabaş']::text[], 8.5, '{"poet":"Abdullah Odabaş","poet_slug":"abdullah-odabas","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/doktor-beye-tesekkur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cinsel Eğitim', 'cinsel-egitim-abdullah-odabas-uq9zn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Daha neler duyacak kulaklarımız,      

Mektepte olacak cinsel eğitim,          	

Müslüman olmaz bu kadar serseri,        	

Kabulu muhal olmaz efendim,           

Cinsi mesele en mahrem bir hal,       

Her yerde konuşulmaz olmaz kılu-kal,    	

Ne acı durum ne çirkin bir hal,         	

Kabulu muhal olmaz efendim,             	

Müslüman devletler duyarsa şayet,       	

Silerler defterden ederler lanet,       	

Demezler merhaba eylemez ülfet,         	

Kabulu muhal olmaz efendim,             	

Gayretullaha şayet dokunsa,             	

Ya bir zelzele olur ya bir kasırga,     	

Ötüşür harabede binlerce karga,         	

Kabulu muhal olmaz efendim,             	

Bela gelmeden yahu uyanmak gerek,

Demesin mesul kişiler ya neme gerek,

Son pişman olsanda bağrın döğerek,

Kabulu muhal olmaz efendim,

Dert büyük yareb derman dileriz,

Bu gafleti yurttan nasıl sileriz,

Bu gidişle ağlamaz neden güleriz,

Kabulu muhal olmaz efendim,

Ne islama yakışır ne de bir Türke,

Şanlı komutan Fatih, ne Atatürk''e,

Duysa vahşiler bizlerden ürke,

Kabulu muhal olmaz efendim,

Okudum Türk tarihin boylu boyunca,

Böyle bir şeri hadise olmamış nice,

Aklımı oynattım sanki duyunca,

Kabulu muhal olmaz efendim,

Meftuniyem dert dökerem derinden,

Korkaramki yer gök oynar yerinden,

Feda bu can vatana ben geçerem serimden,

Kabulu muhal olmaz efendim,', 'Daha neler duyacak kulaklarımız,       Mektepte olacak cinsel eğitim,          	 Müslüman olmaz bu kadar serseri,        	 Kabulu muhal olma...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Odabaş']::text[], 8.5, '{"poet":"Abdullah Odabaş","poet_slug":"abdullah-odabas","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/cinsel-egitim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Darulaceze''den Sesleniş', 'darulaceze-den-seslenis-hasan-karahisar-4fcyf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne zaman derilmiş bir çiçek görsem çocuk elinde,

Bu, biricik yavrumun anneler günü hatırasıdır bende.

Puslu gözlerle bakarım bir akranını görsem karşımda,

Ciğer parem tüter burnumda, bilseniz kanayan bir yaradır içimde.

Derim: “Koştu da geldi, duyunca biricik annesinin halini”,

Alıp da götürecek sıcacık yuvamıza tekrar beni.

Beyaz atlı prensimin alıp götürdüğü gibi beni.

Ne kadar isterdim bilseniz, hiç unutmamak hayalini.

Acıyarak değil, ibretle bakın bize,

Gençliğini nerede, nasıl tüketmiş diye.

Kim dediyse güzellik solar, gençlik biter bize,

Hiç inanmazdık gördüğünüz bugünkü bize.', 'Ne zaman derilmiş bir çiçek görsem çocuk elinde, Bu, biricik yavrumun anneler günü hatırasıdır bende. Puslu gözlerle bakarım bir akranını gö...', ARRAY['Türk Edebiyatı','Şiir','Hasan Karahisar']::text[], 8.5, '{"poet":"Hasan Karahisar","poet_slug":"hasan-karahisar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/darulaceze-den-seslenis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türk Askeri - 1', 'turk-askeri-1-abdullah-odabas-2gkpu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Türk askeri hak leşkeri,                		

Hep ileri durmaz geri,                  		

Kahraman komutan hem erleri,          

Cihanda payidar muzaffer olsun.         	

Basar silahını vermez bağrına,        

Can verir millet-vatan uğruna,          	

Koşsa çıkar Kaf dağının başına,         	

Cihanda payidar muzaffer olsun.         	

Bükülmez Türkün çelik bileği,           	

Kahraman askerin çatal yüreği,          	

Bırakmaz elinden bayrak sancağı,      

Cihanda payidar muzaffer olsun.         	

Şanlı tarihi dolu fetihler,             		

O büyük komutan Yavuz, Fatihler,        	

Asker Allah Allah der düşman titrer,    	

Cihanda payidar muzaffer olsun.         	

Atatürk''te Yunanı döktü denize,

Kim çatarsa pişman olur o bize,

Bunlar nasihat söylerim size,

Cihanda payidar muzaffer olsun.

Korede yardılar çetin çemberi,

Kıbrıs''ta gösterdi büyük hüneri,

Bin düşmana bedel Türkün bir eri,

Cihanda payidar muzaffer olsun.

Sınıfım topçudur atarım havan,

Hiç düşme yeise kendine güven,

Orduya, askere bu olsun duam,

Cihanda payidar muzaffer olsun.

Meftuniyem söylerem ben özümden,

Ah vatanım derken yaşlar akar gözümden,

Pederim gazidir ben giderim peşinden,

Cihanda payidar muzaffer olsun.', 'Türk askeri hak leşkeri,                		 Hep ileri durmaz geri,                  		 Kahraman komutan hem erleri,           Cihanda payidar...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Odabaş']::text[], 8.5, '{"poet":"Abdullah Odabaş","poet_slug":"abdullah-odabas","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/turk-askeri-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '20. Asrın Erkeği', '20-asrin-erkegi-abdullah-odabas-yne7j', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Erkeklik kalmadı zamane bayda,        

Arasan bulunmaz şehirde, köyde,         	

Ne Çorum, Erzurum, Kayseri, Niğde,      	

Sıfırdan sıfıra düşmüş gidiyor,         	

Bayanlar emreder baylar biçare,         	

Açıldı sinemde hezaran yare,           	

Yok mu bir koçak, gözleri kara,         	

Sıfırdan sıfıra düşmüş gidiyor,       

Ne dese bayan söz onun olur,          

Emretse bayan kuş südü bulur,            	

Bilen bilir bilmeyen de ne bilir,       	

Sıfırdan sıfıra düşmüş gidiyor,         	

Ne koçaklar gördük koç gibi herif,      	

Bayana o eder her işi tarif,            		

Şimdiki baylar müsvedde herif,          	

Sıfırdan sıfıra düşmüş gidiyor,       

Görmedik böyle şey gösterdi felek,

Hiç olup gitti bu muydu dilek,

Heba oldu bunca verilen emek,

Sıfırdan sıfıra düşmüş gidiyor,

Bu afat sarmış bütün çevreyi,

Bayanlar attılar baştan çevreyi,

Bizde böyle geçirdik bizim devreyi,

Sıfırdan sıfıra düşmüş gidiyor,

İntizar mı aldık yoksa beddua,

Bulunmaz bir bayan kocayı saya,

Bu yüzden dağılır binlerce yuva,

Sıfırdan sıfıra düşmüş gidiyor,

Erkeklik silindi süngerle fayla,

Ne desen nafile getirmez fayda,

Temelden bozuldu köklü aile,

Sıfırdan sıfıra düşmüş gidiyor,

Meftuni son demde etmedin para,

El açta yalvar perverdigara,

Kudret merhemi ile yareni sara,

Sıfırdan sıfıra düşmüş gidiyor,', 'Erkeklik kalmadı zamane bayda,         Arasan bulunmaz şehirde, köyde,         	 Ne Çorum, Erzurum, Kayseri, Niğde,      	 Sıfırdan sıfıra d...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Odabaş']::text[], 8.5, '{"poet":"Abdullah Odabaş","poet_slug":"abdullah-odabas","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/20-asrin-erkegi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taziye', 'taziye-abdullah-odabas-r5tdj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Teselli eylerem sizi kederli baba ve anne,   	

Hatimler, Kuranlar okundu Ahmet Çimen''e, 

İnşallah göçmüştür kamil imanla,             	

Makamı nur olsun sizler sağ olun,            	

Yandı Erzurum bütün dostları,                	

Mescitte kıldılar hem ahu zarı,              	

Herkez çalıştı bir arı misali,               	

Makamı nur olsun sizler sağ olun,          

Yusuf Ziya hoca başkanlık etti,              	

Çimen''in ruhuna kuran okuttu,              

Sonunda beliğ bir dua etti,		    	

Makamı nur olsun sizler sağ olun,            	

Mescitten eksildi bir sadık cemaat,        

Herkes hakkında eyledi mümin şehadet,

Varsa taksiri yareb sen affet,

Makamı nur olsun sizler sağ olun,

Olsun evlatları mümini kamil,

Okuyup ilim olsunlar amil,

Uyup zamana kalmasın cahil,

Makamı nur olsun sizler sağ olun,

Çimen yeşerdi dostlar kalbinde,

Dileriz rahat yatsın aziz kabrinde,

Sağ elinde olsun defter kıyamet günde,

Makamı nur olsun sizler sağ olun,

Sizlere teselli bizlere düşmez,

Elbette mümin kaderden kaçmaz,

Adam olsa Meftuni yareyi açmaz,

Makamı nur olsun sizler sağ olun,

(Merhumun ruhu için fatiha)', 'Teselli eylerem sizi kederli baba ve anne,   	 Hatimler, Kuranlar okundu Ahmet Çimen''e,  İnşallah göçmüştür kamil imanla,             	 Maka...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Odabaş']::text[], 8.5, '{"poet":"Abdullah Odabaş","poet_slug":"abdullah-odabas","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/taziye-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çanakkale', 'canakkale-hasan-karahisar-36b0p', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çanakkale, bir tarihin yazıldığı yer:

Taşıdığı 250 kiloluk mermisiyle Seyyid Onbaşı’nın,

Türk Milleti için kendini feda eden 57. Alay’ın,

İsimleri dahi sır olan kahraman Mehmetçiklerin,

“Çanakkale Geçilmez! ” diyen Mustafa Kemal’in

Yazdığı bir tarih.

Çanakkale, bir vahşetin yaşandığı yer:

Denizdeki her katrenin kızıla boyandığı,

Mermilerin vücutları lime lime ettiği,

Memleketimde nice ocakların söndüğü,

Vahşi hayvanların bile gıptayla izlediği

Korkunç bir vahşet.

Çanakkale, Allah lafzının susmadığı yer:

Düşünen bir zihinde, çarpan bir yürekte gizlenen,

Nidalarla, tekbirlerle, iniltilerle arşa yükselen,

Dualarla, dillerde, dudaklarda huşuyla vücut bulan,

Şehitlerimizin son nefesinde hayat bulan

La ilahe illALLAH lafzı.', 'Çanakkale, bir tarihin yazıldığı yer: Taşıdığı 250 kiloluk mermisiyle Seyyid Onbaşı’nın, Türk Milleti için kendini feda eden 57. Alay’ın, İs...', ARRAY['Türk Edebiyatı','Şiir','Hasan Karahisar']::text[], 8.5, '{"poet":"Hasan Karahisar","poet_slug":"hasan-karahisar","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/canakkale-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüşvet', 'rusvet-hasan-karahisar-7h3vx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dedim: “Rüşvet bu kardeşim rüşvet! ”

Dedi ki: Ben nüfuzumu kullanırım,

Bunun neresindedir rüşvet? ! ...”

Vereyim gitsin mi yani mangırım.

Dedim: “İnsanlar hak ediyorsa almalı.

Kul hakkı işin içine girerse orada kalmalı.”

Er kişi ol da söyle: “Olmasaydın o makamda,

Yaparlar mıydı işini mangırsız da? 

Derler ki: “Bir deli kuyuya taş atmış,

Kırk akıllı onu oradan çıkaramamış.

Varın siz karar verin bakalım şimdi,

Haklı olan memur mu yoksa şair miydi?', 'Dedim: “Rüşvet bu kardeşim rüşvet! ” Dedi ki: Ben nüfuzumu kullanırım, Bunun neresindedir rüşvet? ! ...” Vereyim gitsin mi yani mangırım. De...', ARRAY['Türk Edebiyatı','Şiir','Hasan Karahisar']::text[], 8.5, '{"poet":"Hasan Karahisar","poet_slug":"hasan-karahisar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/rusvet-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vize!', 'vize-mesut-ozturk-2kmd8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hayatımızı farkında olmadan etkileyen bazı faktörler vardır. 

Her olayda, her halükarda, karşılaştığımız, bu faktörlerden 

biriside vizedir. Vize bir devletten diğer bir devlete 

geçerken o devlet konsolosluklarında verilen izine denir. 

Halbuki sadece bu değildir. Însanoğlunun yaşayabilmesi, 

bu Dünyada var olabilmesi için gereken havada solunum vizesidir.

Yaşayabilmemiz hava alıp verebilmemiz, 

o karmaşık yapımızın faaliyetini düzenli bir şekilde yapması, 

kan dolaşımın devam  etmesi böbrek, kalp ciğer gibi 

organların işlemesi, Aklın hayatımızı yönlendirmesi 

Allahın izniyledir.  Öyleyse biz Allahu Tealadan vizemizi 

almışız. Okulu bitirip daha yükseğine kayıt olmak için 

gereken evrakları hazırlamamız, araştırmaya tabi tutulmamız, 

ancak o okulda gereken şartlara uygun olmamız için 

verdiğimiz mücadele sonucu aldığımız hakta vizedir. 

Geçinmek için verdiğimiz çabalar,evlat büyütmek için 

sarfedilen zamanlar, borç ödemek için verilen çekler, 

senetler, hepsi istikbal için olan kavramlardır. 

Eğer ki sonuçta mutluluk olduysa vizemizi almışız demektir.', 'Hayatımızı farkında olmadan etkileyen bazı faktörler vardır.  Her olayda, her halükarda, karşılaştığımız, bu faktörlerden  biriside vizedir....', ARRAY['Türk Edebiyatı','Şiir','Mesut Öztürk']::text[], 8.5, '{"poet":"Mesut Öztürk","poet_slug":"mesut-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/vize-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel gönül yar-ı senindir senin', 'gel-gonul-yar-i-senindir-senin-ali-riza-unal-wuowc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne  ateştir  yanar  sine-i bahrım,

Nemrurutun nar-ı serindir serin,

Yaş oldu akar-dide-i kahrım,

Gel  gönül yar-ı senindir senin,

Tükendi muradım sensin bahtım,

Bu sevda kuyusu-derindir derin,

Bu feryada sûkut,sendedir ahtım,

Gel  gönül yar-ı senindir senin,

---    nakarat    ----

kadere vefa,bu demde sefadır,

Bu aşkta ölmek,benimdir benim.', 'Ne  ateştir  yanar  sine-i bahrım, Nemrurutun nar-ı serindir serin, Yaş oldu akar-dide-i kahrım, Gel  gönül yar-ı senindir senin, Tükendi mu...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gel-gonul-yar-i-senindir-senin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yuh Çekelim', 'yuh-cekelim-i-brahim-pataz-cmvjf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gelin, kardeşlerim bizi,

Bölenlere, yuh çekelim.

Atalardan kalan izi,

Silenlere, yuh çekelim.

   Yükünü taşırım elin,

   Sırtım çıplak, ayak yalın,

   Hile ile, yurdun malın,

   Çalanlara, yuh çekelim.

Neden, ele, teslim vatan? 

Kahrolsun, kutsalı satan,

Yıllarca halkı uyutan,

Yalanlara, yuh çekelim.

   Kan ağlıyor Anadolu,

   Bu mu? Kalkınmanın yolu,

   Sinsi oyunlarla dolu,

   Planlara yuh çekelim.

Uyan artık,  gardaş uyan,

Bizden değil, bizi soyan,

Ülkemizi geri koyan,

Talanlara yuh çekelim.

   Kuzuların çobanı, kurt,

   Bu nedenle, artıyor, dert,

   Yolsuzluktan, büyük servet,

   Bulanlara, yuh çekelim.

Kararı, sen ver her işe,

Yurdunda, özgürce yaşa,

Ellerin eline maşa,

Olanlara yuh çekelim.

   Bir olalım, birliğe gel,

   İkiliği, aklından sil,

   Bize sövüp, elden ödül,

  Alanlara, yuh çekelim. 

Güzel nutuk, ata ata,

Yön verilmiş, memlekete,

Makamlarında, gaflete,

Dalanlara, yuh çekelim.

   Kin güder, eller  soyuna,

   Bu böyle olmuş, boyuna,

   Her işte, başka oyuna,

   Gelenler, yuh çekelim. 

Sözde aydın, nedir kastın? 

Soyuma, düşmandır dostun,

Yabancıyı,Türk’ten üstün,

Bilenlere, yuh çekelim.

   Türk- İslam’a, türlü  tuzak,

   İnanmazsan, dünyaya bak,

   Bizi, bize vurdurarak,

   Gülenlere, yuh çekelim.

ELEMİ’nin, budur kastı,

Bilmeli, düşmanı dostu,

Dünyamıza, teröristi,

Salanlara, yuh çekelim.

24/07/2005 ADANA

(İBRAHİM PATAZ)', 'Gelin, kardeşlerim bizi, Bölenlere, yuh çekelim. Atalardan kalan izi, Silenlere, yuh çekelim.    Yükünü taşırım elin,    Sırtım çıplak, ayak...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Pataz']::text[], 8.5, '{"poet":"İbrahim Pataz","poet_slug":"i-brahim-pataz","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/yuh-cekelim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Varken Bahar Oldu Tüm Mevsimler', 'sen-varken-bahar-oldu-tum-mevsimler-adnan-cakir-37dik', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir başka güzeldir,

Yüreğinde koklamak gülü.			

Sevginin yağmurunda yıkanmak ölesiye.	

Ve hissetmek sevdanın ateşini.

Seni kokladım da karanfiller soldu,			

Seni yüreğime aldım da,

Güller küstü bana.			

Yokluğunda,

Yağmurlar ıslatamadı beni,

Dünya sustu,

Tenimde can kalmadı.			

Sen varken,

Bahar oldu tüm mevsimler.', 'Bir başka güzeldir, Yüreğinde koklamak gülü.			 Sevginin yağmurunda yıkanmak ölesiye.	 Ve hissetmek sevdanın ateşini. Seni kokladım da karan...', ARRAY['Türk Edebiyatı','Şiir','Adnan Çakır']::text[], 8.5, '{"poet":"Adnan Çakır","poet_slug":"adnan-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sen-varken-bahar-oldu-tum-mevsimler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyler   2', 'beyler-2-i-brahim-pataz-t10at', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kanallardan baktım gene aleme,

Söylenenler, akla,  uymuyor  beyler

Doğruları, almıyorlar kaleme,

Müslümanlar, cana kıymıyor beyler.

   Medya, esir almış, fikri hürleri,

   Gün geçtikçe, tükeniyor türleri,

   Yazar etmiş, hakka gözü körleri,

   Gerçekleri, halka yaymıyor  beyler.

Kur, hayali, yada, güdümlü örgüt,

Dünyaya, terör  yay, ülke işgal et,

İnsanlar bir sürü, çobanlar, aç kurt,

Cani, can almaya  doymuyor beyler.

   Hepsinin içinde, dopdolu kini,

   Ortak düşmanları, tek, İslam Dini,

   Yağma, Müslüman’ın malı, bedeni,

   Zalim, kararından, caymıyor beyler.

Demokrasi, barış, savaş aleti,

Öldür, özgür eyle, işte bu,Batı,

Hapiste yaşamak, ölümden kötü,

İnsanlar, olanı duymuyor beyler.

   Büyük zevktir, masumlarla cenkleri,

   Ölüm saçar, uçakları, tankları,

   Müslüman’a yok mu, (İnsan Hakları?) 

   Yoksa, insandan mı,  saymıyor beyler? 

Gelip, gidip, çalıyorlar kapını,

Bize uydur diye, sosyal yapını,

Barış tezgahına, kirli ipini,

Adamlar, boşuna ıymıyor beyler.

   Kurumuyor, ELEMİ’nin gözleri,

   Acı, ama, gerçek bütün sözleri,

   Yıllar var ki, sözde dostlar bizleri,

   Hiç, adam yerine, koymuyor beyler.

   14/07/2005 ADANA(İBRAHİM PATAZ)', 'Kanallardan baktım gene aleme, Söylenenler, akla,  uymuyor  beyler Doğruları, almıyorlar kaleme, Müslümanlar, cana kıymıyor beyler.    Medya...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Pataz']::text[], 8.5, '{"poet":"İbrahim Pataz","poet_slug":"i-brahim-pataz","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/beyler-2-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karaya Aktım', 'karaya-aktim-elif-nida-ozkan-vhrv9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gün bir söz bırakıp kulaklarına

Göğüne çekilip bulutlarına

Bir ucundan iblis çeker bir  ucundan sen 

Kollarını bağlayan deli-gömlekler,ne giyinsen? 

Ardında kalem gıcırtısı kanat seleri

Duydunuz mu hey sez de duydunuz mu! 

Bu da yazıldımı diye hiç sordunuz mu? 

Atlara ve meleklere aşık olupta

Yer ve gök arasını tam bir soluklta

İçinize çekip yoruldunuz mu? 

Mağaralarda ışık metropolde toz

İsa çıkıyor yokuşu dik merdiveni 

Arabalar yol açın geri dönüyor

Hani öldü demiştiniz bakın gülüyor! 

Kitapları gömdüler işte bu yüzden

Göz ve dilin önündeki kara dehlizden 

Kan doluyor tacına kör kralların

Kirden renk çoğaltan sihirbazların

Karanlık aynasında gün nasıl son bulur 

Ya Hira''yı bilen var mı? Nasıl OKU-NUR? 

Kum zamanın ışıması

Çöl zamanın aşınması

ve yük toz içinde yürüyene ne zordur

Dönerek annemin ve İbrahim''in evine 

Desem biraz zamana dur-suya biraz daha dur! 

Cennetin tüm esmer taşlarını topladım

Ceplerimdeki yırtık kalbimden fazla değil

Şeytana o köprüde ayak üstü rastladım

Uzunca bir ateşi körüklüyordu sefil! 

Beklemedim yürüdüm tabanlarım kapkara

Yüzümü söküp yerden başladım bir duaya

Kökleri bulut bulut o görkemli ağaca; 

Ne olur 

Gemileri

Dar sokaklardan geçir

Ve suları çekilen

Kirlenen-koyulaşan

Yaban denizimize

Üzerimize eğil...', 'Gün bir söz bırakıp kulaklarına Göğüne çekilip bulutlarına Bir ucundan iblis çeker bir  ucundan sen  Kollarını bağlayan deli-gömlekler,ne gi...', ARRAY['Türk Edebiyatı','Şiir','Elif Nida Özkan']::text[], 8.5, '{"poet":"Elif Nida Özkan","poet_slug":"elif-nida-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/karaya-aktim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayıp', 'kayip-firat-caliskan-h8j3j', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir ah çekip bin ahı boğsam					

İçime doldursam sessizliği ölü				

Yanlızlığım ve düşlerim kazınsa yüzeme				

Bakışlarım insanlara çığlık çığlığa haykırsa aşıksı			

Kopsa kıyamet gözlerimde, dökülse yüzümden tüm acı ifadeler		

Yüreğim dingin bir deniz sarhoşsu					

Bakışların gözlerimi felaket fırtınalara çevirse				

Sonra anlatsam ağzımdan tek kelime çıkmadan 			

Kopan çığlıkları kimselere duyurmadan				

Kalabalıklarda yalnızlığı bulsam felçli					

kolu kanadı kırık						

Düşlerime sarılsam						

Göğüs kafesimi parçalayıncaya kadar', 'Bir ah çekip bin ahı boğsam					 İçime doldursam sessizliği ölü				 Yanlızlığım ve düşlerim kazınsa yüzeme				 Bakışlarım insanlara çığlık ç...', ARRAY['Türk Edebiyatı','Şiir','Fırat Çalışkan']::text[], 8.5, '{"poet":"Fırat Çalışkan","poet_slug":"firat-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kayip-60-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hükümsüz Artık Bu Aşk', 'hukumsuz-artik-bu-ask-firat-caliskan-g462m', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Acıyla kıvranıyor							

Taş duvarlar arasına sıkışmış					

Çırpınışı kar etmiyor ki					

Sıva''sı dökülmüş bir sevdanın,					

çatlaklarını kapatmaya yetmiyor artık bu yürek				

Senin için çarpacak, beni ise avutacak olan bir yürek			

Seni belki ölümsüzleştirir hasretine iki mısra dökmek			

Ama sadece kağıt üzerinde,					

seni silmekse benim elimde					

Acıyla kıvranmam, senin için çırpınmam,				

bize yetmeyen yürek, hasretine iki mısra dökmek ve seni silmek		

Benim tükenmişliğimin seninde bittiğinin kanıtı 			

Hükmü yok artık bu aşkın', 'Acıyla kıvranıyor							 Taş duvarlar arasına sıkışmış					 Çırpınışı kar etmiyor ki					 Sıva''sı dökülmüş bir sevdanın,					 çatlaklarını k...', ARRAY['Türk Edebiyatı','Şiir','Fırat Çalışkan']::text[], 8.5, '{"poet":"Fırat Çalışkan","poet_slug":"firat-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hukumsuz-artik-bu-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyaz Masal', 'beyaz-masal-elif-nida-ozkan-9xnan', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'o masalcı,bu mevsim dağlardan kar getirir

bakar ve öyle söyler,gözlerinde titreme

bir harf konar o dağın en olmaz tepesine

ellerinde tuttuğun,bu kar gibiyse insan

şimdi beyaz ve parlak,avcumu okşuyorsan

dilerim ve bilirim

sönmeyeceğini

eriyip zamanda

yitmeyeceğini

göğe baktım 

aynı yol

umut her mevsim vatan

o soğuk değildi ki 

bizi ayakta tutan....', 'o masalcı,bu mevsim dağlardan kar getirir bakar ve öyle söyler,gözlerinde titreme bir harf konar o dağın en olmaz tepesine ellerinde tuttuğu...', ARRAY['Türk Edebiyatı','Şiir','Elif Nida Özkan']::text[], 8.5, '{"poet":"Elif Nida Özkan","poet_slug":"elif-nida-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/beyaz-masal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost Arama', 'dost-arama-rahmi-kenger-h55zs', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Benim sevdam zirvelerde dolaşmak, 

Altaylardan Erciyes’e ulaşmak, 

Amacimiz durmak degil yol aşmak, 

Dost arama dön kendine Türkiye’m. 

Türk tarihi örnek olsun agalar, 

Bu vatani sevmeyene yuhalar, 

Karar için nerde kaldi dualar, 

Dost arama dön kendine Türkiye’m. 

Özbek-Azer-Kazak benim dallarim, 

Dünya’yi saracak bir gün kollarim, 

Bütün dallarima selam yollarim, 

Dost arama dönkendine Türkiye’m. 

Kirgiz-Avar her birisi Türkoglu, 

Avşar-Çerkez hepside Türkoglu, 

Güven duy sen milletine Türkoglu, 

Dost arama dön kendine Türkiye’m. 

Rusya dagıldıki dogdu devletler, 

Türk’e kefen biçen yaşli veletler, 

Çok şükür bunlarida gördük evlatlar, 

Dost arama dön kendine Türkiye’m 

Avrasya’dan selam olsun dünyaya, 

Avrupa çöküyor kalacak yaya, 

Son ver artik yarim kalan rüyaya, 

Dost arama dön kendine Türkiye’m', 'Benim sevdam zirvelerde dolaşmak,  Altaylardan Erciyes’e ulaşmak,  Amacimiz durmak degil yol aşmak,  Dost arama dön kendine Türkiye’m.  Türk...', ARRAY['Türk Edebiyatı','Şiir','Rahmi Kenger']::text[], 8.5, '{"poet":"Rahmi Kenger","poet_slug":"rahmi-kenger","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/dost-arama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Moralim Ağrıyor', 'moralim-agriyor-firat-caliskan-1zx6k', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hani daralırya ruhun					

Alıp yüreğini sökmek istersin ya yerinden				

Yapmak isteyipte yapamadıklarındır				

Olması gerektiğini düşündüklerin						

Tutacakmışsın gibi yakındır					

Ama uzansan tutamazsın					

Bir kötü kahkaha patlar yüzüne 					

kulaklarında yankısı çınlar 					

Tüm hayaller, umutlar ve gelecek güzel günler 				

bir moloz yığını gibidir artık düşer üstüne				

Altından kalkamazsın						

Takatin kalmaz aman dilemeye bile, susarsın				

Atarsın içine ve yakar seni					

Soran olsa bile ''yok birşeylere sığınırsın''				

O zaman öyle acizsindirki 					

Köpekler bile acır haline', 'Hani daralırya ruhun					 Alıp yüreğini sökmek istersin ya yerinden				 Yapmak isteyipte yapamadıklarındır				 Olması gerektiğini düşündükle...', ARRAY['Türk Edebiyatı','Şiir','Fırat Çalışkan']::text[], 8.5, '{"poet":"Fırat Çalışkan","poet_slug":"firat-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/moralim-agriyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Kır Çiçeği', 'ey-kir-cicegi-rahmi-kenger-qg1y0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne su veren olur nede sevenin, 

Aşigim sana ben, ey kır çiçegi, 

Kayalardır senin tek bir güvenin, 

Aşıgım sana ben, ey kır çiçegi. 

Yaratan özenmiş her bir rengine, 

Saraylarda rastlamadim dengine, 

Şöyle bir bakinca düze engine, 

Aşıgım sana ben, ey kır çiçegi. 

Tek dalını koparmaya kıyamam, 

Günlerce koklasam sana doyamam, 

Yapragın alıpta seni sayamam, 

Aşıgım sana ben, ey kır çiçegi. 

Kelebekler bile gezer dalında, 

Tat olursun arıların balında, 

Gönül seni tanır sevda yolunda, 

Aşıgım sana ben, ey kır çiçegi. 

Çigdem, kekik, ıtır ile menekşe, 

Resmetmişler seni oyaya nakşa, 

Ne olur çiçegim hep beni okşa, 

Aşıgım sana ben, ey kır çiçegi. 

Adını söylemek uysallık olur, 

Her topraktan çeşit çeşit renk alır, 

Kuşlar bile sizde sevgiyi bulur, 

Aşıgım sana ben, ey kır çiçegi. 

Her renginde ayrı ayrı koku var, 

Her esen rüzgarla selamın savar, 

En büyük düşmanın bilirim davar, 

Aşıgım sana ben, ey kır çiçegi. 

Senden haz alırım gördügüm yerde, 

Bazen rengin derman oluyor derde, 

Neden boynun bükük yoldaşın nerde, 

Aşıgım sana ben, ey kır çiçegi. 

Yaratan Allah’a kurban olayım, 

Seni görüp muhabbetle dolayım, 

Sen solmada ben saçımı yolayım, 

Rahmi sana aşık, ey kır çiçegi.', 'Ne su veren olur nede sevenin,  Aşigim sana ben, ey kır çiçegi,  Kayalardır senin tek bir güvenin,  Aşıgım sana ben, ey kır çiçegi.  Yaratan...', ARRAY['Türk Edebiyatı','Şiir','Rahmi Kenger']::text[], 8.5, '{"poet":"Rahmi Kenger","poet_slug":"rahmi-kenger","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/ey-kir-cicegi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türk Meni', 'turk-meni-rahmi-kenger-g6fgw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kaldıya milletler suskun bir zaman, 

Kar bastı her yanı vermedi aman, 

Ermeni zulmüyse soğuktan yaman, 

Ermeni değil mi vuran Türk-meni? 

İnanç serbest diye suç mu işledik? 

Ermeniyi Türk oğluyla eşledik, 

Bizler tarih boyu boşa düşledik, 

Ermeni değil mi vuran Türk-meni? 

Erzurum, Erzincan çok çekti çile, 

Ardahan, Kars için yapılan hile, 

Şehitler verirken Van şehrim bile, 

Ermeni değil mi vuran Türk-meni? 

Her nerde var ise bir Türkmen eri, 

Bilsin artık bunlar batı hüneri, 

Sabah olup söndürmeden feneri, 

Ermeni değil mi vuran Türk-meni? 

Ekmek verip beslemiştik onları, 

Unutmayız arka çıkan jonları, 

Ermeniye akan banka fonları, 

Ermeni değil mi vuran Türk-meni? 

Rahmi derki: bak hele bir maziye, 

Bin yetmiş bir den mi çıksak geziye, 

Tartmak için koyarsak teraziye, 

Ermeni değil mi vuran TÜRKMEN’i?', 'Kaldıya milletler suskun bir zaman,  Kar bastı her yanı vermedi aman,  Ermeni zulmüyse soğuktan yaman,  Ermeni değil mi vuran Türk-meni?  İn...', ARRAY['Türk Edebiyatı','Şiir','Rahmi Kenger']::text[], 8.5, '{"poet":"Rahmi Kenger","poet_slug":"rahmi-kenger","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/turk-meni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günahların Yakılışı', 'gunahlarin-yakilisi-firat-caliskan-055l3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Önce sıcaklığı dokunur tenine				

Tutuşur her bir mektup, her bir satır duygu				

Her bir gözyaşı harlar ateşi					

Ortalıkta bir alev sarısı, kahpemsi					

Gözlerinde bir parlaklık oluşur					

Kulaklarında günahların sesi					

Yıldızlar ay ve karanlık tutuşur					

Bu bir yangın gecesi ne yapsan söndüremezsin', 'Önce sıcaklığı dokunur tenine				 Tutuşur her bir mektup, her bir satır duygu				 Her bir gözyaşı harlar ateşi					 Ortalıkta bir alev sarıs...', ARRAY['Türk Edebiyatı','Şiir','Fırat Çalışkan']::text[], 8.5, '{"poet":"Fırat Çalışkan","poet_slug":"firat-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gunahlarin-yakilisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir', 'siir-serkan-karabulut-vmzrt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'yüreğini ellerine alınca yaz durmadan

ve sen olan kendini bilen bir kalem ol

konuşmalar bitince susma 

işte fırsattır konuşamaz dile inat yazmak', 'yüreğini ellerine alınca yaz durmadan ve sen olan kendini bilen bir kalem ol konuşmalar bitince susma  işte fırsattır konuşamaz dile inat ya...', ARRAY['Türk Edebiyatı','Şiir','Serkan Karabulut']::text[], 8.5, '{"poet":"Serkan Karabulut","poet_slug":"serkan-karabulut","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/siir-158-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz Kalmadı', 'biz-kalmadi-sennur-cetin-5enlh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne kadar sevsemde yokki yararı

Benim hayatıma hep oldu zararı

Gönlümün ne çare doğru kararı

İçimde artık biz kalmadı

Dağıtmak istiyorum kalbimdeki hüznü

Unutmak istiyorum ellerini yüzünü

Kayboldu içimde yaşanmadan güzellikler

İçimde artık biz kalmadı

Hayat acıyla, kederle, ayrılıkla değil

Paylaşılan aşkla,sevgiyle güzel

Senin gönlün seçimini yaptı

Yazıklar olsun vefasız aşkına

İçimde artık biz kalmadı

26.07.2004', 'Ne kadar sevsemde yokki yararı Benim hayatıma hep oldu zararı Gönlümün ne çare doğru kararı İçimde artık biz kalmadı Dağıtmak istiyorum kalb...', ARRAY['Türk Edebiyatı','Şiir','Sennur Çetin']::text[], 8.5, '{"poet":"Sennur Çetin","poet_slug":"sennur-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/biz-kalmadi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmem kaç senem daha var dünyalık', 'bilmem-kac-senem-daha-var-dunyalik-serkan-karabulut-d6aqe', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Büyütüyorum içimde git gide,

Küllerinden var ediyorum.

Binlerce doğuyor çoğalıyorsun

Yaşatıyorum ne pahasına olursa olsun.

İlhamım sen ve benim inancım

Saldım semaya aşkımı

Yüksele dursun.

Yüzüyorum, fersah fersah dehlizlerinde.

Sınırı yok ki, nereye gidersen git.

Seninleyim.

Hayal gücüm inancım buna müsait

Kavuşacağım bu mahşerde de olsa,

Dünya haliydi ölüm.

Sonsuzluk var ilerde,

Benim için,

Sana kavuşmak için,

Bilmem kaç senem daha var dünyalık.', 'Büyütüyorum içimde git gide, Küllerinden var ediyorum. Binlerce doğuyor çoğalıyorsun Yaşatıyorum ne pahasına olursa olsun. İlhamım sen ve be...', ARRAY['Türk Edebiyatı','Şiir','Serkan Karabulut']::text[], 8.5, '{"poet":"Serkan Karabulut","poet_slug":"serkan-karabulut","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bilmem-kac-senem-daha-var-dunyalik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şükür', 'sukur-firat-caliskan-juvq5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözyaşına kurban etmiştim					

Tüm hayallerimi sırf akmasınlar diye				

Ve gülümsemelerine endekslemiştim tüm sevinçlerimi			

Yağan yağmurun gülün yapraklarında					

bıraktığı bir çiğ damlası güzelliğindeydi bakışlarındaki sır			

Seni bana bağışlayana						

ve korkusuzca seni sevmek için bana bu duyguyu verene		

O muhteşem kalbinin benim için atmasına izin veren 			

Yüce Allaha şükürler olsun							                                                                                                                 (Keşke bukadar değerli olduğunu bilseydin.)', 'Gözyaşına kurban etmiştim					 Tüm hayallerimi sırf akmasınlar diye				 Ve gülümsemelerine endekslemiştim tüm sevinçlerimi			 Yağan yağmurun...', ARRAY['Türk Edebiyatı','Şiir','Fırat Çalışkan']::text[], 8.5, '{"poet":"Fırat Çalışkan","poet_slug":"firat-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sukur-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boğuşmak', 'bogusmak-abdullah-gultekin-g5slj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Varlığın acı veriyor

Yokluğun ızdırap

İçimde fırtınalar kopuyor

Sana geliyor benliğim istemeden

Dom dom kurşunu gibi saplandın kalbime

Hiçbir hekim yanaşmadı deşmeye

Bu kurşunla razıysam eğer ölmeye

Tutar mısın elimden dalarsam rüyalara

Ben bal arısı sende gül olsan

Ben toprak olsam sende yağmur

Her halükarda sana ihtiyaç duysam

Bana da verir misin bir parçacık kendinden', 'Varlığın acı veriyor Yokluğun ızdırap İçimde fırtınalar kopuyor Sana geliyor benliğim istemeden Dom dom kurşunu gibi saplandın kalbime Hiçbi...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Gültekin']::text[], 8.5, '{"poet":"Abdullah Gültekin","poet_slug":"abdullah-gultekin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bogusmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasıl Olsa', 'nasil-olsa-nurten-altinok-4f4p6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bahar geldi 

Ondan mıdır havalanması güvercinlerin 

Kalpler arasında 

Ulak misali 

Sakın boş verme 

Tut kulağından birini 

Dök içindeki baharı gözlerine

Yaşam 

Yaşanacak kadar uzun 

Sevecek kadar kısa 

Her zaman çıkmıyor adamın karşısına 

''''aha bu '''' diyebileceğimiz sevda 

Bırak atsın taklasını 

Taklacı güvercinlerin 

Her şeyin sonu 

Toprak 

Nasıl olsa 



Sevgili Naci Kasapoğlu’nun  Tak Tak ‘ına...', 'Bahar geldi  Ondan mıdır havalanması güvercinlerin  Kalpler arasında  Ulak misali  Sakın boş verme  Tut kulağından birini  Dök içindeki baha...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/nasil-olsa-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '! .Şiirimin göZü yollaRda..!', 'siirimin-gozu-yollarda-dilek-egri-rh9zs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '''..bir hasret geldi ki birtürlü gitmiyor...! ''

gel memleket gözlüm

toprağım çam ormanlarım

ciğerlerime aşk üfle

yüzünün yaylasında serinleyim

sonra ört üstümü kendinle

saçlarımı savurt nefesinle

aman sevgilim

yavaş...

bana hayaller kurduran buselerini gönderme..! 

gel yastığımın bir köşesini ayırdığım adamım..

gel de rötüşlü uykularımı uyandır

ardından gözlerine dalayım

sesin ninnilerim olsun

ve sonra sabah...

ben senin varlığınla aydınlanayım

bahar mazeretin olsun

cemreleri bavuluna koy gel..

ben giydim çiçekli elbisemi

saçlarımda gökkuşağı..

içimdeki küçük kız hayallerimi uçuruyor..

sen seni de al gel.

bildiğin gibi değil; 

''..bir sevmek geldi ki birtürlü gitmiyor..! ''

27/03/06', '''..bir hasret geldi ki birtürlü gitmiyor...! '' gel memleket gözlüm toprağım çam ormanlarım ciğerlerime aşk üfle yüzünün yaylasında serinleyi...', ARRAY['Türk Edebiyatı','Şiir','Dilek Eğri']::text[], 8.5, '{"poet":"Dilek Eğri","poet_slug":"dilek-egri","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/siirimin-gozu-yollarda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Bana Yaramıyor', 'askin-bana-yaramiyor-erdal-ozkan-mvt5h', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Uzaklarda kal güzelim 

Aşkın bana yaramıyor

İstersen hiç geri dönme

Gönlüm seni aramıyor

Bir zamanlar yanımdaydın

Herşeyimi benden aldın

Şimdi boynu bükük kaldım

Aşkın bana yaramıyor

Razıyım bu yalnızlığa

Alıştım ben ayrılığa

Git buradan çok uzağa

Gönlüm seni aramıyor

Peşindeydim adım adım

Bir an seni bırakmazdım

Fakat mutlu olamadım

Aşkın bana yaramıyor

Kalbimde kalan yarasın

Yaşanmış bir hatırasın

İsterim mutlu olasın

Gönlüm seni aramıyor.', 'Uzaklarda kal güzelim  Aşkın bana yaramıyor İstersen hiç geri dönme Gönlüm seni aramıyor Bir zamanlar yanımdaydın Herşeyimi benden aldın Şim...', ARRAY['Türk Edebiyatı','Şiir','Erdal Özkan']::text[], 8.5, '{"poet":"Erdal Özkan","poet_slug":"erdal-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/askin-bana-yaramiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbette Özlem', 'gurbette-ozlem-canan-karadeniz-0tmi6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Özlem gözlerimden akıyor 

Tazyikli bir su gibi

Titrek sesimle türkümü söylerim

Gökyüzünde ararım kokusu duyulmaz topraklarımın

Ninnisi yüreğimdedir yaşlı anamın

Bu kalabalık şehir yorar

Yabancıdır çehreler yalnızlığın pençesinde

Gitmenin vakti uzun,

Özlemin vakti yanıbaşımda bekler.

Bu gri, soğuk, karanlık şehirde', 'Özlem gözlerimden akıyor  Tazyikli bir su gibi Titrek sesimle türkümü söylerim Gökyüzünde ararım kokusu duyulmaz topraklarımın Ninnisi yüreğ...', ARRAY['Türk Edebiyatı','Şiir','Canan Karadeniz']::text[], 8.5, '{"poet":"Canan Karadeniz","poet_slug":"canan-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gurbette-ozlem-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzünlü bir sonbahar günü', 'huzunlu-bir-sonbahar-gunu-canan-karadeniz-c6c74', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yapraklar mutlu toprağa düşmekten

Rüzgar umutlu agaçları savurmaktan

Ruhlar süzgün, gözler yaşlı

Hüznün melodisinden.

Dalgalar kayalıkların davetinde

Yosunların kokusu yakın,

Yağmurun neşeli yağışından.

Ahmaklaşır kimi zaman

Bedenlere düşerken,

Geçmişi anımsar dalarız

Damlaların arasında

Titrek ellerimizin içi dolar,

Yağmurun dansıyla

Dağılır düşünceler oradan oraya

Pencere önüne düşen,

Her damlada aranır sevgi,

Sorulur hüznün sonrası,

Beklenir,

Gökyüzünden parlayacak güneşin pırıltısı

Umut kıpırıtısı güneşte saklıdır

Gülücükleri içinde biriktirir

Her parlayışta dağıtır

Çimenlerin üzerine,

Uçsuz maviliğin derinliğine

Yeşil dağlara bırakır

Saklı bir hazine gibi', 'Yapraklar mutlu toprağa düşmekten Rüzgar umutlu agaçları savurmaktan Ruhlar süzgün, gözler yaşlı Hüznün melodisinden. Dalgalar kayalıkların ...', ARRAY['Türk Edebiyatı','Şiir','Canan Karadeniz']::text[], 8.5, '{"poet":"Canan Karadeniz","poet_slug":"canan-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/huzunlu-bir-sonbahar-gunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kar ayazı vuruyor beyaz yüzüne', 'kar-ayazi-vuruyor-beyaz-yuzune-canan-karadeniz-76tum', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kar ayazı vuruyor beyaz yüzüne

İncecik bedeni titrerken soğuktan

Yüreğindeki o ışıkla ayakta duruyor

Tek bir kibrit satabilmek uğruna

Mevsim aldırmadan küçük bedene

Tüm ağırlığıyla üzerine çökerken

Morarmış elleriyle yaşarken acıyı

Kısık sesiyle kibrit diye seslenmekte', 'Kar ayazı vuruyor beyaz yüzüne İncecik bedeni titrerken soğuktan Yüreğindeki o ışıkla ayakta duruyor Tek bir kibrit satabilmek uğruna Mevsim...', ARRAY['Türk Edebiyatı','Şiir','Canan Karadeniz']::text[], 8.5, '{"poet":"Canan Karadeniz","poet_slug":"canan-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kar-ayazi-vuruyor-beyaz-yuzune-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benmişim', 'benmisim-zeynal-yaman-1ew2h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sahralarda esatiri ararken

Bir de baktım sahralarda benmişim

Mecnun''dan bir yüce aşkı sorarken

Bir de baktım aşk deryası benmişim

Serap olmaz sevenlerin gözünde

Sevda yatar ariflerin özünde

Su afak şu semavatın yüzünde

Gezen bulut yağan yağmur benmişim

Dizi dizi sonsuza uçar kuşlar

Aşıklara düz olur sarp yokuşlar

Viraneye ağıt yakar baykuşlar

Gülzarda şakıyan bülbül benmişim

Dil zorlanır âşık hâlin demeğe

Mekân yetmez gönüldeki dileğe

İmrenirken günah bilmez meleğe

Meğer âlemlere sultan benmişim

Zeynel''im aşkla yıkadım kalbimi

Çiğneye çiğneye aştım bendimi

Hakk''ın kollarına attım kendimi

Meğer O''nsuz hiç O''nla güç benmişim

1990-Çatalca', 'Sahralarda esatiri ararken Bir de baktım sahralarda benmişim Mecnun''dan bir yüce aşkı sorarken Bir de baktım aşk deryası benmişim Serap olma...', ARRAY['Türk Edebiyatı','Şiir','Zeynal Yaman']::text[], 8.5, '{"poet":"Zeynal Yaman","poet_slug":"zeynal-yaman","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/benmisim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akıcı Yoğun İstanbul Akşamı', 'akici-yogun-i-stanbul-aksami-suleyman-eser-qjuo3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Toplamda bir kasım akşamıydı

Gençliğimle tanıştım kahve köşelerinde

Dikte edilmiş hayaller arka cebimde

Ya bir Moda yangınında yokluk bendeki

Ya karanlıkta adını duymak kaderin

Halini anlatamayan arzuhal elimdeki

Dalmışım manzarasına Üsküdar adliyesinin

Ben öylesine gelmiştim İstanbul’a

Bilemezdim bu kadar salgın olduğunu

Çelişkilerden bile o çıktı

Öylesine vurulmuştum belki de

Manolya kokulu nefesine karışabilmek için

Fakat şimdi ölesiye seviyorum

Nişane verdim ellerine Azrail’in

“beni Salacak’ta al” diye

Biliyorum elbet bir gün alacak

Sehersiz geceler şehri burası

Geç vakte kalamam hikayem uzun

Kim gidecek belli değil kim kalacak

Öylesine gelmiştim İstanbul’a

Hani şiirler yazılır ya kendisine

Belki bende söylenirdim içinde

Yazık! medya kokan yakut akşamlarında

Karaköy’de işporta tezgahlarına düştüm

Bir alt geçidi mesken tuttum kendime

Boynumda yağlı ipe bağlı

Vazifesini icra edemeyen bir cevşen

Yine sağır isyanlarıma Topkapı

Ve sevgililerimi cebimde taşıyorum

Kesip ucuz magazin dergilerinden

Bab-ı Ali’de bir yüce makam

Buse kondurdum ellerine derinden saygılı

Açık kapılar kapandı sevdama

Ayasofya Kapalıçarşı arası

Ayak üstü maskot oldum ecnebi çocuğa

İlgili makamlarla paylaşamadım asla

Kandilli’de yağmur kokan akşamları

Ben öylesine gelmiştim İstanbul’a

Hani hep güzellikleri dillerde dolanır

Manzara denilince akla gelir ya

Bir ev iki ağaç bir kaç martı

Ve tüm bunları kucaklayan bir derya

Öyle gelirdi bana Beyoğlu sokakları

Ve Göksu’da lale devrine karışmanın aşkı

Yazık! İşporta tezgahına düştüm bu akşam

Şişli Mecidiyeköy güzergahında

Geleceğimle tanıştım bir köşede

Ellerimi açmışım yedi kat semaya

“Allah rızası için bir ekmek parası”

Şişli Camii yanı başımda kale gibi

Ben yaslamışım soğuk betona sırtımı

Beykoz’un yeşil koruları içinde

Meltem esintileri aldı geçmişimi

Denizin mavisi işlendi kapılara

Ben karton topladım dükkanlardan

Manzaralar çizildi okul duvarlarına

Ben ayakkabı boyadım Aksaray’da

Hayal satıldı Bostancı’da açık artırmayla

Nargileler çekildi Sultan Ahmet’te

Acı kahveler içildi Çınaraltı’nda

Bir damla yağmura hasret

Metruk arsaların kuytu köşelerinde

Filizlenen hayallerimle boğuştum

Sehersiz geceler şehri İstanbul

Gecelere kalamam hayallerim yoğun

Toplamda bir kasım akşamıydı

Ne Beyoğlu’nda görünmüşüm

O akşam ne uğramışım meskenime

Tamahkâr ellerimde bir tutam saç

Ve ben vefasız ellere

Kanunsuz bünyelere muhtaç

Karla karışık sokak lambaları altında

Bulunmuşum bir köşe başında

On yedi yerimden yaralı

Salacak sahilinin havası bile

Çare olmamış sargısız derdime

Allı yeşilli morlu ve derinden karalı

Bir tutam saç cansız ellerimde

Yolmuşum saçını Kızkulesi’nin

Acıyla karışık ve ölümüne sevdalı

Martılara selam durmuşum pervasız

Rengini sayıyorum gölgelerinin

Uçuk kaçık bir Taksim havası

Ben çok yorgunum bu akşam

Aklımda İstiklal kalabalığı

Kucağımda tomurcuk hayallerim

Akıcı yoğun bir köprü trafiği

Ellerimde Kızkulesi’nin saçları

Yatıyorum Salacak sahilinde

On yedi yerimden yaralı

24.03.2006

-KTHY-', 'Toplamda bir kasım akşamıydı Gençliğimle tanıştım kahve köşelerinde Dikte edilmiş hayaller arka cebimde Ya bir Moda yangınında yokluk bendek...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Eser']::text[], 8.5, '{"poet":"Süleyman Eser","poet_slug":"suleyman-eser","theme":"Türk Şiiri","is_hero":false,"total_lines":92,"source_url":"https://www.antoloji.com/akici-yogun-istanbul-aksami-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülmezdi', 'gulmezdi-zeynal-yaman-5zdoj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gönlümün gördüğünü bir kez görseydi gözler

Gitmesin diye hayâli bir ömür görmezdi

Sıyırıp ar perdesini soymasaydı yüzler

Hayâ eder de Mevla''dan bir ömür gülmezdi

1987-Çatalca', 'Gönlümün gördüğünü bir kez görseydi gözler Gitmesin diye hayâli bir ömür görmezdi Sıyırıp ar perdesini soymasaydı yüzler Hayâ eder de Mevla''...', ARRAY['Türk Edebiyatı','Şiir','Zeynal Yaman']::text[], 8.5, '{"poet":"Zeynal Yaman","poet_slug":"zeynal-yaman","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/gulmezdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostlar Yarın Kütahyadayım', 'dostlar-yarin-kutahyadayim-mehmet-akif-gulhan-dmr7q', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '28.03.2006 da akşam üzeri kütahyada olacağım 

Sohbet ve tanışmak için 

Adres

Saadettin camii civarı''Eğmir Mermercilik''

Harika bir şark köşesi var ve tabii doyumsuz sohbet

Beklerim efendim

TEL 0274 212 44 07 Lütfen not bırakınız

Akif Dede 

Kale bedenine vardım,hoş bir sada gelir. 

Arif olmuş bir ceddim,ziyareti eda gelir. 

Aç huşu ile ellerin göğe,kapa gözün, 

Kulağına, erenlerin na’t-ı şerif gelir. 

Kesme ümidini ademden,dedem 

Azab-ı nar’a gelsin isteme,sabır, 

Ceddin pak eylemiş yüce Yaradan 

Ardından pak-i zürriyetin gelir 

Boş zan eyleme Ademi kesme ümit 

Boş kamışa benzese de,ruhunu üflemiş, 

Yaradan lutfederse,boş kamıştan, 

Suzidil ile Suzinak makam gelir 

Hastayız yanıyor gönül,sür mesini 

Gönül aşk ile iman ile ayara gelir 

Kapalıdır gözümüz,sür meshini 

Açılır,dünya halinden,arşı aleme gelir. 

Edeb ile huzura vardık,sor nesin,kimsin 

Merdane eyle post olalım,ayağın tozuna, 

Erenler evliyalar meclisinde,bedenimiz 

Postun üzerinde bir dem kıla denk gelir. 

Çille-i merdani bitmez 1001gün ile 

Çille-i merdani bitmedi bir gün bile 

Edebin,hayanın sükut ettiği yerde 

Her erdem üzerinde Ali Nusret gelir. 

İstanbuldan Kütahyaya,selam gelir, 

Asırlar evvelinden,Zehradan Eminden gelir 

Senin cemaline kurban,cemaat-i ihvan 

Her dem,karşımızdasın gibi Sabahat’in gelir 

Ahiret bir odadır,birini bırakıp birine geçilecek 

İman sahibi,korkmaz,göğsün açar gelir. 

Kur sema-ı bize,tennuremiz hazır beklesin, 

Ardından Mustafa,Muhammet Akif’ler gelir. 

19 Mayıs 2004 

Mana 

Beden-sur 

Sada-ses 

Arif-Hakkı hakkı ile bilen 

Cedd-babanın babası veya ananın babası 

Eda-anmak,hatırlamak 

Huşu-yüksek huzurda,edepli hal 

Na’t-ı şerif-Hz.Mevlana’nın Peygamberimize methiyesi 

Nar-ateş 

Pak-temiz 

Zürriyet-nesil 

Ney-nefesli bir saz 

Mesh-ayağa giyilen deriden içlik 

Nusrat-Cenab-ı Hakkın yardımı(Nusret)  babamızın ismi 

İhvan-aynı cemaate,tarikata mensuplar 

Cemal-kişideki güzellik,hak ile söylenen doğru söz 

Sabahat-güzel yüz 

Tennure-sema için özel giysi 

Mehmet Akif Gülhan', '28.03.2006 da akşam üzeri kütahyada olacağım  Sohbet ve tanışmak için  Adres Saadettin camii civarı''Eğmir Mermercilik'' Harika bir şark köşes...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Gülhan']::text[], 8.5, '{"poet":"Mehmet Akif Gülhan","poet_slug":"mehmet-akif-gulhan","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/dostlar-yarin-kutahyadayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldızlı şiirler* 06 / Şimdi', 'yildizli-siirler-06-simdi-nurten-altinok-xknrg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yağmurlarına yükledim 

Tutup gözlerinden

Bir İstanbul sabahına

Sesini

Umarsızca ve de sorumsuz 

Şemsiyesizim

Islanıyorum mevsinlerinde

Şimdi...', 'Yağmurlarına yükledim  Tutup gözlerinden Bir İstanbul sabahına Sesini Umarsızca ve de sorumsuz  Şemsiyesizim Islanıyorum mevsinlerinde Şimdi...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yildizli-siirler-06-simdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Çocuk', 'ey-cocuk-zeynal-yaman-42za5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ağlama ey çocuk! 

Nedir mavi gözlerinden akan şu yaşlar? 

Yoksa, söyle! Bu yaşta mı kalp atışı başlar? 

Daha çok küçücüksün

Dayanamazsın bu acıya

Nedir şu yanaklarından süzülen yaşlar? 

Yoksa bu yaşta mı kalp atışı başlar? 

Hicranın mı büyük? 

Bağrın mı yanık? 

Nedir bu yıkık kaşlar? 

Yoksa bu yaşta mı kalp atışı başlar? 

Sevdalı mısın birine? 

Gözlerin pek gamlı bakıyor

Ya şu kanlı yaşlar...

Yoksa bu yaşta mı kalp atışı başlar? 

1984-Ordu', 'Ağlama ey çocuk!  Nedir mavi gözlerinden akan şu yaşlar?  Yoksa, söyle! Bu yaşta mı kalp atışı başlar?  Daha çok küçücüksün Dayanamazsın bu ...', ARRAY['Türk Edebiyatı','Şiir','Zeynal Yaman']::text[], 8.5, '{"poet":"Zeynal Yaman","poet_slug":"zeynal-yaman","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ey-cocuk-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sansın İsterdim', 'sansin-i-sterdim-sadik-softa-tyvku', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bütün sokaklara adını verip,

Bu şehir adını ansın isterdim.

Bütün caddeleri senle yürüyüp,

Caddeler kokuna kansın isterdim.

En büyük caddeden bütün şehire,

Yayılsın gülüşün, duysun yerküre,

Sevgi vicdanlarda olsun mefkure,

Yüreğim seninle yansın isterdim.

Bütün sevdalılar aynı sihirde,

Seninle anılsın sevda şehirde,

Mecnun’u, Leyla’yı unutup birde,

Bütün cihan seni ansın isterdim.

Bütün çiçeklerin gülüşü sen ol,

Sevdanın mimarı, buluşu sen ol,

Bu şehrin kimliği, duruşu sen ol,

Herkes bu kimliği bilsin isterdim.

Paha biçilmesin bir bakışına,

Kutsal eller gibi yakarışına,

Gülüşüne çiçek, gül takışına,

Bülbül buketten gül sansın isterdim.

Bütün sokaklara adını verip,

Hasreti bitirip, vuslata varıp,

Bir ömrü, bu canı yoluna serip,

Ruhum o sevdana kansın isterdim. 

Çankırı-28.06.2005', 'Bütün sokaklara adını verip, Bu şehir adını ansın isterdim. Bütün caddeleri senle yürüyüp, Caddeler kokuna kansın isterdim. En büyük caddede...', ARRAY['Türk Edebiyatı','Şiir','Sadık Softa']::text[], 8.5, '{"poet":"Sadık Softa","poet_slug":"sadik-softa","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sansin-isterdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıyama Durmalı', 'kiyama-durmali-sahabeddin-erzurumluoglu-o7ovu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Günahım affeder isterse eğer,

Kutsaldır kitabım her şeye değer,

Mümin iki cihan şanlıymış meğer,

Kıyama durmalı, miraçtır namaz..

Geceleri zikre alışmak lazım,

Sadık dostlar ile çalışmak lazım,

Allah’ı bilene danışmak lazım,

Kıyama durmalı, miraçtır namaz..

Sen Allah deyince yürekler çağlar,

Kabe’nin yolunda engeldir dağlar,

Muhammed ümmeti nedendir ağlar,

Kıyama durmalı, miraçtır namaz..

Kavgalı Dünya’da oldum süzülen,

Sevip sevilenin hepsi üzülen,

Gaddar zalimlerin topudur gülen,

Kıyama durmalı, miraçtır namaz..

Hu der devran eder aşka eremez,

Nice firavunlar cevap veremez,

Güzel vatanımı kimse geremez,

Kıyama durmalı, miraçtır namaz…', 'Günahım affeder isterse eğer, Kutsaldır kitabım her şeye değer, Mümin iki cihan şanlıymış meğer, Kıyama durmalı, miraçtır namaz.. Geceleri z...', ARRAY['Türk Edebiyatı','Şiir','Şahabeddin Erzurumluoğlu']::text[], 8.5, '{"poet":"Şahabeddin Erzurumluoğlu","poet_slug":"sahabeddin-erzurumluoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kiyama-durmali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ooooof of!', 'ooooof-of-ugur-deniz-ulkegul-5p9ti', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yosma hayaller sakla koynunda

Belki dönerim bir gün

Sana el bana bir ömre bedel şehrin

Bela kokan kuytusunda

Sen bana mahpus ben sana sürgün…

Hatırla sana verdiğim gül’ü

Nasıl da nemlenmişti gözün

Solduğu gün nasıl da ağlamıştın

Dalından düşen son yaprağında

Avuçlarına battıkça hüzün…..

Bekle beni zamansız sorgularında

Belli olmaz bakarsın gelirim

Bir serserinin bıçak sırtı öfkesi

Hani bulmaz beni kör bir kurşun adresi

Sağ kalırsa sen yanım, belki dönebilirim…

Sevemedim senden başkasını

Ne yardan ne serden geçebilirim

Kavline sadık suçlu bileşkem

Yüreğimde saklı duran kelepçem

Kırıp zincirlerini bir gün, sökebilirim….

Üzülme iklimler soğudu diye

Hazan mevsimlerine aldanma sakın

Geçer bunlar kapanır en derin yara

Savur sen saçlarını deli rüzgara

Kopan bir yaprak gibi avuçlarına, düşebilirim…

Yosma hayaller sakla koynunda

En serseri halimle gelebilirim….

Açarsın kapıyı korkulu ürkek

Titrek bir merhabaya dolar yüreğin

Sensizliğin yüzüne küfrederek

O gün gözlerine, gülebilirim....', 'Yosma hayaller sakla koynunda Belki dönerim bir gün Sana el bana bir ömre bedel şehrin Bela kokan kuytusunda Sen bana mahpus ben sana sürgün...', ARRAY['Türk Edebiyatı','Şiir','Uğur Deniz Ülkegül']::text[], 8.5, '{"poet":"Uğur Deniz Ülkegül","poet_slug":"ugur-deniz-ulkegul","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/ooooof-of-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşüm', 'dusum-canan-karadeniz-etqir', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kapının çalınışıyla irkildi

Sessizliği bozan

Kulağını tırmalayan o sese

Yöneldiği anda kalbi yerinden fırlayacaktı

Beklemediği, ummadığı

Yinede geldiyse diyerek

Nefesini tutarak koştuğu kapının yanına

Açıp açmamakta tereddüt etti.

Korku ve heyecanı tüm bedeninde hissederken

Düğümlenen boğazı kurumuştu.

Senaryolar aklından ışık hızıyla geçiyordu.

Ya görecekti.Yada sonsuza dek unutacaktı.

Unutmakmı,

Fikri bile çıldırtmaya yetiyorken

Çözüm üretemiyordu yüreği

Anlamsızdı gidiş

Giden gelmişmiydi hiç

Biten başlarmıydı

Kaçan kurtuluşu yakalamışmıydı

Tutku peşinden ayrılmamıştı.

Kalbine gömmeyi reddederken

Mezar taşına adı yazılmıştı bile

Kabullenmek değil, dönmesini uzaklardan gelip sımsıkı

sarılmasını istiyordu.

Aslında kapının çalındığıda yoktu.

Hayal denizinde uzun bir yolculuğa çıkmıştı.

Dalgalardan sarhoş olup, martılarla ağlayıp

Yunuslarla yarışıyordu gidenin yanına ulaşmak çabasına

Gözlerini açtığında görebildiği avuçlarına dolan 

gözyaşlarıydı.Sevgisi oradan sesleniyordu

Haykırıyordu 

Üzülme, üzülme

Bedenim yok ama 

Ruhum kalbinde unutma diyen

Yaşlardı geriye kalan gecenin yarısında', 'Kapının çalınışıyla irkildi Sessizliği bozan Kulağını tırmalayan o sese Yöneldiği anda kalbi yerinden fırlayacaktı Beklemediği, ummadığı Yin...', ARRAY['Türk Edebiyatı','Şiir','Canan Karadeniz']::text[], 8.5, '{"poet":"Canan Karadeniz","poet_slug":"canan-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/dusum-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aldanış', 'aldanis-nurten-tarim-e1ukn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kaldırımda saçı sakalı karışmış bir adam

Yüreğine inen göz yaşlarıyla sırılsıklam

Duygu denizinde boğulmuş

Bilinçsiz boş bakışlar

Yaşamın karışıklığını onaylar

Kendi karanlığında dışlanmışlığınla yürüdü

Yargılayan saatler uzun

Sessizce bir banka oturdu

Yok olmak istercesine büzüldü

Yırtık çeketine saklanmak istedi

Yaktı bir sigara

Dumanı uzun uzun çekti içine

Bu alem nasıl soldurmuştu benliğini

Bedelini kim bilir kimler ödemişti

Kendi adına

Elindeki sigaradan son nefes çekti.

Kararlı adımlarla yürüdü ıslak kaldırımında

Kulakları sağır eden raks müzikleri

Utandıran tenini saran yasak aşkları

Bozulan düzenini temizlercesine

Benliğinden özür diledi

Titredi birden

Belki ilk kez doğru karar verdi

Adımları geçmişe doğru gitmeye başladı

Yıllar öncesi bıraktığı tertemiz dünyasına

Cezbetmiyordu artık hiç birşey

Ne kırmızı karanfil nede beyaz gül

Geçmişte bıraktığı son temiz nokta

Ulaşmak için koşarken ıslak kaldırıma

Çarptı koca bir kamyon

Hasta cılız bedenine', 'Kaldırımda saçı sakalı karışmış bir adam Yüreğine inen göz yaşlarıyla sırılsıklam Duygu denizinde boğulmuş Bilinçsiz boş bakışlar Yaşamın ka...', ARRAY['Türk Edebiyatı','Şiir','Nurten Tarım']::text[], 8.5, '{"poet":"Nurten Tarım","poet_slug":"nurten-tarim","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/aldanis-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gördün Acımadılar', 'gordun-acimadilar-yusuf-onder-bahceci-7yqf5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen gözlerine bakmaya kıyamazken,

Sen, seni seviyorum be, diyemezken,

Sen ona, asla, asla, ihanet etmezken,

Sana nasıl kıydılar, gördün acımadılar.

Dünya''da acımasız mı olmak gerekir,

Sevdiğini incitmeyen kendi mi incinir,

Bilsem gözlerine bakarmıydım, denir,

Sana nasıl kıydılar, gördün acımadılar.', 'Sen gözlerine bakmaya kıyamazken, Sen, seni seviyorum be, diyemezken, Sen ona, asla, asla, ihanet etmezken, Sana nasıl kıydılar, gördün acım...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gordun-acimadilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arayış', 'arayis-bilal-konal-x90qn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gönlüm arayışta

Rahmeti uman yolculukta

Gözlerim kapalı

Ayaklarım hep yolda

Ellerim boşlukta

Bir el tutar ellerimi

                                         Belki

Sesler yankılanır yüreğimde

Hayalleri canlanır zihnimde

Bir an olsun duramam yine

Omzuma bir el değecek diye

                                          Belki de

Rüzgar hafifçe eser

Sırrını yavaşça söyler

Kanatların var mı der

                                          Kimbilir

Bir kuş gelir Yesrib''den

Haber verir Sevgili''den

Gönül yeşerirse yeniden

Bir gül kopar yüreğimden

                                          Rabbime

Seherde açılan elden

Yaşlar süzülen gözden

Günahsız tertemiz dilden

Dua edilirse gönülden', 'Gönlüm arayışta Rahmeti uman yolculukta Gözlerim kapalı Ayaklarım hep yolda Ellerim boşlukta Bir el tutar ellerimi                          ...', ARRAY['Türk Edebiyatı','Şiir','Bilal Konal']::text[], 8.5, '{"poet":"Bilal Konal","poet_slug":"bilal-konal","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/arayis-110-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Zafer Andı', 'askin-zafer-andi-baris-aluk-j0n20', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '.................Titrek bir mum alevinin havaya bıraktığı bulanık bir is

.................ve göz gözü görmez bir sis değildik biz...

.................beni bilimle anla iki gözüm, felsefeyle anla

.................ve tarihle yargıla...(A.Kaya)

Kaynama noktasındayız şimdi

Tenimizi yakan ayaza rağmen

Bizde buz kaldı mı? 

Sis değil bu gördüğün

............................yanıyoruz! 

Oy canıma can olan

.................çorağıma gül açan

........................ayaza bırakma ellerimi...

Karasında durdum saçlarının

Kibriti dudaklarında çaktım

Hiç üşür müyüm nefesin yüzümdeyken? 

Soğuktan değil bu titreme

..............................biz oluyoruz! 

Oy içimde güneş olan

....................şarabıma tat veren

...........................ayırma nefesini dudaklarımdan...

Yıkıldı bütün duvarlar

Deprem şiddetinde sarsıldı tarih

Ben hiç ölür müyüm sendeyken? 

Korku değil içimize doğan

.............................ant içiyoruz! 

Oy dağlarımda isyan olan

.................kavgama cesaret veren

............................düşürme beni sensizliğe...

Kızıl bir çiçek açtı ülkemin yeşiline

Biz başlatmadık kavgayı gülüm

Boyun eğmek olur mu zalimin oyununa? 

Boşuna değil göğsümüzde kalplerimizin çırpınışı

..................................................................kazanıyoruz! 

Oy varlığıma sebep olan

..............direncime güç veren

..................................diğer yarım

.............................................sevdam

.................................................sevgilim

.......................................................çözme kollarını benden! 

(27.03.2006)    Beyoğlu', '.................Titrek bir mum alevinin havaya bıraktığı bulanık bir is .................ve göz gözü görmez bir sis değildik biz... ..........', ARRAY['Türk Edebiyatı','Şiir','Barış Aluk']::text[], 8.5, '{"poet":"Barış Aluk","poet_slug":"baris-aluk","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/askin-zafer-andi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anla Artık Gönlüm', 'anla-artik-gonlum-ugur-benek-cst1z', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tarifi imkansız bir doğumdur ölüm.

Kimi bir kere ölür,kimi bin kere.

Ne topraktan anlar,ne hesaptan gönlüm,

Düşmeden hayat yolunda gerçeklerine.

Bedenim yerdeki topraktan ibaret,

Niye hala büyüklenirsin kendince? 

Allah için toprağa bile iman et.

Nur saçar Kur''an,sağına verilince.

Hayallerle niye geçirirsin zaman? 

Bu cihanda çıkmayı isteme tahta.

Anlarsın dediğimi gelince o an,

Görünce bir gün üstünde dokuz tahta.

(Dokuz tahta: Mezarda,ölünün üstüne dokuz tahta konur ve üstüne öyle toprak atılır.)  

(27 Mart 2006 - 16:45)', 'Tarifi imkansız bir doğumdur ölüm. Kimi bir kere ölür,kimi bin kere. Ne topraktan anlar,ne hesaptan gönlüm, Düşmeden hayat yolunda gerçekler...', ARRAY['Türk Edebiyatı','Şiir','Uğur Benek']::text[], 8.5, '{"poet":"Uğur Benek","poet_slug":"ugur-benek","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/anla-artik-gonlum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerine Dolan Gülümsemeler', 'gozlerine-dolan-gulumsemeler-murat-tali-2z7zv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'eyy güzel insan, 

kaç parmağın var, 

gülüşünün hacmi ne kadardır, 

gözyaşlarının ağırlığı ölçülebilir mi? 

Attığın adımlara kapılıp gelen gölgenin ulaşabildiği en uzak mesafe ne kadardır. 

Yetişme imkanı var mıdır senin peşinden gelenin? 

biter mi soruların ardındaki sessizlik? 

kim bilir gitmelerin anlamını

toplamların artıya geçtiği yerde 

gözlerine dolabilir mi gülümsemeler

hem biliyor musun? 

bazen öyle güzel gülüyorsunki, 

insan baktığında kaybolan özgürlüğünü arıyor

tarifsizlik böyle birşey midir?', 'eyy güzel insan,  kaç parmağın var,  gülüşünün hacmi ne kadardır,  gözyaşlarının ağırlığı ölçülebilir mi?  Attığın adımlara kapılıp gelen gö...', ARRAY['Türk Edebiyatı','Şiir','Murat Tali']::text[], 8.5, '{"poet":"Murat Tali","poet_slug":"murat-tali","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gozlerine-dolan-gulumsemeler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben?', 'ben-emre-gocer-8yynr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'destenin içine

sıradan bir kağıt olarak geldim dünyaya

bazen üzerine sinek konan baklava

bazen de hançer yemiş kalptim

ne yuva yıktım

ne de birini zengin ettim

ya da tam tersiydim', 'destenin içine sıradan bir kağıt olarak geldim dünyaya bazen üzerine sinek konan baklava bazen de hançer yemiş kalptim ne yuva yıktım ne de ...', ARRAY['Türk Edebiyatı','Şiir','Emre Göçer']::text[], 8.5, '{"poet":"Emre Göçer","poet_slug":"emre-gocer","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ben-262-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidelim', 'gidelim-emre-gocer-xvdiy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'gel gidelim buralardan

buruş buruş

bir sigara paketi olalım

yanmış kibrit içimizde kalsın

ödenmiş faturalar olalım

imzalar mühürler

yeni soyadımız olsun,alışalım

yeni çıkan para olalım

yine değer kaybedelim

elden ele geçelim

üzerimizdeki resmi kendimizi

rezil edelim

ama gidelim', 'gel gidelim buralardan buruş buruş bir sigara paketi olalım yanmış kibrit içimizde kalsın ödenmiş faturalar olalım imzalar mühürler yeni soy...', ARRAY['Türk Edebiyatı','Şiir','Emre Göçer']::text[], 8.5, '{"poet":"Emre Göçer","poet_slug":"emre-gocer","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gidelim-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel', 'gel-emre-gocer-3f5mz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'korkma! 

camı açmadın mı daha önce

adım atmadın mı hiç 

bu kadar basit işte', 'korkma!  camı açmadın mı daha önce adım atmadın mı hiç  bu kadar basit işte...', ARRAY['Türk Edebiyatı','Şiir','Emre Göçer']::text[], 8.5, '{"poet":"Emre Göçer","poet_slug":"emre-gocer","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gel-288-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hazan', 'hazan-sennur-cetin-l5cqs', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Nedir bu zulum bu karmaşa

Yüreğim yanık bitmiyor bu tantana

Yüce mevlam göster adaletini banada

Dünyada iken bir solukta bana bağişla

Hayatımda ne tat var ne tuz

Gönlüm kırıldı  bedenim oldu buz

Kavuşmadan ilkbahara 

Düştüm yine hazana

27.03.2006', 'Nedir bu zulum bu karmaşa Yüreğim yanık bitmiyor bu tantana Yüce mevlam göster adaletini banada Dünyada iken bir solukta bana bağişla Hayatı...', ARRAY['Türk Edebiyatı','Şiir','Sennur Çetin']::text[], 8.5, '{"poet":"Sennur Çetin","poet_slug":"sennur-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/hazan-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahverengi', 'kahverengi-emre-gocer-rddz8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'onun kadar yumuşak bir kalbim

ve ona şekil veren karton kadar

sağlam bir benliğim vardı

bembeyazdım

kullanıldım

atıldım

sudayım', 'onun kadar yumuşak bir kalbim ve ona şekil veren karton kadar sağlam bir benliğim vardı bembeyazdım kullanıldım atıldım sudayım...', ARRAY['Türk Edebiyatı','Şiir','Emre Göçer']::text[], 8.5, '{"poet":"Emre Göçer","poet_slug":"emre-gocer","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kahverengi-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'De Bir Hele', 'de-bir-hele-yusuf-misirlioglu-pq565', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kadırga yaylasında gönlümü çalan dilber; 

De bir hele bu garip senin sevdalın mıdır? 

Bir bakışla kalbimi koparıp alan dilber,

De bir hele bu garip senin sevdalın mıdır? 

Müptelanım; sanma her dala konar bu  gönlüm.

Bu nasıl kara sevda; köze döner bu gönlüm.

Sussam içimde ukde, desem yanar bu gönlüm.

De bir hele bu garip senin sevdalın mıdır? 

Bırakıp gitme beni hatıranla baş başa.

Atma kalbimi köze, yem etme kurda kuşa.

Paralanır derdimi söylesem kara taşa.

De bir hele bu garip senin sevdalın mıdır? 

Hayalinle kurduğum sırça köşkümü kırma.

Çepni alsın gadanı; bana el gibi durma.

Eridim helak oldum; ne olur daha yorma.

De bir hele bu garip senin sevdalın mıdır?', 'Kadırga yaylasında gönlümü çalan dilber;  De bir hele bu garip senin sevdalın mıdır?  Bir bakışla kalbimi koparıp alan dilber, De bir hele b...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Mısırlıoğlu']::text[], 8.5, '{"poet":"Yusuf Mısırlıoğlu","poet_slug":"yusuf-misirlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/de-bir-hele-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umutlarımı Tüketen Geceler', 'umutlarimi-tuketen-geceler-mustafa-dogan-4-84pob', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'UMUTLARIMI TÜKETEN GECELER

Gecenin karanlığına sarıldım, acılar benim yorganım,

Sessizliğin çığlığı yayıldı geceme, tükendi umutlarım,

Meçhullerdeyim kayboldum, bulamaz beni dostlarım,

Ümitler can çekişiyor,yaşamıyor artık son umutlarım.

Yüksek bir dağın başında ki bembeyaz karmış sevgin,

Erirsin yüreğimde çektirdiğin acılarla, farkında mısın,

Sanma ki kalbimde sana sevgim kaldı,anlamaz mısın,

Boşuna arama çoktan bitti,kırıntısını bile bulamazsın.

Sevgin kalbime konan bir kelebekti ömrü çoktan gitti,

Kanatları zayıftı bu sevgimi taşıyamadı kırılıp da gitti,

Sevgi ırmağım o kuru fidan köküne boşuna akıp gitti,

Açmadı o sevgi çiçekleri, bütün emeklerim boşa gitti.', 'UMUTLARIMI TÜKETEN GECELER Gecenin karanlığına sarıldım, acılar benim yorganım, Sessizliğin çığlığı yayıldı geceme, tükendi umutlarım, Meçhu...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Doğan 4']::text[], 8.5, '{"poet":"Mustafa Doğan 4","poet_slug":"mustafa-dogan-4","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/umutlarimi-tuketen-geceler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul Ağlıyor!', 'i-stanbul-agliyor-kiral-boga-l0drg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'I.

İstanbul ağlıyor / göz kapaklarımda; 

Acısı dinmiyor / ne yapsam başımda.

İstanbul böyle mi olmalıydı / kirli,

Deniz’inde çığlık-çığlık martıları; 

Atılan simitlere saldırıyorlar,

Eskimiş şehir hatları vapurlarından! 

II.

Gölgeleri uzuyor / öğle ikindilerinde; 

İşsiz insanlar   / evsiz –barksız çocukların.

Barınak yerleri olmuş köprü altları,

Çocuklar sahipsiz / çocuklar günahsız.

Düşmüşler ekmek kaygısına,

İstanbul ağlıyor / İstanbul perme-perişan; 

Haline baktıkça utanıyor,

Çağ açan-çağ kapatan Sultan’ından! 

III.

Anadolu yanıyor / İstanbul yollarında; 

Her gelen bir şeyler koparıyor / İstanbul’umdan.

İstanbul susuyor / İstanbul konuşmuyor,

Herkes zevk-ü sefaya dalmış; 

Kültürü / o eskidenmiş.

‘Televole’ler yaratılmış / ucuz arebesk şarkıcılardan! 

IV.

Yağmur yağmaya görsün/varoşlarında; 

Kan gölüne dönüyor bataklıkları.

İstanbul karışmış / İstanbul akıyor sel-zebil,

‘Medya savaşları’/ reytingler çala-kalem; 

Bir de ekliyorlar / deprem furyasını,

Medet umuyorlar / utanmadan falcılardan! 

V.

Özenti –beklenti / almış gidiyor başını; 

Çaresiz ve masum / evinden kaçan kızların.

Eli-ayağı kırılmış / yaşamak uğruna,

Bini bir paraya satılan / namusların; 

Hesabı sorulmuyor / nedense bilinmez? 

Günahlar akıtılıyor / köprülerin altından! 

VI.

Işıklı neonlar bir yanda; 

Sönen ocaklar diğer yanda.

İstanbul’u kirletiyor / kalpazanlar,

Üşüşmüşler İstanbul’umu / parçalıyorlar! 

Türkiye mi parçalıyorlar! 

Sahipsiz İstanbul’uma girmiş/ dış güçler; 

Parsel-parsel çalıyorlar / tapularından! 

VII.

Daha durun diyemiyorum / bu gidişe; 

İstanbul ağlıyor-İstanbul çağlıyor.

San’atıyla, inceliğiyle kayıyor / ayaklar altından,

Sebep kim / bütün bunlara? 

İstanbul’um / kimi suçlayalım? 

Keşke  ‘Fatih’ kurtarmasaydı,

Diyesim geliyor / utanıyorum yargılarımdan! 

VIII.

Güzelliğine sözümüz yok; 

Kahroluyorum / bu entrikalara,

İnsanına-yaşayanına.

Bir dönme dolaptır / sürüyor hezeyan,

Tarihine-şanına saygı duymayan; 

Ben de dâhil / duygusuz ve nankörüz; 

Dağlarından-taşlarından! 

28–03/06 Maltepe-İstanbul', 'I. İstanbul ağlıyor / göz kapaklarımda;  Acısı dinmiyor / ne yapsam başımda. İstanbul böyle mi olmalıydı / kirli, Deniz’inde çığlık-çığlık m...', ARRAY['Türk Edebiyatı','Şiir','Kıral Boğa']::text[], 8.5, '{"poet":"Kıral Boğa","poet_slug":"kiral-boga","theme":"Türk Şiiri","is_hero":false,"total_lines":62,"source_url":"https://www.antoloji.com/istanbul-agliyor-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Newroz', 'newroz-adem-tok-7sq9v', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'berfin bahar açmış

düşmüş dağlara

sarı

kırmızı

yeşil

sema bayrak olmuş

almış rengini bağrına

yanan ateş değil

newrozun buğusu

sıçrayan; 

uyanış! 

''ya zılgıtlar'' diyeceksiniz

evet: yoldaş! ..

kawanın türküsü değil mi o çekiç 

				sesleri

sökerken şafağa eşlik eden

ağır ağır

kapanan baran değil mi

başaklara hayat veren alüvyondan

genç kızların yazması hangi gün

saklandı koyna

ya çaylar

neden böyle dinç, bugün; 

neden duru

oysa dün görülmezdi çakıl taşları

berfin bahar açmış

düşmüş dağlara

şehirler arşa çıkıyor teriyle alev alev

şehirler sabaha...

ırak-acem

anadolu-Suriye

dört dağ

bir tanrı başlarında,

ışıl ışıl: med

Mezopotamya

berfin bahar açmış

düşmüş dağlara

dirilmiş

saklı değil kar altında

başkaldırının bayramıdır bugün 

kardelen bugün

bugün bahar 

yüzünü yıkarsın ey! tabiat 

marguez''in yağmuru 

victor Jara''nın parmaklarında gitarının 

yanan telleri 

ses veriyor 

perde perde 

sağanak! 

berfin bahar açmış

düşmüş dağlara

tırtıl kelebek

atla! atla! 

gürleşen ateşten

toprağını yerden selamlayan kafkas kartalı

dumandır bu, şaşırmayan

dumandır katmer katmer kalkan

kardeşlik iklimine

bacası: SADAKAT...

                                                       (21.03.04)

                                                   f tipi hapishane EDİRNE', 'berfin bahar açmış düşmüş dağlara sarı kırmızı yeşil sema bayrak olmuş almış rengini bağrına yanan ateş değil newrozun buğusu sıçrayan;  uya...', ARRAY['Türk Edebiyatı','Şiir','Adem Tok']::text[], 8.5, '{"poet":"Adem Tok","poet_slug":"adem-tok","theme":"Türk Şiiri","is_hero":false,"total_lines":61,"source_url":"https://www.antoloji.com/newroz-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlkbahar', 'i-lkbahar-sururi-turan-xvlb6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İLKBAHAR

papatya çayırları 

tüm ufku kaplamak istiyor

gözlerdeki kara perdeyi yırtarak

acılı gönüllere ıpılık yayılmak

ısıtmak

ısıtmak

rüyalarda

ve işte

orda

çayırlarda

yalınayak koşan

bir kız çocuğu

masumiyetin tanımıdır

savaşlar

depremler

yangınlar

cinayetler

burda

anneler ölüyor

orda

babalar 

çocuklar ölüyor

ve masumiyet

böyle 

hergün

papatya çayırları 

tüm ufku kaplamak istiyor

gözyaşlarımızla

ıpıslak

hoşgeldin ilkbahar', 'İLKBAHAR papatya çayırları  tüm ufku kaplamak istiyor gözlerdeki kara perdeyi yırtarak acılı gönüllere ıpılık yayılmak ısıtmak ısıtmak rüyal...', ARRAY['Türk Edebiyatı','Şiir','Sururi Turan']::text[], 8.5, '{"poet":"Sururi Turan","poet_slug":"sururi-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/ilkbahar-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerdesin Be Aşkım', 'nerdesin-be-askim-sennur-cetin-fdbbq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yüreğimde belirsiz bir sevinç

Gözlerimde unuttuğum bir pırıltı

Dilimde mısralanmış güzel sözler

Nerdesin be aşkım

Seni bekliyor bu kara gözler

Canımdan can iste vereyim

Ben kendimden yıllar oldu vazgeçtim

Sen iste ömrümü düşünmeden feda edeyim

Sen iyi ol ben öleyim

Birgün daha doğdu penceremden

Sensiz ve acılar içinde

Nerdesin be aşkım

Sıcak ellerin tutmuyor ellerimi

Annem sözcüklerin fısıldamıyor kulaklarımda

Yüce mevlamın en büyük lütfü 

Kalp atışım can suyum

Nerdesin be aşkım

Karagözlüme......', 'Yüreğimde belirsiz bir sevinç Gözlerimde unuttuğum bir pırıltı Dilimde mısralanmış güzel sözler Nerdesin be aşkım Seni bekliyor bu kara gözl...', ARRAY['Türk Edebiyatı','Şiir','Sennur Çetin']::text[], 8.5, '{"poet":"Sennur Çetin","poet_slug":"sennur-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/nerdesin-be-askim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek, Sevilmek', 'sevmek-sevilmek-alaattin-colak-s2qow', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevmek, Sevilmek

Sevmek,

Yeryüzünden, gökyüzüne

Bakmak gibi bir şey sanırım

Güneş,Ay, Gezegenler, Bulutlar

Isıtanı, Üşüteni, aydınlatanı 

Bilinmeyeni var.

Birde yıldızlar var

Bazen kayan 

Yakalayamadığımız

Hayal edilemeyecek kadar büyük

Sonsuz

Sevilmek ise

Gökyüzünden,yeryüzüne

Bakmak olsa gerek

Sadece bulutları gördüğümüz

Ancak hayal edebileceğimiz bir şey

Ben gördüğüm hayallerin 

Peşinden koşuyorum

Bir gün 

Güneşin ısıttığı 

Bir gezgenden 

Kayan bir yıldızı

Yakalayacağımı biliyorum.

Yalnızca sevilmeyi bekleyenler

Bulutlar sizin olsun.

İkisinin kesiştiği bir yer var mı? 

Ben de bilmiyorum.', 'Sevmek, Sevilmek Sevmek, Yeryüzünden, gökyüzüne Bakmak gibi bir şey sanırım Güneş,Ay, Gezegenler, Bulutlar Isıtanı, Üşüteni, aydınlatanı  Bi...', ARRAY['Türk Edebiyatı','Şiir','Alaattin Çolak']::text[], 8.5, '{"poet":"Alaattin Çolak","poet_slug":"alaattin-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sevmek-sevilmek-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eyvah ki Eyvah', 'eyvah-ki-eyvah-mehmet-ayhan-gunaydin-aylay', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'EYVAH Kİ EYVAH

Sene doksan üç,

Kendimce…

Şiir yazmaya niyetlenmişim.

İlk şiirlerimin birinde…

Yanıyorum eyvah! 

Diye seslenmişim.

………………….

………………….

………………….

Sene iki bin altı,

Aradan koskoca

On üç yıl geçmiş.

Düzen değişmemiş.

Durum değişmemiş.

Hatta ve hatta

Daha da kötüye gitmiş! ! 

İlgilenen dostlara…

Meraklısına……….

Hal-i beyanımdır.

Hani; 

Yanıyorum eyvah demiştim ya,

Artık YANDIM! ! ! 

Merak etmeyin.

M. Ayhan Günaydın.

     27 Mart 2006 

          Ankara', 'EYVAH Kİ EYVAH Sene doksan üç, Kendimce… Şiir yazmaya niyetlenmişim. İlk şiirlerimin birinde… Yanıyorum eyvah!  Diye seslenmişim. …………………. …...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ayhan Günaydın']::text[], 8.5, '{"poet":"Mehmet Ayhan Günaydın","poet_slug":"mehmet-ayhan-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/eyvah-ki-eyvah-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilekler de adamına göre', 'dilekler-de-adamina-gore-mehmet-halil-9d5ol', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Güçlüye ‘’yaşa! ..’’ demek için

Okumak gerekmiyor

Zayıfa ise, ‘’yaşa’’ demek için

Dört okul bile yetmiyor.', 'Güçlüye ‘’yaşa! ..’’ demek için Okumak gerekmiyor Zayıfa ise, ‘’yaşa’’ demek için Dört okul bile yetmiyor....', ARRAY['Türk Edebiyatı','Şiir','Mehmet Halil']::text[], 8.5, '{"poet":"Mehmet Halil","poet_slug":"mehmet-halil","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/dilekler-de-adamina-gore-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cennetin içindeyim', 'cennetin-icindeyim-vedat-okkar-3iwfb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen dağlardaki güzellik,

Ağaçlardaki yeşillik,

Bir kar kadar sade beyaz,

Yüreğimin nur''usun bembeyaz.

Ben seninleydim biraz önce,

Elinden tutmuştum,

O bembeyaz bulutlarda dolaşıyorduk sessizce.

Karşıkı dağları görüyordum sevgiye hasret,

Hasretten saçları ağırmıştı dağların,

Senin gelişinle güneş vurdu eridi karları,

Akarsuyu görüyordum,

Eğildim senin sudaki yansımanı seyrettim,

İki elini bana doğru açmıştın,

Elimi uzattığımda farkettim gökyüzünde değildim,

Cennetin içindeydim...', 'Sen dağlardaki güzellik, Ağaçlardaki yeşillik, Bir kar kadar sade beyaz, Yüreğimin nur''usun bembeyaz. Ben seninleydim biraz önce, Elinden tu...', ARRAY['Türk Edebiyatı','Şiir','Vedat Okkar']::text[], 8.5, '{"poet":"Vedat Okkar","poet_slug":"vedat-okkar","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/cennetin-icindeyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilirmisin', 'bilirmisin-sevgul-kilicaslan-5jh5o', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yanıbaşındayken

Sana hasret kalmak..

Ne demek? ? 

Bilirmisin..! 

Kalabalıgın tam ortasındayken

Yalnız oldugunu hissetmek..

Ne demek..? ? 

Bilirmisin..! ! 

Yaralı yüregin için için aglarken

Kahkaha atmak zorunda kalmak..

Ne demek..? ? 

Bilirmisin..! ! 

Aşkından deli divane olmuşken

Senden nefret ediyorum 

Ne demek..? ? 

Bilirmisin..! ! 

Bilmedigin her şeyin

Aslında canlı örnegi benim

Yoksa..Onunda

Farkında degilmisin..! !', 'Yanıbaşındayken Sana hasret kalmak.. Ne demek? ?  Bilirmisin..!  Kalabalıgın tam ortasındayken Yalnız oldugunu hissetmek.. Ne demek..? ?  Bi...', ARRAY['Türk Edebiyatı','Şiir','Sevgül Kılıçaslan']::text[], 8.5, '{"poet":"Sevgül Kılıçaslan","poet_slug":"sevgul-kilicaslan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bilirmisin-53-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boncuk', 'boncuk-vedat-okkar-c1v3v', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni tanıdım canım oldun,

Canımdın kanım oldun,

Çok uzaklardan ruhuma doldun,

Mutluluk verici hislerim oldun.

Güzeller güzeli dedim sana,

Çünkü melekler sıvazlamış yüzünü,

Sevgi ve hoşgörü bürümüş yüzünü,

Adını andığımda mutluluk kaplar sözümü.

Yarınlar var önünde,

Sevgiyle mutlulukla seni bekler,

O kadar tatlısın ki,

Zaman zaman mutluluk bile seni özler,

Üzme sakın sen canını,

Yüzünde gülümseme olsun kalbin mutlu,

Bedenine sağlık dolsun,

Sen benim yüreğimde mutluluğu hakeden boncuksun.', 'Seni tanıdım canım oldun, Canımdın kanım oldun, Çok uzaklardan ruhuma doldun, Mutluluk verici hislerim oldun. Güzeller güzeli dedim sana, Çü...', ARRAY['Türk Edebiyatı','Şiir','Vedat Okkar']::text[], 8.5, '{"poet":"Vedat Okkar","poet_slug":"vedat-okkar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/boncuk-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ok Yaydan Çıktı Bir Kere', 'ok-yaydan-cikti-bir-kere-zafer-caglar-mlk3d', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sözlerin sitemlerle doluydu,

Hiç mi hiç,sebepsiz yere.

Düzelmez bir daha aramız,

Ok yaydan çıktı bir kere.

Faydasız ağlaman,sızlaman,

Diz çöküp,önümde yalvarman,

Dönüş yok,eski günlere,

Ok yaydan çıktı bir kere.

Sevgiler,mutlu anlar,

Bak hepsi mazide kaldılar.

Ne yapsan dönüş yok geriye,

Ok yaydan çıktı bir kere.', 'Sözlerin sitemlerle doluydu, Hiç mi hiç,sebepsiz yere. Düzelmez bir daha aramız, Ok yaydan çıktı bir kere. Faydasız ağlaman,sızlaman, Diz çö...', ARRAY['Türk Edebiyatı','Şiir','Zafer Çağlar']::text[], 8.5, '{"poet":"Zafer Çağlar","poet_slug":"zafer-caglar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ok-yaydan-cikti-bir-kere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzaklarda bir Melek', 'uzaklarda-bir-melek-vedat-okkar-axlzw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bugün yine seni düşündüm,

Çok uzaklara gittim düşlerimde,

Dağların en uç tepelerine,

Kuzeyden güneye dolaştım seni aradım.

Nereye gitsem içimde Huzur vardı,

Sanki birşeylerin sıcaklığı,

Anlatılmaz bir mutluluk içimdeki,

Hislerimdeki, yüreğimdeki.

Bahçe bahçe dolaştım düşlerimde,

Her çiçeği kokladım derinden,

Bir çiçek vardı unutulmaz,

Kokusunu hissettim kalbimen.

İçimdeki sıcaklığa ne güzelde yakıştı,

İşte bu içimdeki sıcaklığı saran duygu,

Gözlerimin mutluluğu,

Uzaktaki bir meleğin kokusu.

İnsana mutluluk veren bu duygu,

Kalbime her zaman mutluluk sundu,

Aynı kanımı taşıyoruz yoksa,

Aramızda yollar çokta olsa,

Hislerimdesin düşlerimdesin oysa.', 'Bugün yine seni düşündüm, Çok uzaklara gittim düşlerimde, Dağların en uç tepelerine, Kuzeyden güneye dolaştım seni aradım. Nereye gitsem içi...', ARRAY['Türk Edebiyatı','Şiir','Vedat Okkar']::text[], 8.5, '{"poet":"Vedat Okkar","poet_slug":"vedat-okkar","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/uzaklarda-bir-melek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yerin Hiç Dolmayacak', 'yerin-hic-dolmayacak-zafer-caglar-byc7k', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hiç ayrılma yanımdan,

Çekip gitme uzağa,

Harcayacak,o seni,

Sakın düşme tuzağa.

Kulak ver uyarıma,

Dinle,bak gözlerime,

Hiç sevmedi, o seni,

İnan bu sözlerime.

Neden böyle bozuldu,

Yürüyen ilişkimiz,

Şimdi yabancı olduk,

İnanamıyorum,biz.

Aşkın gözü kör derler,

Mutlaka duymuşsundur,

İnanarak sen ona,

Şeytana uymuşsundur.

Birkaç güzel kelime,

Büyülüyor seni,

Düşünmüyorsan beni,

Ne olur,düşün kendini.

Bu sana son uyarım,

Tekrarı olmayacak,

Ayrılıp gitsen bile,

Yerin hiç dolmayacak.', 'Hiç ayrılma yanımdan, Çekip gitme uzağa, Harcayacak,o seni, Sakın düşme tuzağa. Kulak ver uyarıma, Dinle,bak gözlerime, Hiç sevmedi, o seni,...', ARRAY['Türk Edebiyatı','Şiir','Zafer Çağlar']::text[], 8.5, '{"poet":"Zafer Çağlar","poet_slug":"zafer-caglar","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yerin-hic-dolmayacak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıyamet Kopar', 'kiyamet-kopar-ziya-kara-yufwf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne siz sorun, ne de ben söyleyeyim

Neden böyle üzgün, benim bu halim

Yer yüzü, gök yüzü, fark etmiyor ki; 

Tutunamıyorum, boşluklardayım.

Suçlanacak biri varsa, o, benim

Ben dünyaya uyum sağlayamadım

Sevenim olmadı, sevmek de yasak

Demek ki; ağlamak, benim kaderim.

Hayat daha farklı olabilirdi

Ama ben, her şeye mahkum edildim.

Dünyayı alt üst etsem de boşuna

Gönlüm yarı açık ceza evinde.

Her şey olacağına varacaksa

Ha bir eksik, ha bir fazla benimle

Arayanım soranım yok, yalnızım

Yaşıyor, yaşamıyorum, kime ne? 

Hepimizin sonu belli değil mi? 

Ay''a, güneş''e çıksam ne değişir

Yıldızları tutup, yere indirsem

Bir şey olmaz, ancak kıyamet kopar', 'Ne siz sorun, ne de ben söyleyeyim Neden böyle üzgün, benim bu halim Yer yüzü, gök yüzü, fark etmiyor ki;  Tutunamıyorum, boşluklardayım. Su...', ARRAY['Türk Edebiyatı','Şiir','Ziya Kara']::text[], 8.5, '{"poet":"Ziya Kara","poet_slug":"ziya-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kiyamet-kopar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutsak', 'tutsak-vedat-okkar-dqcjy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tutsak kalmak istiyorum senin gözlerinde,

Şarkı söylemek istiyorum senin özleminle,

Büyümek istiyorum kollarında sessizce,

Avunmak istiyorum yarın geleceksin diye,

Bugün yine sensin düşlerimde,

Kalbimdesin tüm benliğinle,

Hislerimdesim mahsum gülüşlerinle,

Misafirsin yine üç boyutlu gecelerimde,

Gelmelisin artık özlemlerinle,

Görmeliyim seni gözlerimle,

Büyümeliyim çocukça gönlünde,

Tutsak kalmalıyım seninle özgürce.', 'Tutsak kalmak istiyorum senin gözlerinde, Şarkı söylemek istiyorum senin özleminle, Büyümek istiyorum kollarında sessizce, Avunmak istiyorum...', ARRAY['Türk Edebiyatı','Şiir','Vedat Okkar']::text[], 8.5, '{"poet":"Vedat Okkar","poet_slug":"vedat-okkar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/tutsak-61-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Şiirim', 'son-siirim-yasemin-birbudak-svgyp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Nasıl bir girdap ki çıkamıyorum içinden 

Neden vazgeçemiyorum ceylan gözlerinden 

Mutsuzlukla dost olmuşken…

Nerden çıktın karşıma aldın beni benden.

Yaşamın bu kadar güzel olduğunu bilmiyordum

Güneş bu kadar sıcak mıydı? 

Sevda böylesine acıtır mıydı? 

Neden hep mutluluğa  geç kalıyordum…..

Sorgusuz olmalıydı aşk ama imkânsız asla

Gözlerinde kaybolduğum, eridiğim dudaklarında

Mutluluğu bulmuşken yanında

Biliyorum anlamsız bu veda….

Sevda.. Hayat seninle daha acımasız

Yanıyorum, bitiyorum amansız

 Kaçıyorum yine,gidiyorum zamansız..

Çünkü sen şarap kokulum bana imkansızsın imkansız……

22.03.2006 /MERSİN

Yasemin birbudak

(Bir daha şiir yazmayacağımmmm…)', 'Nasıl bir girdap ki çıkamıyorum içinden  Neden vazgeçemiyorum ceylan gözlerinden  Mutsuzlukla dost olmuşken… Nerden çıktın karşıma aldın ben...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Birbudak']::text[], 8.5, '{"poet":"Yasemin Birbudak","poet_slug":"yasemin-birbudak","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/son-siirim-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşka şiir yakışır', 'aska-siir-yakisir-vedat-okkar-w6i4v', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yağmurlar yağarken gökten üstüme

duygularım her an seninle,

Bu güzelliğe meleğimin ağzından

şarkı yakışır.

Ilık bir duygu dolaşır,

Sevgi damarlarımda,

Bana aşıksın diye feryad eder.

Yağmurlara çıkarım

Delikanlı romantik çocuğum

Elimde çiçeklerin en güzeli gelincik,

ısıtır beni sessiz sessiz.

Ansızın bastıran yağmurla ısınır içim,

Şimdi hiç kopamadığım, kaçamadığım,

Yanlızlığımdır sevgine en yakın yerim,

Gelecektir meleğim beklerim...', 'Yağmurlar yağarken gökten üstüme duygularım her an seninle, Bu güzelliğe meleğimin ağzından şarkı yakışır. Ilık bir duygu dolaşır, Sevgi dam...', ARRAY['Türk Edebiyatı','Şiir','Vedat Okkar']::text[], 8.5, '{"poet":"Vedat Okkar","poet_slug":"vedat-okkar","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/aska-siir-yakisir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erzurum''da Sayılı Günler', 'erzurum-da-sayili-gunler-huseyin-kotan-c2qqk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hele dadaş bir dinle size bir destanım var

Kışları uzun mi uzun,baharı dar

Ondört Kasımda koç katımı var

İşte kış bu tarihten sonra başlar

Harman kaldırıp toylar yapılır

Otlar,samanlar mereklere atılır

Gavurmalıklar kesilir,peynirler basılır

Kartol,şalgam,pürçikli kuyulara atılır

Yedi haftalarda ne ararsan bulunur

Rabbim sana binlerce şükürler olsun

Oğlanın boyi uzandi,gelin gızında bir naz

Ülüzgar esmeye başladı havalar ayaz

Gapı önünde durir çifte gara zağar

Gar,Goç gatımından ya ongün önce ya sora yağar

Gapılari bacalari her yeri gaplar

Yerde ne his galır ne de kir,hepsini paklar

Aralığın dördü bizde dan agovandır

Bundan sonra yenilen peynir ile soğandır

Bıldır bele oldi bu yılda böyle olacak

İgirmi gün sonra nahır govan gelecek

Bundan sonra çıkılmaz artık dışarı

Mallara alaf su ver gez aşağı yukarı

Gafada enni şapga belde uzun guşaklar

Gelirse pastırmacı yazı yaşşadı uşaklar

 Aralık ocak aylarına gelir zemheri

İki çeşidi vardır,biri erkek öbürü dişi

Erkek zemheriye güvenilir olmaz ondan zarar

Dişi zemheride pek çok kötülükler var

Çoğu zenginin olmaz bundan haberi

Zemheride su akacağına gan aksın daha iyi

Mahsulden olmaz hayır gider bin bereket

Zemheride su akarsa bu ili hemen terk et

Ocal ayının son cumasına hıdırellez dediler

Şubatın ilk cumasına gadar sürsün istediler

Bu sürede çok yağış olur muhtaçları Hızır bulur

Ona rastlanmak istenir,ondan yardım umulur

Şubatın ikinci cuması ulu camiye gitmeli

O gün gelecek Hızır’ı umutla beklemeli

Kılar namakzını bu camide yöreye veda eder

Hızır ilimizden ayrılır giderde gider

Hıdırellezin birinci günü bolca tuzlu yiyip yatmalı

Rüyada su veren güzele iyice bir bakmalı

Gılik yapıp sevdiğin bacasına goyulacak

Gargalar guşlar hangi bacada yedi o bulunacak

Pisiklerin yattığı yerlerdir küllük

Dar uzunca biçimsiz şeylerde düllük

Analar eledi bebeye höllük

Erzurum’da şubat’ın adıdır cücük

Cücügün son dört günü mardın üç günü beldelegüz

Çok soğuk olur bu gün insanı eder dümdüz

Bu günde,yola çıkıp ölene iyi gözle bakılmaz 

Bile bile çıktı yola arkasından ağıt yakılmaz

Zorlana zorlana geldik mi marda

Bitti alaf yakacak yakacak kaldıkmı darda

Zaten kış boyunca gavrulduk donduk

Gün geldi tıssik yakdık dumanına boğulduk

Guzzigimiz çıkdi baca gar’i dökmekten 

İmanımız gevredi velehevle çekmekten

Ferik,bılik,culluk galmadi hepisin yedik

Ahan bahar gelir hep yollari gözledik

Atın,eşşegin,kurigin alafı bitti

Tıllik Üzeyir yokluktan gurbete gitti

Godik,gudik,enikler hep darda galdi

Sayılı günler durir,umutlar bahara galdi

Bilirsiz mardın sekizine gelmez dokuzuna galmaz

Fazla dırlayan gızi heç kimse almaz

Haca giden leylekler bu gece geldiler

Öyle bir gar yağdı ki onnara peşman oldiler

Mardın onunci güni ezelbahar veya kese yaz

Onyedinci günü haftamahal veya orta yaz 

Bu günlerde yağmurun bolca yağması istenir

Arazinin gardan temizlenmesi beklenir

Dadaş beldesi Türbede yatar büyük Gaziler

Bu zamanda gelir Erzurum’a caziler

Ana,eze,bibi galdi bunlardan naçar

Damlardan girer içeri yağın bereketi gaçar

Aras,Murat,Garasu bu mevsimde coşarlar

Nice ocaklar söner sağa sola taşarlar

Haftamahalda sütler yayıklara yayılır

Yapılan yağın üstüne at mıhi goyulur

Her insana bir taş bacalara düzerler

Hangisinden böcük çıkdi ona bakar gezerler

Böcük çıkan taş sahibi en şanslı kişi

Bütün yıl boyunca onun adına görürler işi

Nisan’a abrel derler günler bir ile başlar

Goca garı soğukları çoluk çocuği haşlar

Beş nisanda camış gıran bulunur

Bu günün soğuğundan çok kötülük umulur

Sabah bulutu gızardı Biplo şimdi ötecek

Bahar yaklaşir artık bacalarda tütecek

Mıhmındırik yapılır yağmur duasına çıkılacak

İkindiden sonra başlar mayıs şırşırları

Bırakmaz ki çıka dışarı insanlari

Kırkikindilerde fazla yağmur istenmez

İmani olan yürekler yokluktan hiç paslanmaz

Fazla yağarsa yağmur kırk kel adı bulunur

İsimleri sayılır ipliğe dualar okunur

Fazla kurak olunca düğümleri bozarlar

Sıcağı gören yürekler gudururlar azarlar

Gar Ağustosun onunda bile Palandökende durur 

Şavki parlar allı pullu şehere vurur

Bu kadar gün yaşadık dalımız ıssınmadi

Sayılı günlere yazacak başka bir şey galmadi

Bu destan için bir makaleden faydalandım

Devamsızlık benimki çok sevdim,çok sevdalandım

Eski heybetli Dadaşlar Türbe deresini aştıda gitti

Sanmayın Erzurum’un sayılı günleri burada bitti', 'Hele dadaş bir dinle size bir destanım var Kışları uzun mi uzun,baharı dar Ondört Kasımda koç katımı var İşte kış bu tarihten sonra başlar H...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Kotan']::text[], 8.5, '{"poet":"Hüseyin Kotan","poet_slug":"huseyin-kotan","theme":"Türk Şiiri","is_hero":false,"total_lines":107,"source_url":"https://www.antoloji.com/erzurum-da-sayili-gunler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ses Ver Cananım', 'ses-ver-cananim-ziya-kara-i5pmd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sessizliği boz da; ses ver cananım

Sesine hasret, canım yanıyor canım

Çare olamadı göz yaşlarım da

Ağaç gibi kurudu yaprağım, dalım

Karış karış parsellere bölünen,

Gönül bahçemde çiçekler açmayacak.

Benliğimden sonra, ruhumu da sattım

Allahım! şimdi ben ne yapacağım?', 'Sessizliği boz da; ses ver cananım Sesine hasret, canım yanıyor canım Çare olamadı göz yaşlarım da Ağaç gibi kurudu yaprağım, dalım Karış ka...', ARRAY['Türk Edebiyatı','Şiir','Ziya Kara']::text[], 8.5, '{"poet":"Ziya Kara","poet_slug":"ziya-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ses-ver-cananim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acıktın mı Dadaşım', 'aciktin-mi-dadasim-huseyin-kotan-ow9hr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Zaman değişir, türli tevür şeyler olir

Milli olan her şeyimiz sessizce gaybolir 

Bu gayıpları ne arayan nede soran var

Size eski yemekleri annadim mi gardaşlar? 

Davul bile vurur dengi dengine 

Geysefe’nin eyisi her zaman zengine 

Mısırı çekeller,südünnen Haşıl ederler

Gış gecelerinde hasır dokumaya gideler

Hesdelere yediriller sarı yağli Hasuta

Damara gan gele erden ere maksuda

Kerti eymekleri yumurta soğan ile yayallar

Acıkmışın önüne Cılbıra’yı goyallar

Epey zehmetlidir inceden Yumurta Pilav

Pisik bile görünce derki miyav miyav

Lahana’nın galınlarından acılı Kapusga

Guşgananın içinde nasılda gasılır hasba

Un gavurmasından yaparlar sıcak olur herle

Soyuk alanlara içiriller terle babam terle

Yufgadan üç köşeli kesilmiş Tatar Böreği

Sarı yağdan,yoğurttan görünmirki göbeği

Tarhınlı yaparlar Mercimekli Kesme Çorbası’nı

Dadaş yedimi elbette sever gaynanasını

Soğan,yumurta gavurmadan Mıhlama 

Bulgur pilavi var yanında gıgıldama

Soğan,Şalğam dolması hep etinnen olur

Şalgamların yanına bolca yoğurt gonur

Peşgunun ortasında Garışık Turşi durur

Fanos’un kölgeside garşıki duvara vurir

Soyuk gecelerde bazen Bulgur Şilesi

Bulunur içinde binbirtürli hilesi

Yufgadan keserler degirmi degirmi Siron’u

Haşmetli tepside sen seyreyle bir onu

Buğdayı,arpayı gavurur Gavut ederler

Sarı yağlı bal şerbetini ortasına töker yerler

Eveliğin yaprağına sarılır Lor Dolması

Yemeklerin has sosu alâsı mı alâsı

Su Böreği sofralardan heç eksik olmaz

Gadayıf Dolması’nın üstüne datli bulunmaz

Gaz Lokması’nın boynu büklüm büklüm bükülür

Ekmek Gadayıfı’nın üstüne bolca ceviz dökülür

Terbiye görmüş etleri böyük şişe düzeller

Ocağın garşısında hızli hızli gezeller

Odun saplı Cağ’a tike tike keseller

Ecem eymek,guri soğan yiyemezsen küseller

Sıcak yaz günlerinde ne güzeldir Ayran Aşı

Höpürdeterek içmezsen gözlerin olur şaşı

Yanında varsa tandırda gızarmış Kelle

Ardından bi tütün sar telle babam telle

Her zaman hazır olur yağda gızarmış Bişi

Yazın uzun günlerinde yersin etli Çirişi

Pirpirim’de bulunur bolca sığır gıyması

Yanında nazlı nazlı yenir İncir Dolması

Toplanır temiz yerden Yemlik ile Tere

Lavaşınnan,lorunnan muhaggak girer eve

Kartoldan,yoğurtdan yağdan yapılır Borani

Lezzet bilenler olmuştur mubaregin hayrani

Çırtma Löbiye’yi gemikli etnen yaparsın

Nar gibi sobaya duzli kartol atarsın

Çilek Soğan’ı üç barmağınnan dutarsın

Gara gözli Tıs Üveze iştahınnan bakarsın

Özene özene geldik işin sonuna

Gıymetli arkadaşım geldi girdi goluma

Herhal yengen bişirmiş Gavurmali Hıngel

Ehdaman etti Kotan’ı alda gel

Daha çokyemeğimiz var,hepsini sayamadım

Bunca yıl hür yaşadım ERZURUM’a doyamadım

Varsın zaman değişsin türli tevür şeyler olsun

Mutfağıza bereket,hanenize sıhhat dolsun

KOTAN yazdı size ecayip yemek destanı

Yemedinse bu yemekleri yede lezzeti tanı

İşte sokağın başında göründi Godida Beşe

Gönüle sevgi dolsun ömür geçmesin beleşe', 'Zaman değişir, türli tevür şeyler olir Milli olan her şeyimiz sessizce gaybolir  Bu gayıpları ne arayan nede soran var Size eski yemekleri a...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Kotan']::text[], 8.5, '{"poet":"Hüseyin Kotan","poet_slug":"huseyin-kotan","theme":"Türk Şiiri","is_hero":false,"total_lines":72,"source_url":"https://www.antoloji.com/aciktin-mi-dadasim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vefasız', 'vefasiz-sevgul-kilicaslan-oi657', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben sana aşıkken

Başkaları çalar hep 

Aşk kapımı..! 

Bir sen çalmadın 

Vefasız..! 

Sana olan sevgimi

Defalarca anlattım..

Daglara..taşlara

Uçan kuşlara..

Bir sen duymadın

Vefasız..! 

Seni sevilmek..

Beni sevmek için,

Yaratmış..Yaradan.

Sevdim seni

Zamansız..

Sevdim seni

Günahsız..

Sensiz olmam imkansız..

Bir sen bilmedin 

Vefasız..!', 'Ben sana aşıkken Başkaları çalar hep  Aşk kapımı..!  Bir sen çalmadın  Vefasız..!  Sana olan sevgimi Defalarca anlattım.. Daglara..taşlara U...', ARRAY['Türk Edebiyatı','Şiir','Sevgül Kılıçaslan']::text[], 8.5, '{"poet":"Sevgül Kılıçaslan","poet_slug":"sevgul-kilicaslan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/vefasiz-70-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeniden Başlayalım', 'yeniden-baslayalim-zafer-caglar-k1oe7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir ışık gibi parlayıp,

Geçtin gözümün önünden,

Hiç sebep,gerek yokken,

Niçin döndün sözünden? 

Biz böyle mi konuştuk,

Biz böyle mi anlaştık? 

Hayat denen gerçeği,

Hep birlikte paylaştık.

Gel yine konuşalım,

Gel yine anlaşalım,

Unutarak geçmişi,

Yeniden başlayalım.

Pişman olmamak için,

Gel,tekrar deneyelim,

Yine de yürümezse,

Birlikte bitirelim.

Sevgi,aşk güzel şeydir,

Bunu yaşayan bilir.

Uzak durup bakanlar,

Belki mahşerde görür.', 'Bir ışık gibi parlayıp, Geçtin gözümün önünden, Hiç sebep,gerek yokken, Niçin döndün sözünden?  Biz böyle mi konuştuk, Biz böyle mi anlaştık...', ARRAY['Türk Edebiyatı','Şiir','Zafer Çağlar']::text[], 8.5, '{"poet":"Zafer Çağlar","poet_slug":"zafer-caglar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yeniden-baslayalim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilen Anlatsın', 'bilen-anlatsin-huseyin-kotan-pw2fy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yıllarca yürüdüm ardınca senin

Bana bu sevdayı, bilen anlatsın

Karardı şafağın sensiz gecenin

Bana bu sevdayı, bilen anlatsın.

Gönül sevmez ise gözler ağlar mı? 

Ayrılık acısı gönül dağlar mı? 

Yanmayan gönülden sevgi çalar mı? 

Bana bu sevdayı,  bilen anlatsın

Toz duman içinde geçiyor günler

Açmadan soluyor dalında güller

Susamış sevgiye canlar, gönüller

Bana bu sevdayı, bilen anlatsın.

Bir vefâ  aradım bülbülde ney’de

Bir sefâ aradım günde gecede

Avâre su misali geçen ömürde

Bana bu sevdayı, bilen anlatsın.

Üveys kadiriyim yaram derince

Ölümsüz güzeli sevdim gönlümce

Toprağı üstüme vermezden önce

Bana bu sevdayı, bilen anlatsın.', 'Yıllarca yürüdüm ardınca senin Bana bu sevdayı, bilen anlatsın Karardı şafağın sensiz gecenin Bana bu sevdayı, bilen anlatsın. Gönül sevmez ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Kotan']::text[], 8.5, '{"poet":"Hüseyin Kotan","poet_slug":"huseyin-kotan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bilen-anlatsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hani', 'hani-huseyin-kotan-g70d9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gönüle saplanan kama gibisin

Muhteşem libasta yama gibisin

Gözleri görmeyen âmâ gibisin

Tükenmiş mecalin kolların hani? 

Gece gündüz masivayı işledin

Ölümsüz hayatı ister düşlerdin

Bed dilinle müminleri taşlardın

Kibir tasladığın hallerin hani? 

Servetler toplayıp vermişsin sele

Oğlunu kızını kaptırdın ele

Kararmış umutlar kapılmış yele

Talana uğramış, malların hani? 

Çalım satar endam ile yürürdün

Kibirlik libasın yerde sürürdün

Uzak yakın her tarafı görürdün

Çıkmaza uğramış, yolların hani? 

Lokmayı haramı bolca yutardın

Alime arife çamur atardın

Beşe alır binbeşyüze satardın

Geçer akçe etmaz, pulların hani? 

Meyil verdin cimri ile zalime

Burun büktün iman ile ilime

Hırlamıştın kur’an ile gülüne

Söylemez doğruyu, dillerin hani? 

Ters yüz olur madalyonlar resimler

Unutulur şöhret ile isimler

Toprağa karışır nazik cisimler

Uğramaz bülbüller, güllerin hani? 

Kaderin yazısı düzdür silinmez

Evvel ahır ne olacak bilinmez

Menzile varmadan asla gülünmez

Gül benzin sararmış, alların hani? 

Mazlumlar derdine olmadın derman

Katline çıkardın bir sürü ferman

Ukbada hesabın görülür yaman

Tükenmez sandığın günlerin hani? 

Üveys kadiriyim hakkı söylerim

Aşkın menziline hedef eylerim

Gaflette geçen demi neylerim

Mevlaya açılmaz ellerin hani?', 'Gönüle saplanan kama gibisin Muhteşem libasta yama gibisin Gözleri görmeyen âmâ gibisin Tükenmiş mecalin kolların hani?  Gece gündüz masivay...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Kotan']::text[], 8.5, '{"poet":"Hüseyin Kotan","poet_slug":"huseyin-kotan","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/hani-108-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüme Mahkum', 'olume-mahkum-ziya-kara-mjr9u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yüreğim paslandı,

Sevgisizlikten.

Sana hasret,

Sana muhtaç,

Öksüzüm ben...

Beraber olamıyorsak 

Yeniden,

Ölüme mahkum,

Sana sevdalıyım ben.', 'Yüreğim paslandı, Sevgisizlikten. Sana hasret, Sana muhtaç, Öksüzüm ben... Beraber olamıyorsak  Yeniden, Ölüme mahkum, Sana sevdalıyım ben....', ARRAY['Türk Edebiyatı','Şiir','Ziya Kara']::text[], 8.5, '{"poet":"Ziya Kara","poet_slug":"ziya-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/olume-mahkum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülümse', 'gulumse-vedat-okkar-2xyif', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gülümse bütün masumiyetinle,

Tabiyat kadar doğal ve kuşlar kadar özgür gülümse,

Gülümse ki, beyazımsı bulutlar yağmura dönüşmesin,

Bahar gülüşünde saklı, gülümse ki çiçekler üşümesin,

Gülümse gülümsedikçe daha güzelsin.

Sen uyandığımda bile,

Görmeye devam ettiğim bir rüya,

Sen sarhoşluğumsun,

Ne ayılabildiğim,

Ne ayılmak istediğimsin.

Sensin meleğim canım sevgilim,

Ben bugün olduğum gibi her anımda

senleyim...', 'Gülümse bütün masumiyetinle, Tabiyat kadar doğal ve kuşlar kadar özgür gülümse, Gülümse ki, beyazımsı bulutlar yağmura dönüşmesin, Bahar gül...', ARRAY['Türk Edebiyatı','Şiir','Vedat Okkar']::text[], 8.5, '{"poet":"Vedat Okkar","poet_slug":"vedat-okkar","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gulumse-83-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonu Ne Olacak', 'sonu-ne-olacak-ziya-kara-5z3ur', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen geldin,

Bahar geldi.

Sen gittin,

Bahar bitti.

Saatler değil,

Hayat; 

Durdu duracak.

Bilmemki; 

Bu ayrılığın

Sonu ne olacak?', 'Sen geldin, Bahar geldi. Sen gittin, Bahar bitti. Saatler değil, Hayat;  Durdu duracak. Bilmemki;  Bu ayrılığın Sonu ne olacak?...', ARRAY['Türk Edebiyatı','Şiir','Ziya Kara']::text[], 8.5, '{"poet":"Ziya Kara","poet_slug":"ziya-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sonu-ne-olacak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Düşünüyorum', 'seni-dusunuyorum-elzem-altinay-yr35p', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'gözlerim kapalı seni düşünüyorum

seni düşünüyorum,

belki mutlu olmayı,belki de gözlerimin sevinç yaşlarıyla dolmasını,

belki hüzün kaplamayı,belki ağıtlar yakmayı

ama tek büyüklüğü 

seni düşünüyorum.', 'gözlerim kapalı seni düşünüyorum seni düşünüyorum, belki mutlu olmayı,belki de gözlerimin sevinç yaşlarıyla dolmasını, belki hüzün kaplamayı...', ARRAY['Türk Edebiyatı','Şiir','Elzem Altınay']::text[], 8.5, '{"poet":"Elzem Altınay","poet_slug":"elzem-altinay","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/seni-dusunuyorum-74-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorumsuz', 'yorumsuz-serap-tepedelen-95shl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yorum yok artık,hiçbir şey için

suskunluk zamanı artık

-şimdiye değin hep susan sen değil miydin? -

konuşmalar güvercin kanadındaydı bir zamanlar

onlar da uçup gittiler

yorum yok artık

bulutların ardından birer birer yittiler...

Yorum yok artık,zamanı da değil ki

ne konuşmak çözüm ne de bağırmak

öyle bir çıkmazdayız-ki sonu olmayan-

dönsen dönüş değil,çıksan çıkış değil

bir bilinmezliğe doğru gidiyoruz.

ne sen farkındasın bunun ne de ben

tüm sevgiler,aşklar,duygular-güzel olan ne varsa-

birer birer yittiler...

Geriye dönüp bakma sakın

bırak,olduğu gibi kalsın geçmiş.

tek bir sözcük varsa söylenecek eğer

tek bir şey kalmışsa geçmişten kalan

onu bari yok etme gülüm

onu bari yok etme.

yaşam devam ettikçe acısıyla tatlısıyla

alabidiğince geçerken günler

yorum yok...yorum yok...

yorumsuz tüm seviler.......

(2006,Bursa)', 'Yorum yok artık,hiçbir şey için suskunluk zamanı artık -şimdiye değin hep susan sen değil miydin? - konuşmalar güvercin kanadındaydı bir zam...', ARRAY['Türk Edebiyatı','Şiir','Serap Tepedelen']::text[], 8.5, '{"poet":"Serap Tepedelen","poet_slug":"serap-tepedelen","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yorumsuz-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülüşün parıldasın yeryüzünde', 'gulusun-parildasin-yeryuzunde-vedat-okkar-c8ich', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni görüyorum düşlerimde

Yanımdasın; 

Ellerini tutuyorum sımsıkı

Gözlerine bakıyorum sıcacık

İçim ısınıyor senin yanında.

Başımı omzuna dayıyorum; 

Sarhoş olmuş gibiyim

Başım dönüyor

Bulutların üzerinde izliyorum dünyayı

Seninle dünya o kadar güzel görünüyorki gözüme

İnanamıyorum...

Gözümü kapattığım her an yanımdasın

Çarpan kalbimin her atışındasın,

Hislerimdesin, duygularımdasın,

Hayatımsın suyumsun meleğim.

Bırak o zaman gülüşün parıldasın yeryüzünde

Güneş kıskansın, ay kıskansın sevgimizi gizlice,

Derinden içten içe 

Haykıralım dünyaya sevgimizi yüksek sesle,

Ama sessizce.

Bulutlar ağlasın,

Damlalar boşalsın gökyüzünden üzerimize,

Mutlulukla sevinç ile,

Damlalarla mutlu olalım sonsuz bir geleceğe...', 'Seni görüyorum düşlerimde Yanımdasın;  Ellerini tutuyorum sımsıkı Gözlerine bakıyorum sıcacık İçim ısınıyor senin yanında. Başımı omzuna day...', ARRAY['Türk Edebiyatı','Şiir','Vedat Okkar']::text[], 8.5, '{"poet":"Vedat Okkar","poet_slug":"vedat-okkar","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gulusun-parildasin-yeryuzunde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canimida Alsalar Senden Vazgecmem!', 'canimida-alsalar-senden-vazgecmem-yasar-gurlek-lwwva', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kestiler  yolumu  baban kardasin

Vazgec  kizimizdan vazgec dediler

Olurmu  o   benim oldu    sirdasim

Canimdan gecerim ondan vazgecmem

Ne olursa olsun vazgec dediler

Dunyayi verseniz yine  vazgecmem

Cekin silahinizi vurun! vazgecmem

Canimida  alsaniz  yine  vazgecmem

Yaşarî   harbidir  senden vazgecmen

Hasretinle seneler  gecip  gitsede

Hayalinle  yasarim senden  vazgecmem

Canimdan  gecerim senden vazgecmem

Dunyamdan gecerim  yardan  gecemem

Kendimden  gecerim  yardan gecemem

Canimdan    gecerim  yardan gecemem

Senden   vazgecmem  senden vazgecmem

27-03-2006

ROTTERDAM

HOLLANDA

Yasar  Gurlek', 'Kestiler  yolumu  baban kardasin Vazgec  kizimizdan vazgec dediler Olurmu  o   benim oldu    sirdasim Canimdan gecerim ondan vazgecmem Ne ol...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Gürlek']::text[], 8.5, '{"poet":"Yaşar Gürlek","poet_slug":"yasar-gurlek","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/canimida-alsalar-senden-vazgecmem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın toğumu', 'askin-togumu-vedat-okkar-lz04h', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir umut çiçeğimidir acaba bu gönlümde açan gelincik,

Aşkın toğumumudur ki içime sığmayan,

İplik iplik yağmuru seyredip beni gururlandıran,

Tanrım nedir bu hisleri bana yaşatan? 

Hani bir müzik çalar bir yerlerde...

Dinlersiniz usul usul

Alır götürür sizi mazinizin derinliklerine,

Yarınlarınızı unutturur...

İşte öyleyim şu an bende,

Bir ses buldum, aylardır peşinden koşuyorum,

Akustiği iyi kalbime bile, hakim olamıyorum,

Ses beni sürüklüyor, çekiyor kendine...

Büyüleyici melekler misali,

Her yerde hep o ses,

Dokunmak istiyorum dokunamıyorum.

Kollarımla sarmaya çalışıyorum,

Saramıyorum, sardığım an hiç bırakmamak için bekliyorum.

Gülüşüne bitiyorum, 

Elimde değil ben seni her gece aklımın bir köşesinde yaşıyorrum,

Ses diyor ki boşver! 

Boşver duyguları tok olan insanları,

Dinlemek istiyorum onu,

Kalabalığın arasından bir tek o sesi duyuyorum,

Onu çok seviyorum, onunda beni sevmesini istiyorum,

Bir türlü söyleyemiyorum,

Ey ses! şimdi ben sana sesleniyorum,

Bir tat veriyorsun bana ki mübala...

Öyle çınlıyorsunki kulağımda,

Aklımdaki herşey hiçbirşey oluyor.

Mutluluk gözyaşları yanaklarımı yakıyor,

Martıların kanatları, denizin dalgaları, gün batımı anlamını yitiriyor

Kendimi iyi hissetmek için onlara bakmıyorum artık,

Çünkü sensin, ruhumu, kalbimi, dünyamı aydınlatan varlık.', 'Bir umut çiçeğimidir acaba bu gönlümde açan gelincik, Aşkın toğumumudur ki içime sığmayan, İplik iplik yağmuru seyredip beni gururlandıran, ...', ARRAY['Türk Edebiyatı','Şiir','Vedat Okkar']::text[], 8.5, '{"poet":"Vedat Okkar","poet_slug":"vedat-okkar","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/askin-togumu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pamuk Tarlaları', 'pamuk-tarlalari-osman-demircan-hciqd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Güneş  ışığı  omuzları  eritiyor.

Toz  toprak  içinde,

Acılar  devşiriyor; 

Pamuk  tarlalarında  insanlar.

Dudakların  bir  ucunda  umut  bekliyor.

Bir  öpüş  ihtilal  oluyor.

Güneş  ısınıyor.

Güneşin  altın  ışıkları

Pamuk  tarlalarının  üzerinde  parlıyor.

Dağlar  küçülüyor.

Taşlar  susuyor.

İnsanlık  sese  dönüşüyor.

Haykırıyor  bir  ağızdan

Toprakları  yağmalanmış  her  halkın  kalbine.

Yoksulluk  bütün  bunlar

Yoksulluk  diyor.', 'Güneş  ışığı  omuzları  eritiyor. Toz  toprak  içinde, Acılar  devşiriyor;  Pamuk  tarlalarında  insanlar. Dudakların  bir  ucunda  umut  be...', ARRAY['Türk Edebiyatı','Şiir','Osman Demircan']::text[], 8.5, '{"poet":"Osman Demircan","poet_slug":"osman-demircan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/pamuk-tarlalari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni Bir Sevda', 'yeni-bir-sevda-mehmet-cengiz-cb77z', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'gidene kal demedim ömrümce

sevmissem  sevdim mehmet''ce

inkar etmedim hiç, güzel günlerdi

yar olmanın mutluluğu, aşkın huzuru vardı gönlümde

ve bir gün ansızın yenik düştün mecburiyetlerine

kim istedi neden istedi ayrılığı, bi önemi yok sevgili

gözler yalan söylemez, hele senin ki

sevmiyorum demişsin, gülmek geliyormuş içinden

kilo almışsın, en sevdimiz yemekleri yer olmusun

sevindim...  yalan oldugunu bildiğim  mutluluğuna

veda notun elimde, neler neler yazmışsın giderken

seksen yaşasamda, sevmem artık başkasını

gidiyorum ama, unutamam yazmışsın aşkını

son nefesinde dudakların ismimi söylüyecekmiş

söyle...

yalancıktanda olsa, bin defa söyle ayrıldığını

dilin gibi gözlerinde alışsın ayrılığa

atamamışsın o gülleri 

şimdi tazesi yok bilirim vazonda

olmayacak da asla, sende beni anla

ölümden dem vurmuşsun son satırda 

ben sende bitersem ölürüm yazıyor 

ölme be sevgili, yok günahım

arama lütfen, aratma ortak arkadaşarı

ben huzurluyum, yine bahar geldi

kırmızı güller beyaz oldu

kefene sardığın mehmet''ten yeni bir sevgili, yar doğdu

aşk var sevgi var mutluluk var gözlerimde

yanıyor yüreğim bilirim dumanı seni boğar

üzülme sırası sende 

delice bir sevda var yüreğimde

inanmıyorum ben bile kendime

tanrı lütfetti aşık oldum yine

beni seviyormuş...

sevipte terkettiğin beni

mecburiyetlere kurban verdiğin beni seviyormuş

hayallerim bıraktığım yerden devam eder oldu

yine çağrı olacak oğlumun adı

gülay diye seslenecegim kızıma 

birtek o farklı işte 

bir başka seviyor beni

tomurcuk olsada sevgisi hala yüreğinde

hapsetti beni gözleriyle

senin sevdan karaydı gözlerin gibi

onunki kahverengi dağ sanki

biliyorsun değilmi

kaderimiz ayrı ahiretimiz bir

suçlu arama kendine dön bir

ben seviyorum

sen 

al sevdan gibi şu kara gömleği giy.

26,03,2006', 'gidene kal demedim ömrümce sevmissem  sevdim mehmet''ce inkar etmedim hiç, güzel günlerdi yar olmanın mutluluğu, aşkın huzuru vardı gönlümde ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Cengiz']::text[], 8.5, '{"poet":"Mehmet Cengiz","poet_slug":"mehmet-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/yeni-bir-sevda-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutmaya Başladım', 'unutmaya-basladim-simge-ozunlu-kiad4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Teninin kokusunu unutmaya başladım,

Bana bakışını,dokunuşunu

Beni sevişini unutmaya başladım.

Bana sarılışını sonra koklayışını

Gözlerimin içine bakışını unutmaya başladım.

Dudaklarının sıcaklığını,beni öpüşünü

Sesini unutmaya başladım,

Çok korkuyorum,sarsılıyorum

Çünkü ben seni ilk defa unutmaya başladım...', 'Teninin kokusunu unutmaya başladım, Bana bakışını,dokunuşunu Beni sevişini unutmaya başladım. Bana sarılışını sonra koklayışını Gözlerimin i...', ARRAY['Türk Edebiyatı','Şiir','Simge Özünlü']::text[], 8.5, '{"poet":"Simge Özünlü","poet_slug":"simge-ozunlu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/unutmaya-basladim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İtiraf', 'i-tiraf-zafer-caglar-xqx3i', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kalbimin tek sahibi,

Sensin,başkası olamaz.

Bu aşk öyle bir aşk ki,

Asırlar geçse solamaz.

Kulak ver sesime,

Anlatıyor bak aşkımı.

Yıllar geçse bile,

Ben hala aşk şaşkını.

İyi ki çıktın karşıma,

Hemen girdin aklıma,

Sitemler etsem bile,

Ne olur bana darılma.

İnanmasan da bana,

Aşığım ben sana hala,

Duymazsan sen sesimi,

Veririm son nefesimi.', 'Kalbimin tek sahibi, Sensin,başkası olamaz. Bu aşk öyle bir aşk ki, Asırlar geçse solamaz. Kulak ver sesime, Anlatıyor bak aşkımı. Yıllar ge...', ARRAY['Türk Edebiyatı','Şiir','Zafer Çağlar']::text[], 8.5, '{"poet":"Zafer Çağlar","poet_slug":"zafer-caglar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/itiraf-113-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buluşalım bu gece gözlerden uzaklarda', 'bulusalim-bu-gece-gozlerden-uzaklarda-vedat-okkar-wlfvk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gel buluşalım bu gece gözlerden uzaklarda,

Sevmişim ben seni canımla kanımla,

Tüm duygularımla.

Bütün gün hayalin gözlerimde,

İki adım ötemdesin koşuyorum yollar bitmiyor,

Gözümden her an hayalin geçiyor,

Sarmak istiyor bu beden seni çok özlüyor.

Seninle üzülürken senin mutluluğunla yaşıyor,

Zamanım seninle iken sensiz geçiyor,

Bazense geçmek bilmiyor,

Özledikçe seviyor sevdikçe ölüyor,

Özlem dolu gecelerde sabah olmuyor.

Gel buluşalım bu gece gözden çok uzaklarda,

Mavi bir gökyüzümüz olsun uçalım seninle yanyana,

Özlemler yok olsun meleğimin yanında,

Kanatlarımızı dokundurarak uçalım mutluluğa.

Aynı gecenin sabahında gözlerimizi açalım yan yana,

Günlerimiz, gecelerimiz bir olsun daima,

Bu gece gel aşkım hayalimden gerçek dünyama,

Duygularım, hislerim her an yanında,

Sende sev aşkım beni mahsum bakışınla,

Ellerini sar aşkım benim boynuma,

Resmini kazımışım kalbimin ortasına,

Mutluluk çok yakın gecenin sabahında,

Sabah güneşinin doğması,

Aşkım Meleğim, Birtanem senin dilinin ucunda,

İki kelime söyle bana mutlu bir sonsuzluğa.', 'Gel buluşalım bu gece gözlerden uzaklarda, Sevmişim ben seni canımla kanımla, Tüm duygularımla. Bütün gün hayalin gözlerimde, İki adım ötemd...', ARRAY['Türk Edebiyatı','Şiir','Vedat Okkar']::text[], 8.5, '{"poet":"Vedat Okkar","poet_slug":"vedat-okkar","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/bulusalim-bu-gece-gozlerden-uzaklarda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '% Bul Getir %', 'bul-getir-cemile-duzgun-l6fjl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şu deli gönlümden neler çekerim

Bana,benden başka mecnun bul getir

Bu gözlerden yaş değil kan dökerim

Sana benden sağlam köle,kul getir

Aşkın ile yanar bağrım sen diye

Dilerim senden de, sönmüş kül getir

Hazine istemem! Neye yarar ki? 

Senin ellerinden bana pul getir...', 'Şu deli gönlümden neler çekerim Bana,benden başka mecnun bul getir Bu gözlerden yaş değil kan dökerim Sana benden sağlam köle,kul getir Aşkı...', ARRAY['Türk Edebiyatı','Şiir','Cemile Düzgün']::text[], 8.5, '{"poet":"Cemile Düzgün","poet_slug":"cemile-duzgun","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bul-getir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgisiz Olmuyor', 'sevgisiz-olmuyor-zafer-caglar-st9yr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir gün ansızın,

Çıktın karşıma.

Kanım kaynadı,

Sana o anda.

Beklerim her akşam,

Seni o yerde.

Gelişin çaredir,

Bendeki derde.

Bak günler geçiyor,

Sen hala yoksun,

Ben seni beklerim,

Sevgiden yoksun.

Sevgi mutluluktur,

Sevilmek hoştur.

Sevgisiz hayat,

Bil ki boştur.

Sevgisiz olmuyor,

Sevgisiz olmuyor!', 'Bir gün ansızın, Çıktın karşıma. Kanım kaynadı, Sana o anda. Beklerim her akşam, Seni o yerde. Gelişin çaredir, Bendeki derde. Bak günler ge...', ARRAY['Türk Edebiyatı','Şiir','Zafer Çağlar']::text[], 8.5, '{"poet":"Zafer Çağlar","poet_slug":"zafer-caglar","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sevgisiz-olmuyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüya Evi', 'ruya-evi-osman-demircan-xmqhw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dünyada

Büyük  bir  marazla

Büyük  bir  acıyla  yaşayacağıma

Küçücük  evimde

Sobanın  kaynattığı  suyun  sesiyle

Buğulu  camların  gizemi  içinde

Yaşamak

Yaşamak  isterim.

Bir  baba  evi  sıcaklığında

Ruhumu  ısıtarak

Bütün  gurbet  yorgunluklarını

Yağmur  sularının  önüne  katarak

Rüya  evimin  içinde

Uykuya  dalarak

Yaşamak

Yaşamak  isterim.', 'Dünyada Büyük  bir  marazla Büyük  bir  acıyla  yaşayacağıma Küçücük  evimde Sobanın  kaynattığı  suyun  sesiyle Buğulu  camların  gizemi  i...', ARRAY['Türk Edebiyatı','Şiir','Osman Demircan']::text[], 8.5, '{"poet":"Osman Demircan","poet_slug":"osman-demircan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ruya-evi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elimde Değil', 'elimde-degil-altay-taskin-prudy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'düşmüşüm yollara

ömrüm bitene kadar

yürüyeceğim patikalarda

hayat kurcalamış sarmallarımı

düşürmüş tuzağına

isteklerini yüklemiş sırtıma

benimkilere de vurulmuş pranga

gerçekleri arıyorum ayışığında', 'düşmüşüm yollara ömrüm bitene kadar yürüyeceğim patikalarda hayat kurcalamış sarmallarımı düşürmüş tuzağına isteklerini yüklemiş sırtıma ben...', ARRAY['Türk Edebiyatı','Şiir','Altay Taşkın']::text[], 8.5, '{"poet":"Altay Taşkın","poet_slug":"altay-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/elimde-degil-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayatımsın', 'hayatimsin-zafer-caglar-8wy8f', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Biz ovaları,dağları,

Gölleri,denizleri,

Beraber aştık.

Biz açlığı,tokluğu,

Kıtlığı,bolluğu,

Beraber paylaştık.

Biz sevgiyi,özlemi,

Acıyı, kederi,

Beraber yaşadık.

İlhamsın,coşkusun,

Hayat dolusun.

Tanrının lütfusun,

Sen bir umutsun.

Canımsın,kanımsın,

Büyük aşkımsın.

Gözümsün,kulağımsın,

Sen hayatımsın.', 'Biz ovaları,dağları, Gölleri,denizleri, Beraber aştık. Biz açlığı,tokluğu, Kıtlığı,bolluğu, Beraber paylaştık. Biz sevgiyi,özlemi, Acıyı, ke...', ARRAY['Türk Edebiyatı','Şiir','Zafer Çağlar']::text[], 8.5, '{"poet":"Zafer Çağlar","poet_slug":"zafer-caglar","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hayatimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana bakmak', 'sana-bakmak-vedat-okkar-fyje0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sana bakmak ruhuma nakış gibi işlemek sevdayı,

Gözyaşını hissetmek doyasıya ruhumun derinliğinde,

Aşık olmak demek bir anlamda sana bakmak,

Acıyı dindirmek derdi bitirmek yaşamak demek kısaca,

Ve sana bakmak o kadar zorki kaybolurcasına içinde,

Sevdanın türküsünü dinlemek sinsice gizlice,

Habersiz olmak demek hayatın cilvesinde,

Yanlız sana bağlanmak demek sana bakmak bir an bile,

Nasılsa mehtapta yıldızları izlemek uzaktan uzağa,

Nasılsa yakomozun verdiği pırıltılar sonsuzca,

Sana bakmak demek onun gibi bir şey işte,

Tarifi mümkün olmauan duygular dolar içime.

Naylon ayakkabılı çocuğun kunduraya özlemiydi sana olan özlemim,

Her gece dizmde uyuttuğum hayallere masallar anlatırım,

İçinde hep sen olan,

Kimi zaman pamuk prenses olurdun,

Kimi zaman elmayı veren cadı,

Ama değişmeyen bir şey vardı,

Hep güzeldin hep beyazdı melek yüzün.

Ve geceler sabaha hasret yaşarken, aradığım her satıra seni anlattım,

Bir şarkı duyarım bir yerlerde,

Senin sesini duyarmışcasına yaşarım o anı  senin yanında,

Mutluluktan uzakların daha uzaklarına,

Büyük zaferkerin nur tabakalarına,

Seni yazdım ebemkuşaklarına.

Birden gökten yağmurlar boşalır damla damla,

Koşarım sağa sola damlaları yakalarım düşmesinler diye yere,

Damlaları toplarım yüreğimle,

Yüreğimdeki güzelliğin aynası olur eşsizce,

Su hayattır kıymetlidir, nimettir insana,

Yüreğimdeki güzelliktir su aynı zamanda,

Su gibi kıymetlisin değerlisin eşsiz meleğim...', 'Sana bakmak ruhuma nakış gibi işlemek sevdayı, Gözyaşını hissetmek doyasıya ruhumun derinliğinde, Aşık olmak demek bir anlamda sana bakmak, ...', ARRAY['Türk Edebiyatı','Şiir','Vedat Okkar']::text[], 8.5, '{"poet":"Vedat Okkar","poet_slug":"vedat-okkar","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/sana-bakmak-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hadi', 'hadi-sumer-kucuk-uvcqe', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gecelerin

Sabah olmasını beklersek

Çok geç olur

Hadi 

Kalk gidelim 

Dosta...', 'Gecelerin Sabah olmasını beklersek Çok geç olur Hadi  Kalk gidelim  Dosta......', ARRAY['Türk Edebiyatı','Şiir','Sümer Küçük']::text[], 8.5, '{"poet":"Sümer Küçük","poet_slug":"sumer-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/hadi-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizim (Hoşkalın Canlar)', 'bizim-hoskalin-canlar-vedat-koparan-i11zk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Adımın anlamı yoktu anlamsızların yanında

Andı vuruluşumuz her vuruluşta çoğalmaya

Yaşamak isterken yaşayamadıklarımızda

Andı adım adının yanında unutulmazlığa

Adımız yazıldı isimsizler mezarlığının yanına

Sevmelerimiz an ölümlerimiz bir adım aşkla

Ölümsüzlüğü sardım bir sigara içimi satırlara

Her şey uçar savrulur kül kalan ölümsüz ruhta

Tarihte kayıp bir kent Artemis sular altında 

Yandı iç denizlerim gök taşları çarpa çarpa

Kayboldum bitimsiz gözlerinin deryasında

Bu memleket bu aşk canda can bu kavga

Bizim

Bitmedi..

Vedat Koparan 27.03.206

İşte geldik bir varız bir yok

az zamana neleri sığdırdık neleri sığdırabilirdik bilemiyorum 

olumlu bir iz bırakabilirsek ne mutlu

Her şey istemlerinizin güzelliğiyle olsun 

şiir sesiniz hiç susmasın 

dostlukla sevgiyle sağlıcakla hoşkalın', 'Adımın anlamı yoktu anlamsızların yanında Andı vuruluşumuz her vuruluşta çoğalmaya Yaşamak isterken yaşayamadıklarımızda Andı adım adının ya...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bizim-hoskalin-canlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zevk', 'zevk-sumer-kucuk-bmkyu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Evleri  var

İki  katlı

Rengide  mor

Sonra  yeşile  boyadılar

Sonra  sarı

Şimdide  maviye  boyuyorlar

Boyarla  ya

Zevk  meselesi.', 'Evleri  var İki  katlı Rengide  mor Sonra  yeşile  boyadılar Sonra  sarı Şimdide  maviye  boyuyorlar Boyarla  ya Zevk  meselesi....', ARRAY['Türk Edebiyatı','Şiir','Sümer Küçük']::text[], 8.5, '{"poet":"Sümer Küçük","poet_slug":"sumer-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/zevk-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnat Oldu Yaşamak', 'i-nat-oldu-yasamak-yurdagul-ozay-agcw9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Öyle geceler vardır ki korkuyla beslenen

Ölüme yakın hem de çok yakın

Öyle günler vardır ki saatlerin saatlere benzemediği

Çaresizliğin acımasızlığın dişlerini geçirdiği

Hele de öyle anlar vardır ki

Perişanlığın bin bir çeşidinin sergilendiği

Onlar umut etmeyi

Hiç ama hiç öğrenemediler

Yitip gitmişlerdi acılarla yüklü

Sanki hayatın dışında yaşarlardı

Kederden ağlar gerilmiş

Pusu kurulmuştu yarınlarına

Kadın zorla hazırlardı kendini

Yaşamdakine rolüne

Gülüşlerini ütüler koyardı gönlünün raflarına

Bir ırmak gibi akarken gecelere

Dualarla uyuturdu yüreğini

Çocuk çaresizliğin perişanlığını taşırdı

Gözlerinde acının en alıcı şekli bulunurdu

Yokluğun yoksulluğun göstergesiydi sanki

Sevinçleri bile çekingendi

Bıçak açmazdı suskunluğunu

Adam işsiz güçsüz

Her sabah takılır giderdi ayaklarının peşine

Her gece umutsuzluğu çekerdi sinesine

Kahırla isyanla dokurdu zamanı

Oysa sevdikleri uğruna yaşamı göze almıştı

Ama hayat ağacının hangi dalına konduysa

Taşımadı dalları onu

Ve bozuluverdi bir gün kurulu düzen

İçindeki o boşluk giderek büyüdü

Ve sürükledi arkasından

Deli hırçın bir geceydi

Adam kendi eliyle kurdu darağacını

Ve sonrasızlığın ipiyle asıldı

Hayat artık ölümün kollarındaydı

Susan geceydi susan  umutlardı

Susan gelmeyi bilmeyen yarınlardı

Ve bir fişekliğe dizilmiş gibi

Karanlığa karışan çığlıklardı

Acıdan ibaret bir beden asılmıştı

Önce kadın gördü

Boşlukta sallanan bedeni

Bir sancı girdi yüreğine yıkımlar geçti içinden

Sonsuza uzanan ayrılıklar geçti

Ve gece parçaladı sahip olduğu her şeyi

Haykırışlar dalga dalga yayıldı duvarlara

Çocuk duymak istemedi

Karanlıkları yırtan o sesi

Ne çığlığa benziyordu ne ağlamaya ne de inlemeye

Kadın kazıdı yüreğine sivri bir bıçakla acıyı

Ve yanına öfkeyi yerleştirdi

Yaşamak inat oldu artık dedi

Bu yaşama karşı 

Açlığa sefalete ve de yokluğa karşı

Sığınmak istemiyordu çaresizliğin kollarına

Hayatı yeniden yoğuracaktı

Umuda yeniden sarılacaktı

Kollarına aldığı oğluna sıkıca sarıldı

Gözlerinin derinliğine iyice baktı

Kendi için değilse de oğlu için yaşayacaktı

Arkasındaki boşluğu son kez döndü

Acıyı iki kat edip

Hüznü kendi çığlığında bıraktı', 'Öyle geceler vardır ki korkuyla beslenen Ölüme yakın hem de çok yakın Öyle günler vardır ki saatlerin saatlere benzemediği Çaresizliğin acım...', ARRAY['Türk Edebiyatı','Şiir','Yurdagül Özay']::text[], 8.5, '{"poet":"Yurdagül Özay","poet_slug":"yurdagul-ozay","theme":"Türk Şiiri","is_hero":false,"total_lines":64,"source_url":"https://www.antoloji.com/inat-oldu-yasamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
