INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölen Son Kişi', 'olen-son-kisi-haluk-ugurluoglu-u14vt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'yağmurun gölgesinde sığındım bugün

ağaçlar küfrettiler

uzakta bir fa minör fısıldıyor

daha da beter sonra

alay ettiler, zalimler, bilmiyorlar...

amansız gelen medcezirler, yüreğime

dur götürme yanlızlığımı

can çekişimi izle, bedbaht

rüzgarsız açılan yelken

son nefesini verdi sigaram

kırıldı, tuz buz ettiler

ah bi bilseler...

beynime çekilen prangalar

muammalar arasında kayboldum galiba

''Seni Seviyorum'' du eskiden

çığlığım ''ney''miş anlayamadım, ağlıyorum

son bir mermi kalmış, nereye

namussuzlar

bunu biliyorlar..', 'yağmurun gölgesinde sığındım bugün ağaçlar küfrettiler uzakta bir fa minör fısıldıyor daha da beter sonra alay ettiler, zalimler, bilmiyorla...', ARRAY['Türk Edebiyatı','Şiir','Haluk Uğurluoğlu']::text[], 8.5, '{"poet":"Haluk Uğurluoğlu","poet_slug":"haluk-ugurluoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/olen-son-kisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüznü Hayat', 'huznu-hayat-gultekin-toga-pifh2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İstila görmüsşüz yadırgı sesle,

Aşıklı,ozanlı yaşayamadık..

Fikir,düşünceyi sundular tasla,

Akıllı, izanlı yaşayamadık

Ya tek sola baktık,ya yalniz sağa,

Ufanıp da dönemedik toprağa,

Köpek balıkları takıldı ağa,

Hamsili, sazanlı yağayamadık..

Ateş tutuşmadı,beyhude tütdü,

Hakikati boğdu,huzuru yutdu,

Kalıplar bünyeyi anarşist etti,

İstedik, düzenli yaşayamadık.

Keyfi kaçar ondan düşman doğruna,

Üç köpeğin sefasının uğruna,

Nifak girdi,birliğimin bağrına,

Oğullu,kızanlı yaşayamadık..

Gülene ağladı,ağlarken güldü,

Sıyrılıp vicdandan gergide kaldı,

Duygulara bile zaptırak geldi,

Sevinçli,hüzünlü yaşayamadık,

Sentezi,mecburi gurbet meskeni

Hak´tan gayri bulmaz kalbin teskini

Salip ne anlasin gönül aşkını,

Bayraklı,Ezanlı yaşayamadık..', 'İstila görmüsşüz yadırgı sesle, Aşıklı,ozanlı yaşayamadık.. Fikir,düşünceyi sundular tasla, Akıllı, izanlı yaşayamadık Ya tek sola baktık,ya...', ARRAY['Türk Edebiyatı','Şiir','Gültekin Toga']::text[], 8.5, '{"poet":"Gültekin Toga","poet_slug":"gultekin-toga","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/huznu-hayat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Abbâs bin UBÂDE (RA)', 'abb-s-bin-ub-de-ra-abdullah-yasar-erdogan-jy6kz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '(Uhud şehitlerinden, Can Şehidlerim: 10) 

    Abbâs  bin  UBÂDE  (RA) 

Adına; Abbâs bin Ubâde bin Nadle

El-Ensâri  El-Hazreci denilmekte,

Akâbe bey’atı’nda olan sahabe,

Medineli bahadır Ubâde’m benim.

Akâbe’de Hazreçlilere bey’at der,

Medine halkını Hakka davet eder,

Abbâs, kayıtsız şartsız itaat ister,

Medineli cengâver Ubâde’m benim.

Mekke’de Peygamber yanında kalmıştı,

“Medineli Muhacir” diye anıldı,

O, Peygamberden önce hicret yapmıştı,

Yiğit Medineli Muhacir’im benim.

Medine’de kardeşlik tesis olmuştu,

Osman bin Maz’un kardeş ilan olundu,

O Abbâs bin Ubâde, Bedir’de yoktu,

Medineli bahadır Ubâde’m benim.

Uhud Savaşı’na katılmıştı o yiğit,

Dağılan orduya okumuştu beyit,

Abbâs, düşmana saldırıp oldu şehid,

Medineli cengâver Ubâde’m benim.

Peygamber aşkıyla vurmuştu düşmana,

Abbâs, düşmanı uğratmıştı bozguna,

Şehid olarak göçtü Rabb-i Rahmana,

Selamlar olsun sana yiğit Ubâde’m.

Şair: Abdullah Yaşar Erdoğan.', '(Uhud şehitlerinden, Can Şehidlerim: 10)      Abbâs  bin  UBÂDE  (RA)  Adına; Abbâs bin Ubâde bin Nadle El-Ensâri  El-Hazreci denilmekte, Ak...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yaşar Erdoğan']::text[], 8.5, '{"poet":"Abdullah Yaşar Erdoğan","poet_slug":"abdullah-yasar-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/abbas-bin-ubade-ra-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul', 'i-stanbul-zafer-caglar-k3dvx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yaklaşık üçyüz milenyum önce,

yerleşmeye başlar insanlar,

bugünkü İstanbul bölgesine.

Zaman hızla akar geçer,

uygarlıklar gelişir,

ve gelinir 15. yüzyıla.

Güçlü Osmanlı İmparatorluğu,

azmeder İstanbul''u almaya; 

elli üç gün süren kuşatmadan sonra,

katar İstanbul''u Osmanlı topraklarına.

Yaşayarak imparatorluğun iyi ve kötü günlerini,

gelir İstanbul 20.yüzyıla.

Demirleyince İstanbul limanı''na işgalci gemiler,

Mustafa Kemal tereddüt etmeden şöyle der:

''''Geldikleri gibi gidecekler! ''''

Gerçekten öyle olmadı mı? 

Geldikleri gibi gitmediler mi? 

Cumhuriyet döneminde,

başlar İstanbul yeniden yapılanmaya; 

ekonomi dahil,her alanda toparlanmaya.

İnşa edilir yeni yollar ve binalar,

kültür merkezleri,hanlar ve limanlar.

Ancak, birşey hiç değişmez İstanbu''da; 

tarih ve güzellik dolu doğa! 

Efsanevi Haliç büyüler herkesi,

Boğazı seyredenin gelir keyfi,neşesi.

Bekledi boğazı yıllarca iki hisar,

Asırlar geçse de hala ayaktalar.

Kabataş ve karşıda Kız Kulesi; 

sanki bir güzellik abidesi.

Birer sanat eseri Sultan Ahmet ve Ayasofya,

gurur kaynağı olacaktır,dünya durdukça.

Ünlüdür İstanbul''un sinagogları,kiliseleri,

sevgiyle kucaklar İstanbul tüm dinleri.

Yaşıyor İstanbul''da yüzbinlerce yabancı,

Eder İstanbul her geleni baş tacı.

Sultan Ahmet Meydanı,Dikilitaş,

 geçmişi andıkça gelir gözümüzden yaş.

Yerebatan Sarayı,Gülhane Parkı,

tüm bunlar İstanbul farkı.

Kulelerden Beyazıt ve Galata,

baktıkça bağlıyor insanı hayata.

Görünce Marmara''dan karayı,

dimdik durur karşımızda Topkapı Sarayı; 

hissettirir bize gücü,kuvveti,

hatırlatarak Fatih Sultan Mehmet''i.

Unutmayalım surlarını İstanbul''un,

görmesi gerek onları yaşayan her kulun.

Tarih kokar İstanbul''un sur içi,sur dışı,

bir başka güzeldir İstanbul''un yazı,kışı.

Yaşamak gerek İstanbul''da ilkbaharı,sonbaharı,

ayrı güzeldir İstanbul''un yağmuru ve karı.

Sayısız aşklar görmüştür İstanbul,

ama İstanbul aşkı için olunur köle kul.

Ebedi olmasını istiyorsak bu aşkın eğer,

sahip çıkalım İstanbul''a hep beraber.', 'Yaklaşık üçyüz milenyum önce, yerleşmeye başlar insanlar, bugünkü İstanbul bölgesine. Zaman hızla akar geçer, uygarlıklar gelişir, ve gelini...', ARRAY['Türk Edebiyatı','Şiir','Zafer Çağlar']::text[], 8.5, '{"poet":"Zafer Çağlar","poet_slug":"zafer-caglar","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/istanbul-435-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duy', 'duy-abdullah-oral-xowz3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'DUY

Yasak koymuşlar özgürlük kuşunun kanatlarına

Mavileri tutuklanmış

Bir gök çizmişler albatroslara

Gün doğumunun vurulduğu yerde

Çatlamış bölünmüş yüreği bulutların

Kimyasal gazlar soluğunu kesmiş rüzgarın

Kendi göğümüzdeki hayatın

Kanı donduran ayazı dökülmekte

                On dokuz aralık sabahına,Duy

Gayrı külrengi bulutlar ıslatmaz

Ölüm odalarına sürüyorlar

Dağlara sığmayan yüreğimi.

Dört duvardan öte yaşam yok

Güneşimi çalıyorlar

Ayın şavkı düşmez gözlerime

Kimse bilmez nasıl öldüğümü,Duy

Bizden olmayanlar kuşatmışlar sokaklarımızı

Onurlu bir yaşamın görkemine düştük diye

Kanatıyorlar ağrılarımı.

Bir başka baharı örgütlüyor umut

Koklamaktayım baharı

Polensiz döllenmekte çiçeklerim

Yine tomurcukta dalım Duy 

Sokaklarda adam sende cinlik

Kaldırımlar boyu duyarsızlık. 

Gün ışığına hasret yüzlere

Kap kapa haykıran peçe gibi asılmış utanç.

Şimdi

     kendinden olmayan 

            renklerin ardından koşanlar

                                    yaşamakta

soluğumu yitirmiş sokaklarda,Duy

Ar damarsız bir vaktindeyiz zamanın

Fitilsiz ateşlenir anaların yüreğinde barut

Rüzgardan yine haber yok

Gün doğumuyla tutuklanmış seher yeli

Dağlar duymaz çığlığımı

Çıplak duvarlar gelir üstüme

Sessizce boğar

Dudaklarımdan dökülür son nefesim

Bir tek isyanım kalır yarına 

Yeniden örgütlemek için Alanları Duy..

                              Kanayan dağlar adlı kitabımdan', 'DUY Yasak koymuşlar özgürlük kuşunun kanatlarına Mavileri tutuklanmış Bir gök çizmişler albatroslara Gün doğumunun vurulduğu yerde Çatlamış ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Oral']::text[], 8.5, '{"poet":"Abdullah Oral","poet_slug":"abdullah-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/duy-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duy 1', 'duy-1-abdullah-oral-sbh6p', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'DUY 1

Duy demekle duyulur mu çığlık? 

Kulaklar duyma özürlüyse

Ve görme özürlüyse yürekler……. 

Ama hep sağır-ve duyarsız

Ama hep kör- kalmayacak,Halkım. 

Duyacak elbette sesini 

Kendisi  için vuruşanın..

Gün gelir

Yanık bir türkü sıcaklığında kucaklanır

Sevinci ve inancı halkı için savaşanın

İşçi tulumuyla halay başında

Gün gelir

Devrim kıvılcımını alevlendiren 

Nasırlı ellerde bayrak olur direnç

Kızıla kesilir hayat

Sınırsız bir dünyayla kucaklar 

Sınıfsız toklum bilincini

Yakındır çatlamaya yüz tutacak 

Kanla sulanmış toprağımda tohum.Duyyyy...

                        Aralık 2001 Kanayan dağlar adlı kitabımdan.', 'DUY 1 Duy demekle duyulur mu çığlık?  Kulaklar duyma özürlüyse Ve görme özürlüyse yürekler…….  Ama hep sağır-ve duyarsız Ama hep kör- kalmay...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Oral']::text[], 8.5, '{"poet":"Abdullah Oral","poet_slug":"abdullah-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/duy-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evrene sığmıyor yüreğim', 'evrene-sigmiyor-yuregim-abdullah-oral-j73z5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'EVRENE SIĞMIYOR YÜREĞİM

Örselenmiş duyguların 

Sevecenliğine koşar ateşe düşen yüreğim

En aptal durağanlığındayım zamanın

Evreni sığdırmaya çalışıyorum 

Evrene sığmayan yüreğime

Yaban çiçeklerini öperin toprak ananın

Takılıp kalmışım

Yeni doğan bebelerin ilk gülüşlerine

Gönül defterimde sevda türküsü

Aşka düşen gözlerimde yağmur

Özgürlüğüm kanat çırpmakta avuçlarımda

Rüzgarın tarifsiz uğultuları

Çarpışır sevgi bulutlarımda

Kalkar bakarım yücesinden dağların

Kokusunu içime çekerek bütün çiçeklerin

Aşka susuzluğumu gidermekteyim evrende.

Kızılını yüreğime koyuyorum güneşin

Sönük kalıyor aşkın kıvılcımından

Sonra eriyip tükeniyorum damla! damla

Koca bir evreni sığdırayım derken yüreğime

Boğulmaktayım aşkın alevli Nehir''inde….

                              Kanayan dağlar adlı kitabımdan', 'EVRENE SIĞMIYOR YÜREĞİM Örselenmiş duyguların  Sevecenliğine koşar ateşe düşen yüreğim En aptal durağanlığındayım zamanın Evreni sığdırmaya ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Oral']::text[], 8.5, '{"poet":"Abdullah Oral","poet_slug":"abdullah-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/evrene-sigmiyor-yuregim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül', 'gul-abdullah-oral-ci4kk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'GÜL

Doğan bir güneş yansımakta 

Umutsuz yaşantıların ortasından

Bir gül

Yılgınlığın içinden umuda duran sevdam

Feri gitmiş gözlere düşen bir ışık

Gül ki

Gülen gözlerinle aydınlansın dünya

Bak nasıl kaçışacak 

Örümcek ağında saklanan böcekler

 Gül

        umut ol

            yürek ol

               feri gitmiş gözlere ışık ol

Gül ki 

 Kırılsın yılgınlığın paslı zinciri

Dişlemesin kelepçeler bileklerimizi

Gül

Durulsun boz bulanık sular

Balıklar oynaşsın yosun tutmuş taşlarda

      Ne zıpkın olsun 

               Ne olta

Avlamasın büyük balıklar küçük balıkları.

Bir gül ki 

Gülüşünle yıkılsın

Özgürlüğe örülmüş duvarlar

Gülüşün kızıla boyasın şafakları

Bir gül ki kızıl saçlım

Gülüşünden güller dereyim

Gelecek aydınlık günlere

Onların gülüşlerinde saklıydı ülkemin aydınlığı.

                                 Kanayan dağlar adlı kitabımdan.', 'GÜL Doğan bir güneş yansımakta  Umutsuz yaşantıların ortasından Bir gül Yılgınlığın içinden umuda duran sevdam Feri gitmiş gözlere düşen bir...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Oral']::text[], 8.5, '{"poet":"Abdullah Oral","poet_slug":"abdullah-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/gul-126-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Firar', 'firar-abdullah-oral-eqjvv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'FİRAR

Gidişinle 

Kırılan duyguları

 Hapsettim yüreğime

Asırları tırnaklayıp 

kanattım ardından.

şimdi hiçbir şey acıtmıyor düşlerimi.

Gaybana  gecelere astım gözlerimi de 

Unuttu ardından dökülmeyi.

Duyuyor musun

Çığlığımın  yansımasını seher yelinden

Gönlüme vurdum ya zincire

Sesime zincir vuramadım.

Biliyorum bir daha dönmeyeceksin

Dönsen de sevmeyeceksin

İki ayrı yabancı olacağız

Bir daha beni tanımayacaksın

Hani yüreğimi zincire vurdun dedim ya yalan

O senin terk edip gittiğin günden beri

                                          hala firarda.

Ben seni yüreğimden hiç söküp atamadım ki..

                                    Kanayan dağlar adlı kitabımdan.', 'FİRAR Gidişinle  Kırılan duyguları  Hapsettim yüreğime Asırları tırnaklayıp  kanattım ardından. şimdi hiçbir şey acıtmıyor düşlerimi. Gayban...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Oral']::text[], 8.5, '{"poet":"Abdullah Oral","poet_slug":"abdullah-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/firar-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Şey', 'her-sey-abdullah-oral-vnh5r', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'HER ŞEY 

Bir sorudur aslında..

Kirpiğin kaşına düşünce güzel

Kanayan gözlerin yaşı silinmez

Bir başka sevda bu kanar durulmaz

Yar gelip yaşımı siler,mi? 

Düşmesin gözüne gönül perdesi

Görünmez gittiğin yolun ötesi

Aşığın yüreği çoban ateşi

Gün olur küllenir söner,mi? 

Aşka düşen bilir aşkın narını

Bal eder acıyı görmez yarını

Almıştır dünyadan gönül karını

Zararını karla böler,mi? 

Aşığın gözünden ışığı seçin

Yol edip ummanı sıratı geçin

Sorsalar Ferhat! a şirini için

Aşk ile dağları deler,mi? 

Kanayan yarayı bulunmaz saran

Yanarımda aşla dilenmem aman

O gün gelip kabre girdiğim zaman

Dostlar bizi bellekten siler,mi? ? ? ? _', 'HER ŞEY  Bir sorudur aslında.. Kirpiğin kaşına düşünce güzel Kanayan gözlerin yaşı silinmez Bir başka sevda bu kanar durulmaz Yar gelip yaşı...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Oral']::text[], 8.5, '{"poet":"Abdullah Oral","poet_slug":"abdullah-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/her-sey-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Hatıra', 'bir-hatira-omer-ziya-soyyigit-2kz2f', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şenledik bir haneyi

Vaynara''nın içinde

Kimsesiz yanlız kaldık

Garip kuş biçiminde

Yattık sabaha kadar

Pantalon çıkarmadan

Öldürdü bizi soğuk

Titredik hiç durmadan

Serilmiş yere ottan

Ve çalıdan bir yatak

Üstümüze atılmış

Bir yorgan saçak saçak

Rüzgar durmadan eser

Sanki her taraf fora

Böyle bilmiş olsaydık

Razıydık bir ahıra

Yapmışız kendimize

Şikayet edemeyiz

Bir akşam daha vardır

Bırakıp gidemeyiz

Bitmiyor Ömer senin

Yaptığın delilikler

Maziye mi benzettin

Dostların seni bekler

5 Eylül 1958 Vaynara', 'Şenledik bir haneyi Vaynara''nın içinde Kimsesiz yanlız kaldık Garip kuş biçiminde Yattık sabaha kadar Pantalon çıkarmadan Öldürdü bizi soğuk...', ARRAY['Türk Edebiyatı','Şiir','Ömer Ziya Soyyiğit']::text[], 8.5, '{"poet":"Ömer Ziya Soyyiğit","poet_slug":"omer-ziya-soyyigit","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bir-hatira-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül', 'gonul-omer-ziya-soyyigit-80z2r', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sarpsın kayalardan, azgın sulardan

Uzun ovalardan, karlı dağlardan

Taşmış nehirlerden, akan sulardan

Bir yaz yağmurundan coşkunsun gönül

Dağları bürümüş duman gibisin

Garip garip öten bülbül gibisin

Ilgıt ılgıt esen yeller gibisin

Seherde ağlayan baykuşsun gönül

Almışsın rengini dağ çiçeğinden

Geçmişsin madurun düz eteğinden

İçmişsin suların gözbebeğinden

Cümle dertten azat olmuşsun gönül

Gonca güller gibi saf ve naziksin

Bir karanfil gibi al ve cazipsin

Mısra-i aşk yazan dertli katipsin

Ezeli ervahta aşıksın gönül

Çizilmiş kaderin, artık bozulmaz

Dolmuş defterlerin, yazı yazılmaz

Derindir mezarın, kolay kazılmaz

Çokcadır sualin, ölünce gönül

Aşık olmuş sana nice simalar

Kimi güler kimi durmadan ağlar

Günahını çekmez en yüce dağlar

Suçlusun, tevbe et durmadan gönül

Dumanlı dağları aşmak istersin

Aşıp yaylalarda koşmak istersin

Soğuk sularından tatmak istersin

Çekilirmi derdin bilemem gönül

Küçüksün üç aylık tıfıl yavrudan

Eskisin doksanlık bir ihtiyardan

Mesutsun bilirim en bahtiyardan

Fakat gülmediğin malumdur gönül

Ömer Ziya derler senin adına

Tatmadın dünyanın bir kez tadına

Koşmadı dostların hiç imdadına

Yanlız kaldın cihan içinde gönül

29 Temmuz 1958 Goga', 'Sarpsın kayalardan, azgın sulardan Uzun ovalardan, karlı dağlardan Taşmış nehirlerden, akan sulardan Bir yaz yağmurundan coşkunsun gönül Dağ...', ARRAY['Türk Edebiyatı','Şiir','Ömer Ziya Soyyiğit']::text[], 8.5, '{"poet":"Ömer Ziya Soyyiğit","poet_slug":"omer-ziya-soyyigit","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/gonul-159-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşündünmü?', 'dusundunmu-omer-ziya-soyyigit-gf0oz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Baktınmı yatıyorken musallada mevtaya

Düşündünmü kardeşim hayatının sonunu

Bağladınmı gönlünü ihlas ile Mevlaya

Düşündünmü kardeşim hayatının sonunu

Hazırlığın varmıdır kara yere girmeye

Münkir nekire varıp cevabını vermeye

Kefeninden başka bir örtün varmı sermeye

Düşündünmü kardeşim hayatının sonunu

Hoşnut mu komşuların senden biliyormusun

Dertlilerin derdini gidip soruyormusun

Yetim gözyaşlarını acep siliyormusun

Düşündünmü kardeşim hayatının sonunu

Bir hayırlı evladın varmı seni anacak

Bıraktınmı mescide bir kandil, hep yanacak

Kabirden kalkdığında kim elinden tutacak

Düşündünmü kardeşim hayatının sonunu

Hesabını yaptınmı orada yapılmadan

Tarttınmı amalini, mahşerde tartılmadan

Ölüm zevkin tattınmı burda, zebun olmadan

Düşündünmü kardeşim hayatının sonunu

Ziya önce kendine bu öğüdü versene

Kurtulup bu teşvişten can evine girsene

Varlığını severek mürşidine versene

Düşündünmü kardeşim hayatının sonunu

13 Mayıs 1981', 'Baktınmı yatıyorken musallada mevtaya Düşündünmü kardeşim hayatının sonunu Bağladınmı gönlünü ihlas ile Mevlaya Düşündünmü kardeşim hayatını...', ARRAY['Türk Edebiyatı','Şiir','Ömer Ziya Soyyiğit']::text[], 8.5, '{"poet":"Ömer Ziya Soyyiğit","poet_slug":"omer-ziya-soyyigit","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/dusundunmu-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Gittiğinden Beri', 'sen-gittiginden-beri-sebnem-ezik-yk7i8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen gittiğinden beri

Bir solukda ömür bitti

Tükendim bu şehrin

Kaldırımlarında

Dünlerin hayrı yok ki

Yarınlarıma

Umutlarım yetim

Düşler zamanında

Kaç sevda geçti

Bu şehrin sokaklarında

Sonrası alıp başını gitti

Buruk……Nemli……

Ben kaçıncıyım bilinmez

Puslu hatıralarda

Sen gittiğinden beri

Göz kırpan aşklara

Kaçamak gönlüm

Soruyor şimdi

Hata nerde

Sen pişman ben pişman

Boşa geçen ömre

Güller küs dikenine

Bir yanımda hayat

Bir yanımda ölüm

Bense tam orta yerinde

Fesliyenleri bile

Sulamaz oldum

Sararıp soldular

Kokuları yok

Eski Yaz Bahçelerinde

Sen gittiğinden beri

Kaldırdım sevdamı

Tozlu raflara

Sevgileri rehin

Sende bıraktım', 'Sen gittiğinden beri Bir solukda ömür bitti Tükendim bu şehrin Kaldırımlarında Dünlerin hayrı yok ki Yarınlarıma Umutlarım yetim Düşler zama...', ARRAY['Türk Edebiyatı','Şiir','Şebnem Ezik']::text[], 8.5, '{"poet":"Şebnem Ezik","poet_slug":"sebnem-ezik","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/sen-gittiginden-beri-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neyleyeyim', 'neyleyeyim-omer-ziya-soyyigit-gon1k', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yolum düştü sarp dağlara

Önüm duman neyleyeyim

Şaşırdım kaldım ortada

Hızır gelmez neyleyeyim

Bilirim dünya fanidir

Muhacirler mekanıdır

Cevru cefa membaıdır

Talihim yok neyleyeyim

İlkbaharda yeşillendim

Yaz gelince çiçeklendim

Sonbaharda delilendim

Kış gelecek neyleyeyim

Çok ağladım gülemedim

Göz yaşımı silemedim

Muradıma eremedim

Ecel geldi neyleyeyim

Yazılan gelirmiş başa

Bunca emel gitti boşa

Ölme sevdiğim çok yaşa

Öl diyemem neyleyeyim

Hayal oldu geçen günler

Heba oldu çok seneler

Serab oldu sevgililer

Göremedim neyleyeyim

Ateşim söndü yanarken

Kurudu yaşım akarken

Hüngür hüngür ben ağlarken

Eller güldü neyleyeyim

Çaresiz kaldım neyleyim

Ne okuyup ne söyleyim

Ah ederek inleyeyim

Kurtuluş yok neyleyeyim

Ötme bülbül garip garip

Ne anlarsın bağrım delip

Sormadı halim yar gelip

Yaram derin neyleyeyim

Sarardı soldu yaprağım

Gençliğimde geçti çağım

Kalem buldum yazacağım

Sabredemem neyleyeyim

Görmedim kimseden vefa

Nedir bilmem zevk-u safa

Öğrendiğim cevr-u cefa

Oldu benim neyleyeyim

Heder oldu çeyrek asır

Adete derde münhasır

Ömer''e Mevlası basır

Masıvayı neyleyeyim

13 Ekim 1958 Goga (eski evin odası)', 'Yolum düştü sarp dağlara Önüm duman neyleyeyim Şaşırdım kaldım ortada Hızır gelmez neyleyeyim Bilirim dünya fanidir Muhacirler mekanıdır Cev...', ARRAY['Türk Edebiyatı','Şiir','Ömer Ziya Soyyiğit']::text[], 8.5, '{"poet":"Ömer Ziya Soyyiğit","poet_slug":"omer-ziya-soyyigit","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/neyleyeyim-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rubailer…..VIII', 'rubailer-viii-sevinc-kavuk-vrzrh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Haktır hep kazandıran, haklılık değil

Bedelimi biçmek de saana hak değil

Ocak 1996', 'Haktır hep kazandıran, haklılık değil Bedelimi biçmek de saana hak değil Ocak 1996...', ARRAY['Türk Edebiyatı','Şiir','Sevinç Kavuk']::text[], 8.5, '{"poet":"Sevinç Kavuk","poet_slug":"sevinc-kavuk","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/rubailer-viii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstek', 'i-stek-omer-ziya-soyyigit-frrmp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gönül afrikada gezmek istiyor

Fakat gitmek için yollar çok uzak

Atlas okyanusda yüzmek istiyor

Lazım ona dört motorlu bir uçak

Kovboy olup Meksikadan Teksasa

At koştursam dinlenmeden günlerce

Arkam sıra koşup gelse vahşiler

Ok atsalar at üstünde, binlerce

Ceronimo önden kesse yolumu

Adamları sağdan soldan bitseler

Bu halimi haber alsa şef koçis

Apaçiler imdadıma gelseler

Korsan olsam akdenizde hükmetsem

Gemilerim yelken açsa rüzgarda

Kralları inim inim inletsem

Diz çökerek ağlasaydı sezarda

Kızak kaysam alaska dağlarında

At oynatsam buhara bağlarında

Pilot olup gökte uçak kullansam

Nergis olsam hindistan diyarında

İmam olsam cumaları kıldırsam

Vaaz edip cemaati kızdırsam

Kadı olup fetvaları yazdırıp

Asileri birer birer astırsam

Hakan olup imparatorluk kurdursam

Ordulara emirleri ben versem

Bir hamlede esir etsem düşmanı

Askerime bol bol ganimet versem

Saraylarım, şatolarım olsaydı

Haznelerim altın gümüş dolsaydı

Kapılarda hizmetçiler beklese

Etrafımı cariyeler sarsaydı

Çok oldu gel artık kesiver sözü

Ömer fanilerin doymuyor gözü

Hayat bir fidandır, kurursa özü

Ancak kara toprak doyurur gözü

4 Haziran 1958 Goga', 'Gönül afrikada gezmek istiyor Fakat gitmek için yollar çok uzak Atlas okyanusda yüzmek istiyor Lazım ona dört motorlu bir uçak Kovboy olup M...', ARRAY['Türk Edebiyatı','Şiir','Ömer Ziya Soyyiğit']::text[], 8.5, '{"poet":"Ömer Ziya Soyyiğit","poet_slug":"omer-ziya-soyyigit","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/istek-47-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sol Yanım', 'sol-yanim-firat-caliskan-ud8dv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mevsimlerden son bahar 					

Yaprak döküyor asılacağım dar ağacı					

Bense bilmediğim bir yolda yürüyorum				

Öyle bir soğuk varki yüreğim bile üşüyor				

Sana olan sevdam bir kangren					

Oysa ben en yorgun halimle sana koşmak istiyorum			

Biliyorsun sol yanım sana ait seni hala unutamıyorum			

Yalnızlığın özletti baharları 					

hani aşkı derin derin yaşatan baharları				

Üşüyünce kucakladım yıldızları					

Elimi her uzattığımda hayat ağacına tutunamamışım, kırmışım		

Solup solup tekrar dirilmişim					

Sevgi deryasına atmışım oltayı					

Bir umudun vurmasını beklemişim					

ve ben kalbimi kimseye değil sana vermişim				

Anlıyorsun değilmi sol yanım sana ait kimseye vermemişim.', 'Mevsimlerden son bahar 					 Yaprak döküyor asılacağım dar ağacı					 Bense bilmediğim bir yolda yürüyorum				 Öyle bir soğuk varki yüreğim ...', ARRAY['Türk Edebiyatı','Şiir','Fırat Çalışkan']::text[], 8.5, '{"poet":"Fırat Çalışkan","poet_slug":"firat-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sol-yanim-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göz Yaşı Dökmeden', 'goz-yasi-dokmeden-firat-caliskan-ngro0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Arkamda bıraktım yarınlarımı, tüm düşlerimi				

Vurdum kendimi yollara 

önüme koyup gelecek günlerimi					

yürüdüm, yol boyunca ağladım 		

Hiç gözyaşı dökmeden							

Uçurumun kenarından attım gençliğimi				

Kaybettiğim yarınlarıma küfrettim					

sonra ağladım							

Hiç gözyaşı dökmeden								

Yüzleşmeden yendim korkularımı					

hasretimi papatyalara anlattım, sevdamı boranlara ve acılarımı toprağa verdim								

Çay demledim, içip içip ağladım 					

Hiç gözyaşı dökmeden								

Su içince dorukların ölüm pınarlarında,duygularımı yıkadım		

Yalnızlığı vede yokluğunu ekmeğime katık yaptım 

doyana kadar ağladım	

Hiç gözyaşı dökmeden', 'Arkamda bıraktım yarınlarımı, tüm düşlerimi				 Vurdum kendimi yollara  önüme koyup gelecek günlerimi					 yürüdüm, yol boyunca ağladım 		 H...', ARRAY['Türk Edebiyatı','Şiir','Fırat Çalışkan']::text[], 8.5, '{"poet":"Fırat Çalışkan","poet_slug":"firat-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/goz-yasi-dokmeden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onur Akın', 'onur-akin-hasan-ozturk-2-eb76a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'O günden bu güne seni sevdim yürekte taşıdım.

Ne aradın sordun yinede seni buldum yaşadım.

Umutla çıktım yoluna mülteci gibi geldim yanına,

Resimlerinde uyudu aşk sonsuz düşüne daldım.

Ak saçlarımın akına düştün cefan sakalıma.

Kaçıncı mevsimi hasretle yaşadık ki hiç sorma.

Irak kaldı gayri sevgi barış aşk ve hürlüğümüz,

Nasıl olsa bir gün gerçek olur ölünce düşümüz.', 'O günden bu güne seni sevdim yürekte taşıdım. Ne aradın sordun yinede seni buldum yaşadım. Umutla çıktım yoluna mülteci gibi geldim yanına, ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Öztürk 2']::text[], 8.5, '{"poet":"Hasan Öztürk 2","poet_slug":"hasan-ozturk-2","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/onur-akin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüküm Giymek', 'hukum-giymek-firat-caliskan-eiymr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Umut tüketip hep hazırdan yedi ömrümüzü hayat			

Bir türlü sevinmesini ve sevmesini öğretmemişti bize			

Her düş kırıklığı bir cam kesiği gibi acıtınca yüreğimizi 			

kaderi suçluyorduk					

Hint kınası olsa yine çıkardı bu alın yazısı diyorduk			

Hele birde sevip sevilmemişsen kişilik namına herşeyi kaybediyorduk	

Tüm çelişkiler dolduranca beyin denen su yığınını 			

hepten aptallaşıyorduk					

Ne sarhoş oluyorduk, nede ayılıyorduk				

Bazen nefrete dönüşürdü nankörlükler 				

Genzimizi yakardı kokmuş kalleşlikler				

Ve bir bir yok olurdu umutlar, kurulan düşler				

Sevmeye yemin içtirir gecelik sevişmeler				

Ruhlarımız güzelliklere kör bakar durur				

Bize kalır ölü sevdalar					

Öldürmediğimizi bile bile kahır vurur					

Şahidi yoktur çünkü						

Her türlü hüküm giymek kaderdi', 'Umut tüketip hep hazırdan yedi ömrümüzü hayat			 Bir türlü sevinmesini ve sevmesini öğretmemişti bize			 Her düş kırıklığı bir cam kesiği gi...', ARRAY['Türk Edebiyatı','Şiir','Fırat Çalışkan']::text[], 8.5, '{"poet":"Fırat Çalışkan","poet_slug":"firat-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/hukum-giymek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlıkla Randevu', 'yalnizlikla-randevu-muhsin-altintas-kqveu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bugün yine hüzünlüyüm, kederliyim, yaslıyım.

Saat onüç onbeş''te yalnızlıkla randevum var.

Yalanların kopyası, gerçeğinse aslıyım,

Gerçekleri bulmak için yalnızlıkla randevum var.

Fırsattan istifade maziye dalmak için,

O günlerde unuttuğum duyguları tatmak için,

Küllenmiş kor ateşi yeniden yakmak için,

Yapayalnız tek başıma yalnızlıkla randevum var.', 'Bugün yine hüzünlüyüm, kederliyim, yaslıyım. Saat onüç onbeş''te yalnızlıkla randevum var. Yalanların kopyası, gerçeğinse aslıyım, Gerçekleri...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Altıntaş']::text[], 8.5, '{"poet":"Muhsin Altıntaş","poet_slug":"muhsin-altintas","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yalnizlikla-randevu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Ara Bul', 'beni-ara-bul-firat-caliskan-0zv40', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Beni gökyüzünde asılı gibi duran yıldızlara sor			

Arada bir uçurumun kenarlarında görmeye gel		

İstersen denizlerin gece görünmeyen yüzünde ara			

birde beni yakamozlardan sor					

Asi bir kargayla konuş ve anlatsın beni sana dağ gülleri			

Bir kelebeğin ardından koş					

Mutlaka seni bana getirecek					

Dağların zirvesine çık belki beni görürsün				

Pınarlardan içtiğin suyu unutma belki damağında tat kalırım		

Sürü halinde uçan kuşlardan biriyimdir belkide				

Beni yağan kar tanelerinden sor					

Gözlerini kırpma, güneşin ışınlarına karşı açık tut beni görmeye çalış	

Beni olmazlarda bulmaya alış					

Yürürken gölgene bak belkide o kadar yakınımdır sana	

Yüreğini al ellerine							

ve beni gör gözbebeklerinin parıltısında', 'Beni gökyüzünde asılı gibi duran yıldızlara sor			 Arada bir uçurumun kenarlarında görmeye gel		 İstersen denizlerin gece görünmeyen yüzünde...', ARRAY['Türk Edebiyatı','Şiir','Fırat Çalışkan']::text[], 8.5, '{"poet":"Fırat Çalışkan","poet_slug":"firat-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/beni-ara-bul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Toyluğumda Sevdiğim', 'toylugumda-sevdigim-umut-gungor-5n6i5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Toyluğumda sevdiğim,

Aşkım idin Gülseren,

Gizli gizli sevdiğim,

Aşkım idin Gülseren.

Yüreğim ısınırdı,

Sen okula gelince,

Gururla kasılırdı,

Gözüm seni görünce.

Sınıf sınıf arardık,

Okulu baştanbaşa,

Ya görmezsek korkardık,

Düşüp tatlı telaşa.

Bırakırdık gözlere,

Aşkı anlatsın diye,

Gem vururduk sözlere,

Gözler anlaşsın diye.

Kurtuluşta yaşadık,

Bu güzel aşkımızı,

Yüreklere taçladık,

Yazarken şarkımızı.', 'Toyluğumda sevdiğim, Aşkım idin Gülseren, Gizli gizli sevdiğim, Aşkım idin Gülseren. Yüreğim ısınırdı, Sen okula gelince, Gururla kasılırdı,...', ARRAY['Türk Edebiyatı','Şiir','Ümüt Güngör']::text[], 8.5, '{"poet":"Ümüt Güngör","poet_slug":"umut-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/toylugumda-sevdigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doyulur mu Hiç', 'doyulur-mu-hic-hasan-gorgu-wj7ex', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Arzuyla bakarken bana gözlerin

Böyle de çekingen durulur mu hiç

Sevgini söylerken tatlı sözlerin

Tam da yarısında susulur mu hiç

Elime uzanıp değerken elin

Koluma dolanır kıvrılır belin

İnceden inceye çalan bestenin

Nağmesine kanıp doyulur mu hiç

Zevk ile sarılan iki bedenin

Tutku ile coşan birleşen tenin

Doruğa tırmanıp fışkıran selin

Önüne barikat kurulur mu hiç

Ya hepten sev beni ya hiç arama

Tabip değil isen değme yarama

Belki de çaresi bulunur amma

Sensiz de yaşamak çekilir mi hiç', 'Arzuyla bakarken bana gözlerin Böyle de çekingen durulur mu hiç Sevgini söylerken tatlı sözlerin Tam da yarısında susulur mu hiç Elime uzanı...', ARRAY['Türk Edebiyatı','Şiir','Hasan Görgü']::text[], 8.5, '{"poet":"Hasan Görgü","poet_slug":"hasan-gorgu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/doyulur-mu-hic-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Hatırlıyorum', 'seni-hatirliyorum-firat-caliskan-ogwaw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hava karardı, üstelik yağmurda dinmedi			

Yüreğim yalnız başına, ıslanıyorum					

Çocukların gözlerinde gördüm gülümsemeni				

Zemheri soğuğunda açan çiçeklerde					

ve halaylarda çaldığın zılgıttan tanıyorum seni				

								

Ben seni geçmişteki yarından					

Gelecekteki dünden hatırlıyorum					

Ben seni şimdi değil,tarihten tanıyorum				

Yağan yağmurun damlalarından, gökyüzünün karanlığından biliyorum	

Seni geceleri yakamozlarda görüyordum, aşk romanlarında okuyordum	

Dalgaların sesinde duyuyordum doğal felaketlerden anımsıyorum seni	

								

Ben seni geçmişteki yarından					

Gelecekteki dünden hatırlıyorum					

Ben seni şimdi değil,tarihten tanıyorum				

Seni; yıldızların altında oturan, söylediğimiz türkülerden tanıyorum.		

Diclenin soğuk sularında yıkanıp,yaktığımız ateşin başındaki sıcaklıktan hatırlıyorum.						

Sabaha karşı tan ağartısında içtiğimiz bir bardak çaydan 		

ve sardığımız tütünün kokusundan biliyorum.								

								

Ben seni geçmişteki yarından					

Gelecekteki dünden hatırlıyorum					

Ben seni şimdi değil,tarihten tanıyorum				

Seni; yürekteki özgürlük ateşinden,					

Kelebeğin kanadındaki renkten,					

Dağ çiçeklerinin yapraklarındaki çiy damlasından,			

Kengerin kökündeki tattan biliyorum.					

								

Yani benseni şimdi değil						

Geçmişteki yarından						

Gelecekteki dünden hatırlıyorum.								

(Geçmişteki yarın, gelecekteki dün:Hayal ettiğim zamanım)', 'Hava karardı, üstelik yağmurda dinmedi			 Yüreğim yalnız başına, ıslanıyorum					 Çocukların gözlerinde gördüm gülümsemeni				 Zemheri soğuğ...', ARRAY['Türk Edebiyatı','Şiir','Fırat Çalışkan']::text[], 8.5, '{"poet":"Fırat Çalışkan","poet_slug":"firat-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/seni-hatirliyorum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sınırsız Ülke', 'sinirsiz-ulke-firat-caliskan-imk3q', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Baktımki dünyanın sahibi çoktur					

Öyleyse bizlere bir yaşam yeri yoktur					

Bir yaşam kurmalı kendi kendine					

Sınırları olmayan mutlu bir ülke', 'Baktımki dünyanın sahibi çoktur					 Öyleyse bizlere bir yaşam yeri yoktur					 Bir yaşam kurmalı kendi kendine					 Sınırları olmayan mutlu...', ARRAY['Türk Edebiyatı','Şiir','Fırat Çalışkan']::text[], 8.5, '{"poet":"Fırat Çalışkan","poet_slug":"firat-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sinirsiz-ulke-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kan Ağla', 'kan-agla-muhsin-altintas-6bprg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aşkı nota nota besteledimde

Şarkı. şiir yerine sen çıkıverdin.

Beni üzen hep sen oldun hayatta,

Bir baktımki ben yerine sen bıkıverdin.

Sarılmışken sımsıkı hayat bağına,

Sırdaş yaptın sen beni dert otağına.

Tamda sığınmışken aşk limanına

Yapayalnız koyup beni, bak kaçıverdin.

Tomurcuk gül misali aşk aç demiştim,

Masumane bir bakışla gülümsemiştin,

Yürektenmi bilmem ama olur demiştin

Verdiğin sözden birden vazgeçiverdin.

Şimdi dostlar yas tutup, düşman sevinsin,

Kederler şaha kalksın, umut yerinsin,

Bu dünyada değilsede ahirette benimsin,

Artık kara bağla vede kan ağla 

Kapanmasın gönül yaran melhem bulama.', 'Aşkı nota nota besteledimde Şarkı. şiir yerine sen çıkıverdin. Beni üzen hep sen oldun hayatta, Bir baktımki ben yerine sen bıkıverdin. Sarı...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Altıntaş']::text[], 8.5, '{"poet":"Muhsin Altıntaş","poet_slug":"muhsin-altintas","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kan-agla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karamsarlığın Bedeli', 'karamsarligin-bedeli-firat-caliskan-l063k', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sana, seni seviyorum diyememek				

Kirpiklerinin kıvrımında asılı kalmaktır boynumdan			

Sensizliğe ağlarken, kendimi teselli etmek				

Boş bir beşiği sallamaktır,acı ninni söyleyerek.				

								

Tututklu kalmak bakışlarına 					

Çatlak dudağa tuz basmaktır.					

Belki yetim belki öksüz kalmaktır.					

Ve yüreğinde mayın patlatmaktır, incitmeden gözlerini			

								

Seni unutmak tahliye etmektir kalbimden tüm duyguları			

Ve unutmamak						

Biliyorken gelmeyeceğini duraklarda seni beklemektir.			

								

Senden ayrı kalmak yakıp bu kenti 				

Ortasında boylu boyunca uzanmaktır.					

Belkide bu duyguların hepsini delice Fırat''a atmaktır.', 'Sana, seni seviyorum diyememek				 Kirpiklerinin kıvrımında asılı kalmaktır boynumdan			 Sensizliğe ağlarken, kendimi teselli etmek				 Boş ...', ARRAY['Türk Edebiyatı','Şiir','Fırat Çalışkan']::text[], 8.5, '{"poet":"Fırat Çalışkan","poet_slug":"firat-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/karamsarligin-bedeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Daye', 'daye-ahmet-guven-ht369', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'DAYÊ

Min biyek dana li keviya avê

Westiyam çûm rûniştim li bin siyê

De min go bila bişewite mala dijmin

Der cîran çûyîne,kes nemayîne

Dayê min qala te kir

Ez giryam,hesa min bîstin çiya û baniyan

Çûçkek firî,hat sekinî li hêla min

Hesa xwe rakir,darev hesa min

Çarx bûm,çûm ber bi malan

Derî kilît kirine der û cîranan

Arek kete dilê min şewitî dayê

De min go heyfa ax û de û bavan

Peyv û Mûzik: Ahmet Güven	

ANA

Bir söğüt diktim suyun kenarına

Yoruldum oturdum gölgesine

Yıkılsın zalimin evi

Komşular gitmiş kimse kalmamış

Ana özledim seni ağladım

Sesim dağıldı gitti dağlara

Bir kuş uçtu kondu üst tarafıma

Ses verdi eşlik etti sesime

Döndüm evlere doğru gittim

Kapıları kitlemiş komşular

Yüreğime bir ateş düştü yandı

Yazık oldu ataların toprağına

Söz ve Müzik: Ahmet Güven', 'DAYÊ Min biyek dana li keviya avê Westiyam çûm rûniştim li bin siyê De min go bila bişewite mala dijmin Der cîran çûyîne,kes nemayîne Dayê m...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Güven']::text[], 8.5, '{"poet":"Ahmet Güven","poet_slug":"ahmet-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/daye-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kal büm', 'kal-bum-ahmet-guven-ottqs', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kal bûm rindê ez kal bûm

Heliyam, heliyam tewa bûm

Genciya min çû, rabit

Robu tu bi ber bîra min ket

Kanî, kanî tu kanî

Ava xwe xweş kanî

Here rindê dey meke

Çavê min bûne kanî

Rudinim li ber derî

Silavên te li ser serî

Here rindê ji bîr meke

Silavên xwe kêm meke

Desmalê xwe li ba ke

Here min ji bîr meke

Mirin heye mi tune

Şûna te heye erde

Peyv û Mûzik: Ahmet Güven

	

YAŞLANDIM

Yaşlandım güzel yaşlandım

Eridim,eridim tükendim

Gençliğim geldi geçti

Gün oldu aklıma düştü

Çeşme senin suyun akar

Çeşme suyun tatlı akar

Git güzel beni yaralama

Gözlerim iki çeşme akar

Otururum kapının önünde

Selamını beklerim

Git güzel unutma

Selamını eksik etme

Giderken mendil salla

Git ama beni unutma

Ölüm varmı yokmu

Sen de girersin toprağa

Söz ve Müzik: Ahmet Güven', 'Kal bûm rindê ez kal bûm Heliyam, heliyam tewa bûm Genciya min çû, rabit Robu tu bi ber bîra min ket Kanî, kanî tu kanî Ava xwe xweş kanî He...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Güven']::text[], 8.5, '{"poet":"Ahmet Güven","poet_slug":"ahmet-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/kal-bum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saklambaç..', 'saklambac-selma-sengoren-w5kqp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir siyah

Bir mavi rengim

Sevgiye lades tuttum

Siyahlara inat

Mavilikleri seçti ömrüm

Kirpiğimin okundan

Kalbime damlayan incim

Kelimelerin içinde 

Gizli tomurcuğum

Söyle kimsin sen

Düşüncelerimin meleği

Beyaz düşlerimin kelebeği

Leylak kokusu yüreğimin

Atışındaki nefes misin

Söyle kimsin sen

Buğulu gözbebeğimde

Suskun sabahlarım 

Mavi gülümseyiş hep yüzümde

Saklambaç oynama gönlümle

Söyle kimsin sen…

div align=''center''embed src=''http://arsiv.kalitelimuzik.com/dizimuzikleri/www.kalitelimuzik.com%20-%20Hirsiz-Polis-%C4%B0mkansiz%20Ask.wma'' width=''100'' height=''16'' autostart=''true'' loop=''true''/embed', 'Bir siyah Bir mavi rengim Sevgiye lades tuttum Siyahlara inat Mavilikleri seçti ömrüm Kirpiğimin okundan Kalbime damlayan incim Kelimelerin ...', ARRAY['Türk Edebiyatı','Şiir','Selma Şengören']::text[], 8.5, '{"poet":"Selma Şengören","poet_slug":"selma-sengoren","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/saklambac-248-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin Olsun', 'senin-olsun-huseyin-sonmez-chz2j', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dikenleri bana ver,

Güller hep senin olsun,

Bu baharda mutluluk,

Senin kalbine dolsun.

İnce ince nağmeler,

Dökülsün hece hece,

Gündüzler senin olsun,

Benim olsun tüm gece.

Kıskanmasın hiç kimse,

Sevgiyi aşkı sende,

Geçecek tüm ömründe,

Mutluluk senin olsun.', 'Dikenleri bana ver, Güller hep senin olsun, Bu baharda mutluluk, Senin kalbine dolsun. İnce ince nağmeler, Dökülsün hece hece, Gündüzler sen...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sönmez']::text[], 8.5, '{"poet":"Hüseyin Sönmez","poet_slug":"huseyin-sonmez","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/senin-olsun-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Töre', 'tore-yusuf-ziya-leblebici-7bewq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Fukara hanene erkeklik derken

Bir kurşuna yenik düştün be emmi

Törenin uğruna yiğitlik derken

Yoldan dönemeden gittin be emmi

Mapusta onları mezarda seni

Ziyaret edenler bilmezler mi ki

Kahpe kan davası nere gider ki

Sende bilemeden gittin be emmi

Kaç adım yürüdün koca dünyada

Garip yetimlerin kaldı ardında

Eyvallah demeden girdin mezara

Sen de diyemeden gittin be emmi

Ocağında pişen aş mıydı tören

Yollarına düşen taş mıydı tören

Sımsıcak evinde yüzler gülerken

Sen de gülemeden gittin be emmi

Yusuf Ziya der ki, düşsek yollara

Gözümüzden yaşı salsak ırmağa

Alıp başımızı varsak dağlara

Bizi düşünmeden gittin be emmi', 'Fukara hanene erkeklik derken Bir kurşuna yenik düştün be emmi Törenin uğruna yiğitlik derken Yoldan dönemeden gittin be emmi Mapusta onları...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/tore-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çelişki..!', 'celiski-alptekin-biber-yyt8k', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir yol var

............kavramam gereken ben...

Bir yol var

............aşmam  gereken ben...

Bir yol aşmışım

...................anlaşılamayan ben...

Yeni yollarda 

........yeni umutlarla

..........yeniden var olmak isteyen

.............................................yine ben...

Var bir çelişki ya...

26 Mart 2006', 'Bir yol var ............kavramam gereken ben... Bir yol var ............aşmam  gereken ben... Bir yol aşmışım ...................anlaşılamay...', ARRAY['Türk Edebiyatı','Şiir','Alptekin Biber']::text[], 8.5, '{"poet":"Alptekin Biber","poet_slug":"alptekin-biber","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/celiski-75-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem', 'ozlem-haldun-karakoyun-m8smt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sabah evden işe gider

Kapıya gelir beni öper

Bana verdiğin bu değer

Sanki dünyaya bedel

Beni bir kez öpüşün

Bana verdiğin o düşün

Güneş kavuşmadan 

Sana özlemle dönüşüm

İşin ne zaman biter 

Diye bana soruşun

Benim sana olan düşüm

işim bitmese de 

Özlemle sana dönüşüm

Senin beni bekleyişin

Bir de kapıda karşılayışın

Kapının zilini çalışım

Senin beni özleyişin

Aslında benim seni özleyişim

Senin güler yüzün 

Kapıyı açınca bana gülüşün

İçimde bir yaradır

Benim seni özleyişim

Özlem nedir sorarsan

Bunu bende ararsan

Benim sana olan tutkumdur

Senin bana olan nutkundur

03.02.2006', 'Sabah evden işe gider Kapıya gelir beni öper Bana verdiğin bu değer Sanki dünyaya bedel Beni bir kez öpüşün Bana verdiğin o düşün Güneş kavu...', ARRAY['Türk Edebiyatı','Şiir','Haldun Karakoyun']::text[], 8.5, '{"poet":"Haldun Karakoyun","poet_slug":"haldun-karakoyun","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/ozlem-325-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aldırma', 'aldirma-yusuf-ziya-leblebici-779in', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yürürsen bu yoldan varışın vardır

Attığın adımdan sakın usanma

Düşersen bir yerden kalkışın vardır

Acım geçti diyeceksin, aldırma

Gurbetten sılaya hasret çekerken

Yüreğine sevda gülü dikerken

Mevla’ya yalvarıp dua ederken

Bir gün sen de güleceksin, aldırma

Daha düşmeden bu derdin içine

Hani senin ile gülenler nerde

Kötü günler elbet kalır geride

Dost düşmanı bileceksin, aldırma

Kar yağmışsa senin yaslı bağrına

Dert üstüne dert binmişse sırtına

Düşmemişse kimse senin ardına

Sen de dostu seçeceksin, aldırma

Umut ekmek gibi Yusuf Ziya’da

Denizden gelen şu deli dalgada

Dağlardan esen şu deli rüzgarda

Bir gün sen de gezeceksin unutma

Bir gün sen de eseceksin, aldırma', 'Yürürsen bu yoldan varışın vardır Attığın adımdan sakın usanma Düşersen bir yerden kalkışın vardır Acım geçti diyeceksin, aldırma Gurbetten ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/aldirma-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vuruyor beni', 'vuruyor-beni-yusuf-ziya-leblebici-5742e', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sigara değil ki gözümde tüten

Senin şu hasretin çalıyor beni

İçerken seni o kara gözünden

Sevdanın kurşunu vuruyor beni

Gündüzü geceye karıştır haydi

Acıyı tatlıyla barıştır haydi

Karanlık günlere gönder güneşi

Kapkara zamanlar sarıyor beni

Yüzünün rengini şaraba verdim

Saçının telini sazıma gerdim

Kaybolan sesini dilime serdim

Yazdığım türküler çalıyor beni

Şu koca dağlara sen misin desem

Sana çıkan yolu bir bilebilsem

Senin bana sevdan nasıldır bilmem

Başımda ellerim sıkıyor beni

Yusuf Ziya’m kadar bundan eminim

Senin ellerini elimde bildim

İçimde yaşarken söyle nerdesin

Hasretin ateşi yakıyor beni', 'Sigara değil ki gözümde tüten Senin şu hasretin çalıyor beni İçerken seni o kara gözünden Sevdanın kurşunu vuruyor beni Gündüzü geceye karış...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/vuruyor-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türkistanda Sabahları Geç Olur', 'turkistanda-sabahlari-gec-olur-umut-gungor-a9fua', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Türkistanda sabahları geç olur, 

Buralardan izlemesi güç olur, 

Zalim çinin zulümleri çığ gibi, 

Buralardan dinlemesi güç olur. 

Asırlardır deneylerde bedenler, 

Sorulmazki nedir asıl nedenler, 

Yetişmiyor can sarmaya kefenler, 

Çin seddinden görülmesi zor olur. 

Kim giderse geçemiyor bu seddi, 

Gözünüzü bu dünyamı kör etti, 

Kim yazacak nota ile bu reddi, 

Çin seddinde fotoğraflar çekenler.', 'Türkistanda sabahları geç olur,  Buralardan izlemesi güç olur,  Zalim çinin zulümleri çığ gibi,  Buralardan dinlemesi güç olur.  Asırlardır ...', ARRAY['Türk Edebiyatı','Şiir','Ümüt Güngör']::text[], 8.5, '{"poet":"Ümüt Güngör","poet_slug":"umut-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/turkistanda-sabahlari-gec-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kar', 'kar-haldun-karakoyun-thpv3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Mevsimindir anladım yağacaksın

Buraları yine beyazlatacaksın

Yağmaya başlamadan önce

Benim romatizmalarımı azacaksın

Çektiğim çileyi çoğaltacaksın

Yağmaya başlamadan önce

Havanın değişeceğini hissettim

Senin soğuğuna alııştım 

Yağmadan önce tedbirimi aldım 

Senin saflığına katlanırım

Sensiz hayat düşledim

Yağmanı dört gözle bekledim

Bugün yağmaya başladın

Seni seyretmeye doyamadım

İnşallah fırtınasız yağarsın 

Sessiz, sakin bir şekilde

Seni yağarken seyretmek

Hayal aleminde düşlemek

Sen yağdıktan sonra

Sana basıp yerle bir etmek

Seni elde taşımak yasaktır

Sensiz yazın sular akmaz

Sen olmayınca hayat olmaz

Sen yağmazsan akan sular olmaz

Sen yağmayınca denizler dolmaz

Sen yağmazsan toprak kanmaz

Yağarken seni özlemle seyretmek

Sana olan özlemi dindirmek

En güzeli seni yağarken 

Sobanın yanında camdan seyretmek

05.02.2006', 'Mevsimindir anladım yağacaksın Buraları yine beyazlatacaksın Yağmaya başlamadan önce Benim romatizmalarımı azacaksın Çektiğim çileyi çoğalta...', ARRAY['Türk Edebiyatı','Şiir','Haldun Karakoyun']::text[], 8.5, '{"poet":"Haldun Karakoyun","poet_slug":"haldun-karakoyun","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/kar-98-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdiğim', 'sevdigim-yusuf-ziya-leblebici-x5kh5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Pembe rüyaları gerçek bilip de

Neden yanlış yola girdik sevdiğim

Yaşanan sevdayı hepten silip de

Ayaklar altına serdik sevdiğim

Nerde hata yaptık biz bu yollarda

El ele verdik ya ıssız koylarda

Peşpeşe koşarken küçük çaylarda

Biz bizi cennette bildik sevdiğim

Ne sende ne bende yokken ayrılık

Sözümüzde yoktu ayrı gayrılık

Aramıza nerden girdi farklılık

Ayrı bedenlere geçtik sevdiğim

Yürürken yarına aynı adımla

Türküler yakardık çalan sazımla

Bu günler sürecek sandık inançla

Yanlış yollarda mı bittik sevdiğim', 'Pembe rüyaları gerçek bilip de Neden yanlış yola girdik sevdiğim Yaşanan sevdayı hepten silip de Ayaklar altına serdik sevdiğim Nerde hata y...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevdigim-97-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çırpınır', 'cirpinir-adnan-kiziltoprak-uflgn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kimi aşk için çırpınır

Kimi Ölüm İçin.

Kimi Pişmanlıktan çırpınır

Kimi gülmek için.

Kimi şiir yazmak için çırpınır,

Kimi yazılanı yırtmak için.

Kimi suç işler çırpınır

kimide onunla olduğu için.

Herkes bir şey için çırpınır

Kimi unutulur, kimi anılır.

Kimi gariplerde gönlünce çırpınır

ama en çok da..

Azap çekip de ağlayanlar çırpınır.', 'Kimi aşk için çırpınır Kimi Ölüm İçin. Kimi Pişmanlıktan çırpınır Kimi gülmek için. Kimi şiir yazmak için çırpınır, Kimi yazılanı yırtmak iç...', ARRAY['Türk Edebiyatı','Şiir','Adnan Kızıltoprak']::text[], 8.5, '{"poet":"Adnan Kızıltoprak","poet_slug":"adnan-kiziltoprak","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/cirpinir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Gideli', 'sen-gideli-huseyin-sonmez-wjsom', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ağlarım ben gülmem artık,

Sevdiğim bırakıp gitti,

Gülmez oldu şu gözlerim,

Ayrılık canıma yetti.

Geçmez oldu sensiz günler,

Kâbus dolu hep geceler,

Ne melekler ne periler,

Halimi hiç bilmez oldu,

Gündüz oldu gece bana,

İsmin oldu hece bana,

Umutlarım benden yana,

Koşup artık gelmez oldu.

Tanıdığım bildiklerim,

Deli gibi sevdiklerim,

Hep arayıp sorduklarım,

Halimi hiç görmez oldu.

Ayrılık ölümden beter,

Bunca acı artık yeter,

Küsmüş bana zalim kader,

Yüzüme hiç gülmez oldu.', 'Ağlarım ben gülmem artık, Sevdiğim bırakıp gitti, Gülmez oldu şu gözlerim, Ayrılık canıma yetti. Geçmez oldu sensiz günler, Kâbus dolu hep g...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sönmez']::text[], 8.5, '{"poet":"Hüseyin Sönmez","poet_slug":"huseyin-sonmez","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sen-gideli-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Örs(eleyen)', 'ors-eleyen-alptekin-biber-g0h3w', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dört yanım derin yalnızlık

......örse çekiç yüreğim..

Örs incinmez,

..............incinen benim...

Beni örs(eleyen)   deyip,

.........................vurur diğerlerim...

26 Mart 2006', 'Dört yanım derin yalnızlık ......örse çekiç yüreğim.. Örs incinmez, ..............incinen benim... Beni örs(eleyen)   deyip, ..................', ARRAY['Türk Edebiyatı','Şiir','Alptekin Biber']::text[], 8.5, '{"poet":"Alptekin Biber","poet_slug":"alptekin-biber","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ors-eleyen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Gözyaşları', 'askin-gozyaslari-adnan-kiziltoprak-hgxpp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Eğer akan yaşlar gülüyorsa,

Gözden yavaş, yavaş sızıyorsa

Belki o! Sadece; 

Aşkın gözyaşlarıdır.

Sana bakarken parlıyorsa

Ondan sonra yaşlar saklanıyorsa

Bilki o! sevgilin,

Akanda aşkın gözyaşlarıdır.', 'Eğer akan yaşlar gülüyorsa, Gözden yavaş, yavaş sızıyorsa Belki o! Sadece;  Aşkın gözyaşlarıdır. Sana bakarken parlıyorsa Ondan sonra yaşlar...', ARRAY['Türk Edebiyatı','Şiir','Adnan Kızıltoprak']::text[], 8.5, '{"poet":"Adnan Kızıltoprak","poet_slug":"adnan-kiziltoprak","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/askin-gozyaslari-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdim Olmadi', 'sevdim-olmadi-omer-altiok-xcucv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bindi yine omuzlarima,

Ayrilmisligin olanca yükü...

Gücüm kalmadi,

Sabrim kalmadi...

Sevecegim dedim,

Sevdim olmadi...



Sonu olmayan bir yol bu,

Yolculuk cetin,

Yollar uzun,

Ac kaldim...

Susuz kaldim,

Kalbim yorgun,

Gönlüm vurgun,

Gelecegim dedim sana ben gülüm...

Geldim olmadi, 

Sevdim olmadi...



Birakmadi yine gecmisim beni,

Sürüklendi pesimden.

Bindiler kücücük omuzlarima.

Kacacak bir yol var mi bilmem...

Ruhum perisan,

Halim acinasi...

Senden cok uzaklara,

Gidecegim dedim...

Gittim olmadi,

Kactim olmadi...



Hep seyrettim zaten gitmeleri,

Gidisleri de güzeldi, tipki gelmeleri gibi...

Bitmeselerdi,

Gitmeselerdi...

Giderlerken hep yanlarinda götürdüler beni...

Paramparca oldum, tükendim...

Bitecegim dedim,

Bittim olmadi,

Yine olmadi.



(27.03.2006,Koblenz', 'Bindi yine omuzlarima, Ayrilmisligin olanca yükü... Gücüm kalmadi, Sabrim kalmadi... Sevecegim dedim, Sevdim olmadi... Sonu olmayan bir yol ...', ARRAY['Türk Edebiyatı','Şiir','Ömer Altiok']::text[], 8.5, '{"poet":"Ömer Altiok","poet_slug":"omer-altiok","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/sevdim-olmadi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elin Elinde', 'elin-elinde-tuncay-demirbilek-v09bj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ELİN ELİNDE

Ey garip,

Cennetle müjdelendin diye sevinme

Lakin senin sevdiğin elin elinde

Ey şanslı,

Cehennemden korkma, bak cennettesin

Lakin senin sevdiğin, elin elinde', 'ELİN ELİNDE Ey garip, Cennetle müjdelendin diye sevinme Lakin senin sevdiğin elin elinde Ey şanslı, Cehennemden korkma, bak cennettesin Laki...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Demirbilek']::text[], 8.5, '{"poet":"Tuncay Demirbilek","poet_slug":"tuncay-demirbilek","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/elin-elinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türkiyem', 'turkiyem-bas-oguzhan-6x5y7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Coşkun akan çaylar 

Çiçek kokan kırlar

Bekler bizi arkadaşlar

Yolculuklar

Gümüşdere boyu

Soğuk pınar suyu

Bekler bizi arkadaşlar 

Yolculuklar', 'Coşkun akan çaylar  Çiçek kokan kırlar Bekler bizi arkadaşlar Yolculuklar Gümüşdere boyu Soğuk pınar suyu Bekler bizi arkadaşlar  Yolculukla...', ARRAY['Türk Edebiyatı','Şiir','Baş Oğuzhan']::text[], 8.5, '{"poet":"Baş Oğuzhan","poet_slug":"bas-oguzhan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/turkiyem-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Ne Anlamsız Ayrılık!', 'bu-ne-anlamsiz-ayrilik-yavuz-bayram-caliskan-32c39', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kırılsa da dallar, batacak da olsa dikenler,

Yürünecektir bu zamansız yol.

Hicranı omzuna alsan,

Hüznü beline taksan, yılmam gelirim.

Ben değil, ayrılık vefasız.

Sevdiğim diyebiliyorsa, diller,

Sevgi ölmemiştir.

Uzandım sabaha,

Baktım güneşe,

Kaybolan sendin.

Kimin elinden tutmuşsun da bana “Gel” diyorsun? 

Bu ne anlamsız ayrılık! 

Uçurumların kenarında bıraktın,

Rıhtımlara yürüdüm,

Sen yoktun.

Kalamadın belli, gidiverdin,

Alıverdi eller koynuna.

Yanmaz mı bu yürek,

Ölmez mi bu can? 

Bulunmaz ilk bakış,

İlk aşk,

İlk yakış,

Bilmez miyim? 

Bende arar dururum sıcaklığını,

Ayaz gecelerde.

Dönüp de düne baktım,

Bu ne anlamsız ayrılık! 

Çınarlar uludur ama bir adım gidemez, 

Senin ettiğini başkası edemez,

Adım atmaya derman mı kaldı,

Sevdiğimdin, yağmurlardan önce eller aldı.

Kaçış değil senden, bil ki seni alan elden,

Sonları bilsem giderim, adına ölüm derim.

Gözlerini almıştım bakmak için,

Yüreğini almıştım yakmak için,

Ellerini almıştım yüzüğümüzü takmak için.

Kalsaydın o sokaklar söylerdi,

Engeller çoğaldı bilmedin mi? 

Anılar sulara daldı,

Bir senli yüreğim vardı,

O da çöllerde kaldı.

Unutur yollar ardında kalan,

Diyorsun ki sevgin falan,

O gözler ufuklarda seni özler,

O buse tadında ömür demlenir,

Sorsam da dudağına,

Sorsam da busene,

Ses veren olmaz.

Kuruttu ayazlar soldum ben,

Bu aşkla son oldum ben.

http://www.geocities.com/siirhan68/', 'Kırılsa da dallar, batacak da olsa dikenler, Yürünecektir bu zamansız yol. Hicranı omzuna alsan, Hüznü beline taksan, yılmam gelirim. Ben de...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/bu-ne-anlamsiz-ayrilik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İç Hesap', 'i-c-hesap-aysun-erat-i1pvn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yalnızlığı denedim ama, olmadı.

Her defasında

Biraz daha dibe yaklaştım.

Baktım ki boğuluyorum

Hem de göz göre göre

Başlarım dedim böyle düzene.

Bir canım var zaten

Bir kurşun atımlık

Katılayım bari insanlar arasına

Bakalım daha ne göreceğim varmış,

Denemeli..

Grup indirimi de oluyor her köşe başında

Fena mı yani? 

“Zararın neresinden dönsen kardır” misali...

03/2006', 'Yalnızlığı denedim ama, olmadı. Her defasında Biraz daha dibe yaklaştım. Baktım ki boğuluyorum Hem de göz göre göre Başlarım dedim böyle düz...', ARRAY['Türk Edebiyatı','Şiir','Aysun Erat']::text[], 8.5, '{"poet":"Aysun Erat","poet_slug":"aysun-erat","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ic-hesap-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dargınmıyım', 'darginmiyim-ugur-aydin-2-dhn7u', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'benimde birilerim vardı bir zamanlar

kah sesini duyduğum kah yüzünü gördüğüm 

uzakta olsa var olduğunu bildiğim...

uzun zaman oldu ne sesini ne de yüzünü gördüm bende ki 

birilerinin...

kaçı dargındır... kaçı alınmıştır bana

kaçı hatıralarında saklıyordu beni 

kimbilir....

yada ben  dargınımdır kaçına kime alınmışımdır 

görmsekte birbirimizi duymasakta sesimizi 

kaybetmişizdir anıların içinde birbirimizi.

uzaklaştırmış dünya meşakkatiyle dostları birbiriden 

silmemiştir sevgileri yüreklerin derin köşelerinden 

kim bilir...

kaç özlem çekilir yürklerden birilerine 

belkide göç başlamıştır dönülmeyen yerlere

geride kalan gidenden geçmişten anılar zarfının içinden postaya verilen

bir yoldur ki bu yol gidilip dönülmeyen...

kim bilir....

tek renk var bütün renkleri içeren hayat aralığında

ışığın rengidir bütün renkleri renklendiren

bir umuttur içimize o renkli ışık sönmeyen 

kim bilir...

ne oluyor bana 

ne o dargınmıyım bu akşam hatıralara 

sesini duymasam yüzünü görmesem bilmesem de nefes aldığını

birileri yaşıyor içimde 

hala......

...................................................................................................................................

iplikçi kızın son sayfası', 'benimde birilerim vardı bir zamanlar kah sesini duyduğum kah yüzünü gördüğüm  uzakta olsa var olduğunu bildiğim... uzun zaman oldu ne sesini...', ARRAY['Türk Edebiyatı','Şiir','Uğur Aydin 2']::text[], 8.5, '{"poet":"Uğur Aydin 2","poet_slug":"ugur-aydin-2","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/darginmiyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Erik Hırsızının Hikayesi...', 'i-ki-erik-hirsizinin-hikayesi-aysun-erat-oblhz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şimdi..

Bu koskoca tarlada

Sen ve ben yani

Aynı dalda

Aynı eriğe mi göz diktik? 

İnanmam..

Aynı hızda 

Ve aynı iştahla

Aynı günaha mı koşuyoruz yani? 

Git işine..

Bilirim günah değil aslında

Olsa olsa göz hakkı ince bir fikirle.

Ama yine de..

Başka ağaç mı kalmadı? 

Git! 

Kendi dalına uzan.

Elma olsa hadi neyse

Bölüşürdük ortadan

03/2006', 'Şimdi.. Bu koskoca tarlada Sen ve ben yani Aynı dalda Aynı eriğe mi göz diktik?  İnanmam.. Aynı hızda  Ve aynı iştahla Aynı günaha mı koşuyo...', ARRAY['Türk Edebiyatı','Şiir','Aysun Erat']::text[], 8.5, '{"poet":"Aysun Erat","poet_slug":"aysun-erat","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/iki-erik-hirsizinin-hikayesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoş Geldin', 'hos-geldin-cafer-yilmaz-tcibr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'depremden virane bedenim.

kolum kanadım enkaz gibi salık.

ezilmişim altında

nefes almak imkansız.

üstüme çullanmış,

adına dert denilen koca enkaz...

kaz güzelim..! 

ellerinle sen kaz...

gece boyu kulağımı tırmalayan

rüzgarın uğultusu.

kapının gıcırtısı bile ürkütür beni.

sönmüş ışıklarım, oda karanlık.

sessizliğin sesini dinliyorum alık alık.

buğulanmış pencerem

damlalar gözyaşımla yarışta...

sil güzelim..! 

ağlanır mı hala bu yaşta..? 

yitikliğin elleri arasında kalmış beynim.

bağırsan yankılanacak kadar derin.

soyulmuş bir dükkan gibi tam takır.

bağır güzelim..! 

avazın çıktığı kadar bağır..! 

oturmuşum mahşerin kaldırım taşına.

kulakları sağır edercesine kalabalık.

cehennem saatleri başlar,

ne zaman güneş batsa odamda.

elinde gelincik çiçeği ile 

bir bahar dayanır kapıma...

hoş geldin hayatıma...

                         28-03-2006', 'depremden virane bedenim. kolum kanadım enkaz gibi salık. ezilmişim altında nefes almak imkansız. üstüme çullanmış, adına dert denilen koca ...', ARRAY['Türk Edebiyatı','Şiir','Cafer Yılmaz']::text[], 8.5, '{"poet":"Cafer Yılmaz","poet_slug":"cafer-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/hos-geldin-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lirik 59 (değmez)', 'lirik-59-degmez-fevzi-cebe-akkoq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'tanıklıklar yaptılar

tanıklıklar yaptım

zaman geçti yinede 

tanıklıklar...

bize kalan sessizlik

ya da benim anladığım 

kılıcım... kınında hala

sarsam da onu

kılıcım, kınında hala

tek bir hareket! 

eylem 

ya da

özgürlük

-grandiyoz-

değmez diyorum, ve

elim gevşiyor

02.08.2005 – 20:05', 'tanıklıklar yaptılar tanıklıklar yaptım zaman geçti yinede  tanıklıklar... bize kalan sessizlik ya da benim anladığım  kılıcım... kınında ha...', ARRAY['Türk Edebiyatı','Şiir','Fevzi Cebe']::text[], 8.5, '{"poet":"Fevzi Cebe","poet_slug":"fevzi-cebe","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/lirik-59-degmez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayatım Sana Ayarlı', 'hayatim-sana-ayarli-bahaettin-karakoc-7glt5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Nehrin ortasına düştüm burgaçta dönüp dururum 

Bana değip kaçan balık birden ellerin oluyor.

Ben ağlarken yaşın yaşın çözülen kara bulutlar 

Sen gülerken ak duvağın, al-al tellerin oluyor.

Bir kahkaha tufanına dönüştüğü zaman neş''en 

Beni söküp sürükleyen deli sellerin oluyor.

Hangi sapa yere çadır kurup yurtlansam, orası, 

Senin sultanlık çayırın, çamlıbellerin oluyor.

Seher ya da gurûb vakti âfaka renk-ıtır veren 

Senin başak söken terin, gonca güllerin oluyor.

Bu ne sevda anlamak zor, gözlerin kılçık atıyor 

Beni sana düğümleyen tatlı dillerin oluyor.

Ne cinim ne de bir melek, bir insanım yolu dölek 

Gamı bana yükler felek, ödül ellerin oluyor

Renkleri senden düşlerin, beytülkasid''dir kaşların 

Peşine düştüm kuşların, sebep gellerin oluyor

Karakoç yolunu seçmiş, seninle kendinden geçmiş 

Sığındığı tek gölgelik, yeşil dalların oluyor…

Bahaeddin KARAKOÇ (Leyl ü Nehar Aşk – T.Diy.Vak.Yay. 1997 / ANKARA)', 'Nehrin ortasına düştüm burgaçta dönüp dururum  Bana değip kaçan balık birden ellerin oluyor. Ben ağlarken yaşın yaşın çözülen kara bulutlar ...', ARRAY['Türk Edebiyatı','Şiir','Bahaettin Karakoç']::text[], 8.5, '{"poet":"Bahaettin Karakoç","poet_slug":"bahaettin-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/hayatim-sana-ayarli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Y o n t u (Yeni)', 'y-o-n-t-u-yeni-baki-sulopasa-xwmmc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'El ayak çekilince

Ocağın derininde

Kıyarım mermerime

Çekicimle, keskimle

İşlendikçe ışıldar

Oniksten somakiye

Renkler yarışır

Kütlemin teninde.

Kendimi yontarım

Yonga yonga

Ağırır başım

Aşınır günlerim, yıllarım.

Hamurumda buldum

Kalsiyum, magnezyum

Sabahtan, akşama

Kendimi yoğuruyorum.

Aşındırıcılar, yüzeyimi parlatır

Güneş, işledikçe içime

Otuz sekiz milimetre

Kristallerim işıldar

Işığım, gönülleri ısıtır.', 'El ayak çekilince Ocağın derininde Kıyarım mermerime Çekicimle, keskimle İşlendikçe ışıldar Oniksten somakiye Renkler yarışır Kütlemin tenin...', ARRAY['Türk Edebiyatı','Şiir','Baki Sulopaşa']::text[], 8.5, '{"poet":"Baki Sulopaşa","poet_slug":"baki-sulopasa","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/y-o-n-t-u-yeni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ve Bu Andaç Şiir Kaldı', 've-bu-andac-siir-kaldi-bahaettin-karakoc-4zen8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Benim ışıklı küremde ne mavi ne de al kaldı 

Boşaldı bütün kovanlar, ne arı ne de bal kaldı.

Fırtınanın şiddetini anlatacak her söz eksik 

Savruldu bütün yapraklar, ne sağlam kök ne dal kaldı.

Bağ viran, bağban çaresiz, çit çekmenin yararı ne, 

Kader dağ koydu omuza, yürüyecek ne hâl kaldı? 

Bel ince, bilekler ak gül, gözlerse yağmur ormanı 

Ne o ince belde kuşak, ne de omuzda şal kaldı.

Kuğu boyunlu sevgilim, akşam sedef, sabah köpük 

Gökte ayla bütünleşmiş, ne hasret ne visâl kaldı.

Tanklarla ezdi içimi, ahımı duymadan geçti 

Ne onda insaftan eser, ne bende bir mecâl kaldı.

Kurtulunca her kesretten, tat aldım aşktan, hasretten 

Bendeki ben''i buldum ben, ne Merih ne Zuhal kaldı.

Unuttum kuruyu yaşı, dağıttım doluyu boşu 

Neyleyim toprağı taşı, gönlümde zü-l-celâl kaldı.

İlişkiler zincirinde eşyanın nabzını tuttum 

Islık çalmayı unuttum, dilimde zü-l-cemâl kaldı

Çöl çiçeğinin ak düşü, çıktığı yerde battı su 

Karakoç''un aynasında yârin yüzü zülâl kaldı...

Bahaeddin KARAKOÇ (Leyl ü Nehar Aşk – T.Diy.Vak.Yay. 1997 / ANKARA)', 'Benim ışıklı küremde ne mavi ne de al kaldı  Boşaldı bütün kovanlar, ne arı ne de bal kaldı. Fırtınanın şiddetini anlatacak her söz eksik  S...', ARRAY['Türk Edebiyatı','Şiir','Bahaettin Karakoç']::text[], 8.5, '{"poet":"Bahaettin Karakoç","poet_slug":"bahaettin-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ve-bu-andac-siir-kaldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Sordum', 'bana-sordum-ramazan-ates-8nc1o', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yaşın kırkı bile çoktan geçmişken,

Sevdaya tutulmak neyine senin? 

Kırk yıldır hep acı çile çekmişken,

Ateşe atılmak neyine senin? 

Bunca yıl gönlüne sözün geçmemiş,

Nerdeyse ömrüyün sonuna gelmiş,

Olur mu? Olmaz mı? Hiç düşünmemiş,

Coşkuya kapılmak neyine senin? 

Ağzında dişin yok, tepende saçın,

Yaşına baksana kaç olmuş yaşın? 

El ağzı torba mı tutup büzesin? 

Laf olup satılmak neyine senin? 

Anladık gönlüne sözün geçmemiş,

Yüreğin vurulmuş, gücün yetmemiş,

Dileğim odur ki artık yetmeli,

Terk edip gidilmek neyine senin? 

Yaş olup dökülmek neyine senin? 

Ramazan Ateş/Enschede-27.3.2006', 'Yaşın kırkı bile çoktan geçmişken, Sevdaya tutulmak neyine senin?  Kırk yıldır hep acı çile çekmişken, Ateşe atılmak neyine senin?  Bunca yı...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bana-sordum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilin Kemiği Yok', 'dilin-kemigi-yok-fatma-guven-s471x', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dilin kemiği yok,

Gırtlak kırk boğum.

Kendini bilmez olursa insan,

Kırk boğumu hesaplamaz,

Olur dilinin kölesi.

Be hey şaşkın! .....

Kör düğümleri atarsın da,

Açmaya başkasını mı çağırırsın? 

Yürek gerek doğru sözü söylemeye.

Dokuz köyden kovulsada,

Onuncu köyde eğlenmeye.

Sanırım bu sözlerim yeter,

Kendi kendini bilmeyene.', 'Dilin kemiği yok, Gırtlak kırk boğum. Kendini bilmez olursa insan, Kırk boğumu hesaplamaz, Olur dilinin kölesi. Be hey şaşkın! ..... Kör düğ...', ARRAY['Türk Edebiyatı','Şiir','Fatma Güven']::text[], 8.5, '{"poet":"Fatma Güven","poet_slug":"fatma-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/dilin-kemigi-yok-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzun', 'uzun-sumer-kucuk-p8w00', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İçeridekilerin

Tek

Dostlları

Uzun  uzun

Düşünmeleridir.', 'İçeridekilerin Tek Dostlları Uzun  uzun Düşünmeleridir....', ARRAY['Türk Edebiyatı','Şiir','Sümer Küçük']::text[], 8.5, '{"poet":"Sümer Küçük","poet_slug":"sumer-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/uzun-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünya', 'dunya-sumer-kucuk-yi526', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dünya bu

Kimi sevişir gezer

Kimi canından bezer

Kimide dünyadan tezer

Dünya bu', 'Dünya bu Kimi sevişir gezer Kimi canından bezer Kimide dünyadan tezer Dünya bu...', ARRAY['Türk Edebiyatı','Şiir','Sümer Küçük']::text[], 8.5, '{"poet":"Sümer Küçük","poet_slug":"sumer-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/dunya-117-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*FeRMaN PaDiŞaHıN sa DaĞLaR BeNiMDiR*', 'ferman-padisahin-sa-daglar-benimdir-mine-ozdemirtas-0xola', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Küçük dağları ben yaratmadım elbet

Ama 

şu gördüğün yamaçlar benim eteklerim

benden yana esmesen de olur

bir el ettim mi şimale

bil ki 

uçuşur dantellerim.

Şerbetin şekerine  bir damla limon

Sıkmaya bile üşenirken ellerin

“Bu dergahtan içeri eğri odun bile giremez” 

Demiş diye derviş.

Sanma ki

Sen ormanı biçerken 

Ben sabırla beklerim. 

Heyhat! 

dardır yenim/ dardır yerim

Bu gidişle; 

Ya,

Göklere dayadığım o masalsı merdivenin

Son basamağın da inerim

Ya da

(Nasıl olsa, bu düş benim)

Bütün uykuları alır / giderim.

27/03/2006', 'Küçük dağları ben yaratmadım elbet Ama  şu gördüğün yamaçlar benim eteklerim benden yana esmesen de olur bir el ettim mi şimale bil ki  uçuş...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ferman-padisahin-sa-daglar-benimdir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kutlu Rota', 'kutlu-rota-turhan-toy-nwpbs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Haydi, vaktimiz tamam kalkıyoruz limandan 

Demir alsın tayfalar tam yol ileri kaptan 

Çarşaf gibi denizde sevdalar uçuşuyor 

Balıklar aşk’a gelmiş gemimize koşuyor 

Martılar çember olmuş başımızda taç gibi 

Deniz öyle berrak ki görünüyor en dibi 

Bu geminin adı aşk yükü cennet sevgisi 

Yolcular suni değil sanki insan delisi 

Samimiyet onların olmazsa olmaz sözü 

Adalet’ ten ayrılmaz Haktadır daim gözü 

Bir yaralı kuş görse ölümlere atlanır

Dökülen onca kana söyle kimler katlanır 

Geminin rotasını döndür kutlu sevdaya 

Selam götürsün rüzgar o masum Rüveyda’ya 

Kutlu sevda yolunda devasa dalga durur 

Geminin gövdesine arka arkaya vurur 

Gayesi gemimizi alabora etmektir 

Sevda yolcularının fikrini kemirmektir 

Yolcular hazırlıklı her engeli aşmaya 

Denizler taşsa bile menzile ulaşmaya 

Kopsa kara fırtına azgın dalga kudursa 

Yüreğinden kopan aşk dalgaları durdursa 

Sevda öyle bir bağ ki kopması mümkün değil 

At gururu kenara Hakkın önünde eğil', 'Haydi, vaktimiz tamam kalkıyoruz limandan  Demir alsın tayfalar tam yol ileri kaptan  Çarşaf gibi denizde sevdalar uçuşuyor  Balıklar aşk’a ...', ARRAY['Türk Edebiyatı','Şiir','Turhan Toy']::text[], 8.5, '{"poet":"Turhan Toy","poet_slug":"turhan-toy","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kutlu-rota-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sefalet', 'sefalet-mustafa-sargin-8egc0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İsyan etsem artık neye yarar

Alcanımı işte hepsi bukadar

Bilirsinki aşkına olmuşum sefalet

Kır gönlümü işte hepsi bukadar

Zaten sevderken yanılmış gözlerim

Acıyorum halime kime ne söyleyim

Bir ahtım vardı oda oldu sefalet

Böylemiydi böylemi olacaktı aşkım

Getirse seni bana sonsuz geceler

Yinemi dolanır gönlüme çileler

Farketmez gülüm olsada sefalet

Ben zaten ölmüşüm boşa olur hayeller', 'İsyan etsem artık neye yarar Alcanımı işte hepsi bukadar Bilirsinki aşkına olmuşum sefalet Kır gönlümü işte hepsi bukadar Zaten sevderken ya...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Sargın']::text[], 8.5, '{"poet":"Mustafa Sargın","poet_slug":"mustafa-sargin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sefalet-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İzmit', 'i-zmit-harun-kaya-3-eq2gt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Atim kaldım yetim kaldım ondan sonra,

Gözlerimde yaş durulmaz dünden sonra,

onyedi austos depreminden sonra,

böyle yıkım gördünmü sen izmit.

giderken canımı aldıda gitti,

yollara kanımı yaydıda gitti,

gözümden nurumu çaldıda gitti,

sorulurmu yanağımdaki yaşlar izmit.

Canım dedim canım bildim sarıldım,

Ona daha ilk gördüğüm an vuruldum,

Bu ateşte kavrulmaktan yoruldum,

Körfezi boca etsen söndüremezsin izmit

Kuru dalga sesinden başka ne bıraktın kulaklarımda,

yarım kaldı sevda türkülerim dudaklarımda,

Volkan gibi kaynarken göz yaşlarım yanaklarımda,

İbrahim gibi ateşlere yandıramazsın artık  izmit.

Canımı alacaksın ama alamayacaksın sevdamı,

Cehennemim bile olsa sürdüreceğim bu gönül davamı,

senin içini bilirim şerefsiz çek omzumdan sahte göz yaşlarını,

sellerin bile onda biri etmez göz yaşlarımın izmit.

Her şeyin sahte lan senin, aşkında baharın, yağmurun gibi,

Yüreksizsin izmit sen bağrında yürekli gezermi,

Bin kat fazla severdim senden sevilmeyen cehennemi,

Bir ömür biriken mutluluğu bir günde sildin izmit.

            Harun KAYA

   Bu şiirin her türlü yayın hakkı şairin kendisine ve/veya temnsilcisine aittir', 'Atim kaldım yetim kaldım ondan sonra, Gözlerimde yaş durulmaz dünden sonra, onyedi austos depreminden sonra, böyle yıkım gördünmü sen izmit....', ARRAY['Türk Edebiyatı','Şiir','Harun Kaya 3']::text[], 8.5, '{"poet":"Harun Kaya 3","poet_slug":"harun-kaya-3","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/izmit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbulu arıyorum..!', 'i-stanbulu-ariyorum-mehmet-goden-9h295', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Küçük bir pencereden görüyorum seni,

Yaşlı İstanbul...

Yüzün yorgun! bedenin hasta,

Üzgünmüsün bu haline? 

Gözün puslu! kalbin yasta! 

Yeşilin yerine, yapılar konmuş! 

Yedi tepene, milyon evler,

Her bir haneye bin umutla,

Uzak diyarlardan gelmişler,

Kimler yaşar oralarda? 

Ne ederler bilmezmisin? 

Sokakların onca Lale,

Her biriyle bir yerdensin! 

Tepelerin  çarpık evler,

Her birisi, bir çirkinler! 

Her yerinde,İstanbul yok! 

Sokak sokak başka yerler! 

İstanbul`um ah İstanbul! 

Sen ne bakir bir yermişsin? 

Onca çalınan  güzelliğini,

Has yüzüne  vermişsin.

27.03.2006

BERLiN', 'Küçük bir pencereden görüyorum seni, Yaşlı İstanbul... Yüzün yorgun! bedenin hasta, Üzgünmüsün bu haline?  Gözün puslu! kalbin yasta!  Yeşil...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Göden']::text[], 8.5, '{"poet":"Mehmet Göden","poet_slug":"mehmet-goden","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/istanbulu-ariyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğin Ateşlere Düşerse', 'yuregin-ateslere-duserse-cebrail-akbayir-3r0cl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yüreğin ateşlere düşerse; 

Bir umutla gökyüzünün maviliğini

Denizin derinliklerine götürmelisin

Gece sıcak bir dokunuş

Güneşin ilk ışıklarındaysa

Mutlu bir gülüş olmalıyım bakışlarında

Bir nefesçesine içine çekmelisin beni

Ekmek gibi su gibi bir şey

İçtikçe beni içmelisin su tadında

Gözlerin gözlerimi aramalı

Taş yürekli sokakların tenhasında

Ardından gelip usulca seslenmelisin

Avuçlarıma sımsıcak bir yürek bırakmalısın

Gözlerini kapadığında bir sen olmalısın

Açtığında da bir ben…

Yüreğin ateşlere düşerse.', 'Yüreğin ateşlere düşerse;  Bir umutla gökyüzünün maviliğini Denizin derinliklerine götürmelisin Gece sıcak bir dokunuş Güneşin ilk ışıkların...', ARRAY['Türk Edebiyatı','Şiir','Cebrail Akbayır']::text[], 8.5, '{"poet":"Cebrail Akbayır","poet_slug":"cebrail-akbayir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yuregin-ateslere-duserse-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Su Damlası', 'su-damlasi-melih-coskun-u5y7o', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ömrüm; 

Genç bir kızın simsiyah saçlarından 

Alnına süzülen bir su damlası,

Akıp geçiyor gözlerimden, yüreğimden...

Ayın ondördünün beyaza boyadığı

Terk edilmiş dağ köyleri görüyorum 

Sonra bulvarlar, caddeler 

Sonra uçsuz bucaksız kalabalıklar

Hep bir ağızdan zafer şarkıları söyleyen

Bir parça ay ışığı 

Gözlüklerimin camında, 

Aklımda bir soru

Ölüm dediğin nedir ki? 

-Sonsuzlukta küçücük bir an 

Öyleyse seni bunca korkutan; 

-Koklayamamak baharda açacak çiçekleri 

Doğmamış çocukların 

Süt kokuşunu duyamamak 

Ağlayamamak ilk baba deyişlerinde

Süzülüyor su damlası 

Kızın alnından 

Kemanın tellerine. 

Terk edilmediği halde 

Aranıp sorulmayan arka mahalleler geliyor aklıma 

Ve o mahallelerin 

Aransa da  bir daha asla bulunamayan çocukları. 

Sonra 

Meydanlar 

Hınca hınç yürekle dolu

Hep bir ağızdan zafer şarkıları söyleyen

Haykırmak istiyorum onlarla birlikte

Ağzımda beyaz bir mendil 

Dişlerimin kanıyla kızıla boyanmış. 

Susuyorum...

Yürüyor su damlası 

Kemanın tellerinden perdelerine doğru

Bir ışık sönüyor ansızın 

Orta Anadolu’nun sert iklimli şehirlerinden birinin 

Herhangi bir evinde

Bir mezar çöküyor ansızın, 

Su damlası düşüyor toprağa,

Susuyor keman 

Susuyorum... 

2006

www.melihcoskun.com', 'Ömrüm;  Genç bir kızın simsiyah saçlarından  Alnına süzülen bir su damlası, Akıp geçiyor gözlerimden, yüreğimden... Ayın ondördünün beyaza b...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/su-damlasi-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nergis', 'nergis-serap-tepedelen-blepu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni yalçın dağlardan getirdiler bana

Sarı tohumlarınla gülümsedin.

Soğuk ve karanlık gecelerin ardından,

Korkunun buz tutan nefesi

Yalarken ensemizi

Gülümseyiverdin nergis,

Tüm sıcaklığınla...

Masanın üstüne bırakmış

Adını gizleyen öğrencim.

Dağların kokusu yayıldı burcu burcu

Elime aldım,kokladım.

Gözlerimin önünde binlerce nergisin

Gizemli güzelliği,

Ağladım.

Ve sen nergis,

Bir tedirginlik sararken yürekleri,

Gülümseyiverdin.

(1992,Pervari/Siirt)', 'Seni yalçın dağlardan getirdiler bana Sarı tohumlarınla gülümsedin. Soğuk ve karanlık gecelerin ardından, Korkunun buz tutan nefesi Yalarken...', ARRAY['Türk Edebiyatı','Şiir','Serap Tepedelen']::text[], 8.5, '{"poet":"Serap Tepedelen","poet_slug":"serap-tepedelen","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/nergis-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine aşık oldum,allah kahretsin..', 'yine-asik-oldum-allah-kahretsin-ercan-akbay-6pxld', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yine aşık oldum,allah kahretsin,

      Yine düşeceğim, meyhanelere,

      Yine tanıyacak, kadehler beni,

      Yine derdi derde,ekleyeceğim.

      Yine kırılacak,düşlerim bir bir,

      Yine izmaritler,sensiz sönecek,

      Yine uzanacak,kaldırım taşı,

      Yine bir cesete,dönecek ruhum.

      Yine aşık oldum,allah kahretsin,

      Yine şiirlere,gebe geceler,

      Yine ayrılıklar,şarkı olacak,

      Yine ben mecnunum,sen yine LEYLA...

                                                       2006 KIŞ.', 'Yine aşık oldum,allah kahretsin,       Yine düşeceğim, meyhanelere,       Yine tanıyacak, kadehler beni,       Yine derdi derde,ekleyeceğim....', ARRAY['Türk Edebiyatı','Şiir','Ercan Akbay']::text[], 8.5, '{"poet":"Ercan Akbay","poet_slug":"ercan-akbay","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yine-asik-oldum-allah-kahretsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Damla Daha', 'bir-damla-daha-tibet-avci-imfql', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben bir erik ağacı

Sen hayat pınarı

Bir dokunup toprağıma

Kaçtın sonra

Ne olur bir damla

Bir damla daha..', 'Ben bir erik ağacı Sen hayat pınarı Bir dokunup toprağıma Kaçtın sonra Ne olur bir damla Bir damla daha.....', ARRAY['Türk Edebiyatı','Şiir','Tibet Avcı']::text[], 8.5, '{"poet":"Tibet Avcı","poet_slug":"tibet-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/bir-damla-daha-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdik', 'sevdik-serap-tepedelen-wjkcd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevdik,

    delicesine.

Kanadı yüreğimiz.

     her kanayan yüreğe,

            karanfiller ektik biz.

 (1998,Bursa)', 'Sevdik,     delicesine. Kanadı yüreğimiz.      her kanayan yüreğe,             karanfiller ektik biz.  (1998,Bursa)...', ARRAY['Türk Edebiyatı','Şiir','Serap Tepedelen']::text[], 8.5, '{"poet":"Serap Tepedelen","poet_slug":"serap-tepedelen","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sevdik-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karmaşa', 'karmasa-tibet-avci-0x7zu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dışında bir kapının,

Kıyısında bir denizin,

Tepesinde bir ağacın,

Kenarında bir şehrin,

Ucunda hayatın,

Ortasındayım derdin..

Herşeyin kenarında

Ama derdin tam ortasında

Bu nasıl bir karmaşa?', 'Dışında bir kapının, Kıyısında bir denizin, Tepesinde bir ağacın, Kenarında bir şehrin, Ucunda hayatın, Ortasındayım derdin.. Herşeyin kenar...', ARRAY['Türk Edebiyatı','Şiir','Tibet Avcı']::text[], 8.5, '{"poet":"Tibet Avcı","poet_slug":"tibet-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/karmasa-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine gelecek', 'yine-gelecek-harun-kaya-3-wowx4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yine pusudayım kapkaranlık bir mezarın içinde.

Gözüm açık başım dik,

Elim kurma kolu ve tetikte 

Gözüm en ufak harekette,

Pür  dikkat  bekliyorum.

Biliyorum her akşam olduğu gibi bu akşamda gelecek,

yine vuracak,

Ve yine gün doğarken hiç bir şey olmamış gibi çekip gidecek.

              

Kan ter içinde kalmış vücudum rüzgarın keskin uğultusu ile tiremekte.

Gelişini hisseden zavallı tenim tüy tüy diken diken irkilmekte. 

.Arkadaşlarıma sesleniyorum 

''Duydunuzmu geliyor işte yaklaşıyor  diyorum,

Öyle bir çocuğun boş bakışları ile 

Bakıyorlar bana acırmış gibi bir deliye,.

Ama haklılar tek bana geliyor Allah''ın belası 

Tek benim için geliyor.

Yaklaşıyor dur diyorum anlamıyor 

Öldürürüm diyorum dinlemiyor,

Sadece yaklaşıyor ve gülüyor dişlerini göstererek. 

Vahşi kurtlar gibi saldırıyor üstüme,

Basıyorum tetiğe 

Kapıp koyu verilyorum namludan başı boş kurşunları sağa sola pervasız ca,

Deliriyor,kuduruyor

Vuruyor Allahsız göğsümü yırtarcasına,

Vuruyor kitapsız kalbimi parçalarcasına,

Savuruyor sana atan kalbimi kıskanırcasına.

Vuruyor vuruyor vuruyor! ! ! ! 

......

......

.......

Ve gidiyor

               

Biliyorum yine her akşamki gibi yarın akşamda gelecek

Yine vuracak ve yine her sabahki gibi çekip gidecek 

Biliyorumki bir tanem yine senin hasretin beni her gece ziyaret edecek.

Senin hasretin hep gelecek

  Harun KAYA

    BU şiirin her türlü telif hakkı şairin kendisine ve/veya temsilcisine aittir', 'Yine pusudayım kapkaranlık bir mezarın içinde. Gözüm açık başım dik, Elim kurma kolu ve tetikte  Gözüm en ufak harekette, Pür  dikkat  bekli...', ARRAY['Türk Edebiyatı','Şiir','Harun Kaya 3']::text[], 8.5, '{"poet":"Harun Kaya 3","poet_slug":"harun-kaya-3","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/yine-gelecek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alev Mavisi Yüreğim', 'alev-mavisi-yuregim-cebrail-akbayir-wn22m', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kendimi bildim bileli

Mavidir günlerimin gözleri,

Suların köpükleri, giysilerim, ellerim...

Bildim bileli kendimi

Yel mavi eser, güller mavi kokar,

Bülbülün kanı mavi akar.

Bulutlar umut yüklüdür,

Düşerim bulutlardan damla damla

Ulaşamadan toprağın yüreğine,

Yakar beni güneşin saçları.

Alev mavisi kalır benden geriye

Masmavi', 'Kendimi bildim bileli Mavidir günlerimin gözleri, Suların köpükleri, giysilerim, ellerim... Bildim bileli kendimi Yel mavi eser, güller mavi...', ARRAY['Türk Edebiyatı','Şiir','Cebrail Akbayır']::text[], 8.5, '{"poet":"Cebrail Akbayır","poet_slug":"cebrail-akbayir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/alev-mavisi-yuregim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzak! uzaklar...!', 'uzak-uzaklar-nazan-i-zmirli-a1sup', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bir  tutam 

toprak,

bir  yudum 

sevgi,

kadeh kadeh

aşk  şarabını,

sabırla  demle.

yoğur   özlemlerinle

özgür    yüreklilikle

kokun,  terin,  nefesinle

şekille.

söz....! 

razı   geleceğim   bahtıma

şu  an   olduğumdan  farklı

bir  yürek  koyabilirsen  ortaya.

uzak.....! 

uzaklar......! 

bu  yürek  seninle   demlendi

yıllardır......zamanla.......

ne  farkeder ki  uzaklar.......

nehirler   değilmi   kıtadan  kıtaya

hayat  veren, birbirini   görmeden

seven.........! ..vazgeçemeyen.......! 

zamanla.......! 

ben

çöllerde  toprak

sen

dağların  buzlu  suları

uzak ! 

uzaklar....! 

...........sevilir

...................zamanla

...............................ulaşılınca.

bu  yürek  seninle  demlendi  yıllarla.

28.03.06- uzak!  uzaklar!', 'bir  tutam  toprak, bir  yudum  sevgi, kadeh kadeh aşk  şarabını, sabırla  demle. yoğur   özlemlerinle özgür    yüreklilikle kokun,  terin, ...', ARRAY['Türk Edebiyatı','Şiir','Nazan İzmirli']::text[], 8.5, '{"poet":"Nazan İzmirli","poet_slug":"nazan-i-zmirli","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/uzak-uzaklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fok', 'fok-ufuk-bayraktar-wt7kg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '________________kutuplarda katledilen foklar için...

biliyor musun,

o üstündeki

hani memelerini örttüğün; 

işte o

hiç yakışmamış sana.

çünkü

o kırmızı kan da

yakışmadı buz mavisi kıyıya.', '________________kutuplarda katledilen foklar için... biliyor musun, o üstündeki hani memelerini örttüğün;  işte o hiç yakışmamış sana. çünkü...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Bayraktar']::text[], 8.5, '{"poet":"Ufuk Bayraktar","poet_slug":"ufuk-bayraktar","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/fok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığın Anatomisi', 'yalnizligin-anatomisi-mehmet-tas-rediw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gün batar, hasret düşer 

Yalın ayak düşlerin yangın yerinde koştuğu 

Yanık yüreklerin ortalık yerine.

Sessizlik derin bir kuyu

Düşüncelerin bir gelip bir gittiği yerde

Başucunda kaç kere okumaya yeltendiğin

Kaç kere sayfaları arasında kaybolup gittiğin 

Yarım kalmış bir ömrün romanı.

Bir paket sigara 

Ve bir kalem 

Tüm yarımları tamamlamak isteyen.

Gece ıslak bir gömlek gibi çöker üstüne

Titrer bedenin ruhunun ayazında

Verilmiş sözler

Unutulmuş yeminler

Kayboluşlar

Ve bütün geç kalışlar

Sıralanır yattığın yer minderinin ayakucuna.

Zaman durur

Silinir bütün renkleri tuvallerin

Derin derin solumalar 

Boşlukta yankılanır.

Duvarlar konuşur

Hayaller dolaşır

Yalnızlık gece gibi koyulaşır

Geç kalmış hevesler ardında

Silik bir tebessüm kalır.

Gün doğar, hasret başlar

Yalın ayak düşlerin yangın yerinde koştuğu 

Yanık yüreklerin ortalık yerine.', 'Gün batar, hasret düşer  Yalın ayak düşlerin yangın yerinde koştuğu  Yanık yüreklerin ortalık yerine. Sessizlik derin bir kuyu Düşüncelerin ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Taş']::text[], 8.5, '{"poet":"Mehmet Taş","poet_slug":"mehmet-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/yalnizligin-anatomisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sende Solacaksin', 'sende-solacaksin-kemal-oguz-0y3cg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kirlarda ciceklerin, ömrü olurmus kisa.

Yapraklari oksiyan, hazan yelleri gibi.

Zaman Seni soldurur, nekadar taze olsan.

Hayat akip gidiyor, yagmur selleri gibi.

Birgün sona erecek, Seninde saltanatin.

Yarali kuslar gibi, kirilacak kanadin.

Kalpte tatli nagmeler, hisler yaratan adin.

Ses vermiyecek pasli, keman telleri gibi.

Hatirdan silinecek, güzel yüzün cehrende.

Yalniz uzak, belirsiz, bir iz kalacak bende.

Solacaksin nekadar, solmak istemesende.

Ömrü bir mevsim süren, hanim elleri gibi.

Filderstadt', 'Kirlarda ciceklerin, ömrü olurmus kisa. Yapraklari oksiyan, hazan yelleri gibi. Zaman Seni soldurur, nekadar taze olsan. Hayat akip gidiyor,...', ARRAY['Türk Edebiyatı','Şiir','Kemal Oguz']::text[], 8.5, '{"poet":"Kemal Oguz","poet_slug":"kemal-oguz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sende-solacaksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektuplar-108 05/05/0001', 'mektuplar-108-05-05-0001-mahzun-doga-bpzbq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gibi değilsin

-cesine de değil

ne sanki

ne de bir şey

benzer gibi hiç değil

Kesin’sin

net’sin

O’sun

sen’sin

ben', 'Gibi değilsin -cesine de değil ne sanki ne de bir şey benzer gibi hiç değil Kesin’sin net’sin O’sun sen’sin ben...', ARRAY['Türk Edebiyatı','Şiir','Mahzun Doğa']::text[], 8.5, '{"poet":"Mahzun Doğa","poet_slug":"mahzun-doga","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/mektuplar-108-05-05-0001-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektuplar-109 06/05/0001', 'mektuplar-109-06-05-0001-mahzun-doga-jy9yo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ve oldu

yokluğuna yakıştı varlığın

ve oldu

içine tam oturdu yalnızlığım

ve oldu

oldun

Giydiğimiz o kıyamet

o mavi sevgilik

Masumine çocuk

oldu

kalmamaya ramak kala

olduk

Kime anlatsak inanmazdı

ve inanmadı

kime anlatamadıysak

seni bende ihtimal

beni sende sen

inanmadı inanan hiç kimse

olmuşken bu kadar olmak

Ve oldu

olmamışken yarımken

olmuşken iki tamız şimdi

ve olduk', 'Ve oldu yokluğuna yakıştı varlığın ve oldu içine tam oturdu yalnızlığım ve oldu oldun Giydiğimiz o kıyamet o mavi sevgilik Masumine çocuk ol...', ARRAY['Türk Edebiyatı','Şiir','Mahzun Doğa']::text[], 8.5, '{"poet":"Mahzun Doğa","poet_slug":"mahzun-doga","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/mektuplar-109-06-05-0001-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Toruna mektup', 'toruna-mektup-harun-kaya-3-3yq0k', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Duydum açmışsın dünyaya gözlerini,

Boş boş bakmışsın çirkef hayata.

Dolmuşsun birden sel olmuş göz yaşların,

Baban şehit oldu deyip ağlattılarmı seni yavrum.

Sarılmışsın yaslamışsın başını ananın göğsüne,

Küfretmişsin içinden acır bakan gözlere,

İki damla yaş düşmüş zavallı ananın dizine,

Baban şehit oldu deyip üzdülermi seni yavrum.

Yollara bakmışsın büzmüşsün dudağını,

Babandan önce yaşlar öpmüş yanağını,

Küçücük yüreğinde hep kanayan yaranı,

Baban şehit oldu deyip dağladılarmı yavrum.

               Harun KAYA

    Bu şiirin her türlü telif hakkı şairin kendine ve/veya temsilcine aittir', 'Duydum açmışsın dünyaya gözlerini, Boş boş bakmışsın çirkef hayata. Dolmuşsun birden sel olmuş göz yaşların, Baban şehit oldu deyip ağlattıl...', ARRAY['Türk Edebiyatı','Şiir','Harun Kaya 3']::text[], 8.5, '{"poet":"Harun Kaya 3","poet_slug":"harun-kaya-3","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/toruna-mektup-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kızanım-1', 'kizanim-1-veysel-alkan-erf0d', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Nasılsın diyisin,nasıl olalım? 

Bilisin halimiz beter Kızanım! 

Süleyip seni de niye yoralım? 

Sen İsle ol,bizi kolver Kızanım! 

Buğdayı bekledik,para etmedi.

Gündöndü güdüktü,borç ödetmedi.

Emekli maaşı zatı yetmedi.

Sen İsle ol,bizi kolver Kızanım! 

Tuhuma,mozuta para yetişmez.

İhtiyaç gübreye,sıra da gelmez.

Toplasak mahsülü,masrafa ermez.

Sen İsle ol,bizi kolver Kızanım! 

Hökümet,tarımı destekler be ya.

Çiftçiyi, kredi köstekler be ya.

Mahsülü alırken,kesçekler be ya.

Sen İsle ol,bizi kolver Kızanım! 

Biz zatı alışık,dünden yokluğa.

Hasrette değiliz,malda çokluğa.

Ermesek ne olur,artık bolluğa.

Sen İsle ol,bizi kolver Kızanım! 

Zatı:Zaten

İsle(ıslah) :iyi,güzel

Beter:kötü

Güdük:zayıf,çelimsiz.

Gündöndü:Ayçiçeği,Günebakan 

Kolvermek(Koyvermek) :boşvermek,önemsememek.

Süleyip:söyleyip

Bilisin:biliyorsun.

Diyisin:diyorsun.

Kızanım 2 şiiri için tıklayın', 'Nasılsın diyisin,nasıl olalım?  Bilisin halimiz beter Kızanım!  Süleyip seni de niye yoralım?  Sen İsle ol,bizi kolver Kızanım!  Buğdayı bek...', ARRAY['Türk Edebiyatı','Şiir','Veysel Alkan']::text[], 8.5, '{"poet":"Veysel Alkan","poet_slug":"veysel-alkan","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/kizanim-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Para Para Para', 'para-para-para-serhat-caliskan-v73ls', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Eşim dostum arkadaşım,hep paraya tapar olmuş

Dünya zenginin yurdu fakire azap olmuş

Yoksa cebinde paran it senden farksız olmuş

Malı olan padişah,haşa para din olmuş.

Fakir aşık olamaz parası yoktur

Çocuğu hasta olsa dermanı yoktur,

Okumak ister ama bu ona çoktur

Çünki tüm kilitleri,hep para açar olmuş

Nerde benim sevenlerim,nerde dost bildiklerim,

Dünyaya zengin geldim,parasızda giderim

Altından evler yapın,parayı yola serin

Zira sizin gönlünüz paraya esir olmuş.

Kardeş kardeşi vurur bu pis kağıt uğruna

Nice yuva yıkılır hep bu para bokuna

Mezarada götürün aman bırakmayın ha

Olurya karşı köyde servetiniz sorulur', 'Eşim dostum arkadaşım,hep paraya tapar olmuş Dünya zenginin yurdu fakire azap olmuş Yoksa cebinde paran it senden farksız olmuş Malı olan pa...', ARRAY['Türk Edebiyatı','Şiir','Serhat Çalışkan']::text[], 8.5, '{"poet":"Serhat Çalışkan","poet_slug":"serhat-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/para-para-para-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağılacağız', 'dagilacagiz-seval-kemertas-gxdri', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Az sonra 

Bütün saatler duracak

Bozkır suskunluğuna teslim olacağız

Üstümüze üşüşen kül rengi bulutlar

Kirletecek düşlerimizi

Hoyrat bir rüzgar esecek

Yine cehennem olacak yürek

Kurşun gibi geceye atılan

Bir tren çığlığında

            DAĞILACAĞIZ……

28.03.2006    01:00', 'Az sonra  Bütün saatler duracak Bozkır suskunluğuna teslim olacağız Üstümüze üşüşen kül rengi bulutlar Kirletecek düşlerimizi Hoyrat bir rüz...', ARRAY['Türk Edebiyatı','Şiir','Seval Kemertaş']::text[], 8.5, '{"poet":"Seval Kemertaş","poet_slug":"seval-kemertas","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/dagilacagiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmiyorsun', 'bilmiyorsun-harun-kaya-3-l4bsm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Atım yatağında hazır bekliyor hep kelimelerin,

Namludan çıkmadan bile nasıl acı verdiğini bilmiyorsun,

Kırıldığın kadar kırmayı adet edinmişsin ama,

Kırıldığından çok kırdığını görmüyorsun..

    HArun KAYA

  Bu şiirin telif hakkı şairin kendisine ve/veya temsilcisine aittir', 'Atım yatağında hazır bekliyor hep kelimelerin, Namludan çıkmadan bile nasıl acı verdiğini bilmiyorsun, Kırıldığın kadar kırmayı adet edinmiş...', ARRAY['Türk Edebiyatı','Şiir','Harun Kaya 3']::text[], 8.5, '{"poet":"Harun Kaya 3","poet_slug":"harun-kaya-3","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/bilmiyorsun-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevişiyorsan', 'sevisiyorsan-harun-kaya-3-d2dsw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Eğer ilk deneyimini yaşayan bir kadınla sevişiyorsan ve gözleri kapalıysa,

Korkuyordur; sakinleştir

NAZİK OL! ! ! 

Eğer seviştiğin kadın çekingense ve gözleri kapalıysa,

Gözgöze gelmeye utanıyordur, sende bakma 

SAYGILI OL! ! ! 

Eğer seviştiğin kadın hayat kadınıysa ve gözleri kapalıysa,

Bu onun mesleği nasıl olsa. Sende rol yap 

RAHAT OL! ! ! 

Eğer seviştiğin kadın çapkınsa ve gözleri kapalıysa,

O an seni başkasıyla aldatıyordur gözlerini açtır 

DİKKATLİ OL! ! ! 

Eğer seviştiğin kadın bu özelliklerin hiçbirini taşımıyor ve gözleri kapalıysa,

Uyuyordur, eline bir sigara alıp uyanmasını bekle,

AKILLI OL! ! ! ! ! ! ! ! ! 

                      Harun KAYA

Bu şiirin her türlü telif hakkı şairin kendine ve/veya temsilcisine aittir.', 'Eğer ilk deneyimini yaşayan bir kadınla sevişiyorsan ve gözleri kapalıysa, Korkuyordur; sakinleştir NAZİK OL! ! !  Eğer seviştiğin kadın çek...', ARRAY['Türk Edebiyatı','Şiir','Harun Kaya 3']::text[], 8.5, '{"poet":"Harun Kaya 3","poet_slug":"harun-kaya-3","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sevisiyorsan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnız İçilen Çaylar', 'yalniz-i-cilen-caylar-gamze-kaya-uans2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '(Cancağızıma...) 

Yine yalnızım

sohbetlerimizi demlediğimiz

öksüz kalan mutfağımızda,

seni bulamadım gecenin sessizliğinde,

hep bekliyorum

belki suskunluğuma son verirsin diye...

Vuslat daha ne kadar gecikecek,

daha ne kadar kapıdan süzülüşünü gözleyeceğim,

yıldızlar seni anıyor hala,

balkonumuz sonsuzluğa bakıyor yine,

seni bekliyor köşedeki sandalye,

herşey seni özledi buralarda.

Çay demledim yine,seversin diye; 

ama gelmiyorsun işte çay saatlerinde bile...

13/11/2004      00.40', '(Cancağızıma...)  Yine yalnızım sohbetlerimizi demlediğimiz öksüz kalan mutfağımızda, seni bulamadım gecenin sessizliğinde, hep bekliyorum b...', ARRAY['Türk Edebiyatı','Şiir','Gamze Kaya']::text[], 8.5, '{"poet":"Gamze Kaya","poet_slug":"gamze-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yalniz-icilen-caylar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık', 'ayrilik-umut-ozen-adu2l', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ayrılıkların bir sonraki günüyüm ben,

usulca yatağımdan kalkarken kıyamete,

hem suçlu hem masum iki yürek atıyor bedenimde 

kızılca kıyamet kopmuş gibi sallanıyor yüreğim.

her defa gözlerimde o buruk, acınası, kimsesiz ifade belirdiğinde

çalınır kulağıma uzakların o dayanılmaz şarkısı,

“hadi gidelim” der yeni bir dünyaya.

şimdi,

sokaktaki ağaçlar ürperiyor rüzgarla bakarken geceye,

sigarımın dumanında uzaklaşıyor gözlerin,

hatıralar bağırıyor, bir nefeslik ömrüm kalmış sanki,

masmaviydi gökyüzü oysa, denizler sonsuz bir hayat demekti

ayrılığın yüzünü  görmeden önce.,

hoşçakal sevgilim, her zaman hatırlıyacağım seni,

hoşçakal.', 'ayrılıkların bir sonraki günüyüm ben, usulca yatağımdan kalkarken kıyamete, hem suçlu hem masum iki yürek atıyor bedenimde  kızılca kıyamet ...', ARRAY['Türk Edebiyatı','Şiir','Umut Özen']::text[], 8.5, '{"poet":"Umut Özen","poet_slug":"umut-ozen","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ayrilik-354-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Define', 'define-umut-ozen-hlmhy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'dün gece bütün şehir uyurken,

gökyüzüne uzanmış,

gizli hazineme giden yolları çiziyordum.

çarmaha gerilmiş ellerimden,

ve kollarımdan kurtularak kısaldım.

güçsüzdüm; 

soluklanmak için bile duracak zamanım yoktu aslında.

suçsuzdum; 

yaşamayı hiç denememiştim bile.

denenmiştim; 

öteki peygamberlerin kitaplarından çaldığım kelimeleri,

kitaplara dağıtıp, saklanmıştım.

bilmiyordum; 

saklandığım yerde beni bulup,

sokaklara ismimi vereceklerini.

yürüyordum,

yıldızlar birer birer tükeniyordu.

kayboluyordu evren,

ay gecenin bu halini hiç beğenmiyordu.

ses kulağa girerken izin istiyordu.

yüksek topuklu ayakkabılarıyla ve

elma kırmızısı dudaklarıyla peşimden gelenler vardı.

yatağımın çarşafında hiç tanımadığım bir kokuydu bütün bıraktıkları,

yıkandığında unutulan bir şarkı gibiydi sözleri.

ve çekip gittiler sonra.

hesabını ödemiştim oysa doğduğum günün.

hazineye giden yolları yürüyordum,

karşımda duran gözler,

yolculuğumun sona erdiğinin bir işaretiydi.

göremese de  beni,

bilmese de,

en değerli hazinemdi.

bir gece daha,

bir kez daha,

sona erdim.', 'dün gece bütün şehir uyurken, gökyüzüne uzanmış, gizli hazineme giden yolları çiziyordum. çarmaha gerilmiş ellerimden, ve kollarımdan kurtul...', ARRAY['Türk Edebiyatı','Şiir','Umut Özen']::text[], 8.5, '{"poet":"Umut Özen","poet_slug":"umut-ozen","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/define-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayır Eski Zamanlar', 'hayir-eski-zamanlar-sedat-demirkaya-zisqt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bulutlara aldan aldanırsan

 ada her yandan yeni rüzgarlar alır

 balıkçı takaları bir gider bin gelir

 karanfilli balıklar takılır ağlarına

 fısıltın yankılanır gecenin kulaklarında

 derman damıtırsın gökkuşağından bir sabah

 bir elinde su, bir yanın ışık

 öylece durursun insanlık sokağında', 'bulutlara aldan aldanırsan  ada her yandan yeni rüzgarlar alır  balıkçı takaları bir gider bin gelir  karanfilli balıklar takılır ağlarına  ...', ARRAY['Türk Edebiyatı','Şiir','Sedat Demirkaya']::text[], 8.5, '{"poet":"Sedat Demirkaya","poet_slug":"sedat-demirkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/hayir-eski-zamanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Fark Eder', 'ne-fark-eder-suleyman-yavuz-sr05y', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Günün rengi mat sen olmayınca

Hayat ne kadarda berbat

Güzel olan her şey 

Sen olmayınca eskisi gibi değil

Hani diyor ya eğil yağmur rüzgâr eğil

Bu bendeki sevda değil

Sen olmayınca da bu bendeki ben değil

Sevgim sevgi değil

Yüzüm yüz sözüm söz değil

Sen olsan olur muydu hiç böyle

Solar mıydı çiçek dalında

Bal yerine avı yapar mıydı arı peteğe

Dert düşer miydi? 

Yaralı yüreğe 

Hayat sen olmayınca berbat 

Nefesim nefes değil

Sesim ses değil

Sensiz kalacaksam eğer

Eğil bedenim 

Eğil ruhum

Toprağa geri dönelim

Ha ölmüşüz 

Ha da onsuz olmuşuz 

Söyle ne fark eder', 'Günün rengi mat sen olmayınca Hayat ne kadarda berbat Güzel olan her şey  Sen olmayınca eskisi gibi değil Hani diyor ya eğil yağmur rüzgâr e...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Yavuz']::text[], 8.5, '{"poet":"Süleyman Yavuz","poet_slug":"suleyman-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ne-fark-eder-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umutlarım', 'umutlarim-emre-saricicek-z8885', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Güne başlıyor hayat

Kurtuluyor matemlerden gökyüzü

Ve sisler çöküyor üzerime

Ne seni görebilirim.

Ne ayak izini.

Ama

Bakışlarındaki pınarı görmemek mümkün değil.

Ya özleyişin, çehremi sarıyor benliğiyle.

Umutlarım, bir kuş kadar yüksekte.

Kanatları, sümbül kokan felekte.

Bekle beni her daim.

Toprağın, tütün kokar yürekte.

Aşk ile, özlem ile,

Sana koşan sevgilerimle.

Bekle beni her daim...', 'Güne başlıyor hayat Kurtuluyor matemlerden gökyüzü Ve sisler çöküyor üzerime Ne seni görebilirim. Ne ayak izini. Ama Bakışlarındaki pınarı g...', ARRAY['Türk Edebiyatı','Şiir','Emre Sarıçiçek']::text[], 8.5, '{"poet":"Emre Sarıçiçek","poet_slug":"emre-saricicek","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/umutlarim-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kazımadan Mektep Sıralarına Sevgilinin Adını', 'kazimadan-mektep-siralarina-sevgilinin-adini-sedat-demirkaya-7rzrv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'nedendir bu çılgın koşu yeni başlangıçlara

iliklerine kadar kan ter içinde sevdalılar

laleler, güller, sislere bürünmüş ay

üzülürsün, geçer önünden kösteklenmiş bir bahar

fallarla uğraşmak zamanı değildir, başarı işte

etkileyici, hoş, sevgili...şimdi sıfatlar aciz

rengini almış gözlerinden bak şuracıkta uyanan deniz', 'nedendir bu çılgın koşu yeni başlangıçlara iliklerine kadar kan ter içinde sevdalılar laleler, güller, sislere bürünmüş ay üzülürsün, geçer ...', ARRAY['Türk Edebiyatı','Şiir','Sedat Demirkaya']::text[], 8.5, '{"poet":"Sedat Demirkaya","poet_slug":"sedat-demirkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kazimadan-mektep-siralarina-sevgilinin-adini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uşağum 16. (yerel)', 'usagum-16-yerel-mikdat-bal-id3es', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Cemiyetun güç kaynağı gençluktur

Bu kaynaktan sen birisun uşağum

En kıymetli varluk sıhhat dinçluktur

Hem atiksun hem serisun uşağum

Sana bir şey diyeceğum kırılma

Gencum diye caka edup kurulma

O gücüni eyi kullan yorulma

MaşaAllah dipdirisun uşağum

Çoği sana tafra atti, payladi

Beceruksuz, dedi yanlış söyledi

Ati alan Üsküdar’ı boyladı

Davran hadi çok gerisun uşağum

Cahilleri yönetenler zalimdur

Sözleri şov propaganda, filimdur

Bu devirde yekane güç ilimdur

Biliyorsan çok irisun uşağum

Mikdatî der bize şeref gurursun

Umudumuz sensun niçun durursun

Vatan sana emanettur korursun

Hainlukten sen berisun uşağum', 'Cemiyetun güç kaynağı gençluktur Bu kaynaktan sen birisun uşağum En kıymetli varluk sıhhat dinçluktur Hem atiksun hem serisun uşağum Sana bi...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/usagum-16-yerel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keşke', 'keske-sevgul-kilicaslan-moeus', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Keşke..

Yalnızlıgım kadar

Yanımda olsaydın..! 

Keşke..

Yalnızlıgımla paylaştıgımı

Seninle paylaşsaydım..! 

Keşke..

Senin adın 

YALNIZLIK olsaydı...! 

Ve.. Ben 

Hep YALNIZ kalsaydım..! !', 'Keşke.. Yalnızlıgım kadar Yanımda olsaydın..!  Keşke.. Yalnızlıgımla paylaştıgımı Seninle paylaşsaydım..!  Keşke.. Senin adın  YALNIZLIK ols...', ARRAY['Türk Edebiyatı','Şiir','Sevgül Kılıçaslan']::text[], 8.5, '{"poet":"Sevgül Kılıçaslan","poet_slug":"sevgul-kilicaslan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/keske-135-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kirman da', 'kirman-da-ufuk-nazim-x3z4a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sol yanından yıkılmış

Bir yapı

Ardahan da bir köy

Kirman da

Şosenin kenarında

Devrimci Gençlerin Derneği

Artık ne genç kaldı

Nede içinde demli çaylar.

Serpmiş tohumlarını

Gunesin tarlasına 

Zamanın dörtnala giden

Atının terkisinde

Derin bir bekleyişte 

Sanki kalan duvarlarıyla

Pür dikkat dinliyor

Gençlerin çığlıklarını

Dünyanın dört bir yanından

Duyuyor

Sinanı, Taylanı

Denizi, Mahiri 

Huseyini, Ulaşı.

Şimdi yaralı olsada

Sol yanı

Cimenlerle dirilişte

Her bahar.

Köyün çayırında

Korkusuzca 

Tarlalarını biçiyor köylüler.

Ağalar uzaktan

Gözleri yaşlı baksada

Gençlerin sesi 

Irgatların kulaklarında

Hala yankılanıyor

Köylüye toprak.......', 'Sol yanından yıkılmış Bir yapı Ardahan da bir köy Kirman da Şosenin kenarında Devrimci Gençlerin Derneği Artık ne genç kaldı Nede içinde dem...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/kirman-da-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnız', 'yalniz-sedat-demirkaya-cl9t6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'umutsuzluk tepesine vurdu bütün yollar

 mektuplar kesildi,rüzgar...beklemede.

 haber almak yok bu hazan adasında...bolca hatırlamak

 son zamanlar gökyüzünde buluttan başkasına yer yok

 tanıdığım bütün göçmenler şafak sökerken

 büyülü davetine uyup özgürlük ağaçlarının

 saldılar ipini geceden yıllar süren komşuluğumuzun', 'umutsuzluk tepesine vurdu bütün yollar  mektuplar kesildi,rüzgar...beklemede.  haber almak yok bu hazan adasında...bolca hatırlamak  son zam...', ARRAY['Türk Edebiyatı','Şiir','Sedat Demirkaya']::text[], 8.5, '{"poet":"Sedat Demirkaya","poet_slug":"sedat-demirkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yalniz-53-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zeka', 'zeka-sevinc-kavuk-ys3ao', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İyi öğretim ve iyi çevre bir zeka artımı

Kalıtsal yetenek, deneyim ve çevresel

Bileşenlerin zekayı da şekillendirdiği

Bir beden senfonisi doğaya eşdeğerlik… 

Vücudun kullanıldığı bir BEDENSEL zeka 

dans ve vücut dili ile spor gibi oyunlarla 

veya icat ile duygu ifade etme yeteneği

el ve bedenleri kontrol, koordine mevcutu…

Soyut, simgesel düşünmede bir SÖZEL zeka

dilsel üretimlerden sorumlu okuma-yazma,

konuşma-tartışma ve edebi ürünler yaratma

güzel de kavram oluşturma ve kelime yazma 

şiir, dil bilgisi, hikaye anlatma, mizah gibi

karmaşık olgularda istekli mizaçlık tümü…

Şekiller tasarısı, zihinde resim yaratma

harita, deniz gibi yüzey bilgileri kullanma

Satranç gibi farklı görüş açılarına beceri ve

yeteneği oluşturan bir GÖRSEL uzamsal zeka

görsel sanatlarda üretim yapma zevkleri…

Tonal ve ritmik kavramları tanıma, kullanma

evrensel ve insan sesi, müzik ve aletlerine 

duyarlık kapasitesiyle bir MÜZİKSEL zeka…

Bilimsel düşünme, objektif gözlem, verilerden

sonuçlama, yargıya varma ve hipotez kurma, bir

MATEMATİKSEL zeka ile kavramları tanıma

sayı ve geometri gibi soyut sembollerle çalışma

bir bilginin parçaları arasında ilişki kurma 

farklı bağıntıları farkediş kapasiteleri bütünü…

Sözlü-sözsüz iletişim kurma bir SOSYAL zeka

grup içinde iş birlikli çalışma yeteneği içeren

kişiler arası ruh halleri, huy, yönelimler gibi 

insanlar arasındaki ilgi farklarını ortaya koyma

kendini başkasının yerine koyma ve anlayabilme

duygu, düşünce ve inaçlarıyla özdeşleşebilme

yeteneklerinin önemlilikler özelliği toplamı….

İnsanın duyguları, duygusal tepkiler derecesi

kendi biliş sürecini tanıma, öz benliğini anlama

ve kendini başkalarına ifade etme yetisi ile

bir çiçek aranjmanı gibi bu bir KİŞİSEL zeka

insanın kendi kişiliği, kendini aşma yeteneği

içsel zekanın işleyen bölümü…başkalarının

duygu ve düşüncelerini anlama, meditasyon

nesne ötesi konularda konsantre olma ile

çok özel ve zeka türlerinin tüm kapsamı…

Haftanın yedi gününe sanki yedi zeka türüyle

Ve herkes bu zeka türlerine çeşitli düzeylerde

sahip olarak doğar ve belki bazısına eğilimli…

Ve herkes bu zeka potansiyellerini geliştirebilir

yerden göğe kadar ve yer altından gök üstüne

beşikten mezara kadar…

her bedensel özürlükle de

beyinsel özürlüler ama

benim gözbebeklerim…

25 Mart 2006____Diliyorum 

______________Tüm bilişsel düzeye azim ve istek bütünlüğünde

______________Sadece güzel amaçlar için kullanmaya özende

______________Özen ve özveride başarılı her yaş ve çağda birer

______________Bağımsız, hür, dinamik, sağlıklı kişilikler oluşsun', 'İyi öğretim ve iyi çevre bir zeka artımı Kalıtsal yetenek, deneyim ve çevresel Bileşenlerin zekayı da şekillendirdiği Bir beden senfonisi do...', ARRAY['Türk Edebiyatı','Şiir','Sevinç Kavuk']::text[], 8.5, '{"poet":"Sevinç Kavuk","poet_slug":"sevinc-kavuk","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/zeka-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '1 Şehrin Sokağına Veda', '1-sehrin-sokagina-veda-arzu-bagriacik-zkhml', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu sabah ışığa uyandığımda 

Biraz melankonik olacağımı 

Anlamış olmalıydım ki, 

Kapıdan çıkmakta zorlandım. 

Yolun karşısına geçip 

Dolmuşa bindiğimde 

Bu yöne gidişimin 

Durak değişikliğiyle 

Süreceğini sezinledim. 

Son durakta indiğimde 

Yürümeye başladım. 

Yedi senedir bu şehirde 

Hiç ayaklarımın basmadığı 

Köşeleri altı ay adımlamışım. 

Her gün seslerini aldığım 

İnsanlarla yüzleşmeye gidecektim. 

Bu sokaklara dönüp 

Adımlamayacaktım 

Yolum buralardan geçmezdi benim 

Kaç sene daha bu şehirde olacaktım 

Ve kaç sene daha 

Bu yollara dönmeyecektim. 

Ne zaman hayatımdaki 

Koca ayları unutup 

Yok sayacaktım..........! 

Sokakları unuttum desem 

İnsanlarına ne yapacaktım? 

2004 Ankara', 'Bu sabah ışığa uyandığımda  Biraz melankonik olacağımı  Anlamış olmalıydım ki,  Kapıdan çıkmakta zorlandım.  Yolun karşısına geçip  Dolmuşa ...', ARRAY['Türk Edebiyatı','Şiir','Arzu Bağrıaçık']::text[], 8.5, '{"poet":"Arzu Bağrıaçık","poet_slug":"arzu-bagriacik","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/1-sehrin-sokagina-veda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '1 Ben', '1-ben-arzu-bagriacik-dngqo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kızaranlığım 

Gözleri perdeli 

Hissedilemeyesi... 

Kokusuz 

Kafesi kıran 

Mezardayım. 

2001 GATA-Ankara', 'Kızaranlığım  Gözleri perdeli  Hissedilemeyesi...  Kokusuz  Kafesi kıran  Mezardayım.  2001 GATA-Ankara...', ARRAY['Türk Edebiyatı','Şiir','Arzu Bağrıaçık']::text[], 8.5, '{"poet":"Arzu Bağrıaçık","poet_slug":"arzu-bagriacik","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/1-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '1 Boş', '1-bos-arzu-bagriacik-t5d2c', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sessiz ve ürkek,perdeyi aralıyorum. 

Elimdeki sigaram,ateş tutuyor geceye. 

Soğuk; üşüyorum. 

Kollarımı bağlıyor,umursamıyorum. 

Cadde bomboş. 

Daha dün yangın vardı,ne kalabalıktı! 

Bugün seyireyleyecek bir şey yok. 

Seyrediyorum. 

Yanan evin ninesi de yok artık. 

Kediler nerede kalacak? 

Ankara', 'Sessiz ve ürkek,perdeyi aralıyorum.  Elimdeki sigaram,ateş tutuyor geceye.  Soğuk; üşüyorum.  Kollarımı bağlıyor,umursamıyorum.  Cadde bombo...', ARRAY['Türk Edebiyatı','Şiir','Arzu Bağrıaçık']::text[], 8.5, '{"poet":"Arzu Bağrıaçık","poet_slug":"arzu-bagriacik","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/1-bos-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '1 Bulutlar Nerede?', '1-bulutlar-nerede-arzu-bagriacik-h8ri5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gökyüzündeki alışkanlığım 

Pamuk bulutlar, 

Nereye kayboldunuz ki 

Grilere teslim etmişsiniz şehri? 

17.06.2001 Ankara', 'Gökyüzündeki alışkanlığım  Pamuk bulutlar,  Nereye kayboldunuz ki  Grilere teslim etmişsiniz şehri?  17.06.2001 Ankara...', ARRAY['Türk Edebiyatı','Şiir','Arzu Bağrıaçık']::text[], 8.5, '{"poet":"Arzu Bağrıaçık","poet_slug":"arzu-bagriacik","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/1-bulutlar-nerede-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '1 Çığlık', '1-ciglik-arzu-bagriacik-olk3g', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Alaysı bir gülümseme mi 

