INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '1 Duvarda Resmin', '1-duvarda-resmin-arzu-bagriacik-gad9d', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '..............................Babama 

O garip derinden bakışın 

Her ruh halimle konuşur benimle 

Neşemle neşelenir 

Üzüntümde destek olur 

Anlatırım, dinler. 

Sanki elinde sigara 

Odada turlar 

Sıkılınca yapar bunu 

Belli etmemek için çaba sarf eder. 

Bir nefes daha çeker 

Çeker, çeker. 

Ardından gelsin bir tane daha 

Sonra kaybolur birden 

Ani olur gelişi gibi gidişi de. 

Değişmedi, 

Düşte, gerçekte. 

2000 Ankara', '..............................Babama  O garip derinden bakışın  Her ruh halimle konuşur benimle  Neşemle neşelenir  Üzüntümde destek olur  A...', ARRAY['Türk Edebiyatı','Şiir','Arzu Bağrıaçık']::text[], 8.5, '{"poet":"Arzu Bağrıaçık","poet_slug":"arzu-bagriacik","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/1-duvarda-resmin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '1 Endişem', '1-endisem-arzu-bagriacik-sm8d1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hayatın sonbaharı artık 

Güneş ufukta bir siyahımsı mor 

Korku filmlerindeki o ürpertici soğuk 

Caddelere,sokaklara hatta en ücra köşelere inmiş. 

İçimin tuhaflığı yetmezmiş gibi, 

Hüznü hissediyorum ufukta. 

Kış aylarından soğuk gecede; 

Sonbahar artık gülümsemiyor bana 

Kasetimdeki yanık türkü beni rahatlatamıyor 

Onca araba,insan sesi içerisinde, 

Hışırdayan yaprak sesleri kafamı karıştırıyor. 

Oysa eskiden böyle düşünmezdim, 

Yaşlandıkça; gönlümde yıkılan heveslerle... 

''Henüz gencim,baharındayım hayatın'' derim bazen 

dolaşırım ıssız köşelerde 

Yinede bir boşluk yaşıyorum; eğlencelerde,düğünlerde. 

Eşyalar hüzne bürünmüş,evim anlamsız 

Gençliğimin kızaran yönleri, 

Hasrete dönüşmüş. 

Geçmişe bakıp,yarınlarımı hecelesem de 

Duygularım paramparça ve yırtık; 

Gönlümde çağlayıp,gözlerime gelen bir hıçkırık... 

Afakanlar bassa da inlemek; 

''Y A R'' diye. 

''Ey endişelerim! Ayrılmayın,lazımsınız bana'' 

''Sen! Her zaman ufkumda,gökkuşağı gibi parlamalısın, 

Nefesimin son anına kadar... 

Ruhuma eş,kalbime denk... 

SEN HÜZNE YENİLEN BU İNSANIN DERTLERİNE DERT, 

EY ÇİLEKEŞ... 

Ankara', 'Hayatın sonbaharı artık  Güneş ufukta bir siyahımsı mor  Korku filmlerindeki o ürpertici soğuk  Caddelere,sokaklara hatta en ücra köşelere i...', ARRAY['Türk Edebiyatı','Şiir','Arzu Bağrıaçık']::text[], 8.5, '{"poet":"Arzu Bağrıaçık","poet_slug":"arzu-bagriacik","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/1-endisem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '1 File Çoraplı Kadın', '1-file-corapli-kadin-arzu-bagriacik-7sadf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözlerimi kapatıp; 

Cama vuran yağmur damlalarının sesiyle, 

Dans ediyorum. 

Ne masamdaki boş tabağı 

Nede bakkalın borcunu umursuyorum. 

Gecenin büyüsünü; 

Tırmalayıcı bir çığlık bozuyor. 

Sarı postişli,file çoraplı, 

Kırmızı pabuçlu bir kadın 

Yardım edin diye bağırıyor. 

Sicim gibi yağmur o an korkutuyor beni. 

Elim telefonda tuşlara basıyor. 

Alo şu adrese acil yardım. 

22.04.2001 Ankara', 'Gözlerimi kapatıp;  Cama vuran yağmur damlalarının sesiyle,  Dans ediyorum.  Ne masamdaki boş tabağı  Nede bakkalın borcunu umursuyorum.  Ge...', ARRAY['Türk Edebiyatı','Şiir','Arzu Bağrıaçık']::text[], 8.5, '{"poet":"Arzu Bağrıaçık","poet_slug":"arzu-bagriacik","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/1-file-corapli-kadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '1 İçten Dışa', '1-i-cten-disa-arzu-bagriacik-ceet9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Susuzluğum 

