INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '1 Kelebek Kanatlarım', '1-kelebek-kanatlarim-arzu-bagriacik-ik6sp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Camları yalayan yağmur yağmasa 

Açacaktım kanatlarımı 

Uçacaktım ya hani yanına! 

Korkum nüksetti aniden 

Yol uzun ulaşamamak vardı 

Farzet bahanelerim fazla. 

Özgür olmak ister kelebek 

Yakalanırsa ne yapar acaba? 

 Ankara', 'Camları yalayan yağmur yağmasa  Açacaktım kanatlarımı  Uçacaktım ya hani yanına!  Korkum nüksetti aniden  Yol uzun ulaşamamak vardı  Farzet ...', ARRAY['Türk Edebiyatı','Şiir','Arzu Bağrıaçık']::text[], 8.5, '{"poet":"Arzu Bağrıaçık","poet_slug":"arzu-bagriacik","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/1-kelebek-kanatlarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '1 Kısır döngü', '1-kisir-dongu-arzu-bagriacik-nxwza', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çıtırtılı esintilerde 

Kulaç sesleri 

Atlıyorum balık gibi 

Yaşayacağım sanki! 

Yanılgıların kısır döngüsünde 

Titriyorum. 

2001 Ankara(Ant)', 'Çıtırtılı esintilerde  Kulaç sesleri  Atlıyorum balık gibi  Yaşayacağım sanki!  Yanılgıların kısır döngüsünde  Titriyorum.  2001 Ankara(Ant)...', ARRAY['Türk Edebiyatı','Şiir','Arzu Bağrıaçık']::text[], 8.5, '{"poet":"Arzu Bağrıaçık","poet_slug":"arzu-bagriacik","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/1-kisir-dongu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '1 Melekler Şehire İnince', '1-melekler-sehire-i-nince-arzu-bagriacik-cdxep', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir demet papatya topladım tepelerden, 

İndirdim meleklerle birlikte evime. 

Öyle zor gitti ki ellerim vazoya. 

Kurumalarına izin vermeyecektim. 

Her düşen beyazlık damla damla canımdı. 

Biliyordum eriyordum günden güne 

Elimden geleni vermeliydim. 

Darda mı başın tanımadığım? 

Bir damlam sende kalsın. 

Bir beyaz daha düştü masama. 

Azalıyordu hızlı zamanla, 

Sulasam da damla damla 

Benim dermansızlığımla. 

Ölüyordu beyazlar yavaş yavaş. 

Sanki dostumdu üzmek istemeyen 

Vermeliydim bir damla daha. 

Uzattım elimi,aldım avuçlarıma; 

Cansızdı benim gibi. 

İstemiyordum beyazla birleşsin kaderimiz. 

Melekler şehirde soluyamazdı. 

2001 Ankara', 'Bir demet papatya topladım tepelerden,  İndirdim meleklerle birlikte evime.  Öyle zor gitti ki ellerim vazoya.  Kurumalarına izin vermeyecek...', ARRAY['Türk Edebiyatı','Şiir','Arzu Bağrıaçık']::text[], 8.5, '{"poet":"Arzu Bağrıaçık","poet_slug":"arzu-bagriacik","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/1-melekler-sehire-inince-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '1 Merhaba', '1-merhaba-arzu-bagriacik-hmi86', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kapalı kapılar ardında 

Berrak gözler 

Pencerem açılmalı 

Güneş yeni ışımakta. 

Kütahya üzeri; 

Ten sıcaklığında. 

Güne haykırışla 

Merhaba. 

2001 Kütahya', 'Kapalı kapılar ardında  Berrak gözler  Pencerem açılmalı  Güneş yeni ışımakta.  Kütahya üzeri;  Ten sıcaklığında.  Güne haykırışla  Merhaba....', ARRAY['Türk Edebiyatı','Şiir','Arzu Bağrıaçık']::text[], 8.5, '{"poet":"Arzu Bağrıaçık","poet_slug":"arzu-bagriacik","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/1-merhaba-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '1 Ne Zaman?', '1-ne-zaman-arzu-bagriacik-501os', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yüreğimin yangını, 

Ne zaman sönecek? 

Yağmur, 

Ne zaman yağacak? 

Bilmiyorum... 

Yine de ben yaşıyorum, 

Yaşamaya çalışıyorum. 

2001 Ankara', 'Yüreğimin yangını,  Ne zaman sönecek?  Yağmur,  Ne zaman yağacak?  Bilmiyorum...  Yine de ben yaşıyorum,  Yaşamaya çalışıyorum.  2001 Ankara...', ARRAY['Türk Edebiyatı','Şiir','Arzu Bağrıaçık']::text[], 8.5, '{"poet":"Arzu Bağrıaçık","poet_slug":"arzu-bagriacik","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/1-ne-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '1 Rengarenk', '1-rengarenk-arzu-bagriacik-2nop4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yeşil esip, 

Beyazı devirir. 

Hayatı karanın, 

Mavisinde dalganın. 

Grisi yağar, 

Sarısı canlanır, 

Pembe umutlanır. 

Bunlara; 

Kırmızı kinlenir. 

Mor ağlamalarda... 

Ankara', 'Yeşil esip,  Beyazı devirir.  Hayatı karanın,  Mavisinde dalganın.  Grisi yağar,  Sarısı canlanır,  Pembe umutlanır.  Bunlara;  Kırmızı kinl...', ARRAY['Türk Edebiyatı','Şiir','Arzu Bağrıaçık']::text[], 8.5, '{"poet":"Arzu Bağrıaçık","poet_slug":"arzu-bagriacik","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/1-rengarenk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '1 Rüyam', '1-ruyam-arzu-bagriacik-y8p6m', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ecel terleriyle uyanıyorum yatağımda. 

